INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (29386,'Воззвание к героям: гора Хиджал!','По приказу его королевского высочества короля Вариана Ринна, все годные к военной службе граждане Альянса обязаны явиться к посланнице Песне Ветра на Лунную поляну.$b$bНаши собратья из круга Кенария сообщают о том, что приспешники Смертокрыла намереваются сжечь дотла Древо Жизни!$b$bЧтобы попасть на Лунную поляну, поговорите с кенарийской посланницей Нефритовой Луной в крепости Штормграда.$b$bЗа честь и славу Альянса! В бой, $gбрат:сестра;!','Поговорите с кенарийской посланницей Нефритовой Луной, чтобы попасть на Лунную поляну.','Путешествие на Лунную поляну','Поговорите с посланницей Песней Ветра в Ночной гавани на Лунной поляне.','Путешествие на Лунную поляну') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воззвание к героям: гора Хиджал!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу его королевского высочества короля Вариана Ринна, все годные к военной службе граждане Альянса обязаны явиться к посланнице Песне Ветра на Лунную поляну.$b$bНаши собратья из круга Кенария сообщают о том, что приспешники Смертокрыла намереваются сжечь дотла Древо Жизни!$b$bЧтобы попасть на Лунную поляну, поговорите с кенарийской посланницей Нефритовой Луной в крепости Штормграда.$b$bЗа честь и славу Альянса! В бой, $gбрат:сестра;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с кенарийской посланницей Нефритовой Луной, чтобы попасть на Лунную поляну.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Путешествие на Лунную поляну',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посланницей Песней Ветра в Ночной гавани на Лунной поляне.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Путешествие на Лунную поляну',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29392,'Пропавшие фамильные ценности','Сегодня из Терамора должна прибыть последняя часть принадлежащих мне вещей. Корабль уже причалил, но курьер до меня пока не добрался. А в ящике, который он должен был доставить, были фамильные ценности, которые моя семья передавала из поколения в поколение.$b$bНе сходишь ли ты в порт Штормграда и не узнаешь ли, что задерживает курьера?','Осмотрите каюту на корабле наемного курьера, чтобы понять, что могло его задержать.','Вряд ли теперь этот курьер сможет встретиться с тем, кто его нанял. Ящик, который он вез, очевидно, исчез.','Осмотрите каюту курьера.','Осмотрите тело наемного курьера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие фамильные ценности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня из Терамора должна прибыть последняя часть принадлежащих мне вещей. Корабль уже причалил, но курьер до меня пока не добрался. А в ящике, который он должен был доставить, были фамильные ценности, которые моя семья передавала из поколения в поколение.$b$bНе сходишь ли ты в порт Штормграда и не узнаешь ли, что задерживает курьера?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите каюту на корабле наемного курьера, чтобы понять, что могло его задержать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вряд ли теперь этот курьер сможет встретиться с тем, кто его нанял. Ящик, который он вез, очевидно, исчез.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотрите каюту курьера.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите тело наемного курьера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29393,'Пиво для Хмельного фестиваля','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.','Авария между бухтой Острорука и этим местом сорвала поставки пива! Да еще и дворфы Черного Железа нападают каждый час, если не чаще!$B$BТак что, если хочешь помочь, вот мое предложение. Я одолжу тебе поводья и одного из моих баранов.$B$BЗа каждый привезенный бочонок ты будешь получать несколько жетонов и возможность подольше ездить на баране!$B$BНО! Как только начнешь, ты не сможешь вновь этим заняться до завтрашнего дня.$B$BТы уверен, что готов начать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиво для Хмельного фестиваля',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Авария между бухтой Острорука и этим местом сорвала поставки пива! Да еще и дворфы Черного Железа нападают каждый час, если не чаще!$B$BТак что, если хочешь помочь, вот мое предложение. Я одолжу тебе поводья и одного из моих баранов.$B$BЗа каждый привезенный бочонок ты будешь получать несколько жетонов и возможность подольше ездить на баране!$B$BНО! Как только начнешь, ты не сможешь вновь этим заняться до завтрашнего дня.$B$BТы уверен, что готов начать?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29394,'Пиво для Хмельного фестиваля','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.','У нас на фестивале пиво льется рекой, и бочонков много не бывает! А в Караносе их как раз предостаточно, чтобы поделиться с нами.$B$BМожешь взять одного из моих баранов.$B$BЗа каждый принесенный мне бочонок ты получишь несколько жетонов и возможность подольше ездить на баране.$B$BНо учти! Возьмешься за задание – и до завтрашнего дня больше ничего не поручу!$B$BНу что, решишься?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиво для Хмельного фестиваля',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас на фестивале пиво льется рекой, и бочонков много не бывает! А в Караносе их как раз предостаточно, чтобы поделиться с нами.$B$BМожешь взять одного из моих баранов.$B$BЗа каждый принесенный мне бочонок ты получишь несколько жетонов и возможность подольше ездить на баране.$B$BНо учти! Возьмешься за задание – и до завтрашнего дня больше ничего не поручу!$B$BНу что, решишься?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29395,'FLAG - Teleport to Uldum') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Teleport to Uldum',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29397,'Новый продавец сувениров','Даже не напоминай мне о прошлогодних пивных кружках, $n.$b$bСкажу тебе начистоту, наши предыдущие продавцы кружек оказались подозрительными личностями. Они были связаны с сектантами Сумеречного Молота...$b$bМы не можем иметь дело с теми, кто хочет разрушить наш мир!$b$bПоэтому теперь у нас новые продавцы и кружки нового образца.$b$bОтнеси этот купон Белби Быстросмен в лагерь Хмельного фестиваля. Взамен она даст тебе бесплатную праздничную кружку. Кроме того, у нее можно купить и другие праздничные товары.','Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.','Ах-х, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$B$BЕще увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...$B$BИли его... $B$BМожет, его...','Что такое, красавчик? Ты ко мне по делу?','Вернитесь к Белби Быстросмен в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый продавец сувениров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже не напоминай мне о прошлогодних пивных кружках, $n.$b$bСкажу тебе начистоту, наши предыдущие продавцы кружек оказались подозрительными личностями. Они были связаны с сектантами Сумеречного Молота...$b$bМы не можем иметь дело с теми, кто хочет разрушить наш мир!$b$bПоэтому теперь у нас новые продавцы и кружки нового образца.$b$bОтнеси этот купон Белби Быстросмен в лагерь Хмельного фестиваля. Взамен она даст тебе бесплатную праздничную кружку. Кроме того, у нее можно купить и другие праздничные товары.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах-х, всего лишь за бесплатным пивом... Может, ты просто стесняешься? Ладно-ладно, вот тебе бесплатная кружечка.$B$BЕще увидимся. Ты ведь захочешь отоварить и другие праздничные купоны... Помни, я вся твоя...$B$BИли его... $B$BМожет, его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что такое, красавчик? Ты ко мне по делу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Белби Быстросмен в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29398,'Скупка краденного','Вы быстро осматриваете каюту, но не находите ничего, что помогло бы установить личность убийцы или его мотивы. Ящик, за которым вас отправили, исчез.$b$bВы поворачиваете к выходу и уже собираетесь выйти из каюты, как вдруг замечаете под ногами что-то маленькое и движущееся. Из-под койки убитого курьера движется цепочка пауков. Куда же они направляются?','Следуйте за пауками и допросите того, кого вы найдете в конце пути.','Тише! Не говори ничего об этом деле. Или конец моей карьере аукциониста!','Попробуйте узнать больше информации от аукциониста Фитча.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скупка краденного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы быстро осматриваете каюту, но не находите ничего, что помогло бы установить личность убийцы или его мотивы. Ящик, за которым вас отправили, исчез.$b$bВы поворачиваете к выходу и уже собираетесь выйти из каюты, как вдруг замечаете под ногами что-то маленькое и движущееся. Из-под койки убитого курьера движется цепочка пауков. Куда же они направляются?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуйте за пауками и допросите того, кого вы найдете в конце пути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тише! Не говори ничего об этом деле. Или конец моей карьере аукциониста!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Попробуйте узнать больше информации от аукциониста Фитча.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29399,'Прицениться','Наконец-то я получил от Катлера какие-то сведения. Но сначала я хочу узнать, на кого ты работаешь.','Поговорите с Хадсоном Барнсом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прицениться',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то я получил от Катлера какие-то сведения. Но сначала я хочу узнать, на кого ты работаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хадсоном Барнсом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (29399,'У тебя такой вид, как будто ты что-то знаешь об этих пропавших вещах.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя такой вид, как будто ты что-то знаешь об этих пропавших вещах.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29400,'Время праздника','Как дела, |3-6($c)? Тыквовин – время празднований и размышлений, хотя многие совершенно не в курсе, почему это так. В частности, церемония сжигания Плетеного человека тоже является загадкой почти для всех, кроме Отрекшихся.$b$bОтправляйся в Руины Лордерона, расположенные над Подгородом, и поговори с зовущей Тьму Янкой. Она расскажет тебе о церемонии сжигания Плетеного человека подробнее.','Поговорите с зовущей Тьму Янкой в Руинах Лордерона у входа в Подгород.','Праздник Плетеного человека имеет богатую историю. Приятно, что Орда теперь тоже присоединится к празднованиям.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время праздника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как дела, |3-6($c)? Тыквовин – время празднований и размышлений, хотя многие совершенно не в курсе, почему это так. В частности, церемония сжигания Плетеного человека тоже является загадкой почти для всех, кроме Отрекшихся.$b$bОтправляйся в Руины Лордерона, расположенные над Подгородом, и поговори с зовущей Тьму Янкой. Она расскажет тебе о церемонии сжигания Плетеного человека подробнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с зовущей Тьму Янкой в Руинах Лордерона у входа в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Праздник Плетеного человека имеет богатую историю. Приятно, что Орда теперь тоже присоединится к празднованиям.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29402,'Меры предосторожности','Я бы на твоем месте остерегался любого, кто скажет, что он владелец этого ящика и его содержимого. Тебя не предупредили об опасности?$b$bУ меня есть идея получше: давай будем искать ящик вместе, а когда найдем, сделаем так, чтобы его содержимое никому не навредило. А чтобы не пострадать самим, нам понадобится зелье. Ингредиенты для его приготовления можно найти в городе. Купи немного порошка чар у торговца реагентами, несколько хрустальных колб у торговца товарами для алхимиков и собери кровавой крапивы на полях к северу от города.','Соберите 5 хрустальных колб, 2 порции порошка чар и 5 стеблей кровавой крапивы.','Иногда я думаю, что стоило мне пойти по стопам своего отца и стать алхимиком.$B$BЭто зелье защитит нас от всех негативных эффектов, которым может подвергнуться тот, кто переносит или хранит этот ящик. Давай выпьем его!','Ты собрал все ингредиенты?','Вернитесь к Хадсону Барнсу в лавку "Загадка" в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меры предосторожности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы на твоем месте остерегался любого, кто скажет, что он владелец этого ящика и его содержимого. Тебя не предупредили об опасности?$b$bУ меня есть идея получше: давай будем искать ящик вместе, а когда найдем, сделаем так, чтобы его содержимое никому не навредило. А чтобы не пострадать самим, нам понадобится зелье. Ингредиенты для его приготовления можно найти в городе. Купи немного порошка чар у торговца реагентами, несколько хрустальных колб у торговца товарами для алхимиков и собери кровавой крапивы на полях к северу от города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 хрустальных колб, 2 порции порошка чар и 5 стеблей кровавой крапивы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Иногда я думаю, что стоило мне пойти по стопам своего отца и стать алхимиком.$B$BЭто зелье защитит нас от всех негативных эффектов, которым может подвергнуться тот, кто переносит или хранит этот ящик. Давай выпьем его!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал все ингредиенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадсону Барнсу в лавку "Загадка" в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29403,'Помощник того, кто интересуется ящиком','Помешайте встрече Саната Лим-Йо и вора, укравшего ящик, в катакомбах под Собором Света.','От ящика исходит ощущение темной силы. Саната Лим-Йо поблизости нет. Вы можете взять ящик и отнести его своему нанимателю.','Осмотрите украденный ящик в катакомбах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощник того, кто интересуется ящиком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помешайте встрече Саната Лим-Йо и вора, укравшего ящик, в катакомбах под Собором Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От ящика исходит ощущение темной силы. Саната Лим-Йо поблизости нет. Вы можете взять ящик и отнести его своему нанимателю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите украденный ящик в катакомбах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29404,'Начало пути','Вы приступаете к обучению, и первое задание будет простым: поговорите с мастером Шан Си.','Поговорите с мастером Шан Си.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начало пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы приступаете к обучению, и первое задание будет простым: поговорите с мастером Шан Си.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Шан Си.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29405,'Урок железного посоха','Для тренировок тебе потребуется соответствующая экипировка. Возьми оружие на одной из оружейных стоек внизу, принеси мне и продемонстрируй свою способность правильно его держать.','Возьмите тренировочное оружие со стойки и экипируйтесь им.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железного посоха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для тренировок тебе потребуется соответствующая экипировка. Возьми оружие на одной из оружейных стоек внизу, принеси мне и продемонстрируй свою способность правильно его держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите тренировочное оружие со стойки и экипируйтесь им.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29406,'Урок песочного кулака','Я хотел бы посмотреть на то, как ты обращаешься с оружием, $gмой юный ученик:моя юная ученица;. Это поможет мне подобрать курс тренировок, наиболее подходящий для совершенствования твоих навыков.$B$BВнизу, на тренировочной площадке, ты найдешь множество манекенов. Потренируйся на них, а затем, когда решишь, что $gосвоился:освоилась;, возвращайся ко мне.','Уничтожьте 5 тренировочных манекенов.','Неплохо, совсем неплохо, $n! Возможно, ты правильно $gвыбрал:выбрала; свой путь.$B$BХорошо. Продолжим.','Ты найдешь тренировочные манекены у подножия холма. Возвращайся, когда закончишь.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок песочного кулака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хотел бы посмотреть на то, как ты обращаешься с оружием, $gмой юный ученик:моя юная ученица;. Это поможет мне подобрать курс тренировок, наиболее подходящий для совершенствования твоих навыков.$B$BВнизу, на тренировочной площадке, ты найдешь множество манекенов. Потренируйся на них, а затем, когда решишь, что $gосвоился:освоилась;, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 тренировочных манекенов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, совсем неплохо, $n! Возможно, ты правильно $gвыбрал:выбрала; свой путь.$B$BХорошо. Продолжим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найдешь тренировочные манекены у подножия холма. Возвращайся, когда закончишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29407,'Предвестие зимы','В ручье, что течет внизу, ты найдешь цветок лотоса. И этот лотос расскажет нам о грядущих переменах. Принеси мне его, и я покажу тебе, что я имею в виду.','Найдите мерцающий лотос.','Вернитесь к мастеру Шан Си на мост рядом с Уголком Спокойствия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предвестие зимы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В ручье, что течет внизу, ты найдешь цветок лотоса. И этот лотос расскажет нам о грядущих переменах. Принеси мне его, и я покажу тебе, что я имею в виду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите мерцающий лотос.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на мост рядом с Уголком Спокойствия.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29408,'Урок горящего свитка','Любая мудрость уместна в определенное время и в определенном месте. А времена меняются, и все мы, кто живет на Шэнь-Цзынь Су, чувствуем это. В этом испытании я попрошу тебя о двух вещах.$b$bВ своей лапе я держу пламя. Когда тебе покажется, что ты $gготов:готова;, попробуй выхватить его.$b$bКогда сделаешь это, поднимись на верхний этаж храма и сожги "Предписание умеренности", которое ты там найдешь.','Выхватите пламя из лапы мастера Шан Си, после чего сожгите "Предписание умеренности".','Наступит время, когда тебе придется положиться на свои инстинкты и действовать не раздумывая.','Вернитесь в храм к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок горящего свитка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любая мудрость уместна в определенное время и в определенном месте. А времена меняются, и все мы, кто живет на Шэнь-Цзынь Су, чувствуем это. В этом испытании я попрошу тебя о двух вещах.$b$bВ своей лапе я держу пламя. Когда тебе покажется, что ты $gготов:готова;, попробуй выхватить его.$b$bКогда сделаешь это, поднимись на верхний этаж храма и сожги "Предписание умеренности", которое ты там найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выхватите пламя из лапы мастера Шан Си, после чего сожгите "Предписание умеренности".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наступит время, когда тебе придется положиться на свои инстинкты и действовать не раздумывая.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в храм к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29409,'Испытание ученика','$n, я вижу в тебе великую силу, равно как и великую храбрость и непревзойденную чистоту души.$B$bНесмотря на твою неопытность, думаю, ты уже $gготов:готова; пройти более серьезное испытание.$B$BОтправляйся вниз по лестнице и перейди через мост. Там ты найдешь Цзяоминь Жо, одного из лучших наших учеников. Сразись с ним в честном бою, одержи над ним победу – и первая часть твоего обучения будет завершена.','Одержите победу над Цзяоминь Жо.','Превосходно, $n. Не осталось никаких сомнений, что ты $gпоступил:поступила; правильно, избрав путь |3-1($c).','Величайшая слава не в том, чтобы ни разу не упасть, но в том, чтобы всякий раз после падения вновь подняться на ноги. Цзяоминь Жо это прекрасно знает. Он находит силу в каждом поражении.$B$BТебе, возможно, лишь предстоит усвоить этот урок.','Поговорите с мастером Шан Си на мосту рядом с Уголком Спокойствия.','Цзяоминь Жо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание ученика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я вижу в тебе великую силу, равно как и великую храбрость и непревзойденную чистоту души.$B$bНесмотря на твою неопытность, думаю, ты уже $gготов:готова; пройти более серьезное испытание.$B$BОтправляйся вниз по лестнице и перейди через мост. Там ты найдешь Цзяоминь Жо, одного из лучших наших учеников. Сразись с ним в честном бою, одержи над ним победу – и первая часть твоего обучения будет завершена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Цзяоминь Жо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, $n. Не осталось никаких сомнений, что ты $gпоступил:поступила; правильно, избрав путь |3-1($c).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Величайшая слава не в том, чтобы ни разу не упасть, но в том, чтобы всякий раз после падения вновь подняться на ноги. Цзяоминь Жо это прекрасно знает. Он находит силу в каждом поражении.$B$BТебе, возможно, лишь предстоит усвоить этот урок.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Шан Си на мосту рядом с Уголком Спокойствия.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Цзяоминь Жо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (29410,'Аиса, следующая по пути Тушуй','Поговорите с торговцем Лорво у пруда Фу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аиса, следующая по пути Тушуй',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с торговцем Лорво у пруда Фу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29411,'И что теперь?','В конце концов вы нашли ящик, за которым вас послал Ансон. Однако все говорит о том, что предупреждения ученика археолога относительно природы содержимого ящика были основаны не на пустом месте.$b$bНет никаких сомнений, что ваш наниматель солгал вам, когда говорил, что дело совсем неопасное. Правда ли вы хотите отнести этот ящик ему? Может быть, лучше передать его Хадсону Барнсу, который позаботится о том, чтобы содержимое ящика никому не навредило?','Верните ящик Ансону Гастингсу в "Позолоченную розу" в Штормграде.$b$bИЛИ$b$bВерните ящик Хадсону Барнсу, которого можно найти в "Золотом бочонке" в Штормграде.','Тебе все же удалось завладеть ящиком до того, как он достался Ксилему! Замечательно!','Ящик, о котором мы говорили, у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И что теперь?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В конце концов вы нашли ящик, за которым вас послал Ансон. Однако все говорит о том, что предупреждения ученика археолога относительно природы содержимого ящика были основаны не на пустом месте.$b$bНет никаких сомнений, что ваш наниматель солгал вам, когда говорил, что дело совсем неопасное. Правда ли вы хотите отнести этот ящик ему? Может быть, лучше передать его Хадсону Барнсу, который позаботится о том, чтобы содержимое ящика никому не навредило?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ящик Ансону Гастингсу в "Позолоченную розу" в Штормграде.$b$bИЛИ$b$bВерните ящик Хадсону Барнсу, которого можно найти в "Золотом бочонке" в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе все же удалось завладеть ящиком до того, как он достался Ксилему! Замечательно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ящик, о котором мы говорили, у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29413,'Страшный ящик','Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшный ящик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29414,'Путь Тушуй','Рада познакомиться, |3-6($c). Я Аиса, следую пути Тушуй.$B$BС тех пор, как мастер Шан сказал мне, что наша задача – найти Хо, духа огня, я провела немало времени в размышлениях. Я знаю, где он сейчас, но не знаю, как до него добраться. Но чтобы найти ответ, достаточно лишь протянуть руку.$B$BСопроводи меня в Пещеру Медитации, она совсем недалеко отсюда. Это место, полное великой мудрости. В пещере я займусь медитацией, раскрою свой разум, и путь к Хо откроется нам.','Защищайте Аису, пока она медитирует.','Поговорите с мастером Шан Си у Пещеры Медитации.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Тушуй',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рада познакомиться, |3-6($c). Я Аиса, следую пути Тушуй.$B$BС тех пор, как мастер Шан сказал мне, что наша задача – найти Хо, духа огня, я провела немало времени в размышлениях. Я знаю, где он сейчас, но не знаю, как до него добраться. Но чтобы найти ответ, достаточно лишь протянуть руку.$B$BСопроводи меня в Пещеру Медитации, она совсем недалеко отсюда. Это место, полное великой мудрости. В пещере я займусь медитацией, раскрою свой разум, и путь к Хо откроется нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте Аису, пока она медитирует.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Шан Си у Пещеры Медитации.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29415,'Пропавшие фамильные ценности','Я говорил курьеру лететь на дирижабле, но нет же, он предпочел плыть на этом гоблинском корабле! И вот теперь он где-то запропастился вместе с моими фамильными ценностями.$b$bЕсли ты хочешь помочь, не сходишь ли ты в порт в восточной части Оргриммара и не узнаешь ли, что задерживает курьера?','Вряд ли теперь этот курьер сможет встретиться с тем, кто его нанял. Ящик, который он вез, очевидно, исчез.','Осмотрите каюту курьера.','Осмотрите тело наемного курьера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие фамильные ценности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я говорил курьеру лететь на дирижабле, но нет же, он предпочел плыть на этом гоблинском корабле! И вот теперь он где-то запропастился вместе с моими фамильными ценностями.$b$bЕсли ты хочешь помочь, не сходишь ли ты в порт в восточной части Оргриммара и не узнаешь ли, что задерживает курьера?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вряд ли теперь этот курьер сможет встретиться с тем, кто его нанял. Ящик, который он вез, очевидно, исчез.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотрите каюту курьера.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите тело наемного курьера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29416,'Скупка краденного','Вы быстро осматриваете каюту, но не находите ничего, что помогло бы установить личность убийцы или его мотивы. Ящик, за которым вас отправили, исчез.$b$bВы поворачиваете к выходу и уже собираетесь выйти из каюты, как вдруг замечаете под ногами что-то маленькое и движущееся. Из-под койки убитого курьера тянется цепочка пауков. Куда они направляются?','Следуйте за пауками и допросите того, кого вы найдете в конце пути.','Тише! Не говори ничего об этом деле. Или конец моей карьере аукциониста!','Попробуйте узнать больше информации от аукциониста Дрезмита.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скупка краденного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы быстро осматриваете каюту, но не находите ничего, что помогло бы установить личность убийцы или его мотивы. Ящик, за которым вас отправили, исчез.$b$bВы поворачиваете к выходу и уже собираетесь выйти из каюты, как вдруг замечаете под ногами что-то маленькое и движущееся. Из-под койки убитого курьера тянется цепочка пауков. Куда они направляются?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуйте за пауками и допросите того, кого вы найдете в конце пути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тише! Не говори ничего об этом деле. Или конец моей карьере аукциониста!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Попробуйте узнать больше информации от аукциониста Дрезмита.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29417,'Путь Хоцзинь','Мы называем злобных обезьян, что напали на деревню, хозенами. Обычно хозены избегают нас, но они предчувствуют какую-то беду, вот и воруют у нас припасы.$B$BИ в этой ситуации нужно действовать решительно. Обезьянам придется уйти, даже если для этого нам понадобится применить силу! Не защитить наш город и наших родных и близких – преступление. Таков путь Хоцзинь.','Убейте 8 воинов из Фэ-Фан.','А в тебе есть боевой дух! Пожалуй, ты мне нравишься!','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Хоцзинь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы называем злобных обезьян, что напали на деревню, хозенами. Обычно хозены избегают нас, но они предчувствуют какую-то беду, вот и воруют у нас припасы.$B$BИ в этой ситуации нужно действовать решительно. Обезьянам придется уйти, даже если для этого нам понадобится применить силу! Не защитить наш город и наших родных и близких – преступление. Таков путь Хоцзинь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 воинов из Фэ-Фан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А в тебе есть боевой дух! Пожалуй, ты мне нравишься!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29418,'Разжигание огня','Ну вот, с этой проблемой разобрались, теперь можно приступать к делу!$B$BХо, дух огня, любит растопку из сухих корней кизила. Растет кизил среди деревьев на юге от деревни. Думаю, тебе будет нетрудно собрать достаточное их количество.','Соберите 5 сухих корней кизила.','Ты ведь не боишься испачкать руки, не так ли?','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разжигание огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, с этой проблемой разобрались, теперь можно приступать к делу!$B$BХо, дух огня, любит растопку из сухих корней кизила. Растет кизил среди деревьев на юге от деревни. Думаю, тебе будет нетрудно собрать достаточное их количество.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 сухих корней кизила.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь не боишься испачкать руки, не так ли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29419,'Пропавший повозчик','Мой повозчик погнался за лесными духами, укравшими припасы. Не думаю, что он мог пострадать, но мне понадобится его помощь, чтобы привести телегу в порядок.$B$BОн побежал в направлении утесов, что на севере. Думаю, ты быстро его найдешь.','Спасите повозчика.','Мне стоило быть осторожнее.','Вернитесь к торговцу Лорво к пруду Фу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший повозчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой повозчик погнался за лесными духами, укравшими припасы. Не думаю, что он мог пострадать, но мне понадобится его помощь, чтобы привести телегу в порядок.$B$BОн побежал в направлении утесов, что на севере. Думаю, ты быстро его найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите повозчика.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне стоило быть осторожнее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Лорво к пруду Фу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29420,'Страж духа','До сих пор ты $gделал:делала; большие успехи, $gмой ученик:моя ученица;. У тебя есть все, что требуется, чтобы разжечь пламя Хо, духа огня.$b$bОн ожидает тебя в пещере, что на юго-западе отсюда, и его охраняет мастер Ли Фэй, пандарен-старейшина, с которым ты $gпознакомился:познакомилась; в Пещере Медитации. Отнеси мастеру Ли Фэю свои подношения. Покажи ему, на что ты $gспособен:способна;, и найди Хо.','Поговорите с мастером Ли Фэем в Святилище Внутреннего Света','Жизнь заключается не в поиске себя. Жизнь – это саморазвитие. Путь перед тобой открыт, но испытания для себя на этом пути будешь выбирать только ты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До сих пор ты $gделал:делала; большие успехи, $gмой ученик:моя ученица;. У тебя есть все, что требуется, чтобы разжечь пламя Хо, духа огня.$b$bОн ожидает тебя в пещере, что на юго-западе отсюда, и его охраняет мастер Ли Фэй, пандарен-старейшина, с которым ты $gпознакомился:познакомилась; в Пещере Медитации. Отнеси мастеру Ли Фэю свои подношения. Покажи ему, на что ты $gспособен:способна;, и найди Хо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Ли Фэем в Святилище Внутреннего Света',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жизнь заключается не в поиске себя. Жизнь – это саморазвитие. Путь перед тобой открыт, но испытания для себя на этом пути будешь выбирать только ты.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29422,'Хо, дух огня','Усильте пламя Хо, духа огня.','<Присмотревшись, сквозь яркое свечение вы замечаете, что он улыбается. Похоже, вы ему понравились.>','<Хо спокойно парит над прудом.>','Поговорите с Хо в Святилище Внутреннего Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хо, дух огня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Усильте пламя Хо, духа огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Присмотревшись, сквозь яркое свечение вы замечаете, что он улыбается. Похоже, вы ему понравились.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Хо спокойно парит над прудом.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хо в Святилище Внутреннего Света.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29423,'Пыл Шэнь-Цзынь Су','$n, ты очень хорошо $gсправился:справилась; с поручением. Хо здесь, и огни храма загорелись вновь. Судя по легкости, с которой тебе далось это задание, тебе многое по плечу.$B$BВ пребывании Хо в храме есть великий смысл. Пришло время поведать тебе о грядущем.','Поговорите с мастером Шан Си в Храме Пяти Рассветов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пыл Шэнь-Цзынь Су',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n, ты очень хорошо $gсправился:справилась; с поручением. Хо здесь, и огни храма загорелись вновь. Судя по легкости, с которой тебе далось это задание, тебе многое по плечу.$B$BВ пребывании Хо в храме есть великий смысл. Пришло время поведать тебе о грядущем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Шан Си в Храме Пяти Рассветов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29424,'Предметы первостепенной важности','Проказники из Янтарного Листа налетели на мою телегу и украли почти все припасы учеников, что я вез на тренировочную площадку. Они, конечно, всегда были нарушителями спокойствия в этих местах, но я первый раз вижу такую агрессивность с их стороны. Не представляю, что могло случиться.$B$BПожалуйста, помоги мне разыскать украденные припасы.','Отберите 6 бочонков с припасами учеников у проказников из Янтарного Листа.','О лесных духах не беспокойся. На самом деле они – обычные растения и со временем снова дадут побеги.','Вернитесь к торговцу Лорво к пруду Фу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предметы первостепенной важности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проказники из Янтарного Листа налетели на мою телегу и украли почти все припасы учеников, что я вез на тренировочную площадку. Они, конечно, всегда были нарушителями спокойствия в этих местах, но я первый раз вижу такую агрессивность с их стороны. Не представляю, что могло случиться.$B$BПожалуйста, помоги мне разыскать украденные припасы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 6 бочонков с припасами учеников у проказников из Янтарного Листа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О лесных духах не беспокойся. На самом деле они – обычные растения и со временем снова дадут побеги.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Лорво к пруду Фу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29425,'Прицениться','Ладно, давай уже оставим Дрофферса в покое, а то мы оставим его без покупателей. Нам же нужно объединить усилия для того, чтобы выследить вора и позаботиться о том, чтобы содержимое ящика не попало в дурные руки.','Похоже, тебе известно что-то о пропавшем ящике.','Поговорите с Делианом Тенью Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прицениться',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, давай уже оставим Дрофферса в покое, а то мы оставим его без покупателей. Нам же нужно объединить усилия для того, чтобы выследить вора и позаботиться о том, чтобы содержимое ящика не попало в дурные руки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, тебе известно что-то о пропавшем ящике.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Делианом Тенью Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29426,'Меры предосторожности','Так тебя кто-то нанял, чтобы ты $gнашел:нашла; ящик? Не нравится мне все это.$b$bСодержимое этого ящика принадлежит Реликварию. Предметы, которые в нем лежат, несут в себе огромную силу и очень опасны.$b$bНам необходимо помешать встрече вора и того, кто планирует забрать ящик. Но сначала нужно позаботиться о своей безопасности.$b$bКупи у торговца реагентами немного порошка чар, у торговца товарами для алхимиков – несколько хрустальных колб и собери кровавую крапиву на Аллее Мудрости.','Соберите 5 хрустальных колб, 2 порции порошка чар и 5 стеблей кровавой крапивы.','Ты собрал все ингредиенты?','Вернитесь к Делиану Тени Солнца в Волок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меры предосторожности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так тебя кто-то нанял, чтобы ты $gнашел:нашла; ящик? Не нравится мне все это.$b$bСодержимое этого ящика принадлежит Реликварию. Предметы, которые в нем лежат, несут в себе огромную силу и очень опасны.$b$bНам необходимо помешать встрече вора и того, кто планирует забрать ящик. Но сначала нужно позаботиться о своей безопасности.$b$bКупи у торговца реагентами немного порошка чар, у торговца товарами для алхимиков – несколько хрустальных колб и собери кровавую крапиву на Аллее Мудрости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 хрустальных колб, 2 порции порошка чар и 5 стеблей кровавой крапивы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал все ингредиенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиану Тени Солнца в Волок.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29427,'Помощник того, кто интересуется ящиком','Помешайте встрече Саната Лим-Йо и вора, укравшего ящик, в Руинах Лордерона.','От ящика исходит ощущение темной силы. Саната Лим-Йо поблизости нет. Вы можете взять ящик и отнести его своему нанимателю.','Осмотрите украденный ящик в Руинах Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощник того, кто интересуется ящиком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помешайте встрече Саната Лим-Йо и вора, укравшего ящик, в Руинах Лордерона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От ящика исходит ощущение темной силы. Саната Лим-Йо поблизости нет. Вы можете взять ящик и отнести его своему нанимателю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Осмотрите украденный ящик в Руинах Лордерона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29428,'И что теперь?','В конце концов вы нашли ящик, за которым вас послал Эдгар Гудвин. Однако все говорит о том, что предупреждения представителя Реликвария относительно природы содержимого ящика были основаны не на пустом месте.$b$bНет никаких сомнений, что ваш наниматель солгал вам, когда говорил, что дело совсем неопасное. Правда ли вы хотите отнести этот ящик ему? Может быть, лучше передать его Делиану Тени Солнца, который позаботится о том, чтобы содержимое ящика никому не навредило?','Никогда не думал, что тебе удастся найти его. Давай-ка посмотрим.','Ящик, о котором мы говорили, у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И что теперь?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В конце концов вы нашли ящик, за которым вас послал Эдгар Гудвин. Однако все говорит о том, что предупреждения представителя Реликвария относительно природы содержимого ящика были основаны не на пустом месте.$b$bНет никаких сомнений, что ваш наниматель солгал вам, когда говорил, что дело совсем неопасное. Правда ли вы хотите отнести этот ящик ему? Может быть, лучше передать его Делиану Тени Солнца, который позаботится о том, чтобы содержимое ящика никому не навредило?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никогда не думал, что тебе удастся найти его. Давай-ка посмотрим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ящик, о котором мы говорили, у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29429,'Страшный ящик','Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.','Кто-то искал этот ящик, потом украл и продал. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшный ящик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот ящик теряли, находили, крали и продавали. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто-то искал этот ящик, потом украл и продал. Всякий, кто попытается иметь дело с заключенной в нем магией, непременно почувствует, как эта сила оборачивается против него.$b$bЯщик выглядит неповрежденным и наполненным магической энергией. Время от времени он вздрагивает или подпрыгивает, как будто в нем заключено что-то живое.$b$bОн словно привязан к вам, и вот теперь он ваш.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29430,'Друг в беде','Знаешь, я давненько не видела Ансона.$b$bВ последнее время он по большей части напивается в стельку в таверне "Позолоченная роза".$b$bНаверное, что-то случилось с ним. Не узнаешь, как у него дела?','Поговорите с Ансоном Гастингсом в таверне "Позолоченная роза" в Торговом квартале Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг в беде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, я давненько не видела Ансона.$b$bВ последнее время он по большей части напивается в стельку в таверне "Позолоченная роза".$b$bНаверное, что-то случилось с ним. Не узнаешь, как у него дела?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ансоном Гастингсом в таверне "Позолоченная роза" в Торговом квартале Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29431,'Друг в беде','Что-то не так с моим другом Эдгаром. Обычно он с удовольствием принимает участие во всех праздничных мероприятиях Тыквовина, но в последнее время он ходит угрюмый и замкнутый.$b$bИ почти все время он сидит в "Сломанном клыке", напиваясь там с орками. Не заглянешь к нему узнать, что случилось?','Поговорите с Эдгаром Гудвином в "Сломанном клыке" в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг в беде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то не так с моим другом Эдгаром. Обычно он с удовольствием принимает участие во всех праздничных мероприятиях Тыквовина, но в последнее время он ходит угрюмый и замкнутый.$b$bИ почти все время он сидит в "Сломанном клыке", напиваясь там с орками. Не заглянешь к нему узнать, что случилось?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эдгаром Гудвином в "Сломанном клыке" в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29432,'Поиск','Долг обязывает меня немедленно отреагировать на то, о чем ты $gрассказал:рассказала; мне, $n. Поэтому я передаю тебе миссию, которая привела меня сюда.$b$bМеня привлек всплеск древней магии, слишком сильной, чтобы можно было назвать ее нормальной. И случилось кое-что еще.$b$bКто-то срубил ветвь Нордрассила и унес ее в глубины Огненных Просторов. Ее могут использовать для ритуала, целью которого будет уничтожение Нордрассила.$b$bТы $gдолжен:должна; найти способ прервать ритуал и вернуть ветвь Древа Жизни.','Верните ветвь Нордрассила из Огненных Просторов.','Поговорите с Калесгосом на Янтарной гряде в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Долг обязывает меня немедленно отреагировать на то, о чем ты $gрассказал:рассказала; мне, $n. Поэтому я передаю тебе миссию, которая привела меня сюда.$b$bМеня привлек всплеск древней магии, слишком сильной, чтобы можно было назвать ее нормальной. И случилось кое-что еще.$b$bКто-то срубил ветвь Нордрассила и унес ее в глубины Огненных Просторов. Ее могут использовать для ритуала, целью которого будет уничтожение Нордрассила.$b$bТы $gдолжен:должна; найти способ прервать ритуал и вернуть ветвь Древа Жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ветвь Нордрассила из Огненных Просторов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом на Янтарной гряде в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29433,'Испытай свою силу','Работай, Чертило!','Вернитесь к Керри Хикс на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытай свою силу',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Работай, Чертило!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керри Хикс на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29434,'Командир танка','Управляя паровым танком, поразите 30 целей за отведенное время.','Вернитесь к Финлею Наповалу на ярмарке Новолуния, чтобы получить свой приз.','Порази эти цели!','Цель танка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир танка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Управляя паровым танком, поразите 30 целей за отведенное время.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Финлею Наповалу на ярмарке Новолуния, чтобы получить свой приз.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Порази эти цели!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Цель танка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (29436,'Наберите 5 очков, приземляясь рядом с мишенью для пушки.','Получите свой приз у Максимы Подрывайстер.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 5 очков, приземляясь рядом с мишенью для пушки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Получите свой приз у Максимы Подрывайстер.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29437,'Падшая стражница','Фэндрал Олений Шлем содержался в тюрьме здесь, на Хиджале. Алисра из стаи зеленых драконов занималась его охраной.$b$bМы можем сделать только один вывод – она перешла на сторону Сумеречного Молота. Тебе нужно сразиться с ней, $n. Если понадобится, убей Алисру. Я не могу ее больше видеть.$b$bВ последний раз ее видели в Руинах Лар\'донира, это к западу от Древа Жизни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падшая стражница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фэндрал Олений Шлем содержался в тюрьме здесь, на Хиджале. Алисра из стаи зеленых драконов занималась его охраной.$b$bМы можем сделать только один вывод – она перешла на сторону Сумеречного Молота. Тебе нужно сразиться с ней, $n. Если понадобится, убей Алисру. Я не могу ее больше видеть.$b$bВ последний раз ее видели в Руинах Лар\'донира, это к западу от Древа Жизни.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29438,'В яблочко!','Считаешь себя хорошим стрелком? Как насчет быстрого состязания?$b$bЯ знаю, как испытать тебя – на это потребуется всего один жетон ярмарки Новолуния.$b$bНу, что скажешь? Насколько ты $gметок:меткая;?','Выбейте 25 очков за 60 секунд.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В яблочко!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Считаешь себя хорошим стрелком? Как насчет быстрого состязания?$b$bЯ знаю, как испытать тебя – на это потребуется всего один жетон ярмарки Новолуния.$b$bНу, что скажешь? Насколько ты $gметок:меткая;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выбейте 25 очков за 60 секунд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29440,'Зов шамана','Служители Земли снова обращаются к тебе, $n.$b$bТралл больше не вождь Орды, но в своей новой роли он более, чем когда-либо нуждается в поддержке своего народа. Он попросил кого-нибудь из ордынцев помогать ему в его следующем предприятии – целительном ритуале, который повлияет на весь наш мир.$b$bТы найдешь его под ветвями Нордрассила, на горе Хиджал, с южной стороны дерева. Откликнись на его зов!','Поговорите с Траллом южнее Древа Жизни, что на горе Хиджал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов шамана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли снова обращаются к тебе, $n.$b$bТралл больше не вождь Орды, но в своей новой роли он более, чем когда-либо нуждается в поддержке своего народа. Он попросил кого-нибудь из ордынцев помогать ему в его следующем предприятии – целительном ритуале, который повлияет на весь наш мир.$b$bТы найдешь его под ветвями Нордрассила, на горе Хиджал, с южной стороны дерева. Откликнись на его зов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом южнее Древа Жизни, что на горе Хиджал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29441,'Из чрева чудовища') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из чрева чудовища',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29443,'Интересный кристалл','В этом странном кристалле заключена какая-то сила. Возможно, раньше он был сосредоточием магических сил, источником энергии или просто амулетом на счастье. Невозможно узнать наверняка.$b$bСудя по тому, что написано в справочнике ярмарки Новолуния, этим кристаллом может заинтересоваться профессор Таддеус Палео с ярмарки Новолуния.','Где ты взял этот кристалл?$B$BКоллекционеры охотятся за такими редкими кристаллами. Я бы хотел изучить этот камень и показать его на ярмарке. Не согласишься ли ты обменять его на купоны ярмарки Новолуния? Я щедро заплачу.','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересный кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом странном кристалле заключена какая-то сила. Возможно, раньше он был сосредоточием магических сил, источником энергии или просто амулетом на счастье. Невозможно узнать наверняка.$b$bСудя по тому, что написано в справочнике ярмарки Новолуния, этим кристаллом может заинтересоваться профессор Таддеус Палео с ярмарки Новолуния.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где ты взял этот кристалл?$B$BКоллекционеры охотятся за такими редкими кристаллами. Я бы хотел изучить этот камень и показать его на ярмарке. Не согласишься ли ты обменять его на купоны ярмарки Новолуния? Я щедро заплачу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (29444,'Необычное яйцо','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное яйцо',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29445,'Загадочный гримуар','Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.$b$bВ справочнике ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя.','Загадочный гримуар, как интересно! Кажется, я раньше не видел подобных. Я с удовольствием добавил бы его в свою коллекцию. Не откажешься ли ты уступить его за купоны ярмарки Новолуния?','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадочный гримуар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.$b$bВ справочнике ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Загадочный гримуар, как интересно! Кажется, я раньше не видел подобных. Я с удовольствием добавил бы его в свою коллекцию. Не откажешься ли ты уступить его за купоны ярмарки Новолуния?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29446,'Изумительное оружие','Вы рассматриваете клинок и украшающую его замысловатую инкрустацию, и понимаете, что он создан рукой настоящего мастера. Но это не церемониальный меч. Царапины и еле видные отметины на лезвии свидетельствуют о том, что этим оружием пользовались в бою.$b$bСправочник ярмарки Новолуния, в котором перечислены различные типы редкого и ценного оружия, не оставляет никаких сомнений в том, что профессор Таддеус Палео с интересом взглянул бы на этот клинок.','Где ты достал такой прекрасный клинок?$B$BСразу видно, что это работа выдающегося мастера. Оружие, достойное любого героя. Я бы с радостью приобрел его.$B$BСогласишься ли ты уступить мне его за пачку купонов ярмарки Новолуния?','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изумительное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы рассматриваете клинок и украшающую его замысловатую инкрустацию, и понимаете, что он создан рукой настоящего мастера. Но это не церемониальный меч. Царапины и еле видные отметины на лезвии свидетельствуют о том, что этим оружием пользовались в бою.$b$bСправочник ярмарки Новолуния, в котором перечислены различные типы редкого и ценного оружия, не оставляет никаких сомнений в том, что профессор Таддеус Палео с интересом взглянул бы на этот клинок.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где ты достал такой прекрасный клинок?$B$BСразу видно, что это работа выдающегося мастера. Оружие, достойное любого героя. Я бы с радостью приобрел его.$B$BСогласишься ли ты уступить мне его за пачку купонов ярмарки Новолуния?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29447,'Интересный кристалл','В этом странном кристалле заключена какая-то сила. Возможно, раньше он был сосредоточием магических сил, источником энергии или просто амулетом на счастье. Невозможно узнать наверняка.$b$bСудя по тому, что написано в справочнике ярмарки Новолуния, этим кристаллом может заинтересоваться профессор Таддеус Палео с ярмарки Новолуния.','Отнесите зачарованный кристалл профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интересный кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом странном кристалле заключена какая-то сила. Возможно, раньше он был сосредоточием магических сил, источником энергии или просто амулетом на счастье. Невозможно узнать наверняка.$b$bСудя по тому, что написано в справочнике ярмарки Новолуния, этим кристаллом может заинтересоваться профессор Таддеус Палео с ярмарки Новолуния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зачарованный кристалл профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29448,'Необычное яйцо','Вы точно не знаете, какое существо должно вылупиться из этого яйца, но вне всякого сомнения это будет необычное животное.$b$bВ справочнике ярмарки Новолуния говорится, что отважные искатели приключений нередко находят яйца диковинных животных во время своих странствий. Далее в нем сказано, что сотрудники чудного зоопарка ярмарки Новолуния очень заинтересованы в приобретении подобных видов.$b$bКогда ярмарка вновь откроется, отнесите яйцо Эббу Ниблгиру, которого можно найти у загонов с животными.','Отнесите громадное яйцо Эббу Ниблгиру на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное яйцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы точно не знаете, какое существо должно вылупиться из этого яйца, но вне всякого сомнения это будет необычное животное.$b$bВ справочнике ярмарки Новолуния говорится, что отважные искатели приключений нередко находят яйца диковинных животных во время своих странствий. Далее в нем сказано, что сотрудники чудного зоопарка ярмарки Новолуния очень заинтересованы в приобретении подобных видов.$b$bКогда ярмарка вновь откроется, отнесите яйцо Эббу Ниблгиру, которого можно найти у загонов с животными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите громадное яйцо Эббу Ниблгиру на ярмарку Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29449,'Загадочный гримуар','Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.$b$bВ справочнике ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя. Ищите Воржея возле его палатки на Острове Новолуния.','Отнесите загадочный гримуар Воржею на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадочный гримуар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трудно сказать, кому принадлежала эта массивная книга. Ее страницы испещрены разнообразными заклинаниями и описаниями чар, лишь немногие из которых вам кажутся знакомыми.$b$bВ справочнике ярмарки Новолуния сказано, что подобные книги могут представлять интерес для Воржея, ярмарочного предсказателя. Ищите Воржея возле его палатки на Острове Новолуния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите загадочный гримуар Воржею на ярмарку Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29450,'Изумительное оружие','Вы рассматриваете клинок и украшающую его замысловатую инкрустацию, и понимаете, что он создан рукой настоящего мастера. Но это не церемониальный меч. Царапины и еле видные отметины на лезвии свидетельствуют о том, что этим оружием пользовались в бою.$b$bСправочник ярмарки Новолуния, в котором перечислены различные типы редкого и ценного оружия, не оставляет никаких сомнений в том, что профессор Таддеус Палео с ярмарки Новолуния с интересом взглянул бы на этот клинок.','Отнесите богато украшенный клинок профессору Таддеусу Палео на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изумительное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы рассматриваете клинок и украшающую его замысловатую инкрустацию, и понимаете, что он создан рукой настоящего мастера. Но это не церемониальный меч. Царапины и еле видные отметины на лезвии свидетельствуют о том, что этим оружием пользовались в бою.$b$bСправочник ярмарки Новолуния, в котором перечислены различные типы редкого и ценного оружия, не оставляет никаких сомнений в том, что профессор Таддеус Палео с ярмарки Новолуния с интересом взглянул бы на этот клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите богато украшенный клинок профессору Таддеусу Палео на ярмарку Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29451,'Великий стратег','Этот фундаментальный трактат о стратегии принадлежит перу известного генерала Андуина Лотара. По словам самого генерала, научный труд описывает правильную расстановку войск и рассказывает о различных стратегиях, способных гарантировать победу практически в любой битве.$b$bПрофессору Таддеусу Палео с ярмарки Новолуния наверняка будет интересно взглянуть на такую редкую книгу.','Не знаю, как это попало к тебе в руки, но не буду и спрашивать. Не согласишься ли ты продать мне эту книгу за купоны ярмарки Новолуния?','Это совсем не похоже на обычную книгу...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий стратег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот фундаментальный трактат о стратегии принадлежит перу известного генерала Андуина Лотара. По словам самого генерала, научный труд описывает правильную расстановку войск и рассказывает о различных стратегиях, способных гарантировать победу практически в любой битве.$b$bПрофессору Таддеусу Палео с ярмарки Новолуния наверняка будет интересно взглянуть на такую редкую книгу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не знаю, как это попало к тебе в руки, но не буду и спрашивать. Не согласишься ли ты продать мне эту книгу за купоны ярмарки Новолуния?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это совсем не похоже на обычную книгу...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (29452,'Твое время пришло','<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>$b$b$gЮный:Юная:c; |3-6($c), слушай внимательно то, что я скажу тебе.$b$bМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.$b$bЯ жду тебя в Оргриммаре, $gсмертный:смертная;. Твое время пришло.','Поговорите с Зирадорми в Оргриммаре.','Зирадорми') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твое время пришло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>$b$b$gЮный:Юная:c; |3-6($c), слушай внимательно то, что я скажу тебе.$b$bМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.$b$bЯ жду тебя в Оргриммаре, $gсмертный:смертная;. Твое время пришло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зирадорми в Оргриммаре.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зирадорми',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertargetname_loc8`) VALUES (29453,'Твое время пришло','<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>$b$b$gЮный:Юная:c; |3-6($c), слушай внимательно то, что я скажу тебе.$b$bМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.$b$bЯ жду тебя в Штормграде, $gсмертный:смертная;. Твое время пришло.','Поговорите с Корридорми в Штормграде.','Давай же начнем, смертный.$B$BУ нас мало времени.','Корридорми') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твое время пришло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Перед вашим мысленным взором появляется прекрасное видение, внутри себя вы слышите тихий голос.>$b$b$gЮный:Юная:c; |3-6($c), слушай внимательно то, что я скажу тебе.$b$bМне предназначено забрать тебя и отвести к тому, от чьего взора не может укрыться ничто.$b$bЯ жду тебя в Штормграде, $gсмертный:смертная;. Твое время пришло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Корридорми в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай же начнем, смертный.$B$BУ нас мало времени.',`offerrewardtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Корридорми',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29454,'Великий стратег','Этот фундаментальный трактат о стратегии принадлежит перу известного генерала Андуина Лотара. По словам самого генерала, научный труд описывает правильную расстановку войск и рассказывает о различных стратегиях, способных гарантировать победу практически в любой битве.$b$bПрофессору Таддеусу Палео наверняка будет интересно взглянуть на такую редкую книгу. Профессора можно найти на ярмарке Новолуния, которая проходит на Острове Новолуния.','Отнесите трактат о стратегии профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий стратег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот фундаментальный трактат о стратегии принадлежит перу известного генерала Андуина Лотара. По словам самого генерала, научный труд описывает правильную расстановку войск и рассказывает о различных стратегиях, способных гарантировать победу практически в любой битве.$b$bПрофессору Таддеусу Палео наверняка будет интересно взглянуть на такую редкую книгу. Профессора можно найти на ярмарке Новолуния, которая проходит на Острове Новолуния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите трактат о стратегии профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29455,'Цель: черепаха','Набросьте 3 кольца на черепаху ярмарки Новолуния.','Получите свой приз у Джессики Роджерс на ярмарке Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: черепаха',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Набросьте 3 кольца на черепаху ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Получите свой приз у Джессики Роджерс на ярмарке Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29456,'Захваченное знамя','На этом изорванном знамени видно поблекшее изображение герба гильдии. Похоже, старое знамя повидало на своем веку множество сражений.$b$bПрофессор Таддеус Палео с ярмарки Новолуния коллекционирует знамена и прочие военные реликвии, так что он может заинтересоваться вашим трофеем.','Великолепное знамя! Я бы с радостью присоединил его к своей коллекции.$B$BСогласишься ли ты уступить мне его за несколько купонов ярмарки Новолуния?','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченное знамя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом изорванном знамени видно поблекшее изображение герба гильдии. Похоже, старое знамя повидало на своем веку множество сражений.$b$bПрофессор Таддеус Палео с ярмарки Новолуния коллекционирует знамена и прочие военные реликвии, так что он может заинтересоваться вашим трофеем.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепное знамя! Я бы с радостью присоединил его к своей коллекции.$B$BСогласишься ли ты уступить мне его за несколько купонов ярмарки Новолуния?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29457,'Вражеский знак различия','Этот поцарапанный знак различия, вероятно, принадлежал вражескому офицеру. Для вас ценность представляет разве что металл, из которого изготовлен знак. Но для какого-нибудь коллекционера этот трофей может оказаться весьма ценным.$b$bПрофессор Таддеус Палео с ярмарки Новолуния на весь Азерот известен своей коллекцией военных трофеев.','Это прекрасный образец знака различия офицера. Многие из них посещают ярмарку Новолуния, но никто не хочет продавать свои знаки различия. Может быть, ты уступишь мне свой за купоны ярмарки Новолуния?','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вражеский знак различия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот поцарапанный знак различия, вероятно, принадлежал вражескому офицеру. Для вас ценность представляет разве что металл, из которого изготовлен знак. Но для какого-нибудь коллекционера этот трофей может оказаться весьма ценным.$b$bПрофессор Таддеус Палео с ярмарки Новолуния на весь Азерот известен своей коллекцией военных трофеев.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасный образец знака различия офицера. Многие из них посещают ярмарку Новолуния, но никто не хочет продавать свои знаки различия. Может быть, ты уступишь мне свой за купоны ярмарки Новолуния?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29458,'Захваченный дневник','Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некого искателя приключений. Автор явно был высокого мнения о собственной персоне и о своих деяниях.$b$bПрофессор Таддеус Палео с ярмарки Новолуния наверняка не отказался бы заглянуть в этот дневник.','Потрясающая находка!$B$B<Профессор перелистывает страницы дневника.>$B$BНе все строки легко прочесть, но если хотя бы треть описанного в этом дневнике правда, то это настоящее сокровище. Я готов дать за него целую пачку купонов ярмарки Новолуния. Продашь?','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченный дневник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некого искателя приключений. Автор явно был высокого мнения о собственной персоне и о своих деяниях.$b$bПрофессор Таддеус Палео с ярмарки Новолуния наверняка не отказался бы заглянуть в этот дневник.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающая находка!$B$B<Профессор перелистывает страницы дневника.>$B$BНе все строки легко прочесть, но если хотя бы треть описанного в этом дневнике правда, то это настоящее сокровище. Я готов дать за него целую пачку купонов ярмарки Новолуния. Продашь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29459,'Захваченное знамя','На этом изорванном знамени видно поблекшее изображение герба гильдии. Похоже, старое знамя повидало на своем веку множество сражений.$b$bПрофессор Таддеус Палео с ярмарки Новолуния коллекционирует знамена и прочие военные реликвии, так что он может заинтересоваться вашим трофеем.','Отнесите знамя павших профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченное знамя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом изорванном знамени видно поблекшее изображение герба гильдии. Похоже, старое знамя повидало на своем веку множество сражений.$b$bПрофессор Таддеус Палео с ярмарки Новолуния коллекционирует знамена и прочие военные реликвии, так что он может заинтересоваться вашим трофеем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите знамя павших профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29460,'Вражеский знак различия','Этот поцарапанный знак различия, вероятно, принадлежал вражескому офицеру. Для вас ценность представляет разве что металл, из которого изготовлен знак. Но для какого-нибудь коллекционера этот трофей может оказаться весьма ценным.$b$bПрофессор Таддеус Палео на весь Азерот известен своей коллекцией военных трофеев. Когда ярмарка Новолуния будет проходить в Элвиннском лесу, вы сможете найти профессора к югу от Златоземья. Покажите ему знак.','Отнесите захваченный знак различия профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вражеский знак различия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот поцарапанный знак различия, вероятно, принадлежал вражескому офицеру. Для вас ценность представляет разве что металл, из которого изготовлен знак. Но для какого-нибудь коллекционера этот трофей может оказаться весьма ценным.$b$bПрофессор Таддеус Палео на весь Азерот известен своей коллекцией военных трофеев. Когда ярмарка Новолуния будет проходить в Элвиннском лесу, вы сможете найти профессора к югу от Златоземья. Покажите ему знак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите захваченный знак различия профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29461,'Захваченный дневник','Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некой искательницы приключений из Орды. Автор явно была высокого мнения о собственной персоне и о своих деяниях.$b$bПрофессор Таддеус Палео с ярмарки Новолуния наверняка с интересом взглянет на этот дневник.','Отнесите захваченный дневник профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченный дневник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потрепанная кожаная обложка этой тетради заляпана грязью и залита кровью. Перелистывая страницы, вы понимаете, что в руках у вас личный дневник некой искательницы приключений из Орды. Автор явно была высокого мнения о собственной персоне и о своих деяниях.$b$bПрофессор Таддеус Палео с ярмарки Новолуния наверняка с интересом взглянет на этот дневник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите захваченный дневник профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29463,'Гноллобой','Наберите 30 очков, колошматя гноллов.','Вернитесь к Моле на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гноллобой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 30 очков, колошматя гноллов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моле на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (29464,'Инструменты ворожбы','Эта коллекция потертых рунических камней немало повидала на своем веку. Камни выглядят старыми, различить, что было выгравировано на их поверхности, невозможно.$b$bВероятно, какой-нибудь коллекционер или ученый сможет рассказать о них больше. Отнесите рунические камни профессору Таддеусу Палео на ярмарку Новолуния.','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструменты ворожбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта коллекция потертых рунических камней немало повидала на своем веку. Камни выглядят старыми, различить, что было выгравировано на их поверхности, невозможно.$b$bВероятно, какой-нибудь коллекционер или ученый сможет рассказать о них больше. Отнесите рунические камни профессору Таддеусу Палео на ярмарку Новолуния.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29465,'Инструменты ворожбы','Эта коллекция потертых рунических камней немало повидала на своем веку. Камни выглядят старыми, различить, что было выгравировано на их поверхности, невозможно.$b$bВероятно, какой-нибудь коллекционер или ученый сможет рассказать о них больше. Отнесите рунические камни профессору Таддеусу Палео на ярмарку Новолуния. Когда ярмарка Новолуния будет проходить в Элвиннском лесу, вы сможете найти профессора к югу от Златоземья.','Отнесите руны ворожея профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструменты ворожбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта коллекция потертых рунических камней немало повидала на своем веку. Камни выглядят старыми, различить, что было выгравировано на их поверхности, невозможно.$b$bВероятно, какой-нибудь коллекционер или ученый сможет рассказать о них больше. Отнесите рунические камни профессору Таддеусу Палео на ярмарку Новолуния. Когда ярмарка Новолуния будет проходить в Элвиннском лесу, вы сможете найти профессора к югу от Златоземья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите руны ворожея профессору Таддеусу Палео на ярмарку Новолуния, проходящую на Острове Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29466,'Много жирных лягушек','Наверное, каждый в Азероте слышал о наших знаменитых хрустящих лягушках. Мы едва справляемся со спросом!$b$bТы производишь впечатление $gрасторопного:расторопной:r; |3-1($r) и к тому же $gотличного рыбака:отличной рыбачки;. Не поможешь мне пополнить запасы лягушек?$b$bЛучшие хрустящие лягушки получаются из жирных лягушек, которые водятся у озера Каменного Быка. Я тебе заплачу.','Поймайте 5 жирных лягушек у озера Каменного Быка.','Принесите жирных лягушек Стомпу Громовому Рогу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Много жирных лягушек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наверное, каждый в Азероте слышал о наших знаменитых хрустящих лягушках. Мы едва справляемся со спросом!$b$bТы производишь впечатление $gрасторопного:расторопной:r; |3-1($r) и к тому же $gотличного рыбака:отличной рыбачки;. Не поможешь мне пополнить запасы лягушек?$b$bЛучшие хрустящие лягушки получаются из жирных лягушек, которые водятся у озера Каменного Быка. Я тебе заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 жирных лягушек у озера Каменного Быка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите жирных лягушек Стомпу Громовому Рогу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29467,'Кстати, о танках','Паровые танки – одно из самых популярных развлечений на ярмарке Новолуния. Посетители ярмарки могут часами участвовать в танковых сражениях, но нередко танки от этого ломаются.$b$bТы, похоже, знаешь, как пользоваться отверткой. Так может быть ты починишь несколько танков? Я заплачу тебе за работу.','Почините 5 сломанных паровых танков на территории ярмарки Новолуния.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кстати, о танках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Паровые танки – одно из самых популярных развлечений на ярмарке Новолуния. Посетители ярмарки могут часами участвовать в танковых сражениях, но нередко танки от этого ломаются.$b$bТы, похоже, знаешь, как пользоваться отверткой. Так может быть ты починишь несколько танков? Я заплачу тебе за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почините 5 сломанных паровых танков на территории ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29468,'Малышке нужны новые подковы','Ты, наверное, уже $gвидел:видела; мою лошадку, там, возле телег. Ее зовут Малышка. Она тащит фургон, в котором мы перевозим всех животных нашего чудного зоопарка.$b$bОна большая труженица и $gзнал:знала; бы ты, как быстро снашиваются ее подковы! Вот и опять пришло время заново подковать ее. Железо я уже купил.$b$bВсе, что требуется от тебя, это сделать подковы и подковать Малышку. Много времени это не займет, к тому же, за работу я заплачу тебе купонами. Что скажешь?','Воспользуйтесь железным сырьем, чтобы выковать 4 подковы. Затем используйте подковы, чтобы подковать Малышку на ярмарке Новолуния.','Вернитесь к Эббу Ниблгиру на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Малышке нужны новые подковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, наверное, уже $gвидел:видела; мою лошадку, там, возле телег. Ее зовут Малышка. Она тащит фургон, в котором мы перевозим всех животных нашего чудного зоопарка.$b$bОна большая труженица и $gзнал:знала; бы ты, как быстро снашиваются ее подковы! Вот и опять пришло время заново подковать ее. Железо я уже купил.$b$bВсе, что требуется от тебя, это сделать подковы и подковать Малышку. Много времени это не займет, к тому же, за работу я заплачу тебе купонами. Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь железным сырьем, чтобы выковать 4 подковы. Затем используйте подковы, чтобы подковать Малышку на ярмарке Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эббу Ниблгиру на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29469,'Повторное использование и переработка','Посетители ярмарки обожают паровые танки! А после закрытия ярмарки здесь все будет завалено их деталями.$b$bБыло бы неправильно просто бросить в грязи такой качественный металл.$b$bЕсли ты поможешь мне собрать самые крупные детали, я смогу переплавить их на запчасти для еще действующих паровых танков. Покупать каждый раз новый металл слишком дорого. Что скажешь?','Соберите 6 деталей паровых танков на территории ярмарки Новолуния.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повторное использование и переработка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посетители ярмарки обожают паровые танки! А после закрытия ярмарки здесь все будет завалено их деталями.$b$bБыло бы неправильно просто бросить в грязи такой качественный металл.$b$bЕсли ты поможешь мне собрать самые крупные детали, я смогу переплавить их на запчасти для еще действующих паровых танков. Покупать каждый раз новый металл слишком дорого. Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 деталей паровых танков на территории ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29470,'Отскоблить шкуры','На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.$b$bПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.','Отскоблите 4 растянутые шкуры на ярмарке Новолуния.','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отскоблить шкуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.$b$bПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отскоблите 4 растянутые шкуры на ярмарке Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29471,'Предсказание будущего','С ростом популярности ярмарки Новолуния у нас все больше и больше посетителей, которые хотят узнать свое будущее.$b$bПо большей части они интересуются такими вещами, которые лучше бы и дальше оставались скрытыми под пеленой времени. Но не мне давать им такие советы.$b$bМой запас записочек с предсказаниями подходит к концу. А у тебя, кажется, твердая рука. Возьми вот эти травы, сделай из них чернила и напиши несколько предсказаний. Я позабочусь о том, чтобы твой труд был оплачен.','Воспользуйтесь пучком экзотических трав, чтобы изготовить пророческие чернила. Затем возьмите чернила и тонкий пергамент, и напишите предсказания Воржея.','Вернитесь к Воржею на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предсказание будущего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С ростом популярности ярмарки Новолуния у нас все больше и больше посетителей, которые хотят узнать свое будущее.$b$bПо большей части они интересуются такими вещами, которые лучше бы и дальше оставались скрытыми под пеленой времени. Но не мне давать им такие советы.$b$bМой запас записочек с предсказаниями подходит к концу. А у тебя, кажется, твердая рука. Возьми вот эти травы, сделай из них чернила и напиши несколько предсказаний. Я позабочусь о том, чтобы твой труд был оплачен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь пучком экзотических трав, чтобы изготовить пророческие чернила. Затем возьмите чернила и тонкий пергамент, и напишите предсказания Воржея.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Воржею на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29472,'Изготовление призов','Популярность ярмарочных развлечений растет, и это означает, что призы у нас расходятся все быстрее и быстрее!$b$bТак что нам нужны дополнительные призы и поскорее. Если ты умеешь работать с кожей, я могу дать тебе набор ремесленника. Придется докупить кое-что у торговцев, например, у Шади Вестницы Туманов, которую можно найти на центральном уступе Громового Утеса, но это будут небольшие расходы.$b$bПоможешь?','Воспользуйтесь набором ремесленника ярмарки Новолуния, чтобы изготовить 5 призов Новолуния. Вам понадобится грубая нить, блесны и синяя краска.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изготовление призов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Популярность ярмарочных развлечений растет, и это означает, что призы у нас расходятся все быстрее и быстрее!$b$bТак что нам нужны дополнительные призы и поскорее. Если ты умеешь работать с кожей, я могу дать тебе набор ремесленника. Придется докупить кое-что у торговцев, например, у Шади Вестницы Туманов, которую можно найти на центральном уступе Громового Утеса, но это будут небольшие расходы.$b$bПоможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором ремесленника ярмарки Новолуния, чтобы изготовить 5 призов Новолуния. Вам понадобится грубая нить, блесны и синяя краска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29473,'Поставить работников на ноги','Работать на ярмарке Новолуния небезопасно, $n. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.$b$bТех, кто пострадал больше всего, мы перевезли в Громовой Утес, на Вершину Духов, но есть еще много других, чьи ранения не так серьезны. Им можно оказать помощь и здесь. Не попробуешь ли ты помочь им при помощи этих бинтов?','Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставить работников на ноги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работать на ярмарке Новолуния небезопасно, $n. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.$b$bТех, кто пострадал больше всего, мы перевезли в Громовой Утес, на Вершину Духов, но есть еще много других, чьи ранения не так серьезны. Им можно оказать помощь и здесь. Не попробуешь ли ты помочь им при помощи этих бинтов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29474,'Утилизация хлама','Люди приходят на ярмарку не только затем, чтобы повеселиться и узнать свое будущее, $n. Многие хотят еще и унести что-то с собой на память. Поэтому я помогаю изготавливать магические аксессуары, которые бы наши гости могли приобрести на свои подарочные купоны.$b$bНо для этого нужно, чтобы у меня постоянно был запас пыли Воржея. Посмотри по сторонам – ты увидишь много выброшенного оружия. С твоими-то навыками наложения чар ты легко сможешь распылить эти предметы. Поможешь мне?','Добудьте 6 горстей пыли Воржея, распыляя выброшенное оружие, валяющееся в районе территории ярмарки Новолуния.','Вернитесь к Воржею на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утилизация хлама',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди приходят на ярмарку не только затем, чтобы повеселиться и узнать свое будущее, $n. Многие хотят еще и унести что-то с собой на память. Поэтому я помогаю изготавливать магические аксессуары, которые бы наши гости могли приобрести на свои подарочные купоны.$b$bНо для этого нужно, чтобы у меня постоянно был запас пыли Воржея. Посмотри по сторонам – ты увидишь много выброшенного оружия. С твоими-то навыками наложения чар ты легко сможешь распылить эти предметы. Поможешь мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 горстей пыли Воржея, распыляя выброшенное оружие, валяющееся в районе территории ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Воржею на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29475,'Гоблинское инженерное дело','Опытный инженер может выбрать ОДНУ специализацию, и я могу научить тебя всем премудростям гоблинского инженерного дела.$b$bЯ не сомневаюсь в твоей квалификации, но мне все равно нужно будет взглянуть на сделанные тобой штуковины. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $gсам:сама; не подорвись!$B$BСдай эти предметы учителю инженерного дела в любой из столиц, и тогда будешь официально $gпризнан:признана; гоблином-инженером с правом доступа ко всем чертежам!','Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец учителю инженерного дела в любой столице.','Похоже, ты действительно готов к настоящей учебе. Я нарекаю тебя гоблином-инженером Вопастрел!$B$BТеперь у тебя будет доступ к нашим самым невероятным дьявольским изобретениям. Надеюсь, тебе понравится! Смотри только, чтобы голову не оторвало!','После того как я получу изготовленные тобой инженерные образцы, я расскажу тебе, как стать полноправным членом клуба гоблинов-инженеров!','Обратитесь к учителю инженерного дела в любой столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Опытный инженер может выбрать ОДНУ специализацию, и я могу научить тебя всем премудростям гоблинского инженерного дела.$b$bЯ не сомневаюсь в твоей квалификации, но мне все равно нужно будет взглянуть на сделанные тобой штуковины. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $gсам:сама; не подорвись!$B$BСдай эти предметы учителю инженерного дела в любой из столиц, и тогда будешь официально $gпризнан:признана; гоблином-инженером с правом доступа ко всем чертежам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец учителю инженерного дела в любой столице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, ты действительно готов к настоящей учебе. Я нарекаю тебя гоблином-инженером Вопастрел!$B$BТеперь у тебя будет доступ к нашим самым невероятным дьявольским изобретениям. Надеюсь, тебе понравится! Смотри только, чтобы голову не оторвало!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','После того как я получу изготовленные тобой инженерные образцы, я расскажу тебе, как стать полноправным членом клуба гоблинов-инженеров!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к учителю инженерного дела в любой столице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29476,'Гномское инженерное дело','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику твоих будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и тогда будешь официально $gпризнан:признана; гномом-инженером с правом доступа ко всем чертежам!','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику твоих будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и тогда будешь официально $gпризнан:признана; гномом-инженером с правом доступа ко всем чертежам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29477,'Гномское инженерное дело','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени учителю инженерного дела в любой столице.','Обратитесь к учителю инженерного дела в любой столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени учителю инженерного дела в любой столице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к учителю инженерного дела в любой столице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29478,'Коктейль с пузырьками','Не сомневаюсь, что в бытность свою алхимиком ты $gприготовил:приготовила; много разных зелий. А как насчет помочь нам с приготовлением несколько менее серьезных продуктов?$b$bМне всегда хотелось попытаться изобрести новый вид столь популярной у нас шипучки – с фруктовым вкусом. Если ты $gготов:готова; помочь, то купи несколько порций обычной шипучки и смешай ее с соком луноягоды.$b$bСок можно купить у Галиссы Солнечной Росы.','Воспользуйтесь шейкером для коктейлей, чтобы смешать ярмарочную шипучку с соком луноягоды и приготовить 5 порций луноягодного лимонада.','Вернитесь к Силаннии на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коктейль с пузырьками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не сомневаюсь, что в бытность свою алхимиком ты $gприготовил:приготовила; много разных зелий. А как насчет помочь нам с приготовлением несколько менее серьезных продуктов?$b$bМне всегда хотелось попытаться изобрести новый вид столь популярной у нас шипучки – с фруктовым вкусом. Если ты $gготов:готова; помочь, то купи несколько порций обычной шипучки и смешай ее с соком луноягоды.$b$bСок можно купить у Галиссы Солнечной Росы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь шейкером для коктейлей, чтобы смешать ярмарочную шипучку с соком луноягоды и приготовить 5 порций луноягодного лимонада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Силаннии на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29479,'Целебные травы','Небольшие лиловые цветочки, которые в изобилии растут здесь, не просто красивы.$b$bИх можно использовать для самых разных нужд – от лечения ран до приправ к блюдам.$b$bДумаю, ты умеешь собирать травы. Поможешь мне восполнить мои запасы темноцвета?','Соберите 6 темноцветов на территории ярмарки Новолуния.','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целебные травы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небольшие лиловые цветочки, которые в изобилии растут здесь, не просто красивы.$b$bИх можно использовать для самых разных нужд – от лечения ран до приправ к блюдам.$b$bДумаю, ты умеешь собирать травы. Поможешь мне восполнить мои запасы темноцвета?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 темноцветов на территории ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29480,'Флаги, флаги повсюду!','Разве не чудесно видеть повсюду флаги ярмарки Новолуния? Это моя самая любимая часть приготовлений. Но многие наши флаги уже старые и потрепанные. Нужно их заменить.$b$bЕсли ты умеешь держать в руках иголку с ниткой, то, может быть, сделаешь новый флаг при помощи этого набора, а потом закрепишь его в груде камней на центральном уступе в Громовом Утесе?$b$bОстальные необходимые тебе вещи можешь приобрести у Шади Вестницы Туманов. Ее тоже можно найти на центральном уступе в Громовом Утесе.','Воспользуйтесь набором для изготовления флага ярмарки Новолуния, чтобы сшить флаг ярмарки. Затем установите флаг, закрепив его в груде камней на центральном уступе Громового Утеса.','Вернитесь к Селине Дорман на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флаги, флаги повсюду!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разве не чудесно видеть повсюду флаги ярмарки Новолуния? Это моя самая любимая часть приготовлений. Но многие наши флаги уже старые и потрепанные. Нужно их заменить.$b$bЕсли ты умеешь держать в руках иголку с ниткой, то, может быть, сделаешь новый флаг при помощи этого набора, а потом закрепишь его в груде камней на центральном уступе в Громовом Утесе?$b$bОстальные необходимые тебе вещи можешь приобрести у Шади Вестницы Туманов. Ее тоже можно найти на центральном уступе в Громовом Утесе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором для изготовления флага ярмарки Новолуния, чтобы сшить флаг ярмарки. Затем установите флаг, закрепив его в груде камней на центральном уступе Громового Утеса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селине Дорман на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29481,'Мастер эликсиров','В эликсире главное – его сила! Если ты хочешь стать настоящим мастером в эликсирах, я могу тебя научить.$b$bТолько знай, что я не учу кого попало, так что прежде чем мы продолжим, мне понадобится подтверждение того, что ты действительно собираешься заниматься этим серьезно. Думаю, нескольких настоев для начала будет достаточно.$b$bИ помни, $n: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области эликсиров, ты уже не сможешь изучать зелья и трансмутацию.','Принесите несколько разных настоев учителю алхимии в любой столице.','Превосходно!','Настои у тебя при себе?','Обратитесь к учителю алхимии в любой столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер эликсиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В эликсире главное – его сила! Если ты хочешь стать настоящим мастером в эликсирах, я могу тебя научить.$b$bТолько знай, что я не учу кого попало, так что прежде чем мы продолжим, мне понадобится подтверждение того, что ты действительно собираешься заниматься этим серьезно. Думаю, нескольких настоев для начала будет достаточно.$b$bИ помни, $n: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области эликсиров, ты уже не сможешь изучать зелья и трансмутацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите несколько разных настоев учителю алхимии в любой столице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Настои у тебя при себе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к учителю алхимии в любой столице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29482,'Мастер трансмутации','Превратить железо в золото, заставить воду стать огнем... Если ты хочешь научиться искусству трансмутации, я могу тебе в этом помочь.$b$bНо обучение стоит очень дорого, поэтому я попрошу тебя сначала раздобыть самые качественные материалы, созданные при помощи трансмутации.$b$bИ помни, $n: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области трансмутации, ты уже не сможешь изучать эликсиры и зелья.','Принесите необходимые материалы учителю алхимии в любой столице.','Превосходно!','Необходимые материаны у тебя с собой?','Обратитесь к учителю алхимии в любой столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер трансмутации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Превратить железо в золото, заставить воду стать огнем... Если ты хочешь научиться искусству трансмутации, я могу тебе в этом помочь.$b$bНо обучение стоит очень дорого, поэтому я попрошу тебя сначала раздобыть самые качественные материалы, созданные при помощи трансмутации.$b$bИ помни, $n: ты можешь изучить только ОДНУ специализацию, так что если ты завершишь свое образование в области трансмутации, ты уже не сможешь изучать эликсиры и зелья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите необходимые материалы учителю алхимии в любой столице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Необходимые материаны у тебя с собой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к учителю алхимии в любой столице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29483,'Пусть ярмарка сверкает','Актерам и животным ярмарки Новолуния требуется намного больше самоцветов, чем я мог подумать. К счастью, вместо самоцветов используются просто ограненные куски стекла, но кому-то все равно нужно этим заниматься.$b$bРаз ты не новичок в ювелирном деле, может быть, ты поможешь нам изготовить некоторое количество сверкающих стеклянных "самоцветов" для актеров?$b$bКрасивые осколки стекла иногда валяются прямо под ногами. Если взяться за дело умеючи, то из них могут получиться прекрасные "самоцветы".','Найдите на территории ярмарки Новолуния осколки стекла и изготовьте 5 сверкающих "самоцветов".','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть ярмарка сверкает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Актерам и животным ярмарки Новолуния требуется намного больше самоцветов, чем я мог подумать. К счастью, вместо самоцветов используются просто ограненные куски стекла, но кому-то все равно нужно этим заниматься.$b$bРаз ты не новичок в ювелирном деле, может быть, ты поможешь нам изготовить некоторое количество сверкающих стеклянных "самоцветов" для актеров?$b$bКрасивые осколки стекла иногда валяются прямо под ногами. Если взяться за дело умеючи, то из них могут получиться прекрасные "самоцветы".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на территории ярмарки Новолуния осколки стекла и изготовьте 5 сверкающих "самоцветов".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29484,'Лягушки с хрустящей корочкой','Кто в Азероте не слышал о хрустящих лягушках ярмарки Новолуния!$b$bМы как раз получили очередную партию свежих лягушек. Как насчет того, чтобы помочь нам на кухне и заодно попрактиковаться в приготовлении блюд?$b$bШади Вестница Туманов с центрального уступа Громового Утеса торгует мукой. Купи у нее немного муки для панировки и приготовь хрустящих лягушек вон в том котле позади меня.','Купите простой муки для панировки жирных лягушек и приготовьте 5 хрустящих лягушек, поджарив их в котле позади Стомпа Громового Рога.','Вернитесь к Стомпу Громовому Рогу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лягушки с хрустящей корочкой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто в Азероте не слышал о хрустящих лягушках ярмарки Новолуния!$b$bМы как раз получили очередную партию свежих лягушек. Как насчет того, чтобы помочь нам на кухне и заодно попрактиковаться в приготовлении блюд?$b$bШади Вестница Туманов с центрального уступа Громового Утеса торгует мукой. Купи у нее немного муки для панировки и приготовь хрустящих лягушек вон в том котле позади меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите простой муки для панировки жирных лягушек и приготовьте 5 хрустящих лягушек, поджарив их в котле позади Стомпа Громового Рога.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стомпу Громовому Рогу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29485,'Развлечения для самых маленьких','Дети всегда задают множество вопросов о том, что и как делает археолог, так что я приготовил для них игру.$b$bЯ возьму артефакты и окаменелости и закопаю их в песок позади шатра. Дети смогут их раскапывать, делать свои маленькие открытия, они увидят, как кости соединяются друг с другом, и поймут, как через археологию можно многое узнавать об истории.$b$bЕсли у тебя есть какие-нибудь ненужные окаменелости, может, отдашь мне их для осуществления моего замысла?','Принесите 15 фрагментов окаменелостей профессору Таддеусу Палео на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Развлечения для самых маленьких',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дети всегда задают множество вопросов о том, что и как делает археолог, так что я приготовил для них игру.$b$bЯ возьму артефакты и окаменелости и закопаю их в песок позади шатра. Дети смогут их раскапывать, делать свои маленькие открытия, они увидят, как кости соединяются друг с другом, и поймут, как через археологию можно многое узнавать об истории.$b$bЕсли у тебя есть какие-нибудь ненужные окаменелости, может, отдашь мне их для осуществления моего замысла?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 фрагментов окаменелостей профессору Таддеусу Палео на ярмарку Новолуния.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29506,'Коктейль с пузырьками','Не сомневаюсь, что в бытность свою алхимиком ты $gприготовил:приготовила; много разных зелий. А как насчет помочь нам с приготовлением несколько менее серьезных продуктов?$b$bМне всегда хотелось попытаться изобрести новый вид столь популярной у нас шипучки – с фруктовым вкусом. Если ты $gготов:готова; помочь, то купи несколько порций обычной шипучки и смешай ее с соком луноягоды.$b$bСок можно купить у любого трактирщика в Элвиннском лесу или в Мулгоре.','Воспользуйтесь шейкером для коктейлей, чтобы смешать ярмарочную шипучку с соком луноягоды и приготовить 5 порций луноягодного лимонада.','Вышло неплохо. Если повезет, скоро этот новый лимонад станет популярным!$B$BСпасибо за помощь!','Как обстоят дела с луноягодным лимонадом?','Вернитесь к Силаннии на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коктейль с пузырьками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не сомневаюсь, что в бытность свою алхимиком ты $gприготовил:приготовила; много разных зелий. А как насчет помочь нам с приготовлением несколько менее серьезных продуктов?$b$bМне всегда хотелось попытаться изобрести новый вид столь популярной у нас шипучки – с фруктовым вкусом. Если ты $gготов:готова; помочь, то купи несколько порций обычной шипучки и смешай ее с соком луноягоды.$b$bСок можно купить у любого трактирщика в Элвиннском лесу или в Мулгоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь шейкером для коктейлей, чтобы смешать ярмарочную шипучку с соком луноягоды и приготовить 5 порций луноягодного лимонада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вышло неплохо. Если повезет, скоро этот новый лимонад станет популярным!$B$BСпасибо за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как обстоят дела с луноягодным лимонадом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Силаннии на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29507,'Развлечения для самых маленьких','Дети всегда задают множество вопросов о том, что и как делает археолог, так что я приготовил для них игру.$b$bЯ возьму артефакты и окаменелости и закопаю их в песок возле шатра. Дети смогут их раскапывать, делать свои маленькие открытия, они увидят, как кости соединяются друг с другом, и поймут, как через археологию можно многое узнавать об истории.$b$bЕсли у тебя есть какие-нибудь ненужные окаменелости, может, отдашь мне их для осуществления моего замысла?','Они превосходны! Как раз такие, какие детям особенно понравится находить.','Ну что? Есть ли у тебя окаменелости, которыми ты хочешь поделиться?','Вернитесь к профессору Таддеусу Палео на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Развлечения для самых маленьких',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дети всегда задают множество вопросов о том, что и как делает археолог, так что я приготовил для них игру.$b$bЯ возьму артефакты и окаменелости и закопаю их в песок возле шатра. Дети смогут их раскапывать, делать свои маленькие открытия, они увидят, как кости соединяются друг с другом, и поймут, как через археологию можно многое узнавать об истории.$b$bЕсли у тебя есть какие-нибудь ненужные окаменелости, может, отдашь мне их для осуществления моего замысла?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они превосходны! Как раз такие, какие детям особенно понравится находить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Есть ли у тебя окаменелости, которыми ты хочешь поделиться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к профессору Таддеусу Палео на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29508,'Малышке нужны новые подковы','Воспользуйтесь железным сырьем, чтобы выковать 4 подковы. Затем используйте подковы, чтобы подковать Малышку на ярмарке Новолуния.','Спасибо тебе за помощь, Золдей! Вот обещанная плата.','Как дела у Малышки?','Вернитесь к Эббу Ниблгиру на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Малышке нужны новые подковы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь железным сырьем, чтобы выковать 4 подковы. Затем используйте подковы, чтобы подковать Малышку на ярмарке Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за помощь, Золдей! Вот обещанная плата.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела у Малышки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эббу Ниблгиру на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29509,'Лягушки с хрустящей корочкой','Кто в Азероте не слышал о хрустящих лягушках ярмарки Новолуния!$b$bМы как раз получили очередную партию свежих лягушек. Как насчет того, чтобы помочь нам на кухне и заодно попрактиковаться в приготовлении блюд?$b$bМуку для кляра можно купить у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.','Купите простой муки для панировки жирных лягушек и приготовьте 5 хрустящих лягушек, поджарив их в котле позади Стомпа Громового Рога.','Чем это пахнет? Хрустящими лягушечками?','Вернитесь к Стомпу Громовому Рогу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лягушки с хрустящей корочкой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто в Азероте не слышал о хрустящих лягушках ярмарки Новолуния!$b$bМы как раз получили очередную партию свежих лягушек. Как насчет того, чтобы помочь нам на кухне и заодно попрактиковаться в приготовлении блюд?$b$bМуку для кляра можно купить у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите простой муки для панировки жирных лягушек и приготовьте 5 хрустящих лягушек, поджарив их в котле позади Стомпа Громового Рога.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем это пахнет? Хрустящими лягушечками?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стомпу Громовому Рогу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29510,'Утилизация хлама','Люди приходят на ярмарку не только затем, чтобы повеселиться и узнать свое будущее, $n. Многие хотят еще и унести что-то с собой на память. Поэтому я помогаю изготавливать магические аксессуары, которые бы наши гости могли приобрести на свои подарочные купоны.$b$bНо для этого нужно, чтобы у меня постоянно был запас пыли Воржея. Посмотри по сторонам – ты увидишь много выброшенного оружия. С твоими-то навыками наложения чар ты легко сможешь распылить эти предметы. Поможешь мне?','Соберите 6 порций пыли Воржея, распылив выброшенное оружие, которое можно найти на территории ярмарки Новолуния.','Это поддержит мои запасы на нужном уровне. Если тебе еще как-нибудь захочется помочь, просто разыщи старину Воржея во время следующей ярмарки Новолуния.','У тебя получилось собрать пыль Воржея?','Вернитесь к Воржею на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утилизация хлама',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди приходят на ярмарку не только затем, чтобы повеселиться и узнать свое будущее, $n. Многие хотят еще и унести что-то с собой на память. Поэтому я помогаю изготавливать магические аксессуары, которые бы наши гости могли приобрести на свои подарочные купоны.$b$bНо для этого нужно, чтобы у меня постоянно был запас пыли Воржея. Посмотри по сторонам – ты увидишь много выброшенного оружия. С твоими-то навыками наложения чар ты легко сможешь распылить эти предметы. Поможешь мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 порций пыли Воржея, распылив выброшенное оружие, которое можно найти на территории ярмарки Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поддержит мои запасы на нужном уровне. Если тебе еще как-нибудь захочется помочь, просто разыщи старину Воржея во время следующей ярмарки Новолуния.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя получилось собрать пыль Воржея?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Воржею на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29511,'Кстати, о танках','Почините 5 сломанных паровых танков на территории ярмарки Новолуния.','Ты неплохо потрудился, ремонтируя эти танки. Вот, держи обещанную плату.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кстати, о танках',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почините 5 сломанных паровых танков на территории ярмарки Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты неплохо потрудился, ремонтируя эти танки. Вот, держи обещанную плату.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29512,'Работать на ярмарке Новолуния небезопасно, $n. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.$b$bНекоторые из пострадавших находятся прямо здесь, у фургонов. Остальные – в лечебном шатре неподалеку, там им оказывают первую помощь. Сможешь помочь раненым работникам при помощи этих бинтов?','Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.','Спасибо за помощь, Золдей. Чтобы ярмарка действовала, все мы должны прикладывать усилия.','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работать на ярмарке Новолуния небезопасно, $n. Не секрет, что многие из наших работников получают травмы при установке, разборке или транспортировке всех этих аттракционов.$b$bНекоторые из пострадавших находятся прямо здесь, у фургонов. Остальные – в лечебном шатре неподалеку, там им оказывают первую помощь. Сможешь помочь раненым работникам при помощи этих бинтов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь бинтами ярмарки Новолуния, чтобы вылечить 4 раненых работников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, Золдей. Чтобы ярмарка действовала, все мы должны прикладывать усилия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29513,'Морской хот-дог','Мы только что ввели в меню новый пункт – морской хот-дог. Мы едва справляемся со спросом!$b$bТы производишь впечатление $gрасторопного:расторопной:r; |3-1($r) и к тому же $gотличного рыбака:отличной рыбачки;. Не поможешь мне пополнить запасы рыбы?$b$bМы же ведь не хотим лишить посетителей ярмарки возможности полакомиться новым деликатесом?','Они превосходны! Вот, держи свои купоны, как договаривались.','Принесите селедок Великого моря Стомпу Громовому Рогу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морской хот-дог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы только что ввели в меню новый пункт – морской хот-дог. Мы едва справляемся со спросом!$b$bТы производишь впечатление $gрасторопного:расторопной:r; |3-1($r) и к тому же $gотличного рыбака:отличной рыбачки;. Не поможешь мне пополнить запасы рыбы?$b$bМы же ведь не хотим лишить посетителей ярмарки возможности полакомиться новым деликатесом?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они превосходны! Вот, держи свои купоны, как договаривались.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите селедок Великого моря Стомпу Громовому Рогу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29514,'Целебные травы','Небольшие лиловые цветочки, которые в изобилии растут здесь, не просто красивы.$b$bИх можно использовать для самых разных нужд – от лечения ран до приправ к блюдам.$b$bДумаю, ты умеешь собирать травы. Поможешь мне восполнить мои запасы темноцвета?','Соберите 6 темноцветов на территории ярмарки Новолуния.','Как идет сбор трав?','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целебные травы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небольшие лиловые цветочки, которые в изобилии растут здесь, не просто красивы.$b$bИх можно использовать для самых разных нужд – от лечения ран до приправ к блюдам.$b$bДумаю, ты умеешь собирать травы. Поможешь мне восполнить мои запасы темноцвета?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 темноцветов на территории ярмарки Новолуния.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет сбор трав?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29515,'Предсказание будущего','С ростом популярности ярмарки Новолуния у нас все больше и больше посетителей, которые хотят узнать свое будущее.$b$bПо большей части они интересуются такими вещами, которые лучше бы и дальше оставались скрытыми в тумане времени. Но не мне давать им такие советы.$b$bМой запас карточек с предсказаниями подходит к концу. А у тебя, кажется, глаз наметанный. Возьми вот эти травы, сделай из них чернила и напиши для меня несколько предсказаний. Пергамент купишь у любого торговца потребительскими товарами в Элвиннском лесу или в Мулгоре.','Воспользуйтесь пучком экзотических трав, чтобы изготовить пророческие чернила. Затем возьмите чернила и тонкий пергамент, и напишите предсказания для Воржея.','Предсказания написаны?','Вернитесь к Воржею на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предсказание будущего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С ростом популярности ярмарки Новолуния у нас все больше и больше посетителей, которые хотят узнать свое будущее.$b$bПо большей части они интересуются такими вещами, которые лучше бы и дальше оставались скрытыми в тумане времени. Но не мне давать им такие советы.$b$bМой запас карточек с предсказаниями подходит к концу. А у тебя, кажется, глаз наметанный. Возьми вот эти травы, сделай из них чернила и напиши для меня несколько предсказаний. Пергамент купишь у любого торговца потребительскими товарами в Элвиннском лесу или в Мулгоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь пучком экзотических трав, чтобы изготовить пророческие чернила. Затем возьмите чернила и тонкий пергамент, и напишите предсказания для Воржея.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предсказания написаны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Воржею на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29516,'Пусть ярмарка сверкает','Актерам и животным ярмарки Новолуния требуется намного больше самоцветов, чем я мог подумать. К счастью, вместо самоцветов используются просто ограненные куски стекла, но кому-то все равно нужно этим заниматься.$b$bРаз ты не новичок в ювелирном деле, может быть, ты поможешь нам изготовить некоторое количество сверкающих стеклянных "самоцветов" для актеров?$b$bКрасивые осколки стекла иногда валяются прямо под ногами. Если взяться за дело умеючи, то из них могут получиться прекрасные "самоцветы".','Найдите на территории ярмарки Новолуния осколки стекла и изготовьте 5 сверкающих "самоцветов".','Прекрасная работа, Гррон. Сразу видно, что у тебя талант.','Получилось изготовить стеклянные "самоцветы" для костюмов актеров?','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть ярмарка сверкает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Актерам и животным ярмарки Новолуния требуется намного больше самоцветов, чем я мог подумать. К счастью, вместо самоцветов используются просто ограненные куски стекла, но кому-то все равно нужно этим заниматься.$b$bРаз ты не новичок в ювелирном деле, может быть, ты поможешь нам изготовить некоторое количество сверкающих стеклянных "самоцветов" для актеров?$b$bКрасивые осколки стекла иногда валяются прямо под ногами. Если взяться за дело умеючи, то из них могут получиться прекрасные "самоцветы".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на территории ярмарки Новолуния осколки стекла и изготовьте 5 сверкающих "самоцветов".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная работа, Гррон. Сразу видно, что у тебя талант.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось изготовить стеклянные "самоцветы" для костюмов актеров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29517,'Изготовление призов','Популярность ярмарочных развлечений растет, и это означает, что призы у нас расходятся все быстрее и быстрее!$b$bТак что нам нужны дополнительные призы и поскорее. Если ты умеешь работать с кожей, я могу дать тебе набор ремесленника. Придется докупить кое-что у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре, но это будут небольшие расходы.$b$bПоможешь?','Воспользуйтесь набором ремесленника ярмарки Новолуния, чтобы изготовить 5 призов Новолуния. Вам понадобится грубая нить, блесны и синяя краска.','Отлично получилось! Не отличишь от остальных. Спасибо тебе за помощь.$B$BЕсли тебе еще когда-нибудь захочется помастерить, загляни ко мне, когда ярмарка Новолуния снова будет в городе.','Получилось сделать призы?','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изготовление призов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Популярность ярмарочных развлечений растет, и это означает, что призы у нас расходятся все быстрее и быстрее!$b$bТак что нам нужны дополнительные призы и поскорее. Если ты умеешь работать с кожей, я могу дать тебе набор ремесленника. Придется докупить кое-что у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре, но это будут небольшие расходы.$b$bПоможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором ремесленника ярмарки Новолуния, чтобы изготовить 5 призов Новолуния. Вам понадобится грубая нить, блесны и синяя краска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично получилось! Не отличишь от остальных. Спасибо тебе за помощь.$B$BЕсли тебе еще когда-нибудь захочется помастерить, загляни ко мне, когда ярмарка Новолуния снова будет в городе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось сделать призы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29518,'Повторное использование и переработка','Посетители ярмарки обожают паровые танки! А после закрытия ярмарки здесь все будет завалено их деталями.$b$bБыло бы неправильно просто бросить в грязи такой качественный металл.$b$bЕсли ты поможешь мне собрать самые крупные детали, я смогу переплавить их на запчасти для еще действующих паровых танков. Покупать каждый раз новый металл слишком дорого. Что скажешь?','Соберите 6 деталей паровых танков на территории ярмарки Новолуния.','Отличные детали. Спасибо тебе за помощь. Они мне очень пригодятся, когда я примусь за ремонт паровых танков.$B$BВот, возьми это за работу.','Ты собрал детали? Здесь же их полно.','Вернитесь к Ринлингу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повторное использование и переработка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посетители ярмарки обожают паровые танки! А после закрытия ярмарки здесь все будет завалено их деталями.$b$bБыло бы неправильно просто бросить в грязи такой качественный металл.$b$bЕсли ты поможешь мне собрать самые крупные детали, я смогу переплавить их на запчасти для еще действующих паровых танков. Покупать каждый раз новый металл слишком дорого. Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 деталей паровых танков на территории ярмарки Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные детали. Спасибо тебе за помощь. Они мне очень пригодятся, когда я примусь за ремонт паровых танков.$B$BВот, возьми это за работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал детали? Здесь же их полно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29519,'Отскоблить шкуры','На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.$b$bПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.','Отскоблите 4 растянутые шкуры на ярмарке Новолуния.','Спасибо за помощь, Потомак. Я никогда не забуду то, что ты сделал для ярмарки Новолуния.$B$BЕсли хочешь, приходи как-нибудь еще, когда ярмарка будет в городе.','Вернитесь к Хроносу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отскоблить шкуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На ярмарке Новолуния всегда повышенный спрос на кожу – нужны палатки, обувь и много всего другого, что тебе даже и в голову не придет! Я поймал несколько животных, убил их и растянул шкуры на земле для дальнейшей обработки.$b$bПохоже, ты умеешь работать с кожей. Если поможешь отскоблить эти шкуры, я тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отскоблите 4 растянутые шкуры на ярмарке Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, Потомак. Я никогда не забуду то, что ты сделал для ярмарки Новолуния.$B$BЕсли хочешь, приходи как-нибудь еще, когда ярмарка будет в городе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29520,'Флаги, флаги повсюду!','Разве не чудесно видеть повсюду флаги ярмарки Новолуния? Это моя самая любимая часть приготовлений. Но многие наши флаги уже старые и потрепанные. Нужно их заменить.$b$bЕсли ты умеешь держать в руках иголку с ниткой, то, может быть, сделаешь новый флаг при помощи этого набора, а потом закрепишь его в одной из груд камней на территории ярмарки?$b$bОстальные необходимые тебе вещи можешь приобрести у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.','Воспользуйтесь набором для изготовления флага ярмарки Новолуния, чтобы сшить флаг ярмарки. Затем установите флаг, закрепив его в груде камней на территории ярмарки Новолуния.','Спасибо за помощь с флагами. У тебя определенно талант к портняжному делу. Когда ярмарка Новолуния в следующий раз будет в городе, приходи и помоги нам еще раз.','Вернитесь к Селине Дорман на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флаги, флаги повсюду!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разве не чудесно видеть повсюду флаги ярмарки Новолуния? Это моя самая любимая часть приготовлений. Но многие наши флаги уже старые и потрепанные. Нужно их заменить.$b$bЕсли ты умеешь держать в руках иголку с ниткой, то, может быть, сделаешь новый флаг при помощи этого набора, а потом закрепишь его в одной из груд камней на территории ярмарки?$b$bОстальные необходимые тебе вещи можешь приобрести у торговцев потребительскими товарами в Элвиннском лесу или в Мулгоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором для изготовления флага ярмарки Новолуния, чтобы сшить флаг ярмарки. Затем установите флаг, закрепив его в груде камней на территории ярмарки Новолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь с флагами. У тебя определенно талант к портняжному делу. Когда ярмарка Новолуния в следующий раз будет в городе, приходи и помоги нам еще раз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селине Дорман на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29521,'Поющие пруды','Мы непременно должны вернуть назад всех трех оставшихся духов целыми и невредимыми. Я слишком стар, чтобы справиться с этим сам. А Аисе и Цзи, при всех их достоинствах, не хватает гибкости ума.$b$bУ тебя же, помимо всех качеств, присущих настоящему герою, есть то, чего нет у них – умение находить равновесие. Именно ты $gдолжен:должна; сделать это.$b$bШу, дух воды, бродит возле Поющих прудов, что на востоке. Разыщи Аису, она поможет тебе найти его. Дальше все будет зависеть только от тебя.','Поговорите с Аисой Воспевающей Облака посреди Поющих прудов.','Рада снова видеть тебя, $n.$B$BТы, должно быть, уже $gпонял:поняла;, что купание в этом пруду превращает в скунса. За время существования Шэнь-Цзынь Су в этих некогда волшебных прудах погибло немало животных. Духи погибших слились с водой, и любой прикоснувшийся к этой воде обретает их облик.$B$BЗдесь есть несколько таких проклятых прудов, и некоторые из них опаснее прочих.','Рада снова видеть тебя, Стекломой.$B$BТы, должно быть, уже понял, что купание в этом пруду превращает в скунса. За время существования Шэнь-Цзынь Су в этих некогда волшебных прудах погибло немало животных. Духи погибших слились с водой, и любой прикоснувшийся к этой воде обретает их облик.$B$BЗдесь есть несколько таких проклятых прудов, и некоторые из них опаснее прочих.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поющие пруды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы непременно должны вернуть назад всех трех оставшихся духов целыми и невредимыми. Я слишком стар, чтобы справиться с этим сам. А Аисе и Цзи, при всех их достоинствах, не хватает гибкости ума.$b$bУ тебя же, помимо всех качеств, присущих настоящему герою, есть то, чего нет у них – умение находить равновесие. Именно ты $gдолжен:должна; сделать это.$b$bШу, дух воды, бродит возле Поющих прудов, что на востоке. Разыщи Аису, она поможет тебе найти его. Дальше все будет зависеть только от тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аисой Воспевающей Облака посреди Поющих прудов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рада снова видеть тебя, $n.$B$BТы, должно быть, уже $gпонял:поняла;, что купание в этом пруду превращает в скунса. За время существования Шэнь-Цзынь Су в этих некогда волшебных прудах погибло немало животных. Духи погибших слились с водой, и любой прикоснувшийся к этой воде обретает их облик.$B$BЗдесь есть несколько таких проклятых прудов, и некоторые из них опаснее прочих.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Рада снова видеть тебя, Стекломой.$B$BТы, должно быть, уже понял, что купание в этом пруду превращает в скунса. За время существования Шэнь-Цзынь Су в этих некогда волшебных прудах погибло немало животных. Духи погибших слились с водой, и любой прикоснувшийся к этой воде обретает их облик.$B$BЗдесь есть несколько таких проклятых прудов, и некоторые из них опаснее прочих.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29522,'Цзи, следующий по пути Хоцзинь','В деревне У-Сун, что на северо-западе, тебя ждет еще один из моих талантливейших учеников. Он не похож на Аису, но в своей противоположности они прекрасно дополняют друг друга.$B$BЦзи Огненная Лапа расскажет тебе, как подготовить подношения для духа огня. Доверься его мудрости.','Поговорите с Цзи Огненной Лапой в деревне У-Сун.','Здравствуй! Ты держишься так спокойно и уверенно... Мне это нравится!$B$BО тебе среди учеников ходят удивительные слухи. Если твои способности хотя бы наполовину так хороши, как все говорят, думаю, мы станем хорошими друзьями!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цзи, следующий по пути Хоцзинь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В деревне У-Сун, что на северо-западе, тебя ждет еще один из моих талантливейших учеников. Он не похож на Аису, но в своей противоположности они прекрасно дополняют друг друга.$B$BЦзи Огненная Лапа расскажет тебе, как подготовить подношения для духа огня. Доверься его мудрости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Цзи Огненной Лапой в деревне У-Сун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй! Ты держишься так спокойно и уверенно... Мне это нравится!$B$BО тебе среди учеников ходят удивительные слухи. Если твои способности хотя бы наполовину так хороши, как все говорят, думаю, мы станем хорошими друзьями!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29523,'Раздувание огня','Странная штука ветер – поймать его так просто невозможно.$B$BЕдинственный способ, как показывает моя практика, – это найти живой ветер. Если он может ударить тебя, то и ты можешь ударить его в ответ, и тогда он уже не проскользнет у тебя между пальцами.$B$BОтправляйся к Святилищу Летнего Бриза, что находится на юге, и призови живой ветер. Одолей его, добудь из него дрожащий бриз и возвращайся сюда. Тогда мы подумаем над нашими дальнейшими действиями.','Раздобудьте дрожащий бриз.','Ты знаешь, что это такое – ухватиться за шанс. Мы с тобой – родственные души, $n.','Когда нам предоставляется шанс, наша обязанность – протянуть руку и крепко за него ухватиться. Поддаться сомнению равносильно поражению.','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раздувание огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странная штука ветер – поймать его так просто невозможно.$B$BЕдинственный способ, как показывает моя практика, – это найти живой ветер. Если он может ударить тебя, то и ты можешь ударить его в ответ, и тогда он уже не проскользнет у тебя между пальцами.$B$BОтправляйся к Святилищу Летнего Бриза, что находится на юге, и призови живой ветер. Одолей его, добудь из него дрожащий бриз и возвращайся сюда. Тогда мы подумаем над нашими дальнейшими действиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте дрожащий бриз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты знаешь, что это такое – ухватиться за шанс. Мы с тобой – родственные души, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда нам предоставляется шанс, наша обязанность – протянуть руку и крепко за него ухватиться. Поддаться сомнению равносильно поражению.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе в деревню У-Сун.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29524,'Урок укрощения гордости','Бой с живым противником – совсем не то же самое, что тренировки с неподвижными манекенами. Живые противники дают отпор. В таком бою рождается страх потерпеть неудачу, а иногда – даже страх смерти.$B$BЧтобы преодолеть эти страхи, потребуются все твое мужество и смелость.$B$BСразись с другими учениками, что тренируются в храме или на площадке под лестницей, и одержи над ними победу.','Одержите победу над 6 учениками Хоцзинь или учениками Тушуй.','Любопытно.$B$BТы здесь не больше часа – а уже на равных сражаешься с опытными учениками.$B$BТы можешь многого добиться, но помни, что твое обучение еще только начинается.','Для всего есть свое время - как для медитации и созерцания, так и для активных действий. Найти равновесие между ними - значит обрести великую мудрость.','Вернитесь в храм к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок укрощения гордости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бой с живым противником – совсем не то же самое, что тренировки с неподвижными манекенами. Живые противники дают отпор. В таком бою рождается страх потерпеть неудачу, а иногда – даже страх смерти.$B$BЧтобы преодолеть эти страхи, потребуются все твое мужество и смелость.$B$BСразись с другими учениками, что тренируются в храме или на площадке под лестницей, и одержи над ними победу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над 6 учениками Хоцзинь или учениками Тушуй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любопытно.$B$BТы здесь не больше часа – а уже на равных сражаешься с опытными учениками.$B$BТы можешь многого добиться, но помни, что твое обучение еще только начинается.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Для всего есть свое время - как для медитации и созерцания, так и для активных действий. Найти равновесие между ними - значит обрести великую мудрость.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в храм к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29527,'Взятие укреплений','Начальник стражи Гарголмар и Вазруден Глашатай отвечают за защиту этих бастионов.$b$bЕсли расправиться с ними, то в рядах их подчиненных наступит полная паника.$b$bУбей их и предоставь мне доказательство того, что можно начинать атаку!','Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана каменному стражу Сток\'тону.','Эта операция зависит от твоего успеха, Месильщик.','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.','Подходи к нему осторожнее.','Назан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взятие укреплений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начальник стражи Гарголмар и Вазруден Глашатай отвечают за защиту этих бастионов.$b$bЕсли расправиться с ними, то в рядах их подчиненных наступит полная паника.$b$bУбей их и предоставь мне доказательство того, что можно начинать атаку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана каменному стражу Сток\'тону.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта операция зависит от твоего успеха, Месильщик.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Подходи к нему осторожнее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Назан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29528,'Взятие укреплений','Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана главному разведчику Чадвику.','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.','Подходи к нему осторожнее.','Назан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взятие укреплений',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начальника стражи Гарголмара, Вазрудена Глашатая и дракона Вазрудена, Назана. Принесите руку Гарголмара и голову Назана главному разведчику Чадвику.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Подходи к нему осторожнее.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Назан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29529,'Демоны в цитадели','Один из наших разведчиков предположительно заметил агента Пылающего Легиона на укреплениях. Если это правда, то Оплоту Чести может грозить серьезная опасность комбинированного нападения!$b$bУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.','Убейте Омора Неодолимого и принесите его копыто главному разведчику Чадвику.','Так это правда. Орки Скверны и Пылающий Легион объединились.','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоны в цитадели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших разведчиков предположительно заметил агента Пылающего Легиона на укреплениях. Если это правда, то Оплоту Чести может грозить серьезная опасность комбинированного нападения!$b$bУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Омора Неодолимого и принесите его копыто главному разведчику Чадвику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это правда. Орки Скверны и Пылающий Легион объединились.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29530,'Демоны в цитадели','Один из наших разведчиков вернулся с неприятными известиями. Он заметил могучего агента Пылающего Легиона на укреплениях!$B$BУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.','Убейте Омора Неодолимого и принесите его копыто каменному стражу Сток\'тону.','Ты расправился с порождением зла?','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоны в цитадели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших разведчиков вернулся с неприятными известиями. Он заметил могучего агента Пылающего Легиона на укреплениях!$B$BУбей этого демона прежде, чем он успеет передать сведения о наших действиях тем, кому он подчиняется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Омора Неодолимого и принесите его копыто каменному стражу Сток\'тону.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты расправился с порождением зла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29531,'Kill Stuff','I really need you to kill some stuff for me. It\'s pretty important.','Kill stuff for Questvendor.','Return to Questvendor.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kill Stuff',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I really need you to kill some stuff for me. It\'s pretty important.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Kill stuff for Questvendor.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Questvendor.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29532,'Темные вести','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть главный разведчик Чадвик!','Доставьте угрожающее письмо главному разведчику Чадвику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть главный разведчик Чадвик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте угрожающее письмо главному разведчику Чадвику.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29533,'Темные вести','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть каменный страж Сток\'тон!','Доставьте угрожающее письмо каменному стражу Сток\'тону.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть каменный страж Сток\'тон!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте угрожающее письмо каменному стражу Сток\'тону.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29534,'Collect Things','The Quest Wizard demands Stuff Tails! Go now and fetch them.','Collect 6 Stuff Tails for the Quest Wizard.','Return to the Quest Wizard on Designer Island.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Collect Things',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The Quest Wizard demands Stuff Tails! Go now and fetch them.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Collect 6 Stuff Tails for the Quest Wizard.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to the Quest Wizard on Designer Island.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29535,'Пустить кровь','Мастер создает все больше и больше орков Скверны, заражая их кровью демонов.$B$BМои руководители полагают, что мы можем обратить этот процесс, но для начала нам нужны образцы орочьей крови и жезл Мастера, чтобы все проверить.','Достаньте для Каса\'реса 10 фиалов крови орков и жезл вливания Скверны.','Возможно, эти фиалы помогут нам покончить с орками Скверны. Надеюсь, ты понимаешь, что от этого во многом зависит успех всей кампании.','Ты вернулся! Да еще и цел и невредим! Молодец. Ты справился с заданием намного лучше остальных.','Вернитесь к Каса\'ресу в Кузню Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустить кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер создает все больше и больше орков Скверны, заражая их кровью демонов.$B$BМои руководители полагают, что мы можем обратить этот процесс, но для начала нам нужны образцы орочьей крови и жезл Мастера, чтобы все проверить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте для Каса\'реса 10 фиалов крови орков и жезл вливания Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, эти фиалы помогут нам покончить с орками Скверны. Надеюсь, ты понимаешь, что от этого во многом зависит успех всей кампании.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся! Да еще и цел и невредим! Молодец. Ты справился с заданием намного лучше остальных.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каса\'ресу в Кузню Крови.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29536,'В сердце ярости','Мы знаем, что орки Скверны наращивают силы, заражая других орков кровью демонов.$B$BЯ хочу, чтобы ты $gпроник:проникла; в это темное место и $gузнал:узнала;, как они это делают. Рискованно посылать туда армию, пока мы не знаем, что нас ждет.','Детально изучите Кузню Крови и доложите о результатах Каса\'ресу.','<Вы рассказываете Каса\'ресу об увиденном в Кузне Крови.>$B$BПонятно.$B$BЕсли они творят подобные вещи с маг\'харскими коричневыми орками, то могут добраться и до нас! Нужно сохранять бдительность, иначе весь Траллмар превратиться в сборище безголовых монстров.','Детально изучите Кузню Крови','Вернитесь к Каса\'ресу в Кузню Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В сердце ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем, что орки Скверны наращивают силы, заражая других орков кровью демонов.$B$BЯ хочу, чтобы ты $gпроник:проникла; в это темное место и $gузнал:узнала;, как они это делают. Рискованно посылать туда армию, пока мы не знаем, что нас ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Детально изучите Кузню Крови и доложите о результатах Каса\'ресу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы рассказываете Каса\'ресу об увиденном в Кузне Крови.>$B$BПонятно.$B$BЕсли они творят подобные вещи с маг\'харскими коричневыми орками, то могут добраться и до нас! Нужно сохранять бдительность, иначе весь Траллмар превратиться в сборище безголовых монстров.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Детально изучите Кузню Крови',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каса\'ресу в Кузню Крови.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29537,'Найти просвет','"Несмотря на все усилия, наши шпионы не могут проникнуть в одну область в Кузне Крови.$B$BОни называют ее "просветом". Это достаточно большая область, в которой, видимо, и держат Магтеридона.$B$BНайди источник просвета и уничтожь его.','Убейте Кели\'дана Разрушителя и вернитесь к Каса\'ресу.','Преграда устранена, но мы все еще не можем проникнуть в эту область. Мы продолжим искать причину неудачи. Спасибо за помощь!','Вернитесь к Каса\'ресу в Кузню Крови.','В глубине таится некое могучее существо.','Кели\'дан Разрушитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти просвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Несмотря на все усилия, наши шпионы не могут проникнуть в одну область в Кузне Крови.$B$BОни называют ее "просветом". Это достаточно большая область, в которой, видимо, и держат Магтеридона.$B$BНайди источник просвета и уничтожь его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кели\'дана Разрушителя и вернитесь к Каса\'ресу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Преграда устранена, но мы все еще не можем проникнуть в эту область. Мы продолжим искать причину неудачи. Спасибо за помощь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каса\'ресу в Кузню Крови.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','В глубине таится некое могучее существо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кели\'дан Разрушитель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29538,'Пустить кровь','Мастер использует кровь демонов и специальный жезл, чтобы превращать коричневых и зеленых орков в красных. Мы хотим набрать немного этой крови, немного с ней поработать и затем испытать ее на орках всех цветов. Возможно, так у нас получится превратить их в безобидных и безвольных болванов.$B$BПринеси мне образцы их крови – посмотрим, что у нас получится сделать. Да – и не забудь прихватить жезл!','Достаньте для Пушкаренка 10 фиалов крови орков и жезл вливания Скверны.','Умопомрачительно! Все, теперь ты мой восьмой лучший друг в этих тлеющих останках жалкой планетенки!','Ну что, приятель, собрал кровь? Это очень важно, иначе мы бы тебя не просили ее достать.','Вернитесь к Пушкаренку в Кузню Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустить кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер использует кровь демонов и специальный жезл, чтобы превращать коричневых и зеленых орков в красных. Мы хотим набрать немного этой крови, немного с ней поработать и затем испытать ее на орках всех цветов. Возможно, так у нас получится превратить их в безобидных и безвольных болванов.$B$BПринеси мне образцы их крови – посмотрим, что у нас получится сделать. Да – и не забудь прихватить жезл!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте для Пушкаренка 10 фиалов крови орков и жезл вливания Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умопомрачительно! Все, теперь ты мой восьмой лучший друг в этих тлеющих останках жалкой планетенки!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, приятель, собрал кровь? Это очень важно, иначе мы бы тебя не просили ее достать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пушкаренку в Кузню Крови.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (29539,'В сердце ярости','Похоже, что болваны, сидящие в Оплоте Чести, вообще не представляют, что здесь происходит. Да это просто горстка никчемных, ленивых магов! По-другому их не назовешь!$B$BВ любом случае, мы и сами не можем понять, что тут творится. Нужно все выяснить!','Детально изучите Кузню Крови и доложите о результатах Пушкаренку.','Детально изучите Кузню Крови','Вернитесь к Пушкаренку в Кузню Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В сердце ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, что болваны, сидящие в Оплоте Чести, вообще не представляют, что здесь происходит. Да это просто горстка никчемных, ленивых магов! По-другому их не назовешь!$B$BВ любом случае, мы и сами не можем понять, что тут творится. Нужно все выяснить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Детально изучите Кузню Крови и доложите о результатах Пушкаренку.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Детально изучите Кузню Крови',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пушкаренку в Кузню Крови.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29540,'Разрушитель','Поступают донесения, что они держат там большого страшного демона, за которым следит специальный орк.$B$BОрк есть орк. Значит его нужно убить, $gсогласен:согласна;? Не важно, натворил он что-то или нет. Орков можно вырезать без разбору!','Убейте Кели\'дана Разрушителя и вернитесь к Пушкаренку.','Ты что, серьезно? Награду за какого-то несчастного орка? Хочешь славы, денег и благородных скакунов?$B$BА вот в мои годы убийство орка само по себе было наградой!','Вернитесь к Пушкаренку в Кузню Крови.','Сделайте ему больно.','Кели\'дан Разрушитель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поступают донесения, что они держат там большого страшного демона, за которым следит специальный орк.$B$BОрк есть орк. Значит его нужно убить, $gсогласен:согласна;? Не важно, натворил он что-то или нет. Орков можно вырезать без разбору!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кели\'дана Разрушителя и вернитесь к Пушкаренку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты что, серьезно? Награду за какого-то несчастного орка? Хочешь славы, денег и благородных скакунов?$B$BА вот в мои годы убийство орка само по себе было наградой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пушкаренку в Кузню Крови.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сделайте ему больно.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кели\'дан Разрушитель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (29541,'Take Care of It','This looks bad... you\'d better do something.','Resolve the dispute any way you see fit.','Resolve the dispute.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Take Care of It',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This looks bad... you\'d better do something.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Resolve the dispute any way you see fit.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Resolve the dispute.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29542,'Захват крепости','С одной стороны Траллмару угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.$b$bОтправляйся на запад, к Бастионам Адского Пламени, и поговори с каменным стражем Сток\'тоном. Он командует секретной операцией по началу наступления Орды на цитадель.','Поговорите с каменным стражем Сток\'тоном в Бастионах Адского Пламени.','Если следовать общепринятым канонам красоты, Лободроб не очень-то привлекателен. Но дело свое он знает. Давай-ка найдем тебе работу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С одной стороны Траллмару угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.$b$bОтправляйся на запад, к Бастионам Адского Пламени, и поговори с каменным стражем Сток\'тоном. Он командует секретной операцией по началу наступления Орды на цитадель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Сток\'тоном в Бастионах Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если следовать общепринятым канонам красоты, Лободроб не очень-то привлекателен. Но дело свое он знает. Давай-ка найдем тебе работу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29543,'Захват крепости','С одной стороны Оплоту Чести угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.$b$bОтправляйся на запад, к Бастионам Адского Пламени, и поговори с главным разведчиком Чадвиком. Он координирует секретную операцию по началу наступления Альянса на цитадель.','Поговорите с главным разведчиком Чадвиком в Бастионах Адского Пламени.','Альтума просто молодец, не правда ли? Но никого из нас не было бы в живых, если бы мы не умели сражаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С одной стороны Оплоту Чести угрожает Легион, с другой – орки Скверны, и крепость непременно захватят, если мы ничего не предпримем.$b$bОтправляйся на запад, к Бастионам Адского Пламени, и поговори с главным разведчиком Чадвиком. Он координирует секретную операцию по началу наступления Альянса на цитадель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным разведчиком Чадвиком в Бастионах Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альтума просто молодец, не правда ли? Но никого из нас не было бы в живых, если бы мы не умели сражаться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29544,'Кузня Крови','Каса\'рес ждет тебя в Кузне Крови. Он уже расчистил небольшой участок и привлек к работе провидцев, чтобы понять, что там происходит.$b$bНо мне не кажется, что этого будет достаточно. Наверняка у Каса\'реса найдется задание для одного или двух бравых воинов. Отправляйся туда и предложи ему свою помощь в решении проблемы с орками Скверны.','Поговорите с Каса\'ресом в Кузне Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузня Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каса\'рес ждет тебя в Кузне Крови. Он уже расчистил небольшой участок и привлек к работе провидцев, чтобы понять, что там происходит.$b$bНо мне не кажется, что этого будет достаточно. Наверняка у Каса\'реса найдется задание для одного или двух бравых воинов. Отправляйся туда и предложи ему свою помощь в решении проблемы с орками Скверны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Каса\'ресом в Кузне Крови.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29545,'Кузня Крови') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузня Крови',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29546,'Склонить чашу весов','Эти мерзкие дикие обезьяны не дают нам покоя с того самого дня, как мы ступили на берег!$b$bПоначалу мы держались, но потом они похитили половину наших бойцов, включая адмирала.$b$bТы только посмотри, сколько их! Им нет числа, мы держимся из последних сил.$b$bЕсли ты здесь для того, чтобы помочь нам, то прикончи хоть сколько-нибудь обезьян.$b$bЛибо мы, либо они... |3-6($r)!','Убейте 12 хозенов-опустошителей.','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Склонить чашу весов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти мерзкие дикие обезьяны не дают нам покоя с того самого дня, как мы ступили на берег!$b$bПоначалу мы держались, но потом они похитили половину наших бойцов, включая адмирала.$b$bТы только посмотри, сколько их! Им нет числа, мы держимся из последних сил.$b$bЕсли ты здесь для того, чтобы помочь нам, то прикончи хоть сколько-нибудь обезьян.$b$bЛибо мы, либо они... |3-6($r)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 хозенов-опустошителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29547,'Приказ короля','Приветствую тебя, |3-6($c).$B$BМне поручено собрать команду для выполнения особо важного задания.$B$BТебе надлежит немедленно явиться в крепость Штормграда на аудиенцию к королю Вариану Ринну. Я буду ждать в зале Войны.','Найдите Верховного адмирала Джес-Терет, которая находится в зале Войны крепости Штормграда.','Для нас есть задание величайшей важности. Адмирал Тейлор и его корабль пропали. Более того, юный Принц исчез вместе с ним, и наша первейшая задача – вернуть его домой в целости и сохранности.','Это дело невероятно срочное... и секретное.','Верховный адмирал Джес-Терет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ короля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c).$B$BМне поручено собрать команду для выполнения особо важного задания.$B$BТебе надлежит немедленно явиться в крепость Штормграда на аудиенцию к королю Вариану Ринну. Я буду ждать в зале Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Верховного адмирала Джес-Терет, которая находится в зале Войны крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для нас есть задание величайшей важности. Адмирал Тейлор и его корабль пропали. Более того, юный Принц исчез вместе с ним, и наша первейшая задача – вернуть его домой в целости и сохранности.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это дело невероятно срочное... и секретное.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный адмирал Джес-Терет',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29548,'Задание','Что ж, ты $gслышал:слышала; короля. Последний раз адмирал Тейлор выходил на связь откуда-то из южных морей.$b$bМы начнем наши поиски с воздуха. Обнаружение принца – Белой Пешки – задача первостепенной важности.$b$b"Небесный огонь" заправлен топливом, загружен припасами и готов к отбытию. Он парит в северной части гавани.$b$bЗаканчивай приготовления и поговори с адмиралом Роджерс на палубе. Отправляемся без промедления.','Поговорите с адмиралом Роджерс на борту "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, ты $gслышал:слышала; короля. Последний раз адмирал Тейлор выходил на связь откуда-то из южных морей.$b$bМы начнем наши поиски с воздуха. Обнаружение принца – Белой Пешки – задача первостепенной важности.$b$b"Небесный огонь" заправлен топливом, загружен припасами и готов к отбытию. Он парит в северной части гавани.$b$bЗаканчивай приготовления и поговори с адмиралом Роджерс на палубе. Отправляемся без промедления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с адмиралом Роджерс на борту "Небесного огня".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29549,'Распорядитель полетов пропал','Я составил список тех, кто пропал, и среди них Доновар Муралл, наш распорядитель полетов.$b$bОн не только жизненно важный член нашей команды, но еще и наш дорогой друг.$b$bПожалуйста, разыщи его и приведи сюда целым и невредимым.','Поговорите с Доноваром Мураллом в Зеленой роще.','Вернитесь к первому помощнику Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распорядитель полетов пропал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я составил список тех, кто пропал, и среди них Доновар Муралл, наш распорядитель полетов.$b$bОн не только жизненно важный член нашей команды, но еще и наш дорогой друг.$b$bПожалуйста, разыщи его и приведи сюда целым и невредимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Доноваром Мураллом в Зеленой роще.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к первому помощнику Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29550,'Спасение Пушинки','<Увидев вас, Доновар заливается слезами.>$B$BП-п-проклятые обезьяны у-у-утащили меня в лес. Я решил, что мне кранты, но тут на выручку прилетела моя верная Пушинка!$B$BОна попыталась их отогнать, и они все набросились на нее! Она тяжело ранена, а в лесу столько этих обезьян... Ей...$B$B<Доновар громко сморкается.>$B$B... Ей не жить! А-а-а! Если только...$B$B$C, слушай, тут в лесу полно имбирного листа. Умоляю, набери немножко этого целительного растения – может, это поможет ее спасти!','Принесите 4 имбирных листа для Пушинки.','Вернитесь к распорядителю полетов Доновару Мураллу в Зеленую рощу, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Пушинки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Увидев вас, Доновар заливается слезами.>$B$BП-п-проклятые обезьяны у-у-утащили меня в лес. Я решил, что мне кранты, но тут на выручку прилетела моя верная Пушинка!$B$BОна попыталась их отогнать, и они все набросились на нее! Она тяжело ранена, а в лесу столько этих обезьян... Ей...$B$B<Доновар громко сморкается.>$B$B... Ей не жить! А-а-а! Если только...$B$B$C, слушай, тут в лесу полно имбирного листа. Умоляю, набери немножко этого целительного растения – может, это поможет ее спасти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 имбирных листа для Пушинки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к распорядителю полетов Доновару Мураллу в Зеленую рощу, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29551,'Луговые охотники','Мы все еще пытаемся составить список пропавших в суматохе боя.$b$bБоюсь, многие из них сейчас блуждают в лесах. Возможно, они ранены и борются за свою жизнь.$b$bНам известно, что лес к северу отсюда кишит злобными тиграми.$b$bИди и убей их. Этим ты дашь нашим бойцам лишний шанс на выживание.','Убейте 8 луговых охотников.','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Луговые охотники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы все еще пытаемся составить список пропавших в суматохе боя.$b$bБоюсь, многие из них сейчас блуждают в лесах. Возможно, они ранены и борются за свою жизнь.$b$bНам известно, что лес к северу отсюда кишит злобными тиграми.$b$bИди и убей их. Этим ты дашь нашим бойцам лишний шанс на выживание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 луговых охотников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29552,'Критическое состояние','Мы вышли победителями из первой битвы, но ситуация остается критической.$b$bВо время первого воздушного боя десятки членов команды "Небесного огня" были ранены.$b$bЕсли не оказать им медицинскую помощь, то состояние их будет только ухудшаться вплоть до их кончины. Мы – их единственная надежда на спасение.$b$bОтправляйся в рощу и помоги всем матросам, кому только сможешь.$b$bМы не бросим ни одного из них.','Помогите 6 раненым пилотам в роще Лап\'дон. Для этого можно использовать целительные заклинания или бинты.','Ты хорошо поработала, Иура. Благодаря тебе эти солдаты будут жить и сражаться.','Вернитесь к Мишке в деревню Лап\'дон, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Критическое состояние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вышли победителями из первой битвы, но ситуация остается критической.$b$bВо время первого воздушного боя десятки членов команды "Небесного огня" были ранены.$b$bЕсли не оказать им медицинскую помощь, то состояние их будет только ухудшаться вплоть до их кончины. Мы – их единственная надежда на спасение.$b$bОтправляйся в рощу и помоги всем матросам, кому только сможешь.$b$bМы не бросим ни одного из них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите 6 раненым пилотам в роще Лап\'дон. Для этого можно использовать целительные заклинания или бинты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо поработала, Иура. Благодаря тебе эти солдаты будут жить и сражаться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в деревню Лап\'дон, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29553,'Пропавший адмирал','Итак, по собранным тобой уликам получается, что это корабль Андуина, а капитаном на нем был адмирал Тейлор. \r\n\r\nВ последней записи адмирал пишет, что после кораблекрушения на судно напали хозены и он намерен защищать его до последнего.\r\n\r\nПо рассказам местных жителей хозены иногда берут пленных. Кроме того, среди обломков мы не нашли труп адмирала Тейлора. Это значит, что он может находиться в укреплении хозенов к северо-востоку отсюда.\r\n\r\nОтправляйся туда, нельзя терять ни минуты!','Найдите адмирала Тейлора.','<Вы нашли адмирала, но он без сознания и, похоже, на краю гибели.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший адмирал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, по собранным тобой уликам получается, что это корабль Андуина, а капитаном на нем был адмирал Тейлор. \r\n\r\nВ последней записи адмирал пишет, что после кораблекрушения на судно напали хозены и он намерен защищать его до последнего.\r\n\r\nПо рассказам местных жителей хозены иногда берут пленных. Кроме того, среди обломков мы не нашли труп адмирала Тейлора. Это значит, что он может находиться в укреплении хозенов к северо-востоку отсюда.\r\n\r\nОтправляйся туда, нельзя терять ни минуты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите адмирала Тейлора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы нашли адмирала, но он без сознания и, похоже, на краю гибели.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29554,'Затонувший мусор','Привет, $n!$B$BВесь берег буквально усыпан разным хламом и обломками корабля.$B$BНа первый взгляд, может показаться, что это просто мусор, но у меня все пойдет в дело! Однажды мне удалось починить подводную лодку с помощью бронзовой трубочки и мочалки!!$B$BПройдись по берегу возле корабля и набери мне всякой всячины. Она понадобится мне для следующего проекта.','Соберите 8 промокших обломков.','Вернитесь к Узлику на Сапфировый берег в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувший мусор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n!$B$BВесь берег буквально усыпан разным хламом и обломками корабля.$B$BНа первый взгляд, может показаться, что это просто мусор, но у меня все пойдет в дело! Однажды мне удалось починить подводную лодку с помощью бронзовой трубочки и мочалки!!$B$BПройдись по берегу возле корабля и набери мне всякой всячины. Она понадобится мне для следующего проекта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 промокших обломков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узлику на Сапфировый берег в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29555,'Белая Пешка','Так, солдат. У меня для тебя задание первостепенной важности.\r\n\r\nОтправляйся на берег к югу отсюда – там в пещере ты найдешь разбитый корабль Альянса. Ты $gдолжен:должна; обыскать его и установить, перевозили ли на нем Андуина.\r\n\r\nЗатем найди судовой журнал и поищи в нем какие-нибудь сведения о его возможном местонахождении.\r\n\r\nТак как это военное судно, то журнал будет зашифрован, поэтому отнеси его для анализа Узлику Шифролому. Он следит за обломками с другой стороны пещеры.','Обыщите Обломки "Авангарда" в Нефритовом лесу и установите, что перевозилось на корабле, а также найдите зашифрованный судовой журнал.','Так-с.. дай-ка взгляну... использование шифра с того момента, когда корабль пропал без вести...$B$B<Узлик определенно что-то прикидывает в голове.>$B$BЕсть!','Как там?','Вернитесь к Узлику Шифролому на Обломки "Авангарда" в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Белая Пешка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, солдат. У меня для тебя задание первостепенной важности.\r\n\r\nОтправляйся на берег к югу отсюда – там в пещере ты найдешь разбитый корабль Альянса. Ты $gдолжен:должна; обыскать его и установить, перевозили ли на нем Андуина.\r\n\r\nЗатем найди судовой журнал и поищи в нем какие-нибудь сведения о его возможном местонахождении.\r\n\r\nТак как это военное судно, то журнал будет зашифрован, поэтому отнеси его для анализа Узлику Шифролому. Он следит за обломками с другой стороны пещеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Обломки "Авангарда" в Нефритовом лесу и установите, что перевозилось на корабле, а также найдите зашифрованный судовой журнал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-с.. дай-ка взгляну... использование шифра с того момента, когда корабль пропал без вести...$B$B<Узлик определенно что-то прикидывает в голове.>$B$BЕсть!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узлику Шифролому на Обломки "Авангарда" в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29556,'Хозены – не друзья, хозены – враги','На юге мы обнаружили обломки корабля Альянса. К несчастью, местные жители рассказали нам, что там мародерствуют существа, которых они называют "хозены".\r\n\r\nГрабя наши разбитые корабли, эти существа дали нам ясно понять, что ни о каком дружелюбии с их стороны речи не идет. Мы не можем позволить им брать трофеи с наших кораблей, воровать наши припасы и, что куда хуже, брать в плен или убивать тех, кто остался в живых.\r\n\r\nОтправляйся туда и разберись с ними! Когда закончишь, поговори с Узликом Шифроломом – нашим агентом ШРУ в этих местах.','Убейте 14 хозенов на Обломках "Авангарда".','Отличная работа. Грязные создания пытались воспользоваться нашей слабостью…$B$BЭто научит их и близко не подходить к кораблям Альянса!','Поговорите с Узликом Шифроломом на Обломках "Авангарда" в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозены – не друзья, хозены – враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юге мы обнаружили обломки корабля Альянса. К несчастью, местные жители рассказали нам, что там мародерствуют существа, которых они называют "хозены".\r\n\r\nГрабя наши разбитые корабли, эти существа дали нам ясно понять, что ни о каком дружелюбии с их стороны речи не идет. Мы не можем позволить им брать трофеи с наших кораблей, воровать наши припасы и, что куда хуже, брать в плен или убивать тех, кто остался в живых.\r\n\r\nОтправляйся туда и разберись с ними! Когда закончишь, поговори с Узликом Шифроломом – нашим агентом ШРУ в этих местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 14 хозенов на Обломках "Авангарда".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Грязные создания пытались воспользоваться нашей слабостью…$B$BЭто научит их и близко не подходить к кораблям Альянса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Узликом Шифроломом на Обломках "Авангарда" в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29557,'Задание продолжается','Флагманский корабль короля затонул неподалеку от этого места.$b$bПо всей вероятности, команда корабля просигнализировала об успешной высадке, но когда за принцем пришли, выяснилось, что он исчез.$b$bНужно обследовать обломки, вдруг найдутся какие-то улики.$b$bУзлик и Салли уже на месте крушения. Иди вдоль пляжа на восток и узнай, не нужна ли им помощь.','Поговорите с Узликом на Сапфировом берегу в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Флагманский корабль короля затонул неподалеку от этого места.$b$bПо всей вероятности, команда корабля просигнализировала об успешной высадке, но когда за принцем пришли, выяснилось, что он исчез.$b$bНужно обследовать обломки, вдруг найдутся какие-то улики.$b$bУзлик и Салли уже на месте крушения. Иди вдоль пляжа на восток и узнай, не нужна ли им помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Узликом на Сапфировом берегу в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29558,'На тропе войны','Вижу, ты хочешь спасти своего друга. Если ты поможешь мне, то я помогу тебе.$b$bПрежде всего, ты и $gсам должен:сама должна; понимать, что чем меньше хозенов из племени Ловкого Хвоста будет поблизости, тем проще будет отсюда выбраться.$b$bУбей хозенов, которые охраняют клетки, – это будет еще одним шагом к свободе.','Убейте 12 древолазов или шаманов из племени Ловкого Хвоста.','Ха-ха-ха! У тебя храброе сердце.$B$BЭто достойно восхищения.','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На тропе войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты хочешь спасти своего друга. Если ты поможешь мне, то я помогу тебе.$b$bПрежде всего, ты и $gсам должен:сама должна; понимать, что чем меньше хозенов из племени Ловкого Хвоста будет поблизости, тем проще будет отсюда выбраться.$b$bУбей хозенов, которые охраняют клетки, – это будет еще одним шагом к свободе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 древолазов или шаманов из племени Ловкого Хвоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! У тебя храброе сердце.$B$BЭто достойно восхищения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29559,'Свободу нашим братьям!','Может быть, ты и $gчужеземец:чужеземка;, но враги у нас с тобой общие – хозены.$b$bЗдесь повсюду расставлены клетки, в которых томятся мои сородичи. И солдат Альянса я тоже видел среди пленников.$b$bЯ не могу уйти, не освободив своих собратьев, как и ты не можешь оставить своих.$b$bКлючи от клеток у хозенов из племени Ловкого Хвоста. Найди ключи и освободи наших друзей.','Освободите 6 пленных цзинь-юй или узников из Альянса.','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу нашим братьям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, ты и $gчужеземец:чужеземка;, но враги у нас с тобой общие – хозены.$b$bЗдесь повсюду расставлены клетки, в которых томятся мои сородичи. И солдат Альянса я тоже видел среди пленников.$b$bЯ не могу уйти, не освободив своих собратьев, как и ты не можешь оставить своих.$b$bКлючи от клеток у хозенов из племени Ловкого Хвоста. Найди ключи и освободи наших друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 пленных цзинь-юй или узников из Альянса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29560,'Древнее могущество','В моей деревне черепа хозенов – это ценные трофеи. Они нужны нам для разных ритуалов, и чем старше череп, тем сильнее его магические свойства.$B$BК счастью для нас, хозены – грязные и легкомысленные твари. Они оставляют черепа мертвых повсюду, даже в своих лагерях и домах.$B$BПринеси мне несколько черепов, и я щедро тебя награжу.','Соберите 8 древних черепов хозенов.','Твоя находчивость радует меня, Лайрим. Мой народ очень ценит это достоинство.$B$BОтличные образцы, которые ты мне принесла, создадут мощную магию.','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее могущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В моей деревне черепа хозенов – это ценные трофеи. Они нужны нам для разных ритуалов, и чем старше череп, тем сильнее его магические свойства.$B$BК счастью для нас, хозены – грязные и легкомысленные твари. Они оставляют черепа мертвых повсюду, даже в своих лагерях и домах.$B$BПринеси мне несколько черепов, и я щедро тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 древних черепов хозенов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя находчивость радует меня, Лайрим. Мой народ очень ценит это достоинство.$B$BОтличные образцы, которые ты мне принесла, создадут мощную магию.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29561,'Наперекор судьбе','$c, до главной базы добрались только мы с тобой.$B$BЯ видел, как другие агенты ШРУ выбросились над лесом к северу отсюда.$B$BСкорее беги туда и постарайся спасти тех, кто выжил.','Найдите пропавших агентов ШРУ.','Поговорите с Мишкой у места крушения в Зеленой роще, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наперекор судьбе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, до главной базы добрались только мы с тобой.$B$BЯ видел, как другие агенты ШРУ выбросились над лесом к северу отсюда.$B$BСкорее беги туда и постарайся спасти тех, кто выжил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите пропавших агентов ШРУ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мишкой у места крушения в Зеленой роще, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29562,'Побег из тюрьмы','Без лечения твой друг Тейлор умрет. Моя деревня находится к востоку отсюда, посреди большого озера.$b$bЯ возьму Тейлора на себя, но двигаться в том направлении крайне опасно.$b$bМне нужно, чтобы ты $gрасчистил:расчистила; путь от хозенов, чтобы я мог в целости и сохранности добраться до деревни.$b$bСможешь?','Убейте 10 опустошителей из племени Ловкого Хвоста.','Спасибо тебе, Лайрим. Благодаря тебе мы благополучно добрались сюда.','Поговорите со Здоровяком Кажаши в деревне Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из тюрьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Без лечения твой друг Тейлор умрет. Моя деревня находится к востоку отсюда, посреди большого озера.$b$bЯ возьму Тейлора на себя, но двигаться в том направлении крайне опасно.$b$bМне нужно, чтобы ты $gрасчистил:расчистила; путь от хозенов, чтобы я мог в целости и сохранности добраться до деревни.$b$bСможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 опустошителей из племени Ловкого Хвоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, Лайрим. Благодаря тебе мы благополучно добрались сюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Здоровяком Кажаши в деревне Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29563,'Пропавшие без вести','Ты $gдолжен:должна; мне помочь! Нас отправили сюда, чтобы мы осмотрели различные части резервуара, но мои друзья до сих пор не вернулись, а времени уже прошло очень много.$B$BМне нужно, чтобы ты $gузнал:узнала;, что с ними стряслось. Натуралист Кус и культиватор Зеленопал отправились вон туда.','Выясните, что случилось с натуралистом Кусом и культиватором Зеленопалом, после чего возвращайтесь к дозорной Джанг.','Вернитесь к дозорной Джанг в Узилище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие без вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдолжен:должна; мне помочь! Нас отправили сюда, чтобы мы осмотрели различные части резервуара, но мои друзья до сих пор не вернулись, а времени уже прошло очень много.$B$BМне нужно, чтобы ты $gузнал:узнала;, что с ними стряслось. Натуралист Кус и культиватор Зеленопал отправились вон туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, что случилось с натуралистом Кусом и культиватором Зеленопалом, после чего возвращайтесь к дозорной Джанг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Джанг в Узилище.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29564,'Преданный брат','Моя деревня поначалу кое-как держалась под натиском наг. Наверное, мы все смогли бы пробиться в Награнд, кабы не мой брат. В обмен на свою свободу он продал всех нас.$B$BА теперь он служит здесь надсмотрщиком, и его кнут без устали гуляет по спинам его же братьев. Пусть Менну сполна заплатит за предательство, |3-6($r).','Убейте Менну Предателя и возвращайтесь к Нахууду.','Смерть Менну не залечит шрамов от его бича на спинах моих родственников и друзей – но теперь у них хотя бы будет возможность дожить свой век на свободе.','Вернитесь к Нахууду в Узилище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преданный брат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя деревня поначалу кое-как держалась под натиском наг. Наверное, мы все смогли бы пробиться в Награнд, кабы не мой брат. В обмен на свою свободу он продал всех нас.$B$BА теперь он служит здесь надсмотрщиком, и его кнут без устали гуляет по спинам его же братьев. Пусть Менну сполна заплатит за предательство, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Менну Предателя и возвращайтесь к Нахууду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смерть Менну не залечит шрамов от его бича на спинах моих родственников и друзей – но теперь у них хотя бы будет возможность дожить свой век на свободе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нахууду в Узилище.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29565,'Суть дела','Нахууд поведал мне, что два могучих создания, Рокмар Трескун и Зыбун, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.$B$BМне больно просить тебя об этом, но их необходимо уничтожить.','Принесите дозорной Джанг Коготь захватчика и Глаз повелителя рабов.','Отрадно, что их души наконец-то освободились – жаль только, что многим из их сородичей пока не суждено обрести покоя.$B$BНам предстоит еще очень многое сделать – особенно здесь, в Кривом Клыке.','Ты убил их?','Вернитесь к дозорной Джанг в Узилище.','Его не спасти.','Зыбун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суть дела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нахууд поведал мне, что два могучих создания, Рокмар Трескун и Зыбун, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.$B$BМне больно просить тебя об этом, но их необходимо уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите дозорной Джанг Коготь захватчика и Глаз повелителя рабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отрадно, что их души наконец-то освободились – жаль только, что многим из их сородичей пока не суждено обрести покоя.$B$BНам предстоит еще очень многое сделать – особенно здесь, в Кривом Клыке.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты убил их?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Джанг в Узилище.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его не спасти.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зыбун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29566,'Наведение справок','Поговорите с дозорной Джанг в Узилище.','Что ты здесь делаешь? Ты что, не видишь, что это очень опасное место?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наведение справок',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дозорной Джанг в Узилище.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ты здесь делаешь? Ты что, не видишь, что это очень опасное место?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29567,'Охота на Охотницу','Споровые великаны, может, и нападают на моих сородичей, но болотоброды отняли больше невинных жизней, чем кто бы то ни было. Это наши древние враги.$B$BИх прародительница, Черная Охотница, обитает в самой глубине топей. Если ты убьешь ее и принесешь мне в качестве доказательства ее мозг, я буду рассказывать о твоей храбрости своим внукам.','Принесите Тшу мозг Черной Охотницы.','Ты вернулся. Означает ли это, что Черной Охотницы больше нет?','Вернитесь к Тшу в Нижетопь.','Она намного сильнее, чем все ее сородичи.','Черная Охотница') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на Охотницу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Споровые великаны, может, и нападают на моих сородичей, но болотоброды отняли больше невинных жизней, чем кто бы то ни было. Это наши древние враги.$B$BИх прародительница, Черная Охотница, обитает в самой глубине топей. Если ты убьешь ее и принесешь мне в качестве доказательства ее мозг, я буду рассказывать о твоей храбрости своим внукам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тшу мозг Черной Охотницы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся. Означает ли это, что Черной Охотницы больше нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тшу в Нижетопь.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она намного сильнее, чем все ее сородичи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Черная Охотница',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29568,'Необходимое зло','Топеглад и Зыбун в былые времена вместе правили, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.$B$BМне больно просить тебя об этом, но их необходимо уничтожить.','Убейте Топеглада, после чего возвращайтесь к натуралисту Кусу.','Сегодня ты оказал услугу всей Зангартопи, Месильщик. Споровые гиганты могут быть агрессивны, но они все равно являются важной частью экосистемы.','Поговорите с натуралистом Кусом в Нижетопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необходимое зло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Топеглад и Зыбун в былые времена вместе правили, стали одними из первых, кого поработили вторгшиеся наги. Потом они помогли им покорить множество обитателей Зангартопи.$B$BМне больно просить тебя об этом, но их необходимо уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Топеглада, после чего возвращайтесь к натуралисту Кусу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня ты оказал услугу всей Зангартопи, Месильщик. Споровые гиганты могут быть агрессивны, но они все равно являются важной частью экосистемы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с натуралистом Кусом в Нижетопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29569,'Бесценный питомец полководца Калитреша','Полководец Калитреш растит в Нижетопи могучую гидру по имени Газ\'ан, которую он собирается напустить на Зангартопь, как только та достаточно вырастет.$B$BБоюсь, что если эта тварь наберет силу, остановить ее не сможет никто. Найди Газ\'ана и убей его – ради всеобщего блага.','Убейте Газ\'ана и принесите его чешуйку дозорной Джанг.','Вернитесь к дозорной Джанг в Нижетопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесценный питомец полководца Калитреша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полководец Калитреш растит в Нижетопи могучую гидру по имени Газ\'ан, которую он собирается напустить на Зангартопь, как только та достаточно вырастет.$B$BБоюсь, что если эта тварь наберет силу, остановить ее не сможет никто. Найди Газ\'ана и убей его – ради всеобщего блага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Газ\'ана и принесите его чешуйку дозорной Джанг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Джанг в Нижетопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29570,'Спасение экспедиции','Последние члены моей экспедиции должны быть где-то поблизости. Без них и собранных ими сведений у нас против наг не будет никаких шансов.$B$BПостарайся отыскать землепряда Гневвса и призывателя ветров Когтя. Я очень надеюсь, что с ними все в порядке.','Выясните, что случилось с землепрядом Гневвсом и призывателем ветров Когтем, после чего возвращайтесь к дозорной Джанг.','Скоро мы все снова соберемся вместе, и этим я обязана тебе!$B$BТеперь нагам точно придет конец. Против нас у них не будет ни единого шанса!','Вернитесь к дозорной Джанг в Нижетопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение экспедиции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последние члены моей экспедиции должны быть где-то поблизости. Без них и собранных ими сведений у нас против наг не будет никаких шансов.$B$BПостарайся отыскать землепряда Гневвса и призывателя ветров Когтя. Я очень надеюсь, что с ними все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, что случилось с землепрядом Гневвсом и призывателем ветров Когтем, после чего возвращайтесь к дозорной Джанг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро мы все снова соберемся вместе, и этим я обязана тебе!$B$BТеперь нагам точно придет конец. Против нас у них не будет ни единого шанса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Джанг в Нижетопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29571,'Защита природы','Служителям Земли часто доводилось сотрудничать с друидами Круга Кенария. Сейчас тоже как раз такой случай.$B$BОтправляйся на север в Нижетопь, отыщи там дозорную Джанг и поговори с ней. Она руководит экспедицией в Резервуар Кривого Клыка, задача которой – остановить наг и спасти Зангартопь.','Поговорите с дозорной Джанг в Нижетопи.','Нижетопь вот-вот станет очередной частью насосной системы наг в Кривом Клыке! Ты должен нам помочь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служителям Земли часто доводилось сотрудничать с друидами Круга Кенария. Сейчас тоже как раз такой случай.$B$BОтправляйся на север в Нижетопь, отыщи там дозорную Джанг и поговори с ней. Она руководит экспедицией в Резервуар Кривого Клыка, задача которой – остановить наг и спасти Зангартопь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дозорной Джанг в Нижетопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нижетопь вот-вот станет очередной частью насосной системы наг в Кривом Клыке! Ты должен нам помочь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29572,'Прежде всего – безопасность!','Эфириалы Шаффара полностью перекрыли нам вход в Гробницы Маны. К счастью, у меня есть план. Мы не можем воспользоваться главным входом, но внутри должно быть несколько порталов.$B$BЯ хочу, чтобы ты сначала $gрасчистил:расчистила; дорогу для моей команды, а затем $gактивировал:активировала; один из порталов, чтобы телепортировать нас внутрь.$B$BПортал находится в комнате направо от входа в залы Шаффара. Не беспокойся, я заплачу тебе за работу...','Вернитесь к пульту управления астрального телепорта в Хилсбрадские поля, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прежде всего – безопасность!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эфириалы Шаффара полностью перекрыли нам вход в Гробницы Маны. К счастью, у меня есть план. Мы не можем воспользоваться главным входом, но внутри должно быть несколько порталов.$B$BЯ хочу, чтобы ты сначала $gрасчистил:расчистила; дорогу для моей команды, а затем $gактивировал:активировала; один из порталов, чтобы телепортировать нас внутрь.$B$BПортал находится в комнате направо от входа в залы Шаффара. Не беспокойся, я заплачу тебе за работу...',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пульту управления астрального телепорта в Хилсбрадские поля, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29573,'Прежде всего – безопасность!','Теперь почти ничего не мешает нашей команде проникнуть внутрь и взять то, что и так принадлежит нам по праву. Теперь главную опасность представляет личная охрана Шаффара.$b$bМне нужно восстановить силы. А ты пока займись его войсками.','Великолепно! Харамад будет счастлив услышать хорошие новости! Теперь все это принадлежит ему!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прежде всего – безопасность!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь почти ничего не мешает нашей команде проникнуть внутрь и взять то, что и так принадлежит нам по праву. Теперь главную опасность представляет личная охрана Шаффара.$b$bМне нужно восстановить силы. А ты пока займись его войсками.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Харамад будет счастлив услышать хорошие новости! Теперь все это принадлежит ему!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29574,'Интригующие образцы','В этих залах, не очень далеко отсюда, обитает существо по имени Пандемоний, которое черпает силы из энергии Бездны.$b$bА немного дальше находится Таварок, существо, которое ту же самую энергию Бездны превращает в кристаллическую структуру, крепче которой я еще никогда не видел!$b$bМне непременно нужно получить образцы для изучения.','Принесите сущность Пандемония и сердце Таварока Мамди по кличке "Олог".','Потрясающие образцы! Они прекрасно подойдут.','Если у тебя нет того, что мне нужно, то не отнимай у меня времени.','Вернитесь к Мамди по кличке "Олог" в гробницы Маны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интригующие образцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих залах, не очень далеко отсюда, обитает существо по имени Пандемоний, которое черпает силы из энергии Бездны.$b$bА немного дальше находится Таварок, существо, которое ту же самую энергию Бездны превращает в кристаллическую структуру, крепче которой я еще никогда не видел!$b$bМне непременно нужно получить образцы для изучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сущность Пандемония и сердце Таварока Мамди по кличке "Олог".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающие образцы! Они прекрасно подойдут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя нет того, что мне нужно, то не отнимай у меня времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мамди по кличке "Олог" в гробницы Маны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29575,'Жестокая вещь – конкуренция','Установив оберег и собрав свое войско, принц Шаффар сумел обчистить это место вообще безо всяких проблем.$B$BНеудивительно, что принц Харамад остался очень недоволен этим и назначил за голову Шаффара неплохую награду.','Ты хотел получить награду за голову Шаффара?','Он могуч, изобретателен, и у него хорошая охрана. Будь начеку.','Принц Шаффар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокая вещь – конкуренция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Установив оберег и собрав свое войско, принц Шаффар сумел обчистить это место вообще безо всяких проблем.$B$BНеудивительно, что принц Харамад остался очень недоволен этим и назначил за голову Шаффара неплохую награду.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хотел получить награду за голову Шаффара?',`requestitemstext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он могуч, изобретателен, и у него хорошая охрана. Будь начеку.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Принц Шаффар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29576,'Запах тревоги','Пусть я уже плохо вижу, но каждый раз при удачной погоде я ощущаю благоухание Сада Сладкого Ветерка так, словно он находится в двух шагах отсюда.$B$BСегодня же ветер принес иной запах – запах гари. Если можешь, сходи туда и проверь, все ли там в порядке. Может, это просто старческий нюх меня подводит.$B$BСад расположен к юго-западу отсюда, за статуей Нефритовой Змеи.','Поговорите с Дерзким Шао в Саду Сладкого Ветерка.','Если ты хочешь познакомиться с моими кулаками, тогда вставай в очередь. Если же нет, то я не откажусь от твоей помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах тревоги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть я уже плохо вижу, но каждый раз при удачной погоде я ощущаю благоухание Сада Сладкого Ветерка так, словно он находится в двух шагах отсюда.$B$BСегодня же ветер принес иной запах – запах гари. Если можешь, сходи туда и проверь, все ли там в порядке. Может, это просто старческий нюх меня подводит.$B$BСад расположен к юго-западу отсюда, за статуей Нефритовой Змеи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дерзким Шао в Саду Сладкого Ветерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если ты хочешь познакомиться с моими кулаками, тогда вставай в очередь. Если же нет, то я не откажусь от твоей помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29577,'Видение Асе','Смотри!$B$B<Асе указывает на огромный водопад.>$B$BОн же питает водой всю долину!$B$BПодумай, $n: эта вода позволяет пандаренам выращивать овощи размером с дом! А откуда она берется? И что в ней особенного?$B$BСтарейшины знают, как говорить с водой и прозревать будущее. Возможно, таким же способом можно узнать и то, откуда течет эта вода...$B$BПо крайней мере стоит попробовать!','Поговорите с Асё у Пруда Чистоты и понаблюдайте за ритуалом.','Удивительно! И как он увидел все это с помощью одной лишь палки?! Похоже, "безумные ритуалы цзинь-юй" и не такие уж безумные.','Поговорите с Чжан Юэ у Пруда Чистоты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видение Асе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри!$B$B<Асе указывает на огромный водопад.>$B$BОн же питает водой всю долину!$B$BПодумай, $n: эта вода позволяет пандаренам выращивать овощи размером с дом! А откуда она берется? И что в ней особенного?$B$BСтарейшины знают, как говорить с водой и прозревать будущее. Возможно, таким же способом можно узнать и то, откуда течет эта вода...$B$BПо крайней мере стоит попробовать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Асё у Пруда Чистоты и понаблюдайте за ритуалом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удивительно! И как он увидел все это с помощью одной лишь палки?! Похоже, "безумные ритуалы цзинь-юй" и не такие уж безумные.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чжан Юэ у Пруда Чистоты.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29578,'Противление злу','Чертовы могу нападают на нас из ниоткуда! Тех, кого не убили на месте, они тащат в лес.$b$bЭто наше последнее убежище, и все, что я могу сделать, это запереться внутри.$b$bЧто скажешь? Желаешь постоять за слабых?','Убейте 8 гормальских налетчиков и 8 гормальских поджигателей в Саду Сладкого Ветерка.','Неплохо, однако деревня все еще в опасности.','Вернитесь к Дерзкому Шао в Сад Сладкого Ветерка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противление злу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чертовы могу нападают на нас из ниоткуда! Тех, кого не убили на месте, они тащат в лес.$b$bЭто наше последнее убежище, и все, что я могу сделать, это запереться внутри.$b$bЧто скажешь? Желаешь постоять за слабых?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 гормальских налетчиков и 8 гормальских поджигателей в Саду Сладкого Ветерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, однако деревня все еще в опасности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерзкому Шао в Сад Сладкого Ветерка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29579,'Сбор выживших','В этой деревне живут не воины, как мы с тобой, а простые крестьяне. Но все же они делают все, чтобы защитить свои дома.$B$BОбойди деревню, найди всех, кто еще может стоять на ногах, и скажи им, чтобы собирались здесь, в доме Ханьай.','Поговорите с 5 фермерами около Сада Сладкого Ветерка и отправьте их в тайное убежище.','Они внутри. Напуганные, но, благодаря тебе, живые.','Вернитесь к Дерзкому Шао в Сад Сладкого Ветерка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор выживших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этой деревне живут не воины, как мы с тобой, а простые крестьяне. Но все же они делают все, чтобы защитить свои дома.$B$BОбойди деревню, найди всех, кто еще может стоять на ногах, и скажи им, чтобы собирались здесь, в доме Ханьай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с 5 фермерами около Сада Сладкого Ветерка и отправьте их в тайное убежище.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они внутри. Напуганные, но, благодаря тебе, живые.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерзкому Шао в Сад Сладкого Ветерка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29580,'Садовые инструменты','И пусть они не мастера боя, но со своими инструментами, будь то простая мотыга или грабли, они сроднились.$B$BЕсли к этому мы добавим еще и правильную мотивацию, то получим войско, способное отразить все атаки могу.$B$BЕсли ты принесешь из сада несколько инструментов, я раздам их любому, кто захочет сражаться.','Соберите 6 садовых инструментов в Саду Сладкого Ветерка.','Среди нас нет |3-8(Воин), но это не важно. За наших родных мы будем драться до последней капли крови.','Какие-то инструменты еще остались?','Принесите садовые инструменты Ханьай в Сад Сладкого Ветерка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Садовые инструменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И пусть они не мастера боя, но со своими инструментами, будь то простая мотыга или грабли, они сроднились.$B$BЕсли к этому мы добавим еще и правильную мотивацию, то получим войско, способное отразить все атаки могу.$B$BЕсли ты принесешь из сада несколько инструментов, я раздам их любому, кто захочет сражаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 садовых инструментов в Саду Сладкого Ветерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Среди нас нет |3-8(Воин), но это не важно. За наших родных мы будем драться до последней капли крови.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие-то инструменты еще остались?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите садовые инструменты Ханьай в Сад Сладкого Ветерка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (29581,'Золотой сон','Должно быть, Асе видел так называемый "золотой сон".$B$BТакие сны не редкость – но, как правило, мы видим их после целого дня работы в пруду. Говорят, такой сон – и бурная радость, которую он приносит – это награда за упорный труд.$B$BЕсть и другой способ его увидеть, однако теперь мы редко им пользуемся. Из корней лотоса и побегов грезолиста, который растет в святилище на верхнем уровне, можно сварить чай.$B$BПринеси грезолист Яню, и он заварит тебе чайку.','Отнесите побег грезолиста Яню, который находится в Новой Цифере.','А, грезолист! Значит, хочешь увидеть золотой сон?$B$BНадо сказать, последний раз я видел золотой сон, когда был еще медвежонком и плескался в прудах. Это было задолго до того, как я увлекся кулинарией.$B$BДа, этих листьев хватит на две чашки... так почему бы и не выпить чаю?$B$BНу, за все хорошее!','Да? Тебе что-то нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Золотой сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, Асе видел так называемый "золотой сон".$B$BТакие сны не редкость – но, как правило, мы видим их после целого дня работы в пруду. Говорят, такой сон – и бурная радость, которую он приносит – это награда за упорный труд.$B$BЕсть и другой способ его увидеть, однако теперь мы редко им пользуемся. Из корней лотоса и побегов грезолиста, который растет в святилище на верхнем уровне, можно сварить чай.$B$BПринеси грезолист Яню, и он заварит тебе чайку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите побег грезолиста Яню, который находится в Новой Цифере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, грезолист! Значит, хочешь увидеть золотой сон?$B$BНадо сказать, последний раз я видел золотой сон, когда был еще медвежонком и плескался в прудах. Это было задолго до того, как я увлекся кулинарией.$B$BДа, этих листьев хватит на две чашки... так почему бы и не выпить чаю?$B$BНу, за все хорошее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Тебе что-то нужно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29582,'Безумная ночь Грека','Грек плохо спал прошлой ночью.$b$bВ дом Грека пришла светящаяся мумия и сказала ему, что он должен отправиться в Аукиндон, в гробницы Маны. Но Грек по-прежнему пытается узнать, что написано в этом объявлении!$b$b<Лицо Грека озаряется.>$b$bГрек придумал! Ты пойдешь и найдешь светящуюся мумию и скажешь ей, что ты вместо Грека. Прекрасный план!','Этот остолоп прислал тебя?$B$B<Работник Морфалиус изучающе смотрит на вас.>$B$BПолагаю, тебе придется сделать это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумная ночь Грека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грек плохо спал прошлой ночью.$b$bВ дом Грека пришла светящаяся мумия и сказала ему, что он должен отправиться в Аукиндон, в гробницы Маны. Но Грек по-прежнему пытается узнать, что написано в этом объявлении!$b$b<Лицо Грека озаряется.>$b$bГрек придумал! Ты пойдешь и найдешь светящуюся мумию и скажешь ей, что ты вместо Грека. Прекрасный план!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот остолоп прислал тебя?$B$B<Работник Морфалиус изучающе смотрит на вас.>$B$BПолагаю, тебе придется сделать это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29583,'Сумасшедший Акерт','Я опытный инженер, гениальный изобретатель, душа любой компании и самый лучший танцор Азерота.$B$BНо разве они меня так называют? Нет.$B$BА стоит только один единственный раз подраться с эфириалом, и тебе на каждом углу начинают кричать: "Сумасшедший".$B$BЯ видел одного из них здесь вчера, клянусь! Он сказал, что если я пойду за ним в Аукиндон к гробницам Маны, то там меня будут ждать сокровища и древние знания!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумасшедший Акерт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я опытный инженер, гениальный изобретатель, душа любой компании и самый лучший танцор Азерота.$B$BНо разве они меня так называют? Нет.$B$BА стоит только один единственный раз подраться с эфириалом, и тебе на каждом углу начинают кричать: "Сумасшедший".$B$BЯ видел одного из них здесь вчера, клянусь! Он сказал, что если я пойду за ним в Аукиндон к гробницам Маны, то там меня будут ждать сокровища и древние знания!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29584,'Уничтожение могу-поджигателей','Мало того что могу на нас напали – они еще и подожгли наши древние сады.$B$BНе понимаю, чего они хотят добиться, но их нужно остановить. Уничтожь врагов в этом саду, чтобы народ мог туда вернуться.','Уничтожьте 8 могу-поджигателей в Саду Сладкого Ветерка.','Вернитесь к Баню в Сад Сладкого Ветерка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение могу-поджигателей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало того что могу на нас напали – они еще и подожгли наши древние сады.$B$BНе понимаю, чего они хотят добиться, но их нужно остановить. Уничтожь врагов в этом саду, чтобы народ мог туда вернуться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 могу-поджигателей в Саду Сладкого Ветерка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню в Сад Сладкого Ветерка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29585,'Плюнь-тушение','В течение многих поколений наши предки ухаживали за этими садами, собирали нектар и делали из него сидр. За это время мы научились в случае необходимости быстро тушить пожары.$B$B<Ханьай дает вам кувшин сидра.>$B$BЕсли сидр смешать с раздавленным имбирным листом и слюной, он быстро становится вязким и липким. Идеальное средство для "удушения" пламени.$B$BПожалуйста, постарайся усмирить огонь. Я уже смешала сидр с имбирным листом, так что тебе остается лишь набрать его в рот и выплюнуть.','Потушите сидром Сладкого Ветерка 12 костров в Саду Сладкого Ветерка.','Недавно до нас добрался выживший и сообщил, что пожар начал затухать.$B$BМы обязаны тебе всем, что у нас есть, чужестранец. Я не смогу отблагодарить тебя, как ты того заслуживаешь, но прими же хоть это.','Вернитесь к Ханьай в Сад Сладкого Ветерка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плюнь-тушение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В течение многих поколений наши предки ухаживали за этими садами, собирали нектар и делали из него сидр. За это время мы научились в случае необходимости быстро тушить пожары.$B$B<Ханьай дает вам кувшин сидра.>$B$BЕсли сидр смешать с раздавленным имбирным листом и слюной, он быстро становится вязким и липким. Идеальное средство для "удушения" пламени.$B$BПожалуйста, постарайся усмирить огонь. Я уже смешала сидр с имбирным листом, так что тебе остается лишь набрать его в рот и выплюнуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите сидром Сладкого Ветерка 12 костров в Саду Сладкого Ветерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недавно до нас добрался выживший и сообщил, что пожар начал затухать.$B$BМы обязаны тебе всем, что у нас есть, чужестранец. Я не смогу отблагодарить тебя, как ты того заслуживаешь, но прими же хоть это.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ханьай в Сад Сладкого Ветерка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29586,'Валежный лес','Сначала... еще до боевых кличей... мы услышали деревья.$b$bОни стонали, скрипели и валились на землю, когда могу прорубались через леса. Они облегчали себе обратный путь.$b$bОни тащили наших друзей по этой тропе к руинам к западу от деревни! Те развалины уже давно опустели, только дети бегают туда играть.$b$bЗачем могу туда вернулись сейчас?','Найдите лагерь налетчиков-могу, следуя по пути из упавших деревьев от северо-западного угла Сада Сладкого Ветерка.','Это не похоже на обычный налет. Они явно готовят что-то серьезное.','Поговорите с Дерзким Шао, скрывающимся к северо-востоку от лагеря Гормал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валежный лес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала... еще до боевых кличей... мы услышали деревья.$b$bОни стонали, скрипели и валились на землю, когда могу прорубались через леса. Они облегчали себе обратный путь.$b$bОни тащили наших друзей по этой тропе к руинам к западу от деревни! Те развалины уже давно опустели, только дети бегают туда играть.$b$bЗачем могу туда вернулись сейчас?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лагерь налетчиков-могу, следуя по пути из упавших деревьев от северо-западного угла Сада Сладкого Ветерка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это не похоже на обычный налет. Они явно готовят что-то серьезное.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дерзким Шао, скрывающимся к северо-востоку от лагеря Гормал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29587,'Сброшенные оковы','Видишь их, $n? Местные фермеры. Связаны и под охраной.$B$BМогу ценят силу превыше всего. Тех, кого признают годным, ждет непосильная работа и безжалостные кнуты надсмотрщиков.$b$bА остальных...$b$bЛучше не будем терять времени.','Освободите 10 связанных фермеров Сладкого Ветерка в лагере Гормал.','В древние времена пандарены были покорены могу. Мы не допустим, чтобы это повторилось.','Вернитесь к Дерзкому Шао в лагерь Гормал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сброшенные оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь их, $n? Местные фермеры. Связаны и под охраной.$B$BМогу ценят силу превыше всего. Тех, кого признают годным, ждет непосильная работа и безжалостные кнуты надсмотрщиков.$b$bА остальных...$b$bЛучше не будем терять времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 10 связанных фермеров Сладкого Ветерка в лагере Гормал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В древние времена пандарены были покорены могу. Мы не допустим, чтобы это повторилось.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерзкому Шао в лагерь Гормал.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29590,'Страж Мертвых','Ужасное создание, которое мы зовем Ширрак, сеет ужас как в материальном мире, так и в мире духов.$B$BТолько в твоем мире ему можно причинить вред. Пожалуйста, помоги нам избавиться от этого кошмара.','Убейте Ширрака Стража Мертвых, затем возвращайтесь к духу дренея.','Быть может, теперь мы, наконец, сумеем обрести покой.','Вернитесь к духу дренея в Аукенайские гробницы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ужасное создание, которое мы зовем Ширрак, сеет ужас как в материальном мире, так и в мире духов.$B$BТолько в твоем мире ему можно причинить вред. Пожалуйста, помоги нам избавиться от этого кошмара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ширрака Стража Мертвых, затем возвращайтесь к духу дренея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быть может, теперь мы, наконец, сумеем обрести покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу дренея в Аукенайские гробницы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29591,'Разъяренные духи','Убейте 5 разгневанных скелетов, 5 разъяренных скелетов и 3 аукенайских некроманта, после чего возвращайтесь к истязаемому жрецу душ в Аукенайские гробницы.','Мертвым место в мире духов – точно так же, как тебе должно пребывать в этом мире.','Вернитесь к страдающему жрецу душ в Аукенайские гробницы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные духи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 разгневанных скелетов, 5 разъяренных скелетов и 3 аукенайских некроманта, после чего возвращайтесь к истязаемому жрецу душ в Аукенайские гробницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мертвым место в мире духов – точно так же, как тебе должно пребывать в этом мире.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страдающему жрецу душ в Аукенайские гробницы.',`completedtext_loc8`);
