INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29593,'Удар по уязвимой точке','Орки Скверны устроили тут большой склад припасов.$B$BЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, |3-6($c)?','Украдите 3 связки припасов Адского Пламени, а затем вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.','Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.','Сколько связок тебе удалось украсть?','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по уязвимой точке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Скверны устроили тут большой склад припасов.$B$BЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 3 связки припасов Адского Пламени, а затем вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько связок тебе удалось украсть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Бастионы Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29594,'Удар по уязвимой точке','Орки Скверны устроили тут большой склад припасов.$B$BЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, |3-6($c)?','Украдите 3 связки припасов Адского Пламени, а затем вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.','Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.','Сколько связок тебе удалось украсть?','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по уязвимой точке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Скверны устроили тут большой склад припасов.$B$BЕсли их украсть, то это нанесет серьезный удар по их планам и значительно поднимет наш боевой дух. Возьмешься за это поручение, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 3 связки припасов Адского Пламени, а затем вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа! Это гораздо эффективнее, чем перебить парочку орков. Они еще долго будут чувствовать последствия кражи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько связок тебе удалось украсть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Бастионы Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29595,'Все будет в порядке','Чувствую, тебе хватило приключений еще до того, как ты $gвошел:вошла; в Аукенайские гробницы, $n.$B$BЯ могу назвать себя счастливым духом, – я никогда не попадался ни Левиксусу, ни экзарху Маладаару, и на мне не ставили эти ужасные некромантические эксперименты. Левиксиуса тебе удалось уничтожить, но Маладаар жив и продолжает терзать пленных духов.$B$BЯ прошу только об одном. Проберись в Аукенайские гробницы и поговори там с духом дренея. Ты $gдолжен:должна; уничтожить экзарха Маладаара.','Проникните в Аукенайские гробницы и поговорите с духом дренея по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона.','Вернитесь к Великому Отцу Алдримусу в Аукиндон, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все будет в порядке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствую, тебе хватило приключений еще до того, как ты $gвошел:вошла; в Аукенайские гробницы, $n.$B$BЯ могу назвать себя счастливым духом, – я никогда не попадался ни Левиксусу, ни экзарху Маладаару, и на мне не ставили эти ужасные некромантические эксперименты. Левиксиуса тебе удалось уничтожить, но Маладаар жив и продолжает терзать пленных духов.$B$BЯ прошу только об одном. Проберись в Аукенайские гробницы и поговори там с духом дренея. Ты $gдолжен:должна; уничтожить экзарха Маладаара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в Аукенайские гробницы и поговорите с духом дренея по просьбе Великого Отца Алдримуса, который находится снаружи Аукенайских гробниц Аукиндона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великому Отцу Алдримусу в Аукиндон, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29596,'Конец экзарху','Экзарх Маладаар занимается своими нечистыми делами в самой дальней части гробниц. Он представляет собой угрозу для обоих наших миров. Его нужно остановить.$b$bТы $gдолжен:должна; убить его во имя всех нас, живых и мертвых.','Убейте экзарха Маладаара и вернитесь к духу дренея в Аукенайские гробницы.','Ты оказал нашему миру огромную услугу. Мы всегда будем помнить об этом.','Вернитесь к духу дренея в Аукенайские гробницы.','Пришло время заставить его заплатить.','Экзарх Маладаар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец экзарху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Экзарх Маладаар занимается своими нечистыми делами в самой дальней части гробниц. Он представляет собой угрозу для обоих наших миров. Его нужно остановить.$b$bТы $gдолжен:должна; убить его во имя всех нас, живых и мертвых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте экзарха Маладаара и вернитесь к духу дренея в Аукенайские гробницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты оказал нашему миру огромную услугу. Мы всегда будем помнить об этом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу дренея в Аукенайские гробницы.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришло время заставить его заплатить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Экзарх Маладаар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29597,'Конец экзарху','Экзарх Маладаар занимается своими нечистыми делами в самой дальней части гробниц. Он представляет собой угрозу для обоих наших миров. Его нужно остановить.$b$bТы $gдолжен:должна; убить его во имя всех нас, живых и мертвых.','Убейте экзарха Маладаара и вернитесь к духу дренея в Аукенайские гробницы.','Вернитесь к духу дренея в Аукенайские гробницы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец экзарху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Экзарх Маладаар занимается своими нечистыми делами в самой дальней части гробниц. Он представляет собой угрозу для обоих наших миров. Его нужно остановить.$b$bТы $gдолжен:должна; убить его во имя всех нас, живых и мертвых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте экзарха Маладаара и вернитесь к духу дренея в Аукенайские гробницы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу дренея в Аукенайские гробницы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (29598,'План Тареты','Именно Тарета придумала первоначальный план, как помочь Траллу бежать из Дарнхольда.$B$BНо драконы Бесконечности захватили ее в плен. Без нашей помощи Траллу вряд ли удастся сбежать. Я дам тебе зажигательные бомбы – тебе нужно будет с их помощью поджечь бараки.','Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.$B$BПосле того как подожжете бараки, разыщите Тралла в подземной темнице.','Вы с Таретой друзья? Это, значит, ее новый план? Ну хорошо...','Вернитесь к Траллу.','Ему нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Тареты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Именно Тарета придумала первоначальный план, как помочь Траллу бежать из Дарнхольда.$B$BНо драконы Бесконечности захватили ее в плен. Без нашей помощи Траллу вряд ли удастся сбежать. Я дам тебе зажигательные бомбы – тебе нужно будет с их помощью поджечь бараки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь в крепость Дарнхольд и заложите пять зажигательных бомб возле бочек внутри каждого из бараков на выселках. Используйте упаковку зажигательных бомб, полученных от Эрозиона.$B$BПосле того как подожжете бараки, разыщите Тралла в подземной темнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы с Таретой друзья? Это, значит, ее новый план? Ну хорошо...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ему нужна твоя помощь!',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29599,'Побег из Дарнхольда','Я знаю, что нужно моему народу, $gчужак:незнакомка;$B$BВ один прекрасный день он сбросит своих притеснителей и встанет с колен. Мы порвем свои цепи и выкуем новую Орду, закалив ее в пламени мятежа.$B$BКак только будешь $gготов:готова; идти, дай мне знать.','Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.$B$BПосле этого возвращайтесь к Эрозиону в Старый Хилсбрад.','Вернитесь к Эрозиону в Старые предгорья Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из Дарнхольда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что нужно моему народу, $gчужак:незнакомка;$B$BВ один прекрасный день он сбросит своих притеснителей и встанет с колен. Мы порвем свои цепи и выкуем новую Орду, закалив ее в пламени мятежа.$B$BКак только будешь $gготов:готова; идти, дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Когда вы будете готовы идти, сообщите об этом Траллу. Помогите ему бежать из крепости Дарнхольд, освободить Тарету и исполнить свое предназначение.$B$BПосле этого возвращайтесь к Эрозиону в Старый Хилсбрад.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрозиону в Старые предгорья Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29600,'Решительные меры','Эти водоемы – особенные: ни одна другая река или озеро не поит водой столько живности во всей Пандарии.$B$BК сожалению, они привлекают к себе не только безобидных животных. Недавно выяснилось, что в верхнем водоеме стали гнездиться драконьи черепахи. Они там просто беспредельничают, честное слово – топчут лотосы и пугают моих работников.$B$BОтдельные особи, конечно, не представляют никакой опасности, но с целой стаей таких лучше не встречаться, поверь мне. Пожалуйста, не откажи в просьбе – уж очень нужна твоя помощь в очистке водоемов.','Уничтожьте 16 шипастых крепкохватов в Пруду Чистоты.','Спасибо, Эрезул.$B$BПожалуйста, прими это в знак моей благодарности.','Вернитесь к Чжан Юэ на Пруд Чистоты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решительные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти водоемы – особенные: ни одна другая река или озеро не поит водой столько живности во всей Пандарии.$B$BК сожалению, они привлекают к себе не только безобидных животных. Недавно выяснилось, что в верхнем водоеме стали гнездиться драконьи черепахи. Они там просто беспредельничают, честное слово – топчут лотосы и пугают моих работников.$B$BОтдельные особи, конечно, не представляют никакой опасности, но с целой стаей таких лучше не встречаться, поверь мне. Пожалуйста, не откажи в просьбе – уж очень нужна твоя помощь в очистке водоемов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 16 шипастых крепкохватов в Пруду Чистоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Эрезул.$B$BПожалуйста, прими это в знак моей благодарности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чжан Юэ на Пруд Чистоты.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29601,'Справочник ярмарки Новолуния','У тебя ведь есть справочник ярмарки Новолуния, $gприятель:подруга;? Это самая полезная книга и ее всегда стоит иметь под рукой.$b$bГде бы в Азероте ты ни $gоказался:оказалась;, она поможет тебе найти и распознать любые ценные артефакты. Описания в книге так подробны, что тебе не составит труда понять, $gнашел:нашла; ты пятисотую латунную пуговицу или же какое-то по-настоящему редкое сокровище, за которым гоняются коллекционеры ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справочник ярмарки Новолуния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя ведь есть справочник ярмарки Новолуния, $gприятель:подруга;? Это самая полезная книга и ее всегда стоит иметь под рукой.$b$bГде бы в Азероте ты ни $gоказался:оказалась;, она поможет тебе найти и распознать любые ценные артефакты. Описания в книге так подробны, что тебе не составит труда понять, $gнашел:нашла; ты пятисотую латунную пуговицу или же какое-то по-настоящему редкое сокровище, за которым гоняются коллекционеры ярмарки Новолуния.',`details_loc8`);
