INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29604,'Выслеживание: проигран ролик о прибытии в Восточный храм') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: проигран ролик о прибытии в Восточный храм',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29605,'Брат на брата','Когда Аукиндон взорвался, племя Сетекк покинуло Скеттис.$B$BМой брат Сит был одним из лидеров племени Сетекк, и именно ему принадлежала идея, что мы должны выйти к руинам храма и встретить нашего бога.$B$BЧерез некоторое время Сит изгнал меня из племени и запретил забрать с собой нашу сестру Лакку. Ты поможешь мне спасти ее?','Освободите из плена Лакку. После этого вернитесь к Исфару, который находится в Сетеккских залах.','Теперь, когда Лакка свободна, оборвались последние нити, связывающие меня с племенем Сетекк.$B$BЯ никогда не прощу себе смерти Сита, но это нужно было сделать. По возвращении в Скеттис я сам исполню по нему похоронные ритуалы.','Вернитесь к Исфару в Сетеккские залы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брат на брата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Аукиндон взорвался, племя Сетекк покинуло Скеттис.$B$BМой брат Сит был одним из лидеров племени Сетекк, и именно ему принадлежала идея, что мы должны выйти к руинам храма и встретить нашего бога.$B$BЧерез некоторое время Сит изгнал меня из племени и запретил забрать с собой нашу сестру Лакку. Ты поможешь мне спасти ее?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите из плена Лакку. После этого вернитесь к Исфару, который находится в Сетеккских залах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда Лакка свободна, оборвались последние нити, связывающие меня с племенем Сетекк.$B$BЯ никогда не прощу себе смерти Сита, но это нужно было сделать. По возвращении в Скеттис я сам исполню по нему похоронные ритуалы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исфару в Сетеккские залы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29606,'Наследство Терокка','Мой народ свято чтит древнего героя по имени Терокк.$B$BВ один прекрасный день он бесследно исчез, оставив после себя лишь маску, копье и некоторые записи.$B$BАраккоа почитают эти реликвии, но племя Сетекк, уходя из Скеттиса, похитило их и унесло с собой.','Принесите маску Терокка, перо Терокка и "Сказание о Терокке" Исфару, который находится в Сетеккских залах.','Я принял участие в злодеяниях племени Сетекк, и за это нет мне прощения. Может быть, возвращение реликвий Терокка хоть немного оправдает меня в глазах моего народа.','Реликвии, принадлежащие Терокку, слишком давно покинули Скеттис. Удалось ли тебе вырвать их из лап племени Сетекк?','Вернитесь к Исфару в Сетеккские залы.','У него перо Терокка.','Король воронов Айкисс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследство Терокка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ свято чтит древнего героя по имени Терокк.$B$BВ один прекрасный день он бесследно исчез, оставив после себя лишь маску, копье и некоторые записи.$B$BАраккоа почитают эти реликвии, но племя Сетекк, уходя из Скеттиса, похитило их и унесло с собой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите маску Терокка, перо Терокка и "Сказание о Терокке" Исфару, который находится в Сетеккских залах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я принял участие в злодеяниях племени Сетекк, и за это нет мне прощения. Может быть, возвращение реликвий Терокка хоть немного оправдает меня в глазах моего народа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Реликвии, принадлежащие Терокку, слишком давно покинули Скеттис. Удалось ли тебе вырвать их из лап племени Сетекк?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исфару в Сетеккские залы.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него перо Терокка.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король воронов Айкисс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29607,'Глаза желания','Я знаю одного покупателя, который очень заинтересован в приобретении глаз кобальтовых змеев, что обитают здесь.$b$bЕсли бы ты $gпринес:принесла; мне несколько этих редких самоцветов, я бы поделился с тобой прибылью.$b$bИдет?','Делец Вийяд из Сетеккских залов хочет, чтобы вы принесли ему 3 кобальтовых глаза.','То что надо. Молодец!$B$BВот твоя доля, как и обещал.','Вернитесь к дельцу Вийяду в Сетеккские залы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза желания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю одного покупателя, который очень заинтересован в приобретении глаз кобальтовых змеев, что обитают здесь.$b$bЕсли бы ты $gпринес:принесла; мне несколько этих редких самоцветов, я бы поделился с тобой прибылью.$b$bИдет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Делец Вийяд из Сетеккских залов хочет, чтобы вы принесли ему 3 кобальтовых глаза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То что надо. Молодец!$B$BВот твоя доля, как и обещал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дельцу Вийяду в Сетеккские залы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29608,'Союзники в Даларане','Добро пожаловать в Нордскол, $n. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты $Gвстретился:встретилась; там с нашими союзниками.$B$BЛети в Даларан на грифоне, и, как прибудешь туда, сразу ступай в нашу таверну, "Благодарность за отвагу". Там разыщи Изирами Попутный Ветер и поговори с ней.$B$BОна поможет тебе привязать твой камень возвращения к городу, чтобы ты $Gмог:могла; быстро возвращаться в Штормград через портал Серебряного Анклава.','Прилетите на грифоне в Даларан и поговорите с Изирами Попутный Ветер в таверне "Благодарность за отвагу".','Добро пожаловать в Даларан! Эта таверна – часть Серебряного Анклава, штаб-квартиры представительства Альянса в нашем городе.$B$BНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к находящемуся поблизости порталу Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзники в Даларане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Нордскол, $n. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты $Gвстретился:встретилась; там с нашими союзниками.$B$BЛети в Даларан на грифоне, и, как прибудешь туда, сразу ступай в нашу таверну, "Благодарность за отвагу". Там разыщи Изирами Попутный Ветер и поговори с ней.$B$BОна поможет тебе привязать твой камень возвращения к городу, чтобы ты $Gмог:могла; быстро возвращаться в Штормград через портал Серебряного Анклава.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прилетите на грифоне в Даларан и поговорите с Изирами Попутный Ветер в таверне "Благодарность за отвагу".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Даларан! Эта таверна – часть Серебряного Анклава, штаб-квартиры представительства Альянса в нашем городе.$B$BНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к находящемуся поблизости порталу Штормграда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29609,'Друзья в Даларане','Добро пожаловать в Нордскол. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты $Gвстретился:встретилась; там с нашими друзьями.$B$BПоговори со мной, чтобы лететь в Даларан. Как прибудешь туда, отправляйся в кабак "Грязное животное". Там разыщи Уду Зверюгу и поговори с ней.$B$BОна поможет тебе привязать твой камень возвращения к городу, чтобы ты $Gмог:могла; быстро возвращаться в Оргриммар через портал в Прибежище Похитителя Солнца.','Летите в Даларан и поговорите с Удой Зверюгой в трактире "Грязное животное".','Я ждала тебя! Эта таверна – часть Прибежища Похитителя Солнца, анклава Орды в Даларане.$B$BНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к порталу Оргриммара, который находится у фонтана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья в Даларане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Нордскол. Меня попросили обеспечить тебя транспортом до Даларана, чтобы ты $Gвстретился:встретилась; там с нашими друзьями.$B$BПоговори со мной, чтобы лететь в Даларан. Как прибудешь туда, отправляйся в кабак "Грязное животное". Там разыщи Уду Зверюгу и поговори с ней.$B$BОна поможет тебе привязать твой камень возвращения к городу, чтобы ты $Gмог:могла; быстро возвращаться в Оргриммар через портал в Прибежище Похитителя Солнца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летите в Даларан и поговорите с Удой Зверюгой в трактире "Грязное животное".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ждала тебя! Эта таверна – часть Прибежища Похитителя Солнца, анклава Орды в Даларане.$B$BНе забудь привязать здесь свой камень возвращения, чтобы быстро возвращаться в город и получить доступ к порталу Оргриммара, который находится у фонтана.',`offerrewardtext_loc8`);
