INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertargetname_loc8`) VALUES (29611,'Искусство войны','Поговорите с генералом Назгримом в крепости Громмаш.','А, хорошо. Ты здесь. И как раз вовремя…','Генерал Назгрим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство войны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Назгримом в крепости Громмаш.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо. Ты здесь. И как раз вовремя…',`offerrewardtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Генерал Назгрим',`questgivertargetname_loc8`);
