INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29613,'Бесславный конец','Полководец Калитреш руководит всей операцией в Паровом подземелье.$B$BЯ хочу, чтобы ты $gубил:убила; его, $n. Наги не оставили нам иного выбора, кроме насилия.$B$BПусть твоя рука не дрогнет.','Убейте полководца Калитреша и возвращайтесь к дозорной Джанг в Паровое подземелье.','Мне жаль, что до этого дошло, но наги не дали нам ни одного шанса решить дело миром.','Вернитесь к дозорной Джанг в Паровое подземелья.','Его нужно остановить!','Полководец Калитреш') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесславный конец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полководец Калитреш руководит всей операцией в Паровом подземелье.$B$BЯ хочу, чтобы ты $gубил:убила; его, $n. Наги не оставили нам иного выбора, кроме насилия.$B$BПусть твоя рука не дрогнет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Калитреша и возвращайтесь к дозорной Джанг в Паровое подземелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне жаль, что до этого дошло, но наги не дали нам ни одного шанса решить дело миром.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Джанг в Паровое подземелья.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его нужно остановить!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Полководец Калитреш',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29614,'Сдерживание заразы','Наги снюхались с лепрогномами – вместе они пытаются распространить по всей Зангартопи ужасную болезнь. Зараза уже охватила почти все Паровое подземелье.$B$BУничтожь все, что заражено, и принеси мне центральный механизм Анжинера Паропуска. Поспеши!','Убейте 3 властителя болот, 6 лепрогномов из резервуара Кривого Клыка, а также достаньте облученный механизм Анжинера Паропуска, после чего возвращайтесь к натуралисту Кусу в Паровое подземелье.','Я рад, что нам удалось остановить эту заразу, пока она не успела расползтись по всей Зангартопи. Спасибо.','Постарайся сделать все как можно тщательнее. От этого зависит судьба всей Зангартопи.','Вернитесь к натуралисту Кусу в Паровое подземелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдерживание заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги снюхались с лепрогномами – вместе они пытаются распространить по всей Зангартопи ужасную болезнь. Зараза уже охватила почти все Паровое подземелье.$B$BУничтожь все, что заражено, и принеси мне центральный механизм Анжинера Паропуска. Поспеши!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 властителя болот, 6 лепрогномов из резервуара Кривого Клыка, а также достаньте облученный механизм Анжинера Паропуска, после чего возвращайтесь к натуралисту Кусу в Паровое подземелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что нам удалось остановить эту заразу, пока она не успела расползтись по всей Зангартопи. Спасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Постарайся сделать все как можно тщательнее. От этого зависит судьба всей Зангартопи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к натуралисту Кусу в Паровое подземелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29615,'Призыватель ветра Коготь и водокрад','Может быть, теперь нам удастся обеспечить исстрадавшуюся землю столь необходимой ей водой.','Вернитесь к призывателю ветров Когтю в Паровое подземелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыватель ветра Коготь и водокрад',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Может быть, теперь нам удастся обеспечить исстрадавшуюся землю столь необходимой ей водой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю ветров Когтю в Паровое подземелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29616,'Штурм Парового подземелья','Пока что нам так и не удалось остановить наг в Паровом подземелье, где находится основная часть их насосной системы.$B$BНо отправленная туда экспедиция уже приступила к работе, так что будем надеяться, что вскоре ситуация переменится. Может, отправишься в Паровое подземелье, отыщешь там дозорную Джанг и предложишь ей и ее людям свою помощь?','Поговорите с дозорной Джанг в Паровом подземелье.','Хвала звездам, ты здесь! Нам нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм Парового подземелья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока что нам так и не удалось остановить наг в Паровом подземелье, где находится основная часть их насосной системы.$B$BНо отправленная туда экспедиция уже приступила к работе, так что будем надеяться, что вскоре ситуация переменится. Может, отправишься в Паровое подземелье, отыщешь там дозорную Джанг и предложишь ей и ее людям свою помощь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дозорной Джанг в Паровом подземелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала звездам, ты здесь! Нам нужна твоя помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29617,'Монастырь Тянь','Со всех концов Пандарии жители стекаются сюда, чтобы пройти тренировку в монастыре Тянь – он находится чуть к северу отсюда. Возможно, это потому, что монахи принимают всех – цзинь-юй, хозенов... Даже |3-6($r) вроде тебя найдет там приют!$B$BМоя подруга детства Линь стала послушницей несколько недель назад. Если хочешь узнать, чему учат в монастыре, поговори с ней!','Поговорите с Линь Мягкой Лапой, которая находится в монастыре Тянь в Нефритовом лесу.','Ты прибыл весьма своевременно. Верховный старейшина Дождевая Туча согласился взять новую группу учеников. Это мой шанс – наконец-то я обучусь боевым искусствам!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Монастырь Тянь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со всех концов Пандарии жители стекаются сюда, чтобы пройти тренировку в монастыре Тянь – он находится чуть к северу отсюда. Возможно, это потому, что монахи принимают всех – цзинь-юй, хозенов... Даже |3-6($r) вроде тебя найдет там приют!$B$BМоя подруга детства Линь стала послушницей несколько недель назад. Если хочешь узнать, чему учат в монастыре, поговори с ней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Линь Мягкой Лапой, которая находится в монастыре Тянь в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прибыл весьма своевременно. Верховный старейшина Дождевая Туча согласился взять новую группу учеников. Это мой шанс – наконец-то я обучусь боевым искусствам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29618,'Верховный старейшина','Как странно, в нашем монастыре –|3-6($c). Ты хочешь учиться?$B$BПохоже, сил тебе не занимать... так что можешь не беспокоиться – тебя непременно примут. Поговори с Верховным старейшиной – он на балконе.','Поговорите с верховным старейшиной Дождевой Тучей в монастыре Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный старейшина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как странно, в нашем монастыре –|3-6($c). Ты хочешь учиться?$B$BПохоже, сил тебе не занимать... так что можешь не беспокоиться – тебя непременно примут. Поговори с Верховным старейшиной – он на балконе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным старейшиной Дождевой Тучей в монастыре Тянь в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29619,'Учтивый гость','Какая новость! Верховный старейшина хочет, чтобы ты $gучился:училась; вместе с нами!$B$BДля нас, учеников, устроят пир... а тебе следует прийти на него с подарком – ну, в знак вежливости.$B$BК югу от храма есть роща; апельсины там удивительно сочные и сладкие! Собери их для праздника!','Соберите 8 спелых апельсинов в апельсиновых рощах к югу от монастыря Тянь.','Отлично, Эрезул! Замечательный подарок!$B$BА я, конечно, принесу пиво.','Ты готов к пиршеству? Скорее бы оно началось!','Вернитесь к Линь Мягкой Лапе в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учтивый гость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая новость! Верховный старейшина хочет, чтобы ты $gучился:училась; вместе с нами!$B$BДля нас, учеников, устроят пир... а тебе следует прийти на него с подарком – ну, в знак вежливости.$B$BК югу от храма есть роща; апельсины там удивительно сочные и сладкие! Собери их для праздника!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 спелых апельсинов в апельсиновых рощах к югу от монастыря Тянь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Эрезул! Замечательный подарок!$B$BА я, конечно, принесу пиво.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты готов к пиршеству? Скорее бы оно началось!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линь Мягкой Лапе в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29620,'Пир на весь мир','Поговорите с верховным старейшиной Дождевой Тучей, который находится на площадке для пиршества в монастыре Тянь.','С формальностями покончено, и скоро ты сможешь приступить к занятиям.$B$BНу, то есть... занятия начнутся после того, как мы махнем еще по кружечке. Или по две. Не возражаешь, Эрезул?','Вернитесь к Верховному старейшине Дождевой Туче в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пир на весь мир',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным старейшиной Дождевой Тучей, который находится на площадке для пиршества в монастыре Тянь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С формальностями покончено, и скоро ты сможешь приступить к занятиям.$B$BНу, то есть... занятия начнутся после того, как мы махнем еще по кружечке. Или по две. Не возражаешь, Эрезул?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному старейшине Дождевой Туче в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29621,'UNUSED','I have but one task for you, and it is a simple one. I would like you to speak with the spirits of the high elders that came before Cloudfall.$b$bTheir spirits have left their bodies, but they have not left this place. Go, speak with them, absorb their wisdom, and curry their favor.$b$bI anxiously await your return.','Speak with the four High Elder spirits in Tian Monastery.','Return to Spirit-Sage Gaoquan at the Tian Monastery in the Jade Forest.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I have but one task for you, and it is a simple one. I would like you to speak with the spirits of the high elders that came before Cloudfall.$b$bTheir spirits have left their bodies, but they have not left this place. Go, speak with them, absorb their wisdom, and curry their favor.$b$bI anxiously await your return.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak with the four High Elder spirits in Tian Monastery.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Spirit-Sage Gaoquan at the Tian Monastery in the Jade Forest.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29622,'Обучение начнется немедленно','<Сяо не поднимает глаз от миски.>$B$BА, $gновенький:новенькая;! Хорошо, что тебе удалось выжить на этом пиру! Первое испытание завершено!$B$B<Сяо громко чавкает.>$B$BСоветую поговорить с инструктором Сянем насчет ваших ежедневных тренировок.$B$B<Сяо продолжает есть. Похоже, разговор окончен.>','Явитесь к инструктору Сяню, который находится в монастыре Тянь в Нефритовом лесу.','Ты пьешь слишком много пива... а теперь еще и на занятия опаздываешь? Похоже, ты отлично приспособился к образу жизни пандаренов.$B$BЧто ж, начнем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение начнется немедленно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Сяо не поднимает глаз от миски.>$B$BА, $gновенький:новенькая;! Хорошо, что тебе удалось выжить на этом пиру! Первое испытание завершено!$B$B<Сяо громко чавкает.>$B$BСоветую поговорить с инструктором Сянем насчет ваших ежедневных тренировок.$B$B<Сяо продолжает есть. Похоже, разговор окончен.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к инструктору Сяню, который находится в монастыре Тянь в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты пьешь слишком много пива... а теперь еще и на занятия опаздываешь? Похоже, ты отлично приспособился к образу жизни пандаренов.$B$BЧто ж, начнем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29623,'Совершенство','Совершенство достигается повторением. Каждый ученик на тренировочной арене когда-нибудь достигнет совершенства... если, конечно, ему хватит упорства. Это факт.$B$B$n, я предлагаю тебе присоединиться к ним. В качестве почетного гостя ты не $gобязан:обязана; выполнять дневную норму в 10 000 ударов. Просто пару минут повторяй действия наставника.','Следуя примеру учителя, нанесите 12 тренировочных ударов на монастырской арене.','Ты уже занимался боевыми искусствами? Сейчас ты не в лучшей форме, но навыки скрыть невозможно.','Вернитесь к инструктору Сяню в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Совершенство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совершенство достигается повторением. Каждый ученик на тренировочной арене когда-нибудь достигнет совершенства... если, конечно, ему хватит упорства. Это факт.$B$B$n, я предлагаю тебе присоединиться к ним. В качестве почетного гостя ты не $gобязан:обязана; выполнять дневную норму в 10 000 ударов. Просто пару минут повторяй действия наставника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуя примеру учителя, нанесите 12 тренировочных ударов на монастырской арене.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уже занимался боевыми искусствами? Сейчас ты не в лучшей форме, но навыки скрыть невозможно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Сяню в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29624,'Внимание','Cледующее испытание потребует от тебя сосредоточенности и внимательности. Потренируйся внизу, в яме с мешками.$B$BМешки висят попарно. Если скажу "слева", атакуй мешок, который висит слева. Если скажу "справа", атакуй мешок, который висит справа.$B$BЕсли не будешь следовать этим простым командам, сильно усложнишь себе жизнь.$B$BНу, $n, давай, бей мешки, пока они не порвутся.','Уничтожьте 2 тренировочных мешка, следуя указаниям инструктора Сяня.','Пусть ты приходящий ученик, но это не значит, что тебе можно отлынивать от занятий.$B$BУверяю тебя, способность быстро переключаться между целями не раз пригодится в бою.','Вернитесь к инструктору Сяню в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внимание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Cледующее испытание потребует от тебя сосредоточенности и внимательности. Потренируйся внизу, в яме с мешками.$B$BМешки висят попарно. Если скажу "слева", атакуй мешок, который висит слева. Если скажу "справа", атакуй мешок, который висит справа.$B$BЕсли не будешь следовать этим простым командам, сильно усложнишь себе жизнь.$B$BНу, $n, давай, бей мешки, пока они не порвутся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 2 тренировочных мешка, следуя указаниям инструктора Сяня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть ты приходящий ученик, но это не значит, что тебе можно отлынивать от занятий.$B$BУверяю тебя, способность быстро переключаться между целями не раз пригодится в бою.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Сяню в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (29625,'UNUSED','temp') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','temp',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29626,'<У заговаривает с вами весьма сурово.>$B$B Ты – Эрезул, да? Любимчик Верховного старейшины? Да, я видел тебя на пиршестве.$B$BОт меня поблажек не жди. Работы у тебя будет столько же, сколько и у самого зеленого пандарена. $B$BА может, и больше.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<У заговаривает с вами весьма сурово.>$B$B Ты – Эрезул, да? Любимчик Верховного старейшины? Да, я видел тебя на пиршестве.$B$BОт меня поблажек не жди. Работы у тебя будет столько же, сколько и у самого зеленого пандарена. $B$BА может, и больше.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29627,'Правильное оружие','Но сначала о главном.$B$BУ правильного ученика должно быть правильное оружие. А добросовестный ученик делает его себе сам... или хотя бы собирает материалы для его изготовления.$B$BВ окрестностях растет ротанг – из него получится весьма достойное оружие. Кроме того, для его обработки тебе понадобится черный ореховый экстракт. Ну и раз уж ты все равно будешь там, добудь немного эля для... $B$B<У умолкает.>$B$B...Ну, ты $gсам:сама; знаешь, для чего нужен эль.','Найдите 6 побегов ротанга в окрестностях рынка монастыря Тянь.$B$BКупите у Юн Белый Цветок бутылочку черного орехового экстракта.$B$BКупите 3 бутыли трижды подгорченного эля у хмелевара Лэй Кан-лэя.','<Хранитель земель У благодарно забирает у вас все принесенное.>$B$BЯ получу оружие, приготовленное для тебя, к концу твоего обучения. А теперь займемся настоящим делом.','<У выжидающе смотрит на вас.>','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правильное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Но сначала о главном.$B$BУ правильного ученика должно быть правильное оружие. А добросовестный ученик делает его себе сам... или хотя бы собирает материалы для его изготовления.$B$BВ окрестностях растет ротанг – из него получится весьма достойное оружие. Кроме того, для его обработки тебе понадобится черный ореховый экстракт. Ну и раз уж ты все равно будешь там, добудь немного эля для... $B$B<У умолкает.>$B$B...Ну, ты $gсам:сама; знаешь, для чего нужен эль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 побегов ротанга в окрестностях рынка монастыря Тянь.$B$BКупите у Юн Белый Цветок бутылочку черного орехового экстракта.$B$BКупите 3 бутыли трижды подгорченного эля у хмелевара Лэй Кан-лэя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хранитель земель У благодарно забирает у вас все принесенное.>$B$BЯ получу оружие, приготовленное для тебя, к концу твоего обучения. А теперь займемся настоящим делом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<У выжидающе смотрит на вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29628,'Сильная поддержка','У некоторых наших учеников аппетит... выше среднего, и поэтому нам не всегда удается запасти на всех достаточно пропитания. В таком случае мы просим помочь нам.$B$BК северо-западу отсюда стоит небольшой домик, в нем живет добрая старушка, которая согласилась сварить для нас похлебку. Тебе нужно просто забрать приготовленное блюдо.','Я разделю похлебку поровну между учениками.$B$BНу, и себе оставлю немного, разумеется.','Поговорите с хранителем земель У в монастыре Тянь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сильная поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У некоторых наших учеников аппетит... выше среднего, и поэтому нам не всегда удается запасти на всех достаточно пропитания. В таком случае мы просим помочь нам.$B$BК северо-западу отсюда стоит небольшой домик, в нем живет добрая старушка, которая согласилась сварить для нас похлебку. Тебе нужно просто забрать приготовленное блюдо.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я разделю похлебку поровну между учениками.$B$BНу, и себе оставлю немного, разумеется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем земель У в монастыре Тянь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29629,'Твердая рука','Черный ореховый экстракт, который ты $gкупил:купила; у госпожи Белый Цветок – всего лишь один из многих, что мы запасаем для разных целей.$B$BЭкстракт краснолиста извлекается из цветов, которые растут на западе, в Буковом лесу. Из одного цветка можно извлечь несколько доз экстракта, но только в том случае, если ты совершенно спокоен и у тебя не дрожат руки.','Соберите 80 сосудов экстракта краснолиста из гроздьев краснолиста Букового леса.','Не забудь вымыть руки. Пятна от сока краснолиста не выводятся.','Говорят, в древности травники набирали 20 сосудов экстракта из каждого бутона.','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твердая рука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черный ореховый экстракт, который ты $gкупил:купила; у госпожи Белый Цветок – всего лишь один из многих, что мы запасаем для разных целей.$B$BЭкстракт краснолиста извлекается из цветов, которые растут на западе, в Буковом лесу. Из одного цветка можно извлечь несколько доз экстракта, но только в том случае, если ты совершенно спокоен и у тебя не дрожат руки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 80 сосудов экстракта краснолиста из гроздьев краснолиста Букового леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не забудь вымыть руки. Пятна от сока краснолиста не выводятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Говорят, в древности травники набирали 20 сосудов экстракта из каждого бутона.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29630,'И тяжелый кулак','Плуты Зеленой Скалы, которые обитают на западе, в Буковом лесу, не представляют для нас серьезной опасности, это правда. Однако в последнее время их численность сильно возросла, а проделки стали досаждать все больше.$B$BМы – хранители леса, и наш долг – поддерживать равновесие. Твоя задача – сократить популяцию этих духов.','Уничтожьте 10 плутов Зеленой Скалы в Буковом лесу.','Спасибо, Эрезул. Через несколько дней численность плутов опять возрастет, но пока равновесие в природе восстановлено.','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И тяжелый кулак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плуты Зеленой Скалы, которые обитают на западе, в Буковом лесу, не представляют для нас серьезной опасности, это правда. Однако в последнее время их численность сильно возросла, а проделки стали досаждать все больше.$B$BМы – хранители леса, и наш долг – поддерживать равновесие. Твоя задача – сократить популяцию этих духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 плутов Зеленой Скалы в Буковом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Эрезул. Через несколько дней численность плутов опять возрастет, но пока равновесие в природе восстановлено.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю земель У в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29631,'Жгучий страх','$n, могу я попросить тебя об услуге?$B$BПеред тем как я попал в монастырь, я совершенно не умел драться. Здесь меня этому научили, но мне никогда не приходилось защищать свою жизнь по-настоящему. Теперь я – стражник, и мне платят за защиту монастыря.$B$BВ общем, с лесными духами я еще справляюсь, а вот тигры Букового леса – это совсем другое дело. Может, разделаешься с ними вместо меня?','Уничтожьте 6 тигров в Буковом лесу.','Вернитесь к хранителю земель Шань Луну к монастырю Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жгучий страх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, могу я попросить тебя об услуге?$B$BПеред тем как я попал в монастырь, я совершенно не умел драться. Здесь меня этому научили, но мне никогда не приходилось защищать свою жизнь по-настоящему. Теперь я – стражник, и мне платят за защиту монастыря.$B$BВ общем, с лесными духами я еще справляюсь, а вот тигры Букового леса – это совсем другое дело. Может, разделаешься с ними вместо меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 тигров в Буковом лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю земель Шань Луну к монастырю Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29632,'Полная боевая готовность','Хорошо, |3-6($r), я хотел бы узнать, из какого теста ты $gвылеплен:вылеплена;.$B$BВызывай наших учеников на поединок. Заставь их выжать из себя максимум, а они будут стараться сделать это с тобой.$B$BКто бы из вас ни победил, в бою вы станете сильнее.','<Мастер Каменный Кулак подозрительно вас разглядывает.>$B$BНу, мне все ясно. Избивать юных учеников ты больше не будешь. Переходим к следующему этапу.','Вернитесь к мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полная боевая готовность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, |3-6($r), я хотел бы узнать, из какого теста ты $gвылеплен:вылеплена;.$B$BВызывай наших учеников на поединок. Заставь их выжать из себя максимум, а они будут стараться сделать это с тобой.$B$BКто бы из вас ни победил, в бою вы станете сильнее.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мастер Каменный Кулак подозрительно вас разглядывает.>$B$BНу, мне все ясно. Избивать юных учеников ты больше не будешь. Переходим к следующему этапу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29633,'Ловкий Чжи-Чжи','На одном из холмов, что справа, ты найдешь хозена по имени Чжи-Чжи. Он, как и ты, одержал много побед в тренировочных поединках. Одолеть его будет не так уж легко.$B$BВызови его на бой и постарайся победить.','Победите Чжи-Чжи в монастыре Тянь.','Воин, похоже, ты снова переходишь на новый уровень.','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.','Быстро бьет, но не так быстро соображает.','Чжи-Чжи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловкий Чжи-Чжи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На одном из холмов, что справа, ты найдешь хозена по имени Чжи-Чжи. Он, как и ты, одержал много побед в тренировочных поединках. Одолеть его будет не так уж легко.$B$BВызови его на бой и постарайся победить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Чжи-Чжи в монастыре Тянь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воин, похоже, ты снова переходишь на новый уровень.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Быстро бьет, но не так быстро соображает.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чжи-Чжи',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29634,'Иссохший Хушунь','Цзинь-юй – давние союзники пандаренов, и поэтому мы с радостью принимаем их в монастыре. Недавно нашим учеником стал Хушунь, один из их старейших шаманов.$B$BКак монах Хушунь пока зауряден, но он был и остается неистовым бойцом. Он сможет оказать тебе достойное сопротивление.','Бросьте вызов Хушуню и победите его в монастыре Тянь.','Воин, предупреждаю!$B$BЕсли ты и дальше будешь побеждать моих лучших воспитанников, я уже не смогу тебя обучать. И тогда ты лишишься возможности наслаждаться моим обществом.$B$BПодумай как следует, прежде чем расправляться с моими учениками.$B$B<Трудно сказать, шутит мастер Каменный Кулак или нет.>','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.','Неудивительно, что он любит находиться у воды.','Хушунь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иссохший Хушунь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цзинь-юй – давние союзники пандаренов, и поэтому мы с радостью принимаем их в монастыре. Недавно нашим учеником стал Хушунь, один из их старейших шаманов.$B$BКак монах Хушунь пока зауряден, но он был и остается неистовым бойцом. Он сможет оказать тебе достойное сопротивление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов Хушуню и победите его в монастыре Тянь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воин, предупреждаю!$B$BЕсли ты и дальше будешь побеждать моих лучших воспитанников, я уже не смогу тебя обучать. И тогда ты лишишься возможности наслаждаться моим обществом.$B$BПодумай как следует, прежде чем расправляться с моими учениками.$B$B<Трудно сказать, шутит мастер Каменный Кулак или нет.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Неудивительно, что он любит находиться у воды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хушунь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29635,'Обжора Сяо','Думаю, ты уже $gвстречался:встречалась; с моим лучшим учеником Сяо... за праздничным столом. Я учу его много лет и очень им доволен, но инструктор Сянь настаивает, что Сяо не хватает дисциплины.$B$BЕсли хочешь знать мое мнение, то дисциплина вообще не важна, пока ты побеждаешь в каждом своем бою. Интересно, продолжит ли Сяо свою серию побед в поединке с тобой?','Бросьте вызов Сяо и победите его в монастыре Тянь.','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.','Осторожно! Любит бросаться едой.','Сяо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обжора Сяо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, ты уже $gвстречался:встречалась; с моим лучшим учеником Сяо... за праздничным столом. Я учу его много лет и очень им доволен, но инструктор Сянь настаивает, что Сяо не хватает дисциплины.$B$BЕсли хочешь знать мое мнение, то дисциплина вообще не важна, пока ты побеждаешь в каждом своем бою. Интересно, продолжит ли Сяо свою серию побед в поединке с тобой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов Сяо и победите его в монастыре Тянь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мастеру Каменному Кулаку в монастырь Тянь, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожно! Любит бросаться едой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сяо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29636,'Проверка на выносливость','$n, я научил тебя всему, что знаю сам. Тебе пора обратиться к инструктору Мян.$B$BПо сравнению с моими тренировками ее спарринги необычны. Но пусть тебя это не смущает – странствующий искатель приключений часто попадает в непредсказуемые ситуации, так что широкие познания различных стилей боя – ценный навык.$B$BПрощай, $n, и удачи тебе в тренировках.','Явитесь к инструктору Мян, которая находится в западной части монастыря Тянь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проверка на выносливость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я научил тебя всему, что знаю сам. Тебе пора обратиться к инструктору Мян.$B$BПо сравнению с моими тренировками ее спарринги необычны. Но пусть тебя это не смущает – странствующий искатель приключений часто попадает в непредсказуемые ситуации, так что широкие познания различных стилей боя – ценный навык.$B$BПрощай, $n, и удачи тебе в тренировках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к инструктору Мян, которая находится в западной части монастыря Тянь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29637,'Суматоха','Мастер Каменный Кулак научил тебя побеждать противника в бою один на один. А теперь ты узнаешь, как сражаться со многими.$B$BКак насчет пятидесяти?$B$BСпустись в Круг Внутреннего Сосредоточения и, когда будешь $gготов:готова;, запусти этот фейерверк. После этого тебя начнут атаковать мои помощники.$B$BТебе нужно просто выжить.','Запустите монастырский фейерверк, находясь в Круге Внутреннего Сосредоточения, а затем продержитесь в этой суматохе не менее двух минут.','Вернитесь к инструктору Мян в монастырь Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суматоха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер Каменный Кулак научил тебя побеждать противника в бою один на один. А теперь ты узнаешь, как сражаться со многими.$B$BКак насчет пятидесяти?$B$BСпустись в Круг Внутреннего Сосредоточения и, когда будешь $gготов:готова;, запусти этот фейерверк. После этого тебя начнут атаковать мои помощники.$B$BТебе нужно просто выжить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запустите монастырский фейерверк, находясь в Круге Внутреннего Сосредоточения, а затем продержитесь в этой суматохе не менее двух минут.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Мян в монастырь Тянь в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29638,'UNUSED','Your training is over, young one. The cycle is complete. Thankfully, this particular cycle ends exactly where it started... with a banquet.$b$bI will meet you over at the banquet grounds. I will likely be dancing on a table.','Явитесь к Верховному старейшине Дождевой Туче, который находится на площадке для пиршества в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Your training is over, young one. The cycle is complete. Thankfully, this particular cycle ends exactly where it started... with a banquet.$b$bI will meet you over at the banquet grounds. I will likely be dancing on a table.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Верховному старейшине Дождевой Туче, который находится на площадке для пиршества в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29639,'С отличием','$n, ты $gпрошел:прошла; все испытания. Обучение закончено, и теперь тебя ждут великие дела...$B$B...но только после пиршества! Верховный старейшина будет ждать тебя на площадке для пиршества. Там мы отпразднуем окончание твоего обучения в нашем монастыре.','Явитесь к Верховному старейшине Дождевой Туче, который находится в монастыре Тянь в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С отличием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gпрошел:прошла; все испытания. Обучение закончено, и теперь тебя ждут великие дела...$B$B...но только после пиршества! Верховный старейшина будет ждать тебя на площадке для пиршества. Там мы отпразднуем окончание твоего обучения в нашем монастыре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Верховному старейшине Дождевой Туче, который находится в монастыре Тянь в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29640,'Найти шпиона То\'гуна!','Члены Совета Теней уже убили большинство наших шпионов. То\'гуну удалось сбежать, но он оказался настолько беспечен, что после этого снова вернулся к своей деятельности. $b$bТы $gдолжен:должна; найти его. Возможно он и глуп, но нам нужна информация, которую он раздобыл.','Найдите шпиона То\'гуна в Темном лабиринте в Аукиндоне.','Поможешь мне выбраться из этой клетки? А то тут тесновато!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти шпиона То\'гуна!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Члены Совета Теней уже убили большинство наших шпионов. То\'гуну удалось сбежать, но он оказался настолько беспечен, что после этого снова вернулся к своей деятельности. $b$bТы $gдолжен:должна; найти его. Возможно он и глуп, но нам нужна информация, которую он раздобыл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите шпиона То\'гуна в Темном лабиринте в Аукиндоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поможешь мне выбраться из этой клетки? А то тут тесновато!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29641,'Инструменты души','Ох! Они пытали меня, хотели вытянуть из меня все, что я знаю...$B$BЯ потерпел неудачу – они скормили всех наших Гиблочреву, и я должен был быть следующим... Но я ничего, ничего им не выдал!$B$BОни увеличивают мощность вызова при помощи специальных предметов. Эти устройства нужно украсть!','Украдите 5 инструментов душ и принесите их шпиону Грик\'те в Темный лабиринт Аукиндона.','Это и есть инструменты душ, которые Совет Теней использует для усиления силы призыва? Интересно...','Тебе удалось отыскать То\'гуна?','Вернитесь к шпиону Грик\'те в Темный лабиринт, что в Аукиндоне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструменты души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох! Они пытали меня, хотели вытянуть из меня все, что я знаю...$B$BЯ потерпел неудачу – они скормили всех наших Гиблочреву, и я должен был быть следующим... Но я ничего, ничего им не выдал!$B$BОни увеличивают мощность вызова при помощи специальных предметов. Эти устройства нужно украсть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 5 инструментов душ и принесите их шпиону Грик\'те в Темный лабиринт Аукиндона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это и есть инструменты душ, которые Совет Теней использует для усиления силы призыва? Интересно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось отыскать То\'гуна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шпиону Грик\'те в Темный лабиринт, что в Аукиндоне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29642,'В Аукиндоне неспокойно','Мои шпионы шлют очень тревожные донесения из Аукиндона. Со времени взрыва это место не доставляло нам ничего, кроме проблем.$B$BИ опять там происходит что-то ужасное. Похоже, Совет Теней вознамерился развязать войну. Хотя донесения недостаточно подробные, понятно, что приготовления идут вовсю.$B$BТебе придется пробраться в Темный лабиринт. Полевой командир Мафуун скажет тебе, что делать.','Ты появился очень вовремя.$B$BМы уже довольно долго здесь сражаемся, и еще несколько дней назад Мелиса обещала прислать подкрепление.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Аукиндоне неспокойно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои шпионы шлют очень тревожные донесения из Аукиндона. Со времени взрыва это место не доставляло нам ничего, кроме проблем.$B$BИ опять там происходит что-то ужасное. Похоже, Совет Теней вознамерился развязать войну. Хотя донесения недостаточно подробные, понятно, что приготовления идут вовсю.$B$BТебе придется пробраться в Темный лабиринт. Полевой командир Мафуун скажет тебе, что делать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты появился очень вовремя.$B$BМы уже довольно долго здесь сражаемся, и еще несколько дней назад Мелиса обещала прислать подкрепление.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29643,'Кодекс Крови','Два года назад совет призвал существо, которое разрушило Аукиндон до основания.$B$BПрочитайте Кодекс Крови, чтобы узнать эту историю. Но будьте осторожны: Великий мастер Ворпил будет защищать его не щадя собственной жизни.','Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне.','Вы открываете фолиант, и вас внезапно охватывает ужас.$B$BЧто-то здесь определенно не так!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кодекс Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Два года назад совет призвал существо, которое разрушило Аукиндон до основания.$B$BПрочитайте Кодекс Крови, чтобы узнать эту историю. Но будьте осторожны: Великий мастер Ворпил будет защищать его не щадя собственной жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте Кодекс Крови в Темном лабиринте в Аукиндоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы открываете фолиант, и вас внезапно охватывает ужас.$B$BЧто-то здесь определенно не так!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29644,'В самом сердце Лабиринта','Совет Теней потерял контроль над неким космическим существом, которое он призвал два года назад.$B$BТеперь это создание, известное как Бормотун, пытается уничтожить Совет Теней и вырваться во внешний мир','Уничтожьте Бормотуна и доложите об этом боевому командиру Мафууну в Темном лабиринте в Аукиндоне.','Вернитесь к боевому командиру Мафууну в Темный лабиринт, что в Аукиндоне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В самом сердце Лабиринта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совет Теней потерял контроль над неким космическим существом, которое он призвал два года назад.$B$BТеперь это создание, известное как Бормотун, пытается уничтожить Совет Теней и вырваться во внешний мир',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Бормотуна и доложите об этом боевому командиру Мафууну в Темном лабиринте в Аукиндоне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому командиру Мафууну в Темный лабиринт, что в Аукиндоне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29645,'Посол Гиблочрев','Когда кабалисты поймали наших шпионов, они скормили их живьем послу Гиблочреву.$B$BМы должны отомстить за наших людей. Перебей ритуалистов, что удерживают Гиблочрева, а после прикончи его самого.$B$BДругой участи он не заслужил.','Убейте 12 кабалистов-ритуалистов и посла Гиблочрева, а затем вернитесь к боевому командиру Мафууну, его можно найти около Темного Лабиринта Аукиндона.','Это не вернет погибших, но, по крайней мере, мы свершили правосудие.','Тебе удалось убить посла?','Вернитесь к боевому командиру Мафууну в Темный лабиринт, что в Аукиндоне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посол Гиблочрев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда кабалисты поймали наших шпионов, они скормили их живьем послу Гиблочреву.$B$BМы должны отомстить за наших людей. Перебей ритуалистов, что удерживают Гиблочрева, а после прикончи его самого.$B$BДругой участи он не заслужил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 кабалистов-ритуалистов и посла Гиблочрева, а затем вернитесь к боевому командиру Мафууну, его можно найти около Темного Лабиринта Аукиндона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это не вернет погибших, но, по крайней мере, мы свершили правосудие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось убить посла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому командиру Мафууну в Темный лабиринт, что в Аукиндоне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29646,'С отличием','Ну, я научил тебя всему, что знал. И все остальные, кажется, тоже.$B$BВерховный старейшина Дождевая Туча будет ждать тебя на площадке для пиршества. Он уже готов отпраздновать твой отъезд. Нет, дело не в том, что мы рады твоему уходу... просто он любит праздники.','Поговорите с верховным старейшиной Дождевой Тучей, который находится на площадке для пиршества в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С отличием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, я научил тебя всему, что знал. И все остальные, кажется, тоже.$B$BВерховный старейшина Дождевая Туча будет ждать тебя на площадке для пиршества. Он уже готов отпраздновать твой отъезд. Нет, дело не в том, что мы рады твоему уходу... просто он любит праздники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным старейшиной Дождевой Тучей, который находится на площадке для пиршества в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29647,'С отличием','Суматоха была твоим последним испытанием. Ты $gизучил:изучила; все предметы, которые преподают в нашем монастыре.$B$BТвое обучение началось с пиршества, им и закончится. Верховный старейшина Дождевая Туча будет ждать тебя на площадке для пиршества. Я буду рядом.','Поговорите с верховным старейшиной Дождевой Тучей на площадке для пиршества в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С отличием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Суматоха была твоим последним испытанием. Ты $gизучил:изучила; все предметы, которые преподают в нашем монастыре.$B$BТвое обучение началось с пиршества, им и закончится. Верховный старейшина Дождевая Туча будет ждать тебя на площадке для пиршества. Я буду рядом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным старейшиной Дождевой Тучей на площадке для пиршества в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29648,'UNUSED') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29649,'Спасение жизни','Пушкаренка убивает могучее проклятие, $n.$B$BСилу главного чернокнижника Пустоклята увеличивают две таинственных жаровни. Быть может, если ты принесешь мне уголек из такой жаровни, мы сможем как-то противодействовать темной магии?','Он был славным солдатом.','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пушкаренка убивает могучее проклятие, $n.$B$BСилу главного чернокнижника Пустоклята увеличивают две таинственных жаровни. Быть может, если ты принесешь мне уголек из такой жаровни, мы сможем как-то противодействовать темной магии?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он был славным солдатом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29650,'Уголь Скверны','Каса\'рес умирает, как трус.$B$BГлавный чернокнижник Пустоклят наложил на него могучее проклятье. Быть может, если ты принесешь мне уголек из его жаровни, мы сможем как-то противодействовать темной магии, пока еще не слишком поздно?','Я спою множество песен о его славе.','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уголь Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каса\'рес умирает, как трус.$B$BГлавный чернокнижник Пустоклят наложил на него могучее проклятье. Быть может, если ты принесешь мне уголек из его жаровни, мы сможем как-то противодействовать темной магии, пока еще не слишком поздно?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я спою множество песен о его славе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29651,'Почтить память погибших','Их лучшие воины беспощадны... и очень сильны.$B$B<Каса\'рес сплевывает кровь.>$B$BТебе нужно будет убить их... иначе нам не победить Каргата...','Каса\'реса... больше нет.','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почтить память погибших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Их лучшие воины беспощадны... и очень сильны.$B$B<Каса\'рес сплевывает кровь.>$B$BТебе нужно будет убить их... иначе нам не победить Каргата...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каса\'реса... больше нет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29652,'Последняя услуга','Старина Пушкаренок долго не протянет...$B$BОкажи мне услугу, убей напоследок самых крупных и подлых орков Скверны, что тебе попадутся.$B$BКак в старые времена, а?','Если бы только мы смогли его спасти...','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что на полуострове Адского пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя услуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старина Пушкаренок долго не протянет...$B$BОкажи мне услугу, убей напоследок самых крупных и подлых орков Скверны, что тебе попадутся.$B$BКак в старые времена, а?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если бы только мы смогли его спасти...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что на полуострове Адского пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (29653,'Воля Вождя','Каргат в свое время был одним из величайших героев орды.$B$BСейчас он носит плащ лже-вождя. Принеси мне его именное оружие, чтобы в нашей памяти он остался великим воителем, каким он был когда-то, а не тем чудовищем, в которое превратился сейчас.','Мы должны запомнить Каргата таким, каким он был раньше, и извлечь для себя уроки их его падения.','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.','Он больше не владеет собой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воля Вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каргат в свое время был одним из величайших героев орды.$B$BСейчас он носит плащ лже-вождя. Принеси мне его именное оружие, чтобы в нашей памяти он остался великим воителем, каким он был когда-то, а не тем чудовищем, в которое превратился сейчас.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны запомнить Каргата таким, каким он был раньше, и извлечь для себя уроки их его падения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он больше не владеет собой.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (29654,'Новый поворот событий','Орки Скверны представляют большую угрозу для Оплота Чести и всего Альянса. Покончить с ней можно лишь одним способом.$B$BНадо убить их вождя.$B$BИ принеси мне его именное оружие, чтобы день его гибели навсегда остался в нашей памяти.','С твоей помощью мы сумели нанести врагу сокрушительный удар.$B$BВпервые за последние годы в Оплоте Чести стало относительно безопасно.','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.','Устранить его – важнейшая задача в этой войне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый поворот событий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Скверны представляют большую угрозу для Оплота Чести и всего Альянса. Покончить с ней можно лишь одним способом.$B$BНадо убить их вождя.$B$BИ принеси мне его именное оружие, чтобы день его гибели навсегда остался в нашей памяти.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей помощью мы сумели нанести врагу сокрушительный удар.$B$BВпервые за последние годы в Оплоте Чести стало относительно безопасно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Устранить его – важнейшая задача в этой войне.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29655,'Особая ткань','Омрогг Завоеватель убил больше храбрых воинов, чем любой другой враг, с которыми меня сводила судьба. Он безжалостен, хитер и невероятно могуч.$B$BУбей его и принеси мне его боевое облачение. Из него мы сделаем знамя, которое вселит в сердца наших врагов страх перед Ордой!','Хорошо. Пусть эти обезумевшие кровожадные твари знают, с кем связались.','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особая ткань',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Омрогг Завоеватель убил больше храбрых воинов, чем любой другой враг, с которыми меня сводила судьба. Он безжалостен, хитер и невероятно могуч.$B$BУбей его и принеси мне его боевое облачение. Из него мы сделаем знамя, которое вселит в сердца наших врагов страх перед Ордой!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Пусть эти обезумевшие кровожадные твари знают, с кем связались.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Сток\'тону в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29656,'Боевое облачение Омрогга','Штормграду нужны доказательства наших успехов в военной кампании.$B$BДумаю, что вместо мешков для трупов стоит продемонстрировать ему боевое облачение Омрогга, самого свирепого воина Каргата. Как думаешь, тебе по силам будет его одолеть?','Моих начальников это очень порадует. Спасибо.','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевое облачение Омрогга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Штормграду нужны доказательства наших успехов в военной кампании.$B$BДумаю, что вместо мешков для трупов стоит продемонстрировать ему боевое облачение Омрогга, самого свирепого воина Каргата. Как думаешь, тебе по силам будет его одолеть?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моих начальников это очень порадует. Спасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному разведчику Чадвику в Разрушенные залы, что в Цитадели Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29657,'Кому многое дано, с того много и спросится','А\'дал попросил вас убить механолорда Конденсарона в Механаре, в Крепости Бурь.','Не тревожься.','А\'дал','Наша работа здесь еще на закончена.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кому многое дано, с того много и спросится',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить механолорда Конденсарона в Механаре, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не тревожься.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Наша работа здесь еще на закончена.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29658,'Паталеон Вычислитель','<Легкий ветерок обдувает ваше лицо.>$B$BОсталось еще одно дело.$B$BПаталеон Вычислитель надзирает за выполнением многих поручений своего повелителя. Он лично повинен во множестве несчастий, что недавно обрушились на этот мир.$B$BЯ попрошу тебя уничтожить его.','А\'дал попросил вас убить Паталеона Вычислителя в Механаре, в Крепости Бурь.','Моя воля должна быть исполнена.','А\'дал','Надежда еще есть.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паталеон Вычислитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Легкий ветерок обдувает ваше лицо.>$B$BОсталось еще одно дело.$B$BПаталеон Вычислитель надзирает за выполнением многих поручений своего повелителя. Он лично повинен во множестве несчастий, что недавно обрушились на этот мир.$B$BЯ попрошу тебя уничтожить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить Паталеона Вычислителя в Механаре, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Моя воля должна быть исполнена.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Надежда еще есть.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29659,'Потерянное сокровище','Я чувствую, что один из артефактов моего народа был похищен и помещен на Склад Легиона.$B$BМы не можем позволить им открыть для себя его истинную мощь. Если ты убьешь стражей ворот и достанешь артефакт, я буду тебе очень благодарен.','Добудьте для А\'дала Ослепляющую ярость со Склада Легиона в Механаре, в Крепости Бурь.','Мы не можем допустить, чтобы он оказался не в тех руках.','А\'дал','Мы благодарны тебе за старания.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянное сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, что один из артефактов моего народа был похищен и помещен на Склад Легиона.$B$BМы не можем позволить им открыть для себя его истинную мощь. Если ты убьешь стражей ворот и достанешь артефакт, я буду тебе очень благодарен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте для А\'дала Ослепляющую ярость со Склада Легиона в Механаре, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы не можем допустить, чтобы он оказался не в тех руках.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мы благодарны тебе за старания.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29660,'Спасение Ботаники','Силы Кель\'таса в Ботанике не сумели обуздать множество содержавшихся там созданий. Мы должны действовать немедленно, чтобы исправить их ошибки.$B$BПервое, что нужно будет сделать – это уничтожить их силы, чтобы в будущем они не доставили проблем.','А\'дал попросил вас убить командира Саранниса, верховного ботаника Фрейвина и Скалезуба Скорбного в Ботанике, в Крепости Бурь.','Ты мне поможешь?','А\'дал','Теперь мы должны разобраться с экспериментами.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Ботаники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы Кель\'таса в Ботанике не сумели обуздать множество содержавшихся там созданий. Мы должны действовать немедленно, чтобы исправить их ошибки.$B$BПервое, что нужно будет сделать – это уничтожить их силы, чтобы в будущем они не доставили проблем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить командира Саранниса, верховного ботаника Фрейвина и Скалезуба Скорбного в Ботанике, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ты мне поможешь?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Теперь мы должны разобраться с экспериментами.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29661,'Урок сухого меха','Я хочу найти способ определить, где находится Шу, с помощью медитации. Ты же можешь потратить это время на тренировки.$B$BПервое твое задание – обычное для всех учеников на этих прудах. Пройди по тренировочным столбам, что к западу отсюда, и позвони в колокол, при этом не упав в пруд.$B$BЕсли же ты сорвешься, проклятие пруда не позволит тебе вновь забраться на столб: тебе придется вернуться на берег и начать все сначала.$b$bАх, да, и остерегайся журавлей.','Пройдите по столбам и позвоните в колокол.','$gВыполнил:Выполнила; ли ты мое задание?','Вернитесь к Аисе Воспевающей Облака к Поющим прудам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок сухого меха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу найти способ определить, где находится Шу, с помощью медитации. Ты же можешь потратить это время на тренировки.$B$BПервое твое задание – обычное для всех учеников на этих прудах. Пройди по тренировочным столбам, что к западу отсюда, и позвони в колокол, при этом не упав в пруд.$B$BЕсли же ты сорвешься, проклятие пруда не позволит тебе вновь забраться на столб: тебе придется вернуться на берег и начать все сначала.$b$bАх, да, и остерегайся журавлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите по столбам и позвоните в колокол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$gВыполнил:Выполнила; ли ты мое задание?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аисе Воспевающей Облака к Поющим прудам.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29662,'Прочней тростника','Принеси мне тростник, что растет в прудах поблизости.$B$BНе спрашивай – зачем. Принесешь – увидишь.','Соберите 8 стеблей жесткого тростника.','Отлично.$B$BПередо мной никакой тростник не устоит.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.','Если я начну хвастаться своей силой, ты мне не поверишь. Лучше я покажу.','Вернитесь к Йо-Йо Железной Брови к Поющим прудам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочней тростника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принеси мне тростник, что растет в прудах поблизости.$B$BНе спрашивай – зачем. Принесешь – увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 стеблей жесткого тростника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично.$B$BПередо мной никакой тростник не устоит.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если я начну хвастаться своей силой, ты мне не поверишь. Лучше я покажу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо-Йо Железной Брови к Поющим прудам.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29663,'Урок равновесия','Для медитации мне нужно достичь большего умиротворения. Ты же, пока я пытаюсь понять, где находится Шу, можешь продолжить тренировки.$B$BОстальные монахи тренируются удерживать равновесие и устраивают поединки на столбах, стоящих в прудах вокруг нас. Вызови их на поединок и одержи победу.','Одержите победу над 6 монахами Тушуй на тренировочных столбах.','Твое искусство растет не по дням, а по часам. Ты учишься крепче стоять на ногах. Удары твои становятся сильнее.$B$BТолько с помощью тренировок и самоконтроля ты сможешь по-настоящему раскрыть все то, что в тебе заложено.','Лишь с помощью самоконтроля мы постигнем гармонию. И лишь гармония позволит нам, воинам, достичь истинных высот в своем искусстве.','Вернитесь к Аисе Воспевающей Облака к Поющим прудам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок равновесия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для медитации мне нужно достичь большего умиротворения. Ты же, пока я пытаюсь понять, где находится Шу, можешь продолжить тренировки.$B$BОстальные монахи тренируются удерживать равновесие и устраивают поединки на столбах, стоящих в прудах вокруг нас. Вызови их на поединок и одержи победу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над 6 монахами Тушуй на тренировочных столбах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое искусство растет не по дням, а по часам. Ты учишься крепче стоять на ногах. Удары твои становятся сильнее.$B$BТолько с помощью тренировок и самоконтроля ты сможешь по-настоящему раскрыть все то, что в тебе заложено.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лишь с помощью самоконтроля мы постигнем гармонию. И лишь гармония позволит нам, воинам, достичь истинных высот в своем искусстве.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аисе Воспевающей Облака к Поющим прудам.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29664,'Огни, пробуждающие силу','Сила твоего разума велика, как и сила твоей воли, но тебе недостает мастерства, чтобы сразиться со мной. Да, ты сражаешься, используя возможности своего тела, но в действительности испытанию подвергается твой характер, твоя суть.$B$BУравняем наши шансы.$B$BВозьми этот факел, зажги его от жаровни, что стоит возле меня, а затем воспользуйся им, чтобы зажечь огонь в трех потухших жаровнях вокруг пруда.','Зажгите ваш факел новичка от жаровни с мерцающим пламенем, после чего с его помощью разожгите огонь на 3 жаровнях возле мастера Ли Фэя.','Вернитесь к мастеру Ли Фэю в Святилище Внутреннего Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огни, пробуждающие силу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сила твоего разума велика, как и сила твоей воли, но тебе недостает мастерства, чтобы сразиться со мной. Да, ты сражаешься, используя возможности своего тела, но в действительности испытанию подвергается твой характер, твоя суть.$B$BУравняем наши шансы.$B$BВозьми этот факел, зажги его от жаровни, что стоит возле меня, а затем воспользуйся им, чтобы зажечь огонь в трех потухших жаровнях вокруг пруда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите ваш факел новичка от жаровни с мерцающим пламенем, после чего с его помощью разожгите огонь на 3 жаровнях возле мастера Ли Фэя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Ли Фэю в Святилище Внутреннего Света.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29665,'Чем дальше – тем хуже','Когда они потерпели кораблекрушение, из моря появились злобные существа, и теперь эти существа копошатся в обломках. Наша помощь, возможно, лишь капля в пруду по сравнению с масштабами несчастья, что постигло их сегодня.$B$BУбей их мучителей. Эти люди отчаянно нуждаются в нашей помощи.','Убейте 8 глубоководных чешуйчатых мучителей.','Да, на поле боя ты любому внушишь страх.','Вернитесь к Йо-Йо Железной Брови на место падения "Небесного искателя".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем дальше – тем хуже',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда они потерпели кораблекрушение, из моря появились злобные существа, и теперь эти существа копошатся в обломках. Наша помощь, возможно, лишь капля в пруду по сравнению с масштабами несчастья, что постигло их сегодня.$B$BУбей их мучителей. Эти люди отчаянно нуждаются в нашей помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 глубоководных чешуйчатых мучителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, на поле боя ты любому внушишь страх.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо-Йо Железной Брови на место падения "Небесного искателя".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29666,'Сквозь тернии','Пруды не безопасны. Последняя и самая опасная угроза исходит от водомерок. Пришло время сократить их число, но, к сожалению, сам я с этой задачей справиться уже не могу.$B$BЕсли ты уничтожишь часть заполонивших пруды водомерок, я буду тебе очень признателен. Помни об их количестве... лучше выманить их к берегу, не залезая в пруд.','Убейте 6 водомерок.','Водомерки – странные создания. Похоже, их привлекает спокойная вода.','Равновесие - хрупкая вещь. Оно во многом опирается на мудрость старейшин. Их уроки часто неочевидны для юного ума, поэтому тебе нужно лишь помнить, что лишь их знания о прошлом позволяют нам сохранять настоящее.','Поговорите со стариком Ляном у Поющих прудов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сквозь тернии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пруды не безопасны. Последняя и самая опасная угроза исходит от водомерок. Пришло время сократить их число, но, к сожалению, сам я с этой задачей справиться уже не могу.$B$BЕсли ты уничтожишь часть заполонивших пруды водомерок, я буду тебе очень признателен. Помни об их количестве... лучше выманить их к берегу, не залезая в пруд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 водомерок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Водомерки – странные создания. Похоже, их привлекает спокойная вода.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Равновесие - хрупкая вещь. Оно во многом опирается на мудрость старейшин. Их уроки часто неочевидны для юного ума, поэтому тебе нужно лишь помнить, что лишь их знания о прошлом позволяют нам сохранять настоящее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со стариком Ляном у Поющих прудов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29667,'Истребление безнадежных','Похоже, силы Кель\'таса испортили содержащихся в Ботанике особей настолько, что их уже не спасти. Я не хочу, чтобы они вырвались оттуда на волю и хлынули в Запределье.$B$BСреди них есть некий Ладж. Он не такой, как все, и я хочу изучить его. Возможно, мы что-то узнаем.','А\'дал попросил вас убить 6 мутантных плотохлестов, 6 мутантных страховизгов и 6 мутантных ужасов, а также достать быстрорастущую ветку Ладжа в Ботанике, в Крепости Бурь.','У нас нет иного выбора.','А\'дал','Все это очень тревожно.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление безнадежных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, силы Кель\'таса испортили содержащихся в Ботанике особей настолько, что их уже не спасти. Я не хочу, чтобы они вырвались оттуда на волю и хлынули в Запределье.$B$BСреди них есть некий Ладж. Он не такой, как все, и я хочу изучить его. Возможно, мы что-то узнаем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить 6 мутантных плотохлестов, 6 мутантных страховизгов и 6 мутантных ужасов, а также достать быстрорастущую ветку Ладжа в Ботанике, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У нас нет иного выбора.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Все это очень тревожно.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29669,'Нерадостное поручение','То, о чем я тебя сейчас попрошу, пронзает мое сердце болью, но у меня нет выбора.$B$BКогда-то Узлодревень был хранителем всей Ботаники, но сейчас и его коснулась скверна. Его нужно будет уничтожить.','А\'дал попросил вас убить Узлодревня в Ботанике, в Крепости Бурь.','Мне так хотелось бы, чтобы до этого не дошло.','А\'дал','Его дух выдержит это.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нерадостное поручение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, о чем я тебя сейчас попрошу, пронзает мое сердце болью, но у меня нет выбора.$B$BКогда-то Узлодревень был хранителем всей Ботаники, но сейчас и его коснулась скверна. Его нужно будет уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить Узлодревня в Ботанике, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мне так хотелось бы, чтобы до этого не дошло.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Его дух выдержит это.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29670,'Расправа над Гормалом','Благодаря тебе у нас теперь есть ополчение – оно сидит в засаде неподалеку. Ханьай сказала что-то про "огненную ярость" – и это, похоже, означает, что они сейчас пьяные и злые.$B$BМогу думают, что с нами можно не считаться. Что ж, мы заставим их раскрыть глаза от удивления.$b$bИди по тропе через руины, к пляжу. Отыщи их предводителя. Когда вступишь в бой, мы придем тебе на помощь.','Убейте Поработителя Гормала в лагере Гормал.','Все это крайне тревожно. Если могу собираются с силами по всему континенту, скоро они станут реальной угрозой для всей Пандарии.','Вернитесь к Дерзкому Шао в лагерь Гормал.','Он хотел бы видеть всех пандаренов закованными в цепи.','Поработитель Гормал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расправа над Гормалом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе у нас теперь есть ополчение – оно сидит в засаде неподалеку. Ханьай сказала что-то про "огненную ярость" – и это, похоже, означает, что они сейчас пьяные и злые.$B$BМогу думают, что с нами можно не считаться. Что ж, мы заставим их раскрыть глаза от удивления.$b$bИди по тропе через руины, к пляжу. Отыщи их предводителя. Когда вступишь в бой, мы придем тебе на помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Поработителя Гормала в лагере Гормал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все это крайне тревожно. Если могу собираются с силами по всему континенту, скоро они станут реальной угрозой для всей Пандарии.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дерзкому Шао в лагерь Гормал.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он хотел бы видеть всех пандаренов закованными в цепи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Поработитель Гормал',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29671,'Черные топи','Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Стража Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.$B$BТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са\'атом.','Пройдите сквозь Пещеры Времени до Черных топей времен открытия Темного портала и поговорите с Са\'атом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черные топи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Стража Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.$B$BТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са\'атом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сквозь Пещеры Времени до Черных топей времен открытия Темного портала и поговорите с Са\'атом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (29672,'Открытие Темного портала','Здесь Страж Медив пытается открыть Темный портал.$B$BПо всем топям будут открываться разломы, из которых хлынут Драконы Бесконечности, которые попытаются разрушить щиты Медива и уничтожить его самого.$B$BУбивай их лидеров и повелителей временных разломов, пока Медив не закончит свою работу!','Са\'ат из Черных топей в Пещерах Времени поручил вам защищать Медива, пока он не откроет Темный портал.$B$BКогда выполните задание, возвращайтесь к Са\'ату.','Темный портал открыт','Вернитесь к Са\'ату в Черные топи.','Он должен выполнить свою миссию!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открытие Темного портала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь Страж Медив пытается открыть Темный портал.$B$BПо всем топям будут открываться разломы, из которых хлынут Драконы Бесконечности, которые попытаются разрушить щиты Медива и уничтожить его самого.$B$BУбивай их лидеров и повелителей временных разломов, пока Медив не закончит свою работу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Са\'ат из Черных топей в Пещерах Времени поручил вам защищать Медива, пока он не откроет Темный портал.$B$BКогда выполните задание, возвращайтесь к Са\'ату.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Темный портал открыт',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Са\'ату в Черные топи.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он должен выполнить свою миссию!',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29673,'Черные топи','Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Стража Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.$B$BТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са\'атом.','Пройдите сквозь Пещеры Времени до Черных топей времен открытия Темного портала и поговорите с Са\'атом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черные топи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драконы Бесконечности, похоже, утратили свою хваленую проницательность. Они собираются уничтожить Стража Медива, чтобы он не открыл Темный портал. На первый взгляд, это могло бы усилить Альянс, но на самом деле приведет к катастрофе и гибели этого мира.$B$BТебе нужно будет отправиться по тропе времени в Черные топи. Иди на запад, потом на юг, мимо будущего меня, пока не дойдешь до тоннеля, где обитают болотные жители. Пройди этот тоннель и поговори с Са\'атом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сквозь Пещеры Времени до Черных топей времен открытия Темного портала и поговорите с Са\'атом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29674,'Бездонная тьма','А\'дал попросил вас убить Зерекета Бездонного в Аркатраце, в Крепости Бурь.','Никому из заключенных нельзя позволить уйти.','А\'дал','К сожалению, еще более опасным заключенным все же удалось бежать.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бездонная тьма',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить Зерекета Бездонного в Аркатраце, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Никому из заключенных нельзя позволить уйти.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','К сожалению, еще более опасным заключенным все же удалось бежать.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29675,'Пока, Даллия','Двое могучих союзников Пылающего Легиона, Провидец Гнева Соккорат и Даллия Глашатай Судьбы, начали собирать из заключенных демонов небольшую армию.$B$BНельзя допустить, чтобы она разрослась – иначе Аркатрац скоро станет очередным оплотом Легиона.','А\'дал попросил вас убить Провидца Гнева Соккората и Даллию Глашатая Судьбы в Аркатраце, в Крепости Бурь.','МЫ должны сделать все, чтобы остановить Легион.','А\'дал','Свет одержит верх.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока, Даллия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Двое могучих союзников Пылающего Легиона, Провидец Гнева Соккорат и Даллия Глашатай Судьбы, начали собирать из заключенных демонов небольшую армию.$B$BНельзя допустить, чтобы она разрослась – иначе Аркатрац скоро станет очередным оплотом Легиона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить Провидца Гнева Соккората и Даллию Глашатая Судьбы в Аркатраце, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','МЫ должны сделать все, чтобы остановить Легион.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Свет одержит верх.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29676,'Поиски старого друга','У Шу был друг, с которым он играл, – пожилой пандарен... старик Лян.$B$BНекоторое время назад Лян переселился подальше от города и перестал тренироваться у прудов. Мне рассказывали, что теперь он живет в небольшом домике на холме, что к северо-востоку отсюда.$B$BВозможно, Лян знает, что заставило Шу покинуть храм и где его можно теперь найти.$B$BОтправляйся к Ляну. Расспроси его о Шу.','Поговорите со стариком Ляном в его пристанище у Поющих прудов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски старого друга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Шу был друг, с которым он играл, – пожилой пандарен... старик Лян.$B$BНекоторое время назад Лян переселился подальше от города и перестал тренироваться у прудов. Мне рассказывали, что теперь он живет в небольшом домике на холме, что к северо-востоку отсюда.$B$BВозможно, Лян знает, что заставило Шу покинуть храм и где его можно теперь найти.$B$BОтправляйся к Ляну. Расспроси его о Шу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со стариком Ляном в его пристанище у Поющих прудов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29677,'Солнечная жемчужина','Шу, дух воды, вечно молод, как и все духи Шэнь-Цзынь Су. Я дружил с Шу всю свою жизнь, но больше играть с ним не могу. Я стар, и мне не хватает сил.$B$BХоть общаться с Шу и нелегко, угодить ему несложно: он попросту хочет дружить. Когда я раз в три месяца возвращался, чтобы поиграть с ним, я всегда брал с собой подарок – солнечную жемчужину. Найти солнечную жемчужину можно в прудах на юго-востоке. Возможно, тебе удастся стать его новым другом.','Достаньте солнечную жемчужину.','Желания Шу не сильно отличаются от наших. Он не хочет быть одиноким. Нежеланным, нелюбимым. Он хочет быть нужным и разделять свою жизнь с другими.$B$BЗная это, завоевать его доверие совсем несложно. Ему просто хочется компании.','Принять решение не возвращаться к прудам было для меня непросто. Не думаю, что Шу понял, почему я не вернулся. Он не знает, что такое постареть и утратить силы.','Поговорите со стариком Ляном у Поющих прудов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Солнечная жемчужина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шу, дух воды, вечно молод, как и все духи Шэнь-Цзынь Су. Я дружил с Шу всю свою жизнь, но больше играть с ним не могу. Я стар, и мне не хватает сил.$B$BХоть общаться с Шу и нелегко, угодить ему несложно: он попросту хочет дружить. Когда я раз в три месяца возвращался, чтобы поиграть с ним, я всегда брал с собой подарок – солнечную жемчужину. Найти солнечную жемчужину можно в прудах на юго-востоке. Возможно, тебе удастся стать его новым другом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте солнечную жемчужину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Желания Шу не сильно отличаются от наших. Он не хочет быть одиноким. Нежеланным, нелюбимым. Он хочет быть нужным и разделять свою жизнь с другими.$B$BЗная это, завоевать его доверие совсем несложно. Ему просто хочется компании.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принять решение не возвращаться к прудам было для меня непросто. Не думаю, что Шу понял, почему я не вернулся. Он не знает, что такое постареть и утратить силы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со стариком Ляном у Поющих прудов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questturntargetname_loc8`) VALUES (29678,'Шу, дух воды','Шу скрывается в глубоком пруду на севере, и у него плохое настроение. Надо пройти по камням и бросить солнечную жемчужину в самый центр пруда. Он поймет намек.','Выманите духа воды Шу, чтобы поиграть с ним.','Похоже, тебе удалось привлечь его внимание, |3-6($c). Думаю, ты ему нравишься.','Аиса Воспевающая Облака') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шу, дух воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шу скрывается в глубоком пруду на севере, и у него плохое настроение. Надо пройти по камням и бросить солнечную жемчужину в самый центр пруда. Он поймет намек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выманите духа воды Шу, чтобы поиграть с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, тебе удалось привлечь его внимание, |3-6($c). Думаю, ты ему нравишься.',`offerrewardtext_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Аиса Воспевающая Облака',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29679,'Новый друг','Он хочет, чтобы ты $gпоиграл:поиграла; с ним. Вперед!','Поднимитесь на 5 фонтанов Шу.','Надо признать, со стороны мне это показалось весьма веселым времяпрепровождением.$B$BИ, похоже, у тебя появился новый друг.','Это твое задание, |3-6($c). Доведи дело до конца.','Поговорите с Аисой Воспевающей Облака у Пруда Созерцания.','Аиса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый друг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он хочет, чтобы ты $gпоиграл:поиграла; с ним. Вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднимитесь на 5 фонтанов Шу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо признать, со стороны мне это показалось весьма веселым времяпрепровождением.$B$BИ, похоже, у тебя появился новый друг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это твое задание, |3-6($c). Доведи дело до конца.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аисой Воспевающей Облака у Пруда Созерцания.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аиса',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29680,'Источник жизненной силы','Мы сделали все, о чем нас просил мастер Шан. Я вернусь в храм и извещу мастера о наших успехах. Следуй по дороге на юг, в сторону полей, и разыщи Угоу, духа земли.$B$BЦзи ждет тебя на крестьянском дворе Дай-Ло. Хочу тебя предупредить – Цзи в своей прямоте иногда ведет себя безрассудно. Помни о том, чему я тебя учила: о терпении и самоконтроле.','Поговорите с Цзи на крестьянском дворе Дай-Ло. У дороги стоит повозка, готовая вас отвезти.','$n! А я все думал – и когда же мы снова увидимся!$b$bК счастью, найти духа земли Угоу было довольно просто. А вот пробудить его... уже гораздо сложнее. Думаю, после всех этих тычков и ударов он проснется не в лучшем самочувствии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник жизненной силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сделали все, о чем нас просил мастер Шан. Я вернусь в храм и извещу мастера о наших успехах. Следуй по дороге на юг, в сторону полей, и разыщи Угоу, духа земли.$B$BЦзи ждет тебя на крестьянском дворе Дай-Ло. Хочу тебя предупредить – Цзи в своей прямоте иногда ведет себя безрассудно. Помни о том, чему я тебя учила: о терпении и самоконтроле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Цзи на крестьянском дворе Дай-Ло. У дороги стоит повозка, готовая вас отвезти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n! А я все думал – и когда же мы снова увидимся!$b$bК счастью, найти духа земли Угоу было довольно просто. А вот пробудить его... уже гораздо сложнее. Думаю, после всех этих тычков и ударов он проснется не в лучшем самочувствии.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29681,'Брешь в системе безопасности','Предвестник Скайрисс – вот главная причина несчастья, случившегося в Аркатраце.$B$BОн совратил с истинного пути начальника тюрьмы Мелличара и заставил его выпустить на свободу множество заключенных. Скоро и предвестник окажется на воле – это лишь вопрос времени.$B$B$n, ты $gдолжен:должна; уничтожить слугу Древних Богов!','А\'дал попросил вас убить предвестника Скайрисса в Аркатраце, в Крепости Бурь.','Будь осторожнее. Он невероятно могуч.','А\'дал','Их возможности вызывают опасения.','А\'дал') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брешь в системе безопасности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предвестник Скайрисс – вот главная причина несчастья, случившегося в Аркатраце.$B$BОн совратил с истинного пути начальника тюрьмы Мелличара и заставил его выпустить на свободу множество заключенных. Скоро и предвестник окажется на воле – это лишь вопрос времени.$B$B$n, ты $gдолжен:должна; уничтожить слугу Древних Богов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал попросил вас убить предвестника Скайрисса в Аркатраце, в Крепости Бурь.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Будь осторожнее. Он невероятно могуч.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','А\'дал',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Их возможности вызывают опасения.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','А\'дал',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (29682,'Терраса Магистров','Рассветное пламя решил, что мы погибли? Ха!$B$BЯ не посылал ему рапортов только потому, что мы не продвинулись ни на йоту!$B$BНо, может быть, ты поможешь нам изменить ситуацию?','Поговорите с экзархом Ларетором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терраса Магистров',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рассветное пламя решил, что мы погибли? Ха!$B$BЯ не посылал ему рапортов только потому, что мы не продвинулись ни на йоту!$B$BНо, может быть, ты поможешь нам изменить ситуацию?',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с экзархом Ларетором.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29683,'Провидец Провидцев','*Тирит говорит с трудом, кривясь от боли.*$b$bСтупай на террасу... используй сферу.$b$b...Они... подпитывают Солнечный Колодец....$b$b *Тирит жадно хватает ртом воздух.*$b$bПоспеши... Нужно остановить их... пока они не...$b$b*Тирит испускает дух.*','Тирит просит вас использовать шар на балконе Террасы Магистров.','Вернитесь к Калесгосу на Террасу Магистров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провидец Провидцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Тирит говорит с трудом, кривясь от боли.*$b$bСтупай на террасу... используй сферу.$b$b...Они... подпитывают Солнечный Колодец....$b$b *Тирит жадно хватает ртом воздух.*$b$bПоспеши... Нужно остановить их... пока они не...$b$b*Тирит испускает дух.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тирит просит вас использовать шар на балконе Террасы Магистров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калесгосу на Террасу Магистров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`endtext_loc8`) VALUES (29684,'Обрыв связи','Найдите Тирита.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обрыв связи',`title_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите Тирита.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29685,'Страшный противник','Ты $gсам видел:сама видела;, что силы Легиона без устали выкачивают силу из Солнечного Колодца, пытаясь направить ее на осуществление своих зловещих планов.$b$bКель\'тас оправился от поражения и снова возглавил армию своих слуг. Его нужно остановить.','*Ларетор внимательно слушает ваш рассказ о том, что произошло на Террасе Магистров.*$B$BНам будет очень не хватать Тирита. Славный был воин – и надежный товарищ. Но, благодаря тебе, его смерть не стала напрасной.','Вернитесь к Экзарху Ларетору на Террасу Магистров.','Это его последний час.','Кель\'тас Солнечный Скиталец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшный противник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсам видел:сама видела;, что силы Легиона без устали выкачивают силу из Солнечного Колодца, пытаясь направить ее на осуществление своих зловещих планов.$b$bКель\'тас оправился от поражения и снова возглавил армию своих слуг. Его нужно остановить.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Ларетор внимательно слушает ваш рассказ о том, что произошло на Террасе Магистров.*$B$BНам будет очень не хватать Тирита. Славный был воин – и надежный товарищ. Но, благодаря тебе, его смерть не стала напрасной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Экзарху Ларетору на Террасу Магистров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это его последний час.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кель\'тас Солнечный Скиталец',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29686,'Радикальный взгляд','Мы не имеем права проиграть эту войну. Я хочу задействовать наших дозорных, чтобы не посылать на смерть наших храбрецов.$B$BЛегиону недавно удалось заполучить в свои ряды могучее создание стихий, и для нашего дела нам понадобится его сущность.','Прекрасно! Я как можно скорее представлю этот проект своим начальникам!','Тебе удалось раздобыть нужную нам сущность?','Вернитесь к Экзарху Ларетору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Радикальный взгляд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не имеем права проиграть эту войну. Я хочу задействовать наших дозорных, чтобы не посылать на смерть наших храбрецов.$B$BЛегиону недавно удалось заполучить в свои ряды могучее создание стихий, и для нашего дела нам понадобится его сущность.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Я как можно скорее представлю этот проект своим начальникам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось раздобыть нужную нам сущность?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Экзарху Ларетору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29687,'Порочные связи','Легион и силы Кель\'таса последнее время стали сотрудничать слишком тесно, и это меня очень беспокоит.$B$BПо имеющимся у нас данным, Селин Огненное Сердце и жрица Делрисса сейчас пытаются объединить две армии вместе. Их нужно остановить.','Отлично, солдат. Шаг за шагом – к цели.','Вернитесь к Экзарху Ларетору на Террасу Магистров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порочные связи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легион и силы Кель\'таса последнее время стали сотрудничать слишком тесно, и это меня очень беспокоит.$B$BПо имеющимся у нас данным, Селин Огненное Сердце и жрица Делрисса сейчас пытаются объединить две армии вместе. Их нужно остановить.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, солдат. Шаг за шагом – к цели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Экзарху Ларетору на Террасу Магистров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29688,'Дальнейшее наступление','Держи голову пониже, а то и глазом не моргнешь, как ее проткнет стрелой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшее наступление',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Держи голову пониже, а то и глазом не моргнешь, как ее проткнет стрелой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (29689,'Переход в наступление','Тихо! Если они заметят нас сейчас – у нас не будет никаких шансов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переход в наступление',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тихо! Если они заметят нас сейчас – у нас не будет никаких шансов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29690,'Сквозь туман','<Назгрим вдыхает морской воздух.>$b$bЧувствуешь, $n? Это запах родного дома – земли, за которую наш род пролил много крови.$b$bИ прислушайся... ты слышишь это? Так звучат мир и спокойствие в созданном нами прибежище, куда наши враги боятся ступить.$b$bЗапомни это ощущение, оно вернется к тебе не скоро. Нас ждет война, в которой мы должны победить.$b$bА теперь иди собираться – мы отправляемся!','Поговорите с генералом Назгримом на борту "Кулака Адского Крика".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сквозь туман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Назгрим вдыхает морской воздух.>$b$bЧувствуешь, $n? Это запах родного дома – земли, за которую наш род пролил много крови.$b$bИ прислушайся... ты слышишь это? Так звучат мир и спокойствие в созданном нами прибежище, куда наши враги боятся ступить.$b$bЗапомни это ощущение, оно вернется к тебе не скоро. Нас ждет война, в которой мы должны победить.$b$bА теперь иди собираться – мы отправляемся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Назгримом на борту "Кулака Адского Крика".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29691,'Принеси мне клумбу!','Мой народ использует кровавый гибискус для многих вещей.$b$bК несчастью, после понижения уровня вод осталось только одно место, где его можно найти.$b$bЕсли ты принесешь мне немного гибискуса, я буду тебе очень признателен.','Соберите 5 цветков кровавого гибискуса и принесите их Тшу в Нижетопь.','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?','Удалось ли тебе собрать гибискус?','Вернитесь к Тшу в Нижетопь к Резервуару Кривого Клыка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принеси мне клумбу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ использует кровавый гибискус для многих вещей.$b$bК несчастью, после понижения уровня вод осталось только одно место, где его можно найти.$b$bЕсли ты принесешь мне немного гибискуса, я буду тебе очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 цветков кровавого гибискуса и принесите их Тшу в Нижетопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе собрать гибискус?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тшу в Нижетопь к Резервуару Кривого Клыка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29692,'Принеси мне еще одну клумбу!','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?','Вернитесь к Тшу в Нижетопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принеси мне еще одну клумбу!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты еще раз заглянешь в Нижетопь?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тшу в Нижетопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29693,'Топор генерала','Мало-помалу приходя в себя, вы начинаете осматривать окрестности и натыкаетесь на предмет, выделяющийся среди разбросанных обломков.$B$BИ вы понимаете, что впервые видите топор Назгрима не в крепкой руке своего хозяина. И этот факт делает ваше затруднительное положение еще более тревожным...$B$BЯсно одно: живой или мертвый, генерал захочет вернуть себе это оружие.','Отнесите топор Назгрима генералу Назгриму.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топор генерала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало-помалу приходя в себя, вы начинаете осматривать окрестности и натыкаетесь на предмет, выделяющийся среди разбросанных обломков.$B$BИ вы понимаете, что впервые видите топор Назгрима не в крепкой руке своего хозяина. И этот факт делает ваше затруднительное положение еще более тревожным...$B$BЯсно одно: живой или мертвый, генерал захочет вернуть себе это оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите топор Назгрима генералу Назгриму.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29694,'Перегруппировка!','Стало быть, у них есть авиабаза! На этот раз я недооценил капитана Альянса. Погибло так много хороших бойцов...$b$bНекоторым удалось пережить крушение, а нам сейчас пригодится любая помощь.$b$bРазыщи в лесу всех, кого сможешь, и осмотри место крушения. Собери бойцов в ближайшей деревне для контратаки.','Спасите Темного мастера Кирин, Риветта Сталехвата, Шокию и сержанта Горрока с Поляны Медовой Росы.','Поговорите с Горроком в Деревне Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перегруппировка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стало быть, у них есть авиабаза! На этот раз я недооценил капитана Альянса. Погибло так много хороших бойцов...$b$bНекоторым удалось пережить крушение, а нам сейчас пригодится любая помощь.$b$bРазыщи в лесу всех, кого сможешь, и осмотри место крушения. Собери бойцов в ближайшей деревне для контратаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Темного мастера Кирин, Риветта Сталехвата, Шокию и сержанта Горрока с Поляны Медовой Росы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Горроком в Деревне Медовой Росы.',`completedtext_loc8`);
