INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29696,'Мои звездочки!','Вещи Кирин растащили лесные духи – но ваше внимание привлекло именно это.$B$BКогда-то сумка, набитая метательными звездочками, висела у нее на поясе. "Звездочки" составляли важную часть ее арсенала.$B$BИ если вам удастся отнять это оружие у местного зверья, это очень поможет в дальнейшем.','Отнимите 100 метательных звезд Кирин у коварных лесных духов.','Поговорите с Кирин у Кулака Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мои звездочки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вещи Кирин растащили лесные духи – но ваше внимание привлекло именно это.$B$BКогда-то сумка, набитая метательными звездочками, висела у нее на поясе. "Звездочки" составляли важную часть ее арсенала.$B$BИ если вам удастся отнять это оружие у местного зверья, это очень поможет в дальнейшем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите 100 метательных звезд Кирин у коварных лесных духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кирин у Кулака Адского Крика.',`completedtext_loc8`);
