INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29703,'Бочка обезьян','Эти обезьянолюди сведут меня с ума! Я пытаюсь изучить особенности пивоварения пандаренов, но эти хозены успевают вылакать образцы раньше, чем мне удается провести все необходимые химические опыты. Не $gмог:могла; бы ты пойти и преподать им урок, разделавшись с парой-тройкой этих хулиганов? Обещаю, ты не пожалеешь о потраченном времени.','Салли хочет, чтобы вы убили 5 пьяных обезьян.','Доложите о результатах Салли Шипяточек, что ждет на крестьянском дворе на Шэнь-Цзынь Су.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бочка обезьян',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти обезьянолюди сведут меня с ума! Я пытаюсь изучить особенности пивоварения пандаренов, но эти хозены успевают вылакать образцы раньше, чем мне удается провести все необходимые химические опыты. Не $gмог:могла; бы ты пойти и преподать им урок, разделавшись с парой-тройкой этих хулиганов? Обещаю, ты не пожалеешь о потраченном времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Салли хочет, чтобы вы убили 5 пьяных обезьян.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доложите о результатах Салли Шипяточек, что ждет на крестьянском дворе на Шэнь-Цзынь Су.',`completedtext_loc8`);
