INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29705,'Нашествие расхитителей выпивки','Как будто нам не хватало хозенов. Теперь нам приходится иметь дело еще и с дворфийскими "пивоварами".$B$BНе $gмог:могла; бы ты вернуть украденные ими бутылки выпивки? Экономика Стальгорна не выдержит такого наплыва "предпринимателей".','Салли просит, чтобы вы отобрали 5 бутылок выпивки у охотников за выпивкой рядом с крестьянским двором в Шэнь-Цзынь Су.','$gДостал:Достала; бутылки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие расхитителей выпивки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как будто нам не хватало хозенов. Теперь нам приходится иметь дело еще и с дворфийскими "пивоварами".$B$BНе $gмог:могла; бы ты вернуть украденные ими бутылки выпивки? Экономика Стальгорна не выдержит такого наплыва "предпринимателей".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Салли просит, чтобы вы отобрали 5 бутылок выпивки у охотников за выпивкой рядом с крестьянским двором в Шэнь-Цзынь Су.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','$gДостал:Достала; бутылки?',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29706,'Взрывочонок','О нет, |3-6($c)! Служители духов, что обретаются поблизости, взъярились – и явно по какой-то надуманной причине.$b$bСделай что-нибудь, пока они не съели наши лица!','Убейте 5 разъяренных служителей духов, пока они не съели лицо Салли Шипяточек.','Вернитесь к Салли Шипяточек на крестьянский двор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывочонок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О нет, |3-6($c)! Служители духов, что обретаются поблизости, взъярились – и явно по какой-то надуманной причине.$b$bСделай что-нибудь, пока они не съели наши лица!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 разъяренных служителей духов, пока они не съели лицо Салли Шипяточек.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли Шипяточек на крестьянский двор.',`completedtext_loc8`);
