INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29712,'По законам Орды','Вы отчаянно пытаетесь осознать свое положение: крушение, чужая земля, почти вся команда погибла...$B$BОсматривая труп этого невезучего существа, вы вдруг замечаете, что вокруг полно его сородичей – и они растаскивают уцелевшие припасы.$B$BСейчас эти твари узнают, что такое правосудие по законам Орды.','Убейте 15 хозенов у обломков "Небесной акулы".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По законам Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы отчаянно пытаетесь осознать свое положение: крушение, чужая земля, почти вся команда погибла...$B$BОсматривая труп этого невезучего существа, вы вдруг замечаете, что вокруг полно его сородичей – и они растаскивают уцелевшие припасы.$B$BСейчас эти твари узнают, что такое правосудие по законам Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 хозенов у обломков "Небесной акулы".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29713,'Стандартный протокол','"Небесная акула" полностью разрушена.$b$bКогда рядом силы Альянса, по правилам требуется уничтожить всю секретную технику. Соленоиды определенно подпадают под эту категорию.$B$BИнструкции Орды предельно ясны. Соберите и уничтожьте соленоиды.','Соберите 8 нестабильных соленоидов.','Разместите соленоиды на обломках дирижабля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стандартный протокол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Небесная акула" полностью разрушена.$b$bКогда рядом силы Альянса, по правилам требуется уничтожить всю секретную технику. Соленоиды определенно подпадают под эту категорию.$B$BИнструкции Орды предельно ясны. Соберите и уничтожьте соленоиды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 нестабильных соленоидов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разместите соленоиды на обломках дирижабля',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29714,'Мокрое дело!','Если флот Альянса подойдет к берегу, дым пожарища непременно приведет их прямо к вам и остаткам вашего экипажа.$B$BДолжен быть способ потушить это пламя...$B$BЭта бочка, похоже, уцелела при катастрофе. Возможно, она все еще способна удерживать воду.$B$BЕсть только один способ это выяснить!','Соберите в Озере Поющих Духов 5 водяных гранул и поместите их в бочку Орды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мокрое дело!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если флот Альянса подойдет к берегу, дым пожарища непременно приведет их прямо к вам и остаткам вашего экипажа.$B$BДолжен быть способ потушить это пламя...$B$BЭта бочка, похоже, уцелела при катастрофе. Возможно, она все еще способна удерживать воду.$B$BЕсть только один способ это выяснить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Озере Поющих Духов 5 водяных гранул и поместите их в бочку Орды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29715,'Ведьма в лесу','$R, ты мне поможешь? Ну, пожалуйста!$B$BДеревенские ребятишки убежали играть в лес и не вернулись. Если пойдешь в ту сторону, может, поищешь их?$B$BСто раз сорванцам было сказано, чтобы они оставили в покое вдову, которая живет в лесу. Думаю, они сейчас там. Им кажется, что она ведьма, вот и дразнят ее.','Найдите Ань Воздушный Мех на дороге, к северу от хижины Нефритовой ведьмы.','Найдите Ань Воздушный Мех.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведьма в лесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, ты мне поможешь? Ну, пожалуйста!$B$BДеревенские ребятишки убежали играть в лес и не вернулись. Если пойдешь в ту сторону, может, поищешь их?$B$BСто раз сорванцам было сказано, чтобы они оставили в покое вдову, которая живет в лесу. Думаю, они сейчас там. Им кажется, что она ведьма, вот и дразнят ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ань Воздушный Мех на дороге, к северу от хижины Нефритовой ведьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Ань Воздушный Мех.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29716,'Снова к хозенам','Я знаю, что в лесу живет ведьма, но никто мне не верит. А она превратила моего друга Шина в нефрит!$b$bМы так перепугались, попытались удрать, но она спустила на нас своих ужасных нефритовых чудовищ! Кое-кто из наших от страха залез на дерево.$b$bТы поможешь спасти моих друзей?','Спасите 6 испуганных юных пандаренов.','Поговорите с Ань Воздушный Мех в Цветущей Заре, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова к хозенам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что в лесу живет ведьма, но никто мне не верит. А она превратила моего друга Шина в нефрит!$b$bМы так перепугались, попытались удрать, но она спустила на нас своих ужасных нефритовых чудовищ! Кое-кто из наших от страха залез на дерево.$b$bТы поможешь спасти моих друзей?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 испуганных юных пандаренов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ань Воздушный Мех в Цветущей Заре, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29717,'Лежать, киса!','Я пыталась оказать сопротивление, но тигры очень уж меня испугали. Они могут превратить тебя в нефритовую статую одним лишь взглядом!$B$BЧестное слово! Ни, друг сестры Чэня, слышал это от мамы Кая. $B$BНо я хочу быть такой же храброй, как и ты! Научишь меня побеждать нефритовых тигров?','Уничтожьте 8 нефритовых стражей.','Ух ты! Круто! Ты типа "Бам!", а они типа "А-а!", а потом ты их разнес в клочья!','Поговорите с Ань Воздушный Мех в Сердце Леса или в Цветущей Заре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лежать, киса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пыталась оказать сопротивление, но тигры очень уж меня испугали. Они могут превратить тебя в нефритовую статую одним лишь взглядом!$B$BЧестное слово! Ни, друг сестры Чэня, слышал это от мамы Кая. $B$BНо я хочу быть такой же храброй, как и ты! Научишь меня побеждать нефритовых тигров?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 нефритовых стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Круто! Ты типа "Бам!", а они типа "А-а!", а потом ты их разнес в клочья!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ань Воздушный Мех в Сердце Леса или в Цветущей Заре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29718,'Шестнадцать унций профилактики','Лучше перестраховаться, чем потом жалеть.$B$BДым над местом крушения, несомненно, привлечет сюда войска Альянса, разыскивающие упавший дирижабль.$b$bВаша команда и так уже понесла потери, так что лишние неприятности ей ни к чему.$B$BСамое разумное решение – это потушить горящие обломки.','Возьмите бочку осененной духами воды и потушите четыре очага возгорания рядом с обломками дирижабля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шестнадцать унций профилактики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лучше перестраховаться, чем потом жалеть.$B$BДым над местом крушения, несомненно, привлечет сюда войска Альянса, разыскивающие упавший дирижабль.$b$bВаша команда и так уже понесла потери, так что лишние неприятности ей ни к чему.$B$BСамое разумное решение – это потушить горящие обломки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите бочку осененной духами воды и потушите четыре очага возгорания рядом с обломками дирижабля.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29719,'На спор','Шин так и не вернулся!$B$BНе нужно было мне... ну, то есть другим ребятам... спорить о том, что он не посмеет постучать в дверь ведьмы.$B$BМы все видели, что из ведьминой хижины вышла толпа нефритовых статуй.$B$BА вдруг одна из них – Шин? Ты не $gмог:могла; бы это проверить?','Осмотрите 7 правдоподобных нефритовых статуй к югу от дома Нефритовой ведьмы.','Поговорите с Ань Воздушный Мех.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На спор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шин так и не вернулся!$B$BНе нужно было мне... ну, то есть другим ребятам... спорить о том, что он не посмеет постучать в дверь ведьмы.$B$BМы все видели, что из ведьминой хижины вышла толпа нефритовых статуй.$B$BА вдруг одна из них – Шин? Ты не $gмог:могла; бы это проверить?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите 7 правдоподобных нефритовых статуй к югу от дома Нефритовой ведьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ань Воздушный Мех.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29720,'Нефритовая ведьма','Должно быть, Шин все еще в руках Нефритовой ведьмы.$B$BЯ... Я не могу! Я не хочу ее видеть! Пожалуйста, поговори с ней! Ты же $gвзрослый:взрослая;! Тебя она не станет превращать в нефрит.','Поговорите с вдовой Зеленой Лапой в хижине Нефритовой ведьмы.','Поговорите с вдовой Зеленой Лапой у хижины нефритовой ведьмы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нефритовая ведьма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, Шин все еще в руках Нефритовой ведьмы.$B$BЯ... Я не могу! Я не хочу ее видеть! Пожалуйста, поговори с ней! Ты же $gвзрослый:взрослая;! Тебя она не станет превращать в нефрит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вдовой Зеленой Лапой в хижине Нефритовой ведьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вдовой Зеленой Лапой у хижины нефритовой ведьмы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29721,'Приношение','Ну, дорогуша, сначала выполни мою просьбу, а уж потом я помогу тебе.$B$BЗа домом есть небольшой пруд, а в нем водится редкая рыба, которая нужна мне для ритуала. Ее так любил мой покойный муж!$B$BПожалуйста, принеси мне одну рыбину.','Вдова Зеленая Лапа попросила вас поймать для нее рыбу в пруде, который находится за домом Нефритовой ведьмы в Нефритовом лесу.','Отдайте рыбу вдове Зеленой Лапе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приношение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, дорогуша, сначала выполни мою просьбу, а уж потом я помогу тебе.$B$BЗа домом есть небольшой пруд, а в нем водится редкая рыба, которая нужна мне для ритуала. Ее так любил мой покойный муж!$B$BПожалуйста, принеси мне одну рыбину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вдова Зеленая Лапа попросила вас поймать для нее рыбу в пруде, который находится за домом Нефритовой ведьмы в Нефритовом лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте рыбу вдове Зеленой Лапе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29722,'Урок мужества','Научишь меня, как стать таким же храбрым, как ты?$B$BМы решили подшутить над ведьмой и, похоже, разозлили лиственных плутов. Кажется, ведьма что-то с ними сделала.$B$BПокажешь мне, как их побеждать?','Победите 8 лиственных плутов к югу от дома Нефритовой ведьмы.','Поговорите с Ань Воздушный Мех.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок мужества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Научишь меня, как стать таким же храбрым, как ты?$B$BМы решили подшутить над ведьмой и, похоже, разозлили лиственных плутов. Кажется, ведьма что-то с ними сделала.$B$BПокажешь мне, как их побеждать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 8 лиственных плутов к югу от дома Нефритовой ведьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ань Воздушный Мех.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29723,'Нефритовая ведьма','Должно быть, Шин все еще в руках Нефритовой ведьмы.$B$BЯ... Я не могу! Я не хочу ее видеть! Пожалуйста, поговори с ней! Ты же $gвзрослый:взрослая;! Тебя она не станет превращать в нефрит.','Победите Нефритовую ведьму.','Поговорите с Ань Воздушный Мех в Цветущей Заре, что в Нефритовом лесу.','Местные называют ее Нефритовой ведьмой – из-за словно живых нефритовых статуй во дворе ее дома.','Вдова Зеленая Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нефритовая ведьма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, Шин все еще в руках Нефритовой ведьмы.$B$BЯ... Я не могу! Я не хочу ее видеть! Пожалуйста, поговори с ней! Ты же $gвзрослый:взрослая;! Тебя она не станет превращать в нефрит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Нефритовую ведьму.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ань Воздушный Мех в Цветущей Заре, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Местные называют ее Нефритовой ведьмой – из-за словно живых нефритовых статуй во дворе ее дома.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вдова Зеленая Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29724,'Похороны в открытом море','Эти дикари... безжалостны.$b$bОни оттащили наших истекающих кровью солдат в свои лагеря, чтобы подвергнуть пыткам. Наши храбрые братья не должны так умирать.$b$bЯ скоро присоединюсь к ним, |3-6($c). Подари мир моей душе и позволь их телам обрести покой.$b$bНайди их останки в лагерях, окружающих место крушения. Вырви их из лап этих тварей.','Отнесите тела 3 передовых бойцов к неподвижной катапульте у обломков "Небесной акулы".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похороны в открытом море',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти дикари... безжалостны.$b$bОни оттащили наших истекающих кровью солдат в свои лагеря, чтобы подвергнуть пыткам. Наши храбрые братья не должны так умирать.$b$bЯ скоро присоединюсь к ним, |3-6($c). Подари мир моей душе и позволь их телам обрести покой.$b$bНайди их останки в лагерях, окружающих место крушения. Вырви их из лап этих тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тела 3 передовых бойцов к неподвижной катапульте у обломков "Небесной акулы".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29725,'Отчет ШРУ: небесный огонь','Да, Эмбер мы нашли, она жива и с ней все в порядке. На этом хорошие новости заканчиваются.$B$BПосмотрим, удастся ли мне продолжить историю старины Релла...','Выслушайте доклад Салли.','Ну вот, теперь ты знаешь, почему старина Релл в таком виде.$B$B<На миг Салли меняется в лице и быстро отворачивается. Он... плачет?>','Поговорите с Салли "Рассольным" Маклири в Деревне Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет ШРУ: небесный огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, Эмбер мы нашли, она жива и с ней все в порядке. На этом хорошие новости заканчиваются.$B$BПосмотрим, удастся ли мне продолжить историю старины Релла...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад Салли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, теперь ты знаешь, почему старина Релл в таком виде.$B$B<На миг Салли меняется в лице и быстро отворачивается. Он... плачет?>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Салли "Рассольным" Маклири в Деревне Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29726,'Отчет ШРУ: враждебные аборигены','Я... я могу рассказать, что было потом! Мы пошли дальше на север, в лес...','Выслушайте отчет Малыша Лу.','К счастью, мы все выжили.$B$BНу, то есть... все, за исключением Стельки...','Вернитесь к Малышу Лу в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет ШРУ: враждебные аборигены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я... я могу рассказать, что было потом! Мы пошли дальше на север, в лес...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте отчет Малыша Лу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','К счастью, мы все выжили.$B$BНу, то есть... все, за исключением Стельки...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малышу Лу в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29727,'Отчет ШРУ: пленных не брать','В конце пути мы свернули на запад и пошли к большой деревне хозенов. Мы разбили лагерь в горах, в укромном месте...','Что ж, ничего не поделаешь. Белую Пешку мы не нашли, но добыли невероятно важные сведения для Альянса.$B$BОрда заключила союз с хозенами и уже вооружает их. Вместе с обезьяньим войском у них в тридцать раз больше бойцов, чем у нас.','Вернитесь к Эмбер Кеарнен в Деревню Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет ШРУ: пленных не брать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В конце пути мы свернули на запад и пошли к большой деревне хозенов. Мы разбили лагерь в горах, в укромном месте...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ничего не поделаешь. Белую Пешку мы не нашли, но добыли невероятно важные сведения для Альянса.$B$BОрда заключила союз с хозенами и уже вооружает их. Вместе с обезьяньим войском у них в тридцать раз больше бойцов, чем у нас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эмбер Кеарнен в Деревню Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29728,'Взрывные работы','$n, я должен попросить тебя еще об одном одолжении.$B$BОставлять королевские вещи на корабле нельзя – их необходимо уничтожить.$B$BИз собранных тобой обломков я изготовил самодельный динамит.$B$BПодложи его на корабль, но не клади заряды слишком близко.$B$BОни... не очень... стабильны... так что нужно разместить их подальше друг от друга – на случай, если один из них взорвется раньше времени.','Разместите 4 заряда самодельного динамита рядом с затонувшим кораблем на Сапфировом берегу. Расстояние между зарядами должно составлять не менее 10 метров.','Вернитесь к Узлику Шифролому на Сапфировый берег в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывные работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я должен попросить тебя еще об одном одолжении.$B$BОставлять королевские вещи на корабле нельзя – их необходимо уничтожить.$B$BИз собранных тобой обломков я изготовил самодельный динамит.$B$BПодложи его на корабль, но не клади заряды слишком близко.$B$BОни... не очень... стабильны... так что нужно разместить их подальше друг от друга – на случай, если один из них взорвется раньше времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разместите 4 заряда самодельного динамита рядом с затонувшим кораблем на Сапфировом берегу. Расстояние между зарядами должно составлять не менее 10 метров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узлику Шифролому на Сапфировый берег в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29729,'Без следа','Взрывчатка заложена. Осталось лишь активировать детонатор.','Активируйте детонатор, чтобы уничтожить все улики.','Вернитесь к Узлику Шифролому на Сапфировый берег в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без следа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взрывчатка заложена. Осталось лишь активировать детонатор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте детонатор, чтобы уничтожить все улики.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Узлику Шифролому на Сапфировый берег в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29730,'Ты хотеть спросить: "Какой бортель стать с сержантом Горроком?" Не переживай, он совсем жив. Не мертв или как-то так.$B$B<Рико переминается с ноги на ногу.>$B$BНу, мы думай, что он жив, но еще он немножко мертв.$B$B<Рико заглядывает вам в глаза, ища в них одобрения.>$B$BХорошо! Я сказать вся правда.','Выслушайте доклад Рико.','Так, ты видеть, что Рико тут не при чем.','Вернитесь к Рико на холм Грукин в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хотеть спросить: "Какой бортель стать с сержантом Горроком?" Не переживай, он совсем жив. Не мертв или как-то так.$B$B<Рико переминается с ноги на ногу.>$B$BНу, мы думай, что он жив, но еще он немножко мертв.$B$B<Рико заглядывает вам в глаза, ища в них одобрения.>$B$BХорошо! Я сказать вся правда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад Рико.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, ты видеть, что Рико тут не при чем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рико на холм Грукин в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29731,'Большая часть из того, что сказал Рико, – правда.$B$BМы не посмели преследовать Горрока – воинов Орды здесь мало. Рисковать нам нельзя – и если честно, мы даже не знаем, какой силой обладает эта ведьма.$B$BЯ продолжу с того места, на котором остановился хозен...','Выслушайте доклад Кирин.','Вот так мы и нашли нашего пленника.$B$BНо это еще не все. Далеко не все...','Вернитесь к темному мастеру Кирин на холм Грукин, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть из того, что сказал Рико, – правда.$B$BМы не посмели преследовать Горрока – воинов Орды здесь мало. Рисковать нам нельзя – и если честно, мы даже не знаем, какой силой обладает эта ведьма.$B$BЯ продолжу с того места, на котором остановился хозен...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад Кирин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так мы и нашли нашего пленника.$B$BНо это еще не все. Далеко не все...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин на холм Грукин, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29732,'Что упало, то не пропало','Риветт оставил какую-то важную машину. На ее ручке вы смогли разобрать слова: "Гоблинский автотранспортер".$B$BЕсли это устройство немного откалибровать, оно сможет доставить роботов в главный лагерь Назгрима.$b$bЭто просто...$B$BНо есть одна сложность.$B$BВо время аварии ящики с припасами оказались на уступе, ниже места падения.$B$BРазмышляя над тем, как их достать, краем глаза вы замечаете длинный свернутый кольцами хвост пролетающего мимо горного летуна...','Добудьте припасы с помощью гоблинского автотранспортера рядом с Обнажившимся корнем.$B$BПримечание: для каждого использования необходим один закрученный хвост горного летуна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что упало, то не пропало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Риветт оставил какую-то важную машину. На ее ручке вы смогли разобрать слова: "Гоблинский автотранспортер".$B$BЕсли это устройство немного откалибровать, оно сможет доставить роботов в главный лагерь Назгрима.$b$bЭто просто...$B$BНо есть одна сложность.$B$BВо время аварии ящики с припасами оказались на уступе, ниже места падения.$B$BРазмышляя над тем, как их достать, краем глаза вы замечаете длинный свернутый кольцами хвост пролетающего мимо горного летуна...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте припасы с помощью гоблинского автотранспортера рядом с Обнажившимся корнем.$B$BПримечание: для каждого использования необходим один закрученный хвост горного летуна.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29733,'Отчет ШРУ: заблудившиеся в лесу','<Справившись с приступом кашля, Релл говорит.>$B$BПожалуйста, $n, ты $gдолжен:должна; узнать, что мы пережили.$B$BПроклятье, да об этом должен узнать весь Альянс. Возможно, у нас осталось совсем мало времени.','Выслушайте доклад Релла.','...и вот <кхе-кхе>как мы нашли...$B$B<Речь Релла обрывается приступом кашля. Из уголка его рта течет струйка крови.>','Поговорите с Реллом Ночным Ветром в Деревне Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет ШРУ: заблудившиеся в лесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Справившись с приступом кашля, Релл говорит.>$B$BПожалуйста, $n, ты $gдолжен:должна; узнать, что мы пережили.$B$BПроклятье, да об этом должен узнать весь Альянс. Возможно, у нас осталось совсем мало времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад Релла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','...и вот <кхе-кхе>как мы нашли...$B$B<Речь Релла обрывается приступом кашля. Из уголка его рта течет струйка крови.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Реллом Ночным Ветром в Деревне Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
