INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29741,'Когда-то все тол\'виры были подобны мне. Ныне же мой народ обрел плоть и кровь – и нуждается в мудрости столетий более, чем когда-либо.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда-то все тол\'виры были подобны мне. Ныне же мой народ обрел плоть и кровь – и нуждается в мудрости столетий более, чем когда-либо.',`offerrewardtext_loc8`);
