INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntargetname_loc8`) VALUES (29743,'Чудовище','Сразу ясно, что эта статуя и окружающие ее руины – очень древние. Очевидно, что этот край возник совсем не по причине недавнего катаклизма, у него своя богатая история.$B$BМоряки ходят здесь уже очень давно, однако никто и никогда не сообщал о том, что здесь есть земля.$B$BВозможно, вам удастся пролить свет на эту тайну, если вы сделаете наброски частей этой древней статуи.','Сделайте наброски всех частей древней статуи.','Древняя статуя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудовище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сразу ясно, что эта статуя и окружающие ее руины – очень древние. Очевидно, что этот край возник совсем не по причине недавнего катаклизма, у него своя богатая история.$B$BМоряки ходят здесь уже очень давно, однако никто и никогда не сообщал о том, что здесь есть земля.$B$BВозможно, вам удастся пролить свет на эту тайну, если вы сделаете наброски частей этой древней статуи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сделайте наброски всех частей древней статуи.',`objectives_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Древняя статуя',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29744,'Ай да натуралист!','Лесные духи редко удаляются от родных мест, и удивительно, что кто-то из них добрался аж до поселка каменщиков. Должно быть, что-то вытеснило их из привычной среды обитания.$B$BДухи, о которых я говорю, родом из лесов Потерянных, что к северу отсюда. Я бы сам отправился туда, но, говорят, там водятся призраки.$B$BТак что мне туда дороги нет.$B$B<Вэн кашляет.>$B$BИли... Туда ведь может отправиться большой и храбрый искатель приключений вроде тебя! Что скажешь?','Осмотрите леса Потерянных, которые находятся к северо-востоку от каменоломни Зеленой Скалы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ай да натуралист!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесные духи редко удаляются от родных мест, и удивительно, что кто-то из них добрался аж до поселка каменщиков. Должно быть, что-то вытеснило их из привычной среды обитания.$B$BДухи, о которых я говорю, родом из лесов Потерянных, что к северу отсюда. Я бы сам отправился туда, но, говорят, там водятся призраки.$B$BТак что мне туда дороги нет.$B$B<Вэн кашляет.>$B$BИли... Туда ведь может отправиться большой и храбрый искатель приключений вроде тебя! Что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите леса Потерянных, которые находятся к северо-востоку от каменоломни Зеленой Скалы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29745,'Духи в беде','<В лесу буйствуют ожившие статуи.>$B$B<Пока они довольствуются тем, что раскалывают лесных духов в щепки, но если так пойдет и дальше, то у пандаренов возникнут неприятности похуже нехватки нефрита.>','Уничтожьте 10 каменных разрушителей в Лесах Потерянных и узнайте, откуда они взялись.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи в беде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В лесу буйствуют ожившие статуи.>$B$B<Пока они довольствуются тем, что раскалывают лесных духов в щепки, но если так пойдет и дальше, то у пандаренов возникнут неприятности похуже нехватки нефрита.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 каменных разрушителей в Лесах Потерянных и узнайте, откуда они взялись.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29746,'Вперед, к развалинам','Какая-то неведомая сила уносит освобожденные души к развалинам на побережье.$B$BПохоже, что и там они не сумеют обрести покой...','Идите в руины Гань Ши, которые находятся к северо-западу от [JADE MINES].') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, к развалинам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какая-то неведомая сила уносит освобожденные души к развалинам на побережье.$B$BПохоже, что и там они не сумеют обрести покой...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в руины Гань Ши, которые находятся к северо-западу от [JADE MINES].',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29747,'Противодействие','<Чародеи могу вызывают из загробного мира несчастных духов и заключают их в статуи.>$B$B<Похоже, одного разрушения статуй недостаточно, чтобы нарушить этот процесс.>','Уничтожьте 8 укротителей духов Шань\'цзэ на Террасе Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противодействие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Чародеи могу вызывают из загробного мира несчастных духов и заключают их в статуи.>$B$B<Похоже, одного разрушения статуй недостаточно, чтобы нарушить этот процесс.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 укротителей духов Шань\'цзэ на Террасе Десяти Громов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29748,'Пни симулякр!','<Осколки древней статуи могу. Судя по всему, ее так и не оживили.>$B$B<Похоже, черная магия могу делает хрупкие статуи прочнее. Их все стоит уничтожить прямо сейчас, не дожидаясь оживления.>$B$B<Хорошего пинка должно быть достаточно.>','Опрокиньте 6 пустующих разрушителей на Террасе Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пни симулякр!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Осколки древней статуи могу. Судя по всему, ее так и не оживили.>$B$B<Похоже, черная магия могу делает хрупкие статуи прочнее. Их все стоит уничтожить прямо сейчас, не дожидаясь оживления.>$B$B<Хорошего пинка должно быть достаточно.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опрокиньте 6 пустующих разрушителей на Террасе Десяти Громов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29749,'Настойчивая просьба','<Вас приводит в ужас какой-то вой. Следом за ним, словно издалека, доносится чей-то едва слышный голос.>$B$BПожалуйста... помоги... в самом сердце руин... ритуал... магия...$B$B...этого быть не должно...$B$BМой посох... на алтаре... воспользуйся им. Пожалуйста, торопись.','Найдите посох Пэй-Чжи и помешайте могу провести ритуал в центре Террасы Десяти Громов.','Позволь представиться: я – Пэй-Чжи, главный заклинатель духов при дворе последнего императора пандаренов Шаохао.$B$BПо крайней мере... я им был.','Пленение духов! Как же мы дошли до того, что могу занимаются таким мерзким делом? И вот, пожалуйста – я стал частью скверного магического конструкта...$B$B<Немного покипятившись, дух обращается к вам.>$B$BКакой нынче век?','Возьми мой посох с алтаря и заряди его при помощи древних духов!','Пэй-Чжи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настойчивая просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вас приводит в ужас какой-то вой. Следом за ним, словно издалека, доносится чей-то едва слышный голос.>$B$BПожалуйста... помоги... в самом сердце руин... ритуал... магия...$B$B...этого быть не должно...$B$BМой посох... на алтаре... воспользуйся им. Пожалуйста, торопись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите посох Пэй-Чжи и помешайте могу провести ритуал в центре Террасы Десяти Громов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Позволь представиться: я – Пэй-Чжи, главный заклинатель духов при дворе последнего императора пандаренов Шаохао.$B$BПо крайней мере... я им был.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пленение духов! Как же мы дошли до того, что могу занимаются таким мерзким делом? И вот, пожалуйста – я стал частью скверного магического конструкта...$B$B<Немного покипятившись, дух обращается к вам.>$B$BКакой нынче век?',`requestitemstext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Возьми мой посох с алтаря и заряди его при помощи древних духов!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пэй-Чжи',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29750,'Вместилище духа','Кромсатели духов – секта жрецов-ассасинов; в дни расцвета империи могу они были элитными войсками императора.$B$BКаждый из них владеет смертельным ударом, которым ассасин подчиняет себе душу убитого и помещает в нефритовый сосуд, чтобы потом доставить укротителю духов.$B$BЕсли в руинах встретишь кромсателя, помни: проклятые сосуды висят у них на поясе.$B$BОсвободи их от этой ноши и принеси сосуды мне.','Соберите 8 сосудов духов, уничтожая кромсателей духов Шань\'цзэ на Террасе Десяти Громов.','Подумать только, все эти годы могу тренировали кромсателей...$B$BТебе удалось найти сосуды?','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вместилище духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кромсатели духов – секта жрецов-ассасинов; в дни расцвета империи могу они были элитными войсками императора.$B$BКаждый из них владеет смертельным ударом, которым ассасин подчиняет себе душу убитого и помещает в нефритовый сосуд, чтобы потом доставить укротителю духов.$B$BЕсли в руинах встретишь кромсателя, помни: проклятые сосуды висят у них на поясе.$B$BОсвободи их от этой ноши и принеси сосуды мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 сосудов духов, уничтожая кромсателей духов Шань\'цзэ на Террасе Десяти Громов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Подумать только, все эти годы могу тренировали кромсателей...$B$BТебе удалось найти сосуды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29751,'Артефакты для ритуала','Здесь столько плененных духов... Они повсюду, я их чувствую. Здесь даже стены – ловушка для умерших.$B$B$n, мы не можем просто разрушить эту магию – так мы лишь выпустим на свободу бесчисленное множество измученных душ. Им нужен маяк – то, что их направит.$B$BС твоей помощью я надеюсь возвести Тань-Чао – мост из этого мира на небеса. Для этого ритуала мне понадобится чаша, свеча и нефритовый цун. Все это можно найти в развалинах.','Принесите Пэй-Чжи надколотую ритуальную чашу, остроконечную ритуальную свечу и нефритовый цун c Террасы Десяти Громов.','Отличная работа. Теперь я смогу провести ритуал и отправить эти души – и себя заодно – туда, где они должны быть.','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Артефакты для ритуала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь столько плененных духов... Они повсюду, я их чувствую. Здесь даже стены – ловушка для умерших.$B$B$n, мы не можем просто разрушить эту магию – так мы лишь выпустим на свободу бесчисленное множество измученных душ. Им нужен маяк – то, что их направит.$B$BС твоей помощью я надеюсь возвести Тань-Чао – мост из этого мира на небеса. Для этого ритуала мне понадобится чаша, свеча и нефритовый цун. Все это можно найти в развалинах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Пэй-Чжи надколотую ритуальную чашу, остроконечную ритуальную свечу и нефритовый цун c Террасы Десяти Громов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Теперь я смогу провести ритуал и отправить эти души – и себя заодно – туда, где они должны быть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29752,'Заблудшие души','Массовый призыв духов, которым занимаются могу, сопровождается определенными побочными эффектами. Некоторые из этих духов помутились рассудком, другие слишком своевольны, чтобы ими можно было управлять. Их лишают свободы и оставляют скитаться до тех пор, пока они не станут посговорчивее.$B$BПодозреваю, что могу где-то создали особое место для удержания духов, которое, по-видимому, охраняют кромсатели духов.$B$BВозьми снова мой посох и воспользуйся им для сбора обнаруженных духов. Не пытайся их одолеть, просто плени их с помощью посоха.','Поймайте 10 своенравных предков на Террасе Десяти Громов с помощью посоха Пэй-Чжи.','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблудшие души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Массовый призыв духов, которым занимаются могу, сопровождается определенными побочными эффектами. Некоторые из этих духов помутились рассудком, другие слишком своевольны, чтобы ими можно было управлять. Их лишают свободы и оставляют скитаться до тех пор, пока они не станут посговорчивее.$B$BПодозреваю, что могу где-то создали особое место для удержания духов, которое, по-видимому, охраняют кромсатели духов.$B$BВозьми снова мой посох и воспользуйся им для сбора обнаруженных духов. Не пытайся их одолеть, просто плени их с помощью посоха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 своенравных предков на Террасе Десяти Громов с помощью посоха Пэй-Чжи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29753,'Назад, к природе','$n, боюсь, мне придется попросить тебя еще об одной услуге.$B$BОказалось, что в собранных тобой сосудах находятся не духи предков могу или убитых врагов, а духи животных. Похоже, кромсатели прибегают к браконьерству, чтобы вдохнуть жизнь в свои симулякры.$B$BЭто усложняет нашу задачу – ведь я не могу провести с собой зверей по мосту.$B$BОтнеси сосуды на запад, в Чащу Приливов, и разбей, чтобы духи могли слиться с природой. Возможно, некоторые из них будут ослеплены гневом, так что их придется усмирить.','Освободите 8 духов животных, бросая на землю сосуды духов в Чаще Приливов.','Их тела давным-давно вернулись в землю – теперь за ними могут последовать и души.','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад, к природе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, боюсь, мне придется попросить тебя еще об одной услуге.$B$BОказалось, что в собранных тобой сосудах находятся не духи предков могу или убитых врагов, а духи животных. Похоже, кромсатели прибегают к браконьерству, чтобы вдохнуть жизнь в свои симулякры.$B$BЭто усложняет нашу задачу – ведь я не могу провести с собой зверей по мосту.$B$BОтнеси сосуды на запад, в Чащу Приливов, и разбей, чтобы духи могли слиться с природой. Возможно, некоторые из них будут ослеплены гневом, так что их придется усмирить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 духов животных, бросая на землю сосуды духов в Чаще Приливов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Их тела давным-давно вернулись в землю – теперь за ними могут последовать и души.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29754,'Мост между небом и землей','Мы готовы открыть Тань-Чао и проводить всех этих духов туда, где они обретут покой.$B$BЯ хочу снова попросить тебя о помощи. Могу, несомненно, почувствуют проведение ритуала и сделают все, что в их силах, чтобы ему помешать. На возведение моста потребуется всего лишь несколько минут, а потом поток настолько усилится, что остановить его будет невозможно.$B$BЕсли ты $gготов:готова; помочь, проводи меня к месту проведения ритуала.','Защищайте Пэй-Чжи во время проведения ритуала на Террасе Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мост между небом и землей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы готовы открыть Тань-Чао и проводить всех этих духов туда, где они обретут покой.$B$BЯ хочу снова попросить тебя о помощи. Могу, несомненно, почувствуют проведение ритуала и сделают все, что в их силах, чтобы ему помешать. На возведение моста потребуется всего лишь несколько минут, а потом поток настолько усилится, что остановить его будет невозможно.$B$BЕсли ты $gготов:готова; помочь, проводи меня к месту проведения ритуала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте Пэй-Чжи во время проведения ритуала на Террасе Десяти Громов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29755,'Расплата','<Духи предков устремляются по построенному Пэй-Чжи мосту Тань-Чао навстречу свободе.>$B$B<В руинах к северу от Тань-Чао остался еще один, последний чертог. Воздух потрескивает от разрядов магической энергии. Шань Цзитун уже взялся за дело.>','Сразитесь с Шань Цзитуном и спасите Пэй-Чжи у трона Пробудителя Духов на Террасе Десяти Громов.','Великая смута рождает великих героев. Таких, как ты. Могу лишь догадываться, какие подвиги ждут тебя впереди.$B$BПознакомиться с тобой – великая честь для меня.$B$BЯ останусь здесь, пока не провожу последнего из духов, а затем уйду по мосту Тань-Чао сам.$B$BИ все-таки меня тревожит предсмертное проклятие того, кто пробуждал духов...$B$B"Вы не остановите гром".$B$BЧто это может означать?','Поговорите с Пэй-Чжи у моста Тань-Чао на Террасе Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Духи предков устремляются по построенному Пэй-Чжи мосту Тань-Чао навстречу свободе.>$B$B<В руинах к северу от Тань-Чао остался еще один, последний чертог. Воздух потрескивает от разрядов магической энергии. Шань Цзитун уже взялся за дело.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с Шань Цзитуном и спасите Пэй-Чжи у трона Пробудителя Духов на Террасе Десяти Громов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великая смута рождает великих героев. Таких, как ты. Могу лишь догадываться, какие подвиги ждут тебя впереди.$B$BПознакомиться с тобой – великая честь для меня.$B$BЯ останусь здесь, пока не провожу последнего из духов, а затем уйду по мосту Тань-Чао сам.$B$BИ все-таки меня тревожит предсмертное проклятие того, кто пробуждал духов...$B$B"Вы не остановите гром".$B$BЧто это может означать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Пэй-Чжи у моста Тань-Чао на Террасе Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29756,'Скромное подношение','Почти все готово к проведению ритуала, нам нужна лишь только одна вещь – подношение. $B$BРасслабься, я не имел в виду жертву, а просто немного пищи.$B$BНам подойдут грибы, которые растут на северо-западе, в Чаще Приливов. Пожалуйста, принеси немного.','Соберите 10 грибов Приливных Туманов в Чаще Приливов.','Даже мертвым известны муки голода.','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромное подношение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Почти все готово к проведению ритуала, нам нужна лишь только одна вещь – подношение. $B$BРасслабься, я не имел в виду жертву, а просто немного пищи.$B$BНам подойдут грибы, которые растут на северо-западе, в Чаще Приливов. Пожалуйста, принеси немного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 грибов Приливных Туманов в Чаще Приливов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже мертвым известны муки голода.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пэй-Чжи на Террасу Десяти Громов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29757,'"Бутылкожабик"','Ты $gслышал:слышала; про то, что случилось в пруду?$B$BТам натуральное нашествие жаб! Они размножаются, как кролики! Фермеры, выращивающие лотос, в ужасе.$B$BА я, кстати, делаю замечательный джем из икры этих жаб – и дети его обожают, раскупают все подчистую.$B$BЕсли пойдешь в сторону пруда, то окажешь всем большую услугу, набрав немного жабьей икры.$B$BВот в эту бутылку. Для меня.$B$BЕсли увидишь пузырьки, сразу черпай!','Соберите икру 8 бурчащих жаб на верхнем уровне Пруда Чистоты.','И если теперь дети спросят: "Бутылкожабик есть?", я отвечу: "Да!"','Вернитесь к Яню в Новую Циферу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Бутылкожабик"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gслышал:слышала; про то, что случилось в пруду?$B$BТам натуральное нашествие жаб! Они размножаются, как кролики! Фермеры, выращивающие лотос, в ужасе.$B$BА я, кстати, делаю замечательный джем из икры этих жаб – и дети его обожают, раскупают все подчистую.$B$BЕсли пойдешь в сторону пруда, то окажешь всем большую услугу, набрав немного жабьей икры.$B$BВот в эту бутылку. Для меня.$B$BЕсли увидишь пузырьки, сразу черпай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите икру 8 бурчащих жаб на верхнем уровне Пруда Чистоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И если теперь дети спросят: "Бутылкожабик есть?", я отвечу: "Да!"',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яню в Новую Циферу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29758,'За надежной спиной','<Толстый панцирь этой драконьей черепахи прочен как камень и усеян острыми шипами. Наверняка он для чего-нибудь сгодится местным жителям.>','Отнесите панцирь Кроша Яню в Новую Циферу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За надежной спиной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Толстый панцирь этой драконьей черепахи прочен как камень и усеян острыми шипами. Наверняка он для чего-нибудь сгодится местным жителям.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите панцирь Кроша Яню в Новую Циферу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29759,'Кун-Динь','Надеюсь, ты сможешь выполнить следующее задание – ведь от этого зависят наши жизни.$B$BЗамки на наших оковах отпирает только один ключ – и, к несчастью, он висит на шее Кун-Диня, ручного тигра хозенов.$B$BТигра держат в большой яме к востоку отсюда. Единственный способ добыть ключ – это убить зверя.','Добудьте ключ племени Ловкого Хвоста, убив Кун-Диня.','Да, с этим ключом я смогу снять наши цепи.$B$BТы освободил нас из этого гнусного места.','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.','Огромный зверь охраняет ключ.','Кун-Динь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кун-Динь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, ты сможешь выполнить следующее задание – ведь от этого зависят наши жизни.$B$BЗамки на наших оковах отпирает только один ключ – и, к несчастью, он висит на шее Кун-Диня, ручного тигра хозенов.$B$BТигра держат в большой яме к востоку отсюда. Единственный способ добыть ключ – это убить зверя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ племени Ловкого Хвоста, убив Кун-Диня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, с этим ключом я смогу снять наши цепи.$B$BТы освободил нас из этого гнусного места.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в Ямы Ловкого Хвоста, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Огромный зверь охраняет ключ.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кун-Динь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29760,'Боец арены','Должно быть, стать хорошим бойцом арены не так просто...$B$BБыть может, Коргол Череподроб, который организует схватки Новолуния, знает, в чем тут штука!','Поговорите с Корголом Череподробом на арене ярмарки Новолуния.','Поговорите с Корголом Череподробом на арене ярмарки Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боец арены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, стать хорошим бойцом арены не так просто...$B$BБыть может, Коргол Череподроб, который организует схватки Новолуния, знает, в чем тут штука!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Корголом Череподробом на арене ярмарки Новолуния.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Корголом Череподробом на арене ярмарки Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29761,'Мастер-боец арены','Вернитесь к Корголу Череподробу на ярмарку Новолуния.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер-боец арены',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корголу Череподробу на ярмарку Новолуния.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29762,'Семейные реликвии','Недавно мы потерпели поражение в схватке с хозенами у Приюта Лунной Воды.$B$BМы увели оттуда всех, кого могли, однако многих не удалось спасти. Сейчас у нас даже нет реликвий, которые помогли бы нам молиться за погибших.$B$BЕсли бы кто-то вернул нам реликвии, принадлежавшие умершим, то мы бы похоронили их надлежащим образом и нашли в себе силы жить дальше.$B$B$n, ты окажешь нам огромную услугу, если их достанешь.','Соберите 8 реликвий Жемчужного Плавника у мертвых жителей деревни Жемчужного Плавника в Приюте Лунной Воды.','Спасибо, Лайрим. Ты даже не представляешь, как много эти вещи значат для семей погибших.','Мы все еще скорбим по нашим погибшим братьям.','Вернитесь к Здоровяку Кажаши в деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семейные реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно мы потерпели поражение в схватке с хозенами у Приюта Лунной Воды.$B$BМы увели оттуда всех, кого могли, однако многих не удалось спасти. Сейчас у нас даже нет реликвий, которые помогли бы нам молиться за погибших.$B$BЕсли бы кто-то вернул нам реликвии, принадлежавшие умершим, то мы бы похоронили их надлежащим образом и нашли в себе силы жить дальше.$B$B$n, ты окажешь нам огромную услугу, если их достанешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 реликвий Жемчужного Плавника у мертвых жителей деревни Жемчужного Плавника в Приюте Лунной Воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Лайрим. Ты даже не представляешь, как много эти вещи значат для семей погибших.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы все еще скорбим по нашим погибшим братьям.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29763,'Кража вражьего грома','Врайкулы не знают страха в битве. Иногда кажется, что они жаждут погибнуть в сражении. Учитывая их свирепость и их численность – мы обречены. Вот так-то.$b$bЕсть, правда, среди них один врайкул, которого они шибко уважают. Зовут его Ингвар. Убей его, и тогда их боевой дух упадет ниже плинтуса.','Защитник Мордун попросил вас принести ему голову Ингвара Расхитителя.','Потрясающе!$B$BПохоже, впервые за последнее время удача все же повернулась к нам лицом.','Вернитесь к защитнику Мордуну в Крепость Утгард.','Ингвар Расхититель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кража вражьего грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врайкулы не знают страха в битве. Иногда кажется, что они жаждут погибнуть в сражении. Учитывая их свирепость и их численность – мы обречены. Вот так-то.$b$bЕсть, правда, среди них один врайкул, которого они шибко уважают. Зовут его Ингвар. Убей его, и тогда их боевой дух упадет ниже плинтуса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитник Мордун попросил вас принести ему голову Ингвара Расхитителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе!$B$BПохоже, впервые за последнее время удача все же повернулась к нам лицом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к защитнику Мордуну в Крепость Утгард.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ингвар Расхититель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29764,'Разоружение','Поверь мне на слово, $gдружище:подруга;: с врайкульскими топорами лучше близко не знакомиться!$b$bУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.$b$bДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.$b$bВ любом случае – чем меньше у них топоров, тем лучше для нас.','*Мордун присвистывает.*$B$BНу ты только взгляни на них? Невероятно.$B$BЯ-то надеялся, что эти первобытные варвары дерутся дубинами да швыряются булыжниками.$B$BВот невезение...','Ну что, ты несешь мне врайкульские топоры?','Вернитесь к защитнику Мордуну в Крепость Утгард.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разоружение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверь мне на слово, $gдружище:подруга;: с врайкульскими топорами лучше близко не знакомиться!$b$bУ меня самого есть парочка шрамов от их клинков – отлично сбалансированных, чудовищно острых и совершенно смертоносных.$b$bДавай-ка, проникни в их крепость и стащи кое-что из врайкульского арсенала. Может быть, нам удастся разобраться, как они куют такое оружие. А может быть, и нет.$b$bВ любом случае – чем меньше у них топоров, тем лучше для нас.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Мордун присвистывает.*$B$BНу ты только взгляни на них? Невероятно.$B$BЯ-то надеялся, что эти первобытные варвары дерутся дубинами да швыряются булыжниками.$B$BВот невезение...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты несешь мне врайкульские топоры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к защитнику Мордуну в Крепость Утгард.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29765,'Все глаза выплакал','Я бы и сам с ними справился.$B$BУбивал бы их одного за другим, а если бы они подобрались слишком близко, притворился бы мертвым. Этот трюк срабатывает каждый раз... ну, почти каждый раз...$B$BОдин из них меня раскусил – и не успел я опомниться, как они уже играли моими глазами, словно шариками.$B$BДикари! Ограбили меня и бросили на верную смерть...$B$BПомоги мне. Дай мне возможность умереть достойно.','Отберите принадлежающие Зин\'Джуну вещи у хозенов-задир.$B$BЕсли Зин\'Джун отстанет от вас, поговорите с ним на возвышенности Кружащихся Ветров.','<Зин\'Джун рыдает... по крайней мере вам так кажется.>$B$BОни порешили Нюхача...$B$BЧто им сделал старый добрый Нюхач?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все глаза выплакал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы и сам с ними справился.$B$BУбивал бы их одного за другим, а если бы они подобрались слишком близко, притворился бы мертвым. Этот трюк срабатывает каждый раз... ну, почти каждый раз...$B$BОдин из них меня раскусил – и не успел я опомниться, как они уже играли моими глазами, словно шариками.$B$BДикари! Ограбили меня и бросили на верную смерть...$B$BПомоги мне. Дай мне возможность умереть достойно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите принадлежающие Зин\'Джуну вещи у хозенов-задир.$B$BЕсли Зин\'Джун отстанет от вас, поговорите с ним на возвышенности Кружащихся Ветров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Зин\'Джун рыдает... по крайней мере вам так кажется.>$B$BОни порешили Нюхача...$B$BЧто им сделал старый добрый Нюхач?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29766,'Хорошее начало','Несмотря на затруднительное положение, в котором мы оказались, все приказы остаются в силе. Нам нужно произвести разведку местности и подготовить все для прихода флота Адского Крика.$B$BНо сначала надо бы разобраться с этими дикарями!$B$BВидишь трупы, которые я сложил вокруг лагеря? Я хочу, чтобы здесь их были горы!$B$BМы – Орда!$B$BЭти крысы еще не знают, что нас нужно бояться, но скоро мы это исправим...','Уничтожьте 4 хозенов-землеметов, 4 хозенов-хулиганов и 3 хозенов-рыболовов.','Поговорите с генералом Назгримом в Надежде Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хорошее начало',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на затруднительное положение, в котором мы оказались, все приказы остаются в силе. Нам нужно произвести разведку местности и подготовить все для прихода флота Адского Крика.$B$BНо сначала надо бы разобраться с этими дикарями!$B$BВидишь трупы, которые я сложил вокруг лагеря? Я хочу, чтобы здесь их были горы!$B$BМы – Орда!$B$BЭти крысы еще не знают, что нас нужно бояться, но скоро мы это исправим...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 4 хозенов-землеметов, 4 хозенов-хулиганов и 3 хозенов-рыболовов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Надежде Адского Крика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29767,'Жареная рыбка','Судьба благоволит смелым!$B$BВаши агрессивные, но просчитанные действия привели к неожиданным результатам. Если выбрать подходящий момент, то можно не только покончить с этими рыболовами, но и забрать себе их улов.$B$BУничтожение противника одновременно с заготовкой провианта – образец эффективности!','Отнимите 12 взрослых карпов у хозенов-рыболовов.','Положите 12 взрослых карпов на жаровню в Надежде Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жареная рыбка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судьба благоволит смелым!$B$BВаши агрессивные, но просчитанные действия привели к неожиданным результатам. Если выбрать подходящий момент, то можно не только покончить с этими рыболовами, но и забрать себе их улов.$B$BУничтожение противника одновременно с заготовкой провианта – образец эффективности!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите 12 взрослых карпов у хозенов-рыболовов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите 12 взрослых карпов на жаровню в Надежде Адского Крика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29768,'Пропавший молот','$n, я придумал! Все просто. Давай-ка устроим такой шум, что даже ему придется проснуться.$B$BПогляди-ка, гонг! Да еще так удобно расположенный! Думаю, именно так его и будили в прошлом. Осталось лишь найти подходящий молот, чтобы звук был как можно громче.$B$BДеревенский староста рассказал мне, что такой молот есть в хмелеварне Ци-Хань, что на берегу реки к юго-западу отсюда. Это недалеко. Не хочешь сходить за ним? А я пока предупрежу жителей деревни.','Возьмите большой молот для объявления перерывов Дай-Ло в хмелеварне Ци-Хань.','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я придумал! Все просто. Давай-ка устроим такой шум, что даже ему придется проснуться.$B$BПогляди-ка, гонг! Да еще так удобно расположенный! Думаю, именно так его и будили в прошлом. Осталось лишь найти подходящий молот, чтобы звук был как можно громче.$B$BДеревенский староста рассказал мне, что такой молот есть в хмелеварне Ци-Хань, что на берегу реки к юго-западу отсюда. Это недалеко. Не хочешь сходить за ним? А я пока предупрежу жителей деревни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите большой молот для объявления перерывов Дай-Ло в хмелеварне Ци-Хань.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29769,'Канальи','Я все пытаюсь разбудить этого упрямого малыша, но, сдается мне, на острове куда ни глянь – всюду беды. Наши поля захвачены гну-синями – ворами и грабителями, похожими на кроликов.$b$bКанальи!$b$bОни размножаются быстрее, чем мы успеваем их убивать! Но у меня есть превосходная идея – надо убивать их еще быстрее! И поскольку ты здесь, $n, не думаю, что с этим у нас возникнут сложности.','Убейте 10 гну-синей.','$n, отличная работа! Стоит тебе появиться, и проблемы решаются сами собой. И это лишь одна из многих причин, по которым ты мне нравишься!','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Канальи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все пытаюсь разбудить этого упрямого малыша, но, сдается мне, на острове куда ни глянь – всюду беды. Наши поля захвачены гну-синями – ворами и грабителями, похожими на кроликов.$b$bКанальи!$b$bОни размножаются быстрее, чем мы успеваем их убивать! Но у меня есть превосходная идея – надо убивать их еще быстрее! И поскольку ты здесь, $n, не думаю, что с этим у нас возникнут сложности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 гну-синей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n, отличная работа! Стоит тебе появиться, и проблемы решаются сами собой. И это лишь одна из многих причин, по которым ты мне нравишься!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29770,'Спасти все что можно','Гну-сини растаскивают все наши овощи, но при этом они воруют куда больше, чем могут съесть. Похоже, они запасаются, по крайней мере, теми овощами, что им нравятся.$B$BНе $gмог:могла; бы ты разыскать украденные ими овощи? У меня целый остров голодных ртов, так что каждая морковка на счету.','Разыщите 3 выкопанные репы, 3 украденные моркови и 3 тыквы.','Да они надкусаны, и как надкусаны! Эх, ладно. Все равно не пропадут.$B$BСпасибо за помощь, друг.','С тех пор как дух земли Угоу заснул, почва засыхает, и нам становится все труднее прорастить в ней новые зерна. Мы должны тщательно беречь все запасы еды, иначе нас ждут тяжелые времена.','Вернитесь к Гао Летнему Ветерку на крестьянский двор Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасти все что можно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гну-сини растаскивают все наши овощи, но при этом они воруют куда больше, чем могут съесть. Похоже, они запасаются, по крайней мере, теми овощами, что им нравятся.$B$BНе $gмог:могла; бы ты разыскать украденные ими овощи? У меня целый остров голодных ртов, так что каждая морковка на счету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите 3 выкопанные репы, 3 украденные моркови и 3 тыквы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да они надкусаны, и как надкусаны! Эх, ладно. Все равно не пропадут.$B$BСпасибо за помощь, друг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С тех пор как дух земли Угоу заснул, почва засыхает, и нам становится все труднее прорастить в ней новые зерна. Мы должны тщательно беречь все запасы еды, иначе нас ждут тяжелые времена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гао Летнему Ветерку на крестьянский двор Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29771,'Прочнее дерева','Принеси мне доски, разбросанные у хмелеварни Ци-Хань.$B$BТы пока не осознаешь, насколько велика моя сила. Я тебе продемонстрирую.','Соберите 12 брошенных досок.','Отлично.$B$BМоя голова сильнее даже самого прочного дерева.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.','Вернитесь к Йо-Йо Железной Брови на крестьянский двор Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочнее дерева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принеси мне доски, разбросанные у хмелеварни Ци-Хань.$B$BТы пока не осознаешь, насколько велика моя сила. Я тебе продемонстрирую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 брошенных досок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично.$B$BМоя голова сильнее даже самого прочного дерева.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо-Йо Железной Брови на крестьянский двор Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29772,'Поднять шум','Ну что, $gготов:готова;, $n? Возможно, нам все-таки стоило найти что-нибудь подходящее для затыкания ушей, но сейчас уже поздно об этом думать. Просто запомни, что тот жуткий звон, что ты будешь слушать в течение нескольких последующих часов – звон победы!$B$BВся честь в этом деле принадлежит тебе, $n. Ударь в гонг, как только будешь $gготов:готова;!','Ударьте в гонг.','Хм... ну... звук не подкачал, но вот от Угоу я ожидал большей прыти. Этот парень заснул не на шутку!$B$BНу да ничего, $n. У меня есть новая идея, и для нее не потребуется никакой особой подготовки. Это как раз в моем духе.','Поговорите с Цзи Огненной Лапой на крестьянском дворе Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поднять шум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, $gготов:готова;, $n? Возможно, нам все-таки стоило найти что-нибудь подходящее для затыкания ушей, но сейчас уже поздно об этом думать. Просто запомни, что тот жуткий звон, что ты будешь слушать в течение нескольких последующих часов – звон победы!$B$BВся честь в этом деле принадлежит тебе, $n. Ударь в гонг, как только будешь $gготов:готова;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ударьте в гонг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... ну... звук не подкачал, но вот от Угоу я ожидал большей прыти. Этот парень заснул не на шутку!$B$BНу да ничего, $n. У меня есть новая идея, и для нее не потребуется никакой особой подготовки. Это как раз в моем духе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой на крестьянском дворе Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29773,'Угоу, дух земли','$n! Найти Угоу было несложно. Это плюс. А вот разбудить его мне пока не удалось. Это минус. Боюсь, когда он проснется, он вряд ли будет себя хорошо чувствовать – я, пока пытался его разбудить, долго его толкал и лупил.$B$BКстати, $n, а ты как спишь? Очень крепко? Что тебя будит по утрам?$B$BМне, например, достаточно выкатиться из кровати, поэтому именно это мы и попробуем! Я привязал веревки к повозке. Мы разгоним ее и перевернем его пару раз – тут-то он и проснется! Шлепни-ка быка, если тебе не трудно, а?','Приведите в чувство быка.','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угоу, дух земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Найти Угоу было несложно. Это плюс. А вот разбудить его мне пока не удалось. Это минус. Боюсь, когда он проснется, он вряд ли будет себя хорошо чувствовать – я, пока пытался его разбудить, долго его толкал и лупил.$B$BКстати, $n, а ты как спишь? Очень крепко? Что тебя будит по утрам?$B$BМне, например, достаточно выкатиться из кровати, поэтому именно это мы и попробуем! Я привязал веревки к повозке. Мы разгоним ее и перевернем его пару раз – тут-то он и проснется! Шлепни-ка быка, если тебе не трудно, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите в чувство быка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе на крестьянский двор Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29774,'Только не в лицо!','Так вот, $n, я тут размышлял над тем, что еще можно предпринять, раз наш план с гонгом не сработал, и тут меня озарило!$B$B Плеснуть водой в лицо. На меня это действует безотказно. А для такого сухого и земляного создания должно сработать в два раза лучше!$B$BНе хочешь попросить Шу, духа воды, помочь нам? Ты найдешь его на озере, рядом с водопадом.','Попросите Шу помочь пробудить Угоу, духа земли.','Насколько я его знаю, он будет рад поучаствовать – неважно, сработает это или нет. Он любит такие проделки.','Поговорите с Цзи Огненной Лапой на крестьянском дворе Дай-Ло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только не в лицо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот, $n, я тут размышлял над тем, что еще можно предпринять, раз наш план с гонгом не сработал, и тут меня озарило!$B$B Плеснуть водой в лицо. На меня это действует безотказно. А для такого сухого и земляного создания должно сработать в два раза лучше!$B$BНе хочешь попросить Шу, духа воды, помочь нам? Ты найдешь его на озере, рядом с водопадом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите Шу помочь пробудить Угоу, духа земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Насколько я его знаю, он будет рад поучаствовать – неважно, сработает это или нет. Он любит такие проделки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой на крестьянском дворе Дай-Ло.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29775,'Душа и тело Шэнь-Цзынь Су') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Душа и тело Шэнь-Цзынь Су',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29776,'Деревня Утреннего Бриза','Встретьтесь с Цзи Огненной Лапой в Деревне Утреннего Бриза.','$n, обнимемся! В этот раз наше расставание было недолгим – и мне это, пожалуй, нравится!$B$BТебе довелось поработать с Аисой, не так ли? Мы избрали разные пути и редко виделись, я почти ничего о ней не знаю. Должен признаться, я заметил, наблюдая за ее упражнениями, что ее движениям свойственна грация, которую я нахожу весьма соблазнительной.$B$BВпрочем, у нас есть более важные дела, не так ли? $n, пока мы ищем Дафэна, давай заодно разберемся с этой обезьяней проблемой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Утреннего Бриза',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Цзи Огненной Лапой в Деревне Утреннего Бриза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n, обнимемся! В этот раз наше расставание было недолгим – и мне это, пожалуй, нравится!$B$BТебе довелось поработать с Аисой, не так ли? Мы избрали разные пути и редко виделись, я почти ничего о ней не знаю. Должен признаться, я заметил, наблюдая за ее упражнениями, что ее движениям свойственна грация, которую я нахожу весьма соблазнительной.$B$BВпрочем, у нас есть более важные дела, не так ли? $n, пока мы ищем Дафэна, давай заодно разберемся с этой обезьяней проблемой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29777,'Орудие врага','Хозены украли наши кисти и теперь корябают на наших свитках изречения своих мудрецов, если, конечно, их можно так назвать. Если ты не против помочь, останови их и верни наши кисти, пока эти хозены не нанесли нам еще больше вреда.','Отнимите 8 испачканных краской кистей.','Благодарю тебя, дитя. Вскоре я вновь приступлю к записи нашей мудрости, и свитки снова можно будет вывесить для всех, желающих почерпнуть из них что-то для себя.','Я не хотел бы принижать достижения хозенов, ведь у каждой расы – свой путь. Однако сейчас они наносят вред нам и нашей культуре. И это та грань, пересечь которую мы им позволить не можем.','Вернитесь к старейшине Шаопаю в Деревню Утреннего Бриза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудие врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены украли наши кисти и теперь корябают на наших свитках изречения своих мудрецов, если, конечно, их можно так назвать. Если ты не против помочь, останови их и верни наши кисти, пока эти хозены не нанесли нам еще больше вреда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите 8 испачканных краской кистей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, дитя. Вскоре я вновь приступлю к записи нашей мудрости, и свитки снова можно будет вывесить для всех, желающих почерпнуть из них что-то для себя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не хотел бы принижать достижения хозенов, ведь у каждой расы – свой путь. Однако сейчас они наносят вред нам и нашей культуре. И это та грань, пересечь которую мы им позволить не можем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Шаопаю в Деревню Утреннего Бриза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29778,'Искаженная мудрость','$n, мы должны помочь старейшине Шаопаю. Мало кто из нас заслуживает большего уважения.$B$BПо пути сюда ты, вероятно, $gзаметил:заметила; свитки мудрости, развешанные на юге отсюда. Хозены осквернили немало этих свитков, и, к сожалению, восстановить их невозможно. К этой проблеме придется подойти решительно – нужно сжечь оскверненные свитки. Уничтожь записи хозенов целиком.$B$BИ не переживай за старейшину Шаопая. Местные жители помогут ему снова написать на свитках изречения наших мудрецов. Я лично прослежу за этим.','Сожгите 5 испорченных свитков мудрости.','Вернитесь к Цзи Огненной Лапе в Деревню Утреннего Бриза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искаженная мудрость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы должны помочь старейшине Шаопаю. Мало кто из нас заслуживает большего уважения.$B$BПо пути сюда ты, вероятно, $gзаметил:заметила; свитки мудрости, развешанные на юге отсюда. Хозены осквернили немало этих свитков, и, к сожалению, восстановить их невозможно. К этой проблеме придется подойти решительно – нужно сжечь оскверненные свитки. Уничтожь записи хозенов целиком.$B$BИ не переживай за старейшину Шаопая. Местные жители помогут ему снова написать на свитках изречения наших мудрецов. Я лично прослежу за этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 5 испорченных свитков мудрости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе в Деревню Утреннего Бриза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29779,'Простое решение','Итак, $n, мы уже второй раз сталкиваемся с распоясавшимися хозенами. Думаю, пора решить эту проблему так, как предписывает путь Хоцзинь. Никакой терпимости. Никакой медитации. Нас интересуют истоки проблемы.$B$BМы отправляемся в деревню хозенов, что к северу отсюда, и вырезаем всех этих вонючих разбойников. Я с нетерпением ждал новой возможности сразиться бок о бок с тобой, $n.','Убейте 20 хозенов в деревне Фэ-Фан.','Хороший бой всегда поднимает мне настроение!','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простое решение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, $n, мы уже второй раз сталкиваемся с распоясавшимися хозенами. Думаю, пора решить эту проблему так, как предписывает путь Хоцзинь. Никакой терпимости. Никакой медитации. Нас интересуют истоки проблемы.$B$BМы отправляемся в деревню хозенов, что к северу отсюда, и вырезаем всех этих вонючих разбойников. Я с нетерпением ждал новой возможности сразиться бок о бок с тобой, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 хозенов в деревне Фэ-Фан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хороший бой всегда поднимает мне настроение!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29780,'Не причини зла','$n, я хотел бы объяснить: путь Хоцзинь – это не путь насилия. Если битвы не избежать, мы будем драться, не колеблясь. Если же есть шанс уладить все мирным путем, мы обязательно воспользуемся им. Но часто простое решение заключается в том, чтобы, как говорится, отрубить змее голову.$B$BУ хозенов есть предводитель, который и подстрекает их нападать на наши поселения. Если мы устраним Рук-рука, нам не придется убивать всех хозенов, чтобы остановить это безумие.$B$BЯ знаю, что ты не из тех, кто следует пути Хоцзинь... но все-таки: поможешь ли ты мне, $n?','Убейте Рук-Рука, главу деревни Фэ-Фан.','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.','Рук-Рук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не причини зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я хотел бы объяснить: путь Хоцзинь – это не путь насилия. Если битвы не избежать, мы будем драться, не колеблясь. Если же есть шанс уладить все мирным путем, мы обязательно воспользуемся им. Но часто простое решение заключается в том, чтобы, как говорится, отрубить змее голову.$B$BУ хозенов есть предводитель, который и подстрекает их нападать на наши поселения. Если мы устраним Рук-рука, нам не придется убивать всех хозенов, чтобы остановить это безумие.$B$BЯ знаю, что ты не из тех, кто следует пути Хоцзинь... но все-таки: поможешь ли ты мне, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Рук-Рука, главу деревни Фэ-Фан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рук-Рук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29781,'Внимание! Обезьяны!','Обезьяны во время своих набегов любят заниматься воровством. Но если пропажа части съестных припасов – потеря не слишком большая, то мысль о обезьянах, играющих с фейерверками... вызывает у меня некоторое беспокойство. Опять же, кто знает, когда эти фейерверки могут пригодиться?$B$BТак как, поможешь мне найти украденные фейерверки, $n?','Добудьте 8 украденных фейерверков.','Удивительно, что они еще не спалили свою деревню этими фейерверками.','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внимание! Обезьяны!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обезьяны во время своих набегов любят заниматься воровством. Но если пропажа части съестных припасов – потеря не слишком большая, то мысль о обезьянах, играющих с фейерверками... вызывает у меня некоторое беспокойство. Опять же, кто знает, когда эти фейерверки могут пригодиться?$B$BТак как, поможешь мне найти украденные фейерверки, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 украденных фейерверков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удивительно, что они еще не спалили свою деревню этими фейерверками.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой около Деревни Утреннего Бриза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29782,'Прочнее кости','Этот огромный пьедестал со статуей нефритового тигра странно смотрится посреди строений хозенов.$B$BЯсно, впрочем, и другое – он очень прочен. Очень.$B$BИ вы знаете, кому его принести.','Принесите пьедестал нефритового тигра Йо-Йо Железной Брови в Деревню Утреннего Бриза.','ОТЛИЧНО! Вот это настоящее испытание. Попробуем-ка этот пьедестал на прочность!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочнее кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот огромный пьедестал со статуей нефритового тигра странно смотрится посреди строений хозенов.$B$BЯсно, впрочем, и другое – он очень прочен. Очень.$B$BИ вы знаете, кому его принести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пьедестал нефритового тигра Йо-Йо Железной Брови в Деревню Утреннего Бриза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ОТЛИЧНО! Вот это настоящее испытание. Попробуем-ка этот пьедестал на прочность!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29783,'Прочнее камня','Соберите 12 брошенных каменных блоков.','Отлично.$B$BМоя голова прочнее даже самого крепкого камня.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.','Физическая сила – ничто, если слаб твой дух.','Вернитесь к Йо-Йо Железной Брови в Деревню Утреннего Бриза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочнее камня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 брошенных каменных блоков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично.$B$BМоя голова прочнее даже самого крепкого камня.$B$BОтойди в сторонку и позволь мне развеять твои сомнения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Физическая сила – ничто, если слаб твой дух.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо-Йо Железной Брови в Деревню Утреннего Бриза.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29784,'Сбалансированный подход','Аиса медитирует над озером с тех самых пор, как мы прибыли, и все ее мысли сосредоточены на Дафэне. Я не знаю, что она надеется обнаружить, но она далеко не глупа, раз мастер Шан Си поручил эту задачу именно ей.$B$BЧтобы подойти к ней, тебе понадобится пройти по натянутым от конца пристани канатам. Это будет неплохой проверкой того, как ты умеешь удерживать равновесие. Думаю, ты легко справишься с этой задачей.','Пройдите по канатам и поговорите с Аисой Воспевающей Облака на озере Утреннего Бриза.','Я впечатлена. Если кто-то из учеников и добирается сюда, то промокает до нитки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбалансированный подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аиса медитирует над озером с тех самых пор, как мы прибыли, и все ее мысли сосредоточены на Дафэне. Я не знаю, что она надеется обнаружить, но она далеко не глупа, раз мастер Шан Си поручил эту задачу именно ей.$B$BЧтобы подойти к ней, тебе понадобится пройти по натянутым от конца пристани канатам. Это будет неплохой проверкой того, как ты умеешь удерживать равновесие. Думаю, ты легко справишься с этой задачей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите по канатам и поговорите с Аисой Воспевающей Облака на озере Утреннего Бриза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлена. Если кто-то из учеников и добирается сюда, то промокает до нитки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29785,'Дафэн, дух воздуха','Если слушать ветер достаточно долго, он принесет тебе ответ.$B$BДафэна, духа воздуха, испугал ониксовый змей. Он прячется в Зале Шептаний, что на южной стороне плато.$B$BОтправляйся к нему. Там к тебе присоединимся мы с Цзи.','Поговорите с Дафэном, духом воздуха, в Зале Шептаний.','Дафэн напуган вашим приближением, но при звуках вашего голоса немного успокаивается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дафэн, дух воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если слушать ветер достаточно долго, он принесет тебе ответ.$B$BДафэна, духа воздуха, испугал ониксовый змей. Он прячется в Зале Шептаний, что на южной стороне плато.$B$BОтправляйся к нему. Там к тебе присоединимся мы с Цзи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дафэном, духом воздуха, в Зале Шептаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дафэн напуган вашим приближением, но при звуках вашего голоса немного успокаивается.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29786,'Битва за небеса','Дафэна, духа воздуха, напугал ониксовый змей, |3-6($c). Мы должны помочь ему справиться с его страхами... или справиться с ними вместо него.$B$BКогда Цзи узнал о змее, он сказал, что у него появилась идея и он займется приготовлениями. Конечно, он опрометчив и безрассуден, однако признаюсь: я завидую его решительности и увлеченности.$B$BПойдем, сразимся с ониксовым змеем.','Победите ониксового змея с помощью фейерверков Цзи.','Поговорите с мастером Шан Си на Хребте Смеющихся Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дафэна, духа воздуха, напугал ониксовый змей, |3-6($c). Мы должны помочь ему справиться с его страхами... или справиться с ними вместо него.$B$BКогда Цзи узнал о змее, он сказал, что у него появилась идея и он займется приготовлениями. Конечно, он опрометчив и безрассуден, однако признаюсь: я завидую его решительности и увлеченности.$B$BПойдем, сразимся с ониксовым змеем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите ониксового змея с помощью фейерверков Цзи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Шан Си на Хребте Смеющихся Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29787,'Достойный пройти','Духи четырех стихий помогут тебе поговорить с землей и выслушать ее мольбы, но перед этим я хочу попросить тебя об одном одолжении.$B$BПрогуляйся со мной, $gюный:юная:c; |3-6($c). Проводи старика-пандарена к западной роще.','Убейте стража старейшин.','Поговорите с мастером Шан Си в Лесу Посохов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойный пройти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи четырех стихий помогут тебе поговорить с землей и выслушать ее мольбы, но перед этим я хочу попросить тебя об одном одолжении.$B$BПрогуляйся со мной, $gюный:юная:c; |3-6($c). Проводи старика-пандарена к западной роще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте стража старейшин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Шан Си в Лесу Посохов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29788,'Неприветливая природа','Тебе уже пришлось столкнуться с лесными духами в Рассветной долине, но в этой роще обитают лесные духи совсем другой породы. Более жестокие и куда более опасные.$B$BЕсли ты прогонишь хотя бы нескольких, духи будут тебе благодарны.','Убейте 8 проказников из Терновой Ветви.','Вернитесь к мастеру Шан Си, который находится в Лесу Посохов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприветливая природа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе уже пришлось столкнуться с лесными духами в Рассветной долине, но в этой роще обитают лесные духи совсем другой породы. Более жестокие и куда более опасные.$B$BЕсли ты прогонишь хотя бы нескольких, духи будут тебе благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 проказников из Терновой Ветви.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си, который находится в Лесу Посохов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29789,'Маленькие, но важные','Я устал, $n. Я должен отдохнуть.$B$BНам необходимо провести ритуал, но для этого нужны обереги из этой рощи. Если ты пройдешься по ней, думаю, легко их заметишь – они висят на деревьях. $B$BТы не обидишься, если я передохну и наберусь сил, а тебе поручу собрать эти обереги?','Раздобудьте 8 ритуальных оберегов Кунь-Пай.','Отдых – это чудесно. Долгие годы жизни тяжким бременем лежат на моих плечах.','Вернитесь к мастеру Шан Си, который находится в Лесу Посохов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькие, но важные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я устал, $n. Я должен отдохнуть.$B$BНам необходимо провести ритуал, но для этого нужны обереги из этой рощи. Если ты пройдешься по ней, думаю, легко их заметишь – они висят на деревьях. $B$BТы не обидишься, если я передохну и наберусь сил, а тебе поручу собрать эти обереги?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 8 ритуальных оберегов Кунь-Пай.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отдых – это чудесно. Долгие годы жизни тяжким бременем лежат на моих плечах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си, который находится в Лесу Посохов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29790,'Делиться мудростью','Это путешествие тебе вскоре предстоит продолжить уже без меня. Остановись же на минуту и выслушай старика. Пусть мои знания послужат основой твоим, чтобы в будущем ты $gдостиг:достигла; такого величия, какого не смог достигнуть я.','Поговорите с Аисой Воспевающей Облака в Лесу Посохов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Делиться мудростью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это путешествие тебе вскоре предстоит продолжить уже без меня. Остановись же на минуту и выслушай старика. Пусть мои знания послужат основой твоим, чтобы в будущем ты $gдостиг:достигла; такого величия, какого не смог достигнуть я.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аисой Воспевающей Облака в Лесу Посохов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29791,'Страдания Шэнь-Цзынь Су','Сейчас не время скорбеть. Воздушный шар готов; нас ждет Шэнь-Цзынь Су.$B$BМы станем первыми за многие столетия пандаренами, кто сможет поговорить с Шэнь-Цзынь Су. Это великая честь.','Взойдите на борт воздушного шара и поговорите с Шэнь-Цзынь Су.','Поговорите со старейшиной Шаопаем в Храме Пяти Рассветов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страдания Шэнь-Цзынь Су',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас не время скорбеть. Воздушный шар готов; нас ждет Шэнь-Цзынь Су.$B$BМы станем первыми за многие столетия пандаренами, кто сможет поговорить с Шэнь-Цзынь Су. Это великая честь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взойдите на борт воздушного шара и поговорите с Шэнь-Цзынь Су.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со старейшиной Шаопаем в Храме Пяти Рассветов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29792,'К великим свершениям','Теперь именно вам предстоит удалить занозу из бока Шэнь-Цзынь Су. Не позвольте различиям между вами помешать вам. Доверьтесь друг другу.$B$BВ лесу Пэй-У живет одинокий отшельник. Отправляйтесь в его хижину. Он знает все о темных созданиях, что прячутся среди деревьев.','Откройте ворота в лес Пэй-У.','Зло поднимается из моря и заполняет собой леса. И теперь речь не только о тиграх... в тенях прячется нечто куда более зловещее, поджидая одинокого пандарена, неосмотрительно забредшего в чащу.$B$BЗдесь вы в опасности.','Поговорите с Вэем Бледной Яростью в Одинокой хижине в лесу Пэй-У.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К великим свершениям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь именно вам предстоит удалить занозу из бока Шэнь-Цзынь Су. Не позвольте различиям между вами помешать вам. Доверьтесь друг другу.$B$BВ лесу Пэй-У живет одинокий отшельник. Отправляйтесь в его хижину. Он знает все о темных созданиях, что прячутся среди деревьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте ворота в лес Пэй-У.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зло поднимается из моря и заполняет собой леса. И теперь речь не только о тиграх... в тенях прячется нечто куда более зловещее, поджидая одинокого пандарена, неосмотрительно забредшего в чащу.$B$BЗдесь вы в опасности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вэем Бледной Яростью в Одинокой хижине в лесу Пэй-У.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29793,'Зло из морских глубин','Я не знаю, что за зло поселилось в лесу, $n, но я знаю, как с ним справиться. Думаю, ты тоже это знаешь.','Убейте 8 темных ужасов или темных кошмаров.','Вернитесь к Цзи Огненной Лапе в лес Пэй-У.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зло из морских глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знаю, что за зло поселилось в лесу, $n, но я знаю, как с ним справиться. Думаю, ты тоже это знаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 темных ужасов или темных кошмаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи Огненной Лапе в лес Пэй-У.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29794,'Своих не бросаем!','Твоя подруга сделала все что можно ради спасения моего экипажа. Примите мою искреннюю признательность.$B$BПроблем у нас все еще куда больше, чем рук, способных с ними справиться – надо потушить пожар, вытащить людей, отбиться от этих злобных морских созданий, да еще и не позволить заключенным сбежать. В общем, проблем по горло.$B$BИ на корабле еще остались люди, которых нужно вытащить до того, как палуба обрушится на их головы. Я знаю, что многого прошу, но не $gмог:могла; бы ты помочь?','Спасите 3 раненых матросов.','Я не знаю, что вы за народ, но судьба нам сегодня определенно улыбнулась. Если бы не ты и твои друзья, погибших было бы куда больше. Я у тебя в долгу.','Вернитесь к Делоре Львиное Сердце на место падения "Небесного искателя".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своих не бросаем!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя подруга сделала все что можно ради спасения моего экипажа. Примите мою искреннюю признательность.$B$BПроблем у нас все еще куда больше, чем рук, способных с ними справиться – надо потушить пожар, вытащить людей, отбиться от этих злобных морских созданий, да еще и не позволить заключенным сбежать. В общем, проблем по горло.$B$BИ на корабле еще остались люди, которых нужно вытащить до того, как палуба обрушится на их головы. Я знаю, что многого прошу, но не $gмог:могла; бы ты помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 3 раненых матросов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не знаю, что вы за народ, но судьба нам сегодня определенно улыбнулась. Если бы не ты и твои друзья, погибших было бы куда больше. Я у тебя в долгу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делоре Львиное Сердце на место падения "Небесного искателя".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29795,'Запас стеблей','Мои люди недоедают, они ранены и истощены, но они – из Орды. Каждый из них будет драться до последнего вздоха. Вы наши новые союзники, и, когда пробьет час, мы встанем с вами спина к спине. Но мы будем значительно сильнее, если у нас будет оружие.$B$BЯ послал моих людей собирать бамбуковые стебли – из них можно будет сделать копья. Если ты не против помочь, нам совсем не помешает лишняя пара рук.','Соберите 10 сломанных стеблей бамбука.','Эти стебли великолепны! Ты и глазом не успеешь моргнуть, как мы сделаем из них копья.','Орда никогда не уходит от боя.','Вернитесь к Корге Крепкой Гриве в Одинокую хижину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запас стеблей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои люди недоедают, они ранены и истощены, но они – из Орды. Каждый из них будет драться до последнего вздоха. Вы наши новые союзники, и, когда пробьет час, мы встанем с вами спина к спине. Но мы будем значительно сильнее, если у нас будет оружие.$B$BЯ послал моих людей собирать бамбуковые стебли – из них можно будет сделать копья. Если ты не против помочь, нам совсем не помешает лишняя пара рук.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 сломанных стеблей бамбука.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти стебли великолепны! Ты и глазом не успеешь моргнуть, как мы сделаем из них копья.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Орда никогда не уходит от боя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корге Крепкой Гриве в Одинокую хижину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29796,'Срочные вести','Я уверен, что Аисе этот план совсем не понравится, но другого выхода у нас нет. Не $gмог:могла; бы ты сообщить ей о наших планах, $n? Она должна быть в курсе, тогда она сможет отвести всех в безопасное место.','Поговорите с Делорой Львиное Сердце у места падения "Небесного искателя".','Твоя подруга сейчас сражается, спасая мой экипаж. Яростно, надо сказать, сражается. Так что, боюсь, с этим сообщением придется немного подождать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочные вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что Аисе этот план совсем не понравится, но другого выхода у нас нет. Не $gмог:могла; бы ты сообщить ей о наших планах, $n? Она должна быть в курсе, тогда она сможет отвести всех в безопасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делорой Львиное Сердце у места падения "Небесного искателя".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя подруга сейчас сражается, спасая мой экипаж. Яростно, надо сказать, сражается. Так что, боюсь, с этим сообщением придется немного подождать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29797,'Медикаменты','Чтобы заняться ранеными, нам нужны медикаменты, а ящики с ними разбросало во все стороны во время крушения. Если тебе удастся найти их и принести мне, моя благодарность будет безграничной.','Найдите 8 ящиков с медикаментами.','То, что нужно. Мои медики сейчас же приступят к работе.$B$BСпасибо.','Ну как, удалось тебе найти те ящики, о которых я говорила?','Вернитесь к Делоре Львиное Сердце на место падения "Небесного искателя".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медикаменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы заняться ранеными, нам нужны медикаменты, а ящики с ними разбросало во все стороны во время крушения. Если тебе удастся найти их и принести мне, моя благодарность будет безграничной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 ящиков с медикаментами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что нужно. Мои медики сейчас же приступят к работе.$B$BСпасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось тебе найти те ящики, о которых я говорила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делоре Львиное Сердце на место падения "Небесного искателя".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29798,'Древнее зло','$n, я как раз искал тебя!$b$bОдин из спасшихся моряков только что видел Аису на месте кораблекрушения. Она сражается с огромным чудовищем. Думаю, ей нужна твоя помощь. Беги к ней и побыстрее!','Победите Вордраку, глубоководный Кошмар.','Поговорите с Аисой Воспевающей Облака на месте падения "Небесного искателя".','Вордрака, глубоководный кошмар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее зло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я как раз искал тебя!$b$bОдин из спасшихся моряков только что видел Аису на месте кораблекрушения. Она сражается с огромным чудовищем. Думаю, ей нужна твоя помощь. Беги к ней и побыстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Вордраку, глубоководный Кошмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аисой Воспевающей Облака на месте падения "Небесного искателя".',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вордрака, глубоководный кошмар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29799,'Исцеление Шэнь-Цзынь Су','Это куда хуже, чем я думал, но мы справимся. Нужно собрать лекарей, чтобы закрыть рану. Мы должны спасти Шэнь-Цзынь Су!$b$bНайди любых целителей, каких только сможешь! Спаси их, освободи – сделай все, что необходимо, чтобы они оказались здесь.$b$bЗащищай их любой ценой!','Защищайте лекарей, пока они исцеляют рану Шэнь-Цзынь Су.','Мы должны защищать лекарей, пока они исцеляют рану!','Поговорите с Цзи Огненной Лапой на месте падения "Небесного искателя"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление Шэнь-Цзынь Су',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это куда хуже, чем я думал, но мы справимся. Нужно собрать лекарей, чтобы закрыть рану. Мы должны спасти Шэнь-Цзынь Су!$b$bНайди любых целителей, каких только сможешь! Спаси их, освободи – сделай все, что необходимо, чтобы они оказались здесь.$b$bЗащищай их любой ценой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте лекарей, пока они исцеляют рану Шэнь-Цзынь Су.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны защищать лекарей, пока они исцеляют рану!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой на месте падения "Небесного искателя"',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29800,'Новые союзники') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые союзники',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29801,'Доказательство силы','Привет, $n! Молва говорит, что ты обладаешь, так сказать, особой ловкостью рук!$B$BТвои умения весьма пригодились бы нам, чтобы разрешить одну весьма деликатную проблему. Но перед тем как я расскажу тебе, в чем заключается суть дела, нам нужно убедиться в том, что ты подходишь для этой работы.$B$BКогда на твоем пути встретится Хагара Владычица Штормов, выкради у нее дешифрующее кольцо тайнописца. Ну что – ты $gготов:готова; взяться за эту работу?','Выкрадите дешифрующее кольцо тайнописца у Хагары Владычицы Штормов, находящейся в Оке Вечности в рейдовой зоне Душа Дракона.','Отнесите кольцо лорду Афрасастразу в Храм Драконьего Покоя в рейдовой зоне Душа Дракона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n! Молва говорит, что ты обладаешь, так сказать, особой ловкостью рук!$B$BТвои умения весьма пригодились бы нам, чтобы разрешить одну весьма деликатную проблему. Но перед тем как я расскажу тебе, в чем заключается суть дела, нам нужно убедиться в том, что ты подходишь для этой работы.$B$BКогда на твоем пути встретится Хагара Владычица Штормов, выкради у нее дешифрующее кольцо тайнописца. Ну что – ты $gготов:готова; взяться за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выкрадите дешифрующее кольцо тайнописца у Хагары Владычицы Штормов, находящейся в Оке Вечности в рейдовой зоне Душа Дракона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите кольцо лорду Афрасастразу в Храм Драконьего Покоя в рейдовой зоне Душа Дракона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29802,'Тайное сообщение','Зарядите свое дешифрующее кольцо тайнописца и используйте его для расшифровки закодированного сообщения Корастразы.','Сообщите о том, что содержится в расшифрованном послании, Корастразе. Она находится в Гранатовом редуте, что в Сумеречном нагорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайное сообщение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зарядите свое дешифрующее кольцо тайнописца и используйте его для расшифровки закодированного сообщения Корастразы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о том, что содержится в расшифрованном послании, Корастразе. Она находится в Гранатовом редуте, что в Сумеречном нагорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29803,'Уши Короля-Лича','Принц Келесет – это глаза и уши Артаса на Фьорде.$B$BМне это решительно не нравится!$B$BСтупай и преподай ему последний урок. Весь мир скажет тебе за это спасибо.','Готов поспорить, бледнолицый гад почувствовал это!$B$BСлышишь, Артас?! Близится час правосудия!','Вернитесь к защитнику Мордуну в Крепость Утгард.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уши Короля-Лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принц Келесет – это глаза и уши Артаса на Фьорде.$B$BМне это решительно не нравится!$B$BСтупай и преподай ему последний урок. Весь мир скажет тебе за это спасибо.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готов поспорить, бледнолицый гад почувствовал это!$B$BСлышишь, Артас?! Близится час правосудия!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к защитнику Мордуну в Крепость Утгард.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (29804,'Бешенство','Я уже собирался отбросить копыта.$B$BНо теперь еще и это!$B$BМы с Нюхачом были старыми приятелями. О, какие воспоминания!..$B$BЯ не смогу смотреть в глаза Нюхачу в загробной жизни, если не отомщу за его смерть!$B$BЭтой шпаной верховодит некий Конк. Мы должны разнюхать, где его лежбище, и замочить – за Нюхача!','Убейте Конка.','Мы потеряли Зин\'Джуна?$B$BЭто поистине черный день, брат. Они заплатят за это!','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.','Конк') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бешенство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже собирался отбросить копыта.$B$BНо теперь еще и это!$B$BМы с Нюхачом были старыми приятелями. О, какие воспоминания!..$B$BЯ не смогу смотреть в глаза Нюхачу в загробной жизни, если не отомщу за его смерть!$B$BЭтой шпаной верховодит некий Конк. Мы должны разнюхать, где его лежбище, и замочить – за Нюхача!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Конка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы потеряли Зин\'Джуна?$B$BЭто поистине черный день, брат. Они заплатят за это!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Конк',`questgivertargetname_loc8`);
