INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29806,'Бродячий Задира','[ph] Найдите и вызовите на бой Бродячего Задиру.','Победите Бродячего Задиру.','Поговорите с Бродячим Задирой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бродячий Задира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[ph] Найдите и вызовите на бой Бродячего Задиру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Бродячего Задиру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бродячим Задирой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29807,'Смерть королю-предателю!','Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.$b$bЭто из-за него наша родина стала такой, какой мы видим ее сейчас. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.$b$bПокончи с правлением Ануб\'арака.','Завоеватель А\'зак из Азжол-Неруба поручил вам уничтожить Ануб\'арака. Вы должны будете вернуться к А\'заку с разбитым панцирем Ануб\'арака.','<А\'зак смотрит на панцирь, и все его глаза вспыхивают зловещим огнем.>$B$BСВЕРШИЛОСЬ!$B$BНочной эльф! Твое имя непременно будет вписано в расширенную историю нашего народа.','Вернитесь к завоевателю А\'заку в Азжол-Неруб.','Король-предатель','Ануб\'арак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть королю-предателю!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ануб\'арак, король-предатель, обитает в некогда славном подземном королевстве Азжол-Неруб.$b$bЭто из-за него наша родина стала такой, какой мы видим ее сейчас. Он правит армией нерубов-нежити, которые, как и их лидер, поклялись в верности Королю-личу.$b$bПокончи с правлением Ануб\'арака.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завоеватель А\'зак из Азжол-Неруба поручил вам уничтожить Ануб\'арака. Вы должны будете вернуться к А\'заку с разбитым панцирем Ануб\'арака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<А\'зак смотрит на панцирь, и все его глаза вспыхивают зловещим огнем.>$B$BСВЕРШИЛОСЬ!$B$BНочной эльф! Твое имя непременно будет вписано в расширенную историю нашего народа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевателю А\'заку в Азжол-Неруб.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Король-предатель',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ануб\'арак',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29808,'И не забудь про яйца!','По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огромную армию.$b$bЭти яйца заражены темной магией. Мы непременно должны уничтожить их.','Завоеватель А\'зак из Азжол-Неруба поручил вам уничтожить 6 нерубских яиц Плети.','Вернитесь к завоевателю А\'заку в Азжол-Неруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И не забудь про яйца!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По всему Азжол-Нерубу порабощенные Плетью нерубы заботятся о яйцах, из которых вскоре должно появиться на свет их потомство, пополнив их и без того огромную армию.$b$bЭти яйца заражены темной магией. Мы непременно должны уничтожить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завоеватель А\'зак из Азжол-Неруба поручил вам уничтожить 6 нерубских яиц Плети.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевателю А\'заку в Азжол-Неруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29809,'"Эффективные раскопки"','В руководстве приведено несколько безумных методик эффективного управления большим числом работников на раскопках.$b$bПролистав книгу, вы понимаете, что автор командует командой мародеров.$b$bСудя по карте на последней странице обложки, на юго-западе Ульдума автор построил бункер.$b$bВозможно, вам следует заглянуть к нему в гости.','Отнесите "Эффективные раскопки" Беллоку Сияющему Клинку, который находится в лагере Шнотца.','Вы предполагаете, что на обложке изображен ушедший в свои мысли автор.','Шнотц') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Эффективные раскопки"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В руководстве приведено несколько безумных методик эффективного управления большим числом работников на раскопках.$b$bПролистав книгу, вы понимаете, что автор командует командой мародеров.$b$bСудя по карте на последней странице обложки, на юго-западе Ульдума автор построил бункер.$b$bВозможно, вам следует заглянуть к нему в гости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите "Эффективные раскопки" Беллоку Сияющему Клинку, который находится в лагере Шнотца.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вы предполагаете, что на обложке изображен ушедший в свои мысли автор.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шнотц',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29810,'Безликие','Когда мои сородичи вели борьбу против нежити, они вынуждены был уходить все глубже и глубже по мере того, как нежить теснила их. В отчаянии они забрались слишком глубоко.$b$bМы невольно стали свидетелями проявлении воли древнего бога, исполняемой существами, известными лишь как Безликие.$b$bВести борьбу с такими могучими противниками на два фронта мы уже не смогли. Из-за этой новой напасти мы проиграли войну с нежитью и лишились дома.$b$bВойди в Ан\'кахет, |3-6($c), и очисти наш старый дом от этих Безликих тварей.','Убейте глашатая Волажа из Ан\'кахета и сопровождающих его трех позабытых по просьбе Киликса Разрушителя из Провала Наржуна.','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безликие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мои сородичи вели борьбу против нежити, они вынуждены был уходить все глубже и глубже по мере того, как нежить теснила их. В отчаянии они забрались слишком глубоко.$b$bМы невольно стали свидетелями проявлении воли древнего бога, исполняемой существами, известными лишь как Безликие.$b$bВести борьбу с такими могучими противниками на два фронта мы уже не смогли. Из-за этой новой напасти мы проиграли войну с нежитью и лишились дома.$b$bВойди в Ан\'кахет, |3-6($c), и очисти наш старый дом от этих Безликих тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте глашатая Волажа из Ан\'кахета и сопровождающих его трех позабытых по просьбе Киликса Разрушителя из Провала Наржуна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киликсу Разрушителю в Провал Наржуна, что в Драконьем Погосте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29811,'Талисман Хранителя Врат','Крик\'тир, хранитель врат Азжол-Неруба, не был предателем.$B$BОн погиб на Войне пауков, защищая наш дом от Плети.$B$BПо долгу службы он владел ключом тайной империи. Я хочу попросить тебя отыскать его, чтобы вернуть империю ее народу.','Завоеватель А\'зак из Азжол-Неруба хочет, чтобы вы достали талисман стража ворот у Крик\'тира, Хранителя Врат.','Так я и думал.$B$BБольшая часть империи оставалась закрытой со времени последней битвы Крик\'тира. Быть может, мои соплеменники уже полностью взяли под контроль глубины и теперь ожидают, когда их выпустят? А может, за запертыми дверьми прячутся безликие?$B$BЛишь время покажет. Сперва же мы должны очистить от скверны Артаса верхние ярусы Азжол-Неруба.','Ты освободил дух Крик\'тира от проклятия нежизни? Что с талисманом?','Вернитесь к завоевателю А\'заку в Азжол-Неруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талисман Хранителя Врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крик\'тир, хранитель врат Азжол-Неруба, не был предателем.$B$BОн погиб на Войне пауков, защищая наш дом от Плети.$B$BПо долгу службы он владел ключом тайной империи. Я хочу попросить тебя отыскать его, чтобы вернуть империю ее народу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завоеватель А\'зак из Азжол-Неруба хочет, чтобы вы достали талисман стража ворот у Крик\'тира, Хранителя Врат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и думал.$B$BБольшая часть империи оставалась закрытой со времени последней битвы Крик\'тира. Быть может, мои соплеменники уже полностью взяли под контроль глубины и теперь ожидают, когда их выпустят? А может, за запертыми дверьми прячутся безликие?$B$BЛишь время покажет. Сперва же мы должны очистить от скверны Артаса верхние ярусы Азжол-Неруба.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты освободил дух Крик\'тира от проклятия нежизни? Что с талисманом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к завоевателю А\'заку в Азжол-Неруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29812,'Спасите няшу!','Лисья роща превратилась в смертельную ловушку для рыжих панд! $B$BУвы мне! Не надо, не надо было помогать этому безумцу – хмелевару Темному Глотку! Но кто мог знать, что в результате всего этого у местных лис появится опьяняющий укус, который делает бедных маленьких мишек совсем беззащитными! $B$BПожалуйста, помоги мне!$B$BСобери панд у этого костра, пусть вдохнут здесь отрезвляющий аромат. Тогда некоторое время панды будут в безопасности.','Заарканьте 5 нетрезвых рыжих панд в Лисьей роще и приведите к ученице Цзи Хмельной Ярости.','Поговорите с ученицей Цзи Хмельной Яростью') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите няшу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лисья роща превратилась в смертельную ловушку для рыжих панд! $B$BУвы мне! Не надо, не надо было помогать этому безумцу – хмелевару Темному Глотку! Но кто мог знать, что в результате всего этого у местных лис появится опьяняющий укус, который делает бедных маленьких мишек совсем беззащитными! $B$BПожалуйста, помоги мне!$B$BСобери панд у этого костра, пусть вдохнут здесь отрезвляющий аромат. Тогда некоторое время панды будут в безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заарканьте 5 нетрезвых рыжих панд в Лисьей роще и приведите к ученице Цзи Хмельной Ярости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ученицей Цзи Хмельной Яростью',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29813,'Смертельное похмелье','Я же просил его этого не делать! Но нет, хмелевар Темный Глоток никого не слушает.$B$BМой хозяин отравил местные источники – он, видите ли, хочет сделать воду "вкуснее". Токсины добрались и сюда, в Лисью рощу – и оказали необратимое воздействие на лис. $B$BТоксины приводят лис в бешенство, и теперь эти звери представляют опасность как для других животных, так и для путников.$B$BТы не $gмог:могла; бы уменьшить численность лис?','Уничтожьте 8 опьяненных лис в Лисьей роще.','Поговорите с ученицей Цзи Хмельной Яростью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельное похмелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я же просил его этого не делать! Но нет, хмелевар Темный Глоток никого не слушает.$B$BМой хозяин отравил местные источники – он, видите ли, хочет сделать воду "вкуснее". Токсины добрались и сюда, в Лисью рощу – и оказали необратимое воздействие на лис. $B$BТоксины приводят лис в бешенство, и теперь эти звери представляют опасность как для других животных, так и для путников.$B$BТы не $gмог:могла; бы уменьшить численность лис?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 опьяненных лис в Лисьей роще.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ученицей Цзи Хмельной Яростью.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29814,'Нужно добавить','Похоже, мой господин отравил своими вкусовыми добавками все местные источники воды.$B$BВозможно, я сумею изготовить противоядие, но мне нужны ингредиенты. Известно, что при легких случаях отравления хороший эффект оказывают орхидеи.$B$BПобеди собирателей орхидей в Ложбине Орхидей и отними у них несколько опыленных цветов. С помощью этих растений мы очистим главный источник.','Победите собирателей орхидей и заберите у них 15 опыленных орхидей.','Принесите опыленные орхидеи ученице Цзи Хмельной Ярости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужно добавить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, мой господин отравил своими вкусовыми добавками все местные источники воды.$B$BВозможно, я сумею изготовить противоядие, но мне нужны ингредиенты. Известно, что при легких случаях отравления хороший эффект оказывают орхидеи.$B$BПобеди собирателей орхидей в Ложбине Орхидей и отними у них несколько опыленных цветов. С помощью этих растений мы очистим главный источник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите собирателей орхидей и заберите у них 15 опыленных орхидей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите опыленные орхидеи ученице Цзи Хмельной Ярости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29815,'Криминалистика','Эти существа повсюду, и настроены они крайне недружелюбно! Нужно разобраться с ними до того, как прибудет очередной отряд Альянса. Нашему экземпляру здорово досталось, но мне все равно удалось сделать несколько удивительных открытий в области его анатомии.$B$BА если у меня будут необходимые реагенты, то я сделаю яд, который сможет эффективно устранять его сородичей. На деле, для этого мне нужно всего лишь немного улучшить тот яд, который у меня уже есть.$B$BПостарайся набрать немного вязкого хлорофилла у воды. Подойдет любой, который можно извлечь из относительно разумных представителей местной флоры.','Соберите 8 образцов вязкого хлорофилла.','Надеюсь, ты преуспела. От этого зависит наша жизнь.','Поговорите с темным мастером Кирин в Надежде Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Криминалистика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти существа повсюду, и настроены они крайне недружелюбно! Нужно разобраться с ними до того, как прибудет очередной отряд Альянса. Нашему экземпляру здорово досталось, но мне все равно удалось сделать несколько удивительных открытий в области его анатомии.$B$BА если у меня будут необходимые реагенты, то я сделаю яд, который сможет эффективно устранять его сородичей. На деле, для этого мне нужно всего лишь немного улучшить тот яд, который у меня уже есть.$B$BПостарайся набрать немного вязкого хлорофилла у воды. Подойдет любой, который можно извлечь из относительно разумных представителей местной флоры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 образцов вязкого хлорофилла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты преуспела. От этого зависит наша жизнь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с темным мастером Кирин в Надежде Адского Крика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29816,'Образцы','Безумный Хмелевар должен сам отведать своей отравы.$B$BК востоку отсюда находятся несколько пандаренов, побывавших на "дегустации", которая едва не стала для них последней.$B$BТы не $gмог:могла; бы добраться до этой долины и узнать, не осталось ли у них напитка, который они вчера пробовали? Если наберешь достаточно образцов, я смогу воссоздать рецепт.$B$BОтдай образцы моему другу Цзяню – он сможет немного изменить их.$B$BИ, кстати, будь $gосторожен:осторожна;. Похоже, этот напиток обладает жуткими побочными эффектами.','Получите 8 образцов токсина у вдрызг пьяных пандаренов и отнесите их Цзяню, который находится в Долине Безумного Хмелевара.','Поговорите с Цзянем в Долине Безумного Хмелевара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безумный Хмелевар должен сам отведать своей отравы.$B$BК востоку отсюда находятся несколько пандаренов, побывавших на "дегустации", которая едва не стала для них последней.$B$BТы не $gмог:могла; бы добраться до этой долины и узнать, не осталось ли у них напитка, который они вчера пробовали? Если наберешь достаточно образцов, я смогу воссоздать рецепт.$B$BОтдай образцы моему другу Цзяню – он сможет немного изменить их.$B$BИ, кстати, будь $gосторожен:осторожна;. Похоже, этот напиток обладает жуткими побочными эффектами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите 8 образцов токсина у вдрызг пьяных пандаренов и отнесите их Цзяню, который находится в Долине Безумного Хмелевара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзянем в Долине Безумного Хмелевара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29817,'Пьяные тигры','Для моего народа орхидеи – лекарство, но для местных тигров это мощное снотворное. Зачастую эти звери заходят в заросли орхидей и засыпают там, одурманенные сильным ароматом.$B$BЕсли же добавить токсин, которым Темный Глоток отравил воду, то эти животные приходят в бешенство. Если ничего не предпринять, тигры начнут нападать на Нефритовый храм. $B$BТы не $gмог:могла; бы уменьшить численность тигров?','Уничтожьте 9 бешеных тигров в Ложбине Орхидей.','Вернитесь к ученице Цзи Хмельной Ярости в Ложбину Орхидей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пьяные тигры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для моего народа орхидеи – лекарство, но для местных тигров это мощное снотворное. Зачастую эти звери заходят в заросли орхидей и засыпают там, одурманенные сильным ароматом.$B$BЕсли же добавить токсин, которым Темный Глоток отравил воду, то эти животные приходят в бешенство. Если ничего не предпринять, тигры начнут нападать на Нефритовый храм. $B$BТы не $gмог:могла; бы уменьшить численность тигров?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 9 бешеных тигров в Ложбине Орхидей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученице Цзи Хмельной Ярости в Ложбину Орхидей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29818,'Улучшение вкуса','Собранные тобой орхидеи помогут нам устранить источник всех неприятностей.$B$BК востоку отсюда, в долине, находится озеро, отравленное хмелеваром Темным Глотком. Отправляйся туда и брось растения в воду. Токсины выйдут на поверхность, и тогда ты сможешь их победить.$B$BКогда все сделаешь, поговори с моим другом Цзянем. Он дружелюбный дух воды и не раз помогал нам с хозяином придумывать новые рецепты.','Бросьте очищающие орхидеи в воды озера в Долине Безумного Хмелевара и победите вышедшие на поверхность токсины.','Поговорите с Цзянем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улучшение вкуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Собранные тобой орхидеи помогут нам устранить источник всех неприятностей.$B$BК востоку отсюда, в долине, находится озеро, отравленное хмелеваром Темным Глотком. Отправляйся туда и брось растения в воду. Токсины выйдут на поверхность, и тогда ты сможешь их победить.$B$BКогда все сделаешь, поговори с моим другом Цзянем. Он дружелюбный дух воды и не раз помогал нам с хозяином придумывать новые рецепты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте очищающие орхидеи в воды озера в Долине Безумного Хмелевара и победите вышедшие на поверхность токсины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзянем.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29819,'Новый господин','Все ясно! С помощью добытых тобой токсинов я не только воссоздал рецепт Темного Глотка, но также исправил ошибку, которая приводила к возникновению заболевания.$B$BТы понимаешь, что это значит? Невероятно богатый вкус и никаких летальных побочных эффектов!$B$BА теперь мы разберемся с хмелеваром. Я нагрузил Белушку образцами. Можешь взять их и вызвать Темного Глотка на поединок дегустаторов?$B$BТебе придется пить то, что он сварит, но мой отрезвляющий огонь поможет тебе сжульничать.','Отправляйтесь на арену Дегустаторов и вызовите хмелевара Темного Глотка на поединок.','Поговорите с ученицей Цзи Хмельной Яростью в Долине Безумного Хмелевара.','Он спятил, точно тебе говорю!','Безумный Хмелевар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый господин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все ясно! С помощью добытых тобой токсинов я не только воссоздал рецепт Темного Глотка, но также исправил ошибку, которая приводила к возникновению заболевания.$B$BТы понимаешь, что это значит? Невероятно богатый вкус и никаких летальных побочных эффектов!$B$BА теперь мы разберемся с хмелеваром. Я нагрузил Белушку образцами. Можешь взять их и вызвать Темного Глотка на поединок дегустаторов?$B$BТебе придется пить то, что он сварит, но мой отрезвляющий огонь поможет тебе сжульничать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на арену Дегустаторов и вызовите хмелевара Темного Глотка на поединок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с ученицей Цзи Хмельной Яростью в Долине Безумного Хмелевара.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он спятил, точно тебе говорю!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Безумный Хмелевар',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29820,'В Нексус','Я отправил боевого мага Кейтлин в Нексус, чтобы она расследовала причину хаоса во владениях Малигоса, но от не было вестей уже несколько дней.$B$BМожет, ты отправишься туда и предложишь ей свою помощь? Наверняка она окажется нелишней – если, конечно, Кейтлин еще не сожрали драконы.','Верховный маг Беринард попросил вас поговорить с боевым магом Кейтлин в Нексусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Нексус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправил боевого мага Кейтлин в Нексус, чтобы она расследовала причину хаоса во владениях Малигоса, но от не было вестей уже несколько дней.$B$BМожет, ты отправишься туда и предложишь ей свою помощь? Наверняка она окажется нелишней – если, конечно, Кейтлин еще не сожрали драконы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Беринард попросил вас поговорить с боевым магом Кейтлин в Нексусе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29821,'Промахнулся лишь на... Так много!','Слушай-ка...$b$bЯ отправил с корабля пару роботов с продовольствием, но они все разбились по дороге.$b$bОдин из них, кажись, пронесся через весь лагерь и грохнулся у водопада.$b$bМожет, сходишь и принесешь содержимое того ящика сюда, а?$b$bУ нас кончились роботы, но мои реактивные ботинки развяжут тебе руки... точнее, ноги.$b$bХа! Отличная шутка...','Найти пропавший ящик с припасами у Водопадов Спокойствия.','Этот ящик должен быть полон припасов...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Промахнулся лишь на... Так много!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай-ка...$b$bЯ отправил с корабля пару роботов с продовольствием, но они все разбились по дороге.$b$bОдин из них, кажись, пронесся через весь лагерь и грохнулся у водопада.$b$bМожет, сходишь и принесешь содержимое того ящика сюда, а?$b$bУ нас кончились роботы, но мои реактивные ботинки развяжут тебе руки... точнее, ноги.$b$bХа! Отличная шутка...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найти пропавший ящик с припасами у Водопадов Спокойствия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот ящик должен быть полон припасов...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29822,'Разузнать обстановку','Будь прокляты эти мохнатые паразиты! Убьешь одного – вылезут еще двое...$b$bНичего не изменилось, $n. Приказ есть приказ, и неважно, сколько нас осталось, чтобы его выполнить.$b$bМне нужно еще поработать над планами и решить кучу вопросов.$b$bИди и разведай обстановку. Не возвращайся, пока не найдешь что-то важное, о чем нужно сообщить.$b$bИ заткни уже этого болтуна, пока будешь там!$b$bВыполняй!','Посетите святилище солнца и святилище луны и убейте Дука Укема.','Поговорите с хранителем истории Чо в Пещере Слов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разузнать обстановку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь прокляты эти мохнатые паразиты! Убьешь одного – вылезут еще двое...$b$bНичего не изменилось, $n. Приказ есть приказ, и неважно, сколько нас осталось, чтобы его выполнить.$b$bМне нужно еще поработать над планами и решить кучу вопросов.$b$bИди и разведай обстановку. Не возвращайся, пока не найдешь что-то важное, о чем нужно сообщить.$b$bИ заткни уже этого болтуна, пока будешь там!$b$bВыполняй!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите святилище солнца и святилище луны и убейте Дука Укема.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Пещере Слов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29823,'Мы искать не только Альянс, ты знаешь. Мы еще смотреть на заносчивый, скользкий цзинь-юй!$B$BНу, мы их найти...','Выслушайте доклад Рико.','Да, я убежать быстро. Так что? Если бы не я, то Кирин погибнуть. Ох, погоди... она уже мертвый...$B$BУходи! Голова Рико болеть сильно.','Вернитесь к Рико на холм Грукин в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы искать не только Альянс, ты знаешь. Мы еще смотреть на заносчивый, скользкий цзинь-юй!$B$BНу, мы их найти...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад Рико.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я убежать быстро. Так что? Если бы не я, то Кирин погибнуть. Ох, погоди... она уже мертвый...$B$BУходи! Голова Рико болеть сильно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рико на холм Грукин в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29825,'Уже не ученик','Когда-то провидец Надокс был моим учителем.$B$BНо я больше не могу считать себя его учеником. Он обратился к служению проклятым и убил мою семью и друзей прямо на моих глазах.$B$BОтыщи его в этих глубинах, |3-6($r), и пусть он заплатит за все свои преступления.','Провидец Изит из Ан\'кахета поручил вам убить старейшину Надокса.','Теперь, когда Надокса не стало, я надеюсь, что смогу сам повести за собой свой народ.$B$BИмперия Азжол-Неруб однажды станет великой, вот увидишь, |3-6(Гном)...','Надеюсь, с могучим Надоксом покончено навсегда?','Вернитесь к провидцу Изиту в Ан\'Кахет.','Молодец.','Провидец Изит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уже не ученик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то провидец Надокс был моим учителем.$B$BНо я больше не могу считать себя его учеником. Он обратился к служению проклятым и убил мою семью и друзей прямо на моих глазах.$B$BОтыщи его в этих глубинах, |3-6($r), и пусть он заплатит за все свои преступления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провидец Изит из Ан\'кахета поручил вам убить старейшину Надокса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда Надокса не стало, я надеюсь, что смогу сам повести за собой свой народ.$B$BИмперия Азжол-Неруб однажды станет великой, вот увидишь, |3-6(Гном)...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, с могучим Надоксом покончено навсегда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Изиту в Ан\'Кахет.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Молодец.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Провидец Изит',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29826,'Возвращение Ан\'Кахета','Принц Талдарам и его армия Плети используют те же самые обереги, что применяли мы для того, чтобы скрыть нашу империю и оградить себя от обитателей ледяных глубин.$B$BОтключи обереги и уничтожь силы Плети, что охраняют их. Мы же поможем местным перебить остальных.','Провидец Изит из Ан\'кахета хочет, чтобы вы убили 3 глаза Талдарама, костомола и принца Талдарама.','Прекрасно.$B$B<Вы слышите несколько щелчков.>$B$BТеперь пора заняться следующим противником.','Вернитесь к провидцу Изиту в Ан\'Кахет.','О неудаче не может быть и речи.','Провидец Изит','Мне нужно попросить тебя еще об одном одолжении.','Провидец Изит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Ан\'Кахета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принц Талдарам и его армия Плети используют те же самые обереги, что применяли мы для того, чтобы скрыть нашу империю и оградить себя от обитателей ледяных глубин.$B$BОтключи обереги и уничтожь силы Плети, что охраняют их. Мы же поможем местным перебить остальных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провидец Изит из Ан\'кахета хочет, чтобы вы убили 3 глаза Талдарама, костомола и принца Талдарама.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно.$B$B<Вы слышите несколько щелчков.>$B$BТеперь пора заняться следующим противником.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Изиту в Ан\'Кахет.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','О неудаче не может быть и речи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Провидец Изит',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мне нужно попросить тебя еще об одном одолжении.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Провидец Изит',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29827,'Кислотный дождь','После твоего ухода все больше и больше этих созданий приближается к лагерю. Похоже, они копят силы для решающего штурма!$B$BНам нужно переходить к самым решительным мерам, если хотим увидеть рассвет.$B$BВот, возьми мои отравленные звездочки и найди способ нанести врагу серьезный урон.','Убейте 25 хозенов-головорезов и 25 хозенов-кинжальщиков с помощью починенного гирокоптера.','Отлично! Какой творческий подход!$B$BЭто их задержит на какое-то время.','Поговорите с Кирин у Кулака Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кислотный дождь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После твоего ухода все больше и больше этих созданий приближается к лагерю. Похоже, они копят силы для решающего штурма!$B$BНам нужно переходить к самым решительным мерам, если хотим увидеть рассвет.$B$BВот, возьми мои отравленные звездочки и найди способ нанести врагу серьезный урон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 25 хозенов-головорезов и 25 хозенов-кинжальщиков с помощью починенного гирокоптера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Какой творческий подход!$B$BЭто их задержит на какое-то время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кирин у Кулака Адского Крика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29828,'Кого боялась Плеть','Один из спасавшихся бегством троллей Драккари рассказал мне о Дреде, великом короле ящеров, которого не брала чума.$B$BЕсли ты отыщешь короля Дреда и принесешь мне один из его зубов, возможно, я сумею изготовить из него оружие.','Курцель из Крепости Драк\'Тарон хочет, чтобы вы убили короля Дреда и принесли ей его зуб.','<Курцель от удивления широко раскрывает глаза.>$B$BНичего себе! Какой здоровенный!','Ну что, этот могучий ящер действительно не выдумка?','Вернитесь к Курцель в Крепость Драк\'Тарон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кого боялась Плеть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из спасавшихся бегством троллей Драккари рассказал мне о Дреде, великом короле ящеров, которого не брала чума.$B$BЕсли ты отыщешь короля Дреда и принесешь мне один из его зубов, возможно, я сумею изготовить из него оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Курцель из Крепости Драк\'Тарон хочет, чтобы вы убили короля Дреда и принесли ей его зуб.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Курцель от удивления широко раскрывает глаза.>$B$BНичего себе! Какой здоровенный!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, этот могучий ящер действительно не выдумка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Курцель в Крепость Драк\'Тарон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29829,'Осторожность – ключ к успеху','Послушай меня, |3-6($r).$b$bЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!$b$bМне нужно, чтобы ты немедленно $gотправился:отправилась; в тюрьму и $gпоговорил:поговорила; с лейтенантом Синклари. Она посвятит тебя в детали.$b$bЭто еще не все. Я хочу, чтобы ты $gдействовал:действовала; очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?$b$bОтлично. А теперь ступай!','Ронин хочет, чтобы вы отправились в Аметистовую крепость и поговорили с лейтенантом Синклари.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожность – ключ к успеху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай меня, |3-6($r).$b$bЯ только что узнал, что в Аметистовой крепости произошел один инцидент. Оказывается, синие драконы планируют масштабную атаку на Даларан!$b$bМне нужно, чтобы ты немедленно $gотправился:отправилась; в тюрьму и $gпоговорил:поговорила; с лейтенантом Синклари. Она посвятит тебя в детали.$b$bЭто еще не все. Я хочу, чтобы ты $gдействовал:действовала; очень осторожно. Незачем попусту тревожить жителей Даларана, особенно, если этой тревоги можно избежать. Я понятно выразился?$b$bОтлично. А теперь ступай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ронин хочет, чтобы вы отправились в Аметистовую крепость и поговорили с лейтенантом Синклари.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29830,'Сдерживание','От моего войска мало что осталось, а прислужники Малигоса продолжают сыпаться на нас, Как из рога изобилия.$B$BИ я опасаюсь, что самое худшее еще впереди.$B$BТебе нужно будет сдерживать их, пока не появится их лидер – Синигоса. Лишь уничтожив ее, мы сможем остановить вторжение и спасти Даларан.$B$BПоговори со мной еще раз, когда будешь $gготов:готова;.','Лейтенант Синклари из Аметистовой крепости хочет, чтобы вы остановили вторжение синих драконов. Когда Синигоса будет повержена, поговорите с лейтенантом снова.','Хвала тебе, герой!$B$BДаларан спасен – и все благодаря твоей храбрости.','Вернитесь к лейтенанту Синклари в Аметистовую крепость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдерживание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От моего войска мало что осталось, а прислужники Малигоса продолжают сыпаться на нас, Как из рога изобилия.$B$BИ я опасаюсь, что самое худшее еще впереди.$B$BТебе нужно будет сдерживать их, пока не появится их лидер – Синигоса. Лишь уничтожив ее, мы сможем остановить вторжение и спасти Даларан.$B$BПоговори со мной еще раз, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лейтенант Синклари из Аметистовой крепости хочет, чтобы вы остановили вторжение синих драконов. Когда Синигоса будет повержена, поговорите с лейтенантом снова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала тебе, герой!$B$BДаларан спасен – и все благодаря твоей храбрости.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Синклари в Аметистовую крепость.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29831,'DEPRECATED: Terror on the High Seas','До Штормграда дошли слухи о том, что на море хозяйничают пираты из Орды – они берут на абордаж корабли Альянса, грабят их и притесняют пассажиров.$B$BГерои Альянса, нам нужна ваша помощь! Вы должны проверить, правдивы ли эти сообщения! Если хотите принять участие в рейде, разыщите в крепости Штормграда верховного адмирала Джес-Терет.','Поговорите с верховным адмиралом Джес-Терет в тронном зале крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Terror on the High Seas',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До Штормграда дошли слухи о том, что на море хозяйничают пираты из Орды – они берут на абордаж корабли Альянса, грабят их и притесняют пассажиров.$B$BГерои Альянса, нам нужна ваша помощь! Вы должны проверить, правдивы ли эти сообщения! Если хотите принять участие в рейде, разыщите в крепости Штормграда верховного адмирала Джес-Терет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным адмиралом Джес-Терет в тронном зале крепости Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29832,'DEPRECATED: Gathering Evidence','Корабль под названием "Доблесть" перевозит пассажиров и грузы из Штормграда в деревню Рут\'теран, что за Дарнасом.$B$BТак вот, пассажиры и команда рассказывают, что воины Орды остановили "Доблесть" у Тельдрассила. Ордынцы украли часть груза, причинили зло пассажирам и вынудили корабль лечь на обратный курс.$B$B$n, мы должны выяснить, что произошло. Ты не $gмог:могла; бы отправиться в порт Штормграда и расспросить о случившемся пассажиров?','Посетите порт Штормграда и поговорите с часовым Элорией, Лумианом Шепотом Звезд, Найетом Ледяной Луной и Финларом Туманным Странником.','Поговорите с Тандиэль Белой Луной в порту Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Gathering Evidence',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корабль под названием "Доблесть" перевозит пассажиров и грузы из Штормграда в деревню Рут\'теран, что за Дарнасом.$B$BТак вот, пассажиры и команда рассказывают, что воины Орды остановили "Доблесть" у Тельдрассила. Ордынцы украли часть груза, причинили зло пассажирам и вынудили корабль лечь на обратный курс.$B$B$n, мы должны выяснить, что произошло. Ты не $gмог:могла; бы отправиться в порт Штормграда и расспросить о случившемся пассажиров?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите порт Штормграда и поговорите с часовым Элорией, Лумианом Шепотом Звезд, Найетом Ледяной Луной и Финларом Туманным Странником.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тандиэль Белой Луной в порту Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29833,'Неоконченное дело','Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.$b$bБольшую часть крови Акали принял другой, и именно он представляет угрозу.$b$bВот что, $n, отправляйся в Гундрак и поговори с Тол\'маром. Он подскажет, что делать дальше.','Хар\'коа хочет, чтобы вы поговорили с Тол\'маром в Гундраке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, это правда: пророк Акали больше не потревожит этот мир, – однако нам предстоит еще многое сделать.$b$bБольшую часть крови Акали принял другой, и именно он представляет угрозу.$b$bВот что, $n, отправляйся в Гундрак и поговори с Тол\'маром. Он подскажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хар\'коа хочет, чтобы вы поговорили с Тол\'маром в Гундраке.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (29833,'Слушай сюда, подруга. Нужно будет сделать одну опасную работенку!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай сюда, подруга. Нужно будет сделать одну опасную работенку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29834,'Гал\'дара заплатит за все','Ничего ужаснее мои глаза не видели. Великий Акали был убит прямо у меня на глазах. Ужасно...$b$bМой удел – лишь наблюдать, но это нельзя так оставить! Гал\'дара и его сторонники должны заплатить за все!$b$bОтомсти за гибель Акали. Это будет доброе дело.','Тол\'мар хочет, чтобы вы убили в Гундраке Слад\'рана, Мураби и Гал\'дару.','Ты правда это сделал? Их больше нет?$B$BНу ты молодец! Вот, прими от меня этот дар. Ледяные пустоши благодарны тебе.','Вернитесь к Тол\'мару в Гундрак.','Предатель заслужил смерть!','Гал\'дара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гал\'дара заплатит за все',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничего ужаснее мои глаза не видели. Великий Акали был убит прямо у меня на глазах. Ужасно...$b$bМой удел – лишь наблюдать, но это нельзя так оставить! Гал\'дара и его сторонники должны заплатить за все!$b$bОтомсти за гибель Акали. Это будет доброе дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тол\'мар хочет, чтобы вы убили в Гундраке Слад\'рана, Мураби и Гал\'дару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты правда это сделал? Их больше нет?$B$BНу ты молодец! Вот, прими от меня этот дар. Ледяные пустоши благодарны тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тол\'мару в Гундрак.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предатель заслужил смерть!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гал\'дара',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29835,'Гал\'дара заплатит за все','Могучий Акали был убит, |3-6($r).$b$bМое призвание в этой жизни – писать историю, а не биться. Но это нельзя так оставить! Гал\'дара и его сторонники должны заплатить за все!$b$bОтомсти за гибель Акали. Это будет доброе дело.','Летописец Ба\'кини хочет, чтобы вы убили в Гундраке Слад\'рана, Мураби и Гал\'дару.','Вернитесь к летописцу Ба\'кини в Гундрак.','И помни – никакой пощады!','Гал\'дара') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гал\'дара заплатит за все',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могучий Акали был убит, |3-6($r).$b$bМое призвание в этой жизни – писать историю, а не биться. Но это нельзя так оставить! Гал\'дара и его сторонники должны заплатить за все!$b$bОтомсти за гибель Акали. Это будет доброе дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летописец Ба\'кини хочет, чтобы вы убили в Гундраке Слад\'рана, Мураби и Гал\'дару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу Ба\'кини в Гундрак.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','И помни – никакой пощады!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гал\'дара',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29836,'Просто проверка','Со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.$b$bОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?','То\'кини хочет, чтобы вы поговорили с Ба\'кини в Гундраке.','То\'кини – мой отец... Он оказался слишком труслив, чтобы так близко подойти к Гундраку, вот и послал меня!$B$BЗдесь очень много предметов, имеющих отношение к истории троллей. Мы не можем позволить Гал\'даре и его безумным последователям скрывать ее от нас!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просто проверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со стороны Гундрака постоянно доносится какой-то зловещий грохот. В последнее время – все громче и чаще.$b$bОдна моя давняя ученица ведет наблюдения на посту, расположенном к западу от Гундрака. Может быть, найдешь время, заглянешь к ней и проверишь, все ли у нее в порядке?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','То\'кини хочет, чтобы вы поговорили с Ба\'кини в Гундраке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То\'кини – мой отец... Он оказался слишком труслив, чтобы так близко подойти к Гундраку, вот и послал меня!$B$BЗдесь очень много предметов, имеющих отношение к истории троллей. Мы не можем позволить Гал\'даре и его безумным последователям скрывать ее от нас!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29837,'Священный свиток','Пергамент покрыт неведомыми изящными письменами, на которые вряд ли способны Йоггторд и его банда.$B$BВы подозреваете, что пергамент – как и почти все, чем хозены владеют, – краденый. $B$BВозможно, законный владелец все еще где-то рядом.','Отнесите покрытый неразборчивыми письменами свиток хранителю истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священный свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пергамент покрыт неведомыми изящными письменами, на которые вряд ли способны Йоггторд и его банда.$B$BВы подозреваете, что пергамент – как и почти все, чем хозены владеют, – краденый. $B$BВозможно, законный владелец все еще где-то рядом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый неразборчивыми письменами свиток хранителю истории Чо.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29838,'Единственный в своем роде','На первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bНо если все, что я слышала, правда, то они соорудили какого-то особенного голема – говорят, что таких еще не было!$b$bВот и принеси мне кусок этого самого голема – на предмет изучения.','Вернитесь к летописцу Ба\'кини в Гундрак.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единственный в своем роде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bНо если все, что я слышала, правда, то они соорудили какого-то особенного голема – говорят, что таких еще не было!$b$bВот и принеси мне кусок этого самого голема – на предмет изучения.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу Ба\'кини в Гундрак.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29839,'Единственный в своем роде','На первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bНо если все, что я слышала, правда, то они соорудили какого-то особенного голема – оживленного запретными чарами!$b$bПринеси мне кусок этого голема – может, мы чего и узнаем.','Тол\'мар хочет, чтобы вы достали обломок колосса Драккари в Гундраке.','Потрясающе! В жизни ничего такого не видал.$B$BОтличная работа, приятель.','Удалось найти голема? Наверняка он бродит где-то неподалеку.','Вернитесь к Тол\'мару в Гундрак.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Единственный в своем роде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На первый взгляд, вроде обычная история: тролли выпустили в мир запретные силы, уничтожив своих же богов, которым должны поклоняться.$b$bНо если все, что я слышала, правда, то они соорудили какого-то особенного голема – оживленного запретными чарами!$b$bПринеси мне кусок этого голема – может, мы чего и узнаем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тол\'мар хочет, чтобы вы достали обломок колосса Драккари в Гундраке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! В жизни ничего такого не видал.$B$BОтличная работа, приятель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти голема? Наверняка он бродит где-то неподалеку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тол\'мару в Гундрак.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29840,'Для наших потомков','Гундраку кранты. Нужно смотреть правде в глаза.$b$bЕсли тебе хватит смелости, разыщи таблички с летописями, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.$B$BМожет, однажды мы вернем этой земле ее былую славу.','Вернитесь к летописцу Ба\'кини в Гундрак.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для наших потомков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гундраку кранты. Нужно смотреть правде в глаза.$b$bЕсли тебе хватит смелости, разыщи таблички с летописями, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.$B$BМожет, однажды мы вернем этой земле ее былую славу.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к летописцу Ба\'кини в Гундрак.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29841,'Обстановка[TEMP]','Р-р-р!$B$BСтоит нам убить одну грязную тварь, как на ее место становятся две новые. Я не хочу говорить об этом остальным – но мне ясно, что долго мы не продержимся.$B$B$n, я останусь здесь защищать наше имущество, а ты отправляйся на разведку.$B$BПомоги нам справиться с этими приматами. На тебя вся надежда...','Проведите разведку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обстановка[TEMP]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Р-р-р!$B$BСтоит нам убить одну грязную тварь, как на ее место становятся две новые. Я не хочу говорить об этом остальным – но мне ясно, что долго мы не продержимся.$B$B$n, я останусь здесь защищать наше имущество, а ты отправляйся на разведку.$B$BПомоги нам справиться с этими приматами. На тебя вся надежда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите разведку.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29842,'В поисках ответов','<Чо стойко переносит поток ваших вопросов, перед тем как начать говорить.>$B$BТебе еще столько предстоит осмыслить, $gстранник:странница;...$B$BПрежде всего нужно научиться задавать правильные вопросы, до того как твой разум научится отличать правду от лжи.$B$BСегодня я уже достаточно медитировал, но мои свечи все еще в Круге Крови.$B$BИди туда. Очисти свой разум. Поговорим снова, когда ты будешь $gготов:готова; меня выслушать.','Зажгите свечи для медитации в Круге Крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках ответов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Чо стойко переносит поток ваших вопросов, перед тем как начать говорить.>$B$BТебе еще столько предстоит осмыслить, $gстранник:странница;...$B$BПрежде всего нужно научиться задавать правильные вопросы, до того как твой разум научится отличать правду от лжи.$B$BСегодня я уже достаточно медитировал, но мои свечи все еще в Круге Крови.$B$BИди туда. Очисти свой разум. Поговорим снова, когда ты будешь $gготов:готова; меня выслушать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите свечи для медитации в Круге Крови.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29843,'Тетушка Линь Воздушный Мех','Как только здесь все наладится, мы сразу же отправимся в город. И пусть кто-нибудь посмеет меня ослушаться – сразу получит по башке! Думаю, теперь у меня все будет хорошо.$B$BБольшое спасибо за помощь. Кстати, можешь заглянуть в Панда-таун и передать тетушке Линь Воздушный Мех, что у нас все в порядке? У нее полно замечательных вещиц, которыми она может тебя наградить.','Доберитесь до Панда-тауна и поговорите с Линь Воздушный Мех.','Поговорите с Линь Воздушный Мех в Панда-тауне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тетушка Линь Воздушный Мех',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только здесь все наладится, мы сразу же отправимся в город. И пусть кто-нибудь посмеет меня ослушаться – сразу получит по башке! Думаю, теперь у меня все будет хорошо.$B$BБольшое спасибо за помощь. Кстати, можешь заглянуть в Панда-таун и передать тетушке Линь Воздушный Мех, что у нас все в порядке? У нее полно замечательных вещиц, которыми она может тебя наградить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Панда-тауна и поговорите с Линь Воздушный Мех.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линь Воздушный Мех в Панда-тауне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29844,'Для наших потомков','Нынче земля ледяных троллей – лишь тень былого могущества.$b$bЕсли тебе хватит смелости, разыщи таблички с летописями, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.$B$BМожет, однажды новое поколение троллей вернет себе эту землю.','Тол\'мар из Гундрака хочет, чтобы вы собрали 6 табличек с летописями Драккари.','Нас, троллей, враги донимали с самых незапамятных времен. Многих рас тогда вообще даже не существовало.$B$BНо уничтожить нас не удавалось еще никому.','Вернитесь к Тол\'мару в Гундрак.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для наших потомков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нынче земля ледяных троллей – лишь тень былого могущества.$b$bЕсли тебе хватит смелости, разыщи таблички с летописями, которые дадут нам ответ на вопрос, что стало причиной падения империи Драккари.$B$BМожет, однажды новое поколение троллей вернет себе эту землю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тол\'мар из Гундрака хочет, чтобы вы собрали 6 табличек с летописями Драккари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нас, троллей, враги донимали с самых незапамятных времен. Многих рас тогда вообще даже не существовало.$B$BНо уничтожить нас не удавалось еще никому.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тол\'мару в Гундрак.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29845,'DEPRECATED: The Merchants\' Plight','Если король Ринн считает, что нападение на "Доблесть" – единичный случай, он сильно ошибается.$B$BПосмотри, сколько в порту разгневанных торговцев – все они не могут отправить деньги и товары в Калимдор. Если король не хочет слушать меня, то пусть хотя бы прислушается к ним.$B$B$n, поговори с торговцами – выслушай их жалобы и собери прошения, а затем возвращайся в крепость Штормграда.','Поговорите со злыми торговцами в порту Штормграда и соберите 7 прошений торговцев.','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: The Merchants\' Plight',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если король Ринн считает, что нападение на "Доблесть" – единичный случай, он сильно ошибается.$B$BПосмотри, сколько в порту разгневанных торговцев – все они не могут отправить деньги и товары в Калимдор. Если король не хочет слушать меня, то пусть хотя бы прислушается к ним.$B$B$n, поговори с торговцами – выслушай их жалобы и собери прошения, а затем возвращайся в крепость Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со злыми торговцами в порту Штормграда и соберите 7 прошений торговцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29846,'DEPRECATED: Captain Rufus Hardwick','Руфус Хардвик, этот капитан из Гилнеаса, был бы нам очень полезен.$B$BКоманде, как обычно, можно пообещать богатую добычу, но с капитаном этот номер не пройдет – ему нужна помощь в одном деликатном деле.$B$BНайди лавку алхимика и купи там разбавленную серу, экстракт кизила и смягчающий шампунь. Отнеси все это капитану, но смотри, не ляпни ничего такого, что поставило бы его в неловкое положение.$B$BКомандование флота на тебя рассчитывает.','Купите разбавленную серу, экстракт кизила и смягчающий шампунь в лавке алхимика в квартале Магов, а затем поговорите с капитаном Руфусом Хардвиком.','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Captain Rufus Hardwick',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руфус Хардвик, этот капитан из Гилнеаса, был бы нам очень полезен.$B$BКоманде, как обычно, можно пообещать богатую добычу, но с капитаном этот номер не пройдет – ему нужна помощь в одном деликатном деле.$B$BНайди лавку алхимика и купи там разбавленную серу, экстракт кизила и смягчающий шампунь. Отнеси все это капитану, но смотри, не ляпни ничего такого, что поставило бы его в неловкое положение.$B$BКомандование флота на тебя рассчитывает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите разбавленную серу, экстракт кизила и смягчающий шампунь в лавке алхимика в квартале Магов, а затем поговорите с капитаном Руфусом Хардвиком.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29847,'Поймать вора','Пройдя через эту пещеру, ты попадешь на территорию поместья Черного Ворона. Тебе нужно незаметно попасть внутрь!$B$B<Мостраз накладывает на вас некие чары.>$B$BВот. Теперь я смогу общаться с тобой, ну и наблюдать за твоими перемещениями по поместью. Итак, проникни в здание, найди яйцо – и не попадись...','Проникните в поместье Черного Ворона и найдите утерянное яйцо черного дракона.','Идите за Гневионом наверх и поговорите с ним в поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать вора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пройдя через эту пещеру, ты попадешь на территорию поместья Черного Ворона. Тебе нужно незаметно попасть внутрь!$B$B<Мостраз накладывает на вас некие чары.>$B$BВот. Теперь я смогу общаться с тобой, ну и наблюдать за твоими перемещениями по поместью. Итак, проникни в здание, найди яйцо – и не попадись...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в поместье Черного Ворона и найдите утерянное яйцо черного дракона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Идите за Гневионом наверх и поговорите с ним в поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29848,'Покинутый дозорный','Я бы с радостью отдал свою жизнь за Творцов или их созданий.$B$BНо после предательства Локена весь Ульдуар, похоже, ополчился на остальной мир. Дева Скорби, вынужденная исполнять свои новые приказы, невероятно страдает.$B$BПрошу тебя – даруй ей покой и принеси мне одну из ее слез.','Калдир Железоруб в Чертогах Камня попросил вас упокоить Деву Скорби и раздобыть Хрустальную слезу Горя.','Хотелось бы мне, чтобы был другой выход, но, похоже, смерть сейчас – единственное спасение для девы.','Вернитесь к Калдиру Железорубу в Чертоги Камня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покинутый дозорный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы с радостью отдал свою жизнь за Творцов или их созданий.$B$BНо после предательства Локена весь Ульдуар, похоже, ополчился на остальной мир. Дева Скорби, вынужденная исполнять свои новые приказы, невероятно страдает.$B$BПрошу тебя – даруй ей покой и принеси мне одну из ее слез.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Калдир Железоруб в Чертогах Камня попросил вас упокоить Деву Скорби и раздобыть Хрустальную слезу Горя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотелось бы мне, чтобы был другой выход, но, похоже, смерть сейчас – единственное спасение для девы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калдиру Железорубу в Чертоги Камня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29849,'DEPRECATED: Gunner Blastbarrel','Вторым кораблем управляет лучший дворф-пушкарь на свете – Ардан Взрывоствол. Если кто и умеет разносить в щепки корабли Орды, так это он со своей командой.$B$BЕго можно найти в Палатах Войны Стальгорна. Постарайся убедить Ардана присоединиться к нам.','Отправляйтесь в Стальгорн, там поговорите с Арданом Взрывостволом, а затем помогите ему собрать 6 членов экипажа.','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Gunner Blastbarrel',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вторым кораблем управляет лучший дворф-пушкарь на свете – Ардан Взрывоствол. Если кто и умеет разносить в щепки корабли Орды, так это он со своей командой.$B$BЕго можно найти в Палатах Войны Стальгорна. Постарайся убедить Ардана присоединиться к нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стальгорн, там поговорите с Арданом Взрывостволом, а затем помогите ему собрать 6 членов экипажа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29850,'Порченые создания','Железные дворфы занялись высечением из камня созданий, которых он вскоре смогут использовать в качестве могучего оружия.$B$BТебе нужно будет победить их надсмотрщика Кристаллуса и всех великанов клана Темных Рун, что попадутся тебе на глаза. Поспеши, пока не поздно!','Калдир Железоруб в Чертогах Камня попросил вас убить 3 великанов клана Темных Рун и Кристаллуса.','Вернитесь к Калдиру Железорубу в Чертоги Камня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порченые создания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железные дворфы занялись высечением из камня созданий, которых он вскоре смогут использовать в качестве могучего оружия.$B$BТебе нужно будет победить их надсмотрщика Кристаллуса и всех великанов клана Темных Рун, что попадутся тебе на глаза. Поспеши, пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Калдир Железоруб в Чертогах Камня попросил вас убить 3 великанов клана Темных Рун и Кристаллуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калдиру Железорубу в Чертоги Камня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (29851,'Чемпион Турнира','Этот турнир еще более приближает нас к последнему противостоянию с Королем-личом.$B$B$n, сражайся достойно и доблестно. Все бойцы, собравшиеся здесь, преследуют общую благородную цель.$B$BВместе мы остановим Артаса!','Верховный лорд Тирион Фордринг поручил вам пройти Испытание Воителя.','Я верю в тебя.','Верховный лорд Тирион Фордринг','Ты вселяешь в меня надежду на успех нашей кампании.','Верховный лорд Тирион Фордринг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чемпион Турнира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот турнир еще более приближает нас к последнему противостоянию с Королем-личом.$B$B$n, сражайся достойно и доблестно. Все бойцы, собравшиеся здесь, преследуют общую благородную цель.$B$BВместе мы остановим Артаса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный лорд Тирион Фордринг поручил вам пройти Испытание Воителя.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я верю в тебя.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный лорд Тирион Фордринг',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ты вселяешь в меня надежду на успех нашей кампании.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Верховный лорд Тирион Фордринг',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29852,'DEPRECATED: They Call Him Swifthands','Третий капер, которого нужно нанять, – капитан Саттон по прозвищу "Верткий". Если Взрывоствол без ума от пушек, то Саттон – легендарный мастер рукопашной.$B$BСкорее всего, Саттон сейчас ищет работу в порту Штормграда. Предупреждаю, он, вероятно, потребует от тебя выполнить какую-нибудь его просьбу.','Поговорите с капитаном "Вертким" Саттоном. Победите первого помощника Вильямса, чтобы убедить Саттона присоединиться к вам.','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: They Call Him Swifthands',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Третий капер, которого нужно нанять, – капитан Саттон по прозвищу "Верткий". Если Взрывоствол без ума от пушек, то Саттон – легендарный мастер рукопашной.$B$BСкорее всего, Саттон сейчас ищет работу в порту Штормграда. Предупреждаю, он, вероятно, потребует от тебя выполнить какую-нибудь его просьбу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном "Вертким" Саттоном. Победите первого помощника Вильямса, чтобы убедить Саттона присоединиться к вам.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному адмиралу Джес-Терет в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntargetname_loc8`) VALUES (29853,'Воитель Короля','Этот турнир еще более приближает нас к последнему противостоянию с Королем-личом.$B$B$n, ты будешь представлять на этой великой арене Альянс.$B$BДокажи лучшим воинам Азерота, чего ты стоишь. Бейся достойно.','Король Вариан Ринн поручил вам пройти Испытание Воителя.','Готовься.','Король Вариан Ринн','Король Вариан Ринн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воитель Короля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот турнир еще более приближает нас к последнему противостоянию с Королем-личом.$B$B$n, ты будешь представлять на этой великой арене Альянс.$B$BДокажи лучшим воинам Азерота, чего ты стоишь. Бейся достойно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король Вариан Ринн поручил вам пройти Испытание Воителя.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Готовься.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король Вариан Ринн',`questgivertargetname_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Король Вариан Ринн',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29854,'DEPRECATED: Claiming Kalimdor','Скоро мы одержим победу! Наши войска уже вступили в бой на всей территории Калимдора.$B$BПоэтому вождь Гаррош Адский Крик приказал, чтобы все |3-7($r), способные держать оружие, прибыли сюда и исполнили свой долг.$B$BИди в Оргриммар, в крепость Громмаш, и обратись к генералу Назгриму за распоряжениями. Да здравствует Орда!','Поговорите с генералом Назгримом, который находится в Оргриммаре, в крепости Громмаш.','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Claiming Kalimdor',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро мы одержим победу! Наши войска уже вступили в бой на всей территории Калимдора.$B$BПоэтому вождь Гаррош Адский Крик приказал, чтобы все |3-7($r), способные держать оружие, прибыли сюда и исполнили свой долг.$B$BИди в Оргриммар, в крепость Громмаш, и обратись к генералу Назгриму за распоряжениями. Да здравствует Орда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Назгримом, который находится в Оргриммаре, в крепости Громмаш.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29856,'Круг Кости','Вы чувствуете, как ваш разум прояснился.$B$BВам показалось, что ваше внимание было сосредоточено.$B$BВозможно, вас усыпило жужжание насекомых. Да, так и есть!$B$BКраем глаза вы замечаете, что чуть дальше к северу расположена еще одна группа камней.$B$BВозможно, там будет потише...','Зажгите свечу для медитации в Круге Кости.','Поговорите с Ка Пао в Круге Кости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг Кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы чувствуете, как ваш разум прояснился.$B$BВам показалось, что ваше внимание было сосредоточено.$B$BВозможно, вас усыпило жужжание насекомых. Да, так и есть!$B$BКраем глаза вы замечаете, что чуть дальше к северу расположена еще одна группа камней.$B$BВозможно, там будет потише...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите свечу для медитации в Круге Кости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ка Пао в Круге Кости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29857,'DEPRECATED: Where Are Those Ships?','Большая часть нашего флота ведет бои на море и атакует Терамор, и поэтому нам не хватает кораблей для полной блокады Калимдора.$B$BВождь приказал корабелам на заставе Зорам\'гар удвоить усилия, но пока мы не получили ни одного нового судна.$B$BОтправляйся туда и разыщи того, кто отвечает за их работу. Передай, что вождю нужны корабли!','Поговорите со смотрителем Моксом на заставе Зорам\'гар в Ясеневом лесу и уничтожьте 6 ночных эльфов-налетчиков на кораблях за пределами города.','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Where Are Those Ships?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть нашего флота ведет бои на море и атакует Терамор, и поэтому нам не хватает кораблей для полной блокады Калимдора.$B$BВождь приказал корабелам на заставе Зорам\'гар удвоить усилия, но пока мы не получили ни одного нового судна.$B$BОтправляйся туда и разыщи того, кто отвечает за их работу. Передай, что вождю нужны корабли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со смотрителем Моксом на заставе Зорам\'гар в Ясеневом лесу и уничтожьте 6 ночных эльфов-налетчиков на кораблях за пределами города.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29858,'Мудрость веков','$GНезнакомец:Незнакомка;, ты $gдолжен:должна; принимать выпавшие на твою долю испытания смиренно и непредвзято.$B$BЧерез прищуренный глаз скептика мудрость не проникнет.$B$BПриходи к Кругу Камня, и я обучу тебя древнему искусству медитации. $B$BКак только ты обретешь мир и покой, то, возможно, поймешь, что ответ все время был где-то рядом.','Поговорите с хранителем истории Чо у Круга Камня и займитесь медитацией.','Поговорите с хранителем истории Чо у Круга Камня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость веков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GНезнакомец:Незнакомка;, ты $gдолжен:должна; принимать выпавшие на твою долю испытания смиренно и непредвзято.$B$BЧерез прищуренный глаз скептика мудрость не проникнет.$B$BПриходи к Кругу Камня, и я обучу тебя древнему искусству медитации. $B$BКак только ты обретешь мир и покой, то, возможно, поймешь, что ответ все время был где-то рядом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо у Круга Камня и займитесь медитацией.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо у Круга Камня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29859,'DEPRECATED: Spies in Our Midst','Да что же это такое! Для захвата Калимдора вождю нужны корабли!$B$BКак, интересно, ночные эльфы узнали о нашем новом флоте? Каким образом они его уничтожили? Ответ только один...$B$B$n, в Оргриммаре у врага есть глаза и уши, так что наша задача – искоренить вражеских шпионов. Беллок Сияющий Клинок передал мне один инструмент – по его словам, он помогает выявлять шпионов.$B$BБери инструмент и действуй, но полагайся не только на него, но и на здравый смысл.','Беседуя с подозрительными горожанами, выявите и ликвидируйте 6 ночных эльфов-шпионов.','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Spies in Our Midst',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да что же это такое! Для захвата Калимдора вождю нужны корабли!$B$BКак, интересно, ночные эльфы узнали о нашем новом флоте? Каким образом они его уничтожили? Ответ только один...$B$B$n, в Оргриммаре у врага есть глаза и уши, так что наша задача – искоренить вражеских шпионов. Беллок Сияющий Клинок передал мне один инструмент – по его словам, он помогает выявлять шпионов.$B$BБери инструмент и действуй, но полагайся не только на него, но и на здравый смысл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Беседуя с подозрительными горожанами, выявите и ликвидируйте 6 ночных эльфов-шпионов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29860,'Диаметральные противоположности','Я скажу тебе прямо, $gмаленький:маленькая:r; |3-6($r) – с тех пор, как наши связи с Торимом были разорваны, мой народ стал другим.$b$bВолхан не успокоится, пока не умрет сам или не покончит с нами. Мы хотим мира, но, боюсь, у нас сейчас нет иного выбора, кроме как воевать.','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы победили Волхана.','Вернитесь к штормовестнику Элдррину в Чертоги Молний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диаметральные противоположности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я скажу тебе прямо, $gмаленький:маленькая:r; |3-6($r) – с тех пор, как наши связи с Торимом были разорваны, мой народ стал другим.$b$bВолхан не успокоится, пока не умрет сам или не покончит с нами. Мы хотим мира, но, боюсь, у нас сейчас нет иного выбора, кроме как воевать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы победили Волхана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штормовестнику Элдррину в Чертоги Молний.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29861,'Любой ценой!','Локен в любом случае должен умереть.$b$bДумаю, ты $gзаслужил:заслужила; честь сразить его своей рукой.$b$bПринеси мне его лживый язык – и заслужишь мою глубочайшую признательность.','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы победили Локена и принесли ему язык Локена.','Ты свершил правосудие над Локеном?','Вернитесь к штормовестнику Элдррину в Чертоги Молний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любой ценой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Локен в любом случае должен умереть.$b$bДумаю, ты $gзаслужил:заслужила; честь сразить его своей рукой.$b$bПринеси мне его лживый язык – и заслужишь мою глубочайшую признательность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы победили Локена и принесли ему язык Локена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты свершил правосудие над Локеном?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штормовестнику Элдррину в Чертоги Молний.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29862,'Расчистка пути','Армии Локена готовятся к войне. Но вот чего они точно не ожидают, так это того, что кто-то нападет на них самих.$B$BНастало время нанести им удар. Уничтожь генерала Бьярнгрима и его армию, пока они не перешли в наступление!','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы убили 3 лекарей и 3 тактиков клана Закаленных Бурей, а также генерала Бьярнгрима.','Вернитесь к штормовестнику Элдррину в Чертоги Молний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расчистка пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армии Локена готовятся к войне. Но вот чего они точно не ожидают, так это того, что кто-то нападет на них самих.$B$BНастало время нанести им удар. Уничтожь генерала Бьярнгрима и его армию, пока они не перешли в наступление!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Штормовестник Элдррин в Чертогах Молний хочет, чтобы вы убили 3 лекарей и 3 тактиков клана Закаленных Бурей, а также генерала Бьярнгрима.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штормовестнику Элдррину в Чертоги Молний.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29863,'Штормовестник Элдррин','Я отправил в Чертоги Молний своего посланника с заданием дать бой Локену.$B$BЕму определенно понадобится помощь – армия Локена очень сильна. Помоги ему всем, чем сможешь. Мы должны любой ценой остановить предателя.','Король Йоккум хочет, чтобы вы отправились в Чертоги Молний и поговорили со штормовестником Элдррином.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штормовестник Элдррин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправил в Чертоги Молний своего посланника с заданием дать бой Локену.$B$BЕму определенно понадобится помощь – армия Локена очень сильна. Помоги ему всем, чем сможешь. Мы должны любой ценой остановить предателя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Король Йоккум хочет, чтобы вы отправились в Чертоги Молний и поговорили со штормовестником Элдррином.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29864,'Работа с первоисточником','Мы делаем все возможное, чтобы минимизировать свои потери в нашей борьбе с Плетью.$B$BК сожалению, врайкулы, добровольно присоединяющиеся к войску Короля-лича, сводят на нет все наши старания.$B$BПрошу тебя, $gхрабрый воитель:храбрая воительница; – уничтожь их духовную наставницу Свалу, пока она не увела за собой в царство вечной тени весь свой народ!','Исповедница Серебряного Авангарда Пейлтресс поручила вам убить Свалу Вечноскорбящую.','С каждым солдатом, которого недосчиталась Плеть, мы спасаем жизнь, и не одну.$B$BСпасибо тебе.','Вернитесь к образу исповедницы Серебряного Авангарда Пейлтресс на Вершину Утгард.','Наша боль для нее – блаженство.','Свала Вечноскорбящая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа с первоисточником',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы делаем все возможное, чтобы минимизировать свои потери в нашей борьбе с Плетью.$B$BК сожалению, врайкулы, добровольно присоединяющиеся к войску Короля-лича, сводят на нет все наши старания.$B$BПрошу тебя, $gхрабрый воитель:храбрая воительница; – уничтожь их духовную наставницу Свалу, пока она не увела за собой в царство вечной тени весь свой народ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исповедница Серебряного Авангарда Пейлтресс поручила вам убить Свалу Вечноскорбящую.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С каждым солдатом, которого недосчиталась Плеть, мы спасаем жизнь, и не одну.$B$BСпасибо тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к образу исповедницы Серебряного Авангарда Пейлтресс на Вершину Утгард.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Наша боль для нее – блаженство.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Свала Вечноскорбящая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29865,'Дорога Шелкодревного леса','К западу отсюда проходит дорога Шелкодревного леса. С тех пор как на ней поселились пауки, она превратилась в смертельную ловушку для путешественников.$B$BЯ бы сам справился с этими тварями, но кто-то должен оберегать харчевню от... м-м-м... опасностей там всяких...$B$BИди же, герой, и одолей этих чудовищ! Если победишь, то я, возможно, поведаю тебе об одном из моих великих подвигов.$B$BНу и еще заплачу.','Победите 8 охотников Шелкодревного леса.','Сколько величия и благородства. Напоминаешь меня в молодости, только не так красив.','Поговорите с Тцзу Железным Брюхом в Цветущей Заре, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога Шелкодревного леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу отсюда проходит дорога Шелкодревного леса. С тех пор как на ней поселились пауки, она превратилась в смертельную ловушку для путешественников.$B$BЯ бы сам справился с этими тварями, но кто-то должен оберегать харчевню от... м-м-м... опасностей там всяких...$B$BИди же, герой, и одолей этих чудовищ! Если победишь, то я, возможно, поведаю тебе об одном из моих великих подвигов.$B$BНу и еще заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 8 охотников Шелкодревного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сколько величия и благородства. Напоминаешь меня в молодости, только не так красив.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тцзу Железным Брюхом в Цветущей Заре, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29866,'Липкие нити','А, добро пожаловать, $gпутник:путница;! Я хочу попросить тебя об услуге.$b$bСире Золотистый Нектар нужен шелк. Лично я его ненавижу, ведь он вечно застревает в шерсти.$b$bНо я так хочу произвести на нее впечатление!$b$bЕсли принесешь мне шелка из Шелкодревного леса, что к западу отсюда, я с радостью заплачу тебе за помощь.','Соберите 7 безупречных шелковых нитей.','Спасибо! О, это превосходно!$B$BНадеюсь, нити не очень на тебя липли?$B$BЯ сейчас же отдам это Сире!','Поговорите с Ло Бродячим Бражником в Цветущей Заре, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Липкие нити',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, добро пожаловать, $gпутник:путница;! Я хочу попросить тебя об услуге.$b$bСире Золотистый Нектар нужен шелк. Лично я его ненавижу, ведь он вечно застревает в шерсти.$b$bНо я так хочу произвести на нее впечатление!$b$bЕсли принесешь мне шелка из Шелкодревного леса, что к западу отсюда, я с радостью заплачу тебе за помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 безупречных шелковых нитей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! О, это превосходно!$B$BНадеюсь, нити не очень на тебя липли?$B$BЯ сейчас же отдам это Сире!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ло Бродячим Бражником в Цветущей Заре, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29867,'DEPRECATED: Shadow Hunter Urko\'jin','Нам нужно усилить флот новыми кораблями, прежде чем ночные эльфы вновь раскинут свою шпионскую сеть в городе.$B$BЧерные Копья еще не внесли свой вклад в общее дело, но все изменится, если мы убедим присоединиться к нам темного охотника Урко\'джина.$B$BОднако Урко\'джин вступит в войну только в том случае, если получит благословение духов. Посети крепость Черного Копья на Островах Эха, забери тотем мореплавания и доставь его Урко\'джину в Аллею Духов.','Найдите тотем мореплавания на Островах Эха в крепости Черного Копья, а затем доставьте его в Аллею Духов в Оргриммаре и отдайте темному охотнику Урко\'джину.','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Shadow Hunter Urko\'jin',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно усилить флот новыми кораблями, прежде чем ночные эльфы вновь раскинут свою шпионскую сеть в городе.$B$BЧерные Копья еще не внесли свой вклад в общее дело, но все изменится, если мы убедим присоединиться к нам темного охотника Урко\'джина.$B$BОднако Урко\'джин вступит в войну только в том случае, если получит благословение духов. Посети крепость Черного Копья на Островах Эха, забери тотем мореплавания и доставь его Урко\'джину в Аллею Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тотем мореплавания на Островах Эха в крепости Черного Копья, а затем доставьте его в Аллею Духов в Оргриммаре и отдайте темному охотнику Урко\'джину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29868,'DEPRECATED: Captain Cartheron','Нам нужны новые корабли – и, к счастью, я знаю одного эльфа, к которому можно за этим обратиться.$B$BЕго зовут капитан Картерон, во всей Орде не найти таких опытных моряков, как у него. Но беда в том, что за свои услуги Картерон потребует плату вперед.$B$BНеси свои деньги в Северные Степи – в Кабестан – и узнай, какой аванс необходимо заплатить капитану Картерону и сколько всего он захочет получить.','Отправляйтесь в Северные Степи, в Кабестан; поговорите там с капитаном Картероном и предложите ему аванс – 100 золотых.','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: Captain Cartheron',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужны новые корабли – и, к счастью, я знаю одного эльфа, к которому можно за этим обратиться.$B$BЕго зовут капитан Картерон, во всей Орде не найти таких опытных моряков, как у него. Но беда в том, что за свои услуги Картерон потребует плату вперед.$B$BНеси свои деньги в Северные Степи – в Кабестан – и узнай, какой аванс необходимо заплатить капитану Картерону и сколько всего он захочет получить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Северные Степи, в Кабестан; поговорите там с капитаном Картероном и предложите ему аванс – 100 золотых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Громмаш в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29869,'Аплодисменты одной ладонью','Тебе еще многое предстоит узнать, но ты уже стоишь на пути к просветлению.$B$BВспомни все, чему я тебя учил, и отправляйся к озеру на западе.$B$BТерпение и постоянные тренировки даруют тебе гармонию и просветление, а затем ты обретешь и мудрость.$B$BИ кстати, моим занятиям больше не будет мешать твой храп.$B$BПрощай.','Помедитируйте в Круге Чешуи.','Найдите целый кувшин у Круга Чешуи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аплодисменты одной ладонью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе еще многое предстоит узнать, но ты уже стоишь на пути к просветлению.$B$BВспомни все, чему я тебя учил, и отправляйся к озеру на западе.$B$BТерпение и постоянные тренировки даруют тебе гармонию и просветление, а затем ты обретешь и мудрость.$B$BИ кстати, моим занятиям больше не будет мешать твой храп.$B$BПрощай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помедитируйте в Круге Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите целый кувшин у Круга Чешуи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29871,'Мудрый Асе','Не знаю, с чего вдруг Асе прозвали "Мудрым". Все цзинь-юй мудрые, и вряд ли он умнее остальных.$b$bСкорее наоборот.$b$bПо крайней мере он хороший воин. Неплохо показал себя в монастыре Тянь. Вот поэтому мы и выбрали его для этого задания.$b$bЕсли хочешь помочь ему в поисках тайного мастера, разыщи его на северной границе долины.','Найдите Мудрого Асе.','Мы раньше не встречались?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрый Асе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, с чего вдруг Асе прозвали "Мудрым". Все цзинь-юй мудрые, и вряд ли он умнее остальных.$b$bСкорее наоборот.$b$bПо крайней мере он хороший воин. Неплохо показал себя в монастыре Тянь. Вот поэтому мы и выбрали его для этого задания.$b$bЕсли хочешь помочь ему в поисках тайного мастера, разыщи его на северной границе долины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мудрого Асе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы раньше не встречались?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29872,'Линь Мягкая Лапа','Линь талантливее, чем ей кажется. Кулаки у нее крепкие, но дух слаб. Однако если вселить в нее уверенность, она превзойдет всех нас.$b$bВозможно, Линь поверит в себя во время путешествия на запад – уже сейчас она направляется в сторону Каменного Плуга. Если встретишь ее, поговори с ней.','Найдите Линь Мягкую Лапу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Линь Мягкая Лапа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Линь талантливее, чем ей кажется. Кулаки у нее крепкие, но дух слаб. Однако если вселить в нее уверенность, она превзойдет всех нас.$b$bВозможно, Линь поверит в себя во время путешествия на запад – уже сейчас она направляется в сторону Каменного Плуга. Если встретишь ее, поговори с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Линь Мягкую Лапу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (29873,'Кен-Кен','Найдите Кен-Кена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кен-Кен',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кен-Кена.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29874,'Кан Ежевичный Посох','Гордость Кана то и дело перерастает в излишнюю самоуверенность, из-за чего он часто ступает на опасный путь. И сегодняшний его маршрут не лучше – он идет в Красарангские джунгли.$b$bОбычно я не прошу странников об одолжении, но... не проверишь, как он там? Мне будет спокойнее, если за ним присмотрит $gотважный:отважная:r; |3-6($r).','Разыщите Кана Ежевичного Посоха.','Уверен, еще несколько недель назад этого поселения тут не было. Откуда они пришли?','Найдите Кана Ежевичного Посоха в Экспедиции ночных эльфов в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кан Ежевичный Посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гордость Кана то и дело перерастает в излишнюю самоуверенность, из-за чего он часто ступает на опасный путь. И сегодняшний его маршрут не лучше – он идет в Красарангские джунгли.$b$bОбычно я не прошу странников об одолжении, но... не проверишь, как он там? Мне будет спокойнее, если за ним присмотрит $gотважный:отважная:r; |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кана Ежевичного Посоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверен, еще несколько недель назад этого поселения тут не было. Откуда они пришли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Кана Ежевичного Посоха в Экспедиции ночных эльфов в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29875,'Кан Ежевичный Посох','Гордость Кана то и дело перерастает в излишнюю самоуверенность, из-за чего он часто ступает на опасный путь. И сегодняшний его маршрут не лучше – он идет в Красарангские джунгли.$b$bОбычно я не прошу странников об одолжении, но... не проверишь, как он там? Мне будет спокойнее, если за ним присмотрит $gотважный:отважная:r; |3-6($r).','Разыщите Кана Ежевичного Посоха.','Уверен, еще несколько недель назад этого поселения тут не было. Откуда они пришли?','Найдите Кана Ежевичного Посоха в Громовой Расселине в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кан Ежевичный Посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гордость Кана то и дело перерастает в излишнюю самоуверенность, из-за чего он часто ступает на опасный путь. И сегодняшний его маршрут не лучше – он идет в Красарангские джунгли.$b$bОбычно я не прошу странников об одолжении, но... не проверишь, как он там? Мне будет спокойнее, если за ним присмотрит $gотважный:отважная:r; |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кана Ежевичного Посоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверен, еще несколько недель назад этого поселения тут не было. Откуда они пришли?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Кана Ежевичного Посоха в Громовой Расселине в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (29876,'DEPRECATED: The Third Captain') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED: The Third Captain',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29877,'Пробелы в образовании','Гну-синь пожирать наши припасы. Гну-синь сам пытаться стать фермером. Только они совсем туп-тупик...$b$bНе веришь Муно? Прошлой ночью они взломать сарай и утащить инструменты. Мы просыпаться и видеть – грабли, тачки в землю вкопать.$b$bГну-синь их ПОЛИВАЛИ. Хотеть вырастить ТАЧКИ.$b$bПожалуйста, верни добро.','Выкопайте 7 сельскохозяйственных инструментов.','Спасибо, друг. Теперь хозен может спокойнецко поработай.','Вернитесь к батраку Муно в Усадьбу Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробелы в образовании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гну-синь пожирать наши припасы. Гну-синь сам пытаться стать фермером. Только они совсем туп-тупик...$b$bНе веришь Муно? Прошлой ночью они взломать сарай и утащить инструменты. Мы просыпаться и видеть – грабли, тачки в землю вкопать.$b$bГну-синь их ПОЛИВАЛИ. Хотеть вырастить ТАЧКИ.$b$bПожалуйста, верни добро.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выкопайте 7 сельскохозяйственных инструментов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, друг. Теперь хозен может спокойнецко поработай.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к батраку Муно в Усадьбу Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29878,'Идеальная ловушка для хозенов','Одно становится предельно ясно: хозены обожают "грязней".$B$BПока вы были в медитативном трансе, перед вашими глазами прошла вереница разрозненных изображений и образов. И сейчас, придя в себя, вы пытаетесь осознать свои видения.$B$BВ вашей голове начинает складываться невероятный, нелепый план. Он совершенно безумен, но, быть может, именно поэтому он и сработает...','Добудьте 8 грязней и 8 целых кувшинов из озера Киттитата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная ловушка для хозенов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одно становится предельно ясно: хозены обожают "грязней".$B$BПока вы были в медитативном трансе, перед вашими глазами прошла вереница разрозненных изображений и образов. И сейчас, придя в себя, вы пытаетесь осознать свои видения.$B$BВ вашей голове начинает складываться невероятный, нелепый план. Он совершенно безумен, но, быть может, именно поэтому он и сработает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 грязней и 8 целых кувшинов из озера Киттитата.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29879,'Проглоченные заживо','Что ж, вернемся к твоей дилемме.$b$bДумаю, с твоей помощью вам удастся наладить отношения с хозенами, как удалось это нам.$b$bТропа за моей спиной приведет тебя к водоему, в котором хозены ловят рыбу себе на пропитание.$b$bКаждый год примерно в это время ужасные твари поселяются в этих водах, и много голодных хозенов пропадает бесследно.$b$bЕсли тебе удастся спасти несколько жертв и наловить рыбы, думаю, к вам станут относиться благосклоннее.','Освободите 5 хозенов от разжиревших кроколисков и поймайте в озере Киттитата 5 грязней.','Шнуропс спасай хозен? И приноси грязни?$B$BХм-м, может, шнуропс и не сильно плохой.$B$BТуки-Туки все равно никогда не любить Дук Укем...','У шнуропса грязни... для моя?','Поговорите с Туки-Туки в Нука-Нука.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проглоченные заживо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, вернемся к твоей дилемме.$b$bДумаю, с твоей помощью вам удастся наладить отношения с хозенами, как удалось это нам.$b$bТропа за моей спиной приведет тебя к водоему, в котором хозены ловят рыбу себе на пропитание.$b$bКаждый год примерно в это время ужасные твари поселяются в этих водах, и много голодных хозенов пропадает бесследно.$b$bЕсли тебе удастся спасти несколько жертв и наловить рыбы, думаю, к вам станут относиться благосклоннее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 хозенов от разжиревших кроколисков и поймайте в озере Киттитата 5 грязней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шнуропс спасай хозен? И приноси грязни?$B$BХм-м, может, шнуропс и не сильно плохой.$B$BТуки-Туки все равно никогда не любить Дук Укем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У шнуропса грязни... для моя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Туки-Туки в Нука-Нука.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29880,'Поймал – отпусти!','Раскладывая рыбу по кувшинам, вы приободряетесь.$B$BПлан может сработать! В идеале "спасенные" хозены должны изменить свое отношение к вам в лучшую сторону. $B$BПора расставлять наживку.','Используйте ловушки для хозенов в лагере Нука-Нука, а затем сломайте их, чтобы освободить 5 хозенов.','Поговорите с вождем Туки-Туки в лагере Нука-Нука.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймал – отпусти!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раскладывая рыбу по кувшинам, вы приободряетесь.$B$BПлан может сработать! В идеале "спасенные" хозены должны изменить свое отношение к вам в лучшую сторону. $B$BПора расставлять наживку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ловушки для хозенов в лагере Нука-Нука, а затем сломайте их, чтобы освободить 5 хозенов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Туки-Туки в лагере Нука-Нука.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29881,'Идеальный цвет','Как видишь, в роще множество прекрасных розовых цветов. Когда цветок отцвел, его лепестки темнеют и опадают.$B$BЕсли ты будешь так $gлюбезен:любезна;... Мне нужно несколько лепестков, которые только что опали – только у них есть тот оттенок, который я ищу.$B$BИз них получатся чернила небывалой красоты! Поможешь мне набрать их?','Соберите 8 свежеопавших лепестков.','О, у тебя прекрасное чувство цвета! Из этого получится великолепный краситель.','Есть лишь небольшой промежуток времени, после того как опавший лист может быть использован для получения идеального оттенка.','Вернитесь к мастеру каллиграфии Глень-цзу в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальный цвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как видишь, в роще множество прекрасных розовых цветов. Когда цветок отцвел, его лепестки темнеют и опадают.$B$BЕсли ты будешь так $gлюбезен:любезна;... Мне нужно несколько лепестков, которые только что опали – только у них есть тот оттенок, который я ищу.$B$BИз них получатся чернила небывалой красоты! Поможешь мне набрать их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 свежеопавших лепестков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, у тебя прекрасное чувство цвета! Из этого получится великолепный краситель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть лишь небольшой промежуток времени, после того как опавший лист может быть использован для получения идеального оттенка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру каллиграфии Глень-цзу в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29882,'Перья из жал','Изящества линий можно добиться только с помощью подходящих инструментов. А мои кисти совсем испортились – щетинки сбились в клочья и колтуны, словно шерсть хозенов. $B$BТебе когда-нибудь приходилось бывать в Дендрарии? Там живут осы, из жал которых выходят отличные перья! Тонкость и четкость линий получается изумительная!$B$BТы не $gмог:могла; бы набрать для меня этих жал?','Соберите 6 осиных жал, убивая садовых ос.','Спасибо, путник. Из этих жал получатся замечательные перья. Вот, возьми за труды.','Тебе удалось набрать жал? Обычно я прошу об этом кого-нибудь из монахов, но они все куда-то подевались.','Поговорите с каллиграфом Цзо По в Дендрарии, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья из жал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изящества линий можно добиться только с помощью подходящих инструментов. А мои кисти совсем испортились – щетинки сбились в клочья и колтуны, словно шерсть хозенов. $B$BТебе когда-нибудь приходилось бывать в Дендрарии? Там живут осы, из жал которых выходят отличные перья! Тонкость и четкость линий получается изумительная!$B$BТы не $gмог:могла; бы набрать для меня этих жал?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 осиных жал, убивая садовых ос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, путник. Из этих жал получатся замечательные перья. Вот, возьми за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось набрать жал? Обычно я прошу об этом кого-нибудь из монахов, но они все куда-то подевались.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с каллиграфом Цзо По в Дендрарии, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29883,'Доверие Жемчужного Плавника','Я тут подумал.$b$bПоддержки у нас нет, и мы находимся ужасно далеко от дома.$b$bИ хотя эти цзинь-юй нам не доверяют, я не чувствую в них враждебности.$b$bИ если бы мы смогли убедить их в наших дружественных намерениях, заключенный между нашими расами союз мог бы оказаться весьма полезным.$b$b$n, ты $gдолжен:должна; поговорить с цзинь-юй, живущими в деревне.$b$bУбеди их вождей, что нас не стоит бояться, что мы хотим только мира.','Поговорите со старейшиной Лушанем, хранителем жемчужин Фуцзинем, инструктором Острым Гребнем и От-Теммдо в деревне Жемчужного Плавника.','Похоже, тебе удалось произвести очень неплохое впечатление.$B$BОтличная работа, Лайрим!','Вернитесь к Реллу Ночному Ветру в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доверие Жемчужного Плавника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут подумал.$b$bПоддержки у нас нет, и мы находимся ужасно далеко от дома.$b$bИ хотя эти цзинь-юй нам не доверяют, я не чувствую в них враждебности.$b$bИ если бы мы смогли убедить их в наших дружественных намерениях, заключенный между нашими расами союз мог бы оказаться весьма полезным.$b$b$n, ты $gдолжен:должна; поговорить с цзинь-юй, живущими в деревне.$b$bУбеди их вождей, что нас не стоит бояться, что мы хотим только мира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Лушанем, хранителем жемчужин Фуцзинем, инструктором Острым Гребнем и От-Теммдо в деревне Жемчужного Плавника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, тебе удалось произвести очень неплохое впечатление.$B$BОтличная работа, Лайрим!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реллу Ночному Ветру в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29884,'Выслеживание: разведчики уходят','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.','Проводите разведчиков, затем поговорите с Большим Лу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: разведчики уходят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите разведчиков, затем поговорите с Большим Лу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29885,'Провиант в дорогу','Мы не можем ждать, пока адмирал поправится.$b$bМы с Салли собираемся отправиться на север на поиски Андуина, но для этого нам нужна провизия.$b$bМестное озеро кишит разной живностью, и у нас есть разрешение на ловлю.$b$bОтправляйся на озеро и добудь что-нибудь, пока мы с Салли занимаемся последними приготовлениями.','Достаньте 6 черепашьих боков.','Этого будет достаточно. Спасибо, Лайрим.','Время не ждет. С каждой минутой Белая Пешка все дальше от нас.$B$BГде припасы, о которых я просил?','Вернитесь к Реллу Ночному Ветру в Деревню Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провиант в дорогу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем ждать, пока адмирал поправится.$b$bМы с Салли собираемся отправиться на север на поиски Андуина, но для этого нам нужна провизия.$b$bМестное озеро кишит разной живностью, и у нас есть разрешение на ловлю.$b$bОтправляйся на озеро и добудь что-нибудь, пока мы с Салли занимаемся последними приготовлениями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 6 черепашьих боков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого будет достаточно. Спасибо, Лайрим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время не ждет. С каждой минутой Белая Пешка все дальше от нас.$B$BГде припасы, о которых я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реллу Ночному Ветру в Деревню Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29886,'Лечение по дзену','Твой друг Тейлор в критическом состоянии. К сожалению, его раны заражены ядом хозенов, справиться с которым очень сложно.$B$BК счастью, наш народ так давно борется с хозенами, что у нас есть целебные снадобья для лечения подобных ран.$b$bИз цветов, которые растут в водах Стеклянного озера, можно приготовить противоядие.$b$b$n, быстрее иди к озеру и собери несколько цветков. От этого зависит жизнь адмирала.','Соберите 6 дзен-лотосов.','Вернитесь к Мишке в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лечение по дзену',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой друг Тейлор в критическом состоянии. К сожалению, его раны заражены ядом хозенов, справиться с которым очень сложно.$B$BК счастью, наш народ так давно борется с хозенами, что у нас есть целебные снадобья для лечения подобных ран.$b$bИз цветов, которые растут в водах Стеклянного озера, можно приготовить противоядие.$b$b$n, быстрее иди к озеру и собери несколько цветков. От этого зависит жизнь адмирала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 дзен-лотосов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29887,'Имущество старейшины','О нет, только не это... Если об этом узнает старейшина!..$B$BКажется, когда я спасался бегством, то не взял с собой церемониальные принадлежности.$b$bНо... Сейчас в Приюте Лунной Воды полно хозенов!$b$bЧто же я за хранитель жемчужин, если был таким беспечным!$b$b<Старик цзинь-юй прячет лицо в ладонях.>$b$bНе будешь ли ты так $gдобр:добра; помочь мне разыскать их?','Заберите у грабителей из племени Ловкого Хвоста церемониальное облачение, нефритовую корону, четки из розового дерева и посох говорящего с водой.','Старейшина – говорящий с водой. Он беседует с водой, и она ему отвечает.','Вернитесь к хранителю жемчужин Фуцзиню в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имущество старейшины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О нет, только не это... Если об этом узнает старейшина!..$B$BКажется, когда я спасался бегством, то не взял с собой церемониальные принадлежности.$b$bНо... Сейчас в Приюте Лунной Воды полно хозенов!$b$bЧто же я за хранитель жемчужин, если был таким беспечным!$b$b<Старик цзинь-юй прячет лицо в ладонях.>$b$bНе будешь ли ты так $gдобр:добра; помочь мне разыскать их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у грабителей из племени Ловкого Хвоста церемониальное облачение, нефритовую корону, четки из розового дерева и посох говорящего с водой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Старейшина – говорящий с водой. Он беседует с водой, и она ему отвечает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю жемчужин Фуцзиню в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29888,'В поисках хранителя истории','Вижу, ты и твои соратники уже отчаялись найти принца Андуина.$B$BЯ знаю того, кто сможет вам помочь – это пандарен, хранитель истории, он знает эти края лучше, чем кто бы то ни было. Не поручусь за теплый прием, но вы, безусловно, заинтересуете друг друга.$B$BОн живет в лесу к юго-западу отсюда. Найди его и скажи, что ты от Жемчужного Плавника.','Разыщите хранителя истории Чо в Павильоне Мечтателя, что в Нефритовом лесу.','Вы осматриваете пустой дом.$B$BПохоже, вы пришли туда, куда нужно, однако хозяина нигде не видно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках хранителя истории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты и твои соратники уже отчаялись найти принца Андуина.$B$BЯ знаю того, кто сможет вам помочь – это пандарен, хранитель истории, он знает эти края лучше, чем кто бы то ни было. Не поручусь за теплый прием, но вы, безусловно, заинтересуете друг друга.$B$BОн живет в лесу к юго-западу отсюда. Найди его и скажи, что ты от Жемчужного Плавника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите хранителя истории Чо в Павильоне Мечтателя, что в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы осматриваете пустой дом.$B$BПохоже, вы пришли туда, куда нужно, однако хозяина нигде не видно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29889,'Позаимствованный напиток','На столе стоит бутылка, от которой исходит восхитительный аромат.$B$BОдин глоточек вам не повредит, верно?','Попробуйте соблазнительный напиток.','Я слышал, что ваш народ прибило к нашим берегам, но не думал, что кого-то принесло прямо к моей двери! Что привело тебя сюда, чужестранец?$B$B<Вы объясняете, что ищете принца Андуина и описываете его пандарену>$B$BОчень интересно! А тебя ко мне послали жители Жемчужного Плавника, да?','Поговорите с хранителем истории Чо в Павильоне Мечтателя в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позаимствованный напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На столе стоит бутылка, от которой исходит восхитительный аромат.$B$BОдин глоточек вам не повредит, верно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попробуйте соблазнительный напиток.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал, что ваш народ прибило к нашим берегам, но не думал, что кого-то принесло прямо к моей двери! Что привело тебя сюда, чужестранец?$B$B<Вы объясняете, что ищете принца Андуина и описываете его пандарену>$B$BОчень интересно! А тебя ко мне послали жители Жемчужного Плавника, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Павильоне Мечтателя в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29890,'Равновесие внутри себя','Хмель глубоких раздумий готов! В этот раз, когда выпьешь его, постарайся понять свои видения, находясь в состоянии внутреннего сосредоточения.$b$bПойдем в пагоду, я научу тебя, как достичь внутреннего спокойствия, которое так ценят пандарены.$b$bТвой взбаламученный разум будет тебя отвлекать, но твоя задача – не терять концентрации.','Медитируйте вместе с хранителем истории Чо в пагоде, которая находится в Павильоне Мечтателя, что в Нефритовом лесу.','Найдите Андуина Ринна в Логове Печали, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Равновесие внутри себя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмель глубоких раздумий готов! В этот раз, когда выпьешь его, постарайся понять свои видения, находясь в состоянии внутреннего сосредоточения.$b$bПойдем в пагоду, я научу тебя, как достичь внутреннего спокойствия, которое так ценят пандарены.$b$bТвой взбаламученный разум будет тебя отвлекать, но твоя задача – не терять концентрации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Медитируйте вместе с хранителем истории Чо в пагоде, которая находится в Павильоне Мечтателя, что в Нефритовом лесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Андуина Ринна в Логове Печали, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29891,'Крепость','Для создания хмеля глубоких раздумий требуется несколько ингредиентов.$B$BПрежде всего нужно придать ему крепость, а для этого мне понадобится сердце жуткого монстра – легендарного Туманного ужаса.$B$BГоворят, такие существа водятся только в самом густом тумане.$B$BК северу и к востоку отсюда, на болоте, обитают небольшие туманные ползуны. Убивай их до тех пор, пока не появится Туманный ужас, и принеси мне его сердце.','Убивайте туманных ползунов, пока не появится Туманный ужас, а затем добудьте его сердце.','Какой удивительный образчик! И то, что ты преуспел, поражает до глубины души.','Кажется, эти сгустки тумана обладают разумом, верно?','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания хмеля глубоких раздумий требуется несколько ингредиентов.$B$BПрежде всего нужно придать ему крепость, а для этого мне понадобится сердце жуткого монстра – легендарного Туманного ужаса.$B$BГоворят, такие существа водятся только в самом густом тумане.$B$BК северу и к востоку отсюда, на болоте, обитают небольшие туманные ползуны. Убивай их до тех пор, пока не появится Туманный ужас, и принеси мне его сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте туманных ползунов, пока не появится Туманный ужас, а затем добудьте его сердце.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой удивительный образчик! И то, что ты преуспел, поражает до глубины души.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, эти сгустки тумана обладают разумом, верно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29892,'Тело','"Тело" напитка – важный и зачастую недооцененный фактор.$B$Bчтобы добиться идеальной консистенции, мне нужны безупречные глаза кроколисков-трясинников, обитающих к востоку отсюда.$B$BБудь $gосторожен:осторожна;. Эти существа весьма злобные.','Добудьте 5 безупречных глаз кроколисков-трясинников.','Там, откуда ты, есть кроколиски?','Осторожней на болотах, мой новый друг!','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Тело" напитка – важный и зачастую недооцененный фактор.$B$Bчтобы добиться идеальной консистенции, мне нужны безупречные глаза кроколисков-трясинников, обитающих к востоку отсюда.$B$BБудь $gосторожен:осторожна;. Эти существа весьма злобные.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 безупречных глаз кроколисков-трясинников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Там, откуда ты, есть кроколиски?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожней на болотах, мой новый друг!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29893,'Оттенок','Отличительная особенность хмеля глубоких раздумий – это его радужный оттенок.$B$BК востоку отсюда обитают янтарные мухи.$B$BВозьми этот нож и отрежь им 8 крыльев; именно они и придадут напитку это чудесное свечение.','Добудьте 8 крыльев янтарных мух.','Прекрасный цвет, исключительная прозрачность, мерцание без излишнего блеска... результат вполне удовлетворительный.$B$BПохоже, у тебя талант, странное существо.','Ты собрал ингредиенты? Уже пора варить хмель глубоких раздумий.','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оттенок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отличительная особенность хмеля глубоких раздумий – это его радужный оттенок.$B$BК востоку отсюда обитают янтарные мухи.$B$BВозьми этот нож и отрежь им 8 крыльев; именно они и придадут напитку это чудесное свечение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 крыльев янтарных мух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасный цвет, исключительная прозрачность, мерцание без излишнего блеска... результат вполне удовлетворительный.$B$BПохоже, у тебя талант, странное существо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал ингредиенты? Уже пора варить хмель глубоких раздумий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в Павильон Мечтателя, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29894,'Духи воды','Нашей войне с хозенами не видно конца. Будущее нашего племени неопределенно.$b$bВот почему говорящий с водой решил попросить совета у священных вод.$B$BСтарейшина Лушань ждет. Доставь ему собранные тобой предметы, и тогда мы сможем начать.','Поговорите со старейшиной Лушанем и поприсутствуйте на церемонии разговора с водой.','Я это видел, Синья. Как ты думаешь, что это значит?$B$BПо-моему, тебе явно отведена какая-то роль в этой истории.','Вернитесь к Здоровяку Кажаши в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нашей войне с хозенами не видно конца. Будущее нашего племени неопределенно.$b$bВот почему говорящий с водой решил попросить совета у священных вод.$B$BСтарейшина Лушань ждет. Доставь ему собранные тобой предметы, и тогда мы сможем начать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Лушанем и поприсутствуйте на церемонии разговора с водой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я это видел, Синья. Как ты думаешь, что это значит?$B$BПо-моему, тебе явно отведена какая-то роль в этой истории.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Кажаши в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29895,'По следу Белой Пешки','Плащ давно превратился в лохмотья, однако его отличный покрой и королевский герб не заметить нельзя.$B$BВам нужно показать эту вещь вашему командиру из Альянса.','Покажите плащ адмиралу Тейлору в Деревне Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следу Белой Пешки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плащ давно превратился в лохмотья, однако его отличный покрой и королевский герб не заметить нельзя.$B$BВам нужно показать эту вещь вашему командиру из Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите плащ адмиралу Тейлору в Деревне Жемчужного Плавника в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29896,'Стейк из дикобраза','Раз уж мы здесь, то нет смысла идти обратно с пустыми руками, не так ли?$b$bА $gслышал:слышала; ли ты, что мясо обитающих здесь дикобразов невероятно сочное и вкусное?$b$bИх очень трудно поймать из-за острых шипов, но ты, думаю, с этим справишься.$b$bДавай, принеси-ка мне парочку стейков, чтобы взять с собой в лагерь.$b$bМы будем обходиться без удобств в этой глуши, зато поедим, как короли!','Добудьте 5 стейков из дикобраза.','Вернитесь к Сандре Эмерелле в Зеленую рощу в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стейк из дикобраза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж мы здесь, то нет смысла идти обратно с пустыми руками, не так ли?$b$bА $gслышал:слышала; ли ты, что мясо обитающих здесь дикобразов невероятно сочное и вкусное?$b$bИх очень трудно поймать из-за острых шипов, но ты, думаю, с этим справишься.$b$bДавай, принеси-ка мне парочку стейков, чтобы взять с собой в лагерь.$b$bМы будем обходиться без удобств в этой глуши, зато поедим, как короли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 стейков из дикобраза.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сандре Эмерелле в Зеленую рощу в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (29897,'Бесплатного сыра не бывает','Сражение позади, но проблемы наши на этом не закончились. Никоим образом.$b$bПрипасы в лагере подходят к концу, а наша поставщица не вернулась после битвы.$b$bГоворят, кто-то видел, как ее утащили в лес к северу отсюда.$b$bПожалуйста, помоги отыскать ее!','Найдите Сандру Эмереллу в Зеленой роще, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесплатного сыра не бывает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сражение позади, но проблемы наши на этом не закончились. Никоим образом.$b$bПрипасы в лагере подходят к концу, а наша поставщица не вернулась после битвы.$b$bГоворят, кто-то видел, как ее утащили в лес к северу отсюда.$b$bПожалуйста, помоги отыскать ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сандру Эмереллу в Зеленой роще, что в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29898,'Священные воды','Я благодарен за то, что ты $gпроделал:проделала; весь этот путь, чтобы спасти меня, но Жэнь одной ногой в могиле!$B$BСтарому пандарену совсем не обязательно было помогать мне, однако он рискнул своей жизнью ради меня.$B$BПока у него не начался жар, он сказал, что целебную воду можно набрать в пещере ниже по склону холма.$B$BЭто опасно, но я сделаю все, лишь бы спасти друга. Ты поможешь мне набрать этой воды?','Наберите целебных вод из четырех священных чаш в Логове Печали.','Вернитесь к Лине Белой Лапе в Логово Печали, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священные воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я благодарен за то, что ты $gпроделал:проделала; весь этот путь, чтобы спасти меня, но Жэнь одной ногой в могиле!$B$BСтарому пандарену совсем не обязательно было помогать мне, однако он рискнул своей жизнью ради меня.$B$BПока у него не начался жар, он сказал, что целебную воду можно набрать в пещере ниже по склону холма.$B$BЭто опасно, но я сделаю все, лишь бы спасти друга. Ты поможешь мне набрать этой воды?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите целебных вод из четырех священных чаш в Логове Печали.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лине Белой Лапе в Логово Печали, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29899,'Покойтесь с миром','Духи... обитатели пещер... они воют от боли... $B$BОни в ловушке... не могут покинуть... этот мир...$B$BЯ... сойду с ума... слушая... их вопли... $B$BПожалуйста... помоги им... обрести покой.','Убейте 6 мучимых духов.','Спасибо... Я... рад... духи... обрели покой.','Вернитесь к Жэню Белой Лапе в Логово Печали в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покойтесь с миром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи... обитатели пещер... они воют от боли... $B$BОни в ловушке... не могут покинуть... этот мир...$B$BЯ... сойду с ума... слушая... их вопли... $B$BПожалуйста... помоги им... обрести покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 мучимых духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо... Я... рад... духи... обрели покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Белой Лапе в Логово Печали в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29900,'Древняя легенда','Поискам Вечноцветущего дола мой отец посвятил всю свою жизнь.$B$BЭтот Дол – таинственное место, закрытое после восстания пандаренов двенадцать тысяч лет назад. Мы так мало о нем знаем!$B$BПоиски привели отца к пещере, вход в которую расположен ниже по склону холма. В ней хранится древнее стихотворение под названием "Песнь Долины", но он не в том состоянии, чтобы пытаться добыть его. Его охраняет какой-то древний дух.$B$BЕсли ты все равно туда направляешься, то, может, принесешь отцу этот свиток?','Заберите "Песнь Долины" из Логова Печали.','Ой, это же стихотворение! Ты... прочел его? Где этот дол?','Вернитесь к Жэню Белой Лапе в Логово Печали в Нефритовом лесу.','Здесь ощущается присутствие темной силы.','Привидение Лина Стального Кулака') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древняя легенда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поискам Вечноцветущего дола мой отец посвятил всю свою жизнь.$B$BЭтот Дол – таинственное место, закрытое после восстания пандаренов двенадцать тысяч лет назад. Мы так мало о нем знаем!$B$BПоиски привели отца к пещере, вход в которую расположен ниже по склону холма. В ней хранится древнее стихотворение под названием "Песнь Долины", но он не в том состоянии, чтобы пытаться добыть его. Его охраняет какой-то древний дух.$B$BЕсли ты все равно туда направляешься, то, может, принесешь отцу этот свиток?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите "Песнь Долины" из Логова Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, это же стихотворение! Ты... прочел его? Где этот дол?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Белой Лапе в Логово Печали в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Здесь ощущается присутствие темной силы.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Привидение Лина Стального Кулака',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29901,'Решение Андуина','Для друзей принца вы уже сделали все, что могли.$B$BВы выполнили задание и нашли Белую Пешку – принца Андуина. Адмирал Тейлор и другие агенты ШРУ с нетерпением ждут возвращения мальчика.$B$BПора отправляться домой.','Передайте Андуину, что пора возвращаться домой.','Что-что он сделал?!$B$BЕму повезло, что я его еще не нашел, потому что я его задушу собственными руками, когда найду!$B$BО чем он только думает... ищет эту долину... Принцам не подобает так себя вести!$B$BЕсли бы у нас не было более срочных дел, за ним по моему приказу гнался бы уже весь флот!','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решение Андуина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для друзей принца вы уже сделали все, что могли.$B$BВы выполнили задание и нашли Белую Пешку – принца Андуина. Адмирал Тейлор и другие агенты ШРУ с нетерпением ждут возвращения мальчика.$B$BПора отправляться домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте Андуину, что пора возвращаться домой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что-что он сделал?!$B$BЕму повезло, что я его еще не нашел, потому что я его задушу собственными руками, когда найду!$B$BО чем он только думает... ищет эту долину... Принцам не подобает так себя вести!$B$BЕсли бы у нас не было более срочных дел, за ним по моему приказу гнался бы уже весь флот!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29902,'Битва с огнем','Эти мартышки диковаты и не очень умны, но у них достаточно мозгов, чтобы понять: огонь – мощное оружие.$B$BНе нужно объяснять, что если на эти пожары махнуть рукой, они уничтожат все, что мы тут построили.$B$BВсе мои люди заняты, так что придется тебе заняться этим. Возьми это ведро с водой и потуши пламя!','Потушите 6 очагов пламени в Лагере потерпевших крушение.','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва с огнем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти мартышки диковаты и не очень умны, но у них достаточно мозгов, чтобы понять: огонь – мощное оружие.$B$BНе нужно объяснять, что если на эти пожары махнуть рукой, они уничтожат все, что мы тут построили.$B$BВсе мои люди заняты, так что придется тебе заняться этим. Возьми это ведро с водой и потуши пламя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 6 очагов пламени в Лагере потерпевших крушение.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейсону Эрли в Лагерь потерпевших крушение в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29903,'Идеальное сочетание','Мы со старейшиной Лушанем договорились о сотрудничестве.$B$BМы поделимся с жителями Деревни Жемчужного Плавника нашим превосходным оружием и знанием военного дела.$B$BА они, в свою очередь, станут нашим мощным союзником, если мы снова столкнемся с Ордой.$B$BВозьми этот ящик и вооружи жителей деревни в соответствии с их навыками.','Поговорите с аквалитами Жемчужного Плавника и должным образом вооружите их.','Отлично. Пусть эти ублюдки из Орды только сунут сюда свой нос!','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальное сочетание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы со старейшиной Лушанем договорились о сотрудничестве.$B$BМы поделимся с жителями Деревни Жемчужного Плавника нашим превосходным оружием и знанием военного дела.$B$BА они, в свою очередь, станут нашим мощным союзником, если мы снова столкнемся с Ордой.$B$BВозьми этот ящик и вооружи жителей деревни в соответствии с их навыками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аквалитами Жемчужного Плавника и должным образом вооружите их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Пусть эти ублюдки из Орды только сунут сюда свой нос!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29904,'Закаленные битвой','Это отряд талантливых учеников Жемчужного Плавника, которым требуется боевой опыт.$b$bОтправляйтесь на северо-восток, в Бамбуковую чащу, и уничтожайте всю живность, какую встретите.$B$BДомой вернетесь только тогда, когда все воины будут готовы к бою.','Обучите учеников Жемчужного Плавника, убив 24 диких зверя в Бамбуковой чаще.','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закаленные битвой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это отряд талантливых учеников Жемчужного Плавника, которым требуется боевой опыт.$b$bОтправляйтесь на северо-восток, в Бамбуковую чащу, и уничтожайте всю живность, какую встретите.$B$BДомой вернетесь только тогда, когда все воины будут готовы к бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обучите учеников Жемчужного Плавника, убив 24 диких зверя в Бамбуковой чаще.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29905,'Пусть горят','Разведчики сообщают, что к хозенам в Ямах Ловкого Хвоста с севера движется подкрепление.$B$BНаши силы собрались на северо-западной гряде и готовы к бою. Они ждут только тебя.$B$BНастало время показать им, чего мы стоим. Пришло время их уничтожить раз и навсегда.','Убейте 15 резервистов Грукин или новобранцев Ловкого Хвоста.','Вернитесь к старейшине Лушаню в Деревню Жемчужного Плавника, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть горят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики сообщают, что к хозенам в Ямах Ловкого Хвоста с севера движется подкрепление.$B$BНаши силы собрались на северо-западной гряде и готовы к бою. Они ждут только тебя.$B$BНастало время показать им, чего мы стоим. Пришло время их уничтожить раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 резервистов Грукин или новобранцев Ловкого Хвоста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Лушаню в Деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29906,'Лови момент','На первый взгляд, у хозенов полностью отсутствует дисциплина, но в этом хаосе есть своя система. Ими командует опытный и хитроумный полководец, вождь Гукгут.$B$BОбычно он руководит ими из огромной ямы, которая находится в лагере на северо-западе отсюда.$B$BБей первым, $n, и никакой пощады – ведь он тебе ответит тем же.','Убейте вождя Гукгута.','Вернитесь к старейшине Лушаню в деревню Жемчужного Плавника, что в Нефритовом лесу.','Вождь хозенов Ловкого Хвоста.','Вождь Гукгут') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лови момент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На первый взгляд, у хозенов полностью отсутствует дисциплина, но в этом хаосе есть своя система. Ими командует опытный и хитроумный полководец, вождь Гукгут.$B$BОбычно он руководит ими из огромной ямы, которая находится в лагере на северо-западе отсюда.$B$BБей первым, $n, и никакой пощады – ведь он тебе ответит тем же.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Гукгута.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Лушаню в деревню Жемчужного Плавника, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вождь хозенов Ловкого Хвоста.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь Гукгут',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29907,'Чэнь и Ли Ли','В Пандарию мы с племянницей прибыли недавно. Мы, как и ты, путешественники и, если честно, совсем не знаем этих мест – мы ведь со Скитающегося острова.$b$bВон на той ферме, кажется, можно отдохнуть и выпить кружку пива. Что скажешь, Ли Ли?$b$b$r, хочешь пойти с нами?','Добро пожаловать! Добро пожаловать, гости дорогие! Пришли, чтобы попробовать репу, которую вырастил мой сын? Или, может, хотите купить свинью?$B$BПожалуйста, чувствуйте себя как дома. Места всем хватит.','Поговорите с Паном Громовой Пятой в Усадьбе Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чэнь и Ли Ли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Пандарию мы с племянницей прибыли недавно. Мы, как и ты, путешественники и, если честно, совсем не знаем этих мест – мы ведь со Скитающегося острова.$b$bВон на той ферме, кажется, можно отдохнуть и выпить кружку пива. Что скажешь, Ли Ли?$b$b$r, хочешь пойти с нами?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать! Добро пожаловать, гости дорогие! Пришли, чтобы попробовать репу, которую вырастил мой сын? Или, может, хотите купить свинью?$B$BПожалуйста, чувствуйте себя как дома. Места всем хватит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Паном Громовой Пятой в Усадьбе Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29908,'Бесконечные хлопоты','Прошу прощения за беспорядок. Гну-сини – эти кроликообразные существа, которые живут на холме, все чаще нападают на мои земли, причиняя огромный вред посевам. А ведь овощи у меня удивительно вкусные, поверь мне на слово.$b$bЯ не солдат... А вот ты $gпохож:похожа; на воина! Может, прогонишь гну-синей с моей земли?','Уничтожьте 8 косозубов-разведчиков, косозубов-трудяг или косозубов-смутьянов. Затем убейте 18 докучливых косозубов.','<Пан оглядывает окрестности.>$B$BНу, ушли далеко не ВСЕ, но и их стало меньше – да и вид у них побитый.$B$BПохоже, они тебя боятся, Эрезул.','Вернитесь к Пану Громовой Пяте в усадьбу Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечные хлопоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу прощения за беспорядок. Гну-сини – эти кроликообразные существа, которые живут на холме, все чаще нападают на мои земли, причиняя огромный вред посевам. А ведь овощи у меня удивительно вкусные, поверь мне на слово.$b$bЯ не солдат... А вот ты $gпохож:похожа; на воина! Может, прогонишь гну-синей с моей земли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 косозубов-разведчиков, косозубов-трудяг или косозубов-смутьянов. Затем убейте 18 докучливых косозубов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пан оглядывает окрестности.>$B$BНу, ушли далеко не ВСЕ, но и их стало меньше – да и вид у них побитый.$B$BПохоже, они тебя боятся, Эрезул.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пану Громовой Пяте в усадьбу Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29909,'Низкая урожайность репы','Благодарю за помощь, $n. Если не откажешься, у меня есть еще одно поручение.$b$bУ подножия холма находится небольшая ферма, она принадлежит моему сыну Ану. Утром он собирался принести мне овощей и фруктов, но так и не пришел.$b$bТы не $gмог:могла; бы выяснить, в чем дело?','Найдите Ана Громовую Пяту.','Что? Да ты кто... Тебя прислал мой отец?$B$BПфф... Он так любит совать нос в мои дела. Нет, у меня все хорошо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Низкая урожайность репы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю за помощь, $n. Если не откажешься, у меня есть еще одно поручение.$b$bУ подножия холма находится небольшая ферма, она принадлежит моему сыну Ану. Утром он собирался принести мне овощей и фруктов, но так и не пришел.$b$bТы не $gмог:могла; бы выяснить, в чем дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ана Громовую Пяту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Да ты кто... Тебя прислал мой отец?$B$BПфф... Он так любит совать нос в мои дела. Нет, у меня все хорошо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29910,'Бесчинствующие сурки','Утром я пошла посмотреть, как отец сражается с гну-синями, а когда вернулась, обнаружила, что ферма кишит сурками!$b$bЯ не хочу их убивать, но от них обязательно нужно избавиться. А, знаю – мы засыплем норы!$b$bЗасыпь их норы землей, и тогда сурки больше не придут к нам на ферму.','Прогоните 6 толстых сурков с фермы Громовой Пяты и засыпьте 6 нор сурков.','Спасибо, странник! Теперь я смогу вернуться к работе.','Вернитесь к Ане Громовой Пяте на ферму Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесчинствующие сурки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Утром я пошла посмотреть, как отец сражается с гну-синями, а когда вернулась, обнаружила, что ферма кишит сурками!$b$bЯ не хочу их убивать, но от них обязательно нужно избавиться. А, знаю – мы засыплем норы!$b$bЗасыпь их норы землей, и тогда сурки больше не придут к нам на ферму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прогоните 6 толстых сурков с фермы Громовой Пяты и засыпьте 6 нор сурков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, странник! Теперь я смогу вернуться к работе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ане Громовой Пяте на ферму Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29911,'Практически идеальные продукты','Держи, $n. Тут все, что просил мой отец.$b$bИ спасибо за то, что $gразобрался:разобралась; с гну-синями.','Отнесите ящик со свежими продуктами Пану Громовой Пяте.','Хо-хо! Вот это мне по душе!','Знакомый запах! Репа?','Принесите ящик со свежими продуктами Пану Громовой Пяте в Усадьбу Пана в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практически идеальные продукты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Держи, $n. Тут все, что просил мой отец.$b$bИ спасибо за то, что $gразобрался:разобралась; с гну-синями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик со свежими продуктами Пану Громовой Пяте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо! Вот это мне по душе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знакомый запах! Репа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите ящик со свежими продуктами Пану Громовой Пяте в Усадьбу Пана в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29912,'Прекрасная Фанни','Почти весь урожай будет продан, но часть овощей я хочу оставить для семьи. Точнее, для свиней моего племянника Ляна.$b$bК сожалению, на дороге, ведущей к ферме Ляна, бесчинствуют докучливые гну-сини. Придется просить Мисс Фанни о помощи.$b$bОтнеси овощи Мисс Фанни, найдешь ее рядом с моим домом. А затем попроси – ВЕЖЛИВО – отправить овощи на ферму Ляна.','Отнесите огромную розовую репу Ана, сочный арбуз Ана и чрезвычайно пряный тофу Пана Мисс Фанни и попросите ее доставить все это на ранчо Громовой Пяты.','Поговорите с Ляном Громовой Пятой на Ранчо Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прекрасная Фанни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Почти весь урожай будет продан, но часть овощей я хочу оставить для семьи. Точнее, для свиней моего племянника Ляна.$b$bК сожалению, на дороге, ведущей к ферме Ляна, бесчинствуют докучливые гну-сини. Придется просить Мисс Фанни о помощи.$b$bОтнеси овощи Мисс Фанни, найдешь ее рядом с моим домом. А затем попроси – ВЕЖЛИВО – отправить овощи на ферму Ляна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите огромную розовую репу Ана, сочный арбуз Ана и чрезвычайно пряный тофу Пана Мисс Фанни и попросите ее доставить все это на ранчо Громовой Пяты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ляном Громовой Пятой на Ранчо Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29913,'Мясо, которое им понравится','Как я уже говорил, мои хрюшки очень разборчивы в еде. Для нормального роста свиньям необходимо мясо, но баранина им не нравится, мясо яка – тоже, а кормить их свининой я не собираюсь.$b$bОднако они с удовольствием едят мясо мушанов и просто обожают черепашатину. И тех и других можно легко найти к западу отсюда.$b$bПравда, охотник из меня никакой. Выручишь юного свиновода?','Принесите 4 стейка из мяса мушана и 80 кусков черепашьего мяса.','Как же больно слышать визг голодных хрюшек.$B$BЕсли сам разводишь свиней, то знаешь, что голодная свинья визжит совсем не так, как сытая.','Вернитесь к Ляну Громовой Пяте на Ранчо Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясо, которое им понравится',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я уже говорил, мои хрюшки очень разборчивы в еде. Для нормального роста свиньям необходимо мясо, но баранина им не нравится, мясо яка – тоже, а кормить их свининой я не собираюсь.$b$bОднако они с удовольствием едят мясо мушанов и просто обожают черепашатину. И тех и других можно легко найти к западу отсюда.$b$bПравда, охотник из меня никакой. Выручишь юного свиновода?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 стейка из мяса мушана и 80 кусков черепашьего мяса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как же больно слышать визг голодных хрюшек.$B$BЕсли сам разводишь свиней, то знаешь, что голодная свинья визжит совсем не так, как сытая.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ляну Громовой Пяте на Ранчо Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29914,'Назад, в хлев','Я приглядываю за своей скотиной, но время от времени она разбегается. Из-за этих гну-синей я ненадолго отвлекся, и пожалуйста – три свиньи исчезли.$b$bМожет, поищешь их? Я бы для начала отправился на запад, вниз по склону холма.','Найдите Цзяня, Лин и Вонючку.','Вернитесь к Ляну Громовой Пяте на Ранчо Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад, в хлев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я приглядываю за своей скотиной, но время от времени она разбегается. Из-за этих гну-синей я ненадолго отвлекся, и пожалуйста – три свиньи исчезли.$b$bМожет, поищешь их? Я бы для начала отправился на запад, вниз по склону холма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Цзяня, Лин и Вонючку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ляну Громовой Пяте на Ранчо Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29915,'Соседский долг','Похоже, не только мне не дает покоя упрямая скотина. Одна из овец Франсиса сбежала уже в третий раз за неделю. Я уже думаю, что ему нужно нанять помощника.$b$bЗагляни к Франсису, $gсосед:соседка;. И приведи ему эту бедную овечку.','Отведите заблудившуюся овечку пастуху Франсису.','Не нужно было приводить сюда овечку. Она... в хлеву находится в большей безопасности, чем здесь.','Ой... Это... Моя овечка?','Отведите заблудившуюся овечку к пастуху Франсису на Луга Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соседский долг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, не только мне не дает покоя упрямая скотина. Одна из овец Франсиса сбежала уже в третий раз за неделю. Я уже думаю, что ему нужно нанять помощника.$b$bЗагляни к Франсису, $gсосед:соседка;. И приведи ему эту бедную овечку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите заблудившуюся овечку пастуху Франсису.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не нужно было приводить сюда овечку. Она... в хлеву находится в большей безопасности, чем здесь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ой... Это... Моя овечка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отведите заблудившуюся овечку к пастуху Франсису на Луга Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29916,'Острые когти и оскаленные зубы','Сначала прилетели ястребы. Наверное, ты $gвидел:видела; как они кружат в небе.$b$bВскоре после этого появились волки – кажется, они почувствовали, что я слаб.$b$bЯ вовсе не такой смельчак, как думал мастер Шан. И если он узнает, что я не справился с этими тварями, он страшно разозлится.$b$bПожалуйста, помоги мне.','Уничтожьте 5 равнинных ястребов – налетчиков и 6 волков-налетчиков.','Они не останавливаются – но по крайней мере мы дали им отпор. Верно?','Вернитесь к пастуху Франсису на Луга Громовой Пяты в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Острые когти и оскаленные зубы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала прилетели ястребы. Наверное, ты $gвидел:видела; как они кружат в небе.$b$bВскоре после этого появились волки – кажется, они почувствовали, что я слаб.$b$bЯ вовсе не такой смельчак, как думал мастер Шан. И если он узнает, что я не справился с этими тварями, он страшно разозлится.$b$bПожалуйста, помоги мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 равнинных ястребов – налетчиков и 6 волков-налетчиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они не останавливаются – но по крайней мере мы дали им отпор. Верно?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пастуху Франсису на Луга Громовой Пяты в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29917,'Волчарро','Я тут подумал... Возможно, волки перестанут нападать на нас, если лишить их вожака.$b$bМы зовем его Волчарро, он обитает на противоположном берегу реки.$b$b<Франсис умолкает – ему нужно отражать новую атаку врага. Видимо, вам нужно самостоятельно разобраться с этим Волчарро.>','Убейте Волчарро.','Я знаю – это мне нужно с ними драться, но... Наверное, я никогда не стану настоящим пастухом.','Вернитесь к пастуху Франсису на Луга Громовой Пяты в Долине Четырех Ветров.','Вожак волчьей стаи, пожиратель овец.','Волчарро') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волчарро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут подумал... Возможно, волки перестанут нападать на нас, если лишить их вожака.$b$bМы зовем его Волчарро, он обитает на противоположном берегу реки.$b$b<Франсис умолкает – ему нужно отражать новую атаку врага. Видимо, вам нужно самостоятельно разобраться с этим Волчарро.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Волчарро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю – это мне нужно с ними драться, но... Наверное, я никогда не стану настоящим пастухом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пастуху Франсису на Луга Громовой Пяты в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вожак волчьей стаи, пожиратель овец.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Волчарро',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29918,'Урок мужества','<Мастер Шан обращается к пастушонку.>$b$bФрансис, ты должен быть смелым! У тебя есть все задатки отличного пастуха, нужно только побороть свой страх!$b$b<Он переводит взгляд на вас.>$b$b$gНезнакомец:Незнакомка;, ты $gпомог:помогла; моей семье. А Франсис для меня тоже как родной.$b$bПокажи моему ученику, что такое храбрость. Возьми эту веревку и зааркань одного из белых ястребов, которые кружат над нами.$b$b<Шан указывает на небо, бросает взгляд на Франсиса и уходит.>','Заарканьте и победите крупного белого равнинного ястреба с помощью аркана фермера.','Франсису потребовалось много времени, чтобы стать пастухом. У каждого из нас бывает полоса неудач... и я, и мой сын Лян – мы тоже когда-то не все умели.$B$BНичего, Франсис всему научится. Так уж заведено у нас, Громовых Пят.','Я вижу, страх тебе неведом.','Принесите аркан фермера Шану Громовой Пяте в Усадьбу Шана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок мужества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мастер Шан обращается к пастушонку.>$b$bФрансис, ты должен быть смелым! У тебя есть все задатки отличного пастуха, нужно только побороть свой страх!$b$b<Он переводит взгляд на вас.>$b$b$gНезнакомец:Незнакомка;, ты $gпомог:помогла; моей семье. А Франсис для меня тоже как родной.$b$bПокажи моему ученику, что такое храбрость. Возьми эту веревку и зааркань одного из белых ястребов, которые кружат над нами.$b$b<Шан указывает на небо, бросает взгляд на Франсиса и уходит.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заарканьте и победите крупного белого равнинного ястреба с помощью аркана фермера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Франсису потребовалось много времени, чтобы стать пастухом. У каждого из нас бывает полоса неудач... и я, и мой сын Лян – мы тоже когда-то не все умели.$B$BНичего, Франсис всему научится. Так уж заведено у нас, Громовых Пят.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу, страх тебе неведом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите аркан фермера Шану Громовой Пяте в Усадьбу Шана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29919,'Все великие пьют одинаково','Привет, $n. Какой раз мы уже встречаемся – четвертый?$b$bСлушай... мой бочонок стремительно пустеет, а на юго-западе, говорят, есть хмелеварня. И мы как раз туда направляемся. Не хочешь составить компанию?','Проводите Чэня Буйного Портера и Ли Ли к хмелеварне на юго-западе.','Поговорите с Грязной Кружкой на участке Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все великие пьют одинаково',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Какой раз мы уже встречаемся – четвертый?$b$bСлушай... мой бочонок стремительно пустеет, а на юго-западе, говорят, есть хмелеварня. И мы как раз туда направляемся. Не хочешь составить компанию?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Чэня Буйного Портера и Ли Ли к хмелеварне на юго-западе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Грязной Кружкой на участке Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29920,'Благословение','Мой возлюбленный Ло попросил у пандриархов разрешения жениться на мне. Хотя они уже давно перешли в иной мир, их благосклонность очень важна для нас.$B$BПроблема в том, что они – призраки, и наши дары и подношения их не впечатлят. Чтобы заслужить их расположение, Ло или кто-то из его друзей должен одолеть их в бою.$B$BМой Ло такой замечательный... но он не боец.$B$BМожет, ты сразишься вместо него?','Вызовите на бой и победите пандриарха Золотистый Нектар, пандриарха Воздушный Мех и пандриарха Ежевичный Посох.','Поговорите с учеником Ло Бродячим Бражником в Святилище Рассвета в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой возлюбленный Ло попросил у пандриархов разрешения жениться на мне. Хотя они уже давно перешли в иной мир, их благосклонность очень важна для нас.$B$BПроблема в том, что они – призраки, и наши дары и подношения их не впечатлят. Чтобы заслужить их расположение, Ло или кто-то из его друзей должен одолеть их в бою.$B$BМой Ло такой замечательный... но он не боец.$B$BМожет, ты сразишься вместо него?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой и победите пандриарха Золотистый Нектар, пандриарха Воздушный Мех и пандриарха Ежевичный Посох.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с учеником Ло Бродячим Бражником в Святилище Рассвета в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29922,'В поисках мудрости','Пока тебя не было, заходил хранитель истории Чо и справлялся о тебе.$B$BЕму срочно нужна твоя помощь в Цветущей Заре к северу отсюда. Он не сказал, чего именно он хотел.$B$BПоговори с мастером воздушных змеев От-Намом, он с радостью отправит тебя туда.','Поговорите с мастером воздушных змеев От-Намом и отправьтесь в Цветущую Зарю.','Твои деяния напомнили мне о давно забытом древнем пророчестве. В этом следует разобраться.$B$BНо для того чтобы разобраться в этом, мне нужен нефрит. Я поручил Тое собрать столько, сколько он сможет, а затем отдать тебе. Принеси мне его, и мы попробуем расшифровать древнее "Знамение Императора".$B$BПока он собирает нефрит, можешь побродить здесь. Кому-то из горожан вполне может потребоваться помощь профессионала твоего уровня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках мудрости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя не было, заходил хранитель истории Чо и справлялся о тебе.$B$BЕму срочно нужна твоя помощь в Цветущей Заре к северу отсюда. Он не сказал, чего именно он хотел.$B$BПоговори с мастером воздушных змеев От-Намом, он с радостью отправит тебя туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером воздушных змеев От-Намом и отправьтесь в Цветущую Зарю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои деяния напомнили мне о давно забытом древнем пророчестве. В этом следует разобраться.$B$BНо для того чтобы разобраться в этом, мне нужен нефрит. Я поручил Тое собрать столько, сколько он сможет, а затем отдать тебе. Принеси мне его, и мы попробуем расшифровать древнее "Знамение Императора".$B$BПока он собирает нефрит, можешь побродить здесь. Кому-то из горожан вполне может потребоваться помощь профессионала твоего уровня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29923,'Хмель глубоких раздумий','Хмель глубоких раздумий готов.$B$BВыпей его у Камня Провидца – он находится справа от красной пагоды.$B$BИщи – и найдешь.','Выпейте хмель глубоких раздумий у Камня Провидца и найдите Белую Пешку.','Поговорите с Белой Пешкой в Логове Печали в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хмель глубоких раздумий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмель глубоких раздумий готов.$B$BВыпей его у Камня Провидца – он находится справа от красной пагоды.$B$BИщи – и найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте хмель глубоких раздумий у Камня Провидца и найдите Белую Пешку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Белой Пешкой в Логове Печали в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (29924,'Смерть Кер Шаню!','Кер Шань – здоровенский дукер.$B$BГрокать мои сыновья вся! Ик-Ик, Наб-Наб, Ит-Ит, Битти-Битти... Не помнить больше... но больше!$B$BШнуропс хотеть помогай хозену? Грокни Кер Шань!$B$BДукер там.$B$B<Ниби-Ниби указывает на восток.>','Убейте Кер Шаня в Тигрином лесу.','Кер Шань') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Кер Шаню!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кер Шань – здоровенский дукер.$B$BГрокать мои сыновья вся! Ик-Ик, Наб-Наб, Ит-Ит, Битти-Битти... Не помнить больше... но больше!$B$BШнуропс хотеть помогай хозену? Грокни Кер Шань!$B$BДукер там.$B$B<Ниби-Ниби указывает на восток.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кер Шаня в Тигрином лесу.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кер Шань',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29925,'Все, что у нас есть','Итак, я попросил об услуге всех, кого я знаю. И вот что теперь у нас есть.$B$BНадеюсь, Чо знает, что делает!$B$BКогда будешь $gготов:готова; к нему отправиться, обращайся ко мне – я тебя отвезу.','Отдайте добытый нефрит хранителю истории Чо у Знамения Императора. Попросите Тою в Цветущей Заре отвезти вас туда.','Я знал, что на Тою можно положиться!$B$BЗнаешь, он что угодно может достать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все, что у нас есть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, я попросил об услуге всех, кого я знаю. И вот что теперь у нас есть.$B$BНадеюсь, Чо знает, что делает!$B$BКогда будешь $gготов:готова; к нему отправиться, обращайся ко мне – я тебя отвезу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте добытый нефрит хранителю истории Чо у Знамения Императора. Попросите Тою в Цветущей Заре отвезти вас туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что на Тою можно положиться!$B$BЗнаешь, он что угодно может достать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29926,'Опасный нефрит','Уничтожьте 12 жевунов Зеленой Скалы и 6 брюхоловов Зеленой Скалы в каменоломне Зеленой Скалы.','Ого! Значит, ты все-таки это сделал!$B$BБратишка, тебе постоянная работа не требуется? Мне нужны такие громилы на полный рабочий день!','Вернитесь к штейгеру Манну в Знамение Императора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасный нефрит',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 жевунов Зеленой Скалы и 6 брюхоловов Зеленой Скалы в каменоломне Зеленой Скалы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого! Значит, ты все-таки это сделал!$B$BБратишка, тебе постоянная работа не требуется? Мне нужны такие громилы на полный рабочий день!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Манну в Знамение Императора.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29927,'Муж Манн','<Штейгерша неожиданно переходит на шепот.>$B$BСлушай, я хочу попросить тебя об одолжении... Но дело сложное, сразу предупреждаю. Мой дуралей-муж Хао, начальник смены, там – в каменоломне. Я ему сказала, чтобы он туда не ходил, что там слишком опасно, но он же упрям, словно хозен, только в два раза глупее. Он ответил, что парней нужно "морально поддержать".$B$B<Манн презрительно фыркает.>$B$BА меня кто поддержит? Что я буду делать, если этот тупица погибнет?!$B$BПожалуйста... найди его. Скажи ему, пусть идет домой.$B$B<При этих словах ее взгляд теплеет, и она отворачивается.>','Найдите Хао Манна в каменоломне Зеленой Скалы.','<Хао смотрит на вас, пытаясь выбраться из-под обломков.>$B$BНет-нет, все в порядке. А-а-а!$B$BНу ладно, может, и не все.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Муж Манн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Штейгерша неожиданно переходит на шепот.>$B$BСлушай, я хочу попросить тебя об одолжении... Но дело сложное, сразу предупреждаю. Мой дуралей-муж Хао, начальник смены, там – в каменоломне. Я ему сказала, чтобы он туда не ходил, что там слишком опасно, но он же упрям, словно хозен, только в два раза глупее. Он ответил, что парней нужно "морально поддержать".$B$B<Манн презрительно фыркает.>$B$BА меня кто поддержит? Что я буду делать, если этот тупица погибнет?!$B$BПожалуйста... найди его. Скажи ему, пусть идет домой.$B$B<При этих словах ее взгляд теплеет, и она отворачивается.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Хао Манна в каменоломне Зеленой Скалы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хао смотрит на вас, пытаясь выбраться из-под обломков.>$B$BНет-нет, все в порядке. А-а-а!$B$BНу ладно, может, и не все.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29928,'У меня нет нефрита, и я хочу кричать!','Наше производство нефрита разваливается на глазах. Шахты – смертельно опасные ловушки, боевой дух рабочих – хуже не бывает... И – как будто этого было мало – Поселок Каменщиков захватили лесные духи!$B$BТеперь даже растения будто бы сговорились меня разорить!$B$BЕсли тебе так нужен нефрит, иди на юго-запад в Поселок Каменщиков и отними нефрит у этих палочек для еды, возомнивших о себе невесть что.','Отнимите 15 кусков нефрита у злобных духов в Поселке Каменщиков Зеленой Скалы.','Что? Они играли моим товаром, как мячом?!$B$BНадеюсь, ты преподал этим зубочисткам урок.$B$BЗнаешь, может, ты не такой уж и молокосос. Мне тут как раз нужен был какой-нибудь вышибала, чтоб устранить мою проблемку на каменоломне.$B$BА судя по масштабам восстановления, которое тут затеял Чо, нефрита, думаю, вам потребуется еще много.','<Манн смотрит на вас широко раскрытыми глазами.>','Вернитесь к штейгеру Манну в Знамение Императора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У меня нет нефрита, и я хочу кричать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше производство нефрита разваливается на глазах. Шахты – смертельно опасные ловушки, боевой дух рабочих – хуже не бывает... И – как будто этого было мало – Поселок Каменщиков захватили лесные духи!$B$BТеперь даже растения будто бы сговорились меня разорить!$B$BЕсли тебе так нужен нефрит, иди на юго-запад в Поселок Каменщиков и отними нефрит у этих палочек для еды, возомнивших о себе невесть что.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите 15 кусков нефрита у злобных духов в Поселке Каменщиков Зеленой Скалы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Они играли моим товаром, как мячом?!$B$BНадеюсь, ты преподал этим зубочисткам урок.$B$BЗнаешь, может, ты не такой уж и молокосос. Мне тут как раз нужен был какой-нибудь вышибала, чтоб устранить мою проблемку на каменоломне.$B$BА судя по масштабам восстановления, которое тут затеял Чо, нефрита, думаю, вам потребуется еще много.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Манн смотрит на вас широко раскрытыми глазами.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Манну в Знамение Императора.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29929,'В ловушке!','<Хао изо всех сил толкает груду камней.>$B$BЭх-ха!..$B$BСейчас угадаю: тебя прислала моя жена? Подумать только – моя крошка, моя белоснежная лилия беспокоится обо мне! Ха-ха! Вечно она всего боится. Слушай... Эх!.. Один маленький обвал... Эх!.. Хао не остановит!$B$BА вот мои парни попали в беду. Помоги им, если сможешь, ладно? А со мной все будет хорошо.$B$BЧестно.','Освободите 8 рудокопов Зеленой Скалы в каменоломне Зеленой Скалы.','<Хао громко хохочет.>$B$BОни улепетывали так, словно за ними гнался сам Кер Шань.','Поговорите с Хао Манном у входа в каменоломню Зеленой Скалы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ловушке!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Хао изо всех сил толкает груду камней.>$B$BЭх-ха!..$B$BСейчас угадаю: тебя прислала моя жена? Подумать только – моя крошка, моя белоснежная лилия беспокоится обо мне! Ха-ха! Вечно она всего боится. Слушай... Эх!.. Один маленький обвал... Эх!.. Хао не остановит!$B$BА вот мои парни попали в беду. Помоги им, если сможешь, ладно? А со мной все будет хорошо.$B$BЧестно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 рудокопов Зеленой Скалы в каменоломне Зеленой Скалы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хао громко хохочет.>$B$BОни улепетывали так, словно за ними гнался сам Кер Шань.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хао Манном у входа в каменоломню Зеленой Скалы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29930,'Что в шахте добыл, то твое','Значит, тебе нужен нефрит? Мы тебе сильно обязаны и поделимся им с тобой. В каменоломне нефрита полно, и теперь благодаря тебе мы живо восстановим его добычу.$B$BМне пора возвращаться к жене, так что давай отвезем ей все добро в этой вагонетке.$B$BПовезу я, а ты поедешь. $gОдин:Одна; |3-6($r) – это не груз. Залезай, и старина Хао тебя отвезет.','Садитесь в вагонетку с нефритом и отправляйтесь вместе с Хао в Знамение Императора.','Ты его спас! Моего медового медведя!$B$BО, спасибо, Аламор! Спасибо!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что в шахте добыл, то твое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, тебе нужен нефрит? Мы тебе сильно обязаны и поделимся им с тобой. В каменоломне нефрита полно, и теперь благодаря тебе мы живо восстановим его добычу.$B$BМне пора возвращаться к жене, так что давай отвезем ей все добро в этой вагонетке.$B$BПовезу я, а ты поедешь. $gОдин:Одна; |3-6($r) – это не груз. Залезай, и старина Хао тебя отвезет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Садитесь в вагонетку с нефритом и отправляйтесь вместе с Хао в Знамение Императора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты его спас! Моего медового медведя!$B$BО, спасибо, Аламор! Спасибо!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29931,'Змеиное Сердце','$GМалыш:Малышка;, ты молодчина. Благодаря тебе у нас есть лишний нефрит, и я знаю, кому он может понадобиться.$B$BМой друг, мастер Рейки, сейчас возводит огромную статую в Змеином Сердце.$B$BОтвези ему этот нефрит и передай привет от его старого друга Манна. Он будет ждать тебя с нетерпением.','Поговорите с мастером Рейки, который находится в Змеином Сердце в Нефритовом лесу.','Я все правильно понимаю? Целая партия чистого качественного нефрита?$B$BХвала небесам. Все знают, что на штейгера Манна можно положиться.$B$BАх да, и на тебя тоже. Спасибо за доставку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеиное Сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GМалыш:Малышка;, ты молодчина. Благодаря тебе у нас есть лишний нефрит, и я знаю, кому он может понадобиться.$B$BМой друг, мастер Рейки, сейчас возводит огромную статую в Змеином Сердце.$B$BОтвези ему этот нефрит и передай привет от его старого друга Манна. Он будет ждать тебя с нетерпением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Рейки, который находится в Змеином Сердце в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я все правильно понимаю? Целая партия чистого качественного нефрита?$B$BХвала небесам. Все знают, что на штейгера Манна можно положиться.$B$BАх да, и на тебя тоже. Спасибо за доставку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (29932,'Храм Нефритовой Змеи','Поговорите с верховным жрецом дождя Чжу в Храме Нефритовой Змеи в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Храм Нефритовой Змеи',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным жрецом дождя Чжу в Храме Нефритовой Змеи в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29933,'Наживка из мух','Шнуропс хозену закадычный друзь? Хозен будет посмотреть!$B$BУ хозенов в Грукине нет наживки. А ноги тигровых мух в воде долго дергаться – отличная штука!$b$bНо Бо-Бо весь болеть от укусов. Шнуропс относить наживку на холм Грукин.','Соберите 30 ножек мух, уничтожая тигровых мух в Тигрином лесу.','Тумс-тумс! Шнуропс – полный стумпа-чумс!','Кусь-кусь для грязней!','Поговорите с вождем Ках-Кахом на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наживка из мух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шнуропс хозену закадычный друзь? Хозен будет посмотреть!$B$BУ хозенов в Грукине нет наживки. А ноги тигровых мух в воде долго дергаться – отличная штука!$b$bНо Бо-Бо весь болеть от укусов. Шнуропс относить наживку на холм Грукин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 30 ножек мух, уничтожая тигровых мух в Тигрином лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тумс-тумс! Шнуропс – полный стумпа-чумс!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кусь-кусь для грязней!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Ках-Кахом на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29934,'Цель: поместье Черного Ворона','Если яйцо действительно находится в поместье Черного Ворона, мы вряд ли можем атаковать в лоб – в бою яйцо может быть случайно уничтожено. Мне нужен кто-то, кто сможет незаметно проскользнуть в поместье и удостовериться, что яйцо там.$B$BИ этот кто-то – ты, $n.$B$BПроникнуть на территорию поместья тебе поможет Мостраз. Он ждет тебя снаружи. Удачи!','Поговорите с Мостразом в пещере за поместьем Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: поместье Черного Ворона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если яйцо действительно находится в поместье Черного Ворона, мы вряд ли можем атаковать в лоб – в бою яйцо может быть случайно уничтожено. Мне нужен кто-то, кто сможет незаметно проскользнуть в поместье и удостовериться, что яйцо там.$B$BИ этот кто-то – ты, $n.$B$BПроникнуть на территорию поместья тебе поможет Мостраз. Он ждет тебя снаружи. Удачи!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мостразом в пещере за поместьем Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29935,'Приказ есть приказ','Хм, может, шнуропс и не совсем плохиш!$b$bДругой лысокожий не такой добряк для хозенов.$b$bХозены брать это у плохих шнуропсов!$b$bВсе добро шнуропсов идти к Ках-Каху – приказ вождя!$b$bВот, шнуропс, твоя держи это. Ках-Ках хотеть завидеть новый хозенский друг.$b$bКах-Ках в лагерь на юг, холм Грукин.','Отнесите приказы Альянса вождю Ках-Каху на холм Грукин.','Хм...$B$BЗлые шнуропсы бить хороших шнуропсов?$B$BХозены помогать хорошим тогда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ есть приказ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм, может, шнуропс и не совсем плохиш!$b$bДругой лысокожий не такой добряк для хозенов.$b$bХозены брать это у плохих шнуропсов!$b$bВсе добро шнуропсов идти к Ках-Каху – приказ вождя!$b$bВот, шнуропс, твоя держи это. Ках-Ках хотеть завидеть новый хозенский друг.$b$bКах-Ках в лагерь на юг, холм Грукин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы Альянса вождю Ках-Каху на холм Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм...$B$BЗлые шнуропсы бить хороших шнуропсов?$B$BХозены помогать хорошим тогда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29936,'Мгновенный обмен сообщениями','Добро пожалуй, шнуропс! Моя Ках-Ках – вождь хозенов Грукина.$b$bДук Укем хотеть быть вождем, но добрый шнуропс его хорошо убивать – большой подарок для Ках-Ках.$b$bХозен иметь тоже подарок для шнуропса – найденство с большого бабаха. Хозены хранить его для шнуропса.','Запустите сигнальную ракету с "Кулака Адского Крика" рядом с вождем Ках-Кахом на холме Грукин.','Тилепа, твои успехи впечатляют.$B$BКто бы мог подумать, что эти существа могут стать нашими союзниками.$B$BНу что ж, теперь мы сможем заняться более важными делами.','Поговорите с генералом Назгримом на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мгновенный обмен сообщениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожалуй, шнуропс! Моя Ках-Ках – вождь хозенов Грукина.$b$bДук Укем хотеть быть вождем, но добрый шнуропс его хорошо убивать – большой подарок для Ках-Ках.$b$bХозен иметь тоже подарок для шнуропса – найденство с большого бабаха. Хозены хранить его для шнуропса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запустите сигнальную ракету с "Кулака Адского Крика" рядом с вождем Ках-Кахом на холме Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тилепа, твои успехи впечатляют.$B$BКто бы мог подумать, что эти существа могут стать нашими союзниками.$B$BНу что ж, теперь мы сможем заняться более важными делами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29937,'Разъяренная дичь','Значит, им нравится рыба? Что ж, тогда закончим это дело – и они нас ПОЛЮБЯТ!$B$BВзрывчатый порошок у меня еще остался, так что нужно чем-нибудь приманить рыбу.$B$BКишки – отличная наживка, она никогда меня не подводила. Я тут видел птиц к югу от города...$B$BНу? Ждешь особого приглашения?','Наберите 6 пригоршней птичьих кишок, убивая кровопалов на Дуковых полях.','О да!$B$BТо, что нужно! Теперь гляди...','Ты же не трогал эту дрянь руками, нет?','Поговорите с Риветтом Сталехватом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренная дичь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, им нравится рыба? Что ж, тогда закончим это дело – и они нас ПОЛЮБЯТ!$B$BВзрывчатый порошок у меня еще остался, так что нужно чем-нибудь приманить рыбу.$B$BКишки – отличная наживка, она никогда меня не подводила. Я тут видел птиц к югу от города...$B$BНу? Ждешь особого приглашения?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 6 пригоршней птичьих кишок, убивая кровопалов на Дуковых полях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да!$B$BТо, что нужно! Теперь гляди...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же не трогал эту дрянь руками, нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом Сталехватом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29938,'Друзья и враги','Эти бортельные цзинь-юй грокать племянников Ках-Ках!$B$BШнуропс грокнул много-много хозенов тогда. Шнуропс грокни много-много цзинь-юй сейчас-сейчас.','Уничтожьте 7 приречных цзинь-юй у реки Безмятежной.','Поговорите с вождем Ках-Кахом на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья и враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти бортельные цзинь-юй грокать племянников Ках-Ках!$B$BШнуропс грокнул много-много хозенов тогда. Шнуропс грокни много-много цзинь-юй сейчас-сейчас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 приречных цзинь-юй у реки Безмятежной.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Ках-Кахом на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29939,'Взрывная наживка','Вот так. Я забросал взрывчатку птичьими кишками.$B$BПожалуй, назову это "Бомба из потрохов" и запатентую!$B$BНу что, раз уж ты $gподружился:подружилась; с этими парнями, как насчет одолжения?$B$BПросто подожги запал и бросай на берег!','Разбросайте бомбы из потрохов на Грязном берегу и соберите 5 взорвавшихся грязней.','Мы только что революционизировали способ добычи еды.$B$BЖизнь этих кретинов... то есть хозенов... изменится навсегда!','Нет такой проблемы, которую нельзя решить с помощью динамита.','Поговорите с Риветтом Сталехватом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывная наживка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот так. Я забросал взрывчатку птичьими кишками.$B$BПожалуй, назову это "Бомба из потрохов" и запатентую!$B$BНу что, раз уж ты $gподружился:подружилась; с этими парнями, как насчет одолжения?$B$BПросто подожги запал и бросай на берег!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбросайте бомбы из потрохов на Грязном берегу и соберите 5 взорвавшихся грязней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы только что революционизировали способ добычи еды.$B$BЖизнь этих кретинов... то есть хозенов... изменится навсегда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет такой проблемы, которую нельзя решить с помощью динамита.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом Сталехватом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29940,'Возвращение похищенного урожая','Ладно, ладно. Вообще-то дела у меня не очень. Я все утро провел, сражаясь с гну-синями, но им все равно удалось унести часть урожая.$b$bГну-сини побежали на юг, к реке. Понятия не имею, зачем им понадобились овощи, думаю, есть они их и не собираются.$b$bМой отец ждет доставку, а в одиночку урожай мне не вернуть. Ты мне поможешь?','Найдите 5 украденных реп и 5 украденных арбузов.','Отлично.$B$B<Ан разглядывает помятую репу и раздавленные арбузы.>$B$BДа что они с ними делали?!','Раз уж отцу нужны овощи, без твоей помощи мне не обойтись.','Вернитесь к Ану Громовой Пяте на Ферму Громовой Пяты, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение похищенного урожая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, ладно. Вообще-то дела у меня не очень. Я все утро провел, сражаясь с гну-синями, но им все равно удалось унести часть урожая.$b$bГну-сини побежали на юг, к реке. Понятия не имею, зачем им понадобились овощи, думаю, есть они их и не собираются.$b$bМой отец ждет доставку, а в одиночку урожай мне не вернуть. Ты мне поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 украденных реп и 5 украденных арбузов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично.$B$B<Ан разглядывает помятую репу и раздавленные арбузы.>$B$BДа что они с ними делали?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раз уж отцу нужны овощи, без твоей помощи мне не обойтись.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ану Громовой Пяте на Ферму Громовой Пяты, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29941,'Там, за горизонтом','Я высоко ценю все то, чего тебе удалось добиться здесь, |3-6($c). В отчете вождю я сообщу обо всех твоих подвигах.$B$BНо отдыхать некогда!$B$BНужно составить карту этих земель – это поможет поселенцам из Орды здесь обосноваться. Я уже собрал отряд, который займется этим делом.$B$BНайди этих воинов до того, как они успеют расслабиться здесь. Сообщи им о поставленной задаче и убеди одного из своих новых друзей стать проводником.$B$BА ты останешься здесь. Нужно заняться приготовлениями.','Поговорите с Шокией, сержантом Горроком, темным мастером Кирин и вождем Ках-Кахом.','Поговорите с генералом Назгримом на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Там, за горизонтом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я высоко ценю все то, чего тебе удалось добиться здесь, |3-6($c). В отчете вождю я сообщу обо всех твоих подвигах.$B$BНо отдыхать некогда!$B$BНужно составить карту этих земель – это поможет поселенцам из Орды здесь обосноваться. Я уже собрал отряд, который займется этим делом.$B$BНайди этих воинов до того, как они успеют расслабиться здесь. Сообщи им о поставленной задаче и убеди одного из своих новых друзей стать проводником.$B$BА ты останешься здесь. Нужно заняться приготовлениями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шокией, сержантом Горроком, темным мастером Кирин и вождем Ках-Кахом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29942,'Глупый шнуропс, грязни – хозенам!','Думать, хозены совсем тум-тум, шнуропс? Погоди, пока хозены подъедят грязни совсем-совсем!$B$BМало-мало грязни для хозенов и мягкостных шнуропсов!$B$BЩелкунцы! Хозен ненавидь бортельных щелкунцев, бортель-мортель! Шнуропс, грокни щелкунцев!$B$B<Икл-Икл указывает на юг.>','Соберите 4 стейка из навозных крепкохватов на Грязном берегу.','Теперь еда у всех! Хозен Икл-Икл великомудр!$B$BКто знать, Икл-Икл однажды стать вождем...','Шнуропс грокай бортельных щелкунцев?','Поговорите с Икл-Иклом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глупый шнуропс, грязни – хозенам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думать, хозены совсем тум-тум, шнуропс? Погоди, пока хозены подъедят грязни совсем-совсем!$B$BМало-мало грязни для хозенов и мягкостных шнуропсов!$B$BЩелкунцы! Хозен ненавидь бортельных щелкунцев, бортель-мортель! Шнуропс, грокни щелкунцев!$B$B<Икл-Икл указывает на юг.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 стейка из навозных крепкохватов на Грязном берегу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь еда у всех! Хозен Икл-Икл великомудр!$B$BКто знать, Икл-Икл однажды стать вождем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Шнуропс грокай бортельных щелкунцев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Икл-Иклом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29943,'Лазутчики в наших землях','Принц Андуин Ринн. Любимый сын вражеского короля! Судьба снова улыбнулась Орде, $n.$b$bНо есть и другая сторона медали. Наивно будет полагать, что про мальчика все забудут.$b$bНаверняка сейчас тут твари из Альянса носом землю роют в поисках своего драгоценного принца.$b$bТак что мы с тобой прочешем окрестности и устраним всех этих спасателей.','Уничтожьте 8 секретных агентов Альянса возле Утеса дивного вида.','Да!$B$BКлянусь окровавленным кулаком Тралла, я скучал по охоте на воинов Альянса!','Поговорите с генералом Назгримом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лазутчики в наших землях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принц Андуин Ринн. Любимый сын вражеского короля! Судьба снова улыбнулась Орде, $n.$b$bНо есть и другая сторона медали. Наивно будет полагать, что про мальчика все забудут.$b$bНаверняка сейчас тут твари из Альянса носом землю роют в поисках своего драгоценного принца.$b$bТак что мы с тобой прочешем окрестности и устраним всех этих спасателей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 секретных агентов Альянса возле Утеса дивного вида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да!$B$BКлянусь окровавленным кулаком Тралла, я скучал по охоте на воинов Альянса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29944,'Лучшие производители','Рано откупоривать бочки, у нас еще есть дела. Эти гну-сини ничуть не отличаются от тех, что живут на Скитающемся острове... Назойливые паразиты, похожие на кроликов... и так же стремительно размножаются.$b$bНу да, мы можем убивать всех гну-синей без разбора, но какой в этом смысл? Лучше уничтожим альфа-самцов, и тогда скорость... размножения... гну-синей замедлится.','Уничтожьте Айюя "Сковородку", Жинаню Вилколапа и Буйноскока.','Вернитесь к Чэню Буйному Портеру на участок Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшие производители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рано откупоривать бочки, у нас еще есть дела. Эти гну-сини ничуть не отличаются от тех, что живут на Скитающемся острове... Назойливые паразиты, похожие на кроликов... и так же стремительно размножаются.$b$bНу да, мы можем убивать всех гну-синей без разбора, но какой в этом смысл? Лучше уничтожим альфа-самцов, и тогда скорость... размножения... гну-синей замедлится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Айюя "Сковородку", Жинаню Вилколапа и Буйноскока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29945,'Желтый и красный дают оранжевый','Дядя Чэнь говорит, что мы поможем тому парню избавиться от гну-синей. Я не против. ОБОЖАЮ злить гну-синей!$b$bПлан такой: покрасим репу в оранжевый цвет и попытаемся убедить гну-синей в том, что это морковь.$b$bВот будет умора!$b$bЯ соберу репу, а ты найди то, из чего можно сделать съедобную оранжевую краску.','Соберите 10 луговых бархатцев и 40 пузырьков с кровью животных.','Вернитесь к Ли Ли на участок Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Желтый и красный дают оранжевый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дядя Чэнь говорит, что мы поможем тому парню избавиться от гну-синей. Я не против. ОБОЖАЮ злить гну-синей!$b$bПлан такой: покрасим репу в оранжевый цвет и попытаемся убедить гну-синей в том, что это морковь.$b$bВот будет умора!$b$bЯ соберу репу, а ты найди то, из чего можно сделать съедобную оранжевую краску.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 луговых бархатцев и 40 пузырьков с кровью животных.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ли Ли на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (29946,'Прародительница','С альфа-самцами мы разобрались, осталась альфа-самка.$b$bГну-синям, в общем, все равно с кем спариваться, однако в большинстве выводков есть главная самка, прародительница. Обычно она больше, сильнее и злее остальных сородичей.$b$bЗнаешь, пожалуй, мне бы хотелось испытать свои силы в бою с такой самкой. Не хочешь ко мне присоединиться?','Победите Чуфу, прародительницу кривоскоков.','Вернитесь к Чэню Буйному Портеру на участок Грязной Кружки, что в Долине Четырех Ветров.','Прародительницами становятся не за красивые глаза.','Чуфа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прародительница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С альфа-самцами мы разобрались, осталась альфа-самка.$b$bГну-синям, в общем, все равно с кем спариваться, однако в большинстве выводков есть главная самка, прародительница. Обычно она больше, сильнее и злее остальных сородичей.$b$bЗнаешь, пожалуй, мне бы хотелось испытать свои силы в бою с такой самкой. Не хочешь ко мне присоединиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Чуфу, прародительницу кривоскоков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Прародительницами становятся не за красивые глаза.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чуфа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29947,'Крадущаяся морковь, затаившаяся репа','Дядя Чэнь продолжает за мной следить, а это значит, что в путешествие я отправлюсь нескоро. Похоже, нести в Извилистую нору эту репу... ну, то есть "морковь"... придется тебе.$b$bЭто несложно. Просто брось овощи перед кривоскоками, а затем смотри, как вытянутся их морды, когда они поймут, что на самом деле это репа!','Бросьте покрашенную в оранжевый репу перед 12 кривоскоками-барахольщиками.','Ха-ха-ха! Обожаю злить гну-синей.','Вернитесь к Ли Ли на участок Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крадущаяся морковь, затаившаяся репа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дядя Чэнь продолжает за мной следить, а это значит, что в путешествие я отправлюсь нескоро. Похоже, нести в Извилистую нору эту репу... ну, то есть "морковь"... придется тебе.$b$bЭто несложно. Просто брось овощи перед кривоскоками, а затем смотри, как вытянутся их морды, когда они поймут, что на самом деле это репа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте покрашенную в оранжевый репу перед 12 кривоскоками-барахольщиками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! Обожаю злить гну-синей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ли Ли на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29948,'Прирожденные воры','Вы с Чэнем оказали мне огромную услугу, расправившись с этими гну-синями. Я не люблю просить об одолжении, но и не отказываюсь от помощи.$b$bИ пока ты истребляешь этих тварей, то, может, заодно поищешь мои мешки с хмелем? Вчера вечером они пропали, и я почти уверен, что их утащили гну-сини.$b$bДумаю, они из них подушки сделали.','Найдите в Извилистой норе 6 украденных мешков хмеля.','О, сердечно вас благодарю, господин. Вы меня просто спасли.','Говорил я этим гну-синям – не лезьте на мою землю!','Вернитесь к Грязной Кружке на участок Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прирожденные воры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с Чэнем оказали мне огромную услугу, расправившись с этими гну-синями. Я не люблю просить об одолжении, но и не отказываюсь от помощи.$b$bИ пока ты истребляешь этих тварей, то, может, заодно поищешь мои мешки с хмелем? Вчера вечером они пропали, и я почти уверен, что их утащили гну-сини.$b$bДумаю, они из них подушки сделали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Извилистой норе 6 украденных мешков хмеля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, сердечно вас благодарю, господин. Вы меня просто спасли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Говорил я этим гну-синям – не лезьте на мою землю!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грязной Кружке на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (29949,'Наследие','За наши подвиги нам полагается награда. Скорее бы попробовать свежее пиво Грязной Кружки.','Выпейте с Чэнем, Ли Ли и Грязной Кружкой.','За дядю Чэня я не беспокоюсь – я знаю, он вернется.$B$BНа самом деле это же мой шанс отправиться в путешествие! Я обойду всю Пандарию, и никакой дядюшка меня не удержит!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За наши подвиги нам полагается награда. Скорее бы попробовать свежее пиво Грязной Кружки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте с Чэнем, Ли Ли и Грязной Кружкой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За дядю Чэня я не беспокоюсь – я знаю, он вернется.$B$BНа самом деле это же мой шанс отправиться в путешествие! Я обойду всю Пандарию, и никакой дядюшка меня не удержит!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29950,'Выходной Ли Ли','Когда дядя Чэнь уезжал, я дала ему слово, что не буду ввязываться ни в какие заварушки... но это не значит, что я не могу исследовать окрестности! Наконец-то я обойду всю Пандарию, не останавливаясь для отдыха через каждые сорок семь шагов!$b$bНе хочешь пойти со мной? Я уверена, в окрестностях много интересного.','Сводите Ли Ли на Шелковые поля, в Новую Циферу и к водопадам Хуаньцзы.','Это было замечательно! Как-нибудь нам с тобой нужно это повторить.$B$BИ, кстати, мы успели до возвращения дяди Чэня. Великолепно.','Отведите Ли Ли на участок Грязной Кружки в Долине Четырех Ветров, после чего поговорите с ней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выходной Ли Ли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда дядя Чэнь уезжал, я дала ему слово, что не буду ввязываться ни в какие заварушки... но это не значит, что я не могу исследовать окрестности! Наконец-то я обойду всю Пандарию, не останавливаясь для отдыха через каждые сорок семь шагов!$b$bНе хочешь пойти со мной? Я уверена, в окрестностях много интересного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сводите Ли Ли на Шелковые поля, в Новую Циферу и к водопадам Хуаньцзы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это было замечательно! Как-нибудь нам с тобой нужно это повторить.$B$BИ, кстати, мы успели до возвращения дяди Чэня. Великолепно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отведите Ли Ли на участок Грязной Кружки в Долине Четырех Ветров, после чего поговорите с ней.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29951,'Мутная вода','Раз уж ты все равно крутишься у меня под ногами, то, пожалуй, я ознакомлю тебя с азами пивоварения. Если честно, это совсем не сложно... Я просто смешиваю все в огромном чане и жду.$b$bВозможно, ты уже знаешь, что я люблю брать воду из реки, что течет к югу отсюда. Ты не $gмог:могла; бы наполнить такой водой вот этот сосуд? А я пока займусь хмелем и ячменем.','Наберите мутную воду в сосуд Грязной Кружки.','Ты молодец, Эрезул. Молодец.','Я сразу понял, что ты настоящий друг.','Вернитесь к Грязной Кружке на участок Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мутная вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты все равно крутишься у меня под ногами, то, пожалуй, я ознакомлю тебя с азами пивоварения. Если честно, это совсем не сложно... Я просто смешиваю все в огромном чане и жду.$b$bВозможно, ты уже знаешь, что я люблю брать воду из реки, что течет к югу отсюда. Ты не $gмог:могла; бы наполнить такой водой вот этот сосуд? А я пока займусь хмелем и ячменем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите мутную воду в сосуд Грязной Кружки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец, Эрезул. Молодец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я сразу понял, что ты настоящий друг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грязной Кружке на участок Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29952,'Разбитые мечты','Выслушайте Чэня Буйного Портера.','Может, мне никогда не суждено остепениться.','Поговорите с Чэнем Буйным Портером на участке Грязной Кружки, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбитые мечты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Чэня Буйного Портера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Может, мне никогда не суждено остепениться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером на участке Грязной Кружки, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29966,'Дотла!','$n, смотри!$B$BЭти собаки из Альянса встали лагерем на гребне.$B$BВот, держи мой грог. Разведем такой костер, чтобы видно было из самого Штормграда!$B$BЗа Орду!','С помощью грога Назгрима уничтожьте лагерь Альянса на вершине Утеса дивного вида.','Ядыч, Альянс нужно изгнать с этой земли!$B$BИ полумеры здесь не помогут!','Поговорите с Назгримом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дотла!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, смотри!$B$BЭти собаки из Альянса встали лагерем на гребне.$B$BВот, держи мой грог. Разведем такой костер, чтобы видно было из самого Штормграда!$B$BЗа Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью грога Назгрима уничтожьте лагерь Альянса на вершине Утеса дивного вида.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ядыч, Альянс нужно изгнать с этой земли!$B$BИ полумеры здесь не помогут!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Назгримом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29967,'И как бабахнет!','Чрезвычайная ситуация!$b$bУбив парочку этих рыбешек, ты, похоже, $gразворошил:разворошила; настоящее осиное гнездо!$b$bОни наступают на холм Грукин!$b$bЯ надеялся, что у меня еще будет время на эксперименты, но, кажется, мои метановые гранаты придется проверять уже на практике!$b$bВстретимся в восточной части форта. Приготовься – придется много бросать!','Поговорите с Риветтом, который стоит к востоку от холма Грукин. Воспользуйтесь его метановыми гранатами, чтобы отразить атаку цзинь-юй.','"Отразить атаку" – это еще мягко сказано!','Поговорите с Риветтом к востоку от холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И как бабахнет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чрезвычайная ситуация!$b$bУбив парочку этих рыбешек, ты, похоже, $gразворошил:разворошила; настоящее осиное гнездо!$b$bОни наступают на холм Грукин!$b$bЯ надеялся, что у меня еще будет время на эксперименты, но, кажется, мои метановые гранаты придется проверять уже на практике!$b$bВстретимся в восточной части форта. Приготовься – придется много бросать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Риветтом, который стоит к востоку от холма Грукин. Воспользуйтесь его метановыми гранатами, чтобы отразить атаку цзинь-юй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','"Отразить атаку" – это еще мягко сказано!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом к востоку от холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29968,'Экологически чистая энергия','Только одно слово: метан!$b$bПереходим на экологически чистые продукты. Смотри: чистое горение, сырье доступное, натуральное, а когда вернемся, друиды наконец-то от меня отстанут.$b$bНу и, кроме того, у меня закончился порох.$b$bПоэтому мне нужна твоя помощь, $n.$b$bНет-нет, я не собираюсь просить тебя делать грязную работу – уж точно не перед генералом. Собирать эти "залежи" предоставь мне.$b$bА ты пока набери дерева для строительства уборной – я мыслю стратегически!','Соберите 7 зеленых ветвей в Дуковых полях.','А-а, метан... Это запах прогресса!','Остерегайся мокрых!.. У-у-у!','Поговорите с Риветтом Сталехватом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экологически чистая энергия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только одно слово: метан!$b$bПереходим на экологически чистые продукты. Смотри: чистое горение, сырье доступное, натуральное, а когда вернемся, друиды наконец-то от меня отстанут.$b$bНу и, кроме того, у меня закончился порох.$b$bПоэтому мне нужна твоя помощь, $n.$b$bНет-нет, я не собираюсь просить тебя делать грязную работу – уж точно не перед генералом. Собирать эти "залежи" предоставь мне.$b$bА ты пока набери дерева для строительства уборной – я мыслю стратегически!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 зеленых ветвей в Дуковых полях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-а, метан... Это запах прогресса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Остерегайся мокрых!.. У-у-у!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом Сталехватом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29971,'Возвращение разведчиков','Слушай, пока тебя не было, вернулись разведчики. И это еще не все: они привели какого-то парнишку из Альянса.$B$BНаверное, тебе стоит с ними поговорить.','Поговорите с Шокией на холме Грукин.','Возможно, у нас проблема.','Поговорите с Шокией на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение разведчиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, пока тебя не было, вернулись разведчики. И это еще не все: они привели какого-то парнишку из Альянса.$B$BНаверное, тебе стоит с ними поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шокией на холме Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, у нас проблема.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Шокией на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (29981,'Остановить стаю','Я не местная и прибыла-то сюда только сегодня. Но уже чувствую – здесь что-то не так.$b$bВон та стена должна защищать пандаренов от богомолов. Но теперь богомолы посылают вперед крылатых разведчиков, для которых этой стены словно и не существует!$b$bИ разведчики эти остаются невредимыми только потому, что им противостоят не солдаты, а крестьяне. Но против такого героя, как ты, у богомолов нет ни одного шанса.','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить стаю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не местная и прибыла-то сюда только сегодня. Но уже чувствую – здесь что-то не так.$b$bВон та стена должна защищать пандаренов от богомолов. Но теперь богомолы посылают вперед крылатых разведчиков, для которых этой стены словно и не существует!$b$bИ разведчики эти остаются невредимыми только потому, что им противостоят не солдаты, а крестьяне. Но против такого героя, как ты, у богомолов нет ни одного шанса.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29982,'Приказ об эвакуации','На полях еще остались фермеры... и кое-кто из них оказался слишком близко к обветшавшей стене. Я не хочу, чтобы крестьяне строили из себя героев. Мы сами разберемся со стаей богомолов, а затем крестьяне смогут вернуться в свои дома.$b$bМонахи Шадо-Пан обороняют город, им некогда заниматься эвакуацией мирных жителей. Ты хочешь показать себя в деле, да? Тогда отведи этих крестьян в безопасное место.','Эвакуируйте семьи Черной Земли, Острой Лапы, Зеленого Пахаря и Грязной Шкуры.','Какие-то упрямые скотоводы хотят осложнить мне жизнь?$B$B<Командир стражи вздыхает.>$B$BНу хорошо. У каждого пандарена есть право защищать свою землю.','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ об эвакуации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На полях еще остались фермеры... и кое-кто из них оказался слишком близко к обветшавшей стене. Я не хочу, чтобы крестьяне строили из себя героев. Мы сами разберемся со стаей богомолов, а затем крестьяне смогут вернуться в свои дома.$b$bМонахи Шадо-Пан обороняют город, им некогда заниматься эвакуацией мирных жителей. Ты хочешь показать себя в деле, да? Тогда отведи этих крестьян в безопасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эвакуируйте семьи Черной Земли, Острой Лапы, Зеленого Пахаря и Грязной Шкуры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие-то упрямые скотоводы хотят осложнить мне жизнь?$B$B<Командир стражи вздыхает.>$B$BНу хорошо. У каждого пандарена есть право защищать свою землю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29983,'Тайный мастер','Теперь мы уже сами сможем защитить Каменный Плуг.$b$b<Командир стражи указывает на Линь Мягкую Лапу.>$b$bЛинь ищет некоего "тайного мастера". Кажется, я знаю, кто это – и где он находится.$b$bОтправляйся на север.','Ты хочешь обучаться воинскому искусству?$B$B<Пандарен внимательно вас разглядывает.>$B$BОтлично.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайный мастер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы уже сами сможем защитить Каменный Плуг.$b$b<Командир стражи указывает на Линь Мягкую Лапу.>$b$bЛинь ищет некоего "тайного мастера". Кажется, я знаю, кто это – и где он находится.$b$bОтправляйся на север.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хочешь обучаться воинскому искусству?$B$B<Пандарен внимательно вас разглядывает.>$B$BОтлично.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29984,'Кулаки храбреца: испытание бамбуком','Мы начнем с испытания бамбуком.$b$bТвоя подруга Линь, кстати, его провалила.$b$bСледуй за мной и внимательно слушай.','Поговорите с мастером Побитой Лапой, а затем 3 раза нанесите удар по связке бамбуковых палок.','Пэкк, да у тебя способности! Итак, продолжим.$B$BПервый этап обучения начинается.','Поговорите с мастером Побитая Лапа в лощине Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулаки храбреца: испытание бамбуком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы начнем с испытания бамбуком.$b$bТвоя подруга Линь, кстати, его провалила.$b$bСледуй за мной и внимательно слушай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Побитой Лапой, а затем 3 раза нанесите удар по связке бамбуковых палок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пэкк, да у тебя способности! Итак, продолжим.$B$BПервый этап обучения начинается.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Побитая Лапа в лощине Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29985,'Там, за туманами','В этом лесу очень туманно – а в туманах бродят странные существа, с которыми постоянно приходится воевать. Все это очень утомительно, вот почему я с радостью поручаю это дело ученикам вроде тебя.$b$bСчитай это частью обучения.','Уничтожьте 12 порождений тумана.','Пэкк, ты отлично выполняешь указания.','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Там, за туманами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом лесу очень туманно – а в туманах бродят странные существа, с которыми постоянно приходится воевать. Все это очень утомительно, вот почему я с радостью поручаю это дело ученикам вроде тебя.$b$bСчитай это частью обучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 порождений тумана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пэкк, ты отлично выполняешь указания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29986,'Стражи тумана','Ученик!$b$bВ этом лесу скрыто несколько стражей – они довольно эффективно разгоняют туман, но за ними нужно постоянно ухаживать.$b$bОдин находится на севере, второй на западе, третий на юге. Найди их все и зажги.','Зажгите северный, западный и южный стражи тумана.','Приль, ты делаешь честь своему народу.','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи тумана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ученик!$b$bВ этом лесу скрыто несколько стражей – они довольно эффективно разгоняют туман, но за ними нужно постоянно ухаживать.$b$bОдин находится на севере, второй на западе, третий на юге. Найди их все и зажги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите северный, западный и южный стражи тумана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приль, ты делаешь честь своему народу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29987,'Кулаки храбреца: испытание деревом','Кажется, ты делаешь успехи. Пойдем со мной – тебя ждет испытание деревом.','Поговорите с мастером Побитой Лапой, затем 4 раза нанесите удар по штабелю досок.','Пэкк, ты умеешь сосредоточить все внимание на работе – а на это способны далеко не все мои ученики.$B$B<Мастер Побитая Лапа бросает взгляд на Линь.>','Поговорите с мастером Побитая Лапа в лощине Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кулаки храбреца: испытание деревом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, ты делаешь успехи. Пойдем со мной – тебя ждет испытание деревом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Побитой Лапой, затем 4 раза нанесите удар по штабелю досок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пэкк, ты умеешь сосредоточить все внимание на работе – а на это способны далеко не все мои ученики.$B$B<Мастер Побитая Лапа бросает взгляд на Линь.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Побитая Лапа в лощине Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29988,'Любовь к яйцам','Я понимаю твое нетерпение, но, к сожалению, ты еще не $gготов:готова;. Ты $gдолжен:должна; продолжать обучение, пока не настанет день последнего испытания. Что же касается очередной задачи... принеси мне яиц.$b$bДа, яиц. В болоте к востоку отсюда живет множество разных птиц... в общем-то довольно мирных. Думаю, ты без труда соберешь столько яиц, что их хватит на несколько недель.','Принесите 10 яиц императорской крачки, 4 яйца журавля-рыболова и 1 яйцо рогоклювого долгонога.','Теперь ты понимаешь, почему я поручаю собирать яйца другим.$B$BНу что, продолжим обучение?','Как продвигается сбор яиц?','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любовь к яйцам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понимаю твое нетерпение, но, к сожалению, ты еще не $gготов:готова;. Ты $gдолжен:должна; продолжать обучение, пока не настанет день последнего испытания. Что же касается очередной задачи... принеси мне яиц.$b$bДа, яиц. В болоте к востоку отсюда живет множество разных птиц... в общем-то довольно мирных. Думаю, ты без труда соберешь столько яиц, что их хватит на несколько недель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 яиц императорской крачки, 4 яйца журавля-рыболова и 1 яйцо рогоклювого долгонога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты понимаешь, почему я поручаю собирать яйца другим.$B$BНу что, продолжим обучение?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается сбор яиц?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Побитой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (29990,'Обучение и дисциплина','И я сказала себе – если когда-нибудь найду тайного мастера, то научусь у него всему, что он знает. $n, это мой шанс, и я его не упущу.$b$bИ все же, боюсь, что мы все еще нужны Каменному Плугу. Я ушла слишком рано, не успев отогнать богомолов-разведчиков. Если ты навестишь командира стражи, я буду чувствовать себя гораздо спокойнее.$b$bДа, и если найдешь остальных, можешь сказать им, где прячется тайный мастер...','Приятно слышать, что у Линь все хорошо.$B$BНаши укрепления пока держатся. Да, время от времени разведчики богомолов перелетают через стены, но не более того.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение и дисциплина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И я сказала себе – если когда-нибудь найду тайного мастера, то научусь у него всему, что он знает. $n, это мой шанс, и я его не упущу.$b$bИ все же, боюсь, что мы все еще нужны Каменному Плугу. Я ушла слишком рано, не успев отогнать богомолов-разведчиков. Если ты навестишь командира стражи, я буду чувствовать себя гораздо спокойнее.$b$bДа, и если найдешь остальных, можешь сказать им, где прячется тайный мастер...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно слышать, что у Линь все хорошо.$B$BНаши укрепления пока держатся. Да, время от времени разведчики богомолов перелетают через стены, но не более того.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29992,'Мягкая Лапа – во всех смыслах этого слова','Я хочу рассказать Сяо, Кану и всем остальным, что нашла тайного мастера, но он меня не отпускает! Говорит, сначала я должна пройти испытание бамбуком.$b$b<Линь шепчет:> Кстати, как тебе это удалось?$b$bПохоже, мне еще долго придется торчать здесь и бесконечно колотить кулаками. А костяшки пальцев уже скоро просто треснут!$b$bПожалуйста, набери листьев нефритовой луны – я сделаю из них мазь, снимающую боль.','Соберите 18 листьев нефритовой луны.','<Линь натирает листьями распухшие лапы.>$B$BСпасибо! Потом я сделаю мазь, но пока что хватит и этого.','Ой! Ой! Ой!','Вернитесь к Линь Мягкой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мягкая Лапа – во всех смыслах этого слова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу рассказать Сяо, Кану и всем остальным, что нашла тайного мастера, но он меня не отпускает! Говорит, сначала я должна пройти испытание бамбуком.$b$b<Линь шепчет:> Кстати, как тебе это удалось?$b$bПохоже, мне еще долго придется торчать здесь и бесконечно колотить кулаками. А костяшки пальцев уже скоро просто треснут!$b$bПожалуйста, набери листьев нефритовой луны – я сделаю из них мазь, снимающую боль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 18 листьев нефритовой луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Линь натирает листьями распухшие лапы.>$B$BСпасибо! Потом я сделаю мазь, но пока что хватит и этого.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ой! Ой! Ой!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линь Мягкой Лапе в лощину Паоцюань, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29993,'В поисках юноши','Ты не $gвидел:видела; моего сына Ло? Вот буквально только что был здесь, и я ему сказал, что сегодня мы уезжаем!$B$BНаверняка снова пытается ухлестывать за юной Сирой Золотистый Нектар. Это именно из-за нее нам и приходится покидать родные края!$B$BЯ не потерплю, чтобы мой сын бегал за девушкой из рода Золотистого Нектара!$B$BЯ отправляюсь на их поиски.$B$BЯ каждый раз ловлю эту парочку, когда они тайком бегают в Дендрарий. Может, заглянешь туда и поищешь их?','Поговорите с мастером каллиграфии Вэем.','Ты ищешь двух влюбленных, глухих к амбициям своих семей. Они были здесь – хотели узнать, как им не сойти с выбранного пути.$B$BК сожалению, они не нашли ответов ни в шелесте листвы, ни в красках неба.','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках юноши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gвидел:видела; моего сына Ло? Вот буквально только что был здесь, и я ему сказал, что сегодня мы уезжаем!$B$BНаверняка снова пытается ухлестывать за юной Сирой Золотистый Нектар. Это именно из-за нее нам и приходится покидать родные края!$B$BЯ не потерплю, чтобы мой сын бегал за девушкой из рода Золотистого Нектара!$B$BЯ отправляюсь на их поиски.$B$BЯ каждый раз ловлю эту парочку, когда они тайком бегают в Дендрарий. Может, заглянешь туда и поищешь их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером каллиграфии Вэем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты ищешь двух влюбленных, глухих к амбициям своих семей. Они были здесь – хотели узнать, как им не сойти с выбранного пути.$B$BК сожалению, они не нашли ответов ни в шелесте листвы, ни в красках неба.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29995,'Святилище Рассвета','Что бы ни говорили главы семей, "дети", которых ты разыскиваешь, на самом деле взрослые пандарены. Их любовь сильнее вражды их семей.$B$BТы найдешь Сиру и Ло в Святилище Рассвета – они обратились за советом к великим пандриархам древности.','Найдите Сиру Золотистый Нектар в Святилище Рассвета.','О, незнакомец! Пожалуйста, скажи, что ты сможешь помочь нам! Мой Ло тяжело ранен!','Поговорите с Сирой Золотистый Нектар в Святилище Рассвета в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что бы ни говорили главы семей, "дети", которых ты разыскиваешь, на самом деле взрослые пандарены. Их любовь сильнее вражды их семей.$B$BТы найдешь Сиру и Ло в Святилище Рассвета – они обратились за советом к великим пандриархам древности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сиру Золотистый Нектар в Святилище Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, незнакомец! Пожалуйста, скажи, что ты сможешь помочь нам! Мой Ло тяжело ранен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сирой Золотистый Нектар в Святилище Рассвета в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (29997,'Дилемма провидца','Убейте водяных демонов, чтобы добыть посох Мудрого Мариса.','Вода слишком мутная. Мне нужен посох, чтобы успокоить духов и поговорить с водой.','Вернитесь к Мудрому Марису в Храм Нефритовой Змеи в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дилемма провидца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте водяных демонов, чтобы добыть посох Мудрого Мариса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вода слишком мутная. Мне нужен посох, чтобы успокоить духов и поговорить с водой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мудрому Марису в Храм Нефритовой Змеи в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (29998,'Заботы библиотекаря','Хранитель истории Каменная Поступь заведует всей библиотекой храма. Но в последнее время что-то беспокоит его и мешает работать.$B$BИ это весьма прискорбно, ведь ему нужно переписать тысячи древних манускриптов.$B$BТы не $gмог:могла; бы сходить по южной дороге к библиотеке и узнать, что его тревожит?','Поговорите с хранителем истории Каменной Поступью в библиотеке храма.','Тебя послал верховный жрец дождя Чжу?$B$BОтлично, поможешь мне.','Вернитесь к Фэй во двор Храма Нефритовой Змеи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заботы библиотекаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хранитель истории Каменная Поступь заведует всей библиотекой храма. Но в последнее время что-то беспокоит его и мешает работать.$B$BИ это весьма прискорбно, ведь ему нужно переписать тысячи древних манускриптов.$B$BТы не $gмог:могла; бы сходить по южной дороге к библиотеке и узнать, что его тревожит?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Каменной Поступью в библиотеке храма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал верховный жрец дождя Чжу?$B$BОтлично, поможешь мне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фэй во двор Храма Нефритовой Змеи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (29999,'Узы наездника','Ты случайно не $gвидел:видела; на тренировочном дворе молодых змеев?$B$BМалыши любят пошалить – и на этот раз несколько из них сбежали, чтобы поиграть до начала занятий. $B$BЕсли наставница заметит, что их нет, она так рассердится!$B$BТы не $gмог:могла; бы привести их ко мне? Я не хочу, чтобы их наказали.$B$BОни любят играть на свежем воздухе, так что ищи их во дворах и вокруг шпилей.','Найдите 4 игривых змеев.','Вернитесь к Фэй во двор Храма Нефритовой Змеи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узы наездника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты случайно не $gвидел:видела; на тренировочном дворе молодых змеев?$B$BМалыши любят пошалить – и на этот раз несколько из них сбежали, чтобы поиграть до начала занятий. $B$BЕсли наставница заметит, что их нет, она так рассердится!$B$BТы не $gмог:могла; бы привести их ко мне? Я не хочу, чтобы их наказали.$B$BОни любят играть на свежем воздухе, так что ищи их во дворах и вокруг шпилей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 4 игривых змеев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фэй во двор Храма Нефритовой Змеи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30000,'Нефритовая Змея','У тебя сообщение для Нефритовой змеи?$B$B<Девочка вопросительно смотрит на вас.>$B$BПохоже, тебе пора наконец с ней встретиться.','Выслушайте Нефритовую Змею.','Вернитесь к верховной жрице ветра И в земли Нефритового храма, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нефритовая Змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя сообщение для Нефритовой змеи?$B$B<Девочка вопросительно смотрит на вас.>$B$BПохоже, тебе пора наконец с ней встретиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Нефритовую Змею.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице ветра И в земли Нефритового храма, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30001,'Нашествие моли','Библиотеку наводнила моль. Моль!$B$BКаждый библиотекарь знает, что моль – самый опасный враг книг, за исключением книжных червей.$B$BНо оказалось, что все мои помощники – жалкие трусы! Они боятся насекомых!$B$BПожалуйста, помоги мне! Ты $gдолжен:должна; немедленно избавить нас от моли! От этого зависит судьба тысяч пандарийских литературных памятников!','Уничтожьте 8 пятнистых мотыльков.','Да-да, спасибо! Тебе удалось значительно сократить их численность. Это чудесно!','Вернитесь к Хранителю свитка в библиотеку Храма Нефритовой Змеи в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие моли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Библиотеку наводнила моль. Моль!$B$BКаждый библиотекарь знает, что моль – самый опасный враг книг, за исключением книжных червей.$B$BНо оказалось, что все мои помощники – жалкие трусы! Они боятся насекомых!$B$BПожалуйста, помоги мне! Ты $gдолжен:должна; немедленно избавить нас от моли! От этого зависит судьба тысяч пандарийских литературных памятников!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 пятнистых мотыльков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да, спасибо! Тебе удалось значительно сократить их численность. Это чудесно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хранителю свитка в библиотеку Храма Нефритовой Змеи в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30002,'Страницы истории','$r, сбылся худший из наших кошмаров.$B$BУ нас. Завелись. Книжные. Черви.$B$BПоложение угрожающее. Их необходимо как можно быстрее уничтожить, пока они не расплодились. $B$BВрага нужно раздавить – в буквальном смысле слова! Пожалуйста, осмотри зараженные книги в библиотеке и раздави всех книжных червей, которых найдешь.','Найдите в библиотеке источники заражения и раздавите 12 книжных червей.','Чудесно! Какое счастье, что нам удалось предотвратить катастрофу.$B$BНет-нет, пожалуйста, не подходи. У тебя на башмаках ошметки червяков налипли.','Вернитесь к Хранителю свитка в библиотеку Храма Нефритовой Змеи в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страницы истории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$r, сбылся худший из наших кошмаров.$B$BУ нас. Завелись. Книжные. Черви.$B$BПоложение угрожающее. Их необходимо как можно быстрее уничтожить, пока они не расплодились. $B$BВрага нужно раздавить – в буквальном смысле слова! Пожалуйста, осмотри зараженные книги в библиотеке и раздави всех книжных червей, которых найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в библиотеке источники заражения и раздавите 12 книжных червей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Какое счастье, что нам удалось предотвратить катастрофу.$B$BНет-нет, пожалуйста, не подходи. У тебя на башмаках ошметки червяков налипли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хранителю свитка в библиотеку Храма Нефритовой Змеи в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30003,'Не суди о книге по обложке') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не суди о книге по обложке',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30004,'Все на своем месте','$n, ты даже представить себе не можешь, какую огромную помощь ты нам $gоказал:оказала;. $B$BЕсли бы драгоценные свитки погибли, то я даже не знаю, что бы я делал.$B$BПожалуйста, сообщи верховному жрецу дождя Чжу о том, что в библиотеке все в порядке.','Хранитель истории Каменная Поступь вернулся к работе?$B$BНевероятно. Ты сделал то, что не удалось четырем жрецам.$B$BКажется... кажется, моя головная боль проходит!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все на своем месте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты даже представить себе не можешь, какую огромную помощь ты нам $gоказал:оказала;. $B$BЕсли бы драгоценные свитки погибли, то я даже не знаю, что бы я делал.$B$BПожалуйста, сообщи верховному жрецу дождя Чжу о том, что в библиотеке все в порядке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хранитель истории Каменная Поступь вернулся к работе?$B$BНевероятно. Ты сделал то, что не удалось четырем жрецам.$B$BКажется... кажется, моя головная боль проходит!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30005,'Огни в небе','Тебе нравятся фейерверки?$B$BЯ их обожаю! В старину мы пугали ими демонов, но лично мне они нравятся за красоту!$B$BКажется, в храме еще остались старые пусковые установки. $B$BТы не $gмог:могла; бы запустить большой фейерверк? Ведь фейерверк – это такая красота!','Запустите 8 фейерверков.','Ура! Фейерверк было видно даже отсюда!$B$BБольшое спасибо, Эрезул.','Вернитесь к Фэй в Храм Нефритовой Змеи, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огни в небе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нравятся фейерверки?$B$BЯ их обожаю! В старину мы пугали ими демонов, но лично мне они нравятся за красоту!$B$BКажется, в храме еще остались старые пусковые установки. $B$BТы не $gмог:могла; бы запустить большой фейерверк? Ведь фейерверк – это такая красота!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запустите 8 фейерверков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Фейерверк было видно даже отсюда!$B$BБольшое спасибо, Эрезул.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фэй в Храм Нефритовой Змеи, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30006,'Тьма вокруг нас','Несмотря на все наши усилия, ша разбили печати вокруг главного храма.$B$BЕсли мы не удержим их, тьма расползется по всему Нефритовому лесу.$B$BНам немедленно нужна твоя помощь. Убивай всех ша, которых встретишь. Найти их будет несложно.','Уничтожьте 15 ша-захватчиков.','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тьма вокруг нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на все наши усилия, ша разбили печати вокруг главного храма.$B$BЕсли мы не удержим их, тьма расползется по всему Нефритовому лесу.$B$BНам немедленно нужна твоя помощь. Убивай всех ша, которых встретишь. Найти их будет несложно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 ша-захватчиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма.',`completedtext_loc8`);
