INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30009,'Сбор войск в форте Грукин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор войск в форте Грукин',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30011,'Новое видение','Пожалуйста, сообщи верховному жрецу дождя Чжу о том, что я немедленно приступаю к работе.','Провидец снова медитирует! Прекрасно! С моих плеч снят огромный груз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое видение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, сообщи верховному жрецу дождя Чжу о том, что я немедленно приступаю к работе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Провидец снова медитирует! Прекрасно! С моих плеч снят огромный груз.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30015,'Цветущая Заря','Кровь и гром! Мой топор жаждет крови!$B$BМы не вернемся в Оргриммар до тех пор, пока не уничтожим последнего солдата Альянса в этой стране.$B$BЯ лично обучу аборигенов, если потребуется. Так или иначе, этот край станет владением Орды!$B$BА пока что возьми – эту карту и какое-то странное послание просил передать тебе местный вождь.$B$BДелай, что $gдолжен:должна;, но поторопись.$B$BВойна скоро начнется...','Поговорите с хранителем истории Чо в Цветущей Заре.$b$bЧтобы добраться туда, поговорите с распорядителем полетов на холме Грукин.','Приветствую, Тилепа!$B$BДобро пожаловать в Цветущую Зарю, дом моего народа.$B$BУвы, но я должен уехать. У хранителя истории всегда полно работы.$B$BЧувствуй себя как дома. Моим соотечественникам, несомненно, пригодятся твои таланты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цветущая Заря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь и гром! Мой топор жаждет крови!$B$BМы не вернемся в Оргриммар до тех пор, пока не уничтожим последнего солдата Альянса в этой стране.$B$BЯ лично обучу аборигенов, если потребуется. Так или иначе, этот край станет владением Орды!$B$BА пока что возьми – эту карту и какое-то странное послание просил передать тебе местный вождь.$B$BДелай, что $gдолжен:должна;, но поторопись.$B$BВойна скоро начнется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо в Цветущей Заре.$b$bЧтобы добраться туда, поговорите с распорядителем полетов на холме Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, Тилепа!$B$BДобро пожаловать в Цветущую Зарю, дом моего народа.$B$BУвы, но я должен уехать. У хранителя истории всегда полно работы.$B$BЧувствуй себя как дома. Моим соотечественникам, несомненно, пригодятся твои таланты.',`offerrewardtext_loc8`);
