INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30027,'Урок железной ветви','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30028,'Грабь награбленное','Раз уж ты идешь на юг, может, попытаешься вернуть украденное у меня зерно?$b$bМы все видели, как птицы и духи улепетывают с целыми мешками зерна. Думаю, их можно найти в полях к востоку и к югу отсюда.','Принесите 8 мешков с зерном хранителю зерна Каю.','Большое спасибо, незнакомец. День выдался не очень, но ты сделал его лучше.$B$BПожалуйста, прими эту заслуженную награду.','Из-за этих птиц и духов мы не сможем доставить сырье в Хмелеварню Буйных Портеров.','Поговорите с хранителем зерна Каем в Императорском хранилище зерна в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабь награбленное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты идешь на юг, может, попытаешься вернуть украденное у меня зерно?$b$bМы все видели, как птицы и духи улепетывают с целыми мешками зерна. Думаю, их можно найти в полях к востоку и к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 мешков с зерном хранителю зерна Каю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо, незнакомец. День выдался не очень, но ты сделал его лучше.$B$BПожалуйста, прими эту заслуженную награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из-за этих птиц и духов мы не сможем доставить сырье в Хмелеварню Буйных Портеров.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем зерна Каем в Императорском хранилище зерна в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30029,'Злые проделки','Уничтожьте 8 зерновых ловкачей.','Спасибо за помощь, незнакомец! Надеюсь, дальше мы сами справимся.','Поговорите с хранителем зерна Каем в Императорском хранилище зерна в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злые проделки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 зерновых ловкачей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, незнакомец! Надеюсь, дальше мы сами справимся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем зерна Каем в Императорском хранилище зерна в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30030,'Духоборство','Давай сразу проясним одну вещь: это был несчастный случай. Я действовал во имя развития ПРОМЫШЛЕННОСТИ!$b$bОткуда я мог знать, что в любую минуту могут напасть духи – и что в их распоряжении окажется моя "Волшебная смесь Паня".$b$bИ теперь их возглавляет огромный и невероятно злобный дух.$b$bЕсли я тебе заплачу, ты его уничтожишь?','Победите Зерноеда Истребителя Ячменя.','Теперь, когда все закончилось, у меня появились мысли насчет нового напитка. Посмотрим.$B$BСпасибо за помощь. Вот твоя награда.','Поговорите с мукомолом Панем в Императорском хранилище зерна в Долине Четырех Ветров.','Вот что бывает, когда в руках лесных духов оказывается Волшебная смесь Паня.','Зерноед Истребитель Ячменя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духоборство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай сразу проясним одну вещь: это был несчастный случай. Я действовал во имя развития ПРОМЫШЛЕННОСТИ!$b$bОткуда я мог знать, что в любую минуту могут напасть духи – и что в их распоряжении окажется моя "Волшебная смесь Паня".$b$bИ теперь их возглавляет огромный и невероятно злобный дух.$b$bЕсли я тебе заплачу, ты его уничтожишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зерноеда Истребителя Ячменя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда все закончилось, у меня появились мысли насчет нового напитка. Посмотрим.$B$BСпасибо за помощь. Вот твоя награда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мукомолом Панем в Императорском хранилище зерна в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вот что бывает, когда в руках лесных духов оказывается Волшебная смесь Паня.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зерноед Истребитель Ячменя',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30031,'Дегустация','Раз уж ты здесь, то чем сидеть без дела, лучше помоги. Мне кажется, что для этого дела я не гожусь – ведь я совсем не пью пиво.$b$bПопробуй немного зерен каждого вида. Посмотрим, есть ли тут сладкое зерно, которое так нужно дяде Чэню.','Попробуйте лежалое зерно, легкое зерно, свежее зерно и солодовое зерно.','Похоже, все это зерно нам не подойдет. Дядя Чэнь на редкость привередлив.$B$BМожет, хозяин зерна знает, где хранится что-то... особенное?','Поговорите с Ли Ли в Императорском хранилище зерна в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дегустация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты здесь, то чем сидеть без дела, лучше помоги. Мне кажется, что для этого дела я не гожусь – ведь я совсем не пью пиво.$b$bПопробуй немного зерен каждого вида. Посмотрим, есть ли тут сладкое зерно, которое так нужно дяде Чэню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попробуйте лежалое зерно, легкое зерно, свежее зерно и солодовое зерно.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, все это зерно нам не подойдет. Дядя Чэнь на редкость привередлив.$B$BМожет, хозяин зерна знает, где хранится что-то... особенное?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ли Ли в Императорском хранилище зерна в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30032,'В поисках идеального ячменя','Тебе нужно сладкое зерно? Помню, отец рассказывал про какой-то солодовый ячмень – кажется, он тебе подойдет. Если, конечно, ты не боишься риска.$b$bНа юге, в Крае ветров, есть пещера.$b$bИ еще там находится старый подъемник, который мой отец соорудил, когда странствовал по джунглям.$b$bВ пещере растет куст – такой же древний, как и мое семейство. С этого куста можно набрать зерна такого сладкого, что просто слов нет.$b$bНо будь $gосторожен:осторожна;: куст охраняют стражи.','Найдите солодовый ячмень в Крае ветров.','По запаху чую: ЭТО – оно самое!','В джунглях раздаются жуткие звуки.','Поговорите с Ли Ли в Императорском хранилище зерна в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках идеального ячменя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно сладкое зерно? Помню, отец рассказывал про какой-то солодовый ячмень – кажется, он тебе подойдет. Если, конечно, ты не боишься риска.$b$bНа юге, в Крае ветров, есть пещера.$b$bИ еще там находится старый подъемник, который мой отец соорудил, когда странствовал по джунглям.$b$bВ пещере растет куст – такой же древний, как и мое семейство. С этого куста можно набрать зерна такого сладкого, что просто слов нет.$b$bНо будь $gосторожен:осторожна;: куст охраняют стражи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите солодовый ячмень в Крае ветров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','По запаху чую: ЭТО – оно самое!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В джунглях раздаются жуткие звуки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ли Ли в Императорском хранилище зерна в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30033,'Урок железной ветви','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Выбери себе чародейский клинок и веер на одной из оружейных стоек внизу, принеси его и покажи мне, что ты умеешь правильно его держать.','Получите чародейский клинок ученика и веер ученика.','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Выбери себе чародейский клинок и веер на одной из оружейных стоек внизу, принеси его и покажи мне, что ты умеешь правильно его держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите чародейский клинок ученика и веер ученика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30034,'Урок железной ветви','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Выбери себе подходящий арбалет на оружейных стойках внизу. Принеси его мне и покажи, что ты умеешь правильно его держать.','Получите арбалет ученика и возьмите его в руки.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Выбери себе подходящий арбалет на оружейных стойках внизу. Принеси его мне и покажи, что ты умеешь правильно его держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите арбалет ученика и возьмите его в руки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30035,'Урок железной ветви','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань палицу и книгу молитв – ты найдешь их внизу, на оружейных стойках. Принеси их мне и продемонстрируй свое умение правильно их держать.','Получите палицу ученика и книгу молитв для учеников и возьмите их.','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань палицу и книгу молитв – ты найдешь их внизу, на оружейных стойках. Принеси их мне и продемонстрируй свое умение правильно их держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите палицу ученика и книгу молитв для учеников и возьмите их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30036,'Урок железной ветви','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань пару кинжалов – ты найдешь их внизу, на оружейных стойках. Принеси их и покажи, что ты умеешь правильно их держать.','Получите пару кинжалов ученика и возьмите их.','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань пару кинжалов – ты найдешь их внизу, на оружейных стойках. Принеси их и покажи, что ты умеешь правильно их держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите пару кинжалов ученика и возьмите их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30037,'Урок железной ветви','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань топор и щит – ты найдешь их внизу, на оружейных стойках. Принеси их и докажи, что ты умеешь правильно их держать.','Получите топор ученика и щит ученика и возьмите их.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала тебе понадобится оружие, которое позволит раскрыться твоим талантам. Достань топор и щит – ты найдешь их внизу, на оружейных стойках. Принеси их и докажи, что ты умеешь правильно их держать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите топор ученика и щит ученика и возьмите их.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30038,'Урок железной ветви','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.','Вернитесь к мастеру Шан Си на тренировочную площадку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок железной ветви',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это прекрасное оружие. Оно как раз тебе подойдет.$B$BА теперь давай опробуем его в действии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбор своего первого оружия - событие в некотором смысле символическое. $gКаждый:Каждая; $c, покинув тренировочную площадку, $gдолжен:должна; быть $gготов:готова; взять в руки оружие, чтобы защищать свой народ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Шан Си на тренировочную площадку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30046,'Решительный Чэнь','Знаешь, что? С меня хватит!$b$bЯ покажу этому дядюшке Гао, на что способен настоящий пивовар. Я найду такие ингредиенты, которые еще никто не брал, и сварю из них такое пиво, лучше которого Гао еще не пробовал.$b$bЯ же Чэнь Буйный Портер – лучший пивовар в мире.','Поговорите с Чэнем Буйным Портером в Полугорье.','Давай сварим пиво.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решительный Чэнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, что? С меня хватит!$b$bЯ покажу этому дядюшке Гао, на что способен настоящий пивовар. Я найду такие ингредиенты, которые еще никто не брал, и сварю из них такое пиво, лучше которого Гао еще не пробовал.$b$bЯ же Чэнь Буйный Портер – лучший пивовар в мире.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чэнем Буйным Портером в Полугорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай сварим пиво.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30047,'Дегустация Чэня','Дядя Чэнь будет в восторге. Ну, или скажет, что зерно не то, и попросит найти послаще. Да, он немного чудаковат.$b$bОтнесем это зерно ему в Полугорье.','Возвращайтесь к Чэню Буйному Портеру.','А, прекрасное солодовое зерно! У вас обоих прекрасное зрение и острое чутье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дегустация Чэня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дядя Чэнь будет в восторге. Ну, или скажет, что зерно не то, и попросит найти послаще. Да, он немного чудаковат.$b$bОтнесем это зерно ему в Полугорье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Чэню Буйному Портеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, прекрасное солодовое зерно! У вас обоих прекрасное зрение и острое чутье.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30048,'Ли Ли и зерно','$n, раскрою тебе свой план: я хочу сварить "Императорский портер". Если сделать все правильно, он получится темный, крепкий, с карамельными нотками.$b$b<Чэнь хмурится.>$b$bТолько сейчас вспомнил... Я же ничего не сказал Ли Ли. Она не знает, какое именно зерно мне нужно!$b$bМожешь с ней поговорить? Скажи, что мне нужно самое сладкое солодовое зерно, какое только можно найти.','Лайрим? Что ты здесь делаешь?$B$BДяде Чэню нужен сладкий солод? Не вопрос! Давай займемся дегустацией.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ли Ли и зерно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, раскрою тебе свой план: я хочу сварить "Императорский портер". Если сделать все правильно, он получится темный, крепкий, с карамельными нотками.$b$b<Чэнь хмурится.>$b$bТолько сейчас вспомнил... Я же ничего не сказал Ли Ли. Она не знает, какое именно зерно мне нужно!$b$bМожешь с ней поговорить? Скажи, что мне нужно самое сладкое солодовое зерно, какое только можно найти.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лайрим? Что ты здесь делаешь?$B$BДяде Чэню нужен сладкий солод? Не вопрос! Давай займемся дегустацией.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30049,'Водоносы','Может, узнаешь, как дела у Грязной Кружки? Вдруг ему нужна помощь?$b$bДумаю, он будет только рад, если $gтакой большой и сильный:такая большая и сильная; |3-6($c), как ты, поможет ему набрать воды.','Пэкк! Ты хочешь мне помочь? Как это мило с твоей стороны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Водоносы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, узнаешь, как дела у Грязной Кружки? Вдруг ему нужна помощь?$b$bДумаю, он будет только рад, если $gтакой большой и сильный:такая большая и сильная; |3-6($c), как ты, поможет ему набрать воды.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пэкк! Ты хочешь мне помочь? Как это мило с твоей стороны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30050,'Фран и лейка','Ты хочешь, чтобы я просто ДАЛА тебе хмель? Пфф! Третий раз за сегодня у меня что-то требует ничтожный |3-6($r) вроде тебя!$b$bНужен хмель? Тогда поработай!$b$b<Она сует вам в руки лейку.>$b$bПолей мои овощи!','Выслушайте распоряжения садовницы Фран и полейте ее 60 растений.$b$bПоливать можно сидя в седле.','Надо же!$B$BА из тебя получится неплохой фермер.','Вернитесь к садовнице Фран в Плодородные земли в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фран и лейка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хочешь, чтобы я просто ДАЛА тебе хмель? Пфф! Третий раз за сегодня у меня что-то требует ничтожный |3-6($r) вроде тебя!$b$bНужен хмель? Тогда поработай!$b$b<Она сует вам в руки лейку.>$b$bПолей мои овощи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте распоряжения садовницы Фран и полейте ее 60 растений.$b$bПоливать можно сидя в седле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо же!$B$BА из тебя получится неплохой фермер.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к садовнице Фран в Плодородные земли в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30051,'Великий забор воды','Смотри, $n, Золоченый Веер. Про местную воду много чего говорят – и плохого тоже.$b$bНе знаю, какая вода понадобится Чэню, но, может, возьмем образец этой?$b$bНу, идем. Вода сама не наберется.','Проводите Грязную Кружку к Бурлящим лужам в Золоченом Веере и помогите ему набрать 30 пригоршней болотной воды.$b$bЕсли вы разделитесь, ищите Грязную Кружку у огромного банана в Золоченом Веере.','Смотри, сколько тут образцов воды! Из такой волшебной воды Чэнь сварит восхитительное пиво!$B$BНу, или такое пиво, от которого месяц будешь сидеть в отхожем месте. Потом узнаем.','Вернитесь к Грязной Кружке в Золоченый Веер, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий забор воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смотри, $n, Золоченый Веер. Про местную воду много чего говорят – и плохого тоже.$b$bНе знаю, какая вода понадобится Чэню, но, может, возьмем образец этой?$b$bНу, идем. Вода сама не наберется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Грязную Кружку к Бурлящим лужам в Золоченом Веере и помогите ему набрать 30 пригоршней болотной воды.$b$bЕсли вы разделитесь, ищите Грязную Кружку у огромного банана в Золоченом Веере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, сколько тут образцов воды! Из такой волшебной воды Чэнь сварит восхитительное пиво!$B$BНу, или такое пиво, от которого месяц будешь сидеть в отхожем месте. Потом узнаем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грязной Кружке в Золоченый Веер, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30052,'Война с сорняками','Тебе нужен хмель? В сарае его полно. Я с радостью им поделюсь... если поможешь мне прополоть поле.$b$bВперед, на борьбу с сорняками!','Вырвите 100 сорняков на поле Гай Ланя.$b$bРвать сорняки можно и сидя в седле.','Так полоть сорняки может только настоящий герой.','Вернитесь к Гай Ланю в Плодородные земли в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с сорняками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужен хмель? В сарае его полно. Я с радостью им поделюсь... если поможешь мне прополоть поле.$b$bВперед, на борьбу с сорняками!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вырвите 100 сорняков на поле Гай Ланя.$b$bРвать сорняки можно и сидя в седле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так полоть сорняки может только настоящий герой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гай Ланю в Плодородные земли в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30053,'Охота на хмель','Ли Ли принесет зерно, Грязная Кружка наберет воды, так что нам остается раздобыть хмель и хорошие бочки. Бочками займусь я... а ты отправляйся на поиски хмеля.$b$bО местном хмеле я знаю мало, но, думаю, что-нибудь подходящее найдется. Постарайся достать немного хмеля у фермеров.','Попросите немного шишек хмеля у садовницы Фран, Гай Ланя и Дэна Грязного Когтя.','Крестьяне готовы поделиться с тобой хмелем... если и ты им поможешь.','Вернитесь к Чэню Буйному Портеру в Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на хмель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ли Ли принесет зерно, Грязная Кружка наберет воды, так что нам остается раздобыть хмель и хорошие бочки. Бочками займусь я... а ты отправляйся на поиски хмеля.$b$bО местном хмеле я знаю мало, но, думаю, что-нибудь подходящее найдется. Постарайся достать немного хмеля у фермеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите немного шишек хмеля у садовницы Фран, Гай Ланя и Дэна Грязного Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крестьяне готовы поделиться с тобой хмелем... если и ты им поможешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру в Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30054,'С меня хватит, бортель-мортель!','Гну-сини слишком много кусают.$b$bКусают морковь Мун-Муна. Мун-Мун пытаться их прогнать, а эти дукеры кусай Мун-Муна в хвост и в грив.$b$bС меня хватит, бортель-мортель!$b$bТвоя дерешься лучше Мун-Муна. Твоя приноси их зубья. Тогда моя посмотреть, кто кусай последним.','Соберите 100 зубов гну-синей.','Сколько зубов! Быть может, Мун-Мун склеит их, и тогда получатся крошечные грабли.','Принеси зубы, и тогда Мун-Мун, возможно, даст тебе хмель.','Вернитесь к Мун-Муну в Плодородные земли в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С меня хватит, бортель-мортель!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гну-сини слишком много кусают.$b$bКусают морковь Мун-Муна. Мун-Мун пытаться их прогнать, а эти дукеры кусай Мун-Муна в хвост и в грив.$b$bС меня хватит, бортель-мортель!$b$bТвоя дерешься лучше Мун-Муна. Твоя приноси их зубья. Тогда моя посмотреть, кто кусай последним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 зубов гну-синей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сколько зубов! Быть может, Мун-Мун склеит их, и тогда получатся крошечные грабли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси зубы, и тогда Мун-Мун, возможно, даст тебе хмель.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мун-Муну в Плодородные земли в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30055,'Хмель Буйного Портера','Все три фермера доставили хмель в Полугорье. Возможно, тебе стоит узнать у Чэня, получил ли он его.','Вернитесь в Полугорье и поговорите с Чэнем Буйным Портером.','Смотри, сколько тут хмеля, притом первосортного!$B$BПэкк, мы делаем успехи. Скоро у нас уже будут все ингредиенты, и тогда мы начнем варить пиво.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хмель Буйного Портера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все три фермера доставили хмель в Полугорье. Возможно, тебе стоит узнать у Чэня, получил ли он его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Полугорье и поговорите с Чэнем Буйным Портером.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, сколько тут хмеля, притом первосортного!$B$BПэкк, мы делаем успехи. Скоро у нас уже будут все ингредиенты, и тогда мы начнем варить пиво.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30056,'Дочь фермера','$gХрабрый:Храбрая:c; |3-6($c), ты как раз вовремя. Моя дочь пропала!$b$bДолжно быть, гну-сини утащили ее в свое вонючее логово. Я слишком стар, чтобы драться, а мои работники сражались с гну-синями все утро и очень устали.$b$bТы не $gмог:могла; бы ее найти?','Найдите Мину Грязный Коготь.','Нет... Нет... вернись... Я не хочу...$B$BПостой, ты же не морковка. Но и не гну-синь. Ты хочешь меня спасти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дочь фермера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gХрабрый:Храбрая:c; |3-6($c), ты как раз вовремя. Моя дочь пропала!$b$bДолжно быть, гну-сини утащили ее в свое вонючее логово. Я слишком стар, чтобы драться, а мои работники сражались с гну-синями все утро и очень устали.$b$bТы не $gмог:могла; бы ее найти?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мину Грязный Коготь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет... Нет... вернись... Я не хочу...$B$BПостой, ты же не морковка. Но и не гну-синь. Ты хочешь меня спасти?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30057,'Морковное безумие','Эти гну-сини... они толкают меня на ужасные, глупые поступки. И все они связаны с морковью. Ты даже не представляешь, сколько раз эти твари кидали в меня морковью!$b$bЛадно, не будем тратить время зря. Выведи меня отсюда!','Отведите Мину Грязный Коготь к отцу.','Что за история с этой морковью? Ничего не понимаю.','Поговорите с Хаоханем Грязным Когтем на Плодородных землях в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морковное безумие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти гну-сини... они толкают меня на ужасные, глупые поступки. И все они связаны с морковью. Ты даже не представляешь, сколько раз эти твари кидали в меня морковью!$b$bЛадно, не будем тратить время зря. Выведи меня отсюда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Мину Грязный Коготь к отцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что за история с этой морковью? Ничего не понимаю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хаоханем Грязным Когтем на Плодородных землях в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30058,'Мотылянь!','Достопочтенный подмастерье Чу, похоже, создал монстра – серебристую крылатую смерть.$b$bЕго зовут Мотылянь.$b$bПотомство этого чудовища ты уже $gвидел:видела;. А теперь мы просим тебя уничтожить самого монстра.$b$b$c, пожалуйста, спустись в яму и брось наживку – это приманит Мотылянь.$b$bНаши истребители мотыльков будут тебе помогать, однако к ним сильно липнут шелковые нити, так что ты тоже выручай их, если они попадут в беду.','Приманите Мотылянь и победите ее.','Мы стремимся достичь совершенства в искусстве – и при этом стать лучше. Но этот путь труден, и ошибок избежать не удастся.$B$BДумаю, завтра на этом поле снова будет полно ошибок. И все же – спасибо за помощь.','Поговорите с мастером Го на Шелковых полях в Долине Четырех Ветров.','Самый могущественный мотылек на свете.','Мотылянь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мотылянь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Достопочтенный подмастерье Чу, похоже, создал монстра – серебристую крылатую смерть.$b$bЕго зовут Мотылянь.$b$bПотомство этого чудовища ты уже $gвидел:видела;. А теперь мы просим тебя уничтожить самого монстра.$b$b$c, пожалуйста, спустись в яму и брось наживку – это приманит Мотылянь.$b$bНаши истребители мотыльков будут тебе помогать, однако к ним сильно липнут шелковые нити, так что ты тоже выручай их, если они попадут в беду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приманите Мотылянь и победите ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы стремимся достичь совершенства в искусстве – и при этом стать лучше. Но этот путь труден, и ошибок избежать не удастся.$B$BДумаю, завтра на этом поле снова будет полно ошибок. И все же – спасибо за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Го на Шелковых полях в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Самый могущественный мотылек на свете.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мотылянь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30059,'Восстание мотыльков','Ой... Отлично! Это же |3-6($c)! Ты мне поможешь?$b$bЯ тут модернизировал производство шелка, а в результате вывел злобных монстров.$b$bЭти мотыльки подняли восстание. Поможешь мне уничтожить хотя бы часть этих мутантов?','Уничтожьте 6 мутировавших шелкопрядов и 8 маленьких мутировавших шелкопрядов.','Похоже, что тут НЕ ТАК УЖ много зараженных мотыльков. По крайней мере ты выиграл для меня немного времени. Больших неприятностей я сумею избежать.','Поговорите с подмастерьем Чу на Шелковых полях в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание мотыльков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой... Отлично! Это же |3-6($c)! Ты мне поможешь?$b$bЯ тут модернизировал производство шелка, а в результате вывел злобных монстров.$b$bЭти мотыльки подняли восстание. Поможешь мне уничтожить хотя бы часть этих мутантов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 мутировавших шелкопрядов и 8 маленьких мутировавших шелкопрядов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, что тут НЕ ТАК УЖ много зараженных мотыльков. По крайней мере ты выиграл для меня немного времени. Больших неприятностей я сумею избежать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с подмастерьем Чу на Шелковых полях в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30063,'Срывая маски','Ша выглядят неодолимыми, но это не так.$B$BПохоже, источником их могущества служат маски. Если ша лишить маски, его сущность будет изгнана обратно, в его мир.$B$BПринеси мне несколько целых масок – хочу изучить их впоследствии. Но будь $gосторожен:осторожна; – вряд ли ша расстанутся с масками по доброй воле.','Соберите 8 масок сомнения.','Подозреваю, что эти маски обеспечивают связь ша с нашим миром.$B$BЯ должен продолжить их изучение, если мы хотим изгнать этих созданий навеки.$B$BСпасибо, Моневиль. Ты оказал нам неоценимую услугу.','Прошу тебя, обращайся с масками осторожно. Иначе они попытаются поглотить тебя.','Вернитесь к верховной жрице грозы Син в земли Нефритового храма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срывая маски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ша выглядят неодолимыми, но это не так.$B$BПохоже, источником их могущества служат маски. Если ша лишить маски, его сущность будет изгнана обратно, в его мир.$B$BПринеси мне несколько целых масок – хочу изучить их впоследствии. Но будь $gосторожен:осторожна; – вряд ли ша расстанутся с масками по доброй воле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 масок сомнения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подозреваю, что эти маски обеспечивают связь ша с нашим миром.$B$BЯ должен продолжить их изучение, если мы хотим изгнать этих созданий навеки.$B$BСпасибо, Моневиль. Ты оказал нам неоценимую услугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу тебя, обращайся с масками осторожно. Иначе они попытаются поглотить тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице грозы Син в земли Нефритового храма.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30064,'Спасая сутры','Когда началось вторжение ша, адептам храма пришлось спешно оставить все свои занятия.$B$BК несчастью, в суматохе они разбросали книги где попало. Эти бесценные кладези знаний нужно спасти!$B$BИди на северо-запад и собери священные сутры на Тренировочной площадке и на Арене служителей.','Соберите 6 древних сутр.','Спасибо! Записи целы! Какая радость!','Как там сутры? Они не пострадали?','Вернитесь к верховной жрице грозы Син в земли Нефритового храма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасая сутры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда началось вторжение ша, адептам храма пришлось спешно оставить все свои занятия.$B$BК несчастью, в суматохе они разбросали книги где попало. Эти бесценные кладези знаний нужно спасти!$B$BИди на северо-запад и собери священные сутры на Тренировочной площадке и на Арене служителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 древних сутр.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Записи целы! Какая радость!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там сутры? Они не пострадали?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице грозы Син в земли Нефритового храма.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30065,'Стрелы судьбы','Наши припасы тают, но больше всего нам не хватает стрел.$B$BНаездники на змеях – опытные стрелки, но если в колчанах пусто, от лучников никакого проку.$B$BВот если бы какой-нибудь храбрец прошел по полям сражений и собрал еще годные стрелы!$B$BКаждая найденная тобой стрела будет использована по назначению.','Соберите 8 стрел защитника.','Эти стрелы в хорошем состоянии, они полетят точно в цель.$B$BОтличная работа, Куанчи.','Тебе удалось найти стрелы?','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стрелы судьбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши припасы тают, но больше всего нам не хватает стрел.$B$BНаездники на змеях – опытные стрелки, но если в колчанах пусто, от лучников никакого проку.$B$BВот если бы какой-нибудь храбрец прошел по полям сражений и собрал еще годные стрелы!$B$BКаждая найденная тобой стрела будет использована по назначению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 стрел защитника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти стрелы в хорошем состоянии, они полетят точно в цель.$B$BОтличная работа, Куанчи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти стрелы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30066,'Невидимая сила','Наши защитники храма бьются много часов без роздыха, и силы их уже на исходе.$B$BЯ дам тебе несколько мантр – пожалуйста, отнеси их нашим воинам.$B$BНе обманись этим скромным клочкам бумаги – в этих древних текстах заключена невиданная сила.','Доставьте древние мантры 6 стражам или адептам Юй-Лун.','Поток ша не иссякает, а наши ряды тают. Но нас не пугают трудности.$B$BСпасибо за помощь в защите нашего дома.','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невидимая сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши защитники храма бьются много часов без роздыха, и силы их уже на исходе.$B$BЯ дам тебе несколько мантр – пожалуйста, отнеси их нашим воинам.$B$BНе обманись этим скромным клочкам бумаги – в этих древних текстах заключена невиданная сила.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте древние мантры 6 стражам или адептам Юй-Лун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поток ша не иссякает, а наши ряды тают. Но нас не пугают трудности.$B$BСпасибо за помощь в защите нашего дома.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30067,'Тень Сомнения','Ужасное порождение ша появилось на юге.$B$BОно пытается уничтожить нашу древнюю святыню – Колокол Тысячи Шептаний.$B$BЗа всю историю храма колокол ни разу не звонил, потому что, по слухам, в нем скрыта великая сила.$B$BПожалуйста, срази этого демона! Мы должны спасти реликвию!','Победите Тень Сомнения.','Ты уберег нас от участи столь ужасной, что мне страшно даже о ней подумать.','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.','Служитель Ша Сомнения.','Тень Сомнения') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень Сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ужасное порождение ша появилось на юге.$B$BОно пытается уничтожить нашу древнюю святыню – Колокол Тысячи Шептаний.$B$BЗа всю историю храма колокол ни разу не звонил, потому что, по слухам, в нем скрыта великая сила.$B$BПожалуйста, срази этого демона! Мы должны спасти реликвию!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Тень Сомнения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уберег нас от участи столь ужасной, что мне страшно даже о ней подумать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Служитель Ша Сомнения.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тень Сомнения',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30068,'Пламя Бездны','Видишь, как неистово бушует черно-белое пламя у стен храма?$B$BИ чем глубже наши сомнения, тем оно яростнее. Если его не усмирить, оно поглотит весь храм!$B$BУ нас осталась последняя надежда.$B$BСадись на боевого змея и лети к Чистому источнику, а затем потуши пламя его водами.','Летите на своем боевом змее к Чистому источнику, наберите в его рот воды и потушите 6 очагов Пламени Бездны.','Ты сыграл важную роль в обуздании огня. Спасибо за помощь.','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламя Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь, как неистово бушует черно-белое пламя у стен храма?$B$BИ чем глубже наши сомнения, тем оно яростнее. Если его не усмирить, оно поглотит весь храм!$B$BУ нас осталась последняя надежда.$B$BСадись на боевого змея и лети к Чистому источнику, а затем потуши пламя его водами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летите на своем боевом змее к Чистому источнику, наберите в его рот воды и потушите 6 очагов Пламени Бездны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сыграл важную роль в обуздании огня. Спасибо за помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тай-Фэну в земли Нефритового храма в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30069,'Столкновение с противником расстраивает все планы','Быстро и без лишнего шума – вот так действуют агенты ШРУ. По крайней мере, таков был план.$b$bРел Ночной Ветер уже в лагере Гаррош\'ар, ищет следы Андуина и Тейлора. Но ситуация накаляется, и ему нужна помощь.$b$bПробейся через этих псов и найди Релла!','Убейте 6 рубак лагеря Гаррош\'ар и 6 ремонтников лагеря Гаррош\'ар.','Молодец! Если когда-нибудь решишь забросить приключения, то ШРУ примет тебя в свои ряды с распростерыми объятиями…','Вернитесь к Реллу Ночному Ветру в лагерь Гаррош\'ар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Столкновение с противником расстраивает все планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстро и без лишнего шума – вот так действуют агенты ШРУ. По крайней мере, таков был план.$b$bРел Ночной Ветер уже в лагере Гаррош\'ар, ищет следы Андуина и Тейлора. Но ситуация накаляется, и ему нужна помощь.$b$bПробейся через этих псов и найди Релла!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 рубак лагеря Гаррош\'ар и 6 ремонтников лагеря Гаррош\'ар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Если когда-нибудь решишь забросить приключения, то ШРУ примет тебя в свои ряды с распростерыми объятиями…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реллу Ночному Ветру в лагерь Гаррош\'ар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30070,'Расправа над Га\'трулом','В общем так, $gдруг:подруга;. Хватит ловить мелкую рыбешку. Мы уже достаточно ослабили армию чернокнижников, пора бы уж расправиться с их предводителем.$b$bГа\'трул находится вон там, среди развалин огромного храма. Ликвидируй его, и Орда лишится последнего оплота в Пандарии.','Убейте Га\'трула.','Ша...$B$BНепросто будет сражаться с Ордой на чужом берегу.','Вернитесь к Реллу Ночному Ветру в Крепость Двух Башен, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расправа над Га\'трулом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В общем так, $gдруг:подруга;. Хватит ловить мелкую рыбешку. Мы уже достаточно ослабили армию чернокнижников, пора бы уж расправиться с их предводителем.$b$bГа\'трул находится вон там, среди развалин огромного храма. Ликвидируй его, и Орда лишится последнего оплота в Пандарии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Га\'трула.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ша...$B$BНепросто будет сражаться с Ордой на чужом берегу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реллу Ночному Ветру в Крепость Двух Башен, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30072,'Шелковый путь','Найдите листья шелковицы, накормите 5 голодных шелкопрядов и возьмите шелк-сырец.','Прекрасные образцы. Я позабочусь о том, чтобы они попали туда, куда нужно. Вот, держи, это тебе.','Все, что нужно, найдено? А за тем, что мы делаем, ты следил?','Поговорите с шелководом Цаем на Шелковых полях в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шелковый путь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите листья шелковицы, накормите 5 голодных шелкопрядов и возьмите шелк-сырец.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные образцы. Я позабочусь о том, чтобы они попали туда, куда нужно. Вот, держи, это тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все, что нужно, найдено? А за тем, что мы делаем, ты следил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с шелководом Цаем на Шелковых полях в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30073,'Император','У нас есть все необходимое – можно начинать варить пиво.$b$bСледи за тем, что я делаю, $n... Может, научишься чему-нибудь.','Помогите Чэню Буйному Портеру сварить пиво.','Спасибо, что ждал так долго. Ты не только храбрый, но и терпеливый.','Поговорите с Чэнем Буйным Портером на Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Император',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть все необходимое – можно начинать варить пиво.$b$bСледи за тем, что я делаю, $n... Может, научишься чему-нибудь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Чэню Буйному Портеру сварить пиво.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что ждал так долго. Ты не только храбрый, но и терпеливый.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером на Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30074,'Стук в дверь','Дверь... заколочена?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стук в дверь',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дверь... заколочена?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30075,'Прочь с дороги!','Ты это видишь? Из окон и дверей хмелеварни лезут гну-сини, хозены и духи воды! Да что там происходит?!$b$bС восточной стороны есть еще один вход. Я побегу туда и постараюсь понять, в чем дело. А ты пока займись этими существами. Пьяные хозены – самые отвратительные твари в мире.','Уничтожьте 10 захмелевших хозенов или шаловливых гну-синей.','Надоела мне эта хмелеварня. Я уже думаю о том, что нам с тобой нужно просто сломать стену и все здесь очистить.','Поговорите с Чэнем Буйным Портером в Хмелеварне Буйных Портеров, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочь с дороги!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты это видишь? Из окон и дверей хмелеварни лезут гну-сини, хозены и духи воды! Да что там происходит?!$b$bС восточной стороны есть еще один вход. Я побегу туда и постараюсь понять, в чем дело. А ты пока займись этими существами. Пьяные хозены – самые отвратительные твари в мире.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 захмелевших хозенов или шаловливых гну-синей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надоела мне эта хмелеварня. Я уже думаю о том, что нам с тобой нужно просто сломать стену и все здесь очистить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в Хмелеварне Буйных Портеров, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30076,'Волшебная вода','Об этой хмелеварне ходит много слухов. Раньше мне казалось, что все это сказки... но потом я сам увидел хозена-великана.$b$bИ я подумал – а что если и остальные слухи верны? Пару дней назад мне рассказывали, что на хмелеварне бесчинствуют духи воды. А ведь они БУКВАЛЬНО СДЕЛАНЫ из воды.$b$bНаверное, из такой волшебной воды получится отличное варево! Если ты ее найдешь, принеси мне, ладно?','Найдите 3 экстракта духов воды.','Похоже на обычную воду. Сложно поверить в то, что когда-то это было настоящее живое существо.$B$BСкорее бы сварить пиво и выпить его.','Вот увидишь, все получится. Это как варить пиво – но вместо воды я возьму экстракты духов воды.','Поговорите с Грязной Кружкой в хмелеварне Буйных Портеров, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебная вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Об этой хмелеварне ходит много слухов. Раньше мне казалось, что все это сказки... но потом я сам увидел хозена-великана.$b$bИ я подумал – а что если и остальные слухи верны? Пару дней назад мне рассказывали, что на хмелеварне бесчинствуют духи воды. А ведь они БУКВАЛЬНО СДЕЛАНЫ из воды.$b$bНаверное, из такой волшебной воды получится отличное варево! Если ты ее найдешь, принеси мне, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 3 экстракта духов воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже на обычную воду. Сложно поверить в то, что когда-то это было настоящее живое существо.$B$BСкорее бы сварить пиво и выпить его.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот увидишь, все получится. Это как варить пиво – но вместо воды я возьму экстракты духов воды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Грязной Кружкой в хмелеварне Буйных Портеров, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30077,'Бочки','Невероятно! Хозен-великан кидается бочками!$b$bБочками!$b$bПохоже, ему удалось захватить всех пандаренов, которые работали поблизости. На твоем месте я бы их освободила. Давай, поработай немного, разомни мышцы.$b$bВстретимся у восточной стены хмелеварни, около черного хода!','Освободите из бочек 7 пандаренов.','А что тут делают обезьяны с бочками?','Поговорите с Ли Ли в Хмелеварне Буйных Портеров, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бочки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Невероятно! Хозен-великан кидается бочками!$b$bБочками!$b$bПохоже, ему удалось захватить всех пандаренов, которые работали поблизости. На твоем месте я бы их освободила. Давай, поработай немного, разомни мышцы.$b$bВстретимся у восточной стены хмелеварни, около черного хода!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите из бочек 7 пандаренов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А что тут делают обезьяны с бочками?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ли Ли в Хмелеварне Буйных Портеров, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30078,'Домашняя уборка','Все, $n. С меня хватит.$b$bЕсли о хмелеварне никто не позаботится, мы ее потеряем. А ведь в ней столько фамильных реликвий – да и пива, что терять ее никак нельзя. $b$bПоэтому... Мы вломимся туда через черный ход – ты, Ли Ли, Грязная Кружка и я.$b$bТам будет настоящая заварушка.$b$bКогда подготовишься, дай мне знать.','Победите Эдди, Йоогу и шипящего желтого хмелементаля.','Смотри, здесь стало гораздо спокойнее. Оказывается, нужно было всего лишь немного позаботиться о хмелеварне.$B$BКонечно, понадобится время на то, чтобы все убрать, но это не страшно.$B$BВедь, в конце концов, это – мой дом.','Вернитесь к Чэню Буйному Портеру на Хмелеварню Буйных Портеров, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Домашняя уборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, $n. С меня хватит.$b$bЕсли о хмелеварне никто не позаботится, мы ее потеряем. А ведь в ней столько фамильных реликвий – да и пива, что терять ее никак нельзя. $b$bПоэтому... Мы вломимся туда через черный ход – ты, Ли Ли, Грязная Кружка и я.$b$bТам будет настоящая заварушка.$b$bКогда подготовишься, дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эдди, Йоогу и шипящего желтого хмелементаля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, здесь стало гораздо спокойнее. Оказывается, нужно было всего лишь немного позаботиться о хмелеварне.$B$BКонечно, понадобится время на то, чтобы все убрать, но это не страшно.$B$BВедь, в конце концов, это – мой дом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру на Хмелеварню Буйных Портеров, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30079,'Пандарены всегда приветствуют путник открытыми объятьями... и открытыми бочонками! Но здесь столько болваны!$b$bВсе такой хмурый, с Кен-Кеном никто не говори.$b$bТы можешь найти в городе того, кто с нами говорить? Может, хороший пандарены просто по домам прятайся?','Только леди-панда в своем уме? Это хуже, чем Кен-Кен думай...','Вернитесь к Кен-Кену в Дозор Чжу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандарены всегда приветствуют путник открытыми объятьями... и открытыми бочонками! Но здесь столько болваны!$b$bВсе такой хмурый, с Кен-Кеном никто не говори.$b$bТы можешь найти в городе того, кто с нами говорить? Может, хороший пандарены просто по домам прятайся?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только леди-панда в своем уме? Это хуже, чем Кен-Кен думай...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кен-Кену в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30080,'В поисках И-Мо','Мой племянник И-Мо всегда был депрессивным. Когда город захлестнула волна отчаяния, он поддался ей сильнее прочих. Он несколько дней сидел и отказывался от еды, просто глядел вдаль.$b$bА теперь он ушел к северо-восточным утесам, где гнездятся и охотятся буревестники.$b$b$c, поищи его, пожалуйста, ладно?','Дай угадаю – тебя прислала моя тетя?','<И-Мо вздыхает.>','Поговорите с И-Мо Длинной Бровью к северо-востоку от Дозора Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках И-Мо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой племянник И-Мо всегда был депрессивным. Когда город захлестнула волна отчаяния, он поддался ей сильнее прочих. Он несколько дней сидел и отказывался от еды, просто глядел вдаль.$b$bА теперь он ушел к северо-восточным утесам, где гнездятся и охотятся буревестники.$b$b$c, поищи его, пожалуйста, ладно?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дай угадаю – тебя прислала моя тетя?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<И-Мо вздыхает.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с И-Мо Длинной Бровью к северо-востоку от Дозора Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30081,'Народная медицина','Вот теперь-то Кен-Кен точно знай, что случилось с пандаренами! Хозены знай старый-старый лекарство, оно их мигом вылечи.$b$bНадо мешай мед, рыбий жир и соль. Кен-Кен видеть на деревьях вокруг города много улей, а в прудах еще останься рыба.$b$bДело теперь за соль... Мэй, наверное, знает, где раздобыть.','Соберите 4 комка медовых сот, 4 скользких ильных рыбы и 4 соляных глыбы в Провинции Чжу.','Поверить не могу, что Кен-Кен не догадайся об этом раньше. Только ЭТО может испортить ему день.','Вернитесь к Кен-Кену в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Народная медицина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот теперь-то Кен-Кен точно знай, что случилось с пандаренами! Хозены знай старый-старый лекарство, оно их мигом вылечи.$b$bНадо мешай мед, рыбий жир и соль. Кен-Кен видеть на деревьях вокруг города много улей, а в прудах еще останься рыба.$b$bДело теперь за соль... Мэй, наверное, знает, где раздобыть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 комка медовых сот, 4 скользких ильных рыбы и 4 соляных глыбы в Провинции Чжу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поверить не могу, что Кен-Кен не догадайся об этом раньше. Только ЭТО может испортить ему день.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кен-Кену в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30082,'Выше нос, И-Мо','С тех пор, как началась гроза, я все время какой-то... уставший.$b$bНе телом, нет. Душа как будто изнемогла. Нет смысла. Нет надежды. Наверное, так чувствуют себя те, от кого подруга уходит к другому, у кого живот покруглее. Но у меня ведь никогда не было подруги – так откуда мне знать?$b$bКак я вообще могу считать, что хоть что-то знаю? Я не нужен никому, кроме этих буревестников. Они хотя бы полакомятся мной на славу.$b$b<И-Мо глубоко вздыхает и продолжает глядеть в небо. Похоже, он никуда отсюда не пойдет.>','Поговорите с Мэй Днище Бочки в Дозоре Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выше нос, И-Мо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как началась гроза, я все время какой-то... уставший.$b$bНе телом, нет. Душа как будто изнемогла. Нет смысла. Нет надежды. Наверное, так чувствуют себя те, от кого подруга уходит к другому, у кого живот покруглее. Но у меня ведь никогда не было подруги – так откуда мне знать?$b$bКак я вообще могу считать, что хоть что-то знаю? Я не нужен никому, кроме этих буревестников. Они хотя бы полакомятся мной на славу.$b$b<И-Мо глубоко вздыхает и продолжает глядеть в небо. Похоже, он никуда отсюда не пойдет.>',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мэй Днище Бочки в Дозоре Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30083,'Защита провинции','Убейте 10 cауроков или сборщиков трав из племени Дикой Чешуи в Провинции Чжу.','Вернитесь к Мэй Днище Бочки в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита провинции',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 cауроков или сборщиков трав из племени Дикой Чешуи в Провинции Чжу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мэй Днище Бочки в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30084,'На границе','Костры отлично защищают нас от всякого зверья, живущего в джунглях. К юго-западу отсюда, вдоль границы, мы разожгли три больших костра, и обычно в них то и дело подбрасывают дровишек, чтобы они не погасли.$b$bНо у костров уже несколько дней никого не было, и они, скорее всего, потухли. И теперь возвращение диких зверей на наши земли, которые мы удерживали веками, – лишь вопрос времени.$b$bПрошу тебя, разожги эти костры. Они охраняют нашу провинцию и напоминают нам о тех, кто заложил основы нашей жизни.','Зажгите мемориальный огонь Чжу, мемориальный огонь Жинь и мемориальный огонь По вдоль юго-западной границы Провинции Чжу.','Вернитесь к Мэй Днище Бочки в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На границе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Костры отлично защищают нас от всякого зверья, живущего в джунглях. К юго-западу отсюда, вдоль границы, мы разожгли три больших костра, и обычно в них то и дело подбрасывают дровишек, чтобы они не погасли.$b$bНо у костров уже несколько дней никого не было, и они, скорее всего, потухли. И теперь возвращение диких зверей на наши земли, которые мы удерживали веками, – лишь вопрос времени.$b$bПрошу тебя, разожги эти костры. Они охраняют нашу провинцию и напоминают нам о тех, кто заложил основы нашей жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите мемориальный огонь Чжу, мемориальный огонь Жинь и мемориальный огонь По вдоль юго-западной границы Провинции Чжу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мэй Днище Бочки в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (30085,'Вперед, в хмелеварню','$n, нам надо узнать, что происходит в этой хмелеварне!$b$bПусть крупных вредителей мы и убили, там, несомненно, есть еще. Собери друзей и встречай меня внутри!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в хмелеварню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нам надо узнать, что происходит в этой хмелеварне!$b$bПусть крупных вредителей мы и убили, там, несомненно, есть еще. Собери друзей и встречай меня внутри!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30086,'Поиски тайного мастера','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.','Выслушайте Сяо и его товарищей.','Ты подслушивал? Не страшно. Ты тоже можешь принять участие в поисках тайного мастера.$B$BНо если ты его найдешь, пожалуйста, сообщи об этом мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски тайного мастера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Сяо и его товарищей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты подслушивал? Не страшно. Ты тоже можешь принять участие в поисках тайного мастера.$B$BНо если ты его найдешь, пожалуйста, сообщи об этом мне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30087,'Кунг-фу: вступление','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке. Я просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.','Выслушайте Сяо и его товарищей.','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кунг-фу: вступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке. Я просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Сяо и его товарищей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30088,'Что за грусть-печаль?','Ясно, значит, не сработай. Кен-Кену весело! А пандарены грустный...$b$bНадо пробовать еще хозен-средство – на этот раз очень старый, давнее даже бабушки. Древнющее! Хозены и сейчас иногда пользуй это – на пирушках часто.$b$bКен-Кену надо с деревом поработай. Ты принести ему зубы! Не свои, большие. Как у пантеры!$b$bА, и краска еще! Мэй скажет, где искать.','Достаньте 18 огромных клыков пантеры и один кувшин с красителем в провинции Чжу.','Ты вовремя! Все готово. Смотри!$B$B<Кен-Кен показывает вырезанную из дерева маску со смешной рожицей.>$B$BТеперь последний доработка – и будет у нас веселуха!','<Кен-Кен поглощен работой, он вырезает что-то из коры.>$B$BЗдорово будет, вот увидишь.','Вернитесь к Кен-Кену в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что за грусть-печаль?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ясно, значит, не сработай. Кен-Кену весело! А пандарены грустный...$b$bНадо пробовать еще хозен-средство – на этот раз очень старый, давнее даже бабушки. Древнющее! Хозены и сейчас иногда пользуй это – на пирушках часто.$b$bКен-Кену надо с деревом поработай. Ты принести ему зубы! Не свои, большие. Как у пантеры!$b$bА, и краска еще! Мэй скажет, где искать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 18 огромных клыков пантеры и один кувшин с красителем в провинции Чжу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты вовремя! Все готово. Смотри!$B$B<Кен-Кен показывает вырезанную из дерева маску со смешной рожицей.>$B$BТеперь последний доработка – и будет у нас веселуха!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Кен-Кен поглощен работой, он вырезает что-то из коры.>$B$BЗдорово будет, вот увидишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кен-Кену в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30089,'Прикрепить на лоб','Ого... Такого я не ожидал!$b$bЕсли подумать, Кен-Кен помнит, зачем хозенам были маски.$b$bЛегенда о Короле обезьян говори, что маской он лечи старый император пандаренов Шаохао, когда он был слишком грустный, чтобы править подданными. А потом маску вместе с печалями императора зарой в землю.$b$bМы надеть маска на пандарена, но мы не зарой тоска в землю, мы дадим печаль пинка под зад!$b$bЗа работу, $n!','Вернитесь к Кен-Кену в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикрепить на лоб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ого... Такого я не ожидал!$b$bЕсли подумать, Кен-Кен помнит, зачем хозенам были маски.$b$bЛегенда о Короле обезьян говори, что маской он лечи старый император пандаренов Шаохао, когда он был слишком грустный, чтобы править подданными. А потом маску вместе с печалями императора зарой в землю.$b$bМы надеть маска на пандарена, но мы не зарой тоска в землю, мы дадим печаль пинка под зад!$b$bЗа работу, $n!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кен-Кену в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30090,'Отчаяние Чжу','Хм... Это кто там? Малыш И-Мо?$b$b<Кен-Кен щурится, силясь разглядеть что-то в потоках ливня.>$b$bТочно! Он стой у колодца и выглядит что-то неважный.$b$bОх, не нравится это Кен-Кену...','Вернитесь к Кен-Кену в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаяние Чжу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... Это кто там? Малыш И-Мо?$b$b<Кен-Кен щурится, силясь разглядеть что-то в потоках ливня.>$b$bТочно! Он стой у колодца и выглядит что-то неважный.$b$bОх, не нравится это Кен-Кену...',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кен-Кену в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30091,'Слезы Пандарии','Все началось с наших прудов. В один день вся вода ушла в землю. А когда в прудах воды не осталось, она начала падать с неба.$b$bНо сколько бы ни лился дождь, пруды не заполняются. Как будто сама земля все пьет, пьет и не может напиться.$b$bПруды теперь воплощают собой отчаяние. Там бродят элементали из воды, что упала с неба, и из соли, что выступила из земли. Это слезы Пандарии.','Убейте 12 стенающих ужасов в Провинции Чжу.','Вернитесь к Мэй Днище Бочки в Дозор Чжу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слезы Пандарии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все началось с наших прудов. В один день вся вода ушла в землю. А когда в прудах воды не осталось, она начала падать с неба.$b$bНо сколько бы ни лился дождь, пруды не заполняются. Как будто сама земля все пьет, пьет и не может напиться.$b$bПруды теперь воплощают собой отчаяние. Там бродят элементали из воды, что упала с неба, и из соли, что выступила из земли. Это слезы Пандарии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 стенающих ужасов в Провинции Чжу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мэй Днище Бочки в Дозор Чжу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30092,'Свой человек в Гилнеасе','Если хочешь помочь мне уничтожить тех черных драконов, что еще прячутся по углам, начни с устранения Хайрама Кредо. Он в Гилнеасе – собирает там армию.$B$BНам пока не удалось проскользнуть мимо его охраны, но за ним сейчас пристально следит наш человек. Заззо Пальцемельк, весьма ловкий маг, сейчас находится возле руин этой бывшей столицы и ждет весточки от нас.$B$BНайди его. Он объяснит, что от тебя требуется.','Найдите Заззо Пальцемелька неподалеку от руин столицы Гилнеаса.','Найдите Заззо Пальцемелька неподалеку от руин столицы Гилнеаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свой человек в Гилнеасе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь помочь мне уничтожить тех черных драконов, что еще прячутся по углам, начни с устранения Хайрама Кредо. Он в Гилнеасе – собирает там армию.$B$BНам пока не удалось проскользнуть мимо его охраны, но за ним сейчас пристально следит наш человек. Заззо Пальцемельк, весьма ловкий маг, сейчас находится возле руин этой бывшей столицы и ждет весточки от нас.$B$BНайди его. Он объяснит, что от тебя требуется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Заззо Пальцемелька неподалеку от руин столицы Гилнеаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Заззо Пальцемелька неподалеку от руин столицы Гилнеаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30094,'Конец Времен','Ноздорму, Аспект бронзовых драконов, просит героев Орды оказать ему услугу. Ты – в числе выбранных им, и поэтому я могу поделиться с тобой кое-какой информацией.$b$bДля моего господина обращаться за помощью к смертным весьма нетипично, но, видимо, со временем все меняется... даже сам Аспект Времени.$b$bОн ждет тебя в Конце Времен, в далеком будущем. Я могу помочь тебе добраться туда, если, конечно, пожелаешь.','Поговорите с Ноздорму в Конце Времен.','Поговорите с Ноздорму в Конце Времен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ноздорму, Аспект бронзовых драконов, просит героев Орды оказать ему услугу. Ты – в числе выбранных им, и поэтому я могу поделиться с тобой кое-какой информацией.$b$bДля моего господина обращаться за помощью к смертным весьма нетипично, но, видимо, со временем все меняется... даже сам Аспект Времени.$b$bОн ждет тебя в Конце Времен, в далеком будущем. Я могу помочь тебе добраться туда, если, конечно, пожелаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ноздорму в Конце Времен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму в Конце Времен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30095,'Конец Времен','Ноздорму, Аспект бронзовых драконов, просит героев Альянса оказать ему услугу. Ты – в числе выбранных им, и поэтому я могу поделиться с тобой кое-какой информацией.$b$bДля моего господина обращаться за помощью к смертным весьма нетипично, но, видимо, со временем все меняется... даже сам Аспект Времени.$b$bОн ждет тебя в Конце Времен, в далеком будущем. Я могу помочь тебе добраться туда, если, конечно, пожелаешь.','Поговорите с Ноздорму в Конце Времен.','Поговорите с Ноздорму в Конце Времен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец Времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ноздорму, Аспект бронзовых драконов, просит героев Альянса оказать ему услугу. Ты – в числе выбранных им, и поэтому я могу поделиться с тобой кое-какой информацией.$b$bДля моего господина обращаться за помощью к смертным весьма нетипично, но, видимо, со временем все меняется... даже сам Аспект Времени.$b$bОн ждет тебя в Конце Времен, в далеком будущем. Я могу помочь тебе добраться туда, если, конечно, пожелаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ноздорму в Конце Времен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму в Конце Времен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30096,'Дорнозму','Убейте Дорнозму.','Дорнозму убит. Передо мной снова открыты дороги времени.','Поговорите с Ноздорму в Святилище бронзовых драконов в Конце Времен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорнозму',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Дорнозму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дорнозму убит. Передо мной снова открыты дороги времени.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму в Святилище бронзовых драконов в Конце Времен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30097,'Пополнение архива','Насколько я понимаю, вы хотите избежать этого будущего. Если это так, нам нужно сохранить данные из этого временного потока, пока они еще не потеряны.$b$bМы считаем, что самые интересные и ценные фрагменты этого будущего – могущественные тени, что бродят в святилищах драконов. Их еще зовут "эхом".$b$bВозьми вот этот сосуд. Держи его при себе, когда будешь уничтожать эти тени. Таким образом мы сможем сохранить часть их энергий в архивах бронзовых драконов.','Уничтожьте два эха в Конце Времен, позволив сосуду Алурми сохранить информацию о них.','<Алурми забирает у вас сосуд.>$B$BДалее ими займусь я. Необходимо их соответствующим образом пометить, задокументировать и поместить на хранение.','Ноздорму торопится. А торопится он очень редко.$B$BВ обычных условиях мне было бы куда проще работать над сбором данных для наших архивов. Увы, обстоятельства диктуют необходимость почти наугад выбирать то, что мы хотели бы сохранить... а также необходимость прибегнуть к услугам наемников вроде тебя.','Вернитесь к Алурми в Конец Времен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение архива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько я понимаю, вы хотите избежать этого будущего. Если это так, нам нужно сохранить данные из этого временного потока, пока они еще не потеряны.$b$bМы считаем, что самые интересные и ценные фрагменты этого будущего – могущественные тени, что бродят в святилищах драконов. Их еще зовут "эхом".$b$bВозьми вот этот сосуд. Держи его при себе, когда будешь уничтожать эти тени. Таким образом мы сможем сохранить часть их энергий в архивах бронзовых драконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте два эха в Конце Времен, позволив сосуду Алурми сохранить информацию о них.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Алурми забирает у вас сосуд.>$B$BДалее ими займусь я. Необходимо их соответствующим образом пометить, задокументировать и поместить на хранение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ноздорму торопится. А торопится он очень редко.$B$BВ обычных условиях мне было бы куда проще работать над сбором данных для наших архивов. Увы, обстоятельства диктуют необходимость почти наугад выбирать то, что мы хотели бы сохранить... а также необходимость прибегнуть к услугам наемников вроде тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алурми в Конец Времен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30098,'Источник Вечности','Нам нужно торопиться – драконы Бесконечности могут попытаться нарушить наши планы. Каждая минута на счету.$b$bИтак, мы отправляемся из далекого будущего в далекое прошлое – во времена Войны Древних. Наша цель – Душа Дракона, артефакт невообразимой силы... достаточной, чтобы победить самого Смертокрыла и помешать ему завладеть вашим настоящим.','Поговорите с Ноздорму у Источника Вечности.','Продолжим же.','Поговорите с Ноздорму у Источника Вечности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно торопиться – драконы Бесконечности могут попытаться нарушить наши планы. Каждая минута на счету.$b$bИтак, мы отправляемся из далекого будущего в далекое прошлое – во времена Войны Древних. Наша цель – Душа Дракона, артефакт невообразимой силы... достаточной, чтобы победить самого Смертокрыла и помешать ему завладеть вашим настоящим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ноздорму у Источника Вечности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Продолжим же.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму у Источника Вечности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30099,'Им нет числа','Между нами и Душой Дракона – легионы демонов. Чтобы двинуться дальше, с ними нужно разобраться.$b$bЕсли я все верно рассчитал – а ошибаюсь я редко – сейчас нам должен встретиться молодой ночной эльф, имя которому Иллидан Ярость Бури. Не сомневаюсь, что в охоте на демонов он нам очень пригодится.$b$bПомоги Иллидану закрыть демонические порталы, а затем убей командующего демонами, Перот\'арна.','Закройте три демонических портала и убейте Перот\'арна.','Хорошо. Двигаемся дальше.','Поговорите с Ноздорму в Источнике Вечности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Им нет числа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Между нами и Душой Дракона – легионы демонов. Чтобы двинуться дальше, с ними нужно разобраться.$b$bЕсли я все верно рассчитал – а ошибаюсь я редко – сейчас нам должен встретиться молодой ночной эльф, имя которому Иллидан Ярость Бури. Не сомневаюсь, что в охоте на демонов он нам очень пригодится.$b$bПомоги Иллидану закрыть демонические порталы, а затем убей командующего демонами, Перот\'арна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте три демонических портала и убейте Перот\'арна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Двигаемся дальше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму в Источнике Вечности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30100,'Тщеславие','Впереди нас ждут королева Азшара и ее стража. Мы не можем допустить даже малейших отклонений от нашего плана. Поэтому мы нанесем удар первыми – раньше, чем она сможет вмешаться.$b$bВпрочем, ты вряд ли убьешь ее сегодня – такое событие практически не прослеживается во временных потоках. Но если тебе удастся отвлечь ее хотя бы ненадолго, можешь считать, что $Gодержал:одержала; победу.','Не дайте королеве Азшаре помешать вашим планам.','От Души Дракона нас отделяют считанные секунды.','Поговорите с Ноздорму у Источника Вечности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тщеславие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впереди нас ждут королева Азшара и ее стража. Мы не можем допустить даже малейших отклонений от нашего плана. Поэтому мы нанесем удар первыми – раньше, чем она сможет вмешаться.$b$bВпрочем, ты вряд ли убьешь ее сегодня – такое событие практически не прослеживается во временных потоках. Но если тебе удастся отвлечь ее хотя бы ненадолго, можешь считать, что $Gодержал:одержала; победу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Не дайте королеве Азшаре помешать вашим планам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От Души Дракона нас отделяют считанные секунды.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ноздорму у Источника Вечности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30101,'Путь к Душе Дракона','Я не могу просто прилететь и забрать Душу Дракона. Древние боги охраняют ее.$b$bМало того, их щит усилен вихрями тайной энергии, испускаемой Источником Вечности, и управляет этой энергией Маннорот – один из сильнейших демонов Легиона.$b$bОтвлеки Маннорота – и связь между Душой Дракона и Источником будет нарушена. Без мощи Источника щит древних богов ослабнет, лишив Душу Дракона неуязвимости.$b$bИ вот тогда я заберу ее.','Убейте Маннорота.','Спасибо за помощь, незнакомец.$B$BТы отлично сражался. Надеюсь, в будущем нам доведется снова бок о бок выйти на боле битвы.','Поговорите с Иллиданом у Источника Вечности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к Душе Дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не могу просто прилететь и забрать Душу Дракона. Древние боги охраняют ее.$b$bМало того, их щит усилен вихрями тайной энергии, испускаемой Источником Вечности, и управляет этой энергией Маннорот – один из сильнейших демонов Легиона.$b$bОтвлеки Маннорота – и связь между Душой Дракона и Источником будет нарушена. Без мощи Источника щит древних богов ослабнет, лишив Душу Дракона неуязвимости.$b$bИ вот тогда я заберу ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Маннорота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, незнакомец.$B$BТы отлично сражался. Надеюсь, в будущем нам доведется снова бок о бок выйти на боле битвы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Иллиданом у Источника Вечности.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30102,'Время Сумерек','Тебе незачем стоять здесь, как истукану. Позволь мне напомнить кое-что. Мы можем УПРАВЛЯТЬ ВРЕМЕНЕМ. В частности благодаря тому, что ты в будущем $Gразделался:разделалась; с Дорнозму.$b$bО, Душа Дракона, которую ты только что $Gосвободил:освободила;? Она уже у Тралла. В твоем настоящем. И ему понадобится твоя помощь.$b$b$GГотов:Готова;?','Поговорите с Траллом во Времени Сумерек.','Ты прибыл.$B$BОтлично. Начнем.','Поговорите с Траллом во Времени Сумерек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время Сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе незачем стоять здесь, как истукану. Позволь мне напомнить кое-что. Мы можем УПРАВЛЯТЬ ВРЕМЕНЕМ. В частности благодаря тому, что ты в будущем $Gразделался:разделалась; с Дорнозму.$b$bО, Душа Дракона, которую ты только что $Gосвободил:освободила;? Она уже у Тралла. В твоем настоящем. И ему понадобится твоя помощь.$b$b$GГотов:Готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом во Времени Сумерек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прибыл.$B$BОтлично. Начнем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом во Времени Сумерек.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30103,'В Храм Драконьего Покоя!','Душа Дракона... Оружие такой силы, что с его помощью можно победить даже самого Смертокрыла. И теперь оно в наших руках. Благодаря тебе.$b$bИдем. Аспекты ждут нас. Мы должны доставить Душу Дракона в Храм Драконьего Покоя, что в центре Драконьего Погоста.','Сопроводите Тралла в Храм Драконьего Покоя.','Я обязан вам жизнью, герои.$B$BДуша Дракона – в Храме, в безопасности. И поэтому, возможно, все живое на Азероте также обязано вам жизнью.','Поговорите с Траллом во Времени Сумерек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Храм Драконьего Покоя!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Душа Дракона... Оружие такой силы, что с его помощью можно победить даже самого Смертокрыла. И теперь оно в наших руках. Благодаря тебе.$b$bИдем. Аспекты ждут нас. Мы должны доставить Душу Дракона в Храм Драконьего Покоя, что в центре Драконьего Погоста.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Тралла в Храм Драконьего Покоя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я обязан вам жизнью, герои.$B$BДуша Дракона – в Храме, в безопасности. И поэтому, возможно, все живое на Азероте также обязано вам жизнью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом во Времени Сумерек.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30104,'Архивация временных потоков','Тебя зовут... $n, если не ошибаюсь? В прошлом ты уже $Gпомогал:помогала; нам с архивацией данных. Впрочем, технически это было в будущем... но, думаю, ты понимаешь, о чем я. Время – весьма относительное понятие.$b$bНашим архивам нужны новые данные. Насколько я понимаю, вы с Ноздорму не планируете перезаписывать этот временной поток, как это было сделано с Концом Времен, но дополнительная информация не помешает никогда.$b$bМне нужны данные по капитану Варо\'тену, по любой из фрейлин Азшары и... хм... как насчет вон того стража Скверны? Того, что у подножия лестницы?','Убейте демона Легиона, королевскую фрейлину и капитана Варо\'тена, при этом собрав информацию о них с помощью сосуда Алурми.','Принесите Алурми в Источник Вечности сосуд Алурми.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Архивация временных потоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя зовут... $n, если не ошибаюсь? В прошлом ты уже $Gпомогал:помогала; нам с архивацией данных. Впрочем, технически это было в будущем... но, думаю, ты понимаешь, о чем я. Время – весьма относительное понятие.$b$bНашим архивам нужны новые данные. Насколько я понимаю, вы с Ноздорму не планируете перезаписывать этот временной поток, как это было сделано с Концом Времен, но дополнительная информация не помешает никогда.$b$bМне нужны данные по капитану Варо\'тену, по любой из фрейлин Азшары и... хм... как насчет вон того стража Скверны? Того, что у подножия лестницы?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте демона Легиона, королевскую фрейлину и капитана Варо\'тена, при этом собрав информацию о них с помощью сосуда Алурми.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите Алурми в Источник Вечности сосуд Алурми.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30105,'Сумеречный Пророк','Текст сообщения гласит:$b$b"Время Сумерек уже близко. Тралл, шаман мира, направляется в Храм Драконьего Покоя. В его руках – Душа Дракона – единственное, что еще представляет какую-то угрозу для нашего господина.$b$bОстановите Тралла – и победа в наших руках. Я буду поблизости, чтобы наблюдать за вашими действиями."$b$b – Сумеречный Пророк','Найдите Сумеречного Пророка и сорвите с него маску.','Как мы и предполагали, Сумеречным Пророком был Бенедикт. Был.$B$BСегодня мы нанесли Культу Сумеречного Молота страшный удар. Будем надеяться, что он станет смертельным.','Поговорите с Траллом во Времени Сумерек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный Пророк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Текст сообщения гласит:$b$b"Время Сумерек уже близко. Тралл, шаман мира, направляется в Храм Драконьего Покоя. В его руках – Душа Дракона – единственное, что еще представляет какую-то угрозу для нашего господина.$b$bОстановите Тралла – и победа в наших руках. Я буду поблизости, чтобы наблюдать за вашими действиями."$b$b – Сумеречный Пророк',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сумеречного Пророка и сорвите с него маску.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как мы и предполагали, Сумеречным Пророком был Бенедикт. Был.$B$BСегодня мы нанесли Культу Сумеречного Молота страшный удар. Будем надеяться, что он станет смертельным.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом во Времени Сумерек.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30106,'Дело сделано','Принц Гневион будет доволен новостями. Возвращайся к нему в поместье Черного Ворона.$B$BКстати, принц весьма щедр с теми, кто сотрудничает с ним.','Доложите о своей победе принцу Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дело сделано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принц Гневион будет доволен новостями. Возвращайся к нему в поместье Черного Ворона.$B$BКстати, принц весьма щедр с теми, кто сотрудничает с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своей победе принцу Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30107,'В поисках самоцветов','В клинках, что я дал тебе, дремлет сила. Они способны на многое, но для этого они должны будут удержать в себе ту мощь, что я собираюсь в них вложить.$B$BИ для этого мне нужно, чтобы ты $gсобрал:собрала; темные самоцветы. Грани этих необычных камней – словно окна в бесконечность. Их часто используют служители Сумеречного Молота для подчинения своей воле сильнейших элементалей.$B$BВокруг Храма Драконьего Покоя кипит великая битва. Собери скопления элементиевых самоцветов – ты найдешь их у приспешников Смертокрыла – и принеси самоцветы мне.','Видишь ли ты их мерцание? В лучах света способны сверкать многие драгоценные камни, но лишь эти способны сверкать тьмой.$B$BИ пока ты выполняешь мое следующее задание, я наложу на них кое-какие чары.$B$BГотов отправляться?','Сколько самоцветов тебе уже удалось собрать?$B$BКстати, как по-твоему, приспешники моего отца настолько же извращены, насколько и он сам?','Принесите темные самоцветы принцу Гневиону в поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках самоцветов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В клинках, что я дал тебе, дремлет сила. Они способны на многое, но для этого они должны будут удержать в себе ту мощь, что я собираюсь в них вложить.$B$BИ для этого мне нужно, чтобы ты $gсобрал:собрала; темные самоцветы. Грани этих необычных камней – словно окна в бесконечность. Их часто используют служители Сумеречного Молота для подчинения своей воле сильнейших элементалей.$B$BВокруг Храма Драконьего Покоя кипит великая битва. Собери скопления элементиевых самоцветов – ты найдешь их у приспешников Смертокрыла – и принеси самоцветы мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь ли ты их мерцание? В лучах света способны сверкать многие драгоценные камни, но лишь эти способны сверкать тьмой.$B$BИ пока ты выполняешь мое следующее задание, я наложу на них кое-какие чары.$B$BГотов отправляться?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько самоцветов тебе уже удалось собрать?$B$BКстати, как по-твоему, приспешники моего отца настолько же извращены, насколько и он сам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите темные самоцветы принцу Гневиону в поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30108,'Свой человек в Каражане','Твоя следующая цель – Нэлис, черный дракон. Она занимается какими-то совершенно безумными магическими экспериментами под руинами Каражана.$B$BТвоя основная задача – уничтожить Нэлис. Но если тебе удастся принести мне некоторое количество ее крови – я смогу воспользоваться ей, чтобы усилить мощь клинков, что я дал тебе.$B$BТвоим сообщником в этом деле снова будет Заззо; он уже ждет тебя на месте. За подробностями обратишься к нему.','Доложитесь Заззо Пальцемельку в руинах на юго-востоке от Каражана.','Сумасшествие. Безумие!$B$BЯ не знаю, чем там внизу занимается Нэлис, но вся эта магическая энергия прямо-таки потоками льется из подвалов. И у нее тут целый культ из глупцов, считающих ее богиней.$B$BЕсли мы хотим от нее избавиться – это стоит провернуть побыстрее. Надеюсь, ты готов!','Поговорите с Заззо Пальцемельком в руинах к юго-востоку от Каражана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свой человек в Каражане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя следующая цель – Нэлис, черный дракон. Она занимается какими-то совершенно безумными магическими экспериментами под руинами Каражана.$B$BТвоя основная задача – уничтожить Нэлис. Но если тебе удастся принести мне некоторое количество ее крови – я смогу воспользоваться ей, чтобы усилить мощь клинков, что я дал тебе.$B$BТвоим сообщником в этом деле снова будет Заззо; он уже ждет тебя на месте. За подробностями обратишься к нему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь Заззо Пальцемельку в руинах на юго-востоке от Каражана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сумасшествие. Безумие!$B$BЯ не знаю, чем там внизу занимается Нэлис, но вся эта магическая энергия прямо-таки потоками льется из подвалов. И у нее тут целый культ из глупцов, считающих ее богиней.$B$BЕсли мы хотим от нее избавиться – это стоит провернуть побыстрее. Надеюсь, ты готов!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Заззо Пальцемельком в руинах к юго-востоку от Каражана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30109,'Кровь предателя','Мне удалось обнаружить, где прячется сама Нэлис – в хозяйском погребе, приличных размеров подвале, находящемся под руинами впереди.$B$BТут повсюду служители ее культа. Ну и, помимо всего прочего, она везде расставила какие-то непонятные устройства, которые, похоже, служат для хранения магии. Возможно, тебе удастся задействовать их против нее самой.$B$BПроскользни мимо этих сектантов, устрани Нэлис – и не забудь о ее крови для Гневиона.$B$BЯ за тобой послежу издалека и вытащу обратно, если что пойдет не так. Что? Нет, сам я туда не полезу!','Проникните в хозяйский погреб в руинах вокруг Каражана, убейте Нэлис и добудьте фиал с кровью черного дракона.','Ты это сделал? Она мертва? Невероятно! Да ты просто кудесник!$B$BНу-ка, дай мне взглянуть на эту кровь. Чтобы сохранить ее энергию на время твоего пути назад в поместье, мне придется заключить ее в магическую матрицу...','Нэлис. Мертва?','Отнесите фиал Заззо Пальцемельку в Каражан на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось обнаружить, где прячется сама Нэлис – в хозяйском погребе, приличных размеров подвале, находящемся под руинами впереди.$B$BТут повсюду служители ее культа. Ну и, помимо всего прочего, она везде расставила какие-то непонятные устройства, которые, похоже, служат для хранения магии. Возможно, тебе удастся задействовать их против нее самой.$B$BПроскользни мимо этих сектантов, устрани Нэлис – и не забудь о ее крови для Гневиона.$B$BЯ за тобой послежу издалека и вытащу обратно, если что пойдет не так. Что? Нет, сам я туда не полезу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в хозяйский погреб в руинах вокруг Каражана, убейте Нэлис и добудьте фиал с кровью черного дракона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты это сделал? Она мертва? Невероятно! Да ты просто кудесник!$B$BНу-ка, дай мне взглянуть на эту кровь. Чтобы сохранить ее энергию на время твоего пути назад в поместье, мне придется заключить ее в магическую матрицу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нэлис. Мертва?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите фиал Заззо Пальцемельку в Каражан на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30112,'Сведение счетов','Темный следопыт Марра повелела вам отправиться в Утгард и убить принца Келесета.','Ах, месть сладка. Подумать только – и это лишь начало!$B$BСкоро Артас получит по заслугам.','Вернитесь к темному следопыту Марре в Крепость Утгард.','Келесет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сведение счетов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Темный следопыт Марра повелела вам отправиться в Утгард и убить принца Келесета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, месть сладка. Подумать только – и это лишь начало!$B$BСкоро Артас получит по заслугам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Марре в Крепость Утгард.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Келесет',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30113,'Из глубин – с победой','<Заззо накладывает на фиал с кровью чары и торопливо сует его вам в руки, будто фиал может его укусить.>$B$BГотово! Тебе стоит как можно скорее отнести эту штуку Гневиону. И свои кинжалы не забудь.$B$BНе имею ни малейшего понятия, что он собирается делать со всем этим. Между нами... от этого ребенка у меня мурашки по коже. Удачи!','Отнесите фиал с кровью черного дракона, а также кинжалы "Страх" и "Воздаяние" Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.','Ты и впрямь мастер своего дела. Нэлис мертва. Пришло время наградить тебя за твои труды.$B$B<Гневион забирает у вас фиал; на его лице отражается странная смесь почтения с отвращением. Он по одному опускает в кровь собранные вами самоцветы, бормоча какую-то магическую формулу.>$B$B<Затем он без предупреждения выливает кровь на лезвия кинжалов; сталь клинков корчится и извивается, будто живая. Когда дым рассеивается, вы замечаете, что форма кинжалов изменилась.>','А! Ты вернулся! Я более не ощущаю присутствия Нэлис. Она мертва? Или, возможно, нашла способ ускользнуть от нас обоих?','Отнесите фиал с кровью черного дракона, а также кинжалы "Страх" и "Воздаяние" Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из глубин – с победой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Заззо накладывает на фиал с кровью чары и торопливо сует его вам в руки, будто фиал может его укусить.>$B$BГотово! Тебе стоит как можно скорее отнести эту штуку Гневиону. И свои кинжалы не забудь.$B$BНе имею ни малейшего понятия, что он собирается делать со всем этим. Между нами... от этого ребенка у меня мурашки по коже. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фиал с кровью черного дракона, а также кинжалы "Страх" и "Воздаяние" Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты и впрямь мастер своего дела. Нэлис мертва. Пришло время наградить тебя за твои труды.$B$B<Гневион забирает у вас фиал; на его лице отражается странная смесь почтения с отвращением. Он по одному опускает в кровь собранные вами самоцветы, бормоча какую-то магическую формулу.>$B$B<Затем он без предупреждения выливает кровь на лезвия кинжалов; сталь клинков корчится и извивается, будто живая. Когда дым рассеивается, вы замечаете, что форма кинжалов изменилась.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А! Ты вернулся! Я более не ощущаю присутствия Нэлис. Она мертва? Или, возможно, нашла способ ускользнуть от нас обоих?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите фиал с кровью черного дракона, а также кинжалы "Страх" и "Воздаяние" Гневиону в поместье Черного Ворона, что в предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30116,'Заостряя клыки','Теперь ты понимаешь, почему я хотел, чтобы ты убивал драконов, но оставлял смертных в живых? Это не их – смертных – вина. Они должны найти свою собственную судьбу без влияния моих сородичей.$B$BНаша миссия уже почти закончилась... и тебе тоже пора приниматься за поиски своей судьбы. Я могу улучшить твои кинжалы. Но собирать темные самоцветы по одной штуке – слишком долго. Мне понадобятся скопления камней. Ты найдешь их у приспешников моего отца.','Соберите 60 скоплений элементиевых самоцветов в рейде "Душа Дракона".','У тебя получилось! Не сомневаюсь, тебе и твоим союзникам пришлось очень нелегко. Твои труды не напрасны, и со временем ты получишь достойную награду. Эти самоцветы послужат основой мощных чар для твоего оружия.$B$BНо нам понадобится катализатор. готова ли ты выполнить последнее – и самое опасное – задание, разбойница?','Итак, сколько скоплений самоцветов тебе удалось добыть?$B$BВоистину, упорство твоей расы вселяет в меня вдохновение!','Принесите самоцветы Гневиону в поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заостряя клыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты понимаешь, почему я хотел, чтобы ты убивал драконов, но оставлял смертных в живых? Это не их – смертных – вина. Они должны найти свою собственную судьбу без влияния моих сородичей.$B$BНаша миссия уже почти закончилась... и тебе тоже пора приниматься за поиски своей судьбы. Я могу улучшить твои кинжалы. Но собирать темные самоцветы по одной штуке – слишком долго. Мне понадобятся скопления камней. Ты найдешь их у приспешников моего отца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 60 скоплений элементиевых самоцветов в рейде "Душа Дракона".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось! Не сомневаюсь, тебе и твоим союзникам пришлось очень нелегко. Твои труды не напрасны, и со временем ты получишь достойную награду. Эти самоцветы послужат основой мощных чар для твоего оружия.$B$BНо нам понадобится катализатор. готова ли ты выполнить последнее – и самое опасное – задание, разбойница?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, сколько скоплений самоцветов тебе удалось добыть?$B$BВоистину, упорство твоей расы вселяет в меня вдохновение!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите самоцветы Гневиону в поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30117,'Жажда Каменного Плуга','Наконец-то! Эмми сдержала слово!$B$BНадеюсь, в "Буйном Портере" все в порядке? А то ведь мои парни без пива долго не протянут.','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жажда Каменного Плуга',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Эмми сдержала слово!$B$BНадеюсь, в "Буйном Портере" все в порядке? А то ведь мои парни без пива долго не протянут.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30118,'Отцеубийство','Твоей следующей целью станет тот, кто прикончил всех убийц, которых я посылал раньше. Я хочу, чтобы ты $gубил:убила; моего отца.$B$BСмертокрыла нужно уничтожить.$B$BВремени у нас почти не осталось. Его безумие уже поразило всех моих сородичей, и если его не остановить, то тьма, что он несет с собой, окутает весь мир.$B$BЕсли каким-то чудом тебе удастся одержать над ним победу, принеси мне что-нибудь из его облачения, например кусок брони, под которой скрывается его истинная хаотическая сущность. Тогда я награжу тебя так, как тебе и не снилось.','Убейте Смертокрыла и получите фрагмент его челюсти.','Я чувствую это… Как будто землю покинула черная тень. Мертв. Мой отец мертв!$B$B<Гневион забирает у вас кусок челюсти. Он начинает читать темное заклинание, и по его рукам и лицу словно пробегает тень; вокруг его головы кружатся самоцветы, собранные вами ранее. Кусок челюсти внезапно разлетается на части, и жуткий шипящий звук возвещает пробуждение ваших кинжалов-близнецов.>$B$BТвоя награда готова. Скорее, забери их. Они вот-вот тебе понадобятся...','Что там с моим отцом?','Отнесите кусок челюсти Смертокрыла и ваши кинжалы-близнецы "Спящее лезвие" и "Дремлющее лезвие" Гневиону в Поместье Черного Ворона, что в предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отцеубийство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоей следующей целью станет тот, кто прикончил всех убийц, которых я посылал раньше. Я хочу, чтобы ты $gубил:убила; моего отца.$B$BСмертокрыла нужно уничтожить.$B$BВремени у нас почти не осталось. Его безумие уже поразило всех моих сородичей, и если его не остановить, то тьма, что он несет с собой, окутает весь мир.$B$BЕсли каким-то чудом тебе удастся одержать над ним победу, принеси мне что-нибудь из его облачения, например кусок брони, под которой скрывается его истинная хаотическая сущность. Тогда я награжу тебя так, как тебе и не снилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Смертокрыла и получите фрагмент его челюсти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую это… Как будто землю покинула черная тень. Мертв. Мой отец мертв!$B$B<Гневион забирает у вас кусок челюсти. Он начинает читать темное заклинание, и по его рукам и лицу словно пробегает тень; вокруг его головы кружатся самоцветы, собранные вами ранее. Кусок челюсти внезапно разлетается на части, и жуткий шипящий звук возвещает пробуждение ваших кинжалов-близнецов.>$B$BТвоя награда готова. Скорее, забери их. Они вот-вот тебе понадобятся...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там с моим отцом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите кусок челюсти Смертокрыла и ваши кинжалы-близнецы "Спящее лезвие" и "Дремлющее лезвие" Гневиону в Поместье Черного Ворона, что в предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30119,'Well of Eternity RP Tracker','Долг обязывает меня немедленно отреагировать на то, о чем ты $gрассказал:рассказала; мне, $n. Поэтому я передаю тебе миссию, которая привела меня сюда.$b$bМеня привлек всплеск древней магии, слишком сильной, чтобы можно было назвать ее нормальной. И случилось кое-что еще.$b$bКто-то срубил ветвь Нордрассила и унес ее в глубины Огненных Просторов. Ее могут использовать для ритуала, целью которого будет уничтожение Нордрассила.$b$bТы $gдолжен:должна; найти способ прервать ритуал и вернуть ветвь Древа Жизни.','Верните ветвь Нордрассила из Огненных Просторов.','Поговорите с Калесгосом на Янтарной гряде в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Well of Eternity RP Tracker',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Долг обязывает меня немедленно отреагировать на то, о чем ты $gрассказал:рассказала; мне, $n. Поэтому я передаю тебе миссию, которая привела меня сюда.$b$bМеня привлек всплеск древней магии, слишком сильной, чтобы можно было назвать ее нормальной. И случилось кое-что еще.$b$bКто-то срубил ветвь Нордрассила и унес ее в глубины Огненных Просторов. Ее могут использовать для ритуала, целью которого будет уничтожение Нордрассила.$b$bТы $gдолжен:должна; найти способ прервать ритуал и вернуть ветвь Древа Жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ветвь Нордрассила из Огненных Просторов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Калесгосом на Янтарной гряде в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30120,'Очищение Драк\'Тарона','Хей, дружище, ты тут! Это хорошо!$b$bСкоро Драк\'Тарон будет очищен от этой мерзкой нежити и засияет во всей своей былой славе, а ты в награду за свои великие деяния обретешь великое сокровище!$b$bКогда доберешься до самой вершины, призови меня, чтобы я провел ритуал. $b$bУвы, но тебе снова придется заплатить за мой призыв. Ты $gдолжен:должна; будешь забрать моджо у выживших.','Дракуру просит вас выпить эликсир возле его жаровни в Драк\'Тароне. Для использования эликсира вам понадобится пять настоев терпения.','Мы совершили великое дело, дружище! И это только начало...$B$BКогда придет время, отыщи меня в Зул\'Драке.$B$BМы с тобой выиграем эту битву!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Драк\'Тарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хей, дружище, ты тут! Это хорошо!$b$bСкоро Драк\'Тарон будет очищен от этой мерзкой нежити и засияет во всей своей былой славе, а ты в награду за свои великие деяния обретешь великое сокровище!$b$bКогда доберешься до самой вершины, призови меня, чтобы я провел ритуал. $b$bУвы, но тебе снова придется заплатить за мой призыв. Ты $gдолжен:должна; будешь забрать моджо у выживших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дракуру просит вас выпить эликсир возле его жаровни в Драк\'Тароне. Для использования эликсира вам понадобится пять настоев терпения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы совершили великое дело, дружище! И это только начало...$B$BКогда придет время, отыщи меня в Зул\'Драке.$B$BМы с тобой выиграем эту битву!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30121,'Поисковый отряд','Я отправил дипломата в руины к востоку отсюда, чтобы он обсудил условия мира с местными жителями.$b$bНо он до сих пор не вернулся, а Кан говорит мне, что джунгли кишат зловещими созданиями, известными как "могу".$b$bЧэцзынь – мой хороший друг и брат Лезы. Если она потеряет брата, то впадет в отчаяние. А она и так еле справляется с лихорадкой.$B$BТы можешь осмотреть руины на востоке и выяснить, что там случилось?','Найдите в Красарангских руинах Чэцзыня Искателя Зари.','Я... яд. Надо... предупредить... Дезко.','Поговорите с Чэцзынем Искателем Зари в Красарангских руинах, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поисковый отряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправил дипломата в руины к востоку отсюда, чтобы он обсудил условия мира с местными жителями.$b$bНо он до сих пор не вернулся, а Кан говорит мне, что джунгли кишат зловещими созданиями, известными как "могу".$b$bЧэцзынь – мой хороший друг и брат Лезы. Если она потеряет брата, то впадет в отчаяние. А она и так еле справляется с лихорадкой.$B$BТы можешь осмотреть руины на востоке и выяснить, что там случилось?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Красарангских руинах Чэцзыня Искателя Зари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я... яд. Надо... предупредить... Дезко.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэцзынем Искателем Зари в Красарангских руинах, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30123,'Похлебка из быстролапов','У Лезы лихорадка. Нельзя, чтобы роженица страдала от лихорадки.$b$bМама Ежевичный Посох как-то говорила мне, что похлебка из быстролапов может вылечить почти любую болезнь. Пора проверить это на деле.$b$bСобери целые железы быстролапов, а я пока соберу необходимые травы.','Соберите 5 целых желез быстролапов.','В джунглях даже воздух полон опасностей.','Вернитесь к Кану Ежевичному Посоху в Громовую Расселину, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похлебка из быстролапов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Лезы лихорадка. Нельзя, чтобы роженица страдала от лихорадки.$b$bМама Ежевичный Посох как-то говорила мне, что похлебка из быстролапов может вылечить почти любую болезнь. Пора проверить это на деле.$b$bСобери целые железы быстролапов, а я пока соберу необходимые травы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 целых желез быстролапов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В джунглях даже воздух полон опасностей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кану Ежевичному Посоху в Громовую Расселину, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30124,'Ослепить их!','Эти Служители Солнца изрядно надоели. Мне нужны настоящие солдаты Орды, которые не понаслышке знают о чести, а не эти миролюбивые солнечные шавки!$b$bАльянс уже здесь, $n. Наверняка шли за нами, или каким-то образом увидели то, что видела Леза. Но это не имеет значения. Я не хочу, чтобы они знали, насколько плохи наши дела. Убей их разведчика к югу отсюда, прежде чем он успеет доложить обстановку.$b$bАдский Крик следит за твоими успехами!','Убейте дарнасского разбойника.','Часовые. Ха! Я помню времена, когда эти создания были настоящим ужасом лесов и нападали на всякого орка или таурена, забредавшего в их чащи в поисках пищи или убежища.','Поговорите с Кором Кровавым Бивнем в Громовой Расселине в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепить их!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти Служители Солнца изрядно надоели. Мне нужны настоящие солдаты Орды, которые не понаслышке знают о чести, а не эти миролюбивые солнечные шавки!$b$bАльянс уже здесь, $n. Наверняка шли за нами, или каким-то образом увидели то, что видела Леза. Но это не имеет значения. Я не хочу, чтобы они знали, насколько плохи наши дела. Убей их разведчика к югу отсюда, прежде чем он успеет доложить обстановку.$b$bАдский Крик следит за твоими успехами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте дарнасского разбойника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Часовые. Ха! Я помню времена, когда эти создания были настоящим ужасом лесов и нападали на всякого орка или таурена, забредавшего в их чащи в поисках пищи или убежища.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Громовой Расселине в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30125,'В погоне за прибылью','Два слова: тигриная кровь!$b$bНа черном рынке она будет расходиться быстрее саронита. Особенно когда я пущу повсюду слухи о ее целебных всяких свойствах.$b$bПравда, тут такое дело – у меня патроны кончились. Не наберешь ли мне несколько пузырьков тигриной крови? А я тебя в долю возьму.','Соберите 12 сосудов тигриной крови.','Поговорите с Даггл Бомбстер в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В погоне за прибылью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Два слова: тигриная кровь!$b$bНа черном рынке она будет расходиться быстрее саронита. Особенно когда я пущу повсюду слухи о ее целебных всяких свойствах.$b$bПравда, тут такое дело – у меня патроны кончились. Не наберешь ли мне несколько пузырьков тигриной крови? А я тебя в долю возьму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 сосудов тигриной крови.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30126,'Мастерство журавля','Для охоты на птиц нужны патроны, а у меня их нет. А при охоте с Эрнестуэем стоит твердо усвоить – хвалиться может лишь тот, кто успешен в охоте.$b$bНе умеешь охотиться – не хвались. А ведь я так люблю хвалиться!$b$bДавай я заплачу тебе, и ты убьешь для меня ловцов карпов! Их можно найти у реки, что к западу отсюда.','Убейте 8 ловцов карпов.','Поговорите с Даггл Бомбстер в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастерство журавля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для охоты на птиц нужны патроны, а у меня их нет. А при охоте с Эрнестуэем стоит твердо усвоить – хвалиться может лишь тот, кто успешен в охоте.$b$bНе умеешь охотиться – не хвались. А ведь я так люблю хвалиться!$b$bДавай я заплачу тебе, и ты убьешь для меня ловцов карпов! Их можно найти у реки, что к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 ловцов карпов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30127,'Руины Доцзян','Могу? Они похожи на эльфов – такие же древние и высокомерные. Рано или поздно все обитатели Азерота должны понять, что Орда не пришла "погостить". Мы – здесь. И мы останемся здесь.$b$bПреподай им этот урок. Могу наращивают силы в руинах к югу и к западу отсюда. Раздавим их до того, как они даже помыслят об атаке.$b$bСходи и узнай, как сражаются эти существа. И как они умирают.','Убейте 6 искателей из Доцзяна, 8 разведчиков из Доцзяна и 4 головорезов из Доцзяна.','Это не просто разбойники. Перед нами древнее племя, которое начинает собираться под единым знаменем. Помяни мое слово, скоро эти земли познают войну.','Поговорите с Кором Кровавым Бивнем в Громовой Расселине в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Доцзян',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу? Они похожи на эльфов – такие же древние и высокомерные. Рано или поздно все обитатели Азерота должны понять, что Орда не пришла "погостить". Мы – здесь. И мы останемся здесь.$b$bПреподай им этот урок. Могу наращивают силы в руинах к югу и к западу отсюда. Раздавим их до того, как они даже помыслят об атаке.$b$bСходи и узнай, как сражаются эти существа. И как они умирают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 искателей из Доцзяна, 8 разведчиков из Доцзяна и 4 головорезов из Доцзяна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это не просто разбойники. Перед нами древнее племя, которое начинает собираться под единым знаменем. Помяни мое слово, скоро эти земли познают войну.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Громовой Расселине в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30128,'Пруд Молодости','Могу нашли Пруд Молодости!$b$bМама Ежевичный Посох рассказывала старые байки о нем. Во времена империи могу они использовали этот Пруд, чтобы продлить свою жизнь.$b$bПравда, почему-то эти истории никогда хорошо не заканчивались. Словно вода там была проклята.$b$bТем не менее, мы должны все разузнать. Есть шанс, что эта вода может помочь Лезе.$b$bПохоже, что Пруд Молодости находится в северо-западной части руин.','Добудьте воду из Пруда Молодости.','Сейчас я готов на все. Эта земля хочет забрать мою жену и нерожденного ребенка. Мне нужна любая помощь.','Боль Лезы ужасна. Теперь ее и ребенка могут спасти лишь те силы, что за пределами моего понимания.','Принесите воду Служителю Солнца Дезко в Громовую Расселину, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пруд Молодости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу нашли Пруд Молодости!$b$bМама Ежевичный Посох рассказывала старые байки о нем. Во времена империи могу они использовали этот Пруд, чтобы продлить свою жизнь.$b$bПравда, почему-то эти истории никогда хорошо не заканчивались. Словно вода там была проклята.$b$bТем не менее, мы должны все разузнать. Есть шанс, что эта вода может помочь Лезе.$b$bПохоже, что Пруд Молодости находится в северо-западной части руин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте воду из Пруда Молодости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас я готов на все. Эта земля хочет забрать мою жену и нерожденного ребенка. Мне нужна любая помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боль Лезы ужасна. Теперь ее и ребенка могут спасти лишь те силы, что за пределами моего понимания.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите воду Служителю Солнца Дезко в Громовую Расселину, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30129,'Тайный план могу','Нечасто могу собираются в таких количествах. Мы должны разобраться, зачем им это понадобилось.$b$bКажется, в центральной части руин кто-то выкрикивал приказы.$b$bНужно посмотреть, располагает ли этот кто-то полезными сведениями.','Раздобудьте доцзянские приказы.','Поговорите с Каном Ежевичным Посохом в Руинах Доцзян или в Громовой Расселине в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайный план могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нечасто могу собираются в таких количествах. Мы должны разобраться, зачем им это понадобилось.$b$bКажется, в центральной части руин кто-то выкрикивал приказы.$b$bНужно посмотреть, располагает ли этот кто-то полезными сведениями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте доцзянские приказы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каном Ежевичным Посохом в Руинах Доцзян или в Громовой Расселине в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30130,'Целебные травы','Лекарство Кана не помогает.$b$bНо есть еще кое-что. Сила, затаенная в недрах земли. Она лишает нас надежды и повергает в отчаяние.$b$bКан говорит, что здесь растут лотосы. Я мог бы сделать из них чай, который придаст Лезе сил.$b$bПожалуйста, $n, поищи листья лотоса в руинах к югу и к западу отсюда, и я отблагодарю тебя за это.','Соберите 20 листьев императорского лотоса.','Спасибо. Кор – прекрасный воин, но иногда ему недостает сострадания. Жизнь всегда должна опережать смерть, иначе после очередной битвы не останется никого.','Поговорите со Служителем Солнца Дезко в Громовой Расселине, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целебные травы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лекарство Кана не помогает.$b$bНо есть еще кое-что. Сила, затаенная в недрах земли. Она лишает нас надежды и повергает в отчаяние.$b$bКан говорит, что здесь растут лотосы. Я мог бы сделать из них чай, который придаст Лезе сил.$b$bПожалуйста, $n, поищи листья лотоса в руинах к югу и к западу отсюда, и я отблагодарю тебя за это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 листьев императорского лотоса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. Кор – прекрасный воин, но иногда ему недостает сострадания. Жизнь всегда должна опережать смерть, иначе после очередной битвы не останется никого.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Служителем Солнца Дезко в Громовой Расселине, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30131,'Жизнь','Мой ребенок появляется на свет. Я должен помочь всем, чем могу.$b$bНе уходи, постой рядом. Если моя жена и ребенок выживут, я хочу показать им того, кому они обязаны жизнью.','Поговорите со Служителем Солнца Дезко и дождитесь появления новорожденного.','Поговорите со служителем солнца Дезко в Громовой Расселине, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой ребенок появляется на свет. Я должен помочь всем, чем могу.$b$bНе уходи, постой рядом. Если моя жена и ребенок выживут, я хочу показать им того, кому они обязаны жизнью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Служителем Солнца Дезко и дождитесь появления новорожденного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со служителем солнца Дезко в Громовой Расселине, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30132,'На запад','Леза теперь вместе с предками, что жили на этой странной земле. Я же должен позаботиться о живых.$b$bКор отправился с отрядом разведчиков на запад, дальше в джунгли.$b$bЯ отправил своего собственного дозорного осмотреть Храм Журавля. Прошу тебя, $n, найди моего разведчика, поговори с ним, а потом отправляйся к Кору и помоги ему, чем сможешь.$b$bМы присоединимся к вам сразу, как только освободимся.','$n! Ты вовремя!$b$bМы устраивали засаду на Альянс в руинах к западу отсюда, но на нас напали могу. Они призывают к себе подкрепление через порталы магов.','Война. Всегда все сводится к войне.','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На запад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леза теперь вместе с предками, что жили на этой странной земле. Я же должен позаботиться о живых.$b$bКор отправился с отрядом разведчиков на запад, дальше в джунгли.$b$bЯ отправил своего собственного дозорного осмотреть Храм Журавля. Прошу тебя, $n, найди моего разведчика, поговори с ним, а потом отправляйся к Кору и помоги ему, чем сможешь.$b$bМы присоединимся к вам сразу, как только освободимся.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n! Ты вовремя!$b$bМы устраивали засаду на Альянс в руинах к западу отсюда, но на нас напали могу. Они призывают к себе подкрепление через порталы магов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Война. Всегда все сводится к войне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30133,'Вперед, в глушь','Поговорите с Коро Странником Туманов у Храма Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в глушь',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Коро Странником Туманов у Храма Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30134,'Дикость','Найдите инструктора Туна на Наветренном острове в Нефритовом лесу.','Слава богу, что они наконец-то кого-то прислали!$B$BТут все пошло кувырком!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикость',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите инструктора Туна на Наветренном острове в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава богу, что они наконец-то кого-то прислали!$B$BТут все пошло кувырком!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30135,'Удачный исход','Убейте 8 потрошителей или яйцеедов из клана Скользкой Чешуи.','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удачный исход',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 потрошителей или яйцеедов из клана Скользкой Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30136,'Опустевшие гнезда','Когда начались нападения, маленькие змееныши в ужасе разбежались кто куда.$B$BСейчас они шатаются по всему острову – напуганные, оторванные от матерей.$B$BЕсли хочешь помочь, бери эту веревку и возьми на поводок заблудившихся малышей. Приведи их обратно к гнездам. Верни их домой!','Возьмите на поводок 6 детенышей облачного змея Наветренного острова и верните их в родные гнезда.','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опустевшие гнезда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда начались нападения, маленькие змееныши в ужасе разбежались кто куда.$B$BСейчас они шатаются по всему острову – напуганные, оторванные от матерей.$B$BЕсли хочешь помочь, бери эту веревку и возьми на поводок заблудившихся малышей. Приведи их обратно к гнездам. Верни их домой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите на поводок 6 детенышей облачного змея Наветренного острова и верните их в родные гнезда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30137,'Сбор яиц','А-а, мне стоило сразу догадаться! У тебя взгляд новичка.$B$BЯ бы с радостью помог тебе выбрать змеиное яйцо. Но клан Скользкой Чешуи обчистил все змеиные гнезда в округе.$B$BМне очень жаль. Не знаю, что тебе сказать.$B$BНо, может, тебе хватит безрассудства, чтобы прокрасться в лагерь сауроков, что к востоку отсюда, и утащить оттуда несколько украденных змеиных яиц? Иначе, боюсь, я не смогу тебе помочь.','Соберите 6 яиц облачного змея.','Чудесно!$B$BЭти яйца... они... ну, в общем, они какие-то мелковатые. Там точно не было ничего получше?$B$BА, ну ладно, учитывая положение вещей, выбирать не приходится.','Сауроки хранят украденные яйца облачных змеев у себя в лагере.','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор яиц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а, мне стоило сразу догадаться! У тебя взгляд новичка.$B$BЯ бы с радостью помог тебе выбрать змеиное яйцо. Но клан Скользкой Чешуи обчистил все змеиные гнезда в округе.$B$BМне очень жаль. Не знаю, что тебе сказать.$B$BНо, может, тебе хватит безрассудства, чтобы прокрасться в лагерь сауроков, что к востоку отсюда, и утащить оттуда несколько украденных змеиных яиц? Иначе, боюсь, я не смогу тебе помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 яиц облачного змея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно!$B$BЭти яйца... они... ну, в общем, они какие-то мелковатые. Там точно не было ничего получше?$B$BА, ну ладно, учитывая положение вещей, выбирать не приходится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сауроки хранят украденные яйца облачных змеев у себя в лагере.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Туну на Наветренный остров, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30138,'Избранный','$n, я осмотрел все яйца и отобрал три, обладающие наибольшим потенциалом.$B$BС собой ты можешь взять только одно.$B$BТы $gготов:готова; принять окончательное решение?','Поговорите с инструктором Туном на Наветренном острове, что в Нефритовом лесу.','Взять можно только одно яйцо.$B$BВыбирай тщательно, пути назад не будет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избранный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я осмотрел все яйца и отобрал три, обладающие наибольшим потенциалом.$B$BС собой ты можешь взять только одно.$B$BТы $gготов:готова; принять окончательное решение?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инструктором Туном на Наветренном острове, что в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взять можно только одно яйцо.$B$BВыбирай тщательно, пути назад не будет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (30139,'Путешествие наездника','Отлично! Просто великолепно! Я верну остальные яйца обратно в гнезда, не потревожив их.$B$BА ты пока доставь одно яйцо инструктору Небесному Шипу в Дендрарий.','Вернитесь к инструктору Небесному Шипу, который находится в Дендрарии, в Нефритовом лесу.','Ах, да, старейшина Анли говорила о том, что наши ряды пополнились новым учеником. Я вижу, ты уже выбрал своего облачного змея.$B$BЯ расскажу тебе, как ухаживать за ним. Дай мне пару минут.','Дикие облачные змеи живут в гармонии с природой. Их редкие яйца очень уязвимы для врагов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие наездника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично! Просто великолепно! Я верну остальные яйца обратно в гнезда, не потревожив их.$B$BА ты пока доставь одно яйцо инструктору Небесному Шипу в Дендрарий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к инструктору Небесному Шипу, который находится в Дендрарии, в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да, старейшина Анли говорила о том, что наши ряды пополнились новым учеником. Я вижу, ты уже выбрал своего облачного змея.$B$BЯ расскажу тебе, как ухаживать за ним. Дай мне пару минут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дикие облачные змеи живут в гармонии с природой. Их редкие яйца очень уязвимы для врагов.',`requestitemstext_loc8`);
