INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30142,'Это...','Ой! Змей может вылупиться из этого яйца в любую секунду!$B$BПохоже, малыш мечтает поскорее с тобой познакомиться.$B$BТы $gготов:готова;?','Смотрите, как из яйца вылупится змей.','Поздравляю! Теперь у тебя есть собственный детеныш змея.$B$BПожалуйста, позаботься о нем, Амарджин.','Вернитесь к инструктору Небесному Шипу в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой! Змей может вылупиться из этого яйца в любую секунду!$B$BПохоже, малыш мечтает поскорее с тобой познакомиться.$B$BТы $gготов:готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Смотрите, как из яйца вылупится змей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поздравляю! Теперь у тебя есть собственный детеныш змея.$B$BПожалуйста, позаботься о нем, Амарджин.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Небесному Шипу в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30143,'Растут, как сорняки','А-а, это снова ты, $n.$B$BИнструктор Режущий Ветер ищет тебя. Сейчас она на восточной гряде.$B$BУ нее какие-то новости о твоем змее.','Поговорите с инструктором Режущий Ветер в Дендрарии.','Поговорите с инструктором Режущий Ветер в Дендрарии, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растут, как сорняки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а, это снова ты, $n.$B$BИнструктор Режущий Ветер ищет тебя. Сейчас она на восточной гряде.$B$BУ нее какие-то новости о твоем змее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инструктором Режущий Ветер в Дендрарии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с инструктором Режущий Ветер в Дендрарии, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30144,'Обучение полету: через кольцо','Теперь, когда твой змей совсем взрослый, можно приступать к учебным полетам.$B$BТы – новичок, и поэтому тебе придется начать с азов.$B$BПервая задача проста. Пролети через 6 облачных колец, которые находятся на востоке, между шпилями.','Пролетите через 6 облачных колец на вашем облачном змее.','Итак, что мы извлекли из этого урока?$B$BСкорость. Главное – скорость.','Вернитесь к инструктору Режущий Ветер в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение полету: через кольцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда твой змей совсем взрослый, можно приступать к учебным полетам.$B$BТы – новичок, и поэтому тебе придется начать с азов.$B$BПервая задача проста. Пролети через 6 облачных колец, которые находятся на востоке, между шпилями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пролетите через 6 облачных колец на вашем облачном змее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, что мы извлекли из этого урока?$B$BСкорость. Главное – скорость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Режущий Ветер в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30146,'Пора перекусить','Облачные змеи любят поесть, а одно из их любимых лакомств – сахарный гольян.$B$BЭти рыбы водятся во всех водоемах Нефритового леса – и пресных, и соленых. Полагаю, ты умеешь рыбачить, и у тебя есть удочка, чтобы их поймать?$B$BПринеси мне несколько сахарных гольянов, и, я уверена, голодные облачные змеи будут тебе очень благодарны.','Поймайте 10 сахарных гольянов в пресных или соленых водоемах Пандарии.','Замечательно! Эта рыба – то, что надо.','Вернитесь к Дженове Зоркий Глаз в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора перекусить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Облачные змеи любят поесть, а одно из их любимых лакомств – сахарный гольян.$B$BЭти рыбы водятся во всех водоемах Нефритового леса – и пресных, и соленых. Полагаю, ты умеешь рыбачить, и у тебя есть удочка, чтобы их поймать?$B$BПринеси мне несколько сахарных гольянов, и, я уверена, голодные облачные змеи будут тебе очень благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 сахарных гольянов в пресных или соленых водоемах Пандарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Эта рыба – то, что надо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженове Зоркий Глаз в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30147,'Осколки прошлого','Посетите места археологических раскопок в Пандарии и соберите 6 реликвий наездников на змеях с помощью вашей способности "Исследовать".','Куанчи, это потрясающе. Найденные тобой реликвии просто бесценны. Изучив их, мы многое узнаем.','Как прошли раскопки?','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки прошлого',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите места археологических раскопок в Пандарии и соберите 6 реликвий наездников на змеях с помощью вашей способности "Исследовать".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Куанчи, это потрясающе. Найденные тобой реликвии просто бесценны. Изучив их, мы многое узнаем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как прошли раскопки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30148,'Всего лишь царапина','Прекрасно! Умение оказать первую помощь – весьма полезное качество.','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всего лишь царапина',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Умение оказать первую помощь – весьма полезное качество.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30149,'Пир чувств','Говорят, ты кое-что смыслишь в кулинарии.$B$BЭто весьма кстати – ведь облачные змеи обожают рыбные пироги.$B$BЕсли ты приготовишь и принесешь сюда 5 порций этого блюда, все здешние облачные змеи будут просто счастливы.','Приготовьте 5 рыбных пирогов.','О, на вид просто объеденье. Ты гениальный повар!','Тебе удалось найти необходимые ингредиенты?','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пир чувств',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, ты кое-что смыслишь в кулинарии.$B$BЭто весьма кстати – ведь облачные змеи обожают рыбные пироги.$B$BЕсли ты приготовишь и принесешь сюда 5 порций этого блюда, все здешние облачные змеи будут просто счастливы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 рыбных пирогов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, на вид просто объеденье. Ты гениальный повар!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти необходимые ингредиенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженове Зоркий Глаз в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30150,'Сладкий как мед','<Детеныш облачного змея носится вокруг вас, а зачем начинает издавать жалобные звуки.>$b$bПо его поведению вы понимаете, что ему хочется чего-то сладкого.$b$bАроматы деревьев Дендрария привлекают пчел.$b$bДолжно быть совсем нетрудно забрать медовые соты у медоносов.','Заберите 30 медовых сот у злых медоносов в Дендрарии.','Детеныш облачного змея бросается к вашей руке. Он обвивает вас длинным хвостом и начинает слизывать мед с ваших пальцев.$B$BЭто щекотно!','<Детеныш облачного змея кружится волчком, радуясь вашему возвращению.>','Вернитесь к вашему детенышу облачного змея в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкий как мед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Детеныш облачного змея носится вокруг вас, а зачем начинает издавать жалобные звуки.>$b$bПо его поведению вы понимаете, что ему хочется чего-то сладкого.$b$bАроматы деревьев Дендрария привлекают пчел.$b$bДолжно быть совсем нетрудно забрать медовые соты у медоносов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 30 медовых сот у злых медоносов в Дендрарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детеныш облачного змея бросается к вашей руке. Он обвивает вас длинным хвостом и начинает слизывать мед с ваших пальцев.$B$BЭто щекотно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Детеныш облачного змея кружится волчком, радуясь вашему возвращению.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вашему детенышу облачного змея в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30151,'Лови!','<Детеныш облачного змея смотрит на вас со скучающим и апатичным видом.>$b$bУ вас возникает ощущение, что он устал сидеть весь день взаперти.$b$bКак насчет игры в мяч?','Подбросьте прыгучий мяч. Затем поймайте его и снова бросьте своему змею. Повторите 8 раз.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лови!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Детеныш облачного змея смотрит на вас со скучающим и апатичным видом.>$b$bУ вас возникает ощущение, что он устал сидеть весь день взаперти.$b$bКак насчет игры в мяч?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подбросьте прыгучий мяч. Затем поймайте его и снова бросьте своему змею. Повторите 8 раз.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30152,'Небесная гонка','Пришло время большой гонки!$B$BПроложи маршрут среди шпилей и собери все 10 клетчатых флагов с контрольных точек.$B$BЗатем не забудь пролететь под финишной чертой.$B$BСостязание будет ожесточенным, так что желаю тебе удачи. Когда будешь $gготов:готова;, скажи мне об этом.','Примите участие в Небесной гонке, пролетев через 10 контрольных точек, а затем – под финишной чертой в Дендрарии.','Замечательно! Что ты чувствуешь после участия в Небесной гонке?$B$BНаверное, не терпится получить свой приз?','Поговорите со старейшиной Анли в Дендрарии, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небесная гонка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время большой гонки!$B$BПроложи маршрут среди шпилей и собери все 10 клетчатых флагов с контрольных точек.$B$BЗатем не забудь пролететь под финишной чертой.$B$BСостязание будет ожесточенным, так что желаю тебе удачи. Когда будешь $gготов:готова;, скажи мне об этом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Примите участие в Небесной гонке, пролетев через 10 контрольных точек, а затем – под финишной чертой в Дендрарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Что ты чувствуешь после участия в Небесной гонке?$B$BНаверное, не терпится получить свой приз?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со старейшиной Анли в Дендрарии, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30153,'Полный вперед','Начинаем тренировку.$B$BЛети за мной вокруг шпилей. Посмотрим, сумеешь ли ты не отстать.','Следуйте за инструктором Режущий Ветер.','Вернитесь к инструктору Режущий Ветер в Дендрарий в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полный вперед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начинаем тренировку.$B$BЛети за мной вокруг шпилей. Посмотрим, сумеешь ли ты не отстать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуйте за инструктором Режущий Ветер.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Режущий Ветер в Дендрарий в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30154,'Самый легкий путь к сердцу змея','<Детеныш облачного змея сердито смотрит на вас.>$b$bПохоже, кое-кто сегодня не в духе!$b$bК счастью, вам прекрасно известно, что может поднять настроение этому маленькому созданию.$b$bОблачные змеи обожают вкус тигриного мяса. Но раздобыть тигриный бок не так-то легко.$b$bВы вспоминаете, что на Наветренном острове, расположенному к северо-западу отсюда, водятся жирные тигры, мясо которых очень сочное.$b$bКонечно, не обойдется без синяков и царапин, но ваш облачный змей того стоит, не правда ли?','Раздобудьте 5 тигриных боков.','Смотрю, ты проявил усердие, добывая пищу для своего голодного маленького змея. Хорошо. Не сомневайся, со временем он оценит твои усилия и полюбит тебя за это.','Похоже, дело сделано.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самый легкий путь к сердцу змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Детеныш облачного змея сердито смотрит на вас.>$b$bПохоже, кое-кто сегодня не в духе!$b$bК счастью, вам прекрасно известно, что может поднять настроение этому маленькому созданию.$b$bОблачные змеи обожают вкус тигриного мяса. Но раздобыть тигриный бок не так-то легко.$b$bВы вспоминаете, что на Наветренном острове, расположенному к северо-западу отсюда, водятся жирные тигры, мясо которых очень сочное.$b$bКонечно, не обойдется без синяков и царапин, но ваш облачный змей того стоит, не правда ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 5 тигриных боков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотрю, ты проявил усердие, добывая пищу для своего голодного маленького змея. Хорошо. Не сомневайся, со временем он оценит твои усилия и полюбит тебя за это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, дело сделано.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30155,'Восстановление равновесия','$n, положение на островах остается очень тяжелым.$B$BСауроки из племени Скользкой Чешуи отказались от мирных переговоров, так что особого выбора у нас нет.$B$BЧтобы защитить диких облачных змеев, мы должны очистить остров от браконьеров. Только тогда змеи смогут жить спокойно.','Убейте 8 потрошителей или яйцеедов из клана Скользкой Чешуи.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление равновесия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, положение на островах остается очень тяжелым.$B$BСауроки из племени Скользкой Чешуи отказались от мирных переговоров, так что особого выбора у нас нет.$B$BЧтобы защитить диких облачных змеев, мы должны очистить остров от браконьеров. Только тогда змеи смогут жить спокойно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 потрошителей или яйцеедов из клана Скользкой Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30156,'Время кормления','<Детеныш облачного змея кидается к вам и начинает покусывать за пальцы.>$b$bБольно! Нет никаких сомнений в том, что ваш маленький питомец голоден. Вы припоминаете, что на острове к северо-востоку отсюда, где живут дикие облачные змеи, обитают весьма мясистые на вид черепахи.$b$BМожет быть, черепашье мясо утолит голод вашего прожорливого малыша?','Скормите вашему змею 3 больших куска мяса черепахи соленых вод.','Ты быстро учишься, юный укротитель. Черепашье мясо жесткое. Но зато в нем много питательных веществ, которые необходимы молодому змею, чтобы расти.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время кормления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Детеныш облачного змея кидается к вам и начинает покусывать за пальцы.>$b$bБольно! Нет никаких сомнений в том, что ваш маленький питомец голоден. Вы припоминаете, что на острове к северо-востоку отсюда, где живут дикие облачные змеи, обитают весьма мясистые на вид черепахи.$b$BМожет быть, черепашье мясо утолит голод вашего прожорливого малыша?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скормите вашему змею 3 больших куска мяса черепахи соленых вод.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты быстро учишься, юный укротитель. Черепашье мясо жесткое. Но зато в нем много питательных веществ, которые необходимы молодому змею, чтобы расти.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30157,'Опустевшие гнезда','Ну, слава богу, еще один укротитель змеев!$b$bМне только что стало известно, что детеныши диких облачных змеев на Наветренном острове подвергаются серьезной опасности!$b$bКто позаботится о милых малышах, когда взрослые змеи сражаются с этими ужасными сауроками? Конечно, никто!$b$bМы должны спасти их!$b$bКаждого укротителя змеев я прошу отправиться туда и помочь. Если ты не очень $gзанят:занята;, может быть, ты проследишь за тем, чтобы детеныши облачных змеев благополучно добрались до родных гнезд?','Возьмите на поводок 6 детенышей облачных змеев Наветренного острова и верните их в родные гнезда.','Вижу, ты прекрасно позаботился о маленьких облачных змеях. Молодец!','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опустевшие гнезда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, слава богу, еще один укротитель змеев!$b$bМне только что стало известно, что детеныши диких облачных змеев на Наветренном острове подвергаются серьезной опасности!$b$bКто позаботится о милых малышах, когда взрослые змеи сражаются с этими ужасными сауроками? Конечно, никто!$b$bМы должны спасти их!$b$bКаждого укротителя змеев я прошу отправиться туда и помочь. Если ты не очень $gзанят:занята;, может быть, ты проследишь за тем, чтобы детеныши облачных змеев благополучно добрались до родных гнезд?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите на поводок 6 детенышей облачных змеев Наветренного острова и верните их в родные гнезда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты прекрасно позаботился о маленьких облачных змеях. Молодец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30158,'Обезоруженный противник','Если мы хотим остановить браконьеров, надо действовать более агрессивно.$B$BЕсли мы лишим врагов того, чем они ловят и убивают змеев, то сможем навсегда покончить с их промыслом.$B$BОтправляйся в восточную часть Наветренного острова, на земли браконьеров, и выкради их оружие.$B$BЕсли обрезать кошке когти, она не сможет царапаться.','Соберите 5 гарпунов Скользкой Чешуи.','Мы их ослабили, но радоваться рано. Даже беззубый тигр опасен.','Готово?','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезоруженный противник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим остановить браконьеров, надо действовать более агрессивно.$B$BЕсли мы лишим врагов того, чем они ловят и убивают змеев, то сможем навсегда покончить с их промыслом.$B$BОтправляйся в восточную часть Наветренного острова, на земли браконьеров, и выкради их оружие.$B$BЕсли обрезать кошке когти, она не сможет царапаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 гарпунов Скользкой Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы их ослабили, но радоваться рано. Даже беззубый тигр опасен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30159,'Сохранение','О нет! Мы должны остановить их, да, $n? Ордену нужна твоя помощь!$b$bЗнаешь, что делают эти ужасные сауроки из клана Скользкой ЧЕшуи?$B$BТеперь они настолько обнаглели, что крадут яйца прямо из гнезд матриархов!$b$bВ то время, когда облачные змеи становятся все более и более редкими, эти... эти негодяи...$b$b<Су-Чи глубоко вздыхает.>$b$b...они едят яйца на обед! Это ужасно!$b$bОтправляйся на северо-восток, на Наветренный остров и собери все оставшиеся целые яйца. Мы – ученики Ордена, и это наш долг!','Соберите 8 украденных яиц.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О нет! Мы должны остановить их, да, $n? Ордену нужна твоя помощь!$b$bЗнаешь, что делают эти ужасные сауроки из клана Скользкой ЧЕшуи?$B$BТеперь они настолько обнаглели, что крадут яйца прямо из гнезд матриархов!$b$bВ то время, когда облачные змеи становятся все более и более редкими, эти... эти негодяи...$b$b<Су-Чи глубоко вздыхает.>$b$b...они едят яйца на обед! Это ужасно!$b$bОтправляйся на северо-восток, на Наветренный остров и собери все оставшиеся целые яйца. Мы – ученики Ордена, и это наш долг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 украденных яиц.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30160,'Рубиновый осколок для Эллы','Это мне? Я... даже не знаю, что сказать.$B$BОчень красиво, спасибо тебе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рубиновый осколок для Эллы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это мне? Я... даже не знаю, что сказать.$B$BОчень красиво, спасибо тебе!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30163,'За племя','Когда могу напали, мы отступили в убежище, но потеряли многих наших друзей.$b$bПоищи на севере и на западе пленников, которых еще можно спасти. И они еще помогут нам в бою.$b$bА всех воинов Альянса, которых найдешь, можешь бросить на произвол судьбы.','Освободите 8 плененных Искателей Зари.','Мы уже потеряли многих. И я не допущу, чтобы мы потеряли еще больше.','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За племя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда могу напали, мы отступили в убежище, но потеряли многих наших друзей.$b$bПоищи на севере и на западе пленников, которых еще можно спасти. И они еще помогут нам в бою.$b$bА всех воинов Альянса, которых найдешь, можешь бросить на произвол судьбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 плененных Искателей Зари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы уже потеряли многих. И я не допущу, чтобы мы потеряли еще больше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (30164,'Я пытался спасти посланников Каменного Плуга, но многих из них эти "богомолы" утащили в джунгли.$b$bЭтим мирным жителям нужна наша помощь.$b$bПожалуйста, возьми с собой растения, которые ты $gсобрал:собрала; раньше. Я наполнил их силой Света, которая мне подвластна. Исцели с их помощью посланников Каменного Плуга.','Поговорите со Служителем Солнца Дезко у Разбитого конвоя в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытался спасти посланников Каменного Плуга, но многих из них эти "богомолы" утащили в джунгли.$b$bЭтим мирным жителям нужна наша помощь.$b$bПожалуйста, возьми с собой растения, которые ты $gсобрал:собрала; раньше. Я наполнил их силой Света, которая мне подвластна. Исцели с их помощью посланников Каменного Плуга.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Служителем Солнца Дезко у Разбитого конвоя в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30165,'Выслеживание: найден синий змей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: найден синий змей',`title_loc8`);
