INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30167,'Выслеживание: найден золотой змей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: найден золотой змей',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30168,'Налетчики-грабители','Сауроки!$b$bЭти отвратительные создания обожают воровать и убивать. Они атаковали наше поселение без малейшего повода!$b$b$c, помоги отобрать наше имущество у этих разорителей Речного Клинка, которые околачиваются около реки, и мы вознаградим тебя.','Верните 5 украденных вещей цзинь-юй.','Немногие захотят помочь попавшей в беду деревне... особенно в такой глуши.$b$bМой народ всегда будет чтить тебя, $n.','Даже мою священную плевательницу – и ту, похоже, украли.','Поговорите с Усталым Шу-шэнем в Деревне Поющего Водопада, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Налетчики-грабители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки!$b$bЭти отвратительные создания обожают воровать и убивать. Они атаковали наше поселение без малейшего повода!$b$b$c, помоги отобрать наше имущество у этих разорителей Речного Клинка, которые околачиваются около реки, и мы вознаградим тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 5 украденных вещей цзинь-юй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Немногие захотят помочь попавшей в беду деревне... особенно в такой глуши.$b$bМой народ всегда будет чтить тебя, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже мою священную плевательницу – и ту, похоже, украли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Усталым Шу-шэнем в Деревне Поющего Водопада, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30169,'Командир налетчиков Слован','Налетчиков возглавляет особенно злобный саурок по имени Слован. Обычно Храм Журавля помогает нам справляться с его головорезами, но сейчас нас перехитрили и переиграли.$b$bПрошу тебя, |3-6($c), помоги нам, убей их вожака.$b$bТы найдешь Слована в его логове за Красарангским водопадом.','Убейте Слована.','Поговорите с Усталым Шу-шэнем в Деревне Поющего Водопада, что в Красарангских джунглях.','Гроза водопадов.','Командир налетчиков Слован') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир налетчиков Слован',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Налетчиков возглавляет особенно злобный саурок по имени Слован. Обычно Храм Журавля помогает нам справляться с его головорезами, но сейчас нас перехитрили и переиграли.$b$bПрошу тебя, |3-6($c), помоги нам, убей их вожака.$b$bТы найдешь Слована в его логове за Красарангским водопадом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Слована.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Усталым Шу-шэнем в Деревне Поющего Водопада, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Гроза водопадов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир налетчиков Слован',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30172,'Катить бочку','Нет-нет-нет, поднимать бочки не нужно. Я сам их удержу.$b$bПусть я и не самый красивый в мире пандарен, и не самый умный, и шутки у меня дурацкие, но зато я сильнее даже дикого мушана.$b$bПросто покажи мне дорогу, а бочки я донесу.','Отведите Грязную Кружку в Полугорье.$b$bЕсли вы разделитесь, ищите Грязную Кружку у огромного банана в Золоченом Веере.','Отлично! Вода здесь!','Поговорите с Чэнем Буйным Портером на Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катить бочку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет-нет-нет, поднимать бочки не нужно. Я сам их удержу.$b$bПусть я и не самый красивый в мире пандарен, и не самый умный, и шутки у меня дурацкие, но зато я сильнее даже дикого мушана.$b$bПросто покажи мне дорогу, а бочки я донесу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Грязную Кружку в Полугорье.$b$bЕсли вы разделитесь, ищите Грязную Кружку у огромного банана в Золоченом Веере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Вода здесь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером на Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30173,'Свиньи войны!','test2 test2 test2 $o1a $o1o') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свиньи войны!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','test2 test2 test2 $o1a $o1o',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30174,'Ради семьи','Кор должен был уже догнать нас. Он сказал, что собирается завладеть Руинами Корцзя, что к востоку отсюда, и поможет нам справиться с богомолами.$b$bНо ему может самому понадобиться помощь в борьбе с Первопроходцем Брожаем. Ты его поддержишь? Мы с Каном скоро подойдем.','Разыщите Кора Кровавого Бивня.','Спасибо, $n, что $gотомстил:отомстила; за моего друга. Мы нечасто виделись, но я буду оплакивать его.$b$bЗнаю, он обязательно захотел бы отдать тебе одну из своих вещей на память в знак признательности.','Поговорите с Дезко в Укрытии Искателей Зари, что в Красарангских джунглях.','Главный Искатель','Первопроходец Брожай') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ради семьи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кор должен был уже догнать нас. Он сказал, что собирается завладеть Руинами Корцзя, что к востоку отсюда, и поможет нам справиться с богомолами.$b$bНо ему может самому понадобиться помощь в борьбе с Первопроходцем Брожаем. Ты его поддержишь? Мы с Каном скоро подойдем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Кора Кровавого Бивня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $n, что $gотомстил:отомстила; за моего друга. Мы нечасто виделись, но я буду оплакивать его.$b$bЗнаю, он обязательно захотел бы отдать тебе одну из своих вещей на память в знак признательности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дезко в Укрытии Искателей Зари, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Главный Искатель',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Первопроходец Брожай',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30175,'Богомолы','Богомолы! Они явились из ниоткуда и разнесли нашу колонну вдребезги, выжившие разбежались кто куда.$b$bТеперь они готовятся напасть на Каменный Плуг.$b$bПрошу тебя, |3-6($c), уничтожь этих чудовищ, пока они не собрали целое войско для штурма.$b$bЕсли мой брат, посланник Лен, уцелел в этой бойне, он вознаградит тебя за помощь.','Убейте 10 ик\'тиков-прародителей.','Поговорите с посланником Леном в Запретных джунглях, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богомолы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы! Они явились из ниоткуда и разнесли нашу колонну вдребезги, выжившие разбежались кто куда.$b$bТеперь они готовятся напасть на Каменный Плуг.$b$bПрошу тебя, |3-6($c), уничтожь этих чудовищ, пока они не собрали целое войско для штурма.$b$bЕсли мой брат, посланник Лен, уцелел в этой бойне, он вознаградит тебя за помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ик\'тиков-прародителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посланником Леном в Запретных джунглях, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30177,'Daily Heroic Random (1st) (Cataclysm)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Daily Heroic Random (1st) (Cataclysm)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30178,'Вперед, в глушь','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победил ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.','Поговорите с Коро Странником Туманов у Храма Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в глушь',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победил ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Коро Странником Туманов у Храма Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30179,'Отрава!','Эти... могу. Не верь им. Яд. Возьми образец... клинки. Принеси их Дезко... Он в Громовой Расселине к западу отсюда.','Соберите 5 отравленных клинков могу.','Есть новости о Чэцзыне?','Поговорите со Служителем Солнца Дезко в Громовой Расселине, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрава!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти... могу. Не верь им. Яд. Возьми образец... клинки. Принеси их Дезко... Он в Громовой Расселине к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 отравленных клинков могу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости о Чэцзыне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Служителем Солнца Дезко в Громовой Расселине, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30180,'Помощь при родах','Моя жена Леза вот-вот начнет рожать, но она больна, очень больна. Мне надо согреть ее, но у нас закончились дрова.$b$bТы можешь собрать нам хворост и ветки с ближайших деревьев? Время уже на исходе!','Соберите 8 кусков древесины.','Поговорите со служителем солнца Дезко в Громовой Расселине, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь при родах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя жена Леза вот-вот начнет рожать, но она больна, очень больна. Мне надо согреть ее, но у нас закончились дрова.$b$bТы можешь собрать нам хворост и ветки с ближайших деревьев? Время уже на исходе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кусков древесины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со служителем солнца Дезко в Громовой Расселине, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30181,'Охота на мушанов','Мушаны! И какие огромные! Им, наверное, столько же лет, сколько и этой земле. Замечательные трофеи.$b$bЕсли хочешь попробовать свои силы в охоте на крупную дичь, начни с них.','Убейте 15 серобоких мушанов.','Поговорите с Хемингом Эрнестуэем-младшим в охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на мушанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мушаны! И какие огромные! Им, наверное, столько же лет, сколько и этой земле. Замечательные трофеи.$b$bЕсли хочешь попробовать свои силы в охоте на крупную дичь, начни с них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 серобоких мушанов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хемингом Эрнестуэем-младшим в охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30182,'Охота на лис','К востоку отсюда я видела много лисиц. Когда я только начинала охотиться, еще на Скитающемся острове, они были моей первой добычей.$b$bЕсли хочешь понять, с чем приходится иметь дело юному охотнику-пандарену, иди на восток и поохоться на лис. Это умные и хитрые твари, так что будь начеку.','Убейте 15 хитрых лисиц.','Отлично! Тебе удалось перехитрить лис. Я поговорю с мистером Плибом, чтобы для тебя сделали еще один трофей.','Поговорите с Тани в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на лис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К востоку отсюда я видела много лисиц. Когда я только начинала охотиться, еще на Скитающемся острове, они были моей первой добычей.$b$bЕсли хочешь понять, с чем приходится иметь дело юному охотнику-пандарену, иди на восток и поохоться на лис. Это умные и хитрые твари, так что будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 хитрых лисиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Тебе удалось перехитрить лис. Я поговорю с мистером Плибом, чтобы для тебя сделали еще один трофей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тани в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30183,'Охота на тигров','Тигры! Куда бы я ни пошла, постоянно слышу про этих клыкастых тварей. Но шанса поохотиться на них у меня пока не было.$b$bТак что давай устроим охоту на тигров. Я пойду на восток, ты иди на запад. Кажется, я видела какую-то стаю около Серого ущелья. Ну и возле мушанов их, наверняка, полно.','Убейте 15 горных хищников.','Ух ты! Очень неплохо. Я поговорю с мистером Плибом, чтобы для тебя сделали трофей.','Поговорите с Тани в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на тигров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тигры! Куда бы я ни пошла, постоянно слышу про этих клыкастых тварей. Но шанса поохотиться на них у меня пока не было.$b$bТак что давай устроим охоту на тигров. Я пойду на восток, ты иди на запад. Кажется, я видела какую-то стаю около Серого ущелья. Ну и возле мушанов их, наверняка, полно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 горных хищников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Очень неплохо. Я поговорю с мистером Плибом, чтобы для тебя сделали трофей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тани в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30184,'Охота на мушанов: Черношкур','Парнишка мой – талантливый охотник, в теории. Давай покажем ему, что такое охота в духе старого Несси?$b$bНа востоке отсюда я видел огромного мушана со шкурой черной, как ночи. И, судя по виду, у него на счету не один охотник.$b$bЕсли тебе нужна настоящая охота – попытайся убить его.','Убейте Черношкура и заберите его голову.','Вот это настоящий трофей!','Ну что ж, охотнику на крупную дичь – самого свирепого хищника.','Поговорите с Хемингом Эрнестуэем в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.','Зверь, о котором в округе ходят легенды.','Черношкур') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на мушанов: Черношкур',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Парнишка мой – талантливый охотник, в теории. Давай покажем ему, что такое охота в духе старого Несси?$b$bНа востоке отсюда я видел огромного мушана со шкурой черной, как ночи. И, судя по виду, у него на счету не один охотник.$b$bЕсли тебе нужна настоящая охота – попытайся убить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Черношкура и заберите его голову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это настоящий трофей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что ж, охотнику на крупную дичь – самого свирепого хищника.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хемингом Эрнестуэем в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Зверь, о котором в округе ходят легенды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Черношкур',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30185,'Охота на черепах','Да, черепахи – твари невеликие, но зато это отличная приманка для большой дичи!$b$bТут недавно нашли какие-то скрижали – и в них говорится, что при древних императорах преступников и недовольных приносили в жертву – бросали в Тораджарскую яму.$b$bНу так вот, я хочу выяснить, что за существа там обитают. Набери черепашьих панцирей и приходи к яме.$b$bПосмотрим, не врут ли легенды.','Соберите 5 неповрежденных черепашьих панцирей.','Спасибо! Теперь я точно обгоню папашу!','Мой отец – такая фигура, что я всегда оставался где-то в тени, на заднем плане. Но сегодня все изменится! Люди узнают, кто такой Хеминг Эрнестуэй-младший!','Поговорите с Хемингом Эрнестуэем-младшим в Тораджарской яме, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на черепах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, черепахи – твари невеликие, но зато это отличная приманка для большой дичи!$b$bТут недавно нашли какие-то скрижали – и в них говорится, что при древних императорах преступников и недовольных приносили в жертву – бросали в Тораджарскую яму.$b$bНу так вот, я хочу выяснить, что за существа там обитают. Набери черепашьих панцирей и приходи к яме.$b$bПосмотрим, не врут ли легенды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 неповрежденных черепашьих панцирей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Теперь я точно обгоню папашу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой отец – такая фигура, что я всегда оставался где-то в тени, на заднем плане. Но сегодня все изменится! Люди узнают, кто такой Хеминг Эрнестуэй-младший!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хемингом Эрнестуэем-младшим в Тораджарской яме, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30186,'Отцы и дети','Если древние скрижали не врут, нам надо всего лишь маленько поплясать, и тогда из глубин появится чудовище.$b$bА мы такие на него бросимся и докажем моему папаше, что мы – настоящие охотники.','Уничтожьте Тораджарскую Погибель.','Поговорите с Хемингом Эрнестуэем в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.','Легендарное чудовище','Тораджарская Погибель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отцы и дети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если древние скрижали не врут, нам надо всего лишь маленько поплясать, и тогда из глубин появится чудовище.$b$bА мы такие на него бросимся и докажем моему папаше, что мы – настоящие охотники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Тораджарскую Погибель.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хемингом Эрнестуэем в Охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Легендарное чудовище',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тораджарская Погибель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30189,'Милое яблочко для Эллы','Это мне? Серьезно?$B$BТакое милое яблоко нельзя есть в одиночку.$B$BВот тебе половина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милое яблочко для Эллы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это мне? Серьезно?$B$BТакое милое яблоко нельзя есть в одиночку.$B$BВот тебе половина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30190,'Снова духи? Я не в духе!','Снова эти духи! Как я их ненавижу. Надо остановить их, пока они не покалечили кого-нибудь или не спалили полдеревни!$B$BУвидишь этих пакостников – разберись с ними!','Убейте 8 синекожих проказников.','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова духи? Я не в духе!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Снова эти духи! Как я их ненавижу. Надо остановить их, пока они не покалечили кого-нибудь или не спалили полдеревни!$B$BУвидишь этих пакостников – разберись с ними!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 синекожих проказников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30191,'Вернуть украденные бочки!','Кто-то оставил пиво на южном склоне, и теперь духи пристрастились к нашему вареву. По утрам они пробираются в город и тащат все бочонки, которые могут найти.$B$BВерни столько, сколько сможешь. Пандарен, работающий без пива... от него толку не будет. Нам нужно поддерживать всех в форме.','Верните 10 украденных бочонков из деревни Туманного Водопада.','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть украденные бочки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто-то оставил пиво на южном склоне, и теперь духи пристрастились к нашему вареву. По утрам они пробираются в город и тащат все бочонки, которые могут найти.$B$BВерни столько, сколько сможешь. Пандарен, работающий без пива... от него толку не будет. Нам нужно поддерживать всех в форме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 10 украденных бочонков из деревни Туманного Водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30192,'Горит мой город','Не знаю, $gзаметил:заметила; ли ты, но мой город в огне!$B$BДухи переворачивают жаровни! Они так спалят все вокруг!$B$BПрошу, помоги нам! Потуши пламя везде, где увидишь!','Потушите 30 огней жаровен.','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горит мой город',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, $gзаметил:заметила; ли ты, но мой город в огне!$B$BДухи переворачивают жаровни! Они так спалят все вокруг!$B$BПрошу, помоги нам! Потуши пламя везде, где увидишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите 30 огней жаровен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30193,'Ожидания мясоедов','Хорошие работники заслуживают доброго обеда, но у меня закончилось свежее мясо!$B$BМожешь сходить на охоту в лес и принести мне мясо газели?','Добудьте 10 кусков мяса долинной газели.','Вернитесь к повару Топу в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожидания мясоедов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошие работники заслуживают доброго обеда, но у меня закончилось свежее мясо!$B$BМожешь сходить на охоту в лес и принести мне мясо газели?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кусков мяса долинной газели.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повару Топу в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30194,'Надвигается буря','В деревне этим утром пропал очередной як. Эти громовые волки из-за реки слишком осмелели.$B$BИх стало больше, чем дол может вынести. Пора проредить их стаю.$B$BЯ буду крайне признателен, если ты согласишься помочь с этим.','Убейте 8 громовых волков.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надвигается буря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В деревне этим утром пропал очередной як. Эти громовые волки из-за реки слишком осмелели.$B$BИх стало больше, чем дол может вынести. Пора проредить их стаю.$B$BЯ буду крайне признателен, если ты согласишься помочь с этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 громовых волков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30195,'Вечноцветы','Не окажешь ли услугу скромному торговцу? Мне нужно пополнить запасы вечноцвета. Эти цветы можно найти в лесу неподалеку.$B$BМожет, соберешь их для меня?','Соберите 10 вечноцветов.','Вернитесь к торговцу Бенни в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечноцветы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не окажешь ли услугу скромному торговцу? Мне нужно пополнить запасы вечноцвета. Эти цветы можно найти в лесу неподалеку.$B$BМожет, соберешь их для меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 вечноцветов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Бенни в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30196,'Мягкогрибной сезон','На строительстве новой деревни, похоже, полно проголодавшихся работников!$B$BМне нужны мягкогрибы, чтобы приготовить похлебку по моему фирменному рецепту. Мягкогрибы растут на кладбище Ту-Шэнь к востоку отсюда. Но там беснуются неупокоенные духи, а боец из меня никудышный.$B$BЕсли будешь сегодня на кладбище, собери мне немного мягкогрибов, хорошо?','Соберите 12 мягкогрибов.','Вернитесь к повару Топу в деревню Туманного Водопада, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мягкогрибной сезон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На строительстве новой деревни, похоже, полно проголодавшихся работников!$B$BМне нужны мягкогрибы, чтобы приготовить похлебку по моему фирменному рецепту. Мягкогрибы растут на кладбище Ту-Шэнь к востоку отсюда. Но там беснуются неупокоенные духи, а боец из меня никудышный.$B$BЕсли будешь сегодня на кладбище, собери мне немного мягкогрибов, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 мягкогрибов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повару Топу в деревню Туманного Водопада, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30197,'Поездка на повозке','Тихо сегодня в нашем доле. Я пошлю Рука на повозке с припасами в деревню XXX. Отправляйся с ним.','Отвезите повозку с припасами в деревню XXX.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поездка на повозке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тихо сегодня в нашем доле. Я пошлю Рука на повозке с припасами в деревню XXX. Отправляйся с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите повозку с припасами в деревню XXX.',`objectives_loc8`);
