INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30204,'Это не камень!','У меня от этих пауков мурашки по спине. Особенно когда на кокон с яйцами случайно наступишь, и сразу по тебе ползет куча мерзких мелких паучат. Как вспомню, так вздрогну.$B$BСожги их, а? Всех сожги.','Убейте 50 пепельных паучат. Факел Куна сожжет их вместе с коконами.','Вернитесь к Куню Осеннему Свету на Руины Го-Лай в Вечноцветущий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это не камень!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня от этих пауков мурашки по спине. Особенно когда на кокон с яйцами случайно наступишь, и сразу по тебе ползет куча мерзких мелких паучат. Как вспомню, так вздрогну.$B$BСожги их, а? Всех сожги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 пепельных паучат. Факел Куна сожжет их вместе с коконами.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету на Руины Го-Лай в Вечноцветущий дол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30205,'Рунические замки','Здравствуй, мой друг.$B$BОдин из воинов Левена принес весть о том, что в восточных руинах хранится реликвия могу. Однако ему не удалось ее заполучить. Мне кажется, что реликвия находится под защитой рунических замков.$B$BПодле реликвии должно быть четыре руны. Если их активировать, то замки откроются, и ты сможешь достать реликвию. Принеси мне ее, и я буду очень признателен.','Найдите древнюю реликвию могу.','Вернитесь к Сынань Мечтательнице на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рунические замки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, мой друг.$B$BОдин из воинов Левена принес весть о том, что в восточных руинах хранится реликвия могу. Однако ему не удалось ее заполучить. Мне кажется, что реликвия находится под защитой рунических замков.$B$BПодле реликвии должно быть четыре руны. Если их активировать, то замки откроются, и ты сможешь достать реликвию. Принеси мне ее, и я буду очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите древнюю реликвию могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сынань Мечтательнице на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30206,'Руны в руинах','В этих руинах хранятся бесценные рунные камни. Они бы нам очень пригодились в восточной части дола.$B$B Пожалуйста, принеси их мне, если найдешь. Договорились?','Соберите 12 рунических камней Го-лай.','Вернитесь к Сынань Мечтательнице на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руны в руинах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих руинах хранятся бесценные рунные камни. Они бы нам очень пригодились в восточной части дола.$B$B Пожалуйста, принеси их мне, если найдешь. Договорились?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 рунических камней Го-лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сынань Мечтательнице на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
