INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30225,'Матриарх пепельных пауков','Мой дорогой Кун заметил, что из Залов Го-Лай лезут все новые пауки. Ему удалось выяснить, что внутри расположилась еще один паук-матриарх.$B$BТебе придется убить эту тварь.','Убейте Кроволапку, матриарха пепельных пауков.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Матриарх пепельных пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой дорогой Кун заметил, что из Залов Го-Лай лезут все новые пауки. Ему удалось выяснить, что внутри расположилась еще один паук-матриарх.$B$BТебе придется убить эту тварь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кроволапку, матриарха пепельных пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30226,'Кровь на руинах','На Возвышающихся руинах, к северу отсюда, видели небольшую группу могу.$B$BЛиквидируй их.','Убейте 8 могу Шао-Тень на Возвышающихся руинах.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь на руинах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Возвышающихся руинах, к северу отсюда, видели небольшую группу могу.$B$BЛиквидируй их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 могу Шао-Тень на Возвышающихся руинах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30227,'Гранитный страж Улунь','Одна из статуй цийлиней в Залах Го-Лай внезапно ожила и едва не убила моего дорогого Куна. Это недопустимо! Никто не смеет угрожать ему.$B$BИди туда сейчас же и разбей эту мерзкую вещь. Мне недосуг, моему любимому нужен уход.','Убейте гранитного стража Улуня.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гранитный страж Улунь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из статуй цийлиней в Залах Го-Лай внезапно ожила и едва не убила моего дорогого Куна. Это недопустимо! Никто не смеет угрожать ему.$B$BИди туда сейчас же и разбей эту мерзкую вещь. Мне недосуг, моему любимому нужен уход.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гранитного стража Улуня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30228,'Как смутить смутьянов','Лесные духи вернулись. Убей их, пока они опять не напакостили.','Убейте 8 духов Каменной Коры.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как смутить смутьянов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесные духи вернулись. Убей их, пока они опять не напакостили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 духов Каменной Коры.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30229,'Великая опасность','Прошу прощения за те резкие слова. Дезко определенно был прав. Надо было дождаться остальных и выдвигаться на запад вместе.$b$bМогу задали нам жару, когда мы обыскивали руины к западу отсюда. Они повылезали из порталов и использовали какую-то темную магию. Столь злого колдовства мне еще не приходилось встречать со времен демонов из Запределья.$b$bНам нужна передышка. Отправляйся на запад, убей призывателей, лиши могу поддержки.','Убейте 8 искателей из Корцзя.','Теперь, когда их подкрепление разбито, мы можем начать атаку на Главного Искателя.','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая опасность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу прощения за те резкие слова. Дезко определенно был прав. Надо было дождаться остальных и выдвигаться на запад вместе.$b$bМогу задали нам жару, когда мы обыскивали руины к западу отсюда. Они повылезали из порталов и использовали какую-то темную магию. Столь злого колдовства мне еще не приходилось встречать со времен демонов из Запределья.$b$bНам нужна передышка. Отправляйся на запад, убей призывателей, лиши могу поддержки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 искателей из Корцзя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда их подкрепление разбито, мы можем начать атаку на Главного Искателя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30230,'Кто-то теряет, кто-то находит','Могу – бандиты. И всегда ими были.$b$bЛишь в старые времена, когда они правили своими империями, им была известна магия.$b$bНо эти могу используют волшебные порталы и заклинания. Их надо остановить!$b$b$n, поищи артефакты, с помощью которых могу творят свою магию. На севере и на западе повсюду бродят их сборщики и искатели, они собирают эти артефакты.','Соберите 10 артефактов могу.','Отлично, $n. Спички детям не игрушка.','Каждый отобранный нами артефакт – серьезный удар по могу.','Поговорите с Каном Ежевичным Посохом в Укрытии Искателей Зари, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто-то теряет, кто-то находит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу – бандиты. И всегда ими были.$b$bЛишь в старые времена, когда они правили своими империями, им была известна магия.$b$bНо эти могу используют волшебные порталы и заклинания. Их надо остановить!$b$b$n, поищи артефакты, с помощью которых могу творят свою магию. На севере и на западе повсюду бродят их сборщики и искатели, они собирают эти артефакты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 артефактов могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $n. Спички детям не игрушка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Каждый отобранный нами артефакт – серьезный удар по могу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каном Ежевичным Посохом в Укрытии Искателей Зари, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30231,'Сбор тыблок','Мне нужно больше тыблок! Сбей с веток несколько штук, хорошо?$B$BВот, возьми. Пригодится на уборке фруктов. Гораздо проще собирать тыблоки, когда они сами к тебе падают.','Соберите 12 тыблок.','Вернитесь к повару Топу в деревню Туманного Водопада, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор тыблок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно больше тыблок! Сбей с веток несколько штук, хорошо?$B$BВот, возьми. Пригодится на уборке фруктов. Гораздо проще собирать тыблоки, когда они сами к тебе падают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 тыблок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повару Топу в деревню Туманного Водопада, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30232,'Взъерошить перышки','Ястребов в Доле все больше и больше. Это хорошо для наших мастеров-лучников, ведь мы хотим, чтобы наши воины стояли на стенах с приличными запасами стрел.$B$BЕсли не возражаешь, может, поможешь нам со сбором перьев?','Соберите 80 шелковых перьев.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взъерошить перышки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ястребов в Доле все больше и больше. Это хорошо для наших мастеров-лучников, ведь мы хотим, чтобы наши воины стояли на стенах с приличными запасами стрел.$B$BЕсли не возражаешь, может, поможешь нам со сбором перьев?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 80 шелковых перьев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30233,'Хрустозуб','Привет! У меня дилемма. Есть прекрасное имя для волка... погоди-ка... Хрустозуб! Здорово, правда? Только вот в лесу сейчас два страшных серых волка, их же будут путать.$B$BВ общем, убей одного, чтобы имя можно было использовать. Это же несложно, правда? После всех твоих подвигов, и так далее.$B$BНу так как, возьмешься? Ну давай, соглашайся!','Убейте Хрустозуба.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустозуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет! У меня дилемма. Есть прекрасное имя для волка... погоди-ка... Хрустозуб! Здорово, правда? Только вот в лесу сейчас два страшных серых волка, их же будут путать.$B$BВ общем, убей одного, чтобы имя можно было использовать. Это же несложно, правда? После всех твоих подвигов, и так далее.$B$BНу так как, возьмешься? Ну давай, соглашайся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хрустозуба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30234,'Злобнохап','Злобнохап! Вот это имя, прямо воплощение свирепости, правда? Я сам его придумал, ему очень подходит. Ведь я не один час пытался отобрать у него свой посох, ничего не вышло!$B$BНу ладно, несколько секунд пытался. С друзьями лучше быть полностью честным, хотя от этого истории становятся такими скучными.$B$BТак вот, не окажешь ли ты мне любезность забрать у этого злобного хапуги мой посох? Целиком, если можно!','Убейте Злобнохапа и добудьте посох Рена.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобнохап',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злобнохап! Вот это имя, прямо воплощение свирепости, правда? Я сам его придумал, ему очень подходит. Ведь я не один час пытался отобрать у него свой посох, ничего не вышло!$B$BНу ладно, несколько секунд пытался. С друзьями лучше быть полностью честным, хотя от этого истории становятся такими скучными.$B$BТак вот, не окажешь ли ты мне любезность забрать у этого злобного хапуги мой посох? Целиком, если можно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Злобнохапа и добудьте посох Рена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30235,'Склизкий тип','Склизень – очень могущественный и древний водяной дух, хотя по его поведению ни за что не скажешь.$B$BСегодня утром он чуть не убил нескольких местных жителей, взял и взорвал несколько бочонков с водой прямо в таверне.$B$BСклизень несокрушим, его нельзя убить, пока течет вода. Но ему стоит напомнить, что мы не будем терпеть его глупые и опасные шутки.$B$BТы можешь передать ему это от имени всей деревни?','Победите Склизня, духа Туманного водопада.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Склизкий тип',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Склизень – очень могущественный и древний водяной дух, хотя по его поведению ни за что не скажешь.$B$BСегодня утром он чуть не убил нескольких местных жителей, взял и взорвал несколько бочонков с водой прямо в таверне.$B$BСклизень несокрушим, его нельзя убить, пока течет вода. Но ему стоит напомнить, что мы не будем терпеть его глупые и опасные шутки.$B$BТы можешь передать ему это от имени всей деревни?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Склизня, духа Туманного водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30236,'Айта','Похоже, Айта снова подняла стадо в воздух и забросила его в реку. Мэр хочет напомнить ей, что мы не потерпим таких шуток.$B$BМожно тебя попросить дойти до горной гряды около нашей деревни и проучить Айту? Тебе не удастся убить ее, только изгнать на время, но это она запомнит надолго.','Победите Айту, духа Золотых ветров.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Айта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, Айта снова подняла стадо в воздух и забросила его в реку. Мэр хочет напомнить ей, что мы не потерпим таких шуток.$B$BМожно тебя попросить дойти до горной гряды около нашей деревни и проучить Айту? Тебе не удастся убить ее, только изгнать на время, но это она запомнит надолго.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Айту, духа Золотых ветров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30237,'Восставшие духи пандаренов','К востоку отсюда расположено кладбище Ту-Шэнь. Там духи древних могу бьются с духами наших предков-пандаренов, восставшими против их владычества. Духи не знают покоя с тех пор, как могу вернулись в наш дол.$B$BЕсли ты согласишься пойти на кладбище и напомнить духам могу об их былом поражении, возможно, духи наших предков обретут мир.','Убейте 8 древних духов могу.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восставшие духи пандаренов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К востоку отсюда расположено кладбище Ту-Шэнь. Там духи древних могу бьются с духами наших предков-пандаренов, восставшими против их владычества. Духи не знают покоя с тех пор, как могу вернулись в наш дол.$B$BЕсли ты согласишься пойти на кладбище и напомнить духам могу об их былом поражении, возможно, духи наших предков обретут мир.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 древних духов могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30238,'Упокоение','Духи наших предков навеки обречены сражаться в одной из величайших битв нашей истории на кладбище Ту-Шэнь, что к востоку отсюда.$B$BВыполни мою просьбу, |3-6($r), почти их могилы. Это напомнит им, что их дела не забыты, хотя прошло столько лет, и что они заслужили свой покой.','Почтите 6 могил пандаренов.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упокоение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи наших предков навеки обречены сражаться в одной из величайших битв нашей истории на кладбище Ту-Шэнь, что к востоку отсюда.$B$BВыполни мою просьбу, |3-6($r), почти их могилы. Это напомнит им, что их дела не забыты, хотя прошло столько лет, и что они заслужили свой покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Почтите 6 могил пандаренов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30239,'Лао-Фэ Поработитель','Вы слышите, как дух Лао-Фэ Поработителя выкрикивает угрозы. Голос доносится из пещеры на вершине погребального кургана Ту-Шэнь.$B$BПобедите его, это придаст сил духам пандаренов.','Убейте дух Лао-Фэ Поработителя.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лао-Фэ Поработитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы слышите, как дух Лао-Фэ Поработителя выкрикивает угрозы. Голос доносится из пещеры на вершине погребального кургана Ту-Шэнь.$B$BПобедите его, это придаст сил духам пандаренов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте дух Лао-Фэ Поработителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30240,'Круг выживания: огонь','Это одно из заданий, которые я даю своим воинам, чтобы они оставались сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись внутри круга 60 секунд и постарайся не погибнуть. Будь начеку.','Войдите в круг выживания и продержитесь внутри 60 секунд.','Опасность, царящая в круге, готовит воина к битве не на жизнь, а на смерть... к тому, что творится сейчас за стеной.','Вернитесь к Юми Золотистой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг выживания: огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это одно из заданий, которые я даю своим воинам, чтобы они оставались сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись внутри круга 60 секунд и постарайся не погибнуть. Будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в круг выживания и продержитесь внутри 60 секунд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Опасность, царящая в круге, готовит воина к битве не на жизнь, а на смерть... к тому, что творится сейчас за стеной.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юми Золотистой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30241,'Предупредить Каменный Плуг','Столько смертей. А будет еще больше, если то, что рассказал о богомолах посланник Хань – правда.$b$bМы должны помочь. Мы должны внести свой вклад в спасение жизней.$b$bОтправляйся в Каменный Плуг. Предупреди там всех о грядущей атаке богомолов.$b$bЯ присоединюсь к тебе с бойцами, каких только смогу собрать, как только предам тело Кора земле.','Богомолы с юга? Не к добру это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить Каменный Плуг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Столько смертей. А будет еще больше, если то, что рассказал о богомолах посланник Хань – правда.$b$bМы должны помочь. Мы должны внести свой вклад в спасение жизней.$b$bОтправляйся в Каменный Плуг. Предупреди там всех о грядущей атаке богомолов.$b$bЯ присоединюсь к тебе с бойцами, каких только смогу собрать, как только предам тело Кора земле.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Богомолы с юга? Не к добру это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30242,'Круг выживания: клинки','Это одно из заданий, которые я даю своим воинам в мирное время, чтобы они оставались сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись внутри круга 60 секунд и постарайся не погибнуть. Будь начеку.','Войдите в круг выживания и продержитесь внутри 60 секунд.','Вернитесь к Юми Золотистой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг выживания: клинки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это одно из заданий, которые я даю своим воинам в мирное время, чтобы они оставались сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись внутри круга 60 секунд и постарайся не погибнуть. Будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в круг выживания и продержитесь внутри 60 секунд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юми Золотистой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30243,'Отпор богомолам','Богомолы опять атакуют, у нас не хватает рук. Я надеюсь на твою помощь, так что приготовил для тебя самое интересное: кипящее масло!$B$BЗрелище страшное, но ничего зазорного в этом занятии нет.$B$BЭто довольно просто. Поднимаешься на стену, находишь пост с маслом и опрокидываешь ведро на богомола, который лезет на стену. Очень эффективное средство.','С помощью котла с кипящим маслом убейте 80 богомолов, атакующих Врата Заходящего Солнца.','Ты нанес огромный урон войскам богомолов. Думаю, дальше защитники справятся сами.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отпор богомолам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы опять атакуют, у нас не хватает рук. Я надеюсь на твою помощь, так что приготовил для тебя самое интересное: кипящее масло!$B$BЗрелище страшное, но ничего зазорного в этом занятии нет.$B$BЭто довольно просто. Поднимаешься на стену, находишь пост с маслом и опрокидываешь ведро на богомола, который лезет на стену. Очень эффективное средство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью котла с кипящим маслом убейте 80 богомолов, атакующих Врата Заходящего Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты нанес огромный урон войскам богомолов. Думаю, дальше защитники справятся сами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30244,'Вдоль Змеиного хребта','Богомолы пробрались на стену! Защитникам бастионов нужно подкрепление.','Убейте 10 богомолов крик\'тик у Врат Заходящего Солнца.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вдоль Змеиного хребта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы пробрались на стену! Защитникам бастионов нужно подкрепление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 богомолов крик\'тик у Врат Заходящего Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30245,'Пропавшие разведчики','Мы отправили разведчиков на север, к Пяти Сестрам, чтобы выяснить, кто из могу командует армией. Почти никто не вернулся.$B$BХотелось бы верить, что остальные не устояли перед кружкой крепкого эля или чьей-нибудь красотой, но ведь они могли попасть в беду.$B$BМожешь узнать, что там с нашими разведчиками? И выясни, удалось ли им что-нибудь разузнать про полководца.','Восстановить 3 доклада разведчиков Шадо-Пан.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие разведчики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили разведчиков на север, к Пяти Сестрам, чтобы выяснить, кто из могу командует армией. Почти никто не вернулся.$B$BХотелось бы верить, что остальные не устояли перед кружкой крепкого эля или чьей-нибудь красотой, но ведь они могли попасть в беду.$B$BМожешь узнать, что там с нашими разведчиками? И выясни, удалось ли им что-нибудь разузнать про полководца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Восстановить 3 доклада разведчиков Шадо-Пан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30246,'Враг на стене','Сколько-то богомолов взобралось на стену. Если их достаточно много, есть риск, что они справятся с воинами, которые там стоят.$B$BПоднимись наверх, помоги очистить стену от всех пришельцев.','Убейте 10 богомолов крик\'тик над Вратами Заходящего Солнца.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг на стене',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сколько-то богомолов взобралось на стену. Если их достаточно много, есть риск, что они справятся с воинами, которые там стоят.$B$BПоднимись наверх, помоги очистить стену от всех пришельцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 богомолов крик\'тик над Вратами Заходящего Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30247,'Курсы по катанию: Вечноцветущий дол','Иди по флагам. Отмечайся на контрольных точках. Сделай круг. Вернись ко мне раньше, чем выйдет время.$b$bКак будешь $gготов:готова; – обращайся ко мне.','Закончите курсы по катанию в Вечноцветущем доле.','Вернитесь к Келари Легкий Шаг в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курсы по катанию: Вечноцветущий дол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иди по флагам. Отмечайся на контрольных точках. Сделай круг. Вернись ко мне раньше, чем выйдет время.$b$bКак будешь $gготов:готова; – обращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закончите курсы по катанию в Вечноцветущем доле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келари Легкий Шаг в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30248,'Мясник','Разведчики сообщают, что низвергнутый империон Шао-Тень сейчас на северном краю стены.$B$BАньцзи Осенний Свет недвусмысленно дала понять, что твоя задача – найти его и убить.','Убейте Бай-Цзиня Мясника.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики сообщают, что низвергнутый империон Шао-Тень сейчас на северном краю стены.$B$BАньцзи Осенний Свет недвусмысленно дала понять, что твоя задача – найти его и убить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бай-Цзиня Мясника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30249,'Во время заката','Гигантская тварь пролезла под воротами и попала во двор! Там нужна твоя помощь.','Уничтожьте Кри\'чона Трупогрыза.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во время заката',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гигантская тварь пролезла под воротами и попала во двор! Там нужна твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Кри\'чона Трупогрыза.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30250,'Круг выживания: гром','Это одно из заданий, которое я даю своим воинам в мирное время, чтобы они были сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись в кругу 90 секунд так, чтобы не упасть и не погибнуть. Не падай.','Войдите в круг выживания и продержитесь внутри 90 секунд.','Вернитесь к Левену Рассветному Клинку в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг выживания: гром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это одно из заданий, которое я даю своим воинам в мирное время, чтобы они были сильными и быстрыми. Посмотрим, как справишься ты.$B$BПродержись в кругу 90 секунд так, чтобы не упасть и не погибнуть. Не падай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в круг выживания и продержитесь внутри 90 секунд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30251,'Вираксис, повелитель роя крик\'тиков','Огромный богомол перебрался через стену. Похоже, наши защитники не справятся с этим громилой без тебя.','Убейте Вираксиса, повелителя роя крик\'тиков.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вираксис, повелитель роя крик\'тиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромный богомол перебрался через стену. Похоже, наши защитники не справятся с этим громилой без тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Вираксиса, повелителя роя крик\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30252,'Рука помощи','Я все утро толкаю эти камни, бью по ним молотом, но все без толку.$B$BИх с места не сдвинешь!$b$b"Со временем станет легче," – говорил дедушка. – "Заниматься сельским хозяйством – это все равно что дышать." Для него-то может быть и да, но не для меня!$b$bКак же я преуспею в фермерстве, если даже не могу подготовить почву?$B$BЭй, погоди минуту! Ты, похоже, $gпарень:девушка; $gсильный:сильная;.$b$bНе поможешь мне? Чтобы я хотя бы перевел дух.','Уберите 8 неподвижных валунов.','Что? Ты убрал все камни? Замечательные новости!$B$BМожет, хоть теперь я смогу что-нибудь выращивать на своей ферме!','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рука помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все утро толкаю эти камни, бью по ним молотом, но все без толку.$B$BИх с места не сдвинешь!$b$b"Со временем станет легче," – говорил дедушка. – "Заниматься сельским хозяйством – это все равно что дышать." Для него-то может быть и да, но не для меня!$b$bКак же я преуспею в фермерстве, если даже не могу подготовить почву?$B$BЭй, погоди минуту! Ты, похоже, $gпарень:девушка; $gсильный:сильная;.$b$bНе поможешь мне? Чтобы я хотя бы перевел дух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уберите 8 неподвижных валунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Ты убрал все камни? Замечательные новости!$B$BМожет, хоть теперь я смогу что-нибудь выращивать на своей ферме!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30253,'Фамильная ферма','$gС-Слышал:С-Слышала;, что было сказано?$B$BПохоже, они хотят, чтобы я убрался отсюда. Считают, что я... им не ровня.$B$BНу да, у меня никогда не было фермы, но сажать семена я умею и тащить из земли репу – тоже.$B$B<Фермер Юн оживляется.>$B$BЗнаешь, что? Я докажу им, что могу стать видным фермером!$B$BМоя ферма станет лучшей в Долине!$B$BПравда, одному пандарену это не под силу. Ты мне поможешь?','Помогите фермеру Юну.','Поговорите с фермером Юном на [ферме], что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фамильная ферма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gС-Слышал:С-Слышала;, что было сказано?$B$BПохоже, они хотят, чтобы я убрался отсюда. Считают, что я... им не ровня.$B$BНу да, у меня никогда не было фермы, но сажать семена я умею и тащить из земли репу – тоже.$B$B<Фермер Юн оживляется.>$B$BЗнаешь, что? Я докажу им, что могу стать видным фермером!$B$BМоя ферма станет лучшей в Долине!$B$BПравда, одному пандарену это не под силу. Ты мне поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите фермеру Юну.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с фермером Юном на [ферме], что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30254,'Растениеводство II: грядки и семена','Ну вот, семена у нас есть, пора их сажать.$B$BПрежде всего мы должны подготовить почву! Нужно вскопать землю, чтобы получилась грядка для наших ростков.$B$BВскопай два участка вон там, затем посади семена.','Неплохо!$B$BВидишь, семена сразу дали ростки! Вот почему эта долина – просто рай для огородника: овощи здесь растут как сумасшедшие!$B$BПравда, работа еще не закончена.','Вернитесь к фермеру Юну на Ферму Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство II: грядки и семена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, семена у нас есть, пора их сажать.$B$BПрежде всего мы должны подготовить почву! Нужно вскопать землю, чтобы получилась грядка для наших ростков.$B$BВскопай два участка вон там, затем посади семена.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо!$B$BВидишь, семена сразу дали ростки! Вот почему эта долина – просто рай для огородника: овощи здесь растут как сумасшедшие!$B$BПравда, работа еще не закончена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30255,'Растениеводство III: уход за овощами','Мой дедушка говорил: "Юни, капуста – она как женщина: если про нее забыть, сгниет. А если ее холить и лелеять, она станет большой и толстой; тогда ее можно перевязать ленточкой, отвезти на рынок и показать друзьям..." Ну да, он жил в другое время, ясно?$B$BСмысл вот в чем: капуста нуждается в уходе! Сегодня она немного пересохла, так полей ее.$B$BВот старая лейка – еще от дедушки осталась. Если понадобится, она всегда будет рядом с полем.','Отлично! Теперь капуста выглядит замечательно!$B$BСегодня ее нужно было полить, а что ей завтра понадобится – неизвестно. Внимательно следи за тем, что растет у тебя на грядках, и тщательно ухаживай за растениями.$B$BДедушка снабдил меня кучей разных советов, так что будешь в чем сомневаться – обращайся!$B$BНо только если у тебя вопрос по крестьянской части...','Вернитесь к фермеру Юну на Ферму Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство III: уход за овощами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой дедушка говорил: "Юни, капуста – она как женщина: если про нее забыть, сгниет. А если ее холить и лелеять, она станет большой и толстой; тогда ее можно перевязать ленточкой, отвезти на рынок и показать друзьям..." Ну да, он жил в другое время, ясно?$B$BСмысл вот в чем: капуста нуждается в уходе! Сегодня она немного пересохла, так полей ее.$B$BВот старая лейка – еще от дедушки осталась. Если понадобится, она всегда будет рядом с полем.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь капуста выглядит замечательно!$B$BСегодня ее нужно было полить, а что ей завтра понадобится – неизвестно. Внимательно следи за тем, что растет у тебя на грядках, и тщательно ухаживай за растениями.$B$BДедушка снабдил меня кучей разных советов, так что будешь в чем сомневаться – обращайся!$B$BНо только если у тебя вопрос по крестьянской части...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30256,'Растениеводство IV: сбор урожая','Наконец-то наша работа принесла плоды! Как правило, нужно выждать день, прежде чем собирать урожай.$B$BНо, к счастью, Зеленое Поле дал нам семена такого сорта капусты, который растет ОЧЕНЬ БЫСТРО. За этот урожай много денег не выручишь, зато ты сможешь быстро ознакомиться со всеми сторонами сельского хозяйства.$B$BКапусту уже можно собирать. И эта честь, конечно же, предоставляется тебе!','Огородничество – дело несложное!$B$BВскопай почву, посади семена, ликвидируй все угрозы растениям – и жди урожая!$B$BСегодня все было просто, но не расслабляйся; дедушка рассказывал кучу жутких историй о том, что творилось на Ферме Солнечной Песни.$B$BФермерство – это не только гигантская репа и прочие корнеплоды!','Смотри, какая... э-э... как это тут говорят? Ах да – "красотисча"!$B$BСмотри, какая красотисча!$B$BКажется, я потихоньку становлюсь настоящим крестьянином!','Вернитесь к фермеру Юну на Ферму Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство IV: сбор урожая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то наша работа принесла плоды! Как правило, нужно выждать день, прежде чем собирать урожай.$B$BНо, к счастью, Зеленое Поле дал нам семена такого сорта капусты, который растет ОЧЕНЬ БЫСТРО. За этот урожай много денег не выручишь, зато ты сможешь быстро ознакомиться со всеми сторонами сельского хозяйства.$B$BКапусту уже можно собирать. И эта честь, конечно же, предоставляется тебе!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огородничество – дело несложное!$B$BВскопай почву, посади семена, ликвидируй все угрозы растениям – и жди урожая!$B$BСегодня все было просто, но не расслабляйся; дедушка рассказывал кучу жутких историй о том, что творилось на Ферме Солнечной Песни.$B$BФермерство – это не только гигантская репа и прочие корнеплоды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотри, какая... э-э... как это тут говорят? Ах да – "красотисча"!$B$BСмотри, какая красотисча!$B$BКажется, я потихоньку становлюсь настоящим крестьянином!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30257,'Растениеводство V: рынок Полугорья','Что ж, $gдруг:подруга;, все это было просто для тренировки!$b$b$gГотов:Готова; к настоящей работе?$b$bДжина Грязный Коготь работает на рынке Полугорья, который находится через дорогу, к югу отсюда.$b$bЯ слышал, что она собиралась купить кое-какие овощи.$b$bПочему бы тебе не обойти ферму и не посмотреть, нет ли тут каких интересных вещиц?$b$bМожет быть, тебе удастся найти что-нибудь, что мы сможем подарить нашей новой соседке!','Внимательно осмотрите темную землю под домом фермера Юна, а затем подарите подарок Джине Грязный Коготь на рынке Полугорья.','Ой, болотная лилия!$B$BМой любимый цветок, между прочим. Ты начинаешь мне нравиться.!$B$BСпасибо.','По-моему, ты в этих краях совсем недавно. Как тебя зовут?','Поговорите с Джиной Грязный Коготь на рынке Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство V: рынок Полугорья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $gдруг:подруга;, все это было просто для тренировки!$b$b$gГотов:Готова; к настоящей работе?$b$bДжина Грязный Коготь работает на рынке Полугорья, который находится через дорогу, к югу отсюда.$b$bЯ слышал, что она собиралась купить кое-какие овощи.$b$bПочему бы тебе не обойти ферму и не посмотреть, нет ли тут каких интересных вещиц?$b$bМожет быть, тебе удастся найти что-нибудь, что мы сможем подарить нашей новой соседке!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Внимательно осмотрите темную землю под домом фермера Юна, а затем подарите подарок Джине Грязный Коготь на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, болотная лилия!$B$BМой любимый цветок, между прочим. Ты начинаешь мне нравиться.!$B$BСпасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','По-моему, ты в этих краях совсем недавно. Как тебя зовут?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джиной Грязный Коготь на рынке Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30258,'Голос Мун-Муна I: проблема с хозенами','Слушай, $n, я тут все думал, как бы заручиться поддержкой Союза земледельцев.$B$BПонимаешь, каждый год Союз принимает новых членов – в голосовании участвует совет, состоящий из пятерых крестьян.$B$BЯ уже заручился поддержкой Джины, но нужно получить и остальные четыре голоса.$B$BПрежде всего нужно познакомиться с Мун-Муном. Он вместе с господином Грязным Когтем работает на ферме Грязного Когтя, что к северо-западу отсюда.','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Мун-Муна I: проблема с хозенами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n, я тут все думал, как бы заручиться поддержкой Союза земледельцев.$B$BПонимаешь, каждый год Союз принимает новых членов – в голосовании участвует совет, состоящий из пятерых крестьян.$B$BЯ уже заручился поддержкой Джины, но нужно получить и остальные четыре голоса.$B$BПрежде всего нужно познакомиться с Мун-Муном. Он вместе с господином Грязным Когтем работает на ферме Грязного Когтя, что к северо-западу отсюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30259,'Голос Мун-Муна II: огородные вредители','Гну-сини вернулись!$B$BОни погрызают морковку господина Грязного Когтя. Уничтожают урожай. А кто за это заплатит? Мун-Мун, вот кто.$B$BТвоя собирай пожеванный морковь, пока Грязный Коготь не видеть. Она на полях к юго-западу отсюда, и под землей тоже, в норах гну-синей.$b$bИначе Мун-Мун неприятностей много-много собирай.$B$BТвоя сделай это для меня?','Соберите 10 частично пережеванных морковок.','Что значит "их погрызли не гну-сини"? Зубы маленькие? Что? А кто, если не они?','Не вижу никакой обгрызенной моркови. И ты не видишь обгрызенной моркови. Господин Грязный Коготь ничего не узнает, хорошо?','Вернитесь к Мун-Муну в дом Хаоханя Грязного Когтя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Мун-Муна II: огородные вредители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гну-сини вернулись!$B$BОни погрызают морковку господина Грязного Когтя. Уничтожают урожай. А кто за это заплатит? Мун-Мун, вот кто.$B$BТвоя собирай пожеванный морковь, пока Грязный Коготь не видеть. Она на полях к юго-западу отсюда, и под землей тоже, в норах гну-синей.$b$bИначе Мун-Мун неприятностей много-много собирай.$B$BТвоя сделай это для меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 частично пережеванных морковок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что значит "их погрызли не гну-сини"? Зубы маленькие? Что? А кто, если не они?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не вижу никакой обгрызенной моркови. И ты не видишь обгрызенной моркови. Господин Грязный Коготь ничего не узнает, хорошо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мун-Муну в дом Хаоханя Грязного Когтя, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30260,'Фермерство I: сорняки','Слушай, $n, я тут подумал – а не расширить ли мне ферму?$B$BВидишь вон тот участок, заросший сорняками? Если мы от них избавимся, то сможем распахать и эту землю.$B$BГоворят, о борьбе с сорняками много знает крестьянин по имени Гай Лань.$B$BЕго ферма находится к западу отсюда. Поговори с ним и узнай, не хочет ли он нам помочь.','Ах да, фермер Юн. Кажется, мы с ним уже виделись.$B$BОн, похоже, парень неплохой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермерство I: сорняки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n, я тут подумал – а не расширить ли мне ферму?$B$BВидишь вон тот участок, заросший сорняками? Если мы от них избавимся, то сможем распахать и эту землю.$B$BГоворят, о борьбе с сорняками много знает крестьянин по имени Гай Лань.$B$BЕго ферма находится к западу отсюда. Поговори с ним и узнай, не хочет ли он нам помочь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, фермер Юн. Кажется, мы с ним уже виделись.$B$BОн, похоже, парень неплохой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30261,'Курсы по катанию: Змеиный Хребет','Доберись до низа стены как можно быстрее.$B$BКак будешь $gготов:готова; – обращайся ко мне.','Закончите курсы по катанию на Змеином Хребте.','Вряд ли те, кто строил стену, предполагали, что на ней будут вытворять такое.','Вернитесь к Келари Легкой Поступи в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курсы по катанию: Змеиный Хребет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доберись до низа стены как можно быстрее.$B$BКак будешь $gготов:готова; – обращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закончите курсы по катанию на Змеином Хребте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вряд ли те, кто строил стену, предполагали, что на ней будут вытворять такое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келари Легкой Поступи в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30262,'NOT USED') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','NOT USED',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30263,'Зачистка леса','Шао-Тень пустились наутек. После поражения многие из них отошли к опушке Зимней Ветви. Нужно закрепить нашу победу.$B$BЗачистим лес к северо-западу отсюда. Нельзя успокаиваться, пока в долине остается хоть один могу.','Убейте 6 могу Шао-Тень на Опушке Зимней Ветви.','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шао-Тень пустились наутек. После поражения многие из них отошли к опушке Зимней Ветви. Нужно закрепить нашу победу.$B$BЗачистим лес к северо-западу отсюда. Нельзя успокаиваться, пока в долине остается хоть один могу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 могу Шао-Тень на Опушке Зимней Ветви.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30264,'Враг у ворот','Богомолы атакуют стену! Я подготовил несколько летающих змеев: с их помощью мы сможем нанести ущерб силам противника в воздухе.$B$BВозьмешься управлять одним из них?','Используйте небесного змея Шадо-Пан, чтобы убить 60 крик\'тиков, а также уничтожить 3 боевые колесницы крик\'тиков и 3 катапульты крик\'тиков.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг у ворот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы атакуют стену! Я подготовил несколько летающих змеев: с их помощью мы сможем нанести ущерб силам противника в воздухе.$B$BВозьмешься управлять одним из них?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте небесного змея Шадо-Пан, чтобы убить 60 крик\'тиков, а также уничтожить 3 боевые колесницы крик\'тиков и 3 катапульты крик\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30265,'Искры в глазах','Я смотрел вниз, вглубь озера, размышляя о жизни, любви и прочих прекрасных вещах... как вдруг я понял, что блики на воде – это не отражение моей сияющей личности: там, в воде, на самом деле что-то сверкает! Конечно же, что-то ценное.$B$BНе $gмог:могла; бы ты спуститься к воде и узнать, что это так загадочно блестит? Ну пожа-а-алуйста!','Достаньте из воды 8 сверкающих рубинов.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искры в глазах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я смотрел вниз, вглубь озера, размышляя о жизни, любви и прочих прекрасных вещах... как вдруг я понял, что блики на воде – это не отражение моей сияющей личности: там, в воде, на самом деле что-то сверкает! Конечно же, что-то ценное.$B$BНе $gмог:могла; бы ты спуститься к воде и узнать, что это так загадочно блестит? Ну пожа-а-алуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте из воды 8 сверкающих рубинов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30266,'Кровавые небеса','Наши пушки установлены на башнях по бокам от главных ворот. С их помощью можно легко очистить небо от богомолов, пытающихся перелететь через стену.$B$BПокажи, на что ты $gспособен:способна;, $n.','Убейте 30 крик\'тиков-роевиков, используя турель Заходящего Солнца.','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавые небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши пушки установлены на башнях по бокам от главных ворот. С их помощью можно легко очистить небо от богомолов, пытающихся перелететь через стену.$B$BПокажи, на что ты $gспособен:способна;, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 крик\'тиков-роевиков, используя турель Заходящего Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30267,'Беда рыбака','Я обожаю рыбную ловлю. И обожал бы еще больше, но вот беда – пропали мои приманки и наживки. Точнее, они были выброшены после небольшого... недоразумения, которое произошло у нас с женой.$b$b<Луговой рыболов Лан вздыхает.>$b$bНеужели семейные проблемы помешают мне рыбачить? Нет! Ведь все, что мне нужно, – это немного насекомых и перьев, а здесь на лугу этого добра полно!$b$bНу что, выручишь рыбака?','Наберите 18 луговых светлячков и 5 тонких алых перьев.','Ну хоть кто-то меня понял! Рыбалка – это же лучшее, что есть в жизни, так?$B$BМожет, покинуть Новую Циферу и уехать на юг к рыболовам... Нет, конечно, семью я не брошу...$B$BНо все-таки... Может пандарен хоть немного помечтать?','Отказываться от рыбной ловли я не собираюсь. Рыбалка – это моя жизнь!','Вернитесь к луговому рыбаку Лану в Новую Циферу, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда рыбака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обожаю рыбную ловлю. И обожал бы еще больше, но вот беда – пропали мои приманки и наживки. Точнее, они были выброшены после небольшого... недоразумения, которое произошло у нас с женой.$b$b<Луговой рыболов Лан вздыхает.>$b$bНеужели семейные проблемы помешают мне рыбачить? Нет! Ведь все, что мне нужно, – это немного насекомых и перьев, а здесь на лугу этого добра полно!$b$bНу что, выручишь рыбака?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите 18 луговых светлячков и 5 тонких алых перьев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну хоть кто-то меня понял! Рыбалка – это же лучшее, что есть в жизни, так?$B$BМожет, покинуть Новую Циферу и уехать на юг к рыболовам... Нет, конечно, семью я не брошу...$B$BНо все-таки... Может пандарен хоть немного помечтать?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отказываться от рыбной ловли я не собираюсь. Рыбалка – это моя жизнь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к луговому рыбаку Лану в Новую Циферу, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30268,'Чернопотница','Взгляни хорошенько. Ближайшая река просто кишит этими змеями. Их яд вызывает болезнь, которую местные жители называют чернопотницей.$b$bНесколько беженцев из храма были укушены, и у них уже проявились все признаки: тошнота, рвота, сильная потливость – тело отторгает все жидкости, что приводит к обезвоживанию и может стать причиной смерти.$b$bМы вводим противоядие так быстро, как только можем, но нам нужно больше ядовитых желез. Не нужно их выдирать – просто принеси целые головы.','Соберите 6 голов темночешуйчатых жаленей, которые водятся в реке Красаранг.','Вернитесь к Андуину Ринну в Укрытие Журавлиного Крыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чернопотница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни хорошенько. Ближайшая река просто кишит этими змеями. Их яд вызывает болезнь, которую местные жители называют чернопотницей.$b$bНесколько беженцев из храма были укушены, и у них уже проявились все признаки: тошнота, рвота, сильная потливость – тело отторгает все жидкости, что приводит к обезвоживанию и может стать причиной смерти.$b$bМы вводим противоядие так быстро, как только можем, но нам нужно больше ядовитых желез. Не нужно их выдирать – просто принеси целые головы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 голов темночешуйчатых жаленей, которые водятся в реке Красаранг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андуину Ринну в Укрытие Журавлиного Крыла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30269,'Опасный проход','У нас в храме говорят: "Не дерись с тигром, если на спине у тебя хозен".$B$BМы еще расправимся с ша, но сперва надо устранить более насущную... проблему.$B$B<Коро с силой бьет извивающегося саурока о камень.>$B$BГруппы беженцев из храма направляются в лагерь на севере, а сауроки устроили на них засаду. Помоги мне довести эту группу до лагеря, и там мы обдумаем наш следующий ход.','Поговорите с Коро Странником Туманов в Укрытии Журавлиного Крыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасный проход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас в храме говорят: "Не дерись с тигром, если на спине у тебя хозен".$B$BМы еще расправимся с ша, но сперва надо устранить более насущную... проблему.$B$B<Коро с силой бьет извивающегося саурока о камень.>$B$BГруппы беженцев из храма направляются в лагерь на севере, а сауроки устроили на них засаду. Помоги мне довести эту группу до лагеря, и там мы обдумаем наш следующий ход.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Коро Странником Туманов в Укрытии Журавлиного Крыла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30270,'Ослепление Речных Клинков','"Сокол в клобуке добычу не поймает".$b$bЭто одна из первых мантр, которым мы учим в храме юных монахов. Она означает, что даже такого опасного и быстрого врага, как сокол, можно обезвредить, лишив его органов чувств.$b$bСауроки выслали повсюду разведчиков, глаза своих разбойничьих отрядов.$b$bПора нам ослепить сауроков, как ты думаешь?','Вернитесь к Коро Страннику Туманов в Укрытие Журавлиного Крыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепление Речных Клинков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Сокол в клобуке добычу не поймает".$b$bЭто одна из первых мантр, которым мы учим в храме юных монахов. Она означает, что даже такого опасного и быстрого врага, как сокол, можно обезвредить, лишив его органов чувств.$b$bСауроки выслали повсюду разведчиков, глаза своих разбойничьих отрядов.$b$bПора нам ослепить сауроков, как ты думаешь?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коро Страннику Туманов в Укрытие Журавлиного Крыла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30271,'Шок и трепет ша','Ша обладают таинственной способностью пробуждать в своих жертвах мощные, часто прямо-таки переполняющие их чувства.$b$bКогда мы бежали из храма, старшие члены ордена Журавлиного Крыла остались, чтобы прикрыть наш отход. Без сомнения, они испытали тяжелое эмоциональное потрясение, и я боюсь, что не все из них достаточно сильны, чтобы не впасть в отчаяние.$b$b$n, мы должны показать им, что надежда еще есть! Покажи им, что отчаяние можно победить!','Убейте ша рядом с десятью отчаявшимися монахами или послушниками, чтобы их вдохновить.','Поговорите с Андуином Ринном в Храме Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шок и трепет ша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ша обладают таинственной способностью пробуждать в своих жертвах мощные, часто прямо-таки переполняющие их чувства.$b$bКогда мы бежали из храма, старшие члены ордена Журавлиного Крыла остались, чтобы прикрыть наш отход. Без сомнения, они испытали тяжелое эмоциональное потрясение, и я боюсь, что не все из них достаточно сильны, чтобы не впасть в отчаяние.$b$b$n, мы должны показать им, что надежда еще есть! Покажи им, что отчаяние можно победить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ша рядом с десятью отчаявшимися монахами или послушниками, чтобы их вдохновить.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Храме Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30272,'Удары по дождю','Помнишь, я говорил про "удары по дождю"?.. Иногда приходится так и поступать.$b$b"Надежда – что солнце за облаками, она греет сердце, но невидима глазу".$b$bШа все изливаются из храма, и похоже, что конца им не будет. Но чтобы увидеть, что сокрыто за пеленой отчаяния, ее надо прорвать.$b$bЕсли тебе повезет, ты найдешь за облаками солнце...','Поговорите с Андуином Ринном в Храме Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удары по дождю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помнишь, я говорил про "удары по дождю"?.. Иногда приходится так и поступать.$b$b"Надежда – что солнце за облаками, она греет сердце, но невидима глазу".$b$bШа все изливаются из храма, и похоже, что конца им не будет. Но чтобы увидеть, что сокрыто за пеленой отчаяния, ее надо прорвать.$b$bЕсли тебе повезет, ты найдешь за облаками солнце...',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Храме Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30273,'Дом Красного Журавля','"Сломлено тело, что без надежды живет – червь отчаяния его изнутри грызет".$b$bЭто – последняя мудрость, которой поделился со мной Красный Журавль всего за несколько часов до нападения ша. Теперь я понимаю смысл этой фразы...$b$b$n, ша атаковали нас, вырвавшись из подвала храма...$b$bВсе его учения... сам Путь Журавля – они готовили нас к встрече с Ша Отчаяния.$b$bКрасный Журавль ждал этой схватки сотни лет!','Поговорите с Чи-Цзи, Красным Журавлем у Храма Красного Журавля.','Ша Отчаяния') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дом Красного Журавля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Сломлено тело, что без надежды живет – червь отчаяния его изнутри грызет".$b$bЭто – последняя мудрость, которой поделился со мной Красный Журавль всего за несколько часов до нападения ша. Теперь я понимаю смысл этой фразы...$b$b$n, ша атаковали нас, вырвавшись из подвала храма...$b$bВсе его учения... сам Путь Журавля – они готовили нас к встрече с Ша Отчаяния.$b$bКрасный Журавль ждал этой схватки сотни лет!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чи-Цзи, Красным Журавлем у Храма Красного Журавля.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ша Отчаяния',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30274,'Волшебная темница','$gВоин:Воительница; Альянса? Здесь? Хвала Элуне.$b$bМой отряд столкнулся с загвоздкой. Мы открыли портал на эту землю с помощью древних свитков, которые существовали еще до правления Азшары.$b$bК несчастью, координаты на них оказались зачарованы и портал, который должен был открыть путь к месту назначения, перенес нас в эту темницу.$b$bМы здесь уже несколько дней, и она медленно высасывает нашу энергию.$b$bТы можешь найти тут рядом засовы, которые запирают темницу, и открыть их?','Найдите и откройте 3 засова темницы.','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.','Его голос эхом отдается в вашей голове.','Хранитель знаний Ваэлдрин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебная темница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gВоин:Воительница; Альянса? Здесь? Хвала Элуне.$b$bМой отряд столкнулся с загвоздкой. Мы открыли портал на эту землю с помощью древних свитков, которые существовали еще до правления Азшары.$b$bК несчастью, координаты на них оказались зачарованы и портал, который должен был открыть путь к месту назначения, перенес нас в эту темницу.$b$bМы здесь уже несколько дней, и она медленно высасывает нашу энергию.$b$bТы можешь найти тут рядом засовы, которые запирают темницу, и открыть их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и откройте 3 засова темницы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его голос эхом отдается в вашей голове.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель знаний Ваэлдрин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30275,'История с кроколиском','С чего вдруг этот кроколиск так вымахал?$b$bНу да, говорят, что старые кроколиски вырастают до огромных размеров... Но ведь этой самке всего несколько десятков лет от роду!$b$bВозможно, кто-то в Новой Цифере прольет свет на эту тайну.','Это хвост кроколиска? Забавно. К нам они нечасто заплывают.$B$BВидел, какие огромные овощи и фрукты выращивают наши фермеры? Все дело в местной воде – в ней что-то есть, поэтому и кроколиски такие здоровенные.$B$BЧто это, мы точно не знаем, но на судьбу не жалуемся. Гигантские овощи – это счастье. А несколько гигантских кроколисков, которых сюда иногда заносит, это так, побочный эффект.','Что это у тебя?','Поговорите с Янем в Новой Цифере, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История с кроколиском',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С чего вдруг этот кроколиск так вымахал?$b$bНу да, говорят, что старые кроколиски вырастают до огромных размеров... Но ведь этой самке всего несколько десятков лет от роду!$b$bВозможно, кто-то в Новой Цифере прольет свет на эту тайну.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хвост кроколиска? Забавно. К нам они нечасто заплывают.$B$BВидел, какие огромные овощи и фрукты выращивают наши фермеры? Все дело в местной воде – в ней что-то есть, поэтому и кроколиски такие здоровенные.$B$BЧто это, мы точно не знаем, но на судьбу не жалуемся. Гигантские овощи – это счастье. А несколько гигантских кроколисков, которых сюда иногда заносит, это так, побочный эффект.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Янем в Новой Цифере, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30277,'Опасный чертог','В сокровищнице Го-Лай за Залом Статуй была найдена древняя реликвия могу. Мы несколько раз пытались забрать ее, но ничего не добились.$b$bНельзя, чтобы она попала в руки Шао-Тень. Мне нужен кто-то, кто сможет раздобыть эту реликвию, и притом побыстрее.$b$bСправишься?','Заберите древнюю реликвию Го-Лай.','Когда все другие меня подводят, ты меня выручаешь. Вот почему ты мне так нравишься.$B$BСпасибо, Номах.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасный чертог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сокровищнице Го-Лай за Залом Статуй была найдена древняя реликвия могу. Мы несколько раз пытались забрать ее, но ничего не добились.$b$bНельзя, чтобы она попала в руки Шао-Тень. Мне нужен кто-то, кто сможет раздобыть эту реликвию, и притом побыстрее.$b$bСправишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите древнюю реликвию Го-Лай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда все другие меня подводят, ты меня выручаешь. Вот почему ты мне так нравишься.$B$BСпасибо, Номах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
