INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30279,'REUSE FOR PROGRESSION') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE FOR PROGRESSION',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30280,'Гром из глубин','Из Залов Го-Лай раздается чей-то рев. Могу пробудили какое-то древнее чудовище, и скоро обязательно попробуют напустить его на мой отряд.$b$bПроберись в Зал Змеи и убей там это чудовище, пока его не натравили на нас. Такое важное и опасное задание я не могу доверить никому, кроме тебя.','Убейте Милау.','Ты сделал то, что даже мне вряд ли бы удалось. Восхищаюсь твоей доблестью.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гром из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из Залов Го-Лай раздается чей-то рев. Могу пробудили какое-то древнее чудовище, и скоро обязательно попробуют напустить его на мой отряд.$b$bПроберись в Зал Змеи и убей там это чудовище, пока его не натравили на нас. Такое важное и опасное задание я не могу доверить никому, кроме тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Милау.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделал то, что даже мне вряд ли бы удалось. Восхищаюсь твоей доблестью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30281,'Бесшумно, но доходчиво','<Он наклоняется и что-то рисует. Вы сразу понимаете – он изображает могу. Он указывает в сторону озера на западе, проводит по своему горлу тупой стороной кинжала и смотрит на вас с надеждой. Видимо, он хочет, чтобы вы убили могу на Озере Белых Лепестков.>','Убейте 6 могу Шао-Тень на Озере Белых Лепестков.','Вернитесь к Хэ Легкой Ноге в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесшумно, но доходчиво',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он наклоняется и что-то рисует. Вы сразу понимаете – он изображает могу. Он указывает в сторону озера на западе, проводит по своему горлу тупой стороной кинжала и смотрит на вас с надеждой. Видимо, он хочет, чтобы вы убили могу на Озере Белых Лепестков.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 могу Шао-Тень на Озере Белых Лепестков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хэ Легкой Ноге в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30282,'Очищающий огонь','Могу подняли свои грязные знамена вокруг озера на западе. Тем самым они заявили свои права на это озеро. Возьми этот факел и расскажи им, что мы думаем на этот счет.','Сожгите 10 знамен Шао-Тень.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищающий огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу подняли свои грязные знамена вокруг озера на западе. Тем самым они заявили свои права на это озеро. Возьми этот факел и расскажи им, что мы думаем на этот счет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 10 знамен Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30283,'Повальное увлечение','Иногда мне жаль этих могу... Вдруг, ловля душ других рас для них – это только способ преодолеть свои проблемы... Ну, знаешь, семья, дети, быт... Может, нам стоит более терпимо относиться к их выходкам?$B$BИли мы можем просто повалить все их статуи для ритуалов ловли душ в озеро. Лично мне такой подход нравится больше.','Уничтожьте ритуальные статуи Шао-Тень.','Вернитесь к Жэню Огненному Языку в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повальное увлечение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда мне жаль этих могу... Вдруг, ловля душ других рас для них – это только способ преодолеть свои проблемы... Ну, знаешь, семья, дети, быт... Может, нам стоит более терпимо относиться к их выходкам?$B$BИли мы можем просто повалить все их статуи для ритуалов ловли душ в озеро. Лично мне такой подход нравится больше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте ритуальные статуи Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30284,'Тысяча острых зубов','Вода сегодня вспенилась, предвещая опасность! Косяк какой-то плотоядной рыбной гадости поселился в нашем озере. Это ужасно! Это случилось как раз, когда я собирался раздеться догола и, как обычно, освежиться в такой денек!$B$BУ тебя, кажется, большой опыт в убийстве всяких противных тварей? Не $gмог:могла; бы ты применить свои навыки и решить эту проблему? Во имя всех пандаренов, желающих искупаться!$B$BЭто было бы очень благородно, учитывая, что я один из них.','Убейте 9 стайных острозубов.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тысяча острых зубов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вода сегодня вспенилась, предвещая опасность! Косяк какой-то плотоядной рыбной гадости поселился в нашем озере. Это ужасно! Это случилось как раз, когда я собирался раздеться догола и, как обычно, освежиться в такой денек!$B$BУ тебя, кажется, большой опыт в убийстве всяких противных тварей? Не $gмог:могла; бы ты применить свои навыки и решить эту проблему? Во имя всех пандаренов, желающих искупаться!$B$BЭто было бы очень благородно, учитывая, что я один из них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 стайных острозубов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30285,'Донесения У Као','После нападения к нам не попало несколько неучтенных донесений разведчиков. Если нам повезло, они все еще в деревне, но на некоторые из них могли наложить лапы могу.$B$BЕсли ты сможешь принести донесения разведчиков, я определенно стану спать спокойнее. Мы не можем позволить, чтобы могу узнали о наших позициях или о каких-либо найденных артефактах, иначе наши воины окажутся в еще большей опасности.','Добудьте 3 донесения разведчиков У Као.','Вернитесь к Сунь Доброе Сердце в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесения У Као',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После нападения к нам не попало несколько неучтенных донесений разведчиков. Если нам повезло, они все еще в деревне, но на некоторые из них могли наложить лапы могу.$B$BЕсли ты сможешь принести донесения разведчиков, я определенно стану спать спокойнее. Мы не можем позволить, чтобы могу узнали о наших позициях или о каких-либо найденных артефактах, иначе наши воины окажутся в еще большей опасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 донесения разведчиков У Као.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30286,'Загнаны в угол','Многие жители деревни напуганы. Не в состоянии защитить себя, они спрятались по углам. Ты $gнужен:нужна; им. Спаси их!$B$BНе теряй времени, спаси как можно больше селян!','Спасите 6 жителей деревни Туманного Водопада.','Вернитесь к Сунь Доброе Сердце в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загнаны в угол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие жители деревни напуганы. Не в состоянии защитить себя, они спрятались по углам. Ты $gнужен:нужна; им. Спаси их!$B$BНе теряй времени, спаси как можно больше селян!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 жителей деревни Туманного Водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30287,'Могу – плохие гости','Левен послал Рука остановить могу, но их оказалось слишком много. Рук один не справится.$B$BПоможешь ему? А он взамен доложит Левену о твоей помощи. Обещаю.','Убейте 6 налетчиков шадо-тянь в деревне Туманного Водопада.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могу – плохие гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Левен послал Рука остановить могу, но их оказалось слишком много. Рук один не справится.$B$BПоможешь ему? А он взамен доложит Левену о твоей помощи. Обещаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 налетчиков шадо-тянь в деревне Туманного Водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30288,'Горит мой город опять','Не знаю, $gзаметил:заметила; ли ты, но мой город... снова горит!$B$BУ нас тут повсюду есть бочки с водой, но никто не может выйти, чтобы затушить пожар. Пожалуйста, умоляю, помоги нам!','Используйте бочки с водой в деревне Туманного Водопада, чтобы потушить 60 пожаров.','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горит мой город опять',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, $gзаметил:заметила; ли ты, но мой город... снова горит!$B$BУ нас тут повсюду есть бочки с водой, но никто не может выйти, чтобы затушить пожар. Пожалуйста, умоляю, помоги нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте бочки с водой в деревне Туманного Водопада, чтобы потушить 60 пожаров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мэру Шие в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30289,'Освободить сознание','Могу крадут у стражников сознание! Заставляют их делать чудовищные вещи.$B$BСтражников не убивай, только могу, потом они забудут о том, что могу крали их сознание, и перестанут вершить зло. Тебе нужно исправить их, как это делает Рук.','Освободите 6 одержимых стражников, убив тех, кто овладел их сознанием.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободить сознание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу крадут у стражников сознание! Заставляют их делать чудовищные вещи.$B$BСтражников не убивай, только могу, потом они забудут о том, что могу крали их сознание, и перестанут вершить зло. Тебе нужно исправить их, как это делает Рук.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 одержимых стражников, убив тех, кто овладел их сознанием.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30290,'Каменные убийцы','Ожившие каменные собаки могу бегать за селянами. Рук пытаться разбить их, они слишком быстрые.$b$bПоможешь ему раздробить их?','Убейте 8 каменных цийлиней.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменные убийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ожившие каменные собаки могу бегать за селянами. Рук пытаться разбить их, они слишком быстрые.$b$bПоможешь ему раздробить их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 каменных цийлиней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30291,'Нечто невероятное','Я тут как-то говорил с Тантаном... опять... Он до сих пор утверждает, что рыбалка – отличное времяпрепровождение. Я довольно скептичен в этом вопросе, но все же решил попробовать еще раз. Я не большой поклонник всего этого сидения с палкой и ожидания поклевки, поэтому я решил поступить более эффективно.$B$BТеперь осталось просто собрать целые рыбешки, которые плавают в озере пузом кверху. Сделаешь это для меня?','Соберите 12 оглушенных карпов Белых Лепестков.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечто невероятное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут как-то говорил с Тантаном... опять... Он до сих пор утверждает, что рыбалка – отличное времяпрепровождение. Я довольно скептичен в этом вопросе, но все же решил попробовать еще раз. Я не большой поклонник всего этого сидения с палкой и ожидания поклевки, поэтому я решил поступить более эффективно.$B$BТеперь осталось просто собрать целые рыбешки, которые плавают в озере пузом кверху. Сделаешь это для меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 оглушенных карпов Белых Лепестков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30292,'Бесцеремонное пробуждение','Могу захватили контроль над сауроками у озера на западе и обратили их против нас! В общем-то, они и так уже были настроены против нас, так что чем думали могу – непонятно.$B$BАньцзи – боец в нашей паре, а я романтик. Поэтому я ищу того, кто помашет там мечом, поколдует, воодушевляюще что-нибудь покричит... ну, знаешь, и все в таком духе.$B$BМожешь убить несколько ящеров?','Убейте 8 одержимых трупоедов Бледного Клинка.','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесцеремонное пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу захватили контроль над сауроками у озера на западе и обратили их против нас! В общем-то, они и так уже были настроены против нас, так что чем думали могу – непонятно.$B$BАньцзи – боец в нашей паре, а я романтик. Поэтому я ищу того, кто помашет там мечом, поколдует, воодушевляюще что-нибудь покричит... ну, знаешь, и все в таком духе.$B$BМожешь убить несколько ящеров?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 одержимых трупоедов Бледного Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30293,'В руках врага','Подчиняющие разум Шао-Тень взяли под контроль наших защитников у Озера Белых Лепестков на западе. Отправься туда и убей могу. Но не трогай защитников! Убийство могу должно освободить их разум.$B$BЧем раньше ты туда отправишься, тем лучше. Аньцзи может вскоре прийти туда, чтобы помочь. Умение сдерживать себя, когда становится жарко, – не та черта характера, из-за которой я на ней женился.','Атакуйте 8 одержимых защитников Белого Лепестка до тех пор, пока они не освободятся от контроля могу.','Вернитесь к семейству Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В руках врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подчиняющие разум Шао-Тень взяли под контроль наших защитников у Озера Белых Лепестков на западе. Отправься туда и убей могу. Но не трогай защитников! Убийство могу должно освободить их разум.$B$BЧем раньше ты туда отправишься, тем лучше. Аньцзи может вскоре прийти туда, чтобы помочь. Умение сдерживать себя, когда становится жарко, – не та черта характера, из-за которой я на ней женился.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Атакуйте 8 одержимых защитников Белого Лепестка до тех пор, пока они не освободятся от контроля могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к семейству Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30294,'Обретение покоя','Подчиняющие разум на Озере Белых Лепестков захватывают души умерших, обрекая их на страшные мучения.$B$BЯ записал для тебя последовательность обряда, который освободит души умерших и направит их на предназначенный им путь. Я не знаю, куда они отправятся, и что там с ними произойдет, но, по крайней мере, это вырвет их из жестоких лап могу.$B$BПроизведи этот обряд возле каждого трупа, который ты найдешь на своем пути. Телами мы займемся позже.','Произведите обряд Освобождения над телами 6 павших защитников Золотого Лотоса.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обретение покоя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подчиняющие разум на Озере Белых Лепестков захватывают души умерших, обрекая их на страшные мучения.$B$BЯ записал для тебя последовательность обряда, который освободит души умерших и направит их на предназначенный им путь. Я не знаю, куда они отправятся, и что там с ними произойдет, но, по крайней мере, это вырвет их из жестоких лап могу.$B$BПроизведи этот обряд возле каждого трупа, который ты найдешь на своем пути. Телами мы займемся позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Произведите обряд Освобождения над телами 6 павших защитников Золотого Лотоса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30295,'Turn-in Quest Test Case') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Turn-in Quest Test Case',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30296,'Гаохунь Ловец Душ','Большой главарь могу здесь! Прямо за деревней! Если мы убьем его, Левен точно останется доволен!$B$BТы здорово $gпомог:помогла; Руку. Может быть, поможешь еще разок? Пожалуйста!','Убейте Гаохуня Ловца Душ.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаохунь Ловец Душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большой главарь могу здесь! Прямо за деревней! Если мы убьем его, Левен точно останется доволен!$B$BТы здорово $gпомог:помогла; Руку. Может быть, поможешь еще разок? Пожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаохуня Ловца Душ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30297,'Баолай Воспламенитель','Большой главарь могу здесь! Прямо за деревней! Если мы убьем его, Левен точно останется доволен!$B$BТы здорово $gпомог:помогла; Руку. Может быть, поможешь еще разок? Пожалуйста!','Убейте Баолая Воспламенителя.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баолай Воспламенитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большой главарь могу здесь! Прямо за деревней! Если мы убьем его, Левен точно останется доволен!$B$BТы здорово $gпомог:помогла; Руку. Может быть, поможешь еще разок? Пожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Баолая Воспламенителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30298,'Руины в красном цвете','Могу думают, что могут просто так взять и поселиться в этих руинах? Давай-ка объясним им, что это не так.','Убейте 8 могу на руинах Го-Лай.','Вернитесь к Левену Рассветному Клинку в руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины в красном цвете',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу думают, что могут просто так взять и поселиться в этих руинах? Давай-ка объясним им, что это не так.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 могу на руинах Го-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30299,'Все средства хороши','Могу заключили духов в старинные статуи, чтобы оживить их, взять под свой контроль и направить против нас.$B$BЕдинственный способ освободить духа – разрушить сосуд, в котором он заточен.','Разрушьте 6 статуй могу.','Вернитесь к Сунь Доброе Сердце в руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все средства хороши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу заключили духов в старинные статуи, чтобы оживить их, взять под свой контроль и направить против нас.$B$BЕдинственный способ освободить духа – разрушить сосуд, в котором он заточен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разрушьте 6 статуй могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30300,'Ключ к успеху','Могу захватили пленников. Они будут пытать их и делать с ними вещи еще похуже.$B$BЛюбым способом освободи их из клеток.','Найдите ключ от клетки Шао-Тень и освободите 6 пленников Золотого Лотоса.','Вернитесь к Сунь Доброе Сердце на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ к успеху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу захватили пленников. Они будут пытать их и делать с ними вещи еще похуже.$B$BЛюбым способом освободи их из клеток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ключ от клетки Шао-Тень и освободите 6 пленников Золотого Лотоса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30301,'Теплый прием','Если мы подожжем спальные палатки могу, это будет лучший способ передать им наше сообщение.$B$BОбследуй руины. Уничтожь каждую палатку, которую найдешь.','Сожгите 6 палаток могу в руинах Го-Лай.','Вернитесь к Левену Рассветному Клинку на руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теплый прием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы подожжем спальные палатки могу, это будет лучший способ передать им наше сообщение.$B$BОбследуй руины. Уничтожь каждую палатку, которую найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 6 палаток могу в руинах Го-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку на руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30302,'Опасный империон','Мои разведчики сообщили, что империон Шао-Тень вошел в Залы Го-Лай. Я хочу убедиться, что он не выйдет оттуда живым. Для этой работы мне нужен кто-то, кому я могу доверять.$B$BДумаю, ты подойдешь, |3-6($c).','Убейте империона Шао-Тень.','Вернитесь к Левену Рассветному Клинку на руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасный империон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики сообщили, что империон Шао-Тень вошел в Залы Го-Лай. Я хочу убедиться, что он не выйдет оттуда живым. Для этой работы мне нужен кто-то, кому я могу доверять.$B$BДумаю, ты подойдешь, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте империона Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку на руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30303,'NOT USED','Вернитесь к Левену Рассветному Клинку в руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','NOT USED',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30304,'Крепкие, как камень','Эй! Рассказать, что необычное случилось со мной сегодня утром?$B$BЯ прогуливался по руинам с Аньцзи. Я смотрел себе под ноги, чтобы больше не наступить на мерзкий паучий кокон, как вдруг одна из статуй ожила и попыталась снести мне голову!$B$BАньцзи, конечно, в конце концов разобралась с ней. Но я не удовлетворен. Я думаю, тебе следует пойти туда и разломать все статуи, независимо от того, двигаются они или нет. Это единственный гарантированный способ решить проблему.','Разрушьте 10 статуй могу.','Вернитесь к Куню Осеннему Свету на Руины Го-Лай в Вечноцветущий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепкие, как камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Рассказать, что необычное случилось со мной сегодня утром?$B$BЯ прогуливался по руинам с Аньцзи. Я смотрел себе под ноги, чтобы больше не наступить на мерзкий паучий кокон, как вдруг одна из статуй ожила и попыталась снести мне голову!$B$BАньцзи, конечно, в конце концов разобралась с ней. Но я не удовлетворен. Я думаю, тебе следует пойти туда и разломать все статуи, независимо от того, двигаются они или нет. Это единственный гарантированный способ решить проблему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разрушьте 10 статуй могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету на Руины Го-Лай в Вечноцветущий дол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30305,'Он знает, что делает','Ты знаешь Хэ Легкую Ногу? Трусливый парень, да к тому же неразговорчивый. Он расставил ловушки для могу повсюду в руинах и сказал Руку, что осталось только заманить в них могу. А Рук толком не знает, как это сделать.$B$BМожет ты справишься? Найдешь ловушки и заманишь в них могу. Только не говори Хэ, пожалуйста.','Заманите 8 противников в отравленные ловушки Хэ.','Вернитесь к Руку Каменной Ступне на руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он знает, что делает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь Хэ Легкую Ногу? Трусливый парень, да к тому же неразговорчивый. Он расставил ловушки для могу повсюду в руинах и сказал Руку, что осталось только заманить в них могу. А Рук толком не знает, как это сделать.$B$BМожет ты справишься? Найдешь ловушки и заманишь в них могу. Только не говори Хэ, пожалуйста.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заманите 8 противников в отравленные ловушки Хэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне на руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30306,'Ринг','У нас есть несколько учеников, которые еще далеки от того, чтобы быть тебе ровней, но из-за того, что их больше, они могут посоревноваться с тобой. А если им не удастся победить, они извлекут урок смирения.$B$BВойди на ринг, когда будешь $gготов:готова;. Не стоит недооценивать их.','Победите на ринге 20 учеников Шадо-Пан.','Очень впечатляет. Кажется, им еще много чему стоит поучиться. Я прослежу за этим.','Вернитесь к Хай-мэ Тяжелой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ринг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть несколько учеников, которые еще далеки от того, чтобы быть тебе ровней, но из-за того, что их больше, они могут посоревноваться с тобой. А если им не удастся победить, они извлекут урок смирения.$B$BВойди на ринг, когда будешь $gготов:готова;. Не стоит недооценивать их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на ринге 20 учеников Шадо-Пан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень впечатляет. Кажется, им еще много чему стоит поучиться. Я прослежу за этим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хай-мэ Тяжелой Лапе в Гарнизон Заходящего Солнца, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30307,'Вечный дозор','Хорошо, что ты с нами, |3-6($c). Если хочешь присоединиться к битве, мне как раз нужен кто-то, чтобы очистить Золотую лестницу от нападающих могу.$B$BЯ могу рассчитывать на тебя?','Убейте 8 могу Шао-Тень на Золотой террасе.','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечный дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что ты с нами, |3-6($c). Если хочешь присоединиться к битве, мне как раз нужен кто-то, чтобы очистить Золотую лестницу от нападающих могу.$B$BЯ могу рассчитывать на тебя?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 могу Шао-Тень на Золотой террасе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30308,'Каменный цийлинь','Левен всегда говорит: "Хороший цийлинь – мертвый цийлинь", и я разделяю эту точку зрения. Ты здесь, чтобы помочь?','Убейте 6 гранитных цийлиней.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный цийлинь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Левен всегда говорит: "Хороший цийлинь – мертвый цийлинь", и я разделяю эту точку зрения. Ты здесь, чтобы помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 гранитных цийлиней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30309,'Твердость камня','Сегодня могу послали свои каменные чучела на наше поле боя. Они оживляют их на Золотой лестнице.$B$BОни большие, их сложнее атаковать, зато если упадут – сразу развалятся на куски. Ты с нами?','Уничтожьте 6 изваяний могу.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твердость камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня могу послали свои каменные чучела на наше поле боя. Они оживляют их на Золотой лестнице.$B$BОни большие, их сложнее атаковать, зато если упадут – сразу развалятся на куски. Ты с нами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 изваяний могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30310,'Гром в небесах','Могу сломили волю небесных змеев и обернули их против нас.$B$BНаши защитники с ними вряд ли справятся, а вот ты – да. Иди на северо-запад к Золотой лестнице и подбей этих змеев.','Убейте 3-х покоренных змеев.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гром в небесах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу сломили волю небесных змеев и обернули их против нас.$B$BНаши защитники с ними вряд ли справятся, а вот ты – да. Иди на северо-запад к Золотой лестнице и подбей этих змеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3-х покоренных змеев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30311,'Выше знамена!','Если бы меня попросили назвать самое важное качество для боевого знамени, я бы сказал, что оно должно быть поднято и видно каждому издали. И видно не потому, что оно горит, а потому что оно высоко и уверенно вздернуто. Само собой разумеется, я обеспокоен ситуацией со знаменами на данный момент.$B$BЕсли бы $gгосподин неизвестный:госпожа неизвестная:c; |3-6($c) $gвызвался:вызвалась; пройтись через поле боя на северо-запад и установить знамена, то и моей благодарности, и, конечно же, благодарности моей чертовски сексуальной жены-командира не было бы предела.','Поднимите 6 знамен Золотого Лотоса.','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выше знамена!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы меня попросили назвать самое важное качество для боевого знамени, я бы сказал, что оно должно быть поднято и видно каждому издали. И видно не потому, что оно горит, а потому что оно высоко и уверенно вздернуто. Само собой разумеется, я обеспокоен ситуацией со знаменами на данный момент.$B$BЕсли бы $gгосподин неизвестный:госпожа неизвестная:c; |3-6($c) $gвызвался:вызвалась; пройтись через поле боя на северо-запад и установить знамена, то и моей благодарности, и, конечно же, благодарности моей чертовски сексуальной жены-командира не было бы предела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднимите 6 знамен Золотого Лотоса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30312,'Второй шанс','Какие-то глупцы попытались прорваться на Золотую лестницу с востока, но были обстреляны пушками. Немногие уцелели в этой мясорубке, а те, кто выжил, вернулись домой с тяжелыми ранениями. Все поле битвы усеяно трупами и ранеными.$B$BВот, возьми эти бинты и помоги пострадавшим защитникам добраться до укреплений. Если тебе известны какие-нибудь исцеляющие заклинания, используй их. Только поторопись, у нас мало времени.','Исцелите 6 раненых защитников.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй шанс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какие-то глупцы попытались прорваться на Золотую лестницу с востока, но были обстреляны пушками. Немногие уцелели в этой мясорубке, а те, кто выжил, вернулись домой с тяжелыми ранениями. Все поле битвы усеяно трупами и ранеными.$B$BВот, возьми эти бинты и помоги пострадавшим защитникам добраться до укреплений. Если тебе известны какие-нибудь исцеляющие заклинания, используй их. Только поторопись, у нас мало времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите 6 раненых защитников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30313,'Блуждающие туманы','<Он смотрит вниз, на мертвое туманное существо у его ног, затем смотрит вверх на вас, а затем указывает на туман, окружающий озеро. Похоже, он хочет, чтобы вы нашли и убили как можно больше таких туманных тварей.>','Убейте 8 бродящих в тумане.','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блуждающие туманы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он смотрит вниз, на мертвое туманное существо у его ног, затем смотрит вверх на вас, а затем указывает на туман, окружающий озеро. Похоже, он хочет, чтобы вы нашли и убили как можно больше таких туманных тварей.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 бродящих в тумане.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30314,'Обломки Бледного Клинка','<Он смотрит вниз, на труп саурока у его ног. Он поднимает взгляд на вас и указывает вниз, на побережье озера. Похоже, он хочет, чтобы вы нашли и убили несколько этих ящеров.>','Убейте 8 сауроков Бледного Клинка.','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки Бледного Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он смотрит вниз, на труп саурока у его ног. Он поднимает взгляд на вас и указывает вниз, на побережье озера. Похоже, он хочет, чтобы вы нашли и убили несколько этих ящеров.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 сауроков Бледного Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30315,'Normal Quest Test Case','Yes?','Give me stuff.','Stuff!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Normal Quest Test Case',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Yes?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Give me stuff.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Stuff!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30316,'Целеустремленность','В другой раз я бы не стал просить о помощи $gтакого:такой; брюзги, как ты, |3-6($c). Но раз уже тебе Золотая лестница все равно по пути, разыщешь немного выпущенных стрел для лучников?','Найдите 12 выпущенных стрел шадо-панов.','Вернитесь к Чэ Дикому Страннику в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целеустремленность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В другой раз я бы не стал просить о помощи $gтакого:такой; брюзги, как ты, |3-6($c). Но раз уже тебе Золотая лестница все равно по пути, разыщешь немного выпущенных стрел для лучников?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 12 выпущенных стрел шадо-панов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэ Дикому Страннику в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30317,'Вода, вода – кругом вода!','Спрашиваешь, чем можешь помочь?$b$bУ нас давно не было дождя. Мне нужно, чтобы кто-нибудь полил грядки в Плодородных землях. Имей в виду: полить надо ВСЕ грядки!$b$bУ распорядителя полетов Крылатой Нга – она живет через дорогу – есть несколько крылатых змеев. Возьми одного из них и с его помощью устрой благодатный живительный душ для пересохшей земли.','Поговорите с Крылатой Нга, возьмите у нее крылатого змея и с его помощью полейте 35 засохших грядок в Плодородных землях.','Однако! Вот с первого взгляда было ясно – видный мелиоратор. Просто золотые руки, право слово.','Вернитесь к фермеру Фуну на рынок Полугорья в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вода, вода – кругом вода!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спрашиваешь, чем можешь помочь?$b$bУ нас давно не было дождя. Мне нужно, чтобы кто-нибудь полил грядки в Плодородных землях. Имей в виду: полить надо ВСЕ грядки!$b$bУ распорядителя полетов Крылатой Нга – она живет через дорогу – есть несколько крылатых змеев. Возьми одного из них и с его помощью устрой благодатный живительный душ для пересохшей земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крылатой Нга, возьмите у нее крылатого змея и с его помощью полейте 35 засохших грядок в Плодородных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Однако! Вот с первого взгляда было ясно – видный мелиоратор. Просто золотые руки, право слово.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Фуну на рынок Полугорья в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30318,'Погоня за курицей','Эй, ты! Как тебя там – $n, да? У меня тут кое-что случилось, срочно нужен кто-нибудь шустрый.$b$bМоя прекрасная курица, обладательница наград и медалей, сбежала из курятника! И теперь она на воле, вступает в тесные отношения с другими несушками, дикими птицами и... <нервно сглатывает> беспородными петухами.$b$bМоя ферма к западу отсюда, к югу от Небогорья. Пожалуйста, найди мою курицу!','Подбирайте цыплят Горной Лапы, пока не найдете породистую курицу.','Клянусь, раньше она такого не делала.','Вернитесь к старику Горной Лапе, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погоня за курицей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Как тебя там – $n, да? У меня тут кое-что случилось, срочно нужен кто-нибудь шустрый.$b$bМоя прекрасная курица, обладательница наград и медалей, сбежала из курятника! И теперь она на воле, вступает в тесные отношения с другими несушками, дикими птицами и... <нервно сглатывает> беспородными петухами.$b$bМоя ферма к западу отсюда, к югу от Небогорья. Пожалуйста, найди мою курицу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подбирайте цыплят Горной Лапы, пока не найдете породистую курицу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клянусь, раньше она такого не делала.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старику Горной Лапе, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30319,'Вредители','Мой работник Вика-Вика вскапывал землю на западном поле, и, насколько я понимаю, у него возникли неприятности с вредителями.$b$bПротив насекомых у него есть пестицид, но боюсь, что средством от сурков он не располагает.$b$bПоможешь ему? Нам и так вредят хозены и гну-сини – нельзя допустить, чтобы урожай погиб из-за каких-то жалких сурков.','Поговорите с Вика-Викой, затем растопчите 25 черноносых сурков.','Вернитесь к Хаоханю Грязному Когтю в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вредители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой работник Вика-Вика вскапывал землю на западном поле, и, насколько я понимаю, у него возникли неприятности с вредителями.$b$bПротив насекомых у него есть пестицид, но боюсь, что средством от сурков он не располагает.$b$bПоможешь ему? Нам и так вредят хозены и гну-сини – нельзя допустить, чтобы урожай погиб из-за каких-то жалких сурков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вика-Викой, затем растопчите 25 черноносых сурков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаоханю Грязному Когтю в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30320,'Свободные духи','Мне достался один из кинжалов терзателей духа Шао-Тень. Он излучает сильную магию. Мне сказали, что он позволит тебе попасть в призрачный вихрь.$B$BМогу с их помощью ловят духов и подчиняют их своей воле, но я надеюсь, что ты используешь его для освобождения духов.$B$BВойди в любой призрачный вихрь, который найдешь и освободи как можно больше духов, пока магия не иссякла.','Войдите в призрачный вихрь и освободите 15 духов пандаренов.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне достался один из кинжалов терзателей духа Шао-Тень. Он излучает сильную магию. Мне сказали, что он позволит тебе попасть в призрачный вихрь.$B$BМогу с их помощью ловят духов и подчиняют их своей воле, но я надеюсь, что ты используешь его для освобождения духов.$B$BВойди в любой призрачный вихрь, который найдешь и освободи как можно больше духов, пока магия не иссякла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в призрачный вихрь и освободите 15 духов пандаренов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30321,'Война с сорняками II','Ш-шкажи... Ты жнаешь того парня... у которого... *ик*... проблемы с шорняками? Кажется, его зовут Гай Лань. Я его обожаю.$b$bОн шкажал, если я... *ик*... пришлю к нему того, кто прополет шорняки, он даст мне эля.$b$bТам всего чуть-чуть шорняков. Наверно...$b$b*ик*','Поговорите с Гай Ланем, затем вырвите 100 сорняков на его ферме. Рвать сорняки можно и сидя в седле.','Шпасибо, гошподин *ик* Атог.','Вернитесь к Йогу Пьяному в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с сорняками II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ш-шкажи... Ты жнаешь того парня... у которого... *ик*... проблемы с шорняками? Кажется, его зовут Гай Лань. Я его обожаю.$b$bОн шкажал, если я... *ик*... пришлю к нему того, кто прополет шорняки, он даст мне эля.$b$bТам всего чуть-чуть шорняков. Наверно...$b$b*ик*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гай Ланем, затем вырвите 100 сорняков на его ферме. Рвать сорняки можно и сидя в седле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шпасибо, гошподин *ик* Атог.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йогу Пьяному в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30322,'Денежные вопросы','Я люблю работать на рынке, хотя кое-что мне совсем не нравится – например, собирать долги.$b$bМногие пандарены не платят просто потому, что им лень, однако несколько мерзких типов демонстративно не хотят этого делать. Кроме того, есть и бедные, которым платить попросту нечем.$b$bКое-кто в этом городе мне задолжал. Можешь напомнить им о том, что пора платить по счетам?','Получите платежи у изготовителя специй Цзинь Цзяо, торговца Джамбези, хозяйки таверны Лэй Лань и у Лоло Лио.','Как хорошо, что удалось наконец разобраться с этим грязным делом. Никто не доставил тебе хлопот, да?','Вернитесь к Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Денежные вопросы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я люблю работать на рынке, хотя кое-что мне совсем не нравится – например, собирать долги.$b$bМногие пандарены не платят просто потому, что им лень, однако несколько мерзких типов демонстративно не хотят этого делать. Кроме того, есть и бедные, которым платить попросту нечем.$b$bКое-кто в этом городе мне задолжал. Можешь напомнить им о том, что пора платить по счетам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите платежи у изготовителя специй Цзинь Цзяо, торговца Джамбези, хозяйки таверны Лэй Лань и у Лоло Лио.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как хорошо, что удалось наконец разобраться с этим грязным делом. Никто не доставил тебе хлопот, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30323,'Они их даже не носят!','Несколько недель назад мерзкие маленькие гну-сини прыгохвосты взломали мой сейф и похитили драгоценности. Кое-что уже удалось вернуть, но большая часть до сих пор не найдена.$b$bЕсли пойдешь на север, на Утес прыгохвостов, пожалуйста, поищи драгоценности. Без них мне жизнь не мила.','Найдите украденный венец, ворованное кольцо и похищенный браслет.','Какие же недоразвитые эти гну-сини! Неужели они не понимают, сколько стоят такие украшения?!','Вернитесь к Тине Грязный Коготь в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они их даже не носят!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько недель назад мерзкие маленькие гну-сини прыгохвосты взломали мой сейф и похитили драгоценности. Кое-что уже удалось вернуть, но большая часть до сих пор не найдена.$b$bЕсли пойдешь на север, на Утес прыгохвостов, пожалуйста, поищи драгоценности. Без них мне жизнь не мила.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите украденный венец, ворованное кольцо и похищенный браслет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие же недоразвитые эти гну-сини! Неужели они не понимают, сколько стоят такие украшения?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тине Грязный Коготь в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30324,'Чи-Чи против!','Не все хозены одинаковые. Чи-Чи из племени лесных хозенов... из Нефритового леса. С ними можно ужиться.$b$bА вот захватчики Куньцзэнь... они пришли издалека, спустились с северных гор. Эти хозены вовсе не такие добродушные, как Чи-Чи.$b$bОни приходят сюда, отнимают наше добро, все разоряют.$b$bЧи-Чи хочет их убить. Поможешь?','Уничтожьте 8 хозенов Куньцзэнь в деревне Куньцзэнь.','Отлично! Чи-Чи знал, что ты сможешь!','Вернитесь к Чи-Чи в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чи-Чи против!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не все хозены одинаковые. Чи-Чи из племени лесных хозенов... из Нефритового леса. С ними можно ужиться.$b$bА вот захватчики Куньцзэнь... они пришли издалека, спустились с северных гор. Эти хозены вовсе не такие добродушные, как Чи-Чи.$b$bОни приходят сюда, отнимают наше добро, все разоряют.$b$bЧи-Чи хочет их убить. Поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 хозенов Куньцзэнь в деревне Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Чи-Чи знал, что ты сможешь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Чи в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30325,'Болевая точка','Мне довелось понаблюдать за хозенами Куньцзэнь – и вот какую интересную особенность я могу отметить. Перед тем как напасть, они проводят странные варварские ритуалы у своего тотема.$b$bЕсли же мы прервем церемонию, то не только отсрочим нападение, но и подорвем боевой дух хозенов! Иди туда и нанеси как можно больше урона!','Разбросайте 8 ритуальных свечей Куньцзэнь и 4 горящих угля и убейте одного ритуалиста Куньцзэнь.','Ха! Это они будут еще несколько дней разгребать.','Вернитесь к Шо в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болевая точка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне довелось понаблюдать за хозенами Куньцзэнь – и вот какую интересную особенность я могу отметить. Перед тем как напасть, они проводят странные варварские ритуалы у своего тотема.$b$bЕсли же мы прервем церемонию, то не только отсрочим нападение, но и подорвем боевой дух хозенов! Иди туда и нанеси как можно больше урона!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбросайте 8 ритуальных свечей Куньцзэнь и 4 горящих угля и убейте одного ритуалиста Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Это они будут еще несколько дней разгребать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шо в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30326,'Вождь-сказитель Куньцзэнь','Послушать местных жителей, так хозены – какие-то полоумные, недоразвитые существа... Но это не так! У них тоже есть мозги – хотя они особенно ими и не пользуются.$b$bГоворят, что у племени Куньцзэнь два вождя – один командует войском, а второй хранит предания и легенды племени.$b$bО, как бы мне хотелось узнать об истории хозенов...','Получите книгу сказаний Куньцзэнь у вождя-сказителя Куньцзэнь.','Ого! Ты посмотри на это! Это...$B$B<Рыба просматривает страницы и мрачнеет.>$B$BОй, кажется, это неприличная картинка. Но все остальное – такое интересное! Обожаю изучать мышление других созданий. Спасибо, Джестерок!','Должно быть, легенды хозенов мало чем отличаются от наших.','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.','Я не знаю его имени. Они постоянно избирают новых вождей.','Вождь-сказитель Куньцзэнь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь-сказитель Куньцзэнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушать местных жителей, так хозены – какие-то полоумные, недоразвитые существа... Но это не так! У них тоже есть мозги – хотя они особенно ими и не пользуются.$b$bГоворят, что у племени Куньцзэнь два вождя – один командует войском, а второй хранит предания и легенды племени.$b$bО, как бы мне хотелось узнать об истории хозенов...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите книгу сказаний Куньцзэнь у вождя-сказителя Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого! Ты посмотри на это! Это...$B$B<Рыба просматривает страницы и мрачнеет.>$B$BОй, кажется, это неприличная картинка. Но все остальное – такое интересное! Обожаю изучать мышление других созданий. Спасибо, Джестерок!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должно быть, легенды хозенов мало чем отличаются от наших.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я не знаю его имени. Они постоянно избирают новых вождей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь-сказитель Куньцзэнь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30327,'Веревки нужно сжечь','Я, э-э... ну...$b$bА, да ладно. Глупая мысль.$b$bЯ вот что думаю: возможно, мы могли бы остановить наступление хозенов Куньцзэнь... ну... никого не убивая. По склону горы тянутся веревки – и мне кажется, что хозены спускаются именно по ним. И...$b$bХотя нет, забудь. Все равно ничего не выйдет.','Сожгите 6 веревок Куньцзэнь.','<Элла сияет.>$B$BТы все сделал? Ради меня? О, спасибо-спасибо-спасибо!','Вернитесь к Элле в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веревки нужно сжечь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, э-э... ну...$b$bА, да ладно. Глупая мысль.$b$bЯ вот что думаю: возможно, мы могли бы остановить наступление хозенов Куньцзэнь... ну... никого не убивая. По склону горы тянутся веревки – и мне кажется, что хозены спускаются именно по ним. И...$b$bХотя нет, забудь. Все равно ничего не выйдет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 6 веревок Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Элла сияет.>$B$BТы все сделал? Ради меня? О, спасибо-спасибо-спасибо!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элле в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30333,'Из двух зол меньшее','Нам, как и другим крестьянам, время от времени досаждают гну-сини.$b$bСамое вредоносное племя – прыгохвосты – обитает в горах, на севере. Прыгохвосты спускаются сюда, только когда у них заканчиваются овощи.$b$bЕсли честно, то мне уже приходилось иметь дело с гну-синями – обычные паразиты, с которыми нужно бороться. А лучший способ борьбы с гну-синями – уничтожение их прародительницы. Как видишь, все просто.','Уничтожьте прародительницу прыгохвостов.','Ну, с этим покончено. Теперь для разнообразия можем заняться сельским хозяйством.','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.','Бей и копай. Копай и бей.','Прародительница прыгохвостов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из двух зол меньшее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам, как и другим крестьянам, время от времени досаждают гну-сини.$b$bСамое вредоносное племя – прыгохвосты – обитает в горах, на севере. Прыгохвосты спускаются сюда, только когда у них заканчиваются овощи.$b$bЕсли честно, то мне уже приходилось иметь дело с гну-синями – обычные паразиты, с которыми нужно бороться. А лучший способ борьбы с гну-синями – уничтожение их прародительницы. Как видишь, все просто.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте прародительницу прыгохвостов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, с этим покончено. Теперь для разнообразия можем заняться сельским хозяйством.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Бей и копай. Копай и бей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Прародительница прыгохвостов',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30334,'Красть плохо... Красть украденное – хорошо','Хозены с западных гор продолжают красть овощи у моих односельчан. Я живу рядом с Полугорьем, поэтому ворюги редко добираются до моих владений – а вот моим друзьям повезло гораздо меньше.$b$bПохоже, хозены крадут гораздо больше, чем могут съесть. Если найдешь в горах овощи, которые еще не испортились... укради их!','Украдите 16 украденных овощей.','Спасибо! Я раздам их нашим фермерам.','Ты добыл овощи?','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красть плохо... Красть украденное – хорошо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены с западных гор продолжают красть овощи у моих односельчан. Я живу рядом с Полугорьем, поэтому ворюги редко добираются до моих владений – а вот моим друзьям повезло гораздо меньше.$b$bПохоже, хозены крадут гораздо больше, чем могут съесть. Если найдешь в горах овощи, которые еще не испортились... укради их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 16 украденных овощей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! Я раздам их нашим фермерам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл овощи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30335,'Борьба с опустошителями','В последнее время хозены Куньцзэнь, обитающие в горах на западе, начали жечь костры и голосить свои жуткие песни. Судя по моим наблюдениям, это означает, что они собираются в очередной набег.$b$bОстановить их нам не удастся, но мы по крайней мере можем уменьшить их численность.','Уничтожьте 12 хозенов Куньцзэнь.','Они непременно нападут, но моя ферма – и фермы друзей – вне опасности.$B$BПо крайней мере если мы будем их защищать. Верно, Овердва?','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с опустошителями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время хозены Куньцзэнь, обитающие в горах на западе, начали жечь костры и голосить свои жуткие песни. Судя по моим наблюдениям, это означает, что они собираются в очередной набег.$b$bОстановить их нам не удастся, но мы по крайней мере можем уменьшить их численность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 хозенов Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они непременно нападут, но моя ферма – и фермы друзей – вне опасности.$B$BПо крайней мере если мы будем их защищать. Верно, Овердва?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30336,'Вождь-охотник Куньцзэнь','По моим сведениям, у хозенов Куньцзэнь два вождя. Один из них безвреден – он занимается зельями, лекарствами и древними легендами. Второй командует охотниками – а в последнее время они охотятся исключительно на наши овощи и фрукты.$b$bВождь-охотник – проблема, которую нужно решить раз и навсегда. Думаю, местные фермеры будут весьма благодарны тебе, если ты... ну... "разберешься" с ним.','Убейте вождя-охотника Куньцзэнь.','Думаю, сегодня хозены устроят пышные празднества в честь нового вождя-охотника.$B$BА это значит, что мои друзья-фермеры смогут хоть немного отдохнуть.','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.','Вожди-охотники Куньцзэнь никогда не переступят границу Небогорья.','Вождь-охотник Куньцзэнь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь-охотник Куньцзэнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По моим сведениям, у хозенов Куньцзэнь два вождя. Один из них безвреден – он занимается зельями, лекарствами и древними легендами. Второй командует охотниками – а в последнее время они охотятся исключительно на наши овощи и фрукты.$b$bВождь-охотник – проблема, которую нужно решить раз и навсегда. Думаю, местные фермеры будут весьма благодарны тебе, если ты... ну... "разберешься" с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя-охотника Куньцзэнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, сегодня хозены устроят пышные празднества в честь нового вождя-охотника.$B$BА это значит, что мои друзья-фермеры смогут хоть немного отдохнуть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вожди-охотники Куньцзэнь никогда не переступят границу Небогорья.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь-охотник Куньцзэнь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30337,'Диверсия','Хозены крадут наше добро, а нам приходится похищать его у них. Этому нужно положить конец.$b$b<Фермер Юн передает вам бочку с фейерверками.>$b$bИди на запад, найди в горах лагерь хозенов и разложи эти фейерверки рядом с украденными припасами. Вдруг хозены увидят взрывы и решат, что все припасы испортились. Возможно, тогда они перестанут их красть!$b$bВедь стоит это попробовать, как считаешь?','Поставьте бочку с фейерверками рядом с кучами украденного оружия, украденных инструментов, украденного зерна и грудой украденных бочек с пивом.','Надеюсь, мы отбили у них охоту красть наши припасы. Лично я бы ни за что не выпил взрывающегося пива и не взял в руки взрывающиеся грабли.','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диверсия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены крадут наше добро, а нам приходится похищать его у них. Этому нужно положить конец.$b$b<Фермер Юн передает вам бочку с фейерверками.>$b$bИди на запад, найди в горах лагерь хозенов и разложи эти фейерверки рядом с украденными припасами. Вдруг хозены увидят взрывы и решат, что все припасы испортились. Возможно, тогда они перестанут их красть!$b$bВедь стоит это попробовать, как считаешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поставьте бочку с фейерверками рядом с кучами украденного оружия, украденных инструментов, украденного зерна и грудой украденных бочек с пивом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, мы отбили у них охоту красть наши припасы. Лично я бы ни за что не выпил взрывающегося пива и не взял в руки взрывающиеся грабли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни или на рынок Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30338,'Тяжелая задача','Мне до сих пор не ясно, зачем могу построили свои статуи так глубоко в озере. Я думаю, что там не всегда была вода, но во время дождя попасть туда было бы практически невозможно.$B$BКому дано понять странные намерения могу...$B$BНе $gмог:могла; бы ты занырнуть туда и достать какие-нибудь артефакты, которые в состоянии поднять? Мне бы это пришлось по душе.','Достаньте из воды 8 артефактов могу.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелая задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне до сих пор не ясно, зачем могу построили свои статуи так глубоко в озере. Я думаю, что там не всегда была вода, но во время дождя попасть туда было бы практически невозможно.$B$BКому дано понять странные намерения могу...$B$BНе $gмог:могла; бы ты занырнуть туда и достать какие-нибудь артефакты, которые в состоянии поднять? Мне бы это пришлось по душе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте из воды 8 артефактов могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30339,'Грязная работенка','Лучший клев во всей Пандарии – здесь, на этом озере. У меня с собой запас пива на целый день, а вот о приманке этого не скажешь.$B$BДа и кто, отправляясь на рыбалку, думает об этом?$B$BЕсли бы ты $gсобрал:собрала; мне немного приманки вдоль берега, то я бы запомнил тебя как крайне приятную личность и непременно сделал бы скидку, когда речь зайдет о плате за мой товар. Ну и, конечно, я тебе заплачу.$B$BНу как, по рукам?','Накопайте 12 свежих червяков из земли Белого Лепестка.','Вернитесь к торговцу Тантану на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная работенка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лучший клев во всей Пандарии – здесь, на этом озере. У меня с собой запас пива на целый день, а вот о приманке этого не скажешь.$B$BДа и кто, отправляясь на рыбалку, думает об этом?$B$BЕсли бы ты $gсобрал:собрала; мне немного приманки вдоль берега, то я бы запомнил тебя как крайне приятную личность и непременно сделал бы скидку, когда речь зайдет о плате за мой товар. Ну и, конечно, я тебе заплачу.$B$BНу как, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накопайте 12 свежих червяков из земли Белого Лепестка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Тантану на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30340,'Палка в грязи','Я собрался порыбачить в этот прекрасный день и, вот незадача, забыл взять удочку. Для рыбалки надо столько всего запомнить – у меня постоянно что-нибудь вываливается из головы.$B$BТростник, который растет вдоль реки, вполне сгодится для удочки. Если бы ты $gдобыл:добыла; мне немного, то я бы запомнил тебя как крайне приятную личность и непременно сделал бы скидку, когда речь зайдет о плате за мой товар. Ну и, конечно, я тебе заплачу.$B$BНу как, по рукам?','Соберите 12 тростников Белого Лепестка.','Вернитесь к торговцу Тантану на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Палка в грязи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я собрался порыбачить в этот прекрасный день и, вот незадача, забыл взять удочку. Для рыбалки надо столько всего запомнить – у меня постоянно что-нибудь вываливается из головы.$B$BТростник, который растет вдоль реки, вполне сгодится для удочки. Если бы ты $gдобыл:добыла; мне немного, то я бы запомнил тебя как крайне приятную личность и непременно сделал бы скидку, когда речь зайдет о плате за мой товар. Ну и, конечно, я тебе заплачу.$B$BНу как, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 тростников Белого Лепестка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Тантану на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30341,'Под внимательным взглядом','<Он смотрит на мертвого разведчика могу у своих ног, смотрит на вас, затем указывает вниз, на побережье озера. Похоже, он хочет, чтобы вы убили несколько разведчиков могу.>','Убейте 8 разведчиков Шао-Тень.','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под внимательным взглядом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он смотрит на мертвого разведчика могу у своих ног, смотрит на вас, затем указывает вниз, на побережье озера. Похоже, он хочет, чтобы вы убили несколько разведчиков могу.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 разведчиков Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хэ Легкой Ноге на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30342,'Острый язык, хрупкие ноги','Я болтал ногами в воде, как вдруг появился один из этих ужасных кроколисков и чуть не оттяпал мне ступню! Представляешь? Я, конечно, могу отдыхать и на берегу, но булькать ногами в воде гораздо веселее. Мне не хватает этого!$B$BНе будешь ли ты так $gлюбезен:любезна; убить парочку или, скажем, восемь кроколисков для меня? Уверяю тебя, они заслуживают смерти за то, что перепугали меня!','Убейте 6 кроколисков тихой заводи.','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Острый язык, хрупкие ноги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я болтал ногами в воде, как вдруг появился один из этих ужасных кроколисков и чуть не оттяпал мне ступню! Представляешь? Я, конечно, могу отдыхать и на берегу, но булькать ногами в воде гораздо веселее. Мне не хватает этого!$B$BНе будешь ли ты так $gлюбезен:любезна; убить парочку или, скажем, восемь кроколисков для меня? Уверяю тебя, они заслуживают смерти за то, что перепугали меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 кроколисков тихой заводи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку на Озеро Белых Лепестков в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30343,'До ватерлинии!','Это покоритель небес Рев Бури, капитан судна "Кулак Гарроша" и командующий этой операцией.$B$BПервое задание – сжечь Седьмой флот до ватерлинии, пока все суда стоят на якоре.$B$BМоряки капитана Дрока удержат вход в гавань, пока работает ваша команда.$B$BРазместите бочки с порохом в трюме каждого корабля, а затем соберитесь у входа в гавань, чтобы оповестить подрывника Бомбастера, который запустит взрыватель и даст воздушному судну сигнал идти вперед.','Разместите бочки с порохом в трюмах всех шести кораблей.','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До ватерлинии!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это покоритель небес Рев Бури, капитан судна "Кулак Гарроша" и командующий этой операцией.$B$BПервое задание – сжечь Седьмой флот до ватерлинии, пока все суда стоят на якоре.$B$BМоряки капитана Дрока удержат вход в гавань, пока работает ваша команда.$B$BРазместите бочки с порохом в трюме каждого корабля, а затем соберитесь у входа в гавань, чтобы оповестить подрывника Бомбастера, который запустит взрыватель и даст воздушному судну сигнал идти вперед.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разместите бочки с порохом в трюмах всех шести кораблей.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Покоритель небес Рев Бури',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Покоритель небес Рев Бури',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30344,'Забытая династия','Не знаю, могу ли я тебя побеспокоить для еще одного задания? Моя дочь, славный командир часовых Лиалия, отказывается выпускать меня в поле.$b$bКаждый день в той темнице я смотрел на руины на севере и мне не терпелось начать исследования.$b$bЕсли мы там, где я думаю, то в этих руинах может скрываться ключ к местонахождению легендарного Пруда Молодости!$b$bПрошу тебя, |3-6($c)! Сходи к руинам и собери там любые таблички, на которых еще сохранились записи.','Соберите 6 династийных табличек.','О! Восхитительно! Восхитительно!$B$BОдин твой поход помог моим изысканиям больше, чем десять лет изучения пыльных книг и распадающихся свитков.$B$BА эти "могу", которых ты видел... Я провел по этому поводу кое-какие исследования и поговорил с Каном.$B$BТеперь я подозреваю, что мы имеем дело с расой времен исчезнувших династий, которые я и изучаю.$B$BРазумеется, отсюда следует и то, что именно они в прошлом владели Прудом Молодости.','Изучать исчезнувшие династии по книгам – это одно, а осматривать древние руины – совсем другое.$B$BПрямо голова кружится от волнения, сотни лет уже такого не было!','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытая династия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, могу ли я тебя побеспокоить для еще одного задания? Моя дочь, славный командир часовых Лиалия, отказывается выпускать меня в поле.$b$bКаждый день в той темнице я смотрел на руины на севере и мне не терпелось начать исследования.$b$bЕсли мы там, где я думаю, то в этих руинах может скрываться ключ к местонахождению легендарного Пруда Молодости!$b$bПрошу тебя, |3-6($c)! Сходи к руинам и собери там любые таблички, на которых еще сохранились записи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 династийных табличек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Восхитительно! Восхитительно!$B$BОдин твой поход помог моим изысканиям больше, чем десять лет изучения пыльных книг и распадающихся свитков.$B$BА эти "могу", которых ты видел... Я провел по этому поводу кое-какие исследования и поговорил с Каном.$B$BТеперь я подозреваю, что мы имеем дело с расой времен исчезнувших династий, которые я и изучаю.$B$BРазумеется, отсюда следует и то, что именно они в прошлом владели Прудом Молодости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Изучать исчезнувшие династии по книгам – это одно, а осматривать древние руины – совсем другое.$B$BПрямо голова кружится от волнения, сотни лет уже такого не было!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30345,'Отрава!','Яд... Я... Я чувствую его... так жжет. Прошу тебя, $n... собери... собери клинки могу. Нам нужны... нужны образцы яда. Для проти... противо... противоядия.','Отберите 5 отравленных клинков могу у могу-разорителей из Забытой династии.','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрава!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яд... Я... Я чувствую его... так жжет. Прошу тебя, $n... собери... собери клинки могу. Нам нужны... нужны образцы яда. Для проти... противо... противоядия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 5 отравленных клинков могу у могу-разорителей из Забытой династии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином у Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30346,'Где же Пруд?','Возможно, эти могу знают, где находится пруд.$b$bНаши разведчики доложили, что видели вражеского командира на южной стороне Руин Доцзян.$b$bУбей его и забери все его записи. Возможно, они наведут тебя на след Пруда.','Заберите доцзянские приказы.','Мысли жреца соприкасаются с вашими.','Хранитель знаний Ваэлдрин','Мысли жреца соприкасаются с вашими.','Хранитель знаний Ваэлдрин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где же Пруд?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, эти могу знают, где находится пруд.$b$bНаши разведчики доложили, что видели вражеского командира на южной стороне Руин Доцзян.$b$bУбей его и забери все его записи. Возможно, они наведут тебя на след Пруда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите доцзянские приказы.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мысли жреца соприкасаются с вашими.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель знаний Ваэлдрин',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мысли жреца соприкасаются с вашими.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Хранитель знаний Ваэлдрин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30347,'Пруд Молодости','Север! Ты найдешь Пруд Молодости на севере. Набери там воды, но будь $gосторожен:осторожна;.$b$bМогу считают этот пруд своим "особо важным объектом". Если Кан Ежевичный Посох не прибыл с тобой, то он ждет тебя у пруда.','Наберите воды молодости.','Ничто так не пробуждает жажду деятельности, как неизбежность смерти.','Поговорите с хранителем знаний Ваэлдрином в Экспедиции ночных эльфов, что в Красарангских джунглях.','Жажда деятельности переполняет вас.','Хранитель знаний Ваэлдрин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пруд Молодости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Север! Ты найдешь Пруд Молодости на севере. Набери там воды, но будь $gосторожен:осторожна;.$b$bМогу считают этот пруд своим "особо важным объектом". Если Кан Ежевичный Посох не прибыл с тобой, то он ждет тебя у пруда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите воды молодости.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ничто так не пробуждает жажду деятельности, как неизбежность смерти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином в Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Жажда деятельности переполняет вас.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель знаний Ваэлдрин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30348,'Бессмертие?','Что-то... не так. Вода какая-то странная.$b$bКогда мы прибыли сюда, я ощущал присутствие Света, сильное и живое, где-то далеко на севере.$b$bЯ думал, что это и есть Пруд Молодости. Но вода... вода чем-то осквернена. Запятнана магией могу.$b$bДумаю, лучше мне ограничиться одним глотком и посмотреть, что получится.','Следите за тем, как Ваэлдрин попробует воду молодости.','Что... что случилось? Вода... она... она только передает жизнь. Новой жизни она не создает.','Поговорите с Ваэлдрином в Экспедиции ночных эльфов, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бессмертие?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то... не так. Вода какая-то странная.$b$bКогда мы прибыли сюда, я ощущал присутствие Света, сильное и живое, где-то далеко на севере.$b$bЯ думал, что это и есть Пруд Молодости. Но вода... вода чем-то осквернена. Запятнана магией могу.$b$bДумаю, лучше мне ограничиться одним глотком и посмотреть, что получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следите за тем, как Ваэлдрин попробует воду молодости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что... что случилось? Вода... она... она только передает жизнь. Новой жизни она не создает.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ваэлдрином в Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30349,'Угроза из Руин Доцзян','Пока ты $gстряхивал:стряхивала; пыль с табличек в руинах для моего отца, я уже потеряла пятерых разведчиков из-за патрулей могу.$b$bЭтим созданиям, как я вижу, мирный путь не интересен, и верить им можно не больше, чем Орде.$b$bК сожалению, их слишком много, а мы слишком слабы.$b$bИди в руины, что к западу отсюда, и убей там побольше могу. Вряд ли они ожидают встретить |3-3($c).','Убейте 6 искателей из Доцзяна, 8 разведчиков из Доцзяна и 4 головореза из Доцзяна.','Отлично, Алоиза. Еще несколько таких успешных заданий, и нам останется лишь произвести тебя в почетные часовые.','Поговорите с часовой Лиалией в Экспедиции ночных эльфов, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза из Руин Доцзян',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gстряхивал:стряхивала; пыль с табличек в руинах для моего отца, я уже потеряла пятерых разведчиков из-за патрулей могу.$b$bЭтим созданиям, как я вижу, мирный путь не интересен, и верить им можно не больше, чем Орде.$b$bК сожалению, их слишком много, а мы слишком слабы.$b$bИди в руины, что к западу отсюда, и убей там побольше могу. Вряд ли они ожидают встретить |3-3($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 искателей из Доцзяна, 8 разведчиков из Доцзяна и 4 головореза из Доцзяна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Алоиза. Еще несколько таких успешных заданий, и нам останется лишь произвести тебя в почетные часовые.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с часовой Лиалией в Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30350,'Извивающийся деликатес','Тайный мастер может и подождать. Ты посмотри на этот народ, $n.$b$BОни такие тощие! Голодают, не иначе.$b$bЗнаешь, что нам нужно? Большая дымящаяся миска извивающегося деликатеса.$b$bЕсли будешь проходить мимо реки, попробуй собрать целые железы быстролапов, а я приготовлю эту похлебку.','Соберите 5 целых желез быстролапов.','Ха! Теперь я смогу приготовить такую похлебку, что эти похожие на бездомных эльфы с ног попадают!','Мама Ежевичный Посох всегда говорила, что извивающийся деликатес так или иначе избавит от любого голода.','Поговорите с Каном Ежевичным Посохом в Экспедиции ночных эльфов в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Извивающийся деликатес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тайный мастер может и подождать. Ты посмотри на этот народ, $n.$b$BОни такие тощие! Голодают, не иначе.$b$bЗнаешь, что нам нужно? Большая дымящаяся миска извивающегося деликатеса.$b$bЕсли будешь проходить мимо реки, попробуй собрать целые железы быстролапов, а я приготовлю эту похлебку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 целых желез быстролапов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Теперь я смогу приготовить такую похлебку, что эти похожие на бездомных эльфы с ног попадают!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мама Ежевичный Посох всегда говорила, что извивающийся деликатес так или иначе избавит от любого голода.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каном Ежевичным Посохом в Экспедиции ночных эльфов в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30351,'Лотосовый чай','Что и говорить, могу знают толк в ядах и проклятиях. Мама Ежевичный Посох всегда говорила – лотосовый чай снимет любое проклятие могу.$b$bЯ видел, что в Руинах Доцзян неподалеку отсюда растут императорские лотосы. Надо собрать их листья и держать их под рукой на случай, если могу начнут буянить.$b$bЗаодно у моих кулаков будет шанс познакомиться с их лицами.','Соберите 20 листьев имперского лотоса.','Вот так! Ты выбираешь, я бью!','Впервые вижу сразу столько могу. Они всегда досаждали нам, но теперь и вправду опасны.','Поговорите с Каном Ежевичным Посохом в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лотосовый чай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что и говорить, могу знают толк в ядах и проклятиях. Мама Ежевичный Посох всегда говорила – лотосовый чай снимет любое проклятие могу.$b$bЯ видел, что в Руинах Доцзян неподалеку отсюда растут императорские лотосы. Надо собрать их листья и держать их под рукой на случай, если могу начнут буянить.$b$bЗаодно у моих кулаков будет шанс познакомиться с их лицами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 листьев имперского лотоса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так! Ты выбираешь, я бью!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Впервые вижу сразу столько могу. Они всегда досаждали нам, но теперь и вправду опасны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каном Ежевичным Посохом в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30352,'Охота на журавля','Для охоты на птиц нужны патроны, а у меня их нет. А при охоте с Эрнестуэем тебе нужно доказать, что ты хвастаешься сообразно трофеям.$b$bНе умеешь охотиться – не хвались. А я люблю хвастовство, так что это нехорошо!$b$bМогу ли я нанять тебя, чтобы убить нескольких ловцов карпов? Ты найдешь их вверх и вниз по реке, что к западу отсюда. Их там полно, так что не стесняйся охотиться, пока занят другими делами.','Убейте 12 ловцов карпов.','Невероятно. Есть только одна вещь, которая могла бы сделать эту поездку на охоту еще более забавной – кресло. Вот награда, которую я обещала.','Поговорите с Даггл Бомбстер в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на журавля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для охоты на птиц нужны патроны, а у меня их нет. А при охоте с Эрнестуэем тебе нужно доказать, что ты хвастаешься сообразно трофеям.$b$bНе умеешь охотиться – не хвались. А я люблю хвастовство, так что это нехорошо!$b$bМогу ли я нанять тебя, чтобы убить нескольких ловцов карпов? Ты найдешь их вверх и вниз по реке, что к западу отсюда. Их там полно, так что не стесняйся охотиться, пока занят другими делами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 ловцов карпов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно. Есть только одна вещь, которая могла бы сделать эту поездку на охоту еще более забавной – кресло. Вот награда, которую я обещала.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30353,'Охота за наживой','Два слова: тигриная кровь!$b$bНа черном рынке она будет расходиться быстрее саронита. Особенно когда я пущу повсюду слух о всяких ее полезных свойствах.$b$bИ эти джунгли просто кишат тиграми. Не наберешь мне несколько пузырьков тигриной крови? А я тебя в долю возьму.','Соберите 12 сосудов тигриной крови.','Отлично! Это сделает приятным мое возвращение в Калимдор. Вот твоя доля.','Я люблю охотиться с Эрнестуэем, но он это делает ради охоты, а я – ради наживы, и с него нет навара.','Поговорите с Даггл Бомбстер в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за наживой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Два слова: тигриная кровь!$b$bНа черном рынке она будет расходиться быстрее саронита. Особенно когда я пущу повсюду слух о всяких ее полезных свойствах.$b$bИ эти джунгли просто кишат тиграми. Не наберешь мне несколько пузырьков тигриной крови? А я тебя в долю возьму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 сосудов тигриной крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это сделает приятным мое возвращение в Калимдор. Вот твоя доля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я люблю охотиться с Эрнестуэем, но он это делает ради охоты, а я – ради наживы, и с него нет навара.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30354,'Своих не бросаем','Мы обыскивали руины к югу отсюда, когда могу свалились на нас из ниоткуда.$b$bКое-кому из нас удалось отступить в этот лагерь, но многие попали в плен. Еще могу захватили воинов Орды, которым повезло там оказаться.$b$bПожалуйста, $n, спаси всех часовых, каких только сможешь.$b$bА Служителей Солнца предоставь их судьбе.','Спасите 8 пленников могу.','Нас так мало... Твоя помощь как нельзя кстати.','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своих не бросаем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обыскивали руины к югу отсюда, когда могу свалились на нас из ниоткуда.$b$bКое-кому из нас удалось отступить в этот лагерь, но многие попали в плен. Еще могу захватили воинов Орды, которым повезло там оказаться.$b$bПожалуйста, $n, спаси всех часовых, каких только сможешь.$b$bА Служителей Солнца предоставь их судьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 пленников могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нас так мало... Твоя помощь как нельзя кстати.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30355,'Кто-то теряет, кто-то находит','Могу не пользуются магией.$b$b.Они – бандиты. И всегда ими были. Лишь в старые времена, когда они правили своими империями, им была известна магия.$b$bНо эти могу используют волшебные порталы и старинные артефакты. Их надо остановить!$b$b$n, поищи артефакты, с помощью которых могу творят свою магию. Я видел груды этих вещиц собирают в Руинах Корцзя, что к югу отсюда.','Соберите 10 артефактов могу.','Отлично, Алоиза. Спички детям не игрушка.','Каждый отобранный нами артефакт – серьезный удар по могу.','Поговорите с Каном Ежевичным Посохом в Лагере Часовых, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто-то теряет, кто-то находит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу не пользуются магией.$b$b.Они – бандиты. И всегда ими были. Лишь в старые времена, когда они правили своими империями, им была известна магия.$b$bНо эти могу используют волшебные порталы и старинные артефакты. Их надо остановить!$b$b$n, поищи артефакты, с помощью которых могу творят свою магию. Я видел груды этих вещиц собирают в Руинах Корцзя, что к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 артефактов могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Алоиза. Спички детям не игрушка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Каждый отобранный нами артефакт – серьезный удар по могу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каном Ежевичным Посохом в Лагере Часовых, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30356,'Перерезать линии снабжения','Искатели могу используют порталы, чтобы доставить к себе подкрепления и припасы с вершины Кунь-Лай.$b$bХуже того, через эти же порталы они отправляют пленных.$b$bИди к Руинам Корцзя и убей там как можно больше искателей из Корцзя.','Убейте 8 искателей из Корцзя.','Ты выиграл нам время, теперь мы сможем зализать раны и подготовить ответный удар.','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перерезать линии снабжения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Искатели могу используют порталы, чтобы доставить к себе подкрепления и припасы с вершины Кунь-Лай.$b$bХуже того, через эти же порталы они отправляют пленных.$b$bИди к Руинам Корцзя и убей там как можно больше искателей из Корцзя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 искателей из Корцзя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты выиграл нам время, теперь мы сможем зализать раны и подготовить ответный удар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30357,'Посланники Каменного Плуга','Помоги мне, $n. Этих бедных пандаренов надо вылечить, а мои силы истощены.$b$bЯ нашел в своей библиотеке старую книгу, которая позволит мне изготовить из добытых тобой листьев целебные припарки.$b$bПолечи ими раненых пандаренов, поставь больных на ноги.','Поговорите с хранителем знаний Ваэлдрином у Разбитого конвоя, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланники Каменного Плуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги мне, $n. Этих бедных пандаренов надо вылечить, а мои силы истощены.$b$bЯ нашел в своей библиотеке старую книгу, которая позволит мне изготовить из добытых тобой листьев целебные припарки.$b$bПолечи ими раненых пандаренов, поставь больных на ноги.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином у Разбитого конвоя, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30358,'Конец грифонам','"Кулак Гарроша" будет удерживать гавань, пока со всеми остальными угрозами с суши не будет покончено.$B$BТвоя следующая цель: Бальдрук, укротитель грифонов Терамора. Нельзя позволить этому безумному дворфу и его бестиям атаковать корабль сверху.$B$BУбей Бальдрука и его крылатых питомцев.','Убейте Бальдрука и его грифонов.','Нельзя позволить Бальдруку напасть на корабль сверху.','Укротитель грифонов Бальдрук','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец грифонам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Кулак Гарроша" будет удерживать гавань, пока со всеми остальными угрозами с суши не будет покончено.$B$BТвоя следующая цель: Бальдрук, укротитель грифонов Терамора. Нельзя позволить этому безумному дворфу и его бестиям атаковать корабль сверху.$B$BУбей Бальдрука и его крылатых питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бальдрука и его грифонов.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нельзя позволить Бальдруку напасть на корабль сверху.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Укротитель грифонов Бальдрук',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Покоритель небес Рев Бури',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30359,'Главный Искатель','У них моя дочь! Брожай... этот Главный Искатель! Я ясно вижу его глазами Лиалии.$b$bБезрассудная девчонка пыталась добыть его голову.$b$bПрошу тебя, $n! Отправляйся к Руинам Корцзя и постарайся найти ее.$b$bЯ приведу Кана и попробую выманить Брожая из руин.','Найдите Лиалию и убейте Первопроходца Брожая.','Спасибо, что отомстил за мою дочь. Она недолго останется мертвой.$B$BУ меня все еще есть вода молодости.','Поговорите с хранителем знаний Ваэлдрином в Лагере Часовых в Красарангских джунглях.','Главный Искатель','Первопроходец Брожай') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный Искатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У них моя дочь! Брожай... этот Главный Искатель! Я ясно вижу его глазами Лиалии.$b$bБезрассудная девчонка пыталась добыть его голову.$b$bПрошу тебя, $n! Отправляйся к Руинам Корцзя и постарайся найти ее.$b$bЯ приведу Кана и попробую выманить Брожая из руин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Лиалию и убейте Первопроходца Брожая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что отомстил за мою дочь. Она недолго останется мертвой.$B$BУ меня все еще есть вода молодости.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем знаний Ваэлдрином в Лагере Часовых в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Главный Искатель',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Первопроходец Брожай',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30360,'Предупредить Каменный Плуг','Отец отдал за меня свою жизнь, Тиранда облекла своим доверием. Часовые поклялись мне в верности.$b$bПора отплатить им добром.$b$bСо смертью Брожая мы сможем прикончить оставшихся могу. Но есть и новая угроза – богомолы.$b$bОтправляйся на север, в Каменный Плуг, и предложи там свою помощь. Скажи им, что я приведу всех часовых, каких смогу собрать, чтобы защитить их жилища от богомолов.','Богомолы на юге? Не к добру это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупредить Каменный Плуг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отец отдал за меня свою жизнь, Тиранда облекла своим доверием. Часовые поклялись мне в верности.$b$bПора отплатить им добром.$b$bСо смертью Брожая мы сможем прикончить оставшихся могу. Но есть и новая угроза – богомолы.$b$bОтправляйся на север, в Каменный Плуг, и предложи там свою помощь. Скажи им, что я приведу всех часовых, каких смогу собрать, чтобы защитить их жилища от богомолов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Богомолы на юге? Не к добру это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30361,'Богомолы','Богомолы! Они явились из ниоткуда и разнесли нашу колонну вдребезги, выжившие разбежались кто куда.$b$bТеперь они готовятся напасть на Каменный Плуг.$b$bПрошу тебя, |3-6($c), уничтожь этих чудовищ, пока они не собрали целое войско для штурма.$b$bЕсли мой брат, посланник Лен, уцелел в этой бойне, он вознаградит тебя за помощь.','Убейте 10 богомолов ик\'тиков.','Поговорите с посланником Леном у Разбитого конвоя в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богомолы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы! Они явились из ниоткуда и разнесли нашу колонну вдребезги, выжившие разбежались кто куда.$b$bТеперь они готовятся напасть на Каменный Плуг.$b$bПрошу тебя, |3-6($c), уничтожь этих чудовищ, пока они не собрали целое войско для штурма.$b$bЕсли мой брат, посланник Лен, уцелел в этой бойне, он вознаградит тебя за помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 богомолов ик\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с посланником Леном у Разбитого конвоя в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30362,'Танкобойня','Последняя угроза воздушному судну – тераморский арсенал паровых танков.$B$BУничтожь все работающие танки и заложи бомбы в те из них, которые никем не управляются.','Уничтожьте все управляемые танки и заложите бомбы во все остальные.','Уничтожьте Большую Бессу!','Большая Бесса','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танкобойня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последняя угроза воздушному судну – тераморский арсенал паровых танков.$B$BУничтожь все работающие танки и заложи бомбы в те из них, которые никем не управляются.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте все управляемые танки и заложите бомбы во все остальные.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Уничтожьте Большую Бессу!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Большая Бесса',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Покоритель небес Рев Бури',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30363,'Переход в наступление','Ха! Выходит, мой отец истратил двадцать лет нашей жизни на бесполезную затею!$b$bТеперь власть в моих руках.$b$bКогда Тиранда отправила нас сюда, она строго наказала нам не возвращаться, пока мы не найдем источник Света, который грезился ей в видениях. Теперь понятно, что это был не Пруд Молодости.$b$bЯ хочу, чтобы ты $gнашел:нашла; мою дозорную. Я отправила ее осмотреть Храм Журавля, но она до сих пор не вернулась.$b$bПоговори с ней и отправляйся к нам в Лагерь Часовых, что к западу отсюда.','Выслушайте доклад часового экспедиции.','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переход в наступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха! Выходит, мой отец истратил двадцать лет нашей жизни на бесполезную затею!$b$bТеперь власть в моих руках.$b$bКогда Тиранда отправила нас сюда, она строго наказала нам не возвращаться, пока мы не найдем источник Света, который грезился ей в видениях. Теперь понятно, что это был не Пруд Молодости.$b$bЯ хочу, чтобы ты $gнашел:нашла; мою дозорную. Я отправила ее осмотреть Храм Журавля, но она до сих пор не вернулась.$b$bПоговори с ней и отправляйся к нам в Лагерь Часовых, что к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте доклад часового экспедиции.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30364,'Лети, шпион!','"Кулак Гарроша" сровняет остров Терамор с землей... Но не раньше, чем мы освободим шпиона, благодаря которому вообще стала возможна вся эта операция.$B$BВойди в Цитадель и убей капитана Ровноступа – у него ключи от кандалов.$B$BНашего шпиона Талена Созвучие Песни, мага Похитителей Солнца, держат в бараках.','Убейте Хедрика Ровноступа и освободите Талена Созвучие Песни из Цитадели.','Войдите в Опорную Цитадель и освободите шпиона Орды.','Тален Созвучие Песни','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лети, шпион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Кулак Гарроша" сровняет остров Терамор с землей... Но не раньше, чем мы освободим шпиона, благодаря которому вообще стала возможна вся эта операция.$B$BВойди в Цитадель и убей капитана Ровноступа – у него ключи от кандалов.$B$BНашего шпиона Талена Созвучие Песни, мага Похитителей Солнца, держат в бараках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хедрика Ровноступа и освободите Талена Созвучие Песни из Цитадели.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Войдите в Опорную Цитадель и освободите шпиона Орды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тален Созвучие Песни',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetna