INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30375,'Морские змеи','Реки здесь просто кишат ядовитыми змеями. Эти змеи покусали тех, кто бежал из храма, и кое-кто из укушенных уже серьезно болен.$b$bМы стараемся как можно быстрее ввести всем противоядие, но нам нужны еще ядовитые железы.$b$bЯ не стану просить тебя вырезать эти железы на месте – слишком много времени уйдет. Лучше принеси мне головы, а я позабочусь об остальном.','Соберите 6 голов темночешуйчатых жаленей, которые водятся в реке Красаранг.','Вернитесь к Андуину Ринну в Укрытие Красного Крыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морские змеи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Реки здесь просто кишат ядовитыми змеями. Эти змеи покусали тех, кто бежал из храма, и кое-кто из укушенных уже серьезно болен.$b$bМы стараемся как можно быстрее ввести всем противоядие, но нам нужны еще ядовитые железы.$b$bЯ не стану просить тебя вырезать эти железы на месте – слишком много времени уйдет. Лучше принеси мне головы, а я позабочусь об остальном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 голов темночешуйчатых жаленей, которые водятся в реке Красаранг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андуину Ринну в Укрытие Красного Крыла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30376,'Надежда умирает последней','Поговорите с Лун Маем в Каменном Плуге.','Наконец-то, хорошие новости. Я сейчас же пошлю сокола в Лагерь Зимнего Цветения с вестью, что Храм Красного Журавля теперь в безопасности.$B$BНам сложно одновременно сражаться с ша и воинственными богомолами.','Поговорите с Лун Маем в Каменном Плуге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежда умирает последней',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лун Маем в Каменном Плуге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то, хорошие новости. Я сейчас же пошлю сокола в Лагерь Зимнего Цветения с вестью, что Храм Красного Журавля теперь в безопасности.$B$BНам сложно одновременно сражаться с ша и воинственными богомолами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лун Маем в Каменном Плуге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30377,'Безопасное расстояние','Как только ты со своими спутниками будешь вне опасности, мы сбросим бомбы и не оставим на острове Терамор камня на камне.$B$BКак можно быстрее вернись на "Морской волк" и поговори с капитаном Дроком.','Вернитесь на "Морской волк" и поговорите с капитаном Дроком.','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безопасное расстояние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только ты со своими спутниками будешь вне опасности, мы сбросим бомбы и не оставим на острове Терамор камня на камне.$B$BКак можно быстрее вернись на "Морской волк" и поговори с капитаном Дроком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь на "Морской волк" и поговорите с капитаном Дроком.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Покоритель небес Рев Бури',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Покоритель небес Рев Бури',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30378,'Подрывник','Соберитесь у входа в гавань, чтобы сообщить подрывнику Бомбастеру о своем успехе.$B$BОн подорвет бочки с порохом и даст воздушному судну сигнал идти вперед.$B$BПроверьте, чтоб никто из группы не остался на кораблях, когда они взлетят на воздух!','Сообщите подрывнику Бомбастеру у входа в гавань, что бочки с порохом заложены.','Подрывник Бомбастер взорвет корабли и направит воздушное судно по вашей отметке.','Подрывник Бомбастер','Командующий операцией и капитан воздушного судна "Кулак Гарроша".','Покоритель небес Рев Бури') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подрывник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Соберитесь у входа в гавань, чтобы сообщить подрывнику Бомбастеру о своем успехе.$B$BОн подорвет бочки с порохом и даст воздушному судну сигнал идти вперед.$B$BПроверьте, чтоб никто из группы не остался на кораблях, когда они взлетят на воздух!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите подрывнику Бомбастеру у входа в гавань, что бочки с порохом заложены.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Подрывник Бомбастер взорвет корабли и направит воздушное судно по вашей отметке.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Подрывник Бомбастер',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Командующий операцией и капитан воздушного судна "Кулак Гарроша".',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Покоритель небес Рев Бури',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30379,'Рубиновый осколок для Джины','Вот это да! Ничего себе камень!$B$BЕще несколько подарков в таком духе, и мне работать не придется!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рубиновый осколок для Джины',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Ничего себе камень!$B$BЕще несколько подарков в таком духе, и мне работать не придется!',`offerrewardtext_loc8`);
