INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30384,'Ослепить их!','Служители Солнца из Орды! Мы недавно видели, как их разведчик околачивался рядом с темницей.$b$bНе знаю, как он туда попал, но точно знаю – он там не один. Они всегда ходят вместе.$b$bУбей разведчика Служителей Солнца, пока он не сообщил врагам, где мы находимся.','Убейте разведчика Служителей Солнца.','Служители Солнца отнюдь не безобидны. Из всех тауренов они самые воинственные.$B$BСпасибо тебе за помощь, Алоиза. Прошу, прими эту награду.','Поговорите с командиром Лиалией в Экспедиции ночных эльфов, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепить их!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Солнца из Орды! Мы недавно видели, как их разведчик околачивался рядом с темницей.$b$bНе знаю, как он туда попал, но точно знаю – он там не один. Они всегда ходят вместе.$b$bУбей разведчика Служителей Солнца, пока он не сообщил врагам, где мы находимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте разведчика Служителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Служители Солнца отнюдь не безобидны. Из всех тауренов они самые воинственные.$B$BСпасибо тебе за помощь, Алоиза. Прошу, прими эту награду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Лиалией в Экспедиции ночных эльфов, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30385,'Гарнизон Заходящего Солнца','Прими мою искреннюю благодарность за помощь. Аньцзи ждет тебя в Гарнизоне Заходящего Солнца, это к западу отсюда.$B$BДа осенит тебя удача, $gюный:юная:c; |3-6($c).','Поговорите с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гарнизон Заходящего Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прими мою искреннюю благодарность за помощь. Аньцзи ждет тебя в Гарнизоне Заходящего Солнца, это к западу отсюда.$B$BДа осенит тебя удача, $gюный:юная:c; |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца.',`objectives_loc8`);
