INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30443,'Никаких служителей солнца','Таурены!$b$bЯ не дам этим блохастым зверям наложить лапы на Пруд Молодости. Никто в Орде не заслуживает бессмертия. Все они по природе своей смертные, которым недостает скромности и умения жить в обществе долгожителей.$b$bПруд сейчас разыскивают вражеские шпионы. Убей их, пока они его не нашли. Шпионов немного, так что лишить врага глаз и ушей тебе будет просто.','Убейте 3 служителей солнца – шпионов.','Поговорите с Ваэлдрином у Экспедиции ночных эльфов в Красарангских джунглях.','Его мысли заполняют ваш разум.','Хранитель знаний Ваэлдрин','Его мысли проникают в ваше сознание.','Хранитель знаний Ваэлдрин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никаких служителей солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таурены!$b$bЯ не дам этим блохастым зверям наложить лапы на Пруд Молодости. Никто в Орде не заслуживает бессмертия. Все они по природе своей смертные, которым недостает скромности и умения жить в обществе долгожителей.$b$bПруд сейчас разыскивают вражеские шпионы. Убей их, пока они его не нашли. Шпионов немного, так что лишить врага глаз и ушей тебе будет просто.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 служителей солнца – шпионов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ваэлдрином у Экспедиции ночных эльфов в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его мысли заполняют ваш разум.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель знаний Ваэлдрин',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Его мысли проникают в ваше сознание.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Хранитель знаний Ваэлдрин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30444,'Без передышки','У нас наметилась передышка. Могу собрались около Пяти Сестер к северу от нас, собираются с силами, перегруппируются. Попробуй помешать им.$B$BНе щади никого.','Убейте 8 могу Шао-Тень около Пяти Сестер.','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Без передышки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас наметилась передышка. Могу собрались около Пяти Сестер к северу от нас, собираются с силами, перегруппируются. Попробуй помешать им.$B$BНе щади никого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 могу Шао-Тень около Пяти Сестер.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Гарнизон Заходящего Солнца в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30445,'Вода молодости','Моя маленькая Лиалия такая своевольная. Я должен был догадаться, что она захочет сразиться с Главным Искателем.$b$bКогда умерла ее мать, я столько времени провел в поисках бессмертия, а ведь мог бы больше быть с ней. Но я настоял на своем, говорил, что мы сможем жить вечно... вместе.$b$bИ теперь моя одержимость стоила маленькой Лиалии жизни.$b$bПрошу тебя, $n, когда она проснется, скажи ей, что я ее люблю.','Передайте Лиалии слова Ваэлдрина.','Он... не должен был так поступать! Не должен был платить за мои ошибки!','Поговорите с командиром Лиалией в Лагере Часовых, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вода молодости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя маленькая Лиалия такая своевольная. Я должен был догадаться, что она захочет сразиться с Главным Искателем.$b$bКогда умерла ее мать, я столько времени провел в поисках бессмертия, а ведь мог бы больше быть с ней. Но я настоял на своем, говорил, что мы сможем жить вечно... вместе.$b$bИ теперь моя одержимость стоила маленькой Лиалии жизни.$b$bПрошу тебя, $n, когда она проснется, скажи ей, что я ее люблю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте Лиалии слова Ваэлдрина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он... не должен был так поступать! Не должен был платить за мои ошибки!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Лиалией в Лагере Часовых, что в Красарангских джунглях.',`completedtext_loc8`);
