INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30457,'Бросить вызов предводителю','Герой здесь и поможет нам!$B$BПеребей яунголов на Куньлайской дороге на северо-западе – этим мы хотим разозлить их военачальника. Как только он появится, отправь его к праотцам.','Убейте 10 яунголов на Куньлайской дороге. После этого появится яунгол-военачальник. Убейте его.','Когда военачальник яунголов будет убит, наши деревни будут в безопасности и беженцы смогут вернуться на свои фермы.','Вернитесь к мэру Ежевичному Посоху в деревню Бинан на вершине Кунь-Лай.','Убейте 10 яунголов из племени Батаари, чтобы разъярить его и заставить появиться. Затем убейте его!','Батаарский огненный воин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бросить вызов предводителю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Герой здесь и поможет нам!$B$BПеребей яунголов на Куньлайской дороге на северо-западе – этим мы хотим разозлить их военачальника. Как только он появится, отправь его к праотцам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 яунголов на Куньлайской дороге. После этого появится яунгол-военачальник. Убейте его.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда военачальник яунголов будет убит, наши деревни будут в безопасности и беженцы смогут вернуться на свои фермы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мэру Ежевичному Посоху в деревню Бинан на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте 10 яунголов из племени Батаари, чтобы разъярить его и заставить появиться. Затем убейте его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Батаарский огненный воин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30458,'Возвращение разведчиков','$n, твои друзья вернулись из разведки и хотят немедленно тебя видеть!$B$BБоюсь, что...$B$BХотя, пожалуй, не стоит опережать события. Ты $gсам:сама; все увидишь.','Поговорите с Реллом Ночным Ветром в Деревне Жемчужного Плавника в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение разведчиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твои друзья вернулись из разведки и хотят немедленно тебя видеть!$B$BБоюсь, что...$B$BХотя, пожалуй, не стоит опережать события. Ты $gсам:сама; все увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Реллом Ночным Ветром в Деревне Жемчужного Плавника в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30459,'Все стрелы','Как только к яунголам прибудет подкрепление, у нас не останется шансов на победу. В таком случае деревня будет потеряна.$B$BСобери с поля боя как можно больше стрел, ладно? У меня есть план, который может спасти нас, если ты поможешь.','Соберите 12 стрел для командира Се.','Вернитесь к командиру Се, находящейся на Куньлайской дороге, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все стрелы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только к яунголам прибудет подкрепление, у нас не останется шансов на победу. В таком случае деревня будет потеряна.$B$BСобери с поля боя как можно больше стрел, ладно? У меня есть план, который может спасти нас, если ты поможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 стрел для командира Се.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Се, находящейся на Куньлайской дороге, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30460,'Сила врачевания','Наши воины доблестно сражаются, удерживая яунголов на Куньлайской дороге к северо-западу отсюда.$B$BВозьми эту жидкую мазь. Это – очень сильное лекарство, рецепт которого передавался в нашей семье от поколения к поколению.$B$BИспользуй дит да джоу, чтобы залечить раны пострадавших бойцов, если ты не владеешь искусством исцеления $gсам:сама;.','Используйте дит да джоу или собственные способности к исцелению, чтобы помочь восьми раненым воинам из деревни Бинан.','Вернитесь к Аптекарю Чэн в деревню Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила врачевания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши воины доблестно сражаются, удерживая яунголов на Куньлайской дороге к северо-западу отсюда.$B$BВозьми эту жидкую мазь. Это – очень сильное лекарство, рецепт которого передавался в нашей семье от поколения к поколению.$B$BИспользуй дит да джоу, чтобы залечить раны пострадавших бойцов, если ты не владеешь искусством исцеления $gсам:сама;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте дит да джоу или собственные способности к исцелению, чтобы помочь восьми раненым воинам из деревни Бинан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Чэн в деревню Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30461,'Вперед, в глушь','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победила ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в глушь',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победила ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30462,'Вперед, в глушь','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победила ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в глушь',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно... И ша уже расползлись по всей провинции, ведь так?$B$BЖаль тебя огорчать, но они уже наводнили и храм. Те из нас, кто не погиб или не стал... одержимым, спасаются бегством.$B$BНо раз ты победила ша в Дозоре Чжу, я прошу тебя помочь нам и здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30464,'На запад','Леза теперь вместе с предками, что жили на этой странной земле. Я же должен позаботиться о живых.$b$bКор отправился с отрядом разведчиков на запад, дальше в джунгли.$b$bНайди его и помоги, чем сможешь. Мы присоединимся к вам сразу, как только освободимся.','Отправляйтесь в Укрытие Искателей Зари.','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На запад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леза теперь вместе с предками, что жили на этой странной земле. Я же должен позаботиться о живых.$b$bКор отправился с отрядом разведчиков на запад, дальше в джунгли.$b$bНайди его и помоги, чем сможешь. Мы присоединимся к вам сразу, как только освободимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Укрытие Искателей Зари.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кором Кровавым Бивнем в Укрытии Искателей Зари в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30465,'Переход в наступление','Ха! Выходит, мой отец истратил двадцать лет нашей жизни на бесполезную затею!$b$bТеперь власть в моих руках.$b$bКогда Тиранда отправила нас сюда, она строго наказала нам не возвращаться, пока мы не найдем источник Света, который грезился ей в видениях. Теперь понятно, что это был не Пруд Молодости.$b$bМы продвигаемся на запад, и нам пригодилась бы твоя помощь.$b$bНайди нас в Лагере Часовых, что к западу отсюда, когда будешь $gготов:готова;.','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.','Алоиза, ты, как обычно, вовремя. Оказалось, могу тоже знают, как пользоваться порталами.','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переход в наступление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха! Выходит, мой отец истратил двадцать лет нашей жизни на бесполезную затею!$b$bТеперь власть в моих руках.$b$bКогда Тиранда отправила нас сюда, она строго наказала нам не возвращаться, пока мы не найдем источник Света, который грезился ей в видениях. Теперь понятно, что это был не Пруд Молодости.$b$bМы продвигаемся на запад, и нам пригодилась бы твоя помощь.$b$bНайди нас в Лагере Часовых, что к западу отсюда, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Алоиза, ты, как обычно, вовремя. Оказалось, могу тоже знают, как пользоваться порталами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лиалией в Лагере Часовых в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30466,'Достаточная мотивация','Обучать этих дикарей – то еще удовольствие.$B$BЗаинтересовать их просто – вся штука в том, чтобы они не теряли этот интерес... не отвлекались... и не засыпали.$B$BРаз уж ты все равно здесь, то помоги мне "подбодрить" недисциплинированных хозенов. Ну, ты понимаешь. Метод выбирай $gсам:сама;.','Мотивируйте 10 ленивых хозенов.','Хм-м, знаешь, Эрезул, я удивлюсь, если мы сможем заставить их сосредоточиться настолько, чтобы вообще применить хоть какую-нибудь тактику.$B$BКогда зазвенят клинки, пусть лучше не попадаются у меня на пути!','Хозены готовы к бою?','Вернитесь к генералу Назгриму на холм Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достаточная мотивация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обучать этих дикарей – то еще удовольствие.$B$BЗаинтересовать их просто – вся штука в том, чтобы они не теряли этот интерес... не отвлекались... и не засыпали.$B$BРаз уж ты все равно здесь, то помоги мне "подбодрить" недисциплинированных хозенов. Ну, ты понимаешь. Метод выбирай $gсам:сама;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мотивируйте 10 ленивых хозенов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм-м, знаешь, Эрезул, я удивлюсь, если мы сможем заставить их сосредоточиться настолько, чтобы вообще применить хоть какую-нибудь тактику.$B$BКогда зазвенят клинки, пусть лучше не попадаются у меня на пути!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хозены готовы к бою?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму на холм Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30467,'Мой сын...','Мой сын... ты можешь разыскать его?\r\n\r\nКогда цзинь-юй напали, он испугался и убежал. Я не знаю, что они с ним сделали, я даже не знаю, жив ли он!\r\n\r\nМоя жизнь потеряет смысл, если я не разыщу его.\r\n\r\nЯ бы попросил Мэй, но с ней что-то не так. Она слишком... вспыльчивая после нападения. Не уверен, что она вернет его в целости и сохранности.','Это так ужасно... Когда началась резня, я просто убежал. Мой отец, Мэй – они живы?','Спасите У-Пэна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мой сын...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой сын... ты можешь разыскать его?\r\n\r\nКогда цзинь-юй напали, он испугался и убежал. Я не знаю, что они с ним сделали, я даже не знаю, жив ли он!\r\n\r\nМоя жизнь потеряет смысл, если я не разыщу его.\r\n\r\nЯ бы попросил Мэй, но с ней что-то не так. Она слишком... вспыльчивая после нападения. Не уверен, что она вернет его в целости и сохранности.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это так ужасно... Когда началась резня, я просто убежал. Мой отец, Мэй – они живы?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Спасите У-Пэна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30468,'Ярость и возмездие','<Мастер клинков плохо выглядит. Ее глаза вдруг потемнели, что так не похоже на пандаренов.>$b$bДумаю, я еще никогда в своей жизни не была так... взбешена!$b$bЯ отразила их атаку, при этом убив нескольких врагов, а тщедушный торговец Ши не позволяет мне закончить начатое!$b$bСделай это за меня! Убей их! Прикончи их всех!','Убейте 15 разъяренных цзинь-юй.','Приятно слышать, что враг повержен. Возможно, тебе пригодится оружие моего телохранителя.','Вернитесь к мастеру клинков Мэй, которая ждет у Озера Чернильной Жабры на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость и возмездие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мастер клинков плохо выглядит. Ее глаза вдруг потемнели, что так не похоже на пандаренов.>$b$bДумаю, я еще никогда в своей жизни не была так... взбешена!$b$bЯ отразила их атаку, при этом убив нескольких врагов, а тщедушный торговец Ши не позволяет мне закончить начатое!$b$bСделай это за меня! Убей их! Прикончи их всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 разъяренных цзинь-юй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно слышать, что враг повержен. Возможно, тебе пригодится оружие моего телохранителя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру клинков Мэй, которая ждет у Озера Чернильной Жабры на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30469,'Возврат собственности','Конечно же, главная задача – поиски моего сына. Но чего мы добились? Разве мы спаслись ради того, чтобы теперь умереть от голода?\r\n\r\nПожалуйста, помоги нам вернуть часть припасов, которые цзинь-юй украли из каравана.','Найдите 8 украденных припасов.','Спасибо! По крайней мере, теперь у нас есть еда.','Вернитесь к торговцу Ши на Озеро Чернильной Жабры, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возврат собственности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно же, главная задача – поиски моего сына. Но чего мы добились? Разве мы спаслись ради того, чтобы теперь умереть от голода?\r\n\r\nПожалуйста, помоги нам вернуть часть припасов, которые цзинь-юй украли из каравана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 украденных припасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо! По крайней мере, теперь у нас есть еда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Ши на Озеро Чернильной Жабры, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30470,'Подарок для Тины','Сегодня Тина Грязный Коготь пришла на рынок Полугорья навестить сестру. Она такая замечательная, но ей сложно придумать подарок!$b$bВ горах на севере можно найти самоцвет под названием "хризоберилл" – он меняет цвет, когда берешь его в руки. Готов спорить, что такого камня у нее нет!$b$bПосмотри в пещерах гну-синей. Думаю, ты довольно быстро его найдешь.','Найдите нешлифованный хризоберилл.','Принесите нешлифованный хризоберил Тине Грязный Коготь, которая находится в Долине Четырех Ветров.','У нее действительно есть все!','Тина Грязный Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Тины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня Тина Грязный Коготь пришла на рынок Полугорья навестить сестру. Она такая замечательная, но ей сложно придумать подарок!$b$bВ горах на севере можно найти самоцвет под названием "хризоберилл" – он меняет цвет, когда берешь его в руки. Готов спорить, что такого камня у нее нет!$b$bПосмотри в пещерах гну-синей. Думаю, ты довольно быстро его найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите нешлифованный хризоберилл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите нешлифованный хризоберил Тине Грязный Коготь, которая находится в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У нее действительно есть все!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тина Грязный Коготь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30471,'Подарок для Чи-Чи','Знаешь, Чи-Чи вовсе не такой уж плохой. Раньше я думал, что от хозенов один вред, но... даже не знаю. Наверное, он просто лучший среди хозенов.$b$bНужно сделать ему что-нибудь приятное. Хозены, которые живут в горах на западе, готовят прекрасный стир-фрай и часто оставляют его в мисках в своих маленьких хижинах.$b$bДумаю, Чи-Чи будет рад полакомиться стир-фраем!','Добудьте настоящий стир-фрай долины.','Ммм?','Отдайте настоящий стир-фрай долины Чи-Чи. Вы найдете его в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.','Говорят, хозены ведут себя отвратительно. А как по мне, так ничего…','Чи-Чи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Чи-Чи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, Чи-Чи вовсе не такой уж плохой. Раньше я думал, что от хозенов один вред, но... даже не знаю. Наверное, он просто лучший среди хозенов.$b$bНужно сделать ему что-нибудь приятное. Хозены, которые живут в горах на западе, готовят прекрасный стир-фрай и часто оставляют его в мисках в своих маленьких хижинах.$b$bДумаю, Чи-Чи будет рад полакомиться стир-фраем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте настоящий стир-фрай долины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ммм?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте настоящий стир-фрай долины Чи-Чи. Вы найдете его в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Говорят, хозены ведут себя отвратительно. А как по мне, так ничего…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чи-Чи',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30472,'Подарок для Шо','Шо – девочка, которая живет в горах – сегодня в городе. Я видел, как она направлялась на рынок Полугорья.$b$bТакой длинный путь... должно быть, она сильно проголодалась. И я знаю, чем мы можем ее угостить!$b$bХозены в Небогорье варят суп из рыбы и яблок – да, сочетание странное, но получается невероятно вкусно. Миску с таким супом можно найти у большого, жуткого тотема хозенов.','Добудьте миску супа Юй-Пин.','Откуда ты узнал, что я умираю от голода? Кто тебе сказал?$B$BАнди, да? Когда он вырастет, то будет разбивать сердца…','Принесите суп Юй-Пин Шо в Долину Четырех Ветров.','Не хотел бы я жить высоко в горах, как она.','Шо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Шо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шо – девочка, которая живет в горах – сегодня в городе. Я видел, как она направлялась на рынок Полугорья.$b$bТакой длинный путь... должно быть, она сильно проголодалась. И я знаю, чем мы можем ее угостить!$b$bХозены в Небогорье варят суп из рыбы и яблок – да, сочетание странное, но получается невероятно вкусно. Миску с таким супом можно найти у большого, жуткого тотема хозенов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте миску супа Юй-Пин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Откуда ты узнал, что я умираю от голода? Кто тебе сказал?$B$BАнди, да? Когда он вырастет, то будет разбивать сердца…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите суп Юй-Пин Шо в Долину Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не хотел бы я жить высоко в горах, как она.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30473,'Подарок для Рыбы','Странная девочка, эта Тростниковая Шкура. Прежде всего, ее зовут Рыба – одно это настораживает.$b$bНо когда познакомишься с ней поближе, понимаешь, что на самом деле она очень милая. Например, ты знаешь, что она любит животных?$b$bСлушай, у меня идея. Хозены Куньцзэнь, которые живут в горах на западе, украшают свои дома фигурками животных, чтобы напугать врагов. Думаю, Рыба точно обрадуется, если подарить ей одну такую фигурку.','Найдите в хижине хозенов Куньцзэнь статуэтку яка.','Привет, $n! Как дела?','Принесите статуэтку Рыбе Тростниковой Шкуре в Долину Четырех Ветров.','Ха-ха! Ее зовут Рыба!','Рыба Тростниковая Шкура') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Рыбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странная девочка, эта Тростниковая Шкура. Прежде всего, ее зовут Рыба – одно это настораживает.$b$bНо когда познакомишься с ней поближе, понимаешь, что на самом деле она очень милая. Например, ты знаешь, что она любит животных?$b$bСлушай, у меня идея. Хозены Куньцзэнь, которые живут в горах на западе, украшают свои дома фигурками животных, чтобы напугать врагов. Думаю, Рыба точно обрадуется, если подарить ей одну такую фигурку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в хижине хозенов Куньцзэнь статуэтку яка.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $n! Как дела?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите статуэтку Рыбе Тростниковой Шкуре в Долину Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ха-ха! Ее зовут Рыба!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рыба Тростниковая Шкура',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30474,'Подарок для Эллы','Бедняжка Элла, она такая застенчивая. Я видел ее на рынке Полугорья – она явно была голодная, но не решалась заговорить ни с одним из поваров.$b$bНужно отнести ей еды – но не простой, а особенной.$b$bХозены Куньцзэнь делают острые клецки с раками-богомолами из ингредиентов, которые воруют с наших ферм. Я острую еду не люблю, но уверен, Элле это понравится.','Достаньте острые клецки с раками-богомолами.','Зачем ты это сделал?! Не нужны мне никакие...$B$B<Элла видит клецки, и у нее текут слюнки.>$B$BНу, ладно. Наверное, я все же хочу есть – совсем чуть-чуть. Спасибо, Уфапорить. И Анди тоже поблагодари.','О! Мм-м... Привет.','Принесите острые клецки с раками-богомолами Элле, которая находится в Долине Четырех Ветров.','Я отсюда слышу, как у нее урчит в животе!','Элла') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Эллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедняжка Элла, она такая застенчивая. Я видел ее на рынке Полугорья – она явно была голодная, но не решалась заговорить ни с одним из поваров.$b$bНужно отнести ей еды – но не простой, а особенной.$b$bХозены Куньцзэнь делают острые клецки с раками-богомолами из ингредиентов, которые воруют с наших ферм. Я острую еду не люблю, но уверен, Элле это понравится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте острые клецки с раками-богомолами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зачем ты это сделал?! Не нужны мне никакие...$B$B<Элла видит клецки, и у нее текут слюнки.>$B$BНу, ладно. Наверное, я все же хочу есть – совсем чуть-чуть. Спасибо, Уфапорить. И Анди тоже поблагодари.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О! Мм-м... Привет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите острые клецки с раками-богомолами Элле, которая находится в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я отсюда слышу, как у нее урчит в животе!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Элла',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30475,'Подарок для Фуна','Фермер Фун немного грубоват, но мама всегда говорила, что он один из лучших фермеров в долине.$b$bЯ придумал просто идеальный подарок для пандарена вроде него.$b$bК западу над холмами кружат равнинные ястребы. Подстрели одного, выбери кусок мяса посочнее, а затем отнеси Кору Железной Лапе, пусть поджарит.','Добудьте окровавленную ногу огромного равнинного ястреба, затем отнесите ее на рынок Полугорья и отдайте Кору Железной Лапе.','Хм-хм!..','Принесите жареную ногу равнинного ястреба фермеру Фуну, который живет в Долине Четырех Ветров.','Номи говорит, что он ест маленьких детей.','Фермер Фун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Фуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фермер Фун немного грубоват, но мама всегда говорила, что он один из лучших фермеров в долине.$b$bЯ придумал просто идеальный подарок для пандарена вроде него.$b$bК западу над холмами кружат равнинные ястребы. Подстрели одного, выбери кусок мяса посочнее, а затем отнеси Кору Железной Лапе, пусть поджарит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте окровавленную ногу огромного равнинного ястреба, затем отнесите ее на рынок Полугорья и отдайте Кору Железной Лапе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм-хм!..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите жареную ногу равнинного ястреба фермеру Фуну, который живет в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Номи говорит, что он ест маленьких детей.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фермер Фун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30476,'Подарок для старика Горной Лапы','У старика Горной Лапы сотни кур... Но вовсе не их он любит больше всего на свете.$b$bЯ видел. Он собирает голубые перья.$b$bПонятия не имею, где здесь можно взять голубые перья – а вот голубые жемчужины встречаются.$b$bИх можно найти на северо-западе, в устрицах на Камышовом озере. Уверен, голубая жемчужина станет прекрасным дополнением к его коллекции перьев!','Найдите синюю пресноводную жемчужину.','Ты смотри! Какая прелесть! Нужно убрать ее подальше, чтобы куры не склевали.$B$BЕе прислал Анди? Он забавный.','Уфапорить! Ты меня напугал.','Принесите синюю пресноводную жемчужину старику Горной Лапе, который находится в Долине Четырех Ветров.','Этот старик определенно любит цыплят.','Старик Горная Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для старика Горной Лапы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У старика Горной Лапы сотни кур... Но вовсе не их он любит больше всего на свете.$b$bЯ видел. Он собирает голубые перья.$b$bПонятия не имею, где здесь можно взять голубые перья – а вот голубые жемчужины встречаются.$b$bИх можно найти на северо-западе, в устрицах на Камышовом озере. Уверен, голубая жемчужина станет прекрасным дополнением к его коллекции перьев!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите синюю пресноводную жемчужину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты смотри! Какая прелесть! Нужно убрать ее подальше, чтобы куры не склевали.$B$BЕе прислал Анди? Он забавный.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уфапорить! Ты меня напугал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите синюю пресноводную жемчужину старику Горной Лапе, который находится в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этот старик определенно любит цыплят.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старик Горная Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30477,'Подарок для Хаоханя','Хаохань Грязный Коготь – важная персона в Союзе земледельцев и самый богатый пандарен в Долине! Он был так добр, что разрешил остаться здесь, и я тоже хочу сделать для него что-нибудь приятное.$b$bВкус у него изысканный – он любит рубины и тому подобное, но у меня не слишком много денег, так что нужно придумать что-то другое.$b$bУ меня есть идея! В Камышовом озере живет огромная рыбина! Мы подарим ему ее зуб!','Найдите зуб огромного камышового окуня.','Нет, ты погляди! Такой зуб не каждый день увидишь!$B$BПаладин, ты охотился на акул?$B$BСпасибо, Овердва. И Анди тоже поблагодари.','Паладин, тебе что-то нужно?','Принесите зуб огромного камышового окуня Хаоханю Грязному Когтю, который находится в Долине Четырех Ветров.','Если я хочу когда-нибудь стать фермером, я должен поддерживать хорошие отношения с ним!','Хаохань Грязный Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Хаоханя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хаохань Грязный Коготь – важная персона в Союзе земледельцев и самый богатый пандарен в Долине! Он был так добр, что разрешил остаться здесь, и я тоже хочу сделать для него что-нибудь приятное.$b$bВкус у него изысканный – он любит рубины и тому подобное, но у меня не слишком много денег, так что нужно придумать что-то другое.$b$bУ меня есть идея! В Камышовом озере живет огромная рыбина! Мы подарим ему ее зуб!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите зуб огромного камышового окуня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, ты погляди! Такой зуб не каждый день увидишь!$B$BПаладин, ты охотился на акул?$B$BСпасибо, Овердва. И Анди тоже поблагодари.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Паладин, тебе что-то нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите зуб огромного камышового окуня Хаоханю Грязному Когтю, который находится в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Если я хочу когда-нибудь стать фермером, я должен поддерживать хорошие отношения с ним!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хаохань Грязный Коготь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30478,'Подарок для Йогу','Иногда мне жаль Йогу. Здесь он единственный цзинь-юй, и, не думаю, что ему удалось с кем-нибудь подружиться. Кроме бутылки, конечно.$b$bЗнаешь, что? У меня идея! У фермера Юна есть корзинка клюквы и несколько яблок. Отнеси их на рынок Полугорья и отдай Бобо Железной Лапе – пусть он сварит что-нибудь особенное для Йогу.','Возьмите 8 яблок Юна, 50 ягод клюквы Юна и отнесите их Бобо Железной Лапе, чтобы он сварил из них яблочно-ягодную брагу.','Мм-м?','Принесите яблочно-ягодную брагу Йогу Пьяному в Долину Четырех Ветров.','У него изо рта пахнет так же, как у моего дядюшки.','Йогу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Йогу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда мне жаль Йогу. Здесь он единственный цзинь-юй, и, не думаю, что ему удалось с кем-нибудь подружиться. Кроме бутылки, конечно.$b$bЗнаешь, что? У меня идея! У фермера Юна есть корзинка клюквы и несколько яблок. Отнеси их на рынок Полугорья и отдай Бобо Железной Лапе – пусть он сварит что-нибудь особенное для Йогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 8 яблок Юна, 50 ягод клюквы Юна и отнесите их Бобо Железной Лапе, чтобы он сварил из них яблочно-ягодную брагу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мм-м?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите яблочно-ягодную брагу Йогу Пьяному в Долину Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него изо рта пахнет так же, как у моего дядюшки.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Йогу',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30479,'Подарок для Джины','Ты $gвидел:видела; на рынке Джину Грязный Коготь? Вот все при ней – красавица, умница, а животик какой милый! Ты не $gмог:могла; бы передать ей мой подарок?$b$bЯ хотел бы подарить ей орхидеи, которые растут на холмах к западу отсюда, но так высоко мне не забраться. Можешь собрать несколько цветков и отнести их Джине?$b$bДа, и когда ее встретишь... передай от меня привет.','Найдите златопламенную орхидею.','Какие красивые! И это мне?$B$BА-а... так они от Анди, да? Кажется, я знаю, кого я сегодня поцелую в лоб…','Здорово!','Принесите златопламенную орхидею Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.','<Вздох...>','Джина Грязный Коготь','Мне кажется, она очень красивая и милая. Но не говори ей, что я это сказал!','Джина Грязный Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для Джины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; на рынке Джину Грязный Коготь? Вот все при ней – красавица, умница, а животик какой милый! Ты не $gмог:могла; бы передать ей мой подарок?$b$bЯ хотел бы подарить ей орхидеи, которые растут на холмах к западу отсюда, но так высоко мне не забраться. Можешь собрать несколько цветков и отнести их Джине?$b$bДа, и когда ее встретишь... передай от меня привет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите златопламенную орхидею.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие красивые! И это мне?$B$BА-а... так они от Анди, да? Кажется, я знаю, кого я сегодня поцелую в лоб…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здорово!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите златопламенную орхидею Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','<Вздох...>',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джина Грязный Коготь',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Мне кажется, она очень красивая и милая. Но не говори ей, что я это сказал!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Джина Грязный Коготь',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30480,'Ритуал','С того момента, как я впервые вышел из речных вод, я знал, что мне предначертано стать Говорящим с водой.\r\n\r\nМеня обучили множеству ритуалов, и мне довелось совершать каждый из них, кроме одного.\r\n\r\nЕсть древнейший ритуал, к которому нам было сказано прибегнуть, если наш народ обернется против нас самих.\r\n\r\nНи разу не приходилось его использовать – по крайней мере, за то время, сколько мы помним эту деревню.\r\n\r\nПохоже, теперь его время настало.','Поговорите с Говорящим с водой Гожаем, а затем завершите ритуал.','Теперь мне ясно. Этот ритуал уничтожил то, что контролировало разум этих существ. Теперь я знаю, что нужно делать.','Поговорите с говорящим с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С того момента, как я впервые вышел из речных вод, я знал, что мне предначертано стать Говорящим с водой.\r\n\r\nМеня обучили множеству ритуалов, и мне довелось совершать каждый из них, кроме одного.\r\n\r\nЕсть древнейший ритуал, к которому нам было сказано прибегнуть, если наш народ обернется против нас самих.\r\n\r\nНи разу не приходилось его использовать – по крайней мере, за то время, сколько мы помним эту деревню.\r\n\r\nПохоже, теперь его время настало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Говорящим с водой Гожаем, а затем завершите ритуал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь мне ясно. Этот ритуал уничтожил то, что контролировало разум этих существ. Теперь я знаю, что нужно делать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящим с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30481,'Вырезано в камне','Видишь, в стенах камни светятся? Руку хочется. Могу их собирают, так что у них тоже есть камни.$B$BУвидишь камни – принеси Руку, ладно? Рук тебе спасибо скажет.','Соберите 12 рунических камней Го-Лай.','Вернитесь к Руку Каменной Ступне на руины Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вырезано в камне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь, в стенах камни светятся? Руку хочется. Могу их собирают, так что у них тоже есть камни.$B$BУвидишь камни – принеси Руку, ладно? Рук тебе спасибо скажет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 рунических камней Го-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне на руины Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30482,'Собиратель душ','Пока вы сражались с могу недалеко от озера, ваше внимание привлек одинокий могу-гигант, проводивший какой-то ритуал. Это следует прекратить.','Убейте повелителя теней Сайдоу и снимите c тела четки.','Принесите бусы собирателя душ Хэ Легкой Ноге в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собиратель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока вы сражались с могу недалеко от озера, ваше внимание привлек одинокий могу-гигант, проводивший какой-то ритуал. Это следует прекратить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте повелителя теней Сайдоу и снимите c тела четки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите бусы собирателя душ Хэ Легкой Ноге в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30483,'NOT USED','Вернитесь к Жэню Огненному Языку, который ждет у Двух Монолитов в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','NOT USED',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэню Огненному Языку, который ждет у Двух Монолитов в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30484,'Мера успеха','Война уже на пороге, $n!$b$bС тех пор, как ты $gушел:ушла;, мы обучали местных жителей, и, думаю, лучше, чем сейчас, они уже не станут.$b$bПосмотри $gсам:сама;. Навести остальных и возвращайся с донесением сюда.$b$bНам придется надеяться на то, что враг подготовлен... еще хуже.','Получите доклады от темного мастера Кирин, Риветта Сталехвата, Шокии и Рико.','По крайней мере, они уверены в себе.$B$BЭто обнадеживает.','Как проходят учения?','Вернитесь к генералу Назгриму на холм Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мера успеха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война уже на пороге, $n!$b$bС тех пор, как ты $gушел:ушла;, мы обучали местных жителей, и, думаю, лучше, чем сейчас, они уже не станут.$b$bПосмотри $gсам:сама;. Навести остальных и возвращайся с донесением сюда.$b$bНам придется надеяться на то, что враг подготовлен... еще хуже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите доклады от темного мастера Кирин, Риветта Сталехвата, Шокии и Рико.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','По крайней мере, они уверены в себе.$B$BЭто обнадеживает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как проходят учения?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму на холм Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30485,'Последний фрагмент головоломки','Эти хозены, $n, ведут себя в высшей степени неестественно. Надели броню и маршируют строем?$b$bЭто беспокоит меня, но обсуждение придется отложить на другой раз. Я здесь, чтобы попросить тебя о помощи.$b$bТа древняя фреска, которую мы видели в прошлый раз, почти разгадана. Нет сомнений, что в ней сокрыта древняя мудрость – знание, которое император хотел нам оставить.$b$bЧтобы расшифровать ее значение, моих медитаций может оказаться недостаточно. Пожалуйста, отнести эту фамильную ценность в святилище моих предков. Мне потребуется их помощь.','Используйте фамильную ценность Чо на площадке с видом на Нефритовую Змею в фамильном святилище Чо.$b$bПопросите Миши доставить вас туда.','<Хранитель истории Чо невольно содрогается>$B$BЛегенды... оказались правдой!','Поговорите с хранителем истории Чо на Обзорной площадке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний фрагмент головоломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти хозены, $n, ведут себя в высшей степени неестественно. Надели броню и маршируют строем?$b$bЭто беспокоит меня, но обсуждение придется отложить на другой раз. Я здесь, чтобы попросить тебя о помощи.$b$bТа древняя фреска, которую мы видели в прошлый раз, почти разгадана. Нет сомнений, что в ней сокрыта древняя мудрость – знание, которое император хотел нам оставить.$b$bЧтобы расшифровать ее значение, моих медитаций может оказаться недостаточно. Пожалуйста, отнести эту фамильную ценность в святилище моих предков. Мне потребуется их помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте фамильную ценность Чо на площадке с видом на Нефритовую Змею в фамильном святилище Чо.$b$bПопросите Миши доставить вас туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хранитель истории Чо невольно содрогается>$B$BЛегенды... оказались правдой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо на Обзорной площадке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30486,'Выслеживание нефритового дракона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание нефритового дракона',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30487,'Умный гору обойдет','На дороге в горах очень опасно. Нужна бездна удачи, чтобы не умереть. Племянник Кривой Ноготь покажет тебе дорогу.$b$bМожет, сегодня и неплохой день для путешествий. Ветер дует с востока, это хороший знак. Груммелям в пути лучше всего, когда дует восточный ветер.$b$bЗалезай в повозку, когда будешь $gготов:готова; отправиться.','Сопроводите повозку и проводников до горы Неутомимых.','Поговорите с Счастливчиком Синей Струной в горном лагере Пика Неутомимых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умный гору обойдет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На дороге в горах очень опасно. Нужна бездна удачи, чтобы не умереть. Племянник Кривой Ноготь покажет тебе дорогу.$b$bМожет, сегодня и неплохой день для путешествий. Ветер дует с востока, это хороший знак. Груммелям в пути лучше всего, когда дует восточный ветер.$b$bЗалезай в повозку, когда будешь $gготов:готова; отправиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите повозку и проводников до горы Неутомимых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Счастливчиком Синей Струной в горном лагере Пика Неутомимых.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30488,'Мускусная Лапа: пропавший сын','Ты еще кто $gтакой:такая;? $c? Никогда о таких не слышал. Ты $gпришел:пришла;, чтобы помогать или воровать моих яков?$b$bЕсли так уж хочешь помочь, иди и разыщи моего сына. Кучка греллей захватила его, и сейчас он даже может не знать, что мы потеряли ранчо.$b$bОни утащили его в Пещеру шаловливых духов к юго-востоку отсюда. Спаси его, и я, может, тебя чем-то да награжу.','Разыщите Мускусную Лапу – младшего в Пещере шаловливых духов.','Поговорите с Мускусной Лапой – младшим в Пещере шаловливых духов на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мускусная Лапа: пропавший сын',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты еще кто $gтакой:такая;? $c? Никогда о таких не слышал. Ты $gпришел:пришла;, чтобы помогать или воровать моих яков?$b$bЕсли так уж хочешь помочь, иди и разыщи моего сына. Кучка греллей захватила его, и сейчас он даже может не знать, что мы потеряли ранчо.$b$bОни утащили его в Пещеру шаловливых духов к юго-востоку отсюда. Спаси его, и я, может, тебя чем-то да награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Мускусную Лапу – младшего в Пещере шаловливых духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мускусной Лапой – младшим в Пещере шаловливых духов на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30489,'Пахучая иголка духов','Если ты хочешь помочь нам, найди несколько пахучих иголок духов в Пещере шаловливых духов.$b$bГруммели не верят в удачу, если не могут ее унюхать. Они заплатят больше, если яки будут пахнуть свежими иголками.','Соберите 100 пахучих иголок духов.','М-м-м. Запах иголки с ни с чем не спутать!','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пахучая иголка духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь помочь нам, найди несколько пахучих иголок духов в Пещере шаловливых духов.$b$bГруммели не верят в удачу, если не могут ее унюхать. Они заплатят больше, если яки будут пахнуть свежими иголками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 пахучих иголок духов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','М-м-м. Запах иголки с ни с чем не спутать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30490,'Як и так, и сяк','Яунголы! Они пришли сюда, взяли что захотели и уничтожили все остальное!$b$bНе могу допустить, чтобы эти бандиты разгромили мою якомойку. Это все, что осталось у меня с сыном.$b$bОтправляйся к нашей старой ферме и выбей всю дурь из этих яунголов. Бьюсь об заклад, если ты убьешь достаточно этих мерзавцев, остальные дважды подумают, прежде чем вернуться сюда.','Убейте 9 хияккеров-разорителей на ферме Мускусной Лапы.','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Як и так, и сяк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы! Они пришли сюда, взяли что захотели и уничтожили все остальное!$b$bНе могу допустить, чтобы эти бандиты разгромили мою якомойку. Это все, что осталось у меня с сыном.$b$bОтправляйся к нашей старой ферме и выбей всю дурь из этих яунголов. Бьюсь об заклад, если ты убьешь достаточно этих мерзавцев, остальные дважды подумают, прежде чем вернуться сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 хияккеров-разорителей на ферме Мускусной Лапы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30491,'На якомойке','Послушай, мой отец сумасшедший. Я люблю его, но он – безумец.$b$bЭти яунголы разрушили нашу ферму и распугали яков, а те разбежались в разные стороны.$b$bМой отец в поисках яков снова свяжется с этими яунголами.$b$bПоможешь нам пригнать некоторых из них, чтобы отец не натворил глупостей?$b$bПросто перегони их на якомойку, чтобы мы смогли помыть их и продать груммелям.','Приведите 6 сбежавших яков на якомойку "Лао и сын".','Поговорите с Мускусной Лапой – младшим на якомойке "Лао и сын" на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На якомойке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, мой отец сумасшедший. Я люблю его, но он – безумец.$b$bЭти яунголы разрушили нашу ферму и распугали яков, а те разбежались в разные стороны.$b$bМой отец в поисках яков снова свяжется с этими яунголами.$b$bПоможешь нам пригнать некоторых из них, чтобы отец не натворил глупостей?$b$bПросто перегони их на якомойку, чтобы мы смогли помыть их и продать груммелям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите 6 сбежавших яков на якомойку "Лао и сын".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мускусной Лапой – младшим на якомойке "Лао и сын" на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30492,'И снова яки','Я не врал о твоей награде. Вот, отведи этих чистых яков к хозяину каравана груммелей к Серебрику.$b$bТы найдешь его на базаре груммелей к западу отсюда. Он – наш покупатель, он заплатит тебе за доставку.$b$bРост у него небольшой, зато он наш самый большой клиент.$b$bЕсли яки разбегутся, возвращайся ко мне. Ну, не то чтобы они просто сюда приходили сами после того, как их вымоют.','Ах! Я прямо чую запах удачи. У Мускусных Лап всегда отличные яки на продажу.','Поговорите со Счастливчиком Серебриком на базаре груммелей на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И снова яки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не врал о твоей награде. Вот, отведи этих чистых яков к хозяину каравана груммелей к Серебрику.$b$bТы найдешь его на базаре груммелей к западу отсюда. Он – наш покупатель, он заплатит тебе за доставку.$b$bРост у него небольшой, зато он наш самый большой клиент.$b$bЕсли яки разбегутся, возвращайся ко мне. Ну, не то чтобы они просто сюда приходили сами после того, как их вымоют.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах! Я прямо чую запах удачи. У Мускусных Лап всегда отличные яки на продажу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Счастливчиком Серебриком на базаре груммелей на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30495,'Любимое дело','Можно я попрошу тебя еще об одном одолжении?$B$BМы сильно отстали от графика, и к тому же последняя партия нефрита так и не пришла, а без нее закончить эту огромную статую невозможно.$B$BУ меня сейчас забот хватает, так что, пожалуйста, отвези эту руду другим мастерам.$B$BИсторик Дин, землемер Сава и мастер воздушных змеев Шоку – они все у пьедестала статуи. Надсмотрщик Эми руководит работами на ее вершине.$B$BВремени у нас мало, так что поторопись!','Доставьте нефрит историку Дину, землемеру Саве, мастеру воздушных змеев Шоку и надсмотрщику Эми.','Что, уже готово? Ну и скорость! Не подумывал о том, чтобы зарабатывать этим на жизнь?','Вернитесь к мастеру Рейки в Змеиное Сердце, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимое дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Можно я попрошу тебя еще об одном одолжении?$B$BМы сильно отстали от графика, и к тому же последняя партия нефрита так и не пришла, а без нее закончить эту огромную статую невозможно.$B$BУ меня сейчас забот хватает, так что, пожалуйста, отвези эту руду другим мастерам.$B$BИсторик Дин, землемер Сава и мастер воздушных змеев Шоку – они все у пьедестала статуи. Надсмотрщик Эми руководит работами на ее вершине.$B$BВремени у нас мало, так что поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте нефрит историку Дину, землемеру Саве, мастеру воздушных змеев Шоку и надсмотрщику Эми.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, уже готово? Ну и скорость! Не подумывал о том, чтобы зарабатывать этим на жизнь?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Рейки в Змеиное Сердце, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30496,'Посох говорящего с водой','В Чернильной Жабре великий раскол, |3-6($r). Старейшина Шай Ху испил оскверненной воды из пруда и заставил остальных последовать его примеру. Когда я попытался препятствовать этому, Орачи из городской стражи забрал у меня ритуальных посох и выгнал меня вон.$b$bТеперь я не просто изгнан, но и лишен возможности обращаться к мудрости вод, которая всегда была со мной!$b$bЯ не воин. Если ты умеешь сражаться, не поможешь ли мне отобрать посох у Орачи? Его можно найти в деревне к северу отсюда.','Хорошо. Теперь у нас есть хоть какая-то надежда все исправить.','Вернитесь к говорящему с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох говорящего с водой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Чернильной Жабре великий раскол, |3-6($r). Старейшина Шай Ху испил оскверненной воды из пруда и заставил остальных последовать его примеру. Когда я попытался препятствовать этому, Орачи из городской стражи забрал у меня ритуальных посох и выгнал меня вон.$b$bТеперь я не просто изгнан, но и лишен возможности обращаться к мудрости вод, которая всегда была со мной!$b$bЯ не воин. Если ты умеешь сражаться, не поможешь ли мне отобрать посох у Орачи? Его можно найти в деревне к северу отсюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Теперь у нас есть хоть какая-то надежда все исправить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящему с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30498,'Вернись!','Так, пока не забыла: меня попросили кое-что тебе передать. Как я понимаю, это письмо от одного из твоих товарищей.$b$bМне дали понять, что ты им $gнужен:нужна; безотлагательно, так что я взяла на себя смелость подготовить для тебя транспорт.$b$bКогда будешь $gготов:готова;, поговори с Гинсой Острый Глаз, у нее уже готов воздушный змей. Ее можно найти к югу отсюда.','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.','Адмирал Тейлор ожидает вашего возвращения.','Адмирал Тейлор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернись!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, пока не забыла: меня попросили кое-что тебе передать. Как я понимаю, это письмо от одного из твоих товарищей.$b$bМне дали понять, что ты им $gнужен:нужна; безотлагательно, так что я взяла на себя смелость подготовить для тебя транспорт.$b$bКогда будешь $gготов:готова;, поговори с Гинсой Острый Глаз, у нее уже готов воздушный змей. Ее можно найти к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Адмирал Тейлор ожидает вашего возвращения.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Адмирал Тейлор',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30499,'Вернись!','Так, пока не забыла: меня попросили кое-что тебе передать. Как я понимаю, это письмо от одного из твоих товарищей.$b$bМне дали понять, что ты им $gнужен:нужна; безотлагательно, так что я взяла на себя смелость подготовить для тебя транспорт.$b$bКогда будешь $gготов:готова;, поговори с Гинсой Острый Глаз, у нее уже готов воздушный змей. Ее можно найти к югу отсюда.','Вернитесь к генералу Назгриму на холм Грукин.','Тром-ка, Эрезул!$B$BНадеюсь, на лесной дороге ты смог разузнать что-нибудь полезное.$B$BНаши приготовления практически закончены, но нам нужна твоя помощь.','Вернитесь к генералу Назгриму на холм Грукин.','Генерал Назгрим ожидает вашего возвращения.','Генерал Назгрим') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернись!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, пока не забыла: меня попросили кое-что тебе передать. Как я понимаю, это письмо от одного из твоих товарищей.$b$bМне дали понять, что ты им $gнужен:нужна; безотлагательно, так что я взяла на себя смелость подготовить для тебя транспорт.$b$bКогда будешь $gготов:готова;, поговори с Гинсой Острый Глаз, у нее уже готов воздушный змей. Ее можно найти к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к генералу Назгриму на холм Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тром-ка, Эрезул!$B$BНадеюсь, на лесной дороге ты смог разузнать что-нибудь полезное.$B$BНаши приготовления практически закончены, но нам нужна твоя помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму на холм Грукин.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Генерал Назгрим ожидает вашего возвращения.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Генерал Назгрим',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30500,'Эмоциональный всплеск','Пандария – земля, полная загадок, $gпутник:путница;.$b$bИ некоторые ее секреты не можем раскрыть даже мы, хранители истории.$b$bИ так просто ситуацию не исправить. Если легенды правдивы, предстоит сделать очень многое, чтобы избавить эти земли от ша.$b$bАгрессия той битвы пробудила духов, чья жизненная сила – негативные эмоции живущих. И я боюсь, он лишь первый из многих.$b$bПока же нам остается только пытаться ослабить их присутствие здесь.','Уничтожьте 10 отзвуков ша.','Какой ужас...$B$BНадо попытаться найти способ все исправить.','Поговорите с хранителем истории Чо в Змеином Сердце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эмоциональный всплеск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандария – земля, полная загадок, $gпутник:путница;.$b$bИ некоторые ее секреты не можем раскрыть даже мы, хранители истории.$b$bИ так просто ситуацию не исправить. Если легенды правдивы, предстоит сделать очень многое, чтобы избавить эти земли от ша.$b$bАгрессия той битвы пробудила духов, чья жизненная сила – негативные эмоции живущих. И я боюсь, он лишь первый из многих.$b$bПока же нам остается только пытаться ослабить их присутствие здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 отзвуков ша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ужас...$B$BНадо попытаться найти способ все исправить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Змеином Сердце.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30501,'Gossip Accept Quest Test Case') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Gossip Accept Quest Test Case',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30502,'Нефритовое сердце','С помощью кусков неземного нефрита победите 6 порождений ша.','<Чо уныло смотрит на вас.>Этот нефрит предназначался... для несоизмеримо большего.','Поговорите с хранителем истории Чо в Змеином Сердце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нефритовое сердце',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью кусков неземного нефрита победите 6 порождений ша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чо уныло смотрит на вас.>Этот нефрит предназначался... для несоизмеримо большего.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Змеином Сердце.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30504,'Срочные меры','Твои товарищи обжились в этих местах. Но вместе с ними сюда пришла война.$b$bПока что мы не знаем всех последствий, но то, что мы уже видели... просто чудовищно.$b$bИ тем не менее, мы не можем оставить твоих друзей, поддавшись злости. Те из них, кто остался в живых, наверняка ранены и нуждаются в помощи.$b$bЭти фейерверки должны были запустить в честь окончания строительства статуи. Используй их, чтобы подать сигнал Миши, он заберет твоих товарищей.','Используйте фейерверки Чо около генерала Назгрима, темного мастера Кирин, Шокии и Риветта Сталехвата.','Мысленно я буду с твоими товарищами, странник.$B$BПусть за ними присмотрят.','Поговорите с хранителем истории Чо в Змеином Сердце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои товарищи обжились в этих местах. Но вместе с ними сюда пришла война.$b$bПока что мы не знаем всех последствий, но то, что мы уже видели... просто чудовищно.$b$bИ тем не менее, мы не можем оставить твоих друзей, поддавшись злости. Те из них, кто остался в живых, наверняка ранены и нуждаются в помощи.$b$bЭти фейерверки должны были запустить в честь окончания строительства статуи. Используй их, чтобы подать сигнал Миши, он заберет твоих товарищей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте фейерверки Чо около генерала Назгрима, темного мастера Кирин, Шокии и Риветта Сталехвата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мысленно я буду с твоими товарищами, странник.$B$BПусть за ними присмотрят.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Змеином Сердце.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30506,'Адмирал Тейлор очнулся','Адмирал Тейлор, похоже, оправился от полученных травм. Он и его люди наверху в доме аптекаря там, в деревне Бинан.$B$BОн хочет встретиться с тобой.','Поговорите с адмиралом Тейлором в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Адмирал Тейлор очнулся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Адмирал Тейлор, похоже, оправился от полученных травм. Он и его люди наверху в доме аптекаря там, в деревне Бинан.$B$BОн хочет встретиться с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с адмиралом Тейлором в деревне Бинан на вершине Кунь-Лай.',`objectives_loc8`);
