INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30512,'Приют Западного Ветра','Поговорите с батраком Бо и со старейшиной Цуланем на Стоянке яунголов.','Ну что ж... мы живы, а ведь без твоей помощи наша участь была бы совсем незавидна.$B$BНо если хочешь, чтобы это место стало твоим основным лагерем и чтобы мы присоединились к Альянсу, есть еще одна вещь, которую тебе нужно сделать, чтобы обеспечить нашу безопасность.','Встретьтесь со старейшиной Цуланем на Стоянке яунголов, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приют Западного Ветра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с батраком Бо и со старейшиной Цуланем на Стоянке яунголов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж... мы живы, а ведь без твоей помощи наша участь была бы совсем незавидна.$B$BНо если хочешь, чтобы это место стало твоим основным лагерем и чтобы мы присоединились к Альянсу, есть еще одна вещь, которую тебе нужно сделать, чтобы обеспечить нашу безопасность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь со старейшиной Цуланем на Стоянке яунголов, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30513,'Приют Восточного Ветра','Поговорите с батраком Ко и со старейшиной Шиао на вершине Кунь-Лай.','Поговорите со старейшиной Шиао в Приюте Восточного Ветра, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приют Восточного Ветра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с батраком Ко и со старейшиной Шиао на вершине Кунь-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со старейшиной Шиао в Приюте Восточного Ветра, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (30514,'Вызов принят','Яунголы всегда были гордым и неуживчивым народом, но такой свирепости я за ними не помню.\r\n\r\nНе знаю, почему они так переменились, но сейчас это все равно некогда выяснять. Пока жив Ур-Батаар, предводитель батаарских яунголов, наши жизни под угрозой.\r\n\r\nИди же в лагерь яунголов и подожги их знамя, вызывая вождя на бой. Победи его, и мы вздохнем свободно.','Подожгите знамя яунголов, чтобы бросить вызов Ур-Батаару, и победите его.','Победа! Наконец-то справедливость восторжествовала, и на какое-то время мы в безопасности, хотя и лишились многого.$B$BТем не менее, все решено. Мы присоединимся к Альянсу и восстановим деревню с твоей помощью.','Вернитесь к старейшине Цуланю в Приют Западного Ветра.','Ур-Батаар, предводитель яунголов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов принят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы всегда были гордым и неуживчивым народом, но такой свирепости я за ними не помню.\r\n\r\nНе знаю, почему они так переменились, но сейчас это все равно некогда выяснять. Пока жив Ур-Батаар, предводитель батаарских яунголов, наши жизни под угрозой.\r\n\r\nИди же в лагерь яунголов и подожги их знамя, вызывая вождя на бой. Победи его, и мы вздохнем свободно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите знамя яунголов, чтобы бросить вызов Ур-Батаару, и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победа! Наконец-то справедливость восторжествовала, и на какое-то время мы в безопасности, хотя и лишились многого.$B$BТем не менее, все решено. Мы присоединимся к Альянсу и восстановим деревню с твоей помощью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Цуланю в Приют Западного Ветра.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ур-Батаар, предводитель яунголов',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (30515,'Вызов принят','Яунголы всегда были гордым и неуживчивым народом, но такой свирепости я за ними не помню.\r\n\r\nНе знаю, почему они так переменились, но сейчас это все равно некогда выяснять. Пока жив Ур-Батаар, предводитель батаарских яунголов, наши жизни под угрозой.\r\n\r\nИди же в лагерь яунголов и подожги их знамя, вызывая вождя на бой. Победи его, и мы вздохнем свободно.','Подожгите знамя яунголов в огненном лагере Батаар, чтобы бросить вызов Ур-Батаару, и победите его.','Вернитесь к старейшине Шиао в Приют Восточного Ветра.','Ур-Батаар, предводитель яунголов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов принят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы всегда были гордым и неуживчивым народом, но такой свирепости я за ними не помню.\r\n\r\nНе знаю, почему они так переменились, но сейчас это все равно некогда выяснять. Пока жив Ур-Батаар, предводитель батаарских яунголов, наши жизни под угрозой.\r\n\r\nИди же в лагерь яунголов и подожги их знамя, вызывая вождя на бой. Победи его, и мы вздохнем свободно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите знамя яунголов в огненном лагере Батаар, чтобы бросить вызов Ур-Батаару, и победите его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Шиао в Приют Восточного Ветра.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ур-Батаар, предводитель яунголов',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30516,'Фермерство I: небольшая проблема','Значит, тебе нужно выполоть несколько сорняков?$B$BРазумеется, $gсосед:соседка;! Но беда в том, что у меня заканчивается средство.$B$BОбычно я сам готовлю антисорняковую смесь – очень мощную и только из природных компонентов, так что земле она не вредит... И растениям она на пользу... Вред только этим надоедливым сорнякам! Они эту смесь ненавидят!$B$BК западу отсюда, на террасах, растет паучий корень. Если принесешь его, я сделаю новую порцию смеси и отнесу на ферму Юна.$B$BЯ бы сам набрал коренья, но... я ненавижу пауков. Ты поймешь, о чем я.','Соберите 6 паучьих корней для Гай Ланя.','Так, и что тут у нас? О, этих запасов мне надолго хватит.$B$BСпасибо!','Как продвигается сбор кореньев?','Вернитесь к Гай Ланю в Плодородные земли в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермерство I: небольшая проблема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, тебе нужно выполоть несколько сорняков?$B$BРазумеется, $gсосед:соседка;! Но беда в том, что у меня заканчивается средство.$B$BОбычно я сам готовлю антисорняковую смесь – очень мощную и только из природных компонентов, так что земле она не вредит... И растениям она на пользу... Вред только этим надоедливым сорнякам! Они эту смесь ненавидят!$B$BК западу отсюда, на террасах, растет паучий корень. Если принесешь его, я сделаю новую порцию смеси и отнесу на ферму Юна.$B$BЯ бы сам набрал коренья, но... я ненавижу пауков. Ты поймешь, о чем я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 паучьих корней для Гай Ланя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, и что тут у нас? О, этих запасов мне надолго хватит.$B$BСпасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается сбор кореньев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гай Ланю в Плодородные земли в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30517,'Голос фермера Фуна I: атака яков','Второй член совета, участвующий в голосовании, – это фермер Фун, и почему он туда попал, догадаться несложно.$B$BУ него самые большие овощи в долине! Надеюсь, когда-нибудь мне удастся вырастить такие же огромные тыквы.$B$BЕсли мы хотим стать земледельцами, надо поговорить с ним.','А, тебя прислал тот новый фермер?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос фермера Фуна I: атака яков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Второй член совета, участвующий в голосовании, – это фермер Фун, и почему он туда попал, догадаться несложно.$B$BУ него самые большие овощи в долине! Надеюсь, когда-нибудь мне удастся вырастить такие же огромные тыквы.$B$BЕсли мы хотим стать земледельцами, надо поговорить с ним.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал тот новый фермер?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30518,'Голос фермера Фуна II: на свободе','Ты хочешь, чтобы я проголосовал за фермера Юна? Ха! Да ты шутишь!$B$BСлушай, я не собираюсь поддерживать какого-то городского белоручку, который не знает, как лопату в руках держать.$B$BИ ты, и этот жулик Юн – позор нашей деревни.$B$BОставь меня в покое. Какой-то хулиган выпустил из загона моих яков, и они помчались куда-то на северо-запад от Полугорья.$B$BЯ не смогу спокойно спать, пока не найду своих дорогих яков.','Отведите 5 беглых лохмачей в загон фермера Фуна на северном краю Луговых угодий.','Вернитесь к фермеру Фуну в Плодородные земли или на рынок Полугорья в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос фермера Фуна II: на свободе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хочешь, чтобы я проголосовал за фермера Юна? Ха! Да ты шутишь!$B$BСлушай, я не собираюсь поддерживать какого-то городского белоручку, который не знает, как лопату в руках держать.$B$BИ ты, и этот жулик Юн – позор нашей деревни.$B$BОставь меня в покое. Какой-то хулиган выпустил из загона моих яков, и они помчались куда-то на северо-запад от Полугорья.$B$BЯ не смогу спокойно спать, пока не найду своих дорогих яков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите 5 беглых лохмачей в загон фермера Фуна на северном краю Луговых угодий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Фуну в Плодородные земли или на рынок Полугорья в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30519,'Голос Наны I: секретный рецепт Наны','Теперь нам нужно заручиться поддержкой Наны Грязный Коготь. Это бабушка Хаоханя, она состояла в Союзе земледельцев уже тогда, когда нас с тобой еще и на свете не было!$b$bЕе можно найти в Полугорье, в здании, которое занимают земледельцы. Почему бы тебе не нанести ей визит?','Да, Нана Грязный Коготь – это я. Может быть, я и старая, но я все прекрасно помню, дорогой. Не то что старик Седой Ус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Наны I: секретный рецепт Наны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам нужно заручиться поддержкой Наны Грязный Коготь. Это бабушка Хаоханя, она состояла в Союзе земледельцев уже тогда, когда нас с тобой еще и на свете не было!$b$bЕе можно найти в Полугорье, в здании, которое занимают земледельцы. Почему бы тебе не нанести ей визит?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Нана Грязный Коготь – это я. Может быть, я и старая, но я все прекрасно помню, дорогой. Не то что старик Седой Ус.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30520,'Несварение желудка','Как сосед фермер Юн мне нравится, но голосовать за него – это совсем другое дело. Он знает, что мой отец – глава Союза земледельцев?$B$BИ вообще, сейчас у меня есть дела поважнее. Многие в округе наелись испортившихся овощей и заболели.$B$BИ так как овощи были приобретены на моем рынке, моя репутация под угрозой.$B$BЯ знаю, как вылечить заболевших, но это будет довольно неприятно.$B$BИ если ты... мм-м... ускоришь дело, я буду перед тобой в долгу.','Используйте крыжовник, чтобы вылечить заболевших жителей Полугорья.','Вернитесь к Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несварение желудка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как сосед фермер Юн мне нравится, но голосовать за него – это совсем другое дело. Он знает, что мой отец – глава Союза земледельцев?$B$BИ вообще, сейчас у меня есть дела поважнее. Многие в округе наелись испортившихся овощей и заболели.$B$BИ так как овощи были приобретены на моем рынке, моя репутация под угрозой.$B$BЯ знаю, как вылечить заболевших, но это будет довольно неприятно.$B$BИ если ты... мм-м... ускоришь дело, я буду перед тобой в долгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте крыжовник, чтобы вылечить заболевших жителей Полугорья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джине Грязный Коготь на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30521,'Голос Хаоханя I: вторжение','$n, хочу поручить тебе непростое дело.$B$BНам нужен еще один голос – голос Хаоханя Грязного Когтя, главы Союза земледельцев.$B$BПоначалу он нас невзлюбил, но мы ведь столько узнали о сельском хозяйстве, что он, должно быть, уже изменил свое мнение!$B$BПожалуйста, поговори с ним. Ты же умеешь убеждать, да?','Что тебе нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Хаоханя I: вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, хочу поручить тебе непростое дело.$B$BНам нужен еще один голос – голос Хаоханя Грязного Когтя, главы Союза земледельцев.$B$BПоначалу он нас невзлюбил, но мы ведь столько узнали о сельском хозяйстве, что он, должно быть, уже изменил свое мнение!$B$BПожалуйста, поговори с ним. Ты же умеешь убеждать, да?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что тебе нужно?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30522,'Голос Хаоханя II: истинные виновники','А ты что здесь делаешь?$B$BСлушай, у меня и так забот хватает, а ночью какие-то негодяи влезли в мой сарай, что к западу отсюда.$B$BОни украли семена, переломали инструменты и сожрали мои припасы. И это еще не все! Пропала целая телега дынь, сломан насос, животные вытаптывают мой урожай...$b$bИ когда же все это закончится!','Найдите 8 подозрительных следов.','Грустно слышать, что у Хаоханя столько проблем. Спасибо, что рассказал мне об этом. Мы постараемся ему помочь.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Хаоханя II: истинные виновники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А ты что здесь делаешь?$B$BСлушай, у меня и так забот хватает, а ночью какие-то негодяи влезли в мой сарай, что к западу отсюда.$B$BОни украли семена, переломали инструменты и сожрали мои припасы. И это еще не все! Пропала целая телега дынь, сломан насос, животные вытаптывают мой урожай...$b$bИ когда же все это закончится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 подозрительных следов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грустно слышать, что у Хаоханя столько проблем. Спасибо, что рассказал мне об этом. Мы постараемся ему помочь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (30523,'Фермерство II: сломанная повозка','Привет, $n. С тех пор как я сюда прибыл, все время смотрю на эту повозку – день за днем, утром и вечером. Жуткое зрелище, правда?$B$BВ городе говорят, что Рыба Тростниковая Шкура – опытный мастер, возможно, ей удастся починить повозку, и тогда мы сможем распахать этот участок.$B$BПожалуйста, узнай у нее, не возьмется ли она за эту работу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермерство II: сломанная повозка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. С тех пор как я сюда прибыл, все время смотрю на эту повозку – день за днем, утром и вечером. Жуткое зрелище, правда?$B$BВ городе говорят, что Рыба Тростниковая Шкура – опытный мастер, возможно, ей удастся починить повозку, и тогда мы сможем распахать этот участок.$B$BПожалуйста, узнай у нее, не возьмется ли она за эту работу?',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30524,'Фермерство I: постучи по дереву','Конечно! У меня на примете есть именно такая повозка!$B$BЯ быстро ее починю, но мне нужны доски.$B$BНа дне озера полно досок, и их можно оттуда выудить – ну, как рыбу. Ха-ха, как рыбу! Дошло?! О, я просто угораю от своих шуток!$B$BА, не важно. Принеси мне доски, и я сразу же приступлю к работе!','Соберите 100 покрытых воском досок.','В озере полно сокровищ – нужно только уметь искать.','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермерство I: постучи по дереву',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно! У меня на примете есть именно такая повозка!$B$BЯ быстро ее починю, но мне нужны доски.$B$BНа дне озера полно досок, и их можно оттуда выудить – ну, как рыбу. Ха-ха, как рыбу! Дошло?! О, я просто угораю от своих шуток!$B$BА, не важно. Принеси мне доски, и я сразу же приступлю к работе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 покрытых воском досок.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В озере полно сокровищ – нужно только уметь искать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30525,'Голос Хаоханя III: чистый яд','Хорошо, $n. Это наш шанс!$b$bНа ферме Грязного Когтя большие проблемы. Эти горные хозены по ночам совершают набеги на ферму, воруют и пожирают его с таким трудом выращенные овощи.$b$bМы должны избавиться от них, и я знаю, как это сделать.$b$bКогда-то давно мой дедушка показывал мне, как готовить яд, чтобы справиться с вредителями на ферме.$b$bИнгредиенты для яда можно найти там, где живут гну-сини, к северу отсюда.$b$bНе беспокойся, $n! Я практически уверен, что это сработает.','Принесите 1 кроволист, 1 пещерную лилию, 1 призрачный гриб и 1 лиловый лишайник.','Ингредиенты у тебя? Отлично!$B$BТеперь мне надо приготовить яд.','Хозенов ждет огромный сюрприз!','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Хаоханя III: чистый яд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, $n. Это наш шанс!$b$bНа ферме Грязного Когтя большие проблемы. Эти горные хозены по ночам совершают набеги на ферму, воруют и пожирают его с таким трудом выращенные овощи.$b$bМы должны избавиться от них, и я знаю, как это сделать.$b$bКогда-то давно мой дедушка показывал мне, как готовить яд, чтобы справиться с вредителями на ферме.$b$bИнгредиенты для яда можно найти там, где живут гну-сини, к северу отсюда.$b$bНе беспокойся, $n! Я практически уверен, что это сработает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 кроволист, 1 пещерную лилию, 1 призрачный гриб и 1 лиловый лишайник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ингредиенты у тебя? Отлично!$B$BТеперь мне надо приготовить яд.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хозенов ждет огромный сюрприз!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30526,'Голодный и одинокий','Тощий голодный пес жалобно завывает и виляет хвостом.$B$BПохоже, сейчас ему бы не помешал хороший обед.','Увидев сочный бифштекс, пес настораживается.$B$BВы бросаете ему кусок мяса, и пес начинает жадно его пожирать.','Глаза пса вспыхивают. Кажется, он вас узнал.','Вернитесь к потерявшемуся псу в Плодородные земли, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голодный и одинокий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тощий голодный пес жалобно завывает и виляет хвостом.$B$BПохоже, сейчас ему бы не помешал хороший обед.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Увидев сочный бифштекс, пес настораживается.$B$BВы бросаете ему кусок мяса, и пес начинает жадно его пожирать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Глаза пса вспыхивают. Кажется, он вас узнал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к потерявшемуся псу в Плодородные земли, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30527,'Голос Хаоханя IV: похитители дынь','Так вот, я узнал, что у эти горные хозены любят сладкие, вкусные дыни.$b$bРаз уж последний урожай Грязного Когтя украли, мы вырастим дыни сами.$b$bА когда дыни вырастут, мы с их помощью выманим вожака хозенов из пещеры!','Посадите 4 полосатых дыни и соберите урожай. Затем доставьте 20 полосатых дынь фермеру Юну.$b$bСемена полосатой дыни можно купить у торговца Зеленое Поле на рынке Полугорья. После обработки почвы и ухода за растением вам нужно подождать один день, прежде чем собрать урожай полосатых дынь.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Хаоханя IV: похитители дынь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот, я узнал, что у эти горные хозены любят сладкие, вкусные дыни.$b$bРаз уж последний урожай Грязного Когтя украли, мы вырастим дыни сами.$b$bА когда дыни вырастут, мы с их помощью выманим вожака хозенов из пещеры!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 4 полосатых дыни и соберите урожай. Затем доставьте 20 полосатых дынь фермеру Юну.$b$bСемена полосатой дыни можно купить у торговца Зеленое Поле на рынке Полугорья. После обработки почвы и ухода за растением вам нужно подождать один день, прежде чем собрать урожай полосатых дынь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30528,'Голос Хаоханя V: вождь Хоп-Хоп','Ну что, приступим к последней части плана?$B$BДеревней Куньцзэнь правит суровый вождь по имени Хоп-Хоп. Говорят, он так суров, что почти не чувствует боли.$B$BЯ впрыснул в дыни ядовитую смесь, так что не вздумай их есть!$B$BКак только он заметит тебя, бросай эти дыни на землю. Хоп-Хоп не упустит возможности полакомиться сладкой полосатой дыней.$b$bКак только он надкусит дыню, то на некоторое время ослабеет, и у тебя будет возможность напасть на него внезапно.','Убейте вождя Хоп-Хопа в Пещере Куньцзэнь на северо-западе.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.','Вожак хозенов Куньцзэнь.','Вождь Хоп-Хоп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Хаоханя V: вождь Хоп-Хоп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, приступим к последней части плана?$B$BДеревней Куньцзэнь правит суровый вождь по имени Хоп-Хоп. Говорят, он так суров, что почти не чувствует боли.$B$BЯ впрыснул в дыни ядовитую смесь, так что не вздумай их есть!$B$BКак только он заметит тебя, бросай эти дыни на землю. Хоп-Хоп не упустит возможности полакомиться сладкой полосатой дыней.$b$bКак только он надкусит дыню, то на некоторое время ослабеет, и у тебя будет возможность напасть на него внезапно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Хоп-Хопа в Пещере Куньцзэнь на северо-западе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вожак хозенов Куньцзэнь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вождь Хоп-Хоп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30529,'Фермерство III: замшелый валун','Теперь, когда мы вступили в Союз земледельцев, господин Грязный Коготь сказал, что с радостью поможет нам сдвинуть огромный валун в центре поля.$B$BА потом мы сделаем кое-что особенное.$B$BСкорей беги к нему и сообщи, что мы готовы.','Юну нужна помощь? Ну, я с радостью ему помогу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермерство III: замшелый валун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы вступили в Союз земледельцев, господин Грязный Коготь сказал, что с радостью поможет нам сдвинуть огромный валун в центре поля.$B$BА потом мы сделаем кое-что особенное.$B$BСкорей беги к нему и сообщи, что мы готовы.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Юну нужна помощь? Ну, я с радостью ему помогу.',`offerrewardtext_loc8`);
