INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30534,'Вторые руки','Талисманы святилища тихонько позвякивают на ветру.','Вернитесь к святилищу земледельцев на Ферму Солнечной Песни, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторые руки',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Талисманы святилища тихонько позвякивают на ветру.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к святилищу земледельцев на Ферму Солнечной Песни, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30535,'Растениеводство I: семена','Ну, начнем с начала! Помощь мне всегда пригодится.$b$bЕсли хочешь быть моим компаньоном, тебе нужно научиться выращивать овощи. А для этого ты $gдолжен:должна; посадить семена!$B$BИ насколько я понимаю, господин Земляная Плюха... Нет, не так... Золотая Бляха? Тоже не то...$B$BЗеленое Поле! Вот как его зовут! В общем, семена нужно получить у него.$B$BЗеленое Поле торгует на рынке в Полугорье – это прямо на юго-восток отсюда. Иди к нему и возьми семена овощей.','Вернитесь к фермеру Юну на Ферму Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство I: семена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, начнем с начала! Помощь мне всегда пригодится.$b$bЕсли хочешь быть моим компаньоном, тебе нужно научиться выращивать овощи. А для этого ты $gдолжен:должна; посадить семена!$B$BИ насколько я понимаю, господин Земляная Плюха... Нет, не так... Золотая Бляха? Тоже не то...$B$BЗеленое Поле! Вот как его зовут! В общем, семена нужно получить у него.$B$BЗеленое Поле торгует на рынке в Полугорье – это прямо на юго-восток отсюда. Иди к нему и возьми семена овощей.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30536,'FLAG - Война с сорняками: обучение','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.','Выслушайте Сяо и его товарищей.','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Война с сорняками: обучение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Сяо и его товарищей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
