INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30565,'Неожиданное преимущество','$n, наши дела идут все лучше. Я тут гулял немного и набрел на эту маленькую красотку.$B$B<Салли указывает на баллисту, стоящую справа от него.>$B$BНо беда в том, что она парная, а ее сестричка еще не готова. Я бы сам ее собрал, если бы эти мерзкие твари из племени Злобного Оскала не напали на меня и не отняли некоторые детали.$B$BСлушай, а ведь ты здорово управляешься с аборигенами. Может, выручишь старину Салли, а?','Отнимите поврежденные водой механизмы и ржавые зажимные болты у хозенов к востоку.','Они, конечно, не так хороши, как она заслуживает, но они будут работать.$B$B<Салли поглаживает разобранную баллисту.>$B$BЯ мигом приведу ее в чувство, расслабься и смотри!','Ну, где мои запчасти?','Вернитесь к Салли "Рассольному" Маклири в Деревню Жемчужного Плавника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неожиданное преимущество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, наши дела идут все лучше. Я тут гулял немного и набрел на эту маленькую красотку.$B$B<Салли указывает на баллисту, стоящую справа от него.>$B$BНо беда в том, что она парная, а ее сестричка еще не готова. Я бы сам ее собрал, если бы эти мерзкие твари из племени Злобного Оскала не напали на меня и не отняли некоторые детали.$B$BСлушай, а ведь ты здорово управляешься с аборигенами. Может, выручишь старину Салли, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите поврежденные водой механизмы и ржавые зажимные болты у хозенов к востоку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они, конечно, не так хороши, как она заслуживает, но они будут работать.$B$B<Салли поглаживает разобранную баллисту.>$B$BЯ мигом приведу ее в чувство, расслабься и смотри!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где мои запчасти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири в Деревню Жемчужного Плавника.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30566,'FLAG - Проблемы с вредителями: обучение','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке. Я просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.','Выслушайте Сяо и его товарищей.','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Проблемы с вредителями: обучение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке. Я просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Сяо и его товарищей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30567,'"Громобой" Бланш','Чуешь этот запах? Приближается шторм! Разразится страшная буря – а у меня тут, между прочим, тоже бурная деятельность!$B$BКогда начнется шторм, разыщи меня на вершине холма, и тогда мы сварим бочонок моего самого знаменитого напитка. Я могу рассчитывать на твою помощь?$B$B','Завершите сценарий "Хмельная буря".','Вернитесь к Бланш. Она либо прогуливается по Нефритовому лесу, либо занимается делами у Хмелеварни Буйных Портеров в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Громобой" Бланш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чуешь этот запах? Приближается шторм! Разразится страшная буря – а у меня тут, между прочим, тоже бурная деятельность!$B$BКогда начнется шторм, разыщи меня на вершине холма, и тогда мы сварим бочонок моего самого знаменитого напитка. Я могу рассчитывать на твою помощь?$B$B',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите сценарий "Хмельная буря".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бланш. Она либо прогуливается по Нефритовому лесу, либо занимается делами у Хмелеварни Буйных Портеров в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30568,'Вклад в общее дело','$n, с возвращением! Знаешь, цзинь-юй обучаются быстрее, чем мне думалось! Мы уже заканчиваем.$B$BПожалуйста, разыщи Эмбер, Здоровяка Кажаши и Мишку. Узнай, не нужна ли им помощь с тренировками.$b$bКажаши и Мишку можно найти здесь, в Деревне Жемчужного Плавника. Эмбер занимается с новобранцами в Ямах Ловкого Хвоста к северо-западу отсюда.','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вклад в общее дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, с возвращением! Знаешь, цзинь-юй обучаются быстрее, чем мне думалось! Мы уже заканчиваем.$B$BПожалуйста, разыщи Эмбер, Здоровяка Кажаши и Мишку. Узнай, не нужна ли им помощь с тренировками.$b$bКажаши и Мишку можно найти здесь, в Деревне Жемчужного Плавника. Эмбер занимается с новобранцами в Ямах Ловкого Хвоста к северо-западу отсюда.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Деревню Жемчужного Плавника.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30569,'Проблемы на ферме','Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\r\n\r\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?','Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы на ферме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\r\n\r\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30570,'Проблемы на ферме','Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\r\n\r\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?','Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы на ферме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я... мне удалось бежать от крестьянина Чоу, он живет к юго-востоку отсюда. Ферма захвачена яунголами, но старик и его жена так просто не сдадутся!\r\n\r\nПрошу тебя, помоги ему. Может, тогда он согласится отправить сюда кого-нибудь, чтобы заготовить еду для вашего нового города?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с крестьянином Чоу на ферме Чоу, что на вершине Кунь-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30571,'Свободу рабам!','Яунголы ордо загоняют моих рабочих до смерти! Это не дело.$B$BПожалуйста, |3-6($c), спаси их, пока не поздно!','Освободите 12 рабов с фермы, убив надзирателей Ордо.','Ну разве ты не прелесть?$B$BХотя, наверное, это несправедливо – заставлять работников оставаться с нами теперь, когда у нас для них совсем мало работы...','Вернитесь к крестьянину Чоу на ферму Чоу, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу рабам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы ордо загоняют моих рабочих до смерти! Это не дело.$B$BПожалуйста, |3-6($c), спаси их, пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 12 рабов с фермы, убив надзирателей Ордо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну разве ты не прелесть?$B$BХотя, наверное, это несправедливо – заставлять работников оставаться с нами теперь, когда у нас для них совсем мало работы...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к крестьянину Чоу на ферму Чоу, что на вершине Кунь-Лай.',`completedtext_loc8`);
