INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30575,'Отлов яков','Мы должны иметь возможность быстро передвигаться, если хотим удержать эту землю. Но это невозможно без верховых животных, а их тут не так много, согласись.\r\n\r\nКажется, местных яков можно объездить. По крайней мере, пандарены так говорят. Ты можешь поймать несколько?','Вернитесь к адмиралу Тейлору в Приют Западного Ветра, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов яков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны иметь возможность быстро передвигаться, если хотим удержать эту землю. Но это невозможно без верховых животных, а их тут не так много, согласись.\r\n\r\nКажется, местных яков можно объездить. По крайней мере, пандарены так говорят. Ты можешь поймать несколько?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Приют Западного Ветра, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30581,'...а еще котелок!','Конечно, я хочу помочь вам. Но нам тоже нужно что-то есть, а у меня нет даже котелка, не говоря уж о том, что в него положить!$B$BВот список того, что мне нужно. Вперед, достань все это!','Собрать 12 корнеплодов и 1 чугунный котелок.','Вот это я понимаю. Теперь можно и за готовку браться.','У тебя все по списку собрано?','Вернитесь к Уен Чоу на ферму Чоу, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...а еще котелок!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, я хочу помочь вам. Но нам тоже нужно что-то есть, а у меня нет даже котелка, не говоря уж о том, что в него положить!$B$BВот список того, что мне нужно. Вперед, достань все это!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Собрать 12 корнеплодов и 1 чугунный котелок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это я понимаю. Теперь можно и за готовку браться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя все по списку собрано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уен Чоу на ферму Чоу, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30582,'Покойная госпожа Мускусная Лапа','На потертом браслете несколько отметин – знаки любви и обожания покойной госпожи Мускусной Лапы.$b$bНаверняка Лао захочет получить эту вещицу назад.','Принесите Лао Мускусной Лапе подарок его жены.','Хм, что это у тебя...','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покойная госпожа Мускусная Лапа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На потертом браслете несколько отметин – знаки любви и обожания покойной госпожи Мускусной Лапы.$b$bНаверняка Лао захочет получить эту вещицу назад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Лао Мускусной Лапе подарок его жены.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, что это у тебя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30583,'Дворфу очень нужно мясо','Эй!\r\n\r\nНам нужно еды раздобыть, если мы тут не хотим с голодухи помереть.$B$BТы, может, не знаешь, но из меня повар хороший. Иди-ка мяса набери, а я его заготовлю, надолго хватит. На много месяцев. Или недель. На несколько дней уж точно.','Соберите 160 мясных кусочков Кунь-Лай.','Вот это дело! Точно тебе говорю, эти обрезки – просто пальчики оближешь!','Ну что, есть мясо?','Вернитесь к Салли "Рассольному" Маклири в Приют Западного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфу очень нужно мясо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй!\r\n\r\nНам нужно еды раздобыть, если мы тут не хотим с голодухи помереть.$B$BТы, может, не знаешь, но из меня повар хороший. Иди-ка мяса набери, а я его заготовлю, надолго хватит. На много месяцев. Или недель. На несколько дней уж точно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 160 мясных кусочков Кунь-Лай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это дело! Точно тебе говорю, эти обрезки – просто пальчики оближешь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, есть мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30584,'Электрошок!','Ты $gел:ела; когда-нибудь свежего доцзянского угря, $n? Нет? Ну, тогда ты, считай, и не $gжил:жила;!$b$bОтправляйся к реке Доцзян и налови нам несколько угрей. Но будь $gосторожен:осторожна;, они могут ударить током!','Поймайте 7 доцзянских угрей в реке Доцзян в Красарангских джунглях.','Какие аппетитные угри, Славентик! Тебе они точно понравятся!','Получилось поймать угрей?','Отнесите угрей рыбаку Хайто в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Электрошок!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gел:ела; когда-нибудь свежего доцзянского угря, $n? Нет? Ну, тогда ты, считай, и не $gжил:жила;!$b$bОтправляйся к реке Доцзян и налови нам несколько угрей. Но будь $gосторожен:осторожна;, они могут ударить током!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 7 доцзянских угрей в реке Доцзян в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие аппетитные угри, Славентик! Тебе они точно понравятся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось поймать угрей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите угрей рыбаку Хайто в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30585,'В тихом омуте','Легенда гласит, что в лесу к северу отсюда живет огромное чудовище. Мой сын пропал, и я боюсь, что он мог подойти слишком близко к его логову...$b$bИди на северо-запад к Красарангскому водопаду и разыщи там таинственный водоворот – это и есть ключ к разгадке. Убей гнусное чудовище и узнай хоть что-нибудь о моем сыне.','Найдите древний рыбацкий пруд у Красарангского водопада, что к северо-западу отсюда, и ловите в нем рыбу, чтобы выманить чудовище из укрытия.','Кольцо моего сына? Что бы это значило?$B$B<Рассан задумывается.>$B$BСитуция мрачная, но не безнадежная. Мой сын не очень-то следит за своими вещами – может, он просто бросил кольцо в воду? Спасибо за помощь, Славентик – я не забуду о той великой услуге, что ты мне оказал.','Есть новости о моем сыне?','Отнесите кольцо старшему рыбаку Рассану в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В тихом омуте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легенда гласит, что в лесу к северу отсюда живет огромное чудовище. Мой сын пропал, и я боюсь, что он мог подойти слишком близко к его логову...$b$bИди на северо-запад к Красарангскому водопаду и разыщи там таинственный водоворот – это и есть ключ к разгадке. Убей гнусное чудовище и узнай хоть что-нибудь о моем сыне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите древний рыбацкий пруд у Красарангского водопада, что к северо-западу отсюда, и ловите в нем рыбу, чтобы выманить чудовище из укрытия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кольцо моего сына? Что бы это значило?$B$B<Рассан задумывается.>$B$BСитуция мрачная, но не безнадежная. Мой сын не очень-то следит за своими вещами – может, он просто бросил кольцо в воду? Спасибо за помощь, Славентик – я не забуду о той великой услуге, что ты мне оказал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости о моем сыне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите кольцо старшему рыбаку Рассану в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30586,'Морские ушки','Уже несколько поколений пандаренов собирают здесь морские ушки. Пора и тебе приобщиться к этому ритуалу.$b$bНайти морские ушки можно к северо-востоку отсюда, в Поющей Котловине. Но будь $gосторожен:осторожна; – туда в последнее время зачастили акулы.','Соберите 9 кусков мяса морских ушек в Поющей Котловине на на северо-востоке.','О! Похоже, ты собрал изрядно моллюсков. Молодцом, Славентик!','А акул там не было?','Отнесите мясо рыбаку Хайто в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морские ушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже несколько поколений пандаренов собирают здесь морские ушки. Пора и тебе приобщиться к этому ритуалу.$b$bНайти морские ушки можно к северо-востоку отсюда, в Поющей Котловине. Но будь $gосторожен:осторожна; – туда в последнее время зачастили акулы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 кусков мяса морских ушек в Поющей Котловине на на северо-востоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Похоже, ты собрал изрядно моллюсков. Молодцом, Славентик!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А акул там не было?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите мясо рыбаку Хайто в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30587,'Як и так, и сяк','Похоже, что яунголы повадились воровать яков. Осмотрев местность, вы убеждаетесь, что напасть на якомойку не составляет никакого труда.$b$bЕсли вы вырежете нескольких яунголов, они поймут, что эту область охраняют.','Убейте 9 хияккеров-разорителей на ферме Мускусной Лапы.','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Як и так, и сяк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, что яунголы повадились воровать яков. Осмотрев местность, вы убеждаетесь, что напасть на якомойку не составляет никакого труда.$b$bЕсли вы вырежете нескольких яунголов, они поймут, что эту область охраняют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 хияккеров-разорителей на ферме Мускусной Лапы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30588,'Рыбалка не задалась','Сауроки из клана Речного Клинка нападают на наших рыбаков! Им нужно срочно помочь!$b$bУбей сауроков и помоги рыбакам вернуться домой.','Убейте 8 береговых налетчиков Речного Клинка у Рыболовной экспедиции, что к западу от Деревни рыболовов.','Рыбаки теперь в безопасности. Спасибо, Славентик.','Сообщите хорошие новости удильщику Шэню в Деревню рыболовов.','Сауроки – яростные бойцы из джунглей, с ними не стоит шутить.','Разоритель Речного Клинка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыбалка не задалась',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки из клана Речного Клинка нападают на наших рыбаков! Им нужно срочно помочь!$b$bУбей сауроков и помоги рыбакам вернуться домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 береговых налетчиков Речного Клинка у Рыболовной экспедиции, что к западу от Деревни рыболовов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рыбаки теперь в безопасности. Спасибо, Славентик.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите хорошие новости удильщику Шэню в Деревню рыболовов.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сауроки – яростные бойцы из джунглей, с ними не стоит шутить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Разоритель Речного Клинка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30589,'Разрушение крушения','Чтобы выбить корабль Альянса, нам нужно найти нашего инженера. Мы расстались с ним, когда спасались после крушения.$B$BДумаю, ты найдешь его где-то в лесу, к западу отсюда. Скажи, что тебя прислал Керга, и он с радостью поможет тебе.','Поговорите с Макаэлем Бэем в лесу Пэй-У.','Так тебя прислал Керга? Пожалуй, я и сам не прочь разобраться с этим кораблем, но для этого придется немного поработать.$B$BДай-ка подумать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушение крушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы выбить корабль Альянса, нам нужно найти нашего инженера. Мы расстались с ним, когда спасались после крушения.$B$BДумаю, ты найдешь его где-то в лесу, к западу отсюда. Скажи, что тебя прислал Керга, и он с радостью поможет тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Макаэлем Бэем в лесу Пэй-У.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя прислал Керга? Пожалуй, я и сам не прочь разобраться с этим кораблем, но для этого придется немного поработать.$B$BДай-ка подумать...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30590,'Не кантовать','Мы можем помочь вам освободить корабль, но для этого нам понадобится побольше взрывчатки, которую мы пытались забрать обратно у Альянса.$B$BПеред бегством я приказал своим людям вынести всю взрывчатку, какую они смогли найти. К югу отсюда много обломков и трупов, там же можно найти и взрывчатку, которая еще не успела взорваться.$B$BПринеси мне достаточное ее количество, и я смогу из нее что-нибудь сообразить.','Найдите 6 зарядов взрывчатки.','Более чем достаточно. Я уже собрал главную панель управления. Еще немного времени – и все будет готово!','Вернитесь к Макаэлю Бэю в лес Пэй-У.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не кантовать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы можем помочь вам освободить корабль, но для этого нам понадобится побольше взрывчатки, которую мы пытались забрать обратно у Альянса.$B$BПеред бегством я приказал своим людям вынести всю взрывчатку, какую они смогли найти. К югу отсюда много обломков и трупов, там же можно найти и взрывчатку, которая еще не успела взорваться.$B$BПринеси мне достаточное ее количество, и я смогу из нее что-нибудь сообразить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 зарядов взрывчатки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Более чем достаточно. Я уже собрал главную панель управления. Еще немного времени – и все будет готово!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макаэлю Бэю в лес Пэй-У.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30591,'Охота на хищников','Этот лес стал куда опаснее с тех пор, как Шэнь-Цзынь Су начал сотрясаться. Потревоженные этой тряской тигры начали нападать на беженцев – и даже на меня.$B$BНам нужно позаботиться о том, чтобы в лесу было безопасно – ради пострадавших и раненых, что собираются здесь.','Убейте 9 тигров Пэй-У.','Вернитесь к Вэю Бледной Ярости в Одинокую хижину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на хищников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот лес стал куда опаснее с тех пор, как Шэнь-Цзынь Су начал сотрясаться. Потревоженные этой тряской тигры начали нападать на беженцев – и даже на меня.$B$BНам нужно позаботиться о том, чтобы в лесу было безопасно – ради пострадавших и раненых, что собираются здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 тигров Пэй-У.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэю Бледной Ярости в Одинокую хижину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30592,'Спасибо тебе, друг груммелей. Тебя ждет удача. Но путь к Змеиному Хребту все еще опасен.','Поговорите с братом Средняя Тропа на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, друг груммелей. Тебя ждет удача. Но путь к Змеиному Хребту все еще опасен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Средняя Тропа на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30593,'Упокоить беспокойных','Уничтожьте 14 терракотовых воинов или терракотовых стражей.','Вернитесь к Мишке в Приют Западного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упокоить беспокойных',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 14 терракотовых воинов или терракотовых стражей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30594,'Упокоить беспокойных','У меня тут много дел, $n. Мне бы пригодилась твоя помощь.$B$BК северо-западу есть область, которую местные называют Могуцзя. Тамошние статуи почему-то оживают, наши пандарены в ужасе от этой новости...$B$BЕсли кто-нибудь не разберется с этой проблемой, могут начаться серьезные неприятности. Мы только что расположились здесь и не можем позволить себе воевать со статуями прямо сейчас.','Уничтожьте 14 терракотовых воинов или терракотовых стражей.','Вопрос со статуями решен, так? Хорошо. У меня есть еще кое-что для тебя.','Разве ты не $gсобирался:собиралась; покончить с этими статуями могу, чтобы они нас тут всех не перебили?','Вернитесь к темному мастеру Кирин в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упокоить беспокойных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня тут много дел, $n. Мне бы пригодилась твоя помощь.$B$BК северо-западу есть область, которую местные называют Могуцзя. Тамошние статуи почему-то оживают, наши пандарены в ужасе от этой новости...$B$BЕсли кто-нибудь не разберется с этой проблемой, могут начаться серьезные неприятности. Мы только что расположились здесь и не можем позволить себе воевать со статуями прямо сейчас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 14 терракотовых воинов или терракотовых стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вопрос со статуями решен, так? Хорошо. У меня есть еще кое-что для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве ты не $gсобирался:собиралась; покончить с этими статуями могу, чтобы они нас тут всех не перебили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30595,'Ценный антиквариат','Дай угадать, ты $gпришел:пришла; разобраться с ожившими статуями могу? Какое совпадение, а я тут, э-э, провожу кое-какие исследования, касающиеся могу.$B$BЯ тебе вот что скажу. Если притащишь столько реликвий, сколько сможешь унести, я поделюсь с тобой кое-чем: средствами... для финансирования моих исследований.','Соберите 12 реликвий могу.','Куда мне положить все эти реликвии?','Вернитесь к Бао Цзяню в Могуцзя, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный антиквариат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дай угадать, ты $gпришел:пришла; разобраться с ожившими статуями могу? Какое совпадение, а я тут, э-э, провожу кое-какие исследования, касающиеся могу.$B$BЯ тебе вот что скажу. Если притащишь столько реликвий, сколько сможешь унести, я поделюсь с тобой кое-чем: средствами... для финансирования моих исследований.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 реликвий могу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Куда мне положить все эти реликвии?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бао Цзяню в Могуцзя, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30596,'Зандаларский тролль?','Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.','Убейте зандаларского воскресителя.','Вернитесь к Мишке в Приют Западного ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский тролль?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте зандаларского воскресителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в Приют Западного ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30598,'Кто знал, что рыбам нравятся яйца?','Огромные журавли гнездятся здесь уже несколько поколений. На Поющих Вершинах они находят укрытие, где можно высиживать птенцов.$b$bНетронутые яйца этих журавлей – отличная приманка для серебристых бычков. Раздобудь такое яйцо и попробуй поймать на него бычка!','Заберите нетронутое яйцо с Поющих Вершин и используйте его как наживку для ловли серебристого бычка.','Редкий серебристый бычок! Куанчи, да ты становишься настоящим рыбаком!','Ты поймал серебристого бычка?','Принесите серебристого бычка старшему рыбаку Рассану в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто знал, что рыбам нравятся яйца?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромные журавли гнездятся здесь уже несколько поколений. На Поющих Вершинах они находят укрытие, где можно высиживать птенцов.$b$bНетронутые яйца этих журавлей – отличная приманка для серебристых бычков. Раздобудь такое яйцо и попробуй поймать на него бычка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите нетронутое яйцо с Поющих Вершин и используйте его как наживку для ловли серебристого бычка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Редкий серебристый бычок! Куанчи, да ты становишься настоящим рыбаком!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поймал серебристого бычка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите серебристого бычка старшему рыбаку Рассану в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30599,'Обезьяний идол','Давным-давно, чтобы предотвратить устраиваемые хозенами погромы, груммели делились с хозенами едой.$b$bНо теперь у племени Ломаного Зуба, которое обитает к югу отсюда, есть большие магические идолы. Ук Всего Дука научил их получать силу с помощью идолов.$b$bОни убивают груммелей идолами!$b$bТы $gдолжен:должна; уничтожить эти идолы.$b$bКаждый из них охраняет вождь. Убей вождя и брось его труп на алтарь.','Положите тела Так-Така, Дак-Дака и Ко-Ко на алтари, которые они охраняют.','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезьяний идол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно, чтобы предотвратить устраиваемые хозенами погромы, груммели делились с хозенами едой.$b$bНо теперь у племени Ломаного Зуба, которое обитает к югу отсюда, есть большие магические идолы. Ук Всего Дука научил их получать силу с помощью идолов.$b$bОни убивают груммелей идолами!$b$bТы $gдолжен:должна; уничтожить эти идолы.$b$bКаждый из них охраняет вождь. Убей вождя и брось его труп на алтарь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите тела Так-Така, Дак-Дака и Ко-Ко на алтари, которые они охраняют.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30600,'Важные вещи','Хозены из племени Ломаного Зуба, которые обитают к югу отсюда, убили всех моих груммелей. И, что еще хуже, погибшие груммели не смогли доставить свои вещи.$b$bПрошу, принеси им покой на великой тропе в нижний мир и верни мне их тюки.$b$bА уж я прослежу, чтобы они попали куда надо.','Найдите 8 тюков груммелей в лагере Ломаного Зуба или в Глубокой пещере.','Груммели простой народ. Наше дело – исследовать и доставлять.','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важные вещи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены из племени Ломаного Зуба, которые обитают к югу отсюда, убили всех моих груммелей. И, что еще хуже, погибшие груммели не смогли доставить свои вещи.$b$bПрошу, принеси им покой на великой тропе в нижний мир и верни мне их тюки.$b$bА уж я прослежу, чтобы они попали куда надо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 тюков груммелей в лагере Ломаного Зуба или в Глубокой пещере.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Груммели простой народ. Наше дело – исследовать и доставлять.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30601,'Когда храбрость ведет, счастье ей сопутствует.','Большая неудача, если идешь в горы без хорошего проводника. Груммели лучше всех покажут дорогу, но многие убежали. Они боятся перевала. Там пропало много хороших груммелей.$b$bГруммели много вещей делают хорошо, но они не храбрые. Может, фимиам огненного лотоса сделает их храбрыми. Тогда они покажут тебе путь.','Убедите 3-х скрывающихся проводников в пещере Ревущего Ветра помочь вам.','Благовония – прямо как чары! Торопись, это длится недолго.','Вернитесь к дядюшке Листу Клевера в Пэй-Лэй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда храбрость ведет, счастье ей сопутствует.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая неудача, если идешь в горы без хорошего проводника. Груммели лучше всех покажут дорогу, но многие убежали. Они боятся перевала. Там пропало много хороших груммелей.$b$bГруммели много вещей делают хорошо, но они не храбрые. Может, фимиам огненного лотоса сделает их храбрыми. Тогда они покажут тебе путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убедите 3-х скрывающихся проводников в пещере Ревущего Ветра помочь вам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благовония – прямо как чары! Торопись, это длится недолго.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дядюшке Листу Клевера в Пэй-Лэй.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30602,'Кроличья Лапка','Хозены Ломаного Зуба похитили Кроличью Лапку! Этот груммель – самая большая удачка.$b$bТак не повезло! Пожалуйста, |3-6($r), помоги вернуть его! Нам так нужна его удача.$b$bМожешь поискать его на заставе Ломаного Зуба?','Спасите брата Кроличью Лапку с заставы Ломаного Зуба.','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кроличья Лапка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены Ломаного Зуба похитили Кроличью Лапку! Этот груммель – самая большая удачка.$b$bТак не повезло! Пожалуйста, |3-6($r), помоги вернуть его! Нам так нужна его удача.$b$bМожешь поискать его на заставе Ломаного Зуба?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите брата Кроличью Лапку с заставы Ломаного Зуба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30603,'Набег Ломаного Зуба','И они стащили мой талисман на удачу! Здешний вожак хозенов Мо-Мо украл мою кроличью лапку.$b$bЭто самый дурной знак для груммеля. Моя лапка приносила удачу груммелям повсюду. Если хозены поймут, как сделать удачу из лапки, все пропало.$b$bПожалуйста, можешь вернуть ее?','Заберите счастливую кроличью лапку у Мо-Мо.','Мой талисман! Счастливый день и большая удача! Огромное спасибо!','Груммелей зовут по удачкам, которые приносят везение кому-то из груммелей. Важно, чтобы хозены не украли удачу.','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набег Ломаного Зуба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И они стащили мой талисман на удачу! Здешний вожак хозенов Мо-Мо украл мою кроличью лапку.$b$bЭто самый дурной знак для груммеля. Моя лапка приносила удачу груммелям повсюду. Если хозены поймут, как сделать удачу из лапки, все пропало.$b$bПожалуйста, можешь вернуть ее?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите счастливую кроличью лапку у Мо-Мо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой талисман! Счастливый день и большая удача! Огромное спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Груммелей зовут по удачкам, которые приносят везение кому-то из груммелей. Важно, чтобы хозены не украли удачу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30604,'Вырывая Ломаный Зуб','Хозены разоряют нас, если думают, что у них недостаточно припасов для всех.$b$bХозены плодятся как гну-синь, у них тоже ртов всегда больше, чем еды.$b$bГруммелей немного, сейчас осталось совсем мало.$b$bОб этом сложно просить, но... Можешь стать другом груммелей и убить несколько хозенов Ломаного Зуба? Это единственный способ уберечь земли от опустошения.','Убейте 8 бойцов Ломаного Зуба и 6 метателей Ломаного Зуба.','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вырывая Ломаный Зуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозены разоряют нас, если думают, что у них недостаточно припасов для всех.$b$bХозены плодятся как гну-синь, у них тоже ртов всегда больше, чем еды.$b$bГруммелей немного, сейчас осталось совсем мало.$b$bОб этом сложно просить, но... Можешь стать другом груммелей и убить несколько хозенов Ломаного Зуба? Это единственный способ уберечь земли от опустошения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 бойцов Ломаного Зуба и 6 метателей Ломаного Зуба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (30605,'Спасите Брата Ячью Подкову.','Поговорите с Братом Ячьей Подковой в логове Тяжелого Когтя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Брата Ячью Подкову.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Ячьей Подковой в логове Тяжелого Когтя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30606,'Тяжелая участь Тяжелого Когтя','У хозенов Тяжелого Когтя появился новый вожак, Ук Всего Дука.$b$bОн видит страх на западе, гнев на юге, ненависть на севере и яунголов на востоке.$b$bИ он посылает своих хозенов разорять все вокруг и запасать припасы перед голодом.$b$bЭтих хозенов много, они опасны.$b$bУдачка, прошу тебя, сможешь победить их бойцов?','Убейте 8 крушителей или пронзателей из племени Тяжелого Когтя в логове Тяжелого Когтя.','У тебя и вправду много удачи!','Поговорите с братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелая участь Тяжелого Когтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У хозенов Тяжелого Когтя появился новый вожак, Ук Всего Дука.$b$bОн видит страх на западе, гнев на юге, ненависть на севере и яунголов на востоке.$b$bИ он посылает своих хозенов разорять все вокруг и запасать припасы перед голодом.$b$bЭтих хозенов много, они опасны.$b$bУдачка, прошу тебя, сможешь победить их бойцов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 крушителей или пронзателей из племени Тяжелого Когтя в логове Тяжелого Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя и вправду много удачи!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Кроличьей Лапкой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30607,'Хозены любят ключи','У хозенов есть йети! Они зовут его старик Пуф-Пуф и держат в задней части пещеры.$b$bОбычно хозены сами боятся стать завтраком для йети, но теперь они кормят их груммелями.$b$bТам есть главный хозен, который сторожит зверя. Можешь узнать, есть ли у него ключи от оков йети?$b$bБольшая неудача для хозенов, если йети будет гулять по форту.','Добудьте ключи от оков йети у Чо Чо Злонравного и освободите Старика Пуф-Пуфа.','Ого-го! Ну и поездочка!','Тот, у кого много удачи, никогда не поедет на грязном яке рядом с йети.','Поговорите с Братом Ячьей Подковой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозены любят ключи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У хозенов есть йети! Они зовут его старик Пуф-Пуф и держат в задней части пещеры.$b$bОбычно хозены сами боятся стать завтраком для йети, но теперь они кормят их груммелями.$b$bТам есть главный хозен, который сторожит зверя. Можешь узнать, есть ли у него ключи от оков йети?$b$bБольшая неудача для хозенов, если йети будет гулять по форту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключи от оков йети у Чо Чо Злонравного и освободите Старика Пуф-Пуфа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого-го! Ну и поездочка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тот, у кого много удачи, никогда не поедет на грязном яке рядом с йети.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Ячьей Подковой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30608,'Закуска из груммелей','Они утащили моих груммелей! Хозены не едят груммелей, а вот йети едят. У хозенов Тяжелого Когтя есть йети!$b$bПрошу, спаси моих груммелей. Выпусти их из клеток или перережь веревки, на которых они висят. Спаси их, как можешь!$b$bНаграда и удача – твои, если сделаешь это.','Спасите 5 захваченных груммелей, открыв клетки или перерезав веревки, на которых они висят.','Поговорите с Братом Ячьей Подковой на путевой станции Джутового Пути на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закуска из груммелей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они утащили моих груммелей! Хозены не едят груммелей, а вот йети едят. У хозенов Тяжелого Когтя есть йети!$b$bПрошу, спаси моих груммелей. Выпусти их из клеток или перережь веревки, на которых они висят. Спаси их, как можешь!$b$bНаграда и удача – твои, если сделаешь это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 захваченных груммелей, открыв клетки или перерезав веревки, на которых они висят.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Ячьей Подковой на путевой станции Джутового Пути на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30609,'Минимальные потери') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минимальные потери',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30610,'Груммель! Груммель! Груммель!','Теперь груммели в безопасности, надо вернуть припасы.$b$bВеликий вождь седошкурых, Ук Всего Дука, потому и великий, что все припасы у него.$b$bИди к Дукерскому Куполу, это на северо-запад. Возьми груммелей. Смотри за ними, проведи их к ящикам с припасами.$b$bДальше они знают, что делать.$b$bВстретимся там.','Проведите 5 груммелей налегке к ящикам с припасами возле Дукерского Купола.','Теперь король хозенов узнает, почему не стоит шутить с груммелями.','Поговорите с Братом Ячьей Подковой у Дукерского Купола на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груммель! Груммель! Груммель!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь груммели в безопасности, надо вернуть припасы.$b$bВеликий вождь седошкурых, Ук Всего Дука, потому и великий, что все припасы у него.$b$bИди к Дукерскому Куполу, это на северо-запад. Возьми груммелей. Смотри за ними, проведи их к ящикам с припасами.$b$bДальше они знают, что делать.$b$bВстретимся там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите 5 груммелей налегке к ящикам с припасами возле Дукерского Купола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь король хозенов узнает, почему не стоит шутить с груммелями.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Ячьей Подковой у Дукерского Купола на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30611,'Освободить йети!','Эта поездка на йети навела меня на кое-какие мысли. Ук Всего Дука держит в качестве домашнего животного йети по кличке Хрумк-Хрумк.$b$bОн запугивает им других хозенов, и они считают его великим предводителем. Надо избавиться от этого йети.$b$bОтправляйся к Дукерскому Куполу, он к северо-западу отсюда, и победи нескольких смотрителей клетки, чтобы ослабить путы Хрумк-Хрумка.$b$bМы с Ячьей Подковой встретим тебя там с множеством благовоний и грязным яком.','Убейте 4-х смотрителей клетки.','Мы нашли яка. Ты разобрался с хозенами?','Поговорите с Братом Кроличьей Лапкой на Дукерском Куполе на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободить йети!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта поездка на йети навела меня на кое-какие мысли. Ук Всего Дука держит в качестве домашнего животного йети по кличке Хрумк-Хрумк.$b$bОн запугивает им других хозенов, и они считают его великим предводителем. Надо избавиться от этого йети.$b$bОтправляйся к Дукерскому Куполу, он к северо-западу отсюда, и победи нескольких смотрителей клетки, чтобы ослабить путы Хрумк-Хрумка.$b$bМы с Ячьей Подковой встретим тебя там с множеством благовоний и грязным яком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4-х смотрителей клетки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы нашли яка. Ты разобрался с хозенами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой на Дукерском Куполе на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30612,'Вожак хозенов','Настало время сразиться с Уком Всего Дука. Если мы его победим, хозенам никто не будет приказывать разорять и грабить.$b$bПлан таков: Ячья Подкова поведет на арену Кисточку и спугнет Хрумк-Хрумка.$b$bЗатем появишься ты и сразишься с Уком Всего Дука, пока внимание хозенов будет отвлечено на йети, бесчинствующего в их доме.$b$bМы встретим тебя в лагере Коту с большой наградой. Удачи тебе, друг груммелей.','Разозлите Хрумк-Хрумка, а затем победите Ука всего Дука.','Ук Всего Дука мертв! Ур-р-р-ра!','Поговорите с Братом Кроличьей Лапкой в лагере Коту на вершине Кунь-Лай.','Вождь горных племен.','Ук Всего Дука') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вожак хозенов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время сразиться с Уком Всего Дука. Если мы его победим, хозенам никто не будет приказывать разорять и грабить.$b$bПлан таков: Ячья Подкова поведет на арену Кисточку и спугнет Хрумк-Хрумка.$b$bЗатем появишься ты и сразишься с Уком Всего Дука, пока внимание хозенов будет отвлечено на йети, бесчинствующего в их доме.$b$bМы встретим тебя в лагере Коту с большой наградой. Удачи тебе, друг груммелей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разозлите Хрумк-Хрумка, а затем победите Ука всего Дука.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ук Всего Дука мертв! Ур-р-р-ра!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Братом Кроличьей Лапкой в лагере Коту на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вождь горных племен.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ук Всего Дука',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30613,'Крепкочешуйчатый карп','Крепкочешуйчатый карп в этих краях – настоящее лакомство.$b$bУвы, поймать их нам не удается – своими мощными челюстями они перекусывают крючки. Возьми эту рыболовную пику и попробуй с ее помощью добыть нам карпов.','Поймайте с помощью рыболовной пики 5 крепкочешуйчатых карпов в водах к югу от Деревни рыболовов.','Осторожнее с карпами, Джестерок. Они и пальцы порой откусывают!','Удалось поймать что-нибудь с помощью пики?','Отнесите крепкочешуйчатого карпа рыбаку Йотимо в Деревню рыболовов.','Крючок здесь не поможет.','Крепкочешуйчатый карп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепкочешуйчатый карп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепкочешуйчатый карп в этих краях – настоящее лакомство.$b$bУвы, поймать их нам не удается – своими мощными челюстями они перекусывают крючки. Возьми эту рыболовную пику и попробуй с ее помощью добыть нам карпов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте с помощью рыболовной пики 5 крепкочешуйчатых карпов в водах к югу от Деревни рыболовов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осторожнее с карпами, Джестерок. Они и пальцы порой откусывают!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось поймать что-нибудь с помощью пики?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите крепкочешуйчатого карпа рыбаку Йотимо в Деревню рыболовов.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Крючок здесь не поможет.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Крепкочешуйчатый карп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30614,'Нефтяная остановка','Когда яунголы пришли сюда, они начали копать в поисках нефти. Что это вообще за "нефть"? А вдруг эта штука – огромный источник удачи? Это надо выяснить.$b$bВот, возьми этот сосуд и заполни его яунгольской нефтью у одного из ветряков. Если добудешь мне немного, в награду получишь много удачки.','Наполните пустой сосуд для нефти у яунгольской нефтяной вышки.','Удачного дня! Возьми это и используй с осторожностью.','Яунголы и так опасны. А яунголы с такой "нефтяной" удачей еще хуже.','Поговорите с Липким Пятном на базаре груммелей на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нефтяная остановка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда яунголы пришли сюда, они начали копать в поисках нефти. Что это вообще за "нефть"? А вдруг эта штука – огромный источник удачи? Это надо выяснить.$b$bВот, возьми этот сосуд и заполни его яунгольской нефтью у одного из ветряков. Если добудешь мне немного, в награду получишь много удачки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой сосуд для нефти у яунгольской нефтяной вышки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удачного дня! Возьми это и используй с осторожностью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яунголы и так опасны. А яунголы с такой "нефтяной" удачей еще хуже.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Липким Пятном на базаре груммелей на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30615,'Зандаларский тролль?','Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.','Убейте зандаларского воскресителя.','Вернитесь к темному мастеру Кирин в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский тролль?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда вы уничтожали статуи могу, вам послышался характерный говор тролля из племени Зандалар.$B$BОчевидно, это серьезная угроза для Приюта Западного ветра, с троллем надо что-то делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте зандаларского воскресителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30616,'Пробки на дорогах','Убейте 8 яунголов в Огненном лагере Жу-Цзинь.','Поговорите с Дымчатым Копотнем на базаре груммелей на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробки на дорогах',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 яунголов в Огненном лагере Жу-Цзинь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дымчатым Копотнем на базаре груммелей на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30617,'Удача в пути','Тот, с кем удача всегда, должен брать благовония в горы, чем ароматнее они – тем лучше.$b$bМожешь подняться к Пэй-Лэй и возжечь благовония, которые встретятся тебе по пути?$b$bЭто принесет удачу всем груммелям, которые пойдут той дорогой.$b$bБрат Перекатыш хорошо наградит тебя. Поговори с ним, когда прибудешь на место.','Зажгите 8 джутовых благовоний удачи по пути в Пэй-Лэй.','Добро пожаловать в Пэй-Лэй! Отсюда открывается дорога к Джутовому Пути и горе Неутомимых.','Поговорите с братом Перекатышем в Пэй-Лэй на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удача в пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот, с кем удача всегда, должен брать благовония в горы, чем ароматнее они – тем лучше.$b$bМожешь подняться к Пэй-Лэй и возжечь благовония, которые встретятся тебе по пути?$b$bЭто принесет удачу всем груммелям, которые пойдут той дорогой.$b$bБрат Перекатыш хорошо наградит тебя. Поговори с ним, когда прибудешь на место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите 8 джутовых благовоний удачи по пути в Пэй-Лэй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Пэй-Лэй! Отсюда открывается дорога к Джутовому Пути и горе Неутомимых.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Перекатышем в Пэй-Лэй на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30618,'Возвращение припасов в Пэй-Лэй','Если ты ищешь лучшие товары в Кунь-Лай, то $gпришел:пришла; по адресу! Конечно, здесь немного пустовато, но это лишь видимость...$b$bДа кого я обманываю? О каких поставках может идти речь, когда на нас постоянно совершают набеги хозены, а еще, будто этого мало, нас разграбляют грелли... У меня на складах почти ничего не осталось.$b$bЕсли ты поможешь вернуть хотя бы часть моих запасов, я дам тебе скидку в магазине.','Разыщите 8 украденных припасов в пещере Ревущего Ветра.','Ну как, удалось отыскать что-нибудь из моих припасов?','Вернитесь к Здоровяку Салю в Пэй-Лэй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение припасов в Пэй-Лэй',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты ищешь лучшие товары в Кунь-Лай, то $gпришел:пришла; по адресу! Конечно, здесь немного пустовато, но это лишь видимость...$b$bДа кого я обманываю? О каких поставках может идти речь, когда на нас постоянно совершают набеги хозены, а еще, будто этого мало, нас разграбляют грелли... У меня на складах почти ничего не осталось.$b$bЕсли ты поможешь вернуть хотя бы часть моих запасов, я дам тебе скидку в магазине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите 8 украденных припасов в пещере Ревущего Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось отыскать что-нибудь из моих припасов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Здоровяку Салю в Пэй-Лэй.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30619,'Я больше не могу!','Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\r\n\r\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\r\n\r\nЛадно, скажем просто: могу – это очень плохо.\r\n\r\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.','Убейте призывателя душ Могуцзя.','Еще недавно я не дал бы ни гроша за наши жизни.$B$BТы не представляешь, на что они способны.$B$BХотя, думаю, уже представляешь, и хорошо. Ну, в какой-то мере.$B$BПредставь себе такую жизнь, только еще хуже, и так пару тысяч лет.','Вернитесь к старейшине Цуланю в Приют Западного Ветра на вершине Кунь-Лай.','Настоящий источник бед в Могуцзя…','Призыватель духов Могуцзя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я больше не могу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\r\n\r\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\r\n\r\nЛадно, скажем просто: могу – это очень плохо.\r\n\r\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте призывателя душ Могуцзя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще недавно я не дал бы ни гроша за наши жизни.$B$BТы не представляешь, на что они способны.$B$BХотя, думаю, уже представляешь, и хорошо. Ну, в какой-то мере.$B$BПредставь себе такую жизнь, только еще хуже, и так пару тысяч лет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Цуланю в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Настоящий источник бед в Могуцзя…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Призыватель духов Могуцзя',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30620,'Я больше не могу!','Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\r\n\r\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\r\n\r\nЛадно, скажем просто: могу – это очень плохо.\r\n\r\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.','Убейте призывателя душ Могуцзя.','Что за крики доносятся с гор? Это зандаларская речь?$B$BКакого дьявола занадаларские тролли забыли в Пандарии?','Вернитесь к старейшине Шиао в Приют Восточного Ветра на вершине Кунь-Лай.','Настоящий источник бед в Могуцзя…','Призыватель духов Могуцзя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я больше не могу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с друзьями все еще обсуждаете ожившие статуи в Могуцзя, но я скажу тебе кое о чем пострашнее.\r\n\r\nГде оживают статуи, там поблизости и могу. Не знаю, встречались ли они тебе, но если нет...\r\n\r\nЛадно, скажем просто: могу – это очень плохо.\r\n\r\nТеперь тебе все время придется оглядываться и держать в уме еще одну угрозу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте призывателя душ Могуцзя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за крики доносятся с гор? Это зандаларская речь?$B$BКакого дьявола занадаларские тролли забыли в Пандарии?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Шиао в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Настоящий источник бед в Могуцзя…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Призыватель духов Могуцзя',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30621,'Они украли мою удачу!','Путешествие по Кунь-Лай научило меня двум вещам. Во-первых, никогда не подкрадываться к спящему яку. Во-вторых, удерживать удачу на своей стороне нужно, но непросто!$b$bГруммели верят в то, что талисман приносит удачу, если носить его с собой. А я считаю, что если один талисман иногда приносит удачу, то с целой кучей оберегов удача никуда от меня не денется!$b$bЯ прибыл в Пэй-Лэй, и эти мерзкие маленькие грелли украли все мои талисманы. Если бы ты $gсмог:смогла; разыскать их, моему счастью не было бы предела!','Верните Цзи-Лу Счастливчику счастливую лапку гну-синя, подкову яка, четырехветровый клевер и золотую монетку.','У тебя получилось разыскать мои талисманы? Удачи никогда не бывает слишком много!','Вернитесь к Цзи-Лу Счастливчику в Пэй-Лэй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они украли мою удачу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешествие по Кунь-Лай научило меня двум вещам. Во-первых, никогда не подкрадываться к спящему яку. Во-вторых, удерживать удачу на своей стороне нужно, но непросто!$b$bГруммели верят в то, что талисман приносит удачу, если носить его с собой. А я считаю, что если один талисман иногда приносит удачу, то с целой кучей оберегов удача никуда от меня не денется!$b$bЯ прибыл в Пэй-Лэй, и эти мерзкие маленькие грелли украли все мои талисманы. Если бы ты $gсмог:смогла; разыскать их, моему счастью не было бы предела!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Цзи-Лу Счастливчику счастливую лапку гну-синя, подкову яка, четырехветровый клевер и золотую монетку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя получилось разыскать мои талисманы? Удачи никогда не бывает слишком много!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзи-Лу Счастливчику в Пэй-Лэй.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30622,'Штурм начинается','Без стены у нас нет ни одного шанса. И если бы ты не $gпривел:привела; сюда столько воинов, мы бы долго не продержались.$b$bРазыщи капитана стражи Дубового Щита – он должен быть рядом с проломом в стене. По пути уничтожь столько богомолов, сколько сможешь.$b$bЕсли нам суждено победить, мы победим. Если потерпим поражение, то умрем с оружием в руках. Да здравствует Пандария!','Уничтожьте 15 ик\'тиков-воинов или ик\'тиков-заразителей.','Моя стена... На этой стене прошла вся моя жизнь...','Поговорите с капитаном Дубовым Щитом на полях Каменного Плуга, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штурм начинается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Без стены у нас нет ни одного шанса. И если бы ты не $gпривел:привела; сюда столько воинов, мы бы долго не продержались.$b$bРазыщи капитана стражи Дубового Щита – он должен быть рядом с проломом в стене. По пути уничтожь столько богомолов, сколько сможешь.$b$bЕсли нам суждено победить, мы победим. Если потерпим поражение, то умрем с оружием в руках. Да здравствует Пандария!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 ик\'тиков-воинов или ик\'тиков-заразителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя стена... На этой стене прошла вся моя жизнь...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном Дубовым Щитом на полях Каменного Плуга, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (30623,'Противоядие','Покажите маску Кен-Кена 5 ик\'тикам – командирам звена, а затем победите появившиеся воплощения страха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противоядие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите маску Кен-Кена 5 ик\'тикам – командирам звена, а затем победите появившиеся воплощения страха.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30624,'Какая польза от бочки с пивом?','Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.','Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и ночным эльфам-поселенцам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Какая польза от бочки с пивом?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и ночным эльфам-поселенцам.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30625,'Больше уже не ученики','Пять учеников – те самые, которые искали тайного мастера – одни отправились на передовую. Я бы послал к ним на помощь монахов Шадо-Пан, но у меня их не осталось.$b$bУ стены рыщут опасные твари. Если встретишь учеников, защити их от чудовищ.','Найдите учеников и помогите им победить ик\'тика-кровожада, наседку, ик\'тика – подрезателя сухожилий и сеятеля страха.','Долго они не продержатся. Эти ребята – герои, но я не хочу, чтобы они стали мертвыми героями.$B$BПора отступать.','Вернитесь к капитану Дубовому Щиту на поля Каменного плуга, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше уже не ученики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пять учеников – те самые, которые искали тайного мастера – одни отправились на передовую. Я бы послал к ним на помощь монахов Шадо-Пан, но у меня их не осталось.$b$bУ стены рыщут опасные твари. Если встретишь учеников, защити их от чудовищ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите учеников и помогите им победить ик\'тика-кровожада, наседку, ик\'тика – подрезателя сухожилий и сеятеля страха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Долго они не продержатся. Эти ребята – герои, но я не хочу, чтобы они стали мертвыми героями.$B$BПора отступать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Дубовому Щиту на поля Каменного плуга, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (30626,'Отступаем!','Ясно.$B$BНу, мы сделали все, что могли. Пора уходить, а заодно пересмотреть нашу стратегию – пока богомолы не захватили всю долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отступаем!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ясно.$B$BНу, мы сделали все, что могли. Пора уходить, а заодно пересмотреть нашу стратегию – пока богомолы не захватили всю долину.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30627,'Спаситель Каменного Плуга','Этот командир говорит быстро. У него есть оружие, которое поможет ему одержать победу. У него есть ВЫ.$b$b"Но ведь это невозможно", – скажете вы.$b$bИ ошибетесь. Это возможно. НИЧЕГО НЕВОЗМОЖНОГО НЕТ.$b$bИди же, $n, и спаси Каменный Плуг!','Поговорите с Мисс Фанни в Каменном Плуге. Затем с ее помощью победите гигантского богомола.','Вернитесь к командиру стражи Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спаситель Каменного Плуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот командир говорит быстро. У него есть оружие, которое поможет ему одержать победу. У него есть ВЫ.$b$b"Но ведь это невозможно", – скажете вы.$b$bИ ошибетесь. Это возможно. НИЧЕГО НЕВОЗМОЖНОГО НЕТ.$b$bИди же, $n, и спаси Каменный Плуг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мисс Фанни в Каменном Плуге. Затем с ее помощью победите гигантского богомола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Лун Маю в Каменный Плуг, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30628,'Благодарность Каменного Плуга','И еще, $n. Не бойся, я не собираюсь снова просить тебя об услуге. Сегодня ты $gубил:убила; достаточно богомолов.$b$bНедавно мы получили партию высококачественной брони с вершины Кунь-Лай. Я собирался оставить это для своих воинов... но, думаю, по справедливости все должно достаться тебе. Эту награду ты найдешь на втором этаже таверны.','Найдите тайник командира и заберите свою награду.','Заглянув внутрь, вы нашли...','Найдите тайник командира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарность Каменного Плуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И еще, $n. Не бойся, я не собираюсь снова просить тебя об услуге. Сегодня ты $gубил:убила; достаточно богомолов.$b$bНедавно мы получили партию высококачественной брони с вершины Кунь-Лай. Я собирался оставить это для своих воинов... но, думаю, по справедливости все должно достаться тебе. Эту награду ты найдешь на втором этаже таверны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тайник командира и заберите свою награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Заглянув внутрь, вы нашли...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите тайник командира.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30629,'FLAG - Игрок в финале','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.','Выслушайте Сяо и его товарищей.','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Игрок в финале',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет. Ищешь хозяина? Тогда обратись к пандарену, который стоит на верхней площадке.$b$bЯ просто гость... как и ты.$b$bПрошу прощения, но нам с друзьями нужно кое-что обсудить. Поговорим позже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Сяо и его товарищей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сяо у Усадьбы Пана, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30630,'В Дол','Я давно жду тебя, $gпутник:путница;.$B$BХотелось бы встретиться при иных обстоятельствах, но боюсь, что ситуация в Вечноцветущем доле крайне тяжелая.$B$BОбсудим это позже, а пока отправляйся к распорядительнице Ви Вин в святилище Семи Звезд.$B$BОна поможет тебе обустроиться.','Поговорите с распорядительницей Ви Вин в святилище Семи Звезд в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Дол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я давно жду тебя, $gпутник:путница;.$B$BХотелось бы встретиться при иных обстоятельствах, но боюсь, что ситуация в Вечноцветущем доле крайне тяжелая.$B$BОбсудим это позже, а пока отправляйся к распорядительнице Ви Вин в святилище Семи Звезд.$B$BОна поможет тебе обустроиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с распорядительницей Ви Вин в святилище Семи Звезд в Вечноцветущем доле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30631,'Святилище Семи Звезд','Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$B$BЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище Семи Звезд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$B$BЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30632,'Руины Го-Лай','Чжи Безмятежный считает, что могу попадают в дол через Руины Го-Лай, это на западе отсюда.$B$BАньцзи и Кунь отправились на разведку, но еще не вернулись.$B$BНужно выяснить, что случилось. Мне нужен $gумелый:умелая:c; |3-6($c).','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чжи Безмятежный считает, что могу попадают в дол через Руины Го-Лай, это на западе отсюда.$B$BАньцзи и Кунь отправились на разведку, но еще не вернулись.$B$BНужно выяснить, что случилось. Мне нужен $gумелый:умелая:c; |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай в Вечноцветущем доле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30633,'Разведчики','Мы уже знаем о том, что могу проникли в Дол, но как выясняется, ситуация еще хуже.$B$BРуины на северо-западе кишат разведчиками, которые собирают там сведения и расхищают сокровища.$B$BТвоя задача проста: избавься от всех разведчиков, которых встретишь. Армия могу не сможет двигаться, лишившись глаз.','Убейте 8 вестников Шао-Тень.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведчики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже знаем о том, что могу проникли в Дол, но как выясняется, ситуация еще хуже.$B$BРуины на северо-западе кишат разведчиками, которые собирают там сведения и расхищают сокровища.$B$BТвоя задача проста: избавься от всех разведчиков, которых встретишь. Армия могу не сможет двигаться, лишившись глаз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 вестников Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30634,'Закрыть проход','Мы с Лао Легкая Нога сходили на север, обшарили руины.$B$BПохоже, что могу лезут в долину из пещеры на склоне холма, и у них уже собрался внушительный отряд.$B$BВрагов слишком много, чтобы бросаться на них в открытую, так что иди ко входу в руины, там тебя ждет Лао Легкая Нога.$B$BОн проведет тебя по-тихому. Вот этот бочонок со взрывчаткой надо положить ко входу в пещеру.$B$BИ все, больше ничего не нужно.','Поговорите с Лао Легкая Нога у подножия Холма Руин и следуйте за ним по тропе. Дойдя до входа в пещеру на Холме Руин, установите там бочонок со взрывчаткой.','Поговорите с Кунем Осенним Светом на Руинах Го-Лай в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закрыть проход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Лао Легкая Нога сходили на север, обшарили руины.$B$BПохоже, что могу лезут в долину из пещеры на склоне холма, и у них уже собрался внушительный отряд.$B$BВрагов слишком много, чтобы бросаться на них в открытую, так что иди ко входу в руины, там тебя ждет Лао Легкая Нога.$B$BОн проведет тебя по-тихому. Вот этот бочонок со взрывчаткой надо положить ко входу в пещеру.$B$BИ все, больше ничего не нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лао Легкая Нога у подножия Холма Руин и следуйте за ним по тропе. Дойдя до входа в пещеру на Холме Руин, установите там бочонок со взрывчаткой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кунем Осенним Светом на Руинах Го-Лай в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30635,'Охотник на цийлиней','С разведчиками теперь все ясно. Но совсем рядом, в Залах Го-Лай, все еще держится большой отряд могу.$B$BК сожалению, пробраться туда сложно, вход в руины сторожат свирепые сторожевые псы.$B$BРазберись с этими тварями. Будь начеку, их не так-то просто заметить.','Убить 9 каменных стражей.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник на цийлиней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С разведчиками теперь все ясно. Но совсем рядом, в Залах Го-Лай, все еще держится большой отряд могу.$B$BК сожалению, пробраться туда сложно, вход в руины сторожат свирепые сторожевые псы.$B$BРазберись с этими тварями. Будь начеку, их не так-то просто заметить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убить 9 каменных стражей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30636,'Камни силы','Много тысячелетий назад правители Вечноцветущего дола черпали энергию из могущественного ревелитового кристалла.$B$BС его помощью они поддерживали города, производства и боевые механизмы.$B$BЧжи Безмятежный попросил нас собрать эти кристаллы и принести их в город.$B$BВозможно, ты найдешь их в руинах.','Соберите 7 ревелитовых кристаллов.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много тысячелетий назад правители Вечноцветущего дола черпали энергию из могущественного ревелитового кристалла.$B$BС его помощью они поддерживали города, производства и боевые механизмы.$B$BЧжи Безмятежный попросил нас собрать эти кристаллы и принести их в город.$B$BВозможно, ты найдешь их в руинах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 ревелитовых кристаллов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30637,'Залы Го-Лай','Проходя рядом с огромными вратами, вы слышите изнутри какие-то звуки.$B$BАньцзи говорила, что поблизости видели могу-разведчиков. Возможно, они пробрались вглубь залов.$B$BВам не терпится проверить это.','Проверьте, есть ли могу в Залах Го-Лай.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Залы Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проходя рядом с огромными вратами, вы слышите изнутри какие-то звуки.$B$BАньцзи говорила, что поблизости видели могу-разведчиков. Возможно, они пробрались вглубь залов.$B$BВам не терпится проверить это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте, есть ли могу в Залах Го-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30638,'Оставить просвет','Это очень важно.$B$BМы с Кунем останемся наблюдать, а ты отправляйся в Золотую Пагоду.$B$BИ поторопись!','Поговорите с Левеном Рассветным Клинком в Золотой Пагоде Вечноцветущего дола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставить просвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это очень важно.$B$BМы с Кунем останемся наблюдать, а ты отправляйся в Золотую Пагоду.$B$BИ поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Левеном Рассветным Клинком в Золотой Пагоде Вечноцветущего дола.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30639,'Секреты Го-Лай','Стражник, несущий службу у руин Го-Лай, недавно сообщил мне, что в чертоги пробрался предводитель Шао-Тень, убив при этом двух моих бойцов. Враги там что-то замышляют. Их надо остановить.$b$bХэ Легкая Нога уже последовал туда за ними. Он будет ждать тебя у входа в западные залы.$b$bОтправляйся поскорее, $n. Мне не нравится думать, что могу на шаг впереди нас.','Найдите Хэ Легкая Нога в Залах Го-Лай и узнайте, что замышляют могу в западных чертогах.','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секреты Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стражник, несущий службу у руин Го-Лай, недавно сообщил мне, что в чертоги пробрался предводитель Шао-Тень, убив при этом двух моих бойцов. Враги там что-то замышляют. Их надо остановить.$b$bХэ Легкая Нога уже последовал туда за ними. Он будет ждать тебя у входа в западные залы.$b$bОтправляйся поскорее, $n. Мне не нравится думать, что могу на шаг впереди нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Хэ Легкая Нога в Залах Го-Лай и узнайте, что замышляют могу в западных чертогах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30640,'Боевое копье Властелина Грома','У меня тревожные новости, $n.$B$BПохоже, могу задумали похитить из Дола три артефакта Силы.$B$BНам надлежит немедленно достать все три и надежно перепрятать их.$B$BВ первую очередь займемся боевым копьем Властелина Грома.$B$BПосле смерти Императора Лэй Шэня его поместили в древнее святилище к северо-западу отсюда.$B$BПринеси копье мне.','Найдите боевое копье Властелина Грома.','Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевое копье Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня тревожные новости, $n.$B$BПохоже, могу задумали похитить из Дола три артефакта Силы.$B$BНам надлежит немедленно достать все три и надежно перепрятать их.$B$BВ первую очередь займемся боевым копьем Властелина Грома.$B$BПосле смерти Императора Лэй Шэня его поместили в древнее святилище к северо-западу отсюда.$B$BПринеси копье мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите боевое копье Властелина Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30641,'Боевой шлем Властелина Грома','Второй артефакт Силы – это боевой шлем Властелина Грома.$B$BИмператор Лэй Шэнь надевал его в битву, и враги обращались в бегство при одном его виде.$B$BКогда Император скончался, шлем был помещен в Залы Го-Лай, что к западу отсюда, и окружен тысячами терракотовых воинов.$B$BТеперь они должны охранять своего вождя и умереть за него.','Найдите боевой шлем Властелина Грома.','Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевой шлем Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Второй артефакт Силы – это боевой шлем Властелина Грома.$B$BИмператор Лэй Шэнь надевал его в битву, и враги обращались в бегство при одном его виде.$B$BКогда Император скончался, шлем был помещен в Залы Го-Лай, что к западу отсюда, и окружен тысячами терракотовых воинов.$B$BТеперь они должны охранять своего вождя и умереть за него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите боевой шлем Властелина Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чжи Безмятежному в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30642,'Боевой топор Властелина Грома','Последний артефакт – это топор Властелина Грома.$B$BЛэй Шэнь сражался, держа в одной руке копье, а в другой – топор.$B$BГоворят, что он мог бросить этот топор с ужасающей точностью, а, настигая жертву, оружие гремело подобно грому.$B$BПосле смерти Императора топор был помещен в церемониальный зал в юго-западной части.$B$BИзлишне говорить, что и топор не должен попасть в руки могу.','Найдите боевой топор Властелина Грома.','Вернитесь к Чжи Безмятежному в Тихий приют в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевой топор Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний артефакт – это топор Властелина Грома.$B$BЛэй Шэнь сражался, держа в одной руке копье, а в другой – топор.$B$BГоворят, что он мог бросить этот топор с ужасающей точностью, а, настигая жертву, оружие гремело подобно грому.$B$BПосле смерти Императора топор был помещен в церемониальный зал в юго-западной части.$B$BИзлишне говорить, что и топор не должен попасть в руки могу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите боевой топор Властелина Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чжи Безмятежному в Тихий приют в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30643,'Сообщение могу','Битва с могу становится все более ожесточенной. Обе стороны сражаются, не щадя никого.$B$BМы не можем держаться вечно. Нужно нанести могу решающий удар, от которого они не смогут оправиться.$B$BОтправляйся в Тихий приют, посоветуйся с Чжи Безмятежным. Может, он сможет что-нибудь придумать.','Поговорите с Чжи Безмятежным в Тихом приюте Вечноцветущего дола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сообщение могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва с могу становится все более ожесточенной. Обе стороны сражаются, не щадя никого.$B$BМы не можем держаться вечно. Нужно нанести могу решающий удар, от которого они не смогут оправиться.$B$BОтправляйся в Тихий приют, посоветуйся с Чжи Безмятежным. Может, он сможет что-нибудь придумать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чжи Безмятежным в Тихом приюте Вечноцветущего дола.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30644,'Что произошло','Вам следует немедленно вернуться в Золотую Пагоду и сообщить о случившемся.','Поговорите с Сунь Доброе Сердце в Золотой Пагоде Вечноцветущего дола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что произошло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам следует немедленно вернуться в Золотую Пагоду и сообщить о случившемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сунь Доброе Сердце в Золотой Пагоде Вечноцветущего дола.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30645,'Сила трех','Убейте 100 могу-захватчиков в Летних полях Вечноцветущего дола.','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила трех',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 100 могу-захватчиков в Летних полях Вечноцветущего дола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30646,'Решающий момент','Никогда не думал, что до этого дойдет!$B$BЛевен решил сразиться с полководцем Чжао-Цзинем Кровопускателем на самом верху лестницы, но наши войска просто не могут подойти!$B$BТеперь никто, кроме нас, не сможет помешать врагу добраться до тайной... и смертельно опасной... силы дола.$B$B$n, ты $gдолжен:должна; остановить его, слышишь?!','Убейте полководца Чжао-Цзиня Кровопускателя.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.','Повелитель могу Шао-Тень.','Чжао-Цзинь Кровопускатель') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решающий момент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никогда не думал, что до этого дойдет!$B$BЛевен решил сразиться с полководцем Чжао-Цзинем Кровопускателем на самом верху лестницы, но наши войска просто не могут подойти!$B$BТеперь никто, кроме нас, не сможет помешать врагу добраться до тайной... и смертельно опасной... силы дола.$B$B$n, ты $gдолжен:должна; остановить его, слышишь?!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Чжао-Цзиня Кровопускателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Повелитель могу Шао-Тень.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чжао-Цзинь Кровопускатель',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30647,'Tracking Quest: Opened the Golden Valley') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Quest: Opened the Golden Valley',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30648,'Только вперед!','Твое путешествие по этой земле было полным событий, $gстранник:странница;, да и моему, похоже, еще суждено продолжаться какое-то время.$b$bЦепь событий началась с вашего прибытия сюда, и хотя некоторые из них весьма опечалили, я чувствую, что за твоим появлением стоит нечто большее.$B$BСейчас было бы мудрым оставить это место и исследовать другие районы Пандарии.$B$BОбратись ко мне, когда будешь готов к отъезду.','Отправляйтесь в Долину Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только вперед!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое путешествие по этой земле было полным событий, $gстранник:странница;, да и моему, похоже, еще суждено продолжаться какое-то время.$b$bЦепь событий началась с вашего прибытия сюда, и хотя некоторые из них весьма опечалили, я чувствую, что за твоим появлением стоит нечто большее.$B$BСейчас было бы мудрым оставить это место и исследовать другие районы Пандарии.$B$BОбратись ко мне, когда будешь готов к отъезду.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь в Долину Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30649,'Святилище Двух Лун','Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$b$bЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.','Поговорите с Джалуу Щедрым, Мокито Сильным, старейшиной Ляо и мадам Ви Ло в Вечноцветущем доле.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище Двух Лун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни на это существо, $gстранник:странница;. Почти сразу же после нашего прибытия могу-убийца напал без предупреждения.$b$bЕго целью был глава Золотого Лотоса. К счастью, мы оказались здесь и смогли защитить его.$B$BПосле покушения на Чжи я опасаюсь за жизнь тех, кто пришел в дол.$B$BСмотрители размещают людей в городе к юго-востоку отсюда. Идит туда и поговори с предводителями. Убедись, что они в безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джалуу Щедрым, Мокито Сильным, старейшиной Ляо и мадам Ви Ло в Вечноцветущем доле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30650,'Пандарены-пленники','Послушай, я знаю, что Альянсу нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\r\n\r\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Альянсу.\r\n\r\nЧто скажешь, $n?','Освободите 8 пандаренов-пленников.','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пандарены-пленники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я знаю, что Альянсу нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\r\n\r\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Альянсу.\r\n\r\nЧто скажешь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 пандаренов-пленников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30651,'Взрыв смеха','Давай-ка повеселимся, $gпарниша:девчонка;!$B$BЯунголы Ордо, что на северо-западе, избавили нас от необходимости изготавливать бомбы. Они у них уже есть.$B$BДавай-ка мы используем эти взрывоопасные бочонки себе на благо – взорвем их буровые установки, как думаешь?','Взорвите западную, южную и восточную буровые установки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.','Вернитесь к Салли "Рассольному" Маклири в Приют Западного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрыв смеха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай-ка повеселимся, $gпарниша:девчонка;!$B$BЯунголы Ордо, что на северо-западе, избавили нас от необходимости изготавливать бомбы. Они у них уже есть.$B$BДавай-ка мы используем эти взрывоопасные бочонки себе на благо – взорвем их буровые установки, как думаешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите западную, южную и восточную буровые установки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30652,'Поддержание магии','Яунголы, обитающие в лагере Ордо, представляют страшную угрозу. Я хочу, чтобы ты $gотправился:отправилась; на северо-запад и $gубил:убила; их вождя.$B$BНо есть одна проблема. Четверо приближенных к нему чародеев, известных как Жильвиси, защищают его пещеру огненным барьером, так что мы не можем попасть туда.$B$BРасправься с ними, и защита пропадет. Они поддерживают магическую связь в шатрах, там ты их и найдешь.','Убейте ордо – призывателя пепла, ордо – пироманта, ордо – шептателя огня и ордо – заклинателя пламени.','Вернитесь к адмиралу Тейлору в Приют Западного ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержание магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы, обитающие в лагере Ордо, представляют страшную угрозу. Я хочу, чтобы ты $gотправился:отправилась; на северо-запад и $gубил:убила; их вождя.$B$BНо есть одна проблема. Четверо приближенных к нему чародеев, известных как Жильвиси, защищают его пещеру огненным барьером, так что мы не можем попасть туда.$B$BРасправься с ними, и защита пропадет. Они поддерживают магическую связь в шатрах, там ты их и найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ордо – призывателя пепла, ордо – пироманта, ордо – шептателя огня и ордо – заклинателя пламени.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Приют Западного ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30653,'Какая польза от бочки с пивом?','Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.','Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и тауренам-поселенцам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Какая польза от бочки с пивом?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вот что думаю.$b$bУ нас есть пиво, которое сварил Чэнь, и все эти воины, которых ты $gсобрал:собрала;. Мы должны их объединить.$b$bТам, на полях, пандарены рискуют жизнью во имя родной страны. Мы с тобой можем хотя бы отнести им бочонок пива.$b$bМожет, они поднимут тост за победу. Может, выпьют в последний раз перед тем, как их прикончит богомол. В любом случае я хочу, чтобы перед боем они выпили хорошего пива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите пиво стражам Чжу, жрецам Журавлиного Крыла, монахам Шадо-Пан и тауренам-поселенцам.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30654,'Залы Го-Лай','Могу что-то затеяли, это точно.$B$BОни отправили разведчиков в Залы Го-Лай.$B$BСмотрители говорят, что там хранятся старинные реликвии древних императоров. Они не только ценны, но и крайне могущественны.$B$BНельзя допустить, чтобы они достались могу! Отправляйся на северо-запад, вниз по спуску! Останови их!','Проверьте, есть ли могу в Залах Го-Лай.','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Залы Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу что-то затеяли, это точно.$B$BОни отправили разведчиков в Залы Го-Лай.$B$BСмотрители говорят, что там хранятся старинные реликвии древних императоров. Они не только ценны, но и крайне могущественны.$B$BНельзя допустить, чтобы они достались могу! Отправляйся на северо-запад, вниз по спуску! Останови их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте, есть ли могу в Залах Го-Лай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет на руины Го-Лай, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30655,'Пандарены-пленники','Послушай, я знаю, что Орде нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\r\n\r\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Орде.\r\n\r\nЧто скажешь, $n?','Освободите 8 пандаренов-пленников.','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пандарены-пленники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я знаю, что Орде нужны рекруты, и нас слишком мало, чтобы установить численный перевес в городе.\r\n\r\nНо мне стало известно, что яунголы в Огненном лагерь Ордо захватили множество пленников. Не сомневаюсь, если ты освободишь их, они с радостью присоединятся к Орде.\r\n\r\nЧто скажешь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 пандаренов-пленников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30656,'Взрыв смеха','Взрывать я люблю. У меня это в крови!$B$BУ яунголов в огненном лагере Ордо на западе отсюда бочонки со взрывчаткой просто повсюду лежат.$B$BОчень правильно будет взорвать их насосы для горючей смеси и заодно развлечься.','Взорвите восточную, южную и западную буровые вышки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.','Вернитесь к Риветту Сталехвату в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрыв смеха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взрывать я люблю. У меня это в крови!$B$BУ яунголов в огненном лагере Ордо на западе отсюда бочонки со взрывчаткой просто повсюду лежат.$B$BОчень правильно будет взорвать их насосы для горючей смеси и заодно развлечься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взорвите восточную, южную и западную буровые вышки. Воспользуйтесь бочонками со взрывчаткой, найденными в огненном лагере Ордо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риветту Сталехвату в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30657,'Поддержание магии','Сейчас наибольшую опасность для нас представляют яунголы с Огненного лагеря Ордо. Тебе предстоит отправиться на запад и уничтожить их предводителя.$B$BЭтот трус затаился в пещере, защищенной огненным щитом. Щит постоянно поддерживают четыре волшебника Жильвиси.$B$BУстрани их, и щит спадет. Они сидят в своих шатрах и поддерживают заклинание.','Убейте ордо – призывателя пепла, ордо – пироманта, ордо – говорящего с огнем и ордо – заклинателя пламени.','<Воины Ордо мертвы. Защита пропадает.>$B$B<Пора убить вожака Ордо!>','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержание магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас наибольшую опасность для нас представляют яунголы с Огненного лагеря Ордо. Тебе предстоит отправиться на запад и уничтожить их предводителя.$B$BЭтот трус затаился в пещере, защищенной огненным щитом. Щит постоянно поддерживают четыре волшебника Жильвиси.$B$BУстрани их, и щит спадет. Они сидят в своих шатрах и поддерживают заклинание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ордо – призывателя пепла, ордо – пироманта, ордо – говорящего с огнем и ордо – заклинателя пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Воины Ордо мертвы. Защита пропадает.>$B$B<Пора убить вожака Ордо!>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30658,'Злючки-колючки','Ты $gслышал:слышала; что-нибудь о колючих иглобрюхах, $n? Конечно же, нет, ты ж впервые в этих местах!$b$bИх можно встретить в Сарджунских Глубинах, прямо на запад отсюда. Возьми рыболовную пику и постарайся добыть мне несколько ядовитых колючих хребтов этих рыб.','Убейте рыболовной пикой 5 колючих иглобрюхов в Сарджунских Глубинах и вернитесь с их хребтами.','Отнесите хребет колючего иглобрюха рыбаку Йотимо в Деревню рыболовов.','Осторожнее, эти хребты оставляют чудовищные шрамы!','Колючий иглобрюх') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злючки-колючки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gслышал:слышала; что-нибудь о колючих иглобрюхах, $n? Конечно же, нет, ты ж впервые в этих местах!$b$bИх можно встретить в Сарджунских Глубинах, прямо на запад отсюда. Возьми рыболовную пику и постарайся добыть мне несколько ядовитых колючих хребтов этих рыб.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте рыболовной пикой 5 колючих иглобрюхов в Сарджунских Глубинах и вернитесь с их хребтами.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите хребет колючего иглобрюха рыбаку Йотимо в Деревню рыболовов.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Осторожнее, эти хребты оставляют чудовищные шрамы!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Колючий иглобрюх',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30660,'Вестник войны Ордо','<Защита пропала. Время войти в пещеру и убить вестника войны Ордо.>','Убейте вестника войны Ордо.','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.','Защита больше не действует!','Вестник войны Ордо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник войны Ордо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Защита пропала. Время войти в пещеру и убить вестника войны Ордо.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вестника войны Ордо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Защита больше не действует!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вестник войны Ордо',`questgivertargetname_loc8`);
