INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30662,'Вестник войны Ордо','Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не появился снова.$b$bВремя войти в пещеру и убить их вождя!','Убейте вестника войны Ордо.','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.','Защита больше не действует!','Вестник войны Ордо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник войны Ордо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не появился снова.$b$bВремя войти в пещеру и убить их вождя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вестника войны Ордо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Приют Западного Ветра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Защита больше не действует!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вестник войны Ордо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30663,'Вестник войны Ордо','Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не восстановили снова.$b$bВремя войти в пещеру и убить вестника войны Ордо!','Убейте вестника войны Ордо.','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.','Защита больше не действует!','Вестник войны Ордо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник войны Ордо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы сняли защиту в огненном лагере Ордо. Скорее идите туда, пока барьер не восстановили снова.$b$bВремя войти в пещеру и убить вестника войны Ордо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вестника войны Ордо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Защита больше не действует!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вестник войны Ордо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30665,'Я послал за подкреплением из монастыря, но ответа пока нет. Мы уже потеряли город... Может, несколько жителей осталось, но мы здесь в безвыходном положении.\r\n\r\nУ нас нет времени на болтовню. Если ты можешь сражаться – помоги моим людям защитить Приют. Если нет – уноси ноги отсюда, иначе долго здесь не протянешь.','Убейте 15 зараженных ша яунголов.','Ты выиграл нам время для передышки. Мы не должны терять надежду, вместо этого нужно действовать.','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я послал за подкреплением из монастыря, но ответа пока нет. Мы уже потеряли город... Может, несколько жителей осталось, но мы здесь в безвыходном положении.\r\n\r\nУ нас нет времени на болтовню. Если ты можешь сражаться – помоги моим людям защитить Приют. Если нет – уноси ноги отсюда, иначе долго здесь не протянешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 зараженных ша яунголов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты выиграл нам время для передышки. Мы не должны терять надежду, вместо этого нужно действовать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30666,'Неожиданная агрессивность кроколисков','Обычно мой день состоит из ловли рыбы, поедания того, что я поймал, и сна. Обрати внимание – пункта "драка с кроколисками" в этом распорядке дня нет.$b$bТы, похоже, $gумелый:умелая:c; |3-6($c). Можешь разделаться с этими кроколисками, чтобы я вернулся к нормальной жизни? Кроколиски обычно обитают в Ки Крак, это на северо-западе.','Убейте 8 кроколисков-смертосмрадов в Ки Крак.','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неожиданная агрессивность кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно мой день состоит из ловли рыбы, поедания того, что я поймал, и сна. Обрати внимание – пункта "драка с кроколисками" в этом распорядке дня нет.$b$bТы, похоже, $gумелый:умелая:c; |3-6($c). Можешь разделаться с этими кроколисками, чтобы я вернулся к нормальной жизни? Кроколиски обычно обитают в Ки Крак, это на северо-западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 кроколисков-смертосмрадов в Ки Крак.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30667,'Распушили перышки','Когда кроколиски напали, они спугнули из гнезд стайку попугаев, и те улетели на остров к северо-западу отсюда.$b$bИз их перьев я бы сделал специальную наживку, которая весьма пригодится, когда и если закончится война с этими рептилиями.$b$bНе желаешь пособирать перья?','Соберите 6 изумрудных хвостовых перьев, 6 алых хвостовых перьев и 6 тусклых хвостовых перьев.','<Бусинка пота блеснула в меху на лбу Тони.>','Вернитесь к Тони Тунцу в Маристу, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распушили перышки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда кроколиски напали, они спугнули из гнезд стайку попугаев, и те улетели на остров к северо-западу отсюда.$b$bИз их перьев я бы сделал специальную наживку, которая весьма пригодится, когда и если закончится война с этими рептилиями.$b$bНе желаешь пособирать перья?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 изумрудных хвостовых перьев, 6 алых хвостовых перьев и 6 тусклых хвостовых перьев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Бусинка пота блеснула в меху на лбу Тони.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тони Тунцу в Маристу, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30668,'На маленьком плоту','<Джей смотрит в направлении Ки Крак.>$b$bХм. Не вижу, чтобы они... успокоились. Нужно попробовать что-то другое.$b$bТебе понадобится плот. Собери доски и водоросли и принеси их мне. А уж я что-нибудь смастерю.','Соберите 4 куска доски и несколько крепких водорослей.','<Джей на удивление искусно связывает доски в крепкий с виду плот и бросает его в воду.>','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На маленьком плоту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Джей смотрит в направлении Ки Крак.>$b$bХм. Не вижу, чтобы они... успокоились. Нужно попробовать что-то другое.$b$bТебе понадобится плот. Собери доски и водоросли и принеси их мне. А уж я что-нибудь смастерю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 куска доски и несколько крепких водорослей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Джей на удивление искусно связывает доски в крепкий с виду плот и бросает его в воду.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30669,'Хранитель истории на озере','Теперь твой плот на воде. Плыви на нем в середину озера. Там ты повстречаешь женщину. Ее зовут Ана У.$b$bКаждый раз, когда у меня возникает вопрос, на который я не могу ответить сам, я обращаюсь к ней. Она растолкует нам, почему кроколиски так разбушевались.','Залезайте на плот и плывите к ведунье Ана У, что обосновалась в центре лагуны Найели.','Вернитесь к ведунье Ана У, что обосновалась в центре лагуны Найели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель истории на озере',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь твой плот на воде. Плыви на нем в середину озера. Там ты повстречаешь женщину. Ее зовут Ана У.$b$bКаждый раз, когда у меня возникает вопрос, на который я не могу ответить сам, я обращаюсь к ней. Она растолкует нам, почему кроколиски так разбушевались.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Залезайте на плот и плывите к ведунье Ана У, что обосновалась в центре лагуны Найели.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Ана У, что обосновалась в центре лагуны Найели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30670,'Прозрение','Хорошо. Теперь я расскажу тебе о том, как победить необузданную ярость.$B$BЯ создам из этих сущностей ловушку для хана Кобая – предводителя яунголов. Несмотря на то, что в ловушку попадется именно он, твоей целью будет нечто другое...','Ты собрал сущности?','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прозрение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Теперь я расскажу тебе о том, как победить необузданную ярость.$B$BЯ создам из этих сущностей ловушку для хана Кобая – предводителя яунголов. Несмотря на то, что в ловушку попадется именно он, твоей целью будет нечто другое...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал сущности?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30671,'Цена мудрости','<Ана слушает вашу историю и кивает.>$b$bКроколиски нападают? Я знаю историю об этом. И я поделюсь ей с тобой, но сперва... хочу утолить голод.$b$bАкулье мясо было бы весьма кстати. В окрестных водах ты найдешь предостаточно акул.','Соберите 5 порций филе акулы.','Вернитесь к ведунье Ана У в лагуну Найели, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цена мудрости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ана слушает вашу историю и кивает.>$b$bКроколиски нападают? Я знаю историю об этом. И я поделюсь ей с тобой, но сперва... хочу утолить голод.$b$bАкулье мясо было бы весьма кстати. В окрестных водах ты найдешь предостаточно акул.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 порций филе акулы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Ана У в лагуну Найели, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30672,'Равновесие','Убейте 10 унга-рыбников.','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Равновесие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 унга-рыбников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джею Дождевой Туче в Маристу, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30673,'В западне','Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В западне',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30674,'Равновесие без насилия','Кажется, еще не вся рыба, выловленная унга-хозенами, умерла. Может, ты еще успеешь бросить ее обратно в воду.','Бросьте 6 вертлявых карпов в лагуну Найели.','Благодарная рыба радостно плывет, чтобы укрыться в середине лагуны.$b$bЕсли повезет, ее съедят кроколиски.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Равновесие без насилия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, еще не вся рыба, выловленная унга-хозенами, умерла. Может, ты еще успеешь бросить ее обратно в воду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте 6 вертлявых карпов в лагуну Найели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарная рыба радостно плывет, чтобы укрыться в середине лагуны.$b$bЕсли повезет, ее съедят кроколиски.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (30675,'Зарытое сокровище хозенов','Карта, которую вы держите в руках, потрескалась, запачкалась и нарисована кое-как, но на берегу там явно нарисован большой крестик.$b$bНеужели где-то на этом острове зарыто сокровище?','Найдите зарытое сокровище хозенов.','Поддавшись вашим усилиям, ящик со скрипом открывается. Очевидно, его-то и прятали хозены...','Это наверняка оно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зарытое сокровище хозенов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Карта, которую вы держите в руках, потрескалась, запачкалась и нарисована кое-как, но на берегу там явно нарисован большой крестик.$b$bНеужели где-то на этом острове зарыто сокровище?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите зарытое сокровище хозенов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поддавшись вашим усилиям, ящик со скрипом открывается. Очевидно, его-то и прятали хозены...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наверняка оно!',`requestitemstext_loc8`);
