INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30678,'Проще пареной... бомбы','Не так-то просто, оказывается, поймать этих скатов! Ты, вроде, $gпарень ловкий:девушка сообразительная; – так не поможешь ли мне?$b$bЯ изготовил бомбы, но плыть на плоту не могу – нога болит. Скаты водятся на отмели к западу отсюда. Возьми бомбы, плыви туда на моем плоту и добудь мне их острые шипы!$b$bА, да – осторожно, там акулы!','При помощи гоблинской бомбы для рыбалки убейте 3 скатов-хвостоколов, заберите их острые шипы и принесите Свистеру. Скаты водятся на мелководье к западу от Деревни рыболовов.','Я вижу, ты неплохо управляешься с бомбами!','Удалось найти скатов-хвостоколов на мелководье?','Отнесите шипы Свистеру в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проще пареной... бомбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так-то просто, оказывается, поймать этих скатов! Ты, вроде, $gпарень ловкий:девушка сообразительная; – так не поможешь ли мне?$b$bЯ изготовил бомбы, но плыть на плоту не могу – нога болит. Скаты водятся на отмели к западу отсюда. Возьми бомбы, плыви туда на моем плоту и добудь мне их острые шипы!$b$bА, да – осторожно, там акулы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи гоблинской бомбы для рыбалки убейте 3 скатов-хвостоколов, заберите их острые шипы и принесите Свистеру. Скаты водятся на мелководье к западу от Деревни рыболовов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты неплохо управляешься с бомбами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти скатов-хвостоколов на мелководье?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите шипы Свистеру в Деревню рыболовов.',`completedtext_loc8`);
