INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30682,'В западне','Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.','Мы не знали, что там остались выжившие.$B$BСпасибо, что привел их в безопасное место, Астральный.','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В западне',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Цзиня Теплого Бочонка, Я Огненную Ветвь, старуху Фун и Ся Чжун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы не знали, что там остались выжившие.$B$BСпасибо, что привел их в безопасное место, Астральный.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30683,'Несчастье путника','Ты что, $gкидался:кидалась; в них нашими припасами?! А почему нельзя было воспользоваться оружием? Или всякими заклинаниями и приемчиками? Ну почему именно припасы?!$b$bТеперь мы не сможем протянуть до конца, особенно с этим племянником Кривым Ногтем. Он же жрет, как йети!$b$bТак, раз ты $gвыкинул:выкинула; все наши припасы, то тебе придется раздобыть новые. Чуть дальше по пути произошло крушение. Возможно, ты сможешь что-нибудь найти в тех обломках.','Поищите припасы в брошенных обломках.','Вернитесь к Счастливчику Синей Струне в горный лагерь Пика Неутомимых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несчастье путника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты что, $gкидался:кидалась; в них нашими припасами?! А почему нельзя было воспользоваться оружием? Или всякими заклинаниями и приемчиками? Ну почему именно припасы?!$b$bТеперь мы не сможем протянуть до конца, особенно с этим племянником Кривым Ногтем. Он же жрет, как йети!$b$bТак, раз ты $gвыкинул:выкинула; все наши припасы, то тебе придется раздобыть новые. Чуть дальше по пути произошло крушение. Возможно, ты сможешь что-нибудь найти в тех обломках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите припасы в брошенных обломках.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Счастливчику Синей Струне в горный лагерь Пика Неутомимых.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30684,'Причуда Искателя','Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной."$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.','Пройдите путь под названием "Причуда Искателя", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.','Поговорите с хранителем истории Чо в лагере Искателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Причуда Искателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной."$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите путь под названием "Причуда Искателя", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в лагере Искателя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30690,'Сорвать маску с яунгола','Заманите хана Кобая в ловушку ослепляющей ярости, сорвите с него маску Злобной ярости и затем победите Злобную ярость.','Я должен чувствовать стыд из-за того, что с деревней покончено, и гордость за твои успехи.$B$BЯ должен ощущать еще множество эмоций, но я не могу позволить себе этого. Нужно полностью держать свои эмоции под контролем, пока наша борьба с ша не будет завершена.','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сорвать маску с яунгола',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заманите хана Кобая в ловушку ослепляющей ярости, сорвите с него маску Злобной ярости и затем победите Злобную ярость.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я должен чувствовать стыд из-за того, что с деревней покончено, и гордость за твои успехи.$B$BЯ должен ощущать еще множество эмоций, но я не могу позволить себе этого. Нужно полностью держать свои эмоции под контролем, пока наша борьба с ша не будет завершена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шадо-мастеру Чуну в Оплот Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30691,'Страдания','Когда окажешься под водой, ты $gдолжен:должна; будешь убить Нахассу, патриарха смертосмрадов. Он страдает. Я слышу, как его предсмертные крики доносятся до поверхности лагуны.$b$bНайди пещеру Нахассы и избавь его от страданий. Не потому, что это решит проблему Маристы с кроколисками. Просто из милосердия.','Избавьте Нахассу от страданий.','Мучения и агония Нахассы наконец-то прекратились.','Вернитесь к ведунье Ана У в лагуну Найели, что в Красарангских джунглях.','Даже самое страшное чудовище заслуживает милосердия.','Нахасса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страдания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда окажешься под водой, ты $gдолжен:должна; будешь убить Нахассу, патриарха смертосмрадов. Он страдает. Я слышу, как его предсмертные крики доносятся до поверхности лагуны.$b$bНайди пещеру Нахассы и избавь его от страданий. Не потому, что это решит проблему Маристы с кроколисками. Просто из милосердия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьте Нахассу от страданий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мучения и агония Нахассы наконец-то прекратились.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Ана У в лагуну Найели, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Даже самое страшное чудовище заслуживает милосердия.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Нахасса',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30692,'Ха-ха! Герой груммелей! Добро пожаловать в лагерь Коту. Груммели прибыли, и теперь тебя ждет удача.','Поговорите с братом Масляком в лагере Коту на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Герой груммелей! Добро пожаловать в лагерь Коту. Груммели прибыли, и теперь тебя ждет удача.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с братом Масляком в лагере Коту на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30694,'Ступай легко','Ученики говорят мне, что в округе полно смертельных ловушек – наверняка их расставили сауроки. Ступишь в такую – и все лицо будет истыкано шипами.$b$bКак гласит пословица, "Путь изобилует опасностями – ступай осторожно, смотри испытующе".$b$b<Коро вручает вам длинную ветку.>$b$bВот твой "испытующий взгляд".$b$bЕе длины должно хватить, чтобы снять ловушки с безопасного расстояния.','Обезвредьте 10 шипастых ловушек Речного Клинка с безопасного расстояния, используя "Испытующий взгляд".','Каждая обезвреженная тобой ловушка – это спасенная жизнь пандарена, зверя или кого-нибудь еще. Такой бесчестной смерти не заслуживает никто.','Вернитесь к Коро Страннику Туманов в Укрытие Журавлиного Крыла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ступай легко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ученики говорят мне, что в округе полно смертельных ловушек – наверняка их расставили сауроки. Ступишь в такую – и все лицо будет истыкано шипами.$b$bКак гласит пословица, "Путь изобилует опасностями – ступай осторожно, смотри испытующе".$b$b<Коро вручает вам длинную ветку.>$b$bВот твой "испытующий взгляд".$b$bЕе длины должно хватить, чтобы снять ловушки с безопасного расстояния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обезвредьте 10 шипастых ловушек Речного Клинка с безопасного расстояния, используя "Испытующий взгляд".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каждая обезвреженная тобой ловушка – это спасенная жизнь пандарена, зверя или кого-нибудь еще. Такой бесчестной смерти не заслуживает никто.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коро Страннику Туманов в Укрытие Журавлиного Крыла.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30695,'Что ждет на Пути','Огромные Пасти Отчаяния в пагодах по обеим сторонам храма извергают из себя ша. Тем временем, твоя импровизированная тренировка следованию Пути продолжается.$b$b"Та, что зашивает порванный зонтик, промокнет меньше той, что бьет по дождю".$b$bИ хоть я не вполне согласен с этим утверждением – иногда удары по дождю приносят немалую пользу, – в нашем случае оно истинно.$b$bУничтожь эти Пасти Отчаяния и дай моему ордену шанс вернуть себе храм.','Метафоры Коро бывают довольно утомительны, но за ними всегда стоит истинная мудрость.','Поговорите с Андуином Ринном в Храме Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что ждет на Пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромные Пасти Отчаяния в пагодах по обеим сторонам храма извергают из себя ша. Тем временем, твоя импровизированная тренировка следованию Пути продолжается.$b$b"Та, что зашивает порванный зонтик, промокнет меньше той, что бьет по дождю".$b$bИ хоть я не вполне согласен с этим утверждением – иногда удары по дождю приносят немалую пользу, – в нашем случае оно истинно.$b$bУничтожь эти Пасти Отчаяния и дай моему ордену шанс вернуть себе храм.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Метафоры Коро бывают довольно утомительны, но за ними всегда стоит истинная мудрость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Храме Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30698,'Сбор металлолома','Ты! Тебя-то я и ищу!$b$bМне нужны запчасти к бомбам для рыбалки, но я повредил ногу и сам их собрать не смогу.$b$bВидишь, вон там, рядом, обломки корабля, потерпевшего крушение? Готов биться об заклад: там есть то, что мне нужно, остается выудить это из воды. Возьми мой рыбацкий плот, сплавай туда и поищи хорошенько! Мой приятель уже пытался помочь, так что если увидишь его плоты там, пользуйся на здоровье.','Возьмите рыбацкий плот гоблина и соберите 15 ржавых обломков кораблекрушения в плавающем хламе около корабля.','Отнесите обломки Свистеру в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор металлолома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты! Тебя-то я и ищу!$b$bМне нужны запчасти к бомбам для рыбалки, но я повредил ногу и сам их собрать не смогу.$b$bВидишь, вон там, рядом, обломки корабля, потерпевшего крушение? Готов биться об заклад: там есть то, что мне нужно, остается выудить это из воды. Возьми мой рыбацкий плот, сплавай туда и поищи хорошенько! Мой приятель уже пытался помочь, так что если увидишь его плоты там, пользуйся на здоровье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите рыбацкий плот гоблина и соберите 15 ржавых обломков кораблекрушения в плавающем хламе около корабля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите обломки Свистеру в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (30699,'Шадо-мастер Чун прислал тебя? Хм-м-м...$B$BДа, мы получили его просьбу выслать подкрепление.$B$BУвы, нам сложно будет ее выполнить. Наш бой только что закончился, и монастырь теперь наглухо заперт.$B$BУ нас тут подкрепления взять неоткуда, положение незавидное!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шадо-мастер Чун прислал тебя? Хм-м-м...$B$BДа, мы получили его просьбу выслать подкрепление.$B$BУвы, нам сложно будет ее выполнить. Наш бой только что закончился, и монастырь теперь наглухо заперт.$B$BУ нас тут подкрепления взять неоткуда, положение незавидное!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30700,'Клешнехват','Огромный ядовитый краб сеет хаос в наших колониях морских ушек. Я хочу, чтобы ты $gспустился:спустилась; в Поющую Котловину и убил его!','Убейте клешнехвата на дне Поющей Котловины и прихватите его клешню как доказательство.','Вот это клешня! Клешнехват оказался больше, чем я думал! Хорошая работа, Роуф!','Ты убил этого мерзкого ползуна?','Отнесите клешню удильщику Шэню в Поющую Котловину.','Клешнехват – гроза здешних моллюсков.','Клешнехват') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клешнехват',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромный ядовитый краб сеет хаос в наших колониях морских ушек. Я хочу, чтобы ты $gспустился:спустилась; в Поющую Котловину и убил его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте клешнехвата на дне Поющей Котловины и прихватите его клешню как доказательство.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это клешня! Клешнехват оказался больше, чем я думал! Хорошая работа, Роуф!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты убил этого мерзкого ползуна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите клешню удильщику Шэню в Поющую Котловину.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Клешнехват – гроза здешних моллюсков.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Клешнехват',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30701,'Суп из шустрого краба','Ничто не сравнится по вкусу с супом из шустрого краба. Это фирменное блюдо Красаранга!$b$bЯ как раз собирался его сварить, когда понял, что мне не хватает главных ингредиентов – глаз!$b$bУбей шустрых крабов – рыболовов и принеси мне их глаза для супа!','Убейте на побережье шустрых крабов – рыболовов и соберите 16 их глаз для вкусного супа.','Сколько глаз-бусинок ты собрал?','Отнесите глаза Фо Фуку в Поющую Котловину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суп из шустрого краба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто не сравнится по вкусу с супом из шустрого краба. Это фирменное блюдо Красаранга!$b$bЯ как раз собирался его сварить, когда понял, что мне не хватает главных ингредиентов – глаз!$b$bУбей шустрых крабов – рыболовов и принеси мне их глаза для супа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте на побережье шустрых крабов – рыболовов и соберите 16 их глаз для вкусного супа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько глаз-бусинок ты собрал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите глаза Фо Фуку в Поющую Котловину.',`completedtext_loc8`);
