INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30706,'Злобные каракули') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные каракули',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30710,'Провоцируя троллей','Нам удалось серьезно оттеснить троллей, но я сомневаюсь, что мы долго будем в безопасности, если не покончим с ними раз и навсегда.\r\n\r\nМой муж – трус, а может, и глупец; как бы то ни было, он не хочет с ними связываться. А я не боюсь.\r\n\r\nПлан таков: сначала надо убить разведчиков. Надеюсь это разозлит их вожака, и затем мы сможем победить его.','Убейте 10 зандарских разведчиков и 5 зандарских колдунов.','Вернитесь к Сяо Мыну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провоцируя троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось серьезно оттеснить троллей, но я сомневаюсь, что мы долго будем в безопасности, если не покончим с ними раз и навсегда.\r\n\r\nМой муж – трус, а может, и глупец; как бы то ни было, он не хочет с ними связываться. А я не боюсь.\r\n\r\nПлан таков: сначала надо убить разведчиков. Надеюсь это разозлит их вожака, и затем мы сможем победить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зандарских разведчиков и 5 зандарских колдунов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сяо Мыну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30714,'Убить вожаков','Теперь они боятся тебя.\r\n\r\nИх главари – мастер клинка и маг, они залегли глубже в руинах. Убей их.\r\nПричини им боль. Ради нас.','Убейте зандаларского мастера клинка и зандаларского мага.','Вернитесь к Сяо Цзы Хай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить вожаков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь они боятся тебя.\r\n\r\nИх главари – мастер клинка и маг, они залегли глубже в руинах. Убей их.\r\nПричини им боль. Ради нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте зандаларского мастера клинка и зандаларского мага.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сяо Цзы Хай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30715,'Несломленная оборона','Когда мы перегруппировались после их первой атаки, нас стало на троих меньше. Ты можешь сражаться, и мы должны организовать оборону, если эти проклятые яунголы снова пойдут в атаку.\r\n\r\nЕсли ты хочешь помочь, упокой души наших павших товарищей и забери их доспехи. Тела ты найдешь к западу отсюда, возле ворот.\r\n\r\nА еще отгони от их тел падальщиков.','Упокойте шадо-мастера Чжияо, Лю Тысячу Ударов и Шию Кипящую Кровь.','Отлично. Я прослежу, чтобы доспехи погибших попали в руки к их ученикам.','Вернитесь к Баню Медвежьему Сердцу в Лагерь Зимнего Цветения на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несломленная оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы перегруппировались после их первой атаки, нас стало на троих меньше. Ты можешь сражаться, и мы должны организовать оборону, если эти проклятые яунголы снова пойдут в атаку.\r\n\r\nЕсли ты хочешь помочь, упокой души наших павших товарищей и забери их доспехи. Тела ты найдешь к западу отсюда, возле ворот.\r\n\r\nА еще отгони от их тел падальщиков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Упокойте шадо-мастера Чжияо, Лю Тысячу Ударов и Шию Кипящую Кровь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Я прослежу, чтобы доспехи погибших попали в руки к их ученикам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в Лагерь Зимнего Цветения на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30716,'В погоне за надеждой','Чи-Цзи всегда с нами. Даже когда его нет в Колыбели, частички его души летят по лесу и берегам острова, следят за нами и испытывают нас.$b$bДокажи Чи-Цзи свою ловкость, $n. Найди и поймай духов Журавля.','Прикоснитесь к 3 духам Журавля.','Чи-Цзи улыбается тебе.','Вернитесь к Ко-На Игривой Лапе в Колыбель Чи-Цзи, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В погоне за надеждой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чи-Цзи всегда с нами. Даже когда его нет в Колыбели, частички его души летят по лесу и берегам острова, следят за нами и испытывают нас.$b$bДокажи Чи-Цзи свою ловкость, $n. Найди и поймай духов Журавля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикоснитесь к 3 духам Журавля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чи-Цзи улыбается тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ко-На Игривой Лапе в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30717,'Дары Великого Журавля','Журавли Красаранга – дар Чи-Цзи. Даже перья, которые они сбрасывают, – великое благо для нас.$b$bЭтими перьями мы украшаем одежду и оперяем стрелы. Но сначала... их нужно собрать.','Соберите 10 даров Великого Журавля.','Даже самые мелкие, самые тонкие их перья – знак того, что Чи-Цзи любит нас.','Вернитесь к Яню Игривой Лапе в Колыбель Чи-Цзи, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дары Великого Журавля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Журавли Красаранга – дар Чи-Цзи. Даже перья, которые они сбрасывают, – великое благо для нас.$b$bЭтими перьями мы украшаем одежду и оперяем стрелы. Но сначала... их нужно собрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 даров Великого Журавля.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже самые мелкие, самые тонкие их перья – знак того, что Чи-Цзи любит нас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яню Игривой Лапе в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30718,'Ученики Чи-Цзи','Наш орден гордится своим боевым мастерством. Мы оттачиваем его, сражаясь друг с другом здесь, в Колыбели Чи-Цзи.$b$bПокажи свою доблесть Красному Журавлю. Отправляйся на юг, в центр острова, и сразись в поединках со своими товарищами-учениками.','Сразитесь с 10 учениками Чи-Цзи.','С каждым поединком, выигранным или проигранным, ты становишься совершеннее. Ты становишься быстрее, крепче, умнее... лучше.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ученики Чи-Цзи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш орден гордится своим боевым мастерством. Мы оттачиваем его, сражаясь друг с другом здесь, в Колыбели Чи-Цзи.$b$bПокажи свою доблесть Красному Журавлю. Отправляйся на юг, в центр острова, и сразись в поединках со своими товарищами-учениками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с 10 учениками Чи-Цзи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С каждым поединком, выигранным или проигранным, ты становишься совершеннее. Ты становишься быстрее, крепче, умнее... лучше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`);
