INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30723,'Честь после смерти','Хм... Раз шадо-мастер Чун доверяет тебе, может, ты нам и пригодишься.\r\n\r\nЯунголы – наши враги.\r\n\r\nНужно доказать, что мы лучше их. Мы уважаем мертвых.\r\n\r\nКак всегда, падальщики уже начали свой кровавый пир. Уменьши их число, чтобы тела наших противников остались неоскверненными. Они собрались на поле битвы, это к западу отсюда.','Убейте 12 падальщиков Кунь-Лай.','Хорошо. После того, что сделали яунголы, им не поздоровится. И все же я не позволю, чтобы их тела были расклеваны птицами.','Вернитесь к Линю Беззвучному Удару в Лагерь Зимнего Цветения на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честь после смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... Раз шадо-мастер Чун доверяет тебе, может, ты нам и пригодишься.\r\n\r\nЯунголы – наши враги.\r\n\r\nНужно доказать, что мы лучше их. Мы уважаем мертвых.\r\n\r\nКак всегда, падальщики уже начали свой кровавый пир. Уменьши их число, чтобы тела наших противников остались неоскверненными. Они собрались на поле битвы, это к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 падальщиков Кунь-Лай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. После того, что сделали яунголы, им не поздоровится. И все же я не позволю, чтобы их тела были расклеваны птицами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линю Беззвучному Удару в Лагерь Зимнего Цветения на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (30724,'На стену!','Они снова атакуют!\r\n\r\n<Линь глядит в сторону Врат Быка.>\r\n\r\n Лучники... на стене!\r\n\r\nСможешь забраться туда? Моя жена Суна только что отправилась на разведку к стене с этим придурком, Лао-Чинем. Если бы он больше времени уделил организации обороны, вместо того чтобы заниматься сооружением этого нелепого хмельного лифта...\r\n\r\nНеважно. Заберись туда и найди мою жену. Она знает, что делать дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На стену!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они снова атакуют!\r\n\r\n<Линь глядит в сторону Врат Быка.>\r\n\r\n Лучники... на стене!\r\n\r\nСможешь забраться туда? Моя жена Суна только что отправилась на разведку к стене с этим придурком, Лао-Чинем. Если бы он больше времени уделил организации обороны, вместо того чтобы заниматься сооружением этого нелепого хмельного лифта...\r\n\r\nНеважно. Заберись туда и найди мою жену. Она знает, что делать дальше.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30725,'Эллия Вороная Грива','Мы постоянно устраиваем поединки один на один между учениками, которые, на наш взгляд, достойны друг друга. Мы нашли такого партнера и тебе, $n.$b$bЕе зовут Эллия Вороная Грива. Для нее, как и для тебя, это будет первая дуэль. Она ждет тебя в павильоне к югу отсюда.','Победите Эллию Вороную Гриву в павильоне Ангхал.','Отлично!$B$BКогда ты придешь в следующий раз, у тебя будет новый соперник. Продолжай выигрывать, и благосклонность Чи-Цзи к тебе возрастет.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Ваш первый противник.','Эллия Вороная Грива') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эллия Вороная Грива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы постоянно устраиваем поединки один на один между учениками, которые, на наш взгляд, достойны друг друга. Мы нашли такого партнера и тебе, $n.$b$bЕе зовут Эллия Вороная Грива. Для нее, как и для тебя, это будет первая дуэль. Она ждет тебя в павильоне к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эллию Вороную Гриву в павильоне Ангхал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично!$B$BКогда ты придешь в следующий раз, у тебя будет новый соперник. Продолжай выигрывать, и благосклонность Чи-Цзи к тебе возрастет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ваш первый противник.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эллия Вороная Грива',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30726,'Минь До-Тан','Твой следующий соперник тоже из новичков. Его зовут Минь До-Тан, и он победил в двух своих последних боях.$b$bОн будет ждать тебя у статуи журавля на юге.','Победите Минь До-Тана.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Ваш следующий противник.','Минь До-Тан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минь До-Тан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой следующий соперник тоже из новичков. Его зовут Минь До-Тан, и он победил в двух своих последних боях.$b$bОн будет ждать тебя у статуи журавля на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Минь До-Тана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ваш следующий противник.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Минь До-Тан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30727,'Эллия Вороная Грива: реванш','Эллия Вороная Грива хочет вновь сразиться с тобой. Похоже, она сочла тебя своим принципиальным соперником.$b$bЗдесь, в Колыбели Чи-Цзи, мы не одобряем такого рода конкуренцию, но и просьбу о реванше мы отклоняем редко. Ты найдешь Эллию на Пьедестале Надежды, это в восточной части острова.','Победите Эллию Вороную Гриву у подножия Пьедестала Надежды.','Два боя – два поражения. Сдается мне, Эллия еще не скоро попробует взять реванш.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Она жаждет реванша!','Эллия Вороная Грива') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эллия Вороная Грива: реванш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эллия Вороная Грива хочет вновь сразиться с тобой. Похоже, она сочла тебя своим принципиальным соперником.$b$bЗдесь, в Колыбели Чи-Цзи, мы не одобряем такого рода конкуренцию, но и просьбу о реванше мы отклоняем редко. Ты найдешь Эллию на Пьедестале Надежды, это в восточной части острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эллию Вороную Гриву у подножия Пьедестала Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Два боя – два поражения. Сдается мне, Эллия еще не скоро попробует взять реванш.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она жаждет реванша!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эллия Вороная Грива',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30728,'Толстяк Лун-Фат','Теперь ты встанешь в пару с... особым учеником. Его зовут Толстяк Лун-Фат.$b$b<Телоний тщательно выбирает слова.>$b$bТолстяк Лун-Фат... дерется иначе, чем принято. Он выходит на поединок не каждый день, но когда выходит, то сам выбирает себе противника. Сегодня по какой-то причине... он выбрал тебя.$b$bТы найдешь его на крыше павильона Ангхал.','Победите Толстяка Лун-Фата на крыше павильона Ангхал.','Ты победил – и это естественно. Толстяк Лун-Фат бьется не ради победы. Он бьется... по другим причинам.$B$BБоюсь, я и так уже слишком много об этом сказал. С этого момента – никаких больше вопросов о Толстяке Лун-Фате.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Его зовут Лун-Фат. "Лун" – потому что он круглый, будто луна.','Толстяк Лун-Фат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Толстяк Лун-Фат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты встанешь в пару с... особым учеником. Его зовут Толстяк Лун-Фат.$b$b<Телоний тщательно выбирает слова.>$b$bТолстяк Лун-Фат... дерется иначе, чем принято. Он выходит на поединок не каждый день, но когда выходит, то сам выбирает себе противника. Сегодня по какой-то причине... он выбрал тебя.$b$bТы найдешь его на крыше павильона Ангхал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Толстяка Лун-Фата на крыше павильона Ангхал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты победил – и это естественно. Толстяк Лун-Фат бьется не ради победы. Он бьется... по другим причинам.$B$BБоюсь, я и так уже слишком много об этом сказал. С этого момента – никаких больше вопросов о Толстяке Лун-Фате.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его зовут Лун-Фат. "Лун" – потому что он круглый, будто луна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Толстяк Лун-Фат',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30729,'Джулия Бейтс','Здесь, в Колыбели, мы приветствуем всех, кто понимает и разделяет идеи учения Красного Журавля. Одна из наших новых необычных учениц прибыла из королевств людей, что на северо-востоке. Она носит довольно непривычное для слуха имя Джулия Бейтс.$b$bОна и будет твоим следующим противником. Ты найдешь ее на западном берегу острова.','Победите Джулию Бейтс.','И вот выигран еще один поединок. Я с нетерпением жду твоего следующего боя, Ролотомаси.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Недавно прибыла в Пандарию.','Джулия Бейтс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джулия Бейтс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Колыбели, мы приветствуем всех, кто понимает и разделяет идеи учения Красного Журавля. Одна из наших новых необычных учениц прибыла из королевств людей, что на северо-востоке. Она носит довольно непривычное для слуха имя Джулия Бейтс.$b$bОна и будет твоим следующим противником. Ты найдешь ее на западном берегу острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Джулию Бейтс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И вот выигран еще один поединок. Я с нетерпением жду твоего следующего боя, Ролотомаси.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Недавно прибыла в Пандарию.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джулия Бейтс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30730,'Ловкий Изисша','Обычно цзинь-юй избегают нашего ордена, но раз в несколько лет кто-нибудь из них встает на Путь Журавля. Один из таких цзинь-юй – Ловкий Изисша.$b$bИзисша – твой следующий соперник. Он ждет тебя на юго-западном берегу острова.','Победите Ловкого Изисшу.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Изисша – на удивление сильный боец, который держится особняком.','Ловкий Изисша') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловкий Изисша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно цзинь-юй избегают нашего ордена, но раз в несколько лет кто-нибудь из них встает на Путь Журавля. Один из таких цзинь-юй – Ловкий Изисша.$b$bИзисша – твой следующий соперник. Он ждет тебя на юго-западном берегу острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ловкого Изисшу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Изисша – на удивление сильный боец, который держится особняком.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ловкий Изисша',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30731,'Ко-На Игривая Лапа','Большинство поединков в Колыбели проходит между двумя учениками. И лишь изредка, когда ученик демонстрирует выдающиеся способности, ему дают шанс сразиться со своим учителем.$b$bСегодня ты выйдешь на поединок с Ко-Ной. Она будет ждать тебя у Пьедестала Надежды.','Победите Ко-Ну Игривую Лапу.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Первый тренировочный бой с вашими учителями!','Ко-На Игривая Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ко-На Игривая Лапа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство поединков в Колыбели проходит между двумя учениками. И лишь изредка, когда ученик демонстрирует выдающиеся способности, ему дают шанс сразиться со своим учителем.$b$bСегодня ты выйдешь на поединок с Ко-Ной. Она будет ждать тебя у Пьедестала Надежды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ко-Ну Игривую Лапу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Первый тренировочный бой с вашими учителями!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ко-На Игривая Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30732,'Эллия Вороная Грива: месть','Твой "любимый враг" появился снова. Эллия Вороная Грива теперь увиливает от работы и все время уделяет тренировкам, чтобы одолеть тебя в бою.$b$b"Я уничтожу |3-3($n)" – так она говорит.$b$bЯ уважил ее право на реванш, но буду внимательно за ней наблюдать. Сдается мне, ее мотивы могли претерпеть опасные изменения.','Победите Эллию Вороную Гриву под Куполом Балрисса.','Я поговорю о поведении Эллии с самим Чи-Цзи. Она ступает по тонкому льду.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Эллия вернулась и намерена одержать верх над соперником.','Эллия Вороная Грива') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эллия Вороная Грива: месть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой "любимый враг" появился снова. Эллия Вороная Грива теперь увиливает от работы и все время уделяет тренировкам, чтобы одолеть тебя в бою.$b$b"Я уничтожу |3-3($n)" – так она говорит.$b$bЯ уважил ее право на реванш, но буду внимательно за ней наблюдать. Сдается мне, ее мотивы могли претерпеть опасные изменения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эллию Вороную Гриву под Куполом Балрисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я поговорю о поведении Эллии с самим Чи-Цзи. Она ступает по тонкому льду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эллия вернулась и намерена одержать верх над соперником.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эллия Вороная Грива',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30733,'Тукка-Тук','Ты становишься у нас знаменитостью, $n. С тобой хочет выйти на поединок один из наших опытных бойцов. Он считает, что ты не так $gсилен:сильна;, как кажешься.$b$bЕго зовут Тукка-Тук, и он хозен. Если ты когда-нибудь $gдрался:дралась; с хозенами, то знаешь, что они весьма сообразительны, несмотря на свой глупый вид. Удачи.','Победите Тукка-Тука.','Превосходно, как и обычно.$B$BПолагаю, мы скоро увидимся снова.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Не проиграл ни одного из последних своих десяти боев.','Тукка-Тук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тукка-Тук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты становишься у нас знаменитостью, $n. С тобой хочет выйти на поединок один из наших опытных бойцов. Он считает, что ты не так $gсилен:сильна;, как кажешься.$b$bЕго зовут Тукка-Тук, и он хозен. Если ты когда-нибудь $gдрался:дралась; с хозенами, то знаешь, что они весьма сообразительны, несмотря на свой глупый вид. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Тукка-Тука.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, как и обычно.$B$BПолагаю, мы скоро увидимся снова.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не проиграл ни одного из последних своих десяти боев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тукка-Тук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30734,'Хук Тачка','Победите Хука Тачку.','У нас остался лишь один ученик, что стоит рангом выше тебя.$B$BСдается мне, ты встретишься с ним по возвращении.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Иммигрант с северных ферм.','Хук Тачка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хук Тачка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Хука Тачку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас остался лишь один ученик, что стоит рангом выше тебя.$B$BСдается мне, ты встретишься с ним по возвращении.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Иммигрант с северных ферм.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хук Тачка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30735,'Миндел Говорящий с Солнцем','Наш лучший ученик – чужестранец, как и ты. Странно и в то же время захватывающе жить во времена, когда так много чужеземцев вступили на Путь Журавля.$b$bТвоего соперника зовут Миндел Говорящий с Солнцем, и он ждет тебя в павильоне Ангхал.','Победите Миндела Говорящего с Солнцем.','Теперь ты – наш лучший ученик. Больше ты не обязан участвовать в поединках с другими учениками. Поздравляю.$B$BКонечно, есть и другие способы проявить себя. У меня такое предчувствие, что мы с тобой еще встретимся...','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Миндел, как и вы, доселе не был побежден.','Миндел Говорящий с Солнцем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миндел Говорящий с Солнцем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш лучший ученик – чужестранец, как и ты. Странно и в то же время захватывающе жить во времена, когда так много чужеземцев вступили на Путь Журавля.$b$bТвоего соперника зовут Миндел Говорящий с Солнцем, и он ждет тебя в павильоне Ангхал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Миндела Говорящего с Солнцем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты – наш лучший ученик. Больше ты не обязан участвовать в поединках с другими учениками. Поздравляю.$B$BКонечно, есть и другие способы проявить себя. У меня такое предчувствие, что мы с тобой еще встретимся...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Миндел, как и вы, доселе не был побежден.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Миндел Говорящий с Солнцем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30736,'Янь Игривая Лапа','Ты уже $gпобеждал:побеждала; Ко-Ну Игривую Лапу, но еще не $gсражался:сражалась; с ее братом Янем.$b$bОн встретит тебя на Пьедестале Надежды и уже не отступит – ведь на кону стоит его репутация учителя.','Победите Яня Игривую Лапу на Пьедестале Надежды.','И после этой победы, похоже, у нас уже не осталось никого, с кем ты мог бы сразиться! Кроме меня, конечно.$B$BНо... я не участвую в поединках. Я к тому, что со мной тебе лучше не биться. Это... добром для тебя не кончится.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Ян живет на острове десятки лет. Бои – это его жизнь.','Янь Игривая Лапа') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Янь Игривая Лапа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gпобеждал:побеждала; Ко-Ну Игривую Лапу, но еще не $gсражался:сражалась; с ее братом Янем.$b$bОн встретит тебя на Пьедестале Надежды и уже не отступит – ведь на кону стоит его репутация учителя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Яня Игривую Лапу на Пьедестале Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И после этой победы, похоже, у нас уже не осталось никого, с кем ты мог бы сразиться! Кроме меня, конечно.$B$BНо... я не участвую в поединках. Я к тому, что со мной тебе лучше не биться. Это... добром для тебя не кончится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ян живет на острове десятки лет. Бои – это его жизнь.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Янь Игривая Лапа',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30737,'Толстяк Лун-Фат: реванш','Толстяк Лун-Фат хочет провести с тобой еще один бой. Мне это кажется странным. И настораживающим.$b$bОн будет ждать тебя на Куполе Балрисса.','Победите Толстяка Лун-Фата на Куполе Балрисса.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Загадочный воитель возвращается.','Толстяк Лун-Фат') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Толстяк Лун-Фат: реванш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Толстяк Лун-Фат хочет провести с тобой еще один бой. Мне это кажется странным. И настораживающим.$b$bОн будет ждать тебя на Куполе Балрисса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Толстяка Лун-Фата на Куполе Балрисса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Загадочный воитель возвращается.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Толстяк Лун-Фат',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30738,'Телоний','Во время нашего прошлого разговора я обещал рассказать тебе секрет Толстяка Лун-Фата. Я по-прежнему намерен его раскрыть... но сначала проверю, $gдостоин:достойна; ли ты этого.$b$bЯ встречу тебя на западном берегу, там мы сойдемся в поединке.','Победите Телония.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','О боевых навыках Телония ходят легенды.','Телоний') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телоний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время нашего прошлого разговора я обещал рассказать тебе секрет Толстяка Лун-Фата. Я по-прежнему намерен его раскрыть... но сначала проверю, $gдостоин:достойна; ли ты этого.$b$bЯ встречу тебя на западном берегу, там мы сойдемся в поединке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Телония.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','О боевых навыках Телония ходят легенды.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Телоний',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30739,'Эллия Вороная Грива: искупление','Вернулась Эллия Вороная Грива, твой принципиальный соперник. Она требует встречи с тобой на верху Пьедестала Надежды.$b$bТы $gдолжен:должна; понять, $n... с ней произошло нечто ужасное. Она изменилась. Ты $gсам:сама; все поймешь, когда придешь к Пьедесталу.$b$bУдачи, $n.','Победите Эллию Вороную Гриву на верху Пьедестала Надежды.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.','Ваш соперник возвращается.','Эллия Вороная Грива') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эллия Вороная Грива: искупление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернулась Эллия Вороная Грива, твой принципиальный соперник. Она требует встречи с тобой на верху Пьедестала Надежды.$b$bТы $gдолжен:должна; понять, $n... с ней произошло нечто ужасное. Она изменилась. Ты $gсам:сама; все поймешь, когда придешь к Пьедесталу.$b$bУдачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эллию Вороную Гриву на верху Пьедестала Надежды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ваш соперник возвращается.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эллия Вороная Грива',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30740,'Чемпион Чи-Цзи','Наш орден всегда будет чтить тебя и твое мастерство, но при этом мы будем рады твоему участию в наших поединках.$b$bОдин из наших чемпионов ждет тебя на верху Купола Балрисса. Ты окажешь ему честь, сразившись с ним.','Победите чемпиона Чи-Цзи.','Воплощенное мастерство, как и обычно.$B$BМы надеемся на скорую встречу с тобой, Каперниан.','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чемпион Чи-Цзи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш орден всегда будет чтить тебя и твое мастерство, но при этом мы будем рады твоему участию в наших поединках.$b$bОдин из наших чемпионов ждет тебя на верху Купола Балрисса. Ты окажешь ему честь, сразившись с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите чемпиона Чи-Цзи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воплощенное мастерство, как и обычно.$B$BМы надеемся на скорую встречу с тобой, Каперниан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телонию в Колыбель Чи-Цзи, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30742,'Взять козла за рога','Плохая идея была. Очень.$B$BНепросто вынимать семена из ягод кафы. Появилась тут идея: козлы-то ягоды едят, а семена из них выходят... на другой день.$B$BНу что, сожрали козлы с пика Коту все мои ягоды и взбесились! Кидаются на все, что движется.$B$BПик Коту раньше был безопасным, там груммели кафу собирали. А теперь все, козлы – штука такая. Поможешь?','Убейте 12 одурманенных кафой горных козлов на пике Коту.','Спасибо тебе. Пусть это будет тебе уроком: не корми козлов.','Вернитесь к кузену Шерстомеху в лагерь Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взять козла за рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плохая идея была. Очень.$B$BНепросто вынимать семена из ягод кафы. Появилась тут идея: козлы-то ягоды едят, а семена из них выходят... на другой день.$B$BНу что, сожрали козлы с пика Коту все мои ягоды и взбесились! Кидаются на все, что движется.$B$BПик Коту раньше был безопасным, там груммели кафу собирали. А теперь все, козлы – штука такая. Поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 одурманенных кафой горных козлов на пике Коту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе. Пусть это будет тебе уроком: не корми козлов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузену Шерстомеху в лагерь Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30743,'Изысканная кафа','Гениально же: ягоды кафы даешь козлу, а на выходе семена.$B$BКафа\'кота и так бешеных денег стоит, да и не достанешь, а тут кафа-гута – пальчики оближешь!$B$BТолько не вышло ничего. Дядя злится, на горе бедлам. Мне бы хоть достать кафа-гуту, которая уже получилась, и больше не связываться.$B$BСобирать не прошу – работа грязная, не для героев – просто оставляй метки, чтоб мне найти было проще, когда опять можно будет на гору ходить.','Хорошо, я схожу туда за... урожаем.$B$B<Кузен Шерстомех обматывает руки длинными льняными полосами.>$B$BИ с чего я решил, что это круто?..','Вернитесь к кузену Шерстомеху в лагерь Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изысканная кафа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гениально же: ягоды кафы даешь козлу, а на выходе семена.$B$BКафа\'кота и так бешеных денег стоит, да и не достанешь, а тут кафа-гута – пальчики оближешь!$B$BТолько не вышло ничего. Дядя злится, на горе бедлам. Мне бы хоть достать кафа-гуту, которая уже получилась, и больше не связываться.$B$BСобирать не прошу – работа грязная, не для героев – просто оставляй метки, чтоб мне найти было проще, когда опять можно будет на гору ходить.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, я схожу туда за... урожаем.$B$B<Кузен Шерстомех обматывает руки длинными льняными полосами.>$B$BИ с чего я решил, что это круто?..',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузену Шерстомеху в лагерь Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30744,'Смесь кафы','Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее: то козлы кусты объедят, то йети все перетаскают.$B$BЯ хорошо заплачу, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.','Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смесь кафы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее: то козлы кусты объедят, то йети все перетаскают.$B$BЯ хорошо заплачу, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30745,'Расхлебывать кафу','Да, на пике Коте водятся йети. Обычно они мирные, едят козлов.$B$BНо теперь они едят козлов, нажравшихся кафы.$b$b<Остробоб недовольно смотрит на кузена Шерстомеха.>$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.','Убейте 5 одурманенных кафой йети в пещерах на пике Коту.','Есть!$B$BЙети и так-то сильны, а уж на что похожи чокнутые любители кафы, даже думать боюсь. Вот это храбрость. А может, везение. Или идиотизм.$B$BИли все сразу.','Вернитесь к дяде Остробобу в лагерь Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расхлебывать кафу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, на пике Коте водятся йети. Обычно они мирные, едят козлов.$B$BНо теперь они едят козлов, нажравшихся кафы.$b$b<Остробоб недовольно смотрит на кузена Шерстомеха.>$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 одурманенных кафой йети в пещерах на пике Коту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Есть!$B$BЙети и так-то сильны, а уж на что похожи чокнутые любители кафы, даже думать боюсь. Вот это храбрость. А может, везение. Или идиотизм.$B$BИли все сразу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дяде Остробобу в лагерь Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30746,'Честная сделка','<Вновь раздается страшный вой, так громко и страшно не ревел еще ни один встреченный вами йети. А затем голос груммеля.>$B$BОй! Умоляю, могучая Коту Кон, прости груммеля. Отпусти меня, я принесу много-много кафы, обещаю!$B$B<Существо, названное Коту Кон, издает ответный рев.>','Принесите мешок ягод кафа\'коту в логово Коту Кон недалеко от пика Коту.','Это кафа?$B$BТы...$B$BВот это да...$B$BУдачка...$B$BСкорее, отдадим ей! Может, она не съест нас обоих...','Коту Кон желает еще кафы, но у меня больше не осталось! Пришлось кланяться и кланяться, но она все равно недовольна!$B$B<Перепуганный груммель сглатывает и переходит почти на шепот.>$B$BКажется, она чует кафу, которую я выпил за завтраком.','Принесите мешок ягод кафа\'коту в логово Коту Кон, что рядом с вершиной пика Коту.','Ужас пика Коту','Коту Кон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честная сделка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вновь раздается страшный вой, так громко и страшно не ревел еще ни один встреченный вами йети. А затем голос груммеля.>$B$BОй! Умоляю, могучая Коту Кон, прости груммеля. Отпусти меня, я принесу много-много кафы, обещаю!$B$B<Существо, названное Коту Кон, издает ответный рев.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мешок ягод кафа\'коту в логово Коту Кон недалеко от пика Коту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это кафа?$B$BТы...$B$BВот это да...$B$BУдачка...$B$BСкорее, отдадим ей! Может, она не съест нас обоих...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Коту Кон желает еще кафы, но у меня больше не осталось! Пришлось кланяться и кланяться, но она все равно недовольна!$B$B<Перепуганный груммель сглатывает и переходит почти на шепот.>$B$BКажется, она чует кафу, которую я выпил за завтраком.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите мешок ягод кафа\'коту в логово Коту Кон, что рядом с вершиной пика Коту.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ужас пика Коту',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Коту Кон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30747,'Джутовая резня','Ух ты! Это было грубо.$B$BХотя чего я ждал...$B$BСпасибо тебе. Похоже, у нас с Грозой пика Коту сложилось взаимовыгодное сотрудничество.','Вернитесь к племяннику Берберри в лагерь Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джутовая резня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Это было грубо.$B$BХотя чего я ждал...$B$BСпасибо тебе. Похоже, у нас с Грозой пика Коту сложилось взаимовыгодное сотрудничество.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к племяннику Берберри в лагерь Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30750,'А ну слезь оттуда!','Яунголы-лучники стоят на стене и прикрывают тех, что внизу. Не знаю уж, что там Лао-Чинь думает, но тебе надо разобраться с этими стрелками.\r\n\r\nНам повезло, что дух Быка на нашей стороне. Когда враги ослабеют, дух Быка оглушит их, и ты сможешь столкнуть их со стены.\r\n\r\nЛучников ты найдешь сразу за этой дверью.','Убейте 12 опытных осулов-лучников или осулов – воинов огня.','Ха! Они так и отлетали во все стороны! Отлично сработано.','Вернитесь к Суне Беззвучный Удар к Вратам Быка на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А ну слезь оттуда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы-лучники стоят на стене и прикрывают тех, что внизу. Не знаю уж, что там Лао-Чинь думает, но тебе надо разобраться с этими стрелками.\r\n\r\nНам повезло, что дух Быка на нашей стороне. Когда враги ослабеют, дух Быка оглушит их, и ты сможешь столкнуть их со стены.\r\n\r\nЛучников ты найдешь сразу за этой дверью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 опытных осулов-лучников или осулов – воинов огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Они так и отлетали во все стороны! Отлично сработано.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Суне Беззвучный Удар к Вратам Быка на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30751,'Ужасная жертва','Я тут подумал и... готов принести ужасную жертву.\r\n\r\nНасколько я понял, мой крепкий хмель укрепит дух защитников Врат Быка и позволит им продержаться подольше...\r\n\r\nМне не хотелось бы сейчас погружаться в детали, но прошу тебя – пока будешь на стене, собери бочки с нефтью, которую они используют, чтобы поджигать стрелы. Они нам пригодятся.','Собрать 6 бочек с яунгольской нефтью.','Хорошо, я продолжу подготовку. Удачи тебе.','Нефть у тебя?','Вернитесь к Лао-Чиню Стальному Брюху к Вратам Быка на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасная жертва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут подумал и... готов принести ужасную жертву.\r\n\r\nНасколько я понял, мой крепкий хмель укрепит дух защитников Врат Быка и позволит им продержаться подольше...\r\n\r\nМне не хотелось бы сейчас погружаться в детали, но прошу тебя – пока будешь на стене, собери бочки с нефтью, которую они используют, чтобы поджигать стрелы. Они нам пригодятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Собрать 6 бочек с яунгольской нефтью.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, я продолжу подготовку. Удачи тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нефть у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лао-Чиню Стальному Брюху к Вратам Быка на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30752,'Невероятно!','Я просто отказываюсь поверить, что стражники не пустят нас в монастырь, если мы убедим их в серьезности ситуации.\r\n\r\nДруг, иди на восток к стражникам и потребуй, чтобы нас пустили. Я пойду с тобой.','Поговорите со стражем монастыря Шадо-Пан и потребуйте, чтобы вас впустили.','Нет... Все хуже, чем мне казалось. Неужели скверна проникла и в монастырь...','Поговорите с Банем Медвежьим Сердцем у монастыря Шадо-Пан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невероятно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я просто отказываюсь поверить, что стражники не пустят нас в монастырь, если мы убедим их в серьезности ситуации.\r\n\r\nДруг, иди на восток к стражникам и потребуй, чтобы нас пустили. Я пойду с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со стражем монастыря Шадо-Пан и потребуйте, чтобы вас впустили.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет... Все хуже, чем мне казалось. Неужели скверна проникла и в монастырь...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Банем Медвежьим Сердцем у монастыря Шадо-Пан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30753,'Верхом на акуле','Есть только один способ убить акулу там, откуда я родом, – голыми руками!$b$bЯ накидал в воду рядом с пристанью достаточно много приманки, так что это место скоро будет кишеть местными рифовыми акулами. Прыгай на первую, которую увидишь, и расправься с ней!','Убейте разъяренную рифовую акулу голыми руками.','Достойный экземпляр, Славентик! Я впечатлен!','Вернитесь к Джону "Большому крючку" Марсоку в Деревню рыболовов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верхом на акуле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть только один способ убить акулу там, откуда я родом, – голыми руками!$b$bЯ накидал в воду рядом с пристанью достаточно много приманки, так что это место скоро будет кишеть местными рифовыми акулами. Прыгай на первую, которую увидишь, и расправься с ней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте разъяренную рифовую акулу голыми руками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Достойный экземпляр, Славентик! Я впечатлен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону "Большому крючку" Марсоку в Деревню рыболовов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30754,'Яркая наживка','Некоторых рыб можно подманить только ярким светом. В лесу к северу отсюда водятся пандаренские светляки, которых называют солнечными ползунами.$b$bИх можно найти у корней пней. Принеси мне пригоршню таких светляков, и я пущу их на наживку!','Соберите 7 солнечных ползунов в лесу к северу от Деревни рыболовов.','Вот эти в самый раз, Славентик. Спасибо за помощь!','Ну, что там с солнечными ползунами?','Принесите солнечных ползунов Джону "Большому крючку" Марсоку в Деревню рыболовов.','Этих маленьких светящихся насекомых можно обнаружить у подножия деревьев в Красарангских джунглях.','Солнечный ползун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яркая наживка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторых рыб можно подманить только ярким светом. В лесу к северу отсюда водятся пандаренские светляки, которых называют солнечными ползунами.$b$bИх можно найти у корней пней. Принеси мне пригоршню таких светляков, и я пущу их на наживку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 солнечных ползунов в лесу к северу от Деревни рыболовов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот эти в самый раз, Славентик. Спасибо за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там с солнечными ползунами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите солнечных ползунов Джону "Большому крючку" Марсоку в Деревню рыболовов.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этих маленьких светящихся насекомых можно обнаружить у подножия деревьев в Красарангских джунглях.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Солнечный ползун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30757,'Глава Шадо-Пан','В нашего настоятеля Тажаня Чжу вселился ша – воплощение чистой ненависти. Монастырь погиб!$B$B$c, я знаю, ты найдешь способ излечить настоятеля! Кажется, он медитирует в Роще Опадающих Лепестков.','Избавьте Тажаня Чжу от одержимости Ша Ненависти.','Поговорите с Тажанем Чжу в Роще Опадающих Лепестков, что в монастыре Шадо-Пан.','Надо освободить его от Ша Ненависти!','Тажань Чжу, глава Шадо-Пан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глава Шадо-Пан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нашего настоятеля Тажаня Чжу вселился ша – воплощение чистой ненависти. Монастырь погиб!$B$B$c, я знаю, ты найдешь способ излечить настоятеля! Кажется, он медитирует в Роще Опадающих Лепестков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьте Тажаня Чжу от одержимости Ша Ненависти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тажанем Чжу в Роще Опадающих Лепестков, что в монастыре Шадо-Пан.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Надо освободить его от Ша Ненависти!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тажань Чжу, глава Шадо-Пан',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30759,'Прямо в пекло','Монастырь Шадо-Пан захвачен!$B$BНовобранцу Киа удалось сообщить мне, что все его обитатели попали под воздействие ша. Страшнее всего, что это случилось даже с нашим господином, Тажанем Чжу.$B$B$c, ты можешь отправиться к северу, в горы? Ты войдешь в монастырь через додзё Небесного Удара. Там прячется Киа.','Поговорите с Новобранцем Киа в додзё Небесного Удара, что в монастыре Шадо-Пан.','Return to no one because you didn\'t get this from a questgiver and there\'s no quest completion NPC spawned.P') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прямо в пекло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Монастырь Шадо-Пан захвачен!$B$BНовобранцу Киа удалось сообщить мне, что все его обитатели попали под воздействие ша. Страшнее всего, что это случилось даже с нашим господином, Тажанем Чжу.$B$B$c, ты можешь отправиться к северу, в горы? Ты войдешь в монастырь через додзё Небесного Удара. Там прячется Киа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Новобранцем Киа в додзё Небесного Удара, что в монастыре Шадо-Пан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to no one because you didn\'t get this from a questgiver and there\'s no quest completion NPC spawned.P',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30763,'Пираньи!','Иную рыбу бывает очень трудно поймать. Волчья пиранья – как раз из таких рыбок.$b$bМне повезло, что сюда $gявился:явилась; ты! Проверим твои рыбацкие умения: принеси мне несколько пираний из реки Красаранг, что к северо-западу отсюда.','Поймайте 5 волчьих пираний в реке Красаранг в Красарангских джунглях.','Вижу, все пальцы у тебя на месте. Отлично.','Повезло?','Отнесите пиранью Фо Фуку в Поющую Котловину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираньи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иную рыбу бывает очень трудно поймать. Волчья пиранья – как раз из таких рыбок.$b$bМне повезло, что сюда $gявился:явилась; ты! Проверим твои рыбацкие умения: принеси мне несколько пираний из реки Красаранг, что к северо-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 волчьих пираний в реке Красаранг в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, все пальцы у тебя на месте. Отлично.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повезло?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите пиранью Фо Фуку в Поющую Котловину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30765,'Восстановленная честь','Значит так, $n. Яунгольский вождь Громила убил шадо-мастера Чжэня и завладел его знаменем.$B$BУбей Громилу и восстанови честь Мстера Чжэня, или это сделаю я.','Верните знамя Чжэня.','Вернитесь к У Као Блейку к Вратам Зимнего Цветения на вершине Кунь-Лай.','Отберите знамя у Громилы и верните честь Чжэна.','Громила') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановленная честь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит так, $n. Яунгольский вождь Громила убил шадо-мастера Чжэня и завладел его знаменем.$B$BУбей Громилу и восстанови честь Мстера Чжэня, или это сделаю я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните знамя Чжэня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к У Као Блейку к Вратам Зимнего Цветения на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Отберите знамя у Громилы и верните честь Чжэна.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Громила',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30766,'Ценный антиквариат','<Со статуи падает реликвия. Да, знаток оценит эту вещь по достоинству.>$B$B<В этих же руинах бродит искатель сокровищ. Возможно, он захочет выкупить у вас находку?>','Соберите еще 11 реликвий могу.','Поговорите с Бао Цзянем у Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный антиквариат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Со статуи падает реликвия. Да, знаток оценит эту вещь по достоинству.>$B$B<В этих же руинах бродит искатель сокровищ. Возможно, он захочет выкупить у вас находку?>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите еще 11 реликвий могу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бао Цзянем у Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30767,'Рискнуть всем','Погоди, что?! Какое безрассудство! Взорвать корабль – это просто безумие! Они могли убить Шэнь-Цзынь Су и всех нас заодно.$b$BЯ знаю, времени у нас мало, но мы должны найти какой-то другой способ...','Избавьте Шэнь-Цзынь Су от занозы.','Первый шаг сделан. Но теперь мы должны спасти Шэнь-Цзынь Су!','Поговорите с Цзи Огненной Лапой на месте падения "Небесного искателя".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рискнуть всем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Погоди, что?! Какое безрассудство! Взорвать корабль – это просто безумие! Они могли убить Шэнь-Цзынь Су и всех нас заодно.$b$BЯ знаю, времени у нас мало, но мы должны найти какой-то другой способ...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избавьте Шэнь-Цзынь Су от занозы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Первый шаг сделан. Но теперь мы должны спасти Шэнь-Цзынь Су!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи Огненной Лапой на месте падения "Небесного искателя".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30768,'Мой муж...','Линь...\r\n\r\nМне все равно, что говорят Бань, Лао-Чинь или даже Тажань Чжу. Я направляюсь в Танлунские степи. Возможно, мне не удастся спасти Линя самостоятельно, но я не собираюсь рассиживаться и ждать, пока это сделают все остальные.\r\n\r\nКак только Тажань Чжу откроет двери своего драгоценного монастыря, мы спасем Линя. А до того я отправлюсь на разведку – убедиться, что с ним все в порядке.','Встретьтесь с Суной Беззвучный Удар на укреплениях Лун-Ин в Танлунских степях.','Хорошо. Похоже, остальные шадо-паны решили, что это удачный момент, чтобы нагнать меня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мой муж...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Линь...\r\n\r\nМне все равно, что говорят Бань, Лао-Чинь или даже Тажань Чжу. Я направляюсь в Танлунские степи. Возможно, мне не удастся спасти Линя самостоятельно, но я не собираюсь рассиживаться и ждать, пока это сделают все остальные.\r\n\r\nКак только Тажань Чжу откроет двери своего драгоценного монастыря, мы спасем Линя. А до того я отправлюсь на разведку – убедиться, что с ним все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Суной Беззвучный Удар на укреплениях Лун-Ин в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Похоже, остальные шадо-паны решили, что это удачный момент, чтобы нагнать меня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30769,'Первое нападение','Теперь, когда мы хорошенько поразмышляли о слабостях наших врагов, можно нанести яунголам прямой удар.$B$BИди и сразись с осулами-буянами на западном плоскогорье.$B$BДай им знать, что мы здесь и не боимся их угроз.','Убейте 6 осулов-остророгов.','Поговорите с Суной Беззвучный Удар в огненном лагере осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первое нападение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы хорошенько поразмышляли о слабостях наших врагов, можно нанести яунголам прямой удар.$B$BИди и сразись с осулами-буянами на западном плоскогорье.$B$BДай им знать, что мы здесь и не боимся их угроз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 осулов-остророгов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Суной Беззвучный Удар в огненном лагере осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30770,'Разъяренный скот','Что нужно каждой армии, так это провизия.$B$BВо вражеском лагере к западу отсюда пасется большое стадо, которое служит основным источником еды для яунгольской армии.$B$BК счастью для нас, яков и диких мушанов, водящихся в этой местности, легко испугать.$B$BПрокрадись туда, отвесь им хороших шлепков и погляди, что из этого выйдет.','Испугайте 8 мохнатых яков или степных зверей.','О-хо-хо! Аж отсюда было видно, как эти животные подняли пыль столбом.$B$BЭти яунголы, небось, до сих пор думают, что произошло.','Поговорите с Банем Медвежьим Сердцем в огненном лагере осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренный скот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что нужно каждой армии, так это провизия.$B$BВо вражеском лагере к западу отсюда пасется большое стадо, которое служит основным источником еды для яунгольской армии.$B$BК счастью для нас, яков и диких мушанов, водящихся в этой местности, легко испугать.$B$BПрокрадись туда, отвесь им хороших шлепков и погляди, что из этого выйдет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испугайте 8 мохнатых яков или степных зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-хо-хо! Аж отсюда было видно, как эти животные подняли пыль столбом.$B$BЭти яунголы, небось, до сих пор думают, что произошло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Банем Медвежьим Сердцем в огненном лагере осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30771,'Лучшая смола','Когда племя осулов идет на войну, его воины смазывают свои копья и стрелы горючей смолой, которая легко воспламеняется.$B$BОни используют это ужасное оружие, чтобы не только проливать кровь, но и стирать жилища врагов с лица земли.$B$BМне нужно, чтобы ты $gсобрал:собрала; эту смолу, пока будешь в их лагере.$B$BС ее помощью мы покажем яунголам, что, когда играешь с огнем, можешь и сам обжечься.','Соберите 8 кусков черной смолы.','Яунголам недостаточно просто победить врагов. Им нужно полностью их уничтожить.','Поговорите с Банем Медвежьим Сердцем в огненном лагере осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшая смола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда племя осулов идет на войну, его воины смазывают свои копья и стрелы горючей смолой, которая легко воспламеняется.$B$BОни используют это ужасное оружие, чтобы не только проливать кровь, но и стирать жилища врагов с лица земли.$B$BМне нужно, чтобы ты $gсобрал:собрала; эту смолу, пока будешь в их лагере.$B$BС ее помощью мы покажем яунголам, что, когда играешь с огнем, можешь и сам обжечься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кусков черной смолы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яунголам недостаточно просто победить врагов. Им нужно полностью их уничтожить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Банем Медвежьим Сердцем в огненном лагере осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30772,'Время ярости','Перед нами главный костяк армии яунголов.$B$BОни стягивают огромные силы, чтобы напасть на поселения Кунь-Лай.$B$BЕсли мы сейчас нападем на осулов, то сможем здорово подорвать их силы.$B$BПомни – каждый, кого мы здесь убьем, не сможет потом убить кого-то из наших.','Убейте 8 осулов-мародеров или осулов-огнеплюев.','Это должно пробить серьезную брешь в их рядах.$B$BСомневаюсь, что они смогут оправиться от таких потерь.','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед нами главный костяк армии яунголов.$B$BОни стягивают огромные силы, чтобы напасть на поселения Кунь-Лай.$B$BЕсли мы сейчас нападем на осулов, то сможем здорово подорвать их силы.$B$BПомни – каждый, кого мы здесь убьем, не сможет потом убить кого-то из наших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 осулов-мародеров или осулов-огнеплюев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это должно пробить серьезную брешь в их рядах.$B$BСомневаюсь, что они смогут оправиться от таких потерь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30773,'Смола – тоже оружие','Используйте взрывчатку Баня, чтобы уничтожить 6 баллист осулов.','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смола – тоже оружие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте взрывчатку Баня, чтобы уничтожить 6 баллист осулов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30774,'Спасение стрелков','Откройте деревянные клетки, чтобы освободить 4 стрелков Лун-Ин и Линя Беззвучный Удар.','Я искренне сожалею, что Линя уже нет в живых.$B$BСуна воприняла весть с глубокой скорбью. Когда-нибудь она меня простит.$B$BОт лица всех спасенных тобой воинов Шадо-Пан хочу сердечно поблагодарить тебя за то, что они вернулись целыми и невредимыми.','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение стрелков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте деревянные клетки, чтобы освободить 4 стрелков Лун-Ин и Линя Беззвучный Удар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я искренне сожалею, что Линя уже нет в живых.$B$BСуна воприняла весть с глубокой скорбью. Когда-нибудь она меня простит.$B$BОт лица всех спасенных тобой воинов Шадо-Пан хочу сердечно поблагодарить тебя за то, что они вернулись целыми и невредимыми.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в огненный лагерь осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30775,'Изгнанник','Да что тут говорить, $gнезнакомец:незнакомка;...$B$BЯ сражался с Цзюн Дуком и проиграл. Я был дураком и поверил, что он будет сражаться честно.$B$BТеперь мои собственные братья обратились против меня, и вот я вынужден говорить с врагами.$B$BЯ знаю, что ты здесь, чтобы пролить кровь осулов.$B$BПрошу только об одном – убей тех троих, кто предал меня.$B$BЭто Юранг, который отравил мое питье. Ку-Тун, который согнул мое копье. И Баттат, который вонзил мне в бок кинжал, когда я был на волосок от победы.$B$BСделай это, и я смогу умереть спокойно.','Убейте Юранга, Ку-Туна и Баттата.','Приятно узнать, что эти трусы погибли от твоей руки.$B$BВозможно, теперь буря в моем сердце утихнет.','Вернитесь к Катаку Побежденному в огненный лагерь осулов в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгнанник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да что тут говорить, $gнезнакомец:незнакомка;...$B$BЯ сражался с Цзюн Дуком и проиграл. Я был дураком и поверил, что он будет сражаться честно.$B$BТеперь мои собственные братья обратились против меня, и вот я вынужден говорить с врагами.$B$BЯ знаю, что ты здесь, чтобы пролить кровь осулов.$B$BПрошу только об одном – убей тех троих, кто предал меня.$B$BЭто Юранг, который отравил мое питье. Ку-Тун, который согнул мое копье. И Баттат, который вонзил мне в бок кинжал, когда я был на волосок от победы.$B$BСделай это, и я смогу умереть спокойно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Юранга, Ку-Туна и Баттата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно узнать, что эти трусы погибли от твоей руки.$B$BВозможно, теперь буря в моем сердце утихнет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катаку Побежденному в огненный лагерь осулов в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30776,'Цзюн Дук','Наконец-то Цзюн Дук мертв.$B$BСотни, может, тысячи расстались с жизнью из-за его неистовой жестокости.$B$BИ хотя они не присутствовали при его смерти, они бы благодарили тебя за храбрость.','Вернитесь к Баню Медвежьему Сердцу на укрепления Лун-Ин, что в Танлунских степях.','Вождь осулов. Убей его!','Цзюн Дук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цзюн Дук',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то Цзюн Дук мертв.$B$BСотни, может, тысячи расстались с жизнью из-за его неистовой жестокости.$B$BИ хотя они не присутствовали при его смерти, они бы благодарили тебя за храбрость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу на укрепления Лун-Ин, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вождь осулов. Убей его!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Цзюн Дук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30777,'Поиски Суны','У меня плохие новости. Когда я вернулся, Суна уже исчезла.$B$BОстальные говорят, что она собрала вещи и направилась по восточной дороге, бормоча что-то о том, что положит конец нашествиям яунголов.$B$BНельзя позволить ей в одиночестве бродить по опасным местам.$B$BЯ собрал группу воинов для дальнейшего похода на восток.$B$BМы вскоре выступаем в путь. Запрыгивай на повозку, если хочешь отправиться вместе с Шадо-Пан. Или можем встретиться прямо там.','Поговорите с Банем Медвежьим Сердцем после прибытия в Хватку Ненависти.','Ну что ж, вот мы и здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Суны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня плохие новости. Когда я вернулся, Суна уже исчезла.$B$BОстальные говорят, что она собрала вещи и направилась по восточной дороге, бормоча что-то о том, что положит конец нашествиям яунголов.$B$BНельзя позволить ей в одиночестве бродить по опасным местам.$B$BЯ собрал группу воинов для дальнейшего похода на восток.$B$BМы вскоре выступаем в путь. Запрыгивай на повозку, если хочешь отправиться вместе с Шадо-Пан. Или можем встретиться прямо там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Банем Медвежьим Сердцем после прибытия в Хватку Ненависти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, вот мы и здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30778,'Прах к праху','Если хотим разбить здесь лагерь, нельзя оставлять гнить все эти тела яунголов.$B$BВозьми этот факел и подожги трупы жителей деревни.$B$BДым от факела заодно очистит землю и воздух вокруг.$B$BДаже наши враги заслуживают того, чтобы покоиться с миром.','Используйте факел Шадо-Пан, чтобы поджечь 20 трупов жителей деревни Слабого Ветра.','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хотим разбить здесь лагерь, нельзя оставлять гнить все эти тела яунголов.$B$BВозьми этот факел и подожги трупы жителей деревни.$B$BДым от факела заодно очистит землю и воздух вокруг.$B$BДаже наши враги заслуживают того, чтобы покоиться с миром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте факел Шадо-Пан, чтобы поджечь 20 трупов жителей деревни Слабого Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30779,'Уничтожение падальщиков','Гниющие трупы привлекают гиен-падальщиков.$B$BОни не просто жрут падаль и разносят болезни: эти дикие твари набросятся на нас, как только завидят.$B$BИди и уничтожь этих зверей. Неприятное задание, но нужное.','Убейте 8 пеплозубых гиен.','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение падальщиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гниющие трупы привлекают гиен-падальщиков.$B$BОни не просто жрут падаль и разносят болезни: эти дикие твари набросятся на нас, как только завидят.$B$BИди и уничтожь этих зверей. Неприятное задание, но нужное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пеплозубых гиен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30780,'Изучение тотемов','Когда мы вошли в деревню, по всему лагерю лежали тотемы яунголов.$B$BЕсть у меня подозрение, что тут задействованы темные силы, а эти тотемы помогут разобраться в природе этих сил.$B$BСможешь ли ты принести мне несколько этих тотемов для дальнейшего изучения? Мне бы хотелось внимательно их осмотреть.','Соберите 9 тотемов деревни Слабого Ветра.','Так и есть! Эти тотемы в свое время использовались для хранения и направления огромного количества магической энергии.$B$BПожалуй, я смогу снова их так использовать!','Я правда верю, что эти тотемы нам пригодятся.','Вернитесь к Ялии Мудрый Шепот в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение тотемов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы вошли в деревню, по всему лагерю лежали тотемы яунголов.$B$BЕсть у меня подозрение, что тут задействованы темные силы, а эти тотемы помогут разобраться в природе этих сил.$B$BСможешь ли ты принести мне несколько этих тотемов для дальнейшего изучения? Мне бы хотелось внимательно их осмотреть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 тотемов деревни Слабого Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так и есть! Эти тотемы в свое время использовались для хранения и направления огромного количества магической энергии.$B$BПожалуй, я смогу снова их так использовать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я правда верю, что эти тотемы нам пригодятся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ялии Мудрый Шепот в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30781,'Тяжкий рок яунголов','Бань попросил меня осмотреть деревню, чтобы определить, что там произошло.$B$BС востока, запада, северо-запада и юга поднимается дым.$B$BМне нужен кто-то, кому я доверяю и кто может прикрыть меня.$B$BЧто скажешь? Поможешь мне в первой вылазке?','Отведите Сяо Ту к клубам дыма в Хватке Ненависти.','Вернитесь к Баню Медвежье Сердце в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжкий рок яунголов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бань попросил меня осмотреть деревню, чтобы определить, что там произошло.$B$BС востока, запада, северо-запада и юга поднимается дым.$B$BМне нужен кто-то, кому я доверяю и кто может прикрыть меня.$B$BЧто скажешь? Поможешь мне в первой вылазке?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Сяо Ту к клубам дыма в Хватке Ненависти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежье Сердце в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30782,'Недобрые духи','Духи погибших жителей деревни вернулись в мир живых! Я чувствую исходящую от них ненависть.$B$B$n, если мы хотим здесь выжить, то должны себя защитить. Это единственный способ их упокоить.','Убейте 10 недобрых духов.','Хорошая работа. Мы не можем принести им воздаяние, но, по крайней мере, можем умерить их ярость.','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недобрые духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи погибших жителей деревни вернулись в мир живых! Я чувствую исходящую от них ненависть.$B$B$n, если мы хотим здесь выжить, то должны себя защитить. Это единственный способ их упокоить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 недобрых духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа. Мы не можем принести им воздаяние, но, по крайней мере, можем умерить их ярость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30783,'Мы во власти ненависти','Нужно было еще раньше догадаться о присутствии ша!$B$BМы в безопасности, пока находимся внутри защитных чар тотема гармонии, но многим из нашего лагеря повезло меньше.$B$BОни оказались в ловушке снаружи лагеря, когда проявила себя сила ша, и теперь обратились друг против друга!$B$BВозьми с собой один из моих тотемов. Помести его рядом с обезумевшим союзником, чтобы очистить его, но проявляй осторожность.$B$BТы можешь столкнуться с тьмой, что заполнила их разум.','Используйте тотем гармонии, чтобы изгнать духи ша из 8 обезумевших следопытов Шадо-Пан. Одержите победу над воплощениями испепеляющей ненависти, чтобы очистить ваших союзников.','Спасибо.$B$BШа нападает на слабых и уязвимых.$B$BЕсли мы не будем бдительными, даже сильнейший из нас может оказаться жертвой темного влияния ша.','Вернитесь к Ялии Мудрый Шепот в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы во власти ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно было еще раньше догадаться о присутствии ша!$B$BМы в безопасности, пока находимся внутри защитных чар тотема гармонии, но многим из нашего лагеря повезло меньше.$B$BОни оказались в ловушке снаружи лагеря, когда проявила себя сила ша, и теперь обратились друг против друга!$B$BВозьми с собой один из моих тотемов. Помести его рядом с обезумевшим союзником, чтобы очистить его, но проявляй осторожность.$B$BТы можешь столкнуться с тьмой, что заполнила их разум.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тотем гармонии, чтобы изгнать духи ша из 8 обезумевших следопытов Шадо-Пан. Одержите победу над воплощениями испепеляющей ненависти, чтобы очистить ваших союзников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо.$B$BШа нападает на слабых и уязвимых.$B$BЕсли мы не будем бдительными, даже сильнейший из нас может оказаться жертвой темного влияния ша.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ялии Мудрый Шепот в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30784,'Точка невозврата','Один из наших следопытов доложил, что видел Суну на холме на северо-западе.$B$BКакое облегчение знать, что она в целости и сохранности. Я опасался того, что она могла сотворить в своем горе.$B$BСможешь ли ты поговорить с ней от моего имени?$B$BВозьми с собой этот тотем. Он может пригодиться против опасностей, с которыми ты можешь столкнуться по дороге.','Найдите Суну Беззвучный Удар.','Что? Она была одержима Ша Ненависти?$B$BНет. Нет!$B$BНесмотря на все наши различия, она была одной из нас. Сегодня Шадо-Пан потерял любимую сестру.$B$BЕе смерть не будет напрасной. Я не успокоюсь, пока не одержу победу над Ша Ненависти!$B$BСуна, клянусь тебе в этом!','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Точка невозврата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших следопытов доложил, что видел Суну на холме на северо-западе.$B$BКакое облегчение знать, что она в целости и сохранности. Я опасался того, что она могла сотворить в своем горе.$B$BСможешь ли ты поговорить с ней от моего имени?$B$BВозьми с собой этот тотем. Он может пригодиться против опасностей, с которыми ты можешь столкнуться по дороге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Суну Беззвучный Удар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Она была одержима Ша Ненависти?$B$BНет. Нет!$B$BНесмотря на все наши различия, она была одной из нас. Сегодня Шадо-Пан потерял любимую сестру.$B$BЕе смерть не будет напрасной. Я не успокоюсь, пока не одержу победу над Ша Ненависти!$B$BСуна, клянусь тебе в этом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в Хватку Ненависти, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30785,'Застава Гао-Жаня','С твоей помощью мы упокоили духов этого места.$B$BНаконец-то они обрели мир.$B$BНаше путешествие по этой проклятой земле, боюсь, только началось.$B$BМне еще нужно закончить здесь несколько важных дел, но мы уже скоро отправимся в путь.$B$BМне нужно, чтобы кто-нибудь поехал вперед и предупредил господина Тажаня Чжу, что мы к нему присоединимся.$B$BНайди его у Заставы Гао-Жаня. Расскажи ему о том, что здесь произошло.','Поговорите с господином Тажанем Чжу у Заставы Гао-Жаня в Танлунских степях.','Ну что, северная экспедиция была успешной? Какие у тебя новости?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застава Гао-Жаня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С твоей помощью мы упокоили духов этого места.$B$BНаконец-то они обрели мир.$B$BНаше путешествие по этой проклятой земле, боюсь, только началось.$B$BМне еще нужно закончить здесь несколько важных дел, но мы уже скоро отправимся в путь.$B$BМне нужно, чтобы кто-нибудь поехал вперед и предупредил господина Тажаня Чжу, что мы к нему присоединимся.$B$BНайди его у Заставы Гао-Жаня. Расскажи ему о том, что здесь произошло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с господином Тажанем Чжу у Заставы Гао-Жаня в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, северная экспедиция была успешной? Какие у тебя новости?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30786,'Копье в боку, сердце на цепи','Моя жизнь кончена. Яунгол проткнул мне бок копьем. Эта рана смертельна.$b$bЯунгол поймал меня в сети своей темной магии. Такой позор... Это страшнее смертельной раны.$b$bЯ не могу остановить смерть. Но ты можешь освободить мою душу.','Убейте Дмонга Наруука, шамана, который захватил Орбисса.','Я свободен.$B$BЯунголов нужно остановить.','Вернитесь к Орбиссу в Нижние Камышовые топи, что в Танлунских степях.','Могущественный туманный шаман из племени осулов.','Дмонг Наруук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Копье в боку, сердце на цепи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя жизнь кончена. Яунгол проткнул мне бок копьем. Эта рана смертельна.$b$bЯунгол поймал меня в сети своей темной магии. Такой позор... Это страшнее смертельной раны.$b$bЯ не могу остановить смерть. Но ты можешь освободить мою душу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Дмонга Наруука, шамана, который захватил Орбисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я свободен.$B$BЯунголов нужно остановить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Могущественный туманный шаман из племени осулов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дмонг Наруук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30787,'Факелы','До недавнего времени шаманы яунголов приходили к нам как друзья. А теперь они подчиняют наших людей своей воле.$b$bОни убивают тех, кто противится их власти. А заодно и тех, кто им подчиняется.$b$bСила туманного шамана яунголов в его факеле. Отбери факел, и он уже ничего не сможет сделать.','Раздобудьте 6 факелов туманного шамана.','Этот факел... Когда-то с его помощью яунголы говорили со мной и с моим народом.$B$BА теперь они обратили его против нас.','Эти факелы помогут мне отомстить.$B$BРана еще не доконала меня. Я успею отплатить врагу.$B$BПока есть время.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Факелы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До недавнего времени шаманы яунголов приходили к нам как друзья. А теперь они подчиняют наших людей своей воле.$b$bОни убивают тех, кто противится их власти. А заодно и тех, кто им подчиняется.$b$bСила туманного шамана яунголов в его факеле. Отбери факел, и он уже ничего не сможет сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 6 факелов туманного шамана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот факел... Когда-то с его помощью яунголы говорили со мной и с моим народом.$B$BА теперь они обратили его против нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти факелы помогут мне отомстить.$B$BРана еще не доконала меня. Я успею отплатить врагу.$B$BПока есть время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30788,'Голгосс','Предводителя туманных шаманов яунголов зовут Джахеш. Он славится своей силой.$b$bНо у нас есть тот, кто может противостоять ему, и зовут его Голгосс.$b$bОн дремлет в туманах Верхних Камышовых топей. Помоги мне призвать его, и он поможет мне отомстить за наш народ.','Призовите Голгосса. Для этого нужно воткнуть факелы туманных шаманов в торфяной ком в Верхних Камышовых топях.','Голгосс не говорит на твоем языке, он только знает пару слов. Думаю, я один понимаю тебя.$B$BОн благодарит тебя за то, что ты его призвал.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голгосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предводителя туманных шаманов яунголов зовут Джахеш. Он славится своей силой.$b$bНо у нас есть тот, кто может противостоять ему, и зовут его Голгосс.$b$bОн дремлет в туманах Верхних Камышовых топей. Помоги мне призвать его, и он поможет мне отомстить за наш народ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите Голгосса. Для этого нужно воткнуть факелы туманных шаманов в торфяной ком в Верхних Камышовых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Голгосс не говорит на твоем языке, он только знает пару слов. Думаю, я один понимаю тебя.$B$BОн благодарит тебя за то, что ты его призвал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30789,'Арконисс','Если я хочу сразиться с Джахешем, вождем туманных шаманов, мне нужно заручиться поддержкой Арконисса. Свирепость Арконисса не знает равных.$b$bОн отдыхает в туманах Верхних Камышовых топей. Найди его жилище, и призови его с помощью факелов.','Призовите Арконисса. Для этого нужно воткнуть факелы туманных шаманов в торфяной холмик в Верхних Камышовых топях.','С Аркониссом проиграть будет невозможно.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арконисс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я хочу сразиться с Джахешем, вождем туманных шаманов, мне нужно заручиться поддержкой Арконисса. Свирепость Арконисса не знает равных.$b$bОн отдыхает в туманах Верхних Камышовых топей. Найди его жилище, и призови его с помощью факелов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите Арконисса. Для этого нужно воткнуть факелы туманных шаманов в торфяной холмик в Верхних Камышовых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С Аркониссом проиграть будет невозможно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30790,'Голод Голгосса','Голгосс очень силен, но ему нужно питание, чтобы воспользоваться силой.$b$bУ кустов заплетня в Верхних Камышовых топях толстые, мясистые ветви. Это должно утолить его аппетит.','Добудьте 10 витых лоз.','Мы на шаг приблизились к моей цели.','Голод Голгосса велик.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голод Голгосса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Голгосс очень силен, но ему нужно питание, чтобы воспользоваться силой.$b$bУ кустов заплетня в Верхних Камышовых топях толстые, мясистые ветви. Это должно утолить его аппетит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 витых лоз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы на шаг приблизились к моей цели.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Голод Голгосса велик.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30791,'Жажда Арконисса','В бою Арконисса охватывает невыразимая ярость, но долгое пребывание в туманах подорвало его силу.$b$bНа болотах водится много грызунов, а их тела наполнены питательной кровью. Вернись с достаточным количеством крови, чтобы восстановить боевой дух Арконисса.','Добудьте 4 образца свернувшейся крови грызунов.','И еще один шаг к завершению моей миссии.','Приготовления уже почти закончены.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жажда Арконисса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бою Арконисса охватывает невыразимая ярость, но долгое пребывание в туманах подорвало его силу.$b$bНа болотах водится много грызунов, а их тела наполнены питательной кровью. Вернись с достаточным количеством крови, чтобы восстановить боевой дух Арконисса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 образца свернувшейся крови грызунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И еще один шаг к завершению моей миссии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приготовления уже почти закончены.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30792,'Орбисс угасает','Я знал, что смерть придет, но не знал, что она настанет так быстро.$b$bМне нужно выиграть время. Туман в Верхних Камышовых топях такой теплый и благоухающий... Этот туман – отличная пища для таких, как я.$b$bСобери его как угодно – в банки, флаконы, заполни им пространство своих сумок. Принеси его сюда – он поможет мне оставаться в своем теле еще какое-то время.','Добудьте 8 сгустков тумана, пройдя через туманные гейзеры в Верхних Камышовых топях.','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орбисс угасает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знал, что смерть придет, но не знал, что она настанет так быстро.$b$bМне нужно выиграть время. Туман в Верхних Камышовых топях такой теплый и благоухающий... Этот туман – отличная пища для таких, как я.$b$bСобери его как угодно – в банки, флаконы, заполни им пространство своих сумок. Принеси его сюда – он поможет мне оставаться в своем теле еще какое-то время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 сгустков тумана, пройдя через туманные гейзеры в Верхних Камышовых топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Нижние Камышовые топи в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30793,'Будущее в тумане','Настало время нанести удар.$b$bГолгосс, Арконисс и я пойдем на восток, во владения Джахеша. Встреть нас там и приготовься к битве.$b$bСегодня мы восстановим гордое имя нашего народа.','Уничтожьте Джахеша-осула.','Вернитесь к Орбиссу в Верхние Камышовые топи, что в Танлунских степях.','Глава туманных шаманов из племени осулов.','Джахеш-осул') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будущее в тумане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время нанести удар.$b$bГолгосс, Арконисс и я пойдем на восток, во владения Джахеша. Встреть нас там и приготовься к битве.$b$bСегодня мы восстановим гордое имя нашего народа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Джахеша-осула.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орбиссу в Верхние Камышовые топи, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Глава туманных шаманов из племени осулов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Джахеш-осул',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30794,'Неотложная помощь','Я... жив... едва-едва. Остальные убиты. Мои друзья... семья...\r\n\r\nЯ должен вернуться в деревню, но мне не хватит сил... Может, ты умеешь лечить? В моей хижине лежит целебный напиток. Если ты владеешь магией, можешь прочитать заклинание.','Исцелите мудреца Ляо, чтобы он смог подняться на ноги.','Благодарю тебя... Думаю, мне придется попросить тебя еще об одной услуге, прежде чем я смогу вернуться в деревню. Я не могу оставить здесь тела моих родных и друзей.','Поговорите с мудрецом Ляо на берегу Цзоучин, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неотложная помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я... жив... едва-едва. Остальные убиты. Мои друзья... семья...\r\n\r\nЯ должен вернуться в деревню, но мне не хватит сил... Может, ты умеешь лечить? В моей хижине лежит целебный напиток. Если ты владеешь магией, можешь прочитать заклинание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите мудреца Ляо, чтобы он смог подняться на ноги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя... Думаю, мне придется попросить тебя еще об одной услуге, прежде чем я смогу вернуться в деревню. Я не могу оставить здесь тела моих родных и друзей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мудрецом Ляо на берегу Цзоучин, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30795,'Оставайся на связи','Поговорите с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставайся на связи',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30796,'Окончательная гибель','Должно быть, души покинули открытые могилы...$b$bДля могу смерть не была концом, а лишь остановкой на пути к новому телу. Темная магия душеловов помогала духам менять оболочки.$b$bНо души, которые провели годы в запертых склепах, просто спятили. Их нужно уничтожить, пока они не рассердились или не обрели новые тела.','Уничтожить 5 страдающих душ.','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окончательная гибель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, души покинули открытые могилы...$b$bДля могу смерть не была концом, а лишь остановкой на пути к новому телу. Темная магия душеловов помогала духам менять оболочки.$b$bНо души, которые провели годы в запертых склепах, просто спятили. Их нужно уничтожить, пока они не рассердились или не обрели новые тела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожить 5 страдающих душ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30797,'Почти живой','Здесь проводился ритуал, но судя по всему, он не был завершен.$b$bСреди разбросанных предметов лежит книга. Вам непонятны письмена на ее страницах.$b$bУнести всю книгу будет тяжело, можно обойтись одной страницей. Возможно, хранитель истории Чо сможет объяснить, что там написано.','Вырвите страницу из открытой книги, чтобы отдать ее хранителю истории Чо.','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почти живой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь проводился ритуал, но судя по всему, он не был завершен.$b$bСреди разбросанных предметов лежит книга. Вам непонятны письмена на ее страницах.$b$bУнести всю книгу будет тяжело, можно обойтись одной страницей. Возможно, хранитель истории Чо сможет объяснить, что там написано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вырвите страницу из открытой книги, чтобы отдать ее хранителю истории Чо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30798,'Щит Императора','Могу осталось совсем немного, и они не живут в больших поселениях. Теперь ясно, что им понадобилось в нашей долине.$b$bИз неупокоенных духов можно собрать огромную армию. И нельзя забывать про зандаларские войска.$b$bА в Гробнице Секретов захоронен отряд великих воинов – Щит Императора. Нельзя допустить, чтобы их воскресили! Этот склеп расположен на самой высокой вершине к юго-западу отсюда.','Остановите ритуал ловли душ в Гробнице Секретов.','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щит Императора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу осталось совсем немного, и они не живут в больших поселениях. Теперь ясно, что им понадобилось в нашей долине.$b$bИз неупокоенных духов можно собрать огромную армию. И нельзя забывать про зандаларские войска.$b$bА в Гробнице Секретов захоронен отряд великих воинов – Щит Императора. Нельзя допустить, чтобы их воскресили! Этот склеп расположен на самой высокой вершине к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Остановите ритуал ловли душ в Гробнице Секретов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30799,'Гробница Теней','Судя по артефактам, найденным на алтаре, здесь готовились провести ритуал ловли душ.$b$bБольшинство книг об этом ритуале хранятся в склепах Гробницы Теней. Возможно, там мы найдем ответы.$b$bВозможно, тебе удастся найти еще что-нибудь. Склеп расположен на ближайшем к алтарю холме.','Скопируйте рисунки с таблички династии Шэнь, таблички династии Вай и таблички династии Цян в Гробнице Теней.','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гробница Теней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по артефактам, найденным на алтаре, здесь готовились провести ритуал ловли душ.$b$bБольшинство книг об этом ритуале хранятся в склепах Гробницы Теней. Возможно, там мы найдем ответы.$b$bВозможно, тебе удастся найти еще что-нибудь. Склеп расположен на ближайшем к алтарю холме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скопируйте рисунки с таблички династии Шэнь, таблички династии Вай и таблички династии Цян в Гробнице Теней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30800,'Похитить останки их Властелина Грома','Нам остается только найти останки Властелина Грома раньше них. Он похоронен в Гробнице Завоевателей.$b$bОтыскать место погребения будет непросто, $n. Несомненно, его могилу защищают стражи, а внутри ждет масса неприятных сюрпризов.$b$bНо попасть внутрь – это еще не все, нужно еще найти сами останки.','Найдите нижнюю часть таблички Лэй Шэня и восстановите скрижаль грома.','Удалось выяснить, где спрятаны останки Властелина Грома?','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похитить останки их Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам остается только найти останки Властелина Грома раньше них. Он похоронен в Гробнице Завоевателей.$b$bОтыскать место погребения будет непросто, $n. Несомненно, его могилу защищают стражи, а внутри ждет масса неприятных сюрпризов.$b$bНо попасть внутрь – это еще не все, нужно еще найти сами останки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите нижнюю часть таблички Лэй Шэня и восстановите скрижаль грома.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось выяснить, где спрятаны останки Властелина Грома?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30801,'Уроки Истории','Властелин Грома был страшным императором, и никто не мог противостоять ему, пока на его стороне были зандалары. Если он вернется, эта земля утонет в насилии и агонии.$b$bНужно найти его останки и перенести их в безопасное место. Скрижаль грома поможет найти место погребения.','Прочитайте скрижаль грома в Гробнице Завоевателей.','Им придется перенести останки в безопасное место. Мы должны следовать за ними!','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки Истории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властелин Грома был страшным императором, и никто не мог противостоять ему, пока на его стороне были зандалары. Если он вернется, эта земля утонет в насилии и агонии.$b$bНужно найти его останки и перенести их в безопасное место. Скрижаль грома поможет найти место погребения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте скрижаль грома в Гробнице Завоевателей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Им придется перенести останки в безопасное место. Мы должны следовать за ними!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30802,'Погоня за грозой','Мы должны выяснить, куда они понесут останки Властелина Грома. В Долине Императоров воскрешение провести невозможно, им придется отойти подальше, в безопасное место.$b$bПохоже, выбраться отсюда тоже будет непросто.$b$bПробейся наружу и попробуй выяснить, где сейчас находятся останки.','Заберите кровавую карту с трупа зандаларского воина.','Удалось узнать, где они сейчас?','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погоня за грозой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны выяснить, куда они понесут останки Властелина Грома. В Долине Императоров воскрешение провести невозможно, им придется отойти подальше, в безопасное место.$b$bПохоже, выбраться отсюда тоже будет непросто.$b$bПробейся наружу и попробуй выяснить, где сейчас находятся останки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите кровавую карту с трупа зандаларского воина.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось узнать, где они сейчас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь Языком Ба-Шона, чтобы поговорить с хранителем истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30804,'Повелитель Ужаса','Больше я этого не вынесу. Моя покойная женушка всю душу в нашу ферму вложила.$b$bА потом яунголы явились, ходят тут, как хозяева, тоже мне. Я хорошо заплачу тебе, если ты сотрешь с мерзкой подлой морды этого типа нахальную улыбочку.','Убейте Повелителя Ужаса.','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.','Он предпочитает манервенность яка силе мушана.','Повелитель Ужаса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Больше я этого не вынесу. Моя покойная женушка всю душу в нашу ферму вложила.$b$bА потом яунголы явились, ходят тут, как хозяева, тоже мне. Я хорошо заплачу тебе, если ты сотрешь с мерзкой подлой морды этого типа нахальную улыбочку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Повелителя Ужаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лао Мускусной Лапой на якомойке "Лао и сын", что на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он предпочитает манервенность яка силе мушана.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель Ужаса',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30805,'Правосудие','Наемники напали на нас, ограбили, а потом ушли.\r\n\r\nОстался один. Он проткнул насквозь тех, кто выжил. Просто так, для смеха!\r\n\r\nОтомсти за погибших. Может, весть о смерти наемников вселит в меня силы, и я смогу жить дальше.\r\n\r\nОни расположились к западу отсюда.','Убейте капитана Живореза и 6 черногривов-наемников.','Да, их больше нет. Я чувствую, как ко мне возвращаются силы. Скоро я смогу вернуться в деревню.','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.','Командир черногривов-наемников.','Капитан Живорез') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правосудие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наемники напали на нас, ограбили, а потом ушли.\r\n\r\nОстался один. Он проткнул насквозь тех, кто выжил. Просто так, для смеха!\r\n\r\nОтомсти за погибших. Может, весть о смерти наемников вселит в меня силы, и я смогу жить дальше.\r\n\r\nОни расположились к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана Живореза и 6 черногривов-наемников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, их больше нет. Я чувствую, как ко мне возвращаются силы. Скоро я смогу вернуться в деревню.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Командир черногривов-наемников.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан Живорез',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30806,'Запах жизни','Найдите прозрачный панцирь голубого краба и 8 украденных пандаренских специй.','Прекрасно, прекрасно. Не очень-то приятно хоронить друзей, но раз уж приходится... Они заслужили достойную церемонию.','Что это за запах? Неужели ингредиенты для благовония Жизни? Или... просто тебе пора помыться.','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах жизни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите прозрачный панцирь голубого краба и 8 украденных пандаренских специй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, прекрасно. Не очень-то приятно хоронить друзей, но раз уж приходится... Они заслужили достойную церемонию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это за запах? Неужели ингредиенты для благовония Жизни? Или... просто тебе пора помыться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30807,'К водопадам во имя павших','Я должен достойно похоронить своих друзей.\r\n\r\nНо нам никогда не приходилось погребать сразу столько тел, мне будет не под силу собрать нужные материалы.\r\n\r\nПрошу тебя, пройди по дороге на юг до озер у подножия гор. Водопады на озерах до блеска шлифуют камни, и из них можно сделать надгробия.','Соберите 3 камня, отполированных водопадами.','Хорошо. Благодарю тебя. Теперь я смогу достойно похоронить своих товарищей.','Тебе удалось найти камни?','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К водопадам во имя павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должен достойно похоронить своих друзей.\r\n\r\nНо нам никогда не приходилось погребать сразу столько тел, мне будет не под силу собрать нужные материалы.\r\n\r\nПрошу тебя, пройди по дороге на юг до озер у подножия гор. Водопады на озерах до блеска шлифуют камни, и из них можно сделать надгробия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 камня, отполированных водопадами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Благодарю тебя. Теперь я смогу достойно похоронить своих товарищей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти камни?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мудрецу Ляо на берег Цзоучин на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30808,'Удача груммеля','Найдите 8 украденых удачек.','Ура! Наши удачки! Огромное тебе спасибо! Тебя ждет удача, друг груммелей!','Удачка приносит много удачи. Яунголы не умеют ими пользоваться, но могут и научиться.','Поговорите со Счастливчиком Серебриком на базаре груммелей на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удача груммеля',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 украденых удачек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура! Наши удачки! Огромное тебе спасибо! Тебя ждет удача, друг груммелей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удачка приносит много удачи. Яунголы не умеют ими пользоваться, но могут и научиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Счастливчиком Серебриком на базаре груммелей на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30814,'Первый шаг','<Лорд Тажань пронзает тебя взглядом.>$B$BПоследняя битва оставила на тебе свой след, |3-6($c).$B$BЭто хорошо. На передовой нам нужны такие закаленные воины, как ты.$B$BМы заняли неплохой плацдарм, но яунголы стремятся отбить его.$B$BХочешь показать, чего ты стоишь? Иди к подножию холма и покажи этим яунголам, что мы не отступим.','Убейте 8 осулов-погромщиков.','Хорошо. Я вижу, чего ты стоишь.$B$BНадеюсь, я смогу рассчитывать на твои таланты, когда придет время.','Вернитесь к Тажаню Чжу на укрепления Лун-Ин в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый шаг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Лорд Тажань пронзает тебя взглядом.>$B$BПоследняя битва оставила на тебе свой след, |3-6($c).$B$BЭто хорошо. На передовой нам нужны такие закаленные воины, как ты.$B$BМы заняли неплохой плацдарм, но яунголы стремятся отбить его.$B$BХочешь показать, чего ты стоишь? Иди к подножию холма и покажи этим яунголам, что мы не отступим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 осулов-погромщиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Я вижу, чего ты стоишь.$B$BНадеюсь, я смогу рассчитывать на твои таланты, когда придет время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на укрепления Лун-Ин в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30815,'Моя смерть','Я решил вытащить это копье из бока.$b$bДля этого мне нужна твоя помощь. Твои руки крепче моих.','Вытащите копье из Орбисса.','Вытащив это копье, я, без сомнения, обрек себя на смерть.$B$BМеня это не пугает.$B$BЛучше умереть, чем носить в себе оружие врага.','Поговорите с Орбиссом в Нижних Камышовых топях в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Моя смерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я решил вытащить это копье из бока.$b$bДля этого мне нужна твоя помощь. Твои руки крепче моих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вытащите копье из Орбисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вытащив это копье, я, без сомнения, обрек себя на смерть.$B$BМеня это не пугает.$B$BЛучше умереть, чем носить в себе оружие врага.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Орбиссом в Нижних Камышовых топях в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30816,'Проверка','Когда пришли тролли, с ними были наемники, их дружки... Я видел, как они пошли дальше, к лагерю рыбаков, на северо-запад. Там живет мой двоюродный брат, он целитель. Ты можешь проверить, все ли в порядке с ним и с его деревней?','Проведайте мудреца Ляо на побережье Цзоучин на вершине Кунь-Лай.','Ох... Брат беспокоится не зря... Плохо мне...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проверка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда пришли тролли, с ними были наемники, их дружки... Я видел, как они пошли дальше, к лагерю рыбаков, на северо-запад. Там живет мой двоюродный брат, он целитель. Ты можешь проверить, все ли в порядке с ним и с его деревней?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведайте мудреца Ляо на побережье Цзоучин на вершине Кунь-Лай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох... Брат беспокоится не зря... Плохо мне...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30817,'Исцеление Шэнь-Цзынь Су','Вот к чему приводит подобное безрассудство. Как ему вообще могло прийти такое в голову?$b$bЛадно, на разговоры у нас нет времени. Нужно действовать, чтобы спасти Шэнь-Цзынь Су.$b$bНайди всех лекарей, каких только сможешь! Спаси их, освободи – делай все, что понадобится, лишь бы они оказались здесь.$b$bЗащищай лекарей любой ценой!','Защищайте лекарей, пока они исцеляют рану Шэнь-Цзынь Су.','Поговорите с Аисой Воспевающей Облака на месте падения "Небесного огня"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление Шэнь-Цзынь Су',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот к чему приводит подобное безрассудство. Как ему вообще могло прийти такое в голову?$b$bЛадно, на разговоры у нас нет времени. Нужно действовать, чтобы спасти Шэнь-Цзынь Су.$b$bНайди всех лекарей, каких только сможешь! Спаси их, освободи – делай все, что понадобится, лишь бы они оказались здесь.$b$bЗащищай лекарей любой ценой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте лекарей, пока они исцеляют рану Шэнь-Цзынь Су.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аисой Воспевающей Облака на месте падения "Небесного огня"',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30818,'Новая судьба','$n, я рада, что план сработал, мы были на волоске от гибели. Если бы не ты, мы бы уже лежали на дне океана вместе с Шэнь-Цзынь Су. Не думаю, что когда-нибудь смогу простить Цзи то, что он вел себя так необдуманно.$b$bУ нас будет много времени на размышления, но сейчас нам необходимо вернуться в Храм Пяти Рассветов. Мы должны сообщить там, что Шэнь-Цзынь Су спасен, и заняться судьбой наших новых союзников.','Вернитесь в Храм Пяти Рассветов. Вы можете добраться туда на повозке, ожидающей вас у места падения "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая судьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я рада, что план сработал, мы были на волоске от гибели. Если бы не ты, мы бы уже лежали на дне океана вместе с Шэнь-Цзынь Су. Не думаю, что когда-нибудь смогу простить Цзи то, что он вел себя так необдуманно.$b$bУ нас будет много времени на размышления, но сейчас нам необходимо вернуться в Храм Пяти Рассветов. Мы должны сообщить там, что Шэнь-Цзынь Су спасен, и заняться судьбой наших новых союзников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Храм Пяти Рассветов. Вы можете добраться туда на повозке, ожидающей вас у места падения "Небесного огня".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30819,'Подготовка к погребению','Благодарю тебя. После всего, что пришлось перенести, удача все же улыбнулась и послала нам тебя.\r\n\r\nТеперь мои друзья отомщены, и я могу достойно похоронить их. Я подготовлю все необходимое для церемонии, после чего мы встретимся на кладбище.\r\n\r\nА пока не затруднит ли тебя вернуться к моему брату и попросить его созвать на похороны всех селян?','Вернитесь к Ли Хаю и расскажите ему о похоронах.','Да... Это просто трагедия. Мы все придем на кладбище, чтобы проводить умерших в мир иной.','Вернитесь к Ли Хаю в деревню Цзоучин и расскажите ему о похоронах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к погребению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю тебя. После всего, что пришлось перенести, удача все же улыбнулась и послала нам тебя.\r\n\r\nТеперь мои друзья отомщены, и я могу достойно похоронить их. Я подготовлю все необходимое для церемонии, после чего мы встретимся на кладбище.\r\n\r\nА пока не затруднит ли тебя вернуться к моему брату и попросить его созвать на похороны всех селян?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Ли Хаю и расскажите ему о похоронах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Это просто трагедия. Мы все придем на кладбище, чтобы проводить умерших в мир иной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ли Хаю в деревню Цзоучин и расскажите ему о похоронах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30820,'Похороны','Я соберу всех жителей, и мы придем на похороны.\r\n\r\nТы так много $gсделал:сделала;, чтобы души наших друзей обрели покой, что мы просим именно тебя зажечь благовония жизни и проводить их души в мир иной.','Посетите похороны и зажгите благовония жизни.','Начнем же погребальную церемонию.','Воскурите благовония, чтобы почтить мертвых.','Поговорите с мудрецом Ляо на кладбище провинции Цзоучин, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я соберу всех жителей, и мы придем на похороны.\r\n\r\nТы так много $gсделал:сделала;, чтобы души наших друзей обрели покой, что мы просим именно тебя зажечь благовония жизни и проводить их души в мир иной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите похороны и зажгите благовония жизни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Начнем же погребальную церемонию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Воскурите благовония, чтобы почтить мертвых.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мудрецом Ляо на кладбище провинции Цзоучин, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30821,'Джутовая резня','Самое время отправиться на "прогулку" с Коту Кон.$B$BМы сварили ей два горшка кафы, у нее энергии – хоть отбавляй!','Ха-ха! Как кричали эти обезьяны! Слышно было даже отсюда!$B$B<Колючник поворачивается к Коту Кон.>$B$BКто тут у нас умница и красавица? Ты!','Вернитесь к племяннику Берберри в лагерь Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джутовая резня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самое время отправиться на "прогулку" с Коту Кон.$B$BМы сварили ей два горшка кафы, у нее энергии – хоть отбавляй!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Как кричали эти обезьяны! Слышно было даже отсюда!$B$B<Колючник поворачивается к Коту Кон.>$B$BКто тут у нас умница и красавица? Ты!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к племяннику Берберри в лагерь Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30823,'Взять козла за рога','Мой двоюродный брат в лагере Коту сделал глупость. Очень большую глупость.$B$BЕму было слишком лень вырезать семечки из ягод кафы вручную, и тут он заметил что козел, съевший кафу, "возвращает" семена... через день или около того.$B$BОн скормил всю кафу козлам на пике Коту, и теперь они посходили с ума! Они бодают все, что движется.$B$BНа пике Коту груммелям раньше было безопасно собирать кафу. Теперь это не так. Не с этими бешеными козлами. Ты поможешь?','Убейте 12 одурманенных кафой горных козлов на пике Коту.','Спасибо, что исправил мою ошибку, друг! Пусть это будет тебе уроком: не корми козлов.','Поговорите с кузеном Шерстомехом в лагере Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взять козла за рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой двоюродный брат в лагере Коту сделал глупость. Очень большую глупость.$B$BЕму было слишком лень вырезать семечки из ягод кафы вручную, и тут он заметил что козел, съевший кафу, "возвращает" семена... через день или около того.$B$BОн скормил всю кафу козлам на пике Коту, и теперь они посходили с ума! Они бодают все, что движется.$B$BНа пике Коту груммелям раньше было безопасно собирать кафу. Теперь это не так. Не с этими бешеными козлами. Ты поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 одурманенных кафой горных козлов на пике Коту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что исправил мою ошибку, друг! Пусть это будет тебе уроком: не корми козлов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кузеном Шерстомехом в лагере Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30824,'Изысканная кафа','Это была сумасшедшая идея: с одной стороны в козла попадают ягоды кафы, а с другой раз – и уже семена.$B$BКафа\'кота уже редкость и стоит уйму денег, но изобретение моего родича, кафа-гута – это изысканно!$B$BНо все кончено. Дядя Остробоб расстроен, а на пике царит беспорядок. Теперь надо только собрать остатки кафа-гуты и больше так не делать.$B$BЯ не прошу тебя собирать ее, это грязная работенка, герои такое не делают. Просто отметь ее, и мы все соберем, когда на горе снова будет безопасно.','Я слышал, что искатель приключений отмечает скопления кафа-гуты там, наверху. Так себе занятие для кого-то вроде тебя, но я ценю это.$B$BЯ скоро поднимусь в горы и... соберу их.$B$B<Кузен Шерстомех обматывает руки полосками льна.>$B$BНе верится, что я считал это хорошей идеей.','Поговорите с кузеном Шерстомехом в лагере Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изысканная кафа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это была сумасшедшая идея: с одной стороны в козла попадают ягоды кафы, а с другой раз – и уже семена.$B$BКафа\'кота уже редкость и стоит уйму денег, но изобретение моего родича, кафа-гута – это изысканно!$B$BНо все кончено. Дядя Остробоб расстроен, а на пике царит беспорядок. Теперь надо только собрать остатки кафа-гуты и больше так не делать.$B$BЯ не прошу тебя собирать ее, это грязная работенка, герои такое не делают. Просто отметь ее, и мы все соберем, когда на горе снова будет безопасно.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал, что искатель приключений отмечает скопления кафа-гуты там, наверху. Так себе занятие для кого-то вроде тебя, но я ценю это.$B$BЯ скоро поднимусь в горы и... соберу их.$B$B<Кузен Шерстомех обматывает руки полосками льна.>$B$BНе верится, что я считал это хорошей идеей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кузеном Шерстомехом в лагере Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30825,'Смесь кафы','Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее, то козлы кусты объедят, то йети все перетаскают.$B$BДядя Остробоб хорошо заплатит тебе, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.','Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смесь кафы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пик Коту знаменит своей кафой – больше на такой высоте ничего не растет.$B$BГруммели торгуют кафой и неплохо наживаются, но теперь это стало опасно благодаря моему родственничку. Он там все на уши поставил, хотел кафой разжиться.$B$BКафа\'коту найти все сложнее, то козлы кусты объедят, то йети все перетаскают.$B$BДядя Остробоб хорошо заплатит тебе, если ты принесешь с пика Коту ягоды кафы.$B$BВот такие они, эти ягоды. Съешь, и сразу узнаешь силу кафы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 ягод кафы на пике Коту. Кусты кафы растут на горных склонах, а в пещерах йети можно найти запасы ягод.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30826,'Расхлебывать кафу','Да, на пике Коту водятся йети. Обычно они мирные, едят козлов.$B$BА потом этот балбес Шерстомех скормил козлам кафу, а йети их сожрали.$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.','Убейте 5 одурманенных кафой йети в пещерах на пике Коту.','Здорово! Долгопой прислал яка сообщить, что ты поможешь нам разобраться с йети.$B$BИ как тебя там не разорвали только! Йети и так-то сильны, а уж на что похожи чокнутые любители кафы, даже думать боюсь. Вот это храбрость. А может, везение. Или идиотизм.$B$BИли все сразу.','Поговорите с дядей Остробобом в лагере Коту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расхлебывать кафу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, на пике Коту водятся йети. Обычно они мирные, едят козлов.$B$BА потом этот балбес Шерстомех скормил козлам кафу, а йети их сожрали.$b$bТеперь они просто бешеные, и, похоже, никогда не спят. Пристрастились к кафе, видать.$b$bВот-вот вылезут из пещер. Пойдут сами кафу искать...$b$bВот это будет беда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 одурманенных кафой йети в пещерах на пике Коту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово! Долгопой прислал яка сообщить, что ты поможешь нам разобраться с йети.$B$BИ как тебя там не разорвали только! Йети и так-то сильны, а уж на что похожи чокнутые любители кафы, даже думать боюсь. Вот это храбрость. А может, везение. Или идиотизм.$B$BИли все сразу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с дядей Остробобом в лагере Коту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30828,'Очищение болота','В болото проникает темное вещество, такое же, как было в Мэй.\r\n\r\nЯ пойду с тобой. Укажешь мне источники порчи, которые надо устранить.\r\n\r\nТебе придется сражаться с тем, что появится оттуда, и защищать меня, пока идет ритуал.','Озеро очищено?','Поговорите с говорящим с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение болота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В болото проникает темное вещество, такое же, как было в Мэй.\r\n\r\nЯ пойду с тобой. Укажешь мне источники порчи, которые надо устранить.\r\n\r\nТебе придется сражаться с тем, что появится оттуда, и защищать меня, пока идет ритуал.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Озеро очищено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящим с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30829,'Язык Ба-Шона','Спасибо, что $gпришел:пришла;, $n. Мне пришлось говорить намеками, потому что я опасаюсь, что могу узнают о моей работе.$B$BОни ищут что-то в долине... расхищают гробницы своих старых королей в поисках могущественных реликвий.$B$BМне не удалось долго понаблюдать за ними – пришлось бежать. Однако и мне удалось утащить один артефакт.$B$BЯзык Ба-Шона позволит нам безопасно общаться на больших расстояниях, но сначала мне надо связать его с собой.$B$BНачнем, когда ты будешь $gготов:готова;.','Помогите хранителю истории Чо провести ритуал Связывания Ба-Шона.','Поговорите с хранителем истории Чо в лагере Искателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Язык Ба-Шона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gпришел:пришла;, $n. Мне пришлось говорить намеками, потому что я опасаюсь, что могу узнают о моей работе.$B$BОни ищут что-то в долине... расхищают гробницы своих старых королей в поисках могущественных реликвий.$B$BМне не удалось долго понаблюдать за ними – пришлось бежать. Однако и мне удалось утащить один артефакт.$B$BЯзык Ба-Шона позволит нам безопасно общаться на больших расстояниях, но сначала мне надо связать его с собой.$B$BНачнем, когда ты будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите хранителю истории Чо провести ритуал Связывания Ба-Шона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в лагере Искателя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30834,'Отец и сын: снова вместе','Они выжили? Мой отец жив!\r\n\r\nЯ думал, мы все умрем в этом ужасном болоте от руки этих безумных цзинь-юй.\r\n\r\nЯ сам найду дорогу назад, встретимся в лагере.','Вернитесь к говорящему с водой из племени Чернильной Жабры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отец и сын: снова вместе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они выжили? Мой отец жив!\r\n\r\nЯ думал, мы все умрем в этом ужасном болоте от руки этих безумных цзинь-юй.\r\n\r\nЯ сам найду дорогу назад, встретимся в лагере.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящему с водой из племени Чернильной Жабры.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30854,'Слежка для Лха-По') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слежка для Лха-По',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30855,'Падение Шай Ху','Я слышу голос болота, ибо оно было очищено.\r\n\r\nНо эту страницу в истории моего народа не перелистнуть, пока жив Шай Ху.\r\n\r\nОн перебрался на остров в центре болота, оскверняя святые места.\r\n\r\nОстерегайся его, ведь он силен. Но после того, что мы уже совершили, я уверен: мы сильнее.','Вернитесь на юго-восточную окраину Озера Чернильной Жабры на вершине Кунь-Лай и побеседуйте с Говорящим с водой Гожаем.','Губитель цзинь-юй Чернильной Жабры. Чтобы спасти их, нужно убить его.','Шай Ху') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Шай Ху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу голос болота, ибо оно было очищено.\r\n\r\nНо эту страницу в истории моего народа не перелистнуть, пока жив Шай Ху.\r\n\r\nОн перебрался на остров в центре болота, оскверняя святые места.\r\n\r\nОстерегайся его, ведь он силен. Но после того, что мы уже совершили, я уверен: мы сильнее.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на юго-восточную окраину Озера Чернильной Жабры на вершине Кунь-Лай и побеседуйте с Говорящим с водой Гожаем.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Губитель цзинь-юй Чернильной Жабры. Чтобы спасти их, нужно убить его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шай Ху',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30879,'Первый тур: хмелевар Чани','Добро пожаловать на мой турнир чемпионов, претендент! Сегодня мы испытаем силу величайших героев Пандарии.$b$bТвой первый противник ждет в восточном павильоне. Победи ее, и сможешь перейти к следующему этапу.$b$bСражайся с силой, помни о чести.','Победите хмелевара Чани.','Отлично, претендент.','Поговорите с Сюэнем в Восточной беседке на вершине Кунь-Лай.','Она только стала хмелеваром, и напитки у нее ужасно горькие.','Хмелевар Чани') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый тур: хмелевар Чани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на мой турнир чемпионов, претендент! Сегодня мы испытаем силу величайших героев Пандарии.$b$bТвой первый противник ждет в восточном павильоне. Победи ее, и сможешь перейти к следующему этапу.$b$bСражайся с силой, помни о чести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите хмелевара Чани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, претендент.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем в Восточной беседке на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Она только стала хмелеваром, и напитки у нее ужасно горькие.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хмелевар Чани',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30880,'Первый раунд: уличный боец.','Добро пожаловать на мой турнир чемпионов, претендент! Сегодня мы испытаем силу величайших героев Пандарии.$b$bТвой первый противник ждет в восточном павильоне. Победи ее и можешь перейти к следующему этапу.$b$bСражайся с силой, помни о чести.','Победите уличного бойца.','Отлично, претендент.','Поговорите с Сюэнем в Восточной беседке на вершине Кунь-Лай.','Знаменитый монах защищает дороги от опасностей Пандарии.','Уличный боец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый раунд: уличный боец.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на мой турнир чемпионов, претендент! Сегодня мы испытаем силу величайших героев Пандарии.$b$bТвой первый противник ждет в восточном павильоне. Победи ее и можешь перейти к следующему этапу.$b$bСражайся с силой, помни о чести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите уличного бойца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, претендент.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем в Восточной беседке на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Знаменитый монах защищает дороги от опасностей Пандарии.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Уличный боец',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30881,'Второй раунд: Мудрый Асе и Кен-Кен.','Возможно, ты знаешь своих следующих противников. Они слишком яростно спорили друг с другом, когда пришли ко мне, и я решил, что они должны сражаться бок о бок.$b$bТак они познают силу дружбы, а я, может, немного развлекусь.$b$bСтупай на северо-восточную арену и встреться лицом к лицу с цзинь-юй и хозеном.$b$bНе давай им спуску, они должны научиться работать вместе.','Победите Мудрого Асе и Кен-Кена.','Прискорбно, что эти двое еще не усвоили урок. Впрочем, неважно. Со временем к ним придет мудрость, я уверен.$B$BПоздравляю с победой!','Поговорите с Сюэнем на северо-восточной арене на вершине Кунь-Лай.','Эти два товарища-путешественника все время друг друга обзывают.','Мудрый Асе и Кен-Кен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй раунд: Мудрый Асе и Кен-Кен.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, ты знаешь своих следующих противников. Они слишком яростно спорили друг с другом, когда пришли ко мне, и я решил, что они должны сражаться бок о бок.$b$bТак они познают силу дружбы, а я, может, немного развлекусь.$b$bСтупай на северо-восточную арену и встреться лицом к лицу с цзинь-юй и хозеном.$b$bНе давай им спуску, они должны научиться работать вместе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мудрого Асе и Кен-Кена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прискорбно, что эти двое еще не усвоили урок. Впрочем, неважно. Со временем к ним придет мудрость, я уверен.$B$BПоздравляю с победой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем на северо-восточной арене на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эти два товарища-путешественника все время друг друга обзывают.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мудрый Асе и Кен-Кен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30882,'Второй раунд: Кан Ежевичный Посох','Твой следующий соперник – Ежевичный Посох. Сила у этого рода в крови. Я помню, как целое столетие чемпионами становились только представители этой семьи.$b$bО! Нет-нет, я ни на что не намекаю, $gмаленький:маленькая:r; |3-6($r).$b$bОтправляйся на восточную арену, что к северу отсюда, и встреться со своим юным соперником. Узнай, можно ли получить силу в наследство или нужно набрать ее самому.','Победите Кана Ежевичного Посоха.','Поколение за поколением члены семьи Ежевичный Посох становились чемпионами. Думаю, этот пандарен тоже рано или поздно получит титул.','Поговорите с Сюэнем на северо-восточной арене на вершине Кунь-Лай.','Семья Ежевичный Посох давно устраивает эти соревнования.','Кан Ежевичный Посох') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй раунд: Кан Ежевичный Посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой следующий соперник – Ежевичный Посох. Сила у этого рода в крови. Я помню, как целое столетие чемпионами становились только представители этой семьи.$b$bО! Нет-нет, я ни на что не намекаю, $gмаленький:маленькая:r; |3-6($r).$b$bОтправляйся на восточную арену, что к северу отсюда, и встреться со своим юным соперником. Узнай, можно ли получить силу в наследство или нужно набрать ее самому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Кана Ежевичного Посоха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поколение за поколением члены семьи Ежевичный Посох становились чемпионами. Думаю, этот пандарен тоже рано или поздно получит титул.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем на северо-восточной арене на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Семья Ежевичный Посох давно устраивает эти соревнования.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кан Ежевичный Посох',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30883,'Третий раунд: Борец','Твой следующий соперник – мой личный фаворит. Он берет грубой силой и несокрушимой волей.$B$BА еще он носит маску.$B$BБой состоится на западной арене. Готовься, и удачи тебе.','Победите Борца.','Достойно, боец. У тебя был сильный соперник.','Поговорите с Сюэнем на западной арене на Вершине Кунь-Лай.','Он никогда не снимает маску.','Борец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Третий раунд: Борец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой следующий соперник – мой личный фаворит. Он берет грубой силой и несокрушимой волей.$B$BА еще он носит маску.$B$BБой состоится на западной арене. Готовься, и удачи тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Борца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Достойно, боец. У тебя был сильный соперник.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем на западной арене на Вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он никогда не снимает маску.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Борец',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30884,'За заставой','Пока меня не было в Кунь-Лай, эта застава слишком надолго осталась без присмотра и без достаточного количества припасов. Нам нужно снова все здесь наладить, прежде чем мы пойдем по следу Ша Ненависти.$B$BТаоши – моя правая рука. Я послал ее на север расследовать слухи о богомолах, которые каким-то образом прорвались сквозь линию наших войск. Мне нужен кто-то, кому я могу доверять и кто поехал бы туда и поработал с ней на пару, заделывая все бреши в нашей обороне.$B$BЕсли то, что мне докладывали о тебе, правда, ты в самый раз подойдешь для этого дела, не так ли, |3-6($c)?','Встретьтесь с Таоши в Логове Сыроземья.','Из тебя, похоже, выйдет толк. Тажань знает, кого посылать. Я это ценю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За заставой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока меня не было в Кунь-Лай, эта застава слишком надолго осталась без присмотра и без достаточного количества припасов. Нам нужно снова все здесь наладить, прежде чем мы пойдем по следу Ша Ненависти.$B$BТаоши – моя правая рука. Я послал ее на север расследовать слухи о богомолах, которые каким-то образом прорвались сквозь линию наших войск. Мне нужен кто-то, кому я могу доверять и кто поехал бы туда и поработал с ней на пару, заделывая все бреши в нашей обороне.$B$BЕсли то, что мне докладывали о тебе, правда, ты в самый раз подойдешь для этого дела, не так ли, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Таоши в Логове Сыроземья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из тебя, похоже, выйдет толк. Тажань знает, кого посылать. Я это ценю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30885,'Третий раунд: Мастер Бум-Бум','Твой следующий соперник нашел свою силу на берегу. Это был ящик с динамитом.$b$bЗаметим, что полученная сила может быть пострашнее силы врожденной.$b$bБой состоится на Западной арене. Готовься.','Победите мастера Бум-Бума.','Достойно, боец. У тебя был сильный соперник.','Поговорите с Сюэнем на западной арене на вершине Кунь-Лай.','Мастер Бум-Бум') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Третий раунд: Мастер Бум-Бум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой следующий соперник нашел свою силу на берегу. Это был ящик с динамитом.$b$bЗаметим, что полученная сила может быть пострашнее силы врожденной.$b$bБой состоится на Западной арене. Готовься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите мастера Бум-Бума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Достойно, боец. У тебя был сильный соперник.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем на западной арене на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мастер Бум-Бум',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30886,'Example Pandaren Race Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Example Pandaren Race Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30887,'Непрошеные гости','Там внизу, под стеной, передовой отряд богомолов. Задача Заставы Гао-Жаня – не пропускать их в восточные Танлунские степи. Если позволить им пройти на север за укрепления, мы потеряем эти земли.$B$BДавай избавимся от них. Я тебе помогу.','Убить 12 крик\'тиков-лазутчиков вместе с Таоши.','Вот где они пробираются сюда – через восточный проход.','Поговорите с Таоши на Пути Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непрошеные гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там внизу, под стеной, передовой отряд богомолов. Задача Заставы Гао-Жаня – не пропускать их в восточные Танлунские степи. Если позволить им пройти на север за укрепления, мы потеряем эти земли.$B$BДавай избавимся от них. Я тебе помогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убить 12 крик\'тиков-лазутчиков вместе с Таоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот где они пробираются сюда – через восточный проход.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таоши на Пути Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30888,'Брешь в обороне','Обычно хватает нескольких разведчиков, чтобы удерживать этот проход. Большая часть территории видна со стены, так что лучники могут осыпать стрелами любые отряды богомолов, которые попытаются пробиться здесь. Проблема в том, что сейчас большая часть лучников занята в схватке у ворот.$B$BВозьми эту сигнальную ракету – она позволит определить, где находятся богомолы, которые пытаются пробраться через восточный проход мимо нашего поредевшего дозора. Убей всех, кого найдешь. Нельзя позволить им открыть путь для полчищ богомолов, которые двинутся дальше в степи.','Используйте сигнальные ракеты Шадо-Пан, чтобы уничтожить 10 крик\'тиков-помечателей.','Вернитесь к Таоши на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брешь в обороне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно хватает нескольких разведчиков, чтобы удерживать этот проход. Большая часть территории видна со стены, так что лучники могут осыпать стрелами любые отряды богомолов, которые попытаются пробиться здесь. Проблема в том, что сейчас большая часть лучников занята в схватке у ворот.$B$BВозьми эту сигнальную ракету – она позволит определить, где находятся богомолы, которые пытаются пробраться через восточный проход мимо нашего поредевшего дозора. Убей всех, кого найдешь. Нельзя позволить им открыть путь для полчищ богомолов, которые двинутся дальше в степи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сигнальные ракеты Шадо-Пан, чтобы уничтожить 10 крик\'тиков-помечателей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таоши на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30889,'Установка ловушек','Приятно тебя видеть, |3-6($c). У нас установлены ловушки по всему проходу, чтобы ловить рыскающих повсюду богомолов, но их последнее время было так много, что почти все ловушки уже сработали.$B$BТаоши говорит, что ты сможешь помочь снова установить некоторые из них, пока ты здесь. Это правда?','Заново зарядите 8 шипастых ловушек Шадо-Пан.','Вернитесь к дозорному Мао на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Установка ловушек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно тебя видеть, |3-6($c). У нас установлены ловушки по всему проходу, чтобы ловить рыскающих повсюду богомолов, но их последнее время было так много, что почти все ловушки уже сработали.$B$BТаоши говорит, что ты сможешь помочь снова установить некоторые из них, пока ты здесь. Это правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заново зарядите 8 шипастых ловушек Шадо-Пан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Мао на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30890,'Бесконечный дозор','Мне доложили, что наши бойцы на Пути Неверного Шага уже дольше двух дней в дозоре. Неудивительно, что богомолы проскальзывают мимо них незамеченными: двое суток на ногах подкосят любого дозорного.$B$BОтправляйся к солдатам и передай, пусть немедленно возвращаются на заставу, чтобы отдохнуть и пополнить припасы. Я найду кого-нибудь им на замену.','Доставьте приказ о возвращении разведчику Вэй-Чиню, разведчице Лун, разведчице Ин и разведчику Цзай-Ганю.','Спасибо тебе. В ближайшее время я отправлю на эти посты новых разведчиков.','Вернитесь к Таоши на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечный дозор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне доложили, что наши бойцы на Пути Неверного Шага уже дольше двух дней в дозоре. Неудивительно, что богомолы проскальзывают мимо них незамеченными: двое суток на ногах подкосят любого дозорного.$B$BОтправляйся к солдатам и передай, пусть немедленно возвращаются на заставу, чтобы отдохнуть и пополнить припасы. Я найду кого-нибудь им на замену.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте приказ о возвращении разведчику Вэй-Чиню, разведчице Лун, разведчице Ин и разведчику Цзай-Ганю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе. В ближайшее время я отправлю на эти посты новых разведчиков.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таоши на Путь Неверного Шага, что к востоку от Заставы Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30891,'Лечение войска','О, $gновенький:новенькая;! Приятно познакомиться. Я – Септи. Поддерживаю здоровье бойцов Шадо-Пан.$B$BУ богомолов есть яд, который проникает под кожу и попадает в кровь. Он приводит к медленной мучительной смерти, если не применить противоядие.$B$BМне нужна пыльца цветков лилового лимона. Ближайшее место, где их можно найти, – это у Логова Сыроземья к северу от заставы. Если окажешься в тех краях, сможешь мне принести этих цветков?','Соберите 10 цветков лилового лимона.','Если ее правильно обработать, эта пыльца способна вытянуть весь яд без серьезных последствий.','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лечение войска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $gновенький:новенькая;! Приятно познакомиться. Я – Септи. Поддерживаю здоровье бойцов Шадо-Пан.$B$BУ богомолов есть яд, который проникает под кожу и попадает в кровь. Он приводит к медленной мучительной смерти, если не применить противоядие.$B$BМне нужна пыльца цветков лилового лимона. Ближайшее место, где их можно найти, – это у Логова Сыроземья к северу от заставы. Если окажешься в тех краях, сможешь мне принести этих цветков?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 цветков лилового лимона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ее правильно обработать, эта пыльца способна вытянуть весь яд без серьезных последствий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30892,'Снова на ногах','$n, мне снова пригодилась бы твоя помощь. Наши воины на южной стороне сражаются из последних сил, и многие из них отравлены ядом богомолов.$B$BНам нужны еще помощники, чтобы было кому позаботиться о раненых. У меня готовы несколько перевязок с принесенными тобой травами, а если ты умеешь исцелять, эффект будет еще сильнее.$B$BПожалуйста, $n, поставь наших воинов на ноги, чтобы они могли вернуться сюда, в более безопасное место.','Исцелите 8 раненых черных стражей Гао-Жаня.','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова на ногах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне снова пригодилась бы твоя помощь. Наши воины на южной стороне сражаются из последних сил, и многие из них отравлены ядом богомолов.$B$BНам нужны еще помощники, чтобы было кому позаботиться о раненых. У меня готовы несколько перевязок с принесенными тобой травами, а если ты умеешь исцелять, эффект будет еще сильнее.$B$BПожалуйста, $n, поставь наших воинов на ноги, чтобы они могли вернуться сюда, в более безопасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите 8 раненых черных стражей Гао-Жаня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30893,'Нескончаемый рой','Убейте 12 крик\'тиков у Заставы Гао-Жаня.','Бойцы заставы начинают тебя уважать. Они видят, что ты умеешь драться.','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нескончаемый рой',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 крик\'тиков у Заставы Гао-Жаня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бойцы заставы начинают тебя уважать. Они видят, что ты умеешь драться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30894,'Копание в останках','У меня есть еще одно дело для тебя, $n, хоть оно и не очень-то веселое. Мне очень нужно узнать все о яде богомолов, но для этого необходимо больше конкретной информации и фактов.$B$BПока будешь на поле битвы к югу отсюда, собери, пожалуйста, несколько конечностей богомолов, чтобы у меня была возможность исследовать их неповрежденные железы.','Соберите 20 конечностей крик\'тиков.','Надеюсь, что найду устойчивое противоядие от яда богомолов, чтобы обезопасить наших воинов. Возможно, мне потребуется некоторое время, чтобы во всем разобраться.','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Копание в останках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть еще одно дело для тебя, $n, хоть оно и не очень-то веселое. Мне очень нужно узнать все о яде богомолов, но для этого необходимо больше конкретной информации и фактов.$B$BПока будешь на поле битвы к югу отсюда, собери, пожалуйста, несколько конечностей богомолов, чтобы у меня была возможность исследовать их неповрежденные железы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 конечностей крик\'тиков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, что найду устойчивое противоядие от яда богомолов, чтобы обезопасить наших воинов. Возможно, мне потребуется некоторое время, чтобы во всем разобраться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к травнице Септи на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30895,'Импровизированные боеприпасы','У меня для тебя есть еще работа.$B$BУ пушек, на которые мы полагаемся в отражении самого сильного натиска богомолов, заканчиваются снаряды. Лагерные канониры изобрели взрывчатое вещество, которое можно делать из семян сферы, растущей на западном кряже.$B$BОни отправили пару новобранцев за ними несколько часов назад, и с тех пор мы о них не слышали. Я хочу послать туда кого-нибудь более толкового, чтобы это задание все-таки было выполнено.$B$BТы как, справишься?','Раздобыть 16 непрочных сфер ужаса из Янтарной топи.','Хорошо иметь |3-3(Охотник), на которого можно рассчитывать.','О, ты вернулся быстрее, чем я ожидал! Семена с тобой?','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Импровизированные боеприпасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня для тебя есть еще работа.$B$BУ пушек, на которые мы полагаемся в отражении самого сильного натиска богомолов, заканчиваются снаряды. Лагерные канониры изобрели взрывчатое вещество, которое можно делать из семян сферы, растущей на западном кряже.$B$BОни отправили пару новобранцев за ними несколько часов назад, и с тех пор мы о них не слышали. Я хочу послать туда кого-нибудь более толкового, чтобы это задание все-таки было выполнено.$B$BТы как, справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобыть 16 непрочных сфер ужаса из Янтарной топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо иметь |3-3(Охотник), на которого можно рассчитывать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, ты вернулся быстрее, чем я ожидал! Семена с тобой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30896,'Воры и возмутители спокойствия','Никак не получается поймать этих маленьких мерзавцев.$B$BУбей любого, кто тебе попадется. И внимательно следи за ценными вещами – они тащат все, что плохо лежит.','Убейте 10 встревоженных крапивников.','Вернитесь к новобранцу Фэну в Янтарную топь, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воры и возмутители спокойствия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никак не получается поймать этих маленьких мерзавцев.$B$BУбей любого, кто тебе попадется. И внимательно следи за ценными вещами – они тащат все, что плохо лежит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 встревоженных крапивников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Фэну в Янтарную топь, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30897,'Не в те руки','Раздобудьте меч новобранца Чао.','Вот предупреждала меня мама, что такое может случиться...','Вернитесь к новобранцу Чао в Янтарную топь, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не в те руки',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте меч новобранца Чао.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот предупреждала меня мама, что такое может случиться...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Чао в Янтарную топь, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30898,'Рой врагов','С тех пор, как ты $gушел:ушла;, богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.','Убейте 50 нападающих богомолов с помощью орудия "дракон".','Мы еще не закончили...','Поговорите с Таоши на заставе Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рой врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как ты $gушел:ушла;, богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 нападающих богомолов с помощью орудия "дракон".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы еще не закончили...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таоши на заставе Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30899,'В умелых руках','Доставьте колчан арбалетных болтов Шадо-Пан повелителю ястребов Нужуну.','На той стороне ущелья большое оживление... Готовится что-то серьезное.','Приближается очередная волна летунов. Готовься.','Принесите колчан арбалетных болтов повелителю ястребов Нужуну на Наблюдательный пункт, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В умелых руках',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте колчан арбалетных болтов Шадо-Пан повелителю ястребов Нужуну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На той стороне ущелья большое оживление... Готовится что-то серьезное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приближается очередная волна летунов. Готовься.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите колчан арбалетных болтов повелителю ястребов Нужуну на Наблюдательный пункт, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30900,'Кошмар Жутких пустошей','Уничтожьте Норвакесс, Кошмар Жутких пустошей.','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.','Норвакесс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кошмар Жутких пустошей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Норвакесс, Кошмар Жутких пустошей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на Заставу Гао-Жаня в Танлунских степях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Норвакесс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30901,'Вдоль южного фронта','Я направляюсь на запад с Таоши, чтобы собрать самых сильных бойцов для сражения с Ша Ненависти.$B$BМне бы хотелось, чтобы ты к нам $gприсоединился:присоединилась;.','Отправляйтесь с Тажанем Чжу и Таоши в Ложбину Тусклого Света.','Давай разберемся с этим, чтобы можно было добраться до моста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вдоль южного фронта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я направляюсь на запад с Таоши, чтобы собрать самых сильных бойцов для сражения с Ша Ненависти.$B$BМне бы хотелось, чтобы ты к нам $gприсоединился:присоединилась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь с Тажанем Чжу и Таоши в Ложбину Тусклого Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай разберемся с этим, чтобы можно было добраться до моста.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30902,'Четвертый раунд: Мастер Воздушный Мех','Отлично, боец. Тебе предстоит финальный раунд.$b$bТвоим последним соперником будет знаменитый повелитель ветра. Он много лет защищал своих людей и уже не раз становился чемпионом.$b$bБой состоится на главной арене.$b$bГотовься... и удачи тебе.','Победите Мастера Воздушный Мех.','Поздравляю, чемпион! Это твой день.','Поговорите с Сюэнем в храме Тигра на вершине Кунь-Лай.','Мэр Цветущей Зари','Мастер Воздушный Мех') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четвертый раунд: Мастер Воздушный Мех',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, боец. Тебе предстоит финальный раунд.$b$bТвоим последним соперником будет знаменитый повелитель ветра. Он много лет защищал своих людей и уже не раз становился чемпионом.$b$bБой состоится на главной арене.$b$bГотовься... и удачи тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мастера Воздушный Мех.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поздравляю, чемпион! Это твой день.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем в храме Тигра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мэр Цветущей Зари',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мастер Воздушный Мех',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (30907,'Четвертый раунд: П.У.Г.','Надвигается последний раунд. Я выбрал для тебя сразу трех соперников. Ты можешь счесть это нечестным... если сил у тебя маловато. А ведь это не так, верно?$b$bОтправляйся в главный храм, выходи на главную арену и сразись с тремя противниками. Докажи, что ты сильнее их всех вместе взятых.$b$bУдачи тебе, боец.','Победите Дамагисса, Хилисса и Танкисса.','Великолепно! Вот так бой!$B$BТебе по праву достается звание чемпиона на сегодняшнем состязании.$B$BНепременно возвращайся к нам и снова продемонстрируй свою силу.','Поговорите с Сюэнем в храме Тигра на вершине Кунь-Лай.','У каждого есть сила, которую они используют в бою.','Дамагисс, Хилисс и Танкисс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четвертый раунд: П.У.Г.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надвигается последний раунд. Я выбрал для тебя сразу трех соперников. Ты можешь счесть это нечестным... если сил у тебя маловато. А ведь это не так, верно?$b$bОтправляйся в главный храм, выходи на главную арену и сразись с тремя противниками. Докажи, что ты сильнее их всех вместе взятых.$b$bУдачи тебе, боец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дамагисса, Хилисса и Танкисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Вот так бой!$B$BТебе по праву достается звание чемпиона на сегодняшнем состязании.$B$BНепременно возвращайся к нам и снова продемонстрируй свою силу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем в храме Тигра на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У каждого есть сила, которую они используют в бою.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дамагисс, Хилисс и Танкисс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntargetname_loc8`) VALUES (30918,'Месть Хуэя','Мне стыдно просить тебя о еще одном одолжении, но я сделаю это ради жителей Зеленой Скалы... Ты не $gмог:могла; бы сразиться с Мстительным Хуэем?','Победите Мстительного Хуэя.','[PH] УБИТЬ!','Мстительный Хуэй','Хмелевар Тцзу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Хуэя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне стыдно просить тебя о еще одном одолжении, но я сделаю это ради жителей Зеленой Скалы... Ты не $gмог:могла; бы сразиться с Мстительным Хуэем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мстительного Хуэя.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','[PH] УБИТЬ!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мстительный Хуэй',`questgivertargetname_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Хмелевар Тцзу',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30921,'Мотивы богомолов','Вернитесь к Тай Хо в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мотивы богомолов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тай Хо в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30922,'Природный антисептик','Члены ордена Шадо-Пан – очень опытные и закаленые многолетними тренировками воины, мы не можем себе позволить терять их из-за царапины отравленным оружием или занесенной в рану инфекции. Вот поэтому мне нужно, чтобы ты $gраздобыл:раздобыла;... кое-что.$b$bВ общем, не буду ходить кругами: моча мушанов – это прекрасный естественный антисептик. И нам очень повезло, что они производят эту жидкость в таких количествах. Нам ее понадобится немало.','Соберите 5 наполненных мочевых пузырей мушана.','Не самая приятная работа, это точно.$B$BНо копать могилы еще хуже.','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природный антисептик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Члены ордена Шадо-Пан – очень опытные и закаленые многолетними тренировками воины, мы не можем себе позволить терять их из-за царапины отравленным оружием или занесенной в рану инфекции. Вот поэтому мне нужно, чтобы ты $gраздобыл:раздобыла;... кое-что.$b$bВ общем, не буду ходить кругами: моча мушанов – это прекрасный естественный антисептик. И нам очень повезло, что они производят эту жидкость в таких количествах. Нам ее понадобится немало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 наполненных мочевых пузырей мушана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не самая приятная работа, это точно.$B$BНо копать могилы еще хуже.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (30923,'Сдержать богомолов','С каждым днем богомолы производят все больше оружия. Мы не можем остановить это... но помешать можем.$b$b<Тай Хо дает вам взрывчатку.>$b$bМне нельзя привлекать к себе внимание. Хочешь отличиться?','Вернитесь к Тай Хо в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдержать богомолов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С каждым днем богомолы производят все больше оружия. Мы не можем остановить это... но помешать можем.$b$b<Тай Хо дает вам взрывчатку.>$b$bМне нельзя привлекать к себе внимание. Хочешь отличиться?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тай Хо в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30924,'Мудрость Нюцзао','Черный Бык Нюцзао обитает в храме к западу отсюда. Быть может, он знает, отчего богомолы решили напасть.$b$bЕму ведомо многое.$b$bМы встретимся в храме Нюцзао, |3-6($c).','Поговорите с Юным Ого в храме Нюцзао, что в Танлунских степях.','Шадо-пан, твой соратник, поговорил со мной. Да, Нюцзао известна причина нападений богомолов, но он не готов сообщить ее.$B$BПока не готов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость Нюцзао',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черный Бык Нюцзао обитает в храме к западу отсюда. Быть может, он знает, отчего богомолы решили напасть.$b$bЕму ведомо многое.$b$bМы встретимся в храме Нюцзао, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Юным Ого в храме Нюцзао, что в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шадо-пан, твой соратник, поговорил со мной. Да, Нюцзао известна причина нападений богомолов, но он не готов сообщить ее.$B$BПока не готов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30925,'Задание Нюцзао','Убивайте богомолов из числа вторгшихся шра\'тиков, чтобы Тай Хо мог обыскать их тела и найти части статуэтки Нюцзао.','Нюцзао будет доволен.$B$BОн полон жалости и сострадания. Он ценил эту вещицу... И он ценит своих приверженцев.','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Нюцзао',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте богомолов из числа вторгшихся шра\'тиков, чтобы Тай Хо мог обыскать их тела и найти части статуэтки Нюцзао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нюцзао будет доволен.$B$BОн полон жалости и сострадания. Он ценил эту вещицу... И он ценит своих приверженцев.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30926,'Страшная правда','Жаль, что приходится подтверждать твои подозрения. Богомолы действительно находятся под властью Ша Страха.$b$bКогда-то мы поклялись удержать это создание в земных недрах под нашим храмом. Но наша бдительность ослабла, и Ша исчез. Теперь он ведет богомолов.$b$bМожешь убедиться в этом. Богомолы прорываются к западной части нашего острова.','Изучите катакомбы Нюцзао и убейте мрачную тень, что обитает там.','Поговорите с Тай Хо в катакомбах Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшная правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жаль, что приходится подтверждать твои подозрения. Богомолы действительно находятся под властью Ша Страха.$b$bКогда-то мы поклялись удержать это создание в земных недрах под нашим храмом. Но наша бдительность ослабла, и Ша исчез. Теперь он ведет богомолов.$b$bМожешь убедиться в этом. Богомолы прорываются к западной части нашего острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите катакомбы Нюцзао и убейте мрачную тень, что обитает там.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тай Хо в катакомбах Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30927,'Даруй им покой','Я подслушивал. Что ж, наш секрет раскрыт.$b$bУзнав, что богомолы роют ход под наш храм, я поступил необдуманно. Я отправил несколько десятков стражей защищать нашу землю, не дав им как следует подготовиться. Они поддались страху и не смогли выбраться наружу.$b$bУмирая, пандарен должен обнимать теплую землю, как будто бы погружаясь в сон. Плохо лежать на спине с раскрытыми от ужаса глазами. Прошу тебя, $n, принеси им заслуженный покой.','Принесите покой 10 насмерть перепуганным стражам: закройте им глаза и переверните их на живот.','Вернитесь к командиру стражи Ципану в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даруй им покой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я подслушивал. Что ж, наш секрет раскрыт.$b$bУзнав, что богомолы роют ход под наш храм, я поступил необдуманно. Я отправил несколько десятков стражей защищать нашу землю, не дав им как следует подготовиться. Они поддались страху и не смогли выбраться наружу.$b$bУмирая, пандарен должен обнимать теплую землю, как будто бы погружаясь в сон. Плохо лежать на спине с раскрытыми от ужаса глазами. Прошу тебя, $n, принеси им заслуженный покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите покой 10 насмерть перепуганным стражам: закройте им глаза и переверните их на живот.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Ципану в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30928,'Путь страха','Теперь ты знаешь тайну Нюцзао. Мы не только служители храма... Мы должны сторожить Ша Страха в земных недрах под храмом.$b$bШа удалось скрыться... но тени его остались. Если ты действительно собираешься в катакомбы, уничтожь эти тени, иначе они выйдут наружу, и у нас будет еще больше проблем.','Убейте 12 кошмарней в катакомбах Нюцзао.','Нам и так хватает врагов: богомолы, могу, яунголы... Нужно разобраться с ша немедленно, потом будет уже поздно.','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь страха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты знаешь тайну Нюцзао. Мы не только служители храма... Мы должны сторожить Ша Страха в земных недрах под храмом.$b$bШа удалось скрыться... но тени его остались. Если ты действительно собираешься в катакомбы, уничтожь эти тени, иначе они выйдут наружу, и у нас будет еще больше проблем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 кошмарней в катакомбах Нюцзао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам и так хватает врагов: богомолы, могу, яунголы... Нужно разобраться с ша немедленно, потом будет уже поздно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30929,'Плохой як','Это здесь меняют дефективных яков?$b$bЭй, кто-нибудь, чего делать-то?','Помогите Синескоку заменить дефективного яка.','Думаю, мы договорились. Теперь им придется заменить этого яка.','Поговорите со Синескоком в храме Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохой як',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это здесь меняют дефективных яков?$b$bЭй, кто-нибудь, чего делать-то?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Синескоку заменить дефективного яка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, мы договорились. Теперь им придется заменить этого яка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Синескоком в храме Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30930,'Выбор яка','Я тут не вижу хороших яков. Все плохие, и все тут.$b$bОдни воняют, другие дерутся, третьи – пугливые какие-то.$b$bТы вот с виду $gвезучий:везучая:r; |3-6($r), возьми-ка лассо, может, ты мне хорошего яка подыщешь.','Воспользуйтесь лассо, чтобы отловить диких танлунских яков. Затем испытайте их в бою, чтобы проверить, подходят ли они Синескоку.','Вернитесь к Синескоку на поля Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выбор яка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут не вижу хороших яков. Все плохие, и все тут.$b$bОдни воняют, другие дерутся, третьи – пугливые какие-то.$b$bТы вот с виду $gвезучий:везучая:r; |3-6($r), возьми-ка лассо, может, ты мне хорошего яка подыщешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь лассо, чтобы отловить диких танлунских яков. Затем испытайте их в бою, чтобы проверить, подходят ли они Синескоку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Синескоку на поля Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30931,'Арбалет отца','Я пришел сюда, чтобы навестить отца в храме. Как только я здесь очутился, то увидел самое ужасное из всего, что мне доводилось видеть.$b$bЭто был богомол, он шел мимо меня с арбалетом отца.$b$BС отцом что-то случилось! Нам нужно выяснить, что именно... но сначала надо вернуть его арбалет. Я видел, что богомол двигался на запад, за храм.','Добудьте арбалет Ку-Яо.','Ага, это папин арбалет.$B$BПойдем к храму. Они знают, что...$B$B<Голос Ку-Мо прерывается.>$B$B...что с ним случилось.','Тебе... тебе удалось его найти?','Вернитесь к Ку-Мо в Танлунские степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арбалет отца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пришел сюда, чтобы навестить отца в храме. Как только я здесь очутился, то увидел самое ужасное из всего, что мне доводилось видеть.$b$bЭто был богомол, он шел мимо меня с арбалетом отца.$b$BС отцом что-то случилось! Нам нужно выяснить, что именно... но сначала надо вернуть его арбалет. Я видел, что богомол двигался на запад, за храм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте арбалет Ку-Яо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, это папин арбалет.$B$BПойдем к храму. Они знают, что...$B$B<Голос Ку-Мо прерывается.>$B$B...что с ним случилось.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе... тебе удалось его найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ку-Мо в Танлунские степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30932,'Стезя отца','Да, отец мальчика, часовой Ку-Яо, пропал. Он может быть где угодно, у нас много врагов.$b$bТы посматривай по сторонам, вдруг что узнаешь. Можешь поискать его яка, или спросить у часового Яло, может, он что знает.','Найдите отцовскую походную постель, отцовский щит, Ха-Шу и часового Яло.','Ни щита, ни лука, ни яка... с папой случилось что-то плохое.','Вернитесь к Ку-Мо в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стезя отца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, отец мальчика, часовой Ку-Яо, пропал. Он может быть где угодно, у нас много врагов.$b$bТы посматривай по сторонам, вдруг что узнаешь. Можешь поискать его яка, или спросить у часового Яло, может, он что знает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите отцовскую походную постель, отцовский щит, Ха-Шу и часового Яло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ни щита, ни лука, ни яка... с папой случилось что-то плохое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ку-Мо в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30933,'В поисках отца','Я искал повсюду... но отца не нашел. Я знаю, что он жив. Но ему нужен лук... вот и все.$b$bЯ слышал, что вы, Шадо-Паны, иногда сражаетесь с богомолами на острове Шра\'весс. Я не знаю, как попасть туда. Если ты будешь там, поищешь моего отца?','Поищите часового Ку-Яо.','<Кажется, Ку-Мо не замечает вас.>','Вернитесь к Ку-Мо в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках отца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я искал повсюду... но отца не нашел. Я знаю, что он жив. Но ему нужен лук... вот и все.$b$bЯ слышал, что вы, Шадо-Паны, иногда сражаетесь с богомолами на острове Шра\'весс. Я не знаю, как попасть туда. Если ты будешь там, поищешь моего отца?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите часового Ку-Яо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кажется, Ку-Мо не замечает вас.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ку-Мо в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30934,'Эффекты - тестовое задание','Привет, дружище! Давай кое-что проверим!$b$bЩелкай по снаряжению!$bБолтай с пузырьком!$bИсцеляй Зеленую Искру!$bУбей цель для убийства!$bЩелкни по трупу!$b$bГромкоговоритель будет сообщать о твоих успехах.$b$bПосле выполнения каждого задания ты будешь взрываться.$B$B(Извини.)','Взаимодействуйте с целями задания и убедитесь в том, что их значки работают.','Вернитесь к хранителю истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эффекты - тестовое задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, дружище! Давай кое-что проверим!$b$bЩелкай по снаряжению!$bБолтай с пузырьком!$bИсцеляй Зеленую Искру!$bУбей цель для убийства!$bЩелкни по трупу!$b$bГромкоговоритель будет сообщать о твоих успехах.$b$bПосле выполнения каждого задания ты будешь взрываться.$B$B(Извини.)',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взаимодействуйте с целями задания и убедитесь в том, что их значки работают.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30935,'История рыбака','Жители Цзоучин знают побережье лучше, чем кто-либо еще во всем Кунь-Лай. Если зандалары скрываются на одном из этих островов, они это выяснят.$B$BМиши доведет тебя до Пути Завоевателей. Я пойду вперед, может, удастся поговорить со старейшинами.$B$BСледуй по дороге до вершины Шепота Облака. Шинь Шепот Облака встретит тебя и проводит в деревню.','Поговорите с Миши, чтобы отправиться на Путь Завоевателей. На вершине Шепота Облака найдите Шиня Шепот Облака.','Старейшины согласились помочь нам узнать, где зандалары спрятали останки Властелина Грома.$B$BНо выдвинули несколько условий...','Поговорите с хранителем истории Чо в деревне Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История рыбака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жители Цзоучин знают побережье лучше, чем кто-либо еще во всем Кунь-Лай. Если зандалары скрываются на одном из этих островов, они это выяснят.$B$BМиши доведет тебя до Пути Завоевателей. Я пойду вперед, может, удастся поговорить со старейшинами.$B$BСледуй по дороге до вершины Шепота Облака. Шинь Шепот Облака встретит тебя и проводит в деревню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Миши, чтобы отправиться на Путь Завоевателей. На вершине Шепота Облака найдите Шиня Шепот Облака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Старейшины согласились помочь нам узнать, где зандалары спрятали останки Властелина Грома.$B$BНо выдвинули несколько условий...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в деревне Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (30936,'UNUSED') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30941,'Подготовка в деревне Цзоучин','Старейшины деревни, похоже, полагают, что где-то рядом захоронены останки Властелина Грома. А еще их беспокоит наше появление. Боятся, что на них из-за нас опять нападут.$b$bНам нужны останки, но оставлять деревню без защиты нельзя. Поговори со старейшиной Шу и Дошу Сгибающим Сталь. Придумайте, как им помочь.','Помогите старейшине Шу и Дошу Сгибающему Сталь подготовить деревню Цзоучин к битве.','Вернитесь к хранителю истории Чо в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка в деревне Цзоучин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старейшины деревни, похоже, полагают, что где-то рядом захоронены останки Властелина Грома. А еще их беспокоит наше появление. Боятся, что на них из-за нас опять нападут.$b$bНам нужны останки, но оставлять деревню без защиты нельзя. Поговори со старейшиной Шу и Дошу Сгибающим Сталь. Придумайте, как им помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите старейшине Шу и Дошу Сгибающему Сталь подготовить деревню Цзоучин к битве.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30942,'Сделай меня воином','Ш-ш-ш! Не говори так громко, отец услышит!$b$b<Шоми указывает на Дошу Сгибающего Сталь.>$b$bМой отец спятил! Он думает, что я буду учиться и чаи гонять, пока на нашу деревню нападают. Глупость какая! Я не трусливей, чем мужчины. Вот только сражаться не умею... пока.$b$bК этому-то я и веду. Возьми меня с собой! Я быстро учусь и не буду путаться под ногами, обещаю!$b$bПожа-а-а-алуйста!$b$bЕсли потеряем друг друга, встретимся здесь снова.','Я покажу отцу, чего я стою!','Поговорите с Шоми в деревне Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сделай меня воином',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ш-ш-ш! Не говори так громко, отец услышит!$b$b<Шоми указывает на Дошу Сгибающего Сталь.>$b$bМой отец спятил! Он думает, что я буду учиться и чаи гонять, пока на нашу деревню нападают. Глупость какая! Я не трусливей, чем мужчины. Вот только сражаться не умею... пока.$b$bК этому-то я и веду. Возьми меня с собой! Я быстро учусь и не буду путаться под ногами, обещаю!$b$bПожа-а-а-алуйста!$b$bЕсли потеряем друг друга, встретимся здесь снова.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я покажу отцу, чего я стою!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Шоми в деревне Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30943,'Осторожность и еще раз осторожность','Судя по количеству воинов, которые пришли сюда, победа будет нелегкой. Но я знаю одну вещь, благодаря которой мы можем получить преимущество.$b$bРядом с деревней растет одно растение, которое можно использовать для создания мощной взрывчатой жидкости. Если ты сможешь набрать достаточно, я начну ее варить.$b$bРастение, которое тебе нужно, называется взрывоцвет. Обращайся с ним осторожнее, |3-6($c).','Принесите старейшине Шу 50 взрывоцветов.','Получилось ли у тебя набрать достаточное количество взрывоцвета?','Вернитесь к старейшине Шу в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожность и еще раз осторожность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по количеству воинов, которые пришли сюда, победа будет нелегкой. Но я знаю одну вещь, благодаря которой мы можем получить преимущество.$b$bРядом с деревней растет одно растение, которое можно использовать для создания мощной взрывчатой жидкости. Если ты сможешь набрать достаточно, я начну ее варить.$b$bРастение, которое тебе нужно, называется взрывоцвет. Обращайся с ним осторожнее, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите старейшине Шу 50 взрывоцветов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Получилось ли у тебя набрать достаточное количество взрывоцвета?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Шу в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30944,'Целая деревня','Жители нашей деревни еще с первого нападения охраняют Цзоучин. Они измождены, а многие из них ранены.$b$bЕсли снова нападут зандалары, то меньше всего нам хотелось бы, чтобы наши защитники заснули посреди битвы. Попроси их оставить свои посты, чтобы у них была возможность подлечиться и навестить семьи.$b$bТы найдешь их на постах вокруг деревни.','Освободите изможенных защитников от несения стражи.','Вернитесь к хранителю истории Чо в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Целая деревня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жители нашей деревни еще с первого нападения охраняют Цзоучин. Они измождены, а многие из них ранены.$b$bЕсли снова нападут зандалары, то меньше всего нам хотелось бы, чтобы наши защитники заснули посреди битвы. Попроси их оставить свои посты, чтобы у них была возможность подлечиться и навестить семьи.$b$bТы найдешь их на постах вокруг деревни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите изможенных защитников от несения стражи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30945,'Это моя добыча','Старейшины хотят, чтобы мы усилили защиту? Мы не монахи, |3-6($c), нам нужно оружие, чтобы сражаться!$B$BСобери с тел этих варваров оружие для меня. Я переплавлю его во что-нибудь более подходящее для жителей нашей деревни, чтобы они могли воевать.$b$bПринеси столько, сколько сможешь, а я позабочусь об остальном.','Украдите 6 клинков у зандаларских захватчиков.','Нам нужна не только удача, чтобы пройти это испытание. Надеюсь, тебе удалось найти что-то, с чем я могу работать.','Вернитесь к Дошу Сгибающему Сталь в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это моя добыча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старейшины хотят, чтобы мы усилили защиту? Мы не монахи, |3-6($c), нам нужно оружие, чтобы сражаться!$B$BСобери с тел этих варваров оружие для меня. Я переплавлю его во что-нибудь более подходящее для жителей нашей деревни, чтобы они могли воевать.$b$bПринеси столько, сколько сможешь, а я позабочусь об остальном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 6 клинков у зандаларских захватчиков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужна не только удача, чтобы пройти это испытание. Надеюсь, тебе удалось найти что-то, с чем я могу работать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дошу Сгибающему Сталь в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30946,'Откровения','Старейшины считают, что останки находятся рядом с островом на северо-востоке. Селяне говорят, что около руин видели пророка Хар\'зула.$b$bНайди Хар\'зула, тогда, может, найдешь и останки Властелина Грома. Не упусти этот шанс, $n. Отправляйся в Покой Кан-Ши и сделай все, что возможно, чтобы остановить пророка.','Поговорите с зандаларским пленником.','Вернитесь к хранителю истории Чо в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откровения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старейшины считают, что останки находятся рядом с островом на северо-востоке. Селяне говорят, что около руин видели пророка Хар\'зула.$b$bНайди Хар\'зула, тогда, может, найдешь и останки Властелина Грома. Не упусти этот шанс, $n. Отправляйся в Покой Кан-Ши и сделай все, что возможно, чтобы остановить пророка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с зандаларским пленником.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30952,'Бесконечная осада','Богомолы постоянно нападают на нас. Они то прибывают, то отступают, но они не уходят насовсем.$b$bНичего, яки – воплощение стойкости. Мы не сдадимся и готовы вечно защищать свой дом.$b$bТы за нас?','Уничтожьте 12 нападающих шра\'тиков в храме Нюцзао.','Ты сражаешься не хуже нас.','Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечная осада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы постоянно нападают на нас. Они то прибывают, то отступают, но они не уходят насовсем.$b$bНичего, яки – воплощение стойкости. Мы не сдадимся и готовы вечно защищать свой дом.$b$bТы за нас?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 12 нападающих шра\'тиков в храме Нюцзао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сражаешься не хуже нас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30953,'Павшие стражи','Наши стражи могут сражаться дни и ночи напролет, но даже их выносливость не беспредельна. Многие уже полностью истощили свои силы в бою с богомолами.$b$bПрошу тебя, помоги им, придумай хоть что-нибудь. Если не сможешь излечить их $gсам:сама;, то дай им вот это. Глоток питательного молока яка придаст им сил.','Исцелите 8 раненых стражей Нюцзао до уровня 50% здоровья. Вы можете воспользоваться флягами с молоком яка или применить свои исцеляющие заклинания.','В такие времена нужно верить, что Нюцзао защитит нас, особенно если дела пойдут еще хуже.$B$BОн всегда на нашей стороне.','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Павшие стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши стражи могут сражаться дни и ночи напролет, но даже их выносливость не беспредельна. Многие уже полностью истощили свои силы в бою с богомолами.$b$bПрошу тебя, помоги им, придумай хоть что-нибудь. Если не сможешь излечить их $gсам:сама;, то дай им вот это. Глоток питательного молока яка придаст им сил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите 8 раненых стражей Нюцзао до уровня 50% здоровья. Вы можете воспользоваться флягами с молоком яка или применить свои исцеляющие заклинания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В такие времена нужно верить, что Нюцзао защитит нас, особенно если дела пойдут еще хуже.$B$BОн всегда на нашей стороне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30954,'Клинок – всегда клинок','Нет времени соблюдать все обычаи. Руки наших каменщиков дрожат и кровоточат. Наши кузнецы не успевают ковать оружие, так быстро оно уходит.$b$bНадо проявить смекалку.$b$bУ многих богомолов есть оружие, и на поле боя лежит вооружение убитых врагов. Глупо не воспользоваться этим.','Достаньте 10 клинков шра\'тиков.','Я прослежу за раздачей оружия. Теперь наши кузнецы смогут передохнуть. Видит Нюцзао, они это заслужили.','Нашим воинам привычнее булавы и дубины. Но сейчас выбирать не приходится.','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок – всегда клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет времени соблюдать все обычаи. Руки наших каменщиков дрожат и кровоточат. Наши кузнецы не успевают ковать оружие, так быстро оно уходит.$b$bНадо проявить смекалку.$b$bУ многих богомолов есть оружие, и на поле боя лежит вооружение убитых врагов. Глупо не воспользоваться этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 10 клинков шра\'тиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я прослежу за раздачей оружия. Теперь наши кузнецы смогут передохнуть. Видит Нюцзао, они это заслужили.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашим воинам привычнее булавы и дубины. Но сейчас выбирать не приходится.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30955,'Подношение','Наш покровитель Нюцзао долго раскачивается, но потом его не остановишь. Я хочу сказать, что если он сдвинется с места, богомолам придется приложить все силы, чтобы остановить его.$B$BПопробуем заинтересовать Нюцзао едой, это проще всего. К счастью, пищи в храме хватает... несмотря на военное время.$B$BМой силач пойдет с тобой, чтобы нести эту ношу.','Возьмите 6 порций еды Нюцзао. Понесет ее силач Нюцзао.','Он проснется. Скоро. Возможно, не сейчас, но уже скоро.$B$BИ тогда...$B$B<Паоша улыбается.>','Вернитесь к старшему ученику Паоша в храм Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш покровитель Нюцзао долго раскачивается, но потом его не остановишь. Я хочу сказать, что если он сдвинется с места, богомолам придется приложить все силы, чтобы остановить его.$B$BПопробуем заинтересовать Нюцзао едой, это проще всего. К счастью, пищи в храме хватает... несмотря на военное время.$B$BМой силач пойдет с тобой, чтобы нести эту ношу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 6 порций еды Нюцзао. Понесет ее силач Нюцзао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он проснется. Скоро. Возможно, не сейчас, но уже скоро.$B$BИ тогда...$B$B<Паоша улыбается.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему ученику Паоша в храм Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30956,'Осада продолжается','Нет ничего хуже этой стаи богомолов. Хорошо еще, что с нами Нюцзао.$B$BПомоги ему, |3-6($c). Возвращайся во двор и помоги защитить храм.','Убейте 25 нападающих на храм Нюцзао шра\'тиков.','Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осада продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет ничего хуже этой стаи богомолов. Хорошо еще, что с нами Нюцзао.$B$BПомоги ему, |3-6($c). Возвращайся во двор и помоги защитить храм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 25 нападающих на храм Нюцзао шра\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Ого в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30957,'Нашествие','Я командир стражей Нюцзао. Наши воины вполне справляются с богомолами.$B$BА вот с куньчунами сложнее.$B$BОни огромные и свирепые, серьезнейшая угроза для моих стражей. Только Нюцзао может выстоять против такого врага... И, возможно, ты.','Победите 4 шра\'тиков-куньчунов.','Вернитесь к командиру стражи Ципану в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я командир стражей Нюцзао. Наши воины вполне справляются с богомолами.$B$BА вот с куньчунами сложнее.$B$BОни огромные и свирепые, серьезнейшая угроза для моих стражей. Только Нюцзао может выстоять против такого врага... И, возможно, ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 4 шра\'тиков-куньчунов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Ципану в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30958,'Под прикрытием Нюцзао','Появление Нюцзао на поле боя – это великое благо... во многих смыслах.$b$bНапример, пока он отвлекает армию противника, у каменщиков есть время укрепить стены. Им нужна твоя помощь.$b$bЕсли увидишь выпавшие из стены камни, кидай им. И поторопись! Нюцзао не сможет сражаться вечно.','Бросьте 10 выпавших из стены камней каменщикам Нюцзао.','Похоже, наши стены обретают прежний облик. Думаю, со временем храм будет восстановлен.','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под прикрытием Нюцзао',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Появление Нюцзао на поле боя – это великое благо... во многих смыслах.$b$bНапример, пока он отвлекает армию противника, у каменщиков есть время укрепить стены. Им нужна твоя помощь.$b$bЕсли увидишь выпавшие из стены камни, кидай им. И поторопись! Нюцзао не сможет сражаться вечно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте 10 выпавших из стены камней каменщикам Нюцзао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, наши стены обретают прежний облик. Думаю, со временем храм будет восстановлен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сторожу яков Киане в храм Нюцзао в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30959,'Мощное оружие','Богомолы в своих жутких боевых повозках сейчас окружают Храм. Чем раньше мы от этих повозок избавимся, тем лучше. Можно их уничтожить с помощью нашего оружия и заклинаний, но вот это сработает гораздо быстрее.$b$b<Ого дает тебе несколько маленьких бочек с наспех уложенной взрывчаткой. >$b$BОпасайся нападения богомолов, которые останутся в фургоне, когда он взорвется. Вообще-то тебе стоит держаться от них как можно дальше.','Уничтожьте 3 боевых повозки шра\'тиков.','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы в своих жутких боевых повозках сейчас окружают Храм. Чем раньше мы от этих повозок избавимся, тем лучше. Можно их уничтожить с помощью нашего оружия и заклинаний, но вот это сработает гораздо быстрее.$b$b<Ого дает тебе несколько маленьких бочек с наспех уложенной взрывчаткой. >$b$BОпасайся нападения богомолов, которые останутся в фургоне, когда он взорвется. Вообще-то тебе стоит держаться от них как можно дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 боевых повозки шра\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юному Ого в храм Нюцзао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30960,'Возвращение из прохода','У меня все еще есть дела в проходе – некоторые богомолы так по нему и пробираются. Однако твоя помощь неоценима в любом деле, так что вряд ли Тажань одобрит, если я попрошу тебя выполнить столь обыденную работу.$B$BТажань все еще должен быть в главном лагере Гао-Жаня. Возвращайся с докладом, а я позже к тебе присоединюсь.','Доложите о возвращении Тажаню Чжу на Заставе Гао-Жаня.','С возвращением. Я слышал о проломах в восточном проходе. Похоже, я выбрал правильных людей для выполнения задания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение из прохода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня все еще есть дела в проходе – некоторые богомолы так по нему и пробираются. Однако твоя помощь неоценима в любом деле, так что вряд ли Тажань одобрит, если я попрошу тебя выполнить столь обыденную работу.$B$BТажань все еще должен быть в главном лагере Гао-Жаня. Возвращайся с докладом, а я позже к тебе присоединюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о возвращении Тажаню Чжу на Заставе Гао-Жаня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением. Я слышал о проломах в восточном проходе. Похоже, я выбрал правильных людей для выполнения задания.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30961,'$gСпаситель:Спасительница; Чернильной Жабры','Теперь я вернусь к своим родичам. Загляни к нам, если будешь на юго-западном берегу болота, и мы отблагодарим тебя.','Встретьтесь с Говорящим с водой Гожаем на юго-западном берегу болота цзинь-юй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','$gСпаситель:Спасительница; Чернильной Жабры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь я вернусь к своим родичам. Загляни к нам, если будешь на юго-западном берегу болота, и мы отблагодарим тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Говорящим с водой Гожаем на юго-западном берегу болота цзинь-юй.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30963,'Полевой бронник','Соберите 120 фрагментов панциря гнилозуба.','Прекрасно. Вечером возьмусь за починку, когда все вернутся.','Наши воины не должны погибать из-за сломанной брони.','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой бронник',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 120 фрагментов панциря гнилозуба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Вечером возьмусь за починку, когда все вернутся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши воины не должны погибать из-за сломанной брони.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30964,'Нужная припарка','Сухая повязка бесполезна, только что мухи в рану не лезут. Иногда, впрочем, большего и не жди.$b$bТолько не у меня.$b$bЯ прокладываю между бинтами пасту из найденных целебных трав. И лучше всего для этих целей подходят ивы Мао, что растут в северо-восточных полях. Если тебе попадутся эти ивы, собери их.','Соберите 11 ив Мао.','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужная припарка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сухая повязка бесполезна, только что мухи в рану не лезут. Иногда, впрочем, большего и не жди.$b$bТолько не у меня.$b$bЯ прокладываю между бинтами пасту из найденных целебных трав. И лучше всего для этих целей подходят ивы Мао, что растут в северо-восточных полях. Если тебе попадутся эти ивы, собери их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 11 ив Мао.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к cнабженцу Бамфу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30965,'Кошачий пастух','Сюэнь поручил мне следить за котятами. Такие забавные малыши.$b$bНо они пропали. Такие сильные оказались, и много их.$b$bТеперь Сюэнь больше мне их не доверит. Нужно найти котят. Поможешь?$b$bВозьми мою клетку, пусть они попадут в безопасное место.','Соберите 8 котят Сюэня.','Поговорите с Хранителем земель Пончем у храма Тигра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кошачий пастух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюэнь поручил мне следить за котятами. Такие забавные малыши.$b$bНо они пропали. Такие сильные оказались, и много их.$b$bТеперь Сюэнь больше мне их не доверит. Нужно найти котят. Поможешь?$b$bВозьми мою клетку, пусть они попадут в безопасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 котят Сюэня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хранителем земель Пончем у храма Тигра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30967,'Освобождение узников','Не все мои сородичи из Чернильной Жабры поддались искушению. Многие последовали моему совету и не стали пить воды, оскверненной ша..$b$bОни прячутся в деревне, боятся до смерти, а может, их стражники напугали.\r\n\r\nСообщи им, что еще не все потеряно! Отправляйся в деревню к северу отсюда. Передай им, чтобы шли ко мне.','Нас не так уж много, но это только начало. Скоро все снова будет как прежде. Мы благодарны тебе.','Вернитесь к говорящему с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение узников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не все мои сородичи из Чернильной Жабры поддались искушению. Многие последовали моему совету и не стали пить воды, оскверненной ша..$b$bОни прячутся в деревне, боятся до смерти, а может, их стражники напугали.\r\n\r\nСообщи им, что еще не все потеряно! Отправляйся в деревню к северу отсюда. Передай им, чтобы шли ко мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нас не так уж много, но это только начало. Скоро все снова будет как прежде. Мы благодарны тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящему с водой Гожаем на Озере Чернильной Жабры на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30968,'Ша Ненависти','Победите Ша Ненависти.','Победить ша... очень сложно. Просто чудо, что нам удалось выйти из этой переделки целыми и невредимыми.$B$BТажань до сих пор винит себя в том, что позволил своей ненависти взять верх и дал возможность чудовищу бесчинствовать в этих землях. На то, чтобы примириться с этим, ему может потребоваться время. Но важно, чтобы это произошло, тогда он будет менее уязвимым в будущем.$B$BСегодня мы совершили великий подвиг, о котором долго будут помнить.$B$BСпасибо тебе за помощь в этом деле.','Поговорите с Таоши в логове Сик\'весс в Танлунских степях.','Ша Ненависти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ша Ненависти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ша Ненависти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победить ша... очень сложно. Просто чудо, что нам удалось выйти из этой переделки целыми и невредимыми.$B$BТажань до сих пор винит себя в том, что позволил своей ненависти взять верх и дал возможность чудовищу бесчинствовать в этих землях. На то, чтобы примириться с этим, ему может потребоваться время. Но важно, чтобы это произошло, тогда он будет менее уязвимым в будущем.$B$BСегодня мы совершили великий подвиг, о котором долго будут помнить.$B$BСпасибо тебе за помощь в этом деле.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таоши в логове Сик\'весс в Танлунских степях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ша Ненависти',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30969,'Новый противник','$n, темные шаманы обладают большой силой, и это привлекло к ним многих союзников – тех, кто раньше был частью Орды, но теперь преследует свои зловещие цели.$b$bНам нужно разобраться с ними и тем самым преподать урок всем остальным, чтобы не повторилась ситуация с Сумеречным Молотом.$b$bУбей как можно больше последователей шаманов и принеси мне их знаки различия.','Добудьте 5 оскверненных знаков различия у любых последователей в Огненной Пропасти.','Ты собрал знаки?','Вернитесь к заклинателю Ксоренту в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый противник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, темные шаманы обладают большой силой, и это привлекло к ним многих союзников – тех, кто раньше был частью Орды, но теперь преследует свои зловещие цели.$b$bНам нужно разобраться с ними и тем самым преподать урок всем остальным, чтобы не повторилась ситуация с Сумеречным Молотом.$b$bУбей как можно больше последователей шаманов и принеси мне их знаки различия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 оскверненных знаков различия у любых последователей в Огненной Пропасти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал знаки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинателю Ксоренту в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30970,'Ослепленные ненавистью','Эти скорпионы находятся под воздействием ша. Из-за этого они повылезали из своих нор и направились в наш лагерь, ослепленные ненавистью к тем, кто вторгся в их земли.$B$BНам нужно избавиться от этих скорпионов и укрепить защиту лагеря. Убей всех, кого найдешь.','Убейте 9 ослепленных ненавистью шкуродеров.','Отлично. То, что осталось от лагеря, будет теперь в большей безопасности.','Вернитесь к Таоши в Ложбину Тусклого Света в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослепленные ненавистью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти скорпионы находятся под воздействием ша. Из-за этого они повылезали из своих нор и направились в наш лагерь, ослепленные ненавистью к тем, кто вторгся в их земли.$B$BНам нужно избавиться от этих скорпионов и укрепить защиту лагеря. Убей всех, кого найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 ослепленных ненавистью шкуродеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. То, что осталось от лагеря, будет теперь в большей безопасности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таоши в Ложбину Тусклого Света в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (30971,'Пополнение запаса','Меня послали обратно в лагерь собрать промасленные стрелы для лучников на мосту, и вот что в итоге получилось... Меня обучали, как и большинство этих пандаренов, а к этому не готовили.$B$BИ все-таки лучникам на мосту нужна наша помощь. Если ты поможешь собрать стрелы из этих обломков, может, мы хоть что-то сможем использовать от того, что здесь осталось...','Соберите 120 огненных стрел Шадо-Пан.','Пандарены на мосту рассчитывают на нас...','Вернитесь к новичку Пао-Мэ в Ложбину Тусклого Света в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня послали обратно в лагерь собрать промасленные стрелы для лучников на мосту, и вот что в итоге получилось... Меня обучали, как и большинство этих пандаренов, а к этому не готовили.$B$BИ все-таки лучникам на мосту нужна наша помощь. Если ты поможешь собрать стрелы из этих обломков, может, мы хоть что-то сможем использовать от того, что здесь осталось...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 120 огненных стрел Шадо-Пан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пандарены на мосту рассчитывают на нас...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новичку Пао-Мэ в Ложбину Тусклого Света в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (30972,'Присоединиться к сражению','Лучникам Лао-Чиня пригодятся эти стрелы на мосту. Сможешь их принести?','Принесите колчан с огненными стрелами Шадо-Пан Лао-Чиню Стальному Брюху на Мост Тусклого Света.','Тажань Чжу рассказал мне о судьбе моего лагеря. Я помешал бы, если бы мог, но нападения со стороны моста не прекращаются.$B$BСпасибо тебе за стрелы. Моим лучникам они понадобятся.','Добро пожаловать в заварушку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Присоединиться к сражению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лучникам Лао-Чиня пригодятся эти стрелы на мосту. Сможешь их принести?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите колчан с огненными стрелами Шадо-Пан Лао-Чиню Стальному Брюху на Мост Тусклого Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тажань Чжу рассказал мне о судьбе моего лагеря. Я помешал бы, если бы мог, но нападения со стороны моста не прекращаются.$B$BСпасибо тебе за стрелы. Моим лучникам они понадобятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в заварушку.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30973,'Охваченные пламенем','У богомолов, пересекающих мост, прочные панцири, которые отражают большинство атак. Но есть у них и слабость – огонь.$B$BБойцы Лао-Чиня принесли для этого на поле боя бочонки. Кидай бочонки в богомолов, а лучники Лао-Чиня их подожгут.$B$BТогда их уже будет легко добить.','Убейте 10 древесных корт\'тик с помощью бочонков Лао-Чиня.','Все это полезно еще и тем, что боевой дух богомолов упадет, когда они увидят, как их товарищи погибают в огне. Зрелище не из приятных, но сколько жизней они бы спасли, если бы прекратили прорываться через нашу оборону.','Вернитесь к Тажаню Чжу на Мост Тусклого Света в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охваченные пламенем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У богомолов, пересекающих мост, прочные панцири, которые отражают большинство атак. Но есть у них и слабость – огонь.$B$BБойцы Лао-Чиня принесли для этого на поле боя бочонки. Кидай бочонки в богомолов, а лучники Лао-Чиня их подожгут.$B$BТогда их уже будет легко добить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 древесных корт\'тик с помощью бочонков Лао-Чиня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все это полезно еще и тем, что боевой дух богомолов упадет, когда они увидят, как их товарищи погибают в огне. Зрелище не из приятных, но сколько жизней они бы спасли, если бы прекратили прорываться через нашу оборону.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на Мост Тусклого Света в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30974,'Крепость духа','Бочонки полны моего худшего пойла. Хорошо горит, но пить его ужасно.$B$BНо вместе с бочонками имеются у меня и кружки с лучшими напитками – для моих сородичей, которые этого заслуживают. Крепкие напитки для крепости духа после бесконечной и страшной схватки.$B$BТы ведь поможешь поднять настроение?','Бросьте 8 напитков Стального Брюха в застрельщиков и следопытов из Ложбины Тусклого Света.','Вернитесь к Лао-Чиню Стальному Брюху на Мост Тусклого Света в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бочонки полны моего худшего пойла. Хорошо горит, но пить его ужасно.$B$BНо вместе с бочонками имеются у меня и кружки с лучшими напитками – для моих сородичей, которые этого заслуживают. Крепкие напитки для крепости духа после бесконечной и страшной схватки.$B$BТы ведь поможешь поднять настроение?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте 8 напитков Стального Брюха в застрельщиков и следопытов из Ложбины Тусклого Света.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лао-Чиню Стальному Брюху на Мост Тусклого Света в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30975,'Захват Моста Тусклого Света','Давай оттесним этих насекомых за мост и сломим их боевой дух!$B$BСледуй за мной.','Помогите Лао-Чиню Стальному Брюху удержать дальнюю часть Моста Тусклого Света.','После такого разгрома богомолы вряд ли вернутся в ближайшее время, так что Лао-Чинь теперь свободен и может присоединиться к нашей охоте.','Поговорите с Тажанем Чжу на Мосту Тусклого Света в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват Моста Тусклого Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай оттесним этих насекомых за мост и сломим их боевой дух!$B$BСледуй за мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Лао-Чиню Стальному Брюху удержать дальнюю часть Моста Тусклого Света.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После такого разгрома богомолы вряд ли вернутся в ближайшее время, так что Лао-Чинь теперь свободен и может присоединиться к нашей охоте.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тажанем Чжу на Мосту Тусклого Света в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30976,'Присоединиться к охоте','Нас на одного больше. Твоя помощь бесценна.$B$BДавайте двинемся на запад к караульному посту Жэнь-сая, чтобы найти последнего участника нашей вечеринки.','Отправляйтесь с Тажанем Чжу, Таоши и Лао-Чинем к дозорному пункту Жэнь-сая.','Мы уже близко. Я чувствую, как подступает неестественная ненависть.$B$BТолько благодаря тренировкам в Шадо-Пан, бойцы на этом посту могут противостоять ее влиянию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Присоединиться к охоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас на одного больше. Твоя помощь бесценна.$B$BДавайте двинемся на запад к караульному посту Жэнь-сая, чтобы найти последнего участника нашей вечеринки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь с Тажанем Чжу, Таоши и Лао-Чинем к дозорному пункту Жэнь-сая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы уже близко. Я чувствую, как подступает неестественная ненависть.$B$BТолько благодаря тренировкам в Шадо-Пан, бойцы на этом посту могут противостоять ее влиянию.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30977,'Привет приземлившимся!','Все мои солдаты сейчас на юго-западе у Наблюдательного пункта, сдерживают богомолов, которые пытаются перелететь через провал. Пока у лучников есть стрелы, ни один богомол не сможет улететь далеко.$B$BЕсли хочешь помочь, добивай богомолов на земле. Возьмешься, |3-6($c)?','Убейте 12 приземлившихся легкокрылых кор\'тиков.','Вернитесь к Жэнь-саю Дубовой Шкуре на дозорный пункт Жэнь-сая в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Привет приземлившимся!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все мои солдаты сейчас на юго-западе у Наблюдательного пункта, сдерживают богомолов, которые пытаются перелететь через провал. Пока у лучников есть стрелы, ни один богомол не сможет улететь далеко.$B$BЕсли хочешь помочь, добивай богомолов на земле. Возьмешься, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 приземлившихся легкокрылых кор\'тиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэнь-саю Дубовой Шкуре на дозорный пункт Жэнь-сая в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30978,'Враждебные небеса','Сейчас нам будет не сладко... $B$BИди-ка к той пушке и начинай палить. Целей будет предостаточно.','Подстрелите 50 кор\'тиков-роевиков и воресс\'талика.','Отличная стрельба!$B$BНо мне определенно показалось, что тот большой жук выжил после падения...','Вернитесь к повелителю ястребов Нужуну на Наблюдательный пункт в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враждебные небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас нам будет не сладко... $B$BИди-ка к той пушке и начинай палить. Целей будет предостаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подстрелите 50 кор\'тиков-роевиков и воресс\'талика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная стрельба!$B$BНо мне определенно показалось, что тот большой жук выжил после падения...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю ястребов Нужуну на Наблюдательный пункт в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertargetname_loc8`) VALUES (30979,'Истребление жуков','Нам нужно спуститься и добить этого огромного жучару. Смелей.','Объединившись с повелителем ястребов Нужуном, убейте Воресс\'талика.','Где же ты был раньше! Это было потрясающе.$B$BДля меня честь сражаться с тобой бок о бок.','Воресс\'талик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление жуков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно спуститься и добить этого огромного жучару. Смелей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Объединившись с повелителем ястребов Нужуном, убейте Воресс\'талика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где же ты был раньше! Это было потрясающе.$B$BДля меня честь сражаться с тобой бок о бок.',`offerrewardtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Воресс\'талик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (30980,'Герои Шадо-Пан','Говоришь, Тажань Чжу сейчас в Танлуне, и он спрашивает обо мне? Должно быть, что-то важное...','Вернитесь с повелителем ястребов Нужуном к Тажаню Чжу на дозорный пункт Жэнь-сая.','Мне нравится, что я всегда могу на тебя положиться. У тебя дух истинного шадо-пана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герои Шадо-Пан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говоришь, Тажань Чжу сейчас в Танлуне, и он спрашивает обо мне? Должно быть, что-то важное...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь с повелителем ястребов Нужуном к Тажаню Чжу на дозорный пункт Жэнь-сая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне нравится, что я всегда могу на тебя положиться. У тебя дух истинного шадо-пана.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (30981,'Таоши и Корвекксис','Убейте Корвекксиса, объединив усилия с Таоши.','Первый кристалл наш...','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.','Корвекксис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таоши и Корвекксис',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Корвекксиса, объединив усилия с Таоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Первый кристалл наш...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Корвекксис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30983,'Темный шаман','Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Орды. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.','Победите темного шамана Корантала и стража лавы Гордота.','Похоже, эксперименты с черной магией свели Гордота с ума.$B$BНадеюсь, Хиловата, что на этом все закончится.','Вернитесь к заклинателю Ксоренту в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный шаман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Орды. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите темного шамана Корантала и стража лавы Гордота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, эксперименты с черной магией свели Гордота с ума.$B$BНадеюсь, Хиловата, что на этом все закончится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинателю Ксоренту в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30984,'Орки своих не бросают','$n, я думал, это будет обычный рейд – уничтожим пару троггов, осмотрим окрестности, а к полудню уже будем сидеть в таверне.$b$bВместо этого у меня пропал целый отряд разведчиков, а Ксор теперь пугает всех новым Сумеречным Молотом.$b$b<Командир Багран плюет с досады.>$b$bПриведи сюда моих разведчиков – тогда мы поймем наконец, что здесь происходит.','Спасите 5 кор\'кронских разведчиков в Огненной Пропасти.','Больше никто не выжил?$B$BНе знаю, кому служат эти шаманы, но они дорого заплатят за это.','Вернитесь к командиру Баграну в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орки своих не бросают',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я думал, это будет обычный рейд – уничтожим пару троггов, осмотрим окрестности, а к полудню уже будем сидеть в таверне.$b$bВместо этого у меня пропал целый отряд разведчиков, а Ксор теперь пугает всех новым Сумеречным Молотом.$b$b<Командир Багран плюет с досады.>$b$bПриведи сюда моих разведчиков – тогда мы поймем наконец, что здесь происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 кор\'кронских разведчиков в Огненной Пропасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Больше никто не выжил?$B$BНе знаю, кому служат эти шаманы, но они дорого заплатят за это.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Баграну в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (30986,'Древняя крипта могу','Наш отряд разведчиков уничтожен! На помощь!','Новобранец Чуббс','Отличная работа!','Новобранец Чуббс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древняя крипта могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш отряд разведчиков уничтожен! На помощь!',`details_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Новобранец Чуббс',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Отличная работа!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Новобранец Чуббс',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (30987,'Вступление в Альянс','$n, мы должны помнить о долге.$b$bНаша задача – распространять учение Тушуй за пределами Скитающегося острова... и начать лучше всего здесь, в Штормграде – сердце Альянса.$b$bНам понадобятся союзники, так что давай сначала узнаем, кто их предводитель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вступление в Альянс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы должны помнить о долге.$b$bНаша задача – распространять учение Тушуй за пределами Скитающегося острова... и начать лучше всего здесь, в Штормграде – сердце Альянса.$b$bНам понадобятся союзники, так что давай сначала узнаем, кто их предводитель.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30988,'Традиции Альянса','Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. Если ты хочешь помочь нашему делу, то я с радостью назову тебя своим союзником.$b$bСледуй за мной, $n.','Проследуйте за королем Варианом Ринном.','Поговорите с королем Варианом Ринном в крепости Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Традиции Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. Если ты хочешь помочь нашему делу, то я с радостью назову тебя своим союзником.$b$bСледуй за мной, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследуйте за королем Варианом Ринном.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Варианом Ринном в крепости Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30989,'Старый боец','Я хочу знать, умеешь ли ты сражаться. Возможно, когда-нибудь тебе придется пойти в бой, и мне нужно знать, сможешь ли ты встать на защиту моего королевства.$b$bЯ наслышан о воинах-пандаренах, но видеть их в деле мне не приходилось.$b$bМожет, сразимся?','Проведите тренировочный поединок с королем Варианом Ринном.','Вернитесь к королю Вариану Ринну в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый боец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу знать, умеешь ли ты сражаться. Возможно, когда-нибудь тебе придется пойти в бой, и мне нужно знать, сможешь ли ты встать на защиту моего королевства.$b$bЯ наслышан о воинах-пандаренах, но видеть их в деле мне не приходилось.$b$bМожет, сразимся?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите тренировочный поединок с королем Варианом Ринном.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`,`questturntargetname_loc8`) VALUES (30990,'Золотые двери','Победите могу-стража гробницы, чтобы открыть золотые двери.','Победите могу-стража гробницы.','Новобранец Чуббс','Новобранец Чуббс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Золотые двери',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Победите могу-стража гробницы, чтобы открыть золотые двери.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите могу-стража гробницы.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Новобранец Чуббс',`questgivertargetname_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Новобранец Чуббс',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30991,'Катушки-покатушки','Вот уж не думал я, когда учился на хмелевара, что мои знания придется использовать столь нестандартным образом.\r\n\r\nТы знаешь, что пиво можно поджечь, и оно будет гореть? А если смешать его с яунгольской нефтью, так и вовсе взрывчатка выйдет.\r\n\r\nВ эти бочки я добавил горючую смесь, что ты $gпринес:принесла;. Подкати их к яунголам, а потом подожги.\r\n\r\nБочка взорвется через несколько секунд, и мало никому не покажется...\r\n\r\nХм, не хотел бы я там оказаться.\r\n\r\nТак что я останусь здесь и буду грустить об этом пиве.','Возьмите бочку у Лао-Чиня, скатите ее с холма на яунголов и подожгите, когда они будут близко, чтобы уничтожить 4 древомета осулов и 50 осулов-завоевателей.','Вот это шарахнуло! Несколько раз даже.$B$BПиво, конечно, жалко, зато теперь мы в безопасности на какое-то время.','Вернитесь к Лао-Чиню Стальному Брюху в Лагерь Зимнего Цветения на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катушки-покатушки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот уж не думал я, когда учился на хмелевара, что мои знания придется использовать столь нестандартным образом.\r\n\r\nТы знаешь, что пиво можно поджечь, и оно будет гореть? А если смешать его с яунгольской нефтью, так и вовсе взрывчатка выйдет.\r\n\r\nВ эти бочки я добавил горючую смесь, что ты $gпринес:принесла;. Подкати их к яунголам, а потом подожги.\r\n\r\nБочка взорвется через несколько секунд, и мало никому не покажется...\r\n\r\nХм, не хотел бы я там оказаться.\r\n\r\nТак что я останусь здесь и буду грустить об этом пиве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите бочку у Лао-Чиня, скатите ее с холма на яунголов и подожгите, когда они будут близко, чтобы уничтожить 4 древомета осулов и 50 осулов-завоевателей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это шарахнуло! Несколько раз даже.$B$BПиво, конечно, жалко, зато теперь мы в безопасности на какое-то время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лао-Чиню Стальному Брюху в Лагерь Зимнего Цветения на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (30992,'Завершить начатое!','У нас новости от Суны, со стены. Что-то вот-вот случится...\r\n\r\nПохоже, они готовят завершающий удар. Пора показать им, кто тут чего стоит.','Закончите битву у Врат Быка.','Ну что ж, лейтенант убит. Думаю, в Кунь-Лай они больше не полезут.$B$BНо чего нам это стоило? Столько народу погибло, Линь в плену... Тажаню Чжу это с рук не сойдет.','Поговорите с Банем Медвежьим Сердцем в Лагере Зимнего Цветения на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершить начатое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас новости от Суны, со стены. Что-то вот-вот случится...\r\n\r\nПохоже, они готовят завершающий удар. Пора показать им, кто тут чего стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закончите битву у Врат Быка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, лейтенант убит. Думаю, в Кунь-Лай они больше не полезут.$B$BНо чего нам это стоило? Столько народу погибло, Линь в плену... Тажаню Чжу это с рук не сойдет.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Банем Медвежьим Сердцем в Лагере Зимнего Цветения на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (30993,'Где же подкрепление?','Так больше продолжаться не может. Откладывать нельзя.\r\n\r\nУчитывая, что творится здесь и в Огненной Ветви, нужно отправляться в монастырь.\r\n\r\nВсе другие дела могут подождать! Мой воздушный шар может подняться к самым вершинам гор, прямо туда. Он привязан у лагеря к северо-востоку отсюда.','Мы пришли, нельзя же было просто сидеть и ждать неизвестно чего.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где же подкрепление?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так больше продолжаться не может. Откладывать нельзя.\r\n\r\nУчитывая, что творится здесь и в Огненной Ветви, нужно отправляться в монастырь.\r\n\r\nВсе другие дела могут подождать! Мой воздушный шар может подняться к самым вершинам гор, прямо туда. Он привязан у лагеря к северо-востоку отсюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы пришли, нельзя же было просто сидеть и ждать неизвестно чего.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (30994,'Трюк Лао-Чиня','Так. С твоей помощью мы снова захватили всю стену. Хорошо.\r\n\r\nЯ пока останусь наверху, вдруг еще какой яунгол решится сюда залезть.\r\n\r\nА вот тебе стоит вернуться, посмотреть, как там дела у Лао-Чиня. Не хочется это признавать, но может, не такая уж плохая у него идея...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трюк Лао-Чиня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так. С твоей помощью мы снова захватили всю стену. Хорошо.\r\n\r\nЯ пока останусь наверху, вдруг еще какой яунгол решится сюда залезть.\r\n\r\nА вот тебе стоит вернуться, посмотреть, как там дела у Лао-Чиня. Не хочется это признавать, но может, не такая уж плохая у него идея...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30995,'Своих не бросаем','Час назад я отправил отряд на разведку, но он до сих пор не вернулся – более того, из пропасти полезли эти проклятые гончие.$b$bНе знаю, что там происходит, но пока разведчики не вернутся, я с места не двинусь.$b$b$n, иди туда и найди их – лучше, конечно, живыми.','Спасите 5 следопытов ШРУ в Огненной Пропасти.','Вернитесь к боевому командиру ШРУ Диркену в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своих не бросаем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Час назад я отправил отряд на разведку, но он до сих пор не вернулся – более того, из пропасти полезли эти проклятые гончие.$b$bНе знаю, что там происходит, но пока разведчики не вернутся, я с места не двинусь.$b$b$n, иди туда и найди их – лучше, конечно, живыми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 следопытов ШРУ в Огненной Пропасти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому командиру ШРУ Диркену в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30996,'Темный шаман','Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Альянса. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.','Победите темного шамана Корантала и стража лавы Гордота.','Вернитесь к верховной колдунье Арине в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный шаман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти темные шаманы уже несколько месяцев проводят здесь жуткие ритуалы и призывают чудовищ.$b$bНе знаю, чего они хотят этим добиться, но одно предельно ясно: шаманы – враги Альянса. И для борьбы с ними мне нужна твоя помощь.$b$bПроложи себе путь в ущелье и убей темного шамана Корантала и стража лавы Гордота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите темного шамана Корантала и стража лавы Гордота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной колдунье Арине в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (30997,'Ветеринарный контроль','Вернитесь к боевому командиру ШРУ Диркену в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветеринарный контроль',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому командиру ШРУ Диркену в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (30998,'Новый противник','$n, с помощью черной магии Орда управляет чудовищами и своими одержимыми собратьями.$b$bЯ намереваюсь положить этому конец, но сначала надо выяснить, кто именно нам противостоит. А для этого мне понадобится твоя помощь.$b$bПроложи себе путь по пещерам и собери знаки различия, которые носят последователи шаманов. Тогда я пойму, какая магия здесь задействована.','Добудьте 5 оскверненных знаков различия у последователей темного шамана.','Вернитесь к верховной колдунье Арине в Огненную Пропасть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый противник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, с помощью черной магии Орда управляет чудовищами и своими одержимыми собратьями.$b$bЯ намереваюсь положить этому конец, но сначала надо выяснить, кто именно нам противостоит. А для этого мне понадобится твоя помощь.$b$bПроложи себе путь по пещерам и собери знаки различия, которые носят последователи шаманов. Тогда я пойму, какая магия здесь задействована.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 оскверненных знаков различия у последователей темного шамана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной колдунье Арине в Огненную Пропасть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (30999,'Нехоженая тропа','Трудный путь вознаграждает самыми ценными знаниями, |3-6($c). Несомненно, я обогащусь великим опытом, пройдя путем Шаохао.$b$bМного лет назад Шаохао отправился на самый высокий пик Кунь-Лай, чтобы получить совет Нефритовой Змеи. Я тоже намерен отправиться в лагерь Искателя, дабы приобщиться к мудрости.$b$bВозможно, тебя заинтересует подобное путешествие? Если да, поговори с дядюшкой Листом Клевера. Он поможет тебе подготовиться.','Поговорите с дядюшкой Листом Клевера в Пэй-Лэй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехоженая тропа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трудный путь вознаграждает самыми ценными знаниями, |3-6($c). Несомненно, я обогащусь великим опытом, пройдя путем Шаохао.$b$bМного лет назад Шаохао отправился на самый высокий пик Кунь-Лай, чтобы получить совет Нефритовой Змеи. Я тоже намерен отправиться в лагерь Искателя, дабы приобщиться к мудрости.$b$bВозможно, тебя заинтересует подобное путешествие? Если да, поговори с дядюшкой Листом Клевера. Он поможет тебе подготовиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дядюшкой Листом Клевера в Пэй-Лэй.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31000,'Жуткое место','Доброволец для наблюдения за Жуткими пустошами? Первый раз вижу такое чудо.$B$BРада, что ты здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуткое место',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Доброволец для наблюдения за Жуткими пустошами? Первый раз вижу такое чудо.$B$BРада, что ты здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31001,'Падение','Мало того, что мы стараемся сдержать богомолов, так теперь из руин внизу полезли пауки.$B$BВ одного из моих лучших стрелков выстрелили паутиной и за ногу утащили прямо вниз!$B$BМы считаем, что он жив, но у меня мало людей и некого послать за ним. Мы уже на пределе, |3-6($c).$B$BПозади меня есть веревка, спустись по ней в руины, если хочешь помочь. Ты же не боишься высоты?$B$BА пауков?','Спуститесь на Гуртанскую террасу с помощью шадопанской веревки и найдите упавшего шадопанского меткого стрелка.','Поговорите со стрелком Ланном на террасе Гуртан, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало того, что мы стараемся сдержать богомолов, так теперь из руин внизу полезли пауки.$B$BВ одного из моих лучших стрелков выстрелили паутиной и за ногу утащили прямо вниз!$B$BМы считаем, что он жив, но у меня мало людей и некого послать за ним. Мы уже на пределе, |3-6($c).$B$BПозади меня есть веревка, спустись по ней в руины, если хочешь помочь. Ты же не боишься высоты?$B$BА пауков?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спуститесь на Гуртанскую террасу с помощью шадопанской веревки и найдите упавшего шадопанского меткого стрелка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со стрелком Ланном на террасе Гуртан, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31002,'Нет','Мы держимся, но едва-едва. Ты нам очень поможешь, если сделаешь хоть что-нибудь, чтобы сдержать поток поднимающихся по стене страхопрядов.$B$BХочешь раскалывать паучьи яйца руками по одному?$B$BСомневаюсь. Возьми одно из наших драконьих ружей и повеселись там внизу. Хочу услышать, как лопается эта мелюзга.','Отличная работа с ружьем. Мы здесь сделали все, что могли, но стрелами их особо не запугаешь.','Отыщите падших стрелков Шадо-Пан на Террасе Гуртан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы держимся, но едва-едва. Ты нам очень поможешь, если сделаешь хоть что-нибудь, чтобы сдержать поток поднимающихся по стене страхопрядов.$B$BХочешь раскалывать паучьи яйца руками по одному?$B$BСомневаюсь. Возьми одно из наших драконьих ружей и повеселись там внизу. Хочу услышать, как лопается эта мелюзга.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа с ружьем. Мы здесь сделали все, что могли, но стрелами их особо не запугаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отыщите падших стрелков Шадо-Пан на Террасе Гуртан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31003,'Безумный богомол','Ты не поверишь, что мне довелось увидеть! Два богомола сражались друг с другом, швыряясь смертоносными заклинаниями.$B$BОдин из них... Такого богомола мне видеть не доводилось. Он был абсолютно другого цвета, и одет иначе, будто какой-то жрец. Второй был настоящий псих, магия лилась из него, словно портер из бочки.$B$BПослушай, мне надо возвращаться на пост, но эти двое все еще сражаются в пещере за моей спиной, и у меня такое чувство, что дело тут серьезное. Может, проверишь?','Узнайте больше о бое богомолов на Террасе Гуртан.','Поговорите с клакси\'ва Тик на террасе Гуртан.','Богомол, пользующийся силой ша, как оружием? Как это возможно?','Адъюнкт Кри\'зот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумный богомол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не поверишь, что мне довелось увидеть! Два богомола сражались друг с другом, швыряясь смертоносными заклинаниями.$B$BОдин из них... Такого богомола мне видеть не доводилось. Он был абсолютно другого цвета, и одет иначе, будто какой-то жрец. Второй был настоящий псих, магия лилась из него, словно портер из бочки.$B$BПослушай, мне надо возвращаться на пост, но эти двое все еще сражаются в пещере за моей спиной, и у меня такое чувство, что дело тут серьезное. Может, проверишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте больше о бое богомолов на Террасе Гуртан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с клакси\'ва Тик на террасе Гуртан.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Богомол, пользующийся силой ша, как оружием? Как это возможно?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Адъюнкт Кри\'зот',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31004,'Застывший в янтаре','Возьми... это...$B$B<Умирающий богомол с трудом вытягивает искалеченную руку. В ней лежит металлическая вилка с двумя длинными тонкими зубцами и украшенной самоцветами ручкой.>$B$BПробуди... Рассекающего Ветер...$B$BТолько так можно... остановить рой.','Используйте камертон клакси на куске древнего янтаря на Террасе Гуртан.','Клакси... взывают ко мне.','Поговорите с Кил\'руком Рассекающим Ветер на террасе Гуртан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застывший в янтаре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми... это...$B$B<Умирающий богомол с трудом вытягивает искалеченную руку. В ней лежит металлическая вилка с двумя длинными тонкими зубцами и украшенной самоцветами ручкой.>$B$BПробуди... Рассекающего Ветер...$B$BТолько так можно... остановить рой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте камертон клакси на куске древнего янтаря на Террасе Гуртан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клакси... взывают ко мне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кил\'руком Рассекающим Ветер на террасе Гуртан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31005,'Тяжелое пробуждение','Прошу простить, что я в таком виде. Я провел во сне долгие годы.$B$BКлакси\'ва должны были заготовить сок кипари для моего Пробуждения... этим придется заняться тебе.$B$BЯ слышу, с юга доносится жужжание нектарниц. У них вдоволь древесного сока, что мне нужен. Принеси их мне.','Принесите 100 кусочков нектарниц Кил\'руку Рассекающему Ветер на террасу Гуртан.','Этого должно хватить.','Я вот-вот умру от истощения, если не получу пищи.','Возвратитесь на Террасу Гуртан к Кил\'руку Рассекающему Ветер.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелое пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу простить, что я в таком виде. Я провел во сне долгие годы.$B$BКлакси\'ва должны были заготовить сок кипари для моего Пробуждения... этим придется заняться тебе.$B$BЯ слышу, с юга доносится жужжание нектарниц. У них вдоволь древесного сока, что мне нужен. Принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 100 кусочков нектарниц Кил\'руку Рассекающему Ветер на террасу Гуртан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого должно хватить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вот-вот умру от истощения, если не получу пищи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Возвратитесь на Террасу Гуртан к Кил\'руку Рассекающему Ветер.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31006,'Совет клакси','Мне нужно предстать перед клакси. Меня бы не пробудили, если бы нашему народу не угрожала опасность.$B$BА от тебя все же есть польза, так что я тебя пощажу.$B$BВозможно, совет найдет тебе применение.','Это священное место собраний клакси.$B$BС твоей стороны будет разумно предоставить переговоры мне.','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Совет клакси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно предстать перед клакси. Меня бы не пробудили, если бы нашему народу не угрожала опасность.$B$BА от тебя все же есть польза, так что я тебя пощажу.$B$BВозможно, совет найдет тебе применение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это священное место собраний клакси.$B$BС твоей стороны будет разумно предоставить переговоры мне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31007,'Нечистые роерожденные','Имперские кладки осквернены! Хранители кладки ускоряют развитие новых роерожденных, питая их этой отвратительной энергией так называемого "ша", прежде чем отправить к стене.$B$BКлакси хотят прервать поток роерожденных из этих жутких кладок. Уничтожь хранителей!','Убейте 6 хранителей кладки Шек\'зир во Владениях Шек\'зир.','Еще несколько предателей, которые вскоре станут кормом для куньчунов.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечистые роерожденные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Имперские кладки осквернены! Хранители кладки ускоряют развитие новых роерожденных, питая их этой отвратительной энергией так называемого "ша", прежде чем отправить к стене.$B$BКлакси хотят прервать поток роерожденных из этих жутких кладок. Уничтожь хранителей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 хранителей кладки Шек\'зир во Владениях Шек\'зир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще несколько предателей, которые вскоре станут кормом для куньчунов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31008,'Янтарное оружие','Ты, ничтожество!$B$BТеперь ты работаешь на меня!$B$BУ воинов клинка Шек\'зир лучшее оружие в империи.$B$BПринеси мне столько янтарных клинков, сколько сможешь, если только тебя не проткнут ими по дороге! Я хочу быть уверен, что оружия при необходимости у нас будет достаточно.','Если все пойдет по плану, клакси остановят императрицу и без твоей помощи. Тем не менее, я должен быть готов ко всему.','Воины клинков с честью носили свои мечи. Теперь это оружие должно стать моим!','Вернитесь к кователю янтаря Зикку в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Янтарное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, ничтожество!$B$BТеперь ты работаешь на меня!$B$BУ воинов клинка Шек\'зир лучшее оружие в империи.$B$BПринеси мне столько янтарных клинков, сколько сможешь, если только тебя не проткнут ими по дороге! Я хочу быть уверен, что оружия при необходимости у нас будет достаточно.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если все пойдет по плану, клакси остановят императрицу и без твоей помощи. Тем не менее, я должен быть готов ко всему.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Воины клинков с честью носили свои мечи. Теперь это оружие должно стать моим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кователю янтаря Зикку в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31009,'Мертвая зона','Клакси\'ва шепчет сонару, и он далеко разносит этот шепот, передает другим сонарам, богомолам, Идеалам. Шепот возвращается, и клакси слышат его.$B$BТак им становится ведомо все.$B$BСонар около дворца молчит. Это неправильно. Он должен петь для клакси.$B$BЧинить сонар – моя работа, но ты служишь клакси, а значит – и мне. Так что ты чини сонар, а я тут подожду!','Поговорите с Кор\'иком в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мертвая зона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси\'ва шепчет сонару, и он далеко разносит этот шепот, передает другим сонарам, богомолам, Идеалам. Шепот возвращается, и клакси слышат его.$B$BТак им становится ведомо все.$B$BСонар около дворца молчит. Это неправильно. Он должен петь для клакси.$B$BЧинить сонар – моя работа, но ты служишь клакси, а значит – и мне. Так что ты чини сонар, а я тут подожду!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31010,'В ее власти','Клакси внимают песне кристалла. Они ощущают присутствие Идеала в кладке к востоку от звукового реле.$B$BХранители кладок пытаются осквернить его... клакси не могут допустить этого.$B$BОтправляйся туда и найди Идеал. Возложи руки на его убежище, шепот клакси пройдет сквозь тебя и освободит его. Защити его, если сможешь.','Найдите и пробудите Идеал во Владениях Шек\'зир.','Неожиданные сновидения прервали мой покой. Невыразимые кошмары!$B$BИ я пробудился.$B$BКлакси говорили со мной. У меня есть приказ, и многое еще предстоит сделать.','Поговорите с Маликом Невредимым в Клакси\'весс.','Мы обнаружили Идеал где-то рядом с тобой.','Кор\'ик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ее власти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси внимают песне кристалла. Они ощущают присутствие Идеала в кладке к востоку от звукового реле.$B$BХранители кладок пытаются осквернить его... клакси не могут допустить этого.$B$BОтправляйся туда и найди Идеал. Возложи руки на его убежище, шепот клакси пройдет сквозь тебя и освободит его. Защити его, если сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и пробудите Идеал во Владениях Шек\'зир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неожиданные сновидения прервали мой покой. Невыразимые кошмары!$B$BИ я пробудился.$B$BКлакси говорили со мной. У меня есть приказ, и многое еще предстоит сделать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Маликом Невредимым в Клакси\'весс.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мы обнаружили Идеал где-то рядом с тобой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Кор\'ик',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31011,'Враг у ворот','Зандалары напали! Помоги нам защитить деревню!$B$BЕсли они одержат верх, нам уже никогда не найти останки Властелина Грома!','Победите 10 зандаларских берсерков, 5 зандаларских чудищ и 3 кровопийц из племени Гурубаши.','Вернитесь к хранителю истории Чо в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг у ворот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары напали! Помоги нам защитить деревню!$B$BЕсли они одержат верх, нам уже никогда не найти останки Властелина Грома!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 10 зандаларских берсерков, 5 зандаларских чудищ и 3 кровопийц из племени Гурубаши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31013,'Традиции Орды','Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. $b$bЭто хорошо. Орде нужны новые силы, и пандарены ей очень пригодятся.$b$bСледуй за мной, $n.','Проследуйте за Гаррошем Адским Криком.','Поговорите с Гаррошем Адским Криком на аллее Чести в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Традиции Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно мне сообщили, что сюда может прибыть кто-то из твоего народа. $b$bЭто хорошо. Орде нужны новые силы, и пандарены ей очень пригодятся.$b$bСледуй за мной, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследуйте за Гаррошем Адским Криком.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаррошем Адским Криком на аллее Чести в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31014,'Дар Адского Крика','Мне нужно знать, умеешь ли ты драться... то есть убивать и при этом оставаться в живых. Рано или поздно каждый из вас отправится на войну, и я должен знать, можно ли на вас рассчитывать.$b$bЕсли помнишь, я упомянул о подарке – он здесь, на Арене Доблести. Открой дверь, которая находится у меня за спиной, и зайди на арену. Я испытаю тебя.','Пройдите испытание Гарроша, победив Оггакса, Гадуна и Ледяную Кровь.','Вернитесь к Гаррошу Адскому Крику в крепость Громмаш в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно знать, умеешь ли ты драться... то есть убивать и при этом оставаться в живых. Рано или поздно каждый из вас отправится на войну, и я должен знать, можно ли на вас рассчитывать.$b$bЕсли помнишь, я упомянул о подарке – он здесь, на Арене Доблести. Открой дверь, которая находится у меня за спиной, и зайди на арену. Я испытаю тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите испытание Гарроша, победив Оггакса, Гадуна и Ледяную Кровь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаррошу Адскому Крику в крепость Громмаш в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31015,'Ваша личная коллекция','У Пандарии богатая история и культура. Легенды, сказания, байки... Если во время своих путешествий ты встретишь ценный артефакт или сведения, связанные с нашими изысканиями, сохрани их.$b$bКогда наберется достаточно материалов, мы сплетем их в книгу, которую добавим в твою личную коллекцию.$b$bРазумеется, ты в любой момент сможешь посетить нас и ознакомиться с этими данными.','Протереть пустую полку.','О! Вот теперь, когда все готово, мы сможем разместить твои находки здесь. С нетерпением жду, когда можно будет взглянуть на них.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ваша личная коллекция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Пандарии богатая история и культура. Легенды, сказания, байки... Если во время своих путешествий ты встретишь ценный артефакт или сведения, связанные с нашими изысканиями, сохрани их.$b$bКогда наберется достаточно материалов, мы сплетем их в книгу, которую добавим в твою личную коллекцию.$b$bРазумеется, ты в любой момент сможешь посетить нас и ознакомиться с этими данными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Протереть пустую полку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Вот теперь, когда все готово, мы сможем разместить твои находки здесь. С нетерпением жду, когда можно будет взглянуть на них.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31016,'Хранители истории','$gДорогой:Дорогая; $n!$b$bМы сделали великое открытие в Вечноцветущем доле. Найдено огромное хранилище, полное книг и свитков, в которых содержатся знания времен империи могу.$b$bПредлагаем посетить нас при первой возможности. Обитель Мудрости находится около печально известных Подземелий Могу\'шан, от входа в подземелья нужно подняться на площадку.$b$bЖдем тебя с нетерпением!$b$bС уважением,$b$bХранитель истории Чо','Поговорите с хранителем истории Чо в Обители Мудрости в Вечноцветущем доле.','Вернитесь к хранителю истории Чо в Обитель Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранители истории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bМы сделали великое открытие в Вечноцветущем доле. Найдено огромное хранилище, полное книг и свитков, в которых содержатся знания времен империи могу.$b$bПредлагаем посетить нас при первой возможности. Обитель Мудрости находится около печально известных Подземелий Могу\'шан, от входа в подземелья нужно подняться на площадку.$b$bЖдем тебя с нетерпением!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости в Вечноцветущем доле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в Обитель Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31017,'Скромный груммель','$gДорогой:Дорогая; $n!$b$bМы получили твою работу по груммелям. Она позволяет составить точное представление об их происхождении и истории.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите книгу "Скромный груммель" хранителю истории Чо в Обитель Мудрости.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромный груммель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bМы получили твою работу по груммелям. Она позволяет составить точное представление об их происхождении и истории.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Скромный груммель" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31018,'Глубоко под Сердцем Страха','Клакси стало известно о существовании еще одного Идеала, Пробудитель.$B$BОн был скрыт от нас неспроста.$B$BОн находится у императрицы. Адъюнкты собираются его уничтожить.$B$BОни творят свои нечистые заклинания, скрывшись глубоко в подземельях дворца. Необходимо им помешать!$B$BПока мы будем удерживать Клакси\'весс, тебе надо остановить их. Пройди по западному выступу и отыщи вход в их зал.','Убейте адьюнктов Эквема, Иккесса, Суруза, Цзикци и освободите Ксарила Отравленный Разум.','Тебе удалось выполнить свою задачу, Пробудитель.','Поговорите с Ксарилом Отравленным Разумом на Ядовитой гряде в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубоко под Сердцем Страха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси стало известно о существовании еще одного Идеала, Пробудитель.$B$BОн был скрыт от нас неспроста.$B$BОн находится у императрицы. Адъюнкты собираются его уничтожить.$B$BОни творят свои нечистые заклинания, скрывшись глубоко в подземельях дворца. Необходимо им помешать!$B$BПока мы будем удерживать Клакси\'весс, тебе надо остановить их. Пройди по западному выступу и отыщи вход в их зал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте адьюнктов Эквема, Иккесса, Суруза, Цзикци и освободите Ксарила Отравленный Разум.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось выполнить свою задачу, Пробудитель.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ксарилом Отравленным Разумом на Ядовитой гряде в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31019,'Янтарь – это жизнь','Чтобы противостоять империи богомолов, нам нужно достать еще янтаря.$B$BБольшие запасы хранятся под озером к югу отсюда, но вокруг этого озера обитает дикое племя сауроков.$B$BУ меня каждый боец на счету. Придется тебе отправиться к озеру и познакомиться с ними. Убей, сколько сможешь. Обязательно прикончи вождя.$B$BНе так уж и сложно, правда?','Убейте 7 раздирателей из клана Туманного Клинка и чешуйчатого повелителя из клана Туманного Клинка.','Кажется, будто из глубин янтаря доносится шепот.$B$BНе может ли внутри спать еще один Идеал?','Янтарь кажется до странности знакомым...','Изучите кусок древнего янтаря на Озере Звезд в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Янтарь – это жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы противостоять империи богомолов, нам нужно достать еще янтаря.$B$BБольшие запасы хранятся под озером к югу отсюда, но вокруг этого озера обитает дикое племя сауроков.$B$BУ меня каждый боец на счету. Придется тебе отправиться к озеру и познакомиться с ними. Убей, сколько сможешь. Обязательно прикончи вождя.$B$BНе так уж и сложно, правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 раздирателей из клана Туманного Клинка и чешуйчатого повелителя из клана Туманного Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, будто из глубин янтаря доносится шепот.$B$BНе может ли внутри спать еще один Идеал?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Янтарь кажется до странности знакомым...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Изучите кусок древнего янтаря на Озере Звезд в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31020,'Обед для зверя','Мне нужно немедленно присоединиться к Совету клакси и другим Идеалам, но у меня едва хватает сил держаться на ногах.$B$BМне нужна пища, Пробудитель.$B$BЯ чувствую, как бьются сердца созданий на северном берегу озера.$B$BПринеси мне их мясо, и я насыщусь им.','Убейте 8 кроколисков-хладогрызов.','Я чувствую, как ко мне возвращаются силы.','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обед для зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно немедленно присоединиться к Совету клакси и другим Идеалам, но у меня едва хватает сил держаться на ногах.$B$BМне нужна пища, Пробудитель.$B$BЯ чувствую, как бьются сердца созданий на северном берегу озера.$B$BПринеси мне их мясо, и я насыщусь им.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 кроколисков-хладогрызов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую, как ко мне возвращаются силы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31021,'Живой янтарь','Жидкий янтарь лучше всего восстанавливает силы Идеала после пробуждения, его принято подносить Идеалу на церемонии пробуждения.$b$bСудя по всему, тебе об этом не сообщили, так что придется импровизировать.$B$BЯ чувствую, что на дне озера есть залежи янтаря. Он подойдет, но мне не хватит сил, чтобы выкопать его самому.$B$BПомоги же мне, и ты не останешься без награды.','Соберите 8 кусков живого янтаря и накормите ими Корвена Первейшего.','Спасибо, Пробудитель. Этого пока хватит.','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живой янтарь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жидкий янтарь лучше всего восстанавливает силы Идеала после пробуждения, его принято подносить Идеалу на церемонии пробуждения.$b$bСудя по всему, тебе об этом не сообщили, так что придется импровизировать.$B$BЯ чувствую, что на дне озера есть залежи янтаря. Он подойдет, но мне не хватит сил, чтобы выкопать его самому.$B$BПомоги же мне, и ты не останешься без награды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кусков живого янтаря и накормите ими Корвена Первейшего.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Пробудитель. Этого пока хватит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31022,'Кипари Зар','Что за дерево растет на холме к западу отсюда? Неужели это... Кипари Зар?$B$B<Корвен Первейший погружается в молчание.>$B$BКогда я вернулся из последнего налета, еще до того, как стать Идеалом, мне была оказана честь, и я посадил кипари.$B$BИ вот из моего саженца выросло огромное дерево, но... с ним что-то не так.$B$BУ его корней должен быть старый сонар. Отведи меня к дереву, Пробудитель. Нужно осмотреть его повнимательней.','Активируйте сонар, а затем защитите Корвена Первейшего, пока он будет изучать дерево.','Когда-то по жилам этого дерева текли обильные реки янтаря. Сейчас это всего лишь пустая оболочка.','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кипари Зар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за дерево растет на холме к западу отсюда? Неужели это... Кипари Зар?$B$B<Корвен Первейший погружается в молчание.>$B$BКогда я вернулся из последнего налета, еще до того, как стать Идеалом, мне была оказана честь, и я посадил кипари.$B$BИ вот из моего саженца выросло огромное дерево, но... с ним что-то не так.$B$BУ его корней должен быть старый сонар. Отведи меня к дереву, Пробудитель. Нужно осмотреть его повнимательней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте сонар, а затем защитите Корвена Первейшего, пока он будет изучать дерево.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда-то по жилам этого дерева текли обильные реки янтаря. Сейчас это всего лишь пустая оболочка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31023,'Реликвии Роя','Эта странная табличка покрыта письменами на языке, возможно, богомольского происхождения.$B$BВы замечаете и другие реликвии, неосторожно разбросанные по стоянкам и в озере.$B$BМожет быть, клакси будет интересно изучить эти артефакты.$B$BКто знает? Возможно, так удастся заслужить их уважение.','Соберите 8 реликвий богомолов.','Что там у тебя?','Вернитесь к кователю янтаря Зикку в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта странная табличка покрыта письменами на языке, возможно, богомольского происхождения.$B$BВы замечаете и другие реликвии, неосторожно разбросанные по стоянкам и в озере.$B$BМожет быть, клакси будет интересно изучить эти артефакты.$B$BКто знает? Возможно, так удастся заслужить их уважение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 реликвий богомолов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кователю янтаря Зикку в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31024,'Угощение куньчуна','По мере того как Ковок растет, ему будут нужны дисциплина и поощрение в равных долях.$B$BУ меня нет проблем с дисциплиной, но наши запасы мяса почти иссякли.$B$BК югу ты найдешь черепах, которые ползают севернее Озера Звезд и Кипари Зар.$B$BПоохоться на них, Ковоку нравится вкус их плоти.','Соберите 4 мясистых черепашьих бедрышка.','Да, достойный пир.$B$BОтлично сработано.','Что у тебя есть для Ковока?','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угощение куньчуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По мере того как Ковок растет, ему будут нужны дисциплина и поощрение в равных долях.$B$BУ меня нет проблем с дисциплиной, но наши запасы мяса почти иссякли.$B$BК югу ты найдешь черепах, которые ползают севернее Озера Звезд и Кипари Зар.$B$BПоохоться на них, Ковоку нравится вкус их плоти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 мясистых черепашьих бедрышка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, достойный пир.$B$BОтлично сработано.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у тебя есть для Ковока?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31025,'Sweet Tooth','We cannot summon a god without a worthy offering.$B$BI have noticed a rare flower growing among the fields to the north.$B$BThe Starshade is a potent flower whose bloom holds a powerfully sweet, intoxicating liquor.$B$BA single taste of this heady substance invigorates and strengthens the body.$B$BSurely, this god will appreciate its worth.','Collect 50 Starshade.','Return to Kil\'ruk the Wind-Reaver at Darkroot Hollow in the Dread Wastes.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Sweet Tooth',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','We cannot summon a god without a worthy offering.$B$BI have noticed a rare flower growing among the fields to the north.$B$BThe Starshade is a potent flower whose bloom holds a powerfully sweet, intoxicating liquor.$B$BA single taste of this heady substance invigorates and strengthens the body.$B$BSurely, this god will appreciate its worth.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Collect 50 Starshade.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Kil\'ruk the Wind-Reaver at Darkroot Hollow in the Dread Wastes.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31026,'Корень проблемы','Кипари Зар умирает.$B$BПорождение тьмы вгрызлось в его корни, пропитывая их скверной.$B$BДерево уже не спасти, но мы можем облегчить его страдания.$B$BСмотри. Злобная тварь оставила ход в свое логово. Достаточно пройти по нему, спуститься с холма и обойти сонар.','Убейте матриарха хладогрызов.','Спасибо тебе, Пробудитель. Теперь Кипари Зар может почивать в мире.$B$BНо похоже, эта тварь была лишь сосудом скверны.$B$BДа... источник должен лежать глубже.','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корень проблемы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кипари Зар умирает.$B$BПорождение тьмы вгрызлось в его корни, пропитывая их скверной.$B$BДерево уже не спасти, но мы можем облегчить его страдания.$B$BСмотри. Злобная тварь оставила ход в свое логово. Достаточно пройти по нему, спуститься с холма и обойти сонар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте матриарха хладогрызов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, Пробудитель. Теперь Кипари Зар может почивать в мире.$B$BНо похоже, эта тварь была лишь сосудом скверны.$B$BДа... источник должен лежать глубже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником, Корвеном Первейшим, на Озере Звезд или в Кипари Зар, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31027,'Бой с Воплощением гнева','Источник жихни очищен, и теперь путь к гробнице открыт. Спустись туда и победи Воплощение гнева.','Победите Воплощение гнева.','Novice Chubbs','Замечательно! Присылайте ваши отзывы по адресу jlecraft@blizzard.com.','Novice Chubbs') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой с Воплощением гнева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Источник жихни очищен, и теперь путь к гробнице открыт. Спустись туда и победи Воплощение гнева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Воплощение гнева.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Novice Chubbs',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Замечательно! Присылайте ваши отзывы по адресу jlecraft@blizzard.com.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Novice Chubbs',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31028,'Paragon 5','The emanations are growing stronger, $c.$B$BI feel them coming from the cave below us.$B$BI wish to study the beast that you have slain, so I will grant you the honor of awakening the next paragon.$B$BAfter all, the danger should be past.$B$BGo now, wallstrider, before I change my mind.','Recover the fifth paragon.','Вернитесь к Кил\'руку Рассекающему Ветер в Жуткие пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Paragon 5',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The emanations are growing stronger, $c.$B$BI feel them coming from the cave below us.$B$BI wish to study the beast that you have slain, so I will grant you the honor of awakening the next paragon.$B$BAfter all, the danger should be past.$B$BGo now, wallstrider, before I change my mind.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Recover the fifth paragon.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Жуткие пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31030,'В монастырь','Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\r\n\r\nСобери друзей, встретимся в монастыре.','Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.','Хорошо, что ты здесь. Ситуация катастрофическая.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В монастырь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\r\n\r\nСобери друзей, встретимся в монастыре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты здесь. Ситуация катастрофическая.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31031,'В монастырь','Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\r\n\r\nСобери друзей, встретимся в монастыре.','Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В монастырь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это... невообразимо. Если в монастыре и правда эпидемия ша, нам нелегко будет очистить монахов от скверны.\r\n\r\nСобери друзей, встретимся в монастыре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Банем Медвежьим Сердцем внутри монастыря Шадо-Пан.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31032,'Дым в небе','Нужун попросил меня раздать факелы, чтобы сжечь трупы.$b$bЛетающие богомолы хрупки и не выдержат горячего дыма.','Сожгите 10 трупов легкокрылых кор\'тиков.','Спасибо тебе, путник.','Вернитесь к стрелку Йе на Наблюдательный пункт в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дым в небе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужун попросил меня раздать факелы, чтобы сжечь трупы.$b$bЛетающие богомолы хрупки и не выдержат горячего дыма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 10 трупов легкокрылых кор\'тиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, путник.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стрелку Йе на Наблюдательный пункт в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31033,'Требуются искатели приключений: Огненная Пропасть','Вождь приказал всем искателям приключений немедленно спускаться в Огненную Пропасть, которая находится под великим городом Оргриммаром!$B$BТемные шаманы скоро пойдут на штурм, а городская стража не в силах долго сдерживать их натиск! Отправляйся в Огненную Пропасть и поговори с командиром Баграном – он скажет, что нужно делать.','Поговорите с командиром Баграном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуются искатели приключений: Огненная Пропасть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь приказал всем искателям приключений немедленно спускаться в Огненную Пропасть, которая находится под великим городом Оргриммаром!$B$BТемные шаманы скоро пойдут на штурм, а городская стража не в силах долго сдерживать их натиск! Отправляйся в Огненную Пропасть и поговори с командиром Баграном – он скажет, что нужно делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Баграном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (31034,'Враг из глубин','Поговорите с командиром Баграном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Баграном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31035,'Враг из глубин','Огненная Пропасть в Оргриммаре захвачена Пламенеющим Клинком. $n, нельзя оставить это безнаказанным, иначе вскоре они обратят взор на Громовой Утес.$B$BОтправляйся в пропасть и поговори с каменным стражем Курджаком прямо возле входа. Помоги ему чем можешь, ибо судьбы наши связаны.','Поговорите с каменным стражем Курджаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненная Пропасть в Оргриммаре захвачена Пламенеющим Клинком. $n, нельзя оставить это безнаказанным, иначе вскоре они обратят взор на Громовой Утес.$B$BОтправляйся в пропасть и поговори с каменным стражем Курджаком прямо возле входа. Помоги ему чем можешь, ибо судьбы наши связаны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем Курджаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31036,'Враг из глубин','Огненную Пропасть Оргриммара захватили темные шаманы. $n, это не должно остаться безнаказанным, иначе в следующий раз они двинутся уже на Громовой Утес.$B$BИди в Пропасть и поговори с командиром Баграном. Наши судьбы тесно связаны, поэтому ты $gдолжен:должна; сделать все, чтобы ему помочь.','Поговорите с командиром Баграном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненную Пропасть Оргриммара захватили темные шаманы. $n, это не должно остаться безнаказанным, иначе в следующий раз они двинутся уже на Громовой Утес.$B$BИди в Пропасть и поговори с командиром Баграном. Наши судьбы тесно связаны, поэтому ты $gдолжен:должна; сделать все, чтобы ему помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Баграном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (31037,'Враг из глубин','Поговорите с командиром Баграном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг из глубин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром Баграном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31038,'Бойцовский круг: Снежный Цветок','Ну что ж, $n, весь лагерь слышал о твоих подвигах.$B$BИ Снежный Цветок не прочь проверить, на что ты годишься в бою.$B$BСоветую подготовиться, |3-6($c). Справиться с ней непросто.$B$BПокажи ей, чего ты стоишь, и ты завоюешь верного друга.','Бросьте вызов Снежному Цветку и победите ее в бойцовском круге.','Так Снежный Цветок побеждена в бою?$B$BДумаю, она немного расстроится.$B$BЗато теперь она на твоей стороне.$B$BОна тяжело сходится с людьми, но вскоре ты поймешь, что у тебя появился надежный друг.','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: Снежный Цветок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, $n, весь лагерь слышал о твоих подвигах.$B$BИ Снежный Цветок не прочь проверить, на что ты годишься в бою.$B$BСоветую подготовиться, |3-6($c). Справиться с ней непросто.$B$BПокажи ей, чего ты стоишь, и ты завоюешь верного друга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов Снежному Цветку и победите ее в бойцовском круге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так Снежный Цветок побеждена в бою?$B$BДумаю, она немного расстроится.$B$BЗато теперь она на твоей стороне.$B$BОна тяжело сходится с людьми, но вскоре ты поймешь, что у тебя появился надежный друг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31039,'Угроза могу','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.','Шань\'цзэ что-то замышляют. Прекрасная работа, Лунван, но мы должны продолжать следить за ними.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шань\'цзэ что-то замышляют. Прекрасная работа, Лунван, но мы должны продолжать следить за ними.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31040,'Злобные духи','Могу подчинили духов из Мрачного леса на острове Шань\'цзэ Дао.$b$bИз мелких пакостников получились покорные слуги Шань\'цзэ. Они наглеют день ото дня, воруют и убивают по слову своих хозяев.$b$bИх нужно уничтожить, но не попадись на их уловки. С виду они безобидны, но внешность обманчива.','Убейте 30 духов Мрачного леса или заклинателей Мрачного леса.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу подчинили духов из Мрачного леса на острове Шань\'цзэ Дао.$b$bИз мелких пакостников получились покорные слуги Шань\'цзэ. Они наглеют день ото дня, воруют и убивают по слову своих хозяев.$b$bИх нужно уничтожить, но не попадись на их уловки. С виду они безобидны, но внешность обманчива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 духов Мрачного леса или заклинателей Мрачного леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31041,'Спасение яиц!','Яйца. Да, ты не $gослышался:ослышалась;, именно яйца, и речь не об омлете.$b$bТы $gвидел:видела; когда-нибудь яйцо облачного змея?$b$bЭто большая редкость. Они похожи на драгоценные камни и ценятся на вес золота.$b$bНа острове Шань\'цзэ Дао, что к северу отсюда, водятся дикие облачные змеи, но могу и духи забирают все их яйца себе.$b$bНам нужно достать как можно больше яиц.$b$bЯ рассчитываю на тебя, $n.','Соберите 8 яиц облачных бегунов.','Осторожно, осторожно!$B$BСпасибо тебе, Лунван! И все яйца целы.$B$BВ Нефритовом лесу найдутся наездники на змеях, которые позаботятся о них.','Ну что, есть яйца? Змеи откладывают яйца в гнездах на пляже, но лесные духи таскают их при первой возможности.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение яиц!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яйца. Да, ты не $gослышался:ослышалась;, именно яйца, и речь не об омлете.$b$bТы $gвидел:видела; когда-нибудь яйцо облачного змея?$b$bЭто большая редкость. Они похожи на драгоценные камни и ценятся на вес золота.$b$bНа острове Шань\'цзэ Дао, что к северу отсюда, водятся дикие облачные змеи, но могу и духи забирают все их яйца себе.$b$bНам нужно достать как можно больше яиц.$b$bЯ рассчитываю на тебя, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 яиц облачных бегунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осторожно, осторожно!$B$BСпасибо тебе, Лунван! И все яйца целы.$B$BВ Нефритовом лесу найдутся наездники на змеях, которые позаботятся о них.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, есть яйца? Змеи откладывают яйца в гнездах на пляже, но лесные духи таскают их при первой возможности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31042,'Ониксовые сердца','Змееловы Шань\'цзэ завладели разумами диких облачных змеев. А еще они создают темных существ из камня, металла и крови с помощью древнего колдовства.$b$bЭти создания, ониксовые Когти Бури, охраняют северо-западный остров.$b$bЯ хочу понять магию, создавшую их. Принеси мне их сердца, и я выясню, с каким колдовством мы имеем дело.','Соберите 4 ониксовых сердца.','Ониксовые Когти Бури никогда не ослушаются повелителя.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ониксовые сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Змееловы Шань\'цзэ завладели разумами диких облачных змеев. А еще они создают темных существ из камня, металла и крови с помощью древнего колдовства.$b$bЭти создания, ониксовые Когти Бури, охраняют северо-западный остров.$b$bЯ хочу понять магию, создавшую их. Принеси мне их сердца, и я выясню, с каким колдовством мы имеем дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 ониксовых сердца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ониксовые Когти Бури никогда не ослушаются повелителя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31043,'Темные искусства','Говорят, что на Шань\'цзэ Дао некогда стоял огромный храм могу.$b$bТам Шань\'цзэ учились подчинять мертвецов и оживлять неодушевленное.$b$bВсе это не пропало бесследно: на острове к северо-западу отсюда есть руины, и они все еще хранят в себе эти знания.$b$bМы должны добыть все, что можно, чтобы понять суть зловещих опытов Шань\'цзэ, и чтобы они не смогли получить доступ к этим знаниям.','Соберите 8 скрижалей Шань\'цзэ.','Знание дает силу. Именно поэтому могу так опасны.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные искусства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что на Шань\'цзэ Дао некогда стоял огромный храм могу.$b$bТам Шань\'цзэ учились подчинять мертвецов и оживлять неодушевленное.$b$bВсе это не пропало бесследно: на острове к северо-западу отсюда есть руины, и они все еще хранят в себе эти знания.$b$bМы должны добыть все, что можно, чтобы понять суть зловещих опытов Шань\'цзэ, и чтобы они не смогли получить доступ к этим знаниям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 скрижалей Шань\'цзэ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знание дает силу. Именно поэтому могу так опасны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31044,'Бронзовые когти','Цийлинь – одно из самых свирепых и верных созданий Шань\'цзэ.$b$bЭти твари не остановятся, пока не убьют свою жертву или не погибнут в схватке.$b$bТебе предстоит сократить их число. А еще нужно добыть их бронзовые когти.$b$bЭто прекрасные заготовки для оружия и крючьев, прочные и острые.','Соберите 20 бронзовых когтей.','Цийлини очень свирепы, но ты не уступишь им.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бронзовые когти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цийлинь – одно из самых свирепых и верных созданий Шань\'цзэ.$b$bЭти твари не остановятся, пока не убьют свою жертву или не погибнут в схватке.$b$bТебе предстоит сократить их число. А еще нужно добыть их бронзовые когти.$b$bЭто прекрасные заготовки для оружия и крючьев, прочные и острые.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 бронзовых когтей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Цийлини очень свирепы, но ты не уступишь им.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31045,'Иллюзии прошлого','$c, тебе предстоит отправиться на северо-запад, на Шань\'цзэ Дао и уничтожить мастеров иллюзий Шань\'цзэ.$b$bЯ знаю, что требую от тебя очень многого.$b$bТвоими противниками будут сильнейшие колдуны Шань\'цзэ.$b$bПобедить их будет непросто, но ты $gлучший:лучшая:c; |3-6($c) из тех, что у нас есть.','Убейте 3-х мастеров иллюзий Шань\'цзэ.','Конечно, тебе это оказалось по плечу, Тормунд!$B$BТеперь мастеров иллюзий Шань\'цзэ стало меньше, это очень облегчит нам задачу.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иллюзии прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, тебе предстоит отправиться на северо-запад, на Шань\'цзэ Дао и уничтожить мастеров иллюзий Шань\'цзэ.$b$bЯ знаю, что требую от тебя очень многого.$b$bТвоими противниками будут сильнейшие колдуны Шань\'цзэ.$b$bПобедить их будет непросто, но ты $gлучший:лучшая:c; |3-6($c) из тех, что у нас есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3-х мастеров иллюзий Шань\'цзэ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, тебе это оказалось по плечу, Тормунд!$B$BТеперь мастеров иллюзий Шань\'цзэ стало меньше, это очень облегчит нам задачу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31046,'Детеныши','Теперь я знаю, что за опыты проводят Шань\'цзэ на северо-западном острове.$b$bОни выращивают змеенышей, прямо из яиц помещают их в крохотные клетки и держат среди отбросов.$b$bЗмеенышей морят голодом и мучают самые жестокие палачи.$b$bМы должны спасти столько детенышей, сколько удастся. Я позволяю тебе наказать всех могу, что попадутся тебе.','Освободите 20 детенышей облачных бегунов.','Эти создания не забудут своего спасителя.$B$BТы отлично справился, Лунван.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детеныши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь я знаю, что за опыты проводят Шань\'цзэ на северо-западном острове.$b$bОни выращивают змеенышей, прямо из яиц помещают их в крохотные клетки и держат среди отбросов.$b$bЗмеенышей морят голодом и мучают самые жестокие палачи.$b$bМы должны спасти столько детенышей, сколько удастся. Я позволяю тебе наказать всех могу, что попадутся тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 20 детенышей облачных бегунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти создания не забудут своего спасителя.$B$BТы отлично справился, Лунван.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31047,'Рожденные свободными','Знаешь ли ты о судьбе великих облачных змеев Пандарии, $n?$b$bТебе непременно следует послушать эту историю, но сейчас у нас мало времени.$b$bТебе достаточно знать, что танлунские дикие облачные бегуны сейчас в беде.$b$bМогу захватывают диких змеев и порабощают их разум, подчиняя своей злой воле.$b$bОтправляйся на северо-запад, к Шань\'цзэ Дао. Освободи взрослых змеев от оков. Спаси их!','Освободите 6 диких облачных бегунов от цепей.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рожденные свободными',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь ли ты о судьбе великих облачных змеев Пандарии, $n?$b$bТебе непременно следует послушать эту историю, но сейчас у нас мало времени.$b$bТебе достаточно знать, что танлунские дикие облачные бегуны сейчас в беде.$b$bМогу захватывают диких змеев и порабощают их разум, подчиняя своей злой воле.$b$bОтправляйся на северо-запад, к Шань\'цзэ Дао. Освободи взрослых змеев от оков. Спаси их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 диких облачных бегунов от цепей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31048,'Траурное настроение','В руинах на Шань\'цзэ Дао мы нашли древние погребальные урны могу.$b$bОбычно такие вещи не представляют опасности, но в этих урнах заперты разъяренные духи могу.$b$bУрны опасны для тех несчастных, которые могут найти их случайно. Но гораздо страшнее, если эти сосуды попадут в злые руки.$b$bНа Шань\'цзэ Дао им не место.','Убейте 24 прародителя Шань\'цзэ. Вы найдете их в погребальных урнах могу.','Вот это мастерство! Время этих духов давно прошло.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Траурное настроение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В руинах на Шань\'цзэ Дао мы нашли древние погребальные урны могу.$b$bОбычно такие вещи не представляют опасности, но в этих урнах заперты разъяренные духи могу.$b$bУрны опасны для тех несчастных, которые могут найти их случайно. Но гораздо страшнее, если эти сосуды попадут в злые руки.$b$bНа Шань\'цзэ Дао им не место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 24 прародителя Шань\'цзэ. Вы найдете их в погребальных урнах могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это мастерство! Время этих духов давно прошло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31049,'Духи не в духе','Духи на Шань\'цзэ Дао частенько шалили, но сейчас они попали под власть могу.$b$bВсе больше духов стекается к новому хозяину.$b$bМы не можем допустить этого.$b$bОдно дело – мелкие пакости, и совсем другое – мощная и опасная темная магия большого отряда духов.$b$bУничтожь их предводительницу, пока не поздно.','Убейте волшебницу Мрачного леса.','Хвалю, Лунван.$B$BЛесные духи безвредны с виду, но это впечатление обманчиво.','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи не в духе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи на Шань\'цзэ Дао частенько шалили, но сейчас они попали под власть могу.$b$bВсе больше духов стекается к новому хозяину.$b$bМы не можем допустить этого.$b$bОдно дело – мелкие пакости, и совсем другое – мощная и опасная темная магия большого отряда духов.$b$bУничтожь их предводительницу, пока не поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте волшебницу Мрачного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвалю, Лунван.$B$BЛесные духи безвредны с виду, но это впечатление обманчиво.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
