INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31055,'Между сауроками и наковальней','$gДорогой:Дорогая; $n!$b$bМы получили твою работу по саурокам и отметили ее как весомый вклад в раскрытие тайн прошлого.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите хранителю истории Чо книгу "Между сауроками и наковальней".','Наконец-то стало понятно, почему сауроки так свирепы. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Между сауроками и наковальней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bМы получили твою работу по саурокам и отметили ее как весомый вклад в раскрытие тайн прошлого.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хранителю истории Чо книгу "Между сауроками и наковальней".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то стало понятно, почему сауроки так свирепы. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31058,'Обезьянье пойло','Пираты! Наши берега избрали своим пристанищем самые невоспитанные, неуемные, недобрые и нечистоплотные хозены, каких только знала Пандария. Мало того, они утверждают, что служат легендарному капитану Уку!$b$bМы каждую ночь видим, как они веселятся и варят пунш на своем острове Унга-Ингу.$b$bА давай возьмем и заберем их пунш! Я даже, пожалуй, смогу его улучшить.$b$bСобери друзей и разыщи меня на южной стороне Унга-Ингу. Пора устроить хмельной забег!','Одержите верх над капитаном Уком.','Поговорите с хмелеваром Бо в Унга-Ингу или в Маристе, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезьянье пойло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пираты! Наши берега избрали своим пристанищем самые невоспитанные, неуемные, недобрые и нечистоплотные хозены, каких только знала Пандария. Мало того, они утверждают, что служат легендарному капитану Уку!$b$bМы каждую ночь видим, как они веселятся и варят пунш на своем острове Унга-Ингу.$b$bА давай возьмем и заберем их пунш! Я даже, пожалуй, смогу его улучшить.$b$bСобери друзей и разыщи меня на южной стороне Унга-Ингу. Пора устроить хмельной забег!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите верх над капитаном Уком.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хмелеваром Бо в Унга-Ингу или в Маристе, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31060,'Dawson test POI') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Dawson test POI',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31061,'Оседлать грозу','Шань-Бу, предводитель Шань\'цзэ, проводит темный ритуал на вершине острова к северо-западу отсюда.$B$BСудя по всему, облачные бегуны Шань\'цзэ усиливают его колдовство, но мы не знаем как.$B$BВозможно, их удастся очистить от скверны.$B$BВозьми бронзовые когти, чтобы оседлать облачного бегуна.$B$BПроучи их... может, они поумнеют!','Оседлайте 8 облачных бегунов Шань\'Цзэ с помощью бронзовых когтей. Атакуйте их, чтобы очистить от скверны.','Нам неизвестны стремления Шань\'цзэ. Мы также не знаем, откуда у них такая власть над дикими змеями.$B$BБань считает, что только боль может избавить их от контроля над разумом.$B$BКогда облачный бегун Шань\'цзэ испытывает сильную боль, он приходит в себя, и злые силы теряют власть над ним.','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оседлать грозу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шань-Бу, предводитель Шань\'цзэ, проводит темный ритуал на вершине острова к северо-западу отсюда.$B$BСудя по всему, облачные бегуны Шань\'цзэ усиливают его колдовство, но мы не знаем как.$B$BВозможно, их удастся очистить от скверны.$B$BВозьми бронзовые когти, чтобы оседлать облачного бегуна.$B$BПроучи их... может, они поумнеют!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оседлайте 8 облачных бегунов Шань\'Цзэ с помощью бронзовых когтей. Атакуйте их, чтобы очистить от скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам неизвестны стремления Шань\'цзэ. Мы также не знаем, откуда у них такая власть над дикими змеями.$B$BБань считает, что только боль может избавить их от контроля над разумом.$B$BКогда облачный бегун Шань\'цзэ испытывает сильную боль, он приходит в себя, и злые силы теряют власть над ним.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31062,'Когда мертвецы говорят','За опытами Шань\'цзэ наблюдает сильный некромант: Шань\'цзэ – вестник смерти.$B$BЧтобы остановить их, придется от него избавиться.','Убейте Шань\'цзэ — вестника смерти.','Прекрасная работа, Тираниум.$B$BХвалю.','Вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда мертвецы говорят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За опытами Шань\'цзэ наблюдает сильный некромант: Шань\'цзэ – вестник смерти.$B$BЧтобы остановить их, придется от него избавиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шань\'цзэ — вестника смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная работа, Тираниум.$B$BХвалю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (31063,'Лао-Чинь и Серевекс','Убейте Серевекса вместе с Лао-Чинем Стальным Брюхом.','Наконец-то второй кристалл у нас. Хорошо.','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.','Серевекс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лао-Чинь и Серевекс',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Серевекса вместе с Лао-Чинем Стальным Брюхом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то второй кристалл у нас. Хорошо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Серевекс',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (31064,'Нужун и Ротек','Воспользуйтесь помощью повелителя ястребов Нужуна, чтобы убить Ротека.','Теперь все кристаллы у нас. И последняя битва уже не за горами.','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.','Ротек') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужун и Ротек',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь помощью повелителя ястребов Нужуна, чтобы убить Ротека.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь все кристаллы у нас. И последняя битва уже не за горами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Тажанем Чжу у логова Сик\'весс в Танлунских степях.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ротек',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31065,'Спрятано внутри','Таоши установила подзорную трубу на склоне горной гряды, чтобы показать мне результаты разведки.$b$bПодойди и посмотри.','Посмотрите в подзорную трубу на дозорном пункте Жэнь-сая.','Наша задача перед нами.','Вернитесь к Тажаню Чжу на дозорный пункт Жэнь-сая в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятано внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таоши установила подзорную трубу на склоне горной гряды, чтобы показать мне результаты разведки.$b$bПодойди и посмотри.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посмотрите в подзорную трубу на дозорном пункте Жэнь-сая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наша задача перед нами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу на дозорный пункт Жэнь-сая в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31066,'Крик из тьмы','Убейте оскверненный Идеал у Кипари Вор.','Что?! Как ты...$B$BЗовущий Смерть был легендарным героем. Он, должно быть, не полностью пробудился.$B$BТебе повезло.','Вернитесь к Кор\'ику в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крик из тьмы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте оскверненный Идеал у Кипари Вор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Как ты...$B$BЗовущий Смерть был легендарным героем. Он, должно быть, не полностью пробудился.$B$BТебе повезло.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кор\'ику в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31067,'Война жужжит на небесах','Убейте Аззикса К\'тая.','Мы не думали причинять кому-то вред. Мы просто хотели сделать немного напитка из сока этого дерева. Разве мы просим слишком многого?','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.','Плохой богомол.','Аззикс К\'тай') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война жужжит на небесах',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аззикса К\'тая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы не думали причинять кому-то вред. Мы просто хотели сделать немного напитка из сока этого дерева. Разве мы просим слишком многого?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Плохой богомол.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аззикс К\'тай',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31068,'Священный рецепт','"Когда небеса загудят в смятении\r\nИ страх поднимется из долин,\r\nВместилище нашего избавленья\r\nРазбей до самых его глубин."$b$bДальше в свитке еще несколько строф. Возможно, кто-то в хмелеваренном дворике "На закате" сможет расшифровать это загадочное послание.','Принесите свиток с предсказанием Ля Десять Песен в хмелеваренный дворик "На закате".','<Ля читает текст целиком.>$B$BЭтот свиток, это... это пророчество...$B$BОно ужасно!','Это какой-то свиток?$B$BНе возражаешь, если я взгляну поближе?','Отчитайтесь перед Ля Десять Песен в хмелеваренном дворике "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священный рецепт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Когда небеса загудят в смятении\r\nИ страх поднимется из долин,\r\nВместилище нашего избавленья\r\nРазбей до самых его глубин."$b$bДальше в свитке еще несколько строф. Возможно, кто-то в хмелеваренном дворике "На закате" сможет расшифровать это загадочное послание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите свиток с предсказанием Ля Десять Песен в хмелеваренный дворик "На закате".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ля читает текст целиком.>$B$BЭтот свиток, это... это пророчество...$B$BОно ужасно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это какой-то свиток?$B$BНе возражаешь, если я взгляну поближе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отчитайтесь перед Ля Десять Песен в хмелеваренном дворике "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31069,'Связанные тенью','Найденный тобой свиток...$b$bЯ все смотрю на эту строчку во второй строфе – "Тенью и деревом ты свяжи". Особенно меня интересует "тень".$b$bНадо сказать, мне часто приходило в голову собрать остаточную сущность ша в окрестностях и добавить ее в пиво. Думаю, это и есть та самая тень, о которой говорится в нашем рецепте.$b$bБольших ша можно найти к юго-востоку от нашего дерева... хотя, возможно, тебе удастся вытрясти немного из местной живности.','Соберите 100 капель тени, убив существ ша и оскверненных ша диких животных в окрестностях хмелеваренного дворика "На закате".','Прекрасно. Это станет отличным дополнением к нашему пиву.$B$BОчень часто самые опасные ингредиенты оказываются самыми вкусными.','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связанные тенью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найденный тобой свиток...$b$bЯ все смотрю на эту строчку во второй строфе – "Тенью и деревом ты свяжи". Особенно меня интересует "тень".$b$bНадо сказать, мне часто приходило в голову собрать остаточную сущность ша в окрестностях и добавить ее в пиво. Думаю, это и есть та самая тень, о которой говорится в нашем рецепте.$b$bБольших ша можно найти к юго-востоку от нашего дерева... хотя, возможно, тебе удастся вытрясти немного из местной живности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 капель тени, убив существ ша и оскверненных ша диких животных в окрестностях хмелеваренного дворика "На закате".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Это станет отличным дополнением к нашему пиву.$B$BОчень часто самые опасные ингредиенты оказываются самыми вкусными.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31070,'Кинжалы великих','В рецепте сказано: "Кинжалы злые великих, статных"...$b$b<Олон глубоко задумался над отрывком.>$b$bМушан! Это точно мушан!$b$bТам полным-полно мушанов с такими огромными зубами, длинными, точно кинжалы. Наверное, о них говорится в рецепте.','Добудьте 3 больших зуба мушана.','Я и представить не мог, что для варева понадобятся зубы мушана.$B$BУ создателя рецепта явно было что-то не то с головой.','Интересно, как же добавить эти штуки в пиво? Их нельзя размолоть – будут на зубах хрустеть.$B$BПопробую просто окунуть их туда на некоторое время.','Вернитесь к Олону в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кинжалы великих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В рецепте сказано: "Кинжалы злые великих, статных"...$b$b<Олон глубоко задумался над отрывком.>$b$bМушан! Это точно мушан!$b$bТам полным-полно мушанов с такими огромными зубами, длинными, точно кинжалы. Наверное, о них говорится в рецепте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 больших зуба мушана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я и представить не мог, что для варева понадобятся зубы мушана.$B$BУ создателя рецепта явно было что-то не то с головой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Интересно, как же добавить эти штуки в пиво? Их нельзя размолоть – будут на зубах хрустеть.$B$BПопробую просто окунуть их туда на некоторое время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Олону в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31071,'Позор мне','Я подвел своих собратьев-хмелеваров.$b$bЯ оставил нужные нам вещи на прогалине к востоку от нашего дерева... Теперь, когда ша заполонили землю, а богомолы вышли на охоту, я не могу вернуться и забрать их, это слишком опасно.$b$bЕсли ты поможешь мне отыскать их, то моя честь будет хотя бы отчасти восстановлена.','Найдите потерянный бочонок, потерянные кружки и потерянные припасы для пикника.','Спасибо, странник, теперь моей радости нет предела!','Неужели тебе удалось найти их все?','Вернитесь к изможденному жаждой Мисшо в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позор мне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я подвел своих собратьев-хмелеваров.$b$bЯ оставил нужные нам вещи на прогалине к востоку от нашего дерева... Теперь, когда ша заполонили землю, а богомолы вышли на охоту, я не могу вернуться и забрать их, это слишком опасно.$b$bЕсли ты поможешь мне отыскать их, то моя честь будет хотя бы отчасти восстановлена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите потерянный бочонок, потерянные кружки и потерянные припасы для пикника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, странник, теперь моей радости нет предела!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели тебе удалось найти их все?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к изможденному жаждой Мисшо в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31072,'Добыть кинжалы','Забудь про них и про их пиво. У нас тут серьезная работа.$b$bВ свитке написано "Кинжалы злые великих, статных". Кажется, я знаю, где их найти.$b$bПара богомолов-лейтенантов патрулирует Подступы Ужаса, что к югу отсюда. У каждого из них есть церемониальный кинжал.$b$bПринеси сюда эти кинжалы, $n. Возможно, мы на пороге чего-то очень важного.','Добудьте клинок Кз\'Кзика и клинок Иликкакса.','Эти кинжалы... смотри!$B$B<Ля прикладывает рукояти кинжалов друг к другу.>$B$BОни идеально совпадают! Но как же их соединить?..','Кажется, я начинаю понимать еще несколько строк пророчества, Астральный.$B$BТебе удалось добыть кинжалы?','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыть кинжалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Забудь про них и про их пиво. У нас тут серьезная работа.$b$bВ свитке написано "Кинжалы злые великих, статных". Кажется, я знаю, где их найти.$b$bПара богомолов-лейтенантов патрулирует Подступы Ужаса, что к югу отсюда. У каждого из них есть церемониальный кинжал.$b$bПринеси сюда эти кинжалы, $n. Возможно, мы на пороге чего-то очень важного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте клинок Кз\'Кзика и клинок Иликкакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти кинжалы... смотри!$B$B<Ля прикладывает рукояти кинжалов друг к другу.>$B$BОни идеально совпадают! Но как же их соединить?..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, я начинаю понимать еще несколько строк пророчества, Астральный.$B$BТебе удалось добыть кинжалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31073,'Скованные древом','<Ву изучает рецепт.>$b$bХм-м... "деревом ты свяжи". Мы обычно не варим дерево. Сок – да, но не древесину.$b$bИзредка мы добавляли в наши напитки сердцевину древней, что водились к западу отсюда. Большинство из них уничтожено богомолами... но их останков хватит для рецепта.','Добудьте 8 кусков ароматной древесной сердцевины.','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скованные древом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ву изучает рецепт.>$b$bХм-м... "деревом ты свяжи". Мы обычно не варим дерево. Сок – да, но не древесину.$b$bИзредка мы добавляли в наши напитки сердцевину древней, что водились к западу отсюда. Большинство из них уничтожено богомолами... но их останков хватит для рецепта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 кусков ароматной древесной сердцевины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31074,'Дерево и тень','Астральный, смотри! Эти кинжалы соединились в раздвоенное лезвие.$B$BМы на верном пути. Я знала, что это не рецепт пива.','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дерево и тень',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Астральный, смотри! Эти кинжалы соединились в раздвоенное лезвие.$B$BМы на верном пути. Я знала, что это не рецепт пива.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31075,'Закатные короли','Встретьтесь с соковаром Ву в деревне Риккитун.','Давненько мне не приходилось варить что-то в походных условиях.','Поговорите с соковаром Ву в деревне Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закатные короли',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с соковаром Ву в деревне Риккитун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давненько мне не приходилось варить что-то в походных условиях.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с соковаром Ву в деревне Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31076,'Судьба семейства Буйный Портер','Приветствую тебя, |3-6($r). Меня зовут Чэнь Буйный Портер.$b$bЯ ищу свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу присоединиться к ним.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?','Спросить у обитателей хмелеваренного дворика "На закате", не видели ли они Буйных Портеров.','<Чэнь внимательно слушает.>$B$BЗдоровяк Дань, Хань, Эви и Мамаша. Я понял.$B$BДумаю, Дань будет здесь в безопасности. Я поищу Эви, Ханя и Мамашу Буйный Портер.$B$BДоброго пути тебе, Риктикитики, следуй путем странника.','Вернитесь к Чэню Буйному Портеру в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба семейства Буйный Портер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($r). Меня зовут Чэнь Буйный Портер.$b$bЯ ищу свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу присоединиться к ним.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спросить у обитателей хмелеваренного дворика "На закате", не видели ли они Буйных Портеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чэнь внимательно слушает.>$B$BЗдоровяк Дань, Хань, Эви и Мамаша. Я понял.$B$BДумаю, Дань будет здесь в безопасности. Я поищу Эви, Ханя и Мамашу Буйный Портер.$B$BДоброго пути тебе, Риктикитики, следуй путем странника.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31077,'Эви Буйный Портер','Я опоздал. Она была совсем малюткой... и я опоздал.$b$bНадо похоронить ее достойно. Маленькая воительница вроде нее заслуживает большего, нежели это.','Подойдите к Чэню в хмелеваренном дворике "На закате" и прослушайте его скорбную песнь.','<Чэнь некоторое время молчит.>','<Чэнь скорбит.>','Поговорите с Чэнем Буйным Портером в хмелеваренном дворике "На закате".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эви Буйный Портер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я опоздал. Она была совсем малюткой... и я опоздал.$b$bНадо похоронить ее достойно. Маленькая воительница вроде нее заслуживает большего, нежели это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подойдите к Чэню в хмелеваренном дворике "На закате" и прослушайте его скорбную песнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чэнь некоторое время молчит.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Чэнь скорбит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в хмелеваренном дворике "На закате".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31078,'Хань Буйный Портер','Время горевать придет позже. Сейчас нужно найти остальных Буйных Портеров.$b$bГоворят, Ханя Буйного Портера в последний раз видели, когда он обследовал Кор\'весс. Подозреваю, что он направился в логово богомолов, прямо по пути.$b$bВстреть меня там, $n. Я не сомневаюсь, что справлюсь с несколькими богомолами в одиночку... но мне спокойней, если ты будешь рядом.','Сначала Эви, теперь Хань.$B$BЯ снова пришел слишком поздно.','Кажется, я вижу там кого-то, но я не могу пробраться сквозь эти янтарные лучи.','Поговорите с Чэнем Буйным Портером в Зале Потоков, расположенном под Кор\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хань Буйный Портер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время горевать придет позже. Сейчас нужно найти остальных Буйных Портеров.$b$bГоворят, Ханя Буйного Портера в последний раз видели, когда он обследовал Кор\'весс. Подозреваю, что он направился в логово богомолов, прямо по пути.$b$bВстреть меня там, $n. Я не сомневаюсь, что справлюсь с несколькими богомолами в одиночку... но мне спокойней, если ты будешь рядом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сначала Эви, теперь Хань.$B$BЯ снова пришел слишком поздно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, я вижу там кого-то, но я не могу пробраться сквозь эти янтарные лучи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в Зале Потоков, расположенном под Кор\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31079,'Страх из долин','Убейте 7 слоняющихся туманных скрытней и 2 кипаритов.','Хорошо, когда гигант вроде тебя оказывается в нашей деревне.$B$BТы можешь принести много пользы.','Вернитесь к Страшиле в деревню Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страх из долин',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 слоняющихся туманных скрытней и 2 кипаритов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, когда гигант вроде тебя оказывается в нашей деревне.$B$BТы можешь принести много пользы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Страшиле в деревню Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31080,'Ярость бурь королей закатных','Кажется, в той старой рукописи говорилось что-то о "закатных королях". У здешних дракончиков есть крылья огненного цвета... похоже на свет солнца на закате.$b$bТы шустрее меня. Попробуй поймать нескольких дракончиков... или хотя бы натрясти с них пыльцы.$b$bНезачем убивать безобидного дракончика, если нужны всего лишь блестки с его крылышек.','Потряси порхунов Риккили, а затем поймай 88 крупинок пыльцы порхунов.','Я не могу поймать ни одного из них!','Вернитесь к Олону в деревню Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость бурь королей закатных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, в той старой рукописи говорилось что-то о "закатных королях". У здешних дракончиков есть крылья огненного цвета... похоже на свет солнца на закате.$b$bТы шустрее меня. Попробуй поймать нескольких дракончиков... или хотя бы натрясти с них пыльцы.$b$bНезачем убивать безобидного дракончика, если нужны всего лишь блестки с его крылышек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потряси порхунов Риккили, а затем поймай 88 крупинок пыльцы порхунов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не могу поймать ни одного из них!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Олону в деревню Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31081,'Заклятья, что силу хранят в веках','Думаю, нам понадобится помощь тех духов.$b$bУ нас есть два зачарованных кинжала, связанных древом и тенью. Теперь нужно, чтобы кто-то произнес древние "заклятья" над нашим артефактом.$b$bПрежде чем просить об услуге, надо показать духам, что у нас добрые намерения. Их глава говорил о паре туманников, укравших нескольких жителей деревни. Если убить этих туманных тварей... то мы, возможно, в награду получим "заклятье", которое нам нужно.','Уничтожьте Агуносса и Мигонесса.','Отличная работа. Я услышала, как духи говорили о нас.$B$BМы привлекли их внимание.','Вернитесь к Ля Десять Песен в деревню Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заклятья, что силу хранят в веках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, нам понадобится помощь тех духов.$b$bУ нас есть два зачарованных кинжала, связанных древом и тенью. Теперь нужно, чтобы кто-то произнес древние "заклятья" над нашим артефактом.$b$bПрежде чем просить об услуге, надо показать духам, что у нас добрые намерения. Их глава говорил о паре туманников, укравших нескольких жителей деревни. Если убить этих туманных тварей... то мы, возможно, в награду получим "заклятье", которое нам нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Агуносса и Мигонесса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Я услышала, как духи говорили о нас.$B$BМы привлекли их внимание.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ля Десять Песен в деревню Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31082,'Вместилище нашего избавленья','Я знаю, что ищете вы с девочкой-пандой. Мы можем провести для вас ритуал... но позже.$b$bСначала я прошу помочь нам. С великой матери древ падают семена. Наша обязанность – собирать их, даже в опасные времена, подобные нынешним.$b$bСопроводите моих заклинателей к семенам матери древ, чтобы они принесли их в яму для семян.','Принесите 3 семени матери древ в яму для семян в деревне Риккитун с помощью заклинателей Риккитун.$b$bВы можете использовать колокол Риккитун, чтобы призвать заклинателей, если вы потеряете друг друга.','Да, хорошо. За семенами матери древ приглядывают.$B$BТеперь поговорим о чарах.','Вернитесь к вождю Риккитун в деревню Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вместилище нашего избавленья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что ищете вы с девочкой-пандой. Мы можем провести для вас ритуал... но позже.$b$bСначала я прошу помочь нам. С великой матери древ падают семена. Наша обязанность – собирать их, даже в опасные времена, подобные нынешним.$b$bСопроводите моих заклинателей к семенам матери древ, чтобы они принесли их в яму для семян.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 семени матери древ в яму для семян в деревне Риккитун с помощью заклинателей Риккитун.$b$bВы можете использовать колокол Риккитун, чтобы призвать заклинателей, если вы потеряете друг друга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, хорошо. За семенами матери древ приглядывают.$B$BТеперь поговорим о чарах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Риккитун в деревню Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31083,'Обещание золота','Сразу после гибели этого существа появилась стайка лесных духов, они забрали жемчужину.$b$bДеревня лесных духов недалеко отсюда, она называется Риккитун. Советую туда зайти.','Доложите вождю Риккитун в деревне Риккитун, что в Жутких пустошах.','Это сияющее семя... это твоя работа? У меня уже было одно... но два лучше.$B$BНам нужно только семя, а не оболочка. Можешь оставить ее себе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обещание золота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сразу после гибели этого существа появилась стайка лесных духов, они забрали жемчужину.$b$bДеревня лесных духов недалеко отсюда, она называется Риккитун. Советую туда зайти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите вождю Риккитун в деревне Риккитун, что в Жутких пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это сияющее семя... это твоя работа? У меня уже было одно... но два лучше.$B$BНам нужно только семя, а не оболочка. Можешь оставить ее себе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31084,'Связать чары','Много, много лет прошло с тех пор, как наше племя проводило этот ритуал. Я буду стараться изо всех сил.','Позвольте вождю Риккитун зачаровать раздвоенный клинок.','Клинок готов.$B$BОсталось только одно: использовать его.','Вернитесь к вождю Риккитун в деревню Риккитун, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связать чары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много, много лет прошло с тех пор, как наше племя проводило этот ритуал. Я буду стараться изо всех сил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позвольте вождю Риккитун зачаровать раздвоенный клинок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клинок готов.$B$BОсталось только одно: использовать его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Риккитун в деревню Риккитун, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31085,'Огонь и былого страх','Мы нашли клинки, связали их древом и тьмой и благословили древним заклинанием. Если я не ошибаюсь, пора использовать эту штуку.$b$bДухи говорили о древней смоле в Янтарной усыпальнице, пещере богомолов возле дворца их императрицы. Это, должно быть, "Кровь Древних", о которой говорит пророчество.$b$bВнутри этой смолы находится что-то важное. Удачи тебе, $n.','Используйте двузубец разрушения на Ийокуке Проницательном, а затем защитите его, пока он не сможет спастись.','В этом куске янтаря был... богомол? Вот бы никогда не подумала, что ключом к победе в войне с богомолами станет богомол!$B$BВек живи, век учись, это правда. А кое-что я теперь знаю наверняка: это точно был не пивной рецепт.','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь и былого страх',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы нашли клинки, связали их древом и тьмой и благословили древним заклинанием. Если я не ошибаюсь, пора использовать эту штуку.$b$bДухи говорили о древней смоле в Янтарной усыпальнице, пещере богомолов возле дворца их императрицы. Это, должно быть, "Кровь Древних", о которой говорит пророчество.$b$bВнутри этой смолы находится что-то важное. Удачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте двузубец разрушения на Ийокуке Проницательном, а затем защитите его, пока он не сможет спастись.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В этом куске янтаря был... богомол? Вот бы никогда не подумала, что ключом к победе в войне с богомолами станет богомол!$B$BВек живи, век учись, это правда. А кое-что я теперь знаю наверняка: это точно был не пивной рецепт.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ля Десять Песен в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31086,'Кровь Древних','Кое в чем мы с Ля совершенно согласны: "кровь Древних" – это наверняка смола здешних великих деревьев. Да и мне ли не знать! Я ведь постоянно использую ее при варке.$b$bСамое древнее из местных деревьев – дом великой императрицы Шек\'зир, который сейчас зовут Сердцем Страха. Добудь немного янтаря с того дерева, и варево будет готово!','Добудьте кусок затвердевшего янтаря.','В самый раз! Теперь все готово.$B$BПопробуем-ка это пиво...','Ну, как успехи?','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кое в чем мы с Ля совершенно согласны: "кровь Древних" – это наверняка смола здешних великих деревьев. Да и мне ли не знать! Я ведь постоянно использую ее при варке.$b$bСамое древнее из местных деревьев – дом великой императрицы Шек\'зир, который сейчас зовут Сердцем Страха. Добудь немного янтаря с того дерева, и варево будет готово!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кусок затвердевшего янтаря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В самый раз! Теперь все готово.$B$BПопробуем-ка это пиво...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к соковару Ву в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31087,'Усиление сигнала','Клакси\'ва стало известно еще об одном Идеале. Его голос слаб и глух, а значит, сигнал надо усилить!$b$bВ Янтарном зале есть башня-сонар, которая затихла очень давно. Ее песнь должна прозвучать вновь. Так приказали клакси!$b$bВ этот раз я пойду с тобой. Ты поможешь мне ее починить.$b$bВозьми резонирующий кристалл и найди меня там.','Активируйте резонирующий маячок в Янтарном зале.','Ты подоспел как раз вовремя.$B$BВозможно, пользы от тебя больше, чем мне казалось поначалу...$B$BПеснь клакси\'ва должна достичь Идеала. Совсем скоро они узнают, куда тебе нужно отправиться, а пока у нас есть и другие дела.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усиление сигнала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси\'ва стало известно еще об одном Идеале. Его голос слаб и глух, а значит, сигнал надо усилить!$b$bВ Янтарном зале есть башня-сонар, которая затихла очень давно. Ее песнь должна прозвучать вновь. Так приказали клакси!$b$bВ этот раз я пойду с тобой. Ты поможешь мне ее починить.$b$bВозьми резонирующий кристалл и найди меня там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте резонирующий маячок в Янтарном зале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты подоспел как раз вовремя.$B$BВозможно, пользы от тебя больше, чем мне казалось поначалу...$B$BПеснь клакси\'ва должна достичь Идеала. Совсем скоро они узнают, куда тебе нужно отправиться, а пока у нас есть и другие дела.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31088,'Преступление и наказание','Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.','Убейте 8 ик\'тиков-жнецов на Жгучей тропе.','Клакси очень довольны твоей работой чужестранец. Мы и не думали, что ты будешь нам столь полезен.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преступление и наказание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 ик\'тиков-жнецов на Жгучей тропе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клакси очень довольны твоей работой чужестранец. Мы и не думали, что ты будешь нам столь полезен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31089,'Уже не у моря','Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.','Поднесите камертон клакси к океаническим камням и пробудите Идеал.','Что ты за существо и как тебе удалось разбудить меня?','Поговорите с Каз\'тиком Манипулятором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уже не у моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднесите камертон клакси к океаническим камням и пробудите Идеал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ты за существо и как тебе удалось разбудить меня?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31090,'Чем старше, тем лучше','Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.','Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.','Даже этот сырой янтарь нам пригодится. В тяжелые времена выбирать не приходится.$B$BКлакси\'ва будут признательны за мою прозорливость. Я им расскажу и о твоей помощи.','Мне бы пойти с тобой за янтарем, но сейчас я нужнее здесь.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем старше, тем лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже этот сырой янтарь нам пригодится. В тяжелые времена выбирать не приходится.$B$BКлакси\'ва будут признательны за мою прозорливость. Я им расскажу и о твоей помощи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне бы пойти с тобой за янтарем, но сейчас я нужнее здесь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31091,'Воссоединение','Тот, кого ты видишь перед собой, не очень-то похож на воина, да? Так почему же его назвали Идеалом, думаешь ты... Не все оружие можно увидеть, Пробудитель. О книге по обложке не судят.$b$bНо мне нужно убедиться в твоей благонадежности, прежде чем я поясню, в чем дело.$b$bНезадолго до того, как я был погружен в сон, нечто драгоценное для меня было спрятано, без чего я ничего не стою.$b$bЗащити меня, пока я ищу мое величайшее оружие, и обретешь мое доверие.','Помогите Каз\'тику Манипулятору, пока он выкапывает свое величайшее оружие.','Ковок по-прежнему впечатляет. Он поможет клакси выиграть еще много битв.','Поговорите с Каз\'тиком Манипулятором на Соленой отмели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоединение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот, кого ты видишь перед собой, не очень-то похож на воина, да? Так почему же его назвали Идеалом, думаешь ты... Не все оружие можно увидеть, Пробудитель. О книге по обложке не судят.$b$bНо мне нужно убедиться в твоей благонадежности, прежде чем я поясню, в чем дело.$b$bНезадолго до того, как я был погружен в сон, нечто драгоценное для меня было спрятано, без чего я ничего не стою.$b$bЗащити меня, пока я ищу мое величайшее оружие, и обретешь мое доверие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Каз\'тику Манипулятору, пока он выкапывает свое величайшее оружие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ковок по-прежнему впечатляет. Он поможет клакси выиграть еще много битв.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором на Соленой отмели.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31092,'Покормить или стать обедом','Я долгие годы изучал куньчунов, и у меня появилась теория: если воспитывать их с детства, то связь между вами, в том числе звуковая, будет крепче.$b$bКогда меня решили заточить в янтаре, я только начал обучать Ковока. Он еще очень молод, и, чтобы раскрыть его потенциал, необходимы долгие тренировки.$b$bЯ доверю Ковока тебе, но запомни: если обидишь его, прощайся с жизнью.$b$bСначала надо накормить Ковока, чтобы завоевать его доверие. Для этого вполне подойдут черепахи, которые водятся в этих краях.','Начните обучение Ковока, скормив ему 6 порций сочного черепашьего филе. Его можно добыть, убивая океанических крепкохватов на Соленой отмели.','Очень хорошо! Меня бы не удивило, если бы Ковок тебя просто сожрал. Приятно видеть, что вы оба целы.$B$BВозможно, уход за куньчунами – это твое призвание.','Поговорите с Каз\'тиком Манипулятором в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покормить или стать обедом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я долгие годы изучал куньчунов, и у меня появилась теория: если воспитывать их с детства, то связь между вами, в том числе звуковая, будет крепче.$b$bКогда меня решили заточить в янтаре, я только начал обучать Ковока. Он еще очень молод, и, чтобы раскрыть его потенциал, необходимы долгие тренировки.$b$bЯ доверю Ковока тебе, но запомни: если обидишь его, прощайся с жизнью.$b$bСначала надо накормить Ковока, чтобы завоевать его доверие. Для этого вполне подойдут черепахи, которые водятся в этих краях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начните обучение Ковока, скормив ему 6 порций сочного черепашьего филе. Его можно добыть, убивая океанических крепкохватов на Соленой отмели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Меня бы не удивило, если бы Ковок тебя просто сожрал. Приятно видеть, что вы оба целы.$B$BВозможно, уход за куньчунами – это твое призвание.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31093,'Хозен в тумане','$gДорогой:Дорогая; $n!$b$bТвое исследование хозенов позволяет взглянуть на них под новым углом.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите работу "Хозен в тумане" хранителю истории Чо в Обитель Мудрости.','Хозены крайне раздражительны по своей природе.$B$BМы добавим эти сведения в твою коллекцию. Если захочешь, чтобы я все рассказал тебе, выбери нужный том из личной коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозен в тумане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bТвое исследование хозенов позволяет взглянуть на них под новым углом.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите работу "Хозен в тумане" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хозены крайне раздражительны по своей природе.$B$BМы добавим эти сведения в твою коллекцию. Если захочешь, чтобы я все рассказал тебе, выбери нужный том из личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31094,'Рыбьи байки','$gДорогой:Дорогая; $n!$b$bТвой труд о цзинь-юй доставил мне истинное наслаждение. Поразительный народ, и такой умный.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите книгу "Рыбьи хвосты" хранителю истории Чо в Обитель Мудрости.','Я всегда восторгался цзинь-юй. Такой мирный народ, так ценит мудрость.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыбьи байки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bТвой труд о цзинь-юй доставил мне истинное наслаждение. Поразительный народ, и такой умный.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Рыбьи хвосты" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я всегда восторгался цзинь-юй. Такой мирный народ, так ценит мудрость.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31095,'$gДорогой:Дорогая; $n!$b$bДавно известно, что могу – зловещий народ, их сердца полны мрака. Однако твое исследование показывает, что они еще хуже.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите книгу "Черное сердце могу" хранителю истории Чо в Обитель Мудрости.','Могу. От одного слова у меня шерсть дыбом становится. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bДавно известно, что могу – зловещий народ, их сердца полны мрака. Однако твое исследование показывает, что они еще хуже.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Черное сердце могу" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могу. От одного слова у меня шерсть дыбом становится. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31096,'За что стоит сражаться','$gДорогой:Дорогая; $n!$b$bТебе удалось раздобыть рассказ о том, как наш народ избавился от гнета могу.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите книгу "За что стоит сражаться" хранителю истории Чо в Обитель Мудрости.','Неужели битва за освобождение народа пандаренов началась с такой малости...$B$BПрекрасно. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За что стоит сражаться',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bТебе удалось раздобыть рассказ о том, как наш народ избавился от гнета могу.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "За что стоит сражаться" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели битва за освобождение народа пандаренов началась с такой малости...$B$BПрекрасно. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31097,'Сердце роя богомолов','$gДорогой:Дорогая; $n!$b$bМы ценим твои усилия по изучению истории и преданий Пандарии, но найденные тобой данные о богомолах попросту лишили меня сна. Пугающие сведения.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите книгу "Сердце роя богомолов" хранителю истории Чо в Обитель Мудрости.','Приступая к этому проекту, я никак не ожидал, что объекты изучения будут настолько захватывающими и устрашающими.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце роя богомолов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bМы ценим твои усилия по изучению истории и преданий Пандарии, но найденные тобой данные о богомолах попросту лишили меня сна. Пугающие сведения.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Сердце роя богомолов" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приступая к этому проекту, я никак не ожидал, что объекты изучения будут настолько захватывающими и устрашающими.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtex