INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31100,'Песнь яунголов','$gУважаемый:Уважаемая; $n.$b$bТвои исследования, касающиеся яунголов оказались очень проницательными.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите "Песнь яунголов" хранителю истории Чо в Обитель Мудрости.','Яунголы – воинственная раса, воспитанная в изгнании за стеной. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Песнь яунголов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gУважаемый:Уважаемая; $n.$b$bТвои исследования, касающиеся яунголов оказались очень проницательными.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Песнь яунголов" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Яунголы – воинственная раса, воспитанная в изгнании за стеной. Мы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31101,'Легенды древних хмелеваров','$gДорогой:Дорогая; $n.$b$bТвои исследования, касающиеся древних хмелеваров, пробудили в нас жажду к знаниям.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите "Легенды древних хмелеваров" хранителю истории Чо в Обитель Мудрости.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенды древних хмелеваров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n.$b$bТвои исследования, касающиеся древних хмелеваров, пробудили в нас жажду к знаниям.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Легенды древних хмелеваров" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31102,'Семь бремен Шаохао','$gДорогой:Дорогая; $n.$b$bТебе удалось восстановить полное сказание о Шаохао – последнем императоре Пандарии.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите "Семь бремен Шаохао" хранителю истории Чо в Обитель Мудрости.','Я давно хотел узнать эту историю. С тех пор, как Ша освободился, у меня в животе появилось чувство, что эта история была в центре всех событий.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семь бремен Шаохао',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n.$b$bТебе удалось восстановить полное сказание о Шаохао – последнем императоре Пандарии.$b$bЕсли ты посетишь нас в Обители Мудрости в Вечноцветущем доле, мы добавим этот вклад в исследования в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Семь бремен Шаохао" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я давно хотел узнать эту историю. С тех пор, как Ша освободился, у меня в животе появилось чувство, что эта история была в центре всех событий.$B$BМы добавим эту информацию в твою коллекцию. Если захочешь прослушать ее, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31103,'Баллада о Лю Лане','$gДорогой:Дорогая; $n!$b$bБлагодаря твоим исследованиям у нас, наконец, есть полная баллада о Лю Лане.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите "Балладу о Лю Лане" хранителю истории Чо в Обитель Мудрости.','Длинная история о Лю Лане и его Скитающемся острове. Отличное дополнение к твоей коллекции. Если захочешь послушать об этом, выбери нужный том в личной коллекции.','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баллада о Лю Лане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bБлагодаря твоим исследованиям у нас, наконец, есть полная баллада о Лю Лане.$b$bЕсли посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Балладу о Лю Лане" хранителю истории Чо в Обитель Мудрости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Длинная история о Лю Лане и его Скитающемся острове. Отличное дополнение к твоей коллекции. Если захочешь послушать об этом, выбери нужный том в личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31104,'Бойцовский круг: Ялия Мудрый Шепот','Бросьте вызов Ялии Мудрый Шепот и победите ее в бойцовском круге.','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: Ялия Мудрый Шепот',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов Ялии Мудрый Шепот и победите ее в бойцовском круге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31105,'Угроза могу','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31106,'Угроза могу','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики засекли большой отряд могу к северо-западу отсюда, на острове Шань\'цзэ Дао.$B$BНовости не из лучших, остров считался пустым.$B$BЧто еще хуже, они проводят какие-то зловещие опыты.$B$B$gНужен хорошо подготовленный:Нужна хорошо подготовленная:c; |3-6($c), чтобы оценить обстановку.$B$BЕсли Шань\'цзэ попробуют тебе помешать, можешь убить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 змееловов Шань\'цзэ или повелителей зверей Шань\'цзэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежье Сердце в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31107,'Граждане новой империи','По приказу Шек\'зир великое дерево Кипари Вор было превращено в тотем ужаса.$B$BТеперь эта кладка, как и те, что снаружи дворца, оскверняет роерожденных.$B$BДобудь яйца вор\'тиков, прежде чем их коснется скверна, и мы вырастим из них граждан новой империи, свободной от ша.','Соберите 10 яиц вор\'тиков у Кипари Вор.','Они уже большие, скоро начнут вылупляться.$B$BОтлично. Они могут нам пригодиться.','Когда-то дерево Кипари Вор было прекрасным. Оно давало много янтаря и было окружено богатыми дичью землями.','Вернитесь к Малику Невредимому в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Граждане новой империи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу Шек\'зир великое дерево Кипари Вор было превращено в тотем ужаса.$B$BТеперь эта кладка, как и те, что снаружи дворца, оскверняет роерожденных.$B$BДобудь яйца вор\'тиков, прежде чем их коснется скверна, и мы вырастим из них граждан новой империи, свободной от ша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 яиц вор\'тиков у Кипари Вор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они уже большие, скоро начнут вылупляться.$B$BОтлично. Они могут нам пригодиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда-то дерево Кипари Вор было прекрасным. Оно давало много янтаря и было окружено богатыми дичью землями.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малику Невредимому в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31108,'Воплощение страха','В янтаре заключена великая сила. Она порождает жизнь.$B$BНо этот янтарь испорчен. В нем сконцентрирован страх.$B$BВор\'тики знают это. Их кипари поражены ша, и смола дерева превращается в кристаллы концентрированного страха.$B$BПринеси их мне. Мы исследуем их и постараемся уничтожить.','Соберите 4 куска жуткого янтаря с вор\'тиков-жуткоревов в Кипари Вор.','Интересно, что будет, если ты съешь эту штуку? Что она сделает с твоими мягкими розовыми внутренностями?','Кристаллы у тебя?','Вернитесь к кователю янтаря Зикку в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воплощение страха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В янтаре заключена великая сила. Она порождает жизнь.$B$BНо этот янтарь испорчен. В нем сконцентрирован страх.$B$BВор\'тики знают это. Их кипари поражены ша, и смола дерева превращается в кристаллы концентрированного страха.$B$BПринеси их мне. Мы исследуем их и постараемся уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 куска жуткого янтаря с вор\'тиков-жуткоревов в Кипари Вор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно, что будет, если ты съешь эту штуку? Что она сделает с твоими мягкими розовыми внутренностями?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристаллы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кователю янтаря Зикку в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31109,'Уничтожение роя','Императрица продолжает наращивать свое войско. Если так будет продолжаться – они преодолеют стену. Заберутся на нее по трупам миллионов роерожденных.$B$BДавай найдем для их трупов место получше.$B$BДай мне знать, когда будешь $gготов:готова; отправиться во Владения Шек\'зир. Я помогу тебе добраться туда.','Уничтожьте 40 Шек\'зир-роерожденных во Владениях Шек\'зир. Поговорите с Кил\'руком Рассекающим Ветер, чтобы отправиться туда.','Достаточно. По крайней мере, пока.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Императрица продолжает наращивать свое войско. Если так будет продолжаться – они преодолеют стену. Заберутся на нее по трупам миллионов роерожденных.$B$BДавай найдем для их трупов место получше.$B$BДай мне знать, когда будешь $gготов:готова; отправиться во Владения Шек\'зир. Я помогу тебе добраться туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 40 Шек\'зир-роерожденных во Владениях Шек\'зир. Поговорите с Кил\'руком Рассекающим Ветер, чтобы отправиться туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Достаточно. По крайней мере, пока.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31110,'Через портал','Вот и |3-6($c), жду не дождусь!$B$BМы поняли, почему портал не работает. Надо больше чародейского порошка.$B$BМожно заказать, но это займет не один месяц... К счастью, порошка немало у могу на этом острове, им он тоже для заклинаний нужен.$B$BНо у них порошок староват, так что нужно много.','Соберите 1000 порций древнего чародейского порошка.','Великолепно!$B$BЭто именно то, что нужно, Астральный.$B$BМы немедленно приступим к работе. Несомненно, скоро нас ждет успех.','Удалось достать порошок?','Вернитесь к Мошу Чародею в Шань\'цзэ Дао, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Через портал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и |3-6($c), жду не дождусь!$B$BМы поняли, почему портал не работает. Надо больше чародейского порошка.$B$BМожно заказать, но это займет не один месяц... К счастью, порошка немало у могу на этом острове, им он тоже для заклинаний нужен.$B$BНо у них порошок староват, так что нужно много.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 1000 порций древнего чародейского порошка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно!$B$BЭто именно то, что нужно, Астральный.$B$BМы немедленно приступим к работе. Несомненно, скоро нас ждет успех.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать порошок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мошу Чародею в Шань\'цзэ Дао, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31111,'Битва с зан\'тиками','Должен признать, Пробудитель, я впечатлен.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва с зан\'тиками',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должен признать, Пробудитель, я впечатлен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31112,'Они такие колючие!','Ящик, когда-то полный очень нужных вещей, полностью разграблен.$b$bБеглый осмотр местности помог найти улики, оставленные воришками. Ледяные шипы, совсем как у водных духов с береговой линии к востоку отсюда.$b$bДля горстки выживших это вопрос жизни и смерти. Надо отнять похищенное у воришек и вернуть в лагерь.','Заберите 5 комплектов для оказания первой помощи у водных духов.','Только взгляните!$B$BЭти вещицы помогут нам продержаться еще несколько дней.$B$BИ мои ботинки! Они целы! Отличная работа, Хель!','Ну как, дорогуша, удалось тебе добраться до украденных вещичек?','Поговорите с Риветтом в Кулаке Адского Крика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они такие колючие!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ящик, когда-то полный очень нужных вещей, полностью разграблен.$b$bБеглый осмотр местности помог найти улики, оставленные воришками. Ледяные шипы, совсем как у водных духов с береговой линии к востоку отсюда.$b$bДля горстки выживших это вопрос жизни и смерти. Надо отнять похищенное у воришек и вернуть в лагерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 5 комплектов для оказания первой помощи у водных духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только взгляните!$B$BЭти вещицы помогут нам продержаться еще несколько дней.$B$BИ мои ботинки! Они целы! Отличная работа, Хель!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, дорогуша, удалось тебе добраться до украденных вещичек?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом в Кулаке Адского Крика.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31113,'Напасть на огненный лагерь Гай-Чо','Яунголы докучают нам постоянно, но отряд, который собрался на северо-востоке, в лагере Гай-Чо, вместе с осулами участвовал в последнем налете на Кунь-Лай.\r\n\r\nНалетчиков следует покарать.\r\n\r\nИди и атакуй лагерь Гай-Чо. Ты отвлечешь их, чтобы враг у Врат Быка не дождался подкреплений.','Убейте 16 яунголов Гай-Чо, толкователей земли или метателей смолы.','Что ж, на некоторое время это их отвадит. Отлично, Тормунд.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напасть на огненный лагерь Гай-Чо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы докучают нам постоянно, но отряд, который собрался на северо-востоке, в лагере Гай-Чо, вместе с осулами участвовал в последнем налете на Кунь-Лай.\r\n\r\nНалетчиков следует покарать.\r\n\r\nИди и атакуй лагерь Гай-Чо. Ты отвлечешь их, чтобы враг у Врат Быка не дождался подкреплений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 яунголов Гай-Чо, толкователей земли или метателей смолы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, на некоторое время это их отвадит. Отлично, Тормунд.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31114,'Напасть на Плато Говорящего с Мертвыми','Мы никогда не трогали говорящих с мертвыми. Они проводили священные погребальные ритуалы в племенах яунголов.\r\n\r\nНо теперь они прибегают к темной магии, оскверняя тела своих бывших соплеменников...\r\n\r\nЯ не знаю, ни где они нашли эти ритуалы, ни почему они позволяют себе осквернять тела погибших соратников, и выяснять это некогда.\r\n\r\nИх нужно остановить.','Убейте 8 говорящих с мертвыми – осквернителей праха и 1 говорящего с мертвыми – крушителя.','Решившись прибегнуть к темной магии, говорящие с мертвыми сами лишили себя права на защиту. Теперь, надеюсь, они одумаются.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напасть на Плато Говорящего с Мертвыми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы никогда не трогали говорящих с мертвыми. Они проводили священные погребальные ритуалы в племенах яунголов.\r\n\r\nНо теперь они прибегают к темной магии, оскверняя тела своих бывших соплеменников...\r\n\r\nЯ не знаю, ни где они нашли эти ритуалы, ни почему они позволяют себе осквернять тела погибших соратников, и выяснять это некогда.\r\n\r\nИх нужно остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 говорящих с мертвыми – осквернителей праха и 1 говорящего с мертвыми – крушителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Решившись прибегнуть к темной магии, говорящие с мертвыми сами лишили себя права на защиту. Теперь, надеюсь, они одумаются.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31115,'FLAG - Freed Han') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Freed Han',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31116,'Пыль духов','Яунголы поймали в ловушку духов своих предков. Но у духов еще осталось немного сущности жизни.\r\n\r\nЕсли тебе удастся победить их в бою, эта сущность достанется тебе в виде пыли. Посыпь этой пылью могилы, и духи смогут обрести новую жизнь.\r\n\r\nТолько так можно исправить то, что натворили толкователи мертвых. И нам будет поспокойней.','Верните 8 духов к их телам на Плато Говорящего с Мертвыми, что в Танлунских степях.','Хорошо. Нам удалось уладить это дело.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пыль духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яунголы поймали в ловушку духов своих предков. Но у духов еще осталось немного сущности жизни.\r\n\r\nЕсли тебе удастся победить их в бою, эта сущность достанется тебе в виде пыли. Посыпь этой пылью могилы, и духи смогут обрести новую жизнь.\r\n\r\nТолько так можно исправить то, что натворили толкователи мертвых. И нам будет поспокойней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 8 духов к их телам на Плато Говорящего с Мертвыми, что в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Нам удалось уладить это дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31117,'Урук!','Говорящего с мертвыми Танлунских степей зовут Уруком. Твоя задача не будет завершена, пока он жив. Иди же!','Убейте Урука на Плато Говорящего с Мертвыми в Танлунских степях.','Урук мертв! Угроза миновала, хотя бы на ближайший день. Спасибо тебе, Тормунд.','Поговорите с мастером Снежным Вихрем в гарнизоне Шадо-Пан, что в Танлунских степях.','Порочный говорящий с мертвыми танлунских яунголов','Урук') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урук!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорящего с мертвыми Танлунских степей зовут Уруком. Твоя задача не будет завершена, пока он жив. Иди же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Урука на Плато Говорящего с Мертвыми в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Урук мертв! Угроза миновала, хотя бы на ближайший день. Спасибо тебе, Тормунд.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Снежным Вихрем в гарнизоне Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Порочный говорящий с мертвыми танлунских яунголов',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Урук',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31118,'Шифр говорящих с мертвыми','Нам нужно разобраться, что пошло не так с говорящими с мертвыми.\r\n\r\nМного лет говорящие с мертвыми просто приглядывали за кладбищами и хоронили павших воинов.\r\n\r\nНо в последний раз мы нашли скрижаль, которая покрыта зашифрованными надписями, но шифр какой-то другой. Если тебе удастся завладеть каким-нибудь свитком, где используется этот же шифр, мы сможем разобраться в том, что происходит.','Заберите у яунголов с Плато Говорящего с Мертвыми свиток с ритуалами ловли душ.','Ага! Дай-ка мне посмотреть.$B$BХм, нужно отправить свиток в монастырь для изучения. Если проанализировать, какие из этих символов встречаются чаще всего, мы сможем приблизиться к расшифровке этого текста.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шифр говорящих с мертвыми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно разобраться, что пошло не так с говорящими с мертвыми.\r\n\r\nМного лет говорящие с мертвыми просто приглядывали за кладбищами и хоронили павших воинов.\r\n\r\nНо в последний раз мы нашли скрижаль, которая покрыта зашифрованными надписями, но шифр какой-то другой. Если тебе удастся завладеть каким-нибудь свитком, где используется этот же шифр, мы сможем разобраться в том, что происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите у яунголов с Плато Говорящего с Мертвыми свиток с ритуалами ловли душ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Дай-ка мне посмотреть.$B$BХм, нужно отправить свиток в монастырь для изучения. Если проанализировать, какие из этих символов встречаются чаще всего, мы сможем приблизиться к расшифровке этого текста.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31119,'Враг моего врага... все равно мой враг!','Богомолы нам враги. Яунголы из огненного лагеря Гай-Чо – тоже.\r\n\r\nНо и друг с другом они не ладят. Богомолы из Кри\'весса постоянно нападают на яунголов Гай-Чо, но дальше ворот прорваться не могут.\r\n\r\nТвое дело – перевернуть все вверх дном. Позаимствуй в огненном лагере Гай-Чо взрывоопасные бочки с нефтью и сбрось их сверху на поле боя.\r\n\r\nНеважно, кто именно пострадает, лишь бы погибло как можно больше народу.','С помощью взрывоопасных бочек с яунгольской нефтью убейте 100 богомолов или яунголов на поле битвы Гай-Чо.','Ха! Молодчина. Будут знать, каково быть врагами Шадо-пан.','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг моего врага... все равно мой враг!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы нам враги. Яунголы из огненного лагеря Гай-Чо – тоже.\r\n\r\nНо и друг с другом они не ладят. Богомолы из Кри\'весса постоянно нападают на яунголов Гай-Чо, но дальше ворот прорваться не могут.\r\n\r\nТвое дело – перевернуть все вверх дном. Позаимствуй в огненном лагере Гай-Чо взрывоопасные бочки с нефтью и сбрось их сверху на поле боя.\r\n\r\nНеважно, кто именно пострадает, лишь бы погибло как можно больше народу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью взрывоопасных бочек с яунгольской нефтью убейте 100 богомолов или яунголов на поле битвы Гай-Чо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Молодчина. Будут знать, каково быть врагами Шадо-пан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вашим спутником Шадо-Пан на поле или вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31120,'Чэн Бо!','Вестника войны огненного лагеря Гай-Чо зовут Чэн Бо. Тебе удалось сорвать немало планов противника, а теперь тебе выпала честь нанести страшный удар.\r\n\r\nУбей вестника войны!','Убейте Чэна Бо в огненном лагере Гай-Чо в Танлунских степях.','Теперь, когда Чэн Бо повержен, мы можем сконцентрировать силы на борьбе с оставшимися врагами. Твои усилия достойны уважения, Тормунд.','Поговорите с мастером Снежным Вихрем в гарнизоне Шадо-Пан, что в Танлунских степях.','Вестник войны яунголов Гай-Чо','Чэн Бо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чэн Бо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вестника войны огненного лагеря Гай-Чо зовут Чэн Бо. Тебе удалось сорвать немало планов противника, а теперь тебе выпала честь нанести страшный удар.\r\n\r\nУбей вестника войны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Чэна Бо в огненном лагере Гай-Чо в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда Чэн Бо повержен, мы можем сконцентрировать силы на борьбе с оставшимися врагами. Твои усилия достойны уважения, Тормунд.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Снежным Вихрем в гарнизоне Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Вестник войны яунголов Гай-Чо',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чэн Бо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31121,'Постой и послушай','Быстрей, быстрей – ваш народ всегда так торопится?$b$bСядь и выпей со мной чаю, и мы обсудим ваше затруднительное положение.$b$b<Хранитель истории Чо терпеливо улыбается.>','Выпейте чая из чайника Чо.','Я помогу тебе, но сначала я хочу немного узнать о вашей Орде...','Поговорите с хранителем истории Чо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Постой и послушай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрей, быстрей – ваш народ всегда так торопится?$b$bСядь и выпей со мной чаю, и мы обсудим ваше затруднительное положение.$b$b<Хранитель истории Чо терпеливо улыбается.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте чая из чайника Чо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я помогу тебе, но сначала я хочу немного узнать о вашей Орде...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо.',`completedtext_loc8`);
