INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31126,'Unlocked Lao-Chen') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Unlocked Lao-Chen',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31127,'Бойцовский круг: Чао Голосистая','Ты кажешься хорошим бойцом, $n.\r\n\r\nОб этом прослышала Чао, теперь она хвалится, что надерет тебе...\r\n\r\nКороче, тебе стоит вызвать ее на бой и попытаться завоевать ее уважение.','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Чао Голосистую и победите ее.','Не думаю, что она очень расстроилась, она слишком любит хорошую драку.$B$BТебе стоит поговорить с ней, как только подвернется возможность. Она прекрасный боец, это видно сразу.','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.','Могучий (и громкоголосый) черный страж Шадо-Пан','Чао Голосистая') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: Чао Голосистая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты кажешься хорошим бойцом, $n.\r\n\r\nОб этом прослышала Чао, теперь она хвалится, что надерет тебе...\r\n\r\nКороче, тебе стоит вызвать ее на бой и попытаться завоевать ее уважение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Чао Голосистую и победите ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думаю, что она очень расстроилась, она слишком любит хорошую драку.$B$BТебе стоит поговорить с ней, как только подвернется возможность. Она прекрасный боец, это видно сразу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Могучий (и громкоголосый) черный страж Шадо-Пан',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чао Голосистая',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31128,'Бойцовский круг: Лао-Чинь Стальное Брюхо','Лао-Чинь почти все время витает в облаках... и обычно в пивных.\r\n\r\nПосле всех этих битв он загорелся идеей создать пиво для сражения.\r\n\r\nЭто прекрасно, конечно, но собственно сражаться-то кто будет?!\r\n\r\nСловом, вызови его на бой, может, тебе удастся вернуть его на землю.\r\n\r\nЕсли ты победишь, с него станется продолжить бой снаружи, лишь бы обставить тебя!','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Лао-Чиня Стальное Брюхо и победите его.','Лао-Чинь никак в себя не придет. Все говорит, с каким бойцом пришлось сразиться да как бы повторить. Это то, что нужно.','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: Лао-Чинь Стальное Брюхо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лао-Чинь почти все время витает в облаках... и обычно в пивных.\r\n\r\nПосле всех этих битв он загорелся идеей создать пиво для сражения.\r\n\r\nЭто прекрасно, конечно, но собственно сражаться-то кто будет?!\r\n\r\nСловом, вызови его на бой, может, тебе удастся вернуть его на землю.\r\n\r\nЕсли ты победишь, с него станется продолжить бой снаружи, лишь бы обставить тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Лао-Чиня Стальное Брюхо и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лао-Чинь никак в себя не придет. Все говорит, с каким бойцом пришлось сразиться да как бы повторить. Это то, что нужно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31129,'Судьба семейства Буйный Портер','$n! Так приятно видеть тебя в добром здравии в таких дальних краях. Кажется, наши пути крепко переплелись между собой.$b$bЯ ищу здесь свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу найти их и присоединиться.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?','Спросить у обитателей хмелеваренного дворика "На закате", не видели ли они Буйных Портеров.','<Чэнь внимательно слушает.>$B$BЗдоровяк Дань, Хань, Эви и Мамаша. Я понял.$B$BДумаю, Дань будет здесь в безопасности. Я поищу Эви, Ханя и Мамашу Буйный Портер.$B$BБереги себя, Астральный.','Вернитесь к Чэню Буйному Портеру в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба семейства Буйный Портер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Так приятно видеть тебя в добром здравии в таких дальних краях. Кажется, наши пути крепко переплелись между собой.$b$bЯ ищу здесь свою семью. Мне сказали, что несколько Буйных Портеров перешли через стену, чтобы помочь справиться с богомолами. Я хочу найти их и присоединиться.$b$bНе проходил ли здесь кто-нибудь по имени Буйный Портер? Можешь помочь мне расспросить здешних жителей?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спросить у обитателей хмелеваренного дворика "На закате", не видели ли они Буйных Портеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Чэнь внимательно слушает.>$B$BЗдоровяк Дань, Хань, Эви и Мамаша. Я понял.$B$BДумаю, Дань будет здесь в безопасности. Я поищу Эви, Ханя и Мамашу Буйный Портер.$B$BБереги себя, Астральный.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чэню Буйному Портеру в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31130,'Визит к хранителю истории Чо','$gНезнакомец:Незнакомка;, я могу помочь тебе найти твоего принца. Но сначала я хочу больше узнать о тебе и твоем народе.$B$BПомоги мне закончить дела, и мы поговорим.$B$BУ тебя взгляд убеленного сединой ветерана многих войн, но наверняка у тебя найдется пара минут, чтобы помочь пандарену-книголюбу вроде меня прибраться в доме, правда?','Подружитесь с хранителем истории Чо, оказав ему помощь по дому: подстригите дерево, покрасьте стену, накормите птиц.','Несмотря на годы, проведенные в боях, ты все еще тонко чувствуешь прекрасное, Торгашонка. Мне это нравится!$B$BДавай теперь найдем твоего пропавшего принца.','Поговорите с хранителем истории Чо в Павильоне Мечтателя в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к хранителю истории Чо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gНезнакомец:Незнакомка;, я могу помочь тебе найти твоего принца. Но сначала я хочу больше узнать о тебе и твоем народе.$B$BПомоги мне закончить дела, и мы поговорим.$B$BУ тебя взгляд убеленного сединой ветерана многих войн, но наверняка у тебя найдется пара минут, чтобы помочь пандарену-книголюбу вроде меня прибраться в доме, правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подружитесь с хранителем истории Чо, оказав ему помощь по дому: подстригите дерево, покрасьте стену, накормите птиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Несмотря на годы, проведенные в боях, ты все еще тонко чувствуешь прекрасное, Торгашонка. Мне это нравится!$B$BДавай теперь найдем твоего пропавшего принца.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Павильоне Мечтателя в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31131,'Озеро Белых Лепестков','Согласно отчетам, сегодня на Озере Белых Лепестков тихо. Но я все равно отправил туда Жэня Огненного Языка и Хэ Легкую Ногу, чтобы убедиться, что все в порядке.$B$BЕсли хочешь помочь, отправляйся на запад, к озеру, встреться с Хэ и помоги ему надежно защитить озеро от угроз.','Поговорите с Хэ Легкой Ногой у Озера Белых Лепестков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Озеро Белых Лепестков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно отчетам, сегодня на Озере Белых Лепестков тихо. Но я все равно отправил туда Жэня Огненного Языка и Хэ Легкую Ногу, чтобы убедиться, что все в порядке.$B$BЕсли хочешь помочь, отправляйся на запад, к озеру, встреться с Хэ и помоги ему надежно защитить озеро от угроз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хэ Легкой Ногой у Озера Белых Лепестков.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31132,'Попробуй побыть мной','Ой, куда подевались мои манеры? Формально, я считаюсь тут хозяином.$b$bПозволь рассказать немного о себе и моем народе, а потом я задам вопросы уже тебе.','Поговорите с хранителем истории Чо у Круга Кости.','Подозреваю, что лучший способ объяснить, что такое хранитель истории – это показать тебе...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попробуй побыть мной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой, куда подевались мои манеры? Формально, я считаюсь тут хозяином.$b$bПозволь рассказать немного о себе и моем народе, а потом я задам вопросы уже тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо у Круга Кости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подозреваю, что лучший способ объяснить, что такое хранитель истории – это показать тебе...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31133,'Агрессия кор\'тик','Я не хмелевар... только от взгляда на все эти ингредиенты голова кружится. Просто пусть ставят пиво передо мной, когда оно готово, и на том спасибо.$b$bНет, я слежу за тем, чтобы хмелеваров не порубили, пока они пытаются сделать идеальное пиво. Это нелегко.$b$bБогомолы кор\'тик с той стороны водоема атакуют нас по ночам. Если ты и так идешь туда, может, вернешь им должок и нападешь на них в ответ?','Вернитесь к Защитнику Аззо в хмелеваренный дворик "На закате", что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агрессия кор\'тик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не хмелевар... только от взгляда на все эти ингредиенты голова кружится. Просто пусть ставят пиво передо мной, когда оно готово, и на том спасибо.$b$bНет, я слежу за тем, чтобы хмелеваров не порубили, пока они пытаются сделать идеальное пиво. Это нелегко.$b$bБогомолы кор\'тик с той стороны водоема атакуют нас по ночам. Если ты и так идешь туда, может, вернешь им должок и нападешь на них в ответ?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Защитнику Аззо в хмелеваренный дворик "На закате", что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31134,'Если бы камни могли говорить','Это очень древнее место.$b$bЛишь недавно я собрал воедино метод перевода забытого языка, на котором вырезаны надписи на этих камнях.$b$bО, радость открытий! Она всегда в новинку, могу заверить.$b$bВот, ты гость. Тебе достается самая почетная роль. Я настаиваю.$b$bЭтим ключом ты откроешь секреты, которые хранят эти камни.','Используйте каменные монолиты в Круге Кости.','На сегодня хватит перевода, пожалуй.$B$BНадеюсь, этот опыт помог многое прояснить.','Поговорите с хранителем истории Чо у Круга Кости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если бы камни могли говорить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это очень древнее место.$b$bЛишь недавно я собрал воедино метод перевода забытого языка, на котором вырезаны надписи на этих камнях.$b$bО, радость открытий! Она всегда в новинку, могу заверить.$b$bВот, ты гость. Тебе достается самая почетная роль. Я настаиваю.$b$bЭтим ключом ты откроешь секреты, которые хранят эти камни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте каменные монолиты в Круге Кости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня хватит перевода, пожалуй.$B$BНадеюсь, этот опыт помог многое прояснить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо у Круга Кости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31136,'За линией обороны','От разведчиков дошли вести о том, что мощный Империон проскользнул сквозь нашу линию обороны на юге и сейчас направляется в восточную долину.$B$BМне нужен тот, кому можно доверять, чтобы остановить это существо. Найди его и убей как можно быстрее, $n.','Убейте Генерала Темуджа.','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За линией обороны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От разведчиков дошли вести о том, что мощный Империон проскользнул сквозь нашу линию обороны на юге и сейчас направляется в восточную долину.$B$BМне нужен тот, кому можно доверять, чтобы остановить это существо. Найди его и убей как можно быстрее, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Генерала Темуджа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Левену Рассветному Клинку в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31137,'Встретиться с главным механиком','Представьтесь главному механику Меггакруту в Новом Городе Механиков.','Представьтесь главному механику Меггакруту в Новом Городе Механиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встретиться с главным механиком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Представьтесь главному механику Меггакруту в Новом Городе Механиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Представьтесь главному механику Меггакруту в Новом Городе Механиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (31139,'Дать отпор!','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что находится в Элвиннском лесу.','Боевой ворг клана Черной горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дать отпор!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что находится в Элвиннском лесу.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Боевой ворг клана Черной горы',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (31140,'Волки и овцы','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что находится в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волки и овцы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что находится в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`questgivertargetname_loc8`) VALUES (31143,'В бой!','Сержант Виллем') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бой!',`title_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сержант Виллем',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (31143,'Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, мы и правда в западне. Я опасаюсь снова посылать туда солдат, так как и они могут погибнуть. Мне нужен доброволец, кто-то, кто рискнет своей жизнью!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31144,'Враг подослал наемных убийц','Прикончите 8 гоблинов-убийц.','Вернитесь к сержанту Виллему, находящемуся позади Аббатства Североземья в Элвиннском лесу.','Это гоблин-убийца. Подлое маленькое создание!','Гоблин-убийца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг подослал наемных убийц',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикончите 8 гоблинов-убийц.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Виллему, находящемуся позади Аббатства Североземья в Элвиннском лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это гоблин-убийца. Подлое маленькое создание!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Гоблин-убийца',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31146,'Простой свиток','Пока ты разбирался с Плетью, тебе пришел свиток. Его принесла пандарен по имени Тин. Может, вы, монахи, и понимаете эти каракули, но я ничего не могу разобрать. Поговори с Тин, она в таверне.','Прочтите изящный свиток и поговорите с Тин Крепкий Желудок в Похоронном Звоне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простой свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты разбирался с Плетью, тебе пришел свиток. Его принесла пандарен по имени Тин. Может, вы, монахи, и понимаете эти каракули, но я ничего не могу разобрать. Поговори с Тин, она в таверне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите изящный свиток и поговорите с Тин Крепкий Желудок в Похоронном Звоне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31147,'Лапа тигра','На пути к мастерству испытаниям подвергнется твои тело и дух. Ты откроешь в себе новые способности, о которых ранее и не $gподозревал:подозревала;. Иди же и работай над собой, и вскоре ты овладеешь ударом тигра. Затем отточи новое умение на тренировочном манекене.','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра", затем испытайте его на тренировочном манекене.','Вернитесь к Тину Крепкому Желудку в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На пути к мастерству испытаниям подвергнется твои тело и дух. Ты откроешь в себе новые способности, о которых ранее и не $gподозревал:подозревала;. Иди же и работай над собой, и вскоре ты овладеешь ударом тигра. Затем отточи новое умение на тренировочном манекене.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра", затем испытайте его на тренировочном манекене.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тину Крепкому Желудку в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31148,'Новобранец Элрет','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новобранец Элрет',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с новобранцем Элрет в Похоронном Звоне, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31150,'Изящная руна','$n, меня попросили передать тебе вот эту руну. Изучи ее, когда будет времечко. Думаю, ее прислал наш гость издалека, Ло. Взгляни на нее и отыщи его в Старой Наковальне.','Изучите изящную руну и поговорите с Ло в Холодной долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изящная руна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, меня попросили передать тебе вот эту руну. Изучи ее, когда будет времечко. Думаю, ее прислал наш гость издалека, Ло. Взгляни на нее и отыщи его в Старой Наковальне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите изящную руну и поговорите с Ло в Холодной долине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31151,'Бей, снова бей, разум всего сильней!','Правда в том, что у тебя уже есть талант и способности, чтобы изучить необходимое. Как я могу помочь тебе? Показать, как правильно применить твои таланты.\r\n\r\nСначала тебе нужно тренироваться до тех пор, пока ты не начнешь понимать суть новой техники. И первой техникой, которую ты выучишь, будет "Лапа тигра". Вперед, тренируйся, пока не откроешь свой внутренний потенциал, а затем оттачивай новый прием!\r\n\r\nПомни: разум всего сильней!','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра", а затем испытайте этот прием на одном из тренировочных манекенов рядом с входом в Старую Наковальню.','Вернитесь к Ло в Старую Наковальню.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бей, снова бей, разум всего сильней!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Правда в том, что у тебя уже есть талант и способности, чтобы изучить необходимое. Как я могу помочь тебе? Показать, как правильно применить твои таланты.\r\n\r\nСначала тебе нужно тренироваться до тех пор, пока ты не начнешь понимать суть новой техники. И первой техникой, которую ты выучишь, будет "Лапа тигра". Вперед, тренируйся, пока не откроешь свой внутренний потенциал, а затем оттачивай новый прием!\r\n\r\nПомни: разум всего сильней!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра", а затем испытайте этот прием на одном из тренировочных манекенов рядом с входом в Старую Наковальню.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ло в Старую Наковальню.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31152,'Взгляд в прошлое','Минуточку. Я только соберу вещи.$b$bНе хотелось бы сейчас потерять эти записи, верно? Особенно после того, как ты за них чуть жизнью и здоровьем не $gпоплатился:поплатилась;!$b$bВот, все на месте. Отправляемся?$b$bНадо сказать, увидев, как ты $gрасправился:расправилась; с тем сауроком, я теперь не так беспокоюсь за наше путешествие!','Поговорите с хранителем истории Чо у Круга Камня.','Я весьма признателен за те знания, которые мои предшественники передали мне.$B$BЭто неоценимая помощь для меня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взгляд в прошлое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Минуточку. Я только соберу вещи.$b$bНе хотелось бы сейчас потерять эти записи, верно? Особенно после того, как ты за них чуть жизнью и здоровьем не $gпоплатился:поплатилась;!$b$bВот, все на месте. Отправляемся?$b$bНадо сказать, увидев, как ты $gрасправился:расправилась; с тем сауроком, я теперь не так беспокоюсь за наше путешествие!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо у Круга Камня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я весьма признателен за те знания, которые мои предшественники передали мне.$B$BЭто неоценимая помощь для меня.',`offerrewardtext_loc8`);
