INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31156,'Покрытый письменами пергамент','О, пока тебя не было, тут прислали пергамент, $n.$B$BПрочти на досуге. Если не ошибаюсь, он от нашего друга-пандарена Гато. Он прибыл издалека, чтобы поделиться мудростью и обучить нас искусству монахов. Не опозорь свой народ, достойно прояви себя на его уроках!','Прочтите покрытый письменами пергамент и поговорите с Гато в Долине Испытаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами пергамент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, пока тебя не было, тут прислали пергамент, $n.$B$BПрочти на досуге. Если не ошибаюсь, он от нашего друга-пандарена Гато. Он прибыл издалека, чтобы поделиться мудростью и обучить нас искусству монахов. Не опозорь свой народ, достойно прояви себя на его уроках!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите покрытый письменами пергамент и поговорите с Гато в Долине Испытаний.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31157,'Лапа тигра','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен и два раза опробуйте на нем "Лапу тигра".','Вернитесь к Гато в Долине Испытаний в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа тигра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен и два раза опробуйте на нем "Лапу тигра".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гато в Долине Испытаний в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31158,'Азы мастерства: поражение цели','Ну ладно, $gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.','Уничтожьте 6 манекенов-тики.','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азы мастерства: поражение цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $gдружище:подруга;. Начнем с азов. Посмотрим, как ты владеешь этим своим оружьицем.$B$BПопробуй-ка разнести в щепки вон те манекены-тики. Не торопись. Делай, как получится. А я посмотрю, как ты дерешься и что с этим можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 манекенов-тики.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31159,'Возрождение Черного Копья','Племя Черного Копья долго угнетали. Мы изгнанники. Раз от раза мы покидали дома... Но этот раз мы не убегать.$B$BВол\'джин предложил возглавлять нас мудростью и благодаря тому мы живы. Та мудрость предостерегает о хаосе что будет у Орды под Гаррош Адский Крик.$B$BНет. Этот раз мы не убегать. Этот раз мы защищать дома.$B$BНужно тренироваться, $n. Ищи Забракса на востоке.','Встретьтесь с Забраксом на тренировочной площадке Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Черного Копья долго угнетали. Мы изгнанники. Раз от раза мы покидали дома... Но этот раз мы не убегать.$B$BВол\'джин предложил возглавлять нас мудростью и благодаря тому мы живы. Та мудрость предостерегает о хаосе что будет у Орды под Гаррош Адский Крик.$B$BНет. Этот раз мы не убегать. Этот раз мы защищать дома.$B$BНужно тренироваться, $n. Ищи Забракса на востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Забраксом на тренировочной площадке Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31160,'Практическое занятие','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.','Добудьте 6 шкур буйногривой рыси.','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Практическое занятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора применить все эти умения на практике, $gдружище:подруга;. Для начала дам простое задание.$B$BСмотри, рыси убивают кабанов. А кабаны – наш продовольственный запас, и как-то вовсе не хочется им делиться. Если желаешь сегодня поужинать, кабаны должны быть живы. По крайней мере, до вечера.$B$BРыси здесь повсюду. Принеси мне побольше их шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 шкур буйногривой рыси.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31161,'Яма испытаний','Ты уже многому $gнаучился:научилась;, |3-6($c). Конечно, это еще не все. Но мы больше не будем практиковаться на манекенах-тики. Просто жаль тратить время...$B$BДавай-ка испробуем твои силы на настоящем противнике. На том, кто будет биться до смерти. Иди в яму испытаний – там тебе подберут соперника. Скажи тюремщику, когда будешь $gготов:готова;.','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже многому $gнаучился:научилась;, |3-6($c). Конечно, это еще не все. Но мы больше не будем практиковаться на манекенах-тики. Просто жаль тратить время...$B$BДавай-ка испробуем твои силы на настоящем противнике. На том, кто будет биться до смерти. Иди в яму испытаний – там тебе подберут соперника. Скажи тюремщику, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с тюремщиком Черного Копья, а затем спуститесь в яму испытаний и убейте пленного разведчика из клана Злобной Чешуи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Забраксу на тренировочную площадку Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31163,'Превосходя ожидания','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.','Поговорите с Вол\'джином в крепости Черного Копья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходя ожидания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты превосходишь все наши ожидания, так что хватит ходить в новичках – самое время взяться за что-нибудь серьезное.$B$BОтправляйся в деревню, что к юго-востоку отсюда, и начинай выполнять различные поручения. Будь на виду – и тебе быстро предложат серьезную работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вол\'джином в крепости Черного Копья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31165,'Каллиграфическая записка','Всего минуту назад тебя искала посыльная, $n! Думаю, она от нашего гостя-пандарена Шоюя. Тебе следует прочитать это.','Прочтите каллиграфическую записку и поговорите с Шоюем в Лагере Нараче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каллиграфическая записка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всего минуту назад тебя искала посыльная, $n! Думаю, она от нашего гостя-пандарена Шоюя. Тебе следует прочитать это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите каллиграфическую записку и поговорите с Шоюем в Лагере Нараче.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31166,'Лапа тигра','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен в Лагере Нараче и отработайте этот прием.','Вернитесь к Шоюю в лагерь Нараче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа тигра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен в Лагере Нараче и отработайте этот прием.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шоюю в лагерь Нараче.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31167,'Фамильное древо','Итак, теперь ты знаешь о этом, $gстранник:странница;. По крайней мере, достаточно для первого знакомства, не так ли?$b$bНу, а ты? Твой народ сильно отличается от моего?$b$bУ нас непременно должно быть что-то общее. Давай-ка посмотрим...','Зажгите связку благовоний в Круге Камня.','Не так уж мы с тобой и отличаемся.$B$BЯ верю, что мы можем стать хорошими друзьями.','Поговорите с хранителем истории Чо у Круга Камня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фамильное древо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, теперь ты знаешь о этом, $gстранник:странница;. По крайней мере, достаточно для первого знакомства, не так ли?$b$bНу, а ты? Твой народ сильно отличается от моего?$b$bУ нас непременно должно быть что-то общее. Давай-ка посмотрим...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите связку благовоний в Круге Камня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не так уж мы с тобой и отличаемся.$B$BЯ верю, что мы можем стать хорошими друзьями.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо у Круга Камня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31168,'Покрытый письменами знак','Этот знак передал мне посланец нашего гостя-пандарена, Лаоси. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и затем отправляйся с ним к Лаоси.','Поговорите с Лаоси в Альдрассиле, что в Тенистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами знак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот знак передал мне посланец нашего гостя-пандарена, Лаоси. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и затем отправляйся с ним к Лаоси.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лаоси в Альдрассиле, что в Тенистой долине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31169,'Искусство монахов','Истинный секрет искусства монаха заключается в том, чтобы открывать внутри себя знания и силу.$B$BИди, набирайся опыта и учи новые умения. Затем покажи их на одном из тренировочных манекенов.','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Поищите тренировочный манекен и попрактикуйтесь в использовании этого приема на нем.','Вернитесь к Лаоси на Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство монахов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Истинный секрет искусства монаха заключается в том, чтобы открывать внутри себя знания и силу.$B$BИди, набирайся опыта и учи новые умения. Затем покажи их на одном из тренировочных манекенов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Поищите тренировочный манекен и попрактикуйтесь в использовании этого приема на нем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лаоси на Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31170,'Наставник монахов','По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных монахов на Острове Солнечного Скитальца тренирует Пао, наша гостья-пандарен. Поговори с ней, может быть, она сможет тебя чему-нибудь научить.$B$BПао, как и все наставники Острова Солнечного Скитальца, находится в нижней части Солнечного Шпиля.','Поговорите с Пао, наставником монахов, в Солнечном Шпиле на Острове Солнечного Скитальца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник монахов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По мере того, как ты будешь набираться опыта, ты наверняка захочешь получить полезные знания от наставника своего класса. Юных монахов на Острове Солнечного Скитальца тренирует Пао, наша гостья-пандарен. Поговори с ней, может быть, она сможет тебя чему-нибудь научить.$B$BПао, как и все наставники Острова Солнечного Скитальца, находится в нижней части Солнечного Шпиля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Пао, наставником монахов, в Солнечном Шпиле на Острове Солнечного Скитальца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31171,'Лапа тигра','Хорошо. Тебя ждет яркое начало пути. Дорога будет долгой, и, чем большего ты сможешь достигнуть, тем проще будут даваться умения, о которых ты раньше даже не $gмечтал:мечтала;.$B$BИди, получи новый опыт и изучи новую технику. Затем продемонстрируй ее на одном из тренировочных манекенов.','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен рядом с Солнечным Шпилем и отработайте этот прием.','Вернитесь к Pao на Солнечный Шпиль на Остров Солнечного Скитальца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо. Тебя ждет яркое начало пути. Дорога будет долгой, и, чем большего ты сможешь достигнуть, тем проще будут даваться умения, о которых ты раньше даже не $gмечтал:мечтала;.$B$BИди, получи новый опыт и изучи новую технику. Затем продемонстрируй ее на одном из тренировочных манекенов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Найдите тренировочный манекен рядом с Солнечным Шпилем и отработайте этот прием.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Pao на Солнечный Шпиль на Остров Солнечного Скитальца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31173,'Лапа тигра','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Разыщите тренировочный манекен на северо-западной стороне места крушения и потренируйтесь на нем.','Вернитесь к Моцзо Буйному Портеру на место крушения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа тигра',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достигните 3-го уровня, чтобы изучить прием "Лапа тигра". Разыщите тренировочный манекен на северо-западной стороне места крушения и потренируйтесь на нем.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моцзо Буйному Портеру на место крушения.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31174,'Озеро Звезд','Обнаружен еще один Идеал.$B$BНа этот раз он в Озере Звезд, это древнее озеро на юге.$B$BПопасть туда будет непросто, путь преграждают враги.$B$BЯ поручаю это тебе. Справишься – останешься в живых.$B$BПровалишь задание – отправлю еще кого-нибудь.','Убейте 12 порабощенных янтароискателей или вос\'тик-надсмотрщиков. Освободите Корвена Первейшего.','Поговорите с Корвеном Первейшим у Озера Звезд, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Озеро Звезд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обнаружен еще один Идеал.$B$BНа этот раз он в Озере Звезд, это древнее озеро на юге.$B$BПопасть туда будет непросто, путь преграждают враги.$B$BЯ поручаю это тебе. Справишься – останешься в живых.$B$BПровалишь задание – отправлю еще кого-нибудь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 порабощенных янтароискателей или вос\'тик-надсмотрщиков. Освободите Корвена Первейшего.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Корвеном Первейшим у Озера Звезд, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31175,'Скир Кровожадный','Пробудите Скира Кровожадного в подводной пещере.','Поговорите со Скиром Кровожадным в Гроте Грязной Чешуи в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скир Кровожадный',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пробудите Скира Кровожадного в подводной пещере.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Скиром Кровожадным в Гроте Грязной Чешуи в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31176,'Странный аппетит','Еда. Мне нужна еда.$B$BВ мои времена мясо морских звезд придавало силы и очищало разум. Вот что я хочу съесть.$B$BПринеси мне звезд с отмелей неподалеку.$B$BЕсли будешь мешкать, я сожру тебя взамен.','Соберите 12 кусочков мяса морских звезд.','Да, давай сюда! Хорошая работа, Пробудитель.','Соки морских звезд очистят мой разум.','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный аппетит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еда. Мне нужна еда.$B$BВ мои времена мясо морских звезд придавало силы и очищало разум. Вот что я хочу съесть.$B$BПринеси мне звезд с отмелей неподалеку.$B$BЕсли будешь мешкать, я сожру тебя взамен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 кусочков мяса морских звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, давай сюда! Хорошая работа, Пробудитель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Соки морских звезд очистят мой разум.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31177,'Хороший обед','Пока я был жив, то считался величайшим воином роя.$B$BПомоги мне восстановить силы, и я покажу тебе, на что способен.$B$BЯ чувствую солоноватый запах моря. А где море, там морские трещоты.$B$BПринеси мне их питательные хвосты. Они должны утолить мой голод.','Соберите 8 хвостов трещотов.','Превосходно. Я сокрушу всех врагов, как только немного окрепну.','У меня еще много работы. Чем скорее я смогу сражаться, тем скорее предстану перед Советом.','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший обед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока я был жив, то считался величайшим воином роя.$B$BПомоги мне восстановить силы, и я покажу тебе, на что способен.$B$BЯ чувствую солоноватый запах моря. А где море, там морские трещоты.$B$BПринеси мне их питательные хвосты. Они должны утолить мой голод.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 хвостов трещотов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я сокрушу всех врагов, как только немного окрепну.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня еще много работы. Чем скорее я смогу сражаться, тем скорее предстану перед Советом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31178,'Кровавое удовольствие','Пока воин не попробовал крови своих врагов, толку от него в бою немного.$B$BЯ еще слишком слаб, чтобы охотиться, так что этим придется заняться тебе.$B$BМне нужна кровь лишь самых свирепых хищников. Я чую их присутствие в водах за стенами этой пещеры.$B$BДобудь мне их крови, и поймешь, почему меня прозвали Кровожадным.','Соберите 100 капель неустойчивой крови ужасающих прилипал.','Да, это подойдет.','Когда я пью кровь врага, его сила переходит ко мне.','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавое удовольствие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока воин не попробовал крови своих врагов, толку от него в бою немного.$B$BЯ еще слишком слаб, чтобы охотиться, так что этим придется заняться тебе.$B$BМне нужна кровь лишь самых свирепых хищников. Я чую их присутствие в водах за стенами этой пещеры.$B$BДобудь мне их крови, и поймешь, почему меня прозвали Кровожадным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 капель неустойчивой крови ужасающих прилипал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это подойдет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда я пью кровь врага, его сила переходит ко мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скиру Кровожадному в Грот Грязной Чешуи, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31179,'Запах крови','Пришлось запачкать руки кровью сауроков, пока тебя не было.$B$BИзвини, не удержался. Смотри, как тщетны их нападки!$B$BНичтожества!$B$BНеужто хотят отомстить за убитых и бросить вызов мне? Мне?!$B$BНе я ли победил в сотне войн? Не я ли бился с тысячей врагов и победил?$B$BА этих... сауроков... я раздавлю, как скорлупу молотом!$B$BУзри мою мощь, Пробудитель! Давай сразимся с ними!$B$BСауроки не пройдут!','Убейте 12 поедаталей плоти и змейников из племени Грязной Чешуи.','Ты хорошо сражаешься, Пробудитель. Из тебя выйдет толк.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришлось запачкать руки кровью сауроков, пока тебя не было.$B$BИзвини, не удержался. Смотри, как тщетны их нападки!$B$BНичтожества!$B$BНеужто хотят отомстить за убитых и бросить вызов мне? Мне?!$B$BНе я ли победил в сотне войн? Не я ли бился с тысячей врагов и победил?$B$BА этих... сауроков... я раздавлю, как скорлупу молотом!$B$BУзри мою мощь, Пробудитель! Давай сразимся с ними!$B$BСауроки не пройдут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 поедаталей плоти и змейников из племени Грязной Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо сражаешься, Пробудитель. Из тебя выйдет толк.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31181,'Свежие горшки','У нас тут полно пустых крабьих горшков и нам для них нужна свежая наживка.$B$BДумаешь, мы их вытащим сюда по одному и будем не торопясь наполнять? Сидя в кресле, чаек попивая? Мечта, не работа...$B$BТак вот, не дождешься.$B$BДавай-ка, отправляйся в Одинокую бухту, это на юго-западе, и разложи в горшки наживку из двух свежих морских монархов. Свежих – это значит, убитых там же, прямо в воде.$B$BА, да, "горшками" у нас называют ловушки. Хочешь сработаться с ребятами, учи жаргон.','Разложите наживку в 10 пустых ловушек для крабов в Одинокой бухте. Для каждой ловушки требуется 2 куска мяса морского монарха.','Сойдет, салага.','Вернитесь к боцману Ари в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свежие горшки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас тут полно пустых крабьих горшков и нам для них нужна свежая наживка.$B$BДумаешь, мы их вытащим сюда по одному и будем не торопясь наполнять? Сидя в кресле, чаек попивая? Мечта, не работа...$B$BТак вот, не дождешься.$B$BДавай-ка, отправляйся в Одинокую бухту, это на юго-западе, и разложи в горшки наживку из двух свежих морских монархов. Свежих – это значит, убитых там же, прямо в воде.$B$BА, да, "горшками" у нас называют ловушки. Хочешь сработаться с ребятами, учи жаргон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разложите наживку в 10 пустых ловушек для крабов в Одинокой бухте. Для каждой ловушки требуется 2 куска мяса морского монарха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сойдет, салага.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боцману Ари в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31182,'Кто выдрал наживку из горшка?','Знаешь, что случилось с наживкой в горшках?$B$BВыдры, вот что.$B$BОни обычно свежих моллюсков жрут, но с голодухи могут и крабьи ловушки очистить.$B$BВ Одинокой бухте выдры охраняются законом, а мы тут вполне легально. Так что грохать этих водных крыс мы не будем, как бы ни хотелось. Надо им жратвы подкинуть, чтоб они на ловушки наши уж и глядеть не хотели.$B$BДай им моллюсков, пусть лопают, пока ты там будешь.','Накормите из мешка с моллюсками 8 хладноусых выдр из Одинокой бухты.','Пусть держат свои усики при себе, подальше от наших ловушек.','Вернитесь к боцману Ари в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто выдрал наживку из горшка?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, что случилось с наживкой в горшках?$B$BВыдры, вот что.$B$BОни обычно свежих моллюсков жрут, но с голодухи могут и крабьи ловушки очистить.$B$BВ Одинокой бухте выдры охраняются законом, а мы тут вполне легально. Так что грохать этих водных крыс мы не будем, как бы ни хотелось. Надо им жратвы подкинуть, чтоб они на ловушки наши уж и глядеть не хотели.$B$BДай им моллюсков, пусть лопают, пока ты там будешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накормите из мешка с моллюсками 8 хладноусых выдр из Одинокой бухты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть держат свои усики при себе, подальше от наших ловушек.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боцману Ари в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31183,'Встреча с капитаном','Ладушки, $p, у меня для тебя новая работенка.$B$BВидишь тюльва в том загончике? Его зовут Пес. Он любимчик Мокрого уже много лет.$B$BВ последнее время Пес неспокоен – кажется, ему надоело сидеть в загоне. Поговори с Мокрым и расскажи ему это.$B$BТебе все равно пора уже встретиться с капитаном.','Поговорите с "Мокрым" Су-Дао в Приюте капитана.','Новый матрос, да? Посмотрим, на что ты сгодишься.$B$BУ меня отличный корабль – пусть он и на дне моря.','Поговорите с "Мокрым" Су-Дао в Приюте капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с капитаном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладушки, $p, у меня для тебя новая работенка.$B$BВидишь тюльва в том загончике? Его зовут Пес. Он любимчик Мокрого уже много лет.$B$BВ последнее время Пес неспокоен – кажется, ему надоело сидеть в загоне. Поговори с Мокрым и расскажи ему это.$B$BТебе все равно пора уже встретиться с капитаном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с "Мокрым" Су-Дао в Приюте капитана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Новый матрос, да? Посмотрим, на что ты сгодишься.$B$BУ меня отличный корабль – пусть он и на дне моря.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с "Мокрым" Су-Дао в Приюте капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31184,'Старость и предательство','Слушай, у меня нет причин тебе доверять, но есть задание, которое я не могу поручить своей команде.$B$BЯ хочу, чтобы ты $gобыскал:обыскала; место крушения нашего старого корабля, "Туманного кузнечика", и $gпринес:принесла; договор фрахтования. Он в серебряном футляре, в cундуке.$B$BОн немного... э-э... инкриминирующий. Не могу рисковать, чтобы моя команда его нашла, если вдруг вздумает наведаться на старичка. "Кузнечик" покоится на шельфе Мацзу, на западе.$B$BСоветую добраться туда на подводном течении, если желудок не шалит. Они там по всему шельфу.','Отыщите договор фрахтования среди обломков "Туманного Кузнечика".','Да, это футляр с договором. Думаю, ты хочешь узнать, из-за чего вся эта суета?$B$B<Мокрый тяжело вздыхает, открывая футляр.>$B$BПора уже с этим разделаться.','Если честно, я надеюсь, что этот договор сожрал морской окунь.$B$BХотя стоп, тогда он все равно может оказаться здесь! Проклятье!','Вернитесь к капитану "Мокрому" Су-Дао в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старость и предательство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, у меня нет причин тебе доверять, но есть задание, которое я не могу поручить своей команде.$B$BЯ хочу, чтобы ты $gобыскал:обыскала; место крушения нашего старого корабля, "Туманного кузнечика", и $gпринес:принесла; договор фрахтования. Он в серебряном футляре, в cундуке.$B$BОн немного... э-э... инкриминирующий. Не могу рисковать, чтобы моя команда его нашла, если вдруг вздумает наведаться на старичка. "Кузнечик" покоится на шельфе Мацзу, на западе.$B$BСоветую добраться туда на подводном течении, если желудок не шалит. Они там по всему шельфу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите договор фрахтования среди обломков "Туманного Кузнечика".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это футляр с договором. Думаю, ты хочешь узнать, из-за чего вся эта суета?$B$B<Мокрый тяжело вздыхает, открывая футляр.>$B$BПора уже с этим разделаться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если честно, я надеюсь, что этот договор сожрал морской окунь.$B$BХотя стоп, тогда он все равно может оказаться здесь! Проклятье!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану "Мокрому" Су-Дао в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31185,'Выгулять Пса','Пес – не мой "питомец", а член команды и мой лучший друг. Не раз спасал мне жизнь.$B$BНо я уже староват, чтобы гулять с ним, а ему надо размяться. Отведи его на прогулку, хорошо?$B$BОн любит плавать вокруг горячих гейзеров к северо-востоку от отмелей.$B$BЕму совершенно необходимо... э-э... "отметиться" на дохлом ките, который находится далеко на западе побережья.$B$BА, и еще он захочет заглянуть на место нашего старого крушения. Он любит воспоминания.','Прогуляйтесь вместе с псом к горячим гейзерам, трупу кита и обломкам "Туманного Кузнечика" на шельфе Мацзу.','Как все прошло? Надеюсь, он не доставил проблем!','Вернитесь к капитану "Мокрому" Су-Дао в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выгулять Пса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пес – не мой "питомец", а член команды и мой лучший друг. Не раз спасал мне жизнь.$B$BНо я уже староват, чтобы гулять с ним, а ему надо размяться. Отведи его на прогулку, хорошо?$B$BОн любит плавать вокруг горячих гейзеров к северо-востоку от отмелей.$B$BЕму совершенно необходимо... э-э... "отметиться" на дохлом ките, который находится далеко на западе побережья.$B$BА, и еще он захочет заглянуть на место нашего старого крушения. Он любит воспоминания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прогуляйтесь вместе с псом к горячим гейзерам, трупу кита и обломкам "Туманного Кузнечика" на шельфе Мацзу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как все прошло? Надеюсь, он не доставил проблем!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану "Мокрому" Су-Дао в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31186,'Накормить Пса','<Пес скулит так, как только может тюлев, с трудом поднося ласт к массивным челюстям.$B$BОн голоден.$B$BШельф Мацзу покрыт твердопанцирными макрурами, которые должны прийтись ему по вкусу.>','Помогите Псу полакомиться останками 10 твердопанцирных клешнехватов.','<Пес с удовольствием облизывается; он выглядит довольным.>','<Наверное, это самый несчастный тюлев, которого вы когда-либо видели.>','Поговорите с Псом на шельфе Мацзу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накормить Пса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Пес скулит так, как только может тюлев, с трудом поднося ласт к массивным челюстям.$B$BОн голоден.$B$BШельф Мацзу покрыт твердопанцирными макрурами, которые должны прийтись ему по вкусу.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Псу полакомиться останками 10 твердопанцирных клешнехватов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Пес с удовольствием облизывается; он выглядит довольным.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Наверное, это самый несчастный тюлев, которого вы когда-либо видели.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Псом на шельфе Мацзу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31187,'Крабы','Говорят, что горшки, которые мы опустили утром на дно, битком набиты крабами!$B$BПроблема в том, что течения усилились, и часть горшков потерялась. И теперь они, до краев полные колючего синего золота, валяются неизвестно где!$B$BТы мне $gнужен:нужна;, чтобы их вернуть. Прицепи эти буйки ко всем полным ловушкам, которые найдешь, и отпусти их на поверхность – мы их подберем.','Прицепите буй "Туманного Кузнечика" к 8 ловушкам с крабами на шельфе Мацзу.','Отличная работа!','Вернитесь к боцману Ари в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крабы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что горшки, которые мы опустили утром на дно, битком набиты крабами!$B$BПроблема в том, что течения усилились, и часть горшков потерялась. И теперь они, до краев полные колючего синего золота, валяются неизвестно где!$B$BТы мне $gнужен:нужна;, чтобы их вернуть. Прицепи эти буйки ко всем полным ловушкам, которые найдешь, и отпусти их на поверхность – мы их подберем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прицепите буй "Туманного Кузнечика" к 8 ловушкам с крабами на шельфе Мацзу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боцману Ари в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31188,'Неделя акулы','Конечно, основной доход у нас с крабов, но мы отсылаем за стену и много всего другого. Масла, растения, даже редкие минералы – море в этих краях щедрое.$B$BА сейчас начался бум на зубы крепкозуба. Похоже, из них получаются отличные ожерелья.$B$BВ западной части шельфа Мацзу водится много крепкозубов. А мне нужно много зубов.','Соберите 200 зубов крепкозуба, выдирая их из челюстей длинноплавниковых крепкозубов на шельфе Мацзу.','Отлично, сгрузи их вон туда. Я к ним прикасаться не хочу. Жуть.','Мне доводилось видеть, как акулы едят нашего брата, и я не понимаю, как можно добровольно вешать их зубы на шею, но кто меня спрашивает.','Вернитесь к боцману Ари в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неделя акулы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, основной доход у нас с крабов, но мы отсылаем за стену и много всего другого. Масла, растения, даже редкие минералы – море в этих краях щедрое.$B$BА сейчас начался бум на зубы крепкозуба. Похоже, из них получаются отличные ожерелья.$B$BВ западной части шельфа Мацзу водится много крепкозубов. А мне нужно много зубов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 200 зубов крепкозуба, выдирая их из челюстей длинноплавниковых крепкозубов на шельфе Мацзу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, сгрузи их вон туда. Я к ним прикасаться не хочу. Жуть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне доводилось видеть, как акулы едят нашего брата, и я не понимаю, как можно добровольно вешать их зубы на шею, но кто меня спрашивает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боцману Ари в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31189,'Ловля на живца','Что происходит? Сначала я слышу крики, а потом вдруг появляются эти твари!','Вернитесь к боцману Ари в Приют капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля на живца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что происходит? Сначала я слышу крики, а потом вдруг появляются эти твари!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боцману Ари в Приют капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31190,'Месть моряка','Я не собираюсь сидеть в этой качалке, пока мою команду пожирает левиафан!$B$BПойдем, надо добраться до причала и спустить на воду шлюпку. Я приберег одну как раз для таких случаев. Мой собственный "малый" "Туманный Кузнечик".$B$BПокажем этой твари, что такое гарпунная лихорадка.','Спустите на воду "малого" "Туманного Кузнечика" на причале в Приюте капитана и уничтожьте Цзяо.','Отлично постреляли!$B$BЯ знал, что мы справимся. Убить можно любую нечисть, главное – взять побольше гарпунов.','Поговорите с капитаном "Мокрым" Су-Дао в Приюте капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть моряка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не собираюсь сидеть в этой качалке, пока мою команду пожирает левиафан!$B$BПойдем, надо добраться до причала и спустить на воду шлюпку. Я приберег одну как раз для таких случаев. Мой собственный "малый" "Туманный Кузнечик".$B$BПокажем этой твари, что такое гарпунная лихорадка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спустите на воду "малого" "Туманного Кузнечика" на причале в Приюте капитана и уничтожьте Цзяо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично постреляли!$B$BЯ знал, что мы справимся. Убить можно любую нечисть, главное – взять побольше гарпунов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном "Мокрым" Су-Дао в Приюте капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31194,'Проблемы со Скользкой Чешуей','Приказы клану Скользкой Чешуи отдает его новый глава, чешуйчатый повелитель. Сейчас он празднует свои победы в юго-восточной части Наветренного острова.$B$BУничтожив его, мы нанесем их племени чувствительный удар.$B$BБез своего повелителя клан дважды подумает, прежде чем снова нападать на беззащитных облачных змеев востока.','Убейте чешуйчатого повелителя из клана Скользкой Чешуи.','Прекрасно! Я знала, что ты одержишь верх над чешуйчатым повелителем.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.','Великая опасность ожидает.','Чешуйчатый повелитель из клана Скользкой Чешуи') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы со Скользкой Чешуей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказы клану Скользкой Чешуи отдает его новый глава, чешуйчатый повелитель. Сейчас он празднует свои победы в юго-восточной части Наветренного острова.$B$BУничтожив его, мы нанесем их племени чувствительный удар.$B$BБез своего повелителя клан дважды подумает, прежде чем снова нападать на беззащитных облачных змеев востока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чешуйчатого повелителя из клана Скользкой Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Я знала, что ты одержишь верх над чешуйчатым повелителем.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Великая опасность ожидает.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чешуйчатый повелитель из клана Скользкой Чешуи',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31195,'Заукать дукера') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заукать дукера',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31196,'Убейте 15 обычных богомолов около острова Шра\'весс.','Отлично! Главное – это внезапность.','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 обычных богомолов около острова Шра\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Главное – это внезапность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31197,'Чем они больше...','Убийство богомолов поменьше – это скорее отвлекающий маневр, им приходится пополнять свои войска, даже если серьезного урона они не понесли.\r\n\r\nБольшие богомолы – совсем другое дело, стоит убить несколько штук, и мы надолго задержим их продвижение на острове. Видимо, в империи их ценят в зависимости от размеров.\r\n\r\nТак что, будь так $gдобр:добра; убей несколько богомолов покрупнее.','Убейте 4 элитных богомолов на острове Шра\'весс.','Ну что ж, отлично. Думаю, несколько дней можно жить спокойно.','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем они больше...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убийство богомолов поменьше – это скорее отвлекающий маневр, им приходится пополнять свои войска, даже если серьезного урона они не понесли.\r\n\r\nБольшие богомолы – совсем другое дело, стоит убить несколько штук, и мы надолго задержим их продвижение на острове. Видимо, в империи их ценят в зависимости от размеров.\r\n\r\nТак что, будь так $gдобр:добра; убей несколько богомолов покрупнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 элитных богомолов на острове Шра\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, отлично. Думаю, несколько дней можно жить спокойно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31198,'Моральная победа','У богомолов на острове Шра\'весс есть статуи, которые они используют... Кто знает, зачем они их используют. Может, они им поклоняются, или переговариваются с их помощью.\r\n\r\nВрага надо уничтожать не только физически, но и морально! Не знаю, как там все устроено у этих богомолов, но статуи явно как-то им помогают.\r\n\r\nПоэтому надо, чтобы ты их $gвзорвал:взорвала;. Это сильно подорвет их боевой дух.','Уничтожьте южного, центрального, восточного и западного идолов на острове Шра\'весс.','Думаю, лишившись своих идолов, они очень расстроятся.','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Моральная победа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У богомолов на острове Шра\'весс есть статуи, которые они используют... Кто знает, зачем они их используют. Может, они им поклоняются, или переговариваются с их помощью.\r\n\r\nВрага надо уничтожать не только физически, но и морально! Не знаю, как там все устроено у этих богомолов, но статуи явно как-то им помогают.\r\n\r\nПоэтому надо, чтобы ты их $gвзорвал:взорвала;. Это сильно подорвет их боевой дух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте южного, центрального, восточного и западного идолов на острове Шра\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, лишившись своих идолов, они очень расстроятся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31199,'Уничтожить осадные орудия!','Богомолы берут не только числом.\r\n\r\nОни умны. У них на службе алхимия, бомбы... и что хуже всего, осадные орудия. Это очень серьезная угроза.\r\n\r\nРазведчики сообщили, что богомолы строят осадные орудия в западной части острова Шра\'весс. Уничтожь их.','Уничтожьте четыре осадных орудия богомолов на острове Шра\'весс в Танлунских степях.','Ну вот, больше не надо беспокоиться из-за осадных орудий. Конечно, они построят их снова, но зато мы выиграли время.','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить осадные орудия!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы берут не только числом.\r\n\r\nОни умны. У них на службе алхимия, бомбы... и что хуже всего, осадные орудия. Это очень серьезная угроза.\r\n\r\nРазведчики сообщили, что богомолы строят осадные орудия в западной части острова Шра\'весс. Уничтожь их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте четыре осадных орудия богомолов на острове Шра\'весс в Танлунских степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, больше не надо беспокоиться из-за осадных орудий. Конечно, они построят их снова, но зато мы выиграли время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31201,'Друзья – не еда!','Спасите учеников Шадо-Пан из северной, центральной и южной кормовых ям куньчунов.','Ну наконец-то. Я тут места себе не нахожу.','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друзья – не еда!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите учеников Шадо-Пан из северной, центральной и южной кормовых ям куньчунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну наконец-то. Я тут места себе не нахожу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим спутником Шадо-Пан на поле или вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31203,'Попутная цель: шра\'тик – повелитель роя','Раз уж мы здесь, надо сделать еще кое-что.\r\n\r\nШра\'тик – повелитель роя направляет атаки богомолов с воздуха. Если мы оставим его в живых, он изрядно потреплет весь наш гарнизон.\r\n\r\nТак что предлагаю в живых его не оставлять. Действуй, $n.','Я слышал, что там ты проделал... кое-какую дополнительную работу. Превосходно.$B$BПриходи потом еще – у нас для тебя непременно найдется работа.','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попутная цель: шра\'тик – повелитель роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж мы здесь, надо сделать еще кое-что.\r\n\r\nШра\'тик – повелитель роя направляет атаки богомолов с воздуха. Если мы оставим его в живых, он изрядно потреплет весь наш гарнизон.\r\n\r\nТак что предлагаю в живых его не оставлять. Действуй, $n.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал, что там ты проделал... кое-какую дополнительную работу. Превосходно.$B$BПриходи потом еще – у нас для тебя непременно найдется работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31204,'Попутная цель: шра\'тик – повелитель улья','Убейте шра\'тика – повелителя улья.','Молодец, Даффман! Ты не стал чураться лишних трудов, и теперь мы сможем передохнуть от богомолов.$B$BПриходи потом еще – у нас для тебя непременно найдется работа.','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попутная цель: шра\'тик – повелитель улья',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте шра\'тика – повелителя улья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, Даффман! Ты не стал чураться лишних трудов, и теперь мы сможем передохнуть от богомолов.$B$BПриходи потом еще – у нас для тебя непременно найдется работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31205,'Lorewalker Cho Tracking Quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Lorewalker Cho Tracking Quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31206,'Горнило Крови: боец из клана Кровавого Глаза!','Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!','Хурп\'дерп побежден','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.','Участник боев из клана Кровавого Глаза.','Хурп\'дерп','Правая рука Гурга.','Водин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горнило Крови: боец из клана Кровавого Глаза!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, я не спорю. Этот край – то еще место, уж никак не Награнд и даже не Зул\'Драк, но знаешь, $gдружище:подруга;, я тебе вот что скажу: я просто двигаю туда, где можно заработать! Поэтому – добро пожаловать на Сумеречное нагорье!$B$BТы тут новичок, и я тебе объясню в двух словах, что здесь и как. Я организатор боев, этот сварливый тролль – мой телохранитель Водин. Ну а ты, стало быть, боец на потеху почтеннейшей публике. У нас тут все по желанию. Захочешь сражаться – собери друзей и скажи мне, а уж у меня найдутся для вас достойные противники.$B$BМожно и прямо сейчас, если хочешь. Ну что, будешь сражаться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на арену Горнила Крови и одержите победу над Хурп\'дерпом!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Хурп\'дерп побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в Горнило Крови на Сумеречном нагорье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Участник боев из клана Кровавого Глаза.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хурп\'дерп',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Правая рука Гурга.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Водин',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31207,'Арена Истребления','Эх, я все еще помню бои, которые мы проводили в этой грязной дыре, в Награнде. Много воды утекло, а, Водин?$B$BЭти монахи из Храма Тигра ценят хорошую драку, точно говорю. Они неплохо заплатили мне, чтобы я обосновался здесь и помогал отбирать лучших бойцов!$B$BНу так что? Выйдешь с парой друзей на Арену Истребления? Это неплохие деньги, кстати.','Выйдите на Арену Истребления и выполните все предложенные задания. Не забудьте забрать свою награду у тролля-прислужника Водина.','Гаргток сказал, что это был славный бой. Выбирай!','Вернитесь к троллю-прислужнику Водину в храме Тигра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арена Истребления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эх, я все еще помню бои, которые мы проводили в этой грязной дыре, в Награнде. Много воды утекло, а, Водин?$B$BЭти монахи из Храма Тигра ценят хорошую драку, точно говорю. Они неплохо заплатили мне, чтобы я обосновался здесь и помогал отбирать лучших бойцов!$B$BНу так что? Выйдешь с парой друзей на Арену Истребления? Это неплохие деньги, кстати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выйдите на Арену Истребления и выполните все предложенные задания. Не забудьте забрать свою награду у тролля-прислужника Водина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гаргток сказал, что это был славный бой. Выбирай!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину в храме Тигра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31208,'Ядовитый умысел','Если хотим одержать верх над императрицей, нужно как следует вооружиться. Себе в качестве оружия я подобрал кое-что особо ядовитое.$B$BЖелезы скорпионов, обитающих на выступе, вырабатывают смертельный яд.$B$BПринеси мне жала этих скорпионов, и я покажу тебе, за что меня прозвали Идеалом.','Соберите 8 ядовитых жал.','Прекрасно, Пробудитель. Надеюсь, ты был аккуратен.$B$BЯд этих скорпионов смертелен, но действует он медленно.','Чувствуешь, как действуют токсины ядохвоста? Эта боль просто очаровательна.','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядовитый умысел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хотим одержать верх над императрицей, нужно как следует вооружиться. Себе в качестве оружия я подобрал кое-что особо ядовитое.$B$BЖелезы скорпионов, обитающих на выступе, вырабатывают смертельный яд.$B$BПринеси мне жала этих скорпионов, и я покажу тебе, за что меня прозвали Идеалом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 ядовитых жал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, Пробудитель. Надеюсь, ты был аккуратен.$B$BЯд этих скорпионов смертелен, но действует он медленно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чувствуешь, как действуют токсины ядохвоста? Эта боль просто очаровательна.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31209,'Черные крылья, черные дела','Для моего первого яда понадобится еще один ингредиент, Пробудитель.$B$BТебе придется отыскать поблизости скарабеев.$B$BУбей их и принеси мне крылья.','Соберите 150 крыльев скарабея.','Великолепно, Пробудитель. Они безукоризненны.$B$BА тебя не привлекает искусство отравителя?','Размолов крылья скарабея, мы получим мельчайший белый порошок. Смертельная добавка.','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черные крылья, черные дела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для моего первого яда понадобится еще один ингредиент, Пробудитель.$B$BТебе придется отыскать поблизости скарабеев.$B$BУбей их и принеси мне крылья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 150 крыльев скарабея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, Пробудитель. Они безукоризненны.$B$BА тебя не привлекает искусство отравителя?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Размолов крылья скарабея, мы получим мельчайший белый порошок. Смертельная добавка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31210,'Жуткоцвет','Последний ингредиент – пожалуй, самый опасный.$B$BЖуткоцвет растет на здешних холмах.$B$BИменно поедая эти токсичные растения, местная фауна стала столь ядовитой.$B$BОдна капля нектара жуткоцвета может убить куньчуна.$B$BПринеси мне эти цветы. И не пытайся их попробовать.','Соберите 8 жуткоцветов.','Мало кто по достоинству оценит то, что ты держишь.$B$BХорошая работа, Пробудитель.','Порой самые красивые вещи – самые опасные.','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуткоцвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний ингредиент – пожалуй, самый опасный.$B$BЖуткоцвет растет на здешних холмах.$B$BИменно поедая эти токсичные растения, местная фауна стала столь ядовитой.$B$BОдна капля нектара жуткоцвета может убить куньчуна.$B$BПринеси мне эти цветы. И не пытайся их попробовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 жуткоцветов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мало кто по достоинству оценит то, что ты держишь.$B$BХорошая работа, Пробудитель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Порой самые красивые вещи – самые опасные.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксарилу Отравленному Разуму в Ядовитую гряду, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31211,'Отравленный разум','Прежде чем мы вернемся в Клакси\'весс, мне хотелось бы увидеть, что стало с империей.$B$BСовет клакси поведал мне, что противник стянул силы к вратам дворца императрицы.$B$BЯ, наконец, приготовил яды. Смерть и разрушения станут прекрасными глашатаями моего возвращения!$B$BСмотри внимательнее, чтобы сыворотки не смешивались! По крайней мере, пока ты держишь сосуды в руках.$B$BПоговори со мной, когда подготовишься к полету.','Поговорите с Ксарилом Отравленный Разум. Убейте 200 богомолов и 3 кунчунов, пока летите вместе с ним.','Поговорите с Ксарилом Отравленным Разумом в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отравленный разум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы вернемся в Клакси\'весс, мне хотелось бы увидеть, что стало с империей.$B$BСовет клакси поведал мне, что противник стянул силы к вратам дворца императрицы.$B$BЯ, наконец, приготовил яды. Смерть и разрушения станут прекрасными глашатаями моего возвращения!$B$BСмотри внимательнее, чтобы сыворотки не смешивались! По крайней мере, пока ты держишь сосуды в руках.$B$BПоговори со мной, когда подготовишься к полету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ксарилом Отравленный Разум. Убейте 200 богомолов и 3 кунчунов, пока летите вместе с ним.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ксарилом Отравленным Разумом в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
