INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31216,'Темные небеса','Убейте 200 богомолов и 3 кунчунов или ужасающих чудищ, пока вас несет по воздуху Ксарил Отравленный Разум.','Отличная работа, Пробудитель. У тебя талант к разрушению.','Вернитесь к Ксарилу Отравленный Разум в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные небеса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 200 богомолов и 3 кунчунов или ужасающих чудищ, пока вас несет по воздуху Ксарил Отравленный Разум.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, Пробудитель. У тебя талант к разрушению.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксарилу Отравленный Разум в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
