INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31220,'Бойцовский круг: повелитель ястребов Нужун','Среди Шадо-Панов ты слывешь хорошим бойцом, $n.\r\n\r\nНужун хочет проверить свои силы и сразиться с тобой.\r\n\r\nХорошая новость: если ты победишь, я позволю ему помогать тебе.\r\n\r\nПлохая новость: сомневаюсь, что ты победишь.','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, повелителя ястребов Нужуна и победите его.','Так-так-так. И я могу ошибаться.$B$BНу что ж, хорошо. Нужун рвется сопровождать тебя.','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.','Смертельно опасный У Као всегда путешествует со своим любимым ястребом по имени Белоснежное Перо.','Повелитель ястребов Нужун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: повелитель ястребов Нужун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди Шадо-Панов ты слывешь хорошим бойцом, $n.\r\n\r\nНужун хочет проверить свои силы и сразиться с тобой.\r\n\r\nХорошая новость: если ты победишь, я позволю ему помогать тебе.\r\n\r\nПлохая новость: сомневаюсь, что ты победишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, повелителя ястребов Нужуна и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-так-так. И я могу ошибаться.$B$BНу что ж, хорошо. Нужун рвется сопровождать тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Смертельно опасный У Као всегда путешествует со своим любимым ястребом по имени Белоснежное Перо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Повелитель ястребов Нужун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31221,'Бойцовский круг: Тэнь-у Красный Дым','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Тэнь-у Красного Дыма и победите его.','Вот это здорово! Хорошая была схватка.$B$BЕсли повезет, теперь он будет стремиться подражать тебе, и это научит его держать рот на замке.','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.','Смертельно опасный разбойник У Као, и бахвалится не хуже, чем сражается.','Тэнь-у Красный Дым') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бойцовский круг: Тэнь-у Красный Дым',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызовите на бой в гарнизоне Шадо-Пан, что в Танлунских степях, Тэнь-у Красного Дыма и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это здорово! Хорошая была схватка.$B$BЕсли повезет, теперь он будет стремиться подражать тебе, и это научит его держать рот на замке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лин Шестой из Пула в гарнизон Шадо-Пан, что в Танлунских степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Смертельно опасный разбойник У Као, и бахвалится не хуже, чем сражается.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Тэнь-у Красный Дым',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31228,'Пророк Хар\'зул','Пророк Хар\'зул – опытный заклинатель, но тебя он недооценивает.$B$BРади защиты этой деревни Хар\'зула и его приспешников нужно убить. Его смерть даст понять Властелину Грома, что мы не отступим!$B$BТы найдешь его на острове Расплаты.','Победите пророка Хар\'зула.','Вернитесь к хранителю истории Чо в деревню Цзоучин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророк Хар\'зул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пророк Хар\'зул – опытный заклинатель, но тебя он недооценивает.$B$BРади защиты этой деревни Хар\'зула и его приспешников нужно убить. Его смерть даст понять Властелину Грома, что мы не отступим!$B$BТы найдешь его на острове Расплаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите пророка Хар\'зула.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю истории Чо в деревню Цзоучин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31230,'Добро пожаловать в Цветущую Зарю!','Чо снова отправился на поиски приключений, а у меня тут заказ на большую партию нефрита. Обращусь за помощью к знакомым.$b$bА ты пока познакомься с местными.$b$bКай Бродячий Бражник – отличный собеседник, как и мастер Воздушный Мех. Кстати, зайди в таверну и передай привет Пэйцзи Золотистый Нектар.$b$bПоговори с этими тремя и узнаешь, чем живет Цветущая Заря.','Поговорите с Каем Бродячим Бражником, мастером Воздушный Мех и Пэйцзи Золотистый Нектар в Цветущей Заре.','Хорошо, очень хорошо. Ты здесь отлично освоишься.','Поговорите с Тоей, который находится в Цветущей Заре, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в Цветущую Зарю!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чо снова отправился на поиски приключений, а у меня тут заказ на большую партию нефрита. Обращусь за помощью к знакомым.$b$bА ты пока познакомься с местными.$b$bКай Бродячий Бражник – отличный собеседник, как и мастер Воздушный Мех. Кстати, зайди в таверну и передай привет Пэйцзи Золотистый Нектар.$b$bПоговори с этими тремя и узнаешь, чем живет Цветущая Заря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Каем Бродячим Бражником, мастером Воздушный Мех и Пэйцзи Золотистый Нектар в Цветущей Заре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, очень хорошо. Ты здесь отлично освоишься.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тоей, который находится в Цветущей Заре, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31231,'Истребление страхопрядов','На террасе Гуртани, где ты меня $gнашел:нашла;, лучникам Шадо-Пан приходится все время следить за страхопрядами, вместо того чтобы сосредоточиться на рое.$B$BУничтожь этих пауков, пусть стрелки хоть немного передохнут.','Убейте 8 страхопрядов-охранников на террасе Гуртани. Поговорите с Кил\'руком Рассекающим Ветер для выброски с воздуха.','Терпеть не могу пауков. Мерзкие безмозглые твари.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление страхопрядов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На террасе Гуртани, где ты меня $gнашел:нашла;, лучникам Шадо-Пан приходится все время следить за страхопрядами, вместо того чтобы сосредоточиться на рое.$B$BУничтожь этих пауков, пусть стрелки хоть немного передохнут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 страхопрядов-охранников на террасе Гуртани. Поговорите с Кил\'руком Рассекающим Ветер для выброски с воздуха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Терпеть не могу пауков. Мерзкие безмозглые твари.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31232,'Древняя империя','Мои братья говорят о древней империи могу, развалины которой еще можно увидеть на востоке.$B$BКогда-то могу владели тайнами колдовства и порабощало непокорных.$B$BМне свойственно любопытство, Пробудитель. Я желаю знать, что за империи были после меня.$B$BЗнание прошлого помогает постичь будущее.$B$BРазыщи же в руинах древние скрижали, дабы мне открылись тайные знания.','Соберите 8 скрижалей Гуртани.','Благодарю тебя, Пробудитель. Мне потребуется некоторое время, чтобы прочесть эти скрижали, но всякое знание ценно.','Несешь ли ты новое знание?','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древняя империя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои братья говорят о древней империи могу, развалины которой еще можно увидеть на востоке.$B$BКогда-то могу владели тайнами колдовства и порабощало непокорных.$B$BМне свойственно любопытство, Пробудитель. Я желаю знать, что за империи были после меня.$B$BЗнание прошлого помогает постичь будущее.$B$BРазыщи же в руинах древние скрижали, дабы мне открылись тайные знания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 скрижалей Гуртани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, Пробудитель. Мне потребуется некоторое время, чтобы прочесть эти скрижали, но всякое знание ценно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Несешь ли ты новое знание?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31233,'Сбор смолы','Я нашел рощу молодых янтарных деревьев к востоку отсюда, Пробудитель.$B$BЯ поместил там емкости для сбора смолы, но у меня не было времени добыть его оттуда.$B$BМне нужно, чтобы кто-то нашел экстракторы. Активируй их и принеси мне образцы янтаря.','Соберите 6 образцов янтарной смолы.','Ах, да, именно это мне и было нужно.$B$BЯ изучу эти образцы. Мы должны продолжать следить за здоровьем этих молодых кипари.','Эти деревья еще молодые. Пока что их нельзя назвать "кипари".$B$BИх смола похожа на воду, а смола настоящего дерева кипари подобна вину.$B$BНадо дать им подрасти.','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор смолы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я нашел рощу молодых янтарных деревьев к востоку отсюда, Пробудитель.$B$BЯ поместил там емкости для сбора смолы, но у меня не было времени добыть его оттуда.$B$BМне нужно, чтобы кто-то нашел экстракторы. Активируй их и принеси мне образцы янтаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 образцов янтарной смолы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да, именно это мне и было нужно.$B$BЯ изучу эти образцы. Мы должны продолжать следить за здоровьем этих молодых кипари.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти деревья еще молодые. Пока что их нельзя назвать "кипари".$B$BИх смола похожа на воду, а смола настоящего дерева кипари подобна вину.$B$BНадо дать им подрасти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31234,'Выколоть глаз','Ах! Пробудитель! Ты $gдолжен:должна; помочь мне! (Ты поможешь мне, или же $gсам:сама; станешь материалом!)$B$BМне нужно больше материалов для экспериментов, да-да! (Кровь и кишки, сердца и мозги, языки и глаза, глаза, глаза!)$B$BК западу отсюда я видел существ, сделанных из тумана. У них такие чудесные, большие, круглые глазные яблоки! Они хорошо видят и не мигают!$B$BИди же, Пробудитель. Принеси мне безупречный глаз!','Добудьте 1 безупречный глаз болотного чудища.','Да, да! Чудесно! Какая вкуснотища!','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс в Жуткие пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выколоть глаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах! Пробудитель! Ты $gдолжен:должна; помочь мне! (Ты поможешь мне, или же $gсам:сама; станешь материалом!)$B$BМне нужно больше материалов для экспериментов, да-да! (Кровь и кишки, сердца и мозги, языки и глаза, глаза, глаза!)$B$BК западу отсюда я видел существ, сделанных из тумана. У них такие чудесные, большие, круглые глазные яблоки! Они хорошо видят и не мигают!$B$BИди же, Пробудитель. Принеси мне безупречный глаз!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 1 безупречный глаз болотного чудища.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да! Чудесно! Какая вкуснотища!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс в Жуткие пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31235,'Нет-нет-нет','C помощью драконьего ружья Шадо-Пан уничтожьте 20 яиц страхопрядов на террасе Гуртани.','Примитивное, но иногда полезное оружие.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет-нет-нет',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','C помощью драконьего ружья Шадо-Пан уничтожьте 20 яиц страхопрядов на террасе Гуртани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Примитивное, но иногда полезное оружие.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31237,'Борьба с насекомыми','Если императрица действительно страдает от паранойи, она пошлет разведчиков во все концы своей страны, чтобы укрепить свою власть.$B$BЭти личинки могут быть повсюду, но их сложно заметить невооруженным глазом. Лучше всего отслеживать их по следам феромонов, которые они оставляют за собой.$B$BЯ уже подарил тебе... реактивный яд, который ненадолго откроет тебе эти следы после того, как ты испытаешь радость от победы.$B$BОтправляйся на террасу Гуртан и вылови этих шпионов.','Растопчите 6 Очей Императрицы на террасе Гуртан. Убийство любого существа позволит вам отслеживать феромоны и поможет их обнаружить.','Знание – сила, Лунван. Нельзя, чтобы императрица отслеживала наши действия.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с насекомыми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если императрица действительно страдает от паранойи, она пошлет разведчиков во все концы своей страны, чтобы укрепить свою власть.$B$BЭти личинки могут быть повсюду, но их сложно заметить невооруженным глазом. Лучше всего отслеживать их по следам феромонов, которые они оставляют за собой.$B$BЯ уже подарил тебе... реактивный яд, который ненадолго откроет тебе эти следы после того, как ты испытаешь радость от победы.$B$BОтправляйся на террасу Гуртан и вылови этих шпионов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Растопчите 6 Очей Императрицы на террасе Гуртан. Убийство любого существа позволит вам отслеживать феромоны и поможет их обнаружить.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знание – сила, Лунван. Нельзя, чтобы императрица отслеживала наши действия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31238,'Пища для мозгов','Принесите 4 языка мушана Каз\'тику Манипулятору в Клакси\'весс.','Ковок скулил, бедняга, все время, пока тебя не было.','Ну что, будет нам чем кормить Ковока?','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пища для мозгов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 языка мушана Каз\'тику Манипулятору в Клакси\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ковок скулил, бедняга, все время, пока тебя не было.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, будет нам чем кормить Ковока?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31239,'Что тебе в имени-имени моем?','Значит, хочешь быть хозеном, шнуропс?$b$bХозены защищай свои земли от врагов, как цзинь-юй.$b$bКах-Ках раньше драться часто с цзинь-юй и побеждать всегда.$b$bХозен давай имя-имя только хороший грокер. Иди грокай цзинь-юй, и когда-нибудь тебя назвать $n-$n.$b$bЦзинь-юй ползай у реки. Бацай их по дукерам!','Уничтожьте 7 приречных цзинь-юй.','Ха-ха! Шнуропс грокай мопсельный цзинь-юй!','Поговорите с вождем Ках-Кахом на холме Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что тебе в имени-имени моем?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, хочешь быть хозеном, шнуропс?$b$bХозены защищай свои земли от врагов, как цзинь-юй.$b$bКах-Ках раньше драться часто с цзинь-юй и побеждать всегда.$b$bХозен давай имя-имя только хороший грокер. Иди грокай цзинь-юй, и когда-нибудь тебя назвать $n-$n.$b$bЦзинь-юй ползай у реки. Бацай их по дукерам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 приречных цзинь-юй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Шнуропс грокай мопсельный цзинь-юй!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Ках-Кахом на холме Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31240,'Нападение Го-лай','Приходила Аньцзи, искала тебя. Сказала еще, что направляется в северо-восточные руины.$B$BОх уж эта Аньцзи, такая пылкая! Лучше бы тебе не заставлять ее ждать, здоровее будешь.','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение Го-лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приходила Аньцзи, искала тебя. Сказала еще, что направляется в северо-восточные руины.$B$BОх уж эта Аньцзи, такая пылкая! Лучше бы тебе не заставлять ее ждать, здоровее будешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31241,'Гадкие шнуропсы','Они говорить, $n – добрый шнуропс...$b$bОни говорить, $n помогай хозенам...$b$bОни говорить, не надо больше грокать, $n.$b$bХорошо. Смотри сюда – гадкие шнуропсы падать, как дождь, их грокать в самый раз!$b$bТвоя иди, веселись! Но только чтоб все блестяшки Ках-Ках! Это правило хозенов номер два.$b$b<Джик-Джик чешет в затылке.>$b$bХм, у хозенов все правила номер два...','Соберите 6 медальонов воинов Альянса у закаленных в боях парашютистов.','Шнуропс грокать – хозен богатеть блестяшками!$B$BКляйснер делать хорошее второе впечатление. А для хозенов цифра два – самая важная!','Поговорите с вождем Ках-Кахом у холма Грукин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гадкие шнуропсы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они говорить, $n – добрый шнуропс...$b$bОни говорить, $n помогай хозенам...$b$bОни говорить, не надо больше грокать, $n.$b$bХорошо. Смотри сюда – гадкие шнуропсы падать, как дождь, их грокать в самый раз!$b$bТвоя иди, веселись! Но только чтоб все блестяшки Ках-Ках! Это правило хозенов номер два.$b$b<Джик-Джик чешет в затылке.>$b$bХм, у хозенов все правила номер два...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 медальонов воинов Альянса у закаленных в боях парашютистов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шнуропс грокать – хозен богатеть блестяшками!$B$BКляйснер делать хорошее второе впечатление. А для хозенов цифра два – самая важная!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Ках-Кахом у холма Грукин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31242,'Деревня Туманного Водопада','Мои разведчики сегодня не видели могу у деревни Туманного Водопада, зато на местном кладбище что-то явно происходит, живность и духи беспокоятся. Чэ уже отправился, чтобы выяснить, в чем дело, но мне нужна твоя помощь.$B$BОтправляйся в деревню, это на юго-западе, встретишь там Чэ. Дальше действуй по обстановке.','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Туманного Водопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики сегодня не видели могу у деревни Туманного Водопада, зато на местном кладбище что-то явно происходит, живность и духи беспокоятся. Чэ уже отправился, чтобы выяснить, в чем дело, но мне нужна твоя помощь.$B$BОтправляйся в деревню, это на юго-западе, встретишь там Чэ. Дальше действуй по обстановке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31243,'Нападение на деревню Туманного Водопада','Около деревни Туманного Водопада, что на юго-западе, видели могу. Туда уже отправились Рук и Сунь, но этого недостаточно.$B$BНе мешкай, жители деревни ждут тебя.','Поговорите с Сунь Доброе Сердце в деревне Туманного Водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на деревню Туманного Водопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Около деревни Туманного Водопада, что на юго-западе, видели могу. Туда уже отправились Рук и Сунь, но этого недостаточно.$B$BНе мешкай, жители деревни ждут тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сунь Доброе Сердце в деревне Туманного Водопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31244,'Лагерь Го-лай','Левен был не на шутку разъярен! Уходя, буркнул что-то о могу в руинах.$B$BДумаю, что надо его разыскать. С разгневанным Левеном хлопот не оберешься.','Поговорите с Левеном Рассветным Клинком в руинах Го-лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Го-лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Левен был не на шутку разъярен! Уходя, буркнул что-то о могу в руинах.$B$BДумаю, что надо его разыскать. С разгневанным Левеном хлопот не оберешься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Левеном Рассветным Клинком в руинах Го-лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31245,'Деревня Туманного Водопада','По дороге в деревню Чэ заходил сюда и спрашивал о тебе. Я ответил, что тебя не видел.$B$BМожешь сходить к нему, если хочешь. А если не хочешь – не ходи. И не надо потом говорить, что от меня нет толку!','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Туманного Водопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По дороге в деревню Чэ заходил сюда и спрашивал о тебе. Я ответил, что тебя не видел.$B$BМожешь сходить к нему, если хочешь. А если не хочешь – не ходи. И не надо потом говорить, что от меня нет толку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31246,'Нападение на деревню Туманного Водопада','Над деревней поднимается дым, и в этот раз я здесь ни при чем!$B$BНадо поспешить на помощь!','Поговорите с Руком Каменной Ступней в деревне Туманного Водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на деревню Туманного Водопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Над деревней поднимается дым, и в этот раз я здесь ни при чем!$B$BНадо поспешить на помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Руком Каменной Ступней в деревне Туманного Водопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31247,'Гарнизон Заходящего Солнца','По дороге в гарнизон Аньцзи и Кун остановились здесь. Прелестная парочка, да? Такие разные, но так преданы друг другу... Аж сердце от радости поет.$B$BОни спрашивали тебя. Может, хотят потренироваться на плацу? Надеюсь, обойдется без выкрутасов...','Поговорите с Аньцзи Осенним Светом в Гарнизоне Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гарнизон Заходящего Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По дороге в гарнизон Аньцзи и Кун остановились здесь. Прелестная парочка, да? Такие разные, но так преданы друг другу... Аж сердце от радости поет.$B$BОни спрашивали тебя. Может, хотят потренироваться на плацу? Надеюсь, обойдется без выкрутасов...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенним Светом в Гарнизоне Заходящего Солнца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31248,'Руины Го-Лай','Я велел Аньцзи и Куну еще раз осмотреть руины Го-Лай. Сейчас никто не видел там могу, но похоже, что именно это место интересует их больше, чем весь наш дол. Вон, на озеро нападали... Нельзя спускать с этого места глаз.$B$BПоэтому ты тоже отправишься туда.$B$BТебе нужно на север, мимо озера, в руины. Аньцзи объяснит, что делать дальше.','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я велел Аньцзи и Куну еще раз осмотреть руины Го-Лай. Сейчас никто не видел там могу, но похоже, что именно это место интересует их больше, чем весь наш дол. Вон, на озеро нападали... Нельзя спускать с этого места глаз.$B$BПоэтому ты тоже отправишься туда.$B$BТебе нужно на север, мимо озера, в руины. Аньцзи объяснит, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31249,'Деревня Туманного Водопада','Судя по донесениям, деревня оказалась нетронута атакой Шао-Тень у озера. Однако рисковать я не буду.$B$BВы с Чэ Диким Странником направитесь дозорными в деревню, заодно и селянам сможете подсобить.','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Туманного Водопада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по донесениям, деревня оказалась нетронута атакой Шао-Тень у озера. Однако рисковать я не буду.$B$BВы с Чэ Диким Странником направитесь дозорными в деревню, заодно и селянам сможете подсобить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Чэ Диким Странником в деревне Туманного Водопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31250,'Гарнизон Заходящего Солнца','Воины могу спускаются по Золотой лестнице, а часть их ударила нам по флангу у Озера Белых Лепестков. Мы понесли тяжелые потери, нас осталось слишком мало.$B$BТребуется срочно ускорить обучение новобранцев. Я отряжу Аньцзи и Куна в Гарнизон Заходящего Солнца, и тебе, $n, нужно отправиться туда вместе с ними. Покажи им, чего стоит $gнастоящий:настоящая:c; $c!','Поговорите с Аньцзи Осенним Светом в Гарнизоне Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гарнизон Заходящего Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воины могу спускаются по Золотой лестнице, а часть их ударила нам по флангу у Озера Белых Лепестков. Мы понесли тяжелые потери, нас осталось слишком мало.$B$BТребуется срочно ускорить обучение новобранцев. Я отряжу Аньцзи и Куна в Гарнизон Заходящего Солнца, и тебе, $n, нужно отправиться туда вместе с ними. Покажи им, чего стоит $gнастоящий:настоящая:c; $c!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенним Светом в Гарнизоне Заходящего Солнца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31251,'Самая лучшая еда','Ну да, ну да.\r\n\r\nВсе знают, что гоблины умеют чинить и взрывать. Ну и... еще ерундой всякой заниматься.\r\n\r\nНо никто не знает, что я, например, прекрасный повар! Люблю это дело.\r\n\r\nЗдесь столько зверья водится, добудь-ка мне мяса, а я уж его приготовлю, пальчики оближешь!\r\n\r\nИ кстати, топлива уйдет всего три-четыре процента.','Соберите 160 мясных кусочков Кунь-Лай.','Я настоящий повар – брюхатый, на кухне... и босой?','Вернитесь к Риветту Сталехвату в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самая лучшая еда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну да, ну да.\r\n\r\nВсе знают, что гоблины умеют чинить и взрывать. Ну и... еще ерундой всякой заниматься.\r\n\r\nНо никто не знает, что я, например, прекрасный повар! Люблю это дело.\r\n\r\nЗдесь столько зверья водится, добудь-ка мне мяса, а я уж его приготовлю, пальчики оближешь!\r\n\r\nИ кстати, топлива уйдет всего три-четыре процента.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 160 мясных кусочков Кунь-Лай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я настоящий повар – брюхатый, на кухне... и босой?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риветту Сталехвату в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31252,'Ну что ж, похоже, нам предстоит многое строить заново.\r\n\r\nЯ не любитель больших заварух, но у батраков моих, признаться, сейчас не так уж много работы. Они так благодарны тебе, что рвутся присоединиться к этому твоему Альянсу. Что ж мне, удерживать их силой?\r\n\r\nВеди их к батраку Бо. Мне будет не хватать их, но с тобой им явно лучше.','Хорошо, что вы вернулись вместе. Теперь мы столько еды заготовим, глазом моргнуть не успеешь.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, похоже, нам предстоит многое строить заново.\r\n\r\nЯ не любитель больших заварух, но у батраков моих, признаться, сейчас не так уж много работы. Они так благодарны тебе, что рвутся присоединиться к этому твоему Альянсу. Что ж мне, удерживать их силой?\r\n\r\nВеди их к батраку Бо. Мне будет не хватать их, но с тобой им явно лучше.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что вы вернулись вместе. Теперь мы столько еды заготовим, глазом моргнуть не успеешь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31253,'Ну что ж, похоже, нам предстоит многое строить заново.\r\n\r\nЯ обычно не присоединяюсь к большим заварухам, но у батраков моих, признаться, не так уж много работы сейчас. Они так благодарны тебе, что рвутся присоединиться к этой твоей Орде. Что ж мне, удерживать их силой?\r\n\r\nВеди их к батраку Ко. Мне будет не хватать моих людей, но пусть будет так.','Хорошо, что вы вернулись вместе. Теперь мы столько еды заготовим, глазом моргнуть не успеешь.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, похоже, нам предстоит многое строить заново.\r\n\r\nЯ обычно не присоединяюсь к большим заварухам, но у батраков моих, признаться, не так уж много работы сейчас. Они так благодарны тебе, что рвутся присоединиться к этой твоей Орде. Что ж мне, удерживать их силой?\r\n\r\nВеди их к батраку Ко. Мне будет не хватать моих людей, но пусть будет так.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что вы вернулись вместе. Теперь мы столько еды заготовим, глазом моргнуть не успеешь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31254,'Дорога в Кунь-Лай','Отправляйтесь в деревню Бинан по Сокрытой лестнице.','Ах, так ты друг Чо? Добро пожаловать!$B$B Мы бы закатили пир в твою честь, но, как видишь, нам сейчас очень туго.$B$BСлушай, может, выручишь нас?','Опять чужаки? Этот день – сплошное испытание.','Поднимитесь по Сокрытой лестнице, чтобы поговорить с мэром Ежевичным Посохом в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Кунь-Лай',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Бинан по Сокрытой лестнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так ты друг Чо? Добро пожаловать!$B$B Мы бы закатили пир в твою честь, но, как видишь, нам сейчас очень туго.$B$BСлушай, может, выручишь нас?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Опять чужаки? Этот день – сплошное испытание.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поднимитесь по Сокрытой лестнице, чтобы поговорить с мэром Ежевичным Посохом в деревне Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31255,'Дорога в Кунь-Лай','Отправляйтесь в деревню Бинан по Сокрытой лестнице.','Опять чужаки? Этот день – сплошное испытание.','Поднимитесь по Сокрытой лестнице, чтобы поговорить с мэром Ежевичным Посохом в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Кунь-Лай',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Бинан по Сокрытой лестнице.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Опять чужаки? Этот день – сплошное испытание.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поднимитесь по Сокрытой лестнице, чтобы поговорить с мэром Ежевичным Посохом в деревне Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31256,'Отлов яков','Лок\'тар, |3-6($c).\r\n\r\nНаши дела неплохи, но необходимо повысить мобильность войск, чтобы укрепить наше положение в Кунь-Лай.\r\n\r\nВоргов и кодоев в окрестностях немного, зато я видел яков. Наши союзники, пандарены, утверждают, что из них получаются хорошие ездовые животные, доверимся их совету.\r\n\r\nСобери несколько яков и пригони сюда, мы начнем их объезжать.','Отлично! Упрямые они, скотины. Но ничего, сгодятся и такие.','Что там с яками?','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов яков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лок\'тар, |3-6($c).\r\n\r\nНаши дела неплохи, но необходимо повысить мобильность войск, чтобы укрепить наше положение в Кунь-Лай.\r\n\r\nВоргов и кодоев в окрестностях немного, зато я видел яков. Наши союзники, пандарены, утверждают, что из них получаются хорошие ездовые животные, доверимся их совету.\r\n\r\nСобери несколько яков и пригони сюда, мы начнем их объезжать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Упрямые они, скотины. Но ничего, сгодятся и такие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там с яками?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Приют Восточного Ветра на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31260,'Охота за наживой: Чашин','Я замыслила еще одну великую аферу!$b$bПока я летела, я видела очень старую тигрицу, которая рыскала неподалеку.$b$bЗнаешь, сколько ее кровь будет стоить на черном рынке? Особенно если мне удастся убедить чернокнижников, что она усилит их заклятья призыва или что-то еще.$b$bПринеси мне немного ее крови, и я возьму тебя в долю. Она рыскала на дальнем берегу реки Доцзян.','Добудьте кровь старой тигрицы.','Впечатляет! Чуешь, как запахло деньгами? Вот твоя доля.','Я подумывала взять эту тигрицу самостоятельно, но если честно, мне еще жить хочется...','Поговорите с Даггл Бомбстер в Красарангских руинах, что в Красарангских джунглях.','Королева Диких зарослей','Чашин') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за наживой: Чашин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я замыслила еще одну великую аферу!$b$bПока я летела, я видела очень старую тигрицу, которая рыскала неподалеку.$b$bЗнаешь, сколько ее кровь будет стоить на черном рынке? Особенно если мне удастся убедить чернокнижников, что она усилит их заклятья призыва или что-то еще.$b$bПринеси мне немного ее крови, и я возьму тебя в долю. Она рыскала на дальнем берегу реки Доцзян.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кровь старой тигрицы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет! Чуешь, как запахло деньгами? Вот твоя доля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я подумывала взять эту тигрицу самостоятельно, но если честно, мне еще жить хочется...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских руинах, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Королева Диких зарослей',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Чашин',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31261,'Голова капитана Джека','Пока вы изучаете с таким трудом добытый трофей, из головы капитана Джека вытекает кровь и таинственным образом впитывается в землю.$b$bСтранно, однако расследовать это нет времени. У вас слишком много работы.$b$bВождь ваших новых союзников, несомненно, обрадуется, узнав о том, как ловко вы умеете грокать.','Отнесите голову капитана Джека вождю Ках-Каху, который находится на холме Грукин.','Бортельно грокнул, шнуропс!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова капитана Джека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока вы изучаете с таким трудом добытый трофей, из головы капитана Джека вытекает кровь и таинственным образом впитывается в землю.$b$bСтранно, однако расследовать это нет времени. У вас слишком много работы.$b$bВождь ваших новых союзников, несомненно, обрадуется, узнав о том, как ловко вы умеете грокать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову капитана Джека вождю Ках-Каху, который находится на холме Грукин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бортельно грокнул, шнуропс!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31262,'Охота на журавля: иглоклюв','Теперь, когда ты получил представление о том, как журавли сражаются, у меня для тебя есть нечто сногсшибательное.$b$bИглоклюв!$b$bНу, я его так называю. Самый здоровенный журавль из виденных мной. Его клюв острый как меч.$b$bК северо-западу отсюда есть большой водопад у реки Доцзян. Иглоклюв любит там бывать.$b$bПринеси мне его клюв в качестве трофея, и я отблагодарю тебя по-эрнестуэйски.','Добудьте иглоклюв.','Вот это я понимаю – трофей. Выглядит грозно. Погоди-ка... это твоя кровь на нем?','Я видел, как эта птица проткнула морду тигру. Что это за место такое, где птицы охотятся на тигров?','Поговорите с Даггл Бомбстер в Красарангских руинах, что в Красарангских джунглях.','Повелитель стаи','Иглоклюв') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на журавля: иглоклюв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты получил представление о том, как журавли сражаются, у меня для тебя есть нечто сногсшибательное.$b$bИглоклюв!$b$bНу, я его так называю. Самый здоровенный журавль из виденных мной. Его клюв острый как меч.$b$bК северо-западу отсюда есть большой водопад у реки Доцзян. Иглоклюв любит там бывать.$b$bПринеси мне его клюв в качестве трофея, и я отблагодарю тебя по-эрнестуэйски.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте иглоклюв.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это я понимаю – трофей. Выглядит грозно. Погоди-ка... это твоя кровь на нем?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я видел, как эта птица проткнула морду тигру. Что это за место такое, где птицы охотятся на тигров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Даггл Бомбстер в Красарангских руинах, что в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Повелитель стаи',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Иглоклюв',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31265,'Дыхание Мацзу','Хочешь помочь? Что ж, начнем с самого начала.$B$B<Ари шарит по карманам, а затем достает маленький флакон с синей светящейся жидкостью.>$B$BВот оно! "Дыхание Мацзу." Собственное изобретение капитана.$B$BЧто? Ты $gдумал:думала;, что я отправлю тебя в море, не позаботившись, чем тебе дышать? Мне нужны матросы, а не трупы!$B$BЗабирай его, салага. С его помощью ты сможешь победить на побережье.','Выпейте зелье "Дыхание Мацзу".','Потом поблагодаришь.','Поговорите с боцманом Ари в Приюте капитана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дыхание Мацзу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь помочь? Что ж, начнем с самого начала.$B$B<Ари шарит по карманам, а затем достает маленький флакон с синей светящейся жидкостью.>$B$BВот оно! "Дыхание Мацзу." Собственное изобретение капитана.$B$BЧто? Ты $gдумал:думала;, что я отправлю тебя в море, не позаботившись, чем тебе дышать? Мне нужны матросы, а не трупы!$B$BЗабирай его, салага. С его помощью ты сможешь победить на побережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте зелье "Дыхание Мацзу".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потом поблагодаришь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с боцманом Ари в Приюте капитана.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31266,'Набеги могу','Мы слышали донесения о нескольких группах могу, проникших на берег здесь, в Танлуне. Понятия не имею, что они тут делают, да мне и, честно говоря, все равно.\r\n\r\nНа тебя, похоже, можно положиться, так что мы решили дать это задание именно тебе.\r\n\r\nВот что предстоит сделать: иди, найди и убей их.\r\n\r\nНаши разведчики доложили, что первая группа высадилась на севере, на полпути отсюда до плато Толкователя Мертвых. Так что иди и расправься с ними.','Найдите и убейте шпиона Шань\'цзэ.','Это был обманный маневр! Они собираются атаковать храм Нюцао!','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набеги могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы слышали донесения о нескольких группах могу, проникших на берег здесь, в Танлуне. Понятия не имею, что они тут делают, да мне и, честно говоря, все равно.\r\n\r\nНа тебя, похоже, можно положиться, так что мы решили дать это задание именно тебе.\r\n\r\nВот что предстоит сделать: иди, найди и убей их.\r\n\r\nНаши разведчики доложили, что первая группа высадилась на севере, на полпути отсюда до плато Толкователя Мертвых. Так что иди и расправься с ними.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте шпиона Шань\'цзэ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это был обманный маневр! Они собираются атаковать храм Нюцао!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Снежному Вихрю в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31267,'Уничтожение клана Туманного Клинка','Корвен рассказал мне о своих изысканиях. Оказывается, глубоко под Озером Звезд расположены гигантские залежи янтаря.$B$BК несчастью, на берегу озера проживает враждебное племя сауроков, которые считают весь янтарь своим.$B$BОни не позволят нам попасть туда.$B$BОтправляйся на юг к озеру и убей сауроков из клана Туманного Клинка, чтобы мы смогли начать безопасную добычу янтаря.','Убейте 6 раздирателей из клана Туманного Клинка.','Превосходная работа. Из этого янтаря мы сможем изготовить оружие, в котором остро нуждаемся.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение клана Туманного Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корвен рассказал мне о своих изысканиях. Оказывается, глубоко под Озером Звезд расположены гигантские залежи янтаря.$B$BК несчастью, на берегу озера проживает враждебное племя сауроков, которые считают весь янтарь своим.$B$BОни не позволят нам попасть туда.$B$BОтправляйся на юг к озеру и убей сауроков из клана Туманного Клинка, чтобы мы смогли начать безопасную добычу янтаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 раздирателей из клана Туманного Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходная работа. Из этого янтаря мы сможем изготовить оружие, в котором остро нуждаемся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31268,'Работа мысли','Далеко на юге в болотах рождаются орудия разрушения – огромные, почти неуничтожимые янтарные скорпионы.$B$BКак и все создания, они подвержены гипнозу, но в отличие от остальных, еще не подчинились моему разуму.$B$BПохоже, чтобы я смог получить власть над ними, потребуются дополнительные исследования.$B$BМне надо изучить их мозг. Добудь для меня несколько экземпляров этих существ.$B$BВозьми звуковой излучатель. Он весьма эффективен против этих тварей.','Соберите 3 покрытых янтарем мозга с тел ик\'тиков-янтарожалов.','Хм-м, как интересно. Они не такие, как мозги, которые я видел раньше.$B$BЯ внимательно изучу их.','Они продолжают сопротивляться звуковому подчинению. Нужно понять, почему.','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа мысли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далеко на юге в болотах рождаются орудия разрушения – огромные, почти неуничтожимые янтарные скорпионы.$B$BКак и все создания, они подвержены гипнозу, но в отличие от остальных, еще не подчинились моему разуму.$B$BПохоже, чтобы я смог получить власть над ними, потребуются дополнительные исследования.$B$BМне надо изучить их мозг. Добудь для меня несколько экземпляров этих существ.$B$BВозьми звуковой излучатель. Он весьма эффективен против этих тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 покрытых янтарем мозга с тел ик\'тиков-янтарожалов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм-м, как интересно. Они не такие, как мозги, которые я видел раньше.$B$BЯ внимательно изучу их.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они продолжают сопротивляться звуковому подчинению. Нужно понять, почему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31269,'Чешуйчатый повелитель','Сауроки у Озера Звезд подчиняются лютому и злобному чешуйчатому повелителю, а он свои земли защищает яростно.$B$BЕсли бы нам удалось прикончить их вожака, то мы бы с легкостью завладели залежами янтаря под водами озера.$B$BИди же! Жилище главаря сауроков находится под землей у южного берега озера. Оттуда он и руководит своими соплеменниками.','Убейте чешуйчатого повелителя из клана Туманного Клинка.','Хорошо. Рад слышать, что он мертв.','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чешуйчатый повелитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки у Озера Звезд подчиняются лютому и злобному чешуйчатому повелителю, а он свои земли защищает яростно.$B$BЕсли бы нам удалось прикончить их вожака, то мы бы с легкостью завладели залежами янтаря под водами озера.$B$BИди же! Жилище главаря сауроков находится под землей у южного берега озера. Оттуда он и руководит своими соплеменниками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чешуйчатого повелителя из клана Туманного Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Рад слышать, что он мертв.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31270,'Схватка со страхом','После того как присутствие ша в Кипари Зар стало очевидным, мне хотелось верить, что нам удастся избавиться от скверны.$B$BК несчастью, Совет клакси подтвердил, что скверна укоренилась глубоко и продолжает распространяться.$B$BК югу отсюда я видел животных, измененных до неузнаваемости ужасной темной силой.$B$BШа превращают свои жертвы во что-то неописуемо жуткое.$B$BМы должны помешать распространению этой скверны. Выследи запятнанных ша мерзкочешуйчатых скорпидов и убей их.','Убейте 15 мерзкочешуйчатых скорпидов.','Тебе удалось очистить холмы от зараженных животных? Прекрасно.$B$BШа – безжалостный враг, нам не пристало испытывать жалость.','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Схватка со страхом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как присутствие ша в Кипари Зар стало очевидным, мне хотелось верить, что нам удастся избавиться от скверны.$B$BК несчастью, Совет клакси подтвердил, что скверна укоренилась глубоко и продолжает распространяться.$B$BК югу отсюда я видел животных, измененных до неузнаваемости ужасной темной силой.$B$BШа превращают свои жертвы во что-то неописуемо жуткое.$B$BМы должны помешать распространению этой скверны. Выследи запятнанных ша мерзкочешуйчатых скорпидов и убей их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 мерзкочешуйчатых скорпидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось очистить холмы от зараженных животных? Прекрасно.$B$BШа – безжалостный враг, нам не пристало испытывать жалость.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31271,'Дурные гены','Далеко на юге, Пробудитель, скрещиватели императрицы проводят свои черные эксперименты. (Черные, но мои чернее!)$B$BОни препарируют местную фауну и вызывают у нее мутации, создавая существ по своим разработкам. (Разработкам, которые станут моими!)$B$BНельзя, чтобы они добились своего! (Нет, нет! Только мне может быть подвластна такая сила!)$B$BИх мутанты уже используются на войне. Иди и уничтожь их, во что бы то ни стало!','Убейте 3 ик\'тиков-скрещивателей и 6 ик\'тиков – смотрителей яиц.','Да, да! Они мертвы!$B$BСпасибо тебе, Пробудитель. Отличная работа.','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс в Жуткие пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурные гены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далеко на юге, Пробудитель, скрещиватели императрицы проводят свои черные эксперименты. (Черные, но мои чернее!)$B$BОни препарируют местную фауну и вызывают у нее мутации, создавая существ по своим разработкам. (Разработкам, которые станут моими!)$B$BНельзя, чтобы они добились своего! (Нет, нет! Только мне может быть подвластна такая сила!)$B$BИх мутанты уже используются на войне. Иди и уничтожь их, во что бы то ни стало!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 ик\'тиков-скрещивателей и 6 ик\'тиков – смотрителей яиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да! Они мертвы!$B$BСпасибо тебе, Пробудитель. Отличная работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс в Жуткие пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31272,'Заражение','Скрещиватели императрицы играют в опасную игру.$B$BК югу отсюда они впрыскивают в местных существ паразитов, полных феромонов, пытаясь создать для своей армии чудовищных мутантов.$B$BОни беспечно позволили червям-паразитам сбежать и затеряться в местной экосистеме.$B$BБез контроля со стороны инфекция распространится между животными, поэтому мы должны что-то предпринять.$B$BЯ ввел тебе слабый токсин. С ним ты сможешь распознать зараженных существ.$B$BНемедленно убей всех носителей паразитов.','Убейте 6 зараженных тварей. Заражены могут быть костепылые мотыльки, синешкурые мушаны и мутирующие скорпиды.','Значит, инфекция распространялась. Ты сдержал ее вовремя.$B$BСомневаюсь, что скрещиватели прекратят эти отвратительные эксперименты, но мы продолжим мешать им.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заражение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скрещиватели императрицы играют в опасную игру.$B$BК югу отсюда они впрыскивают в местных существ паразитов, полных феромонов, пытаясь создать для своей армии чудовищных мутантов.$B$BОни беспечно позволили червям-паразитам сбежать и затеряться в местной экосистеме.$B$BБез контроля со стороны инфекция распространится между животными, поэтому мы должны что-то предпринять.$B$BЯ ввел тебе слабый токсин. С ним ты сможешь распознать зараженных существ.$B$BНемедленно убей всех носителей паразитов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 зараженных тварей. Заражены могут быть костепылые мотыльки, синешкурые мушаны и мутирующие скорпиды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, инфекция распространялась. Ты сдержал ее вовремя.$B$BСомневаюсь, что скрещиватели прекратят эти отвратительные эксперименты, но мы продолжим мешать им.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31273,'Реликвии роя','PH','PH','PH') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','PH',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','PH',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','PH',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31277,'Внезапная атака!','Проклятые могу!\r\n\r\nОказывается, эти шпионы просто отвлекали наше внимание! А пока мы бегали за ними, основные силы могу передвинулись к храму Нюцзао. Оскверненные змеи, повсюду полно могу... просто катастрофа!\r\n\r\nК счастью, Баню удалось пробиться – ему и храбрейшим членам нашего ордена. Если тебе удастся повторить этот подвиг, встреться с ним. Надо остановить этот кошмар!','Встретьтесь с Банем Медвежьим Сердцем снаружи храма Нюцзао в Танлунских степях и остановите вторжение могу.','Храм Нюцзао спасен, могу отступили! И ты удостоишься великой чести.$B$BМы посвятим тебя в шадо-паны.','Вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внезапная атака!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые могу!\r\n\r\nОказывается, эти шпионы просто отвлекали наше внимание! А пока мы бегали за ними, основные силы могу передвинулись к храму Нюцзао. Оскверненные змеи, повсюду полно могу... просто катастрофа!\r\n\r\nК счастью, Баню удалось пробиться – ему и храбрейшим членам нашего ордена. Если тебе удастся повторить этот подвиг, встреться с ним. Надо остановить этот кошмар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Банем Медвежьим Сердцем снаружи храма Нюцзао в Танлунских степях и остановите вторжение могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Храм Нюцзао спасен, могу отступили! И ты удостоишься великой чести.$B$BМы посвятим тебя в шадо-паны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баню Медвежьему Сердцу в гарнизон Шадо-Пан в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31278,'Научиться проходить задания','Whee! You get to make a breadcrumb quest! Now figure out what to do next.','Выполнить задание о хлебных крошках.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Научиться проходить задания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Whee! You get to make a breadcrumb quest! Now figure out what to do next.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выполнить задание о хлебных крошках.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31279,'Все, что я знаю о кулинарии','Как меня радует, что тебе понравилась моя еда. Может, тебе нужны рецепты? Если да, то тебе стоит обучиться им у опытных кулинаров на рынке Полугорья. Они научили меня всему, что я знаю о кулинарии.$b$bЕсли соберешься на рынок Полугорья, не захватишь с собой письмо для Суншинь Железной Лапы? Она была моим любимым учителем. Хочу, чтобы она знала, как я скучаю по ней.','Доставьте письмо Суншинь Железной Лапе. Она обучает желающих на рынке Полугорья.','Очень приятно. Люблю получать вести от своих бывших учеников.','У тебя есть письмо для меня?','Доставьте письмо Суншинь Железной Лапе. Она обучает желающих на рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все, что я знаю о кулинарии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как меня радует, что тебе понравилась моя еда. Может, тебе нужны рецепты? Если да, то тебе стоит обучиться им у опытных кулинаров на рынке Полугорья. Они научили меня всему, что я знаю о кулинарии.$b$bЕсли соберешься на рынок Полугорья, не захватишь с собой письмо для Суншинь Железной Лапы? Она была моим любимым учителем. Хочу, чтобы она знала, как я скучаю по ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Суншинь Железной Лапе. Она обучает желающих на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень приятно. Люблю получать вести от своих бывших учеников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть письмо для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте письмо Суншинь Железной Лапе. Она обучает желающих на рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31280,'Ways of Cooking','There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.','Learn the recipes for Charbroiled Tiger Steak, Jade Forest Fried Rice, Swirling Mist Soup, Shrimp Dumplings, Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market.','Return to the Guide to the Ways.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ways of Cooking',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Learn the recipes for Charbroiled Tiger Steak, Jade Forest Fried Rice, Swirling Mist Soup, Shrimp Dumplings, Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to the Guide to the Ways.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31281,'Так ты хочешь быть поваром?','Хочешь стать шеф-поваром? Если будешь усердно заниматься, я помогу раскрыть твой внутренний потенциал, и неважно, что у тебя нет опыта.$b$bЕсли хочешь учиться, покажи мне, что можешь по крайней мере следовать простым инструкциям. Научись нарезать персики и покажи мне, что получается. У меня есть свежие пандаренские персики, которые я продам тебе за символическую плату.','Научитесь готовить разрезанные персики у наставницы и принесите ей 5 порций готового блюда.','Очень хорошо. Голова на плечах у тебя есть. Я могу многое тебе рассказать, и у меня есть большая часть нужных составляющих процесса обучения. Учись со мной.','Покажи мне, что ты можешь следовать инструкциям.','Отдайте наставнице 5 разрезанных персиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так ты хочешь быть поваром?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь стать шеф-поваром? Если будешь усердно заниматься, я помогу раскрыть твой внутренний потенциал, и неважно, что у тебя нет опыта.$b$bЕсли хочешь учиться, покажи мне, что можешь по крайней мере следовать простым инструкциям. Научись нарезать персики и покажи мне, что получается. У меня есть свежие пандаренские персики, которые я продам тебе за символическую плату.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Научитесь готовить разрезанные персики у наставницы и принесите ей 5 порций готового блюда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Голова на плечах у тебя есть. Я могу многое тебе рассказать, и у меня есть большая часть нужных составляющих процесса обучения. Учись со мной.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи мне, что ты можешь следовать инструкциям.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте наставнице 5 разрезанных персиков.',`completedtext_loc8`);
