INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31285,'Весенняя лодка','Переживите путешествие на "Весенней лодке".','Ну вот, у нас все получилось. Добро пожаловать в деревню Бинан.','Поговорите с хмелеваром Буфом в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Весенняя лодка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переживите путешествие на "Весенней лодке".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, у нас все получилось. Добро пожаловать в деревню Бинан.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хмелеваром Буфом в деревне Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31286,'Грабь награбленное','А, |3-6($c). Мне бы очень пригодились твои таланты.$b$bТут недалеко на конвой напала банда мародерствующих сауроков. И эти мародеры забрали кое-какие... товары, которые ее светлость мадам Гойя собиралась продать.$b$bНельзя красть у ее светлости.$b$bЕсли ты вернешь эти товары, я с удовольствием вознагражу тебя.','Верните 7 товаров черного рынка.','А, наши товары. Мадам Гойя будет очень рада. Тебе удалось заслужить ее благодарность.','Сауроки редко ведут себя так нагло.','Поговорите с Лэнем Шептуном в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабь награбленное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, |3-6($c). Мне бы очень пригодились твои таланты.$b$bТут недалеко на конвой напала банда мародерствующих сауроков. И эти мародеры забрали кое-какие... товары, которые ее светлость мадам Гойя собиралась продать.$b$bНельзя красть у ее светлости.$b$bЕсли ты вернешь эти товары, я с удовольствием вознагражу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 7 товаров черного рынка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, наши товары. Мадам Гойя будет очень рада. Тебе удалось заслужить ее благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сауроки редко ведут себя так нагло.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лэнем Шептуном в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31287,'"Просвещение" сауроков','Весенняя тропа находится под покровительством ее светлости, достопочтенной мадам Гойи.$b$bСауроки из логова клана Грозной Чешуи обязательно должны усвоить этот урок. Мы их уже предупреждали, но, к сожалению, они, похоже, отличаются очень короткой памятью.$b$bОтправляйся на северо-восток к этому логову и найди их вождя-шамана. Убей его и получишь благодарность ее светлости. Вместе с приличествующим вознаграждением.','Победить Пальцепийцу.','Дело сделано, счет должен быть оплачен. Вот твое вознаграждение. И прими нашу благодарность.','Поговорите с Лэнем Шептуном в таверне "В туманах", что на Сокрытой лестнице.','Шаман Грозной Чешуи','Пальцепийца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Просвещение" сауроков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Весенняя тропа находится под покровительством ее светлости, достопочтенной мадам Гойи.$b$bСауроки из логова клана Грозной Чешуи обязательно должны усвоить этот урок. Мы их уже предупреждали, но, к сожалению, они, похоже, отличаются очень короткой памятью.$b$bОтправляйся на северо-восток к этому логову и найди их вождя-шамана. Убей его и получишь благодарность ее светлости. Вместе с приличествующим вознаграждением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победить Пальцепийцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано, счет должен быть оплачен. Вот твое вознаграждение. И прими нашу благодарность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лэнем Шептуном в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Шаман Грозной Чешуи',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пальцепийца',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31288,'Исследовательский проект: династии могу','А, ты любишь странствия! Очень хорошо. Я нахожусь на пороге разгадки темных секретов могу.$b$bНу, не всех, конечно. У них много темных секретов. Но я на пороге открытия по крайней мере одного из них.$b$bЕсли в странствиях тебе попадутся какие-нибудь свидетельства прошлого могу, принеси их мне, и я щедро тебя за это отблагодарю.','Раздобудьте 20 фрагментов артефакта могу.','О, тут есть кое-что полезное. Кое-что очень даже полезное. Спасибо, искатель приключений.','Это опасно – забывать о нашем прошлом.','Поговорите с мастером Лю в Обители Мудрости в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследовательский проект: династии могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, ты любишь странствия! Очень хорошо. Я нахожусь на пороге разгадки темных секретов могу.$b$bНу, не всех, конечно. У них много темных секретов. Но я на пороге открытия по крайней мере одного из них.$b$bЕсли в странствиях тебе попадутся какие-нибудь свидетельства прошлого могу, принеси их мне, и я щедро тебя за это отблагодарю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 20 фрагментов артефакта могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, тут есть кое-что полезное. Кое-что очень даже полезное. Спасибо, искатель приключений.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это опасно – забывать о нашем прошлом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Лю в Обители Мудрости в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31289,'Исследовательский проект: империя пандаренов','А, $gискатель:искательница; приключений! Ты очень вовремя. Мы с дочкой изучаем историю нашего народа и уперлись в тупик.$b$bЕсли тебе попадутся фрагменты прошлого пандаренов, пожалуйста, принеси их нам сюда. Мы очень нуждаемся в дополнительной информации.','Раздобудьте 20 археологических находок пандаренов.','Поговорите с мастером Лю в Обители Мудрости в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследовательский проект: империя пандаренов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $gискатель:искательница; приключений! Ты очень вовремя. Мы с дочкой изучаем историю нашего народа и уперлись в тупик.$b$bЕсли тебе попадутся фрагменты прошлого пандаренов, пожалуйста, принеси их нам сюда. Мы очень нуждаемся в дополнительной информации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 20 археологических находок пандаренов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Лю в Обители Мудрости в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31291,'Открывая прошлое','Хочешь стать $gхранителем:хранительницей; истории? Придется много копаться в прошлом и читать, а потом еще копаться в прошлом и снова читать.$b$bЯ, бывает, целыми днями таращусь на осколки вазы, пытаясь сообразить, как их соединить.$b$bМожешь попробовать. Иди и раскрой тайну одного из артефактов Пандарии, и мы будем очень благодарны, если ты расскажешь нам потом, как тебе это удалось.','Раскройте тайну одного артефакта Пандарии.','Ух ты! У тебя так хорошо получилось соединить эти кусочки! Качество реставрации просто изумительное.$B$BКак у тебя это получилось?','Начинаю сомневаться, что у меня когда-нибудь получится раскрыть тайну этой штуки.','Поговорите с мисс Тай в Обители Мудрости в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открывая прошлое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь стать $gхранителем:хранительницей; истории? Придется много копаться в прошлом и читать, а потом еще копаться в прошлом и снова читать.$b$bЯ, бывает, целыми днями таращусь на осколки вазы, пытаясь сообразить, как их соединить.$b$bМожешь попробовать. Иди и раскрой тайну одного из артефактов Пандарии, и мы будем очень благодарны, если ты расскажешь нам потом, как тебе это удалось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раскройте тайну одного артефакта Пандарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! У тебя так хорошо получилось соединить эти кусочки! Качество реставрации просто изумительное.$B$BКак у тебя это получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Начинаю сомневаться, что у меня когда-нибудь получится раскрыть тайну этой штуки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мисс Тай в Обители Мудрости в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31292,'FLAG - Ancient Pandaren Woodcutter') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Ancient Pandaren Woodcutter',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31293,'Могу – плохие гости','Левен послал Рука остановить могу, но их оказалось слишком много. Рук один не справится.$B$BПоможешь ему? А он взамен доложит Левену о твоей помощи. Обещаю.','Убейте 8 налетчиков шадо-тянь в деревне Туманного Водопада.','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могу – плохие гости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Левен послал Рука остановить могу, но их оказалось слишком много. Рук один не справится.$B$BПоможешь ему? А он взамен доложит Левену о твоей помощи. Обещаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 налетчиков шадо-тянь в деревне Туманного Водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руку Каменной Ступне в деревню Туманного Водопада в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31294,'Руины Го-Лай','Прими мою искреннюю благодарность за твою постоянную помощь. Аньцзи ждет у руин Го-Лай к северо-западу отсюда.$B$BДа осенит тебя удача, $gюный:юная:c; |3-6($c).','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прими мою искреннюю благодарность за твою постоянную помощь. Аньцзи ждет у руин Го-Лай к северо-западу отсюда.$B$BДа осенит тебя удача, $gюный:юная:c; |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31295,'Могу внутри руин Го-Лай','Спасибо за помощь, |3-6($c).$B$BЯ бы и дольше наслаждался твоим обществом, но Левен у руин Го-Лай ведет атаку на могу и ждет твоей помощи.$B$BДа защитят тебя небесные силы!','Поговорите c Левеном Рассветным Клинком у руин Го-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могу внутри руин Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо за помощь, |3-6($c).$B$BЯ бы и дольше наслаждался твоим обществом, но Левен у руин Го-Лай ведет атаку на могу и ждет твоей помощи.$B$BДа защитят тебя небесные силы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите c Левеном Рассветным Клинком у руин Го-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31296,'Руины Го-Лай','Жители деревни, похоже, в безопасности, а могу отступают все дальше. Теперь мы сами сможем с ними разобраться. Спасибо за помощь, $n.$B$BСегодня утром Аньцзи поведет группу, чтобы обследовать территорию и расчистить руины Го-Лай к северо-востоку. Уверен, она оценит помощь кого-то неглупого... вроде тебя. Тебе следует пойти к ней.','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Го-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жители деревни, похоже, в безопасности, а могу отступают все дальше. Теперь мы сами сможем с ними разобраться. Спасибо за помощь, $n.$B$BСегодня утром Аньцзи поведет группу, чтобы обследовать территорию и расчистить руины Го-Лай к северо-востоку. Уверен, она оценит помощь кого-то неглупого... вроде тебя. Тебе следует пойти к ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аньцзи Осенний Свет на руинах Го-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31297,'Гарнизон Заходящего Солнца','Могу скоро не смогут атаковать с той же силой. Дальше мы сами сможем разобраться. Спасибо за твою помощь.$B$BНе хочешь ли ты встретиться с Аньцзи в Гарнизоне Заходящего Солнца на востоке? Ей поручили подготовить новеньких пандаренов для помощи в этом деле. Ты, наверное, тоже сможешь их чему-то научить, полагаю.','Поговорить с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гарнизон Заходящего Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу скоро не смогут атаковать с той же силой. Дальше мы сами сможем разобраться. Спасибо за твою помощь.$B$BНе хочешь ли ты встретиться с Аньцзи в Гарнизоне Заходящего Солнца на востоке? Ей поручили подготовить новеньких пандаренов для помощи в этом деле. Ты, наверное, тоже сможешь их чему-то научить, полагаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорить с Аньцзи Осенний Свет в Гарнизоне Заходящего Солнца.',`objectives_loc8`);
