INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31302,'Путь к величию','Похоже, тебе удалось освоить искусство готовки. Докажи это и приготовь мне 5 мисок рисового пудинга.','Приготовьте 5 порций рисового пудинга и отдайте их Показывающей Путь.','Все отлично. Тебе удалось постичь дзен кулинарии.','Не сомневаюсь, ты можешь стать отличным шеф-поваром, но я не верю словам, я верю пудингам, если можно так сказать.','Вернитесь к Показывающей Путь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к величию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, тебе удалось освоить искусство готовки. Докажи это и приготовь мне 5 мисок рисового пудинга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приготовьте 5 порций рисового пудинга и отдайте их Показывающей Путь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все отлично. Тебе удалось постичь дзен кулинарии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не сомневаюсь, ты можешь стать отличным шеф-поваром, но я не верю словам, я верю пудингам, если можно так сказать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Показывающей Путь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31303,'Печать сломана','<Чо смотрит на вас c неверием.>$b$bЯ... я думал, что ша такой силы – это миф... Мы все так думали. Мы пугали ими детишек, чтобы они не ссорились$b$bСейчас на разговоры нет времени. Эти трещины подпитывают ша, они становятся сильнее с каждой секундой!$b$bЯ должен покопаться в моих семейных архивах. А ты возьми эту пушку и иди к Миши.$b$bНадо найти способ сдержать ша, пока он не распоясался окончательно!','Закройте 12 трещин, чтобы изгнать Ша Сомнения.','У меня очень много дел и очень мало времени.$B$BИмператор предупреждал нас об угрозе, которую принесет война... о Ша.$B$BНо сейчас уже поздно. А о том, как положить конец кризису, Знамение Императора ничего не говорит.','Поговорите с хранителем истории Чо в Змеином Сердце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать сломана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Чо смотрит на вас c неверием.>$b$bЯ... я думал, что ша такой силы – это миф... Мы все так думали. Мы пугали ими детишек, чтобы они не ссорились$b$bСейчас на разговоры нет времени. Эти трещины подпитывают ша, они становятся сильнее с каждой секундой!$b$bЯ должен покопаться в моих семейных архивах. А ты возьми эту пушку и иди к Миши.$b$bНадо найти способ сдержать ша, пока он не распоясался окончательно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте 12 трещин, чтобы изгнать Ша Сомнения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня очень много дел и очень мало времени.$B$BИмператор предупреждал нас об угрозе, которую принесет война... о Ша.$B$BНо сейчас уже поздно. А о том, как положить конец кризису, Знамение Императора ничего не говорит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Змеином Сердце.',`completedtext_loc8`);
