INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31305,'Путь Гриля','If you wish to cook foods that make you stronger, go seek the Master of the Grill. Cook him a skewered peanut chicken to show him that you have the basics.','Make a Skewered Peanut Chicken and give it to the Master of the Grill.','Give the Skewered Chicken to the Master of the Grill.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Гриля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','If you wish to cook foods that make you stronger, go seek the Master of the Grill. Cook him a skewered peanut chicken to show him that you have the basics.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Make a Skewered Peanut Chicken and give it to the Master of the Grill.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Give the Skewered Chicken to the Master of the Grill.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31306,'Причуда Искателя','Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной."$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.','Пройдите путь под названием "Причуда Искателя", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.','О, ты здесь! И ты почтила все святилища!$B$BЯ знал, что ты справишься.','Поговорите с хранителем истории Чо в лагере Искателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Причуда Искателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что у твоего пандарийского друга есть пара идей насчет планов могу.$B$BОн пошел на гору пару дней назад без проводника и сказал, что лишь ты $gдолжен:должна; последовать за ним. Он выразился очень конкретно:$B$B"$c $gдолжен:должна; пройти этот путь без чьей-либо помощи, наедине со своими мыслями. Пусть $gон:она; почтит каждое святилище по пути, прежде чем встретится со мной."$B$BЭта тропа находится к северо-западу от лагеря, она отмечена флагами. Пожалуйста, будь осторожнее! Причуда Искателя – опасный маршрут, даже если тебе сопутствует удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите путь под названием "Причуда Искателя", чтобы найти хранителя истории Чо. По пути остановитесь у трех храмов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ты здесь! И ты почтила все святилища!$B$BЯ знал, что ты справишься.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в лагере Искателя.',`completedtext_loc8`);
