INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31308,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Маркусу Йенсену и расскажите ему о своей победе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маркусу Йенсену и расскажите ему о своей победе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31309,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрительнице стойл Ирме, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Ирмой.','Вернитесь к Маркусу Йенсену в Златоземье.','Ирма, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.','Ирма') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрительнице стойл Ирме, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Ирмой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маркусу Йенсену в Златоземье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Ирма, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ирма',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31310,'Interrogation Tracking') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Interrogation Tracking',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31311,'Путь Гриля','Пандаренский Путь Гриля позволяет готовить блюда, прибавляющие сил. Принеси мастеру Гриля немного сырых стейков из тигриного мяса, и он покажет тебе, как их готовить. В Нефритовом лесу и Красарангских джунглях много тигров. Кроме того, ты можешь найти их и в других местах.','Принесите 5 сырых стейков из тигриного мяса мастеру гриля.','Хорошо.','Чтобы познать Путь Гриля, принеси мне сырых стейков из тигриного мяса.','Отдайте 5 обугленных стейков из тигра мастеру гриля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Гриля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандаренский Путь Гриля позволяет готовить блюда, прибавляющие сил. Принеси мастеру Гриля немного сырых стейков из тигриного мяса, и он покажет тебе, как их готовить. В Нефритовом лесу и Красарангских джунглях много тигров. Кроме того, ты можешь найти их и в других местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 сырых стейков из тигриного мяса мастеру гриля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы познать Путь Гриля, принеси мне сырых стейков из тигриного мяса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте 5 обугленных стейков из тигра мастеру гриля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31312,'Старая карта','Старая выцветшая кожа буквально рассыпается у вас в руках, но надписи все еще можно разобрать.$B$BНа ней нарисована карта и написано следующее:$B$BВ равнине, где четыре ветра правят бал,$BСмеется девушка за веером златым$BИ у подножья лестницы, что предки возвели,$BОна секреты шепчет в гулкой темноте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старая карта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старая выцветшая кожа буквально рассыпается у вас в руках, но надписи все еще можно разобрать.$B$BНа ней нарисована карта и написано следующее:$B$BВ равнине, где четыре ветра правят бал,$BСмеется девушка за веером златым$BИ у подножья лестницы, что предки возвели,$BОна секреты шепчет в гулкой темноте.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31313,'Просто легенда','Что? Глупость какая-то!<У нее вытягивается лицо.>$B$BЧто это за ерунда про девушку, предков и какую-то там лестницу?$B$BНичего не понимаю. А ты?$B$BЛадно, тут есть кого поспрошать, тех, кто постарше нас с тобой будет.$B$BПоспрашивай народ в Полугорье. Наверняка они что-нибудь да знают.','Поговорите с сортировщиком зерна Пэем, резчиком Маком, мамой Минь и со стариком Седым Усом.','Ну конечно! Очень логично! Значит, сокровища спрятаны где-то там, где горы подступают к озеру.','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просто легенда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Глупость какая-то!<У нее вытягивается лицо.>$B$BЧто это за ерунда про девушку, предков и какую-то там лестницу?$B$BНичего не понимаю. А ты?$B$BЛадно, тут есть кого поспрошать, тех, кто постарше нас с тобой будет.$B$BПоспрашивай народ в Полугорье. Наверняка они что-нибудь да знают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сортировщиком зерна Пэем, резчиком Маком, мамой Минь и со стариком Седым Усом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну конечно! Очень логично! Значит, сокровища спрятаны где-то там, где горы подступают к озеру.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбе Тростниковой Шкуре на Камышовое озеро или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31314,'Сокровище Старого Шипа','Ох, очуметь можно! Теперь это самая настоящая охота за сокровищами!$B$BВидимо, на севере, где горы подступают к Камышовому озеру, должен быть какой-то вход или проход.$B$BТам-то мы и с тобой встретимся! На поиски сокровищ!','Найдите вход в пещеру и отыщите клад Старого Шипа.','Крышка сундука легко открывается. Вы заглядываете внутрь...','Найдите клад в Пещере Бесконечного Эха, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Старого Шипа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, очуметь можно! Теперь это самая настоящая охота за сокровищами!$B$BВидимо, на севере, где горы подступают к Камышовому озеру, должен быть какой-то вход или проход.$B$BТам-то мы и с тобой встретимся! На поиски сокровищ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите вход в пещеру и отыщите клад Старого Шипа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крышка сундука легко открывается. Вы заглядываете внутрь...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите клад в Пещере Бесконечного Эха, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (31315,'Наследие Плодородных Земель','На самом дне сундука с сокровищами вы находите свитки и мешочек из мягкой кожи, наполненный семенами.$B$BВ этих свитках – очень подробные земледельческие заметки, изображения растений, числа и подсчеты, места расположения источников и масса другой информации.$B$BНаверняка, это будет интересно кому-нибудь в совете фермеров.','Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Плодородных Земель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На самом дне сундука с сокровищами вы находите свитки и мешочек из мягкой кожи, наполненный семенами.$B$BВ этих свитках – очень подробные земледельческие заметки, изображения растений, числа и подсчеты, места расположения источников и масса другой информации.$B$BНаверняка, это будет интересно кому-нибудь в совете фермеров.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31316,'Джулия, укротительница питомцев','Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bДжулию Стивенс можно найти на виноградниках Маклура, это к югу от Штормграда. Она – начинающая укротительница диких питомцев и, думаю, тебе стоит вызвать ее на поединок!','Победите Джулию Стивенс в битве питомцев.','С этими питомцами ты куда сильнее, чем я думала!','Поговорите с Джулией Стивенс.','Испытай себя, сразившись с Джулией!','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джулия, укротительница питомцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bДжулию Стивенс можно найти на виноградниках Маклура, это к югу от Штормграда. Она – начинающая укротительница диких питомцев и, думаю, тебе стоит вызвать ее на поединок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Джулию Стивенс в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С этими питомцами ты куда сильнее, чем я думала!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джулией Стивенс.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Испытай себя, сразившись с Джулией!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Одри Бернхеп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31317,'Tracking Event: Found Entrance') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Event: Found Entrance',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31318,'Tracking Event: Found Treasure') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Event: Found Treasure',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31319,'Срочные меры','Твои товарищи обжились в этих местах. Но вместе с ними сюда пришла война.$b$bПока что мы не знаем всех последствий, но то, что мы уже видели... просто чудовищно.$b$bИ тем не менее, мы не можем оставить твоих друзей, поддавшись злости. Те из них, кто остался в живых, наверняка ранены и нуждаются в помощи.$b$bЭти фейерверки должны были запустить в честь окончания строительства статуи. Используй их, чтобы подать сигнал Миши, он заберет твоих товарищей.','Запустите фейерверки Чо рядом с адмиралом Тейлором, Мишкой и Салли.','Мысленно я буду с твоими товарищами, странник.$B$BПусть за ними присмотрят.','Поговорите с хранителем истории Чо в Змеином Сердце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои товарищи обжились в этих местах. Но вместе с ними сюда пришла война.$b$bПока что мы не знаем всех последствий, но то, что мы уже видели... просто чудовищно.$b$bИ тем не менее, мы не можем оставить твоих друзей, поддавшись злости. Те из них, кто остался в живых, наверняка ранены и нуждаются в помощи.$b$bЭти фейерверки должны были запустить в честь окончания строительства статуи. Используй их, чтобы подать сигнал Миши, он заберет твоих товарищей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запустите фейерверки Чо рядом с адмиралом Тейлором, Мишкой и Салли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мысленно я буду с твоими товарищами, странник.$B$BПусть за ними присмотрят.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Змеином Сердце.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31320,'Как рыбке рюмка','Привет, $gприятель:подруга;, как шизнь? Не купишь цзинь-юй выпить?','Принесите 1 бутылку соджу четырех ветров Йогу Пьяному. Соджу Четырех Ветров можно приобрести у большинства барменов Пандарии.','Шпасибо, дружище.','Жажда мучает...','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как рыбке рюмка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gприятель:подруга;, как шизнь? Не купишь цзинь-юй выпить?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 бутылку соджу четырех ветров Йогу Пьяному. Соджу Четырех Ветров можно приобрести у большинства барменов Пандарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шпасибо, дружище.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жажда мучает...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31321,'Как рыбке бутылка','А-а-а-а, $gдружище:подрушка;-|3-6($r)!$B$BПонимаю, ты меня тут не первый раз видишь, но поверь мне, я не пьян!$B$BТы пошмотри на меня, пошмотри! Трезв как стеклышко!$B$BКонечно, я люблю топить свои печали в хорошей выпивке, но цзинь-юй не может перепить, $gсам:сама; понимаешь!$B$BНет, от выпивки я жашыпаю и вижу будущее! $B$B$B$BИ чем крепче выпивка, тем отчетливее видения! Принесешь мне чего-нибудь выпить, пошмотрю будущее и для тебя.','Принесите 5 бутылок пандаренского сливового вина Йогу Пьяному. Сливовое вино можно приобрести у большинства барменов Пандарии.','Вот... Шавшем другое дело!','Што жначит, я говорю как пьяный? Я вшегда так говорю!','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как рыбке бутылка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а-а-а, $gдружище:подрушка;-|3-6($r)!$B$BПонимаю, ты меня тут не первый раз видишь, но поверь мне, я не пьян!$B$BТы пошмотри на меня, пошмотри! Трезв как стеклышко!$B$BКонечно, я люблю топить свои печали в хорошей выпивке, но цзинь-юй не может перепить, $gсам:сама; понимаешь!$B$BНет, от выпивки я жашыпаю и вижу будущее! $B$B$B$BИ чем крепче выпивка, тем отчетливее видения! Принесешь мне чего-нибудь выпить, пошмотрю будущее и для тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 бутылок пандаренского сливового вина Йогу Пьяному. Сливовое вино можно приобрести у большинства барменов Пандарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот... Шавшем другое дело!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Што жначит, я говорю как пьяный? Я вшегда так говорю!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31322,'Как рыбке бочка','Мои видения штали меркнуть, |3-6($r).$B$BМне нужно што-то покрепче, для вдохновения!$B$BЯ шлышал, сейчас стали делать отличный напиток.$B$BОн нажывается отвар нефритовой ведьмы.$B$BХочу его попробовать.','Принесите 10 бутылок отвара нефритовой ведьмы Йогу Пьяному. Отвар нефритовой ведьмы можно приготовить, используя умения кулинарии.','О... Какое отличное пойло! Начинаю жашыпать...','Удалошь?','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как рыбке бочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои видения штали меркнуть, |3-6($r).$B$BМне нужно што-то покрепче, для вдохновения!$B$BЯ шлышал, сейчас стали делать отличный напиток.$B$BОн нажывается отвар нефритовой ведьмы.$B$BХочу его попробовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 бутылок отвара нефритовой ведьмы Йогу Пьяному. Отвар нефритовой ведьмы можно приготовить, используя умения кулинарии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О... Какое отличное пойло! Начинаю жашыпать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалошь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31323,'Как рыбке хмелеварня','Так, $n, чтобы видения шнова вернулись ко мне, мне нужна своя хмелеварня.$b$B...$B$BШучу-шучу! $gВидел:Видела; бы ты свое лицо! Как шмешно! Ик.$B$BВ общем, ладно, слышал я тут об одном напитке, подобного которому нет. И я хочу его попробовать.$B$B$gШлышал:Шлышала; про завтрак безумца? Вот если принесешь мне его, штанем друзьями навек.','Принесите 20 завтраков безумца Йогу Пьяному. Завтрак безумца можно приготовить, используя умения кулинарии.','Ты-то его пробовал?','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как рыбке хмелеварня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, $n, чтобы видения шнова вернулись ко мне, мне нужна своя хмелеварня.$b$B...$B$BШучу-шучу! $gВидел:Видела; бы ты свое лицо! Как шмешно! Ик.$B$BВ общем, ладно, слышал я тут об одном напитке, подобного которому нет. И я хочу его попробовать.$B$B$gШлышал:Шлышала; про завтрак безумца? Вот если принесешь мне его, штанем друзьями навек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 завтраков безумца Йогу Пьяному. Завтрак безумца можно приготовить, используя умения кулинарии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты-то его пробовал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йогу Пьяному на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31324,'Семейные тайны','Наши секретные рецепты! Я столько их собирала. А потом... Хозены?$B$B<У тетушки недоуменный вид.>$B$BИ как Гао теперь хоть что-то сварит? Надо вернуть эти рецепты, иначе будет беда, просто беда.','Соберите 5 секретов Буйного Портера.','Хо-хо, а это еще что?$B$B<Пивное брюшко дядюшки Гао колышется, когда он видит фамильные рецепты.>$B$BЯ так и знал, что добавляю слишком много кукурузы.','Ну, привет!','Поговорите с дядюшкой Гао в Дегустационной Хмелеварни Буйных Портеров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семейные тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши секретные рецепты! Я столько их собирала. А потом... Хозены?$B$B<У тетушки недоуменный вид.>$B$BИ как Гао теперь хоть что-то сварит? Надо вернуть эти рецепты, иначе будет беда, просто беда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 секретов Буйного Портера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо, а это еще что?$B$B<Пивное брюшко дядюшки Гао колышется, когда он видит фамильные рецепты.>$B$BЯ так и знал, что добавляю слишком много кукурузы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, привет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с дядюшкой Гао в Дегустационной Хмелеварни Буйных Портеров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31325,'Прекрасное ожерелье','Несмотря на то, что за него хватались десятки грязных рук, это ожерелье по-прежнему прекрасно.$B$BИ у меня не так много вариантов, кому оно может принадлежать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прекрасное ожерелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на то, что за него хватались десятки грязных рук, это ожерелье по-прежнему прекрасно.$B$BИ у меня не так много вариантов, кому оно может принадлежать.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31326,'Роскошная тиара Тины','Это великолепная тиара. Интересно, у кого в равнине хватит денег на то, чтобы купить такое роскошное украшение?$B$BВпрочем, неважно, думаю, награду они дадут щедрую.','Моя тиара! Да, она пропала... Где тебе удалось ее найти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Роскошная тиара Тины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это великолепная тиара. Интересно, у кого в равнине хватит денег на то, чтобы купить такое роскошное украшение?$B$BВпрочем, неважно, думаю, награду они дадут щедрую.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя тиара! Да, она пропала... Где тебе удалось ее найти?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31327,'Проблемы хмелевара','После того, как в хмелеварню заявились хозены и прочие твари, у хмелеваров возникли серьезные неприятности.$B$BОкажи мне услугу, выясни, что там происходит.','Убейте Янь-Чжу Высвобожденного.','Поговорите с Чэнем Буйным Портером в Дегустационной хмелеварни Буйных Портеров.','Убейте его, чтобы спасти дядюшку Гао.','Янь-Чжу Высвобожденный') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы хмелевара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того, как в хмелеварню заявились хозены и прочие твари, у хмелеваров возникли серьезные неприятности.$B$BОкажи мне услугу, выясни, что там происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Янь-Чжу Высвобожденного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в Дегустационной хмелеварни Буйных Портеров.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте его, чтобы спасти дядюшку Гао.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Янь-Чжу Высвобожденный',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31328,'Изящная серьга','Вы вытаскиваете серьгу из уха мохнатого существа. Похоже, ему нравилось носить эту красивую висюльку. Пожалуй, даже слишком нравилось.$B$BВозможно, владелица захочет получить свое украшение обратно. И совершенно необязательно рассказывать ей, где эта серьга была... и кто ее носил.','О, моя серьга! И даже подходит к той, которую я ношу сегодня!$B$B<Тина вдевает серьгу в ухо>$B$BCпасибо, Вивиша!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изящная серьга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы вытаскиваете серьгу из уха мохнатого существа. Похоже, ему нравилось носить эту красивую висюльку. Пожалуй, даже слишком нравилось.$B$BВозможно, владелица захочет получить свое украшение обратно. И совершенно необязательно рассказывать ей, где эта серьга была... и кто ее носил.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, моя серьга! И даже подходит к той, которую я ношу сегодня!$B$B<Тина вдевает серьгу в ухо>$B$BCпасибо, Вивиша!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31329,'Великолепная брошь','Это очень старая, антикварная брошь, отделанная тончайшей филигранью по краям. Судя по виду, стоит она немало.$B$BПоскольку в этих краях есть только одна особа, постоянно теряющая украшения, вероятно, стоит вернуть ей ее брошь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великолепная брошь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это очень старая, антикварная брошь, отделанная тончайшей филигранью по краям. Судя по виду, стоит она немало.$B$BПоскольку в этих краях есть только одна особа, постоянно теряющая украшения, вероятно, стоит вернуть ей ее брошь.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31331,'Научиться проходить задания','Ура! Ты выполнил задание о хлебных крошках! Теперь разберись, что делать дальше.','Выполнить задание о хлебных крошках.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Научиться проходить задания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ура! Ты выполнил задание о хлебных крошках! Теперь разберись, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выполнить задание о хлебных крошках.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31332,'Урок 1: разрезанные персики','Уже очень хочется чему-нибудь научиться. Начнем с разрезанных персиков, да?','Достаньте 5 пандаренских персиков для занятий с Номи.','Вот! Ну что, у меня получилось?','Я очень сильно хочу стать поваром, но другие ребята начали заниматься уже пару месяцев назад. Без твоей помощи я их не нагоню.','Отдайте Номи 5 пандаренских персиков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок 1: разрезанные персики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже очень хочется чему-нибудь научиться. Начнем с разрезанных персиков, да?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 5 пандаренских персиков для занятий с Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот! Ну что, у меня получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я очень сильно хочу стать поваром, но другие ребята начали заниматься уже пару месяцев назад. Без твоей помощи я их не нагоню.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Номи 5 пандаренских персиков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31333,'Урок 2: растворимая лапша','Растворимую лапшу готовить совсем просто, так ведь?','Достаньте 5 порций лапши быстрого приготовления для занятий с Номи.','Вот! Ну что, у меня получилось?','Оказывается, лапшу так легко испортить!','Отдайте Номи 5 порций лапши быстрого приготовления.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок 2: растворимая лапша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растворимую лапшу готовить совсем просто, так ведь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 5 порций лапши быстрого приготовления для занятий с Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот! Ну что, у меня получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Оказывается, лапшу так легко испортить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Номи 5 порций лапши быстрого приготовления.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31334,'Урок 3: подрумяненная соленая рыба','Надо же, готовить сложнее, чем кажется. Все постоянно пригорает.','Достаньте 5 золотистых карпов для занятий с Номи.','Вот! Ну что, у меня получилось?','Надеюсь, я не подожгу себя. Поехали.','Отдайте Номи 5 золотистых карпов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок 3: подрумяненная соленая рыба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо же, готовить сложнее, чем кажется. Все постоянно пригорает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 5 золотистых карпов для занятий с Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот! Ну что, у меня получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, я не подожгу себя. Поехали.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Номи 5 золотистых карпов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31335,'Урок 4: сушеный игольчатый гриб.','Не очень люблю грибы... но все равно попробую освоить это блюдо.','Достаньте 5 опят для занятий с Номи.','Вот! Ну что, у меня получилось?','Фу.','Отдайте Номи 5 опят.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок 4: сушеный игольчатый гриб.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не очень люблю грибы... но все равно попробую освоить это блюдо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 5 опят для занятий с Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот! Ну что, у меня получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Номи 5 опят.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31336,'Урок 5: торт из молотого риса','Обожаю рисовые торты. Надеюсь, получится вкусно.','Достаньте 5 порций риса для занятий с Номи.','Вот! Ну что, у меня получилось?','Очень интересно, что я наготовлю.','Отдайте Номи 5 порций риса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок 5: торт из молотого риса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обожаю рисовые торты. Надеюсь, получится вкусно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 5 порций риса для занятий с Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот! Ну что, у меня получилось?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень интересно, что я наготовлю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте Номи 5 порций риса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31337,'Знак признательности','Спасибо, что интересуешься, как у меня дела! Сегодня мне удалось помочь семейству Железной Лапы, и они сказали, что я могу передать это тебе.','Получите подарок Номи.','Ты – мой самый любимый учитель!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак признательности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что интересуешься, как у меня дела! Сегодня мне удалось помочь семейству Железной Лапы, и они сказали, что я могу передать это тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите подарок Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты – мой самый любимый учитель!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31338,'Заблудший барашек','Любимый барашка Чи-Чи, Бяша, совсем пропасть!$B$BПлохой барашка всегда убегай с фермы!$B$BГлупый баран! Я искать везде — его нет.$B$BМожешь помочь, |3-6($r)?','Найдите Бяшу и верните его Чи-Чи.','Ты найти его! Спасибо!','Ты найти мой Бяша? Ох, я так переживай!','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблудший барашек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любимый барашка Чи-Чи, Бяша, совсем пропасть!$B$BПлохой барашка всегда убегай с фермы!$B$BГлупый баран! Я искать везде — его нет.$B$BМожешь помочь, |3-6($r)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бяшу и верните его Чи-Чи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты найти его! Спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найти мой Бяша? Ох, я так переживай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31339,'Заблудший барашек... Еще раз','Тупой барашка! Опять пойти гулять!$B$BМожешь найти еще раз?','Найдите Бяшу и верните его Чи-Чи.','Бяша, ты делать меня несчастным! Плохой баран! Чи-Чи сильно-сильно переживай!','Ох, бедный Бяша. Ему страшно и одиноко...','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблудший барашек... Еще раз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тупой барашка! Опять пойти гулять!$B$BМожешь найти еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бяшу и верните его Чи-Чи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бяша, ты делать меня несчастным! Плохой баран! Чи-Чи сильно-сильно переживай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ох, бедный Бяша. Ему страшно и одиноко...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31340,'Ох, Бяша...','Хм... ты угадай... Бяша ушел. Снова!$B$BГлупый-глупый баран! Одни хлопоты с ним!$B$BЯ не хотеть просить, но... я обещай – это в последний раз.$B$BНайдешь Бяшу?','Найдите Бяшу.','Что? Бяша... умер?$B$B<У Чи-Чи начинают дрожать губы.>','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ох, Бяша...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... ты угадай... Бяша ушел. Снова!$B$BГлупый-глупый баран! Одни хлопоты с ним!$B$BЯ не хотеть просить, но... я обещай – это в последний раз.$B$BНайдешь Бяшу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бяшу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Бяша... умер?$B$B<У Чи-Чи начинают дрожать губы.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Чи. Его можно найти в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31341,'Волк в овечьей шкуре','А-а-а! Это был последний капля!$B$bХозены с гор убить мой Бяшу!$B$BЯ знай, кто это делать, и я хочу месть!$B$BЕсли хочешь помогать, бери этот старый овечий шкура.$B$BИди на север, в горы, и надень на себя. Жди мелкий дукер Крунко и сломать все-все его кости!','Используйте старую овечью шкуру в Небогорье или в деревне Куньцзэнь, а потом убейте Крунко.','Вернитесь к Чи-Чи. Вы найдете его в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волк в овечьей шкуре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а-а! Это был последний капля!$B$bХозены с гор убить мой Бяшу!$B$BЯ знай, кто это делать, и я хочу месть!$B$BЕсли хочешь помогать, бери этот старый овечий шкура.$B$BИди на север, в горы, и надень на себя. Жди мелкий дукер Крунко и сломать все-все его кости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте старую овечью шкуру в Небогорье или в деревне Куньцзэнь, а потом убейте Крунко.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Чи. Вы найдете его в доме Чи-Чи или на рынке Полугорья в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31342,'Путь к уважению лежит через насилие.','Твое боевое мастерство несомненно.$B$BНо если ты хочешь помогать нам и дальше, я попрошу тебя о еще одной услуге.$B$BВ Закрытых покоях под землей притаился Ша Жестокости. Уничтожь его, и заслужишь мое уважение.','Убейте Ша Жестокости.','Поговорите с мастером Снежным Вихрем в Роще Опадающих Лепестков, что в монастыре Шадо-Пан.','Мастер Снежный Вихрь попросил вас убить это кошмарное существо.','Ша Жестокости') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к уважению лежит через насилие.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое боевое мастерство несомненно.$B$BНо если ты хочешь помогать нам и дальше, я попрошу тебя о еще одной услуге.$B$BВ Закрытых покоях под землей притаился Ша Жестокости. Уничтожь его, и заслужишь мое уважение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ша Жестокости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Снежным Вихрем в Роще Опадающих Лепестков, что в монастыре Шадо-Пан.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мастер Снежный Вихрь попросил вас убить это кошмарное существо.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ша Жестокости',`questgivertargetname_loc8`);
