INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31354,'Дар Мацзу','Вы с капитаном отлично справились, $n! Я горжусь, что ты в моей команде.$B$BКстати! Цзюй Лэню удалось выжить! Он выплыл на берег, когда вы начали бомбардировать левиафана гарпунами. Плел что-то про какое-то гигантское яйцо, которое принесло сюда вместе с Цзяо.$B$BИди, проверь, как он там, ладно? Наверное, он уже вытащил это яйцо из воды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Мацзу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с капитаном отлично справились, $n! Я горжусь, что ты в моей команде.$B$BКстати! Цзюй Лэню удалось выжить! Он выплыл на берег, когда вы начали бомбардировать левиафана гарпунами. Плел что-то про какое-то гигантское яйцо, которое принесло сюда вместе с Цзяо.$B$BИди, проверь, как он там, ладно? Наверное, он уже вытащил это яйцо из воды.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31355,'Восстановление чистоты нефрита','$c, ты поможешь нам?$B$BЭтот храм был осквернен. Даже сейчас три мастера продолжают сражаться с обуревающими их сомнениями.$B$BПожалуйста, умоляю тебя, помоги Мудрому Марису, Лю Пламенному Сердцу и хранителю истории Каменной Поступи одолеть ша.','Помогите Мудрому Марису, Лю Пламенное Сердце и хранителю истории Каменная поступь справиться с ша.','То, что случилось с Мудрым Марисом и жрицей Пламенное Сердце, очень печально. Но все равно – благодарю тебя от всей души.','Поговорите со жрицей Летним Лепестком в Храме Нефритовой Змеи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление чистоты нефрита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, ты поможешь нам?$B$BЭтот храм был осквернен. Даже сейчас три мастера продолжают сражаться с обуревающими их сомнениями.$B$BПожалуйста, умоляю тебя, помоги Мудрому Марису, Лю Пламенному Сердцу и хранителю истории Каменной Поступи одолеть ша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Мудрому Марису, Лю Пламенное Сердце и хранителю истории Каменная поступь справиться с ша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что случилось с Мудрым Марисом и жрицей Пламенное Сердце, очень печально. Но все равно – благодарю тебя от всей души.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со жрицей Летним Лепестком в Храме Нефритовой Змеи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31356,'Глубина сомнений порождает глубину мысли','Один древний пандарен сказал "Глубина сомнений порождает глубину мысли."$B$BШа Сомнения отравил Нефритовое сердце, которое находится в храме. Его необходимо уничтожить.$B$BОсмелюсь предположить, |3-6($c), что выполнив это задание, ты станешь $gмудр:мудра; не по годам.','Убейте Ша Сомнения.','Я никогда в тебе не сомневался. Но почему-то мудрости в тебе не прибавилось.$B$B<мастер подмигивает>','Поговорите с мастером Порывистым Ветром в Храме Нефритовой Змеи.','Избавьте храм от сомнений.','Ша Сомнения') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубина сомнений порождает глубину мысли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один древний пандарен сказал "Глубина сомнений порождает глубину мысли."$B$BШа Сомнения отравил Нефритовое сердце, которое находится в храме. Его необходимо уничтожить.$B$BОсмелюсь предположить, |3-6($c), что выполнив это задание, ты станешь $gмудр:мудра; не по годам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ша Сомнения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я никогда в тебе не сомневался. Но почему-то мудрости в тебе не прибавилось.$B$B<мастер подмигивает>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Порывистым Ветром в Храме Нефритовой Змеи.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Избавьте храм от сомнений.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ша Сомнения',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31357,'Реликвии Четырех Королей','Могу вернулись к жизни, и теперь угрожают всей Пандарии. И они вот-вот станут еще более опасны.$B$BЛегенда гласит о четырех королях могу: Цзыань Беспросветная Тьма, Мын Безумный, Цян Безжалостный и Субетай Быстрый. Четыре артефакта этих королей хранятся в Королевском хранилище.$B$BТебе нужно найти артефакты до того, как это сделают могу, иначе мы уже не сможем их остановить.','Я найду, где спрятать эти реликвии.$B$BПандария перед тобой в неоплатном долгу, Фэндом.','Нам надо найти светильник, весы, свиток и лук, пока это не сделали Синь и его кланы.','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Четырех Королей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу вернулись к жизни, и теперь угрожают всей Пандарии. И они вот-вот станут еще более опасны.$B$BЛегенда гласит о четырех королях могу: Цзыань Беспросветная Тьма, Мын Безумный, Цян Безжалостный и Субетай Быстрый. Четыре артефакта этих королей хранятся в Королевском хранилище.$B$BТебе нужно найти артефакты до того, как это сделают могу, иначе мы уже не сможем их остановить.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я найду, где спрятать эти реликвии.$B$BПандария перед тобой в неоплатном долгу, Фэндом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам надо найти светильник, весы, свиток и лук, пока это не сделали Синь и его кланы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31359,'Говорящий с куньчунами','Чтобы упрочить связь с Ковоком, надо постоянно подвергать его испытаниям – ментальным и физическим. Надо уважать его силу и интеллект, только тогда он позволит себя тренировать.$b$bДумаю, племя Грязной Чешуи – хорошая проверка, Ковок сможет показать себя, а ты будешь в относительной безопасности.$b$bК тому же, так этих тварей на Соленой отмели станет поменьше.','Убейте оракула Хисс\'ира и 10 членов племени Грязной Чешуи.','Твой прогресс весьма впечатляет, Пробудитель. Ковок становится сильнее и умнее, и кажется, ты ему нравишься.$B$BПохоже, мне удалось выбрать наилучшего помощника.','Поговорите с Каз\'тиком Манипулятором Клакси\'весс.','Верховный оракул племени Грязной Чешуи.','Оракул Хисс\'ир') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Говорящий с куньчунами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы упрочить связь с Ковоком, надо постоянно подвергать его испытаниям – ментальным и физическим. Надо уважать его силу и интеллект, только тогда он позволит себя тренировать.$b$bДумаю, племя Грязной Чешуи – хорошая проверка, Ковок сможет показать себя, а ты будешь в относительной безопасности.$b$bК тому же, так этих тварей на Соленой отмели станет поменьше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте оракула Хисс\'ира и 10 членов племени Грязной Чешуи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой прогресс весьма впечатляет, Пробудитель. Ковок становится сильнее и умнее, и кажется, ты ему нравишься.$B$BПохоже, мне удалось выбрать наилучшего помощника.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором Клакси\'весс.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Верховный оракул племени Грязной Чешуи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Оракул Хисс\'ир',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31360,'Новый урок для мастера','У могу появился новый король – Синь Мастер Боя.$B$BОн подчинил себе все кланы могу, и теперь они сражаются за его благосклонность.$B$BЯ не знаю более великого воина, так что не надо его недооценивать, $n.$B$BНаша судьба в твоих руках.','Убейте Синя Мастера Боя.','Это была поистине великая битва.$B$BХорошо, что ты на нашей стороне, Фэндом.','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан.','Убейте нового короля могу.','Синь Мастер Боя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый урок для мастера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У могу появился новый король – Синь Мастер Боя.$B$BОн подчинил себе все кланы могу, и теперь они сражаются за его благосклонность.$B$BЯ не знаю более великого воина, так что не надо его недооценивать, $n.$B$BНаша судьба в твоих руках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Синя Мастера Боя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это была поистине великая битва.$B$BХорошо, что ты на нашей стороне, Фэндом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сынань Мечтательницей во Дворце Могу\'шан.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте нового короля могу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Синь Мастер Боя',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31362,'Последний фрагмент головоломки','Надо сказать, $n, несмотря на вечную вражду с хозенами, цзинь-юй никогда не были настроены столь воинственно. Меня это беспокоит. Ладно, эту проблему обсудим в другой раз. Сейчас мне нужна твоя помощь.$b$bТа древняя фреска, которую мы видели в прошлый раз, почти разгадана. Нет сомнений, что в ней сокрыта древняя мудрость – знание, которое хотел нам оставить император.$b$bЧтобы расшифровать ее значение, моих медитаций может оказаться недостаточно. Пожалуйста, отнести эту фамильную ценность в святилище моего рода. Мне потребуется помощь предков.','Используйте фамильную ценность Чо у фамильного святилища Чо на площадке с видом на Нефритовую Змею Чо.$b$bПопросите Миши доставить вас туда.','<Хранитель истории Чо невольно содрогается>$B$BЛегенды... оказались правдой!','Поговорите с хранителем истории Чо на Обзорной площадке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний фрагмент головоломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо сказать, $n, несмотря на вечную вражду с хозенами, цзинь-юй никогда не были настроены столь воинственно. Меня это беспокоит. Ладно, эту проблему обсудим в другой раз. Сейчас мне нужна твоя помощь.$b$bТа древняя фреска, которую мы видели в прошлый раз, почти разгадана. Нет сомнений, что в ней сокрыта древняя мудрость – знание, которое хотел нам оставить император.$b$bЧтобы расшифровать ее значение, моих медитаций может оказаться недостаточно. Пожалуйста, отнести эту фамильную ценность в святилище моего рода. Мне потребуется помощь предков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте фамильную ценность Чо у фамильного святилища Чо на площадке с видом на Нефритовую Змею Чо.$b$bПопросите Миши доставить вас туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хранитель истории Чо невольно содрогается>$B$BЛегенды... оказались правдой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо на Обзорной площадке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31363,'Освещая путь','Нам нужно подкрепление! Кто-то должен прорваться туда и зажечь сигнальный огонь.$B$BХочешь вызваться, |3-6($c)? Дело добровольное.','Зажгите сигнальный огонь','Потрясающе, Фэндом. Очень вовремя!','Поговорите с лучницей Ли у врат Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освещая путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно подкрепление! Кто-то должен прорваться туда и зажечь сигнальный огонь.$B$BХочешь вызваться, |3-6($c)? Дело добровольное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите сигнальный огонь',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе, Фэндом. Очень вовремя!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лучницей Ли у врат Заходящего Солнца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31364,'Тараканище!','У богомолов в распоряжении есть очень опасная тварь – Райгонн. С помощью этого гигантского жука они собираются разрушить ворота!$B$BНельзя допустить, чтобы эта тварь прорвалась в Дол.','Убейте Райгонна.','Глазам своим не верю!$B$BCпасибо тебе, Фэндом!','Поговорите с лучницей Ли у врат Заходящего Солнца.','Не дай ему прорваться внутрь!','Райгонн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тараканище!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У богомолов в распоряжении есть очень опасная тварь – Райгонн. С помощью этого гигантского жука они собираются разрушить ворота!$B$BНельзя допустить, чтобы эта тварь прорвалась в Дол.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Райгонна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глазам своим не верю!$B$BCпасибо тебе, Фэндом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лучницей Ли у врат Заходящего Солнца.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не дай ему прорваться внутрь!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Райгонн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31365,'Где-то внутри','Я отправил к богомолам с десяток своих солдат.$B$BНи один не вернулся.$B$BРаз уж ты собираешься драться с богомолами, думаю, у тебя будет возможность освободить тех, кому не повезло попасть в плен.$B$BВозьмешься?','Спасите 12 шадопанских пленников.','Поговорите с шадо-мастером Чум Киу при осаде храма Нюцзао.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где-то внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправил к богомолам с десяток своих солдат.$B$BНи один не вернулся.$B$BРаз уж ты собираешься драться с богомолами, думаю, у тебя будет возможность освободить тех, кому не повезло попасть в плен.$B$BВозьмешься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 12 шадопанских пленников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с шадо-мастером Чум Киу при осаде храма Нюцзао.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31366,'Убейте командующего флангом','Богомолы осаждают храм Нюцзао.$B$BДаже сейчас командующий флангом Нер\'онок и его войска пытаются построить мост через последнее ущелье.$B$BТы $gдолжен:должна; им помешать.','Убейте командующего флангом Нер\'онока.','Поговорите с шадо-мастером Чум Киу при осаде храма Нюцзао.','Его надо убить, чтобы помешать строительству моста.','Командующий флангом Нер\'онок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убейте командующего флангом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы осаждают храм Нюцзао.$B$BДаже сейчас командующий флангом Нер\'онок и его войска пытаются построить мост через последнее ущелье.$B$BТы $gдолжен:должна; им помешать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командующего флангом Нер\'онока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с шадо-мастером Чум Киу при осаде храма Нюцзао.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его надо убить, чтобы помешать строительству моста.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командующий флангом Нер\'онок',`questgivertargetname_loc8`);
