INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (31378,'Храм Красного Журавля все еще сотрясают последствия нашествия ша, лишь недавно там нашли в себе силы собраться и начать восстановление храма и его воинов.$B$BЕсли ты $gготов:готова; помочь храму, поговори с Телонием в Колыбели Чи-Цзи.','Поговорите с Телонием в Колыбели Чи-Цзи в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Храм Красного Журавля все еще сотрясают последствия нашествия ша, лишь недавно там нашли в себе силы собраться и начать восстановление храма и его воинов.$B$BЕсли ты $gготов:готова; помочь храму, поговори с Телонием в Колыбели Чи-Цзи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Телонием в Колыбели Чи-Цзи в Красарангских джунглях.',`objectives_loc8`);
