INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31380,'Испытание в храме Белого Тигра','Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!','Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание в храме Белого Тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31381,'Испытание в храме Белого Тигра','Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!','Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание в храме Белого Тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюэнь, великий дух Севера, ищет величайших героев.$B$BСегодня он устраивает турнир в своем храме на вершине Кунь-Лай.$B$BЕсли ты $gготов:готова; встретиться в битве с лучшими бойцами Пандарии, отправляйся туда и выйди на арену!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сюэнем в храме Белого Тигра на вершине Кунь-Лай.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31382,'Оборона храма Нюцзао','Богомолы напали на храм Нюцзао, далеко на западе.$B$BХрам пока еще держится, но без поддержки это долго не продлится.$B$BОтправляйся на помощь защитникам, |3-6($c).','Поговорите со старейшиной Ого в храме Нюцзао в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона храма Нюцзао',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Богомолы напали на храм Нюцзао, далеко на западе.$B$BХрам пока еще держится, но без поддержки это долго не продлится.$B$BОтправляйся на помощь защитникам, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Ого в храме Нюцзао в Танлунских степях.',`objectives_loc8`);
