INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31384,'Золотой Лотос','Золотой Лотос на протяжении веков охранял Дол, обеспечивая его безопасность.$B$BПосле недавних событий это священное место находится под угрозой, и на свободу вырвались страшные силы, но союзники Золотого Лотоса не сдаются и пытаются отстоять Дол.$B$BЕсли ты хочешь помочь, присоединись к ним в Гарнизоне Заходящего Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Золотой Лотос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Золотой Лотос на протяжении веков охранял Дол, обеспечивая его безопасность.$B$BПосле недавних событий это священное место находится под угрозой, и на свободу вырвались страшные силы, но союзники Золотого Лотоса не сдаются и пытаются отстоять Дол.$B$BЕсли ты хочешь помочь, присоединись к ним в Гарнизоне Заходящего Солнца.',`details_loc8`);
