INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31386,'Армия Шадо-Пан','Шадо-паны проводят столь масштабную мобилизацию впервые за многие века.$B$BШа Ненависти удалось скрыться за Змеиным Хребтом, и наш священный долг – остановить его.$B$BХотя нашим воинам и нет равных, но нас просто слишком мало. Если бы нам $gпомог достойный:помогла достойная:c; |3-6($c), то ситуация могла бы обернуться в нашу пользу.$B$BЕсли хочешь присоединиться к армии Шадо-Пан, поговори с Тажанем Чжу в Танлунских степях.','Поговорите с Тажанем Чжу на укреплениях Лун-Ин, которые находятся в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Армия Шадо-Пан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шадо-паны проводят столь масштабную мобилизацию впервые за многие века.$B$BШа Ненависти удалось скрыться за Змеиным Хребтом, и наш священный долг – остановить его.$B$BХотя нашим воинам и нет равных, но нас просто слишком мало. Если бы нам $gпомог достойный:помогла достойная:c; |3-6($c), то ситуация могла бы обернуться в нашу пользу.$B$BЕсли хочешь присоединиться к армии Шадо-Пан, поговори с Тажанем Чжу в Танлунских степях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тажанем Чжу на укреплениях Лун-Ин, которые находятся в Танлунских степях.',`objectives_loc8`);
