INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31394,'Никому не позволено входить в дол без разрешения Августейших Небожителей. Похоже, Сюэнь Белый Тигр готов меня выслушать.$b$bНо после случившегося глава Шадо-Пан, Тажань Чжу, не желает даже близко подпускать к долу кого-либо из Альянса или Орды.$b$b<Андуин качает головой.>$b$bВозможно, у тебя получится убедить его. Поговори от нашего имени с Белым Тигром. Но будь начеку! Он может подвергнуть тебя множеству испытаний...','Поговорите с Сюэнем и пройдите его испытания.','Молодец, $n!$b$bБелый Тигр разрешил нам сопроводить пандаренов в Вечноцветущий дол. Там уже появился аванпост Альянса. Можно начинать работу над восстановлением!','Поговорите с Андуином Ринном в Храме Белого Тигра.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никому не позволено входить в дол без разрешения Августейших Небожителей. Похоже, Сюэнь Белый Тигр готов меня выслушать.$b$bНо после случившегося глава Шадо-Пан, Тажань Чжу, не желает даже близко подпускать к долу кого-либо из Альянса или Орды.$b$b<Андуин качает головой.>$b$bВозможно, у тебя получится убедить его. Поговори от нашего имени с Белым Тигром. Но будь начеку! Он может подвергнуть тебя множеству испытаний...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сюэнем и пройдите его испытания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $n!$b$bБелый Тигр разрешил нам сопроводить пандаренов в Вечноцветущий дол. Там уже появился аванпост Альянса. Можно начинать работу над восстановлением!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Храме Белого Тигра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31395,'Должен признать, человечий теленок умеет говорить. Теперь я понимаю, почему Бейн Кровавое Копыто так высоко ценит принца.$b$bИ все же наши аргументы пока не убеждают. От меня толку мало, но ты – другое дело. Возможно, у $gпосланника:посланницы; Орды получится изменить ситуацию?$b$b$r, поговори с Белым Тигром от нашего имени.$b$bНо будь начеку! Он может подвергнуть тебя многим испытаниям...','Поговорите с Сюэнем и пройдите его испытания.','Поговорите со служителем солнца Дезко в Храме Белого Тигра.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должен признать, человечий теленок умеет говорить. Теперь я понимаю, почему Бейн Кровавое Копыто так высоко ценит принца.$b$bИ все же наши аргументы пока не убеждают. От меня толку мало, но ты – другое дело. Возможно, у $gпосланника:посланницы; Орды получится изменить ситуацию?$b$b$r, поговори с Белым Тигром от нашего имени.$b$bНо будь начеку! Он может подвергнуть тебя многим испытаниям...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сюэнем и пройдите его испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со служителем солнца Дезко в Храме Белого Тигра.',`completedtext_loc8`);
