INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31439,'Потерянный сигнал','Кто-то нарушил работу маяка в Янтарном зале. Но прежде, чем сигнал пропал, клакси\'ва обнаружили неподалеку еще один Идеал.$b$bОни считают, что он скрыт в этом проклятом болоте, Топи Темного Корня.$b$bВстретимся на болоте, там мы поставим временный маячок, пока не удастся активировать башню в Янтарном зале.$b$bПробуди Идеал и помоги мне.','Пробудите Идеала в Топях Темного Корня.','Что ж, пора мне взяться за дело. Это место очень опасно, Пробудитель.','Поговорите с Хисеком Хранителем Роя в Топи Темного Корня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный сигнал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто-то нарушил работу маяка в Янтарном зале. Но прежде, чем сигнал пропал, клакси\'ва обнаружили неподалеку еще один Идеал.$b$bОни считают, что он скрыт в этом проклятом болоте, Топи Темного Корня.$b$bВстретимся на болоте, там мы поставим временный маячок, пока не удастся активировать башню в Янтарном зале.$b$bПробуди Идеал и помоги мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пробудите Идеала в Топях Темного Корня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, пора мне взяться за дело. Это место очень опасно, Пробудитель.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хисеком Хранителем Роя в Топи Темного Корня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31440,'Четыре фолианта','В Некроситете изучают четыре основных труда по некромантии: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".$B$BПока мы пробиваем себе путь в этом проклятом месте, найди каждую из этих книг и уничтожь их, чтобы ни один глупец больше не смог прийти сюда и познать темные тайны.','Уничтожьте четыре фолианта: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".','Спасибо, Пивобород.$B$BТеперь, когда эти книги уничтожены, я могу упокоиться с миром. Больше ни одна живая душа не пострадает от них.','Поговорите с говорящим черепом в Некроситете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четыре фолианта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Некроситете изучают четыре основных труда по некромантии: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".$B$BПока мы пробиваем себе путь в этом проклятом месте, найди каждую из этих книг и уничтожь их, чтобы ни один глупец больше не смог прийти сюда и познать темные тайны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте четыре фолианта: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Пивобород.$B$BТеперь, когда эти книги уничтожены, я могу упокоиться с миром. Больше ни одна живая душа не пострадает от них.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящим черепом в Некроситете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31441,'Порча повсюду','Сегодня ты усвоишь важный урок, Пробудитель. На войне нельзя доверять никому. Даже приближенные к клакси могут подвергнуться порче.$b$bНеизвестно, давно ли этот предатель действовал нам во вред. Он должен быть уничтожен!$b$bТы в замешательстве. Не видишь предателя среди нас? Позволь мне помочь тебе распознать его.','Победите предателя в Топи Темного Корня.','Это еще цветочки. Война – дело неприятное.$B$BПорча императрицы распространилась далеко, и ее очаги не так легко обнаружить.$B$BРаботы – непочатый край, ведь надо еще устранить тот ущерб, что нанес Кор\'ик.','Поговорите с Хисеком Хранителем Роя в Топи Темного Корня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порча повсюду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня ты усвоишь важный урок, Пробудитель. На войне нельзя доверять никому. Даже приближенные к клакси могут подвергнуться порче.$b$bНеизвестно, давно ли этот предатель действовал нам во вред. Он должен быть уничтожен!$b$bТы в замешательстве. Не видишь предателя среди нас? Позволь мне помочь тебе распознать его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите предателя в Топи Темного Корня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это еще цветочки. Война – дело неприятное.$B$BПорча императрицы распространилась далеко, и ее очаги не так легко обнаружить.$B$BРаботы – непочатый край, ведь надо еще устранить тот ущерб, что нанес Кор\'ик.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хисеком Хранителем Роя в Топи Темного Корня.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31442,'Четыре фолианта','В Некроситете изучают четыре основных труда по некромантии: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".$B$BПока мы пробиваем себе путь в этом проклятом месте, найди каждую из этих книг и уничтожь их, чтобы ни один глупец больше не смог прийти сюда и познать темные тайны.','Уничтожьте четыре фолианта: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".','В этих фолиантах содержатся знания, из-за которых это место и все, кто так или иначе связан с ним, прокляты на веки.$B$BУничтожь эти книги!','Поговорите с говорящим черепом в Некроситете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четыре фолианта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Некроситете изучают четыре основных труда по некромантии: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".$B$BПока мы пробиваем себе путь в этом проклятом месте, найди каждую из этих книг и уничтожь их, чтобы ни один глупец больше не смог прийти сюда и познать темные тайны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте четыре фолианта: "В тени света", "Сокровенное знание Кел\'Тузада", "Запретные обряды и иные ритуалы некромантов" и "Гримуар Тьмы".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В этих фолиантах содержатся знания, из-за которых это место и все, кто так или иначе связан с ним, прокляты на веки.$B$BУничтожь эти книги!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с говорящим черепом в Некроситете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31445,'zzOld','If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to my brother Haito at the Anglers Wharf in Krasarang Wilds.$B$BI\'m sure he\'d love to show you a thing or two about reeling!','Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','zzOld',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to my brother Haito at the Anglers Wharf in Krasarang Wilds.$B$BI\'m sure he\'d love to show you a thing or two about reeling!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31447,'Конец страданиям','Это место так и будет проклято, пока жив темный магистр Гандлинг.$B$BУбей его, $n. И пусть смерть его будет мучительна.','Убейте темного магистра Гандлинга.','Узри мой истинный облик.$B$BЯ у тебя в неоплатном долгу. Спасибо, что снял проклятие с моей семьи.$B$BКел\'Тузад, Король-лич и темный магистр Гандлинг мертвы.$B$BБыть может, теперь я смогу обрести покой.','Поговорите с призраком лорда Алексея Барова в Некроситете.','Убейте темного магистра, чтобы снять проклятие.','Темный магистр Гандлинг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец страданиям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место так и будет проклято, пока жив темный магистр Гандлинг.$B$BУбей его, $n. И пусть смерть его будет мучительна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте темного магистра Гандлинга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Узри мой истинный облик.$B$BЯ у тебя в неоплатном долгу. Спасибо, что снял проклятие с моей семьи.$B$BКел\'Тузад, Король-лич и темный магистр Гандлинг мертвы.$B$BБыть может, теперь я смогу обрести покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с призраком лорда Алексея Барова в Некроситете.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте темного магистра, чтобы снять проклятие.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный магистр Гандлинг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31448,'Конец страданиям','Это место так и будет проклято, пока жив темный магистр Гандлинг.$B$BУбей его, $n. И пусть смерть его будет мучительна.','Убейте темного магистра Гандлинга.','Узри мой истинный облик.$B$BЯ у тебя в неоплатном долгу. Спасибо, что снял проклятие с моей семьи.$B$BКел\'Тузад, Король-лич и темный магистр Гандлинг мертвы.$B$BБыть может, теперь я смогу обрести покой.','Поговорите с призраком лорда Алексея Барова в Некроситете.','Убейте темного магистра, чтобы снять проклятие.','Темный магистр Гандлинг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец страданиям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это место так и будет проклято, пока жив темный магистр Гандлинг.$B$BУбей его, $n. И пусть смерть его будет мучительна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте темного магистра Гандлинга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Узри мой истинный облик.$B$BЯ у тебя в неоплатном долгу. Спасибо, что снял проклятие с моей семьи.$B$BКел\'Тузад, Король-лич и темный магистр Гандлинг мертвы.$B$BБыть может, теперь я смогу обрести покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с призраком лорда Алексея Барова в Некроситете.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убейте темного магистра, чтобы снять проклятие.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный магистр Гандлинг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31450,'Новая судьба','Новые союзники позволили осознать нам очень важный факт: болеет не только Шэнь-Цзынь Су, но и вся земля за облаками. Мир необходимо исцелить, и эта задача возложена на вас.$B$BЯ желаю, чтобы ты, Цзи и Аиса покинули меня и несли мудрость и силу миру. Хоть Альянс и Орда и придерживаются разных идеалов, они действуют во имя благих целей.$B$BВыбор я оставляю за тобой.','Поговорите с духом мастера Шан Си и сообщите ему, с кем вы желаете пойти: с Альянсом или с Ордой.','Да будет так... Вот он, наш новый дом.','Поговорите с Цзи или Аисой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая судьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новые союзники позволили осознать нам очень важный факт: болеет не только Шэнь-Цзынь Су, но и вся земля за облаками. Мир необходимо исцелить, и эта задача возложена на вас.$B$BЯ желаю, чтобы ты, Цзи и Аиса покинули меня и несли мудрость и силу миру. Хоть Альянс и Орда и придерживаются разных идеалов, они действуют во имя благих целей.$B$BВыбор я оставляю за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом мастера Шан Си и сообщите ему, с кем вы желаете пойти: с Альянсом или с Ордой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да будет так... Вот он, наш новый дом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цзи или Аисой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31451,'Пропавший торговец','Мой сын! Они забрали моего сына... Ты можешь мне помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший торговец',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой сын! Они забрали моего сына... Ты можешь мне помочь?',`offerrewardtext_loc8`);
