INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31453,'Шадо-Пан','Ты кто? Умеешь сражаться? Если так, нам пригодилась бы твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шадо-Пан',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты кто? Умеешь сражаться? Если так, нам пригодилась бы твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31454,'Так рождается легенда','Наш мир сейчас на распутье. Следующие месяцы определят его будущее – если, конечно, это будущее у нас будет.$b$bВпрочем, я опережаю события. Сбавим темп. Садись, выпей со мной. Поговорим о будущем Азерота.','Выпейте с Гневионом. Он угощает.','Разумеется, я должен попросить тебя, чтобы наш разговор остался в тайне.$B$BНе стоит тревожить тех, кто, скажем так, уступает тебе талантами.','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так рождается легенда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш мир сейчас на распутье. Следующие месяцы определят его будущее – если, конечно, это будущее у нас будет.$b$bВпрочем, я опережаю события. Сбавим темп. Садись, выпей со мной. Поговорим о будущем Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте с Гневионом. Он угощает.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разумеется, я должен попросить тебя, чтобы наш разговор остался в тайне.$B$BНе стоит тревожить тех, кто, скажем так, уступает тебе талантами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31455,'Шадо-Пан','Ты кто? Умеешь сражаться? Если так, нам пригодилась бы твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шадо-Пан',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты кто? Умеешь сражаться? Если так, нам пригодилась бы твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31456,'Ферма Мускусной Лапы','Здесь неподалеку есть еще одно поселение пандаренов – ферма Мускусной Лапы. Уж не знаю, удалось ли им там пережить вторжение яунголов.\r\n\r\nТы очень $gпомог:помогла; нам – так помоги уж заодно и им!','Чего? А ты еще кто? Чего надо?$B$BА, так ты хочешь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ферма Мускусной Лапы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь неподалеку есть еще одно поселение пандаренов – ферма Мускусной Лапы. Уж не знаю, удалось ли им там пережить вторжение яунголов.\r\n\r\nТы очень $gпомог:помогла; нам – так помоги уж заодно и им!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего? А ты еще кто? Чего надо?$B$BА, так ты хочешь помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31457,'Ферма Мускусной Лапы','Здесь неподалеку есть еще одно поселение пандаренов – ферма Мускусной Лапы. Уж не знаю, удалось ли им там пережить вторжение яунголов.\r\n\r\nТы очень $gпомог:помогла; нам – так помоги уж заодно и им!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ферма Мускусной Лапы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь неподалеку есть еще одно поселение пандаренов – ферма Мускусной Лапы. Уж не знаю, удалось ли им там пережить вторжение яунголов.\r\n\r\nТы очень $gпомог:помогла; нам – так помоги уж заодно и им!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31458,'Устранение ущерба','Кор\'ик неделями докладывал обо всем императрице. Ей известно обо всех действиях клакси.$b$bЭтому надо положить конец немедленно!$b$bВ Кипари Ик первыми узнают о кончине Кор\'ика. Было бы неплохо, если бы эти известия не достигли императрицы.$b$bНадо расправиться с шептателями и уничтожить маяк. Это даст нам достаточно времени, чтобы составить план действий и обхитрить императрицу.','Убейте 5 ик\'тиков-шептателей и выведите из строя маяк Кипари Ик.','Отличная работа! Теперь мы сможем справиться с последствиями предательства Кор\'ика.$B$BВозможно, тебе удалось слегка изменить положение дел в нашу пользу.','Знание – это сила, Пробудитель. Те, кто больше знают, всегда сильнее других.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение ущерба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кор\'ик неделями докладывал обо всем императрице. Ей известно обо всех действиях клакси.$b$bЭтому надо положить конец немедленно!$b$bВ Кипари Ик первыми узнают о кончине Кор\'ика. Было бы неплохо, если бы эти известия не достигли императрицы.$b$bНадо расправиться с шептателями и уничтожить маяк. Это даст нам достаточно времени, чтобы составить план действий и обхитрить императрицу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 ик\'тиков-шептателей и выведите из строя маяк Кипари Ик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа! Теперь мы сможем справиться с последствиями предательства Кор\'ика.$B$BВозможно, тебе удалось слегка изменить положение дел в нашу пользу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знание – это сила, Пробудитель. Те, кто больше знают, всегда сильнее других.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31459,'Послание от Чо','Ко мне приходил груммель, просил передать, что Чо ожидает тебя. Отправляйся к Чо, наверняка, дело важное.\r\n\r\nГруммель сказал, что Чо сейчас к северу отсюда, в Пэй-Лэй.','Здравствуй. Приятно снова повидаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание от Чо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ко мне приходил груммель, просил передать, что Чо ожидает тебя. Отправляйся к Чо, наверняка, дело важное.\r\n\r\nГруммель сказал, что Чо сейчас к северу отсюда, в Пэй-Лэй.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй. Приятно снова повидаться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31460,'Послание от Чо','Забегал один из этих миленьких груммелей. Передавал, что Чо ожидает тебя. Отправляйся скорее!\r\n\r\nГруммель сказал, что Чо сейчас к северу отсюда, в Пэй-Лэй.','Здравствуй. Приятно снова повидаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание от Чо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Забегал один из этих миленьких груммелей. Передавал, что Чо ожидает тебя. Отправляйся скорее!\r\n\r\nГруммель сказал, что Чо сейчас к северу отсюда, в Пэй-Лэй.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй. Приятно снова повидаться.',`offerrewardtext_loc8`);
