INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31465,'Ответы на вопросы','Кипари Ик – одно из тех мест, в которых императрица Шек\'зир растит свое потомство. Молодые роерожденные безрассудны, ими тяжело управлять. К тому же они смертельно опасны.$b$bОни вырабатывают особо опасный яд, который с возрастом теряет свою силу. Если он попадет на кожу, то даже самый сильный и опытный воин будет обездвижен.$b$bЯ хочу, чтобы ты $gпринес:принесла; мне этот яд.','Соберите 6 покрытых ядом жвал ик\'тиков-роерожденных в Кипари Ик.','Этот яд сейчас довольно силен, и, похоже, даже не слабеет...$B$BВесьма любопытно. Надо срочно сообщить обо всем клакси. Спасибо, Пробудитель.','Яд роерожденных не только станет нашим дополнительным оружием, но и поможет узнать, на каком этапе развития находится сейчас рой.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответы на вопросы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кипари Ик – одно из тех мест, в которых императрица Шек\'зир растит свое потомство. Молодые роерожденные безрассудны, ими тяжело управлять. К тому же они смертельно опасны.$b$bОни вырабатывают особо опасный яд, который с возрастом теряет свою силу. Если он попадет на кожу, то даже самый сильный и опытный воин будет обездвижен.$b$bЯ хочу, чтобы ты $gпринес:принесла; мне этот яд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 покрытых ядом жвал ик\'тиков-роерожденных в Кипари Ик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот яд сейчас довольно силен, и, похоже, даже не слабеет...$B$BВесьма любопытно. Надо срочно сообщить обо всем клакси. Спасибо, Пробудитель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яд роерожденных не только станет нашим дополнительным оружием, но и поможет узнать, на каком этапе развития находится сейчас рой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31466,'FLAG - Took Loot') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG - Took Loot',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31467,'Сила тигра','Я – мастер Жаровни. Еда, которую я готовлю, делает тебя сильнее. Выучись готовить жаренный на углях стейк из тигриного мяса и покажи мне, на что ты $gспособен:способна;.','Выучите рецепт жареного на углях стейка из тигриного мяса у мастера Жаровни и угостите его 5 стейками.','Сила и здоровье! Таков Путь Гриля.','Выучи рецепт и покажи мне, что ты умеешь.','Принесите 5 обугленных стейков из тигриного мяса Мастеру гриля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – мастер Жаровни. Еда, которую я готовлю, делает тебя сильнее. Выучись готовить жаренный на углях стейк из тигриного мяса и покажи мне, на что ты $gспособен:способна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт жареного на углях стейка из тигриного мяса у мастера Жаровни и угостите его 5 стейками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сила и здоровье! Таков Путь Гриля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выучи рецепт и покажи мне, что ты умеешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 обугленных стейков из тигриного мяса Мастеру гриля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31468,'Испытание Черного принца','Я слышал, что ты – $gпервый:первая; среди первых, и все же, если позволишь, я хотел бы испытать твою доблесть лично.$b$bМогу, что осаждают Вечноцветущий дол, приспешники могу, населяющие Шань\'цзэ Дао и запятнанные порчей ша богомолы, что заполонили Жуткие пустоши – вот противники, что вполне подойдут для воителя твоего калибра.$b$bПокажи мне свою силу. И не спеши, я понимаю, что это займет у тебя некоторое время.','Добейтесь, чтобы Черный принц относился к вам с уважением. Заработать у него репутацию можно, убивая могу и богомолов 90-го уровня в Вечноцветущем доле, Танлунских степях и Жутких пустошах.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание Черного принца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что ты – $gпервый:первая; среди первых, и все же, если позволишь, я хотел бы испытать твою доблесть лично.$b$bМогу, что осаждают Вечноцветущий дол, приспешники могу, населяющие Шань\'цзэ Дао и запятнанные порчей ша богомолы, что заполонили Жуткие пустоши – вот противники, что вполне подойдут для воителя твоего калибра.$b$bПокажи мне свою силу. И не спеши, я понимаю, что это займет у тебя некоторое время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейтесь, чтобы Черный принц относился к вам с уважением. Заработать у него репутацию можно, убивая могу и богомолов 90-го уровня в Вечноцветущем доле, Танлунских степях и Жутких пустошах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31469,'UNUSED','The Pandaren Way of the Grill produces foods that increase your physical strength. Learn the recipe for Charbroiled Tiger Steak from the Master of the Grill and show him the results of your learning.','Make a Charbroiled Tiger Steak for the Master of the Grill. You will need to learn the Way of the Grill and the recipe from him first.','Give the Charbroiled Tiger Steak to the Master of the Grill.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The Pandaren Way of the Grill produces foods that increase your physical strength. Learn the recipe for Charbroiled Tiger Steak from the Master of the Grill and show him the results of your learning.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Make a Charbroiled Tiger Steak for the Master of the Grill. You will need to learn the Way of the Grill and the recipe from him first.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Give the Charbroiled Tiger Steak to the Master of the Grill.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31470,'Путь Вок','Если ты желаешь готовить еду, повышающую ловкость, тебе нужно принести немного моркови и риса мастеру Вок. Местные гну-сини таскают с грядок морковь и повсюду ее прячут. А если у тебя есть ферма, ты можешь вырастить ее и $gсам:сама;.','Принесите 5 диких хрустящих морковок мастеру Вок.','Отлично.','Здравствуй, будущий повар! Хочешь постичь Путь Вок?','Принесите 5 хрустящих морковок мастеру Вок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Вок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты желаешь готовить еду, повышающую ловкость, тебе нужно принести немного моркови и риса мастеру Вок. Местные гну-сини таскают с грядок морковь и повсюду ее прячут. А если у тебя есть ферма, ты можешь вырастить ее и $gсам:сама;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 диких хрустящих морковок мастеру Вок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй, будущий повар! Хочешь постичь Путь Вок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 хрустящих морковок мастеру Вок.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31471,'Проворность тигра','Путь Вок требует от кулинара ловкости. Сначала я обучу тебя готовить пассерованную морковь.','Выучите рецепт приготовления пассерованной моркови у мастера Вок, а затем дайте ей 5 пассерованных морковок.','Ты молодчина.','Позволь мне научить тебя готовить пассерованную морковь.','Принесите 5 порций пассерованной моркови мастеру Вок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проворность тигра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путь Вок требует от кулинара ловкости. Сначала я обучу тебя готовить пассерованную морковь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт приготовления пассерованной моркови у мастера Вок, а затем дайте ей 5 пассерованных морковок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодчина.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позволь мне научить тебя готовить пассерованную морковь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 порций пассерованной моркови мастеру Вок.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31472,'Путь Котелка','Кухня Пути Котелка помогает повысить интеллект. Принеси мастеру Котелка немного нефритовой двоякодышащей рыбы, и она все тебе объяснит. Нефритовую двоякодышащую рыбу можно поймать в водоемах Нефритового леса.','Принесите 5 нефритовых двоякодышащих рыб мастеру котелка.','Отлично. Начнем урок.','Хочешь выучить рецепт супа из клубящегося тумана? Сначала принеси мне нефритовых двоякодышащих рыб.','Принесите 5 нефритовых двоякодышащих рыб мастеру котелка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Котелка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кухня Пути Котелка помогает повысить интеллект. Принеси мастеру Котелка немного нефритовой двоякодышащей рыбы, и она все тебе объяснит. Нефритовую двоякодышащую рыбу можно поймать в водоемах Нефритового леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 нефритовых двоякодышащих рыб мастеру котелка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Начнем урок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь выучить рецепт супа из клубящегося тумана? Сначала принеси мне нефритовых двоякодышащих рыб.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 нефритовых двоякодышащих рыб мастеру котелка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31473,'Сила врагов','Соберите 10 печатей власти и 10 печатей мудрости, победив боссов в рейдах "Подземелья Могу\'шан", "Сердце Страха" и "Терраса Вечной Весны".','Печатью мудрости обычно владеют те, кто применяют магию, а печатью власти – те, кто предпочитают грубую силу.$B$BЭто не правило, а лишь информация, которая может помочь в поисках. Все может оказаться и наоборот.','Принесите печати Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила врагов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 печатей власти и 10 печатей мудрости, победив боссов в рейдах "Подземелья Могу\'шан", "Сердце Страха" и "Терраса Вечной Весны".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Печатью мудрости обычно владеют те, кто применяют магию, а печатью власти – те, кто предпочитают грубую силу.$B$BЭто не правило, а лишь информация, которая может помочь в поисках. Все может оказаться и наоборот.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите печати Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31474,'Суп созерцания','Пока кулинар наблюдает за котлом, у него есть время для размышлений. Давай я обучу тебя, как готовить суп из клубящегося тумана, и ты поймешь, о чем я говорю.','Выучите рецепт супа из клубящегося тумана у мастера котелка и угостите ее 5 порциями супа.','Интеллект – это дар, оттачиваемый со временем.','Если хочешь познать Путь Котелка, начни с приготовления супа из клубящегося тумана.','Принесите 5 порций супа из клубящегося тумана мастеру котелка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суп созерцания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока кулинар наблюдает за котлом, у него есть время для размышлений. Давай я обучу тебя, как готовить суп из клубящегося тумана, и ты поймешь, о чем я говорю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт супа из клубящегося тумана у мастера котелка и угостите ее 5 порциями супа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интеллект – это дар, оттачиваемый со временем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если хочешь познать Путь Котелка, начни с приготовления супа из клубящегося тумана.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 порций супа из клубящегося тумана мастеру котелка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31475,'Путь Пароварки','После хорошей трапезы любой воспрянет духом. А от кухни Пути Пароварки и подавно. Принеси мастеру пароварки немного гигантских раков-богомолов и он все тебе объяснит. Гигантских раков-богомолов можно поймать в океане.','Принесите 5 раков-богомолов мастеру пароварки.','Прекрасные ингредиенты.','Хочешь выучиться Пути Пароварки? Тебе потребуются раки-богомолы.','Принесите 5 гигантских раков-богомолов Мастеру пароварки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Пароварки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После хорошей трапезы любой воспрянет духом. А от кухни Пути Пароварки и подавно. Принеси мастеру пароварки немного гигантских раков-богомолов и он все тебе объяснит. Гигантских раков-богомолов можно поймать в океане.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 раков-богомолов мастеру пароварки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные ингредиенты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь выучиться Пути Пароварки? Тебе потребуются раки-богомолы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 гигантских раков-богомолов Мастеру пароварки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31476,'Дух кулинарии','Когда я готовлю на пару, еда пропитывается моей любовью. Позволь мне научить тебя готовить клецки с раками-богомолами.','Выучите рецепт клецек с раками-богомолами у мастера пароварки и угостите его 5 клецками.','От хорошей еды можно воспрянуть духом.','Позволь мне научить тебя готовить клецки с раками-богомолами.','Принесите 5 клецек с раками-богомолами Мастеру пароварки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух кулинарии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я готовлю на пару, еда пропитывается моей любовью. Позволь мне научить тебя готовить клецки с раками-богомолами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт клецек с раками-богомолами у мастера пароварки и угостите его 5 клецками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От хорошей еды можно воспрянуть духом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позволь мне научить тебя готовить клецки с раками-богомолами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 клецек с раками-богомолами Мастеру пароварки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31477,'Закалка','Говорят, что журавль, охраняющий сон своей стаи, берет в клюв камень. Если он засыпает, то роняет камень и от этого просыпается. Чтобы управляться с печью, тебе понадобится закалка и терпение. Изучи рецепт приготовления жареной дичи и покажи мне, что тебе удалось усвоить.','Выучите рецепт приготовления жареной дичи у мастера печи и дайте ему попробовать 5 блюд из жареной дичи.','Выносливость и закалка нужны для достижения мастерства в любом деле. Работа с раскаленной печью требует много терпения, но результаты стоят затраченных усилий.','Выучи рецепт приготовления жареной дичи и дай мне попробовать готовое блюдо.','Принесите 5 порций жареной дичи мастеру печи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закалка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что журавль, охраняющий сон своей стаи, берет в клюв камень. Если он засыпает, то роняет камень и от этого просыпается. Чтобы управляться с печью, тебе понадобится закалка и терпение. Изучи рецепт приготовления жареной дичи и покажи мне, что тебе удалось усвоить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт приготовления жареной дичи у мастера печи и дайте ему попробовать 5 блюд из жареной дичи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выносливость и закалка нужны для достижения мастерства в любом деле. Работа с раскаленной печью требует много терпения, но результаты стоят затраченных усилий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выучи рецепт приготовления жареной дичи и дай мне попробовать готовое блюдо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 порций жареной дичи мастеру печи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31478,'Путь Печи','Принесите 5 грудок дикой птицы мастеру печи.','Сгодится.','Хочешь обучиться Пути Печи? Тебе потребуются грудки дикой птицы.','Принесите 5 грудок дикой птицы мастеру печи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Печи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 грудок дикой птицы мастеру печи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сгодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь обучиться Пути Печи? Тебе потребуются грудки дикой птицы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите 5 грудок дикой птицы мастеру печи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31479,'Путь варения напитков','Пандаренский кулинарный Путь варения напитков – это... Впрочем, пусть лучше об этом расскажет опытный мастер. Принеси ему немного женьшеня и он тебе все покажет.','Принесите женьшень мастеру варения напитков. Женьшень можно купить у Суншиня Железной Лапы.','Прекрасный корень женьшеня! Хочешь научиться готовить из него чай?','Хочешь познать Путь варения напитков?','Принесите одну порцию женьшеня мастеру варения напитков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь варения напитков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандаренский кулинарный Путь варения напитков – это... Впрочем, пусть лучше об этом расскажет опытный мастер. Принеси ему немного женьшеня и он тебе все покажет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите женьшень мастеру варения напитков. Женьшень можно купить у Суншиня Железной Лапы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасный корень женьшеня! Хочешь научиться готовить из него чай?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь познать Путь варения напитков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите одну порцию женьшеня мастеру варения напитков.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31480,'Выпей чаю','Мои братья и сестры всегда так заняты. Жизнь слишком коротка, чтобы провести ее в делах и заботах. Выпей со мной женьшеневого чаю и насладись мгновением.','Выучите рецепт приготовления женьшеневого чая у мастера варки и угостите его одной чашечкой.','Отлично. Очень вкусно.','Позволь-ка научить тебя приготовлению женьшеневого чая.','Принесите одну порцию женьшеневого чая мастеру варки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выпей чаю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои братья и сестры всегда так заняты. Жизнь слишком коротка, чтобы провести ее в делах и заботах. Выпей со мной женьшеневого чаю и насладись мгновением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выучите рецепт приготовления женьшеневого чая у мастера варки и угостите его одной чашечкой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Очень вкусно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позволь-ка научить тебя приготовлению женьшеневого чая.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите одну порцию женьшеневого чая мастеру варки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (31481,'Страх как он есть','Принесите Химеру Страха Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страх как он есть',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите Химеру Страха Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31482,'Дыхание Черного принца','<Гневион пристально смотрит на вас.>$b$bТы из редкой породы, $n.$b$bИменно $gтакой мне и нужен:такая мне и нужна; – кто-то, кому хватит сил изменить ход событий во всем мире.$b$bЯ обещал тебе награду, и ты ее получишь! К востоку от таверны есть каменная лестница, ведущая к месту, которое местные жители называют "Причудой Камнетеса". Встретимся там.','Доберитесь до верха лестницы и встретьтесь с Гневионом на Причуде Камнетеса, чтобы забрать свою награду.','Поговорите с Гневионом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дыхание Черного принца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гневион пристально смотрит на вас.>$b$bТы из редкой породы, $n.$b$bИменно $gтакой мне и нужен:такая мне и нужна; – кто-то, кому хватит сил изменить ход событий во всем мире.$b$bЯ обещал тебе награду, и ты ее получишь! К востоку от таверны есть каменная лестница, ведущая к месту, которое местные жители называют "Причудой Камнетеса". Встретимся там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до верха лестницы и встретьтесь с Гневионом на Причуде Камнетеса, чтобы забрать свою награду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31483,'Приближение...','Пандаренская кампания только начинается! Сейчас нам надо обратить внимание на конфликт между Альянсом и Ордой.$b$bМои осведомители в Поместье Черного Ворона сообщили, что 7-ой Легион Альянса и войска Орды уже приближаются к южным берегам Пандарии. Нравится нам это или нет, но скоро наша земля станет полем боя.$b$bПока что нам не о чем больше говорить, но свяжись со мной, когда здесь появится твой флот. А потом... мы вместе устремимся в бой.','Свяжитесь с Гневионом, когда ваш флот доберется до южного побережья Пандарии.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приближение...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандаренская кампания только начинается! Сейчас нам надо обратить внимание на конфликт между Альянсом и Ордой.$b$bМои осведомители в Поместье Черного Ворона сообщили, что 7-ой Легион Альянса и войска Орды уже приближаются к южным берегам Пандарии. Нравится нам это или нет, но скоро наша земля станет полем боя.$b$bПока что нам не о чем больше говорить, но свяжись со мной, когда здесь появится твой флот. А потом... мы вместе устремимся в бой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с Гневионом, когда ваш флот доберется до южного побережья Пандарии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31484,'По следам Хисека') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следам Хисека',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31485,'UNUSED','I am not a master chef like my siblings. What I am is a great teacher. If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.$b$bIf you wish to learn, show me you can at least follow basic instructions. Learn the recipe for soft-boiled eggs, make five of them and bring them to me. I have fresh eggs which I will sell to you at a token price.','Learn the recipe for Soft-Boiled Eggs from the Guide to the Ways and make 5 of them for her.','Give the 5 Soft-Boiled Eggs to the Guide to the Ways.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I am not a master chef like my siblings. What I am is a great teacher. If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are.$b$bIf you wish to learn, show me you can at least follow basic instructions. Learn the recipe for soft-boiled eggs, make five of them and bring them to me. I have fresh eggs which I will sell to you at a token price.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Learn the recipe for Soft-Boiled Eggs from the Guide to the Ways and make 5 of them for her.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Give the 5 Soft-Boiled Eggs to the Guide to the Ways.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31486,'Все, что я знаю о кулинарии','Как меня радует, что тебе понравилась моя еда. Может, тебе нужны рецепты? Если да, то тебе стоит обучиться им у опытных кулинаров на рынке Полугорья. Они научили меня всему, что я знаю о кулинарии.$b$bЕсли соберешься на рынок Полугорья, не захватишь с собой письмо для Суншинь Железной Лапы? Она была моим любимым учителем. Хочу, чтобы она знала, как я скучаю по ней.','Доставьте письмо Суншинь Железной Лапе. Она преподает на рынке Полугорья.','Ой, как это мило... Люблю, когда бывшие ученики присылают мне весточки.','У тебя есть письмо для меня?','Доставьте письмо Суншинь Железная Лапа. Она обучает желающих на рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все, что я знаю о кулинарии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как меня радует, что тебе понравилась моя еда. Может, тебе нужны рецепты? Если да, то тебе стоит обучиться им у опытных кулинаров на рынке Полугорья. Они научили меня всему, что я знаю о кулинарии.$b$bЕсли соберешься на рынок Полугорья, не захватишь с собой письмо для Суншинь Железной Лапы? Она была моим любимым учителем. Хочу, чтобы она знала, как я скучаю по ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Суншинь Железной Лапе. Она преподает на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, как это мило... Люблю, когда бывшие ученики присылают мне весточки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть письмо для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте письмо Суншинь Железная Лапа. Она обучает желающих на рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31487,'Звуковое разрушение','Использование акустического управления куньчунами было начальным этапом моих исследований, и этот метод довольно примитивен. Но, судя по всему, Империя все же взяла его на вооружение. Очевидно, манипуляторам Шек\'зир не по нраву устанавливать связь с куньчунами, как должно.$B$BИ они поплатятся за свою лень.$B$BВоспользуйся этим камертоном рядом с Ужасными куньчунами во Владениях Шек\'зир и увидишь, как они набросятся на своих же хозяев. Используй суматоху, как преимущество и уничтожь их всех.','Убейте 4 ужасных куньчунов и 6 манипуляторов Шек\'зир во Владениях Шек\'зир. Камертон звукового разрушения ослабит куньчунов и собьет их с толку.','Это послужит им уроком. Куньчунов следует уважать и опасаться.','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звуковое разрушение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Использование акустического управления куньчунами было начальным этапом моих исследований, и этот метод довольно примитивен. Но, судя по всему, Империя все же взяла его на вооружение. Очевидно, манипуляторам Шек\'зир не по нраву устанавливать связь с куньчунами, как должно.$B$BИ они поплатятся за свою лень.$B$BВоспользуйся этим камертоном рядом с Ужасными куньчунами во Владениях Шек\'зир и увидишь, как они набросятся на своих же хозяев. Используй суматоху, как преимущество и уничтожь их всех.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 ужасных куньчунов и 6 манипуляторов Шек\'зир во Владениях Шек\'зир. Камертон звукового разрушения ослабит куньчунов и собьет их с толку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это послужит им уроком. Куньчунов следует уважать и опасаться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31488,'Чужак в чужой стране','Прошу прощения, |3-6($c). Тебя зовут $n?$b$bМеня попросила передать тебе это незнакомка в темном плаще. Она, как и ты, прибыла из-за туманов, но... в общем, я ей не верю.$b$bЗаписку передали из таверны на Сокрытой лестнице. Я отдам ее, но, прошу тебя... не забывай об осторожности!','Разыщите некоего Черного принца в таверне "В туманах", что расположена на Сокрытой лестнице.','А! Вижу, мои помощники сделали свою работу и привели тебя ко мне. Чудесно.','Так ты получил мое письмо!','Разыщите "Черного принца" в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужак в чужой стране',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу прощения, |3-6($c). Тебя зовут $n?$b$bМеня попросила передать тебе это незнакомка в темном плаще. Она, как и ты, прибыла из-за туманов, но... в общем, я ей не верю.$b$bЗаписку передали из таверны на Сокрытой лестнице. Я отдам ее, но, прошу тебя... не забывай об осторожности!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите некоего Черного принца в таверне "В туманах", что расположена на Сокрытой лестнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Вижу, мои помощники сделали свою работу и привели тебя ко мне. Чудесно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так ты получил мое письмо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите "Черного принца" в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31489,'Чужак в чужой стране','Прошу прощения, |3-6($c). Тебя зовут $n?$b$bМеня попросила передать тебе это незнакомка в темном плаще. Она, как и ты, прибыла из-за туманов, но... в общем, я ей не верю.$b$bОна упомянула имя "Гневион". Тебе это о чем-нибудь говорит?$b$bЯ отдам тебе записку, но, прошу, если собираешься вести с ними дела, будь $gосторожен:осторожна;.','Разыщите некоего Гневиона в таверне "В туманах", что расположена на Сокрытой лестнице.','Найдите Гневиона в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужак в чужой стране',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу прощения, |3-6($c). Тебя зовут $n?$b$bМеня попросила передать тебе это незнакомка в темном плаще. Она, как и ты, прибыла из-за туманов, но... в общем, я ей не верю.$b$bОна упомянула имя "Гневион". Тебе это о чем-нибудь говорит?$b$bЯ отдам тебе записку, но, прошу, если собираешься вести с ними дела, будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите некоего Гневиона в таверне "В туманах", что расположена на Сокрытой лестнице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Гневиона в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31490,'Всех до единого','А теперь – самое главное. Давай-ка поохотимся на крестоносцев Алого ордена.$b$bИ когда я говорю "поохотимся", я имею в виду – изведем их под корень, убьем всех до единого.','Убейте 50 крестоносцев Алого ордена в залах Алого ордена.','Поговорите с рыцарем в капюшоне в залах Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всех до единого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь – самое главное. Давай-ка поохотимся на крестоносцев Алого ордена.$b$bИ когда я говорю "поохотимся", я имею в виду – изведем их под корень, убьем всех до единого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 крестоносцев Алого ордена в залах Алого ордена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем в капюшоне в залах Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31491,'Трехметровый шест','Однажды Сюэнь предложил последнему императору Пандарии такое испытание: встать в центре комнаты и сдерживать нападающих монахов, защищаясь лишь трехметровым шестом.$b$bМой рекорд – десять. Сможешь его побить?','Сдержите не менее 10-и монахов из Храма Тигра с помощью трехметрового шеста.','Поговорите с Линь Мягкой Лапой в Храме Тигра, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трехметровый шест',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однажды Сюэнь предложил последнему императору Пандарии такое испытание: встать в центре комнаты и сдерживать нападающих монахов, защищаясь лишь трехметровым шестом.$b$bМой рекорд – десять. Сможешь его побить?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сдержите не менее 10-и монахов из Храма Тигра с помощью трехметрового шеста.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линь Мягкой Лапой в Храме Тигра, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31492,'Факел силы','У Сюэня есть испытание, которое, по его словам, "придает силу". Я начинаю подозревать, что под словом "сила" он понимает совсем не то, что мы.$b$bВот, возьми этот факел и отнеси его к вершине храмовых ворот. Если донесешь его туда так, чтобы он не потух – испытание пройдено.$b$bИ, самое главное: даже не пытайся везти факел, сидя на верховом животном. Его задует моментально. Уж поверь.','Ух ты! Получилось. А мне вот обычно мешают порывы ветра.','Поговорите с Линь Мягкой Лапой в Храме Белого Тигра, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Факел силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Сюэня есть испытание, которое, по его словам, "придает силу". Я начинаю подозревать, что под словом "сила" он понимает совсем не то, что мы.$b$bВот, возьми этот факел и отнеси его к вершине храмовых ворот. Если донесешь его туда так, чтобы он не потух – испытание пройдено.$b$bИ, самое главное: даже не пытайся везти факел, сидя на верховом животном. Его задует моментально. Уж поверь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Получилось. А мне вот обычно мешают порывы ветра.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линь Мягкой Лапой в Храме Белого Тигра, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31493,'Сохранить и уберечь... не более того','Здесь, в этих залах есть книга, которая для меня очень ценна.$b$bК несчастью, сейчас ей завладел ткач пламени Кеглер. Мои попытки подобраться к нему ничем не увенчались.$b$bВозможно, тебе повезет больше. Но берегись – ходят слухи, что он уже окончательно сошел с ума. Ткач пламени хочет сжечь все до единой книги, что стоят в библиотеке.$b$bВозможно, заодно он намерен сжечь и залы Алого ордена.','Заполучите кодекс ордена.','О да!$B$B<Рыцарь в капюшоне радостно потирает руки при виде кодекса.>$B$BТеперь у меня есть перечень всех имен крестоносцев Алого ордена!$B$BА то, знаешь... мало ли, вдруг с кем-то из них еще не рассчитались. Не люблю быть должной.','Мне обязательно нужно завладеть кодексом.','Поговорите с рыцарем в капюшоне в залах Алого ордена.','У него кодекс ордена. Нужно скорее забрать эту книгу, пока он не сжег ее дотла.','Ткач пламени Кеглер') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранить и уберечь... не более того',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в этих залах есть книга, которая для меня очень ценна.$b$bК несчастью, сейчас ей завладел ткач пламени Кеглер. Мои попытки подобраться к нему ничем не увенчались.$b$bВозможно, тебе повезет больше. Но берегись – ходят слухи, что он уже окончательно сошел с ума. Ткач пламени хочет сжечь все до единой книги, что стоят в библиотеке.$b$bВозможно, заодно он намерен сжечь и залы Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заполучите кодекс ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да!$B$B<Рыцарь в капюшоне радостно потирает руки при виде кодекса.>$B$BТеперь у меня есть перечень всех имен крестоносцев Алого ордена!$B$BА то, знаешь... мало ли, вдруг с кем-то из них еще не рассчитались. Не люблю быть должной.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне обязательно нужно завладеть кодексом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем в капюшоне в залах Алого ордена.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У него кодекс ордена. Нужно скорее забрать эту книгу, пока он не сжег ее дотла.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ткач пламени Кеглер',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31494,'Свободу куньчунам','Манипуляторы Шек\'зир собирают молодых куньчунов и воздействуют на них энергией чистого страха, чтобы изменить их и ускорить их рост.$B$BОтвратительно! Я не позволю, чтобы это продолжалось!$B$BОсвободи этих куньчунов из клеток.','Откройте клетки куньчунов и освободите 8 юных куньчунов во Владениях Шек\'зир.','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу куньчунам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Манипуляторы Шек\'зир собирают молодых куньчунов и воздействуют на них энергией чистого страха, чтобы изменить их и ускорить их рост.$B$BОтвратительно! Я не позволю, чтобы это продолжалось!$B$BОсвободи этих куньчунов из клеток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте клетки куньчунов и освободите 8 юных куньчунов во Владениях Шек\'зир.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31495,'Всех до единого','А теперь – самое главное. Давай-ка поохотимся на крестоносцев Алого ордена.$b$bИ когда я говорю "поохотимся", я имею в виду – изведем их под корень, убьем всех до единого.','Убейте 50 крестоносцев Алого ордена в залах Алого ордена.','Отличное начало, Эрезул!$B$BСкоро от Алого ордена останется лишь безобразная строчка в анналах истории.','Поговорите с рыцарем в капюшоне в залах Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всех до единого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь – самое главное. Давай-ка поохотимся на крестоносцев Алого ордена.$b$bИ когда я говорю "поохотимся", я имею в виду – изведем их под корень, убьем всех до единого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 крестоносцев Алого ордена в залах Алого ордена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличное начало, Эрезул!$B$BСкоро от Алого ордена останется лишь безобразная строчка в анналах истории.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем в капюшоне в залах Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31496,'Лучший напиток Империи','Чудесные свойства сока кипари не перестают меня поражать. Но самое главное, из него можно изготовить очень питательный и невероятно вкусный напиток.$B$BКонечно же, лучше всего его готовят во дворце. В домах верноподданных эта прекрасная жидкость накапливается в особых сборниках.$B$BНаполни этот кувшин соком и возвращайся ко мне. Я так давно не пробовал этого чудесного напитка.','Используйте кувшин для сока на императорских сборниках сока 4 раза, чтобы наполнить его.','О, да! Наконец-то! Отдавай кувшин скорее! Мои лапки трясутся от нетерпения.','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший напиток Империи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудесные свойства сока кипари не перестают меня поражать. Но самое главное, из него можно изготовить очень питательный и невероятно вкусный напиток.$B$BКонечно же, лучше всего его готовят во дворце. В домах верноподданных эта прекрасная жидкость накапливается в особых сборниках.$B$BНаполни этот кувшин соком и возвращайся ко мне. Я так давно не пробовал этого чудесного напитка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте кувшин для сока на императорских сборниках сока 4 раза, чтобы наполнить его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! Наконец-то! Отдавай кувшин скорее! Мои лапки трясутся от нетерпения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
