INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31502,'Подрезать крылышки','Юные летуны в этих краях меня просто завораживают. Такая ловкость и выносливость скорее свойственны тем, кто давно занимается полетами и отдает этому занятию всего себя, без остатка.$B$BНаверное, их крылья каким-то образом эволюционировали... Или тренировки стали более действенными? Или это генетическая мутация? Или селекция?$B$BПроклятье! Без образцов тканей я ничего не узнаю.$B$BПринеси мне их крылья. И постарайся не испортить, будь так $gдобр:добра;. Они нужны мне в целости и сохранности.','Соберите 24 крыла пронзателей, уничтожая пронзателей Шек\'зир во Владениях Шек\'зир.','Отлично, ты их почти не помял.','Ну что, крылья у тебя?','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подрезать крылышки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Юные летуны в этих краях меня просто завораживают. Такая ловкость и выносливость скорее свойственны тем, кто давно занимается полетами и отдает этому занятию всего себя, без остатка.$B$BНаверное, их крылья каким-то образом эволюционировали... Или тренировки стали более действенными? Или это генетическая мутация? Или селекция?$B$BПроклятье! Без образцов тканей я ничего не узнаю.$B$BПринеси мне их крылья. И постарайся не испортить, будь так $gдобр:добра;. Они нужны мне в целости и сохранности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 24 крыла пронзателей, уничтожая пронзателей Шек\'зир во Владениях Шек\'зир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, ты их почти не помял.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, крылья у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31503,'Короткий путь к краху','То, что я делаю, предназначено для опытных воинов. Это не игрушки для неразумных детей!','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс, что в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Короткий путь к краху',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что я делаю, предназначено для опытных воинов. Это не игрушки для неразумных детей!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс, что в Жутких пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31504,'Минные поля','Если агенты Великой Императрицы действуют так же, как в мое время, скорее всего, во владениях богомолов спрятано немало феромоновых мин.$B$BДостаточно шепота императрицы, и все они взорвутся, накрыв окрестности облаком феромонов, и тогда от войск не будет никакого толка.$B$BЕсли мы хотим, чтобы у нас появился шанс на победу, надо обезвредить эти мины. "Дар", которым я наградил тебя при нашей первой встрече, позволит тебе увидеть эти мины. Активируй их, а затем отбеги на безопасное расстояние.','Обезвредьте 8 феромоновых мин во Владениях Шек\'зир и в Сердце Страха.','Надеюсь, ты не подвергся действию феромонов? Это может привести к... Впрочем, не буду пугать тебя подробностями.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс, что в Жутких пустошей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минные поля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если агенты Великой Императрицы действуют так же, как в мое время, скорее всего, во владениях богомолов спрятано немало феромоновых мин.$B$BДостаточно шепота императрицы, и все они взорвутся, накрыв окрестности облаком феромонов, и тогда от войск не будет никакого толка.$B$BЕсли мы хотим, чтобы у нас появился шанс на победу, надо обезвредить эти мины. "Дар", которым я наградил тебя при нашей первой встрече, позволит тебе увидеть эти мины. Активируй их, а затем отбеги на безопасное расстояние.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обезвредьте 8 феромоновых мин во Владениях Шек\'зир и в Сердце Страха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, ты не подвергся действию феромонов? Это может привести к... Впрочем, не буду пугать тебя подробностями.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс, что в Жутких пустошей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31505,'Итак, один за одним, ее чемпионы погибают.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, один за одним, ее чемпионы погибают.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31506,'Оковы манипуляторов','Найдите 6 пар наручников зан\'тиков, уничтожая порабощенных рудокопов и порабощенных громил на Зан\'вессе.','Очень хитроумные устройства. Есть у меня чувство, что нам они пригодятся.','Ты же можешь справиться с этим заданием, или я ошибаюсь?','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы манипуляторов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 пар наручников зан\'тиков, уничтожая порабощенных рудокопов и порабощенных громил на Зан\'вессе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хитроумные устройства. Есть у меня чувство, что нам они пригодятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же можешь справиться с этим заданием, или я ошибаюсь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каз\'тику Манипулятору в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31507,'Катастрофа','Кипарит загорелся? Потрясающе!$B$BЭто не совсем то, на что я рассчитывал, но все равно хорошо.','Вернитесь к Корвену Первейшему в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катастрофа',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кипарит загорелся? Потрясающе!$B$BЭто не совсем то, на что я рассчитывал, но все равно хорошо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корвену Первейшему в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31508,'Нужны образцы','Соберите 6 кристаллов кипарита, уничтожая разрыхлителей грязи на Соленой отмели.','Смотри-ка, у тебя получилось. А я, честно говоря, думал, что придется тебя собирать на этом поле по кусочкам.','Ну что, образцы у тебя?','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужны образцы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кристаллов кипарита, уничтожая разрыхлителей грязи на Соленой отмели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри-ка, у тебя получилось. А я, честно говоря, думал, что придется тебя собирать на этом поле по кусочкам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, образцы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31509,'Страх пускает корни','Этот вид необычайно интересен, но даже оставлять его для исследований слишком опасно.','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страх пускает корни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот вид необычайно интересен, но даже оставлять его для исследований слишком опасно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рик\'калу Разрезателю в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31510,'Тишина','Потеря связи с Зан\'весс загонит Императрицу еще глубже в паранойю и безумие.$B$BОтлично. Она должна страдать.','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тишина',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потеря связи с Зан\'весс загонит Императрицу еще глубже в паранойю и безумие.$B$BОтлично. Она должна страдать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хисеку Хранителю Роя в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31511,'Очевидец истории','Добро пожаловать в Святилище Двух Лун, путник.$B$BЯ знаю, что Небожители отправили тебя помочь нам, но для начала как следует отдохни и исследуй город.$B$BМы рады видеть тебя в Вечноцветущем доле!','Поговорите с мадам Ви Ло в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очевидец истории',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Святилище Двух Лун, путник.$B$BЯ знаю, что Небожители отправили тебя помочь нам, но для начала как следует отдохни и исследуй город.$B$BМы рады видеть тебя в Вечноцветущем доле!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мадам Ви Ло в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (31512,'Очевидец истории','Поговорите с распорядительницей Ви Вин в святилище Семи Звезд в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очевидец истории',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с распорядительницей Ви Вин в святилище Семи Звезд в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31513,'Мечи помазанника','Хуже всего в крестоносцах Алого ордена то, что они умудряются возвращаться даже после смерти.$b$bЗа всеми этими воскрешениями стоит верховный инквизитор Вайтмейн. Не станет ее – не станет и ордена.$b$bЧтобы упокоить ее навсегда, нам нужны два легендарных клинка, у каждого из которых своя забытая, но славная история.$b$bК счастью для меня... э-э... нас, эти два клинка, мечи помазанника, хранятся здесь, в монастыре.$b$bНайди их, и, когда убьешь Вайтмейн, воткни мечи в ее труп, чтобы она уже не смогла ожить.','Заберите два меча помазанника.','<Второй меч помазанника парит в воздухе прямо перед мокрой статуей. От меча поднимается пар.>$B$B<Вы почему-то чувствуете, что Воля Провидения дожидается именно вас.>','<Вы уже завладели одним мечом и собираетесь забрать другой.>$B$B<За мечом стоит статуя, надпись на которой гласит "Воля Провидения".>','Найдите второй меч помазанника в монастыре Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мечи помазанника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хуже всего в крестоносцах Алого ордена то, что они умудряются возвращаться даже после смерти.$b$bЗа всеми этими воскрешениями стоит верховный инквизитор Вайтмейн. Не станет ее – не станет и ордена.$b$bЧтобы упокоить ее навсегда, нам нужны два легендарных клинка, у каждого из которых своя забытая, но славная история.$b$bК счастью для меня... э-э... нас, эти два клинка, мечи помазанника, хранятся здесь, в монастыре.$b$bНайди их, и, когда убьешь Вайтмейн, воткни мечи в ее труп, чтобы она уже не смогла ожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите два меча помазанника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Второй меч помазанника парит в воздухе прямо перед мокрой статуей. От меча поднимается пар.>$B$B<Вы почему-то чувствуете, что Воля Провидения дожидается именно вас.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы уже завладели одним мечом и собираетесь забрать другой.>$B$B<За мечом стоит статуя, надпись на которой гласит "Воля Провидения".>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите второй меч помазанника в монастыре Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31514,'Прах к праху','<Вы берете в руку второй меч и чувствуете, как сила обоих клинков наполняет вас.>$B$B<Дело за малым. Как объяснила таинственная женщина в капюшоне, чтобы остановить Алый орден, нужно пронзить тело верховного инквизитора Вайтмейн обоими клинками.>','Пронзите мечами помазанника тело верховного инквизитора Вайтмейн, чтобы она могла обрести вечный покой.','Поговорите с Лилиан Восс в монастыре Алого ордена.','Пронзи ее тело мечами послушника, чтобы положить конец тирании Алого ордена.','Верховный инквизитор Вайтмейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы берете в руку второй меч и чувствуете, как сила обоих клинков наполняет вас.>$B$B<Дело за малым. Как объяснила таинственная женщина в капюшоне, чтобы остановить Алый орден, нужно пронзить тело верховного инквизитора Вайтмейн обоими клинками.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пронзите мечами помазанника тело верховного инквизитора Вайтмейн, чтобы она могла обрести вечный покой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лилиан Восс в монастыре Алого ордена.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пронзи ее тело мечами послушника, чтобы положить конец тирании Алого ордена.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный инквизитор Вайтмейн',`questgivertargetname_loc8`);
