INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31516,'Прах к праху','<Вы берете в руку второй меч и чувствуете, как сила обоих клинков наполняет вас.>$B$B<Дело за малым. Как объяснила таинственная женщина в капюшоне, чтобы остановить Алый орден, нужно пронзить тело верховного инквизитора Вайтмейн обоими клинками.>','Пронзите мечами помазанника тело верховного инквизитора Вайтмейн, чтобы она могла обрести вечный покой.','Теперь, когда Вайтмейн больше нет, Алому ордену настанет конец. Теперь осталось убрать мусор.$B$BСпасибо тебе, Астральный. Не только от меня, но от всех, кто противостоял их злобе и ненависти.$B$BИ позволь поблагодарить за новые мечи. Они послужат мне верой и правдой в Некроситете, когда я буду сражаться с темным магистром Гандлингом.$B$BДо скорой встречи.','Поговорите с Лилиан Восс в монастыре Алого ордена.','Пронзи ее тело Мечами Помазанника, чтобы положить конец тирании Алого ордена.','Верховный инквизитор Вайтмейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах к праху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы берете в руку второй меч и чувствуете, как сила обоих клинков наполняет вас.>$B$B<Дело за малым. Как объяснила таинственная женщина в капюшоне, чтобы остановить Алый орден, нужно пронзить тело верховного инквизитора Вайтмейн обоими клинками.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пронзите мечами помазанника тело верховного инквизитора Вайтмейн, чтобы она могла обрести вечный покой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда Вайтмейн больше нет, Алому ордену настанет конец. Теперь осталось убрать мусор.$B$BСпасибо тебе, Астральный. Не только от меня, но от всех, кто противостоял их злобе и ненависти.$B$BИ позволь поблагодарить за новые мечи. Они послужат мне верой и правдой в Некроситете, когда я буду сражаться с темным магистром Гандлингом.$B$BДо скорой встречи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лилиан Восс в монастыре Алого ордена.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пронзи ее тело Мечами Помазанника, чтобы положить конец тирании Алого ордена.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Верховный инквизитор Вайтмейн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31517,'Проучить задиру','Мы ценим силу, а не жестокость. К сожалению, ко мне приходят и те, кто позабыл различия между ними.$b$BОдному из таких претендентов я отказал.$b$bВ качестве возмездия он захватил деревеньку Иньин.$b$bОтправляйся в Иньин, она находится к юго-востоку от храма, и сразись с этим "Шонуфом". Преподай ему урок истинной силы.','Победите Шонуфа.','Я признаю твою победу и благодарю за то, что ты проучил этого головореза.','Поговорите с Сюэнем в Храме Тигра, что на Вершине Кунь-Лай.','"Мастер" огнеплетения.','Шонуф') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проучить задиру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ценим силу, а не жестокость. К сожалению, ко мне приходят и те, кто позабыл различия между ними.$b$BОдному из таких претендентов я отказал.$b$bВ качестве возмездия он захватил деревеньку Иньин.$b$bОтправляйся в Иньин, она находится к юго-востоку от храма, и сразись с этим "Шонуфом". Преподай ему урок истинной силы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Шонуфа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я признаю твою победу и благодарю за то, что ты проучил этого головореза.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сюэнем в Храме Тигра, что на Вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','"Мастер" огнеплетения.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шонуф',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31518,'Вечноцветущий дол','Последний раз врата в дол открывались в незапамятные времена, $n.$b$bЯ бы ни за что не пропустил такое событие, и тебе не советую!$b$bВстретимся к югу от вершины Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечноцветущий дол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний раз врата в дол открывались в незапамятные времена, $n.$b$bЯ бы ни за что не пропустил такое событие, и тебе не советую!$b$bВстретимся к югу от вершины Кунь-Лай.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31519,'Серьезное испытание: Янь-Чжу Высвобожденный','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; на Хмелеварню Буйных Портеров. Когда прибудешь на место, задействуй сферу испытания и обрати в ветер Янь-Чжу Высвобожденного.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Хмелеварню Буйных Портеров в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Янь-Чжу Высвобожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; на Хмелеварню Буйных Портеров. Когда прибудешь на место, задействуй сферу испытания и обрати в ветер Янь-Чжу Высвобожденного.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Хмелеварню Буйных Портеров в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31520,'Серьезное испытание: Ша Сомнения','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; в Храм Нефритовой Змеи. Когда прибудешь на место, задействуй сферу испытания и испепели Ша Сомнения.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Храм Нефритовой Змеи в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Ша Сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; в Храм Нефритовой Змеи. Когда прибудешь на место, задействуй сферу испытания и испепели Ша Сомнения.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Храм Нефритовой Змеи в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31522,'Серьезное испытание: Ша Ненависти','Я хочу, чтобы ты $gсобрал:собрала; спокойную группу и $gотправился:отправилась; в Монастырь Шадо-Пан. Когда прибудешь на место, задействуй сферу испытания и спаси Тажаня Чжу из плена Ша Ненависти.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Монастырь Шадо-Пан в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Ша Ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; спокойную группу и $gотправился:отправилась; в Монастырь Шадо-Пан. Когда прибудешь на место, задействуй сферу испытания и спаси Тажаня Чжу из плена Ша Ненависти.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Монастырь Шадо-Пан в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31523,'Серьезное испытание: Синь Мастер Боя','Я хочу, чтобы ты $gсобрал:собрала; ловкую группу и $gотправился:отправилась; во Дворец Могу\'шан. Когда прибудешь на место, задействуй сферу испытания и срази Синя Мастера Боя.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Дворец Могу\'шан в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Синь Мастер Боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; ловкую группу и $gотправился:отправилась; во Дворец Могу\'шан. Когда прибудешь на место, задействуй сферу испытания и срази Синя Мастера Боя.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Дворец Могу\'шан в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31524,'Серьезное испытание: Райгонн','Я хочу, чтобы ты $gсобрал:собрала; могучую группу и $gотправился:отправилась; к Вратам Заходящего Солнца. Когда прибудешь на место, задействуй сферу испытания и сокруши Райгонна.$B$BВозвращайся ко мне за наградой, когда завершишь это испытание.','Пройдите Врата Заходящего Солнца в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Райгонн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; могучую группу и $gотправился:отправилась; к Вратам Заходящего Солнца. Когда прибудешь на место, задействуй сферу испытания и сокруши Райгонна.$B$BВозвращайся ко мне за наградой, когда завершишь это испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Врата Заходящего Солнца в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31525,'Серьезное испытание: командующий флангом Нер\'онок','Я хочу, чтобы ты $gсобрал:собрала; зоркую группу и $gпринял:приняла; участие в осаде храма Нюцзао. Когда прибудешь на место, задействуй сферу испытания и сровняй с землей командующего флангом Нер\'онока.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Осаду храма Нюцзао в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: командующий флангом Нер\'онок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; зоркую группу и $gпринял:приняла; участие в осаде храма Нюцзао. Когда прибудешь на место, задействуй сферу испытания и сровняй с землей командующего флангом Нер\'онока.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Осаду храма Нюцзао в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31526,'Серьезное испытание: Дюранд','Я хочу, чтобы ты $gсобрал:собрала; храбрую группу и $gотправился:отправилась; в Монастырь Алого ордена. Когда прибудешь на место, задействуй сферу испытания и покарай Дюранда.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Монастырь Алого ордена в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Дюранд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; храбрую группу и $gотправился:отправилась; в Монастырь Алого ордена. Когда прибудешь на место, задействуй сферу испытания и покарай Дюранда.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Монастырь Алого ордена в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31527,'Серьезное испытание: ткач пламени Кеглер','Я хочу, чтобы ты $gсобрал:собрала; находчивую группу и $gотправился:отправилась; в Залы Алого ордена. Когда прибудешь на место, задействуй сферу испытания и положи конец надругательству над книгами, которое творит ткач пламени Кеглер.','Пройдите Залы Алого ордена в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: ткач пламени Кеглер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; находчивую группу и $gотправился:отправилась; в Залы Алого ордена. Когда прибудешь на место, задействуй сферу испытания и положи конец надругательству над книгами, которое творит ткач пламени Кеглер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Залы Алого ордена в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31528,'Серьезное испытание: темный магистр Гандлинг','Я хочу, чтобы ты $gсобрал:собрала; бесстрашную группу и $gотправился:отправилась; в Некроситет. Когда прибудешь на место, задействуй сферу испытания и очисти Некроситет от тлетворного влияния темного магистра Гандлинга.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Некроситет в режиме испытания.','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: темный магистр Гандлинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; бесстрашную группу и $gотправился:отправилась; в Некроситет. Когда прибудешь на место, задействуй сферу испытания и очисти Некроситет от тлетворного влияния темного магистра Гандлинга.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Некроситет в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Ули в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31529,'Операция "Отстрел вредителей"','Меня отправили в эту долину, чтобы защищать Плодородную землю от любых угроз.$B$BИ я обнаружила серьезную проблему: прыгохвосты-вредители роют норы в утесах гор над нашими землями.$B$BЕсли не вмешаться, они размножатся и начнут уничтожать поля.$B$BИх необходимо истребить.','Убейте 12 прыгохвостов-вредителей.','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Отстрел вредителей"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня отправили в эту долину, чтобы защищать Плодородную землю от любых угроз.$B$BИ я обнаружила серьезную проблему: прыгохвосты-вредители роют норы в утесах гор над нашими землями.$B$BЕсли не вмешаться, они размножатся и начнут уничтожать поля.$B$BИх необходимо истребить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 прыгохвостов-вредителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31530,'Операция "Десяток хозенов"','Я наблюдаю за лагерем хозенов с самого прибытия, и мне не нравится то, что я вижу.$B$BПод покровом ночи хозены спускаются с гор и крадут продовольствие с фермерских угодий.$B$BЭто безнаказанное воровство необходимо пресечь. Я убивала их, как только видела, но один в поле не воин.$B$BНужна твоя помощь. Убей столько хозенов, сколько сможешь.','Убейте 12 прыгохвостов-вредителей.','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Десяток хозенов"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я наблюдаю за лагерем хозенов с самого прибытия, и мне не нравится то, что я вижу.$B$BПод покровом ночи хозены спускаются с гор и крадут продовольствие с фермерских угодий.$B$BЭто безнаказанное воровство необходимо пресечь. Я убивала их, как только видела, но один в поле не воин.$B$BНужна твоя помощь. Убей столько хозенов, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 прыгохвостов-вредителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31531,'Операция "Угроза с воздуха"','Обнаружена еще одна серьезная угроза. Из тех, о которой большинство и не подозревает.$B$BСкальные хищники, парящие над горами к востоку отсюда, опасны.$B$BЯ видел, как они планируют к фермам и крадут урожай и семена, когда никто не видит.$B$BЧтобы защитить фермерские хозяйства, необходимо уменьшить популяцию скальных хищников.','Убейте 12 скальных хищников.','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Угроза с воздуха"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обнаружена еще одна серьезная угроза. Из тех, о которой большинство и не подозревает.$B$BСкальные хищники, парящие над горами к востоку отсюда, опасны.$B$BЯ видел, как они планируют к фермам и крадут урожай и семена, когда никто не видит.$B$BЧтобы защитить фермерские хозяйства, необходимо уменьшить популяцию скальных хищников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 скальных хищников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31532,'Операция "Скальный хищник"','Сегодня утром во время обхода гор я заметила огромную белую птицу, которая пикировала к земле.$B$BЗатем птица ухватила своими когтями целого яка, подняла его и скрылась в скалах.$B$BСегодня она охотится на яков, а завтра ведь может начать охотиться и на фермеров!$B$BНеобходимо уничтожить эту птицу, пока никто не пострадал.','Убейте большого скального ястреба.','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Скальный хищник"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня утром во время обхода гор я заметила огромную белую птицу, которая пикировала к земле.$B$BЗатем птица ухватила своими когтями целого яка, подняла его и скрылась в скалах.$B$BСегодня она охотится на яков, а завтра ведь может начать охотиться и на фермеров!$B$BНеобходимо уничтожить эту птицу, пока никто не пострадал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте большого скального ястреба.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шо в деревню Куньцзэнь или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31533,'Идеальное перо','Вы еще ни разу не видели пера, подобного этому.$B$BВы знаете, кого оно может заинтересовать.','Принесите перо старику Горной Лапе. Его можно найти на рынке Полугорья или в доме старика Горная Лапа, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальное перо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы еще ни разу не видели пера, подобного этому.$B$BВы знаете, кого оно может заинтересовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите перо старику Горной Лапе. Его можно найти на рынке Полугорья или в доме старика Горная Лапа, что в Долине Четырех Ветров.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31534,'Хмель новичка','Ты умеешь хранить секреты, $n?$B$BЯ решила попробовать себя в хмелеварении. У меня есть лишь старый перегонный куб, но он все еще в рабочем состоянии.$B$BЕсть у меня идея для необычного хмеля, но мне не хватает ингредиентов.$B$BЯ стеснительная и почти не общаюсь с жителями города, но заметила, что ты вовсю заводишь друзей.$B$BТебя не затруднит попросить у фермеров необходимые ингредиенты?','Возьмите 1 сладкий озерный арбуз у Хаоханя Грязного Когтя, 1 бархатистый персик у Джины Грязный Коготь, 1 черешню у Рыбы Тростниковой Шкуры и 1 красный редис у фермера Фуна.','Ты $gпринес:принесла; их! Как здорово, $n!$b$bПриступлю к изготовлению хмеля как можно скорее.','Я не знаю, как это взбрело мне в голову. Может, от того, что я днями напролет смотрела на хмелеварню. Я чувствую... что хочу варить лучший хмель в долине... нет... во всей Пандарии!$b$bКакая глупая мечта, да?','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хмель новичка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты умеешь хранить секреты, $n?$B$BЯ решила попробовать себя в хмелеварении. У меня есть лишь старый перегонный куб, но он все еще в рабочем состоянии.$B$BЕсть у меня идея для необычного хмеля, но мне не хватает ингредиентов.$B$BЯ стеснительная и почти не общаюсь с жителями города, но заметила, что ты вовсю заводишь друзей.$B$BТебя не затруднит попросить у фермеров необходимые ингредиенты?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите 1 сладкий озерный арбуз у Хаоханя Грязного Когтя, 1 бархатистый персик у Джины Грязный Коготь, 1 черешню у Рыбы Тростниковой Шкуры и 1 красный редис у фермера Фуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $gпринес:принесла; их! Как здорово, $n!$b$bПриступлю к изготовлению хмеля как можно скорее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не знаю, как это взбрело мне в голову. Может, от того, что я днями напролет смотрела на хмелеварню. Я чувствую... что хочу варить лучший хмель в долине... нет... во всей Пандарии!$b$bКакая глупая мечта, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31535,'Поход за продуктами','Со всей Пандарии к нам приходят учиться кулинарному искусству. Мы очень гордимся тем, что являемся лучшими поварами, но с радостью делимся нашими знаниями. Уроки стоят очень немного, чтобы каждый желающий мог их себе позволить.$b$bИз-за этого нам часто не хватает необходимых для уроков ингредиентов. Может, ты пожертвуешь что-нибудь школе и поможешь нашим ученикам?','Принесите Намь Железной Лапе пакет с продуктами. Пакет с продуктами можно создать, используя контейнеры, которые продает торговец Чэн.','Мы очень ценим твою помощь. Некоторым нашим ученикам она необходима.','Тяжело учиться готовить, если готовить не из чего.','Отдайте пакет с продуктами Намю Железной Лапе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поход за продуктами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со всей Пандарии к нам приходят учиться кулинарному искусству. Мы очень гордимся тем, что являемся лучшими поварами, но с радостью делимся нашими знаниями. Уроки стоят очень немного, чтобы каждый желающий мог их себе позволить.$b$bИз-за этого нам часто не хватает необходимых для уроков ингредиентов. Может, ты пожертвуешь что-нибудь школе и поможешь нашим ученикам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Намь Железной Лапе пакет с продуктами. Пакет с продуктами можно создать, используя контейнеры, которые продает торговец Чэн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень ценим твою помощь. Некоторым нашим ученикам она необходима.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тяжело учиться готовить, если готовить не из чего.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте пакет с продуктами Намю Железной Лапе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31536,'Сохранить свежесть','Чтобы сохранить свежесть продуктов их нужно правильно хранить. К счастью, Торговец Чэн продает неплохие контейнеры. Очень неудобно просить о подобной услуге, но мне нужна пустая корзина для тигрятины. Можешь сходить и купить ее для меня?','Принесите Намь Железной Лапе пустую корзину для тигрятины.','Спасибо. Теперь мясо останется свежим, и мы сможем приготовить его позже.','Продукты портятся, если их неправильно хранить.','Отдайте пустую корзину для мяса тигра Намю Железной Лапе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранить свежесть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы сохранить свежесть продуктов их нужно правильно хранить. К счастью, Торговец Чэн продает неплохие контейнеры. Очень неудобно просить о подобной услуге, но мне нужна пустая корзина для тигрятины. Можешь сходить и купить ее для меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Намь Железной Лапе пустую корзину для тигрятины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. Теперь мясо останется свежим, и мы сможем приготовить его позже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Продукты портятся, если их неправильно хранить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте пустую корзину для мяса тигра Намю Железной Лапе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31537,'Проба хмеля Эллы','Что ж, я наконец закончила приготовление хмеля, но не смогу узнать хороший ли он, если никто его не попробует.$B$BПожалуйста, возьми мой хмель, угости жителей Полугорья и расскажи, что они думают о нем?$B$BЯ... Я не могу попросить их сама.','Узнайте у Йогу Пьяного, Бобо Железной Лапы, фермера Юна и Наны Грязный Коготь, что они думают о хмеле Эллы.','Правда? Они прямо так и сказали? Ну надо же!','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проба хмеля Эллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, я наконец закончила приготовление хмеля, но не смогу узнать хороший ли он, если никто его не попробует.$B$BПожалуйста, возьми мой хмель, угости жителей Полугорья и расскажи, что они думают о нем?$B$BЯ... Я не могу попросить их сама.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте у Йогу Пьяного, Бобо Железной Лапы, фермера Юна и Наны Грязный Коготь, что они думают о хмеле Эллы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Правда? Они прямо так и сказали? Ну надо же!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31538,'Отличный хмель','Нужно дать продегустировать мой хмель еще кое-кому.$B$BОн путешествовал по всему свету и всегда пробовал лучшие местные напитки.$B$BСейчас он в городе, и мне интересно, что он скажет о моем хмеле.','Попросите Чэня Буйного Портера попробовать хмель Эллы.','Ты же не подшучиваешь надо мной, $n? Что ж, если он так сказал... Значит... Видимо, я все же умею варить хмель!$b$bСпасибо тебе, $n. Ты $gпомог:помогла; мне обрести уверенность в своих силах.','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отличный хмель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно дать продегустировать мой хмель еще кое-кому.$B$BОн путешествовал по всему свету и всегда пробовал лучшие местные напитки.$B$BСейчас он в городе, и мне интересно, что он скажет о моем хмеле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите Чэня Буйного Портера попробовать хмель Эллы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты же не подшучиваешь надо мной, $n? Что ж, если он так сказал... Значит... Видимо, я все же умею варить хмель!$b$bСпасибо тебе, $n. Ты $gпомог:помогла; мне обрести уверенность в своих силах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элле в дом Эллы или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31548,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить твои навыки!$b$bОтправляйся в долину и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Грейди Баннсону в Каранос и сообщите ему о своей победе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить твои навыки!$b$bОтправляйся в долину и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейди Баннсону в Каранос и сообщите ему о своей победе!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31549,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Шелби Щебенке, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрителем стойл Шелби Щебенкой.','Вернитесь к Грейди Баннсону в Каранос.','Шелби Щебенка, местный смотритель стойл, может исцелять и оживлять ваших питомцев.','Шелби Щебенка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Шелби Щебенке, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрителем стойл Шелби Щебенкой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейди Баннсону в Каранос.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Шелби Щебенка, местный смотритель стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шелби Щебенка',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31550,'Отлов питомца','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.','Поймайте боевого питомца.','Вернитесь к Маркусу Йенсену и покажите ему, кого вы поймали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов питомца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте боевого питомца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маркусу Йенсену и покажите ему, кого вы поймали!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31551,'Отлов питомца','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.','Поймайте боевого питомца.','Вернитесь к Грейди Баннсону в Каранос и покажите ему, кого вы поймали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов питомца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте боевого питомца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грейди Баннсону в Каранос и покажите ему, кого вы поймали!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31552,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Валине в Доланаар и сообщите ей о своей победе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валине в Доланаар и сообщите ей о своей победе!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31553,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сериадне, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сериадной.','Вернитесь к Валине в Доланаар.','Сериадна, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.','Сериадна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сериадне, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сериадной.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валине в Доланаар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сериадна, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сериадна',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31554,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сериадне, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сериадной.','Вернитесь к Сериадне в Доланаар.','Сериадна, местная смотрительница стойл, может исцелять и оживлять питомцев.','Сериадна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сериадне, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сериадной.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сериадне в Доланаар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сериадна, местная смотрительница стойл, может исцелять и оживлять питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сериадна',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31555,'Отлов питомца','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.','Поймайте боевого питомца.','Вернитесь к Валине в Доланаар и покажите ей, кого вы поймали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов питомца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте боевого питомца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валине в Доланаар и покажите ей, кого вы поймали!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31556,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся на поиски боевых питомцев в округе и вступи в схватку с любым из них. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Лейне на Лазурную заставу и сообщите ей о своей победе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся на поиски боевых питомцев в округе и вступи в схватку с любым из них. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейне на Лазурную заставу и сообщите ей о своей победе!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31568,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Эсбине, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Эсбиной.','Вернитесь к Лейне на Лазурную заставу.','Эсбина, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.','Эсбина') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Эсбине, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Эсбиной.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейне на Лазурную заставу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Эсбина, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Эсбина',`questgivertargetname_loc8`);
