INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31573,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Налин в деревню Кровавого Копыта и сообщите ей о своей победе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налин в деревню Кровавого Копыта и сообщите ей о своей победе!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31574,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сейкве, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сейквой.','Вернитесь к Налин в деревню Кровавого Копыта.','Сейква, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.','Сейква') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Сейкве, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрительницей стойл Сейквой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налин в деревню Кровавого Копыта.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сейква, местная смотрительница стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Сейква',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31575,'Отлов питомца','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.','Поймайте боевого питомца.','Вернитесь к Налин в деревню Кровавого Копыта и покажите ей, кого вы поймали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов питомца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично справляешься, $n. Скоро ты и $gсам:сама; не заметишь, как станешь мастером в обращении с питомцами. А теперь пришла пора поймать собственного питомца!$b$bОтправляйся на поиски за город и найди там боевого питомца. Затем вступи с ним в бой, а когда у него останется мало здоровья, брось ловушку.$b$bНе забудь, что твой питомец должен быть минимум 3-го уровня, иначе ловушку нельзя будет использовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте боевого питомца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налин в деревню Кровавого Копыта и покажите ей, кого вы поймали!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31576,'Изучение основ','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!','Победите в битве питомцев.','Вернитесь к Анселю Финкепу в Брилл и сообщите ему о своей победе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение основ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты умеешь обучать питомцев, пора бы проверить навыки!$b$bОтправляйся в лес и вступи там в схватку с боевым питомцем. Когда одержишь победу, возвращайся ко мне, и я продолжу обучать тебя. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анселю Финкепу в Брилл и сообщите ему о своей победе!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31577,'На поправку','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Морганусу, чтобы вылечить и оживить питомцев.','Излечите своих питомцев полностью, поговорив со смотрителем стойл Морганусом.','Вернитесь к Анселю Финкепу в Брилл.','Морганус, местный смотритель стойл, может исцелять и оживлять ваших питомцев.','Морганус') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поправку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда бой выигран, надо подлечить питомцев, чтобы они могли сражаться и дальше! Следует обратиться к смотрителю стойл Морганусу, чтобы вылечить и оживить питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Излечите своих питомцев полностью, поговорив со смотрителем стойл Морганусом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анселю Финкепу в Брилл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Морганус, местный смотритель стойл, может исцелять и оживлять ваших питомцев.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Морганус',`questgivertargetname_loc8`);
