INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31598,'Ядро Кипа\'рака','Любопытно. С твоей стороны, Пробудитель, было мудро заметить всю важность происходящего. Натуральный кипарит для нас очень ценен.$B$BВот твоя награда. Все по справедливости.','Принесите большое кипаритовое ядро кователю янтаря Зикку в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядро Кипа\'рака',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любопытно. С твоей стороны, Пробудитель, было мудро заметить всю важность происходящего. Натуральный кипарит для нас очень ценен.$B$BВот твоя награда. Все по справедливости.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите большое кипаритовое ядро кователю янтаря Зикку в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31599,'Мощные жвала матриарха','Я узнаю эти жвала. Знаешь, Каранош ведь съела моего брата.$B$BХотя, конечно, у меня братьев – миллионы.$B$B<Зикк усмехается.>','Принесите огромные жвала куньчуна кователю янтаря Зикку в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощные жвала матриарха',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я узнаю эти жвала. Знаешь, Каранош ведь съела моего брата.$B$BХотя, конечно, у меня братьев – миллионы.$B$B<Зикк усмехается.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите огромные жвала куньчуна кователю янтаря Зикку в Клакси\'весс.',`completedtext_loc8`);
