INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (31604,'Атака на Зан\'весс','Поселение на острове Зан\'весс – последняя надежда на будущее для моего народа. Несмотря на то, что богомолы острова верны Шек\'зир, деревья кипари на нем не подверглись тлетворному влиянию ша.$B$BНо, исполняя имперский приказ, Зан\'тики забирают у них смолу в чудовищных количествах.$B$BТы $gдоказал:доказала;, что на тебя можно положиться. Совет хочет, чтобы ты $gвозглавил:возглавила; нападение на остров. Твоя задача: остановить богомолов и уберечь кипари.$B$BПоговори со мной, когда будешь $gготов:готова;.','Возглавьте нападение на Зан\'весс. Чтобы начать, поговорите с Клакси\'ва Вор или воспользуйтесь системой поиска подземелий.','Вернитесь к клакси\'ва Вор в Клакси\'весс.','Клакси\'ва Вор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на Зан\'весс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поселение на острове Зан\'весс – последняя надежда на будущее для моего народа. Несмотря на то, что богомолы острова верны Шек\'зир, деревья кипари на нем не подверглись тлетворному влиянию ша.$B$BНо, исполняя имперский приказ, Зан\'тики забирают у них смолу в чудовищных количествах.$B$BТы $gдоказал:доказала;, что на тебя можно положиться. Совет хочет, чтобы ты $gвозглавил:возглавила; нападение на остров. Твоя задача: остановить богомолов и уберечь кипари.$B$BПоговори со мной, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возглавьте нападение на Зан\'весс. Чтобы начать, поговорите с Клакси\'ва Вор или воспользуйтесь системой поиска подземелий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к клакси\'ва Вор в Клакси\'весс.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Клакси\'ва Вор',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31605,'Раскопки Зан\'тиков','<Судя по внешнему виду, богомол только недавно выбрался из своего саркофага. Он откашливается.>Раз… ре… за… тель пробудился.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскопки Зан\'тиков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Судя по внешнему виду, богомол только недавно выбрался из своего саркофага. Он откашливается.>Раз… ре… за… тель пробудился.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31606,'Пробуждение Рик\'кала','Ты... не похож на них...$B$BЯ слышу зов клакси... <кашляет>$B$BДай мне прийти в себя.','Сдерживайте зан\'тиков, пока Рик\'кал не придет в себя.','Посмотрите на него! Столько всяких приспособлений и частей организма для убийства. Просто поразительно.$B$BЯ когда-нибудь заберу себе твой мозг. Ха-ха-ха.','Поговорите с Рик\'калом Разрезателем в Зан\'весс или Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение Рик\'кала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты... не похож на них...$B$BЯ слышу зов клакси... <кашляет>$B$BДай мне прийти в себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сдерживайте зан\'тиков, пока Рик\'кал не придет в себя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрите на него! Столько всяких приспособлений и частей организма для убийства. Просто поразительно.$B$BЯ когда-нибудь заберу себе твой мозг. Ха-ха-ха.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рик\'калом Разрезателем в Зан\'весс или Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31607,'Выслеживание: задания "Недобрые духи" и "Мы во власти ненависти"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: задания "Недобрые духи" и "Мы во власти ненависти"',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31609,'Гнев Шек\'зир','Остальные освобожденные Идеалы рассеяны по всему Сердцу Страха. Они сражаются с роем богомолов, и им может понадобится твоя помощь!','Разбейте рой богомолов, уничтожив Акколона, Шокс\'тика, Проявление ужаса и 25 богомолов-прислужников.','Пока что осада прервана.','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев Шек\'зир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остальные освобожденные Идеалы рассеяны по всему Сердцу Страха. Они сражаются с роем богомолов, и им может понадобится твоя помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбейте рой богомолов, уничтожив Акколона, Шокс\'тика, Проявление ужаса и 25 богомолов-прислужников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пока что осада прервана.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31611,'Куньлайский сногсшибатель','Защитите фестиваль Хмельнолуния.','Похоже, я плохо представлял, насколько опасно в наши дни ремесло хмелевара.','Поговорите с хмелеваром Буфом на фестивале Хмельнолуния или в деревне Бинан, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куньлайский сногсшибатель',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите фестиваль Хмельнолуния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, я плохо представлял, насколько опасно в наши дни ремесло хмелевара.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хмелеваром Буфом на фестивале Хмельнолуния или в деревне Бинан, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31612,'Тень империи','Пока что ты $gсумел:сумела; понять лишь часть законов, по которым живет наш орден. Ты – $gчужестранец:чужестранка;, и к тебе относились соответствующим образом.$b$bНо мы не можем и дальше иметь от тебя секреты. Есть кое-что, что ты $gдолжен:должна; увидеть.','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень империи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока что ты $gсумел:сумела; понять лишь часть законов, по которым живет наш орден. Ты – $gчужестранец:чужестранка;, и к тебе относились соответствующим образом.$b$bНо мы не можем и дальше иметь от тебя секреты. Есть кое-что, что ты $gдолжен:должна; увидеть.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кил\'руком Рассекающим Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31613,'Отвар Зеленой Скалы','Я сейчас готовлю свой знаменитый отвар Зеленой Скалы.$b$bОн пригодится нам в борьбе с негодяями и всякими злодеями, которых сейчас полно в шахтах.$b$bВот что я скажу – может, соберешь друзей да и приведешь их сюда, чтобы попробовали мой напиток?$b$bПервая кружка – за счет заведения!','Помогите защитить деревню Зеленой Скалы.','Поговорите с хмелеваром Тцзу в деревне Зеленой Скалы, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвар Зеленой Скалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сейчас готовлю свой знаменитый отвар Зеленой Скалы.$b$bОн пригодится нам в борьбе с негодяями и всякими злодеями, которых сейчас полно в шахтах.$b$bВот что я скажу – может, соберешь друзей да и приведешь их сюда, чтобы попробовали мой напиток?$b$bПервая кружка – за счет заведения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите защитить деревню Зеленой Скалы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хмелеваром Тцзу в деревне Зеленой Скалы, что в Нефритовом лесу.',`completedtext_loc8`);
