INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31656,'Угроза на юге','Поговорите с лучницей Ли на Змеином Хребте.','Доброволец на службу в Жутких пустошах? Это что-то новое!$B$BПриятно познакомиться.','Поговорите с лучницей Ли на Змеином хребте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза на юге',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лучницей Ли на Змеином Хребте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Доброволец на службу в Жутких пустошах? Это что-то новое!$B$BПриятно познакомиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лучницей Ли на Змеином хребте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31660,'Обуза для роя','У только что появившихся на свет богомолов есть только два инстинкта: есть и убивать. Они нападают на сородичей, пожирая слабых и оставляя в живых сильнейших.$B$BВсе меняется, когда приходит время роя: роерожденные нападают лишь на врагов.$B$BНо роерожденные из Владений Шек\'зир осквернены. Они появляются на свет в тенях и кошмарах, их ведет не голод, а ужас.$B$BОни обуза для роя, и они должны быть уничтожены.','Убейте 30 роерожденных во Владениях Шек\'зир.','Их яйца должны были греться в солнечных лучах и слушать песни мириадов крыльев еще десять лет.$B$BИмператрица заплатит за свои преступления.','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обуза для роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У только что появившихся на свет богомолов есть только два инстинкта: есть и убивать. Они нападают на сородичей, пожирая слабых и оставляя в живых сильнейших.$B$BВсе меняется, когда приходит время роя: роерожденные нападают лишь на врагов.$B$BНо роерожденные из Владений Шек\'зир осквернены. Они появляются на свет в тенях и кошмарах, их ведет не голод, а ужас.$B$BОни обуза для роя, и они должны быть уничтожены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 роерожденных во Владениях Шек\'зир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Их яйца должны были греться в солнечных лучах и слушать песни мириадов крыльев еще десять лет.$B$BИмператрица заплатит за свои преступления.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31661,'Источник чудовищной силы','Покажите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.','Ты хоть знаешь, что это такое? Это же янтарь!$B$BНо он заражен страхом.$B$BЧужеземец вроде тебя вряд ли поймет, что это значит.','Принесите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник чудовищной силы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хоть знаешь, что это такое? Это же янтарь!$B$BНо он заражен страхом.$B$BЧужеземец вроде тебя вряд ли поймет, что это значит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите тронутый ша кристалл кователю янтаря Зикку в Клакси\'весс.',`completedtext_loc8`);
