INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31668,'Ambush Event Tracking') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ambush Event Tracking',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31669,'Капустное испытание','Мой дедушка всегда говорил, что о фермере можно судить по его капусте. Всякий раз, когда в городе появялся новый фермер, дедушка покупал у того пару кочанов, чтобы понять, что тот из себя представляет.$b$bТеперь я сам стал фермером, и мне представился шанс показать себя. Не $gмог:могла; бы ты посадить для меня немного капусты?','Погоди, пусть они только попробуют эту капусту! Тогда-то они все поймут.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капустное испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой дедушка всегда говорил, что о фермере можно судить по его капусте. Всякий раз, когда в городе появялся новый фермер, дедушка покупал у того пару кочанов, чтобы понять, что тот из себя представляет.$b$bТеперь я сам стал фермером, и мне представился шанс показать себя. Не $gмог:могла; бы ты посадить для меня немного капусты?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Погоди, пусть они только попробуют эту капусту! Тогда-то они все поймут.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31670,'Эта притягательная морковь','Мой дедушка всегда говорил: "От моркови нет никакой пользы, она лишь приманивает гну-синей". Кажется, за свою жизнь он не вырастил ни одной морковки.$b$bНо в этом я с ним не соглашусь. Я рисковать люблю. И к тому же я люблю морковь.$b$bМожет, раздобудешь семена и вырастишь для меня морковь?','Не могу дождаться, когда эта морковь вырастет. Спасибо тебе, Волчарен. Завтра снова увидимся?','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эта притягательная морковь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой дедушка всегда говорил: "От моркови нет никакой пользы, она лишь приманивает гну-синей". Кажется, за свою жизнь он не вырастил ни одной морковки.$b$bНо в этом я с ним не соглашусь. Я рисковать люблю. И к тому же я люблю морковь.$b$bМожет, раздобудешь семена и вырастишь для меня морковь?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не могу дождаться, когда эта морковь вырастет. Спасибо тебе, Волчарен. Завтра снова увидимся?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31671,'Почему бы и не лук-шалот?','Я слышал, что Хаохань собирался сажать лук-шалот сегодня. Не уверен, что сегодня самый подходящий для этого день, но, надеюсь, он знает, что делает. В конце концов, это же он глава союза земледельцев.$b$bНе посадишь для меня лук-шалот?','Мне кажется, я уже чувствую аромат лука-шалота. Не могу дождаться, когда он вырастет, чтобы завтра продать его. Спасибо!','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почему бы и не лук-шалот?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что Хаохань собирался сажать лук-шалот сегодня. Не уверен, что сегодня самый подходящий для этого день, но, надеюсь, он знает, что делает. В конце концов, это же он глава союза земледельцев.$b$bНе посадишь для меня лук-шалот?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне кажется, я уже чувствую аромат лука-шалота. Не могу дождаться, когда он вырастет, чтобы завтра продать его. Спасибо!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31672,'Тыквенный аромат','На рынке поговаривают, что Джине Грязный Коготь нравится аромат цветков тыквы. Может быть, если на моей ферме будут расти тыквы, то она будет почаще сюда захаживать?$b$bНе посадишь для меня тыкву?','Посадите тыкву могу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.','А теперь перейдем к выжидательной тактике…$B$BПрости, это как-то грозно прозвучало. Забудь, что я это сказал.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквенный аромат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На рынке поговаривают, что Джине Грязный Коготь нравится аромат цветков тыквы. Может быть, если на моей ферме будут расти тыквы, то она будет почаще сюда захаживать?$b$bНе посадишь для меня тыкву?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите тыкву могу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А теперь перейдем к выжидательной тактике…$B$BПрости, это как-то грозно прозвучало. Забудь, что я это сказал.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31673,'Красный лук-порей – лучшее средство против кроколисков','Дедушка всегда говорил мне, что запах красного лука-порея отпугивает кроколисков. Наверное, он был прав... Он всегда выращивал лук-порей, и я никогда не видел ни одного кроколиска вблизи его фермы.$b$bВообще-то водоемов тут поблизости нет... но лучше лишний раз подстраховаться.','Хотел бы я посмотреть на тех кроколисков, которые отважатся напасть на мою ферму!$B$BХа-ха-ха!','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красный лук-порей – лучшее средство против кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дедушка всегда говорил мне, что запах красного лука-порея отпугивает кроколисков. Наверное, он был прав... Он всегда выращивал лук-порей, и я никогда не видел ни одного кроколиска вблизи его фермы.$b$bВообще-то водоемов тут поблизости нет... но лучше лишний раз подстраховаться.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотел бы я посмотреть на тех кроколисков, которые отважатся напасть на мою ферму!$B$BХа-ха-ха!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31674,'Розовая репа: вызов брошен','Старик Горная Лапа был готов поспорить, что на моей земле невозможно вырастить розовую репу.$b$bЯ ему докажу, что он не прав. У меня будут расти самые большие, самые розовые репки, из всех, какие только видел этот простофиля!','Посадите розовую репу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.','Ха! Вот теперь-то он увидит.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Розовая репа: вызов брошен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старик Горная Лапа был готов поспорить, что на моей земле невозможно вырастить розовую репу.$b$bЯ ему докажу, что он не прав. У меня будут расти самые большие, самые розовые репки, из всех, какие только видел этот простофиля!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите розовую репу на ферме Солнечной Песни. Семена можно приобрести у торговца Зеленое Поле на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Вот теперь-то он увидит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31675,'Лечение белой репой','Ты только посмотри на эти грядки. Они просто сияют.$B$BДедушка бы гордился тобой.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лечение белой репой',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты только посмотри на эти грядки. Они просто сияют.$B$BДедушка бы гордился тобой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31676,'Месть древних','До меня доносятся яростные вопли духов гуртанских могу, которых я сразил давным-давно. Они шныряют по развалинам террасы в поисках мщения.$B$BМне не хватит сил дать им отпор, если они найдут меня в таком состоянии. Отвлеки их и разделайся с ними.$B$BЗакончи начатое, и я открою тебе, кто я такой.','Убейте 6 мстительных гуртанских духов на Террасе Гуртан.','Могу – наши общие враги. Возможно, не единственные.$B$BЕще увидим.','Возвратитесь на Террасу Гуртан к Кил\'руку Рассекающему Ветер.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня доносятся яростные вопли духов гуртанских могу, которых я сразил давным-давно. Они шныряют по развалинам террасы в поисках мщения.$B$BМне не хватит сил дать им отпор, если они найдут меня в таком состоянии. Отвлеки их и разделайся с ними.$B$BЗакончи начатое, и я открою тебе, кто я такой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 мстительных гуртанских духов на Террасе Гуртан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могу – наши общие враги. Возможно, не единственные.$B$BЕще увидим.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Возвратитесь на Террасу Гуртан к Кил\'руку Рассекающему Ветер.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31677,'Прах вождя','<Многие столетия назад Кил\'рук Рассекающий Ветер одолел вождя Гуртана, но дух повелителя зверей из рода могу до сих пор витает над руинами древней крепости.$B$BПобеда над этим духом может помочь вам заслужить благосклонность клакси.>','Принесите прах вождя клана Гуртан Кил\'руку Рассекающему Ветер в Клакси\'весс.','Гуртан был трусом, который дрессировал чудовищ, чтобы они сражались за него в бою. Испугавшись смерти, он решил запечатать свой дух в урне.$B$BТеперь мы сможем уничтожить его столько раз, сколько захотим.$B$BТы славно поработал!','Принесите прах вождя Гуртана Кил\'руку Рассекающему Ветер в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Многие столетия назад Кил\'рук Рассекающий Ветер одолел вождя Гуртана, но дух повелителя зверей из рода могу до сих пор витает над руинами древней крепости.$B$BПобеда над этим духом может помочь вам заслужить благосклонность клакси.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите прах вождя клана Гуртан Кил\'руку Рассекающему Ветер в Клакси\'весс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гуртан был трусом, который дрессировал чудовищ, чтобы они сражались за него в бою. Испугавшись смерти, он решил запечатать свой дух в урне.$B$BТеперь мы сможем уничтожить его столько раз, сколько захотим.$B$BТы славно поработал!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите прах вождя Гуртана Кил\'руку Рассекающему Ветер в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31679,'Усиление сигнала','Клакси\'ва стало известно еще об одном Идеале. Его голос слаб и глух, а значит, сигнал надо усилить!$b$bВ Янтарном зале есть башня-сонар, которая затихла очень давно. Ее песнь должна прозвучать вновь. Так приказали клакси!$b$bВ этот раз я пойду с тобой. Ты поможешь мне ее починить.$b$bВозьми резонирующий кристалл и найди меня там.','Активировать резонирующий маячок в Янтарной впадине.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усиление сигнала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси\'ва стало известно еще об одном Идеале. Его голос слаб и глух, а значит, сигнал надо усилить!$b$bВ Янтарном зале есть башня-сонар, которая затихла очень давно. Ее песнь должна прозвучать вновь. Так приказали клакси!$b$bВ этот раз я пойду с тобой. Ты поможешь мне ее починить.$b$bВозьми резонирующий кристалл и найди меня там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активировать резонирующий маячок в Янтарной впадине.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31680,'Преступление и наказание','Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.','Убейте 8 ик\'тиков-жнецов на Жгучей тропе.','Клакси очень довольны твоей работой $gчужестранец:чужестранка;. Мы и не думали, что ты будешь нам столь $gполезен:полезна;.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преступление и наказание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вдоль Жгучей тропы растет много молодых деревьев кипари, но императрица приказала собирать янтарь и с этих саженцев... слишком рано! Так нельзя, $gчужестранец:чужестранка;!$b$bКлакси\'ва требуют, чтобы злодеи понесли заслуженное наказание! Доставь им радость и уничтожь ик\'тиков-жнецов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 ик\'тиков-жнецов на Жгучей тропе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клакси очень довольны твоей работой $gчужестранец:чужестранка;. Мы и не думали, что ты будешь нам столь $gполезен:полезна;.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31681,'Чем старше, тем лучше','Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.','Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.','Поговорите с Кор\'иком в Янтарном зале.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем старше, тем лучше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Собирать янтарь с саженцев – преступление, но еще большее преступление – позволить ему бесцельно пропасть.$b$bМолодой янтарь не так полезен, но клакси он все равно пригодится. Принесем им побольше янтаря, и они восславят меня!$b$bСобери молодой янтарь, мы поместим его в хранилище, выдержим его там, и он будет пригоден для еды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 кувшинов с янтарем с накопителей янтаря на Жгучей тропе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кор\'иком в Янтарном зале.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31682,'Уже не у моря','Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.','Поднесите камертон клакси к океаническим камням и пробудите Идеал.','Поговорите с Каз\'тиком Манипулятором.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уже не у моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси\'ва говорили со мной, $gчужестранец:чужестранка;. Идеал был спрятан на Соленой отмели, но нам все же удалось его отыскать.$b$bЕго окружают люди-ящеры, и мы не можем позволить им и пальцем его тронуть!$b$bНайди его и пробуди. Без Идеала можешь не возвращаться!$b$bЕсли справишься со своей задачей, то клакси будут нам весьма признательны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поднесите камертон клакси к океаническим камням и пробудите Идеал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31685,'Долина Четырех Ветров') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долина Четырех Ветров',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31687,'Проредить сик\'тиков','Убейте 12 богомолов cик\'тиков.','Богомолы жестоки. Но, к счастью для нас, в тебе целеустремленности еще больше, чем в них.$B$BХорошо, что ты оказался в этих местах.','Вернитесь к Жэнь-саю Дубовой Шкуре в дозорный пункт Жэнь-сая, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проредить сик\'тиков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 богомолов cик\'тиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Богомолы жестоки. Но, к счастью для нас, в тебе целеустремленности еще больше, чем в них.$B$BХорошо, что ты оказался в этих местах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэнь-саю Дубовой Шкуре в дозорный пункт Жэнь-сая, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31688,'Поиски Беспокойного Лэна','Один из моих лучших разведчиков, Беспокойный Лэн, пропал без вести во время нашей операции на той стороне Сик\'весса. Надеюсь, он попал в плен, а не был убит, но поскольку богомолы находятся под воздействием ша, ничего нельзя утверждать наверняка.$b$bМожешь ли ты проверить клетки вокруг Сик\'весса? Я просто обязан искать его как можно лучше, но нас так мало, а нам нужно держать оборону на юге.$b$bПожалуйста, |3-6($c), даже если он уже мертв, найди его. Я должен знать, что с ним случилось.','Обыщите клетки сик\'тиков и попытайтесь найти Беспокойного Лэна.','Лэн говорил мне о твоей храбрости. Он у тебя в долгу. Так же, как и я.','Вернитесь к Жэнь-саю Дубовой Шкуре в дозорный пункт Жэнь-сая, что в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Беспокойного Лэна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из моих лучших разведчиков, Беспокойный Лэн, пропал без вести во время нашей операции на той стороне Сик\'весса. Надеюсь, он попал в плен, а не был убит, но поскольку богомолы находятся под воздействием ша, ничего нельзя утверждать наверняка.$b$bМожешь ли ты проверить клетки вокруг Сик\'весса? Я просто обязан искать его как можно лучше, но нас так мало, а нам нужно держать оборону на юге.$b$bПожалуйста, |3-6($c), даже если он уже мертв, найди его. Я должен знать, что с ним случилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите клетки сик\'тиков и попытайтесь найти Беспокойного Лэна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лэн говорил мне о твоей храбрости. Он у тебя в долгу. Так же, как и я.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Жэнь-саю Дубовой Шкуре в дозорный пункт Жэнь-сая, что в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31689,'Воины ужаса','Клакси многое знают и многое понимают. Они поделились со мной своей мудростью.$B$BВор\'тики впустили в себя ша, чтобы с новообретенной силой повелевать своим ложным роем. Их воины поглощают оскверненный янтарь и называют себя воинами ужаса.$B$BТакие, как они, не должны существовать. Они – грязь, которую надо стереть с лица земли.$B$BИ ты положишь начало их падению, когда прибудешь в Кипари Вор.','Убейте 6 вор\'тиков – воинов ужаса в Кипари Вор.','Копье – могучее оружие в умелых руках. Только слабак станет зачаровывать его магией.$B$BА слабаки нам не нужны.','Вернитесь к Малику Невредимому в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воины ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клакси многое знают и многое понимают. Они поделились со мной своей мудростью.$B$BВор\'тики впустили в себя ша, чтобы с новообретенной силой повелевать своим ложным роем. Их воины поглощают оскверненный янтарь и называют себя воинами ужаса.$B$BТакие, как они, не должны существовать. Они – грязь, которую надо стереть с лица земли.$B$BИ ты положишь начало их падению, когда прибудешь в Кипари Вор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 вор\'тиков – воинов ужаса в Кипари Вор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Копье – могучее оружие в умелых руках. Только слабак станет зачаровывать его магией.$B$BА слабаки нам не нужны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малику Невредимому в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31690,'Покрытый письменами тигриный посох','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.','Принесите ваш покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу в Дендрарий.','Отдайте покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами тигриный посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ваш покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу в Дендрарий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте покрытый письменами тигриный посох мастеру каллиграфии Глень-цзу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31691,'Покрытый письменами журавлиный посох','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.','Принесите ваш покрытый письменами журавлиный посох мастеру каллиграфии Цзо По в Дендрарий.','Отдайте покрытый письменами журавлиный посох мастеру каллиграфии Цзо По.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами журавлиный посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ваш покрытый письменами журавлиный посох мастеру каллиграфии Цзо По в Дендрарий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте покрытый письменами журавлиный посох мастеру каллиграфии Цзо По.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31692,'Покрытый письменами змеиный посох','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.','Принесите ваш покрытый письменами змеиный посох мастеру каллиграфии Вэю в Дендрарий.','Отдайте покрытый письменами змеиный посох мастеру каллиграфии Вэю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами змеиный посох',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот посох очень мощный, но вы понимаете, что рано или поздно "перерастете" его. Когда это случится, один из мастеров каллиграфии в Дендрарии скорее всего с удовольствием примет его в дар от вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ваш покрытый письменами змеиный посох мастеру каллиграфии Вэю в Дендрарий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отдайте покрытый письменами змеиный посох мастеру каллиграфии Вэю.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31693,'Джулия Стивенс','Думаешь, что сможешь снова меня одолеть?','Победите Джулию Стивенс в битве питомцев.','Да, ты действительно хороший наставник питомцев. Так что твой случай – исключение.','Поговорите с Джулией Стивенс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джулия Стивенс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, что сможешь снова меня одолеть?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Джулию Стивенс в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ты действительно хороший наставник питомцев. Так что твой случай – исключение.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джулией Стивенс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31694,'Хисинген Блюз','test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl\r\n\r\n*DO NOT LOCALIZE*','test log desc ! $1oa $1oo $1oo $1oa test cona $oo fodasse $o1x caracois $o1 crl\r\n\r\n*DO NOT LOCALIZE*','test comp text! $1oa $1oo $1oo $1oa test cona $oo fodasse $o1x caracois $o1 crl\r\n\r\n*DO NOT LOCALIZE*') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хисинген Блюз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl\r\n\r\n*DO NOT LOCALIZE*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','test log desc ! $1oa $1oo $1oo $1oa test cona $oo fodasse $o1x caracois $o1 crl\r\n\r\n*DO NOT LOCALIZE*',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','test comp text! $1oa $1oo $1oo $1oa test cona $oo fodasse $o1x caracois $o1 crl\r\n\r\n*DO NOT LOCALIZE*',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (31695,'По ту сторону стены','Добро пожаловать в Танлунские степи. Если ты решительно настаиваешь на том, чтобы исследовать самые темные уголки Пандарии, то глупо было бы с моей стороны не воспользоваться твоей помощью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По ту сторону стены',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Танлунские степи. Если ты решительно настаиваешь на том, чтобы исследовать самые темные уголки Пандарии, то глупо было бы с моей стороны не воспользоваться твоей помощью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31697,'ACCIDENTAL COPY [reuse if you like]','С тех пор, как ты $gушел:ушла; богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.','Убейте 50 нападающих богомолов с помощью орудия "дракон".','Поговорите с Таоши на Заставе Гао-Жаня в Танлунских степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ACCIDENTAL COPY [reuse if you like]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как ты $gушел:ушла; богомолов в округе стало намного больше. Давай-ка используем собранные тобой сферы.$B$BОтправляйся на заставу и бери управление одной из пушек на себя. Не пропусти ни единого врага.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 50 нападающих богомолов с помощью орудия "дракон".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таоши на Заставе Гао-Жаня в Танлунских степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31698,'Сокращение популяции','Последние несколько лет были изобильными, и, как результат, популяция диких тигров на Наветренном острове резко выросла.$b$bСвирепые звери истребили всю обитающую поблизости дичь и начинают покушаться на гнезда облачных змеев.$b$bВ итоге тигры живут себе припеваючи, а облачных змеев становится все меньше.$b$bЕсли мы ничего не предпримем, эти хищные кошки их полностью уничтожат.$b$bМы должны сократить численность тигров, |3-6($r).','Убейте 8 тигров или матерых тигров Наветренного острова.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокращение популяции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последние несколько лет были изобильными, и, как результат, популяция диких тигров на Наветренном острове резко выросла.$b$bСвирепые звери истребили всю обитающую поблизости дичь и начинают покушаться на гнезда облачных змеев.$b$bВ итоге тигры живут себе припеваючи, а облачных змеев становится все меньше.$b$bЕсли мы ничего не предпримем, эти хищные кошки их полностью уничтожат.$b$bМы должны сократить численность тигров, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 тигров или матерых тигров Наветренного острова.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31699,'Боязнь духов','Черт возьми, и как я собиралась выполнить эту работу?$B$BИнструктор Небесный Шип попросил меня убить несколько тигров на Наветренном острове, но говорят, там все просто кишит духами!$B$BФу! Ненавижу духов! У меня от них мурашки!$B$BОни такие маленькие, и... и... прыгают на тебя, и... и... у них такие холодные маленькие липкие ручонки!$B$BФу-у-у-у! Ты $gдолжен:должна; мне помочь, $n. Избавься от этих тварей, умоляю!','Убейте 7 темных духов – плутов.','Ты поставил этих духов на место, Эрезул. На какое-то время они угомонятся.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боязнь духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черт возьми, и как я собиралась выполнить эту работу?$B$BИнструктор Небесный Шип попросил меня убить несколько тигров на Наветренном острове, но говорят, там все просто кишит духами!$B$BФу! Ненавижу духов! У меня от них мурашки!$B$BОни такие маленькие, и... и... прыгают на тебя, и... и... у них такие холодные маленькие липкие ручонки!$B$BФу-у-у-у! Ты $gдолжен:должна; мне помочь, $n. Избавься от этих тварей, умоляю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 темных духов – плутов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты поставил этих духов на место, Эрезул. На какое-то время они угомонятся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31700,'Сапог не на ту ногу','Ненавижу лесных духов. Однажды один такой маленький негодник преследовал меня целый день – подмешивал мне в чай песок и подкидывал жуков в волосы.$B$BЧто это за выходки?!$B$BДумаю, пришло время отплатить им той же монетой. Знаешь, что духи Наветренного острова любят больше всего?$B$BО, да! Сапоги!$B$BВот их-то мы и украдем! Духи просто с ума сойдут! Хе-хе.$B$BЯ вообще-то боюсь подходить близко к духам, так что придется это сделать тебе, $n.','Украдите 14 пар украденных сапог.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапог не на ту ногу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ненавижу лесных духов. Однажды один такой маленький негодник преследовал меня целый день – подмешивал мне в чай песок и подкидывал жуков в волосы.$B$BЧто это за выходки?!$B$BДумаю, пришло время отплатить им той же монетой. Знаешь, что духи Наветренного острова любят больше всего?$B$BО, да! Сапоги!$B$BВот их-то мы и украдем! Духи просто с ума сойдут! Хе-хе.$B$BЯ вообще-то боюсь подходить близко к духам, так что придется это сделать тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 14 пар украденных сапог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31701,'Охотница Наветренного острова','Я узнала о том, что в лесах в северо-западной части острова бесчинствует злобный зверь – охотница Наветренного острова.$b$bОна уже убила нескольких облачных змеев и ранила не одного наездника из тех, кто пытался ее одолеть.$b$bНужно положить этому конец, пока от нее не пострадал еще кто-нибудь. Можешь заняться этим?','Убейте охотницу Наветренного острова.','Спасибо, Роуф. На тебя можно положиться.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.','Логово охотницы находится в северо-западной части Наветренного острова.','Охотница Наветренного острова') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотница Наветренного острова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я узнала о том, что в лесах в северо-западной части острова бесчинствует злобный зверь – охотница Наветренного острова.$b$bОна уже убила нескольких облачных змеев и ранила не одного наездника из тех, кто пытался ее одолеть.$b$bНужно положить этому конец, пока от нее не пострадал еще кто-нибудь. Можешь заняться этим?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте охотницу Наветренного острова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Роуф. На тебя можно положиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Логово охотницы находится в северо-западной части Наветренного острова.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Охотница Наветренного острова',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31702,'Крадучись','Мне рассказывали о большом белом звере, который бродит по лесам в северо-западной части острова, где обитают дикие облачные змеи.$b$bОхотница Наветренного острова – близкая подруга этого свирепого создания. Он уже убил нескольких матриархов облачных змеев.$b$bМы не можем допустить, чтобы по острову свободно разгуливал такой страшный хищник.$b$bОтправляйся туда и разберись с ним. И мы увидим, чего стоят твои тренировки.','Убейте саблезуба Наветренного острова.','Вижу, тебе удалось справиться со зверем. Ты далеко пойдешь.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.','Король острова.','Саблезуб Наветренного острова') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крадучись',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне рассказывали о большом белом звере, который бродит по лесам в северо-западной части острова, где обитают дикие облачные змеи.$b$bОхотница Наветренного острова – близкая подруга этого свирепого создания. Он уже убил нескольких матриархов облачных змеев.$b$bМы не можем допустить, чтобы по острову свободно разгуливал такой страшный хищник.$b$bОтправляйся туда и разберись с ним. И мы увидим, чего стоят твои тренировки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте саблезуба Наветренного острова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, тебе удалось справиться со зверем. Ты далеко пойдешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Король острова.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Саблезуб Наветренного острова',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31703,'Беспредел Сумасброда','У меня есть еще одно задание для тебя.$b$bЗлонравный Сумасброд – предводитель островных лесных духов.$b$bЕсли где-то начинаются неприятности с хмелеварением, наверняка именно он дергает за ниточки.$b$bУ нас нет времени, чтобы тратить его на надоедливых и нахальных духов. Расправься со Злонравным Сумасбродом и сделай это побыстрее.','Убейте Злонравного Сумасброда.','Туда ему и дорога! Со всем, что навалилось нас за эти дни, хоть одной головной болью будет меньше.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.','Предводитель лесных духов. Опасайся его.','Злонравный Сумасброд') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспредел Сумасброда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть еще одно задание для тебя.$b$bЗлонравный Сумасброд – предводитель островных лесных духов.$b$bЕсли где-то начинаются неприятности с хмелеварением, наверняка именно он дергает за ниточки.$b$bУ нас нет времени, чтобы тратить его на надоедливых и нахальных духов. Расправься со Злонравным Сумасбродом и сделай это побыстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Злонравного Сумасброда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Туда ему и дорога! Со всем, что навалилось нас за эти дни, хоть одной головной болью будет меньше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предводитель лесных духов. Опасайся его.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Злонравный Сумасброд',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31704,'Большая уборка','<Детеныш облачного змея ловит ваш взгляд и стыдливо наклоняет голову.>$b$bКажется, кое-кто не сдержался, и с ним произошла небольшая "неприятность".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было случиться... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.','Соберите 5 мешочков экскрементов.','Детеныш облачного змея удовлетворенно играет, не обращая на вас внимания. Да… порой вам кажется, что быть укротителем змеев – неблагодарная работа.','<Детеныш облачного змея смотрит на вас невинными глазами.>','Вернитесь к детенышу облачного змея в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая уборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Детеныш облачного змея ловит ваш взгляд и стыдливо наклоняет голову.>$b$bКажется, кое-кто не сдержался, и с ним произошла небольшая "неприятность".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было случиться... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 мешочков экскрементов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детеныш облачного змея удовлетворенно играет, не обращая на вас внимания. Да… порой вам кажется, что быть укротителем змеев – неблагодарная работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Детеныш облачного змея смотрит на вас невинными глазами.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к детенышу облачного змея в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31705,'Не ужаль меня','Дендрарий – это наш дом. Тихая гавань, где мы растим детенышей змеев и обучаем наших учеников.$b$bК сожалению, есть и другие, куда более опасные существа, которые хотят здесь поселиться.$b$bК северу отсюда, за рекой, мы видели огромного шершня, который пил нектар цветов.$b$bЭта тварь уже ужалила четырех наших учеников.$b$bВозьми этот мед и воспользуйся им как приманкой, чтобы выманить шершня из укрытия. Затем убей его, чтобы он больше не причинил никому вреда.','Воспользуйтесь медом на поляне в северной части Дендрария, а затем убейте садового острожала.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не ужаль меня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дендрарий – это наш дом. Тихая гавань, где мы растим детенышей змеев и обучаем наших учеников.$b$bК сожалению, есть и другие, куда более опасные существа, которые хотят здесь поселиться.$b$bК северу отсюда, за рекой, мы видели огромного шершня, который пил нектар цветов.$b$bЭта тварь уже ужалила четырех наших учеников.$b$bВозьми этот мед и воспользуйся им как приманкой, чтобы выманить шершня из укрытия. Затем убей его, чтобы он больше не причинил никому вреда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь медом на поляне в северной части Дендрария, а затем убейте садового острожала.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31706,'Рыдающие вдовы','Пауки, обитающие вблизи деревни Шри-Ла, стали очень агрессивными. Они представляют собой серьезную опасность для рыболовов, которые удят рыбу на берегу.$b$bРади их безопасности я прошу тебя отправиться туда и убить рыдающих вдов в Плаче Вдовы.$b$bТы найдешь пещеру, если пойдешь вдоль берега в северном направлении.','Убейте 7 рыдающих вдов.','Инструктор Небесный Шип сообщил мне о ситуации в Плаче Вдовы. Ты отлично справился.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыдающие вдовы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пауки, обитающие вблизи деревни Шри-Ла, стали очень агрессивными. Они представляют собой серьезную опасность для рыболовов, которые удят рыбу на берегу.$b$bРади их безопасности я прошу тебя отправиться туда и убить рыдающих вдов в Плаче Вдовы.$b$bТы найдешь пещеру, если пойдешь вдоль берега в северном направлении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 рыдающих вдов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Инструктор Небесный Шип сообщил мне о ситуации в Плаче Вдовы. Ты отлично справился.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31707,'Спутанная паутина','Мы получаем тревожные сообщения от рыболовов из деревни Шри-Ла, $n.$b$bНа жителей деревни нападают пауки, которые обитают в Плаче Вдовы – прибрежной пещере, расположенной к северу отсюда.$b$bПауки тащат своих жертв вглубь пещеры, опутывают их коконами из паутины и оставляют до своего следующего обеда.$b$bМы надеемся, что некоторые из них все еще живы и мы можем спасти их! Отправляйся туда и освободи всех, кого сможешь найти.','Разорвите паутину вдовы и освободите 5 жителей деревни Шри-Ла.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спутанная паутина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы получаем тревожные сообщения от рыболовов из деревни Шри-Ла, $n.$b$bНа жителей деревни нападают пауки, которые обитают в Плаче Вдовы – прибрежной пещере, расположенной к северу отсюда.$b$bПауки тащат своих жертв вглубь пещеры, опутывают их коконами из паутины и оставляют до своего следующего обеда.$b$bМы надеемся, что некоторые из них все еще живы и мы можем спасти их! Отправляйся туда и освободи всех, кого сможешь найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разорвите паутину вдовы и освободите 5 жителей деревни Шри-Ла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31708,'Змеиные чешуйки','Я вижу, ты $gполучил:получила:r; своего собственного облачного змея, |3-6($r).$b$bТы не забываешь о том, что его надо кормить, убирать за ним и играть с ним? Только в этом случае твой змей вырастет здоровым и сильным.$b$bА теперь я поделюсь с тобой одним секретом. К северу отсюда, в Плаче Вдовы, растут грибы, известные как "змеиные чешуйки".$b$bНайти их трудно, но эти грибы особенные и содержат в себе много питательных веществ. Твоему змею они вряд ли понравятся. Впрочем, кто любит есть то, что полезно?','Соберите 25 "змеиных чешуек".','<Облачный змей обнюхивает грибы и кривится. Он пытается удрать, но вы аккуратно держите его и убеждаете съесть эти губчатые грибы.>','<Ваш облачный змей радостно встречает вас.>','Вернитесь к вашему детенышу облачного змея в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеиные чешуйки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, ты $gполучил:получила:r; своего собственного облачного змея, |3-6($r).$b$bТы не забываешь о том, что его надо кормить, убирать за ним и играть с ним? Только в этом случае твой змей вырастет здоровым и сильным.$b$bА теперь я поделюсь с тобой одним секретом. К северу отсюда, в Плаче Вдовы, растут грибы, известные как "змеиные чешуйки".$b$bНайти их трудно, но эти грибы особенные и содержат в себе много питательных веществ. Твоему змею они вряд ли понравятся. Впрочем, кто любит есть то, что полезно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 25 "змеиных чешуек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Облачный змей обнюхивает грибы и кривится. Он пытается удрать, но вы аккуратно держите его и убеждаете съесть эти губчатые грибы.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Ваш облачный змей радостно встречает вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вашему детенышу облачного змея в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31709,'Мучительные сомнения','Говорят, что в Плаче Вдовы, что к северу отсюда, происходит что-то странное.$b$bМы с Гиацинтом ходили туда на разведку, и теперь я не сомневаюсь в том, что в эту пещеру каким-то образом проникли ша.$b$bЯ изобрел устройство, которое позволяет измерить уровень энергии ша.$b$bЕсли ты направляешься в ту сторону, может быть, произведешь замеры?$b$bВолнения ша выглядят как потоки темной и светлой энергии, поднимающиеся из земли.','Воспользуйтесь устройством измерения силы ша в местах волнений ша в Плаче Вдовы. Вход в Плач Вдовы находится в северной части берега, южнее деревни Шри-Ла.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мучительные сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что в Плаче Вдовы, что к северу отсюда, происходит что-то странное.$b$bМы с Гиацинтом ходили туда на разведку, и теперь я не сомневаюсь в том, что в эту пещеру каким-то образом проникли ша.$b$bЯ изобрел устройство, которое позволяет измерить уровень энергии ша.$b$bЕсли ты направляешься в ту сторону, может быть, произведешь замеры?$b$bВолнения ша выглядят как потоки темной и светлой энергии, поднимающиеся из земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь устройством измерения силы ша в местах волнений ша в Плаче Вдовы. Вход в Плач Вдовы находится в северной части берега, южнее деревни Шри-Ла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31710,'Маленькие лакомства','При вашем приближении облачный змей открывает свою пасть, из которой капает слюна. По его виду заметно, что он успел сильно проголодаться с момента вашей последней встречи.$b$bПо тому, какие звуки он издает и как бьет хвостом, вы понимаете, что он не просто голоден, а хочет получить свое любимое лакомство.$b$bВаш змей любит пожевать маленькие паучьи глаза. Но такое изысканное лакомство можно добыть, только убивая порождений вдовы, которые обитают в пещере на берегу к северу отсюда.$b$bЧто ж, выхода нет. Ваш змей ждет.','Соберите 100 маленьких паучьих глаз.','Облачный змей нежно тычется мордой в вашу ладонь, а затем набрасывается на угощение!','При вашем возвращении змей оживляется.','Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькие лакомства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При вашем приближении облачный змей открывает свою пасть, из которой капает слюна. По его виду заметно, что он успел сильно проголодаться с момента вашей последней встречи.$b$bПо тому, какие звуки он издает и как бьет хвостом, вы понимаете, что он не просто голоден, а хочет получить свое любимое лакомство.$b$bВаш змей любит пожевать маленькие паучьи глаза. Но такое изысканное лакомство можно добыть, только убивая порождений вдовы, которые обитают в пещере на берегу к северу отсюда.$b$bЧто ж, выхода нет. Ваш змей ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 маленьких паучьих глаз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Облачный змей нежно тычется мордой в вашу ладонь, а затем набрасывается на угощение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','При вашем возвращении змей оживляется.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31711,'Зерно сомнения','Основная проблема с Ша Сомнения в том, |3-6($r), что они проникают повсюду.$b$bСтоит зерну сомнения попасть в благодатную почву, как оно начинает расти со скоростью сорняка.$b$bИменно такое зерно пустило корни в Плаче Вдовы, что к северу отсюда. И мы должны поступить с ним так же, как с любым другим сорняком – вырвать его с корнем, немедленно.$b$bУничтожь разрастающийся очаг сомнений, пока еще кто-то не стал жертвой этой заразы.','Уничтожьте зерно сомнения.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зерно сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основная проблема с Ша Сомнения в том, |3-6($r), что они проникают повсюду.$b$bСтоит зерну сомнения попасть в благодатную почву, как оно начинает расти со скоростью сорняка.$b$bИменно такое зерно пустило корни в Плаче Вдовы, что к северу отсюда. И мы должны поступить с ним так же, как с любым другим сорняком – вырвать его с корнем, немедленно.$b$bУничтожь разрастающийся очаг сомнений, пока еще кто-то не стал жертвой этой заразы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте зерно сомнения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31712,'Обезьяньи проказы','Странные вести доходят до нас из деревни Шри-Ла.$b$bПохоже, племя хозенов с удобством расположилось в Уна Кагу – пещере, расположенной на берегу, к югу от рыбацкой деревни.$b$bИ чувствуют они себя там просто прекрасно. Племя занимается грабежом и мародерством по всему берегу.$b$bМы должны преподать им урок... и это тот самый случай, когда можно действовать только силой. Они уже и так злоупотребили гостеприимством.','Убейте 13 хозенов Уна.','Хозены создавали много проблем. Ты правильно сделал, что выполнил просьбу инструктора Небесного Шипа.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезьяньи проказы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странные вести доходят до нас из деревни Шри-Ла.$b$bПохоже, племя хозенов с удобством расположилось в Уна Кагу – пещере, расположенной на берегу, к югу от рыбацкой деревни.$b$bИ чувствуют они себя там просто прекрасно. Племя занимается грабежом и мародерством по всему берегу.$b$bМы должны преподать им урок... и это тот самый случай, когда можно действовать только силой. Они уже и так злоупотребили гостеприимством.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 13 хозенов Уна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хозены создавали много проблем. Ты правильно сделал, что выполнил просьбу инструктора Небесного Шипа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31713,'Спасение портера','Это какой-то кошмар, $n!$B$BКогда я вчера зашел в "Танцующую змею", там не налили ни капли. Оказалось, что у них закончился портер, а тот, что был отправлен из деревни Шри-Ла, разворовали хозены. Разворовали!$B$BЭти хозены Уна вообще доставляют много хлопот на пристани. Они тащат портер со всего побережья в свое логово в Уна Кагу.$B$BУ меня все падает из рук, когда нечем промочить горло.$B$BКто-то должен пойти туда и спасти наш портер!','Соберите 100 порций украденного портера Шри-Ла.','О, благодарение Буйным Портерам! Ты мой герой!','Где портер? Мне его очень не хватает...','Вернитесь к Айсу Длинной Лапе в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение портера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это какой-то кошмар, $n!$B$BКогда я вчера зашел в "Танцующую змею", там не налили ни капли. Оказалось, что у них закончился портер, а тот, что был отправлен из деревни Шри-Ла, разворовали хозены. Разворовали!$B$BЭти хозены Уна вообще доставляют много хлопот на пристани. Они тащат портер со всего побережья в свое логово в Уна Кагу.$B$BУ меня все падает из рук, когда нечем промочить горло.$B$BКто-то должен пойти туда и спасти наш портер!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 порций украденного портера Шри-Ла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, благодарение Буйным Портерам! Ты мой герой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где портер? Мне его очень не хватает...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Айсу Длинной Лапе в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31714,'Спасение змеев','Соберите 10 спасенных змеев.','Да, детеныши выглядят изможденными. Они многое пережили, но благодаря тебе они теперь в безопасности.','Орден Облачного Змея веками работает над тем, чтобы змеи стали нашими верными спутниками. Своей добротой мы воспитываем в них самые лучшие качества.$B$BК сожалению, гнев и насилие способны превратить их в агрессивных созданий.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение змеев',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 спасенных змеев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, детеныши выглядят изможденными. Они многое пережили, но благодаря тебе они теперь в безопасности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Орден Облачного Змея веками работает над тем, чтобы змеи стали нашими верными спутниками. Своей добротой мы воспитываем в них самые лучшие качества.$B$BК сожалению, гнев и насилие способны превратить их в агрессивных созданий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31715,'Лорд Уна','Главарь хозенов Уна – разбойник по имени Лорд Уна.$B$BОб этом капитане и его команде ходят жуткие истории. Всюду, куда он направляется, его племя сеет разрушение.$B$BУна причаливают на своих лодках к плодородным берегам, грабят местные деревни, выжимают из земли все до капли и двигаются дальше.$B$BПока я за все отвечаю, я не позволю, чтобы это случилось и с нашим краем.$B$BМне нужен тот, кто искоренит эту проблему незамедлительно.','Убейте Лорда Уна.','Так что, главарь мертв? Хорошо. Может, теперь хозены оставят деревню в покое.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Уна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главарь хозенов Уна – разбойник по имени Лорд Уна.$B$BОб этом капитане и его команде ходят жуткие истории. Всюду, куда он направляется, его племя сеет разрушение.$B$BУна причаливают на своих лодках к плодородным берегам, грабят местные деревни, выжимают из земли все до капли и двигаются дальше.$B$BПока я за все отвечаю, я не позволю, чтобы это случилось и с нашим краем.$B$BМне нужен тот, кто искоренит эту проблему незамедлительно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Лорда Уна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так что, главарь мертв? Хорошо. Может, теперь хозены оставят деревню в покое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31716,'Большая уборка','<Когда вы приближаетесь к загону, змей стремительно перелетает в угол и прячется.>$b$BПо его стыдливому взгляду становится понятно, что кое-кто не сдержался и с ним произошла небольшая "неприятность".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было произойти... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.','Соберите 5 больших мешков экскрементов.','Детеныш облачного змея удовлетворенно играет, не обращая на вас внимания. Да… порой вам кажется, что быть укротителем змеев – неблагодарная работа.','<Детеныш облачного змея удивленно смотрит на вас.>','Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая уборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Когда вы приближаетесь к загону, змей стремительно перелетает в угол и прячется.>$b$BПо его стыдливому взгляду становится понятно, что кое-кто не сдержался и с ним произошла небольшая "неприятность".$b$bЧто ж, неудивительно. Раз этот змей столько ест, то такое должно было произойти... рано или поздно.$b$bЛучше найти оставленные змеем кучки и убрать их, пока об этом не узнал распорядитель змеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 больших мешков экскрементов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детеныш облачного змея удовлетворенно играет, не обращая на вас внимания. Да… порой вам кажется, что быть укротителем змеев – неблагодарная работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Детеныш облачного змея удивленно смотрит на вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вашему змею в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31717,'Поединок укротителей: Айс Длинная Лапа','Ты котируешься все выше среди наших учеников, $n.$B$BКак меч закаляется в огне, так и наши ученики становятся сильнее, сражаясь друг с другом.$B$BСегодня ты сойдешься в поединке с одним из наших ярчайших учеников, Айсом Длинной Лапой. Чтобы победить его, тебе придется использовать свои защитные умения.$B$BПоговори с ним на ринге, чтобы начать состязание. Удачи.','Поговорите с Айсом Длинной Лапой, а затем победите его.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок укротителей: Айс Длинная Лапа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты котируешься все выше среди наших учеников, $n.$B$BКак меч закаляется в огне, так и наши ученики становятся сильнее, сражаясь друг с другом.$B$BСегодня ты сойдешься в поединке с одним из наших ярчайших учеников, Айсом Длинной Лапой. Чтобы победить его, тебе придется использовать свои защитные умения.$B$BПоговори с ним на ринге, чтобы начать состязание. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Айсом Длинной Лапой, а затем победите его.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31718,'Поединок укротителей: Большой Бао','Ты уже $gготов:готова; к следующему уроку, $n?$b$bСегодня тебе предстоит встретиться на ринге с Большим Бао. Он большой во всех смыслах этого слова. И он не сдастся до последнего.$b$bЕсли хочешь одержать над ним победу, тебе нужно быть $gстойким:стойкой;.$b$bПоговори с ним на ринге, чтобы начать поединок. Желаю удачи!','Поговорите с Большим Бао, а затем победите его.','Вы оба стояли до конца. Отлично, мой ученик.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок укротителей: Большой Бао',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gготов:готова; к следующему уроку, $n?$b$bСегодня тебе предстоит встретиться на ринге с Большим Бао. Он большой во всех смыслах этого слова. И он не сдастся до последнего.$b$bЕсли хочешь одержать над ним победу, тебе нужно быть $gстойким:стойкой;.$b$bПоговори с ним на ринге, чтобы начать поединок. Желаю удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Большим Бао, а затем победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы оба стояли до конца. Отлично, мой ученик.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31719,'Поединок укротителей: Нинья Темное Колесо','У тебя большой потенциал, $n. Однако без дисциплины и смирения талант мало чего стоит.$B$BСегодня ты сразишься с Ниньей Темное Колесо. Благодаря природной силе она стала одной из самых талантливых учениц.$B$BЕсли надеешься победить ее, то придется действовать на пределе самообладания.$B$BЧтобы начать состязание, поговори с ней на ринге. Удачи.','Поговорите с Ниньей Темное Колесо, а затем победите ее.','Бой с Ниньей быстро покажет сильные и слабые стороны. Отлично.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок укротителей: Нинья Темное Колесо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя большой потенциал, $n. Однако без дисциплины и смирения талант мало чего стоит.$B$BСегодня ты сразишься с Ниньей Темное Колесо. Благодаря природной силе она стала одной из самых талантливых учениц.$B$BЕсли надеешься победить ее, то придется действовать на пределе самообладания.$B$BЧтобы начать состязание, поговори с ней на ринге. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ниньей Темное Колесо, а затем победите ее.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бой с Ниньей быстро покажет сильные и слабые стороны. Отлично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31720,'Поединок укротителей: Сладкая Су-Чи','Сегодня тебе предстоит встретиться на ринге со Сладкой Су-Чи. Несмотря на ее милую внешность, она – сильный противник.$b$bОна атакует быстро и точно, правда, спустя какое-то время столь мощные атаки утомляют ее.$b$bЕсли надеешься победить ее, тебе будет нужно сосредоточиться на нанесении урона, когда она ослабнет.$b$bПоговори с Су-Чи и начинай поединок. Удачи.','Поговорите со Сладкой Су-Чи, а затем победите ее.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок укротителей: Сладкая Су-Чи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня тебе предстоит встретиться на ринге со Сладкой Су-Чи. Несмотря на ее милую внешность, она – сильный противник.$b$bОна атакует быстро и точно, правда, спустя какое-то время столь мощные атаки утомляют ее.$b$bЕсли надеешься победить ее, тебе будет нужно сосредоточиться на нанесении урона, когда она ослабнет.$b$bПоговори с Су-Чи и начинай поединок. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Сладкой Су-Чи, а затем победите ее.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31721,'Поединок укротителей: Цюа-Жо Белая Бровь','Цюа-Жо считают лучшим послушником Ордена.$B$BКажется, у него нет слабых сторон. Он сметлив, силен, прилежен и даровит.$B$BТебе предстоит сойтись в поединке с одним из лучших бойцов.$B$BПоговори с ним, чтобы начать схватку. Кто бы из вас ни победил, ты многому научишься в бою с таким непростым соперником.','Поговорите с Цюа-Жо Белой Бровью, а затем победите его в бою.','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок укротителей: Цюа-Жо Белая Бровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цюа-Жо считают лучшим послушником Ордена.$B$BКажется, у него нет слабых сторон. Он сметлив, силен, прилежен и даровит.$B$BТебе предстоит сойтись в поединке с одним из лучших бойцов.$B$BПоговори с ним, чтобы начать схватку. Кто бы из вас ни победил, ты многому научишься в бою с таким непростым соперником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Цюа-Жо Белой Бровью, а затем победите его в бою.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Анли в Дендрарий, что в Нефритовом лесу.',`completedtext_loc8`);
