INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31724,'Старик Макдональд','Победите старика Макдональда в битве питомцев.','Должно быть, думаешь, что ты настоящий ас, да?','Поговорите со стариком Макдональдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старик Макдональд',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите старика Макдональда в битве питомцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должно быть, думаешь, что ты настоящий ас, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со стариком Макдональдом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31725,'Линдси','Победите Линдси в битве питомцев.','Кто учил тебя сражаться?','Поговорите с Линдси.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Линдси',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Линдси в битве питомцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто учил тебя сражаться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линдси.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31726,'Эрик Дэвидсон','Все мои друзья говорят об ужасном воргене по имени Эрик Дэвидсон из Сумеречного леса, с которым еще никто не устраивал битв питомцев.$b$bДумаю, если тебе удастся найти и победить его, то после этой победы все будут говорить только о тебе!','Победите Эрика Дэвидсона в битве питомцев.','Ты не только не боишься меня, ты еще и одержал надо мной честную победу. Я впечатлен.','Поговорите с Эриком Дэвидсоном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрик Дэвидсон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все мои друзья говорят об ужасном воргене по имени Эрик Дэвидсон из Сумеречного леса, с которым еще никто не устраивал битв питомцев.$b$bДумаю, если тебе удастся найти и победить его, то после этой победы все будут говорить только о тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эрика Дэвидсона в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не только не боишься меня, ты еще и одержал надо мной честную победу. Я впечатлен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эриком Дэвидсоном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31727,'Поиск припасов','Если мы хотим выиграть эту войну, нельзя упустить ни единой мелочи.$b$bВдоль побережья были замечены посторонние. Нам не нужны чужаки, но их припасы могут пригодиться.$b$bЕсли там есть что-то полезное, мы должны опередить императрицу и завладеть этим.','Поговорите с боцманом Ари в Приюте капитана, что в Жутких пустошах.','Так, значит, нами заинтересовались жуки? Что ж, если им что-то нужно от нас, пусть приходят сюда и заработают это сами.$B$BТак у нас тут заведено – кто не работает, тот не ест. Тебя это, кстати, тоже касается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск припасов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим выиграть эту войну, нельзя упустить ни единой мелочи.$b$bВдоль побережья были замечены посторонние. Нам не нужны чужаки, но их припасы могут пригодиться.$b$bЕсли там есть что-то полезное, мы должны опередить императрицу и завладеть этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с боцманом Ари в Приюте капитана, что в Жутких пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, значит, нами заинтересовались жуки? Что ж, если им что-то нужно от нас, пусть приходят сюда и заработают это сами.$B$BТак у нас тут заведено – кто не работает, тот не ест. Тебя это, кстати, тоже касается.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31728,'Билл Баклер','Победите Билла Баклера в битве питомцев.','Требую переиграть… ик! Это было нечестно! Вас было двое!','Поговорите с Биллом Баклером.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Билл Баклер',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Билла Баклера в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Требую переиграть… ик! Это было нечестно! Вас было двое!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Биллом Баклером.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31729,'Стивен Лисбен','Если тебе показалось, что сражаться со мной было трудно, сейчас тебе стоит хорошенько приготовиться. Дальше будет только сложнее.$b$bРазыщи Стивена Лисбена, обычно он бродит по дорогам в южной части Северной Тернистой долины, и ты увидишь, кто самый сильный укротитель питомцев!','Победите Стивена Лисбена в битве питомцев.','Вот это представление! Поистине грандиозная схватка.','Поговорите со Стивеном Лисбеном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стивен Лисбен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе показалось, что сражаться со мной было трудно, сейчас тебе стоит хорошенько приготовиться. Дальше будет только сложнее.$b$bРазыщи Стивена Лисбена, обычно он бродит по дорогам в южной части Северной Тернистой долины, и ты увидишь, кто самый сильный укротитель питомцев!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Стивена Лисбена в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это представление! Поистине грандиозная схватка.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Стивеном Лисбеном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31730,'Недружественная просьба','Поговорите с соковаром Ву в хмелеваренном дворике в Жутких пустошах.','Значит, они хотят, чтобы мы ушли? Вот эгоисты! Мы собираем янтарь только с одного дерева!$B$BДа никуда я не пойду, ясно тебе? Мне надо хмель варить.$B$BВпрочем, мы же разумны, а значит – можем прийти к взаимовыгодному соглашению. Давай я буду поставлять им хмель, а они перестанут пытаться нас убить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недружественная просьба',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с соковаром Ву в хмелеваренном дворике в Жутких пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, они хотят, чтобы мы ушли? Вот эгоисты! Мы собираем янтарь только с одного дерева!$B$BДа никуда я не пойду, ясно тебе? Мне надо хмель варить.$B$BВпрочем, мы же разумны, а значит – можем прийти к взаимовыгодному соглашению. Давай я буду поставлять им хмель, а они перестанут пытаться нас убить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31731,'[SINK SHIPS] (Not Used?)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[SINK SHIPS] (Not Used?)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31732,'Да разверзнется ад','Я не позволю Орде закрепиться на этих берегах раньше нас! Если ищешь приключений на свою голову, то можешь взять гирокоптер, который стоит на корме. Он уже подготовлен к атаке, так что от тебя просто требуется пострелять.$B$BЗадай жару этим оркам!','Летите на гирокоптере "Небесного огня", чтобы уничтожить 60 солдат лагеря Гаррош\'ар и 8 крошшеров лагеря Гаррош\'ар, а затем потопите "Жнец Кровавого Кулака" и "Адский Шрам".','Надлежащее приветствие для Орды на новой земле!','Поговорите с адмиралом Роджерс на борту "Небесного огня" в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да разверзнется ад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не позволю Орде закрепиться на этих берегах раньше нас! Если ищешь приключений на свою голову, то можешь взять гирокоптер, который стоит на корме. Он уже подготовлен к атаке, так что от тебя просто требуется пострелять.$B$BЗадай жару этим оркам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Летите на гирокоптере "Небесного огня", чтобы уничтожить 60 солдат лагеря Гаррош\'ар и 8 крошшеров лагеря Гаррош\'ар, а затем потопите "Жнец Кровавого Кулака" и "Адский Шрам".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надлежащее приветствие для Орды на новой земле!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с адмиралом Роджерс на борту "Небесного огня" в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31733,'Коснуться земли','Их город пылает, а воины разрознены и сломлены. Все наши должны быть на земле немедленно, чтобы прикончить их.$B$BХватай парашют у борта корабля и прыгай вниз!','Используйте парашют "Небесного огня", чтобы приземлиться в лагере Гаррош\'ар, после чего поговорите с Салли "Рассольным" Маклири.','Ты как раз вовремя, дружище! Пора ломать и крушить!','Поговорите с Салли "Рассольным" Маклири в лагере Гаррош\'ар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коснуться земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Их город пылает, а воины разрознены и сломлены. Все наши должны быть на земле немедленно, чтобы прикончить их.$B$BХватай парашют у борта корабля и прыгай вниз!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте парашют "Небесного огня", чтобы приземлиться в лагере Гаррош\'ар, после чего поговорите с Салли "Рассольным" Маклири.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя, дружище! Пора ломать и крушить!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Салли "Рассольным" Маклири в лагере Гаррош\'ар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31734,'Яркая встреча','Ты $gвидел:видела;, какого размера эти боевые повозки? Там напихано столько взрывчатки, что можно подумать, будто Орда хочет не захватить континент, а разнести его на кусочки!$B$BНам надо обезвредить эти повозки, пока они еще в лагере Гаррош\'ар.$B$BВот, возьми эти карманные ракеты. Выпусти их в повозку и полюбуйся фейерверком!','Используйте сигнальный пистолет Салли, чтобы уничтожить 5 боевых повозок Орды.','Теперь, когда с повозками покончено, мы можем отправляться к командиру.','Явитесь к Реллу Ночному Ветру в лагерь Гаррош\'ар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яркая встреча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела;, какого размера эти боевые повозки? Там напихано столько взрывчатки, что можно подумать, будто Орда хочет не захватить континент, а разнести его на кусочки!$B$BНам надо обезвредить эти повозки, пока они еще в лагере Гаррош\'ар.$B$BВот, возьми эти карманные ракеты. Выпусти их в повозку и полюбуйся фейерверком!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сигнальный пистолет Салли, чтобы уничтожить 5 боевых повозок Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда с повозками покончено, мы можем отправляться к командиру.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к Реллу Ночному Ветру в лагерь Гаррош\'ар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31735,'Подходящий инструмент','Используйте сигнальный пистолет Салли, чтобы уничтожить баррикады, и сразитесь с Га\'трулом на другом конце дока.','Мы еще поймаем его. Зуб даю.','Поговорите с Реллом Ночным Ветром в лагере Гаррош\'ар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подходящий инструмент',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сигнальный пистолет Салли, чтобы уничтожить баррикады, и сразитесь с Га\'трулом на другом конце дока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы еще поймаем его. Зуб даю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Реллом Ночным Ветром в лагере Гаррош\'ар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31736,'Посланник Альянса','К северу от этого лагеря находится вишневый сад, а за ним прячется деревенька. Нам надо будет остановиться там и перевязать раненых, пока мы будем готовить наш следующий ход.$B$BОтправляйся в эту деревню и поговори с тамошним предводителем. Мы с агентом Мишкой встретим тебя там.$B$BИ будь повежливей, $n! Я возлагаю на тебя честь представлять весь Альянс. Не заставь меня пожалеть об этом.$B$BНадеюсь, что $gтакой могущественный герой:такая могущественная воительница; как ты произведет на них хорошее впечатление.','Найдите мэра деревни Лап\'дон и поговорите с ним.','Когда опустился туман, мы поняли, что прибытие гостей – это вопрос времени.$B$BНо никто не мог предсказать, что все будет именно так.','Поговорите с Сунк Ханом в деревне Лап\'дон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланник Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северу от этого лагеря находится вишневый сад, а за ним прячется деревенька. Нам надо будет остановиться там и перевязать раненых, пока мы будем готовить наш следующий ход.$B$BОтправляйся в эту деревню и поговори с тамошним предводителем. Мы с агентом Мишкой встретим тебя там.$B$BИ будь повежливей, $n! Я возлагаю на тебя честь представлять весь Альянс. Не заставь меня пожалеть об этом.$B$BНадеюсь, что $gтакой могущественный герой:такая могущественная воительница; как ты произведет на них хорошее впечатление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите мэра деревни Лап\'дон и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда опустился туман, мы поняли, что прибытие гостей – это вопрос времени.$B$BНо никто не мог предсказать, что все будет именно так.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сунк Ханом в деревне Лап\'дон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31737,'Цена войны','Тут все пылает, а с "Небесного огня" докладывают, что еще больше этих... теней выползает из земли. Нам надо уводить всех прочь отсюда.$B$BРасчисти путь через лагерь по дороге на север и направляйся в город. Я встречу тебя там.','Рад, что ты не боишься ответственности за свои действия. Если ничего не делать, то негативные эмоции могут очень быстро одолеть любого. Именно это и произошло с тем, кого вы зовете Реллом.','Поговорите с Тажанем Чжу в деревне Лап\'дон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цена войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут все пылает, а с "Небесного огня" докладывают, что еще больше этих... теней выползает из земли. Нам надо уводить всех прочь отсюда.$B$BРасчисти путь через лагерь по дороге на север и направляйся в город. Я встречу тебя там.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад, что ты не боишься ответственности за свои действия. Если ничего не делать, то негативные эмоции могут очень быстро одолеть любого. Именно это и произошло с тем, кого вы зовете Реллом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тажанем Чжу в деревне Лап\'дон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31738,'Батраки-мародеры','Как наша деревня стала полем боя?$B$BК западу отсюда негодяи из Орды вырубают наш бесценный сад. Без яблоневых деревьев пропадет вся деревня – не будет ни урожая, ни еды, ни заработка.$B$BЕсли ты действительно не $gтакой:такая; как они, докажи нам это! Защити сад и накажи тех, кто бесчинствует на нашей земле!','Вернитесь к Сунк Хану в деревню Лап\'дон, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батраки-мародеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как наша деревня стала полем боя?$B$BК западу отсюда негодяи из Орды вырубают наш бесценный сад. Без яблоневых деревьев пропадет вся деревня – не будет ни урожая, ни еды, ни заработка.$B$BЕсли ты действительно не $gтакой:такая; как они, докажи нам это! Защити сад и накажи тех, кто бесчинствует на нашей земле!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунк Хану в деревню Лап\'дон, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31739,'Приоритеты!','Эти так называемые "орки" разграбили хмелеварню и сбежали с бочками моего лучшего сидра!$b$bЯ знаю, что повсюду война, но я не тот хмелевар, который будет стоять и смотреть на то, как его коллекционный напиток пьют недостойные его личности!$b$bЭта "Орда" получит отпор.$b$bПочему бы тебе не обратить свое оружие на доброе дело и не помочь мне вернуть мой сидр?','Соберите 6 бочек сидра Яблоневого Цвета.','Я погляжу, вы вдвоем без дела не сидели. Спасибо за то, что вернул мои бочки.','Поговорите с Линь Яблоневым Цветом в роще Лап\'дон, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приоритеты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти так называемые "орки" разграбили хмелеварню и сбежали с бочками моего лучшего сидра!$b$bЯ знаю, что повсюду война, но я не тот хмелевар, который будет стоять и смотреть на то, как его коллекционный напиток пьют недостойные его личности!$b$bЭта "Орда" получит отпор.$b$bПочему бы тебе не обратить свое оружие на доброе дело и не помочь мне вернуть мой сидр?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 бочек сидра Яблоневого Цвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я погляжу, вы вдвоем без дела не сидели. Спасибо за то, что вернул мои бочки.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линь Яблоневым Цветом в роще Лап\'дон, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31740,'Буйство Куку','Мы беспокоимся не только о своих погребах.$b$bКуку, наш любимый мушан, сошел с ума! Только посмотри на него!$b$bЧто я только не пробовала! И уговаривала его, и упрашивала, и кричала, и успокаивала... Ничего не помогает.$b$bБоюсь, он больше не контролирует себя. Есть только один способ спасти как его, так и нашу хмелеварню.$b$bНанеси ему быстрый и точный удар. Он ничего не почувствует.','Убейте Куку.','Вернитесь к Сунк Хану в деревню Лап\'дон, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буйство Куку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы беспокоимся не только о своих погребах.$b$bКуку, наш любимый мушан, сошел с ума! Только посмотри на него!$b$bЧто я только не пробовала! И уговаривала его, и упрашивала, и кричала, и успокаивала... Ничего не помогает.$b$bБоюсь, он больше не контролирует себя. Есть только один способ спасти как его, так и нашу хмелеварню.$b$bНанеси ему быстрый и точный удар. Он ничего не почувствует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Куку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунк Хану в деревню Лап\'дон, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31741,'Крепость Двух Башен','Я не доверяю Орде. Ее представители используют темную магию и явно не с добрыми намерениями. Мы больше не можем терпеть их присутствие в Крепости Двух Башен, в двух шагах от деревни Лап\'дон.$b$bУмоляю, $gчужестранец:чужестранка;, помоги нам, а не то с нашей деревней случится что-то ужасное.','Убейте 15 солдат Орды в Крепости Двух Башен.','Ну и бойню же ты там устроил.$B$BОтличная работа.','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость Двух Башен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не доверяю Орде. Ее представители используют темную магию и явно не с добрыми намерениями. Мы больше не можем терпеть их присутствие в Крепости Двух Башен, в двух шагах от деревни Лап\'дон.$b$bУмоляю, $gчужестранец:чужестранка;, помоги нам, а не то с нашей деревней случится что-то ужасное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 солдат Орды в Крепости Двух Башен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и бойню же ты там устроил.$B$BОтличная работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31742,'Разрозненные силы','Орда сама делает за нас всю работу. Их грызня и разрозненность раскололи лагерь надвое: орки на западе, нежить на востоке.$b$bОрки подчиняются своему командиру Далгану, а нежить следует за Белландрой Бурей Скверны, могучей чернокнижницей. Если повезет, то внутренние стычки отвлекут их, и ты сможешь пробраться внутрь и убить обоих. Салли уже засел в руинах. Найди его там, когда закончишь.','Убить Далгана и Белландру Бурю Скверны.','"Отправляйтесь с докладом к Салли "Рассольному" Маклири в Крепость Двух Башен, что в Нефритовом лесу".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрозненные силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда сама делает за нас всю работу. Их грызня и разрозненность раскололи лагерь надвое: орки на западе, нежить на востоке.$b$bОрки подчиняются своему командиру Далгану, а нежить следует за Белландрой Бурей Скверны, могучей чернокнижницей. Если повезет, то внутренние стычки отвлекут их, и ты сможешь пробраться внутрь и убить обоих. Салли уже засел в руинах. Найди его там, когда закончишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убить Далгана и Белландру Бурю Скверны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','"Отправляйтесь с докладом к Салли "Рассольному" Маклири в Крепость Двух Башен, что в Нефритовом лесу".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31743,'Дым над Ордой','Салли обнаружил лагерь Орды к северу отсюда и доложил, что видел огромную кучу взрывчатки, а также небольшую группу разрушителей. И это не считая демонов, которых призвали чернокнижники.$b$bК счастью, мы были готовы к этому. "Небесный огонь" поддержит нас с воздуха. Надо только показать нашим пилотам, куда бить.$b$b<Релл подает дымовую сигнальную ракету и со значением кивает.>','Используйте сигнальный огонь Альянса, чтобы вызвать воздушный удар по груде боеприпасов, разрушителям Двух Башен, диким бесам и Ксу\'даггабе.','Мои ребятки там, в небе, задают всем жару, да? Ха-ха-ха!','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дым над Ордой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Салли обнаружил лагерь Орды к северу отсюда и доложил, что видел огромную кучу взрывчатки, а также небольшую группу разрушителей. И это не считая демонов, которых призвали чернокнижники.$b$bК счастью, мы были готовы к этому. "Небесный огонь" поддержит нас с воздуха. Надо только показать нашим пилотам, куда бить.$b$b<Релл подает дымовую сигнальную ракету и со значением кивает.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте сигнальный огонь Альянса, чтобы вызвать воздушный удар по груде боеприпасов, разрушителям Двух Башен, диким бесам и Ксу\'даггабе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои ребятки там, в небе, задают всем жару, да? Ха-ха-ха!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31744,'Нечестная торговля','Хоть мы и только познакомились, у нас есть общий враг – так называемая "Орда".$b$bНесколько дней назад их командир предложил нам сделку. Когда мы отказались, его прислужники похитили наших детей, чтобы выбить из нас согласие.$b$bМы обратились за помощью к монахам Шадо-Пан, но вершина Кунь-Лай от нас в нескольких днях пути. Ты можешь нам помочь?','Освободите 8 захваченных юных пандаренов из Крепости Двух Башен, уничтожив демонические очи, которые их сторожат.','Ага, я видел малышей. Попались мне на пути сюда.$B$BЭто хороший поступок, парень. Этих деток будут тревожить ночные кошмары, но когда-нибудь они вырастут и перестанут бояться, и это благодаря тебе.','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестная торговля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть мы и только познакомились, у нас есть общий враг – так называемая "Орда".$b$bНесколько дней назад их командир предложил нам сделку. Когда мы отказались, его прислужники похитили наших детей, чтобы выбить из нас согласие.$b$bМы обратились за помощью к монахам Шадо-Пан, но вершина Кунь-Лай от нас в нескольких днях пути. Ты можешь нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 захваченных юных пандаренов из Крепости Двух Башен, уничтожив демонические очи, которые их сторожат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, я видел малышей. Попались мне на пути сюда.$B$BЭто хороший поступок, парень. Этих деток будут тревожить ночные кошмары, но когда-нибудь они вырастут и перестанут бояться, и это благодаря тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Явитесь к Салли "Рассольному" Маклири в Крепость Двух Башен в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31745,'Все дальше и дальше','"Ша", говоришь? Будь $gосторожен:осторожна;, $n, над этими краями сгущается тьма.$b$bМы очистим местность от остатков Орды, а тебе придется продолжить основную операцию по спасению капитана Тейлора и поискам принца Андуина.$b$bПо донесениям воздушной разведки остатки кораблекрушения были замечены вблизи деревни Лап\'дон. Отправляйся туда и обратись за дальнейшими указаниями к адмиралу Роджерс.$b$bМожешь воспользоваться моим гирокоптером.','Явитесь к адмиралу Роджерс в деревне Лап\'дон в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все дальше и дальше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Ша", говоришь? Будь $gосторожен:осторожна;, $n, над этими краями сгущается тьма.$b$bМы очистим местность от остатков Орды, а тебе придется продолжить основную операцию по спасению капитана Тейлора и поискам принца Андуина.$b$bПо донесениям воздушной разведки остатки кораблекрушения были замечены вблизи деревни Лап\'дон. Отправляйся туда и обратись за дальнейшими указаниями к адмиралу Роджерс.$b$bМожешь воспользоваться моим гирокоптером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к адмиралу Роджерс в деревне Лап\'дон в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31754,'Огневая поддержка','Эти пушки могу на Золотой лестнице не дают нам приблизиться. Вот было бы здорово, если бы они вдруг сломались, не правда ли?','Уничтожьте 7 пушек Шао-Тень.','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огневая поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти пушки могу на Золотой лестнице не дают нам приблизиться. Вот было бы здорово, если бы они вдруг сломались, не правда ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 пушек Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31755,'Жестокий поступок','Я слышу крики захваченных в плен солдат и мирных жителей, доносящиеся с Золотой лестницы. Их пытают!$B$BПожалуйста, прошу тебя, их надо спасти!','Спасите 5 стражей Золотого Лотоса или жителей Деревни Туманного Водопада.','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокий поступок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу крики захваченных в плен солдат и мирных жителей, доносящиеся с Золотой лестницы. Их пытают!$B$BПожалуйста, прошу тебя, их надо спасти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 5 стражей Золотого Лотоса или жителей Деревни Туманного Водопада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сунь Доброе Сердце в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31756,'Кажется, дождь собирается','Могу призывают какую-то зловещую бурю на Золотой лестнице. Честно говоря, мне не нравится, когда могу заваривают кашу с громом и молниями. Мы должны остановить их.$B$BНайти их призыватели бурь не составит труда – из них вырываются разряды молний. Не согласишься ли ты уничтожить их? Тогда мне будет спаться гораздо спокойнее.','Уничтожьте призывающие бурю посохи.','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кажется, дождь собирается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу призывают какую-то зловещую бурю на Золотой лестнице. Честно говоря, мне не нравится, когда могу заваривают кашу с громом и молниями. Мы должны остановить их.$B$BНайти их призыватели бурь не составит труда – из них вырываются разряды молний. Не согласишься ли ты уничтожить их? Тогда мне будет спаться гораздо спокойнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте призывающие бурю посохи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31757,'Освобожденные духи','Шао-Тень выпустили на нас захваченных духов! Они летят с Золотой лестницы, и их так много, что не видно конца этому призрачному нашествию. Убей столько, сколько сможешь. Они не очень сильны, но могут одолеть тебя числом.$B$BУдачи!','Убейте 12 освобожденных духов.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобожденные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шао-Тень выпустили на нас захваченных духов! Они летят с Золотой лестницы, и их так много, что не видно конца этому призрачному нашествию. Убей столько, сколько сможешь. Они не очень сильны, но могут одолеть тебя числом.$B$BУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 освобожденных духов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31758,'Разведка','Лао Легкая Нога опять попал в плен на Золотой лестнице. Боюсь, я вынужден признать – разведчик из него никакой.$B$BНо не можем же мы бросить его там? Пожалуйста, отыщи его и спаси.','Спасите Лао Легкую Ногу.','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лао Легкая Нога опять попал в плен на Золотой лестнице. Боюсь, я вынужден признать – разведчик из него никакой.$B$BНо не можем же мы бросить его там? Пожалуйста, отыщи его и спаси.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите Лао Легкую Ногу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Куню Осеннему Свету в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (31759,'[RESCUE GOLDEN LOTUS SQUAD] [GET RID OF THIS?]','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[RESCUE GOLDEN LOTUS SQUAD] [GET RID OF THIS?]',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31760,'Превентивный удар','Могу возводят какое-то гигантское каменное чудовище на Золотой лестнице, и что-то мне подсказывает, что они собираются наслать его на нас.$B$BНе желаешь донести до них наше мнение по этому вопросу? Только убедись, что они все поняли правильно.','Остановите ритуал усиления колосса Шао-Тень.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превентивный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу возводят какое-то гигантское каменное чудовище на Золотой лестнице, и что-то мне подсказывает, что они собираются наслать его на нас.$B$BНе желаешь донести до них наше мнение по этому вопросу? Только убедись, что они все поняли правильно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Остановите ритуал усиления колосса Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31761,'Breaking Their Spirits (Not Yet Implemented)','Могу сложили тела наших павших братьев на самой вершине Золотой лестницы и проводят нечестивые ритуалы, призванные отделить души и наслать их на нас.$B$BНайди, где они проводят этот ритуал, и останови их. Сделай все, чтобы они больше никогда не повторяли этой ошибки.','Остановите ритуал насылания духов Шао-Тень.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Breaking Their Spirits (Not Yet Implemented)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу сложили тела наших павших братьев на самой вершине Золотой лестницы и проводят нечестивые ритуалы, призванные отделить души и наслать их на нас.$B$BНайди, где они проводят этот ритуал, и останови их. Сделай все, чтобы они больше никогда не повторяли этой ошибки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Остановите ритуал насылания духов Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31762,'Рассыпающийся колосс','Могу все же возвели свою гигантскую каменную статую, и теперь собираются послать ее на борьбу с нами.$B$BВ ответ я собираюсь послать тебя на борьбу с ней.$B$BОна спускается с Золотой лестницы. Поставь ее на колени!','Уничтожьте колосса Шао-Тень.','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассыпающийся колосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу все же возвели свою гигантскую каменную статую, и теперь собираются послать ее на борьбу с нами.$B$BВ ответ я собираюсь послать тебя на борьбу с ней.$B$BОна спускается с Золотой лестницы. Поставь ее на колени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте колосса Шао-Тень.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аньцзи Осенний Свет в Золотую Пагоду, что в Вечноцветущем доле.',`completedtext_loc8`);
