INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (31764,'[PUT OUT THE FIRES]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PUT OUT THE FIRES]',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31765,'Раскрась мир красным!','Они вырубили наши двигатели, и мы упали здесь... здесь! Прямо на вражеской линии огня!$b$bТы знаешь, что надо делать, $n. Спускайся под палубы и встань за орудия!$b$bПокажи этим уродам, что они на нашей линии огня!','Используйте башню боевого корабля, чтобы уничтожить 80 солдат и 9 пушек Громовой крепости.','Поговорите с Риветтом Сталехватом на борту "Кулака Адского Крика" в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскрась мир красным!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они вырубили наши двигатели, и мы упали здесь... здесь! Прямо на вражеской линии огня!$b$bТы знаешь, что надо делать, $n. Спускайся под палубы и встань за орудия!$b$bПокажи этим уродам, что они на нашей линии огня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте башню боевого корабля, чтобы уничтожить 80 солдат и 9 пушек Громовой крепости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Риветтом Сталехватом на борту "Кулака Адского Крика" в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31766,'Коснуться земли','Назгрим возглавил наземную операцию и попросил немедленно прислать тебя к нему.$B$BУ нас есть несколько канатов для спуска, привязанных возле орудий. Это самый быстрый путь вниз – ну, из тех, что заканчиваются удачно.','Используйте канат для спуска, чтобы добраться до земли.','Вот и ты!$B$BЯ уже начал беспокоиться, что ты пропустишь все веселье.','Поговорите с генералом Назгримом на поляне Медовой Росы в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коснуться земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Назгрим возглавил наземную операцию и попросил немедленно прислать тебя к нему.$B$BУ нас есть несколько канатов для спуска, привязанных возле орудий. Это самый быстрый путь вниз – ну, из тех, что заканчиваются удачно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте канат для спуска, чтобы добраться до земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и ты!$B$BЯ уже начал беспокоиться, что ты пропустишь все веселье.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом на поляне Медовой Росы в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31767,'Прикончить их!','Мы их потрепали. Пора их прикончить!$b$bЭту крепость надо очистить от Альянса, и нам негде держать пленников.$b$b<На лице Назгрима мелькает тень улыбки.>$b$bТы знаешь, что делать, $n. Эти трусы побегут, если дать им шанс.$b$bПостарайся им его не дать!','Уничтожьте 15 солдат Громовой крепости.','Поговорите с генералом Назгримом в Громовой крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикончить их!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы их потрепали. Пора их прикончить!$b$bЭту крепость надо очистить от Альянса, и нам негде держать пленников.$b$b<На лице Назгрима мелькает тень улыбки.>$b$bТы знаешь, что делать, $n. Эти трусы побегут, если дать им шанс.$b$bПостарайся им его не дать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 солдат Громовой крепости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Громовой крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31768,'Огонь – лучший ответ','Уничтожить их силы недостаточно. Нельзя оставить им ни единого шанса на спасение!$b$bВозьми это ружье и выстрели из него в боеприпасы. Пусть останутся ни с чем!','Уничтожьте 10 штабелей боеприпасов Громовой крепости.','Поговорите с генералом Назгримом в Громовой крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь – лучший ответ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уничтожить их силы недостаточно. Нельзя оставить им ни единого шанса на спасение!$b$bВозьми это ружье и выстрели из него в боеприпасы. Пусть останутся ни с чем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 штабелей боеприпасов Громовой крепости.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Громовой крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31769,'Завершающий удар!','Мы узнали, что их капитан забаррикадировался над нами.$b$bЭтот трус отправил свои отряды на смерть, а сам спрятался от нашего гнева! Типично для Альянса! Неважно. Он больше не сможет бежать от судьбы.$b$bЯ поведу своих пехотинцев на стены, а ты возглавишь основную атаку на крепостные валы. Используй ружье для подрыва взрывчатки, чтобы пробить себе дорогу.$b$bВстретимся наверху и вместе расправимся с этим ничтожеством, которое называет себя капитаном!','Уничтожьте капитана Дорена в Громовой крепости.','Воздушная база, которая находилась тут все это время! Если бы я только знал, отрядил бы больше бойцов к орудиям… эх!$B$B<Назгрим бледнеет, и его тело начинает источать загадочную темную энергию.>','Поговорите с генералом Назгримом в Громовой крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершающий удар!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы узнали, что их капитан забаррикадировался над нами.$b$bЭтот трус отправил свои отряды на смерть, а сам спрятался от нашего гнева! Типично для Альянса! Неважно. Он больше не сможет бежать от судьбы.$b$bЯ поведу своих пехотинцев на стены, а ты возглавишь основную атаку на крепостные валы. Используй ружье для подрыва взрывчатки, чтобы пробить себе дорогу.$b$bВстретимся наверху и вместе расправимся с этим ничтожеством, которое называет себя капитаном!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте капитана Дорена в Громовой крепости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воздушная база, которая находилась тут все это время! Если бы я только знал, отрядил бы больше бойцов к орудиям… эх!$B$B<Назгрим бледнеет, и его тело начинает источать загадочную темную энергию.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Громовой крепости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31770,'Или с нами, или...','Помощь жителей соседней деревушки стала необходимостью, $n.$b$bНам нужна эта деревня, чтобы позаботиться о раненых и перегруппироваться.$b$bМожет быть, ее жители помогут нам после того, как стали свидетелями жестокости Альянса.$b$bТы будешь посланником Орды. Обеспечь нам помощь со стороны их главы. И не разочаруй меня!','Попытайтесь заручиться поддержкой мэра Медовая Роса в Деревне Медовой Росы.','Ваши раздоры принесли разорение в нашу маленькую деревню!$B$BНам не интересна ваша война, но мы не прогоним раненых.','Поговорите с мэром Медовая Роса в Деревне Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Или с нами, или...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помощь жителей соседней деревушки стала необходимостью, $n.$b$bНам нужна эта деревня, чтобы позаботиться о раненых и перегруппироваться.$b$bМожет быть, ее жители помогут нам после того, как стали свидетелями жестокости Альянса.$b$bТы будешь посланником Орды. Обеспечь нам помощь со стороны их главы. И не разочаруй меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попытайтесь заручиться поддержкой мэра Медовая Роса в Деревне Медовой Росы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваши раздоры принесли разорение в нашу маленькую деревню!$B$BНам не интересна ваша война, но мы не прогоним раненых.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мэром Медовая Роса в Деревне Медовой Росы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31771,'Лицом к лицу с последствиями','Я не знаю предыстории вашей войны, да и не хочу ее знать. Наша земля живо реагирует на любую отрицательную энергию. Ненависть, сомнение и насилие, которые вы принесли с собой, яростно хлещут из ран Пандарии.$b$bТо, что вы натворили, посеяло хаос в руинах! Иди же туда и приведи все в порядок, а затем возвращайся ко мне. Я постараюсь объяснить тебе, что произошло.','Убейте 20 наваждений ша и 7 ша – вестников ужаса.','Рад, что ты не боишься ответственности за свои действия. Если ничего не делать, то негативные эмоции могут очень быстро одолеть любого. Именно это и произошло с тем, кого вы зовете Назгримом.','Поговорите с Тажанем Чжу в деревне Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лицом к лицу с последствиями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знаю предыстории вашей войны, да и не хочу ее знать. Наша земля живо реагирует на любую отрицательную энергию. Ненависть, сомнение и насилие, которые вы принесли с собой, яростно хлещут из ран Пандарии.$b$bТо, что вы натворили, посеяло хаос в руинах! Иди же туда и приведи все в порядок, а затем возвращайся ко мне. Я постараюсь объяснить тебе, что произошло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 наваждений ша и 7 ша – вестников ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад, что ты не боишься ответственности за свои действия. Если ничего не делать, то негативные эмоции могут очень быстро одолеть любого. Именно это и произошло с тем, кого вы зовете Назгримом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тажанем Чжу в деревне Медовой Росы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31772,'Приоритеты!','Только посмотри на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.','Найдите 6 бочек медового хмеля на поляне Медовой Росы.','Ну, не так много, как я рассчитывала, но обойдемся и этим. Нет нужды плакать над пролитым пивом.','Вернитесь к Элли Медовой Лапе в Деревню Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приоритеты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только посмотри на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 бочек медового хмеля на поляне Медовой Росы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, не так много, как я рассчитывала, но обойдемся и этим. Нет нужды плакать над пролитым пивом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элли Медовой Лапе в Деревню Медовой Росы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31773,'Докучливые хищники','Все животные взбесились!$b$bОбычно хищники держатся подальше от деревни, но теперь мы не можем их отогнать! Они себя раньше так никогда не вели!$b$bМэр даже позвал на помощь Шадо-Пан, но пока еще никто не приехал. Не $gмог:могла; бы ты разобраться с хищниками, пока они не задрали одного из фермеров?','Уничтожьте 10 зараженных ша хищников на Поляне Медовой Росы.','Ах, так это ваша война в руинах так влияет на местных животных? Это очень тревожная новость, ведь раньше звери никогда не вели себя так агрессивно.$B$BСпасибо за помощь в защите деревни, но смерть этих несчастных животных – настоящая трагедия.','Вернитесь к Тажаню Чжу в деревню Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Докучливые хищники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все животные взбесились!$b$bОбычно хищники держатся подальше от деревни, но теперь мы не можем их отогнать! Они себя раньше так никогда не вели!$b$bМэр даже позвал на помощь Шадо-Пан, но пока еще никто не приехал. Не $gмог:могла; бы ты разобраться с хищниками, пока они не задрали одного из фермеров?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 зараженных ша хищников на Поляне Медовой Росы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так это ваша война в руинах так влияет на местных животных? Это очень тревожная новость, ведь раньше звери никогда не вели себя так агрессивно.$B$BСпасибо за помощь в защите деревни, но смерть этих несчастных животных – настоящая трагедия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу в деревню Медовой Росы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31774,'В поисках Зин\'Джуна','Риветт утверждает, что видел, как Зин\'Джун покинул корабль вместе с остальными выжившими. Это значит, что он может быть где угодно.$b$bМы не оставим его здесь. Его могли ранить или того хуже – взять в плен!$b$bОтыщи Зин\'Джуна и приведи его к нам.','Найдите Зин\'Джуна где-то на Возвышенности Кружащихся Ветров.','Поговорите с Зин\'Джуном на Возвышенности Кружащихся Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Зин\'Джуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Риветт утверждает, что видел, как Зин\'Джун покинул корабль вместе с остальными выжившими. Это значит, что он может быть где угодно.$b$bМы не оставим его здесь. Его могли ранить или того хуже – взять в плен!$b$bОтыщи Зин\'Джуна и приведи его к нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Зин\'Джуна где-то на Возвышенности Кружащихся Ветров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зин\'Джуном на Возвышенности Кружащихся Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31775,'Нападение на взлетную полосу','Мне удалось обнаружить секретный аэродром Альянса, Взлетную полосу Сильной Руки, $n. Это было несложно – врагов там целое скопище.$b$b<Назгрим отплевывается.>$b$bОни полагают, что мы уже разбиты, но, видать, они не знают, что такое Орда! Каждый ордынец дерется до последнего вздоха... а порой и после него! Пусть отведают нашей стали!','Убейте 15 бойцов Сильной Руки на Взлетной полосе Сильной Руки.','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на взлетную полосу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось обнаружить секретный аэродром Альянса, Взлетную полосу Сильной Руки, $n. Это было несложно – врагов там целое скопище.$b$b<Назгрим отплевывается.>$b$bОни полагают, что мы уже разбиты, но, видать, они не знают, что такое Орда! Каждый ордынец дерется до последнего вздоха... а порой и после него! Пусть отведают нашей стали!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 бойцов Сильной Руки на Взлетной полосе Сильной Руки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31776,'Слабости Сильной Руки','Поступили донесения разведки, и я отметил для тебя главные цели на Взлетной полосе Сильной Руки.$b$bДва гнома-механика следят за состоянием гирокоптеров Альянса. Ликвидируй механиков, и число исправных гирокоптеров резко снизится.$b$bЕще одна цель, рыцарь смерти – дворф, ходит по периметру базы. Он в чем-то похож на тебя – такой же не связанный обязательствами искатель приключений и опасный противник.$b$bИ, наконец, известная личность – капрал Джексон Сильвер. Это герой Альянса, который мастерски обращается с арбалетом.$b$bЖелаю удачи, |3-6($n).','Убейте капрала Джексона Сильвера, Моргуса Вредоруба, а также старшего инженера Гайкокрутса и гиро-механика Клейкомяша.','Кровь и гром, Смертуш. Кровь и гром!','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабости Сильной Руки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поступили донесения разведки, и я отметил для тебя главные цели на Взлетной полосе Сильной Руки.$b$bДва гнома-механика следят за состоянием гирокоптеров Альянса. Ликвидируй механиков, и число исправных гирокоптеров резко снизится.$b$bЕще одна цель, рыцарь смерти – дворф, ходит по периметру базы. Он в чем-то похож на тебя – такой же не связанный обязательствами искатель приключений и опасный противник.$b$bИ, наконец, известная личность – капрал Джексон Сильвер. Это герой Альянса, который мастерски обращается с арбалетом.$b$bЖелаю удачи, |3-6($n).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капрала Джексона Сильвера, Моргуса Вредоруба, а также старшего инженера Гайкокрутса и гиро-механика Клейкомяша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кровь и гром, Смертуш. Кровь и гром!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с генералом Назгримом в Закутке Конка, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31777,'"Фейерверк"','По дороге сюда я приметил несколько ручных ракетометов.$b$bМожет, это были и установки для запуска фейерверков, сложно сказать. В общем, будем считать, что это ручные ракетометы, пока не будет доказано обратное.$b$bДумаю, в руках $gтакого опытного:такой опытной:c; |3-1($c) подобная установка превратится в грозное оружие. С ее помощью можно будет даже сбить гирокоптер. Если найдешь такую установку, то обязательно опробуй ее на хлипких гирокоптерах.','Соберите конфискованные установки для фейерверков на Взлетной полосе Сильной Руки, а затем примените их против 12 гирокоптеров Сильной Руки.','Надеюсь, им понравился наш "фейерверк".','Вернитесь к Риветту Сталехвату в Закуток Конка, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Фейерверк"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По дороге сюда я приметил несколько ручных ракетометов.$b$bМожет, это были и установки для запуска фейерверков, сложно сказать. В общем, будем считать, что это ручные ракетометы, пока не будет доказано обратное.$b$bДумаю, в руках $gтакого опытного:такой опытной:c; |3-1($c) подобная установка превратится в грозное оружие. С ее помощью можно будет даже сбить гирокоптер. Если найдешь такую установку, то обязательно опробуй ее на хлипких гирокоптерах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите конфискованные установки для фейерверков на Взлетной полосе Сильной Руки, а затем примените их против 12 гирокоптеров Сильной Руки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, им понравился наш "фейерверк".',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риветту Сталехвату в Закуток Конка, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31778,'Ненадежные союзники','Сначала мы тепло встретили Альянс. Некоторые жители деревни даже вызвались помочь чужакам в строительстве взлетной полосы. И лишь недавно мы осознали, что на самом деле там строят военную базу, в двух шагах от деревни!$b$bПодозреваю даже, что некоторых жителей удерживают там насильно. Если найдешь их, |3-6($c), передай им, что пора вернуться домой.','Убедите 12 пандаренов-добровольцев уйти со Взлетной полосы Сильной Руки.','Вернитесь к торговцу Цзыню в Закуток Конка, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ненадежные союзники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала мы тепло встретили Альянс. Некоторые жители деревни даже вызвались помочь чужакам в строительстве взлетной полосы. И лишь недавно мы осознали, что на самом деле там строят военную базу, в двух шагах от деревни!$b$bПодозреваю даже, что некоторых жителей удерживают там насильно. Если найдешь их, |3-6($c), передай им, что пора вернуться домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убедите 12 пандаренов-добровольцев уйти со Взлетной полосы Сильной Руки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу Цзыню в Закуток Конка, что в Нефритовом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31779,'Тьма внутри','Тебе там случайно не попадался на глаза капитан Дорен?$b$bЭтот хлюпик где-то прячется. Если его нет на воздушной базе, значит он укрылся поблизости! Обыщи периметр базы, проверь пещеру к юго-западу от главного аэродрома. Я хочу, чтобы Альянс свалил отсюда!','Убейте капитана Дорена.','Альянс отступает. Теперь тебе, Назгриму, Кирин, Горроку, Шокии и Риветту понадобится база для вылазок.$B$BНужно поменять эти флаги.$B$BЗа Орду!','Поменяйте флаг в центре Взлетной полосы Сильной Руки, что в Нефритовом лесу.','Дорен – командир Сильной Руки. Нужно его убить!','Капитан Дорен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тьма внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе там случайно не попадался на глаза капитан Дорен?$b$bЭтот хлюпик где-то прячется. Если его нет на воздушной базе, значит он укрылся поблизости! Обыщи периметр базы, проверь пещеру к юго-западу от главного аэродрома. Я хочу, чтобы Альянс свалил отсюда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана Дорена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альянс отступает. Теперь тебе, Назгриму, Кирин, Горроку, Шокии и Риветту понадобится база для вылазок.$B$BНужно поменять эти флаги.$B$BЗа Орду!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поменяйте флаг в центре Взлетной полосы Сильной Руки, что в Нефритовом лесу.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Дорен – командир Сильной Руки. Нужно его убить!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан Дорен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31780,'Старик Макдональд','В этот раз я тебе доставлю хлопот!','Победите старика Макдональда в битве питомцев.','Выходит, мне еще многому предстоит научиться.','Поговорите со стариком Макдональдом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старик Макдональд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этот раз я тебе доставлю хлопот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите старика Макдональда в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выходит, мне еще многому предстоит научиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со стариком Макдональдом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31781,'Линдси','Что, хочешь меня одолеть? Я всегда готова к бою.','Победите Линдси в битве питомцев.','Так неинтересно!','Поговорите с Линдси.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Линдси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, хочешь меня одолеть? Я всегда готова к бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Линдси в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так неинтересно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Линдси.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31782,'Свержение','Совет принял решение, Пробудитель.$b$bС помощью ритуала мы покончим с императрицей и обеспечим будущее нашей великой империи.$b$bУзри же силу клакси!','Мы еще не закончили, Пробудитель.$B$BТвоя помощь оказалась для нас крайне полезной.$B$BОт имени оставшихся членов совета я прошу тебя продолжить начатое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свержение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совет принял решение, Пробудитель.$b$bС помощью ритуала мы покончим с императрицей и обеспечим будущее нашей великой империи.$b$bУзри же силу клакси!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы еще не закончили, Пробудитель.$B$BТвоя помощь оказалась для нас крайне полезной.$B$BОт имени оставшихся членов совета я прошу тебя продолжить начатое.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31785,'Новый уровень!','Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!','Повысьте уровень питомца до 3-го.','Вернитесь к Маркусу Йенсену в Златоземье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый уровень!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Повысьте уровень питомца до 3-го.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маркусу Йенсену в Златоземье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31786,'Безупречные оковы мятежника','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.','Выставите артефакт на обозрение.','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.','Уберите хлам и выставите артефакт на обозрение.','Выставите артефакт в Обители Мудрости..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречные оковы мятежника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выставите артефакт на обозрение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уберите хлам и выставите артефакт на обозрение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выставите артефакт в Обители Мудрости..',`completedtext_loc8`);
