INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31808,'Механическая ярость','Ковок развивается с потрясающей скоростью. Возможно, годы спячки повлияли на его процесс роста?...$b$bКак бы то ни было, это как нельзя кстати. Самое время проверить, на что он способен.$b$b$n, ты так много $gсделал:сделала; для его обучения – тебе и управлять им сегодня!$b$bЯ уже подвел его к краю рва. Найди его и уничтожь армию Шек\'зир!','Уничтожьте 200 богомолов, управляя Ковоком во рве.','Я увидел картину битвы в твоем сознании. Это была настоящая бойня. Замечательно!','Поговорите с Каз\'тиком Манипулятором в Клакси\'весс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Механическая ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ковок развивается с потрясающей скоростью. Возможно, годы спячки повлияли на его процесс роста?...$b$bКак бы то ни было, это как нельзя кстати. Самое время проверить, на что он способен.$b$b$n, ты так много $gсделал:сделала; для его обучения – тебе и управлять им сегодня!$b$bЯ уже подвел его к краю рва. Найди его и уничтожь армию Шек\'зир!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 200 богомолов, управляя Ковоком во рве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я увидел картину битвы в твоем сознании. Это была настоящая бойня. Замечательно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Каз\'тиком Манипулятором в Клакси\'весс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (31809,'Глядя на отрубленный коготь лапы Ша Злости, вы понимаете, что о вашей победе непременно захочет узнать Бань Медвежье Сердце, командир монахов Шадо-Пан в Танлунских степях.','<Вы отдаете коготь Баню, и его глаза округляются от удивления – он понимает, что именно вы сделали.>$B$BТеперь мне ясно, что произошло.$B$BТы совершил невозможное. Твое имя войдет в хроники Шадо-Пан, и пока мы живы, мы будем почитать тебя.','<Бань с прищуром смотрит на вас.>$B$BТы какой-то другой. Ты изменился.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глядя на отрубленный коготь лапы Ша Злости, вы понимаете, что о вашей победе непременно захочет узнать Бань Медвежье Сердце, командир монахов Шадо-Пан в Танлунских степях.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы отдаете коготь Баню, и его глаза округляются от удивления – он понимает, что именно вы сделали.>$B$BТеперь мне ясно, что произошло.$B$BТы совершил невозможное. Твое имя войдет в хроники Шадо-Пан, и пока мы живы, мы будем почитать тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Бань с прищуром смотрит на вас.>$B$BТы какой-то другой. Ты изменился.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31812,'Зунта, укротитель питомцев','Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bЗунту можно найти у фермы Тор\'кренов, это к югу от Оргриммара. Он – начинающий укротитель диких питомцев и, думаю, тебе стоит вызвать его на поединок!','Победите Зунту в битве питомцев.','А, Варзок. Да, я хорошо его знаю. Он правильно сделал, что прислал тебя сюда.','Поговорите с Зунтой.','Испытай себя, сразившись с Зунтой!','Зунта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зунта, укротитель питомцев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу сказать, что тебе удалось заметно улучшить свои навыки, $n. Думаю, пришло время для более серьезного испытания.$b$bЗунту можно найти у фермы Тор\'кренов, это к югу от Оргриммара. Он – начинающий укротитель диких питомцев и, думаю, тебе стоит вызвать его на поединок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зунту в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, Варзок. Да, я хорошо его знаю. Он правильно сделал, что прислал тебя сюда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зунтой.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Испытай себя, сразившись с Зунтой!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Зунта',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31813,'Дагра Яростная','Тут неподалеку есть еще один укротитель. Попробуй-ка сразиться с ней!$b$bДагра Яростная будет тебя ждать на северном склоне Тернистого холма, к востоку от Перекрестка. Победишь ее – получишь заслуженную награду.','Победите Дагру Яростную в битве питомцев.','Ты сражаешься с упорством не боящегося поражений существа – и не терпящего их. Ты далеко пойдешь.','Поговорите с Дагрой Яростной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дагра Яростная',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут неподалеку есть еще один укротитель. Попробуй-ка сразиться с ней!$b$bДагра Яростная будет тебя ждать на северном склоне Тернистого холма, к востоку от Перекрестка. Победишь ее – получишь заслуженную награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дагру Яростную в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сражаешься с упорством не боящегося поражений существа – и не терпящего их. Ты далеко пойдешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дагрой Яростной.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31814,'Аналинн','Решимость ничего не значит, если не найти ей достойного применения.$b$bРазыщи на дорогах западного Ясеневого леса Аналинн. Она немного... эксцентричная... но укротитель из нее отменный! Если сумеешь ее победить, твоя команда станет только сильнее!','Победите Аналинн в битве питомцев.','Тебе не понять. Это не поражение, а просто досадная оплошность.','Поговорите с Аналинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аналинн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Решимость ничего не значит, если не найти ей достойного применения.$b$bРазыщи на дорогах западного Ясеневого леса Аналинн. Она немного... эксцентричная... но укротитель из нее отменный! Если сумеешь ее победить, твоя команда станет только сильнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Аналинн в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе не понять. Это не поражение, а просто досадная оплошность.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аналинн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31815,'Зоня Садистка','$n, появилась прекрасная возможность, и, я думаю, ты будешь в ней $gзаинтересован:заинтересована;.$b$bЗоня Садистка из южной части Когтистых гор снова участвует в поединках. Думаю, тебе стоит встретиться с ней, чтобы отточить свои навыки укротителя питомцев.','Победите Зоню Садистку в битве питомцев.','Поговорите с Зоней Садисткой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зоня Садистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, появилась прекрасная возможность, и, я думаю, ты будешь в ней $gзаинтересован:заинтересована;.$b$bЗоня Садистка из южной части Когтистых гор снова участвует в поединках. Думаю, тебе стоит встретиться с ней, чтобы отточить свои навыки укротителя питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зоню Садистку в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зоней Садисткой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31816,'Предатель Глак','Are you up for an adventure? Bill the Pirate, local star tamer down in the Cape of Stranglethorn, has issued an open challenge to prepared trainers!$b$bYou can find Bill the Pirate in the southern Cape of Stranglethorn, walking the local roads to find potential fights.','Defeat Bill the Pirate in a pet battle.','Make him walk the plank!','Marcus Jensen','Wonderful!','Marcus Jensen') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель Глак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Are you up for an adventure? Bill the Pirate, local star tamer down in the Cape of Stranglethorn, has issued an open challenge to prepared trainers!$b$bYou can find Bill the Pirate in the southern Cape of Stranglethorn, walking the local roads to find potential fights.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Defeat Bill the Pirate in a pet battle.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Make him walk the plank!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Marcus Jensen',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Wonderful!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Marcus Jensen',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31817,'Мерда Могучее Копыто','$gГотов:Готова:r; к настоящей проверке твоего мастерства, |3-6($r)?$b$bМерда Могучее Копыто разбила лагерь в местечке, которое называют Просекой Карнума. Это в Пустошах. Поединок с таким сильным укротителем питомцев, как она, станет для тебя хорошей проверкой, не так ли?','Победите Мерду Могучее Копыто в битве питомцев.','Вся мощь Пустошей не сравнится с твоим желанием расти над собой. Я восхищаюсь усилиями, которые ты прилагаешь.','Поговорите с Мердой Могучее Копыто.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерда Могучее Копыто',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gГотов:Готова:r; к настоящей проверке твоего мастерства, |3-6($r)?$b$bМерда Могучее Копыто разбила лагерь в местечке, которое называют Просекой Карнума. Это в Пустошах. Поединок с таким сильным укротителем питомцев, как она, станет для тебя хорошей проверкой, не так ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мерду Могучее Копыто в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вся мощь Пустошей не сравнится с твоим желанием расти над собой. Я восхищаюсь усилиями, которые ты прилагаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мердой Могучее Копыто.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31818,'Зунта','Думаешь, что сможешь снова меня одолеть?','Победите Зунту в битве питомцев.','Ладно, чувак! Сдаюсь!','Поговорите с Зунтой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зунта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, что сможешь снова меня одолеть?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зунту в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, чувак! Сдаюсь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зунтой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31819,'Дагра Яростная','В этот раз ты встретишь на горе собственную смерть.','Победите Дагру Яростную в битве питомцев.','Это невозможно!','Поговорите с Дагрой Яростной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дагра Яростная',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этот раз ты встретишь на горе собственную смерть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дагру Яростную в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это невозможно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дагрой Яростной.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31820,'Подарок для учителя','Я полностью догнал других детей, даже несмотря на то, что начал гораздо позже. И теперь я могу посещать обычные уроки вместе со всеми!$b$bЯ сделал для тебя фартук, чтобы показать, как я ценю все то, что ты для меня $gсделал:сделала;. Надеюсь, тебе нравится?','Получите подарок от Номи.','Я так тебе благодарен.','Получите подарок от Номи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок для учителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я полностью догнал других детей, даже несмотря на то, что начал гораздо позже. И теперь я могу посещать обычные уроки вместе со всеми!$b$bЯ сделал для тебя фартук, чтобы показать, как я ценю все то, что ты для меня $gсделал:сделала;. Надеюсь, тебе нравится?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите подарок от Номи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так тебе благодарен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Получите подарок от Номи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31821,'Новый уровень!','Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!','Повысьте уровень питомца до 3-го.','Вернитесь к Одри Бернхеп в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый уровень!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замечательно. Очень важно следить за здоровьем питомца, чтобы он всегда был готов к битве.$b$bВот мое следующее задание: проведи несколько битв и повысь уровень одного питомца до 3-го. После этого возвращайся ко мне и мы поговорим о том, как научиться ловить питомцев для себя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Повысьте уровень питомца до 3-го.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Одри Бернхеп в Штормград.',`completedtext_loc8`);
