INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (31847,'Жуткое место','Я уверен, многие наши союзники захотят прибегнуть к твоим услугам после нашей победы. Но сейчас я получил просьбу о помощи от защитников стены в Жутких пустошах.\r\n\r\nЕсли хочешь откликнуться на их призыв, бери воздушного змея и отправляйся к лучнице Ли.','Доброволец для наблюдения за Жуткими пустошами? Первый раз вижу такое чудо.$B$BРада, что ты здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жуткое место',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, многие наши союзники захотят прибегнуть к твоим услугам после нашей победы. Но сейчас я получил просьбу о помощи от защитников стены в Жутких пустошах.\r\n\r\nЕсли хочешь откликнуться на их призыв, бери воздушного змея и отправляйся к лучнице Ли.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Доброволец для наблюдения за Жуткими пустошами? Первый раз вижу такое чудо.$B$BРада, что ты здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31850,'Эрик Дэвидсон','Итак, ты снова $gявился:явилась; в лес, чтобы вызвать меня на бой. Мои смертоносные питомцы принимают твой дерзкий вызов.','Победите Эрика Дэвидсона в битве питомцев.','Что ж, ты рискнул и одержал победу.','Поговорите с Эриком Дэвидсоном.','Превосходно!','Маркус Йенсен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрик Дэвидсон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, ты снова $gявился:явилась; в лес, чтобы вызвать меня на бой. Мои смертоносные питомцы принимают твой дерзкий вызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эрика Дэвидсона в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты рискнул и одержал победу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эриком Дэвидсоном.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Превосходно!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Маркус Йенсен',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31851,'Билл Баклер','Ну что, $gявился:явилась; попробовать еще разок?$B$BСейаас узнаешь, почему меня называют "ужасом долины".','Победите Билла Баклера в битве питомцев.','Хорошо, сегодня ты победил, приятель. Но в следующий раз я тебе спуску не дам.','Поговорите с Биллом Баклером.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Билл Баклер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, $gявился:явилась; попробовать еще разок?$B$BСейаас узнаешь, почему меня называют "ужасом долины".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Билла Баклера в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, сегодня ты победил, приятель. Но в следующий раз я тебе спуску не дам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Биллом Баклером.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31852,'Стивен Лисбен','Ты осмеливаешься снова бросить мне вызов? На этот раз я выйду победителем в битве!','Победите Стивена Лисбена в битве питомцев.','Захватывающий поединок! Славный бой!','Поговорите со Стивеном Лисбеном.','Ну и зрелище!','Маркус Йенсен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стивен Лисбен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты осмеливаешься снова бросить мне вызов? На этот раз я выйду победителем в битве!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Стивена Лисбена в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Захватывающий поединок! Славный бой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со Стивеном Лисбеном.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ну и зрелище!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Маркус Йенсен',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31853,'Все на борт!','$gСлыхал:Слыхала;, $n? Мне нужна команда опытных бойцов для опасного задания.$b$bНужно как следует потрепать Альянс, и ты отправляешься со мной!$b$bМы не вернемся, пока не выполним задачу, так что собирай вещи и готовься.$b$bЯ буду на борту свежеотстроенного боевого судна над бухтой Острорука.$b$bНе заставляй меня ждать!','Поговорите с генералом Назгримом на борту корабля "Кулак Адского Крика".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все на борт!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gСлыхал:Слыхала;, $n? Мне нужна команда опытных бойцов для опасного задания.$b$bНужно как следует потрепать Альянс, и ты отправляешься со мной!$b$bМы не вернемся, пока не выполним задачу, так что собирай вещи и готовься.$b$bЯ буду на борту свежеотстроенного боевого судна над бухтой Острорука.$b$bНе заставляй меня ждать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Назгримом на борту корабля "Кулак Адского Крика".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31854,'Аналинн','Вижу, ты снова меня $gнашел:нашла;. Видимо, хочешь снова вызвать меня на бой? Что ж, я не против.','Победите Аналинн в битве питомцев.','Твои питомцы ликуют. Надеюсь, ты тоже наслаждаешься своей победой.','Поговорите с Аналинн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аналинн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты снова меня $gнашел:нашла;. Видимо, хочешь снова вызвать меня на бой? Что ж, я не против.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Аналинн в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои питомцы ликуют. Надеюсь, ты тоже наслаждаешься своей победой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аналинн.',`completedtext_loc8`);
