INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31862,'Зоня Садистка','Добыча сама идет в лапы хищника, даже не подозревая об опасности. На этот раз Зоня с тобой позабавится.','Победите Зоню Садистку в битве питомцев.','Думаешь, что победил меня? На самом деле с каждым поражением я становлюсь сильнее.','Поговорите с Зоней Садисткой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зоня Садистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добыча сама идет в лапы хищника, даже не подозревая об опасности. На этот раз Зоня с тобой позабавится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зоню Садистку в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаешь, что победил меня? На самом деле с каждым поражением я становлюсь сильнее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Зоней Садисткой.',`completedtext_loc8`);
