INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31870,'Кассандра Бахбах','Кассандра Бахбах – очень хороший укротитель. Она известна своей любовью к механическим питомцам. Если победишь ее – сделаешь еще один шаг в сторону победы.$B$BКогда найдешь ее в Южных степях рядом с шахтерским городком Дранфикса – вызови на дуэль. Если тебе удастся победить, то твой авторитет в глазах Варзока несомненно возрастет.$B$BУдачи.','Победите Кассандру Бахбах в битве питомцев.','Ух ты! А ты крепкий орешек!','Поговорите с Кассандрой Бахбах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кассандра Бахбах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кассандра Бахбах – очень хороший укротитель. Она известна своей любовью к механическим питомцам. Если победишь ее – сделаешь еще один шаг в сторону победы.$B$BКогда найдешь ее в Южных степях рядом с шахтерским городком Дранфикса – вызови на дуэль. Если тебе удастся победить, то твой авторитет в глазах Варзока несомненно возрастет.$B$BУдачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Кассандру Бахбах в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! А ты крепкий орешек!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кассандрой Бахбах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31871,'Предатель Глак','Ты победить Глака до этого, но сегодня Глак открутить голову $gничтожному:ничтожному:r; |3-2($r).','Победите предателя Глака в битве питомцев.','Нет! Только не проиграть! Давай снова!','Поговорите с предателем Глаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель Глак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты победить Глака до этого, но сегодня Глак открутить голову $gничтожному:ничтожному:r; |3-2($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите предателя Глака в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет! Только не проиграть! Давай снова!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с предателем Глаком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31872,'Мерда Могучее Копыто','Как изо дня в день земля питает урожай, так и моя команда становится все сильнее и сильнее. Ты действительно хочешь сразиться со мной? Просто сразу признай свое поражение, в этом нет ничего страшного.','Победите Мерду Могучее Копыто в битве питомцев.','Заслуженная победа. Твой дар в подготовке питомцев больше моего.','Поговорите с Мердой Могучее Копыто.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерда Могучее Копыто',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как изо дня в день земля питает урожай, так и моя команда становится все сильнее и сильнее. Ты действительно хочешь сразиться со мной? Просто сразу признай свое поражение, в этом нет ничего страшного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мерду Могучее Копыто в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Заслуженная победа. Твой дар в подготовке питомцев больше моего.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мердой Могучее Копыто.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31876,'Мастера каллиграфии Дендрария','Мне говорили, что мастерам каллиграфии в Дендрарии требуется помощь умелого начертателя. Если хочешь помочь, поговори с мастером каллиграфии Вэем.','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.','А, опытный начертатель. Некоторым из нас действительно не помешает твоя помощь.','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастера каллиграфии Дендрария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне говорили, что мастерам каллиграфии в Дендрарии требуется помощь умелого начертателя. Если хочешь помочь, поговори с мастером каллиграфии Вэем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, опытный начертатель. Некоторым из нас действительно не помешает твоя помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером каллиграфии Вэем в Дендрарии, что в Нефритовом лесу.',`completedtext_loc8`);
