INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31889,'Укротители боевых питомцев: Калимдор','Теперь, когда ты $gотточил:отточила; свои навыки, время заняться битвами питомцев всерьез.$b$bЯ хочу, чтобы ты $gпобедил:победила; пятерых укротителей боевых питомцев Калимдора: предателя Глака в Фераласе, Греззла Великого в Пылевых топях, Келу Зловещий Тотем в Тысяче Игл, Золтана в Оскверненном лесу и Елену Порхающую Бабочку на Лунной поляне.$b$bЕсли тебе удастся одержать над ними верх, ты сможешь двигаться дальше.','Победите предателя Глака, Греззла Великого, Келу Зловещий Тотем, Золтана и Елену Порхающую Бабочку в битвах питомцев.','Вот это да! Действительно, впечатляюще.','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Калимдор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gотточил:отточила; свои навыки, время заняться битвами питомцев всерьез.$b$bЯ хочу, чтобы ты $gпобедил:победила; пятерых укротителей боевых питомцев Калимдора: предателя Глака в Фераласе, Греззла Великого в Пылевых топях, Келу Зловещий Тотем в Тысяче Игл, Золтана в Оскверненном лесу и Елену Порхающую Бабочку на Лунной поляне.$b$bЕсли тебе удастся одержать над ними верх, ты сможешь двигаться дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите предателя Глака, Греззла Великого, Келу Зловещий Тотем, Золтана и Елену Порхающую Бабочку в битвах питомцев.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Вот это да! Действительно, впечатляюще.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Одри Бернхеп',`questturntargetname_loc8`);
