INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31894,'Хрупкое равновесие','Поговорите с Орбиссом, который находится в Камышовых топях.','<Орбисс стонет, глядя на вас.>$B$BЗначит, Шадо-Пан прислал тебя понаблюдать за яунголами? Ну, ты видишь, что они делают?','Поговорите с Орбиссом в Камышовых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрупкое равновесие',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Орбиссом, который находится в Камышовых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орбисс стонет, глядя на вас.>$B$BЗначит, Шадо-Пан прислал тебя понаблюдать за яунголами? Ну, ты видишь, что они делают?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Орбиссом в Камышовых топях.',`completedtext_loc8`);
