INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31897,'Великая укротительница Трикси','Укротители в Калимдоре говорят о тебе. Это ты $gтот выскочка, что наделал:та выскочка, что наделала; столько шума. Заходи на мою тренировочную площадку на холмах Ледополоха в Зимних ключах, я покажу тебе, как сражаются мастера.','Победите Ледяную Трикси в битве питомцев.','А ты ничего для новичка! Но в следующий раз тебе так не повезет!','Поговорите с Ледяной Трикси.','Думаешь, у тебя хватит духу?','Ледяная Трикси') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Трикси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Укротители в Калимдоре говорят о тебе. Это ты $gтот выскочка, что наделал:та выскочка, что наделала; столько шума. Заходи на мою тренировочную площадку на холмах Ледополоха в Зимних ключах, я покажу тебе, как сражаются мастера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ледяную Трикси в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты ничего для новичка! Но в следующий раз тебе так не повезет!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ледяной Трикси.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Думаешь, у тебя хватит духу?',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ледяная Трикси',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31903,'Укротители боевых питомцев: Восточные королевства','Победите Дэвида Косса, Дейзу Плейгхорн, Кортана Даркхаммера, Эверессу и Дурина Черномолота в битвах питомцев.','Я никогда не сомневался в тебе.','Варзок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Восточные королевства',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дэвида Косса, Дейзу Плейгхорн, Кортана Даркхаммера, Эверессу и Дурина Черномолота в битвах питомцев.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Я никогда не сомневался в тебе.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Варзок',`questturntargetname_loc8`);
