INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31908,'Елена Порхающая Бабочка','Вижу, ты $gподготовился:подготовился; к очередной воздушной схватке. Ну что, полетели?','Победите Елену Порхающую Бабочку в битве питомцев.','Иду на посадку. Ты победил.','Поговорите с Еленой Порхающей Бабочкой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Елена Порхающая Бабочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты $gподготовился:подготовился; к очередной воздушной схватке. Ну что, полетели?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Елену Порхающую Бабочку в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Иду на посадку. Ты победил.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Еленой Порхающей Бабочкой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31909,'Великая укротительница Трикси','Замри! Ты уже $gотогрелся:отогрелась; после нашей прошлой встречи? Что ж, давай это исправим.','Победите Ледяную Трикси в битве питомцев.','Ты такой горячий!','Поговорите с Ледяной Трикси.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Трикси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замри! Ты уже $gотогрелся:отогрелась; после нашей прошлой встречи? Что ж, давай это исправим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ледяную Трикси в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты такой горячий!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ледяной Трикси.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31910,'Дэвид Косс','Мои исследования позволили значительно увеличить потенциал моей команды. Теперь мне обеспечена победа в бою.','Победите Дэвида Косса в битве питомцев.','Хм, по-видимому, мои исследования еще далеки от завершения.','Поговорите с Дэвидом Коссом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дэвид Косс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои исследования позволили значительно увеличить потенциал моей команды. Теперь мне обеспечена победа в бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дэвида Косса в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, по-видимому, мои исследования еще далеки от завершения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дэвидом Коссом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31911,'Дэйза Плейгхорн','Ты еще не $gсвернул:свернула; на истинный путь – путь нежити. Возможно, этот бой выведет тебя на верную дорогу.','Победите Дэйзу Плейгхорн в битве питомцев.','Возможно, нежитие – не совсем верный путь…','Поговорите с Дэйзой Плейгхорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дэйза Плейгхорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты еще не $gсвернул:свернула; на истинный путь – путь нежити. Возможно, этот бой выведет тебя на верную дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дэйзу Плейгхорн в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, нежитие – не совсем верный путь…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дэйзой Плейгхорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31912,'Кортан Черномолот','Слышал, что ты победил моего туповатого братца. Это так?$B$BЗначит, настал час моего триумфа!','Победите Кортана Черномолота в битве питомцев.','Ты ничем не лучше Дурина – лишь бы только прославиться! Мда.','Поговорите с Кортаном Черномолотом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кортан Черномолот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышал, что ты победил моего туповатого братца. Это так?$B$BЗначит, настал час моего триумфа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Кортана Черномолота в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты ничем не лучше Дурина – лишь бы только прославиться! Мда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кортаном Черномолотом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31913,'Эвересса','Вскоре я познаю все боевые секреты и стану непобедима.','Победите Эверессу в битве питомцев.','Вижу, ты тоже знаешь пару трюков.','Поговорите с Эверессой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эвересса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вскоре я познаю все боевые секреты и стану непобедима.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Эверессу в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты тоже знаешь пару трюков.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эверессой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31914,'Дурин Черномолот','Пока я служил Повелителю огня, я всякого насмотрелся. Какие бы трюки ты ни $gвыкинул:выкинула;, меня не остановишь!','Победите Дурина Черномолота в битве питомцев.','Клянусь жизнью, я тебя одолею. Не зря же я потратил столько времени на подготовку.','Поговорите с Дурином Черномолотом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурин Черномолот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока я служил Повелителю огня, я всякого насмотрелся. Какие бы трюки ты ни $gвыкинул:выкинула;, меня не остановишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дурина Черномолота в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь жизнью, я тебя одолею. Не зря же я потратил столько времени на подготовку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дурином Черномолотом.',`completedtext_loc8`);
