INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31920,'Великий укротитель Антари','Мне приходилось встречать таких, как ты. Таких же молодых и наивных укротителей, которые считают, что победу им должны поднести на блюдечке с голубой каемочкой.$B$BКак же! Настало время настоящей битвы, |3-6($c)! Я, рыцарь крови Антари из Долины Призрачной Луны, собираюсь показать тебе, что значит поражение!','Победите рыцаря крови Антари в битве питомцев.','Это невозможно! Я не могу проиграть!','Поговорите с рыцарем крови Антари.','У тебя нет шансов.','Рыцарь крови Антари') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Антари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне приходилось встречать таких, как ты. Таких же молодых и наивных укротителей, которые считают, что победу им должны поднести на блюдечке с голубой каемочкой.$B$BКак же! Настало время настоящей битвы, |3-6($c)! Я, рыцарь крови Антари из Долины Призрачной Луны, собираюсь показать тебе, что значит поражение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите рыцаря крови Антари в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это невозможно! Я не могу проиграть!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем крови Антари.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','У тебя нет шансов.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рыцарь крови Антари',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31921,'Укротители боевых питомцев: Запределье','Победите Ники Мелкотех, Рас\'ана, Наррока и Морулу Древнего в битвах питомцев.','Пусть битвы принесут тебе славу.','Варзок','Вот и еще один этап твоего пути завершен.','Варзок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Запределье',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ники Мелкотех, Рас\'ана, Наррока и Морулу Древнего в битвах питомцев.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пусть битвы принесут тебе славу.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Варзок',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Вот и еще один этап твоего пути завершен.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Варзок',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31922,'Ники Мелкотех','Согласно моим расчетам вероятность твоей победы составляет 32,333%. Приемлемый для меня риск.','Победите Ники Мелкотех в битве питомцев.','Да, забыл приписать единичку!','Поговорите с Ники Мелкотех.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ники Мелкотех',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно моим расчетам вероятность твоей победы составляет 32,333%. Приемлемый для меня риск.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ники Мелкотех в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, забыл приписать единичку!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ники Мелкотех.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31923,'Рас\'ан','Хочешь сразиться снова? Я хорошо подготовился к битве.','Победите Рас\'ана в битве питомцев.','Отличная работа!','Поговорите с Рас\'аном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рас\'ан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь сразиться снова? Я хорошо подготовился к битве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Рас\'ана в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Рас\'аном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31924,'Наррок','Хочу снова принять участие в бою. Нужно дрессировать малышей.','Победите Наррока в битве питомцев.','Что ж, моим новичкам предстоит еще многому научиться. Спасибо за бой.','Поговорите с Нарроком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наррок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу снова принять участие в бою. Нужно дрессировать малышей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Наррока в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, моим новичкам предстоит еще многому научиться. Спасибо за бой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Нарроком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31925,'Морулу Древний','Я многому научился с нашей последней встречи. Хочешь попробовать еще раз?','Победите Морулу Древнего в битве питомцев.','Даже я нахожу в каждом дне что-то новое для себя.','Поговорите с Морулу Древним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морулу Древний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я многому научился с нашей последней встречи. Хочешь попробовать еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Морулу Древнего в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Даже я нахожу в каждом дне что-то новое для себя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Морулу Древним.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31926,'Великий укротитель Антари','В прошлый раз ты $gвоспользовался:воспользовалась; моей оплошностью, чтобы вырвать победу из моих рук. Сегодня я не дам тебе ни малейшего шанса, |3-6($r).','Победите рыцаря крови Антари в битве питомцев.','Глупец, думаешь, ты сильнее меня. Клянусь тебе, победа будет за мной!','Поговорите с рыцарем крови Антари.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Антари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В прошлый раз ты $gвоспользовался:воспользовалась; моей оплошностью, чтобы вырвать победу из моих рук. Сегодня я не дам тебе ни малейшего шанса, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите рыцаря крови Антари в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глупец, думаешь, ты сильнее меня. Клянусь тебе, победа будет за мной!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с рыцарем крови Антари.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31927,'Укротители боевых питомцев: Нордскол','Победите Бигла Фитиля, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.','Покажи им, кто здесь лучший!','Одри Бернхеп','Ну что, начнем?','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Нордскол',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Бигла Фитиля, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Покажи им, кто здесь лучший!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Одри Бернхеп',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ну что, начнем?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Одри Бернхеп',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31928,'Великий укротитель Пейн','Я считаю, что остальные укротители были к тебе слишком снисходительны.$B$BОт настоящего укротителя требуется почти военная дисциплина! Я подарю тебе возможность своими глазами увидеть, к каким результатом она приводит!$B$BПриходи на Ристалище Серебряного турнира в Ледяную корону – и увидишь, каких высот ты можешь достичь!','Победите майора Пейна в битве питомцев.','Поговорите с майором Пейном.','За Альянс!','Майор Пейн') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Пейн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я считаю, что остальные укротители были к тебе слишком снисходительны.$B$BОт настоящего укротителя требуется почти военная дисциплина! Я подарю тебе возможность своими глазами увидеть, к каким результатом она приводит!$B$BПриходи на Ристалище Серебряного турнира в Ледяную корону – и увидишь, каких высот ты можешь достичь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите майора Пейна в битве питомцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с майором Пейном.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','За Альянс!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Майор Пейн',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31929,'Укротители боевых питомцев: Нордскол','Победите Бигла Фитиля, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.','Я не проиграю!','Варзок','Тебя ждет самое сложное испытание.','Варзок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Нордскол',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Бигла Фитиля, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я не проиграю!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Варзок',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Тебя ждет самое сложное испытание.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Варзок',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31930,'Укротители боевых питомцев: Пандария','Победите Хюну Хранительницу Святилищ, фермера Ниши, Мо\'рука, Отважного Юня, искателя Зусши и странника пустошей Шу в битвах питомцев.','Уже почти все!','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Пандария',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Хюну Хранительницу Святилищ, фермера Ниши, Мо\'рука, Отважного Юня, искателя Зусши и странника пустошей Шу в битвах питомцев.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Уже почти все!',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Одри Бернхеп',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31931,'Бигл Фитиль','Клянусь, я видел, как один из моих цеплят вчера полетел! Недолгий был полет, но все-таки. Теперь нас точно ждет большая победа!$B$BО, хочешь сразиться снова?','Победите Бигла Фитиля в битве питомцев.','Однажды мы взлетим, а ты падешь!','Поговорите с Биглом Фитилем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бигл Фитиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клянусь, я видел, как один из моих цеплят вчера полетел! Недолгий был полет, но все-таки. Теперь нас точно ждет большая победа!$B$BО, хочешь сразиться снова?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Бигла Фитиля в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Однажды мы взлетим, а ты падешь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Биглом Фитилем.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31932,'Почти Безголовый Якоб','Ты снова и снова оказываешься мудрее меня. Зачем ты приходишь в эти леса?$B$BА, ты хочешь сразиться еще раз. Ну хорошо.','Победите Почти Безголового Якоба в битве питомцев.','Твой риск оказался оправданным. А теперь уходи!','Поговорите с Почти Безголовым Якобом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почти Безголовый Якоб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты снова и снова оказываешься мудрее меня. Зачем ты приходишь в эти леса?$B$BА, ты хочешь сразиться еще раз. Ну хорошо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Почти Безголового Якоба в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой риск оказался оправданным. А теперь уходи!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Почти Безголовым Якобом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31933,'Окрут Убийца Драконов','Как ты смеешь меня отвлекать?! Но раз $gотвлек:отвлекла; – давай сражаться! Доставай своих питомцев, я тебе покажу гнев Адского Крика!','Победите Окрута Убийцу Драконов в битве питомцев.','Сразись с неизбежным! Драконы снова послужат нам, а ты падешь от моей руки в битве питомцев. Клянусь плащом Вождя, так и будет!','Поговорите с Окрутом Убийцей Драконов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окрут Убийца Драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты смеешь меня отвлекать?! Но раз $gотвлек:отвлекла; – давай сражаться! Доставай своих питомцев, я тебе покажу гнев Адского Крика!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Окрута Убийцу Драконов в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразись с неизбежным! Драконы снова послужат нам, а ты падешь от моей руки в битве питомцев. Клянусь плащом Вождя, так и будет!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Окрутом Убийцей Драконов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31934,'Гатреч','Моя любить биться! С тобой не так легко, как с другими! Еще бой?','Победите Гатреча в битве питомцев.','Моя любить биться с тобой! Даже если моя проигрывать!','Поговорите с Гатречем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гатреч',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя любить биться! С тобой не так легко, как с другими! Еще бой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Гатреча в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя любить биться с тобой! Даже если моя проигрывать!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гатречем.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31935,'Великий укротитель Пейн','О, $gмятежный:мятежная:c; |3-6($c) $gвернулся:вернулась;, чтобы еще раз испытать свои силы в бою с великим укротителем. Твоя храбрость тебя погубит!','Победите майора Пейна в битве питомцев.','Потрясающая тактика, Элдр, хоть твоя победа меня и разочаровала. Ты молодец.','Поговорите с майором Пейном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Пейн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $gмятежный:мятежная:c; |3-6($c) $gвернулся:вернулась;, чтобы еще раз испытать свои силы в бою с великим укротителем. Твоя храбрость тебя погубит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите майора Пейна в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающая тактика, Элдр, хоть твоя победа меня и разочаровала. Ты молодец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с майором Пейном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31936,'Поливная система "Принцесса цзинь-юй"','<На обратной стороне коробки рисунок – девушка-цзинь-юй в окружении рекламных проспектов.>$B$B"Эй, огородник! Все еще грустишь по засохшим тыквам? Плачешь над увядшей капустой? У тебя луковые страдания и дынная меланхолия?$B$BТогда купи "Принцессу цзинь-юй"! Она омоет твой сад, словно чудесный весенний дождь, она напоит..."$B$B<И так далее в том же духе еще шесть абзацев.>"','Отнесите поливную систему "Принцесса цзинь-юй" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.','Поливная система? Специально для фермеров? Спасибо, Нуклеотид! Все лучше, чем бегать вдоль грядок с лейкой.$B$B"Принцесса цзинь-юй"? С чего вдруг?$B$B<Юн переворачивает коробку и начинает читать.>$B$BНу ладно, я даже думать об этом не хочу. Просто возьму и установлю сейчас эту штуку!','Отнесите поливную систему "Принцесса цзинь-юй" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поливная система "Принцесса цзинь-юй"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<На обратной стороне коробки рисунок – девушка-цзинь-юй в окружении рекламных проспектов.>$B$B"Эй, огородник! Все еще грустишь по засохшим тыквам? Плачешь над увядшей капустой? У тебя луковые страдания и дынная меланхолия?$B$BТогда купи "Принцессу цзинь-юй"! Она омоет твой сад, словно чудесный весенний дождь, она напоит..."$B$B<И так далее в том же духе еще шесть абзацев.>"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите поливную систему "Принцесса цзинь-юй" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поливная система? Специально для фермеров? Спасибо, Нуклеотид! Все лучше, чем бегать вдоль грядок с лейкой.$B$B"Принцесса цзинь-юй"? С чего вдруг?$B$B<Юн переворачивает коробку и начинает читать.>$B$BНу ладно, я даже думать об этом не хочу. Просто возьму и установлю сейчас эту штуку!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите поливную систему "Принцесса цзинь-юй" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (31937,'Инсектицид "Властелин Грома"','<На коробке изображена грозная физиономия могу – существо смотрит вниз, на аккуратные строчки.>$B$B"НЕ ДАЙТЕ СЛАБЫМ, ОТВРАТИТЕЛЬНЫМ НАСЕКОМЫМ СОЖРАТЬ ВАШ ПРЕКРАСНЫЙ УРОЖАЙ. ОБРУШЬТЕ НА НИХ ВСЮ МОЩЬ "ВЛАСТЕЛИНА ГРОМА" И ЗАЩИТИТЕ СВОЕ ИМУЩЕСТВО".$B$B<Остальное место занято изображением различных насекомых, которые рыдают от ужаса или спасаются бегством.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инсектицид "Властелин Грома"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<На коробке изображена грозная физиономия могу – существо смотрит вниз, на аккуратные строчки.>$B$B"НЕ ДАЙТЕ СЛАБЫМ, ОТВРАТИТЕЛЬНЫМ НАСЕКОМЫМ СОЖРАТЬ ВАШ ПРЕКРАСНЫЙ УРОЖАЙ. ОБРУШЬТЕ НА НИХ ВСЮ МОЩЬ "ВЛАСТЕЛИНА ГРОМА" И ЗАЩИТИТЕ СВОЕ ИМУЩЕСТВО".$B$B<Остальное место занято изображением различных насекомых, которые рыдают от ужаса или спасаются бегством.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31938,'Суперплуг "Бороздящий землю"','<На коробке изображен неестественно мускулистый крестьянин-пандарен, идущий за плугом. За ним тянется широкая борозда. На руках и плечах пандарена повисли шаловливые дети.$B$BРядом с крестьянином – столь же мускулистая женщина; на голове она изящно удерживает рог изобилия, а ногой ловко бьет по морде гну-синя.>$B$B"Бороздящий землю. Вы – хозяин земли. Вы – хозяин жизни".','Отнесите суперплуг "Бороздящий землю" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.','Суперплуг "Бороздящий землю"! Я... я и представить себе не мог, что когда-нибудь у меня будет такой. Ты хоть представляешь, сколько времени он нам сбережет?$B$BГоворят, если пройти с этим плугом двадцать ярдов каменной породы, получишь песочницу – и штраф от Шадо-Пан за то, что напугал соседей землетрясением!!$B$BЭто будет круто!','Отнесите суперплуг "Бороздящий землю" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суперплуг "Бороздящий землю"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<На коробке изображен неестественно мускулистый крестьянин-пандарен, идущий за плугом. За ним тянется широкая борозда. На руках и плечах пандарена повисли шаловливые дети.$B$BРядом с крестьянином – столь же мускулистая женщина; на голове она изящно удерживает рог изобилия, а ногой ловко бьет по морде гну-синя.>$B$B"Бороздящий землю. Вы – хозяин земли. Вы – хозяин жизни".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите суперплуг "Бороздящий землю" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Суперплуг "Бороздящий землю"! Я... я и представить себе не мог, что когда-нибудь у меня будет такой. Ты хоть представляешь, сколько времени он нам сбережет?$B$BГоворят, если пройти с этим плугом двадцать ярдов каменной породы, получишь песочницу – и штраф от Шадо-Пан за то, что напугал соседей землетрясением!!$B$BЭто будет круто!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите суперплуг "Бороздящий землю" фермеру Юну, который находится на ферме Солнечной Песни или на рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31939,'[TEMP]','Ну что ж, дружок, все это было лишь для тренировки!$b$b$gГотов:Готова; заняться по-настоящему важными вещами?$b$bМэй Мэй Железной Лапы с рынка нужна морковь для похлебки. А кто может вырастить морковь? Мы!$b$bДавай, покажи мне, чему ты $gнаучился:научилась;, и собери урожай с четырех грядок хрустящей моркови.','Посадите 4 хрустящих моркови и соберите урожай. Семена хрустящей моркови можно приобрести у торговца Зеленое Поле на рынке Полугорья. После посадки и ухода за растениями вам придется подождать один день, пока урожай не созреет.','Поговорите с фермером Юном на Ферме Солнечной Песни, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[TEMP]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, дружок, все это было лишь для тренировки!$b$b$gГотов:Готова; заняться по-настоящему важными вещами?$b$bМэй Мэй Железной Лапы с рынка нужна морковь для похлебки. А кто может вырастить морковь? Мы!$b$bДавай, покажи мне, чему ты $gнаучился:научилась;, и собери урожай с четырех грядок хрустящей моркови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 4 хрустящих моркови и соберите урожай. Семена хрустящей моркови можно приобрести у торговца Зеленое Поле на рынке Полугорья. После посадки и ухода за растениями вам придется подождать один день, пока урожай не созреет.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с фермером Юном на Ферме Солнечной Песни, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31940,'Наставники боевых питомцев: Пандария','Тебе удалось победить лучших укротителей боевых питомцев Запределья, но теперь тебя ждет Нордскол!$b$bТы $gдолжен:должна; победить четырех укротителей боевых питомцев: Зигги Бескрылого в Ревущем фьорде, Почти Безголового Якоба в Лесу Хрустальной Песни, Окрута Убийцу Драконов в Драконьем Погосте и Гатреча в Зул\'Драке.$b$bЕсли тебе удастся победить их всех, великий укротитель боевых питомцев наверняка вызовет тебя на поединок!','Победите Зигги Бескрылого, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.','Покажи им!','Одри Бернхеп','Ну что, начнем?','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставники боевых питомцев: Пандария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось победить лучших укротителей боевых питомцев Запределья, но теперь тебя ждет Нордскол!$b$bТы $gдолжен:должна; победить четырех укротителей боевых питомцев: Зигги Бескрылого в Ревущем фьорде, Почти Безголового Якоба в Лесу Хрустальной Песни, Окрута Убийцу Драконов в Драконьем Погосте и Гатреча в Зул\'Драке.$b$bЕсли тебе удастся победить их всех, великий укротитель боевых питомцев наверняка вызовет тебя на поединок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Зигги Бескрылого, Почти Безголового Якоба, Окрута Убийцу Драконов и Гатреча в битвах питомцев.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Покажи им!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Одри Бернхеп',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ну что, начнем?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Одри Бернхеп',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31941,'Кабачок против неприятного запаха','Дедушка всегда говорил: "Один кабачок в неделю и ты всегда будешь приятно пахнуть."$b$b<Юн незаметно принюхивается.>$b$bГм. Кажется, неделя уже на исходе. Не поможешь ли мне посадить нефритовый кабачок?','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кабачок против неприятного запаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дедушка всегда говорил: "Один кабачок в неделю и ты всегда будешь приятно пахнуть."$b$b<Юн незаметно принюхивается.>$b$bГм. Кажется, неделя уже на исходе. Не поможешь ли мне посадить нефритовый кабачок?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31942,'Время сажать дыни','<Фермер Юн смотрит в небо и втягивает ноздрями воздух.>$b$bХмм...$b$b<Он облизывает лапу, поднимает ее вверх, втыкает в землю коготь пальца на ноге, а затем изучает длину тени.>$b$bДа. Время сажать дыни.$b$bНе можешь принести семена и помочь мне посадить полосатую дыню?','Едва успели. Чуть было не пропустили благоприятный для посадки дынь период.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время сажать дыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Фермер Юн смотрит в небо и втягивает ноздрями воздух.>$b$bХмм...$b$b<Он облизывает лапу, поднимает ее вверх, втыкает в землю коготь пальца на ноге, а затем изучает длину тени.>$b$bДа. Время сажать дыни.$b$bНе можешь принести семена и помочь мне посадить полосатую дыню?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Едва успели. Чуть было не пропустили благоприятный для посадки дынь период.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31943,'Ведьмины ягоды','Этот местный паренек, Анди, станет превосходным фермером, когда вырастет. Мне достаточно просто взглянуть на него.$b$bДумаю, надо посадить немного ведьминых ягод для него. Дети любят эти ягоды, так что это будет отличный сюрприз.','О, ведьмины ягоды! Я не могу ждать, пока они созреют!$B$BНо мне придется.','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведьмины ягоды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот местный паренек, Анди, станет превосходным фермером, когда вырастет. Мне достаточно просто взглянуть на него.$b$bДумаю, надо посадить немного ведьминых ягод для него. Дети любят эти ягоды, так что это будет отличный сюрприз.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ведьмины ягоды! Я не могу ждать, пока они созреют!$B$BНо мне придется.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Юну на Ферму Солнечной Песни в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (31944,'Завершение тренировок: последнее испытание','Приветствую, $n. Пришло время закончить твои тренировки. Отправляйся на тренировочную площадку, чтобы пройти последнее испытание.','Поговорите с мастером Хайтом в Святилище Быка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершение тренировок: последнее испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $n. Пришло время закончить твои тренировки. Отправляйся на тренировочную площадку, чтобы пройти последнее испытание.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Хайтом в Святилище Быка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31945,'Растениеводство VI: голос Джины','Еще немного, и я разорюсь! Видишь – все Железные Лапы заняты готовкой.$B$BИх вкуснейшие блюда привлекают на рынок множество покупателей, но у поваров закончился лук-шалот!$B$BКазалось бы, и что в этом такого? Но на самом деле это важнейший ингредиент, без него блюда получаются далеко не такими вкусными и ароматными.$B$BЭто ужасно! Новая партия лука поступит только через неделю!$B$BСекундочку! Ты же фермер, да? Поможешь мне?','Посадите и вырастите 1 лук-шалот, затем принесите 5 луковиц лука-шалота Джине Грязный Коготь.$b$bСемена лука-шалота можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.','Не может быть! Ну, я видела лук и получше, но и этот сойдет. Лагго, ты наша спасительница!!','Многие недооценивают лук-шалот, ведь на первый взгляд он такой маленький и невзрачный. Однако на самом деле он придает блюдам неповторимый вкус.','Поговорите с Джиной Грязный Коготь на рынке Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растениеводство VI: голос Джины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще немного, и я разорюсь! Видишь – все Железные Лапы заняты готовкой.$B$BИх вкуснейшие блюда привлекают на рынок множество покупателей, но у поваров закончился лук-шалот!$B$BКазалось бы, и что в этом такого? Но на самом деле это важнейший ингредиент, без него блюда получаются далеко не такими вкусными и ароматными.$B$BЭто ужасно! Новая партия лука поступит только через неделю!$B$BСекундочку! Ты же фермер, да? Поможешь мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите и вырастите 1 лук-шалот, затем принесите 5 луковиц лука-шалота Джине Грязный Коготь.$b$bСемена лука-шалота можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть! Ну, я видела лук и получше, но и этот сойдет. Лагго, ты наша спасительница!!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Многие недооценивают лук-шалот, ведь на первый взгляд он такой маленький и невзрачный. Однако на самом деле он придает блюдам неповторимый вкус.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джиной Грязный Коготь на рынке Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31946,'Голос Мун-Муна III: великая подмена моркови','Мун-Мун плевай, кто крадет морковь. Но не плевай, что господин Грязный Коготь сделай с бедным Мун-Мун, когда увидь, что урожай пропал!$B$B<Мун-Мун задумчиво потирает подбородок.>$B$BСтой! Мун-Мун имей блестящий мысль. Ты вырасти морковь сейчас. А мы потом притворимся, что она – морковь господина Грязного Когтя.$B$BДа!','Посадите и вырастите 2 сочные хрустящие моркови, затем принесите 10 сочных хрустящих морковок Мун-Муну.$b$bСемена сочной хрустящей моркови можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.','Ух ты, какой сочный и хрустящий морковь! Джестерок, Мун-Мун не знал, что ты такой фермер хороший.','Гну-сини обожают морковь, а репу ненавидят. Репа мерзкая.','Вернитесь к Мун-Муну в дом Хаоханя Грязного Когтя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Мун-Муна III: великая подмена моркови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мун-Мун плевай, кто крадет морковь. Но не плевай, что господин Грязный Коготь сделай с бедным Мун-Мун, когда увидь, что урожай пропал!$B$B<Мун-Мун задумчиво потирает подбородок.>$B$BСтой! Мун-Мун имей блестящий мысль. Ты вырасти морковь сейчас. А мы потом притворимся, что она – морковь господина Грязного Когтя.$B$BДа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите и вырастите 2 сочные хрустящие моркови, затем принесите 10 сочных хрустящих морковок Мун-Муну.$b$bСемена сочной хрустящей моркови можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, какой сочный и хрустящий морковь! Джестерок, Мун-Мун не знал, что ты такой фермер хороший.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гну-сини обожают морковь, а репу ненавидят. Репа мерзкая.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мун-Муну в дом Хаоханя Грязного Когтя, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31947,'Голос фермера Фуна III: без ума от капусты','<Фермер Фун лучится от счастья.>$B$BТы $gвернул:вернула; мне моих драгоценных яков! Но, к сожалению, на воле они отощали.$B$BЯки совсем изголодались, но я не могу кормить их простой обычной травой.$B$BНет уж, они будут есть самую сочную капусту, которую только можно найти в долине.$B$BПравда, мои амбары сейчас пусты. Если принесешь мне капусту, я щедро тебя награжу.','У всех моих яков есть имена. Вот это – Волосатик, это Космач, дальше Пушок, Шерстистый, а это...','Вернитесь к фермеру Фуну в Плодородные земли или на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос фермера Фуна III: без ума от капусты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Фермер Фун лучится от счастья.>$B$BТы $gвернул:вернула; мне моих драгоценных яков! Но, к сожалению, на воле они отощали.$B$BЯки совсем изголодались, но я не могу кормить их простой обычной травой.$B$BНет уж, они будут есть самую сочную капусту, которую только можно найти в долине.$B$BПравда, мои амбары сейчас пусты. Если принесешь мне капусту, я щедро тебя награжу.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У всех моих яков есть имена. Вот это – Волосатик, это Космач, дальше Пушок, Шерстистый, а это...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Фуну в Плодородные земли или на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31948,'Голос Наны II: священные источники','$n, ты очень вовремя. Я как раз собираюсь делать сироп из ведьминых ягод.$B$BТы когда-нибудь $gслышал:слышала; об этом чудесном напитке?$B$BС каждым глотком ты молодеешь на десять лет! А как, по-твоему, мне до сих пор удается так хорошо выглядеть?$B$BВ общем, мне нужен особый ингредиент – тысячелетняя вода. Ее можно набрать из водопада на севере.$B$BМне туда ходить уже тяжело – но если ты принесешь воды, я поделюсь с тобой сиропом.','Наберите в пустой кувшин тысячелетней воды из Золотого водопада.','В эту долину вода течет с севера, из Вечноцветущего дола. Говорят, что она обладает чудесными волшебными свойствами.','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Наны II: священные источники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты очень вовремя. Я как раз собираюсь делать сироп из ведьминых ягод.$B$BТы когда-нибудь $gслышал:слышала; об этом чудесном напитке?$B$BС каждым глотком ты молодеешь на десять лет! А как, по-твоему, мне до сих пор удается так хорошо выглядеть?$B$BВ общем, мне нужен особый ингредиент – тысячелетняя вода. Ее можно набрать из водопада на севере.$B$BМне туда ходить уже тяжело – но если ты принесешь воды, я поделюсь с тобой сиропом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите в пустой кувшин тысячелетней воды из Золотого водопада.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В эту долину вода течет с севера, из Вечноцветущего дола. Говорят, что она обладает чудесными волшебными свойствами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (31949,'Голос Наны III: сироп из ведьминых ягод','Теперь у нас есть вода – и я уже почти чувствую вкус холодного сиропа!$B$BТеперь нам просто нужно найти немного ведьминых ягод.$B$BВ этом году у моего внука ягоды совсем не уродились, так что надо поискать в другом месте.$B$BСкажи, а у тебя на ферме ведьмины ягоды не растут? Может, принесешь?$B$BЕсли они подойдут, мы сделаем из них отличный сироп!','Посадите и вырастите 3 ведьминых ягоды, затем принесите 15 ведьминых ягод Нане Грязный Коготь.$b$bСемена ведьминых ягод можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.','<Нана Грязный Коготь разглядывает темную ведьмину ягоду, затем бросает ее в рот. На лице старушки появляется улыбка.>$B$BО небо! Я уже столько лет не ела таких сладких и сочных ведьминых ягод! Такие мог вырастить только... только старый Юн, дедушка твоего друга!$B$B<Нана Грязный Коготь краснеет.>$B$BОн был таким проказником! Я до сих пор помню, как летом мы до отвала наедались этими ягодами – и ни о чем не тревожились!$B$BСпасибо, что напомнил мне о старом друге.','Давай быстрее, ладно? Я уже стара, мне уже не так много осталось. Я хочу еще раз выпить сиропа, пока не представилась!','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Наны III: сироп из ведьминых ягод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас есть вода – и я уже почти чувствую вкус холодного сиропа!$B$BТеперь нам просто нужно найти немного ведьминых ягод.$B$BВ этом году у моего внука ягоды совсем не уродились, так что надо поискать в другом месте.$B$BСкажи, а у тебя на ферме ведьмины ягоды не растут? Может, принесешь?$B$BЕсли они подойдут, мы сделаем из них отличный сироп!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите и вырастите 3 ведьминых ягоды, затем принесите 15 ведьминых ягод Нане Грязный Коготь.$b$bСемена ведьминых ягод можно купить на рынке Полугорья у торговца Зеленое Поле. После того как вскопаете грядку и посадите растение, подождите один день, прежде чем собрать урожай.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Нана Грязный Коготь разглядывает темную ведьмину ягоду, затем бросает ее в рот. На лице старушки появляется улыбка.>$B$BО небо! Я уже столько лет не ела таких сладких и сочных ведьминых ягод! Такие мог вырастить только... только старый Юн, дедушка твоего друга!$B$B<Нана Грязный Коготь краснеет.>$B$BОн был таким проказником! Я до сих пор помню, как летом мы до отвала наедались этими ягодами – и ни о чем не тревожились!$B$BСпасибо, что напомнил мне о старом друге.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай быстрее, ладно? Я уже стара, мне уже не так много осталось. Я хочу еще раз выпить сиропа, пока не представилась!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31950,'Ну что ж, дружок, все это было лишь для тренировки!$b$b$gГотов:Готова; заняться по-настоящему важными вещами?$b$bМэй Мэй Железной Лапы с рынка нужна морковь для похлебки. А кто может вырастить морковь? Мы!$b$bДавай, покажи мне, чему ты $gнаучился:научилась;, и собери урожай с четырех грядок хрустящей моркови.','Посадите 4 хрустящих моркови и соберите урожай. Семена хрустящей моркови можно приобрести у торговца Зеленое Поле на рынке Полугорья. После посадки и ухода за растениями вам придется подождать один день, пока урожай не созреет.','Поговорите с фермером Юном на Ферме Солнечной Песни, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, дружок, все это было лишь для тренировки!$b$b$gГотов:Готова; заняться по-настоящему важными вещами?$b$bМэй Мэй Железной Лапы с рынка нужна морковь для похлебки. А кто может вырастить морковь? Мы!$b$bДавай, покажи мне, чему ты $gнаучился:научилась;, и собери урожай с четырех грядок хрустящей моркови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 4 хрустящих моркови и соберите урожай. Семена хрустящей моркови можно приобрести у торговца Зеленое Поле на рынке Полугорья. После посадки и ухода за растениями вам придется подождать один день, пока урожай не созреет.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с фермером Юном на Ферме Солнечной Песни, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31951,'Великая укротительница Аки','Ты хорошо $gпроявил:проявила; себя в боях с укротителями Азерота. Даже величайшие из мастеров не смогли устоять перед твоей хитростью.$B$BЯ буду ждать тебя в Вечноцветущем доле, ибо ты $gдостоин:достойна; со мной сразиться. Приходи, $n, и мы посмотрим, достаточно ли ты $gсилен:сильна;, чтобы победить.','Победите Аки Избранную в битве питомцев.','Тебе удалось победить. Продолжай тренироваться и сражаться с другими укротителями. Это путешествие никогда не закончится.','Поговорите с Аки Избранной.','Пришла пора сразиться со мной.','Аки Избранная') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Аки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gпроявил:проявила; себя в боях с укротителями Азерота. Даже величайшие из мастеров не смогли устоять перед твоей хитростью.$B$BЯ буду ждать тебя в Вечноцветущем доле, ибо ты $gдостоин:достойна; со мной сразиться. Приходи, $n, и мы посмотрим, достаточно ли ты $gсилен:сильна;, чтобы победить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Аки Избранную в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось победить. Продолжай тренироваться и сражаться с другими укротителями. Это путешествие никогда не закончится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аки Избранной.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Пришла пора сразиться со мной.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аки Избранная',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31952,'Укротители боевых питомцев: Пандария','Победите Хюну Хранительницу Святилищ, фермера Ниши, Мо\'рука, Отважного Юня, искателя Зусши и странника пустошей Шу в битвах питомцев.','Тебя ждет последнее испытание.','Варзок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Пандария',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Хюну Хранительницу Святилищ, фермера Ниши, Мо\'рука, Отважного Юня, искателя Зусши и странника пустошей Шу в битвах питомцев.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Тебя ждет последнее испытание.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Варзок',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31953,'Великая укротительница Хюна','Ты снова ищешь битвы? Я готова к схватке. Я выйду из нее более сильной и смогу лучше защищать святилища нашего народа.','Победите Хюну Хранительницу Святилищ в битве питомцев.','Ты обладаешь великой силой. Могу ли я надеяться на твою помощь в защите святынь?','Поговорите с Хюной Хранительницей Святилищ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Хюна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты снова ищешь битвы? Я готова к схватке. Я выйду из нее более сильной и смогу лучше защищать святилища нашего народа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Хюну Хранительницу Святилищ в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты обладаешь великой силой. Могу ли я надеяться на твою помощь в защите святынь?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хюной Хранительницей Святилищ.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31954,'Великий укротитель Мо\'рук','На этот раз я бить тебя! Увидишь!','Победите Мо\'рука в битве питомцев.','В следующий раз ты проиграешь. Я гарантирую это!','Поговорите с Мор\'уком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Мо\'рук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этот раз я бить тебя! Увидишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мо\'рука в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В следующий раз ты проиграешь. Я гарантирую это!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мор\'уком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31955,'Великая укротительница Ниши','Благодаря земле, в которой проходят тренировки, мои питомцы становятся все сильнее и сильнее. У тебя никаких шансов!','Победите фермера Ниши в битве питомцев.','Отлично! Кажется, не только я тренировался!','Поговорите с фермером Ниши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Ниши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря земле, в которой проходят тренировки, мои питомцы становятся все сильнее и сильнее. У тебя никаких шансов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите фермера Ниши в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Кажется, не только я тренировался!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с фермером Ниши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31956,'Великий укротитель Юнь','Если ты думаешь, что я позволю тебе победить еще раз, то ты глубоко заблуждаешься. На этот раз я тебе спуску не дам!','Победите Отважного Юня в битве питомцев.','Отлично. Ты снова победил. А теперь уходи, мне надо подготовиться к нашей следующей встрече.','Поговорите с великим укротителем Юнем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Юнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты думаешь, что я позволю тебе победить еще раз, то ты глубоко заблуждаешься. На этот раз я тебе спуску не дам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Отважного Юня в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Ты снова победил. А теперь уходи, мне надо подготовиться к нашей следующей встрече.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с великим укротителем Юнем.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31957,'Великий укротитель Шу','Ты забираешься в самое сердце степей, чтобы сразиться со мной еще раз и потерпеть поражение от рук великого укротителя? Это очень благородно, но и очень глупо.','Победите странника пустошей Шу в битве питомцев.','Я за всю свою жизнь не встречал таких целеустремленных укротителей, как ты. Выходит, все, что о тебе говорят, – правда. С тобой придется считаться.','Поговорите со странником пустошей Шу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Шу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты забираешься в самое сердце степей, чтобы сразиться со мной еще раз и потерпеть поражение от рук великого укротителя? Это очень благородно, но и очень глупо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите странника пустошей Шу в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я за всю свою жизнь не встречал таких целеустремленных укротителей, как ты. Выходит, все, что о тебе говорят, – правда. С тобой придется считаться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со странником пустошей Шу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31958,'Великая укротительница Аки','Хочешь еще раз попытать удачу? Ну что ж, давай сразимся.','Победите Аки Избранную в битве питомцев.','Ты стал сильнее, а твои успехи несомненны. Продолжай свое путешествие.','Поговорите с Аки Избранной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая укротительница Аки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь еще раз попытать удачу? Ну что ж, давай сразимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Аки Избранную в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты стал сильнее, а твои успехи несомненны. Продолжай свое путешествие.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Аки Избранной.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31959,'Военный поход императрицы','Похоже, великая императрица Шек\'зир сильно на нас разозлилась, ее терпение исчерпано. Мы только что узнали, что в тени Сердца Страха собирается огромное войско, которому приказано сокрушить Клакси\'весс.$b$bПока что нам удается продержаться, но такую осаду мы не выдержим.$b$bПробудитель, твоя помощь поистине бесценна. Иди же и займи же свое место на поле боя подле Идеалов.$b$bВстретимся там!','Поговорите с Маликом Невредимым за пределами Сердца Страха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военный поход императрицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, великая императрица Шек\'зир сильно на нас разозлилась, ее терпение исчерпано. Мы только что узнали, что в тени Сердца Страха собирается огромное войско, которому приказано сокрушить Клакси\'весс.$b$bПока что нам удается продержаться, но такую осаду мы не выдержим.$b$bПробудитель, твоя помощь поистине бесценна. Иди же и займи же свое место на поле боя подле Идеалов.$b$bВстретимся там!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маликом Невредимым за пределами Сердца Страха.',`objectives_loc8`);
