INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (31966,'Укротители боевых питомцев: Cataclysm','Победите Брока, Бордина Крепкорука и Гоза Гибельную Ярость в битвах питомцев.','Покажи свои лучшие стороны!','Одри Бернхеп','Ну что, начнем?','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротители боевых питомцев: Cataclysm',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Брока, Бордина Крепкорука и Гоза Гибельную Ярость в битвах питомцев.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Покажи свои лучшие стороны!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Одри Бернхеп',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Ну что, начнем?',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Одри Бернхеп',`questturntargetname_loc8`);
