INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31968,'Ростки сомнения','Альянс... У него столько кораблей. Что же нам делать? Мне... как-то... не по себе...','Приведите Назгрима в чувство.','Поговорите с Тажанем Чжу в Громовой крепости, что в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ростки сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс... У него столько кораблей. Что же нам делать? Мне... как-то... не по себе...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите Назгрима в чувство.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тажанем Чжу в Громовой крепости, что в Нефритовом лесу.',`completedtext_loc8`);
