INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31970,'Великий укротитель Обалис','Победите Обалиса в битве питомцев.','Я был неправ. Ты готов встретиться с моими лучшими питомцами.','Поговорите с Обалисом.','Жду не дождусь битвы с тобой.','Обалис') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Обалис',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Обалиса в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я был неправ. Ты готов встретиться с моими лучшими питомцами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Обалисом.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Жду не дождусь битвы с тобой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Обалис',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31971,'Великий укротитель Обалис','Вижу, великий укротитель снова здесь. Хочешь сразиться еще раз? Хорошо. Я принимаю твой вызов.','Победите Обалиса в битве питомцев.','Ты победил, но сильнее стал я. Будь осторожнее, когда захочешь сразиться со мной в следующий раз.','Поговорите с Обалисом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Обалис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, великий укротитель снова здесь. Хочешь сразиться еще раз? Хорошо. Я принимаю твой вызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Обалиса в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты победил, но сильнее стал я. Будь осторожнее, когда захочешь сразиться со мной в следующий раз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Обалисом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31972,'Брок','Я пока не очень хорошо понимаю, чего от меня хотят эти крохи. Может, еще одна битва укрепит связь между нами?','Победите Брока в битве питомцев.','Это поражение сблизило меня и моих питомцев еще сильнее. Спасибо тебе за этот бой.','Поговорите с Броком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пока не очень хорошо понимаю, чего от меня хотят эти крохи. Может, еще одна битва укрепит связь между нами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Брока в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поражение сблизило меня и моих питомцев еще сильнее. Спасибо тебе за этот бой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Броком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31973,'Бордин Крепкорук','Местные жители научили меня чувствовать силу земли. Ее поддержка никогда не ослабевает. Давай сразимся еще раз, и ты увидишь, как я силен!','Победите Бордина Крепкорука в битве питомцев.','Нет, нет, я просто отвлекся. Еще один бой?','Поговорите с Бордином Крепкоруком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бордин Крепкорук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Местные жители научили меня чувствовать силу земли. Ее поддержка никогда не ослабевает. Давай сразимся еще раз, и ты увидишь, как я силен!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Бордина Крепкорука в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, нет, я просто отвлекся. Еще один бой?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бордином Крепкоруком.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31974,'Гоз Гибельная Ярость','По моим венам течет сила сумерек. Я – бог! У тебя нет шансов против меня!','Победите Гоза Гибельную Ярость в битве питомцев.','Ты сражаешься с яростью моих повелителей. Возможно, мы не так уж сильно отличаемся.','Поговорите с Гозом Гибельной Яростью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоз Гибельная Ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По моим венам течет сила сумерек. Я – бог! У тебя нет шансов против меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Гоза Гибельную Ярость в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сражаешься с яростью моих повелителей. Возможно, мы не так уж сильно отличаемся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гозом Гибельной Яростью.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31975,'Возвращение героя','Я считаю, что тебе самое место среди всяких дельцов из Запределья. Возвращайся-ка в Штормград к Одри Бернхеп и спроси у нее, что делать дальше!','Обратитесь к Одри Бернхеп в Штормграде.','Посмотрим-ка… Куда бы послать тебя дальше…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я считаю, что тебе самое место среди всяких дельцов из Запределья. Возвращайся-ка в Штормград к Одри Бернхеп и спроси у нее, что делать дальше!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим-ка… Куда бы послать тебя дальше…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31976,'Возвращение героя','Все только и говорят, что о твоих боевых навыках. Возвращайся к Одри Бернхеп за дальнейшими указаниями.','Обратитесь к Одри Бернхеп в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все только и говорят, что о твоих боевых навыках. Возвращайся к Одри Бернхеп за дальнейшими указаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`);
