INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31978,'Приоритеты!','Только посмотрите на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались от подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.','Найдите 6 бочек медового хмеля на поляне Медовой Росы.','Ну, не так много, как я рассчитывала, но обойдемся и этим. Нет нужды плакать над пролитым пивом.','Вернитесь к Элли Медовой Лапе в Деревню Медовой Росы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приоритеты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только посмотрите на этот бардак! Весь хмель пропал!$b$bТажань Чжу предупреждал, чтобы мы держались от подальше от чужаков, но сейчас нам пригодится любая помощь.$b$bМы везли хмель в Цветущую Зарю, как вдруг начался бой. И все наше добро пропало!$b$bХочешь помочь нам? Может быть, ты найдешь какие-нибудь уцелевшие бочки с медовым хмелем? Тогда наши потери не будут столь ужасными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 6 бочек медового хмеля на поляне Медовой Росы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, не так много, как я рассчитывала, но обойдемся и этим. Нет нужды плакать над пролитым пивом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элли Медовой Лапе в Деревню Медовой Росы.',`completedtext_loc8`);
