INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31981,'Превосходный ученик','Беги к своей наставнице, Одри Бернхеп, в Штормград. Может быть, она посчитает тебя более... $gдостойным:достойной;... для поединков.','Обратитесь к Одри Бернхеп в Штормграде.','Ты и правда победил великого укротителя Антари? Не может быть! Надо найти тебе противника посильнее!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходный ученик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беги к своей наставнице, Одри Бернхеп, в Штормград. Может быть, она посчитает тебя более... $gдостойным:достойной;... для поединков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты и правда победил великого укротителя Антари? Не может быть! Надо найти тебе противника посильнее!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31982,'Превосходный ученик','Беги к своему наставнику, Варзоку, в Оргриммар. Может быть, он посчитает тебя более... $gдостойным:достойной;... для поединков.','Обратитесь к Варзоку в Оргриммаре.','Есть только одно место, куда тебе следует отправиться дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходный ученик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беги к своему наставнику, Варзоку, в Оргриммар. Может быть, он посчитает тебя более... $gдостойным:достойной;... для поединков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Варзоку в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Есть только одно место, куда тебе следует отправиться дальше.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31983,'Краткая отсрочка','Для |3-1($r) ты отлично $gсправился:справилась;. Теперь возвращайся в Оргриммар и поговори с этим грубияном Варзоком. Может быть, он отправит тебя куда-нибудь подальше от моей семьи.','Обратитесь к Варзоку в Оргриммаре.','Думаю, я знаю, что тебе нужно сделать дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Краткая отсрочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для |3-1($r) ты отлично $gсправился:справилась;. Теперь возвращайся в Оргриммар и поговори с этим грубияном Варзоком. Может быть, он отправит тебя куда-нибудь подальше от моей семьи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Варзоку в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, я знаю, что тебе нужно сделать дальше.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31984,'Краткая отсрочка','Здорово, действительно здорово! А теперь, пожалуйста, возвращайся к Одри Бернхеп в Штормград.$b$bДа, и передай ей от меня привет. Этой прелестной молодой женщине может пригодиться компания такого опытного бойца, как я.','Обратитесь к Одри Бернхеп в Штормграде.','Пэйн попросил тебя навестить меня, да? Он ничему не учится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Краткая отсрочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здорово, действительно здорово! А теперь, пожалуйста, возвращайся к Одри Бернхеп в Штормград.$b$bДа, и передай ей от меня привет. Этой прелестной молодой женщине может пригодиться компания такого опытного бойца, как я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пэйн попросил тебя навестить меня, да? Он ничему не учится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31985,'Триумфальное возвращение','По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Одри Бернхеп. Она расскажет тебе, что делать дальше.','Обратитесь к Одри Бернхеп в Штормграде.','Полагаю, ты встречался с Обалисом? Он неплохой парень, если не обращать внимание на его внешнюю суровость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Триумфальное возвращение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Одри Бернхеп. Она расскажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, ты встречался с Обалисом? Он неплохой парень, если не обращать внимание на его внешнюю суровость.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (31986,'Триумфальное возвращение','По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Варзоком. Он расскажет тебе, что делать дальше.','Обратитесь к Варзоку в Оргриммаре.','Теперь ты можешь испытать себя в настоящем бою. Ты готов?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Триумфальное возвращение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По мнению твоего наставника, теперь ты полностью $gготов:готова;. Возвращайся в Штормград и поговори с Варзоком. Он расскажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Варзоку в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты можешь испытать себя в настоящем бою. Ты готов?',`offerrewardtext_loc8`);
