INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (31989,'Пик Безмятежности - завершение обучения','Поговорите с мастером Хайтом в Святилище Быка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пик Безмятежности - завершение обучения',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мастером Хайтом в Святилище Быка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (31990,'Одри Бернхеп','Боюсь, я ничему не могу научить тебя, $n. Однако твой путь, как дрессировщика питомцев, еще далек от завершения!$b$bПоговори с Одри Бернхеп в Штормграде. Она знакома со многими из лучших дрессировщиков Азерота и поможет тебе в твоем дальнейшем обучении.','Обратитесь к Одри Бернхеп в Штормграде.','Задай им!','Грейди Баннсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одри Бернхеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, я ничему не могу научить тебя, $n. Однако твой путь, как дрессировщика питомцев, еще далек от завершения!$b$bПоговори с Одри Бернхеп в Штормграде. Она знакома со многими из лучших дрессировщиков Азерота и поможет тебе в твоем дальнейшем обучении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Задай им!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Грейди Баннсон',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (31991,'Великий укротитель Зусши','Я знал, что рано или поздно ты вернешься, чтобы еще раз сразиться со мной. Давай посмотрим, в ком из нас больше тактической мудрости.','Победите искателя Зусши в битве питомцев.','Ты и в самом деле лучше меня. А теперь прости меня, я должен посоветоваться с водой относительно этого поражения.','Поговорите с искателем Зусши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий укротитель Зусши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знал, что рано или поздно ты вернешься, чтобы еще раз сразиться со мной. Давай посмотрим, в ком из нас больше тактической мудрости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите искателя Зусши в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты и в самом деле лучше меня. А теперь прости меня, я должен посоветоваться с водой относительно этого поражения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с искателем Зусши.',`completedtext_loc8`);
