INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (31998,'Серьезное испытание: Ша Сомнения','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; в Храм Нефритовой Змеи. Когда прибудешь на место, задействуй сферу испытания и испепели Ша Сомнения.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Храм Нефритовой Змеи в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Ша Сомнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; в Храм Нефритовой Змеи. Когда прибудешь на место, задействуй сферу испытания и испепели Ша Сомнения.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Храм Нефритовой Змеи в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (31999,'Приказ Назгрима','Что ж, теперь у тебя имеется удобная база для вылазок, Альянсом даже и не пахнет, а несколько ветеранов Орды готовы к приказаниям. Пора приступать к завоеванию континента.$b$bГенерал Назгрим знает, с чего начать.','Поговорите с генералом Назгримом на Взлетной полосе Сильной Руки в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ Назгрима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, теперь у тебя имеется удобная база для вылазок, Альянсом даже и не пахнет, а несколько ветеранов Орды готовы к приказаниям. Пора приступать к завоеванию континента.$b$bГенерал Назгрим знает, с чего начать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Назгримом на Взлетной полосе Сильной Руки в Нефритовом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32000,'Серьезное испытание: Янь-Чжу Высвобожденный','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; на Хмелеварню Буйных Портеров. Когда прибудешь на место, задействуй сферу испытания и обрати в ветер Янь-Чжу Высвобожденного.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Хмелеварню Буйных Портеров в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Янь-Чжу Высвобожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; крепкую группу и $gотправился:отправилась; на Хмелеварню Буйных Портеров. Когда прибудешь на место, задействуй сферу испытания и обрати в ветер Янь-Чжу Высвобожденного.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Хмелеварню Буйных Портеров в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32001,'Серьезное испытание: Ша Ненависти','Я хочу, чтобы ты $gсобрал:собрала; спокойную группу и $gотправился:отправилась; в Монастырь Шадо-Пан. Когда прибудешь на место, задействуй сферу испытания и спаси Тажаня Чжу из плена Ша Ненависти.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Монастырь Шадо-Пан в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Ша Ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; спокойную группу и $gотправился:отправилась; в Монастырь Шадо-Пан. Когда прибудешь на место, задействуй сферу испытания и спаси Тажаня Чжу из плена Ша Ненависти.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Монастырь Шадо-Пан в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32002,'Серьезное испытание: Синь Мастер Боя','Я хочу, чтобы ты $gсобрал:собрала; ловкую группу и $gотправился:отправилась; во Дворец Могу\'шан. Когда прибудешь на место, задействуй сферу испытания и срази Синя Мастера Боя.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Дворец Могу\'шан в режиме испытания.','Большое спасибо, Лекарт. Твое боевое мастерство несравненно, а твое проворство ужасает врагов.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Синь Мастер Боя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; ловкую группу и $gотправился:отправилась; во Дворец Могу\'шан. Когда прибудешь на место, задействуй сферу испытания и срази Синя Мастера Боя.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Дворец Могу\'шан в режиме испытания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо, Лекарт. Твое боевое мастерство несравненно, а твое проворство ужасает врагов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32003,'Серьезное испытание: Райгонн','Я хочу, чтобы ты $gсобрал:собрала; могучую группу и $gотправился:отправилась; к Вратам Заходящего Солнца. Когда прибудешь на место, задействуй сферу испытания и сокруши Райгонна.$B$BВозвращайся ко мне за наградой, когда завершишь это испытание.','Пройдите Врата Заходящего Солнца в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Райгонн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; могучую группу и $gотправился:отправилась; к Вратам Заходящего Солнца. Когда прибудешь на место, задействуй сферу испытания и сокруши Райгонна.$B$BВозвращайся ко мне за наградой, когда завершишь это испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Врата Заходящего Солнца в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32004,'Серьезное испытание: командующий флангом Нер\'онок','Я хочу, чтобы ты $gсобрал:собрала; зоркую группу и $gпринял:приняла; участие в осаде храма Нюцзао. Когда прибудешь на место, задействуй сферу испытания и сровняй с землей командующего флангом Нер\'онока.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Осаду храма Нюцзао в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: командующий флангом Нер\'онок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; зоркую группу и $gпринял:приняла; участие в осаде храма Нюцзао. Когда прибудешь на место, задействуй сферу испытания и сровняй с землей командующего флангом Нер\'онока.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Осаду храма Нюцзао в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32005,'Серьезное испытание: Дюранд','Я хочу, чтобы ты $gсобрал:собрала; храбрую группу и $gотправился:отправилась; в Монастырь Алого ордена. Когда прибудешь на место, задействуй сферу испытания и покарай Дюранда.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Монастырь Алого ордена в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: Дюранд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; храбрую группу и $gотправился:отправилась; в Монастырь Алого ордена. Когда прибудешь на место, задействуй сферу испытания и покарай Дюранда.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Монастырь Алого ордена в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32006,'Серьезное испытание: ткач пламени Кеглер','Я хочу, чтобы ты $gсобрал:собрала; находчивую группу и $gотправился:отправилась; в Залы Алого ордена. Когда прибудешь на место, задействуй сферу испытания и положи конец надругательству над книгами, которое творит ткач пламени Кеглер.','Пройдите Залы Алого ордена в режиме испытания.','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: ткач пламени Кеглер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; находчивую группу и $gотправился:отправилась; в Залы Алого ордена. Когда прибудешь на место, задействуй сферу испытания и положи конец надругательству над книгами, которое творит ткач пламени Кеглер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Залы Алого ордена в режиме испытания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32007,'Серьезное испытание: темный магистр Гандлинг','Я хочу, чтобы ты $gсобрал:собрала; бесстрашную группу и $gотправился:отправилась; в Некроситет. Когда прибудешь на место, задействуй сферу испытания и очисти Некроситет от тлетворного влияния темного магистра Гандлинга.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.','Пройдите Некроситет в режиме испытания.','Друль, ты совершил великое дело. Гандлинг больше никогда не потревожит мертвых. Да упокоится с миром их прах!','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное испытание: темный магистр Гандлинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $gсобрал:собрала; бесстрашную группу и $gотправился:отправилась; в Некроситет. Когда прибудешь на место, задействуй сферу испытания и очисти Некроситет от тлетворного влияния темного магистра Гандлинга.$B$BВозвращайся ко мне за наградой, когда завершишь испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите Некроситет в режиме испытания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Друль, ты совершил великое дело. Гандлинг больше никогда не потревожит мертвых. Да упокоится с миром их прах!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру испытаний Суну в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32008,'Одри Бернхеп','Приветствую тебя, $n! Меня зовут Одри Бернхеп. Я много о тебе слышала. Ты становишься $gизвестным укротителем:известной укротительницей; питомцев!$b$bТебе следует поговорить со мной в Штормграде. Я знакома со многими из лучших укротителей питомцев Азерота, и я могу помочь тебе стать еще опытнее!','Обратитесь к Одри Бернхеп в Штормграде.','Не могу дождаться встречи с тобой!','Одри Бернхеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одри Бернхеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n! Меня зовут Одри Бернхеп. Я много о тебе слышала. Ты становишься $gизвестным укротителем:известной укротительницей; питомцев!$b$bТебе следует поговорить со мной в Штормграде. Я знакома со многими из лучших укротителей питомцев Азерота, и я могу помочь тебе стать еще опытнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Одри Бернхеп в Штормграде.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Не могу дождаться встречи с тобой!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Одри Бернхеп',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32009,'Варзок','Лок\'тар, $n. Меня зовут Варзок. Я многое слышал о твоих успехах в качестве $gукротителя:укротительницы; боевых питомцев, и я хочу познакомить тебя с другими укротителями Азерота, чтобы ты $gпродолжал:продолжала; оттачивать свои навыки.$b$bПоговори со мной в Оргриммаре, и мы начнем.','Поговорите с Варзоком в Оргриммаре.','Я ждал встречи с тобой.','Варзок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Варзок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лок\'тар, $n. Меня зовут Варзок. Я многое слышал о твоих успехах в качестве $gукротителя:укротительницы; боевых питомцев, и я хочу познакомить тебя с другими укротителями Азерота, чтобы ты $gпродолжал:продолжала; оттачивать свои навыки.$b$bПоговори со мной в Оргриммаре, и мы начнем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Варзоком в Оргриммаре.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Я ждал встречи с тобой.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Варзок',`questgivertargetname_loc8`);
