INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32016,'Большие амулеты удачи','Приветствую тебя, $n. Мне выпала честь предоставить тебе прекрасную возможность. Несколько столетий мы совершенствовали метод, который позволяет влиять даже на законы вероятности. Если у тебя будет большой амулет удачи, ты сможешь находить ценные артефакты гораздо чаще.','Соберите 90 малых амулетов удачи.','Вернитесь к старейшине Линь в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большие амулеты удачи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n. Мне выпала честь предоставить тебе прекрасную возможность. Несколько столетий мы совершенствовали метод, который позволяет влиять даже на законы вероятности. Если у тебя будет большой амулет удачи, ты сможешь находить ценные артефакты гораздо чаще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 90 малых амулетов удачи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Линь в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
