INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32030,'Раз в тысячу лет','Время пришло, Пробудитель.$b$bСила совета сокрушит падшую императрицу.$b$bЭтот ритуал не проводился многие тысячи лет, и ни разу еще при нем не присутствовал чужестранец.$b$bВ знак нашей благодарности за твои деяния я приглашаю тебя стать $gсвидетелем:свидетельницей; этого великого исторического события.','Ты вовремя прибыл, Пробудитель.$B$BРитуал в самом разгаре.','Возвращайся в Клакси\'весс и стань свидетелем обновления нашей империи.','Клакси\'ва Ик') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раз в тысячу лет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, Пробудитель.$b$bСила совета сокрушит падшую императрицу.$b$bЭтот ритуал не проводился многие тысячи лет, и ни разу еще при нем не присутствовал чужестранец.$b$bВ знак нашей благодарности за твои деяния я приглашаю тебя стать $gсвидетелем:свидетельницей; этого великого исторического события.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты вовремя прибыл, Пробудитель.$B$BРитуал в самом разгаре.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Возвращайся в Клакси\'весс и стань свидетелем обновления нашей империи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Клакси\'ва Ик',`questgivertargetname_loc8`);
