INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32038,'Искусство охоты на оленей','Я всегда любил поохотиться на оленей. Олени сильные и быстрые животные и защищают свою территорию.$b$bХоть они и питаются одной травой, но бегают так, что охотнику приходится попотеть, чтобы их поймать.$b$bК востоку отсюда полно оленей пустошей. Они только и ждут, чтобы какой-нибудь охотник устроил им хорошую пробежку.$b$bУдачной охоты.','Убейте 10 оленей пустошей.','С Ясеневого леса у меня не было такой отличной охоты на оленей.','Поговорите с Мэттом "Везунчиком" Удавахиным в охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство охоты на оленей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда любил поохотиться на оленей. Олени сильные и быстрые животные и защищают свою территорию.$b$bХоть они и питаются одной травой, но бегают так, что охотнику приходится попотеть, чтобы их поймать.$b$bК востоку отсюда полно оленей пустошей. Они только и ждут, чтобы какой-нибудь охотник устроил им хорошую пробежку.$b$bУдачной охоты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 оленей пустошей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С Ясеневого леса у меня не было такой отличной охоты на оленей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мэттом "Везунчиком" Удавахиным в охотничьем лагере Эрнестуэя, что в Долине Четырех Ветров.',`completedtext_loc8`);
