INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32045,'Дети воды','Убейте Красора, Громожабра и Суккулу.','Пусть это станет для тебя уроком: нельзя пить слишком много воды.$B$BТеперь понимаешь, почему у нас такая большая хмелеварня?','Вернитесь к резчику Маку в Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дети воды',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Красора, Громожабра и Суккулу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть это станет для тебя уроком: нельзя пить слишком много воды.$B$BТеперь понимаешь, почему у нас такая большая хмелеварня?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к резчику Маку в Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
