INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32105,'Безупречная надгробная плита','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.','Выставите артефакт на обозрение.','Выставите артефакт в Обители Мудрости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная надгробная плита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выставите артефакт на обозрение.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выставите артефакт в Обители Мудрости.',`completedtext_loc8`);
