INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32108,'Крепость Покорителей','Настало время показать этой новой земле истинную мощь Орды.$B$BВозвращайся на берег и зажги оставшийся сигнальный огонь. Наш флот ждет.','Зажгите сигнальный огонь на берегу в Точке высадки Орды, чтобы подать сигнал флоту Орды.','<Этот огонь подаст сигнал к высадке войск Орды на побережье, что станет началом военной кампании Гарроша в Пандарии.>','Зажгите сигнальный огонь на берегу в Точке высадки Орды, чтобы подать сигнал флоту Орды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость Покорителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время показать этой новой земле истинную мощь Орды.$B$BВозвращайся на берег и зажги оставшийся сигнальный огонь. Наш флот ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите сигнальный огонь на берегу в Точке высадки Орды, чтобы подать сигнал флоту Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Этот огонь подаст сигнал к высадке войск Орды на побережье, что станет началом военной кампании Гарроша в Пандарии.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Зажгите сигнальный огонь на берегу в Точке высадки Орды, чтобы подать сигнал флоту Орды.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32109,'Львиный лагерь','Слишком долго Орда бесчинствовала на просторах Азерота. Я не позволю, чтобы эта новая земля была завоевана каким-то варварским "вождем"!$B$BТы $gготов:готова; защитить берега Пандарии во имя Альянса?$B$BДавай вернемся на место высадки. Там ты воспользуешься установкой для запуска сигнальных ракет, чтобы подать сигнал нашему флоту и начать операцию "Заслон".','Воспользуйтесь установкой для запуска сигнальных ракет в Красарангской бухте, чтобы подать сигнал флоту Альянса.','<Синие паруса едва различимы на горизонте. Это могучий флот Альянса, ожидающий сигнала к высадке.>','Воспользуйтесь установкой для запуска сигнальных ракет в Красарангской бухте, чтобы подать сигнал флоту Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Львиный лагерь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слишком долго Орда бесчинствовала на просторах Азерота. Я не позволю, чтобы эта новая земля была завоевана каким-то варварским "вождем"!$B$BТы $gготов:готова; защитить берега Пандарии во имя Альянса?$B$BДавай вернемся на место высадки. Там ты воспользуешься установкой для запуска сигнальных ракет, чтобы подать сигнал нашему флоту и начать операцию "Заслон".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь установкой для запуска сигнальных ракет в Красарангской бухте, чтобы подать сигнал флоту Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Синие паруса едва различимы на горизонте. Это могучий флот Альянса, ожидающий сигнала к высадке.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь установкой для запуска сигнальных ракет в Красарангской бухте, чтобы подать сигнал флоту Альянса.',`completedtext_loc8`);
