INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32114,'Так ты хочешь потестировать ежедневные задания ?','Хочешь потестить дэйлики? Отлично.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так ты хочешь потестировать ежедневные задания ?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь потестить дэйлики? Отлично.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32115,'Узы прошлого','Могу – это шайка негодяев, поработивших пандаренов, которых затем заставляли работать в пещерах даже после их смерти. Отправляйся туда и освободи порабощенных духов! Они не должны больше страдать!\r\n\r\nОднако будь $gосторожен:осторожна;... эти духи испытали столько боли, что теперь не отличают друзей от врагов. Скорее всего, они примут тебя в штыки.','Освободите 14 беспокойных духов рабов.','Ты сделал доброе дело. Это ужасно – видеть, как души мертвых не могут найти покой.','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узы прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу – это шайка негодяев, поработивших пандаренов, которых затем заставляли работать в пещерах даже после их смерти. Отправляйся туда и освободи порабощенных духов! Они не должны больше страдать!\r\n\r\nОднако будь $gосторожен:осторожна;... эти духи испытали столько боли, что теперь не отличают друзей от врагов. Скорее всего, они примут тебя в штыки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 14 беспокойных духов рабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделал доброе дело. Это ужасно – видеть, как души мертвых не могут найти покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32116,'Не забываем о приоритетах!','Когда я приказал раскопать тоннель к северо-западу отсюда, то был уверен, что мы найдем там что-нибудь полезное. Золото, железо... хоть что-нибудь!\r\n\r\nВместо этого мы обнаружили артефакты могу и в довесок получили дворфов из Лиги исследователей, с которыми нужно нянчиться.\r\n\r\nСолдаты доложили мне о сложной ситуации в шахтах. Ринн приказал мне оказывать поддержку Лиге исследователей, но я не могу послать туда своих людей. Может быть, ты выяснишь, что там происходит?','Встретьтесь с Хильдой Хорнсвоггл на Руинах Огудея в Красарангских джунглях.','У-у, да у нас там серьезная проблема. Словно целый улей разворошили. Только вместо пчел там призрачные шершни могу с гигантскими жалами!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не забываем о приоритетах!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я приказал раскопать тоннель к северо-западу отсюда, то был уверен, что мы найдем там что-нибудь полезное. Золото, железо... хоть что-нибудь!\r\n\r\nВместо этого мы обнаружили артефакты могу и в довесок получили дворфов из Лиги исследователей, с которыми нужно нянчиться.\r\n\r\nСолдаты доложили мне о сложной ситуации в шахтах. Ринн приказал мне оказывать поддержку Лиге исследователей, но я не могу послать туда своих людей. Может быть, ты выяснишь, что там происходит?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Хильдой Хорнсвоггл на Руинах Огудея в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У-у, да у нас там серьезная проблема. Словно целый улей разворошили. Только вместо пчел там призрачные шершни могу с гигантскими жалами!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (32118,'Воспользоваться преимуществом','Идиоты из Лиги исследователей раскопали древние руины могу на северо-востоке. И, конечно же, потревожили обитающих там духов могу.\r\n\r\nМы воспользуемся их оплошкой. Зайди в этот портал и свяжись с Келисом Солнечным Полетом, моим агентом в районе руин.','Вот как? Значит, подмога от Беллока. Он сам никогда не берется за грязную работенку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воспользоваться преимуществом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Идиоты из Лиги исследователей раскопали древние руины могу на северо-востоке. И, конечно же, потревожили обитающих там духов могу.\r\n\r\nМы воспользуемся их оплошкой. Зайди в этот портал и свяжись с Келисом Солнечным Полетом, моим агентом в районе руин.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот как? Значит, подмога от Беллока. Он сам никогда не берется за грязную работенку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32119,'Это загадка','Нечто распугало всех рабочих. Некая аномалия... может, привидение или заклятие... Я никогда не сталкивалась с подобным.\r\n\r\nМне удалось засечь необычный сигнал и настроить на него это устройство. Экран тебе подскажет, насколько близко ты $gподошел:подошла; к цели.\r\n\r\nКогда подберешься к аномалии вплотную, затяни ее внутрь ловушки и покончи с ней навсегда!','Воспользуйтесь детектором аномалии, который дала вам Хильда, и уничтожьте аномалию.','Молодец. Теперь нужно просто подождать, пока все успокоится.','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это загадка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нечто распугало всех рабочих. Некая аномалия... может, привидение или заклятие... Я никогда не сталкивалась с подобным.\r\n\r\nМне удалось засечь необычный сигнал и настроить на него это устройство. Экран тебе подскажет, насколько близко ты $gподошел:подошла; к цели.\r\n\r\nКогда подберешься к аномалии вплотную, затяни ее внутрь ловушки и покончи с ней навсегда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь детектором аномалии, который дала вам Хильда, и уничтожьте аномалию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец. Теперь нужно просто подождать, пока все успокоится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32120,'Наследие Огудея','Руины, на которых мы расположились, были в свое время построены Огудеем, древним правителем могу. Мы мало о нем знаем, но повышенная активность духов в этом месте наводит на мысль о том, что он занимался их порабощением.\r\n\r\nПри уничтожении духа частица его сущности остается в нашем мире. Принеси нам такие частицы для исследований. Может быть, они помогут пролить свет на историю и могущество Огудея.','Соберите 5 древних частиц духов могу.','Отлично. Мы немедленно приступим к исследованиям.','Чтобы получить эссенцию, нужно вначале уничтожить духов. Приступай!','Вернитесь к Келису Солнечному Полету на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Огудея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руины, на которых мы расположились, были в свое время построены Огудеем, древним правителем могу. Мы мало о нем знаем, но повышенная активность духов в этом месте наводит на мысль о том, что он занимался их порабощением.\r\n\r\nПри уничтожении духа частица его сущности остается в нашем мире. Принеси нам такие частицы для исследований. Может быть, они помогут пролить свет на историю и могущество Огудея.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 древних частиц духов могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Мы немедленно приступим к исследованиям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы получить эссенцию, нужно вначале уничтожить духов. Приступай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келису Солнечному Полету на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32121,'Ловушка для духа','Среди руин кое-где попадаются ярко-синие кристаллы. Если на них косо посмотреть, то можно получить ораву кровожадных духов на свою голову.\r\n\r\nВ общем, если хочешь, чтобы мои ребята туда вернулись, то сначала расчисти руины от кристаллов.','Уничтожьте 3 ловушки для духов.','Противные штуковины! Благодарим за твою помощь.','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка для духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди руин кое-где попадаются ярко-синие кристаллы. Если на них косо посмотреть, то можно получить ораву кровожадных духов на свою голову.\r\n\r\nВ общем, если хочешь, чтобы мои ребята туда вернулись, то сначала расчисти руины от кристаллов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 ловушки для духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Противные штуковины! Благодарим за твою помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32122,'Служители Огудея','Когда я вела раскопки в древней части руин могу, то наткнулась на неприятный сюрприз. Именно оттуда вылезли два самых мерзких призрака.\r\n\r\n$gПриятель:Подруга;, нам нужно от них избавиться.','Убейте Мэн-до, Силу Гор, и Гэнь-ли, Играющего со Словами.','Молодец! Прими мои поздравления! Что бы мы без тебя делали!$B$BБудем надеяться, что с призраками покончено…','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Служители Огудея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я вела раскопки в древней части руин могу, то наткнулась на неприятный сюрприз. Именно оттуда вылезли два самых мерзких призрака.\r\n\r\n$gПриятель:Подруга;, нам нужно от них избавиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мэн-до, Силу Гор, и Гэнь-ли, Играющего со Словами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Прими мои поздравления! Что бы мы без тебя делали!$B$BБудем надеяться, что с призраками покончено…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32123,'Стоять насмерть','Альянс, осуществил высадку на берег. Если мы сейчас потерпим поражение, то Орда не сможет удержаться на этом континенте.$b$bОтправляйся на поле боя к югу отсюда и перебей там всех воинов Альянса, которые только встретятся тебе на пути.$b$bПокажи им, что любой ордынец, который в силах стоять на ногах, способен забрать с собой десяток солдат Альянса!','Уничтожьте 10 солдат Альянса в Крепости Покорителей.','Отличная работа, Аверус. Вижу, что здешние места закалили твою волю и помогли отточить боевые навыки.','Поговорите с Шокиа в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стоять насмерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс, осуществил высадку на берег. Если мы сейчас потерпим поражение, то Орда не сможет удержаться на этом континенте.$b$bОтправляйся на поле боя к югу отсюда и перебей там всех воинов Альянса, которые только встретятся тебе на пути.$b$bПокажи им, что любой ордынец, который в силах стоять на ногах, способен забрать с собой десяток солдат Альянса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 солдат Альянса в Крепости Покорителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, Аверус. Вижу, что здешние места закалили твою волю и помогли отточить боевые навыки.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Шокиа в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (32125,'Don\'t Try So Hard - DEPRECATED','А, |3-6($c)! Тебя-то мне как раз и не хватало.$b$bМне донесли, что шпионы Альянса выползли из крепости. Жаль, что они так ничему и не научились! Так что давай, покажи им, на что ты $gспособен:способна;.$b$bНужно перебить парочку шпионов в назидание остальным.$b$bВозьми с собой мою последнюю разработку – "Вонючий выкуриватель шпионов" с улучшенной формулой. Просто бросай эти гранаты у стен крепости на юге, и эти жалкие лазутчики сами выпрыгнут из нор.','Убейте 8 саботажников ШРУ.','Поговорите с проекцией торгового принца Галливикса в Крепости Покорителей, что в Красарангских джунглях.','Вам кажется, что его голос раздается из… ближайшего куста.','Торговый принц Галливикс') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Don\'t Try So Hard - DEPRECATED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, |3-6($c)! Тебя-то мне как раз и не хватало.$b$bМне донесли, что шпионы Альянса выползли из крепости. Жаль, что они так ничему и не научились! Так что давай, покажи им, на что ты $gспособен:способна;.$b$bНужно перебить парочку шпионов в назидание остальным.$b$bВозьми с собой мою последнюю разработку – "Вонючий выкуриватель шпионов" с улучшенной формулой. Просто бросай эти гранаты у стен крепости на юге, и эти жалкие лазутчики сами выпрыгнут из нор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 саботажников ШРУ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией торгового принца Галливикса в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Вам кажется, что его голос раздается из… ближайшего куста.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Торговый принц Галливикс',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32126,'Разбить ящики','Бойцы Альянса – трусы, но не дураки. Если бы вместо нас им противостоял другой противник, то их операция могла бы оказаться успешной.$b$bОни постоянно снабжают высадившихся боеприпасами с воздуха. Это позволяет им продолжать осаду и атаковать наши позиции.$b$bОсмотри пляжи и доки к югу отсюда и уничтожь все сброшенные контейнеры с поставками, которые найдешь.$b$bПусть солдаты Альянса придут в уныние при виде уничтоженных продуктов и боеприпасов.','Уничтожьте 8 поставок Альянса.','Помни, что самое лучшее оружие – не всегда то, которое стреляет дальше всего или наносит самый большой урон. На самом деле, лучшее оружие – это то, которое стреляет безотказно.','Поговорите с Броликом в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбить ящики',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бойцы Альянса – трусы, но не дураки. Если бы вместо нас им противостоял другой противник, то их операция могла бы оказаться успешной.$b$bОни постоянно снабжают высадившихся боеприпасами с воздуха. Это позволяет им продолжать осаду и атаковать наши позиции.$b$bОсмотри пляжи и доки к югу отсюда и уничтожь все сброшенные контейнеры с поставками, которые найдешь.$b$bПусть солдаты Альянса придут в уныние при виде уничтоженных продуктов и боеприпасов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 поставок Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Помни, что самое лучшее оружие – не всегда то, которое стреляет дальше всего или наносит самый большой урон. На самом деле, лучшее оружие – это то, которое стреляет безотказно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Броликом в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32127,'Все мертвы, все мертвы','Наш вождь отправил меня сюда, чтобы раз и навсегда расправиться с угрозой со стороны Альянса.$b$bУ этих людишек и их союзников есть только одно слабое место – они не способны сражаться без предводителя.$b$bКогда будешь $gготов:готова;, отправляйся на поле битвы и высматривай корабли противника вдоль южного берега.$b$bНайди капитанов и убей их. За Орду!','Победите капитана Брента Черного и капитана Малки.','Недостаточно уничтожить лидеров Альянса. Нужно дать остальным понять, какую цену им придется заплатить, если они хотят занять место погибших.','Поговорите с Броликом в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все мертвы, все мертвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш вождь отправил меня сюда, чтобы раз и навсегда расправиться с угрозой со стороны Альянса.$b$bУ этих людишек и их союзников есть только одно слабое место – они не способны сражаться без предводителя.$b$bКогда будешь $gготов:готова;, отправляйся на поле битвы и высматривай корабли противника вдоль южного берега.$b$bНайди капитанов и убей их. За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите капитана Брента Черного и капитана Малки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недостаточно уничтожить лидеров Альянса. Нужно дать остальным понять, какую цену им придется заплатить, если они хотят занять место погибших.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Броликом в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32128,'Еще один урок','Флот Альянса подошел к южному берегу и ведет оттуда артиллерийский обстрел наших позиций. Посмотрим, что станет с их осадой без огневой поддержки.$b$bПроникни на вражеские корабли и уничтожь их боезапасы. Это значительно ослабит натиск противника.','Уничтожьте взрывоопасный груз на "Непокорном" и на "Клинке Доблести".','Корабли горят! Но просто так их не потопить. Уверен, что через день-два они потушат пожар.','Поговорите с кровавым стражем Гро\'ташем в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще один урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Флот Альянса подошел к южному берегу и ведет оттуда артиллерийский обстрел наших позиций. Посмотрим, что станет с их осадой без огневой поддержки.$b$bПроникни на вражеские корабли и уничтожь их боезапасы. Это значительно ослабит натиск противника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте взрывоопасный груз на "Непокорном" и на "Клинке Доблести".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Корабли горят! Но просто так их не потопить. Уверен, что через день-два они потушат пожар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кровавым стражем Гро\'ташем в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32129,'Defense Daily 06') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Defense Daily 06',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32130,'Богатое месторождение','У меня тут целая очередь клиентов, которые хотят приобрести старые добрые уши! Да не любые, а только самые толстые, какие только можно найти!\r\n\r\nНаверное, они верят, что подобные уши приносят удачу.\r\n\r\nКороче говоря, достань для меня такие уши. Только не трогай местных животных. Лучше отправляйся во Львиный лагерь за ушами Альянса!\r\n\r\nПовеселись там на здоровье. Не забудь, что мне нужны только лучшие уши!','Соберите 10 толстых ушей Альянса во Львином лагере, что в Красарангских джунглях.','Хорошие и толстые. Как по заказу. Ах, да… Вот твоя доля.','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Богатое месторождение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня тут целая очередь клиентов, которые хотят приобрести старые добрые уши! Да не любые, а только самые толстые, какие только можно найти!\r\n\r\nНаверное, они верят, что подобные уши приносят удачу.\r\n\r\nКороче говоря, достань для меня такие уши. Только не трогай местных животных. Лучше отправляйся во Львиный лагерь за ушами Альянса!\r\n\r\nПовеселись там на здоровье. Не забудь, что мне нужны только лучшие уши!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 толстых ушей Альянса во Львином лагере, что в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошие и толстые. Как по заказу. Ах, да… Вот твоя доля.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32131,'Нам нужно больше минералов','Гномы добывают камни могу в карьере на северо-востоке.\r\n\r\nА потом, представь себе, строят из них всякую ерунду!\r\n\r\n<Заззикс закатывает глаза.>\r\n\r\nИдиоты, они даже не понимают, что эти самые камни использовались для возведения живых статуй! \r\n\r\nА мы могли бы улучшить камни с помощью гоблинских технологий и устроить огромный взрыв!\r\n\r\nНо притащить сюда их будет нелегко – камни тяжелые. Гномы отправили на их добычу дурацких взрывоботов. Знаешь что... повзрывай-ка эти махины рядом с глыбами и принеси мне каменные обломки.\r\n\r\nИли просто перебей там всех и забери камни. На твое усмотрение.','Соберите 20 живых камней в карьере Львиного лагеря. Их можно забрать у инженеров из Львиного лагеря или добыть, взрывая раскопоботов возле каменных глыб.','О, да! Ты принес камни! Сейчас я изготовлю самую лучшую бомбу в мире!$B$BТы не представляешь, как я люблю бомбы! Вначале мастерить их, а потом устраивать ба-бах…$B$BХм, да, именно так я и лишился одного глаза. А тебе-то что?','Где камни? У меня руки чешутся что-нибудь подорвать!','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нам нужно больше минералов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномы добывают камни могу в карьере на северо-востоке.\r\n\r\nА потом, представь себе, строят из них всякую ерунду!\r\n\r\n<Заззикс закатывает глаза.>\r\n\r\nИдиоты, они даже не понимают, что эти самые камни использовались для возведения живых статуй! \r\n\r\nА мы могли бы улучшить камни с помощью гоблинских технологий и устроить огромный взрыв!\r\n\r\nНо притащить сюда их будет нелегко – камни тяжелые. Гномы отправили на их добычу дурацких взрывоботов. Знаешь что... повзрывай-ка эти махины рядом с глыбами и принеси мне каменные обломки.\r\n\r\nИли просто перебей там всех и забери камни. На твое усмотрение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 живых камней в карьере Львиного лагеря. Их можно забрать у инженеров из Львиного лагеря или добыть, взрывая раскопоботов возле каменных глыб.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! Ты принес камни! Сейчас я изготовлю самую лучшую бомбу в мире!$B$BТы не представляешь, как я люблю бомбы! Вначале мастерить их, а потом устраивать ба-бах…$B$BХм, да, именно так я и лишился одного глаза. А тебе-то что?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где камни? У меня руки чешутся что-нибудь подорвать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32132,'Травля рабочих','Боюсь, наши друзья-гоблины имеют слабое представление о стратегии затяжной войны.\r\n\r\nДля взятия укрепленных позиций противника требуется вначале отобрать у него возможность пополнять резервы и отстраивать базу.\r\n\r\nВ данном случае мы говорим о крестьянах. Если их уничтожить, то оборона противника ослабнет. А после этого падет и вся крепость.','Убейте 30 крестьян из Львиного лагеря.','Хорошо. Это, по меньшей мере, на несколько дней внесет смятение в их ряды.$B$BВойну за раз не выиграешь, но уверяю тебя, мы на верном пути.','Вернитесь к темному мастеру Кирин на Аванпост Искрожига в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Травля рабочих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, наши друзья-гоблины имеют слабое представление о стратегии затяжной войны.\r\n\r\nДля взятия укрепленных позиций противника требуется вначале отобрать у него возможность пополнять резервы и отстраивать базу.\r\n\r\nВ данном случае мы говорим о крестьянах. Если их уничтожить, то оборона противника ослабнет. А после этого падет и вся крепость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 крестьян из Львиного лагеря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Это, по меньшей мере, на несколько дней внесет смятение в их ряды.$B$BВойну за раз не выиграешь, но уверяю тебя, мы на верном пути.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин на Аванпост Искрожига в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32133,'Наблюдательные тотемы','Вражеская база слишком хорошо прикрыта с воздуха. Над ней летает слишком много дворфов на грифонах. Это значит, что нам не рассмотреть базу сверху.\r\n\r\nОдин тролль... по дружбе поделился со мной наблюдательными тотемами, которые могут помочь нам увидеть, что же там происходит.\r\n\r\nЭто хорошая новость, а плохая – это то, что тебе придется их туда отнести.','Установите наблюдательные тотемы на пристани, в ратуше и на втором этаже казарм Львиного лагеря.','Вернитесь к темному мастеру Кирин во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдательные тотемы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вражеская база слишком хорошо прикрыта с воздуха. Над ней летает слишком много дворфов на грифонах. Это значит, что нам не рассмотреть базу сверху.\r\n\r\nОдин тролль... по дружбе поделился со мной наблюдательными тотемами, которые могут помочь нам увидеть, что же там происходит.\r\n\r\nЭто хорошая новость, а плохая – это то, что тебе придется их туда отнести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите наблюдательные тотемы на пристани, в ратуше и на втором этаже казарм Львиного лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32134,'Жесткий отпор','Убейте 8 инженеров дворфийских орудий и 2 дворфийские мортиры Львиного лагеря.','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жесткий отпор',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 инженеров дворфийских орудий и 2 дворфийские мортиры Львиного лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Заззиксу "Поджаренному" Искрожигу на Аванпост Искрожига, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32135,'Смерть героям!','Порой уничтожить пару вражеских бойцов важнее, чем расправиться с целой сотней.\r\n\r\nПротивник пустил в бой несколько героев, которые воодушевляют остальных солдат своим присутствием. Если их убрать, это не только подорвет вражескую оборону, но и деморализует противника.\r\n\r\nИтак, ликвидируй для меня одного героя. Я знаю, ты справишься.','Убейте героя Альянса во Львином лагере, что в Красарангских джунглях.','Тело без головы долго не живет.$B$B…если, конечно, ты не Отрекшийся. Наверное, в моем положении стоит придумать другую поговорку.','Вернитесь к темному мастеру Кирин во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть героям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Порой уничтожить пару вражеских бойцов важнее, чем расправиться с целой сотней.\r\n\r\nПротивник пустил в бой несколько героев, которые воодушевляют остальных солдат своим присутствием. Если их убрать, это не только подорвет вражескую оборону, но и деморализует противника.\r\n\r\nИтак, ликвидируй для меня одного героя. Я знаю, ты справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте героя Альянса во Львином лагере, что в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тело без головы долго не живет.$B$B…если, конечно, ты не Отрекшийся. Наверное, в моем положении стоит придумать другую поговорку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному мастеру Кирин во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (32136,'Заказ: топливо','Наши запасы топлива на исходе, а без горючего мы не сможем запустить строительные механизмы. Что же мне тогда делать? Таскать кирпичи руками?$b$bНет уж, я не приспособлена для тяжелого труда! Я же себе маникюр испорчу!$b$bВсе, ступай на нефтезавод и заставь их выполнить сверхурочный заказ. Бегом! Мне утром уже примеривали пояс с инструментами. Он еще ужасно не подходил по цвету к моим ботинкам.','Маловато топлива! Что, Ее "Милейшество" боится, что ей придется вылезти из шезлонга?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: топливо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши запасы топлива на исходе, а без горючего мы не сможем запустить строительные механизмы. Что же мне тогда делать? Таскать кирпичи руками?$b$bНет уж, я не приспособлена для тяжелого труда! Я же себе маникюр испорчу!$b$bВсе, ступай на нефтезавод и заставь их выполнить сверхурочный заказ. Бегом! Мне утром уже примеривали пояс с инструментами. Он еще ужасно не подходил по цвету к моим ботинкам.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Маловато топлива! Что, Ее "Милейшество" боится, что ей придется вылезти из шезлонга?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32137,'Топливо на исходе','Какое исключительное топливо! К сожалению, оно нуждается в дополнительной очистке.$b$bГоворят, есть такая система, которая использует морскую воду в качестве катализатора при очистке. Честно говоря, у меня нет времени разбираться, как она работает, так что я просто закинул бочки в воду.$b$bЗнаю, знаю, я молодец. Вот только не знаю, как их теперь оттуда достать...$b$bМожет быть, ты мне сможешь помочь?','Соберите 9 бочек с "очищенным" топливом в Водосливе Черных Песков.','Хм, почему бочки мокрые? Ладно, давай сюда. Хорошо хоть ты успел до того, как они заставили меня взяться за дело. Что может быть ужаснее работы?','Выходит, для водослива нашлось применение? Хоть какая-то от него будет польза...','Вернитесь к леди-боссу Триксель в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Топливо на исходе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какое исключительное топливо! К сожалению, оно нуждается в дополнительной очистке.$b$bГоворят, есть такая система, которая использует морскую воду в качестве катализатора при очистке. Честно говоря, у меня нет времени разбираться, как она работает, так что я просто закинул бочки в воду.$b$bЗнаю, знаю, я молодец. Вот только не знаю, как их теперь оттуда достать...$b$bМожет быть, ты мне сможешь помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 бочек с "очищенным" топливом в Водосливе Черных Песков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, почему бочки мокрые? Ладно, давай сюда. Хорошо хоть ты успел до того, как они заставили меня взяться за дело. Что может быть ужаснее работы?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выходит, для водослива нашлось применение? Хоть какая-то от него будет польза...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди-боссу Триксель в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32138,'Заказ: лес','Каждый день одно и то же! У нас закончилось то, у нас закончилось се, пойди да принеси! Можно подумать, я тут прохлаждаюсь!$b$bА я работаю! Я вкалываю как проклятый як! Я тут такие штуки делаю, что берегись!$b$bА они мне – нужно больше бревен! Ну, чего ты стоишь как $gвкопанный:вкопанная;? Пойди скажи этому остолопу Зино, чтобы запускал свои крошшеры!','Найдите Зино "Крошшера" Скоротяпеля на лесопилке.','Остолоп?! Да я тут из кожи вон лезу!$B$BМожет, Ее "Бесполезность" соизволит подойти сюда и заготовить лес своими руками?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: лес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый день одно и то же! У нас закончилось то, у нас закончилось се, пойди да принеси! Можно подумать, я тут прохлаждаюсь!$b$bА я работаю! Я вкалываю как проклятый як! Я тут такие штуки делаю, что берегись!$b$bА они мне – нужно больше бревен! Ну, чего ты стоишь как $gвкопанный:вкопанная;? Пойди скажи этому остолопу Зино, чтобы запускал свои крошшеры!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Зино "Крошшера" Скоротяпеля на лесопилке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остолоп?! Да я тут из кожи вон лезу!$B$BМожет, Ее "Бесполезность" соизволит подойти сюда и заготовить лес своими руками?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32139,'Лесозаготовка','Мы только что выполнили предыдущий заказ сегодня утром. Как, во имя всего святого, они успели израсходовать все бревна за такой короткий срок?!$b$bМои лесорубы работают в две смены, рубят деревья и обрабатывают древесину!$b$bВот только им постоянно мешают солдаты из Львиного лагеря. Я уже разок оказался на волосок от смерти, так что больше туда не сунусь!$b$bГууб пойдет с тобой и поможет с заказом. Он немного туповат, но зато хорошо таскает бревна.','Соберите 9 досок Крепости Покорителей на Лесопилке Скоротяпеля.','Наконец-то ты принес доски! Я уж думал, придется самому отправляться за стройматериалами.','Вернитесь к Зино "Крошшеру" Скоротяпелю на Лесопилку Скоротяпеля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесозаготовка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы только что выполнили предыдущий заказ сегодня утром. Как, во имя всего святого, они успели израсходовать все бревна за такой короткий срок?!$b$bМои лесорубы работают в две смены, рубят деревья и обрабатывают древесину!$b$bВот только им постоянно мешают солдаты из Львиного лагеря. Я уже разок оказался на волосок от смерти, так что больше туда не сунусь!$b$bГууб пойдет с тобой и поможет с заказом. Он немного туповат, но зато хорошо таскает бревна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 досок Крепости Покорителей на Лесопилке Скоротяпеля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то ты принес доски! Я уж думал, придется самому отправляться за стройматериалами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зино "Крошшеру" Скоротяпелю на Лесопилку Скоротяпеля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32140,'Заказ: руда','Когда мне доложили, что в шахте нашли какие-то удивительные камни, я, разумеется, сразу представила себе алмазы. Все знают, что из шахт добывают алмазы! Ну, в крайнем случае, рубины...$b$bА вместо этого мне приносят какую-то странную железяку! И что, скажите на милость, мне с ней делать?$b$bАх, ну конечно, никто и не обещал мне блестящей карьеры. Но я всего лишь стараюсь делать свое дело с огоньком.$b$bИ к тому же, на железо только что поступил новый заказ. Так что отправляйся к Дакси ко входу в Карьер Рудогрызя и наполни тележку железной рудой!','Найдите "Бриллиантовую" Дакси Рудогрызь у карьера Рудогрызя".','Она все еще жалуется по поводу брильянтов и рубинов? Мы тут нашли для нее кое-что получше брильянтов.$B$BЭта руда особенная. Она наделена силой!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мне доложили, что в шахте нашли какие-то удивительные камни, я, разумеется, сразу представила себе алмазы. Все знают, что из шахт добывают алмазы! Ну, в крайнем случае, рубины...$b$bА вместо этого мне приносят какую-то странную железяку! И что, скажите на милость, мне с ней делать?$b$bАх, ну конечно, никто и не обещал мне блестящей карьеры. Но я всего лишь стараюсь делать свое дело с огоньком.$b$bИ к тому же, на железо только что поступил новый заказ. Так что отправляйся к Дакси ко входу в Карьер Рудогрызя и наполни тележку железной рудой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите "Бриллиантовую" Дакси Рудогрызь у карьера Рудогрызя".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она все еще жалуется по поводу брильянтов и рубинов? Мы тут нашли для нее кое-что получше брильянтов.$B$BЭта руда особенная. Она наделена силой!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32141,'Мощный металл','Соберите 7 кусков заряженной руды в карьере Рудогрызя.','Им удалось найти в шахте что-нибудь полезное? Какой-нибудь изумруд или опал? Или им так сложно пошевелиться?$B$BНеважно. Я сама прослежу, чтобы груз доставили, куда следует.','Тебе удалось найти в шахте что-нибудь блестящее?','Вернитесь к леди-боссу Триксель в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощный металл',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 кусков заряженной руды в карьере Рудогрызя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Им удалось найти в шахте что-нибудь полезное? Какой-нибудь изумруд или опал? Или им так сложно пошевелиться?$B$BНеважно. Я сама прослежу, чтобы груз доставили, куда следует.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти в шахте что-нибудь блестящее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди-боссу Триксель в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32142,'Разрушительная мощь','Нельзя позволить, чтобы орки захватили эти земли. Они осквернят и разорят их, как Калимдор.$b$b$p, я хочу, чтобы над этим континентом развевался наш флаг, а ордынцы лежали в гробах. Ступай на побережье и обрушь на захватчиков всю мощь Альянса!$b$bЗа короля!','Убейте 10 орков в Крепости Покорителей.','Отлично, солдат. Это поможет нам обуздать Орду.','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушительная мощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя позволить, чтобы орки захватили эти земли. Они осквернят и разорят их, как Калимдор.$b$b$p, я хочу, чтобы над этим континентом развевался наш флаг, а ордынцы лежали в гробах. Ступай на побережье и обрушь на захватчиков всю мощь Альянса!$b$bЗа короля!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 орков в Крепости Покорителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, солдат. Это поможет нам обуздать Орду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (32143,'Некая магия','Привет, $p! Наслышан, наслышан о твоих подвигах на поле битвы. Не желаешь ли испытать мой новый "Осад-о-матик"? Это универсальное, многофункциональное устройство! При его испытаниях почти никто не пострадал.$b$bА если будешь проходить мимо Крепости Покорителей, не зевай – ищи мои развед-о-метры. Они настроены на обнаружение подходящих целей для уничтожения. Как только найдешь развед-о-метр, активируй его, и я отправлю осад-о-матик в точку, где ты находишься.$b$bДо встречи на поле боевых действий, так сказать!','Поговорите с мехмастером Замыкальцем на "Небесном огне" в Красарангских джунглях.','Сигнал передается при помощи множества скрытых устройств.','Мехмастер Замыкалец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некая магия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $p! Наслышан, наслышан о твоих подвигах на поле битвы. Не желаешь ли испытать мой новый "Осад-о-матик"? Это универсальное, многофункциональное устройство! При его испытаниях почти никто не пострадал.$b$bА если будешь проходить мимо Крепости Покорителей, не зевай – ищи мои развед-о-метры. Они настроены на обнаружение подходящих целей для уничтожения. Как только найдешь развед-о-метр, активируй его, и я отправлю осад-о-матик в точку, где ты находишься.$b$bДо встречи на поле боевых действий, так сказать!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мехмастером Замыкальцем на "Небесном огне" в Красарангских джунглях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Сигнал передается при помощи множества скрытых устройств.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Мехмастер Замыкалец',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32144,'Враг под напором','Орда всегда отличалась боевой доблестью. Их воины пойдут на смерть без малейших раздумий.$b$bМы должны найти способ сломить их волю, не потеряв при этом наших солдат.$b$bНайди припасы Орды, спрятанные вдоль побережья и возле их кораблей. Уничтожь их все до единого.$b$bНет ничего хуже, чем видеть, как твои надежды на сытный ужин улетучиваются вместе с дымом.$b$bКогда закончишь, найди Салли за лагерем противника. У него есть для тебя поручение.','Уничтожьте 8 ящиков с припасами Орды.','Благодаря тебе Орда теперь не сможет пополнить припасы своей армии.$B$BТеперь им не выстоять под нашей осадой, а вражеский боевой дух вскоре падет.$B$BНужно продолжить наш напор.','Поговорите с Мишкой на борту "Небесного огня" в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг под напором',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда всегда отличалась боевой доблестью. Их воины пойдут на смерть без малейших раздумий.$b$bМы должны найти способ сломить их волю, не потеряв при этом наших солдат.$b$bНайди припасы Орды, спрятанные вдоль побережья и возле их кораблей. Уничтожь их все до единого.$b$bНет ничего хуже, чем видеть, как твои надежды на сытный ужин улетучиваются вместе с дымом.$b$bКогда закончишь, найди Салли за лагерем противника. У него есть для тебя поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 ящиков с припасами Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе Орда теперь не сможет пополнить припасы своей армии.$B$BТеперь им не выстоять под нашей осадой, а вражеский боевой дух вскоре падет.$B$BНужно продолжить наш напор.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мишкой на борту "Небесного огня" в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32145,'Не теряй головы','Мои приборы обнаружили во дворе Крепости Покорителей три очень опасные цели.$b$bЭто эмиссар огров, кор\'кронский офицер и полоумный гоблин, изготавливающий бомбы.$b$bМои осад-о-матики пока не готовы к одиночному бою, так что тебе придется разобраться с этими целями.$b$bУдачи! Когда закончишь – сообщи мне. Я буду на "Небесном огне".','Победите каменного стража Рук\'ру, бумженера Зарубеня и Ор\'дака.','Превосходно! Прости, что пришлось подвергнуть опасности такого славного солдата, но мой Авто-Уничтож-о-троник Мк 2 пока еще не готов.','Поговорите с мехмастером Замыкальцем на борту "Небесного огня" в Красарангских джунглях.','Сигнал передается посредством множества скрытых устройств.','Мехмастер Замыкалец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не теряй головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои приборы обнаружили во дворе Крепости Покорителей три очень опасные цели.$b$bЭто эмиссар огров, кор\'кронский офицер и полоумный гоблин, изготавливающий бомбы.$b$bМои осад-о-матики пока не готовы к одиночному бою, так что тебе придется разобраться с этими целями.$b$bУдачи! Когда закончишь – сообщи мне. Я буду на "Небесном огне".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите каменного стража Рук\'ру, бумженера Зарубеня и Ор\'дака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Прости, что пришлось подвергнуть опасности такого славного солдата, но мой Авто-Уничтож-о-троник Мк 2 пока еще не готов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с мехмастером Замыкальцем на борту "Небесного огня" в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сигнал передается посредством множества скрытых устройств.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мехмастер Замыкалец',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32146,'Молот гнева','Похоже, Орда считает, что может спрятаться за своими гориллоподобными балбесами.$b$bЭти охламоны, конечно, сильные, но тупые как пробки.$b$bИди и обрушь на них молот гнева Альянса!','Убейте 5 неуклюжих балбесов.','Спасибо, солдат. Пусть Орда придумает что-нибудь получше балбесов. Нас таким добром не испугаешь.','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот гнева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, Орда считает, что может спрятаться за своими гориллоподобными балбесами.$b$bЭти охламоны, конечно, сильные, но тупые как пробки.$b$bИди и обрушь на них молот гнева Альянса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 неуклюжих балбесов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, солдат. Пусть Орда придумает что-нибудь получше балбесов. Нас таким добром не испугаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32147,'Attack Daily 06') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Attack Daily 06',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32148,'Защита базы','Во вражеской армии, конечно, много рубак, которые только и ждут момента, когда смогут прорвать нашу оборону, чтобы всех тут перерезать.\r\n\r\nВот только не о них я сейчас думаю. У врага есть еще шаманы и налетчики. Шаманы используют магию, чтобы усилить рубак, а налетчики могут осуществлять молниеносные набеги на наши строения.\r\n\r\nНужно, чтобы ты $gубил:убила; несколько таких шаманов и налетчиков.\r\n\r\nИтак, за дело! Защищай базу!','Убейте 12 шаманов или налетчиков из Крепости Покорителей.','Отлично сработано, солдат. Думаю, без шаманов и налетчиков им наши укрепления окажутся не по зубам.','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита базы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во вражеской армии, конечно, много рубак, которые только и ждут момента, когда смогут прорвать нашу оборону, чтобы всех тут перерезать.\r\n\r\nВот только не о них я сейчас думаю. У врага есть еще шаманы и налетчики. Шаманы используют магию, чтобы усилить рубак, а налетчики могут осуществлять молниеносные набеги на наши строения.\r\n\r\nНужно, чтобы ты $gубил:убила; несколько таких шаманов и налетчиков.\r\n\r\nИтак, за дело! Защищай базу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 шаманов или налетчиков из Крепости Покорителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, солдат. Думаю, без шаманов и налетчиков им наши укрепления окажутся не по зубам.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32149,'Сбор ресурсов','Бедные фермеры...\r\n\r\nДа, конечно, они трусоваты. Но они ведь попросту не умеют сражаться, а им нужно заготавливать для нас древесину. Ордынцы нападают на них... все это просто ужасно!\r\n\r\nНо если мы хотим продержаться, нам нужна эта древесина. Отправляйся туда и собери все брошенные ими бревна.','Соберите 12 бревен Львиного лагеря, вытаскивая их из штабелей брошенной в спешке древесины.','Удалось собрать бревна?','Вернитесь к Мишке в Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор ресурсов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедные фермеры...\r\n\r\nДа, конечно, они трусоваты. Но они ведь попросту не умеют сражаться, а им нужно заготавливать для нас древесину. Ордынцы нападают на них... все это просто ужасно!\r\n\r\nНо если мы хотим продержаться, нам нужна эта древесина. Отправляйся туда и собери все брошенные ими бревна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 бревен Львиного лагеря, вытаскивая их из штабелей брошенной в спешке древесины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать бревна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32150,'Отрезать снабжение','Орда решила поручить снабжение армии гоблинам. А там, где гоблины, там и неаккуратно уложенная взрывчатка.\r\n\r\nПо донесениям разведки во вражеских фургонах с припасами перевозят и снаряды для разрушителей. Достаточно чуть-чуть ткнуть ящик с боеприпасами, и он взлетит на воздух.\r\n\r\nЕсли уничтожить достаточно ящиков, то мы оставим врага ни с чем и выиграем время для контрудара, да еще и спасем жизни наших солдат. Так что берись за дело!','Уничтожьте 8 тележек с припасами из Крепости Покорителей.','Без этих припасов они не смогут пополнить свои силы новыми бойцами. А если этого не случится, то у нас появятся прекрасные шансы на победу.$B$BХотя бы в этот день.','Вернитесь к Мишке в Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрезать снабжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда решила поручить снабжение армии гоблинам. А там, где гоблины, там и неаккуратно уложенная взрывчатка.\r\n\r\nПо донесениям разведки во вражеских фургонах с припасами перевозят и снаряды для разрушителей. Достаточно чуть-чуть ткнуть ящик с боеприпасами, и он взлетит на воздух.\r\n\r\nЕсли уничтожить достаточно ящиков, то мы оставим врага ни с чем и выиграем время для контрудара, да еще и спасем жизни наших солдат. Так что берись за дело!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 тележек с припасами из Крепости Покорителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Без этих припасов они не смогут пополнить свои силы новыми бойцами. А если этого не случится, то у нас появятся прекрасные шансы на победу.$B$BХотя бы в этот день.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке в Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32151,'Защита башен','Прекрасно! Теперь мы используем собранную тобой руду, чтобы быстренько залатать бреши в стенах.','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита башен',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Теперь мы используем собранную тобой руду, чтобы быстренько залатать бреши в стенах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32152,'Прорыв осады','Ты им показал, кто тут хозяин, Элрондо. Молодец!','Нужно уничтожить разрушители, солдат!','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорыв осады',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты им показал, кто тут хозяин, Элрондо. Молодец!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно уничтожить разрушители, солдат!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32153,'Смерть героям!','Вижу, ты $gсилен:сильна;. Сильнее многих моих бойцов. Именно поэтому я хочу поручить тебе особое задание.\r\n\r\nОрда посылает против нас своих лучших героев – мастеров клинка, вождей тауренов. В общем, кого только можно.\r\n\r\nЯ хочу, чтобы ты $gуничтожил:уничтожила; одного из героев. Так мы не просто нанесем им серьезный удар, но еще и пошатнем боевой дух.','Убейте героя Орды.','Знаю, что было нелегко, но ты выполнил задачу. Отличная работа. Выражаю тебе свою благодарность, солдат.','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть героям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты $gсилен:сильна;. Сильнее многих моих бойцов. Именно поэтому я хочу поручить тебе особое задание.\r\n\r\nОрда посылает против нас своих лучших героев – мастеров клинка, вождей тауренов. В общем, кого только можно.\r\n\r\nЯ хочу, чтобы ты $gуничтожил:уничтожила; одного из героев. Так мы не просто нанесем им серьезный удар, но еще и пошатнем боевой дух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте героя Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаю, что было нелегко, но ты выполнил задачу. Отличная работа. Выражаю тебе свою благодарность, солдат.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Тротману во Львиный лагерь, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32154,'Поджог','Ситуация с гоблинами совсем вышла из-под контроля! Сперва они вырубили лес и возвели там свою чудовищную буровую установку. А теперь они начали скидывать бочки с нефтью в залив!$b$bНужно положить конец этому кошмару! По крайней мере, остудить гоблинов.$b$bЕсли поджечь их баки с горючим, то впридачу можно спалить и парочку гоблинов!','Используйте нестабильную взрывчатку, чтобы подорвать северо-восточный бак с горючим, северный бак с горючим и северо-западный бак с горючим.','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поджог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ситуация с гоблинами совсем вышла из-под контроля! Сперва они вырубили лес и возвели там свою чудовищную буровую установку. А теперь они начали скидывать бочки с нефтью в залив!$b$bНужно положить конец этому кошмару! По крайней мере, остудить гоблинов.$b$bЕсли поджечь их баки с горючим, то впридачу можно спалить и парочку гоблинов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте нестабильную взрывчатку, чтобы подорвать северо-восточный бак с горючим, северный бак с горючим и северо-западный бак с горючим.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32155,'Вынужденные поломки','Не в моих правилах ломать что-нибудь сознательно, но в данной ситуации этого не избежать.$b$bГоблинская буровая установка держится на честном слове. Так что нужно ею заняться.$b$bМы уже отправили к ней саботажников, но и твоя помощь пригодится, чтобы поскорее снести установку.$b$bОтправляйся туда и сверни несколько вентилей!','Украдите 7 ржавых вентилей с нефтяной платформы на Пляже Трюмных Вод.','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденные поломки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не в моих правилах ломать что-нибудь сознательно, но в данной ситуации этого не избежать.$b$bГоблинская буровая установка держится на честном слове. Так что нужно ею заняться.$b$bМы уже отправили к ней саботажников, но и твоя помощь пригодится, чтобы поскорее снести установку.$b$bОтправляйся туда и сверни несколько вентилей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 7 ржавых вентилей с нефтяной платформы на Пляже Трюмных Вод.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32156,'Последние почести','Это варварство, |3-6($c)! Мы потеряли слишком много людей, пытаясь остановить картель Трюмных Вод.$b$bПавшие солдаты сражались храбро и заслужили последние почести. Мы должны хотя бы сообщить их родным печальные известия.$b$bВозможно, тебе удастся найти их жетоны на поле боя?','Соберите 7 армейских жетонов павших солдат операции "Заслон" на пляже Трюмных Вод или в его окрестностях.','Мы не должны терять чувство достоинства даже на поле битвы.','Вернитесь к Мишке на борт "Небесного огня" над Южными островами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это варварство, |3-6($c)! Мы потеряли слишком много людей, пытаясь остановить картель Трюмных Вод.$b$bПавшие солдаты сражались храбро и заслужили последние почести. Мы должны хотя бы сообщить их родным печальные известия.$b$bВозможно, тебе удастся найти их жетоны на поле боя?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 армейских жетонов павших солдат операции "Заслон" на пляже Трюмных Вод или в его окрестностях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы не должны терять чувство достоинства даже на поле битвы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мишке на борт "Небесного огня" над Южными островами.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32157,'Хороший гоблин – мертвый гоблин','То, что эти варвары сделали с Красарангскими джунглями, непростительно. Остановить это можно только одним способом – уничтожить картель Трюмных Вод раз и навсегда.$b$bЭто пойдет на благо и Пандарии, и всему Альянсу. Ступай на пляж Трюмных Вод и убей их всех до единого. Не сомневаюсь, Орда ринется им на подмогу. Не отступай, пока песок не обагрится их кровью!','Вернитесь к небесному адмиралу Роджерс на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший гоблин – мертвый гоблин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что эти варвары сделали с Красарангскими джунглями, непростительно. Остановить это можно только одним способом – уничтожить картель Трюмных Вод раз и навсегда.$b$bЭто пойдет на благо и Пандарии, и всему Альянсу. Ступай на пляж Трюмных Вод и убей их всех до единого. Не сомневаюсь, Орда ринется им на подмогу. Не отступай, пока песок не обагрится их кровью!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному адмиралу Роджерс на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32158,'Два шага до победы','Вернитесь к Серафине Зимней на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Два шага до победы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серафине Зимней на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32159,'Круг жизни','Нужно попытаться как можно скорее остановить разрушительный хаос, в который погружается этот континент! За каждое уничтоженное врагами дерево мы станем сажать новое!$b$bВозьми эти непредсказуемые семена, $n.$b$bТолько не медли. Злоба и ненависть, исходящие от Крепости Покорителей, несомненно, уже проникли в почву, а реакция природы непредсказуема.$b$bНе могу гарантировать, что побеги, выросшие из этих семян, поведут себя дружелюбно.','Посадите 11 беспокойных семян рядом с Лесопилкой Скоротяпеля.','Вернитесь к Серафине Зимней на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно попытаться как можно скорее остановить разрушительный хаос, в который погружается этот континент! За каждое уничтоженное врагами дерево мы станем сажать новое!$b$bВозьми эти непредсказуемые семена, $n.$b$bТолько не медли. Злоба и ненависть, исходящие от Крепости Покорителей, несомненно, уже проникли в почву, а реакция природы непредсказуема.$b$bНе могу гарантировать, что побеги, выросшие из этих семян, поведут себя дружелюбно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 11 беспокойных семян рядом с Лесопилкой Скоротяпеля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серафине Зимней на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32161,'Охота повелителя зверей: журавль','Вместе с силком вы получаете полезный совет по ловле журавлей.$b$bСамые огромные журавли в Красарангских джунглях не купятся на простую приманку в виде еды. Вам придется сыграть на их чувствах, чтобы выманить из чащи.$b$bВ Колыбели Чи-Цзи и в Поющих Вершинах на востоке отсюда водится множество журавлей. Надергайте у них достаточно перьев и сложите их на видное место возле Храма Журавля. Добыча не замедлит появиться.','Соберите 5 безупречных золотистых журавлиных перьев и 1 безупречное черное журавлиное перо.','Принесите безупречные перья на берег к югу от Храма Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота повелителя зверей: журавль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместе с силком вы получаете полезный совет по ловле журавлей.$b$bСамые огромные журавли в Красарангских джунглях не купятся на простую приманку в виде еды. Вам придется сыграть на их чувствах, чтобы выманить из чащи.$b$bВ Колыбели Чи-Цзи и в Поющих Вершинах на востоке отсюда водится множество журавлей. Надергайте у них достаточно перьев и сложите их на видное место возле Храма Журавля. Добыча не замедлит появиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 безупречных золотистых журавлиных перьев и 1 безупречное черное журавлиное перо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите безупречные перья на берег к югу от Храма Красного Журавля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32162,'Охота повелителя зверей: тигр','Вместе с ловушкой вы получаете полезный совет по ловле тигров.$b$bТигры – настоящие гурманы, но в этих джунглях им редко попадается достойная добыча. Если вы хотите выманить из логова матерого зверя, вам придется найти для него соблазнительную приманку.$b$bПо другую сторону Змеиного Хребта пасется стадо яков. Убейте несколько быков, сложите их мясо на границе джунглей, установите ловушку и ждите свою добычу.','Соберите 25 неотбитых филе яка.','Вы кладете мясо на ловушку и смотрите в сторону джунглей…','Похоже, это идеальное место, чтобы установить ловушку для тигра.','Принесите мясо яка на пляж к северу от Крепости Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота повелителя зверей: тигр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместе с ловушкой вы получаете полезный совет по ловле тигров.$b$bТигры – настоящие гурманы, но в этих джунглях им редко попадается достойная добыча. Если вы хотите выманить из логова матерого зверя, вам придется найти для него соблазнительную приманку.$b$bПо другую сторону Змеиного Хребта пасется стадо яков. Убейте несколько быков, сложите их мясо на границе джунглей, установите ловушку и ждите свою добычу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 25 неотбитых филе яка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете мясо на ловушку и смотрите в сторону джунглей…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, это идеальное место, чтобы установить ловушку для тигра.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите мясо яка на пляж к северу от Крепости Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32163,'Охота повелителя зверей: краб','Вместе с ящиком вы получаете полезный совет по ловле крабов.$b$bКрабы – удивительные древние существа. Их жизнь подчинена инстинктам, отличным от наших.$b$bМаленьких крабов поймать легко, но большие особи прячутся глубоко в песках, подальше от опасностей. Чтобы выманить их, придется воздействовать на их тонкое обоняние.$b$bЖители поселения Унга на юго-востоке отсюда ловят рыбу и оставляют ее тухнуть на солнце, прежде чем употребить в пищу. Соберите в кучу достаточно вонючей рыбы, и вы наверняка поймаете гигантского краба.','Заберите 30 вонючих тухлых рыб у жителей поселения Унга-Ингу.','Вы разбрасываете тухлую рыбу, подготавливаете ящик и смотрите в сторону пляжа…','Похоже, это неплохое место для ловли крабов.','Принесите гнилую рыбу на пляж к югу от Руин Доцзян.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота повелителя зверей: краб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместе с ящиком вы получаете полезный совет по ловле крабов.$b$bКрабы – удивительные древние существа. Их жизнь подчинена инстинктам, отличным от наших.$b$bМаленьких крабов поймать легко, но большие особи прячутся глубоко в песках, подальше от опасностей. Чтобы выманить их, придется воздействовать на их тонкое обоняние.$b$bЖители поселения Унга на юго-востоке отсюда ловят рыбу и оставляют ее тухнуть на солнце, прежде чем употребить в пищу. Соберите в кучу достаточно вонючей рыбы, и вы наверняка поймаете гигантского краба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 30 вонючих тухлых рыб у жителей поселения Унга-Ингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы разбрасываете тухлую рыбу, подготавливаете ящик и смотрите в сторону пляжа…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, это неплохое место для ловли крабов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите гнилую рыбу на пляж к югу от Руин Доцзян.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32164,'Охота повелителя зверей: журавль','Вместе с силком вы получаете полезный совет по ловле журавлей.$b$bСамые огромные журавли в Красарангских джунглях не купятся на простую приманку в виде еды. Вам придется сыграть на их чувствах, чтобы выманить из чащи.$b$bВ Колыбели Чи-Цзи и в Поющих Вершинах на западе отсюда водится множество журавлей. Надергайте у них достаточно перьев и сложите их на видное место возле Храма Журавля. Добыча не замедлит появиться.','Соберите 5 безупречных золотистых журавлиных перьев и 1 безупречное черное журавлиное перо.','Вы кладете перья в грязь и смотрите в сторону Храма Журавля…','Это то самое место возле Храма Журавля.','Принесите безупречные перья на берег к югу от Храма Красного Журавля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота повелителя зверей: журавль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вместе с силком вы получаете полезный совет по ловле журавлей.$b$bСамые огромные журавли в Красарангских джунглях не купятся на простую приманку в виде еды. Вам придется сыграть на их чувствах, чтобы выманить из чащи.$b$bВ Колыбели Чи-Цзи и в Поющих Вершинах на западе отсюда водится множество журавлей. Надергайте у них достаточно перьев и сложите их на видное место возле Храма Журавля. Добыча не замедлит появиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 безупречных золотистых журавлиных перьев и 1 безупречное черное журавлиное перо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете перья в грязь и смотрите в сторону Храма Журавля…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это то самое место возле Храма Журавля.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите безупречные перья на берег к югу от Храма Красного Журавля.',`completedtext_loc8`);
