INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32181,'Добыча повелителя зверей: журавль','Древний журавль жив, но оглушен.$b$bОтнесите его к Джорну Небесному Провидцу, пока он не пришел в себя.','Отнесите древнего багряноголового журавля Джорну Небесному Провидцу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыча повелителя зверей: журавль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний журавль жив, но оглушен.$b$bОтнесите его к Джорну Небесному Провидцу, пока он не пришел в себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите древнего багряноголового журавля Джорну Небесному Провидцу.',`objectives_loc8`);
