INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (32183,'Добыча повелителя зверей: краб','Огромный краб жив, но оглушен.$b$bОтнесите его к Джорну Небесному Провидцу, пока он не пришел в себя.','Отнесите громадного шустрого краба Джорну Небесному Провидцу.','Поймать такого зверя можно и в одиночку, но по-настоящему победить его можно только с помощниками.$B$BПоговори со мной, когда ты соберешь достаточное количество союзников. И мы посмотрим, что окажется сильнее – мощь Орды или сила краба.','C возвращением, Твайдрагон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыча повелителя зверей: краб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огромный краб жив, но оглушен.$b$bОтнесите его к Джорну Небесному Провидцу, пока он не пришел в себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите громадного шустрого краба Джорну Небесному Провидцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поймать такого зверя можно и в одиночку, но по-настоящему победить его можно только с помощниками.$B$BПоговори со мной, когда ты соберешь достаточное количество союзников. И мы посмотрим, что окажется сильнее – мощь Орды или сила краба.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','C возвращением, Твайдрагон.',`requestitemstext_loc8`);
