INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32189,'Странный новичок','Сегодня утром заходил странный парень в остроконечной шляпе, пытался продать какие-то особые семена. Клялся и божился, что они волшебные.$B$BЯ не против здоровой конкуренции – бизнес есть бизнес! – но этот продавец выглядел каким-то... потрепанным. А, и еще от него ЗВЕРСКИ воняло.$B$BСделай доброе дело, присмотрись к нему поближе. Ты найдешь его возле Цзянь Железной Лапы – он там готовит что-то на пробу.','Поговорите с Барнаби Флетчером на рынке Полугорья.','Аммм… ням… мням… $B$B<Барнаби поднимает голову, и вы видите несколько дынных семечек, запутавшихся в его бороде. По его подбородку стекает струйка сока.>$B$BА… Покупатель! Подходи, подходи. Меня зовут Флетчер. Барнаби Флетчер, приятно познакомиться.$B$B<Он вытирает ладонь о костюм и протягивает вам липкую руку в пятнах сока.>','Поговорите с Барнаби Флетчером на Рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный новичок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня утром заходил странный парень в остроконечной шляпе, пытался продать какие-то особые семена. Клялся и божился, что они волшебные.$B$BЯ не против здоровой конкуренции – бизнес есть бизнес! – но этот продавец выглядел каким-то... потрепанным. А, и еще от него ЗВЕРСКИ воняло.$B$BСделай доброе дело, присмотрись к нему поближе. Ты найдешь его возле Цзянь Железной Лапы – он там готовит что-то на пробу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Барнаби Флетчером на рынке Полугорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аммм… ням… мням… $B$B<Барнаби поднимает голову, и вы видите несколько дынных семечек, запутавшихся в его бороде. По его подбородку стекает струйка сока.>$B$BА… Покупатель! Подходи, подходи. Меня зовут Флетчер. Барнаби Флетчер, приятно познакомиться.$B$B<Он вытирает ладонь о костюм и протягивает вам липкую руку в пятнах сока.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Барнаби Флетчером на Рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32190,'В Могуцзя','Поговорите с правящим лордом Лор\'темаром Тероном в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Могуцзя',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с правящим лордом Лор\'темаром Тероном в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32191,'Древние стражи','Перед тем, как могу разбили наш разведывательный отряд, мы обнаружили древние реликвии в руинах к северу отсюда.$B$BНеплохо было бы собрать несколько образцов для изучения, но терракотовые стражи могу на дают нам этого сделать.$B$BЕсли ты как-то разберешься с ними, то мы сможем продолжить работу.','Убейте 5 стражей клана Корун.','Прекрасно. Теперь мы сможем продолжить раскопки без назойливых стражей.','Вернитесь к Фанлиру Серебряному Шипу в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем, как могу разбили наш разведывательный отряд, мы обнаружили древние реликвии в руинах к северу отсюда.$B$BНеплохо было бы собрать несколько образцов для изучения, но терракотовые стражи могу на дают нам этого сделать.$B$BЕсли ты как-то разберешься с ними, то мы сможем продолжить работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 стражей клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Теперь мы сможем продолжить раскопки без назойливых стражей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фанлиру Серебряному Шипу в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32192,'Кровные братья','Мы разобрались с хранителями могу и их псами, но многим эльфам крови из разведывательного отряда посчастливилось намного меньше.$B$BМножество наших собратьев попали в ловушку в руинах к северу отсюда. Мы рассматриваем различные варианты их освобождения, но, по-моему, в этой ситуации не стоит церемониться.$B$BОтправляйся туда и убей стражников, которые охраняют пленников. Если интуиция меня не обманывает, так мы освободим наших товарищей.','Освободите 6 магов из Крепости Покорителей, убивая хранителей клана Корун.','Мы, эльфы крови, всегда верой и правдой служили Орде. Однако в последнее время я все чаще задумываюсь, к чему приведет наша служба под началом Гарроша.','Вернитесь к Лор\'темару Терону в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровные братья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы разобрались с хранителями могу и их псами, но многим эльфам крови из разведывательного отряда посчастливилось намного меньше.$B$BМножество наших собратьев попали в ловушку в руинах к северу отсюда. Мы рассматриваем различные варианты их освобождения, но, по-моему, в этой ситуации не стоит церемониться.$B$BОтправляйся туда и убей стражников, которые охраняют пленников. Если интуиция меня не обманывает, так мы освободим наших товарищей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 магов из Крепости Покорителей, убивая хранителей клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы, эльфы крови, всегда верой и правдой служили Орде. Однако в последнее время я все чаще задумываюсь, к чему приведет наша служба под началом Гарроша.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32193,'В Могуцзя','Несколько дней назад Лига исследователей отправила экспедицию на север.$B$BС тех пор от нее не было никаких вестей. Я не успокоюсь, пока не узнаю, что с ними все в порядке.$B$BПоследнее, что мы знаем, это то, что Бранн Бронзобород направлялся в Могуцзя на вершине Кунь-Лай.$B$BРазыщи его и сообщи о том, как он. А добраться до места тебе поможет Фенни.','Найдите Бранна Бронзоборода в Могуцзя. Поговорите с Фенни Хорнсвоггл в Львином лагере.','Этим артефактам, должно быть, несколько тысяч лет. Тебе доводилось видывать что-нибудь подобное?','Поговорите с Бранном Бронзобородом в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Могуцзя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько дней назад Лига исследователей отправила экспедицию на север.$B$BС тех пор от нее не было никаких вестей. Я не успокоюсь, пока не узнаю, что с ними все в порядке.$B$BПоследнее, что мы знаем, это то, что Бранн Бронзобород направлялся в Могуцзя на вершине Кунь-Лай.$B$BРазыщи его и сообщи о том, как он. А добраться до места тебе поможет Фенни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бранна Бронзоборода в Могуцзя. Поговорите с Фенни Хорнсвоггл в Львином лагере.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этим артефактам, должно быть, несколько тысяч лет. Тебе доводилось видывать что-нибудь подобное?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бранном Бронзобородом в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32194,'Дурная кровь','Лига исследователей проводит раскопки в этих руинах, а моя обязанность – обеспечивать защиту.$b$bКогда мы прибыли сюда, то увидели, что здесь полно эльфов крови. Похоже, могу интересуют Орду не меньше, чем нас.$b$bК сожалению, их силы в пять раз превосходят наши.$b$bВ руинах множество эльфов крови – убей их всех и забери найденные ими артефакты.','Отберите 5 артефактов клана Корун у руноискателей Луносвета, волшебников или рыцарей из Крепости Покорителей.','Что задумали эти эльфы крови?','Вернитесь к Саранье Небесной Глефе в Могуцзя, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дурная кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига исследователей проводит раскопки в этих руинах, а моя обязанность – обеспечивать защиту.$b$bКогда мы прибыли сюда, то увидели, что здесь полно эльфов крови. Похоже, могу интересуют Орду не меньше, чем нас.$b$bК сожалению, их силы в пять раз превосходят наши.$b$bВ руинах множество эльфов крови – убей их всех и забери найденные ими артефакты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите 5 артефактов клана Корун у руноискателей Луносвета, волшебников или рыцарей из Крепости Покорителей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что задумали эти эльфы крови?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саранье Небесной Глефе в Могуцзя, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32195,'Остаточная ярость','Мы обнаружили в руинах остаточную энергию ша, $n.$b$bО, знаю-знаю, какие мысли сейчас проносятся в твоей голове – ша, это же опасно, да? Без паники! Эта энергия настолько слаба, что бояться совершенно нечего. Все под контролем!$b$bА теперь мне нужно, чтобы ты $gотправился:отправилась; в руины и $gсобрал:собрала; немного сущности злоблингов. Вот тебе бутыль, наполни ее!','Убейте 27 злоблингов.','Вернитесь к Бранну Бронзобороду в Могуцзя, что на Вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остаточная ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили в руинах остаточную энергию ша, $n.$b$bО, знаю-знаю, какие мысли сейчас проносятся в твоей голове – ша, это же опасно, да? Без паники! Эта энергия настолько слаба, что бояться совершенно нечего. Все под контролем!$b$bА теперь мне нужно, чтобы ты $gотправился:отправилась; в руины и $gсобрал:собрала; немного сущности злоблингов. Вот тебе бутыль, наполни ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 27 злоблингов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бранну Бронзобороду в Могуцзя, что на Вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32196,'Как бы магия','Приветствую вас, <..вставьте свое имя..>!$b$bВам кажется, что постоянные войны угрожают вашей жизни? Ваша броня износилась в бесконечных сражениях во имя Орды?$b$bУ нас есть для вас то, что вы так долго искали – Осад-о-матик 4000.$b$bИспытайте на себе новейший прототип прямо сейчас! Ищите развед-о-метры <возле разрушителей на пляже>, <возле входа в лагерь Орды> и <возле склада с бомбами в лагере Орды>!','Найдите 3 Осад-о-матика в Крепости Покорителей.','Поговорите с проекцией главного механика Меггакрута на "Небесном огне" в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как бы магия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую вас, <..вставьте свое имя..>!$b$bВам кажется, что постоянные войны угрожают вашей жизни? Ваша броня износилась в бесконечных сражениях во имя Орды?$b$bУ нас есть для вас то, что вы так долго искали – Осад-о-матик 4000.$b$bИспытайте на себе новейший прототип прямо сейчас! Ищите развед-о-метры <возле разрушителей на пляже>, <возле входа в лагерь Орды> и <возле склада с бомбами в лагере Орды>!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 3 Осад-о-матика в Крепости Покорителей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией главного механика Меггакрута на "Небесном огне" в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32197,'Загадочный мясной рулет','Мы то и дело получаем жалобы, что Леди-босс забирает себе лучшую еду, а остальным достаются одни объедки с барского стола.$b$bМне кажется, среди рабочих зреет недовольство. В чем-то я их понимаю – даже мне не достается таких изысканных блюд!$b$bНадо, чтобы Сезик что-нибудь придумал, чтобы местная еда казалась хоть чуточку аппетитнее...$b$bПридумал! Мы приготовим загадочный мясной рулет!','Соберите 7 кусков загадочного мяса, убивая местную живность.','Я должен держать марку! Я повар, а не кудесник!$B$BВ этом мясе есть только одна загадка – каким образом Герцог собирается скормить его рабочим!','Ну, что там у тебя есть?','Вернитесь к Сезику Перешпарю, которого можно найти рядом с Кипящими Раками на Пляже Трюмных Вод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадочный мясной рулет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы то и дело получаем жалобы, что Леди-босс забирает себе лучшую еду, а остальным достаются одни объедки с барского стола.$b$bМне кажется, среди рабочих зреет недовольство. В чем-то я их понимаю – даже мне не достается таких изысканных блюд!$b$bНадо, чтобы Сезик что-нибудь придумал, чтобы местная еда казалась хоть чуточку аппетитнее...$b$bПридумал! Мы приготовим загадочный мясной рулет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 кусков загадочного мяса, убивая местную живность.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я должен держать марку! Я повар, а не кудесник!$B$BВ этом мясе есть только одна загадка – каким образом Герцог собирается скормить его рабочим!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там у тебя есть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сезику Перешпарю, которого можно найти рядом с Кипящими Раками на Пляже Трюмных Вод.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32198,'Волшебный летающий мусор','Прежде чем мы заключим деловое соглашение, я вынужден уведомить тебя, что нахожусь на лечении от зельезависимости. Таковы требования моего центра реабилитации.$B$BТеперь, когда эта маленькая формальность улажена, давай поговорим о порталах!$B$BВидишь ли, большие порталы в городах, работающие круглосуточно, поглощают тонну магической энергии. Она кристаллизуется вокруг рамок, и никто обычно не обращает на эти наросты внимания. Но когда я, хм... вынужден был провести некоторое время в стоках Даларана, я заметил, что эти кристаллы обладают некоей мощью!$B$BМне удалось тебя заинтересовать?','Поговорите с Барнаби Флетчером и узнайте больше о кристаллах порталов.','Я так и знал, что тебя это заинтересует!$B$BДело вот в чем: в данном состоянии осколки нестабильны. Но почва в этой долине весьма восприимчива к магическим свойствам. Я уверен, если закопать здесь один из осколков, может произойти весьма занимательная реакция.$B$BЭнергию можно стабилизировать и создать настоящий, действующий портал. Ну или... ты прорвешь ткань реальности и создашь расщелину, из которой вырвется невообразимый и кошмарный ужас!$B$BОпыт подсказывает, что эти события равновероятны... но проверить мою догадку можно только одним способом.$B$BВот, держи образец!','Поговорите с Барнаби Флетчером на рынке Полугорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебный летающий мусор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы заключим деловое соглашение, я вынужден уведомить тебя, что нахожусь на лечении от зельезависимости. Таковы требования моего центра реабилитации.$B$BТеперь, когда эта маленькая формальность улажена, давай поговорим о порталах!$B$BВидишь ли, большие порталы в городах, работающие круглосуточно, поглощают тонну магической энергии. Она кристаллизуется вокруг рамок, и никто обычно не обращает на эти наросты внимания. Но когда я, хм... вынужден был провести некоторое время в стоках Даларана, я заметил, что эти кристаллы обладают некоей мощью!$B$BМне удалось тебя заинтересовать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Барнаби Флетчером и узнайте больше о кристаллах порталов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так и знал, что тебя это заинтересует!$B$BДело вот в чем: в данном состоянии осколки нестабильны. Но почва в этой долине весьма восприимчива к магическим свойствам. Я уверен, если закопать здесь один из осколков, может произойти весьма занимательная реакция.$B$BЭнергию можно стабилизировать и создать настоящий, действующий портал. Ну или... ты прорвешь ткань реальности и создашь расщелину, из которой вырвется невообразимый и кошмарный ужас!$B$BОпыт подсказывает, что эти события равновероятны... но проверить мою догадку можно только одним способом.$B$BВот, держи образец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Барнаби Флетчером на рынке Полугорья.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32199,'Красарангское лакомство','Какое отвратительное мясо! Придется основательно его сдобрить специями, чтобы перебить запах.$B$BЛучшие деликатесы для леди-босса!$B$B<Сезик скалится и подмигивает вам.>','Ах, значит, Леди-босс заждалась угощения? Тогда, может, ей уже стоит вылезти из креслица и самой все приготовить?','Вернитесь к Сезику Перешпарю, которого можно найти рядом с Кипящими Раками на Пляже Трюмных Вод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красарангское лакомство',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое отвратительное мясо! Придется основательно его сдобрить специями, чтобы перебить запах.$B$BЛучшие деликатесы для леди-босса!$B$B<Сезик скалится и подмигивает вам.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, значит, Леди-босс заждалась угощения? Тогда, может, ей уже стоит вылезти из креслица и самой все приготовить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сезику Перешпарю, которого можно найти рядом с Кипящими Раками на Пляже Трюмных Вод.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32200,'Угроза За\'Туала','$n! То, о чем я попрошу тебя, ужасно, но у нас нет другого выхода.\r\n\r\nРазыщи троллей в городе или на пляже и убей их. Так будет лучше для всех.','Убейте 12 троллей в За\'Туале.','Вернитесь к Халдарону Светлому Крылу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза За\'Туала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! То, о чем я попрошу тебя, ужасно, но у нас нет другого выхода.\r\n\r\nРазыщи троллей в городе или на пляже и убей их. Так будет лучше для всех.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 троллей в За\'Туале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32201,'Мертвое дело','Двор Костей, что к югу отсюда, просто кишит могу. Они ни на минуту не прекращают проведение своих ритуалов с громом и молниями.$b$bЕсли мы хотим, чтобы наши планы завладеть этим островом успешно воплотились в жизнь, нам нельзя позволять могу удерживать эту стратегическую позицию.$b$bИх нужно ликвидировать.','Убейте 10 хранителей могил Шань\'цзэ, кромсателей душ Шань\'цзэ или призывателей грома Шань\'цзэ.','Вернитесь к Верховному магистру Роммату на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мертвое дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Двор Костей, что к югу отсюда, просто кишит могу. Они ни на минуту не прекращают проведение своих ритуалов с громом и молниями.$b$bЕсли мы хотим, чтобы наши планы завладеть этим островом успешно воплотились в жизнь, нам нельзя позволять могу удерживать эту стратегическую позицию.$b$bИх нужно ликвидировать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 хранителей могил Шань\'цзэ, кромсателей душ Шань\'цзэ или призывателей грома Шань\'цзэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному магистру Роммату на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32202,'Убить троллей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить троллей',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32203,'Убить духов могу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить духов могу',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32204,'Угроза Гнилого Клинка','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Орды, мы сможем подумать о чем-то более основательном.','Убейте 10 сауроков Гнилого Клинка.','Придет день, и этот остров будет принадлежать Орде. И я могу только надеяться на то, что к тому времени на нем не будет ни одного саурока.$B$B<Этас усмехается.>$B$BПо крайней мере они тоже атакуют Альянс.','Вернитесь к верховному магу Этасу Похитителю Солнца на Oстров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Гнилого Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Орды, мы сможем подумать о чем-то более основательном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 сауроков Гнилого Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Придет день, и этот остров будет принадлежать Орде. И я могу только надеяться на то, что к тому времени на нем не будет ни одного саурока.$B$B<Этас усмехается.>$B$BПо крайней мере они тоже атакуют Альянс.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Этасу Похитителю Солнца на Oстров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32205,'Сбор донесений разведчиков','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор донесений разведчиков',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32206,'Дополнительный удар по врагу','Здешние зандалары очень могущественны, |3-6($c). Недооценивать их нельзя. Мы не можем считать, что они слабые противники, лишь потому, что у них нет мечей.$b$bС каждым днем их все больше, и в их руках – древние магические знания.$b$bПомоги нам очистить эту территорию, |3-6($c). И, возможно, в процессе мы даже сможем чему-то у них научиться.','Убейте 8 зандаларских троллей на Террасе Завоевателя.','Вернитесь к капитану разведчиков Эльсии на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дополнительный удар по врагу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здешние зандалары очень могущественны, |3-6($c). Недооценивать их нельзя. Мы не можем считать, что они слабые противники, лишь потому, что у них нет мечей.$b$bС каждым днем их все больше, и в их руках – древние магические знания.$b$bПомоги нам очистить эту территорию, |3-6($c). И, возможно, в процессе мы даже сможем чему-то у них научиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 зандаларских троллей на Террасе Завоевателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32207,'Расправа','В загонах для зверей ты встретишь самых опытных укротителей зверей в зандаларской армии. Они натренированы убивать – топорами, когтями или при помощи зверей. В этих загонах зандалары и готовят своих воинов-наездников.$b$bНам нужно, чтобы ты $gубил:убила; всех зандаларов, каких только встретишь, пока они не выехали на поле боя верхом на своих чудовищных подопечных.','Убейте 10 зандаларских троллей в загонах для зверей.','Опытный зандаларский заклинатель зверей верхом на своем животном способен расправиться с целым полчищем противников на поле боя. Твой предупредительный удар уберег множество жизней. Спасибо тебе!','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расправа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В загонах для зверей ты встретишь самых опытных укротителей зверей в зандаларской армии. Они натренированы убивать – топорами, когтями или при помощи зверей. В этих загонах зандалары и готовят своих воинов-наездников.$b$bНам нужно, чтобы ты $gубил:убила; всех зандаларов, каких только встретишь, пока они не выехали на поле боя верхом на своих чудовищных подопечных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зандаларских троллей в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опытный зандаларский заклинатель зверей верхом на своем животном способен расправиться с целым полчищем противников на поле боя. Твой предупредительный удар уберег множество жизней. Спасибо тебе!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32208,'Максимальная нагрузка','Шахта к северу отсюда используется для добычи призрачной железной руды и для обогащения ее энергией молний.\r\n\r\nНам нужно уничтожить буры, которыми могу пользуются для добычи руды. Эти буры невосприимчивы к обычным атакам, но их можно разрушить при помощи мощного электрического импульса. \r\n\r\nДа, и когда будешь там, заодно убей того, кто руководит операцией.','Воспользуйтесь полностью заряженным чародейским конденсатором, чтобы уничтожить 3 молниевых бура в Шахте молний, и убейте повелителя металла Моно-Ханя.','Пришло время двигаться вперед – к кузне!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Максимальная нагрузка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шахта к северу отсюда используется для добычи призрачной железной руды и для обогащения ее энергией молний.\r\n\r\nНам нужно уничтожить буры, которыми могу пользуются для добычи руды. Эти буры невосприимчивы к обычным атакам, но их можно разрушить при помощи мощного электрического импульса. \r\n\r\nДа, и когда будешь там, заодно убей того, кто руководит операцией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь полностью заряженным чародейским конденсатором, чтобы уничтожить 3 молниевых бура в Шахте молний, и убейте повелителя металла Моно-Ханя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пришло время двигаться вперед – к кузне!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32209,'Спаси наших разведчиков!','Судя по тому, как в шахте много могу, это место имеет для них огромное значение. Но нам нужно побольше узнать о том, чем они там занимаются. Поэтому мы отправили в шахту своих разведчиков.\r\n\r\nК сожалению, многие из них попали в плен, а некоторые, как мы узнали, подвергаются пыткам. Ты $gдолжен:должна; спасти их. Никто не заслуживает таких страданий...\r\n\r\nДа, и когда закончишь, убей того, кто взял из в плен. Никакой пощады, $p!','Спасите 3 захваченных посланников Похитителей Солнца в Шахте молний и убейте повелителя металла Моно-Ханя.','Пришло время двигаться вперед – к кузне!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спаси наших разведчиков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по тому, как в шахте много могу, это место имеет для них огромное значение. Но нам нужно побольше узнать о том, чем они там занимаются. Поэтому мы отправили в шахту своих разведчиков.\r\n\r\nК сожалению, многие из них попали в плен, а некоторые, как мы узнали, подвергаются пыткам. Ты $gдолжен:должна; спасти их. Никто не заслуживает таких страданий...\r\n\r\nДа, и когда закончишь, убей того, кто взял из в плен. Никакой пощады, $p!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 3 захваченных посланников Похитителей Солнца в Шахте молний и убейте повелителя металла Моно-Ханя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пришло время двигаться вперед – к кузне!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32210,'Kill mogu boss for key, use object behind jumping puzzle') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kill mogu boss for key, use object behind jumping puzzle',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32211,'Повелитель Гроз Налак','[PH] Kill Nalak [Description]','[PH] Kill Nalak [Log Description]','[PH] Убить Налака [Completion Text]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Гроз Налак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Kill Nalak [Description]',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Kill Nalak [Log Description]',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[PH] Убить Налака [Completion Text]',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32212,'Атака на Зеб\'тул','Благодаря усилиям разведки на побережье у нас появилась ценная информация об острове, |3-6($c).$B$BОднако мы ничего не достигнем, если не начнем продвигаться вглубь суши.$B$BЯ собрал команду лучших бойцов из наших воздушных отрядов.$B$BЯ бы хотел, чтобы ты $gприсоединился:присоединилась; к нападению. Такой герой, как ты, может переломить ход боя в нашу пользу в решающий момент.$B$BКогда будешь $gготов:готова; к атаке, поговори со мной.','Завершите сценарий "Атака на Зеб\'тул". Для начала атаки поговорите с Лор\'темаром Тероном.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета на Острове Грома. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на Зеб\'тул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря усилиям разведки на побережье у нас появилась ценная информация об острове, |3-6($c).$B$BОднако мы ничего не достигнем, если не начнем продвигаться вглубь суши.$B$BЯ собрал команду лучших бойцов из наших воздушных отрядов.$B$BЯ бы хотел, чтобы ты $gприсоединился:присоединилась; к нападению. Такой герой, как ты, может переломить ход боя в нашу пользу в решающий момент.$B$BКогда будешь $gготов:готова; к атаке, поговори со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите сценарий "Атака на Зеб\'тул". Для начала атаки поговорите с Лор\'темаром Тероном.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета на Острове Грома. ',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32213,'Старые враги','Значит, Джайна думает, что ей и ее Кирин-Тору снова удастся нас отбросить? Я не буду так просто стоять и смотреть, как повторяются даларанские события!$b$bНа этот раз мы будем бить в ответ! Теперь мы пойдем в атаку…$b$bОтправляйся на Аметистовый утес и убей каждого встречного агента Кирин-Тора.','Значит, Аметистовый утес покрылся кровью наших врагов? Отлично, |3-6(Вислобон).$B$BНо, боюсь, этот бой не закончен. Нам придется снова и снова показывать им силу.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, Джайна думает, что ей и ее Кирин-Тору снова удастся нас отбросить? Я не буду так просто стоять и смотреть, как повторяются даларанские события!$b$bНа этот раз мы будем бить в ответ! Теперь мы пойдем в атаку…$b$bОтправляйся на Аметистовый утес и убей каждого встречного агента Кирин-Тора.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Аметистовый утес покрылся кровью наших врагов? Отлично, |3-6(Вислобон).$B$BНо, боюсь, этот бой не закончен. Нам придется снова и снова показывать им силу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32214,'Шпионы на территории Трюмных Вод','Ничто так не нервирует, как ощущение, что кто-то следует за тобой по пятам, когда ты идешь куда-то по своим делам! И я сталкиваюсь с этим постоянно. За нами следят!$B$BСоздается ощущение, что пляж просто кишит шпионами!$b$bЯ немного доработал наши инфракрасные очки, чтобы раз и навсегда покончить с этими диверсантами. Да, с самыми настоящими диверсантами! Вот, примерь. С помощью моих очков ты сможешь ликвидировать всех шпионов!','Отлично, Строцци! Так я и знал! Крысы из Альянса пробрались и сюда!$B$BНикому еще не удавалось просто так водить за нос картель Трюмных Вод!','Вернитесь к Риветту Сталехвату в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпионы на территории Трюмных Вод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто так не нервирует, как ощущение, что кто-то следует за тобой по пятам, когда ты идешь куда-то по своим делам! И я сталкиваюсь с этим постоянно. За нами следят!$B$BСоздается ощущение, что пляж просто кишит шпионами!$b$bЯ немного доработал наши инфракрасные очки, чтобы раз и навсегда покончить с этими диверсантами. Да, с самыми настоящими диверсантами! Вот, примерь. С помощью моих очков ты сможешь ликвидировать всех шпионов!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Строцци! Так я и знал! Крысы из Альянса пробрались и сюда!$B$BНикому еще не удавалось просто так водить за нос картель Трюмных Вод!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риветту Сталехвату в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32215,'Отвратительные жертвоприношения','Зандалары используют наших сородичей в отвратительных ритуалах! Их нужно остановить!\r\n\r\nПроберись в центр За\'Туала и разрушь их алтари.','Уничтожьте жертвенные алтари зандаларов.','Вернитесь к Элине Заралае на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвратительные жертвоприношения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары используют наших сородичей в отвратительных ритуалах! Их нужно остановить!\r\n\r\nПроберись в центр За\'Туала и разрушь их алтари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте жертвенные алтари зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элине Заралае на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32216,'Измученный птеродактиль','Зандалары видят в небесных крикунах лишь способных убивать хищников. Они подчиняют их своей воле при помощи мучений и жестокости.\r\n\r\nЯ слышу, как в лагере кричит от боли какой-то небесный крикун. Похоже, он пытается вырваться из рук своих мучителей.\r\n\r\nНайди небесного крикуна в За\'Туале и помоги ему освободиться от тех, кто держит его в неволе.','Освободите измученного небесного крикуна.','Вернитесь к Кетиэлю Солнечному Копью на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измученный птеродактиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары видят в небесных крикунах лишь способных убивать хищников. Они подчиняют их своей воле при помощи мучений и жестокости.\r\n\r\nЯ слышу, как в лагере кричит от боли какой-то небесный крикун. Похоже, он пытается вырваться из рук своих мучителей.\r\n\r\nНайди небесного крикуна в За\'Туале и помоги ему освободиться от тех, кто держит его в неволе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите измученного небесного крикуна.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кетиэлю Солнечному Копью на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32217,'Темные подношения','Душеловы зандаларов проводят жертвенные ритуалы, чтобы умилостивить лоа и своих мерзких богов. В этих темных ритуалах они приносят в жертву наших сородичей.\r\n\r\nУничтожь подношения, которые увидишь среди их палаток в За\'Туале, и, возможно, у нас получится остановить ритуалы.','Уничтожьте 6 зандаларских подношений.','Вернитесь к Элине Заралае на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные подношения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Душеловы зандаларов проводят жертвенные ритуалы, чтобы умилостивить лоа и своих мерзких богов. В этих темных ритуалах они приносят в жертву наших сородичей.\r\n\r\nУничтожь подношения, которые увидишь среди их палаток в За\'Туале, и, возможно, у нас получится остановить ритуалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 зандаларских подношений.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элине Заралае на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32218,'Прах врагов','Могу во Дворе Костей увеличивают свою армию, воскрешая своих погибших воинов.$b$bМы не можем позволить этому продолжаться.$b$bВозьми этот факел и сожги все мумифицированные останки, какие найдешь.$b$bМы уничтожим наших врагов до того, как они будут иметь возможность подняться.','Сожгите 8 мумифицированных останков.','Вернитесь к капитану Аэртасу Огненному Ястребу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу во Дворе Костей увеличивают свою армию, воскрешая своих погибших воинов.$b$bМы не можем позволить этому продолжаться.$b$bВозьми этот факел и сожги все мумифицированные останки, какие найдешь.$b$bМы уничтожим наших врагов до того, как они будут иметь возможность подняться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 8 мумифицированных останков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Аэртасу Огненному Ястребу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32219,'Каменный холод','Наше наступление на Двор Костей продолжается. Мы продвигаемся вперед не слишком быстро, но все же прогресс очевиден.$b$bК несчастью, мы получили несколько сообщений о том, что каменные статуи цийлиней неожиданно начали оживать.$b$bЯ не могу допустить, чтобы эти цийлини угрожали моей исследовательской экспедиции.$b$bОтправляйся во Двор Костей и уничтожь все статуи цийлиней, какие найдешь.','Уничтожьте 8 могильных стражей.','Рада слышать, что ты разнес этих цийлиней на тысячу мелких кусочков. Это большой вклад в наши военные дела.','Вернитесь к Ришель Светлый Локон на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше наступление на Двор Костей продолжается. Мы продвигаемся вперед не слишком быстро, но все же прогресс очевиден.$b$bК несчастью, мы получили несколько сообщений о том, что каменные статуи цийлиней неожиданно начали оживать.$b$bЯ не могу допустить, чтобы эти цийлини угрожали моей исследовательской экспедиции.$b$bОтправляйся во Двор Костей и уничтожь все статуи цийлиней, какие найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 могильных стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рада слышать, что ты разнес этих цийлиней на тысячу мелких кусочков. Это большой вклад в наши военные дела.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ришель Светлый Локон на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32220,'Освобождение душ','Мы все время осаждаем могу во Дворе Костей, но боюсь, мы лишь поставляем им жертв для их ужасных ритуалов.$b$bМогу не просто убивают своих пленников. Они похищают их души и используют для оживления камня или превращают погибших в призрачные орудия войны.$b$bЯ не могу допустить, чтобы могу пополняли свои армии за счет разведчиков, и неважно, за кого они сражаются – за Орду или Альянс.$b$bОтправляйся к криптам и спустись в них. Освободи тех, кто еще остался в живых.','Спасите 6 разведчиков Похитителей Солнца или Серебряного Союза.','Спасибо, Звергон. Ты снял тяжелый груз с моего сердца.$B$BЯ никогда не забуду то, что ты сделал сегодня.','Вернитесь к верховному магистру Роммату на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы все время осаждаем могу во Дворе Костей, но боюсь, мы лишь поставляем им жертв для их ужасных ритуалов.$b$bМогу не просто убивают своих пленников. Они похищают их души и используют для оживления камня или превращают погибших в призрачные орудия войны.$b$bЯ не могу допустить, чтобы могу пополняли свои армии за счет разведчиков, и неважно, за кого они сражаются – за Орду или Альянс.$b$bОтправляйся к криптам и спустись в них. Освободи тех, кто еще остался в живых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 6 разведчиков Похитителей Солнца или Серебряного Союза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, Звергон. Ты снял тяжелый груз с моего сердца.$B$BЯ никогда не забуду то, что ты сделал сегодня.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32221,'Нападение на пляж','Постоянные нападения из Львиного лагеря мешают нашим поставкам древесины.$b$bПока нам удавалось сдерживать их натиск, но, похоже, настало время показать им, кто здесь главный!$b$bСтупай на побережье и обагри его кровью!','Убейте 10 любых воинов операции "Заслон", включая саботажников ШРУ, на пляже Трюмных Вод или в его окрестностях.','Вернитесь к Риветту Сталехвату в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на пляж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постоянные нападения из Львиного лагеря мешают нашим поставкам древесины.$b$bПока нам удавалось сдерживать их натиск, но, похоже, настало время показать им, кто здесь главный!$b$bСтупай на побережье и обагри его кровью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 любых воинов операции "Заслон", включая саботажников ШРУ, на пляже Трюмных Вод или в его окрестностях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риветту Сталехвату в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32222,'Разыскивается: главный инженер Винтоверт','Вернитесь к кровавому стражу Гро\'ташу в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: главный инженер Винтоверт',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Гро\'ташу в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`completedtext_loc8`) VALUES (32223,'Расправьтесь с лейтенантом Этаном Джейкобсоном на Южных островах, расположенных к югу от Лесопилки Скоротяпеля.','Вернитесь к кровавому стражу Гро\'ташу в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расправьтесь с лейтенантом Этаном Джейкобсоном на Южных островах, расположенных к югу от Лесопилки Скоротяпеля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровавому стражу Гро\'ташу в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32224,'Покончить с восставшими','Ты $gвидел:видела; призраков на кладбище?$b$bЭто восставшие предки, духи погибших могу, которых призвали в этот мир.$B$BЕсли их разозлить, они атакуют быстро и бесшумно, и число их растет с каждым днем.$B$BОни не принадлежат этому миру. Уничтожь их и заставь вернуться обратно в могилы.','Убейте 15 восставших предков.','Вернитесь к Ришель Светлый Локон на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с восставшими',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; призраков на кладбище?$b$bЭто восставшие предки, духи погибших могу, которых призвали в этот мир.$B$BЕсли их разозлить, они атакуют быстро и бесшумно, и число их растет с каждым днем.$B$BОни не принадлежат этому миру. Уничтожь их и заставь вернуться обратно в могилы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 восставших предков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ришель Светлый Локон на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32225,'Ритуал вызова грома','Прервите ритуал призывателей грома Шань\'цзэ.','Вернитесь к верховному магистру Роммату на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал вызова грома',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите ритуал призывателей грома Шань\'цзэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32226,'В склепы','У Реликвария сегодня поистине знаменательный день!$b$bС каждым днем исследователи приносят для изучения и каталогизации все больше реликвий.$b$bНедавно один из них нашел во Дворе Костей этот свиток.$b$bЯ думаю, эта магическая формула может использоваться для общения с загробным миром. И если я правильно понимаю язык могу, то ты можешь попытаться воспользоваться этой магической формулой в последней комнате Залов Превознесения.$b$bПроверишь мою теорию?','Воспользуйтесь чарами Гуры в Залах Превознесения, а затем победите Гуру Освобожденного.','Вернитесь к Ришель Светлый Локон на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В склепы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Реликвария сегодня поистине знаменательный день!$b$bС каждым днем исследователи приносят для изучения и каталогизации все больше реликвий.$b$bНедавно один из них нашел во Дворе Костей этот свиток.$b$bЯ думаю, эта магическая формула может использоваться для общения с загробным миром. И если я правильно понимаю язык могу, то ты можешь попытаться воспользоваться этой магической формулой в последней комнате Залов Превознесения.$b$bПроверишь мою теорию?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь чарами Гуры в Залах Превознесения, а затем победите Гуру Освобожденного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ришель Светлый Локон на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32227,'Предотвращение будущей угрозы','Существа, которых зандалары используют для верховой езды, не рождаются такими огромными или злобными и преданными своим владельцам.\r\n\r\nЕсли ты прогонишь птенцов небесных крикунов с пляжа, то возможно у них появится шанс прожить нормальную жизнь.','Вернитесь к Кетиэлю Солнечному Копью на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предотвращение будущей угрозы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существа, которых зандалары используют для верховой езды, не рождаются такими огромными или злобными и преданными своим владельцам.\r\n\r\nЕсли ты прогонишь птенцов небесных крикунов с пляжа, то возможно у них появится шанс прожить нормальную жизнь.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кетиэлю Солнечному Копью на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32228,'Содрогающаяся трясина','В болоте обитает огромное чудовище. Пока оно еще не осмелилось напасть на нас, но я думаю, это временно.$B$BРасправься с ним, пока оно не проголодалось и не напало на наш лагерь.','Убейте могучего дьявозавра.','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Содрогающаяся трясина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В болоте обитает огромное чудовище. Пока оно еще не осмелилось напасть на нас, но я думаю, это временно.$B$BРасправься с ним, пока оно не проголодалось и не напало на наш лагерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте могучего дьявозавра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32229,'Уничтожение военного отряда троллей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение военного отряда троллей',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32230,'Зандаларский колосс','Тролли выпустили одну из своих громадин на южной дороге и блокировали наш проход по острову. Проследи, чтобы дорога была очищена, |3-6($c).','Уничтожьте зандаларского колосса.','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский колосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли выпустили одну из своих громадин на южной дороге и блокировали наш проход по острову. Проследи, чтобы дорога была очищена, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте зандаларского колосса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32231,'Освещенный путь во тьме','В Мрачных топях действует некая темная магия, которая тушит даже наши магические огни. Из-за этого наши разведчики плутают в пути.$B$BКогда попадешь на болото, зажги там все потухнувшие факелы, что обнаружишь. Это позволит нашим разведчикам найти дорогу. Да и тебе $gсамому:самой; будет проще выбраться оттуда.','Зажгите 8 погасших факелов в Мрачных топях.','Вернитесь к магистру Хаторелю на мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освещенный путь во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Мрачных топях действует некая темная магия, которая тушит даже наши магические огни. Из-за этого наши разведчики плутают в пути.$B$BКогда попадешь на болото, зажги там все потухнувшие факелы, что обнаружишь. Это позволит нашим разведчикам найти дорогу. Да и тебе $gсамому:самой; будет проще выбраться оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите 8 погасших факелов в Мрачных топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32232,'Важно то, что внутри','Во время последней разведывательной операции мне на пути попалось кое-что странное. Группа зандаларов совершает ритуал над чем-то вроде огромного стража. Возможно, они пытаются оживить его.$b$bНам нужно остановить ритуал и уничтожить стража. Эта громадина наверняка опасна.$b$bПришлось послать разведчицу, чтобы она проследила за их действиями. Встреться с ней и узнай, как их остановить.','Уничтожьте стража Та\'ку на Террасе Завоевателя.','Вернитесь к капитану разведчиков Эльсии на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важно то, что внутри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время последней разведывательной операции мне на пути попалось кое-что странное. Группа зандаларов совершает ритуал над чем-то вроде огромного стража. Возможно, они пытаются оживить его.$b$bНам нужно остановить ритуал и уничтожить стража. Эта громадина наверняка опасна.$b$bПришлось послать разведчицу, чтобы она проследила за их действиями. Встреться с ней и узнай, как их остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте стража Та\'ку на Террасе Завоевателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32233,'Операция по разоружению','Посмотри вокруг, |3-6($c). Что ты видишь? Лично я вижу массу новых возможностей.$b$bЗдешние заклинатели работают над тем, чтобы усилить оружие зандаларов при помощи мощной магии. Как будто бы просто острых клинков недостаточно для того, чтобы приструнить даже самых сильных противников.$b$bВо время своей разведывательной операции я заметила, что оружие не очень хорошо охраняется. Вот тут-то ты нам и пригодишься...$b$bЕсли украсть это оружие, то мы сможем им воспользоваться. Ну или по крайней мере им не смогут воспользоваться наши враги.','Вернитесь к капитану разведчиков Эльсии на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция по разоружению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри вокруг, |3-6($c). Что ты видишь? Лично я вижу массу новых возможностей.$b$bЗдешние заклинатели работают над тем, чтобы усилить оружие зандаларов при помощи мощной магии. Как будто бы просто острых клинков недостаточно для того, чтобы приструнить даже самых сильных противников.$b$bВо время своей разведывательной операции я заметила, что оружие не очень хорошо охраняется. Вот тут-то ты нам и пригодишься...$b$bЕсли украсть это оружие, то мы сможем им воспользоваться. Ну или по крайней мере им не смогут воспользоваться наши враги.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32234,'Знание – сила','Зандалары практикуют какую-то особенную магию. Прежде чем бороться с ней, мы должны понять ее, |3-6($c).$b$bИх умение управлять тайной магией и темными силами поистине впечатляет. Мне было бы интересно узнать, как им удалось достичь того, что не удается многим другим.$b$bВозможно, ответы на мои вопросы содержатся в их ритуальных артефактах. Принеси мне образцы их артефактов, и я хорошо тебя награжу.','Добудьте 6 ритуальных артефактов на Террасе Завоевателя.','Тебе удалось найти артефакты?','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание – сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары практикуют какую-то особенную магию. Прежде чем бороться с ней, мы должны понять ее, |3-6($c).$b$bИх умение управлять тайной магией и темными силами поистине впечатляет. Мне было бы интересно узнать, как им удалось достичь того, что не удается многим другим.$b$bВозможно, ответы на мои вопросы содержатся в их ритуальных артефактах. Принеси мне образцы их артефактов, и я хорошо тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 ритуальных артефактов на Террасе Завоевателя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти артефакты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32235,'Воздушные цели','Гномы переместили сюда свои летательные аппараты! Я хочу, чтобы в небе над нами ничего не мельтешило!$b$bВзбирайся на то, что там у тебя есть для передвижения и уничтожь их жалкие леталки!$b$bВоспользуйся грогом, которым со мной любезно "поделились" наши союзники-гоблины. Лучше уж его пустить на уничтожение гирокоптеров, чем оставить его у этих зеленых бесов.','Уничтожьте 6 гирокоптеров X2 "Небесного огня" с помощью бутылок с зажигательной смесью.','Ха! Никакие металлические штучки не выдержат меткого попадания бутылкой грога.','Поговорите с кровавым стражем Гро\'ташем в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушные цели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномы переместили сюда свои летательные аппараты! Я хочу, чтобы в небе над нами ничего не мельтешило!$b$bВзбирайся на то, что там у тебя есть для передвижения и уничтожь их жалкие леталки!$b$bВоспользуйся грогом, которым со мной любезно "поделились" наши союзники-гоблины. Лучше уж его пустить на уничтожение гирокоптеров, чем оставить его у этих зеленых бесов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 гирокоптеров X2 "Небесного огня" с помощью бутылок с зажигательной смесью.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Никакие металлические штучки не выдержат меткого попадания бутылкой грога.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с кровавым стражем Гро\'ташем в Крепости Покорителей, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32236,'Жукам – нет!','Пещера кишит сланцевыми пауками! Как же девушка может справиться с работой, если они захватывают рудокопов и руду?$b$bВот тут-то и пригодится мое последнее изобретение – Жуконет! Надо только разбрызгать химикат по всей пещере, и дело в шляпе! Сланцевые пауки ненавидят это вещество, да и рудокопы от него не испытывают слишком много долговременных побочных эффектов.$b$bТак что не о чем беспокоиться!$b$bВозьми-ка этот опрыскиватель и за работу!','Опрыскайте 5 сланцевых пауков Жуконетом и уничтожьте 12 сланцевиков.','Вот это мне по душе! Думаю, теперь пауки десять раз подумают, прежде чем сунуться в шахты Трюмных Вод.','Вернитесь к Бикси Циркулярке в карьер Рудогрызя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жукам – нет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пещера кишит сланцевыми пауками! Как же девушка может справиться с работой, если они захватывают рудокопов и руду?$b$bВот тут-то и пригодится мое последнее изобретение – Жуконет! Надо только разбрызгать химикат по всей пещере, и дело в шляпе! Сланцевые пауки ненавидят это вещество, да и рудокопы от него не испытывают слишком много долговременных побочных эффектов.$b$bТак что не о чем беспокоиться!$b$bВозьми-ка этот опрыскиватель и за работу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опрыскайте 5 сланцевых пауков Жуконетом и уничтожьте 12 сланцевиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это мне по душе! Думаю, теперь пауки десять раз подумают, прежде чем сунуться в шахты Трюмных Вод.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бикси Циркулярке в карьер Рудогрызя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32237,'Ценный ресурс','У нас под ногами целые залежи ценного ресурса, $n!$b$bНаша буровая установка просто не справляется с таким объемом нефти! Она буквально трещит по швам! Точнее по вентилям.$b$bЯ работаю в две смены, чтобы починить вентили, но всякий раз они вновь выходят из строя.$b$bСкладывается впечатление, будто кто-то за мной идет по пятам и все ломает. Такая вот ерунда...$b$bМожет, у тебя получится все наладить? Перекрой столько вентилей, сколько сможешь!','Перекройте 8 неисправных вентилей в нефтяном фонтане Скрипетельки.','Значит, за мной следили! Подлые крысы!$B$BВидимо, придется устанавливать для этих трусов особые ловушки… взрывные ловушки!','Вернитесь к Бакси Циркулярке на Пляж Трюмных Вод.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный ресурс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас под ногами целые залежи ценного ресурса, $n!$b$bНаша буровая установка просто не справляется с таким объемом нефти! Она буквально трещит по швам! Точнее по вентилям.$b$bЯ работаю в две смены, чтобы починить вентили, но всякий раз они вновь выходят из строя.$b$bСкладывается впечатление, будто кто-то за мной идет по пятам и все ломает. Такая вот ерунда...$b$bМожет, у тебя получится все наладить? Перекрой столько вентилей, сколько сможешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перекройте 8 неисправных вентилей в нефтяном фонтане Скрипетельки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, за мной следили! Подлые крысы!$B$BВидимо, придется устанавливать для этих трусов особые ловушки… взрывные ловушки!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бакси Циркулярке на Пляж Трюмных Вод.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32238,'Универсальный взрывопульт','Дроботы доставляют нам много проблем, но кажется, я нашла выход!$b$bЯ изготовила для себя универсальный пульт дистанционного управления, но он действует только на определенной частоте!$b$bПохоже, именно эта частота ослабляет броню дроботов!$b$bИспользуй мой пульт, чтобы немного размягчить дроботов, а потом надавай им тумаков!','Уничтожьте 9 дроботов операции "Заслон" возле Лесопилки Скоротяпеля.','Молодец, Теребианус! Мне отсюда были видны взрывы!$B$BОказывается, быть гением – это так просто! Теперь в моей гениальности мог убедиться каждый.','Вернитесь к Бикси Циркулярке на Лесопилку Скоротяпеля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Универсальный взрывопульт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дроботы доставляют нам много проблем, но кажется, я нашла выход!$b$bЯ изготовила для себя универсальный пульт дистанционного управления, но он действует только на определенной частоте!$b$bПохоже, именно эта частота ослабляет броню дроботов!$b$bИспользуй мой пульт, чтобы немного размягчить дроботов, а потом надавай им тумаков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 9 дроботов операции "Заслон" возле Лесопилки Скоротяпеля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, Теребианус! Мне отсюда были видны взрывы!$B$BОказывается, быть гением – это так просто! Теперь в моей гениальности мог убедиться каждый.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бикси Циркулярке на Лесопилку Скоротяпеля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (32242,'Позабытые секреты','Говорят, некогда могу владели множеством складов, где был запрятан целый арсенал разрушительного оружия.$B$BКогда армия могу готовилась к войне, она вселяла ужас в сердца своих врагов.$B$BЯ хочу понять, как они это делали. Именно за этим секретом я прибыл в Пандарию!$B$BЯ послал экспедицию для изучения руин к западу отсюда, но раскопки продвигаются так медленно, словно их ведут безмозглые батраки!$B$BУзнай-ка, в чем там дело, у Фанлира Серебряного Шипа, руководителя раскопок.','Тебя прислал вождь? Что ему нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позабытые секреты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, некогда могу владели множеством складов, где был запрятан целый арсенал разрушительного оружия.$B$BКогда армия могу готовилась к войне, она вселяла ужас в сердца своих врагов.$B$BЯ хочу понять, как они это делали. Именно за этим секретом я прибыл в Пандарию!$B$BЯ послал экспедицию для изучения руин к западу отсюда, но раскопки продвигаются так медленно, словно их ведут безмозглые батраки!$B$BУзнай-ка, в чем там дело, у Фанлира Серебряного Шипа, руководителя раскопок.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал вождь? Что ему нужно?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32243,'Источник силы клана Корун','Здорово! Ты когда-нибудь $gвидывал:видывала; что-нибудь похожее на эти статуи?$B$BЯ перед этим пробежалась по руинам и нашла кое-что интересное в самой высокой точке.$B$BМне не удалось подобраться поближе, но оно было похоже на статую, только живую!$B$BЯ не смогла пройти мимо злобных эльфов крови, а вот ты сможешь.$B$BТы ведь не откажешься подняться наверх и принести мне оттуда все, что может представлять интерес?','Убейте чаровяза из клана Корун и заберите у него пораженный ша коготь.','Ух ты, что это такое?','Вернитесь к Хильде Хорнсвоггл в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник силы клана Корун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здорово! Ты когда-нибудь $gвидывал:видывала; что-нибудь похожее на эти статуи?$B$BЯ перед этим пробежалась по руинам и нашла кое-что интересное в самой высокой точке.$B$BМне не удалось подобраться поближе, но оно было похоже на статую, только живую!$B$BЯ не смогла пройти мимо злобных эльфов крови, а вот ты сможешь.$B$BТы ведь не откажешься подняться наверх и принести мне оттуда все, что может представлять интерес?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чаровяза из клана Корун и заберите у него пораженный ша коготь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, что это такое?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32244,'Корун','Терракотовые стражи выглядят устрашающе, но они не идут ни в какое сравнение с существом, которое мы обнаружили в верхней части руин.$B$BВыжившие разведчики рассказали, что на северном гребне горы, в самой высокой точке, им повстречался какой-то чаровяз могу.$B$BОн использует магию, с которой нам еще никогда не приходилось сталкиваться.$B$BНужно как можно больше узнать об этом создании. Убей его и принеси мне все, что удастся найти.','Убейте чаровяза из клана Корун и заберите у него кодекс клана Корун.','Какая удивительная находка! Именно то, что мы искали!','Что тебе удалось найти?','Вернитесь к Фанлиру Серебряному Шипу в Могуцзя на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Терракотовые стражи выглядят устрашающе, но они не идут ни в какое сравнение с существом, которое мы обнаружили в верхней части руин.$B$BВыжившие разведчики рассказали, что на северном гребне горы, в самой высокой точке, им повстречался какой-то чаровяз могу.$B$BОн использует магию, с которой нам еще никогда не приходилось сталкиваться.$B$BНужно как можно больше узнать об этом создании. Убей его и принеси мне все, что удастся найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чаровяза из клана Корун и заберите у него кодекс клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая удивительная находка! Именно то, что мы искали!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фанлиру Серебряному Шипу в Могуцзя на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32246,'Встреча с разведчицей','Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки разведчики Альянса столкнулись с отрядом Орды на берегах Красарангских джунглей.$B$BПовстречайся с разведчицей Линной и помоги защитить место для высадки.','Поговорите с разведчицей Линной в Красарангской бухте, что в Красарангских джунглях.','Поговорите с разведчицей Линной в Красарангской бухте, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с разведчицей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки разведчики Альянса столкнулись с отрядом Орды на берегах Красарангских джунглей.$B$BПовстречайся с разведчицей Линной и помоги защитить место для высадки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с разведчицей Линной в Красарангской бухте, что в Красарангских джунглях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с разведчицей Линной в Красарангской бухте, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32247,'Истинный король','Нельзя терять ни минуты! Мы должны найти Тротмана и обеспечить нашу безопасность.$B$BЯ беспокоюсь за дворфов – они крепкие ребята, но не солдаты. Они должны быть у скал, что к северу отсюда.$B$BСедлай коня, |3-6($c). Мы сделаем все во имя наших друзей. Во имя Альянса.','Сопроводите короля Вариана Ринна к маршалу Тротману и Хильде Хорнсвоггл. Убейте 25 солдат Орды.','Меня устраивает это место. Настало время привести сюда весь наш флот.','Поговорите с королем Варианом Ринном в Красарангской бухте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинный король',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя терять ни минуты! Мы должны найти Тротмана и обеспечить нашу безопасность.$B$BЯ беспокоюсь за дворфов – они крепкие ребята, но не солдаты. Они должны быть у скал, что к северу отсюда.$B$BСедлай коня, |3-6($c). Мы сделаем все во имя наших друзей. Во имя Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите короля Вариана Ринна к маршалу Тротману и Хильде Хорнсвоггл. Убейте 25 солдат Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня устраивает это место. Настало время привести сюда весь наш флот.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Варианом Ринном в Красарангской бухте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32248,'Немного терпения','Начните сценарий "Немного терпения" и обратитесь к королю Вариану Ринну.','Начните сценарий "Немного терпения" и поговорите с королем Варианом Ринном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного терпения',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начните сценарий "Немного терпения" и обратитесь к королю Вариану Ринну.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Начните сценарий "Немного терпения" и поговорите с королем Варианом Ринном.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32249,'Встреча с разведчицей','Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки флота, разведчики Орды столкнулись с отрядом Альянса на небольшом островке недалеко от Красарангских джунглей.$B$BВстреться с разведчицей Роклой и помоги защитить место для высадки.','Поговорите с разведчицей Роклой в Точке высадки Орды, что в Красарангских джунглях.','Ты как раз вовремя. Мы ждем вождя с минуты на минуту. Как только он убедится, что выбрано подходящее место, прибудет наш флот.','Поговорите с разведчицей Роклой в Точке высадки Орды, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с разведчицей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошло уже два месяца с того момента, как разошлась пелена туманов. В поисках подходящего места для высадки флота, разведчики Орды столкнулись с отрядом Альянса на небольшом островке недалеко от Красарангских джунглей.$B$BВстреться с разведчицей Роклой и помоги защитить место для высадки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с разведчицей Роклой в Точке высадки Орды, что в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя. Мы ждем вождя с минуты на минуту. Как только он убедится, что выбрано подходящее место, прибудет наш флот.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с разведчицей Роклой в Точке высадки Орды, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32250,'Могущество вождя','Пойдем, |3-6($c). Я хочу осмотреть остров, чтобы убедиться, что подготовка в высадке проведена успешно.$B$BКровавый страж Гро\'таш должен быть где-то на северной стороне острова – там он ищет подходящее место для строительства крепости. Разведотряд гоблинов направился на восточное побережье в поисках нефти.$B$BДавай уничтожим эту жалкую горстку врагов и установим господство Орды над островом!','Сопроводите Гарроша Адского Крика к кровавому стражу Гро\'ташу и Гриззлу Скрипетолу, а также уничтожьте 25 бойцов Альянса.','Отлично. Мы их заставим с собой считаться!','Поговорите с Гаррошем Адским Криком в Точке высадки Орды, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могущество вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пойдем, |3-6($c). Я хочу осмотреть остров, чтобы убедиться, что подготовка в высадке проведена успешно.$B$BКровавый страж Гро\'таш должен быть где-то на северной стороне острова – там он ищет подходящее место для строительства крепости. Разведотряд гоблинов направился на восточное побережье в поисках нефти.$B$BДавай уничтожим эту жалкую горстку врагов и установим господство Орды над островом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Гарроша Адского Крика к кровавому стражу Гро\'ташу и Гриззлу Скрипетолу, а также уничтожьте 25 бойцов Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Мы их заставим с собой считаться!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаррошем Адским Криком в Точке высадки Орды, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32251,'Кинжал во тьме','Темный охотник Вол\'джин присоединился к группе кор\'кронских разведчиков, выполняющих важное поручение вождя.$B$BРазумеется, они будут рады, если вы поможете им в этой нелегкой миссии, но имейте в виду – дела могут пойти плохо.','Начните сценарий "Кинжал во тьме" и обратитесь к Вол\'джину.','Начните сценарий "Кинжал во тьме" и поговорите с Вол\'джином.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кинжал во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темный охотник Вол\'джин присоединился к группе кор\'кронских разведчиков, выполняющих важное поручение вождя.$B$BРазумеется, они будут рады, если вы поможете им в этой нелегкой миссии, но имейте в виду – дела могут пойти плохо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начните сценарий "Кинжал во тьме" и обратитесь к Вол\'джину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Начните сценарий "Кинжал во тьме" и поговорите с Вол\'джином.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32252,'Вестники лоа','Тебе приходилось слышать о лоа? Мы не очень хорошо понимаем, что это, но, кажется, какая-то темная магия, которая обладает подобием разума.\r\n\r\nМы не знаем, какой силой обладают лоа, но я вынужден просить тебя остановить их ритуалы, |3-6($c).','Победите 2 вестников лоа.','Могу только представить себе, свидетелям каких ужасных вещей тебе пришлось стать, Звергон. Сегодня тебе пришлось пройти испытание на смелость, и ты выполнил задачу и не посрамил Орду.','Вернитесь к Халдарону Светлому Крылу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестники лоа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось слышать о лоа? Мы не очень хорошо понимаем, что это, но, кажется, какая-то темная магия, которая обладает подобием разума.\r\n\r\nМы не знаем, какой силой обладают лоа, но я вынужден просить тебя остановить их ритуалы, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 2 вестников лоа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могу только представить себе, свидетелям каких ужасных вещей тебе пришлось стать, Звергон. Сегодня тебе пришлось пройти испытание на смелость, и ты выполнил задачу и не посрамил Орду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32253,'REMOVE (No Longer Used)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REMOVE (No Longer Used)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32254,'Манипулирование сауроками','На утесах Ихгалук работают три магистра. Они следят за сауроками и всеми силами стараются настроить их против могу. Я хочу, чтобы ты $gнашел:нашла; их и $gузнал:узнала;, не нужны ли им припасы или помощь.$b$bОни находятся в укрытиях. Ищи мерцающие столпы света в деревне сауроков.','Поговорите с магистрами Арланом, Сариеном и Весарой.','Вернитесь к верховному магу Этасу Похитителю Солнца на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манипулирование сауроками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На утесах Ихгалук работают три магистра. Они следят за сауроками и всеми силами стараются настроить их против могу. Я хочу, чтобы ты $gнашел:нашла; их и $gузнал:узнала;, не нужны ли им припасы или помощь.$b$bОни находятся в укрытиях. Ищи мерцающие столпы света в деревне сауроков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с магистрами Арланом, Сариеном и Весарой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Этасу Похитителю Солнца на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32255,'Возвращение големов','Сауроки постоянно пытаются вторгнуться на наши территории, но обычно нашим големам удается дать им отпор. Однако некоторые из них были повержены, и сауроки утащили их на утесы Ихгалук.$b$bЯ хочу вернуть их назад. Ни одной скользкой ящерице не видать имущества Похитителей Солнца, пока я здесь командую.','Верните 4 украденных големов Похитителей Солнца.','Вернитесь к Этасу Похитителю Солнца на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение големов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки постоянно пытаются вторгнуться на наши территории, но обычно нашим големам удается дать им отпор. Однако некоторые из них были повержены, и сауроки утащили их на утесы Ихгалук.$b$bЯ хочу вернуть их назад. Ни одной скользкой ящерице не видать имущества Похитителей Солнца, пока я здесь командую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 4 украденных големов Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Этасу Похитителю Солнца на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32256,'Расцвет империи','Вождь Гаррош Адский Крик направляется на север вместе с отрядом элитных бойцов.$B$BСообщи ему о наших многочисленных победах над Альянсом. Поговори с Так-Таком, он тебе поможет добраться до места.','Докладывай.','Поговорите с вождем Гаррошем Адским Криком в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расцвет империи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь Гаррош Адский Крик направляется на север вместе с отрядом элитных бойцов.$B$BСообщи ему о наших многочисленных победах над Альянсом. Поговори с Так-Таком, он тебе поможет добраться до места.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Докладывай.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с вождем Гаррошем Адским Криком в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32257,'Глас богов','Слишком медленно?! Да мы трудимся изо всех сил, чтобы выполнить волю вождя!$B$BОднако раскопки следует вести осторожно, нужно записывать каждую находку и, конечно, требуется все делать с предельной осторожностью. Вождь должен войти в нашу ситуацию!$B$BВозможно, в скором времени мы будем готовы продемонстрировать ему результаты своей работы. Видишь ту статую на западе?$B$BМы подозреваем, что на самом деле это древний сосуд для хранения ценностей. Нам просто нужно найти способ ее открыть.$B$BЕсли ты хочешь помочь нам с раскопками, то веди себя поосторожнее.','Осмотрите ртутного стража и найдите древнюю табличку клана Корун.','Хм… очень интересно. Эта табличка содержит множество тайн.','Мы и сами в силах провести раскопки. Я понимаю, что тебя прислал вождь, но мы справимся быстрее, если он даст нам делать свою работу.','Поговорите с Фанлиром Серебряным Шипом на Плато предков, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глас богов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слишком медленно?! Да мы трудимся изо всех сил, чтобы выполнить волю вождя!$B$BОднако раскопки следует вести осторожно, нужно записывать каждую находку и, конечно, требуется все делать с предельной осторожностью. Вождь должен войти в нашу ситуацию!$B$BВозможно, в скором времени мы будем готовы продемонстрировать ему результаты своей работы. Видишь ту статую на западе?$B$BМы подозреваем, что на самом деле это древний сосуд для хранения ценностей. Нам просто нужно найти способ ее открыть.$B$BЕсли ты хочешь помочь нам с раскопками, то веди себя поосторожнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите ртутного стража и найдите древнюю табличку клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм… очень интересно. Эта табличка содержит множество тайн.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы и сами в силах провести раскопки. Я понимаю, что тебя прислал вождь, но мы справимся быстрее, если он даст нам делать свою работу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Фанлиром Серебряным Шипом на Плато предков, что в Вечноцветущем доле.',`completedtext_loc8`);
