INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32262,'Возвращение пленников','Эти выскочки из Кирин-Тора совсем обнаглели! Теперь они удерживают наших собратьев в качестве военнопленных!$b$bПодобное обращение с Похитителями Солнца недопустимо, так что никаких переговоров по обмену пленниками не будет. Мы вызволим их самостоятельно.$b$bОтправляйся на Аметистовый утес и освободи столько пленников, сколько сможешь. Но только $gсам:сама; не попадись в лапы Кирин-Тора. Мы не можем себе позволить потерять еще и тебя.','Освободите 5 пленников из Похитителей Солнца, удерживаемых в окрестностях Аметистового утеса.','Те, кого ты сегодня спас, несомненно, отблагодарили бы тебя, если бы не валились с ног от усталости.$B$BИтак, наша операция продолжается. И мы никого не будем оставлять в беде!','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение пленников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти выскочки из Кирин-Тора совсем обнаглели! Теперь они удерживают наших собратьев в качестве военнопленных!$b$bПодобное обращение с Похитителями Солнца недопустимо, так что никаких переговоров по обмену пленниками не будет. Мы вызволим их самостоятельно.$b$bОтправляйся на Аметистовый утес и освободи столько пленников, сколько сможешь. Но только $gсам:сама; не попадись в лапы Кирин-Тора. Мы не можем себе позволить потерять еще и тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 пленников из Похитителей Солнца, удерживаемых в окрестностях Аметистового утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Те, кого ты сегодня спас, несомненно, отблагодарили бы тебя, если бы не валились с ног от усталости.$B$BИтак, наша операция продолжается. И мы никого не будем оставлять в беде!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32263,'Find scout near enemy camp (injured, port him back)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Find scout near enemy camp (injured, port him back)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32264,'Зачарованная книга','У Джайны есть несколько очень могущественных магических артефактов. Она всегда возит их с собой. Один из этих предметов меня очень интересует.$b$bКнига, таящая в себе знания, которую Верховные Маги передают из поколения в поколение. Мне удавалось увидеть ее лишь мельком.$b$bИ, раз уж мы теперь по разные стороны баррикад, не вижу ничего страшного в том, чтобы завладеть этой книгой.','Заберите потрепанную книгу заклинаний Джайны, ее можно найти на Аметистовом утесе.','Ну что? Книга у тебя?','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованная книга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Джайны есть несколько очень могущественных магических артефактов. Она всегда возит их с собой. Один из этих предметов меня очень интересует.$b$bКнига, таящая в себе знания, которую Верховные Маги передают из поколения в поколение. Мне удавалось увидеть ее лишь мельком.$b$bИ, раз уж мы теперь по разные стороны баррикад, не вижу ничего страшного в том, чтобы завладеть этой книгой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите потрепанную книгу заклинаний Джайны, ее можно найти на Аметистовом утесе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Книга у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32265,'Заряженный моганит','Мы каждый день отправляем шпионов на базу Кирин-Тора. Некоторые из них получили задание найти на вражеской территории заряженный моганит и доставить его сюда.$b$bОни не вернулись обратно, хотя я знаю, что они покинули базу Кирин-Тора.$b$bОбыщи джунгли между нами и базой и собери весь моганит, который мог потеряться при транспортировке. Принеси его мне и мы найдем ему достойное применение.','Найдите заряженный моганит и принесите его верховному чародею Савору.','Замечательно. Нам этот артефакт пригодится больше, чем Кирин-Тору.','Поговорите с верховным чародеем Савором на Мысе Искателя Рассвета, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заряженный моганит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы каждый день отправляем шпионов на базу Кирин-Тора. Некоторые из них получили задание найти на вражеской территории заряженный моганит и доставить его сюда.$b$bОни не вернулись обратно, хотя я знаю, что они покинули базу Кирин-Тора.$b$bОбыщи джунгли между нами и базой и собери весь моганит, который мог потеряться при транспортировке. Принеси его мне и мы найдем ему достойное применение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заряженный моганит и принесите его верховному чародею Савору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Нам этот артефакт пригодится больше, чем Кирин-Тору.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным чародеем Савором на Мысе Искателя Рассвета, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32266,'Олицетворение маны','Манадемоны – ужасно противные создания. Поскольку они небольшие, их легко недооценить, но для чародеев они могут оказаться смертельными. Кирин-Тор посеял эту заразу по всему Аметистовому утесу.$b$bНадо обращаться с ними осторожно. Поодиночке с ними легко расправиться, но когда они собираются в группы, это все осложняет.$b$bОтправляйся на Аметистовый утес и сократи их ряды.','Убейте 9 манадемонов Кирин-Тора.','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Олицетворение маны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Манадемоны – ужасно противные создания. Поскольку они небольшие, их легко недооценить, но для чародеев они могут оказаться смертельными. Кирин-Тор посеял эту заразу по всему Аметистовому утесу.$b$bНадо обращаться с ними осторожно. Поодиночке с ними легко расправиться, но когда они собираются в группы, это все осложняет.$b$bОтправляйся на Аметистовый утес и сократи их ряды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 манадемонов Кирин-Тора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32267,'Destroy enemy portal near camp (streaming attackers, defended, enemy can use)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Destroy enemy portal near camp (streaming attackers, defended, enemy can use)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32268,'Тактические мана-бомбы','Ах, |3-6($p), я как раз ищу $gтакого:такую:r; |3-3($r), как ты. Мне прислали новую партию тактических мана-бомб, которые нужно разместить в ключевых точках на Аметистовом утесе к юго-востоку отсюда.$b$bВот, возьми. Я не могу доверить нашим простым солдатам такую мощь. Ох... и не тряси их ни в коем случае.$b$bУстанови одну на кораблях Кирин-Тора, еще одну – возле их припасов, а последнюю – на големе, которого они строят.','Установите тактическую мана-бомбу на корабле Альянса, партии припасов Альянса и в месте проведения ритуала возведения.','Наверняка даже эти маленькие мана-бомбы заставляют Джайну кипеть от злости. Поделом ей.$B$BДаларан был моим домом еще до того, как ее деды появились на свет. Какое она имела право выгнать меня из моего собственного дома?','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тактические мана-бомбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, |3-6($p), я как раз ищу $gтакого:такую:r; |3-3($r), как ты. Мне прислали новую партию тактических мана-бомб, которые нужно разместить в ключевых точках на Аметистовом утесе к юго-востоку отсюда.$b$bВот, возьми. Я не могу доверить нашим простым солдатам такую мощь. Ох... и не тряси их ни в коем случае.$b$bУстанови одну на кораблях Кирин-Тора, еще одну – возле их припасов, а последнюю – на големе, которого они строят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите тактическую мана-бомбу на корабле Альянса, партии припасов Альянса и в месте проведения ритуала возведения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наверняка даже эти маленькие мана-бомбы заставляют Джайну кипеть от злости. Поделом ей.$B$BДаларан был моим домом еще до того, как ее деды появились на свет. Какое она имела право выгнать меня из моего собственного дома?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32269,'Вывести защиту из строя','Нам надо пристально следить за Кирин-Тором и тем, чем они занимаются изо дня в день. Обычно это не вызывало бы проблем. Мы бы заслали к ним шпиона и ждали его доносов.$b$bНо у нас тут возникла проблема, и, как мне кажется, ты можешь помочь ее разрешить.$b$bСила защитных кристаллов Кирин-Тора возросла. Пройти мимо них почти невозможно. Если их на какое-то время обезвредить, то мы сможем пробраться внутрь.','Уничтожьте 6 защитных кристаллов Кирин-Тора.','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вывести защиту из строя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам надо пристально следить за Кирин-Тором и тем, чем они занимаются изо дня в день. Обычно это не вызывало бы проблем. Мы бы заслали к ним шпиона и ждали его доносов.$b$bНо у нас тут возникла проблема, и, как мне кажется, ты можешь помочь ее разрешить.$b$bСила защитных кристаллов Кирин-Тора возросла. Пройти мимо них почти невозможно. Если их на какое-то время обезвредить, то мы сможем пробраться внутрь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 защитных кристаллов Кирин-Тора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
