INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32273,'Destroy summoning circles in enemy camp (BloodElf_PowerOrb_Red)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Destroy summoning circles in enemy camp (BloodElf_PowerOrb_Red)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32274,'Обитатели утесов Ихгалук','Клан Гнилого Клинка угрожает нашим собратьям, но ответить на это кровавой резней, убивая всех подряд, было бы чересчур.$b$bРазумнее всего будет убить вождей их племени. Кровопролития при этом будет меньше, но они поймут, что нужно уважать установленные нами границы.','Убейте громилу Гнилого Клинка, сауро-жреца Гнилого Клинка и рассекателя волн Гнилого Клинка.','Я знаю истинную цену пролитой крови. Я знаю цену войне.$B$BКонечно, проще всего было бы устроить бойню и убивать их до тех пор, пока они не сдадутся. Но правильно ли это?','Вернитесь к служителю солнца Дезко на Остров Грома. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обитатели утесов Ихгалук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Гнилого Клинка угрожает нашим собратьям, но ответить на это кровавой резней, убивая всех подряд, было бы чересчур.$b$bРазумнее всего будет убить вождей их племени. Кровопролития при этом будет меньше, но они поймут, что нужно уважать установленные нами границы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте громилу Гнилого Клинка, сауро-жреца Гнилого Клинка и рассекателя волн Гнилого Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю истинную цену пролитой крови. Я знаю цену войне.$B$BКонечно, проще всего было бы устроить бойню и убивать их до тех пор, пока они не сдадутся. Но правильно ли это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к служителю солнца Дезко на Остров Грома. ',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32275,'Оперативная смерть','Зандаларские заклинатели зверей дрессируют небесных крикунов, превращая их в яростных существ, способных напасть с неба. Душеловам для ритуалов требуется огромное количество жертв – и этими жертвами становятся наши сородичи. А воины-ягуары подбираются все ближе к сердцу нашего лагеря.\r\n\r\nРазыщи их в За\'Туале и устрани эту угрозу.','Убейте 3 зандаларских душеловов, 3 зандаларских заклинателей зверей и 3 зандаларских воинов-ягуаров.','Я не смогу сомкнуть глаз до тех пор, пока мы полностью не избавимся от угрозы со стороны зандаларов. Но твоя помощь приблизила нас к этой цели. Благодарю тебя, Тираниум.','Вернитесь к Халдарону Светлому Крылу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оперативная смерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандаларские заклинатели зверей дрессируют небесных крикунов, превращая их в яростных существ, способных напасть с неба. Душеловам для ритуалов требуется огромное количество жертв – и этими жертвами становятся наши сородичи. А воины-ягуары подбираются все ближе к сердцу нашего лагеря.\r\n\r\nРазыщи их в За\'Туале и устрани эту угрозу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 зандаларских душеловов, 3 зандаларских заклинателей зверей и 3 зандаларских воинов-ягуаров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не смогу сомкнуть глаз до тех пор, пока мы полностью не избавимся от угрозы со стороны зандаларов. Но твоя помощь приблизила нас к этой цели. Благодарю тебя, Тираниум.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Халдарону Светлому Крылу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32276,'Разрушить эту стену!','Итак, время пришло. Мы достаточно укрепились здесь, и теперь можно попытаться перейти в наступление и направиться прямо в логово Властелина Грома. К сожалению, в ближайшее время он вряд ли планирует открыть для нас ворота.$b$bПолагаю, нам придется принять роль незваных гостей и открыть эти ворота самостоятельно. Дай мне знать, когда будешь $gготов:готова;, $n.','Поговорите с Лор\'темаром Тероном, а затем займите нижний город и обеспечьте там безопасность для войск Орды.','Благодаря твоей помощи мы сделали огромный шаг к нашей цели.','Вернитесь к Лор\'темару Терону на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушить эту стену!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, время пришло. Мы достаточно укрепились здесь, и теперь можно попытаться перейти в наступление и направиться прямо в логово Властелина Грома. К сожалению, в ближайшее время он вряд ли планирует открыть для нас ворота.$b$bПолагаю, нам придется принять роль незваных гостей и открыть эти ворота самостоятельно. Дай мне знать, когда будешь $gготов:готова;, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лор\'темаром Тероном, а затем займите нижний город и обеспечьте там безопасность для войск Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря твоей помощи мы сделали огромный шаг к нашей цели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32277,'В небо!','Проникните в Шахту Молний.','Превосходная работа. У нас появился просто грандиозный шанс.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В небо!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в Шахту Молний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходная работа. У нас появился просто грандиозный шанс.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32278,'Решительные меры','Зандаларские боевые корабли бороздят воды вокруг острова. На них перевозят солдат и боевых зверей, которые вступают в армию Лэй Шэня.$B$BЕсли нам удастся захватить пристань, то мы перекроем пути снабжения Властелина Грома и создадим вам надежный плацдарм.$B$BУ меня есть план действий, и большая армия нам вовсе не потребуется.','Проникните на Пристань Бушующих Волн и откройте ворота изнутри. Поговорите с Таоши, чтобы начать задание.','Обратитесь к Лор\'темару Терону на Мысе Искателя Рассвета на Острове Грома. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решительные меры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандаларские боевые корабли бороздят воды вокруг острова. На них перевозят солдат и боевых зверей, которые вступают в армию Лэй Шэня.$B$BЕсли нам удастся захватить пристань, то мы перекроем пути снабжения Властелина Грома и создадим вам надежный плацдарм.$B$BУ меня есть план действий, и большая армия нам вовсе не потребуется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните на Пристань Бушующих Волн и откройте ворота изнутри. Поговорите с Таоши, чтобы начать задание.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Лор\'темару Терону на Мысе Искателя Рассвета на Острове Грома. ',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32279,'Падение Шань-Бу','Давным-давно Лэй Шэнь обнаружил редкую кладку драконьих яиц. Из одного вылупился невероятно злобный дракон, который пожрал своих укротителей. Тогда Лэй Шэнь забрал его к себе.\r\n\r\nТеперь Шань-Бу, один из верных прислужников императора, пытается воскресить этого дракона. Мы должны одолеть Шань-Бу и не дать ему вернуть к жизни Налака!\r\n\r\nДай мне знать, когда мы можем выступать.','Победите Шань-Бу.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Шань-Бу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Лэй Шэнь обнаружил редкую кладку драконьих яиц. Из одного вылупился невероятно злобный дракон, который пожрал своих укротителей. Тогда Лэй Шэнь забрал его к себе.\r\n\r\nТеперь Шань-Бу, один из верных прислужников императора, пытается воскресить этого дракона. Мы должны одолеть Шань-Бу и не дать ему вернуть к жизни Налака!\r\n\r\nДай мне знать, когда мы можем выступать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Шань-Бу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32280,'Мателлокалипсис','Неплохое начало. Но теперь пора предпринять решительные действия.\r\n\r\nУбей повелителя металла Моно-Ханя.','Убейте повелителя металла Моно-Ханя у Шахты молний на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мателлокалипсис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неплохое начало. Но теперь пора предпринять решительные действия.\r\n\r\nУбей повелителя металла Моно-Ханя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте повелителя металла Моно-Ханя у Шахты молний на Острове Грома.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32281,'Кончина плотореза','Могу, на котором лежит ответственность за пытки посланников, плоторез Гоцзю, стоит возле шахты.\r\n\r\nУчитвая то, что он сделал с вашими посланниками, убить его будет только справедливо.','Убейте плотореза Гоцзю у Шахты молний на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кончина плотореза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу, на котором лежит ответственность за пытки посланников, плоторез Гоцзю, стоит возле шахты.\r\n\r\nУчитвая то, что он сделал с вашими посланниками, убить его будет только справедливо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте плотореза Гоцзю у Шахты молний на Острове Грома.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32282,'Компот из компсогната','Ящеры и компсогнаты зандаларов представляют для наших войск серьезную опасность. Они обладают небывалыми охотничьими навыками и могут почуять добычу на огромном расстоянии. Если они застанут свою жертву врасплох, этот бой может быть для нее последним.$b$bЯ хочу, чтобы ты $gпробрался:пробралась; в загоны для зверей и $gсократил:сократила; их количество. Мы должны убить их до того, как они пройдут полный курс дрессировки.','Убейте 5 ящеров и 10 дрессированных компсогнатов в загонах для зверей.','Сразу после прибытия на этот остров мы потеряли трех отличных солдат. Компсогнаты пробрались в палатки и убили их во сне. Иногда по ночам мне кажется, что я все еще слышу крики...','Поговорите с капитаном разведчиков Эльсией на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Компот из компсогната',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ящеры и компсогнаты зандаларов представляют для наших войск серьезную опасность. Они обладают небывалыми охотничьими навыками и могут почуять добычу на огромном расстоянии. Если они застанут свою жертву врасплох, этот бой может быть для нее последним.$b$bЯ хочу, чтобы ты $gпробрался:пробралась; в загоны для зверей и $gсократил:сократила; их количество. Мы должны убить их до того, как они пройдут полный курс дрессировки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 ящеров и 10 дрессированных компсогнатов в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразу после прибытия на этот остров мы потеряли трех отличных солдат. Компсогнаты пробрались в палатки и убили их во сне. Иногда по ночам мне кажется, что я все еще слышу крики...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном разведчиков Эльсией на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32283,'Лоа-завр','Зандалары научились насыщать своих зверей силой лоа, после чего те становятся невероятно сильны и смертельно опасны.$b$bМы должны прекратить это.$b$bУбей говорящего с лоа в загонах для зверей. Его можно найти возле светящихся животных.$b$bНельзя допустить, чтобы эти зверства продолжались.','Победите говорящего с лоа.','Отлично! Эти звери достаточно сильные. Нам совсем не нужно, чтобы они были полны злобы.','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лоа-завр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары научились насыщать своих зверей силой лоа, после чего те становятся невероятно сильны и смертельно опасны.$b$bМы должны прекратить это.$b$bУбей говорящего с лоа в загонах для зверей. Его можно найти возле светящихся животных.$b$bНельзя допустить, чтобы эти зверства продолжались.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите говорящего с лоа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Эти звери достаточно сильные. Нам совсем не нужно, чтобы они были полны злобы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32284,'Нужная встреча','$p? Какая удачная встреча.$b$bЧэнь Буйный Портер просил передать тебе этот сверток. Он ждет тебя в деревне Бинан на вершине Кунь-Лай.$b$bЧэнь обнаружил твоего раненого союзника, которому требуется помощь.$B$BЕще он сказал, чтобы ты обратился к Так-Таку, и он поможет тебе как можно быстрее добраться до него.','Найдите Чэня Буйного Портера в деревне Бинан. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.','О, так ты получил мое послание. Очень хорошо. Вол\'джин на грани смерти, и мне нужна твоя помощь, чтобы исцелить его.','Поговорите с Чэнем Буйным Портером в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужная встреча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$p? Какая удачная встреча.$b$bЧэнь Буйный Портер просил передать тебе этот сверток. Он ждет тебя в деревне Бинан на вершине Кунь-Лай.$b$bЧэнь обнаружил твоего раненого союзника, которому требуется помощь.$B$BЕще он сказал, чтобы ты обратился к Так-Таку, и он поможет тебе как можно быстрее добраться до него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Чэня Буйного Портера в деревне Бинан. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, так ты получил мое послание. Очень хорошо. Вол\'джин на грани смерти, и мне нужна твоя помощь, чтобы исцелить его.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в деревне Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32285,'Недремлющий легион','Шань’цзэ создают армию, оживляя статуи в центре острова, армию, которая днем и ночью пытается пробить нашу защиту. Уничтожь эти ходячие статуи, если увидишь их. Наши защитники будут очень благодарны.','Убейте 6 оживших воинов.','Ты сделал доброе дело.','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недремлющий легион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шань’цзэ создают армию, оживляя статуи в центре острова, армию, которая днем и ночью пытается пробить нашу защиту. Уничтожь эти ходячие статуи, если увидишь их. Наши защитники будут очень благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 оживших воинов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделал доброе дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32286,'Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32287,'Враги под башней','В Мрачных топях могу оживляют армию статуй возле башни. Лор\'темар приказывает убить их. Думаю, это работа как раз для тебя.','Убейте 7 могу Шань\'цзэ в Мрачных топях.','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враги под башней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Мрачных топях могу оживляют армию статуй возле башни. Лор\'темар приказывает убить их. Думаю, это работа как раз для тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 могу Шань\'цзэ в Мрачных топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32288,'Укрепим оборону','Усильте 6 защитных кристаллов Похитителей Солнца.','Итак, защитные кристаллы усилены, и мы можем заняться другими делами. Теперь никто не проскользнет мимо нас!','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укрепим оборону',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Усильте 6 защитных кристаллов Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, защитные кристаллы усилены, и мы можем заняться другими делами. Теперь никто не проскользнет мимо нас!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.',`completedtext_loc8`);
