INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32292,'Впереди кузня!','Перед тобой – кузня, центр производства оружия могу.\r\n\r\nТам же находится страж ворот, который хранит ключи, открывающие врата от следующей части города.\r\n\r\nПора двигаться вперед!','Итак?','Вернитесь к капитану разведчиков Эльсии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впереди кузня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тобой – кузня, центр производства оружия могу.\r\n\r\nТам же находится страж ворот, который хранит ключи, открывающие врата от следующей части города.\r\n\r\nПора двигаться вперед!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32293,'Среди костей','Мои разведчики обнаружили опасного зандалара среди костей к западу от утесов Ихгалук. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?','Убейте Зур\'чаку Ваятеля Костей.','Хорошо, что мне есть на кого положиться.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики обнаружили опасного зандалара среди костей к западу от утесов Ихгалук. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зур\'чаку Ваятеля Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что мне есть на кого положиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32294,'Дождь из костей','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?','Убейте Зур\'чаку Ваятеля Костей.','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дождь из костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зур\'чаку Ваятеля Костей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32295,'Необычная книга','Книга написана вычурным шрифтом, который выглядит так, будто слова парят над бумагой. Вам кажется, что это язык демонов, но буквы выписаны с большим изяществом.$B$BВозможно, кто-нибудь из ваших демонических спутников подскажет, что это такое?','Поговорите с вашим демоническим прислужником, чтобы определить происхождение книги.','Кодекс оказался наделенной великой силой книгой, написанной на языке, более древнем, чем демонический. Пожалуй, стоит показать ее наставникам чернокнижников в столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычная книга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Книга написана вычурным шрифтом, который выглядит так, будто слова парят над бумагой. Вам кажется, что это язык демонов, но буквы выписаны с большим изяществом.$B$BВозможно, кто-нибудь из ваших демонических спутников подскажет, что это такое?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вашим демоническим прислужником, чтобы определить происхождение книги.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Кодекс оказался наделенной великой силой книгой, написанной на языке, более древнем, чем демонический. Пожалуй, стоит показать ее наставникам чернокнижников в столице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32296,'Сокровища Властелина Грома','Разведчики донесли, что из склепа Лэй Шэня в цитадель продолжают переносить сокровища. У нас есть доступ к тайному входу в цитадель, расположенному в стоках, но из-за ворот мы не можем начать перехватывать их груз. Чтобы набег удался, нам понадобится ключ, который есть только у самых доверенных лиц Лэй Шэня.$B$BЕсли тебе попадется такой ключ, доставь его мне.$B$BМожешь оставить себе все, что соберешь при набеге. Я просто хочу, чтобы грузы не ушли Лэй Шэню.','Поговорите с Таоши, чтобы войти в цитадель Властелина Грома. Там отдайте ей ключи от дворца Лэй Шэня, чтобы начать набег на охрану сокровищницы.','Это, конечно, не провал, но в следующий раз будет лучше.$B$BСпасибо за ключ. Без тебя этот налет бы не состоялся.','Поговорите с Таоши на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики донесли, что из склепа Лэй Шэня в цитадель продолжают переносить сокровища. У нас есть доступ к тайному входу в цитадель, расположенному в стоках, но из-за ворот мы не можем начать перехватывать их груз. Чтобы набег удался, нам понадобится ключ, который есть только у самых доверенных лиц Лэй Шэня.$B$BЕсли тебе попадется такой ключ, доставь его мне.$B$BМожешь оставить себе все, что соберешь при набеге. Я просто хочу, чтобы грузы не ушли Лэй Шэню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Таоши, чтобы войти в цитадель Властелина Грома. Там отдайте ей ключи от дворца Лэй Шэня, чтобы начать набег на охрану сокровищницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это, конечно, не провал, но в следующий раз будет лучше.$B$BСпасибо за ключ. Без тебя этот налет бы не состоялся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Таоши на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32297,'Дикорог или дьявозавр','У нас есть отличная возможность нарушить планы зандаларов и заодно как следует посмеяться.$b$bВ этих загонах для зверей держат дьявозавра и дикорога. На них надета броня, а их разум при помощи заклинаний контролируют зандалары.$b$bОтправляйся в лагерь и прерви один из этих подчиняющих ритуалов. Какой именно – не имеет значения. Просто убей тех, кто пытается подчинить себе существо. Разъяренный зверь начнет носиться по всему лагерю зандаларов. А ты расслабься и наслаждайся веселым зрелищем.','Прервите подчиняющий ритуал, убив всех неигровых персонажей вокруг непокорного дикорога или непокорного дьявозавра.','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикорог или дьявозавр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть отличная возможность нарушить планы зандаларов и заодно как следует посмеяться.$b$bВ этих загонах для зверей держат дьявозавра и дикорога. На них надета броня, а их разум при помощи заклинаний контролируют зандалары.$b$bОтправляйся в лагерь и прерви один из этих подчиняющих ритуалов. Какой именно – не имеет значения. Просто убей тех, кто пытается подчинить себе существо. Разъяренный зверь начнет носиться по всему лагерю зандаларов. А ты расслабься и наслаждайся веселым зрелищем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите подчиняющий ритуал, убив всех неигровых персонажей вокруг непокорного дикорога или непокорного дьявозавра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с магистром Эдиеном Солнечной Низиной на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32298,'Мощь динозавра','У зандаларов есть множество фетишей и оберегов, при помощи которых они управляют своим зверинцем.$b$bЧто ж, мы можем сделать то же самое.$b$bНайди какие-нибудь из этих фетишей и опробуй их действие на разных животных в загонах для зверей.$b$bОбрати внимание, как действует каждый из них на разных животных. А затем сообщи результаты мне.$b$bМожет быть, это даст нам необходимое преимущество в борьбе с зандаларами.','Найдите и используйте заврофетиши на 5 ящерах, компсогнатах, небесных крикунах или дикорогах в загонах для зверей.','Очень интересные результаты. Уверен, где-то должен быть маг, который в этом разбирается. А вообще-то мне просто было приятно слышать, как орут тролли, на которых нападают их собственные животные.','Поговорите с капитаном разведчиков Эльсией на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь динозавра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У зандаларов есть множество фетишей и оберегов, при помощи которых они управляют своим зверинцем.$b$bЧто ж, мы можем сделать то же самое.$b$bНайди какие-нибудь из этих фетишей и опробуй их действие на разных животных в загонах для зверей.$b$bОбрати внимание, как действует каждый из них на разных животных. А затем сообщи результаты мне.$b$bМожет быть, это даст нам необходимое преимущество в борьбе с зандаларами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и используйте заврофетиши на 5 ящерах, компсогнатах, небесных крикунах или дикорогах в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень интересные результаты. Уверен, где-то должен быть маг, который в этом разбирается. А вообще-то мне просто было приятно слышать, как орут тролли, на которых нападают их собственные животные.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном разведчиков Эльсией на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32299,'Небольшая чистка','Скажу прямо, у меня для тебя довольно грязная работенка.$b$bСауроки Гнилого Клинка сносят всю свою гниль в водоем в самом центре деревни. Она настолько отвратительна, что стала собираться в плотную, подвижную и живую массу.$b$bСауроки, конечно, могут устраивать у себя болото, но их гниль стала вытекать за пределы деревни. Думаю, настала пора вмешаться в ситуацию.','Уничтожьте 75 частиц дрожащей гнили на утесах Ихгалук.','Именно из-за такой работы я порой радуюсь, что большая часть моего носа осталась в могиле.','Вернитесь к Амалии Пеншир на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшая чистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу прямо, у меня для тебя довольно грязная работенка.$b$bСауроки Гнилого Клинка сносят всю свою гниль в водоем в самом центре деревни. Она настолько отвратительна, что стала собираться в плотную, подвижную и живую массу.$b$bСауроки, конечно, могут устраивать у себя болото, но их гниль стала вытекать за пределы деревни. Думаю, настала пора вмешаться в ситуацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 75 частиц дрожащей гнили на утесах Ихгалук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Именно из-за такой работы я порой радуюсь, что большая часть моего носа осталась в могиле.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амалии Пеншир на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32300,'Взрывоопасная ирония','Что ж, похоже, леди Праудмур решила использовать против нас наше собственное оружие. Защитные кристаллы сработали: через границу просочились несколько лазутчиков с тактическими мана-бомбами.$b$bМожно бы и оценить иронию этой ситуации, не будь бомбы действительно опасны.$b$bНайди эти бомбы и обезвредь их. Судя по состоянию кристаллов, одна из них находится рядом с кораблями Орды к северу, одна на мосту на большой остров, и одна – рядом с кристаллами ясновидения в восточной части мыса.','Отличная работа. Настоящая ирония в том, что, будь это обычные бомбы, нам было бы гораздо сложнее обнаружить их. Какая-нибудь хитроумная гномья примочка – и нашей операции здесь мог бы прийти конец.','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывоопасная ирония',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, похоже, леди Праудмур решила использовать против нас наше собственное оружие. Защитные кристаллы сработали: через границу просочились несколько лазутчиков с тактическими мана-бомбами.$b$bМожно бы и оценить иронию этой ситуации, не будь бомбы действительно опасны.$b$bНайди эти бомбы и обезвредь их. Судя по состоянию кристаллов, одна из них находится рядом с кораблями Орды к северу, одна на мосту на большой остров, и одна – рядом с кристаллами ясновидения в восточной части мыса.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Настоящая ирония в том, что, будь это обычные бомбы, нам было бы гораздо сложнее обнаружить их. Какая-нибудь хитроумная гномья примочка – и нашей операции здесь мог бы прийти конец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32301,'Старые враги','Подумать только, когда-то мы сражались плечом к плечу! Предательство Похитителей Солнца застало нас врасплох. Больше такое не повторится!$b$bОни показали свою истинную суть. Раз они встали на сторону Гарроша и поддались его безумию, то обречены на смерть.$b$bУбивай всех агентов Похитителей Солнца, которые тебе встретятся. Мы будем к ним беспощадны!','Да, тебе удалось неплохо потрепать Похитителей Солнца. Они кишат, словно паразиты – их осталось еще много. Нужно быть постоянно начеку.','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подумать только, когда-то мы сражались плечом к плечу! Предательство Похитителей Солнца застало нас врасплох. Больше такое не повторится!$b$bОни показали свою истинную суть. Раз они встали на сторону Гарроша и поддались его безумию, то обречены на смерть.$b$bУбивай всех агентов Похитителей Солнца, которые тебе встретятся. Мы будем к ним беспощадны!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, тебе удалось неплохо потрепать Похитителей Солнца. Они кишат, словно паразиты – их осталось еще много. Нужно быть постоянно начеку.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32302,'Уничтожение големов','Големы Кирин-Тора ужасно примитивны, но, тем не менее, представляют угрозу.$b$bОтправляйся на Аметистовый утес и обезвредь эти ничтожные машины войны. Покажи Кирин-Тору, как легко их сломить!$b$bТакое послание Кирин-Тору не удастся проигнорировать.','Уничтожьте 3 голема Кирин-Тора на Аметистовом утесе.','Големы уничтожены? Хорошо!$B$BНельзя дать Джайне и Кирин-Тору забыть о том, что Похитителей Солнца не так уж легко победить.','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение големов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Големы Кирин-Тора ужасно примитивны, но, тем не менее, представляют угрозу.$b$bОтправляйся на Аметистовый утес и обезвредь эти ничтожные машины войны. Покажи Кирин-Тору, как легко их сломить!$b$bТакое послание Кирин-Тору не удастся проигнорировать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 голема Кирин-Тора на Аметистовом утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Големы уничтожены? Хорошо!$B$BНельзя дать Джайне и Кирин-Тору забыть о том, что Похитителей Солнца не так уж легко победить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиране Окровавленной на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32303,'Создан для войны','Джайна думает, что с легкостью выиграет эту битву. Я докажу ей, что она заблуждается!$b$bУ Кирин-Тор есть оружие, которое необходимо ликвидировать. Чародейский разрушитель – огромный голем, который может полностью изменить ход битвы.$b$bЕсли мы уничтожим его, Праудмур поймет, что с нами не так легко справиться.','Ликвидируйте чародейского разрушителя.','Жаль, не довелось увидеть лицо Праудмур, когда он увидела, что случилось с ее машиной смерти!$B$BНаверняка она построит новую, но мы выиграли время.','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создан для войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Джайна думает, что с легкостью выиграет эту битву. Я докажу ей, что она заблуждается!$b$bУ Кирин-Тор есть оружие, которое необходимо ликвидировать. Чародейский разрушитель – огромный голем, который может полностью изменить ход битвы.$b$bЕсли мы уничтожим его, Праудмур поймет, что с нами не так легко справиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ликвидируйте чародейского разрушителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жаль, не довелось увидеть лицо Праудмур, когда он увидела, что случилось с ее машиной смерти!$B$BНаверняка она построит новую, но мы выиграли время.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному чародею Савору на Мыс Искателя Рассвета.',`completedtext_loc8`);
