INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32305,'Перегрузка','Для усиления своих войск Кирин-Тор использует мана-сферы. Так не должно продолжаться.$b$bМана-сферы разбросаны на окраинах Аметистового утеска. Используй этот кристалл маны, чтобы разрушить их.$b$bКаждая уничтоженная мана-сфера приближает нас к победе.','Уничтожьте 7 мана-сфер на Аметистовом утесе.','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перегрузка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для усиления своих войск Кирин-Тор использует мана-сферы. Так не должно продолжаться.$b$bМана-сферы разбросаны на окраинах Аметистового утеска. Используй этот кристалл маны, чтобы разрушить их.$b$bКаждая уничтоженная мана-сфера приближает нас к победе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 7 мана-сфер на Аметистовом утесе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.',`completedtext_loc8`);
