INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32307,'Чтец мертвого языка','Вам надо вернуться в столицу и найти тренера чернокнижников, который может знать больше о кодексе.','Отнесите кодекс наставнику чернокнижников в вашей столице.','Где... во имя великой Тьмы, откуда у тебя это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтец мертвого языка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам надо вернуться в столицу и найти тренера чернокнижников, который может знать больше о кодексе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кодекс наставнику чернокнижников в вашей столице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где... во имя великой Тьмы, откуда у тебя это?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32309,'История шести мастеров','Возможно, эта книга – как раз то, что мы искали...$b$bКак много тебе известно о Совете Мрачной Жатвы, $n?$b$bПосле гибели Смертокрыла шесть великих чернокнижников собрались вместе, чтобы обучать своих соратников более сложным видам магии – знаниям, похищенным ими у наших побежденных противников.$b$bВзгляни на эту книгу...','Прочтите первую главу "Наследия мастеров".','Возвращайтесь к вашему наставнику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История шести мастеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, эта книга – как раз то, что мы искали...$b$bКак много тебе известно о Совете Мрачной Жатвы, $n?$b$bПосле гибели Смертокрыла шесть великих чернокнижников собрались вместе, чтобы обучать своих соратников более сложным видам магии – знаниям, похищенным ими у наших побежденных противников.$b$bВзгляни на эту книгу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите первую главу "Наследия мастеров".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Возвращайтесь к вашему наставнику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32310,'История шести мастеров','Возможно, эта книга – как раз то, что мы искали...$b$bКак много тебе известно о Совете Мрачной Жатвы, $n?$b$bПосле гибели Смертокрыла шесть великих чернокнижников собрались вместе, чтобы обучать своих соратников более сложным видам магии – знаниям, похищенным ими у наших побежденных противников.$b$bВзгляни на эту книгу...','Прочтите первую главу "Наследия мастеров".','Теперь тебе пора узнать кое-что еще...','Возвращайтесь к вашему наставнику.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История шести мастеров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, эта книга – как раз то, что мы искали...$b$bКак много тебе известно о Совете Мрачной Жатвы, $n?$b$bПосле гибели Смертокрыла шесть великих чернокнижников собрались вместе, чтобы обучать своих соратников более сложным видам магии – знаниям, похищенным ими у наших побежденных противников.$b$bВзгляни на эту книгу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите первую главу "Наследия мастеров".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь тебе пора узнать кое-что еще...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Возвращайтесь к вашему наставнику.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32311,'Приказы о зачислении на военную службу','После возвращения Совет передал полученные знания всем остальным чернокнижникам.$b$bНо вскоре после этого они исчезли...$b$b$n! Книга, которую ты держишь в руках, может быть как раз той вещью, которая поможет убедить их присоединиться к нам в нашем нападении на Альянс!$b$bРазыщи генерала Назгрима в Крепости Покорителей и убеди его в важности этой миссии.','Найдите генерала Назгрима в Крепости Покорителей, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы о зачислении на военную службу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После возвращения Совет передал полученные знания всем остальным чернокнижникам.$b$bНо вскоре после этого они исчезли...$b$b$n! Книга, которую ты держишь в руках, может быть как раз той вещью, которая поможет убедить их присоединиться к нам в нашем нападении на Альянс!$b$bРазыщи генерала Назгрима в Крепости Покорителей и убеди его в важности этой миссии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите генерала Назгрима в Крепости Покорителей, что в Красарангских джунглях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32312,'Приказы о зачислении на военную службу','После возвращения Совет передал полученные знания всем остальным чернокнижникам.$b$bНо вскоре после этого они исчезли...$b$b$n! Книга, которую ты держишь в руках, может быть как раз той вещью, которая поможет убедить их присоединиться к нам в нашем нападении на Орду!$b$bРазыщи адмирала Тейлора в Львином лагере и убеди его в важности этой миссии.','Найдите адмирала Тейлора в Львином лагере, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы о зачислении на военную службу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После возвращения Совет передал полученные знания всем остальным чернокнижникам.$b$bНо вскоре после этого они исчезли...$b$b$n! Книга, которую ты держишь в руках, может быть как раз той вещью, которая поможет убедить их присоединиться к нам в нашем нападении на Орду!$b$bРазыщи адмирала Тейлора в Львином лагере и убеди его в важности этой миссии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите адмирала Тейлора в Львином лагере, что в Красарангских джунглях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32313,'Выследить Хельхейма','$n... Ты правильно меня $gуслышал:услышала;. Вождь Гаррош приказал мне выследить Совет Мрачной Жатвы.$b$bЯ узнал о том, что Альянс нас опережает, к несчастью. Мне говорили, что человек-чернокнижник по имени Харим Хельхейм владеет информацией, которая может нам помочь разыскать их.$b$bОтправляйся в Львиный лагерь, проберись на их базу и заполучи документы. Не жалей Хельхейма.','Убейте Харима Хельхейма и заберите вторую часть "Наследия мастеров".','Вернитесь к генералу Назгриму в Крепость Покорителей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выследить Хельхейма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n... Ты правильно меня $gуслышал:услышала;. Вождь Гаррош приказал мне выследить Совет Мрачной Жатвы.$b$bЯ узнал о том, что Альянс нас опережает, к несчастью. Мне говорили, что человек-чернокнижник по имени Харим Хельхейм владеет информацией, которая может нам помочь разыскать их.$b$bОтправляйся в Львиный лагерь, проберись на их базу и заполучи документы. Не жалей Хельхейма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Харима Хельхейма и заберите вторую часть "Наследия мастеров".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Назгриму в Крепость Покорителей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32314,'Убить Селенору','$n... Ты правильно меня $gуслышал:услышала;. Король Вариан приказал мне выследить Совет Мрачной Жатвы.$b$bК несчастью, Орда тоже за ними охотится. Один из моих шпионов сообщил, что вторая часть их дневника – у тенеманта Селеноры.$b$bОтправляйся в Крепость Покорителей, убей Селенору, обыщи ее труп и принеси сюда все, что найдешь.','Убейте тенеманта Селенору в Крепости Покорителей и заберите вторую часть "Наследия мастеров".','Вернитесь к адмиралу Тейлору в Львиный лагерь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить Селенору',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n... Ты правильно меня $gуслышал:услышала;. Король Вариан приказал мне выследить Совет Мрачной Жатвы.$b$bК несчастью, Орда тоже за ними охотится. Один из моих шпионов сообщил, что вторая часть их дневника – у тенеманта Селеноры.$b$bОтправляйся в Крепость Покорителей, убей Селенору, обыщи ее труп и принеси сюда все, что найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте тенеманта Селенору в Крепости Покорителей и заберите вторую часть "Наследия мастеров".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Тейлору в Львиный лагерь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32315,'Призыв о помощи от Андуина','Спасибо тебе, |3-6(Охотник). Нам предстоит много дел.','Поговорите с Андуином Ринном на Императорской бирже в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв о помощи от Андуина',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, |3-6(Охотник). Нам предстоит много дел.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном на Императорской бирже в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32316,'Сердце Альянса','Не могу поверить в то, что произошло, $n. Неужели после множества испытаний, пережитых нами в Пандарии, наши люди так не извлекли никаких уроков?$B$BНа днях экспедиция Бранна вернулась из Могуцзя, принеся с собой образец ша для исследования.$B$BУ меня сразу возникли сомнения насчет этой затеи, и вот подтвердились мои худшие опасения.$B$BШа сбежал из заточения. Думаю, не стоит объяснять, насколько страшно его присутствие в самом сердце дола.$B$BНужно как можно быстрее избавиться от него!','Сразитесь с 6 пораженными ша пехотинцами. Если вы разминетесь с принцем Андуином, можете встретиться с ним на Императорской бирже.','Вижу, вы с моим сыном славно потрудились. Спасибо, что ты взялся помочь нам в доле.','Поговорите с королем Варианом Ринном в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не могу поверить в то, что произошло, $n. Неужели после множества испытаний, пережитых нами в Пандарии, наши люди так не извлекли никаких уроков?$B$BНа днях экспедиция Бранна вернулась из Могуцзя, принеся с собой образец ша для исследования.$B$BУ меня сразу возникли сомнения насчет этой затеи, и вот подтвердились мои худшие опасения.$B$BШа сбежал из заточения. Думаю, не стоит объяснять, насколько страшно его присутствие в самом сердце дола.$B$BНужно как можно быстрее избавиться от него!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с 6 пораженными ша пехотинцами. Если вы разминетесь с принцем Андуином, можете встретиться с ним на Императорской бирже.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, вы с моим сыном славно потрудились. Спасибо, что ты взялся помочь нам в доле.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с королем Варианом Ринном в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32318,'Время на исцеление','Вол\'джин погиб бы, если бы в его жилах не текла кровь троллей. Он давно бы встал на ноги, но яд блокирует его способность к регенерации.$b$bМы должны очистить его тело от яда, чтобы он смог восстановиться. $b$bПоднимайся в небо и лети на юго-восток. Когда окажешься над горной грядой Тайного поселения, смотри внимательнее – там должны обитать иглистые лесные духи. Принеси мне несколько самых острых и прочных игл.$b$bС помощью акупунктуры я постараюсь вывести яд из его тела и ускорить выздоровление.','Соберите 10 прочных игл.','Отлично. Эти иглы должны подойти.','Только мои травы отгоняют смерть от Вол\'джина. Я ни на минуту не могу оставить его.','Поговорите с Чэнем Буйным Портером в деревне Бинан на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время на исцеление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вол\'джин погиб бы, если бы в его жилах не текла кровь троллей. Он давно бы встал на ноги, но яд блокирует его способность к регенерации.$b$bМы должны очистить его тело от яда, чтобы он смог восстановиться. $b$bПоднимайся в небо и лети на юго-восток. Когда окажешься над горной грядой Тайного поселения, смотри внимательнее – там должны обитать иглистые лесные духи. Принеси мне несколько самых острых и прочных игл.$b$bС помощью акупунктуры я постараюсь вывести яд из его тела и ускорить выздоровление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 прочных игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Эти иглы должны подойти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только мои травы отгоняют смерть от Вол\'джина. Я ни на минуту не могу оставить его.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Чэнем Буйным Портером в деревне Бинан на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32319,'Найти Тралла!','<Вол\'джин приоткрывает глаза и слабо двигает губами, пытаясь заговорить. Хотя вы не слышите не звука, по его губам можно прочесть два слова.>$b$bНайди Тралла.$b$b<Вол\'джин с усилием вкладывает в ваши руки камень возвращения и теряет сознание.>','Найдите Тралла, воспользовавшись камнем возвращения Вол\'джина.','<Тралл безмолвно смотрит на камень, который вы вручили ему.>$B$BЭто камень Вол\'джина! Неужели все зашло так далеко?','Ты проделал долгий путь, чтобы увидеть меня. Что за весть ты несешь?','Поговорите с Траллом в Долине Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Тралла!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вол\'джин приоткрывает глаза и слабо двигает губами, пытаясь заговорить. Хотя вы не слышите не звука, по его губам можно прочесть два слова.>$b$bНайди Тралла.$b$b<Вол\'джин с усилием вкладывает в ваши руки камень возвращения и теряет сознание.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Тралла, воспользовавшись камнем возвращения Вол\'джина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тралл безмолвно смотрит на камень, который вы вручили ему.>$B$BЭто камень Вол\'джина! Неужели все зашло так далеко?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты проделал долгий путь, чтобы увидеть меня. Что за весть ты несешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом в Долине Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32320,'Орда – одна семья','Вол\'джин много раз спасал мою жизнь. Мне больно видеть, как мои собственные кор\'кроны сражаются с его народом.','Поговорите с Траллом на островах Эха в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орда – одна семья',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вол\'джин много раз спасал мою жизнь. Мне больно видеть, как мои собственные кор\'кроны сражаются с его народом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом на островах Эха в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32321,'Король обезьян','С тех пор, как Орда захватила Божественный колокол, я искал способ противостоять его силе.$b$bМои поиски привели меня к этой гробнице. Следуй за мной, и я расскажу тебе всю историю до конца.$b$bЕсли потеряешь меня, возвращайся ко входу в гробницу. Дай мне знать, когда будешь $gготов:готова;.','А, услада моей души! Ну-ка спой предо мной, да спляши! Что за дело привело тебя ко мне на поклон? Да не стой как чурбан, от тебя меня клонит в сон! Не, так дело у нас с тобой не пойдет. Разгадай три загадки мои – будет слава тебе и почет!','Поговорите с Королем обезьян в Гробнице Завоевателей на Вершине Кунь-Лай.','Иногда миф можно победить только другим мифом.','Король обезьян') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король обезьян',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как Орда захватила Божественный колокол, я искал способ противостоять его силе.$b$bМои поиски привели меня к этой гробнице. Следуй за мной, и я расскажу тебе всю историю до конца.$b$bЕсли потеряешь меня, возвращайся ко входу в гробницу. Дай мне знать, когда будешь $gготов:готова;.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, услада моей души! Ну-ка спой предо мной, да спляши! Что за дело привело тебя ко мне на поклон? Да не стой как чурбан, от тебя меня клонит в сон! Не, так дело у нас с тобой не пойдет. Разгадай три загадки мои – будет слава тебе и почет!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Гробнице Завоевателей на Вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Иногда миф можно победить только другим мифом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Король обезьян',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32324,'В поисках сигнала','Осколки камня души сливаются в ваших руках.$B$BСтранно, но в камне не чувствуется присутствия души. Вместо этого он вытягивает энергию откуда-то из Долины Призрачной Луны. Взглянув на восток, вы ощущаете связь, которая тянется через горы до самых ворот Черного храма.','Следуйте за камнем души к вратам Черного храма.','Отнесите камень души к воротам Черного храма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках сигнала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осколки камня души сливаются в ваших руках.$B$BСтранно, но в камне не чувствуется присутствия души. Вместо этого он вытягивает энергию откуда-то из Долины Призрачной Луны. Взглянув на восток, вы ощущаете связь, которая тянется через горы до самых ворот Черного храма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следуйте за камнем души к вратам Черного храма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите камень души к воротам Черного храма.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32325,'Проникновение в Черный храм','Найдите метку Джубеки у главного входа Черного храма. Оказавшись внутри, поговорите с Джубекой на Храмовой вершине.','Ты сделал для этого мира больше, чем можешь себе представить, чернокнижник. Даже немного жаль, что Канретад закончил таким образом. С другой стороны, это было неизбежно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение в Черный храм',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите метку Джубеки у главного входа Черного храма. Оказавшись внутри, поговорите с Джубекой на Храмовой вершине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделал для этого мира больше, чем можешь себе представить, чернокнижник. Даже немного жаль, что Канретад закончил таким образом. С другой стороны, это было неизбежно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32326,'Проникновение','$n! Ты-то мне как раз и $gнужен:нужна;.$b$bМы знаем, где Альянс спрятал Божественный колокол. Мы уже внедрили нашего агента на вражескую территорию. Тебе надо только помочь ему выполнить миссию.$b$bСобирай вещи, ты отправляешься в Дарнас.','Воспользуйтесь порталом Похитителей Солнца в Крепости Покорителей, чтобы добраться до Дарнаса.','Найдите Фанлира Серебряного Шипа, который находится рядом с воротами Дарнаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Ты-то мне как раз и $gнужен:нужна;.$b$bМы знаем, где Альянс спрятал Божественный колокол. Мы уже внедрили нашего агента на вражескую территорию. Тебе надо только помочь ему выполнить миссию.$b$bСобирай вещи, ты отправляешься в Дарнас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом Похитителей Солнца в Крепости Покорителей, чтобы добраться до Дарнаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите Фанлира Серебряного Шипа, который находится рядом с воротами Дарнаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32327,'Миссия: Дарнас','Божественный колокол где-то в городе. Мы не хотим устраивать переполох, нам нужен только артефакт. Тебе придется найти способ незаметно проникнуть в город. Это значит – никаких полетов, никаких бешеных скачек и стычек.$b$bЯ помогу тебе, обеспечу незаметность. Еще я дам тебе этот маленький амулет, с помощью которого ты сможешь перенестись сюда, если попадешь в беду.$b$bСтупай, $n, отыщи Божественный колокол и пометь его, чтобы вместе с ним перенестись обратно.','Найдите Божественный колокол.$b$bЕсли попадете в беду, воспользуйтесь амулетом Луносвета, чтобы вернуться к Фанлиру.','Вернитесь к Фанлиру Серебряному Шипу, которого можно найти рядом с воротами Дарнаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия: Дарнас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Божественный колокол где-то в городе. Мы не хотим устраивать переполох, нам нужен только артефакт. Тебе придется найти способ незаметно проникнуть в город. Это значит – никаких полетов, никаких бешеных скачек и стычек.$b$bЯ помогу тебе, обеспечу незаметность. Еще я дам тебе этот маленький амулет, с помощью которого ты сможешь перенестись сюда, если попадешь в беду.$b$bСтупай, $n, отыщи Божественный колокол и пометь его, чтобы вместе с ним перенестись обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Божественный колокол.$b$bЕсли попадете в беду, воспользуйтесь амулетом Луносвета, чтобы вернуться к Фанлиру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фанлиру Серебряному Шипу, которого можно найти рядом с воротами Дарнаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32328,'Возвращение с победой','Этот портал рядом со мной перенесет тебя в Крепость Покорителей. Шагай в него, а я только замету следы, чтобы Праудмур не поняла, что мы в чем-то замешаны, и сразу за тобой.','Доложите о своих успехах Назгриму в Крепости Покорителей в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение с победой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот портал рядом со мной перенесет тебя в Крепость Покорителей. Шагай в него, а я только замету следы, чтобы Праудмур не поняла, что мы в чем-то замешаны, и сразу за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своих успехах Назгриму в Крепости Покорителей в Красарангских джунглях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32329,'Где результаты?','А, $p. Вождь поручил мне доставить тебя в Луносвет.$b$bОн обеспокоен тем, что изыскания Лор\'темара все еще не привели к желанному результату и надеется, что твой уникальный... опыт... общения с могу поможет достичь цели.$b$bКогда прибудешь в Луносвет, найди Лор\'темара и заставь его поторопиться с исследованиями.','Поговорите с Лор\'темаром Тероном в Луносвете.','Поговорите с Лор\'темаром Тероном в Луносвете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где результаты?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $p. Вождь поручил мне доставить тебя в Луносвет.$b$bОн обеспокоен тем, что изыскания Лор\'темара все еще не привели к желанному результату и надеется, что твой уникальный... опыт... общения с могу поможет достичь цели.$b$bКогда прибудешь в Луносвет, найди Лор\'темара и заставь его поторопиться с исследованиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лор\'темаром Тероном в Луносвете.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном в Луносвете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32330,'Что в коробке?','Помогите Этасу и Роммату провести эксперимент.','Страшно смотреть, как бездумно Гаррош обращается с моими сородичами. Боюсь даже представить, чем бы тут все закончилось, если бы не ты.','Поговорите с Лор\'темаром Тероном в Луносвете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что в коробке?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Этасу и Роммату провести эксперимент.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Страшно смотреть, как бездумно Гаррош обращается с моими сородичами. Боюсь даже представить, чем бы тут все закончилось, если бы не ты.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном в Луносвете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32331,'Кирин-Тор','Как я рад снова видеть тебя! Признаться, я опасался, что Джайна уже наизусть выучила мои дипломатические приемы, и я ничего не смогу ей противопоставить.$B$BЯ очень рассчитываю на твою помощь в улаживании этого конфликта!','Поговорите с Андуином Ринном в Лиловой гостиной, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кирин-Тор',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я рад снова видеть тебя! Признаться, я опасался, что Джайна уже наизусть выучила мои дипломатические приемы, и я ничего не смогу ей противопоставить.$B$BЯ очень рассчитываю на твою помощь в улаживании этого конфликта!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Лиловой гостиной, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32332,'Первая загадка: милосердие','Так ты $gразбудил:разбудила; Короля обезьян из-за какого-то молота? Хочешь молот, друг мой сладкий? Разгадай-ка три загадки!$b$bСлушай первую загадку: "В этом камне жизнь страдает,$b$bОт хозяев лик скрывает.$b$bЗа стеной сомкнулся круг, торопись-ка, друг, на юг.$b$bТы янтарь скорей найди, существо освободи."$b$bПринеси-ка мне в ответ, тот загадочный предмет.','Найдите предмет, который загадал Король обезьян.','А! Янтарь! Чистый и дикий. Никак, пришлось пролить кровь из-за него? Конечно, конечно…$B$BДикий янтарь – коварная штука. Многие погибли, стремясь его обрести.$B$BУ милосердия столько лиц, сколько в самой толстой книге страниц.','А, это ты, мое мудрое дитя. Где же мой янтарь?','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первая загадка: милосердие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты $gразбудил:разбудила; Короля обезьян из-за какого-то молота? Хочешь молот, друг мой сладкий? Разгадай-ка три загадки!$b$bСлушай первую загадку: "В этом камне жизнь страдает,$b$bОт хозяев лик скрывает.$b$bЗа стеной сомкнулся круг, торопись-ка, друг, на юг.$b$bТы янтарь скорей найди, существо освободи."$b$bПринеси-ка мне в ответ, тот загадочный предмет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите предмет, который загадал Король обезьян.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Янтарь! Чистый и дикий. Никак, пришлось пролить кровь из-за него? Конечно, конечно…$B$BДикий янтарь – коварная штука. Многие погибли, стремясь его обрести.$B$BУ милосердия столько лиц, сколько в самой толстой книге страниц.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, это ты, мое мудрое дитя. Где же мой янтарь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32333,'Вторая загадка: дружба','Хочешь остановить колокол? Сначала заполучи молот.$b$bХочешь молот? Сначала давай подружимся!$b$bХочешь подружиться? Сначала нам надо распить ритуальную кружку особого отвара.$b$bХочешь отвар? Отправляйся в Святилище Братства.$b$bХочешь отправиться в Святилище Братства? Отлично! Святилище в Нефритовом лесу к юго-западу от монастыря Тянь. Ударь в гонг и принеси Королю обезьян немного отвара.$b$bАх, да... не думай, что он тебе легко достанется.','Найдите металлический отвар.','Ах, металлический отвар! Им угощают друзей после славной битвы.$B$BМы со стариной Шаохао распили немало таких кружек. Ах, этот сладкий дым сражений и крепкое рукопожатие друга…','Отвар у тебя?','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторая загадка: дружба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь остановить колокол? Сначала заполучи молот.$b$bХочешь молот? Сначала давай подружимся!$b$bХочешь подружиться? Сначала нам надо распить ритуальную кружку особого отвара.$b$bХочешь отвар? Отправляйся в Святилище Братства.$b$bХочешь отправиться в Святилище Братства? Отлично! Святилище в Нефритовом лесу к юго-западу от монастыря Тянь. Ударь в гонг и принеси Королю обезьян немного отвара.$b$bАх, да... не думай, что он тебе легко достанется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите металлический отвар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, металлический отвар! Им угощают друзей после славной битвы.$B$BМы со стариной Шаохао распили немало таких кружек. Ах, этот сладкий дым сражений и крепкое рукопожатие друга…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отвар у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32334,'Третья загадка: сила','Победите соперника в Храме Белого Тигра.','Зачем упражняться в скупости? Зачем упражняться в глупости?$B$BТы просишь у короля артефакт огромной силы! Я должен быть уверен, что ты не трус. Ты можешь быть храбрым дукером, но перед могу многие пасовали!','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Третья загадка: сила',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите соперника в Храме Белого Тигра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зачем упражняться в скупости? Зачем упражняться в глупости?$B$BТы просишь у короля артефакт огромной силы! Я должен быть уверен, что ты не трус. Ты можешь быть храбрым дукером, но перед могу многие пасовали!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32335,'Величайшая проделка','Три загадки $gсмог:смогла; ты разгадать... Хорошо, хорошо. Король обезьян не выдает свои секреты кому угодно.$b$bТак вот, это была величайшая шутка, которую я провернул.$b$bХочешь, расскажу историю о молоте и обезьяне? Нет? Очень жаль, потому что тебе все равно придется меня выслушать!','Выслушайте историю Короля обезьян.','Поговорите с Андуином Ринном в Львином лагере в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Величайшая проделка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Три загадки $gсмог:смогла; ты разгадать... Хорошо, хорошо. Король обезьян не выдает свои секреты кому угодно.$b$bТак вот, это была величайшая шутка, которую я провернул.$b$bХочешь, расскажу историю о молоте и обезьяне? Нет? Очень жаль, потому что тебе все равно придется меня выслушать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте историю Короля обезьян.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Львином лагере в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32336,'Рукоятка','Жил-был вождь по имени Ингу-Ингу,$b$bС которым мы пили как-то в обнимку.$b$bОн выпил десять кружек кряду$b$bИ забрал рукоятку себе в награду.$b$bТак король рукоятку спрятал,$b$bА дети Инги пошли брат на брата.$b$bИх вождь сеет зло, убивает, калечит.$b$bСтупай в Унга-Ингу, тебя я там встречу.','Найдите рукоятку молота.','Артефакты не делают нас великими. Артефакты помогают нам стать собой. Хорошие становится лучше. Плохие становится хуже. А вождь Ингу-Ингу стал шнуропсее.','Ингу был хорошим хозеном. Ох, какие он вечеринки устраивал!','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рукоятка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жил-был вождь по имени Ингу-Ингу,$b$bС которым мы пили как-то в обнимку.$b$bОн выпил десять кружек кряду$b$bИ забрал рукоятку себе в награду.$b$bТак король рукоятку спрятал,$b$bА дети Инги пошли брат на брата.$b$bИх вождь сеет зло, убивает, калечит.$b$bСтупай в Унга-Ингу, тебя я там встречу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите рукоятку молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Артефакты не делают нас великими. Артефакты помогают нам стать собой. Хорошие становится лучше. Плохие становится хуже. А вождь Ингу-Ингу стал шнуропсее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ингу был хорошим хозеном. Ох, какие он вечеринки устраивал!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32337,'Боек молота','Король обезьян знает, где искать боек.$b$bЯ отдал его хозену, который давно уже ёк.$b$bВожди Куньцзэнь передавали боек от отца к сыну, пока однажды гну-синь Скиггит не вонзил им нож в спину. Теперь шнуропсы бойку воздают честь, потому что он был слишком велик и Скиггит не смог его съесть. За бойком ушел мой сыщик, от него не скроешься, он все сыщет. Давай-ка, дружище, беги и ты теперь. Найди его в горах к западу от Плодородных земель.','Найдите боек молота.','То, что гну-сини не понимают, они почитают, убивают или забывают.$B$BНадо послать им мою статую.','Боек у тебя?','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боек молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Король обезьян знает, где искать боек.$b$bЯ отдал его хозену, который давно уже ёк.$b$bВожди Куньцзэнь передавали боек от отца к сыну, пока однажды гну-синь Скиггит не вонзил им нож в спину. Теперь шнуропсы бойку воздают честь, потому что он был слишком велик и Скиггит не смог его съесть. За бойком ушел мой сыщик, от него не скроешься, он все сыщет. Давай-ка, дружище, беги и ты теперь. Найди его в горах к западу от Плодородных земель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите боек молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что гну-сини не понимают, они почитают, убивают или забывают.$B$BНадо послать им мою статую.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боек у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32338,'Гармоничная мазь','Легендами не рождаются, легендами становятся. В этой поговорке мудрость великая кроется.$b$bСколько веревке ни виться – всему приходит свой срок. Думай об этом, когда будешь сражаться с могу по прозвищу "Клинок".$b$bУ него ты найдешь гармоничную мазь, которая звенит, словно медь.$b$bПринеси ее королю, и мы заставим молот запеть!$b$bСтупай вдоль стены на север, не тая своего лица. А потом поверни налево, как дойдешь до ее конца.','Найдите гармоничную мазь.','Я-хууу!','Удивительно, как могу умудрились заполучить мазь.$B$BМного странного произошло с тех пор, как мир раскололся на части.','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.','Этот убийца могу пользуется гармоничной мазью, чтобы побеждать противников.','"Клинок"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гармоничная мазь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легендами не рождаются, легендами становятся. В этой поговорке мудрость великая кроется.$b$bСколько веревке ни виться – всему приходит свой срок. Думай об этом, когда будешь сражаться с могу по прозвищу "Клинок".$b$bУ него ты найдешь гармоничную мазь, которая звенит, словно медь.$b$bПринеси ее королю, и мы заставим молот запеть!$b$bСтупай вдоль стены на север, не тая своего лица. А потом поверни налево, как дойдешь до ее конца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите гармоничную мазь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я-хууу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удивительно, как могу умудрились заполучить мазь.$B$BМного странного произошло с тех пор, как мир раскололся на части.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Королем обезьян в Львином лагере в Красарангских джунглях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Этот убийца могу пользуется гармоничной мазью, чтобы побеждать противников.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','"Клинок"',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32339,'Воссоздание молота','А теперь – за работу! Соберем-ка молот!','Получите Молот гармонии.','Поговорите с Андуином Ринном в Львином лагере в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоздание молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь – за работу! Соберем-ка молот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите Молот гармонии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Львином лагере в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32340,'Разграбление Черного храма','Пока Акама и его солдаты разбираются с демонами, никто не помешает вам увести парочку реликвий...','Соберите все, до чего дотянутся руки, и доберитесь до конца Приюта Земных Наслаждений.','Вы собрали все, что смогли унести. Пора сматывать удочки, пока Акама не вернулся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбление Черного храма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Акама и его солдаты разбираются с демонами, никто не помешает вам увести парочку реликвий...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите все, до чего дотянутся руки, и доберитесь до конца Приюта Земных Наслаждений.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы собрали все, что смогли унести. Пора сматывать удочки, пока Акама не вернулся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (32341,'Демонстрация силы','Отряд Акамы окружили демоны, которых вы выпустили из Реликвария Душ.$B$BПокажите свою силу, спасите Акаму и его людей!','Убейте демонов, напавших на отряд Акамы в Залах Страданий.','Победите демонов до того, как воины Акамы погибнут.','Вернитесь к Акаме в Святилище Теней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонстрация силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отряд Акамы окружили демоны, которых вы выпустили из Реликвария Душ.$B$BПокажите свою силу, спасите Акаму и его людей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте демонов, напавших на отряд Акамы в Залах Страданий.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите демонов до того, как воины Акамы погибнут.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акаме в Святилище Теней.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32342,'Ловушка для духов','Мы обнаружили в руинах несколько могущественных артефактов могу. В этих артефактах заключены духи, которых, видимо, использовали в определенных обрядах или ритуалах призыва.\r\n\r\nМы никогда не встречали подобных артефактов, и их обязательно нужно исследовать. Это поможет нам продвинуться в изучении техники пленения духов, которой пользовались могу.\r\n\r\nОтправляйся туда и принеси мне несколько образцов для изучения.','Соберите 3 ловушки для духов.','О, да! Давай сюда, только осторожно.','Ловушки у тебя с собой?','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка для духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили в руинах несколько могущественных артефактов могу. В этих артефактах заключены духи, которых, видимо, использовали в определенных обрядах или ритуалах призыва.\r\n\r\nМы никогда не встречали подобных артефактов, и их обязательно нужно исследовать. Это поможет нам продвинуться в изучении техники пленения духов, которой пользовались могу.\r\n\r\nОтправляйся туда и принеси мне несколько образцов для изучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 ловушки для духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, да! Давай сюда, только осторожно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ловушки у тебя с собой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32343,'Защитники Огудея','Дилетанты из Альянса бездумно потревожили двух могущественных духов могу.\r\n\r\nИменно эти духи нам и нужны, |3-6($c). Уничтожь их и заполучи их эссенции. Так мы значительно продвинемся в изучении истории этих необычных руин.','Соберите эссенцию Мэн-до и эссенцию Гэнь-ли на Руинах Огудея.','Какие сокровища! Если нам повезет, духи вернутся, и мы сможем получить новые образцы эссенции для изучения.','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитники Огудея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дилетанты из Альянса бездумно потревожили двух могущественных духов могу.\r\n\r\nИменно эти духи нам и нужны, |3-6($c). Уничтожь их и заполучи их эссенции. Так мы значительно продвинемся в изучении истории этих необычных руин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите эссенцию Мэн-до и эссенцию Гэнь-ли на Руинах Огудея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие сокровища! Если нам повезет, духи вернутся, и мы сможем получить новые образцы эссенции для изучения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32344,'Это загадка','Мы обнаружили в шахтах некоторые… аномалии чародейского или духовного происхождения. Они мешают нам понять природу магии, использовавшейся в связующих душу ритуалах.\r\n\r\nЭти аномалии крайне нестабильны, но нам удалось вычленить магическую составляющую явлений, и один из наших магов настроил этот кристалл на поиск аналогичных колебаний.\r\n\r\nВнимательно следи за ним – по мере приближения к аномалии он начнет светиться все ярче и ярче. Как только приблизишься вплотную, используй кристалл, чтобы устранить ее.','Используйте чародейский кристалл, чтобы найти аномалию на Руинах Огудея.','А, да. Один из наших исследователей доложил, что аномалия устранена. Отличная работа!','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это загадка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили в шахтах некоторые… аномалии чародейского или духовного происхождения. Они мешают нам понять природу магии, использовавшейся в связующих душу ритуалах.\r\n\r\nЭти аномалии крайне нестабильны, но нам удалось вычленить магическую составляющую явлений, и один из наших магов настроил этот кристалл на поиск аналогичных колебаний.\r\n\r\nВнимательно следи за ним – по мере приближения к аномалии он начнет светиться все ярче и ярче. Как только приблизишься вплотную, используй кристалл, чтобы устранить ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте чародейский кристалл, чтобы найти аномалию на Руинах Огудея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, да. Один из наших исследователей доложил, что аномалия устранена. Отличная работа!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32345,'Мы не чудовища!','Освободите 14 беспокойных духов рабов.','Молодчина. Я знаю, по сравнению с целью нашего исследования твои достижения кажутся незначительными, но на самом деле это не так.','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы не чудовища!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 14 беспокойных духов рабов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодчина. Я знаю, по сравнению с целью нашего исследования твои достижения кажутся незначительными, но на самом деле это не так.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Келисом Солнечным Полетом на Руинах Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32346,'Я не боюсь призраков!','Послушай-ка, у нас тут проблемка, и старина Тротман нас вмиг вышвырнет отсюда, если мы ее не решим.\r\n\r\nПожалуйста, помоги нам!','Убейте 12 подвластных духам могу.','Отлично! Сейчас у нас все пойдет как по маслу!','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я не боюсь призраков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай-ка, у нас тут проблемка, и старина Тротман нас вмиг вышвырнет отсюда, если мы ее не решим.\r\n\r\nПожалуйста, помоги нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 подвластных духам могу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Сейчас у нас все пойдет как по маслу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32347,'Уведомление о выселении','Проклятые рыцари Реликвария проникли в руины. Они захватили нижнюю секцию и проводят магические ритуалы.\r\n\r\nНастало время вручить им уведомление о выселении в виде следа твоего ботинка на их задницах!','Убейте 10 членов Реликвария на Руинах Огудея.','Ха! Теперь они убегут в Луносвет, поджав хвосты!','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уведомление о выселении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые рыцари Реликвария проникли в руины. Они захватили нижнюю секцию и проводят магические ритуалы.\r\n\r\nНастало время вручить им уведомление о выселении в виде следа твоего ботинка на их задницах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 членов Реликвария на Руинах Огудея.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Теперь они убегут в Луносвет, поджав хвосты!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хильде Хорнсвоггл на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32348,'Нападем, пока враг слаб!','Альянс зря думает, что захватил эти руины. Напрасно они надеются на близлежащий боевой лагерь. \r\n\r\nПридется их разочаровать. Иди и убей несколько стражников. ','Убейте 12 воинов Львиного лагеря.','Отличный денек! Эти глупцы из Альянса получили по заслугам, и наши исследования идут полным ходом!','Вернитесь к Келису Солнечному Полету на Руины Огудея в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападем, пока враг слаб!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс зря думает, что захватил эти руины. Напрасно они надеются на близлежащий боевой лагерь. \r\n\r\nПридется их разочаровать. Иди и убей несколько стражников. ',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 воинов Львиного лагеря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный денек! Эти глупцы из Альянса получили по заслугам, и наши исследования идут полным ходом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келису Солнечному Полету на Руины Огудея в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32351,'Эхо грома','Здравствуй, |3-6(Охотник). Тебя прислали из Крепости Покорителей? Отлично, нам надо о многом поговорить.','Поговорите с верховным вождем Бейном Кровавым Копытом в Императорском торговом зале, что в Святилище Двух Лун в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эхо грома',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, |3-6(Охотник). Тебя прислали из Крепости Покорителей? Отлично, нам надо о многом поговорить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным вождем Бейном Кровавым Копытом в Императорском торговом зале, что в Святилище Двух Лун в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32352,'Надвигается буря','Если тебя прислал генерал Назгрим, значит, тебе можно доверять.$B$BПрибыв сюда, я обнаружил, что Гаррош... экспериментирует... с какой-то древней силой, источник которой он обнаружил где-то в горах на севере.$B$BОн полагает, что так называемые "ша" могут усилить нашу армию.$B$BК сожалению, пока что результаты его экспериментов говорят об обратном.$B$BСолдаты подвержены вспышкам неконтролируемой ярости. Я хочу, чтобы ты $gпоговорил:поговорила; с ними. Держи оружие наготове на случай, если тебе придется защищаться.','Бросьте вызов 6 пораженным ша рубакам.','Ты одолел моих защитников? Ну наконец-то у нас появился кто-то, кто может совладать со своими ненавистью и жестокостью! Побольше бы таких воинов, как ты.','Поговорите с Гаррошем Адским Криком в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надвигается буря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебя прислал генерал Назгрим, значит, тебе можно доверять.$B$BПрибыв сюда, я обнаружил, что Гаррош... экспериментирует... с какой-то древней силой, источник которой он обнаружил где-то в горах на севере.$B$BОн полагает, что так называемые "ша" могут усилить нашу армию.$B$BК сожалению, пока что результаты его экспериментов говорят об обратном.$B$BСолдаты подвержены вспышкам неконтролируемой ярости. Я хочу, чтобы ты $gпоговорил:поговорила; с ними. Держи оружие наготове на случай, если тебе придется защищаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте вызов 6 пораженным ша рубакам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты одолел моих защитников? Ну наконец-то у нас появился кто-то, кто может совладать со своими ненавистью и жестокостью! Побольше бы таких воинов, как ты.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаррошем Адским Криком в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32355,'Молот гармонии','Найдите Андуина в Гробнице Завоевателей. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы она доставила вас на место.','Рад, что тебе удалось добраться сюда, друг мой. Мне понадобится твоя помощь. Отец считает, что мне было бы лучше отсидеться в безопасной гавани, но я хорошо усвоил уроки Пандарии. Даже один человек, оказавшийся в нужном месте в нужное время, может сделать больше, чем величайшая из армий.','Поговорите с Андуином Ринном в Гробнице Завоевателей на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молот гармонии',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Андуина в Гробнице Завоевателей. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы она доставила вас на место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад, что тебе удалось добраться сюда, друг мой. Мне понадобится твоя помощь. Отец считает, что мне было бы лучше отсидеться в безопасной гавани, но я хорошо усвоил уроки Пандарии. Даже один человек, оказавшийся в нужном месте в нужное время, может сделать больше, чем величайшая из армий.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Гробнице Завоевателей на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32356,'Выслеживание: сбор посланников','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.','Проводите разведчиков, затем поговорите с Большим Лу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: сбор посланников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите разведчиков, затем поговорите с Большим Лу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32357,'Выслеживание: завершение события','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.','Проводите разведчиков, затем поговорите с Большим Лу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: завершение события',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите разведчиков, затем поговорите с Большим Лу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32358,'Сущность души') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность души',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32359,'Глаз наару','Сущность души превратилась в кристалл. Это тот самый артефакт, который пытались создать Канретад и Джубека, но вы все еще не знаете, куда они делись.$B$BНайдите Черного принца в таверне "В туманах" и узнайте у него, где их искать.','Принесите Око Бури Гневиону в таверну "В туманах".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаз наару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сущность души превратилась в кристалл. Это тот самый артефакт, который пытались создать Канретад и Джубека, но вы все еще не знаете, куда они делись.$B$BНайдите Черного принца в таверне "В туманах" и узнайте у него, где их искать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Око Бури Гневиону в таверну "В туманах".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32360,'В ожидании Мрачной Жатвы','$n, я никогда не слышал о Совете Мрачной Жатвы, но меня беспокоит, что они интересуются источником силы моего отца.$B$BУ меня есть кое-какие... знакомые, которые могут помочь выследить их, но большинство моих агентов оказались вовлечены в конфликт между Ордой и Альянсом в Красарангских джунглях. Я дам тебе знать, когда там станет поспокойнее.$B$BА пока можешь оставить реликвию Наару под моей защитой. Или возьми ее с собой, мне все равно. Только не пропадай.','Дождитесь, когда с вами свяжется Гневион.$B$B[Продолжение следует в обновлении 5.2.]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В ожидании Мрачной Жатвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я никогда не слышал о Совете Мрачной Жатвы, но меня беспокоит, что они интересуются источником силы моего отца.$B$BУ меня есть кое-какие... знакомые, которые могут помочь выследить их, но большинство моих агентов оказались вовлечены в конфликт между Ордой и Альянсом в Красарангских джунглях. Я дам тебе знать, когда там станет поспокойнее.$B$BА пока можешь оставить реликвию Наару под моей защитой. Или возьми ее с собой, мне все равно. Только не пропадай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, когда с вами свяжется Гневион.$B$B[Продолжение следует в обновлении 5.2.]',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32361,'Выслеживание: завершение события','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.','Проводите разведчиков, затем поговорите с Большим Лу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выслеживание: завершение события',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам с Салли пора. Если мы заметим следы Белой Пешки, доложим незамедлительно.$B$BАдмирал Тейлор еще не оправился от ран, так что, боюсь, командовать придется тебе. Пока нас не будет, постарайся узнать как можно больше у этих цзинь-юй. Я жду полного отчета к нашему возвращению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите разведчиков, затем поговорите с Большим Лу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32362,'Судьба Даларана','Джайна отказывается меня слушать. Отец надеялся, что я смогу оказать на нее влияние, но, похоже, она все еще видит во мне ребенка.$b$bА вот ты – герой Альянса, и к тебе она обязательно прислушается.$b$b$gНе мог:Не могла; бы ты попробовать убедить Джайну, что мы нуждаемся в ее помощи?','Поговорите с Джайной Праудмур и выслушайте ее рассказ.','Спасибо тебе за помощь, герой! Слова Джайны мудры. Надеюсь, ее вера в Похитителей Солнца укрепится.','Поговорите с Андуином Ринном в Лиловой гостиной, что в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Даларана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Джайна отказывается меня слушать. Отец надеялся, что я смогу оказать на нее влияние, но, похоже, она все еще видит во мне ребенка.$b$bА вот ты – герой Альянса, и к тебе она обязательно прислушается.$b$b$gНе мог:Не могла; бы ты попробовать убедить Джайну, что мы нуждаемся в ее помощи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джайной Праудмур и выслушайте ее рассказ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за помощь, герой! Слова Джайны мудры. Надеюсь, ее вера в Похитителей Солнца укрепится.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином Ринном в Лиловой гостиной, что в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32363,'Экспедиция к Кунь-Лай','Верховный вождь Кровавое Копыто передал тебе еще одно сообщение.$B$BПохоже, ты $gпроизвел:произвела; на него впечатление!$B$BОн сейчас следует за авангардом вождя на вершину Кунь-Лай, что на севере отсюда. Там они устроили передовую Гаррош\'ар, что к востоку от Пэй-Лэй.$B$BНе заставляй его ждать! Поговори с Так-Таком, он тебе поможет добраться до места.','Поговорите с Бейном Кровавым Копытом на Передовой Гаррош\'ар на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспедиция к Кунь-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный вождь Кровавое Копыто передал тебе еще одно сообщение.$B$BПохоже, ты $gпроизвел:произвела; на него впечатление!$B$BОн сейчас следует за авангардом вождя на вершину Кунь-Лай, что на севере отсюда. Там они устроили передовую Гаррош\'ар, что к востоку от Пэй-Лэй.$B$BНе заставляй его ждать! Поговори с Так-Таком, он тебе поможет добраться до места.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бейном Кровавым Копытом на Передовой Гаррош\'ар на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32364,'Лекарство пандаренов','Когда я был в долине, мне в руки попался древний пандаренский рецепт напитка Памяти. Кажется, этот напиток мог бы помочь вытянуть кое-какие детали из Шена Киена.$B$BНадеюсь, ты с пониманием отнесешься к тому, что за его ингредиентами придется отправиться тебе. Сам рецепт можно найти в книге рядом с моими пожитками.','Найдите рецепт напитка Памяти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство пандаренов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я был в долине, мне в руки попался древний пандаренский рецепт напитка Памяти. Кажется, этот напиток мог бы помочь вытянуть кое-какие детали из Шена Киена.$B$BНадеюсь, ты с пониманием отнесешься к тому, что за его ингредиентами придется отправиться тебе. Сам рецепт можно найти в книге рядом с моими пожитками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите рецепт напитка Памяти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32365,'Tracking Event: Epilogue Complete') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Event: Epilogue Complete',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32366,'Капельку огня','6 порций огненного вина Жу-Цзинь. Этот крепкий напиток помогает расслабиться и дарит приятные воспоминания.$B$B<Рядом есть еще одна заметка.>$B$B(Мне он подарил только чудовищное похмелье).','Соберите 6 порций огненного вина Жу-Цзинь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капельку огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','6 порций огненного вина Жу-Цзинь. Этот крепкий напиток помогает расслабиться и дарит приятные воспоминания.$B$B<Рядом есть еще одна заметка.>$B$B(Мне он подарил только чудовищное похмелье).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 порций огненного вина Жу-Цзинь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32367,'Немного яка','3 порции свежего молока яка. Способствует укреплению зубов и костей, а также бодрости духа. $B$B<Сбоку есть приписка знакомым почерком.>$B$B(Ну почему все эти проклятые яки выглядят одинаково?!)','Соберите 3 порции свежего молока яка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного яка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','3 порции свежего молока яка. Способствует укреплению зубов и костей, а также бодрости духа. $B$B<Сбоку есть приписка знакомым почерком.>$B$B(Ну почему все эти проклятые яки выглядят одинаково?!)',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 порции свежего молока яка.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32368,'Напиток Памяти','Напиток готов. Пей.','Выпейте напиток Памяти и узнайте о прошлом Шена Киена.','Расскажи, что ты видел?','Поговорите с Бейном Кровавое Копыто на Передовой Гаррош\'ар на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напиток Памяти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Напиток готов. Пей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте напиток Памяти и узнайте о прошлом Шена Киена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Расскажи, что ты видел?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бейном Кровавое Копыто на Передовой Гаррош\'ар на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32369,'Тайны прошлого') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны прошлого',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32370,'Экспедиция к Кунь-Лай','Слава Альянсу, |3-6($c). Мы продолжаем теснить Орду в Красарангских джунглях, но до окончательной победы еще далеко.$B$BПока мы здесь удерживаем линию фронта, тебе предстоит помочь нам в другой битве, в которой мы поразим противника в самое сердце.$B$BСекретный агент ШРУ Коннелли прислал донесение, в котором говорится, что авангардный отряд Орды движется по северным склонам горы Кунь-Лай.$B$BОтправляйся без промедления в указанное место, свяжись с агентом Коннелли и узнай, что происходит. А добраться тебе поможет Фенни.','Найдите агента Коннели на Базаре груммелей. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.','<Вы уже начинаете сомневаться, когда пандарен внезапно начинает говорить голосом Коннелли.>$B$BГде тебя носит, дружище! Я тебя уже заждался.$B$BЭти пандарены – отличные ребята, но с ними каши не сваришь.','Поговорите с агентом Коннели на Базаре груммелей, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экспедиция к Кунь-Лай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слава Альянсу, |3-6($c). Мы продолжаем теснить Орду в Красарангских джунглях, но до окончательной победы еще далеко.$B$BПока мы здесь удерживаем линию фронта, тебе предстоит помочь нам в другой битве, в которой мы поразим противника в самое сердце.$B$BСекретный агент ШРУ Коннелли прислал донесение, в котором говорится, что авангардный отряд Орды движется по северным склонам горы Кунь-Лай.$B$BОтправляйся без промедления в указанное место, свяжись с агентом Коннелли и узнай, что происходит. А добраться тебе поможет Фенни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите агента Коннели на Базаре груммелей. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы уже начинаете сомневаться, когда пандарен внезапно начинает говорить голосом Коннелли.>$B$BГде тебя носит, дружище! Я тебя уже заждался.$B$BЭти пандарены – отличные ребята, но с ними каши не сваришь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с агентом Коннели на Базаре груммелей, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32371,'Напиток Памяти','<Из передатчика доносится треск и статические помехи, через которые прорывается голос агента Коннелли.>$B$BТеперь, дружище, тебя ждет настоящее испытание.$B$BПрокрадись в самый центр лагеря и постарайся узнать что-нибудь важное.','Воспользуйтесь кор\'кронской маскировкой, чтобы проникнуть в лагерь. Затем выпейте напиток Памяти и узнайте прошлое Шена Киена.','Ты уже вернулся? Шустро же ты. И что тебе удалось узнать?','Вернитесь к агенту Коннелли на Базар груммелей, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напиток Памяти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Из передатчика доносится треск и статические помехи, через которые прорывается голос агента Коннелли.>$B$BТеперь, дружище, тебя ждет настоящее испытание.$B$BПрокрадись в самый центр лагеря и постарайся узнать что-нибудь важное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь кор\'кронской маскировкой, чтобы проникнуть в лагерь. Затем выпейте напиток Памяти и узнайте прошлое Шена Киена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уже вернулся? Шустро же ты. И что тебе удалось узнать?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к агенту Коннелли на Базар груммелей, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32372,'Освобождение','Кор\'кронцы – отличные солдаты и верно служат вождю. Их присутствие означает, что Гаррош боится восстания.$b$bВол\'джин и его тролли такие же члены Орды, как и орки. $b$bМы должны освободить троллей от оккупации. Мне больно говорить это, но тебе придется пролить кровь кор\'кронцев, чтобы тролли могли вернуть свой город. Когда все будет кончено, приходи в Крепость Черного Копья, и мы бросим вызов их предводителю.','Убейте 10 кор\'кронских надзирателей, 5 кор\'кронских поработителей и Гул\'тара Поработителя.','Эти орки изменились. Орда тоже изменилась. Неужели мне предстоит убивать собственных орков до тех пор, пока Орда вновь не станет "моей"? Имею ли я право заставлять всю Орду стать прежней?$B$BМы живем в непростые времена. Однако сейчас мне нужно позаботиться о народе Вол\'джина.','Поговорите с Траллом в крепости Черного Копья на островах Эха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кор\'кронцы – отличные солдаты и верно служат вождю. Их присутствие означает, что Гаррош боится восстания.$b$bВол\'джин и его тролли такие же члены Орды, как и орки. $b$bМы должны освободить троллей от оккупации. Мне больно говорить это, но тебе придется пролить кровь кор\'кронцев, чтобы тролли могли вернуть свой город. Когда все будет кончено, приходи в Крепость Черного Копья, и мы бросим вызов их предводителю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 кор\'кронских надзирателей, 5 кор\'кронских поработителей и Гул\'тара Поработителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти орки изменились. Орда тоже изменилась. Неужели мне предстоит убивать собственных орков до тех пор, пока Орда вновь не станет "моей"? Имею ли я право заставлять всю Орду стать прежней?$B$BМы живем в непростые времена. Однако сейчас мне нужно позаботиться о народе Вол\'джина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Траллом в крепости Черного Копья на островах Эха.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32373,'Мерило для предводителя','Пандаренская кампания вошла в новую фазу. К берегам континента пристали самые мощные корабли военно-морского флота Альянса. Гаррош Адский Крик толкает Орду в пламя войны, ваш король пытается сдержать его напор... Признаться, Вариан Ринн все еще представляет для меня загадку. У тебя есть минутка? Давай поговорим немного о вашем предводителе.','Поговорите с Гневионом в таверне "В туманах".','Интересно, как король Ринн проявит себя в этой ситуации.$B$BНо еще больше я хочу знать, на что ты способен. Давай это выясним…','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерило для предводителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандаренская кампания вошла в новую фазу. К берегам континента пристали самые мощные корабли военно-морского флота Альянса. Гаррош Адский Крик толкает Орду в пламя войны, ваш король пытается сдержать его напор... Признаться, Вариан Ринн все еще представляет для меня загадку. У тебя есть минутка? Давай поговорим немного о вашем предводителе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом в таверне "В туманах".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно, как король Ринн проявит себя в этой ситуации.$B$BНо еще больше я хочу знать, на что ты способен. Давай это выясним…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32375,'Щепотку этого','100 свежих пуговичных грибов. Растут во влажных и сырых местах. $B$B<На полях страницы есть рукописная заметка.>$B$BНе все грибы полезны для здоровья! Они могут также вызывать серьезные отравления, лихорадку, галлюцинации и заворот кишок. Не забудь: собирай только съедобные дикорастущие грибы!)','Соберите 100 пуговичных грибов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щепотку этого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','100 свежих пуговичных грибов. Растут во влажных и сырых местах. $B$B<На полях страницы есть рукописная заметка.>$B$BНе все грибы полезны для здоровья! Они могут также вызывать серьезные отравления, лихорадку, галлюцинации и заворот кишок. Не забудь: собирай только съедобные дикорастущие грибы!)',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 100 пуговичных грибов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32376,'В долину!','Ах, вот и ты.$B$BПрости, мне следовало написать более подробную записку, но Гаррош в последнее время очень нами недоволен. Боюсь, его поспешные действия могут сорвать всю операцию.','Встретьтесь с вашим "другом из Луносвета" в Долине Императоров, что на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В долину!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, вот и ты.$B$BПрости, мне следовало написать более подробную записку, но Гаррош в последнее время очень нами недоволен. Боюсь, его поспешные действия могут сорвать всю операцию.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с вашим "другом из Луносвета" в Долине Императоров, что на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (32377,'Орки в наших рядах','Найдите кор\'кронский шлем, кор\'кронские доспехи и кор\'кронские сапоги и сделайте из них кор\'кронскую маскировку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орки в наших рядах',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кор\'кронский шлем, кор\'кронские доспехи и кор\'кронские сапоги и сделайте из них кор\'кронскую маскировку.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32378,'Расчистить путь','Убейте 10 могу клана Корун.','Отлично. Пора двигаться дальше.','Вернитесь к Лор\'темару Терону в Долину Императоров на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расчистить путь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 могу клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Пора двигаться дальше.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону в Долину Императоров на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32379,'Наследие клана Корун','Найдите документ "Наследие клана Корун" в Долине Императоров, а также "Приказы клана Корун" и запечатанный артефакт Корун у могу клана Корун.','Отлично, отлично. Над этим стоит поразмышлять… $B$BЯ отдам эти документы Реликварию на изучение. Возможно, нам удастся раскрыть секрет этих могу.','Вернитесь к Лор\'темару Терону в Долину Императоров на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие клана Корун',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите документ "Наследие клана Корун" в Долине Императоров, а также "Приказы клана Корун" и запечатанный артефакт Корун у могу клана Корун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично. Над этим стоит поразмышлять… $B$BЯ отдам эти документы Реликварию на изучение. Возможно, нам удастся раскрыть секрет этих могу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону в Долину Императоров на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32380,'Он лучший среди нас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он лучший среди нас',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32381,'Поймать шпиона','Я могла бы сказать тебе, кто такой Коннелли, но это было бы слишком просто! Если хочешь поймать шпиона, думай $gсам:сама; как шпион. $b$bДля начала тебе придется пройти испытание.$b$bНастоящий шпион всегда обращает внимание на мельчайшие детали, которые могут многое сказать о человеке.$b$bЯ дам тебе напиток, который надо будет кое-кому доставить, и скажу тебе только одну отличительную черту этого человека. Об остальном тебе придется догадаться $gсамому:самой;.$b$bБудь $gосторожен:осторожна; – посетители не любят, когда их заказы путают!','Доставьте коктейли "Розовый суслик", "Дынный сюрприз могу" и "Ржавый кинжал" нужным посетителям.','Поговорите с барменшей Таунсли в бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать шпиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могла бы сказать тебе, кто такой Коннелли, но это было бы слишком просто! Если хочешь поймать шпиона, думай $gсам:сама; как шпион. $b$bДля начала тебе придется пройти испытание.$b$bНастоящий шпион всегда обращает внимание на мельчайшие детали, которые могут многое сказать о человеке.$b$bЯ дам тебе напиток, который надо будет кое-кому доставить, и скажу тебе только одну отличительную черту этого человека. Об остальном тебе придется догадаться $gсамому:самой;.$b$bБудь $gосторожен:осторожна; – посетители не любят, когда их заказы путают!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте коктейли "Розовый суслик", "Дынный сюрприз могу" и "Ржавый кинжал" нужным посетителям.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с барменшей Таунсли в бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32382,'Он под прикрытием','Агенту Коннелли удалось проникнуть в лагерь Гарроша в Кунь-Лай! Он сейчас среди солдат, следит за каждым шагом вождя.$b$bОн просил, чтобы я послал именно тебя для сбора важных разведданных.$b$bСмотри, он достал для тебя маскировку. Не забудь надеть ее перед тем, как приблизишься к лагерю! Я не сомневаюсь, что его хорошо охраняют.$b$bТолько не спрашивай, как его искать. Он говорил, у тебя настолько острый глаз, что ты без труда его узнаешь.','Ты как раз вовремя. Судя по собранным разведданным, Гаррош наткнулся на след какой-то могущественной древней реликвии могу.$B$BЕсли мы сможем понять, за чем он охотится, то нам, возможно, удастся ему помешать.$B$BНадо действовать быстро!','Поговорите с Коннели в огненном лагере Батаар, что на вершине Кунь-Лай .') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он под прикрытием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Агенту Коннелли удалось проникнуть в лагерь Гарроша в Кунь-Лай! Он сейчас среди солдат, следит за каждым шагом вождя.$b$bОн просил, чтобы я послал именно тебя для сбора важных разведданных.$b$bСмотри, он достал для тебя маскировку. Не забудь надеть ее перед тем, как приблизишься к лагерю! Я не сомневаюсь, что его хорошо охраняют.$b$bТолько не спрашивай, как его искать. Он говорил, у тебя настолько острый глаз, что ты без труда его узнаешь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя. Судя по собранным разведданным, Гаррош наткнулся на след какой-то могущественной древней реликвии могу.$B$BЕсли мы сможем понять, за чем он охотится, то нам, возможно, удастся ему помешать.$B$BНадо действовать быстро!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Коннели в огненном лагере Батаар, что на вершине Кунь-Лай .',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32383,'Жучки повсюду','Мне удалось поставить несколько жучков вокруг лагеря, но чем их будет больше – тем лучше.$b$bЯ замаскировал их под статуи, и они прекрасно сливаются с окружающей обстановкой$b$bТвоя маскировка позволит тебе спокойно разгуливать по лагерю, только не приближайся к собаке и не попадайся на глаза Гаррошу! Он и Нэро сразу тебя раскусят.$b$bУчти, если тебя поймают, я не смогу помочь — я не могу рисковать выполнением задания.','Поставьте тщательно замаскированные жучки в большом шатре, возле малых шатров и возле припасов.','Молодец! Никогда нельзя недооценивать маленьких людей.','Вернитесь к братцу Доброзубу в Огненный лагерь Батаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жучки повсюду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось поставить несколько жучков вокруг лагеря, но чем их будет больше – тем лучше.$b$bЯ замаскировал их под статуи, и они прекрасно сливаются с окружающей обстановкой$b$bТвоя маскировка позволит тебе спокойно разгуливать по лагерю, только не приближайся к собаке и не попадайся на глаза Гаррошу! Он и Нэро сразу тебя раскусят.$b$bУчти, если тебя поймают, я не смогу помочь — я не могу рисковать выполнением задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поставьте тщательно замаскированные жучки в большом шатре, возле малых шатров и возле припасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! Никогда нельзя недооценивать маленьких людей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к братцу Доброзубу в Огненный лагерь Батаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32384,'Захват предводителя','Настало время сделать ответный ход. Ступай к Гробнице Теней, измотай его и возьми в плен.\r\n\r\nЯ буду ждать здесь на случай, если появится Гаррош, и постараюсь задержать его, чтобы награда досталась нам и он в ярости не уничтожил ее.\r\n\r\nТоропись!','Надо же, мы все-таки захватили его. Только что нам теперь делать с ним? Пожалуй, я свяжусь с предводителями наших союзников и спрошу у них совета. Не уверен, что без из помощи нам удастся выбить хоть слово из этого могу.','Поговорите с Лор\'темаром Тероном в Долине Императоров на вершине Кунь-Лай.','Это предводитель клана Корун! Его надо взять живым!','Шен Киен') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват предводителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время сделать ответный ход. Ступай к Гробнице Теней, измотай его и возьми в плен.\r\n\r\nЯ буду ждать здесь на случай, если появится Гаррош, и постараюсь задержать его, чтобы награда досталась нам и он в ярости не уничтожил ее.\r\n\r\nТоропись!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо же, мы все-таки захватили его. Только что нам теперь делать с ним? Пожалуй, я свяжусь с предводителями наших союзников и спрошу у них совета. Не уверен, что без из помощи нам удастся выбить хоть слово из этого могу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном в Долине Императоров на вершине Кунь-Лай.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Это предводитель клана Корун! Его надо взять живым!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Шен Киен',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32388,'Смена командования','Убейте полководца Кровавого Эфеса в Крепости Покорителей в Красарангских джунглях. Вам потребуется группа.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена командования',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте полководца Кровавого Эфеса в Крепости Покорителей в Красарангских джунглях. Вам потребуется группа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32389,'Львиный рык','Это мировая война, $n. Она прокатилась во всему Калимдору и Восточным королевствам и, наконец, пришла в Пандарию. Ты уже $gотличился:отличилась; на поле боя? Я хочу увидеть это собственными глазами.$b$bЖду твоих донесений с линии фронта.','Выиграйте битвы за храм Котмогу и Сверкающие копи.','<Гневион жадно выслушивает ваш рассказ о подвигах на поле боя, и его глаза то и дело вспыхивают красным огнем.>$B$BНу надо же… невероятно! Только в пылу битвы можно различить истинный дух воина.$B$BТы и твой Альянс не разочаровали меня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Львиный рык',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это мировая война, $n. Она прокатилась во всему Калимдору и Восточным королевствам и, наконец, пришла в Пандарию. Ты уже $gотличился:отличилась; на поле боя? Я хочу увидеть это собственными глазами.$b$bЖду твоих донесений с линии фронта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битвы за храм Котмогу и Сверкающие копи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гневион жадно выслушивает ваш рассказ о подвигах на поле боя, и его глаза то и дело вспыхивают красным огнем.>$B$BНу надо же… невероятно! Только в пылу битвы можно различить истинный дух воина.$B$BТы и твой Альянс не разочаровали меня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32390,'Зов предводителя','Твоими глазами я видел битвы на побережье и эпические сражения по всему миру. Ты мой самый терпеливый... и самый полезный агент.$b$bЯ присматривался и к твоему королю. Хочешь знать, что я увидел в нем?','Поговорите с Гневионом.','<В резном, выложенном шелком сундучке находится странный предмет. Похоже, с его помощью можно дополнительно улучшить пораженное ша оружие. Вид пустого гнезда вызывает в вас беспокойство. Оно похоже на бездонную глазницу, смотрящую на вас с осуждением...>','Выберите награду, открыв сундук Гневиона в таверне "В туманах".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов предводителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоими глазами я видел битвы на побережье и эпические сражения по всему миру. Ты мой самый терпеливый... и самый полезный агент.$b$bЯ присматривался и к твоему королю. Хочешь знать, что я увидел в нем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В резном, выложенном шелком сундучке находится странный предмет. Похоже, с его помощью можно дополнительно улучшить пораженное ша оружие. Вид пустого гнезда вызывает в вас беспокойство. Оно похоже на бездонную глазницу, смотрящую на вас с осуждением...>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выберите награду, открыв сундук Гневиона в таверне "В туманах".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32391,'Руины клана Корун','Гаррош послал сотни всадников на северное побережье вершины Кунь-лай в поисках склепа могу, подобного тому, что ты $gвидел:видела; в воспоминаниях Шена Киена.$B$BИ одному из всадников удалось найти место, где покоится Божественный колокол. Гаррош отправил за ним мастера клинка Иши.$B$BСтупай, помоги ему защищать артефакт. Убей любого, кто осмелится на него посягнуть!$B$BПоговори с Так-Таком, он поможет тебе добраться до места.','Найдите Иши на Руинах клана Корун. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.','Альянс опередил нас! Как это возможно?','Поговорите с Иши в руинах клана Корун на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины клана Корун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гаррош послал сотни всадников на северное побережье вершины Кунь-лай в поисках склепа могу, подобного тому, что ты $gвидел:видела; в воспоминаниях Шена Киена.$B$BИ одному из всадников удалось найти место, где покоится Божественный колокол. Гаррош отправил за ним мастера клинка Иши.$B$BСтупай, помоги ему защищать артефакт. Убей любого, кто осмелится на него посягнуть!$B$BПоговори с Так-Таком, он поможет тебе добраться до места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Иши на Руинах клана Корун. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альянс опередил нас! Как это возможно?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Иши в руинах клана Корун на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32392,'Божественный колокол','Если Альянс считает, что они могут увести Божественный колокол у нас из-под носа, они ошибаются! Мы уже загнали их в ловушку – в склепы, что под нами.$b$bОни заплатят жизнью за то, что осмелились бросить нам вызов.$b$bИди со мной, |3-6($c). Мы объясним им всю глубину их заблуждений.','Убейте Саранью Небесную Глефу.','Значит, Дарнас?$B$BДолжно быть, Альянс записал эту победу на свой счет. Хорошо… чем выше их самомнение, тем легче будет увести приз прямо у них из-под носа.','Поговорите с Иши в руинах клана Корун на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Божественный колокол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если Альянс считает, что они могут увести Божественный колокол у нас из-под носа, они ошибаются! Мы уже загнали их в ловушку – в склепы, что под нами.$b$bОни заплатят жизнью за то, что осмелились бросить нам вызов.$b$bИди со мной, |3-6($c). Мы объясним им всю глубину их заблуждений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Саранью Небесную Глефу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Дарнас?$B$BДолжно быть, Альянс записал эту победу на свой счет. Хорошо… чем выше их самомнение, тем легче будет увести приз прямо у них из-под носа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Иши в руинах клана Корун на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32393,'Руины клана Корун','Настало время сделать решительный шаг, $n.$b$bТеперь, когда мы знаем точное местонахождение Божественного колокола, мы сможем отправить отряд наших лучших бойцов, чтобы они подняли артефакт на поверхность. $b$bЭкспедицию возглавит Саранья Небесная Глефа. Присоединись к ее отряду на северных склонах горы Кунь-Лай и приложи все усилия, чтобы наши старания увенчались успехом.$b$bУдачи тебе, |3-6($c). Полагаю, мне не стоит напоминать, насколько важна наша миссия.$B$BПоговори с Фенни, она знает, как туда добраться.','Найдите Саранью Небесную Глефу на Руинах клана Корун. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.','Мы взорвали двери несколько секунд назад. Ты как раз вовремя, поможешь нам с колоколом!','Поговорите с Сараньей Небесной Глефой в руинах клана Корун на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины клана Корун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время сделать решительный шаг, $n.$b$bТеперь, когда мы знаем точное местонахождение Божественного колокола, мы сможем отправить отряд наших лучших бойцов, чтобы они подняли артефакт на поверхность. $b$bЭкспедицию возглавит Саранья Небесная Глефа. Присоединись к ее отряду на северных склонах горы Кунь-Лай и приложи все усилия, чтобы наши старания увенчались успехом.$b$bУдачи тебе, |3-6($c). Полагаю, мне не стоит напоминать, насколько важна наша миссия.$B$BПоговори с Фенни, она знает, как туда добраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Саранью Небесную Глефу на Руинах клана Корун. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы взорвали двери несколько секунд назад. Ты как раз вовремя, поможешь нам с колоколом!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сараньей Небесной Глефой в руинах клана Корун на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32394,'Божественный колокол','Неизвестно, что ждет нас впереди, поэтому я лично возглавлю поисковую группу.$b$bЕсли донесения верны, могу клана Корун спрятали Божественный колокол прямо под нами.$b$bУ меня есть предчувствие, что столь могущественный артефакт должен хорошо охраняться.$b$b$c, твоя задача – защищать меня. Дай знать, когда будешь $gготов:готова;.','Убейте ткача ужаса Аварту и найдите Божественный колокол.','Поговорите с Сараньей Небесной Глефой в руинах клана Корун на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Божественный колокол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неизвестно, что ждет нас впереди, поэтому я лично возглавлю поисковую группу.$b$bЕсли донесения верны, могу клана Корун спрятали Божественный колокол прямо под нами.$b$bУ меня есть предчувствие, что столь могущественный артефакт должен хорошо охраняться.$b$b$c, твоя задача – защищать меня. Дай знать, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ткача ужаса Аварту и найдите Божественный колокол.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сараньей Небесной Глефой в руинах клана Корун на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32395,'Tracking Event: Saw Avartu') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Event: Saw Avartu',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32396,'Uncompletable Binding Quest [DND]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Uncompletable Binding Quest [DND]',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32397,'Он даже не заметит','Я заметил, что Гаррош и эльф крови из Реликвария вечно таскают с собой какой-то дневник.$b$bОни с ним почти не расстаются. Могу поспорить, там что-то очень важное. Я и подумал – может быть, тебе удастся стянуть его со стола, если мы устроим в лагере переполох?$b$bМы устроим переполох с помощью этих яков. Огрей одного из них кнутом, и они сделают все остальное.$b$bПриготовься действовать быстро!','Создайте переполох в лагере и украдите потрепанный дневник.','Фух! Ты едва успел унести ноги. Не то, чтобы я в тебе сомневался… Ладно, давай посмотрим, что там, в дневнике.','Что тебе удалось обнаружить?','Вернитесь к братцу Доброзубу в Огненный лагерь Батаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он даже не заметит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я заметил, что Гаррош и эльф крови из Реликвария вечно таскают с собой какой-то дневник.$b$bОни с ним почти не расстаются. Могу поспорить, там что-то очень важное. Я и подумал – может быть, тебе удастся стянуть его со стола, если мы устроим в лагере переполох?$b$bМы устроим переполох с помощью этих яков. Огрей одного из них кнутом, и они сделают все остальное.$b$bПриготовься действовать быстро!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте переполох в лагере и украдите потрепанный дневник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фух! Ты едва успел унести ноги. Не то, чтобы я в тебе сомневался… Ладно, давай посмотрим, что там, в дневнике.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось обнаружить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к братцу Доброзубу в Огненный лагерь Батаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32398,'Глас колокола','Твои усилия не прошли даром, |3-6($c).$B$BСегодня вождь Гаррош собирает самых прославленных защитников Орды на вершине Кунь-Лай, чтобы они услышали звон Божественного колокола.$B$BРазумеется, ты $gзаслужил:заслужила; право присутствовать при этом историческом событии.$B$BСтупай. Сегодня занимается заря новой эры Орды. Пусть Так-Так поможет тебе как можно скорее добраться до места.','Найдите Малкорока в Крыле императора. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.','Поговорите с Малкороком в Крыле императора на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глас колокола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои усилия не прошли даром, |3-6($c).$B$BСегодня вождь Гаррош собирает самых прославленных защитников Орды на вершине Кунь-Лай, чтобы они услышали звон Божественного колокола.$B$BРазумеется, ты $gзаслужил:заслужила; право присутствовать при этом историческом событии.$B$BСтупай. Сегодня занимается заря новой эры Орды. Пусть Так-Так поможет тебе как можно скорее добраться до места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Малкорока в Крыле императора. Поговорите с Так-Таком в Крепости Покорителей, чтобы добраться туда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Малкороком в Крыле императора на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32399,'Дыхание непроглядной тьмы','Время пришло, $n. Мы прошли долгий путь, и наконец наши усилия были вознаграждены.$B$BСегодня наш вождь Гаррош Адский Крик изменит историю всех народов.$B$BСегодня мы узрим становление новой Орды – Орды Гарроша!$B$BПозаботься, чтобы никто не прервал церемонию.','Услышьте звон Божественного колокола.','Они уничтожили Божественный колокол, но взамен я отнял жизнь проклятому отпрыску Альянса!$B$BМой отец мог бы гордиться мной.$B$BПобеда досталась нам дорогой ценой, но это нас не остановит. Мы найдем другой способ сокрушить врагов и принести победу Орде!','Поговорите с Гаррошем в Крыле императора на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дыхание непроглядной тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n. Мы прошли долгий путь, и наконец наши усилия были вознаграждены.$B$BСегодня наш вождь Гаррош Адский Крик изменит историю всех народов.$B$BСегодня мы узрим становление новой Орды – Орды Гарроша!$B$BПозаботься, чтобы никто не прервал церемонию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Услышьте звон Божественного колокола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они уничтожили Божественный колокол, но взамен я отнял жизнь проклятому отпрыску Альянса!$B$BМой отец мог бы гордиться мной.$B$BПобеда досталась нам дорогой ценой, но это нас не остановит. Мы найдем другой способ сокрушить врагов и принести победу Орде!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаррошем в Крыле императора на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32400,'Глас колокола','Войска Орды стекаются к Крылу императора на вершине горы Кунь-Лай. $B$BТам находится древний храм могу, источник невообразимой силы. Это может значить только одно – Гаррош намеревается пробить в Божественный колокол... а Андуин и Молот гармонии пропали.$B$BМогу поклясться, этот глупый мальчишка отправился на север. У меня нет времени собирать элитный отряд на его поиски. Тебе придется отправиться туда $gсамому:самой; и остановить его.$B$BФенни доставит тебя на место.','Найдите Андуина в Крыле императора. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.','Поговорите с Андуином в Крыле императора на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глас колокола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Орды стекаются к Крылу императора на вершине горы Кунь-Лай. $B$BТам находится древний храм могу, источник невообразимой силы. Это может значить только одно – Гаррош намеревается пробить в Божественный колокол... а Андуин и Молот гармонии пропали.$B$BМогу поклясться, этот глупый мальчишка отправился на север. У меня нет времени собирать элитный отряд на его поиски. Тебе придется отправиться туда $gсамому:самой; и остановить его.$B$BФенни доставит тебя на место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Андуина в Крыле императора. Поговорите с Фенни Хорнсвоггл в Львином лагере, чтобы добраться туда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином в Крыле императора на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32401,'Дыхание непроглядной тьмы','Гаррош в любой момент может прозвонить в колокол. У нас нет времени дожидаться, когда войска отца доберутся сюда! Это единственный шанс остановить вождя.$B$BЯ попытаюсь воззвать к его благоразумию прежде, чем пущу в ход Молот гармонии.$B$BВыступаем по твоему сигналу, $n. Я буду прямо за тобой.','Убейте Иши и уничтожьте Божественный колокол.','<Андуин похож на сломанную куклу. Он лежит неподвижно, как камень, и только ветер развевает его золотистые волосы. >$B$B<Вы сидите рядом, не в силах подняться, и холод пробирается к вашему сердцу. Колокол уничтожен, но воцарившаяся тишина оглушает.>$B$B<Внезапно вам кажется, что принц слегка пошевелил рукой. Вы наклоняетесь и видите – он дышит! Андуин на грани смерти, но он жив! Он жив!>','Поговорите с Андуином в Крыле императора на вершине Кунь-Лай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дыхание непроглядной тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гаррош в любой момент может прозвонить в колокол. У нас нет времени дожидаться, когда войска отца доберутся сюда! Это единственный шанс остановить вождя.$B$BЯ попытаюсь воззвать к его благоразумию прежде, чем пущу в ход Молот гармонии.$B$BВыступаем по твоему сигналу, $n. Я буду прямо за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Иши и уничтожьте Божественный колокол.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Андуин похож на сломанную куклу. Он лежит неподвижно, как камень, и только ветер развевает его золотистые волосы. >$B$B<Вы сидите рядом, не в силах подняться, и холод пробирается к вашему сердцу. Колокол уничтожен, но воцарившаяся тишина оглушает.>$B$B<Внезапно вам кажется, что принц слегка пошевелил рукой. Вы наклоняетесь и видите – он дышит! Андуин на грани смерти, но он жив! Он жив!>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Андуином в Крыле императора на вершине Кунь-Лай.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32402,'Ситуация в Даларане','Ночные эльфы узнали, что Божественный колокол украден. Этого мы ожидали.$b$bОднако они также поняли, что якобы "нейтральные" Похитители Солнца были в этом замешаны. И вот это уже нехорошо.$b$bТебе надо срочно отправиться в Даларан. Поговори с Кромтар, пусть выделит тебе птичку попроворнее. Когда прибудешь на место, разыщи верховного магистра Роммата.','Поговорите с Кромтар и отправьтесь в Даларан.','Поговорите с верховным магистром Ромматом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ситуация в Даларане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ночные эльфы узнали, что Божественный колокол украден. Этого мы ожидали.$b$bОднако они также поняли, что якобы "нейтральные" Похитители Солнца были в этом замешаны. И вот это уже нехорошо.$b$bТебе надо срочно отправиться в Даларан. Поговори с Кромтар, пусть выделит тебе птичку попроворнее. Когда прибудешь на место, разыщи верховного магистра Роммата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кромтар и отправьтесь в Даларан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным магистром Ромматом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32403,'Все начинается в стоках','Спасите 9 горожан – Похитителей Солнца.','Давай продолжать в том же духе.','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все начинается в стоках',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 9 горожан – Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай продолжать в том же духе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32404,'Жестокость на арене','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жестокость на арене',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32405,'Каждый Похититель Солнца, изгнанный Джайной из города, усилит армию Орды. Он будет сражаться за нас.$b$bЯ соберу под наши знамена самых сильных эльфов. Я уже знаю, что на тебя можно положиться, поэтому не сомневаюсь, что ты сможешь стереть с лица земли эту тварь на черном рынке.$b$bКогда разберешься с ним, возвращайся ко мне и приготовься подняться наверх.','Убейте Сорина Мага.','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый Похититель Солнца, изгнанный Джайной из города, усилит армию Орды. Он будет сражаться за нас.$b$bЯ соберу под наши знамена самых сильных эльфов. Я уже знаю, что на тебя можно положиться, поэтому не сомневаюсь, что ты сможешь стереть с лица земли эту тварь на черном рынке.$b$bКогда разберешься с ним, возвращайся ко мне и приготовься подняться наверх.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сорина Мага.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32406,'Элемент неожиданности','Если мы хотим выжить на поверхности, нам потребуется какая-то база.$b$bЯ попробую захватить центр города. Знаю, это рискованно, но вряд ли Джайна и Серебряный союз ожидают, что мы можем напасть на них.$b$bДержись рядом со мной, $n.','Проследуйте за верховным магистром Ромматом в центр Даларана.','Давай действовать быстро.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элемент неожиданности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хотим выжить на поверхности, нам потребуется какая-то база.$b$bЯ попробую захватить центр города. Знаю, это рискованно, но вряд ли Джайна и Серебряный союз ожидают, что мы можем напасть на них.$b$bДержись рядом со мной, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследуйте за верховным магистром Ромматом в центр Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай действовать быстро.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32407,'[NYI] Magus Commerce Exchange') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NYI] Magus Commerce Exchange',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32408,'Я получил сведения из надежных источников, что верховного мага Этаса Похитителя Солнца держат в Серебряном Анклаве, оплоте Серебряного Союза. Его захватила чародей Ратаэлла.$b$bБольшинство агентов Союза сейчас заняты истреблением Похитителей Солнца, что дает нам шанс освободить его. Убей Ратаэллу и вытащи Этаса из темницы.','Убейте чародея Ратаэллу.','Мы продолжим спасать Похитителей Солнца. Возможно, это поможет нам определить местонахождение Этаса.','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я получил сведения из надежных источников, что верховного мага Этаса Похитителя Солнца держат в Серебряном Анклаве, оплоте Серебряного Союза. Его захватила чародей Ратаэлла.$b$bБольшинство агентов Союза сейчас заняты истреблением Похитителей Солнца, что дает нам шанс освободить его. Убей Ратаэллу и вытащи Этаса из темницы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Ратаэллу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы продолжим спасать Похитителей Солнца. Возможно, это поможет нам определить местонахождение Этаса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32409,'Подлинный облик Кирин-Тора','Кирин-Тор, наконец, сбросил маски и перестал притворяться, будто занимает нейтральную позицию в конфликте. До меня дошли слухи, что возле памятника Антонидасу были незаметно размещены войска Альянса по прямому приказу Джайны.$b$bКонечно, там нет Похитителей Солнца, но столь явное попустительство со стороны Кирин-Тора меня просто бесит!$b$bНе желаешь ли прогуляться до памятника, $n? Развеешься, воздухом подышишь... да заодно погоняешь этих синерылых псов из Альянса.','Убейте лейтенанта Корвина и 10 солдат из его отряда.','Спасибо тебе, $n.$b$bМеня беспокоит, что нам придется схлестнуться с высшими эльфами Серебряного союза… но я никогда не устану проливать кровь Альянса.','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинный облик Кирин-Тора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кирин-Тор, наконец, сбросил маски и перестал притворяться, будто занимает нейтральную позицию в конфликте. До меня дошли слухи, что возле памятника Антонидасу были незаметно размещены войска Альянса по прямому приказу Джайны.$b$bКонечно, там нет Похитителей Солнца, но столь явное попустительство со стороны Кирин-Тора меня просто бесит!$b$bНе желаешь ли прогуляться до памятника, $n? Развеешься, воздухом подышишь... да заодно погоняешь этих синерылых псов из Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лейтенанта Корвина и 10 солдат из его отряда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $n.$b$bМеня беспокоит, что нам придется схлестнуться с высшими эльфами Серебряного союза… но я никогда не устану проливать кровь Альянса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32410,'Площадка Краса','Освободите 6 дракондоров Похитителей Солнца.','Молодец, $n.','Вернитесь к верховному магистру Роммату в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Площадка Краса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 дракондоров Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32412,'Последняя надежда','Мы обыскали все, кроме Аметистовой цитадели, но нигде нет ни следа верховного мага Этаса.$b$bПопробуй поискать его в крепости – может быть, нам повезет, и его держат именно там. Если нет... что ж, сегодня мы сделали все, что могли.','Убейте командира магов Зуроса и осуществите побег из Даларана.','Это ты, $n? Что здесь происходит?','Поговорите с Лор\'темаром Тероном в Луносвете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя надежда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обыскали все, кроме Аметистовой цитадели, но нигде нет ни следа верховного мага Этаса.$b$bПопробуй поискать его в крепости – может быть, нам повезет, и его держат именно там. Если нет... что ж, сегодня мы сделали все, что могли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте командира магов Зуроса и осуществите побег из Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ты, $n? Что здесь происходит?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном в Луносвете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32413,'Возвращение в Красаранг','Мне все равно, кому ты $gклялся:клялась; в верности – Роммату и мне, Гаррошу или кому-то еще. Сейчас мне важно только одно – ты $gсовершил:совершила; настоящий подвиг.$b$bДай мне знать, когда будешь $gготов:готова; вернуться в Пандарию, и я отправлю тебя прямиком в Красарангские джунгли.','Доложите генералу Назгриму в Крепости Покорителей в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Красаранг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне все равно, кому ты $gклялся:клялась; в верности – Роммату и мне, Гаррошу или кому-то еще. Сейчас мне важно только одно – ты $gсовершил:совершила; настоящий подвиг.$b$bДай мне знать, когда будешь $gготов:готова; вернуться в Пандарию, и я отправлю тебя прямиком в Красарангские джунгли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите генералу Назгриму в Крепости Покорителей в Красарангских джунглях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32414,'Дарнас в осаде?','Как ты уже знаешь, наши союзники, ночные эльфы, отвезли Божественный колокол в Дарнас – для изучения и безопасного хранения. Буквально только что они телепортировали сюда несколько магов-высокорожденных, которые просят помощи. Детали туманны: кажется, было внезапное нападение на город.$b$bЯ не знаю, что это может быть, но Джайна уже в Дарнасе, и, возможно, ей требуется помощь.$b$bПоговори с Шеймусом, он телепортирует тебя в Дарнас. Найди Джайну!','Обратитесь к Шеймусу Золотым Башмакам в Львином лагере, чтобы он помог вам попасть в Дарнас. По прибытии поговорите с Джайной.','Колокол пропал…$B$BНа месте преступления мы обнаружили следы тайной магии. Возможно, мне удастся узнать, куда они ведут…','Поговорите с Леди Джайной Праудмур за пределами Дарнаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дарнас в осаде?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты уже знаешь, наши союзники, ночные эльфы, отвезли Божественный колокол в Дарнас – для изучения и безопасного хранения. Буквально только что они телепортировали сюда несколько магов-высокорожденных, которые просят помощи. Детали туманны: кажется, было внезапное нападение на город.$b$bЯ не знаю, что это может быть, но Джайна уже в Дарнасе, и, возможно, ей требуется помощь.$b$bПоговори с Шеймусом, он телепортирует тебя в Дарнас. Найди Джайну!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Шеймусу Золотым Башмакам в Львином лагере, чтобы он помог вам попасть в Дарнас. По прибытии поговорите с Джайной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Колокол пропал…$B$BНа месте преступления мы обнаружили следы тайной магии. Возможно, мне удастся узнать, куда они ведут…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Джайной Праудмур за пределами Дарнаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32415,'Их следы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Их следы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32416,'Решение Джайны','Слишком долго я пыталась установить дружеские отношения между Ордой и Альянсом. Я слишком часто давала Орде еще один шанс, и каждый раз она вонзала мне кинжал в спину.$b$bЯ не хочу, чтобы меня снова предали! Если Орда желает использовать Кирин-Тор как оружие в войне с Альянсом, то им нет больше места в Даларане.$b$bСледуй за мной, $n.','Воспользуйтесь порталом из Дарнаса в Даларан и поговорите с Верисой Ветрокрылой.','У меня есть для тебя несколько поручений.$B$BДжайна отправилась приводить в исполнение новые законы.','Поговорите с Верисой Ветрокрылой в Даларане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решение Джайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слишком долго я пыталась установить дружеские отношения между Ордой и Альянсом. Я слишком часто давала Орде еще один шанс, и каждый раз она вонзала мне кинжал в спину.$b$bЯ не хочу, чтобы меня снова предали! Если Орда желает использовать Кирин-Тор как оружие в войне с Альянсом, то им нет больше места в Даларане.$b$bСледуй за мной, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь порталом из Дарнаса в Даларан и поговорите с Верисой Ветрокрылой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня есть для тебя несколько поручений.$B$BДжайна отправилась приводить в исполнение новые законы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Верисой Ветрокрылой в Даларане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32417,'Зачистка стоков','Джайна расправилась почти со всеми Похитителями Солнца в городе, но многие из них все еще прячутся в стоках.$b$bНайди этих лживых крыс и положи конец их жалким жизням!','Убейте 12 Похитителей Солнца в стоках Даларана.','Избавиться от крыс всегда приятно. Ты молодец.','Вернитесь к Верисе Ветрокрылой в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка стоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Джайна расправилась почти со всеми Похитителями Солнца в городе, но многие из них все еще прячутся в стоках.$b$bНайди этих лживых крыс и положи конец их жалким жизням!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 Похитителей Солнца в стоках Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Избавиться от крыс всегда приятно. Ты молодец.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32418,'Нечестная сделка','Убейте мастера каллиграфии Айлона, Толирию, механомага Асталона и Синтарию Пепельную Паутину.','Хотя методы Джайны меня смущают, я понимаю ее мотивы.$B$BИногда мы должны дать отпор.','Вернитесь к Верисе Ветрокрылой в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестная сделка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте мастера каллиграфии Айлона, Толирию, механомага Асталона и Синтарию Пепельную Паутину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотя методы Джайны меня смущают, я понимаю ее мотивы.$B$BИногда мы должны дать отпор.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32419,'Негде спрятаться','Убейте 16 Похитителей Солнца в Прибежище Похитителей Солнца.','Это был кровавый день, Аклорион, и на твою долю выпала кровавая работа.$B$BНо не забывай, с чего все началось: это Похитители Солнца решили использовать ресурсы Кирин-Тора, чтобы помочь Орде в битве против Альянса.$B$BЕсли бы мы промедлили, они сделали то же самое с каждым из нас.','Вернитесь к Верисе Ветрокрылой в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Негде спрятаться',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 16 Похитителей Солнца в Прибежище Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это был кровавый день, Аклорион, и на твою долю выпала кровавая работа.$B$BНо не забывай, с чего все началось: это Похитители Солнца решили использовать ресурсы Кирин-Тора, чтобы помочь Орде в битве против Альянса.$B$BЕсли бы мы промедлили, они сделали то же самое с каждым из нас.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32420,'Деньги вперед','Я только что видела одного из Похитителей Солнца – Бразайла, кажется, – бегущего по направлению к северному банку. Наверняка хочет набить себе карманы перед тем, как сделать ноги.$b$bПерехвати этого грязного воришку. Когда он и прочие Похитители Солнца предали нас, они лишились права на свое богатство.','Убейте магистра Бразайла.','Мало того, что он трус и предатель, так еще и вор впридачу!$B$BХа. Орда и Похитители Солнца – все на одно лицо. Они заслужили то, что получили.','Вернитесь к Верисе Ветрокрылой в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деньги вперед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я только что видела одного из Похитителей Солнца – Бразайла, кажется, – бегущего по направлению к северному банку. Наверняка хочет набить себе карманы перед тем, как сделать ноги.$b$bПерехвати этого грязного воришку. Когда он и прочие Похитители Солнца предали нас, они лишились права на свое богатство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте магистра Бразайла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мало того, что он трус и предатель, так еще и вор впридачу!$B$BХа. Орда и Похитители Солнца – все на одно лицо. Они заслужили то, что получили.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32421,'Некуда бежать','Покорившихся Похитителей Солнца отправят в Аметистовую крепость. Непокорных приговорят к казни.$b$bНикто из них не должен ускользнуть.$b$bНа Площадке Краса Похитители Солнца держат своих дракондоров. Возьми эту пыль и осыпь ей пташек, чтобы они не смогли взлететь. Или просто перебей их, мне все равно.','Лишите 5 дракондоров Похитителей Солнца возможности летать.','Теперь Похитителям Солнца придется ответить за все. Тюрьма или смерть – их судьба в их собственных руках.','Вернитесь к Верисе Ветрокрылой в Даларан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некуда бежать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Покорившихся Похитителей Солнца отправят в Аметистовую крепость. Непокорных приговорят к казни.$b$bНикто из них не должен ускользнуть.$b$bНа Площадке Краса Похитители Солнца держат своих дракондоров. Возьми эту пыль и осыпь ей пташек, чтобы они не смогли взлететь. Или просто перебей их, мне все равно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лишите 5 дракондоров Похитителей Солнца возможности летать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь Похитителям Солнца придется ответить за все. Тюрьма или смерть – их судьба в их собственных руках.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой в Даларан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32422,'[NYI] Into Violet Hold') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NYI] Into Violet Hold',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32423,'Что должно быть сделано','Спасибо тебе за помощь, $n. Теперь я и сама справлюсь с оставшимися Похитителями Солнца.$b$bДжайна скоро отправляется в Львиный лагерь, чтобы поговорить с королем Варианом. Она попросила, чтобы ты тоже $gприсутствовал:присутствовала; на встрече.','Поговорите с Верисой Ветрокрылой, чтобы отправиться в Львиный лагерь, после чего поговорите с королем Варианом Ринном.','Я не могу винить тебя за то, что ты исполнял приказ. Я понимаю, почему Джайна решила действовать без моего одобрения.$B$BНо вы должны понять… это не игра. Это война, в которой гибнут люди и решается судьба всего Альянса.$B$BВо всяком случае, Кирин-Тор встал на нашу сторону. Сегодня мы одержали великую победу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что должно быть сделано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо тебе за помощь, $n. Теперь я и сама справлюсь с оставшимися Похитителями Солнца.$b$bДжайна скоро отправляется в Львиный лагерь, чтобы поговорить с королем Варианом. Она попросила, чтобы ты тоже $gприсутствовал:присутствовала; на встрече.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верисой Ветрокрылой, чтобы отправиться в Львиный лагерь, после чего поговорите с королем Варианом Ринном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не могу винить тебя за то, что ты исполнял приказ. Я понимаю, почему Джайна решила действовать без моего одобрения.$B$BНо вы должны понять… это не игра. Это война, в которой гибнут люди и решается судьба всего Альянса.$B$BВо всяком случае, Кирин-Тор встал на нашу сторону. Сегодня мы одержали великую победу.',`offerrewardtext_loc8`);
