INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (32426,'Смешать, но не взбалтывать','Если в ШРУ забыли, что значит слово "отставка", пусть заглянут в словарь!$B$BПохоже, дела у них и впрямь плохи, раз они обратились ко мне.$B$BХорошо, я возьмусь за это дело, но сперва мне потребуется собрать кое-какие данные.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смешать, но не взбалтывать',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если в ШРУ забыли, что значит слово "отставка", пусть заглянут в словарь!$B$BПохоже, дела у них и впрямь плохи, раз они обратились ко мне.$B$BХорошо, я возьмусь за это дело, но сперва мне потребуется собрать кое-какие данные.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32427,'Мерило для предводителя','Пандаренская кампания вошла в новую фазу. Ваш вождь потряс пандаренов военной мощью Орды. Этот континент склонится перед ним, и в его распоряжении будут все ресурсы Пандарии – хотят того пандарены или нет.$b$bЕго цели понятны мне, но я не могу вообразить, что им движет. Кто он, Гаррош Адский Крик? Куда он ведет Орду? Это я бы хотел обсудить с тобой, если ты не против.','Поговорите с Гневионом в таверне "В туманах".','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерило для предводителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандаренская кампания вошла в новую фазу. Ваш вождь потряс пандаренов военной мощью Орды. Этот континент склонится перед ним, и в его распоряжении будут все ресурсы Пандарии – хотят того пандарены или нет.$b$bЕго цели понятны мне, но я не могу вообразить, что им движет. Кто он, Гаррош Адский Крик? Куда он ведет Орду? Это я бы хотел обсудить с тобой, если ты не против.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом в таверне "В туманах".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом в таверне "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32428,'Укротитель пандаренских духов','Легенды гласят, что по Пандарии бродят легендарные духи. Найди их и победи в бою.','Победите всех пандаренских духов в битве питомцев.','Не могу поверить, что тебе удалось одолеть духов!','Вернитесь в Вечноцветущий дол.','Испытай себя, сразившись с этими духами!','Пандаренский дух воды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель пандаренских духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легенды гласят, что по Пандарии бродят легендарные духи. Найди их и победи в бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите всех пандаренских духов в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не могу поверить, что тебе удалось одолеть духов!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Вечноцветущий дол.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Испытай себя, сразившись с этими духами!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Пандаренский дух воды',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32430,'Смена командования','Убейте верховного маршала Двукоссу в Львином лагере в Красарангских джунглях. Вам потребуется группа.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена командования',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного маршала Двукоссу в Львином лагере в Красарангских джунглях. Вам потребуется группа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32431,'Слава Орде','Это мировая война, $n. Она прокатилась во всему Калимдору и Восточным королевствам и, наконец, пришла в Пандарию. Ты уже $gотличился:отличилась; на поле боя? Я хочу увидеть это собственными глазами.$b$bЖду твоих донесений с линии фронта.','Выиграйте битвы за храм Котмогу и Сверкающие копи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слава Орде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это мировая война, $n. Она прокатилась во всему Калимдору и Восточным королевствам и, наконец, пришла в Пандарию. Ты уже $gотличился:отличилась; на поле боя? Я хочу увидеть это собственными глазами.$b$bЖду твоих донесений с линии фронта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битвы за храм Котмогу и Сверкающие копи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32432,'Душа Орды','Твоими глазами я видел битвы на побережье и эпические сражения по всему миру. Ты мой самый терпеливый... и самый полезный агент.$b$bЯ присматривался и к Гаррошу Адскому Крику. Хочешь знать, что я понял?','Поговорите с Гневионом.','<В резном, выложенном шелком сундучке находится странный предмет. Похоже, с его помощью можно дополнительно улучшить пораженное ша оружие. Вид пустого гнезда вызывает в вас беспокойство. Оно похоже на бездонную глазницу, смотрящую на вас с осуждением...>','Выберите награду, открыв сундук Гневиона в таверне "В туманах".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Душа Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоими глазами я видел битвы на побережье и эпические сражения по всему миру. Ты мой самый терпеливый... и самый полезный агент.$b$bЯ присматривался и к Гаррошу Адскому Крику. Хочешь знать, что я понял?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В резном, выложенном шелком сундучке находится странный предмет. Похоже, с его помощью можно дополнительно улучшить пораженное ша оружие. Вид пустого гнезда вызывает в вас беспокойство. Оно похоже на бездонную глазницу, смотрящую на вас с осуждением...>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выберите награду, открыв сундук Гневиона в таверне "В туманах".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32433,'Яма для Подкопника','Грезик Рудогрызь стал досадной помехой на нашем пути, $n. С ним надо покончить.$b$bТы ведь знаешь, |3-6($c), что эта земля реагирует на каждый наш поступок. Мы не можем позволить гоблинам бесцельно уничтожать ее богатства.$b$bНаши разведчики докладывают, что из карьера Рудогрызя вырвались ша. За этой бедой стоит гоблин Грезик Рудогрызь.$b$bУбей его, и возможно, нам удастся сдержать натиск ша.','Убейте Грезика Рудогрызя в карьере Рудогрызя.','Вернитесь к небесному адмиралу Роджерс на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яма для Подкопника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грезик Рудогрызь стал досадной помехой на нашем пути, $n. С ним надо покончить.$b$bТы ведь знаешь, |3-6($c), что эта земля реагирует на каждый наш поступок. Мы не можем позволить гоблинам бесцельно уничтожать ее богатства.$b$bНаши разведчики докладывают, что из карьера Рудогрызя вырвались ша. За этой бедой стоит гоблин Грезик Рудогрызь.$b$bУбей его, и возможно, нам удастся сдержать натиск ша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Грезика Рудогрызя в карьере Рудогрызя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному адмиралу Роджерс на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32434,'Пылающий пандаренский дух','Ты $gрешил:решила; снова бросить мне вызов?','Победите пылающего пандаренского духа в битве питомцев.','В следующий раз ты проиграешь. Я гарантирую это!','Поговорите с пылающим пандаренским духом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающий пандаренский дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gрешил:решила; снова бросить мне вызов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите пылающего пандаренского духа в битве питомцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В следующий раз ты проиграешь. Я гарантирую это!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с пылающим пандаренским духом.',`completedtext_loc8`);
