INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32446,'Требуется разборка','Эти крошшеры начинают меня беспокоить.$b$bМы послали дроботов, чтобы разобраться с ними, но ничего путного из этого не вышло. Они ломаются быстрее, чем мы успеваем их чинить!$b$bСмотри, я нашел какой-то странный пульт управления. Думаю, мы могли бы использовать его после некоторой доводки.$b$bПопробуй направить его на крошшеров в джунглях. Надеюсь, они сломаются, и ты принесешь мне металлолом.','Уничтожьте джунглевые крошшеры с помощью перепрограммированного пульта дистанционного управления и соберите 6 кусков металлолома.','Пульт сработал как надо?','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуется разборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти крошшеры начинают меня беспокоить.$b$bМы послали дроботов, чтобы разобраться с ними, но ничего путного из этого не вышло. Они ломаются быстрее, чем мы успеваем их чинить!$b$bСмотри, я нашел какой-то странный пульт управления. Думаю, мы могли бы использовать его после некоторой доводки.$b$bПопробуй направить его на крошшеров в джунглях. Надеюсь, они сломаются, и ты принесешь мне металлолом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте джунглевые крошшеры с помощью перепрограммированного пульта дистанционного управления и соберите 6 кусков металлолома.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пульт сработал как надо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Салли "Рассольному" Маклири на борт "Небесного огня".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32448,'Связь с прошлым','Когда я бродил по долу, мне в руки попался древний пандаренский рецепт напитка Памяти. Кажется, этот напиток мог бы помочь вытянуть кое-какие детали из Шена Киена.$B$BНадеюсь, ты с пониманием отнесешься к тому, что за его ингредиентами придется отправиться тебе. Прежде всего нам понадобится сущность могу, который жил в то время, которое нас интересует.$B$BТакого духа можно отыскать на северо-западе, на Пути Завоевателей.','Найдите духовную сущность Варатуса.','Отлично. Это последний ингредиент.','Никогда не знаешь, что найдешь в книге. Особенно если это древняя пандаренская книга.$B$BМне не терпится испытать действие напитка Памяти.','Вернитесь к Бейну Кровавому Копыту на передовую Гаррош\'ар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связь с прошлым',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я бродил по долу, мне в руки попался древний пандаренский рецепт напитка Памяти. Кажется, этот напиток мог бы помочь вытянуть кое-какие детали из Шена Киена.$B$BНадеюсь, ты с пониманием отнесешься к тому, что за его ингредиентами придется отправиться тебе. Прежде всего нам понадобится сущность могу, который жил в то время, которое нас интересует.$B$BТакого духа можно отыскать на северо-западе, на Пути Завоевателей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите духовную сущность Варатуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Это последний ингредиент.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никогда не знаешь, что найдешь в книге. Особенно если это древняя пандаренская книга.$B$BМне не терпится испытать действие напитка Памяти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бейну Кровавому Копыту на передовую Гаррош\'ар.',`completedtext_loc8`);
