INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (32450,'Время настало!','Все интереснее и интереснее! У меня есть кое-какие планы относительно Львиного лагеря…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время настало!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все интереснее и интереснее! У меня есть кое-какие планы относительно Львиного лагеря…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32451,'Послание','Настало время показать этим ордынским шакалам всю силу Альянса! Сегодня они проснутся и увидят наши войска на пороге.$b$bОтправляйся к адмиралу Роджерс на "Небесный огонь". Она объяснит тебе наш план действий.$b$bУдачи, |3-6($c). Альянс гордится тобой!','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время показать этим ордынским шакалам всю силу Альянса! Сегодня они проснутся и увидят наши войска на пороге.$b$bОтправляйся к адмиралу Роджерс на "Небесный огонь". Она объяснит тебе наш план действий.$b$bУдачи, |3-6($c). Альянс гордится тобой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (32452,'Теперь мы примемся за гоблинов','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.','Самое время разобраться с этим досадным недоразумением! Мы должны преподать урок мерзавцам из картеля Трюмных Вод!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теперь мы примемся за гоблинов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с небесным адмиралом Роджерс на борту "Небесного огня" в Красарангских джунглях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Самое время разобраться с этим досадным недоразумением! Мы должны преподать урок мерзавцам из картеля Трюмных Вод!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32455,'Тишина','Мм..м..мы справились?$B$B<Андуин с трудом выталкивает из себя слова.>$B$BН...найд..и... си...гнальный огонь...$B$BВ... сумке...','Запустите сигнальную ракету Альянса.','Поговорите с адмиралом Тейлором в Львином лагере, что в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тишина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мм..м..мы справились?$B$B<Андуин с трудом выталкивает из себя слова.>$B$BН...найд..и... си...гнальный огонь...$B$BВ... сумке...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Запустите сигнальную ракету Альянса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с адмиралом Тейлором в Львином лагере, что в Красарангских джунглях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32457,'Властелин Грома','Поговорите с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.','Поговорите с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Властелин Грома',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32460,'Выследить воров','Вместе с Джайной выясните, кто и каким образом выкрал Божественный колокол. Вы можете поговорить с Шеймусом Золотыми Башмаками в Львином лагере, чтобы отправиться в Дарнас.','Я приняла решение.$B$BОтдельные члены Кирин-Тора презрели приказ и оказали помощь Орде. Я не потерплю подобного предательства!$B$B<Глаза Джайны полыхают гневом.>$B$BИди за мной, Аклорион. Мы должны очистить Даларан от этой скверны.','Поговорите с Леди Джайной Праудмур за пределами Дарнаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выследить воров',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вместе с Джайной выясните, кто и каким образом выкрал Божественный колокол. Вы можете поговорить с Шеймусом Золотыми Башмаками в Львином лагере, чтобы отправиться в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я приняла решение.$B$BОтдельные члены Кирин-Тора презрели приказ и оказали помощь Орде. Я не потерплю подобного предательства!$B$B<Глаза Джайны полыхают гневом.>$B$BИди за мной, Аклорион. Мы должны очистить Даларан от этой скверны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Джайной Праудмур за пределами Дарнаса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32461,'Орден Облачного Змея','А, я гляжу, ты $gстал счастливым обладателем:стала счастливой обладательницей; облачного змея!$B$BНо чтобы подняться в небеса, тебе придется научиться управлять этим величественным животным.$B$BЕсли тебе близок наш путь, поговори с инструктором Небесным Шипом в Дендрарии, который находится в Нефритовом лесу.$B$BУдачи, |3-6($r)!','Поговорите с инструктором Небесным Шипом в Дендрарии, расположенном в Нефритовом лесу.','Должно быть, ты здесь, чтобы присоединиться к Ордену?','Немногие удостаиваются чести оседлать облачного змея.','Старейшина Анли') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орден Облачного Змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, я гляжу, ты $gстал счастливым обладателем:стала счастливой обладательницей; облачного змея!$B$BНо чтобы подняться в небеса, тебе придется научиться управлять этим величественным животным.$B$BЕсли тебе близок наш путь, поговори с инструктором Небесным Шипом в Дендрарии, который находится в Нефритовом лесу.$B$BУдачи, |3-6($r)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инструктором Небесным Шипом в Дендрарии, расположенном в Нефритовом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должно быть, ты здесь, чтобы присоединиться к Ордену?',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Немногие удостаиваются чести оседлать облачного змея.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Старейшина Анли',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32467,'Sacrificial Prevention [PH]','Зандаларские жрецы в городе к северу отсюда подготавливают тела наших погибших союзников к жертвоприношению.\r\n\r\nКак лучше всего не дать этому произойти? Убить их. Убить их всех.','Убейте 5 зандаларских жрецов.','Вернитесь к Доджу к югу от Города троллей на Острове Властелина Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Sacrificial Prevention [PH]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандаларские жрецы в городе к северу отсюда подготавливают тела наших погибших союзников к жертвоприношению.\r\n\r\nКак лучше всего не дать этому произойти? Убить их. Убить их всех.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 зандаларских жрецов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доджу к югу от Города троллей на Острове Властелина Грома.',`completedtext_loc8`);
