INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32472,'Frighten Pterodactyls [PH]','Птенцы птеродактилей, которых зандалары дрессируют к северу отсюда, пока еще не слишком дикие и жестокие существа. Но это только пока.\r\n\r\nДумаю, нам нужно спасти их, прежде чем тролли полностью их не испортили. Попробуй просто напугать их. Возможно, испугавшись, некоторые из них улетят и тем самым спасутся от несчастливой участи.','Напугайте 12 птенцов птеродактиля.','Вернитесь к Доджу, он ждет на юге города троллей на острове Властелина Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Frighten Pterodactyls [PH]',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Птенцы птеродактилей, которых зандалары дрессируют к северу отсюда, пока еще не слишком дикие и жестокие существа. Но это только пока.\r\n\r\nДумаю, нам нужно спасти их, прежде чем тролли полностью их не испортили. Попробуй просто напугать их. Возможно, испугавшись, некоторые из них улетят и тем самым спасутся от несчастливой участи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Напугайте 12 птенцов птеродактиля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доджу, он ждет на юге города троллей на острове Властелина Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32474,'Испытание доблести','<Внезапно Гневион делает надрез на своем большом пальце и прижимает его к вашему лбу. При прикосновении его кровь обжигает вас и мгновенно впитывается в кожу.>$b$bВот! Теперь я буду наблюдать за тобой, |3-6($c). Я слежу за тобой.$b$bПандарены, как и Альянс, высоко чтят доблесть. Есть много способов продемонстрировать свою доблесть на этом континенте – например, делая ежедневные задания или сражаясь с героическими противниками в их логове. Выбирать тебе.$b$bДокажи мне свою храбрость, $n!','Получите достижение "Испытание доблести", заработав 3000 очков доблести.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Внезапно Гневион делает надрез на своем большом пальце и прижимает его к вашему лбу. При прикосновении его кровь обжигает вас и мгновенно впитывается в кожу.>$b$bВот! Теперь я буду наблюдать за тобой, |3-6($c). Я слежу за тобой.$b$bПандарены, как и Альянс, высоко чтят доблесть. Есть много способов продемонстрировать свою доблесть на этом континенте – например, делая ежедневные задания или сражаясь с героическими противниками в их логове. Выбирать тебе.$b$bДокажи мне свою храбрость, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите достижение "Испытание доблести", заработав 3000 очков доблести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32475,'Вспышка жизни','Вы берете в руку пронизанное молниями яйцо, и оно обжигает вас. Вы вспоминаете, что Ялия Мудрый Шепот из Шадо-Пан рассказывала вам о грозовых облачных змеях. Возможно, она знает, что делать с этим яйцом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вспышка жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы берете в руку пронизанное молниями яйцо, и оно обжигает вас. Вы вспоминаете, что Ялия Мудрый Шепот из Шадо-Пан рассказывала вам о грозовых облачных змеях. Возможно, она знает, что делать с этим яйцом.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32476,'Испытание доблести','<Внезапно Гневион делает надрез на своем большом пальце и прижимает его к вашему лбу. Его кровь обжигает вас и тут же впитывается в кожу.>$b$bОтлично! Теперь я буду знать все, что с тобой происходит. Ты будешь моими глазами.$b$bПандарены, как и ордынцы, высоко чтят доблесть. Есть много способов проявить доблесть на этом континенте. Станешь ли ты выполнять ежедневные поручения или убивать могучих противниках в темных подземельях – я оставляю выбор за тобой.$b$bПродемонстрируй мне свою отвагу, $n! ','Получите достижение "Испытание доблести", заработав 3000 очков доблести.','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Внезапно Гневион делает надрез на своем большом пальце и прижимает его к вашему лбу. Его кровь обжигает вас и тут же впитывается в кожу.>$b$bОтлично! Теперь я буду знать все, что с тобой происходит. Ты будешь моими глазами.$b$bПандарены, как и ордынцы, высоко чтят доблесть. Есть много способов проявить доблесть на этом континенте. Станешь ли ты выполнять ежедневные поручения или убивать могучих противниках в темных подземельях – я оставляю выбор за тобой.$b$bПродемонстрируй мне свою отвагу, $n! ',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите достижение "Испытание доблести", заработав 3000 очков доблести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице".',`completedtext_loc8`);
