INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32482,'Проверьте своего хранителя-цыпленка [PH]') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проверьте своего хранителя-цыпленка [PH]',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32485,'Укрепим оборону','Этот остров – опасное место, $n. На нас могут напасть зандалары, могу, сауроки, а что самое плохое – и Похитители Солнца.$b$bПо моему приказу на границе нашего лагеря расставлены защитные кристаллы. Сейчас они только ранят нападающих, но мне надоели полумеры!$b$bТы поможешь нам зарядить их так, чтобы они представляли смертельную угрозу.','Усильте 6 защитных кристаллов Кирин-Тора вокруг Аметистового утеса.','Отлично сработано, Фёклачка. Эти кристаллы защитят нас от любых тварей.$B$BТеперь, когда Аметистовый утес надежно защищен, можно сосредоточиться на более неотложных задачах.','Вернитесь к леди Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укрепим оборону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот остров – опасное место, $n. На нас могут напасть зандалары, могу, сауроки, а что самое плохое – и Похитители Солнца.$b$bПо моему приказу на границе нашего лагеря расставлены защитные кристаллы. Сейчас они только ранят нападающих, но мне надоели полумеры!$b$bТы поможешь нам зарядить их так, чтобы они представляли смертельную угрозу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Усильте 6 защитных кристаллов Кирин-Тора вокруг Аметистового утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, Фёклачка. Эти кристаллы защитят нас от любых тварей.$B$BТеперь, когда Аметистовый утес надежно защищен, можно сосредоточиться на более неотложных задачах.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32489,'Кишащий насекомыми Ихгалук','А, тараканы! Я как-то купила себе таракана в Подгороде.$b$bТараканы впитывают в себя всякую заразу, как губка, а затем разносят ее на такое расстоение, на какое только способны убежать. То есть очень, очень далеко.$b$bУтесы Ихгалук просто кишат этими тварями, и оттуда они разносят скверну Гнилого Клинка по всему острову. Когда будешь там, раздави столько тараканов, сколько сможешь.','Раздавите 75 тараканов Ихгалук.','Любая помощь будет кстати.','Вернитесь к Амалии Пеншир на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кишащий насекомыми Ихгалук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, тараканы! Я как-то купила себе таракана в Подгороде.$b$bТараканы впитывают в себя всякую заразу, как губка, а затем разносят ее на такое расстоение, на какое только способны убежать. То есть очень, очень далеко.$b$bУтесы Ихгалук просто кишат этими тварями, и оттуда они разносят скверну Гнилого Клинка по всему острову. Когда будешь там, раздави столько тараканов, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздавите 75 тараканов Ихгалук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любая помощь будет кстати.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амалии Пеншир на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32490,'UNUSED') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32491,'Оставленное гнить','Сауроки из клана Гнилого Клинка не едят все мясо той дичи, на которую охотятся. Они складывают его в большие кучи и оставляют гнить возле домов, привлекая этим паразитов, которые потом разносят заразу.$b$bМы не можем допустить того, чтобы болезни распространялись за пределы утесов Ихгалук. Найди мясные кучи и избавься от них.','Уничтожьте 3 зловонные кучи мяса.','Эти кучи – идеальные условия для развития возбудителей болезни.$B$BЕсли бы я по-прежнему занималась распространением чумы, я бы позаимствовала идею.','Вернитесь к Амалии Пеншир на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставленное гнить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки из клана Гнилого Клинка не едят все мясо той дичи, на которую охотятся. Они складывают его в большие кучи и оставляют гнить возле домов, привлекая этим паразитов, которые потом разносят заразу.$b$bМы не можем допустить того, чтобы болезни распространялись за пределы утесов Ихгалук. Найди мясные кучи и избавься от них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 зловонные кучи мяса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти кучи – идеальные условия для развития возбудителей болезни.$B$BЕсли бы я по-прежнему занималась распространением чумы, я бы позаимствовала идею.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амалии Пеншир на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32492,'Уничтожить котлы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить котлы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32493,'Все они падут','Зандалары не потерпят в своих рядах слабых, |3-6($c).$b$bТех, кого признают слабыми, они часто приносят в жертву во время их варварских церемоний. Духов жертв ловят и отправляют в заточение. Их заключают в тела стражей, которые охраняют эту территорию.$b$bЯ хочу изучить их природу. Для этого мне понадобится твоя помощь.$b$bВозьми этот резонирующий кристалл и извлеки духов из тел стражей.$b$bНе дай им ускользнуть от тебя!','Убейте 5 питаемых духом стражей и используйте резонирующий кристалл, чтобы поймать духов зандаларов, заключенных в них.','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все они падут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары не потерпят в своих рядах слабых, |3-6($c).$b$bТех, кого признают слабыми, они часто приносят в жертву во время их варварских церемоний. Духов жертв ловят и отправляют в заточение. Их заключают в тела стражей, которые охраняют эту территорию.$b$bЯ хочу изучить их природу. Для этого мне понадобится твоя помощь.$b$bВозьми этот резонирующий кристалл и извлеки духов из тел стражей.$b$bНе дай им ускользнуть от тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 питаемых духом стражей и используйте резонирующий кристалл, чтобы поймать духов зандаларов, заключенных в них.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32494,'Демонстрация силы','Маски у тебя?','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонстрация силы',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Маски у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эдиену Солнечной Низине на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32495,'Кровопускатель','До меня дошла тревожная информация, |3-6($c).$b$bВо Дворе Костей могу отправляют своих пленников к генералу по имени Кайда Кровопускатель.$b$bЯ избавлю тебя от подробностей, но он получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.','Убейте Кайду Кровопускателя.','Вернитесь к верховному магистру Роммату на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровопускатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня дошла тревожная информация, |3-6($c).$b$bВо Дворе Костей могу отправляют своих пленников к генералу по имени Кайда Кровопускатель.$b$bЯ избавлю тебя от подробностей, но он получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кайду Кровопускателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магистру Роммату на Остров Грома.',`completedtext_loc8`);
