INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (32497,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь костру праздника Огненного солнцеворота в Жутких пустошах.','Поклонитесь костру праздника Огненного солнцеворота в Жутких пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Жутких пустошах.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Жутких пустошах.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (32498,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь костру праздника Огненного солнцеворота в Нефритовом лесу.','Поклонитесь костру праздника Огненного солнцеворота в Нефритовом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Нефритовом лесу.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Нефритовом лесу.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (32499,'Поклонение огню','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?','Поклонитесь костру праздника Огненного солнцеворота в Красарангских джунглях.','Поклонитесь костру праздника Огненного солнцеворота в Красарангских джунглях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Праздник Огненного солнцеворота – время поклонения стихиям. Огонь разжигает страсти в нашей душе. Сколько раз эти страсти приводили к открытой агрессии... Сейчас же, находясь на этой земле, мы направляем свои эмоции так, чтоб выразить почтение стихии огня.$b$bМы поклонимся пламени, как того требуют традиции. Желаешь ли ты присоединиться к нашему чествованию огня, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Красарангских джунглях.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поклонитесь костру праздника Огненного солнцеворота в Красарангских джунглях.',`endtext_loc8`);
