INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32504,'Миссия: тайны Штормграда','Пошлите отряд под прикрытием в самое сердце вражеской территории, чтобы разведать их планы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия: тайны Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пошлите отряд под прикрытием в самое сердце вражеской территории, чтобы разведать их планы.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32506,'Крылья для полета','Поймайте птенца дикого террокрыла.','Замечательно! Отдам его смотрителю. Спасибо.','Великая тьма нависла над этим островом...','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылья для полета',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте птенца дикого террокрыла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Отдам его смотрителю. Спасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Великая тьма нависла над этим островом...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Хаторелю на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (32507,'В шкуре саурока','Утесы Ихгалук – опасное место. К счастью, тебе помогает магия Похитителей Солнца.$b$bЯ могу превратить тебя в саурока.$b$bСейчас я сделаю первую половину иллюзии. После этого отправляйся прямо на утесы Ихгалук и убей там одного саурока Гнилого Клинка. Там я свяжусь с тобой и завершу создание иллюзии.','Отправляйтесь на утесы Ихгалук и убейте саурока Гнилого Клинка.','<В вашем сознании звучит голос магистра Сайи.>$b$bДело сделано? Хорошо.$b$bТеперь я могу завершить иллюзию. Скоро ты увидишь изменения в своем облике. Пока ты не вступишь в бой, все сауроки будут считать тебя $gодним:одной; из своих.$b$bУдачи!','Я замаскирую тебя, так что тебя будет не отличить от саурока.','Магистр Сайя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В шкуре саурока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Утесы Ихгалук – опасное место. К счастью, тебе помогает магия Похитителей Солнца.$b$bЯ могу превратить тебя в саурока.$b$bСейчас я сделаю первую половину иллюзии. После этого отправляйся прямо на утесы Ихгалук и убей там одного саурока Гнилого Клинка. Там я свяжусь с тобой и завершу создание иллюзии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на утесы Ихгалук и убейте саурока Гнилого Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<В вашем сознании звучит голос магистра Сайи.>$b$bДело сделано? Хорошо.$b$bТеперь я могу завершить иллюзию. Скоро ты увидишь изменения в своем облике. Пока ты не вступишь в бой, все сауроки будут считать тебя $gодним:одной; из своих.$b$bУдачи!',`offerrewardtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Я замаскирую тебя, так что тебя будет не отличить от саурока.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Магистр Сайя',`questturntargetname_loc8`);
