INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32516,'Кровопускатель','До меня дошла тревожная информация, |3-6($c).$b$bСвоих пленников могу отправляют к генералу по имени Кайда Кровопускатель, во Двор Костей, что к югу отсюда.$b$bЯ избавлю тебя от подробностей, но он получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.','Убейте Кайду Кровопускателя.','Вернитесь к Верховному магистру Роммату в [лагерь Орды] на остров Властелина грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровопускатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня дошла тревожная информация, |3-6($c).$b$bСвоих пленников могу отправляют к генералу по имени Кайда Кровопускатель, во Двор Костей, что к югу отсюда.$b$bЯ избавлю тебя от подробностей, но он получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кайду Кровопускателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному магистру Роммату в [лагерь Орды] на остров Властелина грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32517,'Одолеть камень','Во Дворе Костей проводят свои темные ритуалы чародеи Властелина Грома.$B$BЧтобы увеличить численность своей армии, кромсатели душ Шань\'цзэ запечатывают украденные у живых души в каменные статуи.$B$BПосле этого каменных завоевателей оживляют и они превращаются в опасных противников.$B$BНужно остановить ритуал до того, как статуи оживут.','Остановите ритуал по оживлению древнего каменного завоевателя в главном храме Двора Костей.','Надежная оборона так же эффективна, как и массированное нападение. Теперь у нас стало на одного врага меньше.$B$BТы молодец!','Вернитесь к Ришель Светлый Локон на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одолеть камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Дворе Костей проводят свои темные ритуалы чародеи Властелина Грома.$B$BЧтобы увеличить численность своей армии, кромсатели душ Шань\'цзэ запечатывают украденные у живых души в каменные статуи.$B$BПосле этого каменных завоевателей оживляют и они превращаются в опасных противников.$B$BНужно остановить ритуал до того, как статуи оживут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Остановите ритуал по оживлению древнего каменного завоевателя в главном храме Двора Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надежная оборона так же эффективна, как и массированное нападение. Теперь у нас стало на одного врага меньше.$B$BТы молодец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ришель Светлый Локон на Остров Грома.',`completedtext_loc8`);
