INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32520,'Магия против магии','Мои разведчики засекли опасного зандалара на нашей стороне За\'Туала. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?','Убейте чародея Джор\'гуву.','Твои навыки весьма впечатляют. Благодарю тебя за помощь, Звергон.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия против магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики засекли опасного зандалара на нашей стороне За\'Туала. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои навыки весьма впечатляют. Благодарю тебя за помощь, Звергон.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32521,'Вторжение','Мне доложили, что на северном побережье замечен зандаларский военный отряд. Я ищу добровольца, который вызовется его уничтожить. Ты возьмешься за эту работу?','Убейте Нуркала, военного вождя зандаларов.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне доложили, что на северном побережье замечен зандаларский военный отряд. Я ищу добровольца, который вызовется его уничтожить. Ты возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32522,'Серьезная угроза','Мои разведчики обнаружили командира могу у подножия центральной башни. Его нужно убить, пока он не организовал атаку на наши позиции.$B$BТы возьмешься за эту работу?','Убейте Хограка Поработителя.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики обнаружили командира могу у подножия центральной башни. Его нужно убить, пока он не организовал атаку на наши позиции.$B$BТы возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хограка Поработителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32523,'Загоны для зверей','Нельзя сбрасывать со счетов зверей, которых зандалары используют, чтобы атаковать наш лагерь. Я отправил в загоны для зверей капитана разведчиков Эльсию и нескольких боевых магов для защиты.$b$bДвигайся на восток и разыщи ее у проломов в стене. Помоги ей справиться с кавалерией и осадными животными, которых заставили сражаться против нас.$b$bЭльсия и маги замаскированы, ты узнаешь их по мерцанию аур укрывающих заклинаний.','Разыщите капитана разведчиков Эльсию в загонах для зверей.','Хорошо, что Лор\'темар прислал именно тебя. Самим нам с этими зверями не справиться. Пора их припугнуть.','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загоны для зверей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя сбрасывать со счетов зверей, которых зандалары используют, чтобы атаковать наш лагерь. Я отправил в загоны для зверей капитана разведчиков Эльсию и нескольких боевых магов для защиты.$b$bДвигайся на восток и разыщи ее у проломов в стене. Помоги ей справиться с кавалерией и осадными животными, которых заставили сражаться против нас.$b$bЭльсия и маги замаскированы, ты узнаешь их по мерцанию аур укрывающих заклинаний.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите капитана разведчиков Эльсию в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что Лор\'темар прислал именно тебя. Самим нам с этими зверями не справиться. Пора их припугнуть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32524,'Бой барабанов троллей','Ты слышишь это, |3-6($c)? Грохот военных барабанов вдали. Зандалары готовятся к бою с нами.$b$bДавай же лишим их этой возможности – успеть подготовить свою защиту. Нужно атаковать прямо сейчас!$b$bОбратись к капитану разведчиков Эльсии на Террасе Завоевателя. Она скажет, что тебе делать дальше.','Найдите капитана разведчиков Эльсию на Террасе Завоевателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой барабанов троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты слышишь это, |3-6($c)? Грохот военных барабанов вдали. Зандалары готовятся к бою с нами.$b$bДавай же лишим их этой возможности – успеть подготовить свою защиту. Нужно атаковать прямо сейчас!$b$bОбратись к капитану разведчиков Эльсии на Террасе Завоевателя. Она скажет, что тебе делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана разведчиков Эльсию на Террасе Завоевателя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32525,'Прах врагов','Могу во Дворе Костей увеличивают свою армию, воскрешая своих погибших воинов.$b$bМы не можем позволить этому продолжаться.$b$bВозьми этот факел и сожги все мумифицированные останки, какие найдешь.$b$bМы уничтожим наших врагов до того, как они будут иметь возможность подняться.','Сожгите 8 мумифицированных останков.','Благодаря тебе, Элрондо, их мертвые больше не поднимутся. Прекрасно.','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прах врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу во Дворе Костей увеличивают свою армию, воскрешая своих погибших воинов.$b$bМы не можем позволить этому продолжаться.$b$bВозьми этот факел и сожги все мумифицированные останки, какие найдешь.$b$bМы уничтожим наших врагов до того, как они будут иметь возможность подняться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 8 мумифицированных останков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе, Элрондо, их мертвые больше не поднимутся. Прекрасно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32526,'Освобождение душ','Мы все время осаждаем могу во Дворе Костей, но боюсь, мы лишь поставляем им жертв для их ужасных ритуалов.$b$bМогу не просто убивают своих пленников. Они похищают их души и используют для оживления камня или превращают погибших в призрачные орудия войны.$b$bЯ не могу допустить, чтобы могу пополняли свои армии засчет разведчиков, и неважно, за кого они сражаются – за Орду или Альянс.$b$bОтправляйся к криптам и спустись в них. Освободи тех, кто еще остался в живых.','Вернитесь к Нараси Снежной Заре на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобождение душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы все время осаждаем могу во Дворе Костей, но боюсь, мы лишь поставляем им жертв для их ужасных ритуалов.$b$bМогу не просто убивают своих пленников. Они похищают их души и используют для оживления камня или превращают погибших в призрачные орудия войны.$b$bЯ не могу допустить, чтобы могу пополняли свои армии засчет разведчиков, и неважно, за кого они сражаются – за Орду или Альянс.$b$bОтправляйся к криптам и спустись в них. Освободи тех, кто еще остался в живых.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32527,'Мертвое дело','Двор Костей, что к югу отсюда, просто кишит могу. Они ни на минуту не прекращают проведение своих ритуалов с громом и молниями.$b$bЕсли мы хотим, чтобы наши планы завладеть этим островом успешно воплотились в жизнь, нам нельзя позволять могу удерживать эту стратегическую позицию.$b$bИх нужно ликвидировать.','Убейте 10 хранителей могил Шань\'цзэ, кромсателей душ Шань\'цзэ или призывателей грома Шань\'цзэ.','Великолепно. Ты нанес могу такой удар, который они не скоро забудут.','Вернитесь к Нараси Снежной Заре на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мертвое дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Двор Костей, что к югу отсюда, просто кишит могу. Они ни на минуту не прекращают проведение своих ритуалов с громом и молниями.$b$bЕсли мы хотим, чтобы наши планы завладеть этим островом успешно воплотились в жизнь, нам нельзя позволять могу удерживать эту стратегическую позицию.$b$bИх нужно ликвидировать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 хранителей могил Шань\'цзэ, кромсателей душ Шань\'цзэ или призывателей грома Шань\'цзэ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Ты нанес могу такой удар, который они не скоро забудут.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нараси Снежной Заре на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32528,'В склепы','Каждый день мы находим во Дворе Костей все новые реликвии.$b$bНедавно нашли среди могильных камней в самом глубоком склепе к западу отсюда этот свиток.$b$bЯ думаю, эта магическая формула вполне может использоваться для общения с загробным миром. И если я правильно понимаю язык могу, то ты можешь попытаться воспользоваться этой магической формулой в последней комнате Залов Превознесения.$b$bПроверишь мою теорию?','Воспользуйтесь чарами Гуры в Залах Превознесения, а затем победите Гуру Освобожденного.','Вернитесь к Данаре Серебристое Стеклышко на Аметистовый утес, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В склепы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый день мы находим во Дворе Костей все новые реликвии.$b$bНедавно нашли среди могильных камней в самом глубоком склепе к западу отсюда этот свиток.$b$bЯ думаю, эта магическая формула вполне может использоваться для общения с загробным миром. И если я правильно понимаю язык могу, то ты можешь попытаться воспользоваться этой магической формулой в последней комнате Залов Превознесения.$b$bПроверишь мою теорию?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь чарами Гуры в Залах Превознесения, а затем победите Гуру Освобожденного.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данаре Серебристое Стеклышко на Аметистовый утес, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32529,'Ритуал вызова грома','Во Дворе Костей, в глубине руин западной крипты, самые могущественные колдуны Властелина Грома заряжают грозовой разрядник электричеством.$b$bПо-видимому, они планируют использовать это грозное оружие, чтобы разрушить нашу крепость на Аметистовом утесе.$B$BНужно немедленно остановить их ритуал.','Прервите ритуал призывателей грома Шань\'цзэ.','Вернитесь к Вилене Амарантовой на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуал вызова грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Дворе Костей, в глубине руин западной крипты, самые могущественные колдуны Властелина Грома заряжают грозовой разрядник электричеством.$b$bПо-видимому, они планируют использовать это грозное оружие, чтобы разрушить нашу крепость на Аметистовом утесе.$B$BНужно немедленно остановить их ритуал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите ритуал призывателей грома Шань\'цзэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вилене Амарантовой на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32530,'Кровопускатель','До меня дошла тревожная информация, |3-6($c).$b$bВо Дворе Костей могу отправляют своих пленников к генералу по имени Кайда Кровопускатель.$b$bОн получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.','Убейте Кайду Кровопускателя.','Я рада слышать, что это гнусное создание мертво. Ты оказал нам большую услугу, Теньвойны.','Вернитесь к Вилене Амарантовой на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровопускатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До меня дошла тревожная информация, |3-6($c).$b$bВо Дворе Костей могу отправляют своих пленников к генералу по имени Кайда Кровопускатель.$b$bОн получает удовольствие от того, что пытает своих жертв.$b$bЭто чудовище нужно остановить. А если тебе суждено погибнуть от его клинка, то я желаю тебе быстрой смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кайду Кровопускателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада слышать, что это гнусное создание мертво. Ты оказал нам большую услугу, Теньвойны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вилене Амарантовой на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32531,'Одолеть камень','Во Дворе Костей проводят свои темные ритуалы чародеи Властелина Грома.$B$BЧтобы увеличить численность своей армии, кромсатели душ Шань\'цзэ запечатывают украденные у живых души в каменные статуи.$B$BПосле этого каменных завоевателей оживляют и они превращаются в опасных противников на поле боя.$B$BНужно остановить ритуал до того, как статуи оживут.','Остановите ритуал по оживлению древнего каменного завоевателя в главном храме Двора Костей.','Надежная оборона так же эффективна, как и массированное нападение. Теперь у нас стало на одного врага меньше.$B$BТы молодец!','Вернитесь к Вилене Амарантовой на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одолеть камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Дворе Костей проводят свои темные ритуалы чародеи Властелина Грома.$B$BЧтобы увеличить численность своей армии, кромсатели душ Шань\'цзэ запечатывают украденные у живых души в каменные статуи.$B$BПосле этого каменных завоевателей оживляют и они превращаются в опасных противников на поле боя.$B$BНужно остановить ритуал до того, как статуи оживут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Остановите ритуал по оживлению древнего каменного завоевателя в главном храме Двора Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надежная оборона так же эффективна, как и массированное нападение. Теперь у нас стало на одного врага меньше.$B$BТы молодец!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вилене Амарантовой на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32532,'Покончить с восставшими','Ты $gвидел:видела; призраков на кладбище?$b$bЭто восставшие предки, духи погибших могу, которых призвали в этот мир.$B$BЕсли их разозлить, они атакуют быстро и бесшумно, и число их растет с каждым днем.$B$BОни не принадлежат этому миру. Уничтожь их и заставь вернуться обратно в могилы.','Убейте 15 восставших предков.','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с восставшими',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвидел:видела; призраков на кладбище?$b$bЭто восставшие предки, духи погибших могу, которых призвали в этот мир.$B$BЕсли их разозлить, они атакуют быстро и бесшумно, и число их растет с каждым днем.$B$BОни не принадлежат этому миру. Уничтожь их и заставь вернуться обратно в могилы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 восставших предков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32533,'Каменный холод','Наше наступление на Двор Костей продолжается. Мы продвигаемся вперед не слишком быстро, но все же прогресс очевиден.$b$bК несчастью, мы получили несколько сообщений о том, что каменные статуи цийлиней неожиданно начали оживать. Эти цийлини слишком опасны, чтобы не обращать на них внимания.$b$bОтправляйся во Двор Костей и уничтожь все статуи цийлиней, какие найдешь.','Уничтожьте 8 могильных стражей.','Рад слышать, что ты разнес этих цийлиней на тысячу мелких кусочков. Это была заметная помеха в моих работах на этом острове.','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наше наступление на Двор Костей продолжается. Мы продвигаемся вперед не слишком быстро, но все же прогресс очевиден.$b$bК несчастью, мы получили несколько сообщений о том, что каменные статуи цийлиней неожиданно начали оживать. Эти цийлини слишком опасны, чтобы не обращать на них внимания.$b$bОтправляйся во Двор Костей и уничтожь все статуи цийлиней, какие найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 могильных стражей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад слышать, что ты разнес этих цийлиней на тысячу мелких кусочков. Это была заметная помеха в моих работах на этом острове.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Данаре Серебристое Стеклышко на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32534,'Угроза Гнилого Клинка','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Орды, мы сможем подумать о чем-то более основательном.','Убейте 10 сауроков Гнилого Клинка.','Вернитесь к Верховному магу Этасу Похитителю Солнца в [TEMP] город Орды на острове могу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Гнилого Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Орды, мы сможем подумать о чем-то более основательном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 сауроков Гнилого Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному магу Этасу Похитителю Солнца в [TEMP] город Орды на острове могу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32535,'Угроза Гнилого Клинка','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Альянса, мы сможем подумать о чем-то более основательном.','Убейте 10 сауроков Гнилого Клинка.','Придет день, и этот остров будет принадлежать Альянсу. И я могу только надеяться на то, что к тому времени на нем не будет ни одного саурока.$B$B<Модера усмехается.>$B$BПо крайней мере они тоже атакуют Орду.','Вернитесь к верховному магу Модере на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Гнилого Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Саурокам на утесах Ихгалук просто нет числа. Эти твари нападают на моих воинов и заражают воду и живую природу вокруг себя, мешая проведению наших операций.$b$bСократи их число, $n. А когда этот остров окажется в руках Альянса, мы сможем подумать о чем-то более основательном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 сауроков Гнилого Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Придет день, и этот остров будет принадлежать Альянсу. И я могу только надеяться на то, что к тому времени на нем не будет ни одного саурока.$B$B<Модера усмехается.>$B$BПо крайней мере они тоже атакуют Орду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Модере на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32536,'Манипулирование сауроками','На утесах Ихгалук работают три магистра. Они следят за сауроками и всеми силами стараются настроить их против могу. Я хочу, чтобы ты $gнашел:нашла; их и $gузнал:узнала;, не нужны ли им припасы или помощь.$b$bОни находятся в укрытиях. Ищи мерцающие столпы света в деревне сауроков.','Поговорите с магистрами Ялисом, Лианисом и Саналией.','Вернитесь к верховному магу Модере на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манипулирование сауроками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На утесах Ихгалук работают три магистра. Они следят за сауроками и всеми силами стараются настроить их против могу. Я хочу, чтобы ты $gнашел:нашла; их и $gузнал:узнала;, не нужны ли им припасы или помощь.$b$bОни находятся в укрытиях. Ищи мерцающие столпы света в деревне сауроков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с магистрами Ялисом, Лианисом и Саналией.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Модере на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32537,'Возвращение големов','Вернитесь к Верховному магу Модере на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение големов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному магу Модере на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32538,'Отвратительные жертвоприношения','Могущественные душеловы проводят ужасные обряды поклонения своим злобным богам.\r\n\r\nМы придумали способ, как можно уничтожить алтари, но трудность заключается в том, чтобы уцелеть, подбираясь к алтарю.\r\n\r\nОтправляйся в глубины За\'Туала и уничтожь алтари.','Уничтожьте жертвенные алтари зандаларов.','Вернитесь к Далвину Джакору на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвратительные жертвоприношения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могущественные душеловы проводят ужасные обряды поклонения своим злобным богам.\r\n\r\nМы придумали способ, как можно уничтожить алтари, но трудность заключается в том, чтобы уцелеть, подбираясь к алтарю.\r\n\r\nОтправляйся в глубины За\'Туала и уничтожь алтари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте жертвенные алтари зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далвину Джакору на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32539,'Темные подношения','Душеловы зандаларов проводят жертвенные ритуалы, чтобы умилостивить лоа и своих мерзких богов. В этих темных ритуалах они убивают наших сородичей.\r\n\r\nУничтожь все зандаларские подношения, которые сможешь найти в За\'Туале, чтобы уменьшить число этих жертвоприношений.','Уничтожьте 6 зандаларских подношений.','Вернитесь к Далвину Джакору на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные подношения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Душеловы зандаларов проводят жертвенные ритуалы, чтобы умилостивить лоа и своих мерзких богов. В этих темных ритуалах они убивают наших сородичей.\r\n\r\nУничтожь все зандаларские подношения, которые сможешь найти в За\'Туале, чтобы уменьшить число этих жертвоприношений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 зандаларских подношений.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далвину Джакору на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32540,'Вестники лоа','Если тебе доведется провести некоторое время в За\'Туале, ты скорее всего увидишь большие шатры, воплощающие истинное зло.\r\n\r\nПожалуйста, отправляйся в лагерь троллей и положи конец их ужасным ритуалам.','Победите 2 вестников лоа.','Большинство из тех, кому довелось увидеть подобные ритуалы, никогда не возвращались. А те, кому это все же удалось, остались потрясены до глубины души. Ты не выглядишь взволнованным, Ннорд. Ты сделал великое дело. Я впечатлен.','Вернитесь к верховному магу Лан\'далоку на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестники лоа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебе доведется провести некоторое время в За\'Туале, ты скорее всего увидишь большие шатры, воплощающие истинное зло.\r\n\r\nПожалуйста, отправляйся в лагерь троллей и положи конец их ужасным ритуалам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 2 вестников лоа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большинство из тех, кому довелось увидеть подобные ритуалы, никогда не возвращались. А те, кому это все же удалось, остались потрясены до глубины души. Ты не выглядишь взволнованным, Ннорд. Ты сделал великое дело. Я впечатлен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32541,'Предотвращение будущей угрозы','Мне больно думать о том, что приходится терпеть бедным небесным крикунам, пока тролли дрессируют их, превращая в орудия войны.\r\n\r\nПтенцы птеродактилей очень пугливы и улетают, если подойти к ним слишком близко. Пожалуйста, напугай нескольких птенцов, пока зандалары не завершили свое грязное дело.','Вернитесь к Ако на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предотвращение будущей угрозы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне больно думать о том, что приходится терпеть бедным небесным крикунам, пока тролли дрессируют их, превращая в орудия войны.\r\n\r\nПтенцы птеродактилей очень пугливы и улетают, если подойти к ним слишком близко. Пожалуйста, напугай нескольких птенцов, пока зандалары не завершили свое грязное дело.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ако на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32542,'Оперативный удар','Душеловы зандаларов приносят жертвы своим богам. Их заклинатели зверей подчиняют невинных небесных крикунов своей воле. А воины-ягуары с каждым днем подбираются к нам все ближе.\r\n\r\nОтправляйся в За\'Туал, |3-6($r), и разберись со всеми этими проблемами. Нанеси зандаларам урон.','Убейте 3 зандаларских душеловов, 3 зандаларских заклинателей зверей и 3 зандаларских воинов-ягуаров.','Теперь, после того, как мы избавились от наиболее опасных представителей их племени, возможно, зандалары как следует подумают, прежде чем связываться с нами.','Вернитесь к верховному магу Лан\'далоку на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оперативный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Душеловы зандаларов приносят жертвы своим богам. Их заклинатели зверей подчиняют невинных небесных крикунов своей воле. А воины-ягуары с каждым днем подбираются к нам все ближе.\r\n\r\nОтправляйся в За\'Туал, |3-6($r), и разберись со всеми этими проблемами. Нанеси зандаларам урон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 зандаларских душеловов, 3 зандаларских заклинателей зверей и 3 зандаларских воинов-ягуаров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, после того, как мы избавились от наиболее опасных представителей их племени, возможно, зандалары как следует подумают, прежде чем связываться с нами.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32543,'Опасности За\'Туала','Зандалары – опасные противники. Возможно, куда более опасные, чем все, встречавшиеся нам раньше. Но и ты не лыком $gшит:шита;, $n.\r\n\r\nОтправляйся в За\'Туал, это на западе, и покажи им, на что ты $gспособен:способна;.','Убейте 12 троллей в За\'Туале.','Вернитесь к верховному магу Лан\'далоку на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасности За\'Туала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары – опасные противники. Возможно, куда более опасные, чем все, встречавшиеся нам раньше. Но и ты не лыком $gшит:шита;, $n.\r\n\r\nОтправляйся в За\'Туал, это на западе, и покажи им, на что ты $gспособен:способна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 троллей в За\'Туале.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лан\'далоку на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32544,'Измученный птеродактиль','Тролли пытают одного из небесных крикунов в За\'Туале, чтобы навеки подчинить своей воле.\r\n\r\nУничтожь всех мучителей этого невинного создания. Я надеюсь, что оно еще сможет подняться в небо. ','Освободите измученного небесного крикуна.','Надеюсь, это существо запомнит, кто его спас. По-моему, не стоит лишний раз переходить ему дорогу.','Вернитесь к Ако на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измученный птеродактиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли пытают одного из небесных крикунов в За\'Туале, чтобы навеки подчинить своей воле.\r\n\r\nУничтожь всех мучителей этого невинного создания. Я надеюсь, что оно еще сможет подняться в небо. ',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите измученного небесного крикуна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, это существо запомнит, кто его спас. По-моему, не стоит лишний раз переходить ему дорогу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ако на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32545,'Обитатели утесов Ихгалук','Клан Гнилого Клинка угрожает нашим собратьям, но ответить на это кровавой резней, убивая всех подряд, было бы чересчур. И пусть тебя не удивляют их действия – они просто защищают тот маленький клочок земли, который считают своим домом.$b$bРазумнее всего будет убить вождей их племени. Кровопролития при этом будет меньше, но они поймут, что нужно уважать установленные нами границы. ','Убейте громилу Гнилого Клинка, сауро-жреца Гнилого Клинка и рассекателя волн Гнилого Клинка.','Я знаю истинную цену пролитой крови. Я знаю цену войне.$B$BКонечно, проще всего было бы устроить бойню и убивать их до тех пор, пока они не сдадутся. Но правильно ли это?','Вернитесь к Лиалии на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обитатели утесов Ихгалук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Гнилого Клинка угрожает нашим собратьям, но ответить на это кровавой резней, убивая всех подряд, было бы чересчур. И пусть тебя не удивляют их действия – они просто защищают тот маленький клочок земли, который считают своим домом.$b$bРазумнее всего будет убить вождей их племени. Кровопролития при этом будет меньше, но они поймут, что нужно уважать установленные нами границы. ',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте громилу Гнилого Клинка, сауро-жреца Гнилого Клинка и рассекателя волн Гнилого Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю истинную цену пролитой крови. Я знаю цену войне.$B$BКонечно, проще всего было бы устроить бойню и убивать их до тех пор, пока они не сдадутся. Но правильно ли это?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лиалии на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32546,'Небольшая чистка','Скажу прямо, у меня для тебя довольно грязная работенка.$b$bСауроки Гнилого Клинка сносят всю свою гниль в водоем в самом центре деревни. Она настолько отвратительна, что стала собираться в плотную, подвижную и живую массу.$b$bСауроки, конечно, могут устраивать у себя болото, но их гниль стала вытекать за пределы деревни. Думаю, настала пора вмешаться в ситуацию.','Уничтожьте 75 частиц дрожащей гнили на утесах Ихгалук.','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшая чистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу прямо, у меня для тебя довольно грязная работенка.$b$bСауроки Гнилого Клинка сносят всю свою гниль в водоем в самом центре деревни. Она настолько отвратительна, что стала собираться в плотную, подвижную и живую массу.$b$bСауроки, конечно, могут устраивать у себя болото, но их гниль стала вытекать за пределы деревни. Думаю, настала пора вмешаться в ситуацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 75 частиц дрожащей гнили на утесах Ихгалук.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32547,'Кишащий насекомыми Ихгалук','Раздавите 75 тараканов Ихгалук.','Любая помощь будет кстати.','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кишащий насекомыми Ихгалук',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздавите 75 тараканов Ихгалук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любая помощь будет кстати.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32548,'Оставленное гнить','Сауроки из клана Гнилого Клинка не едят все мясо той дичи, на которую охотятся. Они складывают его в большие кучи и оставляют гнить возле домов, привлекая этим паразитов, которые потом разносят заразу.$b$bМы не можем допустить того, чтобы болезни распространялись за пределы утесов Ихгалук. Найди мясные кучи и избавься от них.','Уничтожьте 3 зловонные кучи мяса.','Эти кучи – идеальные условия для развития возбудителей болезни.$B$BЕсли бы я по-прежнему занимался распространением чумы, я бы позаимствовал идею.','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставленное гнить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки из клана Гнилого Клинка не едят все мясо той дичи, на которую охотятся. Они складывают его в большие кучи и оставляют гнить возле домов, привлекая этим паразитов, которые потом разносят заразу.$b$bМы не можем допустить того, чтобы болезни распространялись за пределы утесов Ихгалук. Найди мясные кучи и избавься от них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 зловонные кучи мяса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти кучи – идеальные условия для развития возбудителей болезни.$B$BЕсли бы я по-прежнему занимался распространением чумы, я бы позаимствовал идею.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к санитарному магу Стивену Литмачу на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (32549,'В шкуре саурока','Утесы Ихгалук – опасное место. К счастью, тебе помогает магия Кирин-Тора.$b$bЯ могу превратить тебя в саурока.$b$bСейчас я сделаю первую половину иллюзии. После этого отправляйся прямо на утесы Ихгалук и убей там одного саурока Гнилого Клинка. Там я свяжусь с тобой и завершу создание иллюзии.','Отправляйтесь на утесы Ихгалук и убейте саурока Гнилого Клинка.','Я сделаю так, что ты будешь выглядеть, как саурок.','Проекция верховного мага Варгота') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В шкуре саурока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Утесы Ихгалук – опасное место. К счастью, тебе помогает магия Кирин-Тора.$b$bЯ могу превратить тебя в саурока.$b$bСейчас я сделаю первую половину иллюзии. После этого отправляйся прямо на утесы Ихгалук и убей там одного саурока Гнилого Клинка. Там я свяжусь с тобой и завершу создание иллюзии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на утесы Ихгалук и убейте саурока Гнилого Клинка.',`objectives_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Я сделаю так, что ты будешь выглядеть, как саурок.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Проекция верховного мага Варгота',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32550,'Расправа','В загонах для зверей ты встретишь самых опытных укротителей зверей в зандаларской армии. Они натренированы убивать – топорами, когтями или при помощи зверей. В этом бестиарии зандалары и готовят своих воинов-наездников.$b$bНам нужно, чтобы ты $gубил:убила; всех зандаларов, каких только встретишь в загонах для зверей, пока они не выехали на поле боя верхом на своих чудовищных подопечных.','Убейте 10 зандаларских троллей в загонах для зверей.','Эти тролли использовали для своих грязных целей темную магию. Нетерпеливые, низменные существа. Ты оказал услугу всему миру, расправившись с ними.','Поговорите с капитаном разведчиков Дэлином на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расправа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В загонах для зверей ты встретишь самых опытных укротителей зверей в зандаларской армии. Они натренированы убивать – топорами, когтями или при помощи зверей. В этом бестиарии зандалары и готовят своих воинов-наездников.$b$bНам нужно, чтобы ты $gубил:убила; всех зандаларов, каких только встретишь в загонах для зверей, пока они не выехали на поле боя верхом на своих чудовищных подопечных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зандаларских троллей в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти тролли использовали для своих грязных целей темную магию. Нетерпеливые, низменные существа. Ты оказал услугу всему миру, расправившись с ними.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном разведчиков Дэлином на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32551,'Компот из компсогната','Сразу после прибытия на этот остров мы потеряли трех отличных солдат. Компсогнаты пробрались в палатки и убили их во сне. Иногда по ночам мне кажется, что я все еще слышу крики...','Поговорите с капитаном разведчиков Дэлином на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Компот из компсогната',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразу после прибытия на этот остров мы потеряли трех отличных солдат. Компсогнаты пробрались в палатки и убили их во сне. Иногда по ночам мне кажется, что я все еще слышу крики...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном разведчиков Дэлином на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32552,'Лоа-завр','Зандалары научились насыщать своих зверей силой лоа, после чего те становятся невероятно сильны и смертельно опасны.$b$bМы должны прекратить это.$b$bУбей говорящего с лоа в загонах для зверей. Его можно найти возле светящихся животных.$b$bНельзя допустить, чтобы эти зверства продолжались.','Победите говорящего с лоа.','Отлично! Эти звери достаточно сильные. Нам совсем не нужно, чтобы они были полны злобы.','Поговорите с Мьюрой Яркопряд на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лоа-завр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары научились насыщать своих зверей силой лоа, после чего те становятся невероятно сильны и смертельно опасны.$b$bМы должны прекратить это.$b$bУбей говорящего с лоа в загонах для зверей. Его можно найти возле светящихся животных.$b$bНельзя допустить, чтобы эти зверства продолжались.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите говорящего с лоа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Эти звери достаточно сильные. Нам совсем не нужно, чтобы они были полны злобы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мьюрой Яркопряд на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32553,'Дикорог или дьявозавр','У нас есть отличная возможность нарушить планы зандаларов и заодно как следует посмеяться.$b$bВ этих загонах для зверей держат дьявозавра и дикорога. На них надета броня, а их разум при помощи заклинаний контролируют зандалары.$b$bОтправляйся в лагерь и прерви один из этих подчиняющих ритуалов. Какой именно – не имеет значения. Просто убей тех, кто пытается подчинить себе существо. Разьяренный зверь начнет носиться по всему лагерю зандаларов. А ты расслабься и наслаждайся веселым зрелищем.','Прервите подчиняющий ритуал, убив всех неигровых персонажей вокруг непокорного дикорога или непокорного дьявозавра.','Нет ничего более увлекательного, чем смотреть на то, как разъяренное доисторическое животное разносит по камешкам поселение твоих врагов.$B$BЕсли бы сейчас было поспокойнее, я бы даже билеты начал продавать на это представление.','Поговорите с Мьюрой Яркопряд на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикорог или дьявозавр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть отличная возможность нарушить планы зандаларов и заодно как следует посмеяться.$b$bВ этих загонах для зверей держат дьявозавра и дикорога. На них надета броня, а их разум при помощи заклинаний контролируют зандалары.$b$bОтправляйся в лагерь и прерви один из этих подчиняющих ритуалов. Какой именно – не имеет значения. Просто убей тех, кто пытается подчинить себе существо. Разьяренный зверь начнет носиться по всему лагерю зандаларов. А ты расслабься и наслаждайся веселым зрелищем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прервите подчиняющий ритуал, убив всех неигровых персонажей вокруг непокорного дикорога или непокорного дьявозавра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет ничего более увлекательного, чем смотреть на то, как разъяренное доисторическое животное разносит по камешкам поселение твоих врагов.$B$BЕсли бы сейчас было поспокойнее, я бы даже билеты начал продавать на это представление.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Мьюрой Яркопряд на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32554,'Мощь динозавра','У зандаларов есть множество фетишей и оберегов, при помощи которых они управляют своим зверинцем.$b$bЧто ж, мы можем сделать то же самое.$b$bНайди какие-нибудь из этих фетишей и опробуй их действие на разных животных в загонах для зверей.$b$bОбрати внимание, как действует каждый из них на разных животных. А затем сообщи результаты мне.$b$bМожет быть, это даст нам необходимое преимущество в борьбе с зандаларами.','Найдите и используйте заврофетиши на 5 ящерах, компсогнатах, небесных крикунах или дикорогах в загонах для зверей.','Очень интересные результаты. Где-то наверняка должен быть маг, которому будут интересны подробности. Мне-то просто приятно послушать, как кричат тролли, на которых нападают их собственные звери.','Поговорите с капитаном разведчиков Дэлином на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь динозавра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У зандаларов есть множество фетишей и оберегов, при помощи которых они управляют своим зверинцем.$b$bЧто ж, мы можем сделать то же самое.$b$bНайди какие-нибудь из этих фетишей и опробуй их действие на разных животных в загонах для зверей.$b$bОбрати внимание, как действует каждый из них на разных животных. А затем сообщи результаты мне.$b$bМожет быть, это даст нам необходимое преимущество в борьбе с зандаларами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и используйте заврофетиши на 5 ящерах, компсогнатах, небесных крикунах или дикорогах в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень интересные результаты. Где-то наверняка должен быть маг, которому будут интересны подробности. Мне-то просто приятно послушать, как кричат тролли, на которых нападают их собственные звери.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капитаном разведчиков Дэлином на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32555,'Вековые стражи','В зандаларском обществе распространены жертвоприношения. Порой жертвы даже сами вызываются участвовать в их варварских ритуалах. Это считается у них великой честью!$b$bСлабые желают проявить себя даже ценой собственной жизни – их души заключают в тела стражей, которые охраняют эту территорию. Они отдают себя в услужение своему народу.$b$bВозьми этот резонирующий кристалл. Уничтожь несколько стражей и извлеки духов из их тел, а затем принеси мне кристалл.','Уничтожьте 5 питаемых духом стражей и воспользуйтесь резонирующим кристаллом, чтобы вытянуть из них духов зандаларов.','Любопытно, |3-6(Рыцарь смерти). Кристалл гудит от негодования томящихся в нем духов. Их жажда служить не угасла даже спустя столько времени.$B$BЯ хочу получше изучить этот феномен.','Вернитесь к Мьюре Яркопряд на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вековые стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В зандаларском обществе распространены жертвоприношения. Порой жертвы даже сами вызываются участвовать в их варварских ритуалах. Это считается у них великой честью!$b$bСлабые желают проявить себя даже ценой собственной жизни – их души заключают в тела стражей, которые охраняют эту территорию. Они отдают себя в услужение своему народу.$b$bВозьми этот резонирующий кристалл. Уничтожь несколько стражей и извлеки духов из их тел, а затем принеси мне кристалл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 питаемых духом стражей и воспользуйтесь резонирующим кристаллом, чтобы вытянуть из них духов зандаларов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Любопытно, |3-6(Рыцарь смерти). Кристалл гудит от негодования томящихся в нем духов. Их жажда служить не угасла даже спустя столько времени.$B$BЯ хочу получше изучить этот феномен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мьюре Яркопряд на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32556,'Чем больше ты знаешь…','Все округа завалена зандаларскими артефактами. Я бы слукавила, если бы сказала, что они меня совсем не интересуют. Мне хочется понять, какую роль эти предметы играют в зандаларских ритуалах.$b$bЧем лучше понимаешь врага, тем проще с ним справиться.$b$bДля того чтобы изучить артефакты, мне нужно посмотреть на них поближе. Принеси мне все артефакты, что сможешь найти.','Принесите 6 ритуальных артефактов с Террасы Завоевателя.','Чудесные находки! На их изучение уйдет некоторое время, но знания о зандаларах принесут там немалую пользу.','Вернитесь к Мьюре Яркопряд на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чем больше ты знаешь…',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все округа завалена зандаларскими артефактами. Я бы слукавила, если бы сказала, что они меня совсем не интересуют. Мне хочется понять, какую роль эти предметы играют в зандаларских ритуалах.$b$bЧем лучше понимаешь врага, тем проще с ним справиться.$b$bДля того чтобы изучить артефакты, мне нужно посмотреть на них поближе. Принеси мне все артефакты, что сможешь найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 ритуальных артефактов с Террасы Завоевателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесные находки! На их изучение уйдет некоторое время, но знания о зандаларах принесут там немалую пользу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мьюре Яркопряд на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32557,'Обезоружить врага','Магия – это ужасающая сила в руках опытного заклинателя. Клинок же – мощное оружие даже в самых неумелых руках.$b$bЗандалары владеют мощным оружием, которое усилено с помощью магических чар. Нужно лишить их этого преимущества.$b$bУкради у них столько единиц оружия, сколько сможешь.','Вернитесь к капитану разведчиков Дэлину на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезоружить врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магия – это ужасающая сила в руках опытного заклинателя. Клинок же – мощное оружие даже в самых неумелых руках.$b$bЗандалары владеют мощным оружием, которое усилено с помощью магических чар. Нужно лишить их этого преимущества.$b$bУкради у них столько единиц оружия, сколько сможешь.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32558,'Все в семью','Где же маски?','Вернитесь к Мьюре Яркопряд на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все в семью',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где же маски?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мьюре Яркопряд на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32559,'Даже великанам приходит конец','Зандалары поклоняются лоа, духам животных, которых они часто призывают на помощь. Они даже могут попытаться привязать призванных духов к одному гигантскому голему. Последствия этого будут просто ужасны.$b$bЯ выслал вперед разведчика для сбора дополнительной информации, но нам потребуется и твоя помощь.$b$bНужно остановить зандаларский ритуал любой ценой.','Уничтожьте стража Та\'ку на Террасе Завоевателя.','Вернитесь к капитану разведчиков Дэлину на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даже великанам приходит конец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары поклоняются лоа, духам животных, которых они часто призывают на помощь. Они даже могут попытаться привязать призванных духов к одному гигантскому голему. Последствия этого будут просто ужасны.$b$bЯ выслал вперед разведчика для сбора дополнительной информации, но нам потребуется и твоя помощь.$b$bНужно остановить зандаларский ритуал любой ценой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте стража Та\'ку на Террасе Завоевателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32560,'Хранить в тайне','Местные зандалары представляют угрозу для нашей кампании, |3-6($c).$b$bОни используют магию самым отвратительным образом – смешивают силу тайной магии с силой тьмы, ни капли не задумываясь о последствиях.$b$bНельзя, чтобы они и дальше оттачивали здесь свои гнусные навыки. Что еше хуже, об этой ужасной магии может прознать Орда.$b$bМы должны уменьшить их численность. Думаю, ты знаешь, что делать.','Убейте 8 зандаларских троллей на Террасе Завоевателя.','Вернитесь к капитану разведчиков Дэлину на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранить в тайне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Местные зандалары представляют угрозу для нашей кампании, |3-6($c).$b$bОни используют магию самым отвратительным образом – смешивают силу тайной магии с силой тьмы, ни капли не задумываясь о последствиях.$b$bНельзя, чтобы они и дальше оттачивали здесь свои гнусные навыки. Что еше хуже, об этой ужасной магии может прознать Орда.$b$bМы должны уменьшить их численность. Думаю, ты знаешь, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 зандаларских троллей на Террасе Завоевателя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32561,'Магия против магии','Один из моих ясновидцев обнаружил командира зандаларов рядом с центральной башней. Его надо уничтожить.$B$BТы сможешь это сделать, |3-6($c)?','Убейте чародея Джор\'гуву.','Вернитесь к Лор\'темару Терону на "Алый Путник".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия против магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из моих ясновидцев обнаружил командира зандаларов рядом с центральной башней. Его надо уничтожить.$B$BТы сможешь это сделать, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на "Алый Путник".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32562,'Серьезная угроза','Один из моих разведчиков вернулся и доложил о командире могу у подножия центральной башни. Его надо уничтожить.$B$BТы сможешь это сделать, |3-6($c)?','Убейте Хограка Поработителя.','Вернитесь к Лор\'темару Терону на "Алый Путник".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из моих разведчиков вернулся и доложил о командире могу у подножия центральной башни. Его надо уничтожить.$B$BТы сможешь это сделать, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хограка Поработителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на "Алый Путник".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32563,'Вторжение','На побережье внизу сразу за стенами мы заметили военный отряд зандаларов. Нужно избавиться от них до того, как мы вернемся в лагерь.$b$bВозьмешься за это?','Убейте Нуркала, военного вождя зандаларов.','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На побережье внизу сразу за стенами мы заметили военный отряд зандаларов. Нужно избавиться от них до того, как мы вернемся в лагерь.$b$bВозьмешься за это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32564,'Зандалары на подъеме','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?','Убейте чародея Джор\'гуву.','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандалары на подъеме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32565,'Вторжение','Там, на пляже, мы заметили зандаларский отряд. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bВозьмешься за это?','Убейте Нуркала, военного вождя зандаларов.','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там, на пляже, мы заметили зандаларский отряд. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bВозьмешься за это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии к северу от Мрачных топей.',`completedtext_loc8`);
