INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32567,'Загоны для зверей','Нельзя допустить, чтобы еще один зандаларский наездник прорвался сквозь нашу линию обороны!$b$bЯ отправила капитана разведчиков Дэлина вместе с боевыми магами в загоны для зверей к северо-западу отсюда. Их задача – проникнуть в стан врага и нанести урон зандаларским осадным зверям и кавалерии.$b$bТы найдешь их по призрачному мерцанию, возникающему при использовании чародейской маскировки.','Найдите капитана разведчиков Дэлина в загонах для зверей.','Сегодня мы охотимся на охотников.','Найдите капитана Дэлина в загонах для зверей на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загоны для зверей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя допустить, чтобы еще один зандаларский наездник прорвался сквозь нашу линию обороны!$b$bЯ отправила капитана разведчиков Дэлина вместе с боевыми магами в загоны для зверей к северо-западу отсюда. Их задача – проникнуть в стан врага и нанести урон зандаларским осадным зверям и кавалерии.$b$bТы найдешь их по призрачному мерцанию, возникающему при использовании чародейской маскировки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана разведчиков Дэлина в загонах для зверей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня мы охотимся на охотников.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана Дэлина в загонах для зверей на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32568,'Нет времени отдыхать','Мы многое успели сделать со времени прибытия сюда, но у нас нет времени на отдых. Благодаря твоей помощи нам удалось пробиться на верхний уровень крепости Властелина Грома.$b$bТеперь я прошу тебя продолжить нашу кампанию. Обратись к капитану разведчиков Дэлину на Террасе Завоевателя. У него будут для тебя дальнейшие приказания.','Найдите капитана разведчиков Дэлина на Террасе Завоевателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет времени отдыхать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы многое успели сделать со времени прибытия сюда, но у нас нет времени на отдых. Благодаря твоей помощи нам удалось пробиться на верхний уровень крепости Властелина Грома.$b$bТеперь я прошу тебя продолжить нашу кампанию. Обратись к капитану разведчиков Дэлину на Террасе Завоевателя. У него будут для тебя дальнейшие приказания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана разведчиков Дэлина на Террасе Завоевателя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32569,'Освещенный путь во тьме','В Мрачных топях действует некая темная магия, которая тушит даже наши магические огни. Из-за этого наши разведчики плутают в пути.$B$BКогда попадешь на болото, зажги там все потухнувшие факелы, что обнаружишь. Это позволит нашим разведчикам найти дорогу. Да и тебе $gсамому:самой; будет проще выбраться оттуда.','Зажгите 8 погасших факелов в Мрачных топях.','Вернитесь к боевому магу Юриасу на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освещенный путь во тьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Мрачных топях действует некая темная магия, которая тушит даже наши магические огни. Из-за этого наши разведчики плутают в пути.$B$BКогда попадешь на болото, зажги там все потухнувшие факелы, что обнаружишь. Это позволит нашим разведчикам найти дорогу. Да и тебе $gсамому:самой; будет проще выбраться оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите 8 погасших факелов в Мрачных топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Юриасу на Аметистовый утес.',`completedtext_loc8`);
