INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32571,'Крылья для полета','Поймайте птенца дикого террокрыла.','Отлично! Я передам его нашему смотрителю. Спасибо тебе.','Великая тьма нависла над этим островом...','Вернитесь к боевому магу Юриасу на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылья для полета',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте птенца дикого террокрыла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Я передам его нашему смотрителю. Спасибо тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Великая тьма нависла над этим островом...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Юриасу на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32572,'Недремлющий легион','Убейте 6 оживших воинов.','Ты сделал доброе дело.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недремлющий легион',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 оживших воинов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сделал доброе дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32573,'Враги под башней','В Мрачных топях могу оживляют армию статуй возле башни. Вериса приказывает убить их. Думаю, это работа как раз для тебя.','Убейте 7 могу Шань\'цзэ в Мрачных топях.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враги под башней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Мрачных топях могу оживляют армию статуй возле башни. Вериса приказывает убить их. Думаю, это работа как раз для тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 могу Шань\'цзэ в Мрачных топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32574,'Содрогающаяся трясина','В болоте обитает огромное чудовище. Пока оно еще не осмелилось напасть на нас, но я думаю, это временно.$B$BРасправься с ним, пока оно не проголодалось и не напало на наш лагерь.','Убейте могучего дьявозавра.','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Содрогающаяся трясина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В болоте обитает огромное чудовище. Пока оно еще не осмелилось напасть на нас, но я думаю, это временно.$B$BРасправься с ним, пока оно не проголодалось и не напало на наш лагерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте могучего дьявозавра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32575,'Зандаларский колосс','Тролли выпустили одну из своих громадин на южной дороге и блокировали наш проход по острову. Проследи, чтобы дорога была очищена, |3-6($c).','Уничтожьте зандаларского колосса.','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский колосс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли выпустили одну из своих громадин на южной дороге и блокировали наш проход по острову. Проследи, чтобы дорога была очищена, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте зандаларского колосса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верисе Ветрокрылой на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32576,'Магия против магии','Один из ясновидцев обнаружил командира зандаларов рядом центральной башней. Его следует устранить.$B$BТы сможешь это сделать, |3-6($c)?','Убейте чародея Джор\'гуву.','Вернитесь к Джайне Праудмур на "Морскую Стрелу".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия против магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из ясновидцев обнаружил командира зандаларов рядом центральной башней. Его следует устранить.$B$BТы сможешь это сделать, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на "Морскую Стрелу".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32577,'Нависшая угроза','Один из разведчиков Верисы доложил о том, что обнаружил командира могу под центральной башней. Его следует устранить.$B$BТы сможешь это сделать, |3-6($c)?','Убейте Хограка Поработителя.','Вернитесь к Джайне Праудмур на "Морскую Стрелу".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нависшая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из разведчиков Верисы доложил о том, что обнаружил командира могу под центральной башней. Его следует устранить.$B$BТы сможешь это сделать, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хограка Поработителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на "Морскую Стрелу".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32578,'Среди костей','Разведчики обнаружили опасного зандалара среди костей к западу от утесов Ихгалук. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?','Убейте Зур\'чаку Ваятеля Костей.','Хорошо, что мне есть на кого положиться.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики обнаружили опасного зандалара среди костей к западу от утесов Ихгалук. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зур\'чаку Ваятеля Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что мне есть на кого положиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32579,'Магия против магии','Разведчики засекли опасного зандалара на нашей стороне За\'Туала. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?','Убейте чародея Джор\'гуву.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия против магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики засекли опасного зандалара на нашей стороне За\'Туала. Я ищу добровольца, который вызовется его ликвидировать. Ты возьмешься за эту работу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32580,'Вторжение','Нам доложили, что прямо за городской стеной, к северу от крепости, на пляже замечен зандаларский военный отряд. Противника нужно найти и уничтожить.$B$BВызовешься добровольцем, |3-6($c)?','Убейте Нуркала, военного вождя зандаларов.','Мы признательны тебе за помощь, Дроунд.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам доложили, что прямо за городской стеной, к северу от крепости, на пляже замечен зандаларский военный отряд. Противника нужно найти и уничтожить.$B$BВызовешься добровольцем, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы признательны тебе за помощь, Дроунд.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32581,'Серьезная угроза','Ясновидцы обнаружили командира могу под центральной башней. Нужно его уничтожить до того, как он сможет организовать атаку на наши позиции.$B$BТы возьмешься провести эту операцию?','Убейте Хограка Поработителя.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ясновидцы обнаружили командира могу под центральной башней. Нужно его уничтожить до того, как он сможет организовать атаку на наши позиции.$B$BТы возьмешься провести эту операцию?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хограка Поработителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32582,'Дождь из костей','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bНе займешься ли ты этим?','Убейте Зур\'чаку Ваятеля Костей.','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дождь из костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bНе займешься ли ты этим?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зур\'чаку Ваятеля Костей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32583,'Зандалары на подъеме','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?','Убейте чародея Джор\'гуву.','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандалары на подъеме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В верхней части центральной лестницы мы заметили одного из вождей зандаларов. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bМожешь позаботиться об этом?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте чародея Джор\'гуву.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32584,'Вторжение','На побережье внизу сразу за стенами мы заметили военный отряд зандаларов. Нужно избавиться от них до того, как мы вернемся в лагерь.$b$bВозьмешься за это?','Убейте Нуркала, военного вождя зандаларов.','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На побережье внизу сразу за стенами мы заметили военный отряд зандаларов. Нужно избавиться от них до того, как мы вернемся в лагерь.$b$bВозьмешься за это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32585,'Вторжение','Там, на пляже, мы заметили зандаларский отряд. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bВозьмешься за это?','Убейте Нуркала, военного вождя зандаларов.','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Там, на пляже, мы заметили зандаларский отряд. Нужно избавиться от него до того, как мы вернемся в лагерь.$b$bВозьмешься за это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нуркала, военного вождя зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину. Его можно найти к северу от Мрачных топей.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32586,'Максимальная нагрузка','Шахта, которая располагается к северу отсюда, имеет огромное значение для могу. Для добычи руды они пользуются гигантскими молниевыми бурами.\r\n\r\nЕсли тебе удастся разрушить эти буры, это будет огромным ударом для могу и сильно замедлит их производство оружия.\r\n\r\nДа, и заодно убей того, кто руководит операцией, хорошо?','Уничтожьте 3 молниевых бура в Шахте молний и убейте повелителя металла Моно-Ханя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Максимальная нагрузка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шахта, которая располагается к северу отсюда, имеет огромное значение для могу. Для добычи руды они пользуются гигантскими молниевыми бурами.\r\n\r\nЕсли тебе удастся разрушить эти буры, это будет огромным ударом для могу и сильно замедлит их производство оружия.\r\n\r\nДа, и заодно убей того, кто руководит операцией, хорошо?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 3 молниевых бура в Шахте молний и убейте повелителя металла Моно-Ханя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32587,'Впереди кузня!','Перед тобой – кузня, центр производства оружия могу.\r\n\r\nТам же находится страж ворот, который хранит ключи, открывающие врата от следующей части города.\r\n\r\nПора двигаться вперед!','Отлично. То, что ты сделал сегодня, на один шаг приближает нас к главной цели.','Итак?','Вернитесь к капитану разведчиков Дэлину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впереди кузня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тобой – кузня, центр производства оружия могу.\r\n\r\nТам же находится страж ворот, который хранит ключи, открывающие врата от следующей части города.\r\n\r\nПора двигаться вперед!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. То, что ты сделал сегодня, на один шаг приближает нас к главной цели.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32588,'Секретные агенты Ее Mагичества','По личному приказанию Джайны некоторые из наших разведчиков пытались проникнуть на территорию могу, чтобы выяснить, что происходит в шахте.\r\n\r\nИх схватили и никто не знает, каким ужасным пыткам подвергают.\r\n\r\nТы $gдолжен:должна; освободить их и убить того, кто за всем этим стоит!','Спасите 3 захваченных представителей Кирин-Тора в Шахте молний и убейте повелителя металла Моно-Ханя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секретные агенты Ее Mагичества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По личному приказанию Джайны некоторые из наших разведчиков пытались проникнуть на территорию могу, чтобы выяснить, что происходит в шахте.\r\n\r\nИх схватили и никто не знает, каким ужасным пыткам подвергают.\r\n\r\nТы $gдолжен:должна; освободить их и убить того, кто за всем этим стоит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 3 захваченных представителей Кирин-Тора в Шахте молний и убейте повелителя металла Моно-Ханя.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (32589,'Живая кровь','Разведчики обнаружили странного голема в Шахте Молний. Несомненно, это секретное оружие Властелина Грома.$b$bВозможно, мы могли бы его использовать в своих целях. Если мы сможем запустить устройство, то у нас получится изучить его подробнее. И самое главное, мы сумеем выявить его уязвимые части.$b$bОтправляйся в Престол Гроз и используй этот кристалл, чтобы поймать сущность, вдыхающую жизнь в подобных големов.$b$bВозвращайся ко мне по завершении задания.','Используйте настроенный кристалл, чтобы извлечь останки Анимуса из Темного Анимуса на Престоле Гроз.','Твой поход увенчался успехом?','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.','Темный Анимус') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живая кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики обнаружили странного голема в Шахте Молний. Несомненно, это секретное оружие Властелина Грома.$b$bВозможно, мы могли бы его использовать в своих целях. Если мы сможем запустить устройство, то у нас получится изучить его подробнее. И самое главное, мы сумеем выявить его уязвимые части.$b$bОтправляйся в Престол Гроз и используй этот кристалл, чтобы поймать сущность, вдыхающую жизнь в подобных големов.$b$bВозвращайся ко мне по завершении задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте настроенный кристалл, чтобы извлечь останки Анимуса из Темного Анимуса на Престоле Гроз.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твой поход увенчался успехом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Темный Анимус',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32590,'Встретимся наверху','Я хочу, чтобы ты кое с кем $gвстретился:встретилась;. Эту скромную таверну недавно посетил наследный принц Штормграда. Я приказал своим стражам защищать его от любых проявлений агрессии со стороны Орды. Мне ни к чему излишнее внимание.$b$bМы с ним обсуждали последние произошедшие в мире события – сражение у южных берегов, его стычку с Гаррошем и предстоящее нападение на Властелина Грома.$b$bПойдем! Поговорим наверху...','Встретьтесь с Гневионом в таверне "В туманах", что на Сокрытой лестнице.','Встретьтесь с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встретимся наверху',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты кое с кем $gвстретился:встретилась;. Эту скромную таверну недавно посетил наследный принц Штормграда. Я приказал своим стражам защищать его от любых проявлений агрессии со стороны Орды. Мне ни к чему излишнее внимание.$b$bМы с ним обсуждали последние произошедшие в мире события – сражение у южных берегов, его стычку с Гаррошем и предстоящее нападение на Властелина Грома.$b$bПойдем! Поговорим наверху...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Гневионом в таверне "В туманах", что на Сокрытой лестнице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Гневионом на втором этаже таверны "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32591,'Секреты Первой империи','Соберите 20 тайн империи и 40 слитков триллия.','<Гневион изучает принесенные вами сокровища.>$B$BЗамечательно. Триллий, конечно, потребует дополнительной обработки, но эти образцы отличного качества.$B$BМне понадобится некоторое время на изучение этих артефактов, но я уверен, что мне удастся использовать полученные знания и создать нечто, представляющее ценность для нас обоих.','Что тебе удалось обнаружить в Престоле Гроз? Верно ли то, что говорят о Властелине Грома?','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секреты Первой империи',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 тайн империи и 40 слитков триллия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гневион изучает принесенные вами сокровища.>$B$BЗамечательно. Триллий, конечно, потребует дополнительной обработки, но эти образцы отличного качества.$B$BМне понадобится некоторое время на изучение этих артефактов, но я уверен, что мне удастся использовать полученные знания и создать нечто, представляющее ценность для нас обоих.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось обнаружить в Престоле Гроз? Верно ли то, что говорят о Властелине Грома?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32593,'Кузня Грома','Все готово, $n, и именно ты $gстал:стала; избранным мною героем.$b$bТеперь мы должны пробраться в легендарную Кузню Грома, принадлежащую самому Лэй Шэню! Двигайся вперед вместе со своей фракцией, пока тебе не откроется доступ к Кузне Грома, если этого еще не произошло ранее.$b$bЯ буду ждать тебя там. Будь $gготов:готова; к бою!','Узри Копье молний! Это проводник, способный передавать и контролировать ту энергию, с помощью которой Властелин Грома основал свою империю.$B$BЕго сила сейчас спит... но ты можешь это изменить. Если окажешься достоин.','Поговорите с Гневионом возле Кузни Грома на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузня Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, $n, и именно ты $gстал:стала; избранным мною героем.$b$bТеперь мы должны пробраться в легендарную Кузню Грома, принадлежащую самому Лэй Шэню! Двигайся вперед вместе со своей фракцией, пока тебе не откроется доступ к Кузне Грома, если этого еще не произошло ранее.$b$bЯ буду ждать тебя там. Будь $gготов:готова; к бою!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Узри Копье молний! Это проводник, способный передавать и контролировать ту энергию, с помощью которой Властелин Грома основал свою империю.$B$BЕго сила сейчас спит... но ты можешь это изменить. Если окажешься достоин.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом возле Кузни Грома на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32594,'Дух Повелителя Гроз','Наша следующая цель – закалить это оружие в крови полубога, получившего силы Властелина Грома.$b$bМои агенты говорят, что могу по имени Шань-Бу сейчас создает такое существо, чтобы оно охраняло цитадель Властелина Грома.$b$bКак только твой отряд пробьет дорогу к главным воротам, атакуй Повелителя Гроз Налака и вонзи это копье ему в бок. Существо сделает все, что в его силах, чтобы остановить тебя – постарайся прожить достаточно долго, чтобы заполучить силу Повелителя Гроз!','Ты справился! Копье наполнено силой и могуществом!$B$BОх, друг мой, тебе положена достойная награда...','Что с Повелителем Гроз Налаком? А с копьем? Мне нужны подробности!','Принесите закаленное Копье молний Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Повелителя Гроз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша следующая цель – закалить это оружие в крови полубога, получившего силы Властелина Грома.$b$bМои агенты говорят, что могу по имени Шань-Бу сейчас создает такое существо, чтобы оно охраняло цитадель Властелина Грома.$b$bКак только твой отряд пробьет дорогу к главным воротам, атакуй Повелителя Гроз Налака и вонзи это копье ему в бок. Существо сделает все, что в его силах, чтобы остановить тебя – постарайся прожить достаточно долго, чтобы заполучить силу Повелителя Гроз!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты справился! Копье наполнено силой и могуществом!$B$BОх, друг мой, тебе положена достойная награда...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что с Повелителем Гроз Налаком? А с копьем? Мне нужны подробности!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите закаленное Копье молний Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32595,'Корона Небес','Помнишь Причуду Камнетеса, холм к востоку отсюда, где мы с тобой уже встречались?$b$bЯ собираюсь использовать Копье молний и создать нечто особое, но здесь я это, конечно, сделать не смогу.$b$bВстретимся на вершине Причуды Камнетеса и мы вместе отпразднуем наши победы!','Встретьтесь с Гневионом на вершине Причуды Камнетеса на Сокрытой лестнице и получите свою награду.','Корона Небес! Используй ее для улучшения своего шлема.$B$BТакже она обладает свойствами третьего глаза – я смогу следить за твоими успехами, когда мы перейдем к следующей части нашего путешествия.','Поговорите с Гневионом на вершине Причуды Камнетеса на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помнишь Причуду Камнетеса, холм к востоку отсюда, где мы с тобой уже встречались?$b$bЯ собираюсь использовать Копье молний и создать нечто особое, но здесь я это, конечно, сделать не смогу.$b$bВстретимся на вершине Причуды Камнетеса и мы вместе отпразднуем наши победы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Гневионом на вершине Причуды Камнетеса на Сокрытой лестнице и получите свою награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Корона Небес! Используй ее для улучшения своего шлема.$B$BТакже она обладает свойствами третьего глаза – я смогу следить за твоими успехами, когда мы перейдем к следующей части нашего путешествия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом на вершине Причуды Камнетеса на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32596,'Эхо титанов','Благодаря твоей работе, Папи, мы восстановили древнюю повесть. Могу некогда были созданиями из камня и выполняли приказы титанов. Но затем их хозяева умолкли, и они стали жертвой проклятья плоти. В итоге пришел Лэй Шэнь, заключил в тюрьму смотрителя Ра и захватил его власть. Ах, какую империю он создал!$B$BТеперь, когда мы знаем это, пора действовать...','Что тебе уже удалось найти?$B$BНам надо собрать всю информацию, которую только сможем!','Принесите рунные камни титанов Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эхо титанов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря твоей работе, Папи, мы восстановили древнюю повесть. Могу некогда были созданиями из камня и выполняли приказы титанов. Но затем их хозяева умолкли, и они стали жертвой проклятья плоти. В итоге пришел Лэй Шэнь, заключил в тюрьму смотрителя Ра и захватил его власть. Ах, какую империю он создал!$B$BТеперь, когда мы знаем это, пора действовать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе уже удалось найти?$B$BНам надо собрать всю информацию, которую только сможем!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите рунные камни титанов Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32597,'Сердце Властелина Грома','Властелин Грома уже двенадцать тысяч лет как мертв, но зов зандаларов вернул его. Без сомнения, сила титанов сохранила его мерзкий труп.$b$bСила титанов, которая принадлежит мне по праву.$b$b$n! Принеси мне сердце Властелина Грома. Когда оно станет моим, никто не сможет возродить его снова.$b$bПринеси его мне, |3-6($c). Принеси мне его холодное, мертвое сердце!','Убейте Властелина Грома и заберите сердце Властелина Грома.','<Гневион сжимает черное сердце в ладони; его глаза торжествующе горят.>$B$BТы... ты сделал это! Черное сердце Властелина Грома!','Властелин Грома! Что с ним стало?','Принесите сердце Гневиону в таверну "В туманах" на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властелин Грома уже двенадцать тысяч лет как мертв, но зов зандаларов вернул его. Без сомнения, сила титанов сохранила его мерзкий труп.$b$bСила титанов, которая принадлежит мне по праву.$b$b$n! Принеси мне сердце Властелина Грома. Когда оно станет моим, никто не сможет возродить его снова.$b$bПринеси его мне, |3-6($c). Принеси мне его холодное, мертвое сердце!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Властелина Грома и заберите сердце Властелина Грома.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гневион сжимает черное сердце в ладони; его глаза торжествующе горят.>$B$BТы... ты сделал это! Черное сердце Властелина Грома!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Властелин Грома! Что с ним стало?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите сердце Гневиону в таверну "В туманах" на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32598,'Расплата','Властелин Грома мертв, и теперь Альянс и Орда используют в своих целях инструменты, с помощью которых он подавлял народ.$b$bМы приближаемся к кульминации пандаренской кампании. Интриги Адского Крика заставили Альянс выступить против него – но самое главное, он вызвал раздробленность в рядах Орды. Как говорят пандарены, "лапша готова". Все балансирует на грани взрыва, и вся наша работа была проделана ради этого.$b$bМне нужно время, чтобы составить план. Приходи ко мне, как только твоя фракция будет готова выступить!','Поговорите с Гневионом на верхнем этаже таверны "В туманах" на Сокрытой лестнице.','Поговорите с Гневионом на верхнем этаже таверны "В туманах" на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властелин Грома мертв, и теперь Альянс и Орда используют в своих целях инструменты, с помощью которых он подавлял народ.$b$bМы приближаемся к кульминации пандаренской кампании. Интриги Адского Крика заставили Альянс выступить против него – но самое главное, он вызвал раздробленность в рядах Орды. Как говорят пандарены, "лапша готова". Все балансирует на грани взрыва, и вся наша работа была проделана ради этого.$b$bМне нужно время, чтобы составить план. Приходи ко мне, как только твоя фракция будет готова выступить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гневионом на верхнем этаже таверны "В туманах" на Сокрытой лестнице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом на верхнем этаже таверны "В туманах" на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32599,'Защита будущего','Ходят слухи, что Властелин Грома черпает силу прямо из скрытого источника, находящегося в его дворце.$b$bДаже если он будет побежден, новый тиран, возможно, Гаррош, все равно сможет использовать эту силу для достижения ужасных целей.$b$bНам нужно нанести удар первыми!$b$bВозьми мой посох на Вершину Бурь. После победы над Лэй Шэнем помести мой посох в центр его помоста.$b$bМы вытянем остатки его силы, чтобы она навсегда осталась в наших руках.','Уничтожьте Властелина Грома на Вершине Бурь и используйте посох Антонидаса, чтобы вытянуть остаточную силу из его помоста.','Благодаря тебе, Элрондо, мы укрепили наше преимущество. Твои деяния будут помнить.$B$BГаррош заплатит за свои злодейства!','Когда сила Лэй Шэня окажется в моем посохе, нас будет не остановить.','Вернитесь к Леди Джайне Праудмур на Остров Грома. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита будущего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что Властелин Грома черпает силу прямо из скрытого источника, находящегося в его дворце.$b$bДаже если он будет побежден, новый тиран, возможно, Гаррош, все равно сможет использовать эту силу для достижения ужасных целей.$b$bНам нужно нанести удар первыми!$b$bВозьми мой посох на Вершину Бурь. После победы над Лэй Шэнем помести мой посох в центр его помоста.$b$bМы вытянем остатки его силы, чтобы она навсегда осталась в наших руках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Властелина Грома на Вершине Бурь и используйте посох Антонидаса, чтобы вытянуть остаточную силу из его помоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе, Элрондо, мы укрепили наше преимущество. Твои деяния будут помнить.$B$BГаррош заплатит за свои злодейства!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда сила Лэй Шэня окажется в моем посохе, нас будет не остановить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леди Джайне Праудмур на Остров Грома. ',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32600,'Пророчество зандаларов','$gДорогой:Дорогая; $p!$b$bМы прочитали твои заметки о зандаларах и, кажется, я понимаю, чем вызвана их нынешняя агрессия.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите хранителю истории Чо книгу "Пророчество Зандаларов".','Неудивительно, что зандалары пришли сюда. Им нужен новый дом, а их союзники – могу – наверняка немало пообещали им. Мы внесем эту работу в твою коллекцию. Если хочешь, чтобы я прочел ее тебе, укажи на нужный том в своей личной коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчество зандаларов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $p!$b$bМы прочитали твои заметки о зандаларах и, кажется, я понимаю, чем вызвана их нынешняя агрессия.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хранителю истории Чо книгу "Пророчество Зандаларов".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неудивительно, что зандалары пришли сюда. Им нужен новый дом, а их союзники – могу – наверняка немало пообещали им. Мы внесем эту работу в твою коллекцию. Если хочешь, чтобы я прочел ее тебе, укажи на нужный том в своей личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32601,'Раскаты грома','$gДорогой:Дорогая; $p!$b$bЗловещие раскаты грома уже давно вселяют страх в мой народ. Теперь, благодаря тебе, мы знаем, что виной всему Лэй Шэнь.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо','Принесите хранителю истории Чо книгу "Раскаты грома".','Единственный наш источник знаний о Лэй Шэне – мрачные легенды, пришедшие из глубины веков. Мне всегда было интересно – не приукрашивают ли они реальность, наделяя Лэй Шэня слишком большим могуществом. Но твои исследования показали, что эти легенды недооценивали Властелина Грома. Воистину, наступили темные дни.$B$BМы добавим эти знания в твою коллекцию. Если хочешь услышать еще раз эту историю, просто укажи на нужный том в коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскаты грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $p!$b$bЗловещие раскаты грома уже давно вселяют страх в мой народ. Теперь, благодаря тебе, мы знаем, что виной всему Лэй Шэнь.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за приложенные усилия!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хранителю истории Чо книгу "Раскаты грома".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Единственный наш источник знаний о Лэй Шэне – мрачные легенды, пришедшие из глубины веков. Мне всегда было интересно – не приукрашивают ли они реальность, наделяя Лэй Шэня слишком большим могуществом. Но твои исследования показали, что эти легенды недооценивали Властелина Грома. Воистину, наступили темные дни.$B$BМы добавим эти знания в твою коллекцию. Если хочешь услышать еще раз эту историю, просто укажи на нужный том в коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32602,'Боги и монстры','$gДорогой:Дорогая; $n!$b$bНеужели могу действительно связаны с титанами? В это очень сложно поверить. Но, просмотрев твои записи, я начал понимать, что представляют из себя могу.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за усердие!$b$bС уважением,$b$bХранитель истории Чо','Принесите хранителю истории Чо книгу "Боги и монстры".','Твои находки выбили меня из колеи. Но они проливают свет на вопросы, которые давно нас интересуют: "Откуда пришли могу? И почему они были такими страшными тиранами?"$B$BМы внесем эту работу в твою коллекцию. Если хочешь, чтобы я прочел ее тебе, укажи на нужный том в своей личной коллекции.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боги и монстры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДорогой:Дорогая; $n!$b$bНеужели могу действительно связаны с титанами? В это очень сложно поверить. Но, просмотрев твои записи, я начал понимать, что представляют из себя могу.$b$bЕсли ты посетишь Обитель Мудрости в Вечноцветущем доле, мы сможем внести эту работу в твою личную коллекцию.$b$bБлагодарим за усердие!$b$bС уважением,$b$bХранитель истории Чо',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хранителю истории Чо книгу "Боги и монстры".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои находки выбили меня из колеи. Но они проливают свет на вопросы, которые давно нас интересуют: "Откуда пришли могу? И почему они были такими страшными тиранами?"$B$BМы внесем эту работу в твою коллекцию. Если хочешь, чтобы я прочел ее тебе, укажи на нужный том в своей личной коллекции.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32604,'Звери из легенд, книга I','В этих краях всегда будут рассказывать истории о Ка\'ви Проглоте, Нитуне, Кафи и Дос-Ригаре. Хочешь сразиться с ними еще раз?','Победите Ка\'ви Проглота, Нитуна, Кафи и Дос-Ригара.','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.','Вернитесь в Вечноцветущий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звери из легенд, книга I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих краях всегда будут рассказывать истории о Ка\'ви Проглоте, Нитуне, Кафи и Дос-Ригаре. Хочешь сразиться с ними еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ка\'ви Проглота, Нитуна, Кафи и Дос-Ригара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Вечноцветущий дол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32605,'Небольшой стимул','Сауроки отвратительны, но у нас есть общий враг: могу. И лучше уж я пошлю на бой с могу сауроков, чем своих собственных бойцов.$b$bМы собрали оружие могу. Вонзи эти копья в черепа сауроков. Плесни масла в огонь вражды наших противников, и ты спасешь жизни воинов Орды.','Вонзите оружие могу в трупы 9 сауроков Гнилого Клинка.','Вернитесь к Верховному магу Этасу Похитителю Солнца на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшой стимул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки отвратительны, но у нас есть общий враг: могу. И лучше уж я пошлю на бой с могу сауроков, чем своих собственных бойцов.$b$bМы собрали оружие могу. Вонзи эти копья в черепа сауроков. Плесни масла в огонь вражды наших противников, и ты спасешь жизни воинов Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вонзите оружие могу в трупы 9 сауроков Гнилого Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верховному магу Этасу Похитителю Солнца на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32606,'Небольшой стимул','Сауроки отвратительны, но у нас есть общий враг: могу. И лучше уж я пошлю на бой с могу сауроков, чем своих собственных бойцов.$b$bМы собрали оружие могу. Вонзи эти копья в черепа сауроков. Плесни масла в огонь вражды наших противников, и ты спасешь жизни воинов Альянса.','Вонзите оружие могу в трупы 9 сауроков Гнилого Клинка.','Вернитесь к верховному магу Модере на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшой стимул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сауроки отвратительны, но у нас есть общий враг: могу. И лучше уж я пошлю на бой с могу сауроков, чем своих собственных бойцов.$b$bМы собрали оружие могу. Вонзи эти копья в черепа сауроков. Плесни масла в огонь вражды наших противников, и ты спасешь жизни воинов Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вонзите оружие могу в трупы 9 сауроков Гнилого Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Модере на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32607,'Увольнение на берег... надолго','Зандалары уже начали чинить этот корабль, но мы легко можем помешать им.$B$BПросто сними нового капитана с занимаемой им должности и укради ремонтные инструкции из мастерской перед хранилищем.$B$BНикакого капитана. Никакого ремонта. Никакого корабля.','Украдите ремонтные инструкции и убейте нового капитана зандаларского боевого корабля.','Поговорите с Джайной Праудмур на Аметистовом утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увольнение на берег... надолго',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары уже начали чинить этот корабль, но мы легко можем помешать им.$B$BПросто сними нового капитана с занимаемой им должности и укради ремонтные инструкции из мастерской перед хранилищем.$B$BНикакого капитана. Никакого ремонта. Никакого корабля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите ремонтные инструкции и убейте нового капитана зандаларского боевого корабля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джайной Праудмур на Аметистовом утесе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32608,'Набег на хранилище','Отправляйтесь в Древнее хранилище и раздобудьте амулет "Колье Грома".','Это что? Ожерелье? Что ты пытаешься мне… а-а, кажется, я все поняла! Оно из сокровищницы Властелина Грома! Потрясающе… а какая сила…$B$BКирин-Тор позаботится об этом артефакте. Прими нашу скромную награду.','Сила Властелина Грома легендарна. Если мы хотим его победить, нам придется использовать для этого все возможности.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набег на хранилище',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Древнее хранилище и раздобудьте амулет "Колье Грома".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это что? Ожерелье? Что ты пытаешься мне… а-а, кажется, я все поняла! Оно из сокровищницы Властелина Грома! Потрясающе… а какая сила…$B$BКирин-Тор позаботится об этом артефакте. Прими нашу скромную награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сила Властелина Грома легендарна. Если мы хотим его победить, нам придется использовать для этого все возможности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
