INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32618,'Уроки верховой езды','Пора тебе научиться верховой езде! Найди Рандала Охотника на лесопилке Восточной долины в Элвиннском лесу. Не забудь купить себе там ездовое животное!','Найдите Рандала Охотника.','Не забудь купить себе ездовое животное, пока ты здесь! Кати Охотницу можно найти здесь же, в лагере.',' ','Найдите Рандала Охотника и научитесь верховой езде!','Рандал Охотник') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора тебе научиться верховой езде! Найди Рандала Охотника на лесопилке Восточной долины в Элвиннском лесу. Не забудь купить себе там ездовое животное!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Рандала Охотника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не забудь купить себе ездовое животное, пока ты здесь! Кати Охотницу можно найти здесь же, в лагере.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='',' ',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите Рандала Охотника и научитесь верховой езде!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Рандал Охотник',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32621,'Молниеносная сталь','Ваш наметанный глаз сразу видит, что эта стальная заготовка обладает какими-то очень странными свойствами. Может быть, что-нибудь неподалеку подскажет, в чем тут дело?','Исследуйте Кузню Грома, чтобы найти "Секреты молниеносной стали".','Язык вам незнаком, но схемы в книге вполне понятны глазу опытного кузнеца. Ясно, что, используя призрачное железо, можно создать материал огромной мощи... возможно, достаточно могущественный, чтобы воссоздать и усилить оружие, давно затерянное в туманах времени.','Найдите "Секреты молниеносной стали".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молниеносная сталь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ваш наметанный глаз сразу видит, что эта стальная заготовка обладает какими-то очень странными свойствами. Может быть, что-нибудь неподалеку подскажет, в чем тут дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте Кузню Грома, чтобы найти "Секреты молниеносной стали".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Язык вам незнаком, но схемы в книге вполне понятны глазу опытного кузнеца. Ясно, что, используя призрачное железо, можно создать материал огромной мощи... возможно, достаточно могущественный, чтобы воссоздать и усилить оружие, давно затерянное в туманах времени.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите "Секреты молниеносной стали".',`completedtext_loc8`);
