INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32627,'Заряженный моганит','Мы ежедневно посылаем лазутчиков на базу Похитителей Солнца. Некоторым был дан приказ забрать у врага заряженный моганит и принести его сюда.$b$bОни не вернулись, хотя я могу подтвердить, что на базе Похитителей Солнца их уже нет.$b$bТвоя задача – прочесать джунгли отсюда до базы и найти заряженный моганит, который потерялся в пути. Принеси его мне, и мы найдем ему отличное применение.','Найдите заряженный моганит и принесите его боевому магу Юриасу.','Замечательно. Нам этот артефакт пригодится больше, чем Похитителям Солнца.','Поговорите с боевым магом Юриасом на Аметистовом утесе, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заряженный моганит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ежедневно посылаем лазутчиков на базу Похитителей Солнца. Некоторым был дан приказ забрать у врага заряженный моганит и принести его сюда.$b$bОни не вернулись, хотя я могу подтвердить, что на базе Похитителей Солнца их уже нет.$b$bТвоя задача – прочесать джунгли отсюда до базы и найти заряженный моганит, который потерялся в пути. Принеси его мне, и мы найдем ему отличное применение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заряженный моганит и принесите его боевому магу Юриасу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Нам этот артефакт пригодится больше, чем Похитителям Солнца.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с боевым магом Юриасом на Аметистовом утесе, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32628,'Тактические мана-бомбы','Мне неприятно прибегать к такому оружию, но Похитители Солнца должны поплатиться за свои деяния.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тактические мана-бомбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне неприятно прибегать к такому оружию, но Похитители Солнца должны поплатиться за свои деяния.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
