INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32630,'Дневник главного инженера Цзарда','Какой необычный источник энергии. Интересно, как он работает? И что можно с его помощью создать?','Исследуйте Кузню Грома, чтобы найти "Секреты стабилизированных молний".','Найдите "Секреты стабилизированных молний".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник главного инженера Цзарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой необычный источник энергии. Интересно, как он работает? И что можно с его помощью создать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте Кузню Грома, чтобы найти "Секреты стабилизированных молний".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите "Секреты стабилизированных молний".',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32631,'Признание и почет','Вернитесь к боевому магу Юриасу на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Признание и почет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Юриасу на Аметистовый утес.',`completedtext_loc8`);
