INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32633,'Зачарованная книга','У Верховного магистра Роммата есть предмет, который очень мне нужен.$b$bУ него с собой могущественный фолиант. Будет лучше, если мы заберем его у Похитителей Солнца.$b$bНайди книгу магических формул Роммата и принеси ее мне.','Удалось найти книгу?','Вернитесь к боевому магу Юриасу на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованная книга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Верховного магистра Роммата есть предмет, который очень мне нужен.$b$bУ него с собой могущественный фолиант. Будет лучше, если мы заберем его у Похитителей Солнца.$b$bНайди книгу магических формул Роммата и принеси ее мне.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти книгу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Юриасу на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32634,'Вывести защиту из строя','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вывести защиту из строя',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32635,'Хватит бомб!','Похитители Солнца установили тактические мана-бомбы возле нашего лагеря. Их надо обезвредить, пока они не успели взорваться.$b$bИх надо искать в районе важных объектов – например, рядом с нашими припасами. Не пропусти ни одной мана-бомбы. Мы не должны уступать Похитителям Солнца ни одного клочка земли.','Обезвредьте тактические мана-бомбы, установленные на кораблях Альянса, а также около припасов на Аметистовом утесе и рядом с местом проведения ритуала возведения.','Вернитесь к леди Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хватит бомб!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похитители Солнца установили тактические мана-бомбы возле нашего лагеря. Их надо обезвредить, пока они не успели взорваться.$b$bИх надо искать в районе важных объектов – например, рядом с нашими припасами. Не пропусти ни одной мана-бомбы. Мы не должны уступать Похитителям Солнца ни одного клочка земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обезвредьте тактические мана-бомбы, установленные на кораблях Альянса, а также около припасов на Аметистовом утесе и рядом с местом проведения ритуала возведения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32636,'Возвращение пленников','Похитители Солнца не гнушаются самых отвратительных методов в достижении своих целей, $n.$b$bНедавно мне доложили, что несколько представителей Кирин-Тора пропали без вести. Подозреваю, что Похитители Солнца приложили к этому руку.$b$bИ лучше бы нашим пропавшим собратьям быть в добром здравии, иначе месть моя будет невероятно страшна. Я прошу тебя вернуть пропавших целыми и невредимыми, но для этого тебе нужно поторопиться.','Сегодня тебе удалось спасти многих, Тормунд. Я даже не представляю, насколько это ужасно – быть недвижимым и беспомощным в окружении врагов.','Вернитесь к леди Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение пленников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похитители Солнца не гнушаются самых отвратительных методов в достижении своих целей, $n.$b$bНедавно мне доложили, что несколько представителей Кирин-Тора пропали без вести. Подозреваю, что Похитители Солнца приложили к этому руку.$b$bИ лучше бы нашим пропавшим собратьям быть в добром здравии, иначе месть моя будет невероятно страшна. Я прошу тебя вернуть пропавших целыми и невредимыми, но для этого тебе нужно поторопиться.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня тебе удалось спасти многих, Тормунд. Я даже не представляю, насколько это ужасно – быть недвижимым и беспомощным в окружении врагов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32637,'Перегрузка','Войска Похитителей Солнца становятся все сильнее. Думаю, в этом замешана магия, но точно сказать не могу.$b$bМудрым шагом будет прочесать их лагерь в поисках дополнительного источника силы.$b$bКак найдешь, используй эти кристаллы, чтобы перегрузить источник и уничтожить его.','Выходит, они построили объекты, которые дополнительно усиливают их? Надо будет к ним присмотреться.$B$BБольшое тебе спасибо за информацию.','Вернитесь к леди Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перегрузка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Похитителей Солнца становятся все сильнее. Думаю, в этом замешана магия, но точно сказать не могу.$b$bМудрым шагом будет прочесать их лагерь в поисках дополнительного источника силы.$b$bКак найдешь, используй эти кристаллы, чтобы перегрузить источник и уничтожить его.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выходит, они построили объекты, которые дополнительно усиливают их? Надо будет к ним присмотреться.$B$BБольшое тебе спасибо за информацию.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32638,'Пожиратели маны','Иногда даже самые крохотные создания могут представлять большую угрозу.$b$bПохитители Солнца привезли с собой маназмеев. Небольшие по размеру, они, тем не менее, способны нейтрализовать наших заклинателей на время боя. Многие на собственной шкуре поняли, что их лучше не недооценивать.$b$bРасправься с ними как можно быстрее.','Убейте 9 маназмеев Похитителей Солнца.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожиратели маны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда даже самые крохотные создания могут представлять большую угрозу.$b$bПохитители Солнца привезли с собой маназмеев. Небольшие по размеру, они, тем не менее, способны нейтрализовать наших заклинателей на время боя. Многие на собственной шкуре поняли, что их лучше не недооценивать.$b$bРасправься с ними как можно быстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 маназмеев Похитителей Солнца.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (32639,'Уничтожение големов','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожение големов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32640,'Лучшие бойцы Властелина Грома','На острове таится опасность: нам угрожают повелители молний, древние духи и первобытные зандаларские чудовища. Эти три группы бойцов только и ждут, чтобы напасть на нас из засады.$B$BЕсли тебе удастся добыть ритуальные камни Шань\'цзэ, разбросанные по всему острову, ты сможешь выманить этих могущественных существ из засады и вступить с ними в бой.$B$BНайди и уничтожь врагов из каждой группы, чтобы помешать их планам, и я награжу тебя.','Вернитесь к Тажаню Чжу в Мрачную пещеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшие бойцы Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове таится опасность: нам угрожают повелители молний, древние духи и первобытные зандаларские чудовища. Эти три группы бойцов только и ждут, чтобы напасть на нас из засады.$B$BЕсли тебе удастся добыть ритуальные камни Шань\'цзэ, разбросанные по всему острову, ты сможешь выманить этих могущественных существ из засады и вступить с ними в бой.$B$BНайди и уничтожь врагов из каждой группы, чтобы помешать их планам, и я награжу тебя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу в Мрачную пещеру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32641,'Лучшие бойцы Властелина Грома','На острове таится опасность: нам угрожают три группы врагов – повелители молний, древние духи и первобытные зандаларские чудовища. Они все только и ждут, чтобы напасть на нас из засады.$B$BЕсли тебе удастся добыть ритуальные камни Шань\'цзэ, разбросанные по всему острову, ты сможешь выманить этих могущественных существ из засады и вступить с ними в бой.$B$BНайди и уничтожь врагов из каждой группы, чтобы помешать их планам, и я награжу тебя.','Вернитесь к Тажаню Чжу в Мрачную пещеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшие бойцы Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове таится опасность: нам угрожают три группы врагов – повелители молний, древние духи и первобытные зандаларские чудовища. Они все только и ждут, чтобы напасть на нас из засады.$B$BЕсли тебе удастся добыть ритуальные камни Шань\'цзэ, разбросанные по всему острову, ты сможешь выманить этих могущественных существ из засады и вступить с ними в бой.$B$BНайди и уничтожь врагов из каждой группы, чтобы помешать их планам, и я награжу тебя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу в Мрачную пещеру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32642,'Заказ: Армия Покорителей I','<Страница исписана почерком Юна. Похоже, его одолевали противоречивые чувства.>$b$bЯ стараюсь держаться в стороне от вооруженных конфликтов, но заказ есть заказ. Поскольку ты из Орды, я решил передать его тебе.$b$bАрмии Покорителей нужна партия красного лука-порея.$b$bПохоже, их бойцы жить без него не могут!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Армия Покорителей I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Страница исписана почерком Юна. Похоже, его одолевали противоречивые чувства.>$b$bЯ стараюсь держаться в стороне от вооруженных конфликтов, но заказ есть заказ. Поскольку ты из Орды, я решил передать его тебе.$b$bАрмии Покорителей нужна партия красного лука-порея.$b$bПохоже, их бойцы жить без него не могут!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32643,'Заказ: Армия Покорителей II','Когда красный лук-порей вырастет, останется только сложить его в ящик.$b$bПодумать только, этот красный лук-порей поможет нашей армии в Пандарии!','Соберите урожай с 8 растений красного лука-порея и упакуйте 40 единиц красного лука порея для Армии Покорителей.','Положите красный лук-порей в ящик. Посыльный Армии Покорителей скоро его заберет.','Пустой ящик, в который нужно положить урожай.','Положите красный лук порей в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Армия Покорителей II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда красный лук-порей вырастет, останется только сложить его в ящик.$b$bПодумать только, этот красный лук-порей поможет нашей армии в Пандарии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите урожай с 8 растений красного лука-порея и упакуйте 40 единиц красного лука порея для Армии Покорителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите красный лук-порей в ящик. Посыльный Армии Покорителей скоро его заберет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите красный лук порей в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32644,'Атака на Шаол\'мару','Благодаря усилиям разведки на побережье у нас появилась ценная информация об острове, |3-6($c).$B$BОднако мы ничего не достигнем, если не начнем продвигаться вглубь суши.$B$BЯ собрала команду лучших бойцов из наших воздушных отрядов.$B$BЯ бы хотела, чтобы ты $gприсоединился:присоединилась; к нападению. Такой герой, как ты, может переломить ход боя в нашу пользу в решающий момент.$B$BКогда будешь $gготов:готова; к атаке, поговори со мной.','Завершите сценарий "Атака на Шаол\'мару". Поговорите с Джайной Праудмур, чтобы начать атаку.','Да, герой! У тебя получилось!$B$BТеперь Властелин Грома познает всю мощь Кирин-Тора!','Вернитесь к Джайне Праудмур на Аметистовый утес, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на Шаол\'мару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря усилиям разведки на побережье у нас появилась ценная информация об острове, |3-6($c).$B$BОднако мы ничего не достигнем, если не начнем продвигаться вглубь суши.$B$BЯ собрала команду лучших бойцов из наших воздушных отрядов.$B$BЯ бы хотела, чтобы ты $gприсоединился:присоединилась; к нападению. Такой герой, как ты, может переломить ход боя в нашу пользу в решающий момент.$B$BКогда будешь $gготов:готова; к атаке, поговори со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завершите сценарий "Атака на Шаол\'мару". Поговорите с Джайной Праудмур, чтобы начать атаку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, герой! У тебя получилось!$B$BТеперь Властелин Грома познает всю мощь Кирин-Тора!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32645,'Заказ: операция "Заслон" I','<Страница исписана почерком Юна. Похоже, его одолевали противоречивые чувства.>$b$bЯ стараюсь держаться в стороне от вооруженных конфликтов, но заказ есть заказ. Поскольку ты из Альянса, я решил передать его тебе.$b$bОперации "Заслон" нужно много ведьминых ягод.$b$bТочно не знаю, но, кажется, они собираются использовать их в качестве оружия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: операция "Заслон" I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Страница исписана почерком Юна. Похоже, его одолевали противоречивые чувства.>$b$bЯ стараюсь держаться в стороне от вооруженных конфликтов, но заказ есть заказ. Поскольку ты из Альянса, я решил передать его тебе.$b$bОперации "Заслон" нужно много ведьминых ягод.$b$bТочно не знаю, но, кажется, они собираются использовать их в качестве оружия.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32646,'Заказ: операция "Заслон" II','Когда ведьмины ягоды вырастут, останется только сложить их в ящик.$b$bПодумать только, эти ведьмины ягоды помогут нашим силам в Пандарии!','Соберите урожай с 8 кустов ведьминых ягод и передайте 40 ведьминых ягод операции "Заслон".','Положите ведьмины ягоды в ящик. Скоро за ним придет посыльный операции "Заслон".','Пустой ящик, в который нужно положить урожай.','Положите ведьмины ягоды в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: операция "Заслон" II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда ведьмины ягоды вырастут, останется только сложить их в ящик.$b$bПодумать только, эти ведьмины ягоды помогут нашим силам в Пандарии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите урожай с 8 кустов ведьминых ягод и передайте 40 ведьминых ягод операции "Заслон".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите ведьмины ягоды в ящик. Скоро за ним придет посыльный операции "Заслон".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите ведьмины ягоды в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32647,'Заказ: Золотой Лотос I','<Этот заказ Юн изложил кратко.>$b$bЗолотой Лотос попросил огромное количество белой репы.$b$bВ тексте заказа говорилось о злых духах, которые устроили беспорядки в деревне Туманного Водопада. Судя по всему, духи не любят репу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Золотой Лотос I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Этот заказ Юн изложил кратко.>$b$bЗолотой Лотос попросил огромное количество белой репы.$b$bВ тексте заказа говорилось о злых духах, которые устроили беспорядки в деревне Туманного Водопада. Судя по всему, духи не любят репу!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32648,'Заказ: Золотой Лотос II','Будем надеяться, урожай им понравится!$b$bКогда эта белая репа созреет, ее надо будет лишь сложить в ящик.','Соберите 8 спелых белых реп и приготовьте 40 белых реп для Золотого Лотоса.','Положите белую репу в ящик. Скоро за ней придет посыльный Золотого Лотоса.','Пустой ящик, в который нужно положить урожай.','Поместите белую репу в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Золотой Лотос II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будем надеяться, урожай им понравится!$b$bКогда эта белая репа созреет, ее надо будет лишь сложить в ящик.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 спелых белых реп и приготовьте 40 белых реп для Золотого Лотоса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите белую репу в ящик. Скоро за ней придет посыльный Золотого Лотоса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поместите белую репу в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32649,'Заказ: Шадо-Пан I') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Шадо-Пан I',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32650,'Заказ: Шадо-Пан II','Аккуратно положите капусту кале в ящик. Скоро за ней придет посыльный Шадо-Пан.','Пустой ящик, в который нужно положить урожай.','Поместите капусту кале в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Шадо-Пан II',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аккуратно положите капусту кале в ящик. Скоро за ней придет посыльный Шадо-Пан.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поместите капусту кале в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
