INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32652,'В небо!','С помощью террокрыла, которого ты $gнашел:нашла; у зандаларов, мы сможем нанести могу решающий удар и лишить их возможности продолжать изготавливать оружие.\r\n\r\nСкажи мне, когда будешь $gготов:готова;.','Проникните в Шахту Молний.','Превосходная работа. У нас появился просто грандиозный шанс.','Вернитесь к Джайне Праудмур на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В небо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью террокрыла, которого ты $gнашел:нашла; у зандаларов, мы сможем нанести могу решающий удар и лишить их возможности продолжать изготавливать оружие.\r\n\r\nСкажи мне, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните в Шахту Молний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходная работа. У нас появился просто грандиозный шанс.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32653,'Заказ: Августейшие Небожители I','<Ветхая бумага испещрена знакомым почерком Юна.>$b$bУченикам из Колыбели Чи-Цзи нужны полосатые дыни. По всей видимости, для упражнений.$b$bЗавтра от них прибудет посыльный. Отдай ему столько дынь, сколько сможешь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Августейшие Небожители I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Ветхая бумага испещрена знакомым почерком Юна.>$b$bУченикам из Колыбели Чи-Цзи нужны полосатые дыни. По всей видимости, для упражнений.$b$bЗавтра от них прибудет посыльный. Отдай ему столько дынь, сколько сможешь.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32654,'Разрушить эту стену!','Итак, время пришло. Мы достаточно укрепились здесь, и теперь можно попытаться перейти в наступление и направиться прямо в логово Властелина Грома. К сожалению, в ближайшее время он вряд ли планирует открыть для нас ворота.$b$bПолагаю, нам придется принять роль незваных гостей и открыть эти ворота самостоятельно. Дай мне знать, когда будешь $gготов:готова;, $n.','Поговорите с леди Джайной Праудмур, а затем займите нижний город и обеспечьте там безопасность для войск Альянса.','Благодаря твоей помощи мы сделали огромный шаг к нашей цели.','Вернитесь к леди Джайне Праудмур на Остров Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушить эту стену!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, время пришло. Мы достаточно укрепились здесь, и теперь можно попытаться перейти в наступление и направиться прямо в логово Властелина Грома. К сожалению, в ближайшее время он вряд ли планирует открыть для нас ворота.$b$bПолагаю, нам придется принять роль незваных гостей и открыть эти ворота самостоятельно. Дай мне знать, когда будешь $gготов:готова;, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с леди Джайной Праудмур, а затем займите нижний город и обеспечьте там безопасность для войск Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря твоей помощи мы сделали огромный шаг к нашей цели.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Остров Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32655,'Смелая идея','Зандаларские боевые корабли бороздят воды вокруг острова. На них перевозят солдат и боевых зверей, которые вступают в армию Лэй Шэня.$B$BЕсли нам удастся захватить пристань, то мы перекроем пути снабжения Властелина Грома и создадим вам надежный плацдарм.$B$BУ меня есть план действий, и большая армия нам вовсе не потребуется.','Проникните на Пристань Бушующих Волн и откройте ворота изнутри. Поговорите с Таоши, чтобы начать задание.','Обратитесь к Джайне Праудмур на Аметистовом утесе, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смелая идея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандаларские боевые корабли бороздят воды вокруг острова. На них перевозят солдат и боевых зверей, которые вступают в армию Лэй Шэня.$B$BЕсли нам удастся захватить пристань, то мы перекроем пути снабжения Властелина Грома и создадим вам надежный плацдарм.$B$BУ меня есть план действий, и большая армия нам вовсе не потребуется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проникните на Пристань Бушующих Волн и откройте ворота изнутри. Поговорите с Таоши, чтобы начать задание.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обратитесь к Джайне Праудмур на Аметистовом утесе, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32656,'Падение Шань-Бу','Давным-давно Лэй Шэнь обнаружил редкую кладку драконьих яиц. Из одного вылупился невероятно злобный дракон, который пожрал своих укротителей. Тогда Лэй Шэнь забрал его к себе.\r\n\r\nТеперь Шань-Бу, один из верных прислужников императора, пытается воскресить этого дракона. У нас появился шанс одолеть Шань-Бу!\r\n\r\nДай мне знать, когда мы можем выступать!','Победите Шань-Бу.','Вернитесь к Джайне Праудмур на Аметистовый утес, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Шань-Бу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Лэй Шэнь обнаружил редкую кладку драконьих яиц. Из одного вылупился невероятно злобный дракон, который пожрал своих укротителей. Тогда Лэй Шэнь забрал его к себе.\r\n\r\nТеперь Шань-Бу, один из верных прислужников императора, пытается воскресить этого дракона. У нас появился шанс одолеть Шань-Бу!\r\n\r\nДай мне знать, когда мы можем выступать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Шань-Бу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джайне Праудмур на Аметистовый утес, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32657,'Заказ: Августейшие Небожители II','Когда полосатые дыни вырастут, останется только сложить их в ящик.$b$bСкоро за ним придет ученик из Колыбели Чи-Цзи.','Положите полосатые дыни в этот ящик. Августейшие Небожители будут довольны.','Пустой ящик, в который нужно положить урожай.','Положите полосатые дыни в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Августейшие Небожители II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда полосатые дыни вырастут, останется только сложить их в ящик.$b$bСкоро за ним придет ученик из Колыбели Чи-Цзи.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите полосатые дыни в этот ящик. Августейшие Небожители будут довольны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите полосатые дыни в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (32658,'Заказ: Клакси I','<Разобрать почерк Юна не слишком просто, но приятно осознавать, что он все еще участвует в делах фермы.>$b$bСегодня утром пришел заказ от клакси. Они потребовали для каких-то исследований тыквы могу.$b$bЯ считаю, что лучше не задавать им лишних вопросов...$b$bЛучше принимайся за работу. В противном случаев не хочу даже и думать о том, что насекомые такого размера могут сделать с твоими посевами!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Клакси I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Разобрать почерк Юна не слишком просто, но приятно осознавать, что он все еще участвует в делах фермы.>$b$bСегодня утром пришел заказ от клакси. Они потребовали для каких-то исследований тыквы могу.$b$bЯ считаю, что лучше не задавать им лишних вопросов...$b$bЛучше принимайся за работу. В противном случаев не хочу даже и думать о том, что насекомые такого размера могут сделать с твоими посевами!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32659,'Заказ: Клакси II','Когда тыквы могу вырастут, останется только сложить их в ящик.$b$bИ не стоит слишком мешкать. Клакси не отличаются терпением!','Соберите 8 спелых тыкв могу и упакуйте 40 тыкв могу для Клакси.','Положите тыквы могу в ящик. Скоро за ним придет посыльный клакси.','Пустой ящик, в который нужно положить урожай.','Положите тыквы могу в пустой ящик на ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Клакси II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда тыквы могу вырастут, останется только сложить их в ящик.$b$bИ не стоит слишком мешкать. Клакси не отличаются терпением!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 спелых тыкв могу и упакуйте 40 тыкв могу для Клакси.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите тыквы могу в ящик. Скоро за ним придет посыльный клакси.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите тыквы могу в пустой ящик на ферме Солнечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`questgivertargetname_loc8`) VALUES (32661,'Уроки верховой езды','Не забудь купить скакуна, пока ты здесь. Тораллиус стоит вон там.','Аалун') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не забудь купить скакуна, пока ты здесь. Тораллиус стоит вон там.',`offerrewardtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Аалун',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32662,'Уроки верховой езды','Пора тебе научиться ездить верхом! Найди Ультама на Ферме Янтарленов в Дун Мороге, это у дороги к востоку от Стальгорна. И не забудь купить себе скакуна, пока будешь там.','Найдите Ультама Громового Рога.','Не забудь купить скакуна, пока ты здесь. Верон Янтарлен стоит у ворот фермы.','Найди Ультама Громового Рога и научись ездить верхом.','Ультам Громовой Рог') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора тебе научиться ездить верхом! Найди Ультама на Ферме Янтарленов в Дун Мороге, это у дороги к востоку от Стальгорна. И не забудь купить себе скакуна, пока будешь там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ультама Громового Рога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не забудь купить скакуна, пока ты здесь. Верон Янтарлен стоит у ворот фермы.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найди Ультама Громового Рога и научись ездить верхом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Ультам Громовой Рог',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32663,'Уроки верховой езды','Пора тебе научиться ездить верхом! Найди Бинджи Перосвиста в поселке Сталежара в Дун Мороге. И не забудь купить себе скакуна, пока будешь там.','Найдите Бинджи Перосвиста.','Не забудь купить скакуна, пока ты здесь. Милли стоит вон там.','Найди Бинджи Перосвиста и научись ездить верхом.','Бинджи Перосвист') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уроки верховой езды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора тебе научиться ездить верхом! Найди Бинджи Перосвиста в поселке Сталежара в Дун Мороге. И не забудь купить себе скакуна, пока будешь там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бинджи Перосвиста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не забудь купить скакуна, пока ты здесь. Милли стоит вон там.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найди Бинджи Перосвиста и научись ездить верхом.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бинджи Перосвист',`questgivertargetname_loc8`);
