INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32674,'Я верю, что ты можешь летать','Небеса взывают к вам! Пришло время научиться летать!\r\n\r\nНаправляйтесь на летную площадку, что в Оргриммаре, и найдите там Мазту, летного инструктора.\r\n\r\nИ не забудьте приобрести летающее средство передвижения!','Найдите Мазту.','О, рада тебя видеть. Похоже, ты уже готов бросить вызов небесам!$B$BПомни, ты можешь приобрести летающее средство передвижения у Дракмы, который стоит прямо за мной.','Найдите Мазту и научитесь летать!','Мазта') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я верю, что ты можешь летать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небеса взывают к вам! Пришло время научиться летать!\r\n\r\nНаправляйтесь на летную площадку, что в Оргриммаре, и найдите там Мазту, летного инструктора.\r\n\r\nИ не забудьте приобрести летающее средство передвижения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мазту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, рада тебя видеть. Похоже, ты уже готов бросить вызов небесам!$B$BПомни, ты можешь приобрести летающее средство передвижения у Дракмы, который стоит прямо за мной.',`offerrewardtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите Мазту и научитесь летать!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Мазта',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32675,'Я верю, что ты можешь летать','Небеса взывают к вам! Пришло время научиться летать!\r\n\r\nНаправляйтесь на грифоний насест, что в Штормграде, и найдите там Браллу Дымокрыл, летного инструктора.\r\n\r\nИ не забудьте приобрести летающее средство передвижения!','Найдите Браллу Дымокрыл.','Найдите Браллу Дымокрыл и научитесь летать!','Бралла Дымокрыл') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я верю, что ты можешь летать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небеса взывают к вам! Пришло время научиться летать!\r\n\r\nНаправляйтесь на грифоний насест, что в Штормграде, и найдите там Браллу Дымокрыл, летного инструктора.\r\n\r\nИ не забудьте приобрести летающее средство передвижения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Браллу Дымокрыл.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Найдите Браллу Дымокрыл и научитесь летать!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Бралла Дымокрыл',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32676,'Увольнение на берег... надолго','Зандалары уже начали чинить этот корабль, но мы легко можем помешать им.$B$BПросто сними нового капитана с занимаемой им должности и укради ремонтные инструкции из мастерской перед хранилищем.$B$BНикакого капитана. Никакого ремонта. Никакого корабля.','Украдите ремонтные инструкции и убейте нового капитана боевого корабля зандаларов.','Поговорите с Лор\'темаром Тероном на Мысе Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Увольнение на берег... надолго',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандалары уже начали чинить этот корабль, но мы легко можем помешать им.$B$BПросто сними нового капитана с занимаемой им должности и укради ремонтные инструкции из мастерской перед хранилищем.$B$BНикакого капитана. Никакого ремонта. Никакого корабля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите ремонтные инструкции и убейте нового капитана боевого корабля зандаларов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном на Мысе Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32677,'Набег на хранилище','В Древнем хранилище содержатся самые страшные орудия Лэй Шэня и самые ценные для него вещи. Зачастую один и тот же предмет представляет собой и то, и другое. Кто бы мог подумать.$B$BВ частности, меня интересует один артефакт – амулет под названием "Колье Грома". Раздобыв этот артефакт, мы сможем понять, каким образом ему удается контролировать силу молний.$B$BОтправляйся в это хранилище и убей смотрителя. Завладей его ключом, и тогда ты сможешь достать амулет из тайника, который находится в задней части хранилища.','Отправляйтесь в Древнее хранилище и раздобудьте амулет "Колье Грома".','Надеюсь, у тебя хорошие новости.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набег на хранилище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Древнем хранилище содержатся самые страшные орудия Лэй Шэня и самые ценные для него вещи. Зачастую один и тот же предмет представляет собой и то, и другое. Кто бы мог подумать.$B$BВ частности, меня интересует один артефакт – амулет под названием "Колье Грома". Раздобыв этот артефакт, мы сможем понять, каким образом ему удается контролировать силу молний.$B$BОтправляйся в это хранилище и убей смотрителя. Завладей его ключом, и тогда ты сможешь достать амулет из тайника, который находится в задней части хранилища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Древнее хранилище и раздобудьте амулет "Колье Грома".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, у тебя хорошие новости.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`questgivertargetname_loc8`) VALUES (32678,'Гром и молния','Явитесь к капитану разведчиков Эльсии в гарнизон Шадо-Пан, что в Танлунских степях.','Капитан разведчиков Эльсия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гром и молния',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к капитану разведчиков Эльсии в гарнизон Шадо-Пан, что в Танлунских степях.',`objectives_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Капитан разведчиков Эльсия',`questgivertargetname_loc8`);
