INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32680,'Надвигается буря','Нельзя терять ни минуты, $n. С каждым мигом Джайна и Кирин-Тор все увереннее чувствуют себя на острове, и от них становится все сложнее избавиться.$b$bЛор\'темар ждет нас. Поговори со мной, когда будешь $gготов:готова; отправляться. Я самолично буду сопровождать тебя.','Поговорите с Лор\'темаром Тероном на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надвигается буря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя терять ни минуты, $n. С каждым мигом Джайна и Кирин-Тор все увереннее чувствуют себя на острове, и от них становится все сложнее избавиться.$b$bЛор\'темар ждет нас. Поговори со мной, когда будешь $gготов:готова; отправляться. Я самолично буду сопровождать тебя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лор\'темаром Тероном на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32681,'Надвигается буря','Нельзя терять ни минуты, $n. С каждым мигом Похитители Солнца все увереннее чувствуют себя на острове, и от них становится все сложнее избавиться.$b$bЛеди Джайна Праудмур ждет нас. Поговори со мной, когда будешь $gготов:готова; отправляться. Я самолично буду сопровождать тебя.','Поговорите с леди Джайной Праудмур на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надвигается буря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя терять ни минуты, $n. С каждым мигом Похитители Солнца все увереннее чувствуют себя на острове, и от них становится все сложнее избавиться.$b$bЛеди Джайна Праудмур ждет нас. Поговори со мной, когда будешь $gготов:готова; отправляться. Я самолично буду сопровождать тебя.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с леди Джайной Праудмур на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32682,'Наследники земли','Как ты знаешь, $n, годы берут свое. Невозможно всегда оставаться молодым и полным сил.$B$BЯ ищу того, кому можно передать мои обязанности в совете земледельцев, и мне кажется, что лучшая кандидатура – это фермер Юн.$B$BЕму еще многому предстоит научиться, но у него светлая голова, и, что еще важнее, доброе сердце.$B$BКак думаешь, он согласится?','Поговорите с фермером Юном.','Он согласился? Так и знал, что ты сможешь его убедить, Теньвойны. Теперь я могу жить спокойно, зная, что Союз Земледельцев в надежных руках.','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследники земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты знаешь, $n, годы берут свое. Невозможно всегда оставаться молодым и полным сил.$B$BЯ ищу того, кому можно передать мои обязанности в совете земледельцев, и мне кажется, что лучшая кандидатура – это фермер Юн.$B$BЕму еще многому предстоит научиться, но у него светлая голова, и, что еще важнее, доброе сердце.$B$BКак думаешь, он согласится?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с фермером Юном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он согласился? Так и знал, что ты сможешь его убедить, Теньвойны. Теперь я могу жить спокойно, зная, что Союз Земледельцев в надежных руках.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нане Грязный Коготь в Полугорье, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32683,'Так ты хочешь быть кузнецом...','Хорошо узнавать свойства более простых разновидностей металла и постепенно развивать свои навыки, но можно стать хорошим кузнецом, делая различные вещи из призрачного железа. Если хочешь избрать этот путь, чтобы достичь уровня дзен-мастера кузнечного дела, я могу кое-чему научить тебя. Но сначала покажи мне, что ты уже умеешь – создай призрачную отмычку.','Создайте призрачную отмычку, достигнув уровня навыка кузнечного дела, равного 500, и принесите эту вещь своему учителю. Если вы хотите совершенствоваться, используя пандаренские материалы, изучите соответствующие вашему уровню учебные чертежи у Куллена Хмуроброва.','Очень хорошо. Теперь ты готов стать дзен-мастером кузнечного дела.','Ну как, учишься понемногу?','Создайте призрачную отмычку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так ты хочешь быть кузнецом...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо узнавать свойства более простых разновидностей металла и постепенно развивать свои навыки, но можно стать хорошим кузнецом, делая различные вещи из призрачного железа. Если хочешь избрать этот путь, чтобы достичь уровня дзен-мастера кузнечного дела, я могу кое-чему научить тебя. Но сначала покажи мне, что ты уже умеешь – создай призрачную отмычку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте призрачную отмычку, достигнув уровня навыка кузнечного дела, равного 500, и принесите эту вещь своему учителю. Если вы хотите совершенствоваться, используя пандаренские материалы, изучите соответствующие вашему уровню учебные чертежи у Куллена Хмуроброва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Теперь ты готов стать дзен-мастером кузнечного дела.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, учишься понемногу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Создайте призрачную отмычку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32684,'Хочешь рыбки?','Тебе нужен золотистый карп? Или другая пандаренская рыба? Сама-то я не рыбачка, но у реки есть паренек, он учит всех желающих. Поговори с ним, может быть, он поделится с тобой рыбой и научит рыбачить.','Поговорите с Беном Трубноголосым.','А! Ты хочешь научиться рыбачить? Я как раз тот, кто тебе нужен. Но для начала вот – немного рыбы!','Поговорите с Беном Трубноголосым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хочешь рыбки?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужен золотистый карп? Или другая пандаренская рыба? Сама-то я не рыбачка, но у реки есть паренек, он учит всех желающих. Поговори с ним, может быть, он поделится с тобой рыбой и научит рыбачить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Беном Трубноголосым.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Ты хочешь научиться рыбачить? Я как раз тот, кто тебе нужен. Но для начала вот – немного рыбы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Беном Трубноголосым.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32685,'Удочка больше не нужна!','Воды рек и озер Пандарии буквально кишат рыбой! Теперь тебе даже не нужна удочка: главное, не прозевать нужный момент. Попробуй и увидишь!','Поймайте 5 золотистых карпов. Чтобы закинуть удочку, щелкните по значку рыбалки на вкладке профессий. Внимательно наблюдайте за поплавком: щелкните по нему, когда он задергается, и вытащите улов из воды. ','Давай-ка поглядим... Да, отличные рыбки. Молодец! Вот, возьми еще.','Поймайте 5 золотистых карпов без удочки!','Поймайте 5 золотистых карпов без удочки!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удочка больше не нужна!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воды рек и озер Пандарии буквально кишат рыбой! Теперь тебе даже не нужна удочка: главное, не прозевать нужный момент. Попробуй и увидишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 золотистых карпов. Чтобы закинуть удочку, щелкните по значку рыбалки на вкладке профессий. Внимательно наблюдайте за поплавком: щелкните по нему, когда он задергается, и вытащите улов из воды. ',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай-ка поглядим... Да, отличные рыбки. Молодец! Вот, возьми еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поймайте 5 золотистых карпов без удочки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поймайте 5 золотистых карпов без удочки!',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32686,'Безупречное знамя империи богомолов','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.','Выставите артефакт на обозрение.','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.','Уберите хлам и выставите артефакт на обозрение.','Выставите артефакт в Обители Мудрости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречное знамя империи богомолов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выставите артефакт на обозрение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уберите хлам и выставите артефакт на обозрение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выставите артефакт в Обители Мудрости.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32687,'Безупречный древний сборник сока','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.','Выставите артефакт на обозрение.','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.','Уберите хлам и выставите артефакт на обозрение.','Выставите артефакт в Обители Мудрости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречный древний сборник сока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Артефакт был восстановлен в прекрасном состоянии. Возможно, стоит выставить его в Обители Мудрости, чтобы археологи и хранители истории смогли изучить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выставите артефакт на обозрение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это поможет археологам и хранителям истории лучше понимать историю Пандарии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уберите хлам и выставите артефакт на обозрение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Выставите артефакт в Обители Мудрости.',`completedtext_loc8`);
