INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32706,'Союзники, скрывающиеся в тенях','Шадо-Паны прибыли сюда еще до нас, и они уже сражаются с силами Властелина Грома.$B$BЯ хочу, чтобы ты $gвстретился:встретилась; с Тажанем Чжу, предводителем Шадо-Панов. Предложи ему помощь от Кирин-Тора. Я не думаю, что он остро нуждается в этой помощи, но это предложение станет жестом доброй воли и благих намерений.','Поговорите с Тажанем Чжу в Мрачной пещере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзники, скрывающиеся в тенях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шадо-Паны прибыли сюда еще до нас, и они уже сражаются с силами Властелина Грома.$B$BЯ хочу, чтобы ты $gвстретился:встретилась; с Тажанем Чжу, предводителем Шадо-Панов. Предложи ему помощь от Кирин-Тора. Я не думаю, что он остро нуждается в этой помощи, но это предложение станет жестом доброй воли и благих намерений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тажанем Чжу в Мрачной пещере.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32707,'Есть у меня одна просьба, |3-6($c).$B$BК нам в руки попал могущественный ритуальный камень, который могу Шань\'цзэ использовали, чтобы призывать в бой своих союзников, но для совершения ритуала одного камня недостаточно.$B$BЕсли найдешь еще три таких камня, принеси их мне. Мы сможем сконцентрировать свои силы и использовать камни, чтобы заманить самых могущественных слуг Лэй Шэня прямо в наши ловушки.','Найдите три ритуальных камня Шань\'цзэ. Эти камни – большая редкость, на то, чтобы найти их, может уйти немало времени.','Отлично. Я покажу тебе, как использовать эти камни, и ты сможешь организовать засаду.','Удалось найти камни, о которых мы говорили?','Вернитесь к Тажаню Чжу в Мрачную пещеру.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть у меня одна просьба, |3-6($c).$B$BК нам в руки попал могущественный ритуальный камень, который могу Шань\'цзэ использовали, чтобы призывать в бой своих союзников, но для совершения ритуала одного камня недостаточно.$B$BЕсли найдешь еще три таких камня, принеси их мне. Мы сможем сконцентрировать свои силы и использовать камни, чтобы заманить самых могущественных слуг Лэй Шэня прямо в наши ловушки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите три ритуальных камня Шань\'цзэ. Эти камни – большая редкость, на то, чтобы найти их, может уйти немало времени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Я покажу тебе, как использовать эти камни, и ты сможешь организовать засаду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти камни, о которых мы говорили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу в Мрачную пещеру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32708,'Ловушка для могу','Отнеси эти 3 ритуальных камня в то место, которое я отметил на карте. Там ты увидишь место проведения ритуала Шань\'цзэ, отмеченное ритуальным предметом. Используй его, чтобы привлечь внимание одного из могущественных представителей Шань\'цзэ.$B$BНо учти, что одному туда ходить опасно. Тебе предстоит столкнуться с одним из самых могущественных слуг Властелина Грома, поэтому возьми с собой надежных друзей.$B$BИ когда ты встретишься с врагом, будь $gбеспощаден:беспощадна;.','Используйте 3 ритуальных камня Шань\'цзэ, чтобы привлечь внимание защитника Властелина Грома, а затем убейте его.','Очень впечатляет.$B$BЕсли тебе удастся найти больше союзников, можно будет организовать еще больше подобных засад. Враги не сразу смогут понять, что мы действуем таким хитрым способом.','Вернитесь к Тажаню Чжу в Мрачную пещеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка для могу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси эти 3 ритуальных камня в то место, которое я отметил на карте. Там ты увидишь место проведения ритуала Шань\'цзэ, отмеченное ритуальным предметом. Используй его, чтобы привлечь внимание одного из могущественных представителей Шань\'цзэ.$B$BНо учти, что одному туда ходить опасно. Тебе предстоит столкнуться с одним из самых могущественных слуг Властелина Грома, поэтому возьми с собой надежных друзей.$B$BИ когда ты встретишься с врагом, будь $gбеспощаден:беспощадна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте 3 ритуальных камня Шань\'цзэ, чтобы привлечь внимание защитника Властелина Грома, а затем убейте его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень впечатляет.$B$BЕсли тебе удастся найти больше союзников, можно будет организовать еще больше подобных засад. Враги не сразу смогут понять, что мы действуем таким хитрым способом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тажаню Чжу в Мрачную пещеру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32709,'Союзники, скрывающиеся в тенях','Шадо-Паны прибыли сюда еще до нас, и они уже сражаются с силами Властелина Грома.$B$BЯ хочу, чтобы ты $gвстретился:встретилась; с Тажанем Чжу, предводителем Шадо-Панов. Предложи ему помощь от Похитителей Солнца. Я не думаю, что он остро нуждается в этой помощи, но это предложение станет жестом доброй воли и благих намерений.','Поговорите с Тажанем Чжу в Мрачной пещере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзники, скрывающиеся в тенях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шадо-Паны прибыли сюда еще до нас, и они уже сражаются с силами Властелина Грома.$B$BЯ хочу, чтобы ты $gвстретился:встретилась; с Тажанем Чжу, предводителем Шадо-Панов. Предложи ему помощь от Похитителей Солнца. Я не думаю, что он остро нуждается в этой помощи, но это предложение станет жестом доброй воли и благих намерений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тажанем Чжу в Мрачной пещере.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32710,'Я чую неприятности!','Вы улавливаете сильный запах, который доносится откуда-то в вашем направлении. Желудок сводит от густой тошнотворной вони, наполняющей ваши ноздри.$b $bЗапах знаком вам: так пахнет саурок. Это запах гниющей плоти саурока с легкими нотками выгребной ямы.','Найдите и убейте Мясо\'рока Прокаженного.','Мясо\'рок булькает и стонет в отдалении.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я чую неприятности!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы улавливаете сильный запах, который доносится откуда-то в вашем направлении. Желудок сводит от густой тошнотворной вони, наполняющей ваши ноздри.$b $bЗапах знаком вам: так пахнет саурок. Это запах гниющей плоти саурока с легкими нотками выгребной ямы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте Мясо\'рока Прокаженного.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Мясо\'рок булькает и стонет в отдалении.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32711,'Агония и анима','Вы замечаете инициалы П.Р.К., каллиграфически выведенные на боку Анимуса.$b$bПеред вами – создатель Анимуса, предводитель ритуалистов Келад. По приказу Властелина Грома Лэй Шэня Келад без устали трудился, чтобы придумать идеальное воплощение для анимы. Что-то функциональное, величественное, наделенное сознанием, но самое главное – смертоносное.$b$bНужно остановить его, пока Властелин Грома не воплотил в жизнь его новую идею.','Убейте предводителя ритуалистов Келада.','Предводитель ритуалистов Келад смотрит на вас с негодованием.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агония и анима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы замечаете инициалы П.Р.К., каллиграфически выведенные на боку Анимуса.$b$bПеред вами – создатель Анимуса, предводитель ритуалистов Келад. По приказу Властелина Грома Лэй Шэня Келад без устали трудился, чтобы придумать идеальное воплощение для анимы. Что-то функциональное, величественное, наделенное сознанием, но самое главное – смертоносное.$b$bНужно остановить его, пока Властелин Грома не воплотил в жизнь его новую идею.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте предводителя ритуалистов Келада.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Предводитель ритуалистов Келад смотрит на вас с негодованием.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32712,'Зао\'чо Кровожадный','Вы слышите треск электрических зарядов, и чувствуете, как ток пощипывает уши и пробегает по позвоночнику. Когда вы подходите к двери, ваши пальцы немеют, а сердце начинает биться в два раза быстрее.$b$bЗао\'чо стоит наверху лестницы, плетя молнию между пальцев, по его лицу блуждает безумная ухмылка.','Убейте Зао\'чо.','Смотреть на молнию в глазах Зао\'чо так же больно, как на солнце.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зао\'чо Кровожадный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы слышите треск электрических зарядов, и чувствуете, как ток пощипывает уши и пробегает по позвоночнику. Когда вы подходите к двери, ваши пальцы немеют, а сердце начинает биться в два раза быстрее.$b$bЗао\'чо стоит наверху лестницы, плетя молнию между пальцев, по его лицу блуждает безумная ухмылка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зао\'чо.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Смотреть на молнию в глазах Зао\'чо так же больно, как на солнце.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32713,'Камни губят все живое','Невозможно описать словами невыразимый ужас, который внушает лавина камня, костей и крови, неумолимо и бездушно сносящая все на вашем пути...$b $bЧудовищные землетрясения раскалывают пустую оболочку земли, и лишь хаос и разрушение царят там, где побывало это существо. Похоже, оно не догадывается о твоем присутствии.','Уничтожьте скальный ужас.','В древние времена такому существу бы поклонялись, считая его одним из младших богов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни губят все живое',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Невозможно описать словами невыразимый ужас, который внушает лавина камня, костей и крови, неумолимо и бездушно сносящая все на вашем пути...$b $bЧудовищные землетрясения раскалывают пустую оболочку земли, и лишь хаос и разрушение царят там, где побывало это существо. Похоже, оно не догадывается о твоем присутствии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте скальный ужас.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','В древние времена такому существу бы поклонялись, считая его одним из младших богов.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32714,'Приручение бури','Вдалеке вы слышите воинственный крик. Вы видите темную фигуру, которую окружают вихрящиеся и потрескивающие облака. Вспыхивает молния, и перед вами появляется Но\'ку Буревестник, насмешливо глядящий прямо на вас.','Убейте Но\'ку Буревестника.','Когда Но\'ку проходит через двор, от его ступней расходятся ветвящиеся молнии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вдалеке вы слышите воинственный крик. Вы видите темную фигуру, которую окружают вихрящиеся и потрескивающие облака. Вспыхивает молния, и перед вами появляется Но\'ку Буревестник, насмешливо глядящий прямо на вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Но\'ку Буревестника.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Когда Но\'ку проходит через двор, от его ступней расходятся ветвящиеся молнии.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32715,'Реквием по королеве','Вы ощущаете уколы холодного ветра, в котором чувствуется печаль. Ваше сердце замирает, когда вы слышите слабые, мелодичные всхлипы Монары, последней королевы могу.$b$bВы чувствуете ее скорбь, и призрачная рука, сотканная из воздуха, тянется к вашему сердцу. Как только она касается его, перед вашими глазами встает картина последних моментов жизни Монары... ее жестокого убийства Лэй Шэнем.$b$bМонара всхлипывает в темноте все громче и громче, печальнее и печальнее...','Упокойте Монару.','Монара, последняя известная королева могу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реквием по королеве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы ощущаете уколы холодного ветра, в котором чувствуется печаль. Ваше сердце замирает, когда вы слышите слабые, мелодичные всхлипы Монары, последней королевы могу.$b$bВы чувствуете ее скорбь, и призрачная рука, сотканная из воздуха, тянется к вашему сердцу. Как только она касается его, перед вашими глазами встает картина последних моментов жизни Монары... ее жестокого убийства Лэй Шэнем.$b$bМонара всхлипывает в темноте все громче и громче, печальнее и печальнее...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Упокойте Монару.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Монара, последняя известная королева могу.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`) VALUES (32716,'Глаза Властелина Грома','Туман вокруг павших скрытней расступается, и вы слышите внезапный грохот.$b$bКамни, блокирующие вход в стоки, падают на находящуюся внизу жидкость, а из темноты появляются четыре гниющих глаза.','Победите засаду!','Немигающий глаз подергивается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза Властелина Грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Туман вокруг павших скрытней расступается, и вы слышите внезапный грохот.$b$bКамни, блокирующие вход в стоки, падают на находящуюся внизу жидкость, а из темноты появляются четыре гниющих глаза.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите засаду!',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Немигающий глаз подергивается.',`questgivertextwindow_loc8`);
