INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32722,'Впереди кузня!','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.','Вернитесь к капитану разведчиков Эльсии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впереди кузня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Эльсии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32723,'reuse me','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.','Убейте главного кузнеца и получите фрагмент кодекса от стража врат могу на Острове Грома.','Вернитесь к <тому, кто выдал задание>.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','reuse me',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте главного кузнеца и получите фрагмент кодекса от стража врат могу на Острове Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к <тому, кто выдал задание>.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (32724,'Впереди кузня!','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.','Вернитесь к капитану разведчиков Дэлину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Впереди кузня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану разведчиков Дэлину.',`completedtext_loc8`);
