INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32726,'Так ты хочешь быть кузнецом...','Хорошо узнавать свойства более простых разновидностей металла и постепенно развивать свои навыки, но можно стать хорошим кузнецом, делая различные вещи из призрачного железа. Если хочешь избрать этот путь, чтобы достичь уровня дзен-мастера кузнечного дела, я могу кое-чему научить тебя. Но сначала покажи мне, что ты уже умеешь – создай призрачную отмычку.','Создайте призрачную отмычку, достигнув уровня навыка кузнечного дела, равного 500, и принесите эту вещь своему учителю. Если вы хотите совершенствоваться, используя пандаренские материалы, изучите соответствующие вашему уровню учебные чертежи у Джорунги Каменное Копыто.','Создайте призрачную отмычку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так ты хочешь быть кузнецом...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо узнавать свойства более простых разновидностей металла и постепенно развивать свои навыки, но можно стать хорошим кузнецом, делая различные вещи из призрачного железа. Если хочешь избрать этот путь, чтобы достичь уровня дзен-мастера кузнечного дела, я могу кое-чему научить тебя. Но сначала покажи мне, что ты уже умеешь – создай призрачную отмычку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте призрачную отмычку, достигнув уровня навыка кузнечного дела, равного 500, и принесите эту вещь своему учителю. Если вы хотите совершенствоваться, используя пандаренские материалы, изучите соответствующие вашему уровню учебные чертежи у Джорунги Каменное Копыто.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Создайте призрачную отмычку.',`completedtext_loc8`);
