INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32728,'Двор Костей','Могу во Дворе Костей постоянно угрожают безопасности нашего лагеря. Я поручила верховному магистру Роммату заняться этой проблемой, но ему не помешает твоя помощь.$B$BОтправляйся к нему немедленно.','Разыщите верховного магистра Роммата возле Двора Костей.','А, хорошо… тут для тебя найдется работа.','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двор Костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу во Дворе Костей постоянно угрожают безопасности нашего лагеря. Я поручила верховному магистру Роммату заняться этой проблемой, но ему не помешает твоя помощь.$B$BОтправляйся к нему немедленно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите верховного магистра Роммата возле Двора Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо… тут для тебя найдется работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32729,'За\'Туал','С тех пор, как мы высадились на остров, зандалары постоянно угрожают нашей безопасности. Я поручил Халдарону Светлому Крылу уменьшить их численность в За\'Туале, что на юге отсюда.$B$BОтправляйся к нему, как только сможешь. У него есть для тебя работа.','Разыщите Халдарона Светлое Крыло снаружи За\'Туала.','Хочешь поохотиться на зандаларов? Отлично.','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За\'Туал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тех пор, как мы высадились на остров, зандалары постоянно угрожают нашей безопасности. Я поручил Халдарону Светлому Крылу уменьшить их численность в За\'Туале, что на юге отсюда.$B$BОтправляйся к нему, как только сможешь. У него есть для тебя работа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Халдарона Светлое Крыло снаружи За\'Туала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хочешь поохотиться на зандаларов? Отлично.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32730,'Утесы Ихгалук','Этас сейчас на юго-востоке, на утесах Ихгалук, где он пытается натравить сауроков на зандаларов и могу.$B$BОтправляйся туда и помоги ему, чем сможешь.','Разыщите верховного мага Этаса Похитителя Солнца возле утесов Ихгалук.','Ты как раз вовремя. Мне не помешает помощь.','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утесы Ихгалук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этас сейчас на юго-востоке, на утесах Ихгалук, где он пытается натравить сауроков на зандаларов и могу.$B$BОтправляйся туда и помоги ему, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите верховного мага Этаса Похитителя Солнца возле утесов Ихгалук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя. Мне не помешает помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32731,'Двор Костей','Могу во Дворе Костей – одна из серьезнейших угроз нашим силам на этом острове. Я поручила Нараси Снежной Заре заняться этой проблемой, но ей не помешает помощь $gумелого:умелой:c; |3-1($c).$B$BОтправляйся к ней и помоги всем, чем сумеешь.','Разыщите Нараси Снежную Зарю возле Двора Костей.','А, хорошо… тут для тебя найдется работа.','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Двор Костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могу во Дворе Костей – одна из серьезнейших угроз нашим силам на этом острове. Я поручила Нараси Снежной Заре заняться этой проблемой, но ей не помешает помощь $gумелого:умелой:c; |3-1($c).$B$BОтправляйся к ней и помоги всем, чем сумеешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Нараси Снежную Зарю возле Двора Костей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо… тут для тебя найдется работа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите капитана разведчиков Эльсию в загонах для зверей, что на Острове Грома.',`completedtext_loc8`);
