INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32758,'Чтец мертвого языка','Вам надо вернуться в столицу и найти тренера чернокнижников, который может знать больше о Кодексе.','Отнесите кодекс наставнику чернокнижников в вашей столице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чтец мертвого языка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам надо вернуться в столицу и найти тренера чернокнижников, который может знать больше о Кодексе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кодекс наставнику чернокнижников в вашей столице.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32806,'Король и Совет','Хорошо, что ты здесь, $n. Хмель глубоких раздумий помогает мне узнать, что творится в мире, но чем больше я узнаю, тем меньше понимаю.$b$bК примеру, король Ринн попросил дворфов Стальгорна предоставить ему больше войск, но не все дворфы поддерживают его.$b$bЯ расскажу тебе больше, но сперва мне хотелось бы узнать о твоих приключениях от тебя лично...','Пройдите сценарий "Кровь на снегу". Чтобы встать в очередь, воспользуйтесь поиском подземелий или выпейте хмель глубоких раздумий хранителя истории Чо.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король и Совет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что ты здесь, $n. Хмель глубоких раздумий помогает мне узнать, что творится в мире, но чем больше я узнаю, тем меньше понимаю.$b$bК примеру, король Ринн попросил дворфов Стальгорна предоставить ему больше войск, но не все дворфы поддерживают его.$b$bЯ расскажу тебе больше, но сперва мне хотелось бы узнать о твоих приключениях от тебя лично...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сценарий "Кровь на снегу". Чтобы встать в очередь, воспользуйтесь поиском подземелий или выпейте хмель глубоких раздумий хранителя истории Чо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32807,'Вождь и тьма','Теперь я вижу, как король Альянса ведет свой народ. Но что же задумал вождь Орды? Прямо под нами толпы гоблинов роют туннели по его приказу. Что он надеется найти? Мы должны выяснить!','Пройдите сценарий "Темное сердце Пандарии". Для этого можно встать в очередь в системе поиска подземелий или выпить хмель глубоких раздумий хранителя истории Чо.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь и тьма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь я вижу, как король Альянса ведет свой народ. Но что же задумал вождь Орды? Прямо под нами толпы гоблинов роют туннели по его приказу. Что он надеется найти? Мы должны выяснить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите сценарий "Темное сердце Пандарии". Для этого можно встать в очередь в системе поиска подземелий или выпить хмель глубоких раздумий хранителя истории Чо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32808,'Полевые работы','Мой хмель глубоких раздумий тоже не открывает мне всего, видения рассеяны в пространстве и времени. Но ясно, что в Оргриммаре, столице Орды, скоро произойдут большие перемены.$b$bТебе надо отправиться туда и увидеть все лично!$b$bХмель показывает мне двух храбрых шпионов Альянса, в одиночку действующих в Дуротаре. Вижу имена – Эмбер и Салли...$b$bМожет быть, ты их помнишь? Сдается мне, им нужна твоя помощь!$b$bЭмбер и Салли ты найдешь в Калимдоре, на заставе Дранош\'ар, что находится рядом со Скалой Черепа.','Переместитесь в Калимдор с помощью Глипа Кряхтумблера из Святилища Семи Звезд. Затем поговорите с Эмбер Кеарнен, ведущей разведку в Бухте Острорука рядом со Скалой Черепа в Дуротаре.\r\n','Поговорите с Эмбер Кеарнен около Скалы Черепа в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевые работы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой хмель глубоких раздумий тоже не открывает мне всего, видения рассеяны в пространстве и времени. Но ясно, что в Оргриммаре, столице Орды, скоро произойдут большие перемены.$b$bТебе надо отправиться туда и увидеть все лично!$b$bХмель показывает мне двух храбрых шпионов Альянса, в одиночку действующих в Дуротаре. Вижу имена – Эмбер и Салли...$b$bМожет быть, ты их помнишь? Сдается мне, им нужна твоя помощь!$b$bЭмбер и Салли ты найдешь в Калимдоре, на заставе Дранош\'ар, что находится рядом со Скалой Черепа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переместитесь в Калимдор с помощью Глипа Кряхтумблера из Святилища Семи Звезд. Затем поговорите с Эмбер Кеарнен, ведущей разведку в Бухте Острорука рядом со Скалой Черепа в Дуротаре.\r\n',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Эмбер Кеарнен около Скалы Черепа в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32809,'Сбор разведданных','Гаррош продолжает наращивать силы в Оргриммаре, теперь это настоящая крепость!$b$bКороль Ринн не рискнет нападать, пока у нас не будет достаточно информации.$b$bПроникни на заставу с помощью Проекта К0Т. Постарайся собрать как можно больше разведданных. Попробуй добыть важные документы, поищи бреши в обороне, которыми можно воспользоваться. Будь начеку и не попадись!','Добудьте информацию о кор\'кронских линиях снабжения, операции "Уничтожение Черного Копья" и кор\'кронских командных пунктах, а также освободите пленника.','Вернитесь к Эмбер Кеарнен на заставу Дранош\'ар в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор разведданных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гаррош продолжает наращивать силы в Оргриммаре, теперь это настоящая крепость!$b$bКороль Ринн не рискнет нападать, пока у нас не будет достаточно информации.$b$bПроникни на заставу с помощью Проекта К0Т. Постарайся собрать как можно больше разведданных. Попробуй добыть важные документы, поищи бреши в обороне, которыми можно воспользоваться. Будь начеку и не попадись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте информацию о кор\'кронских линиях снабжения, операции "Уничтожение Черного Копья" и кор\'кронских командных пунктах, а также освободите пленника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эмбер Кеарнен на заставу Дранош\'ар в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32810,'Восстание Черного Копья','Тролли подняли восстание. Это может оказаться нам на руку! Если они откроют второй фронт, Гаррош не сможет оборонять город сразу и от них, и от нас.$b$bЯ хочу поручить тебе очень рискованное задание. Тебе надо начать переговоры с Вол\'джином из племени Черного Копья от имени Альянса.$b$bПопробуй найти пленницу-тролля, которую мы освободили из лап кор\'кронских вояк. Зен\'табра ее зовут, ведь так?$b$bВозможно, это наш единственный шанс низвергнуть Гарроша...','Поговорите с Зен\'таброй в Колючем Холме, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли подняли восстание. Это может оказаться нам на руку! Если они откроют второй фронт, Гаррош не сможет оборонять город сразу и от них, и от нас.$b$bЯ хочу поручить тебе очень рискованное задание. Тебе надо начать переговоры с Вол\'джином из племени Черного Копья от имени Альянса.$b$bПопробуй найти пленницу-тролля, которую мы освободили из лап кор\'кронских вояк. Зен\'табра ее зовут, ведь так?$b$bВозможно, это наш единственный шанс низвергнуть Гарроша...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зен\'таброй в Колючем Холме, что в Дуротаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32811,'Поле битвы: Степи','Хочешь, чтобы мы были заодно, сделай так, чтобы я тебе поверил.$b$bВ Северных Степях собирается войско кор\'кронских солдат. Прихвостни Гарроша вовсю копят разные припасы – древесину, нефть, камень, мясо. То, что как раз нужно Черному Копью для борьбы.$b$bСтупай в Степи. Убивай воинов кор\'крон. Принеси мне их припасы! Бей любого, кого увидишь, сопровождай обозы с припасами, зови подмогу, чтобы уложить самых крепких. Что угодно.$b$bДокажи, что Альянсу это надо! Я слежу за тобой.','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.','Вернитесь к Вол\'джину в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поле битвы: Степи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь, чтобы мы были заодно, сделай так, чтобы я тебе поверил.$b$bВ Северных Степях собирается войско кор\'кронских солдат. Прихвостни Гарроша вовсю копят разные припасы – древесину, нефть, камень, мясо. То, что как раз нужно Черному Копью для борьбы.$b$bСтупай в Степи. Убивай воинов кор\'крон. Принеси мне их припасы! Бей любого, кого увидишь, сопровождай обозы с припасами, зови подмогу, чтобы уложить самых крепких. Что угодно.$b$bДокажи, что Альянсу это надо! Я слежу за тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32812,'Восстание Черного Копья','Хмель глубоких раздумий позволяет мне увидеть не все. Видения рассеяны в пространстве и времени. Но ясно, что в Орде разгорается большой конфликт.$b$bВидения говорят мне, что тролль Вол\'джин из племени Черного Копья уже отправился в Дуротар, чтобы защищать свой народ. Его сопровождает Чэнь Буйный Портер, хмелевар со Скитающегося острова.$b$bУж если я что и знаю про Чэня, так это то, что бедокурить он мастер, каких мало... Поторопись же!','Отправляйтесь в Дуротар и поговорите с Ки\'той Стрелоклыком в деревне Сен\'джин. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмель глубоких раздумий позволяет мне увидеть не все. Видения рассеяны в пространстве и времени. Но ясно, что в Орде разгорается большой конфликт.$b$bВидения говорят мне, что тролль Вол\'джин из племени Черного Копья уже отправился в Дуротар, чтобы защищать свой народ. Его сопровождает Чэнь Буйный Портер, хмелевар со Скитающегося острова.$b$bУж если я что и знаю про Чэня, так это то, что бедокурить он мастер, каких мало... Поторопись же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Дуротар и поговорите с Ки\'той Стрелоклыком в деревне Сен\'джин. ',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32813,'Битва в деревне Сен\'джин','<Гул боевых барабанов слышен в отдалении.>$b$b$c, ты снова в нужном месте в нужное время. Адский Крик пошел против своего народа.$b$bХочет узнать, что будет, если поссориться с Черным Копьем. Вперед! Бейся с нами бок о бок! Пусть он увидит настоящий дух Орды!','Защитите деревню Сен\'джин от нападения кор\'кронских бойцов.','Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва в деревне Сен\'джин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гул боевых барабанов слышен в отдалении.>$b$b$c, ты снова в нужном месте в нужное время. Адский Крик пошел против своего народа.$b$bХочет узнать, что будет, если поссориться с Черным Копьем. Вперед! Бейся с нами бок о бок! Пусть он увидит настоящий дух Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите деревню Сен\'джин от нападения кор\'кронских бойцов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32814,'Битва за Колючий Холм','Ударим прямо сейчас! Не дадим Адскому Крику опомниться. На север! Пора резать кор\'кронским солдатам глотки.$b$bЕсли возьмем Колючий Холм, все дороги в Дуротаре будут наши.$b$bВперед! Давай за мной!','Освободите 6 пленных и одолейте кор\'кронских командиров, чтобы помочь восставшим троллям из племени Черного Копья захватить Колючий Холм.','Поговорите с Вол\'джином под сторожевой башней Колючего Холма в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Колючий Холм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ударим прямо сейчас! Не дадим Адскому Крику опомниться. На север! Пора резать кор\'кронским солдатам глотки.$b$bЕсли возьмем Колючий Холм, все дороги в Дуротаре будут наши.$b$bВперед! Давай за мной!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 6 пленных и одолейте кор\'кронских командиров, чтобы помочь восставшим троллям из племени Черного Копья захватить Колючий Холм.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вол\'джином под сторожевой башней Колючего Холма в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32815,'Старый провидец') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый провидец',`title_loc8`);
