INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32818,'Пройдите сценарий "Темное сердце Пандарии"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пройдите сценарий "Темное сердце Пандарии"',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32819,'Поле битвы: Степи','Чтобы восстать против вождя, мне понадобится армия и припасы.$b$bАрмия у меня есть, и моим солдатам не занимать ненависти к Адскому Крику за все, что он сотворил с Ордой. А вот древесины, мяса, нефти и камня не хватает.$b$bК счастью для нас, солдаты Кор\'крон все это запасают к западу отсюда, в Северных Степях, причем в огромных количествах. Убивай всех кор\'кронцев, которые будут встречаться тебе на пути, а еще помоги нашим братьям-тауренам с охраной караванов и найди помощников для расправы над командирами Кор\'крона.','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.','Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поле битвы: Степи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы восстать против вождя, мне понадобится армия и припасы.$b$bАрмия у меня есть, и моим солдатам не занимать ненависти к Адскому Крику за все, что он сотворил с Ордой. А вот древесины, мяса, нефти и камня не хватает.$b$bК счастью для нас, солдаты Кор\'крон все это запасают к западу отсюда, в Северных Степях, причем в огромных количествах. Убивай всех кор\'кронцев, которые будут встречаться тебе на пути, а еще помоги нашим братьям-тауренам с охраной караванов и найди помощников для расправы над командирами Кор\'крона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в деревню Сен\'джин в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32825,'Используй меня еще раз','Убейте 10 последователей Кирин-Тора или игроков на Острове Грома.','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Используй меня еще раз',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 последователей Кирин-Тора или игроков на Острове Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лор\'темару Терону на Мыс Искателя Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32826,'Используй меня еще раз','Ах, |3-6($p), я как раз ищу $gтакого:такую:r; |3-3($r), как ты. Мне прислали новую партию тактических мана-бомб, которые нужно разместить в ключевых точках на Мысе Искателя Рассвета к северо-западу отсюда.$b$bВот, возьми. Пора отплатить Похитителям Солнца их же монетой.$b$bУстанови одну на кораблях Похитителей Солнца, еще одну – у кристаллов ясновидения, а последнюю – на мосту, ведущему к их передовой базе.','Установите тактическую мана-бомбу на корабле Похитителей Солнца, у кристаллов ясновидения и на самом внутреннем мосту Мыса Искателя Рассвета.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Используй меня еще раз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, |3-6($p), я как раз ищу $gтакого:такую:r; |3-3($r), как ты. Мне прислали новую партию тактических мана-бомб, которые нужно разместить в ключевых точках на Мысе Искателя Рассвета к северо-западу отсюда.$b$bВот, возьми. Пора отплатить Похитителям Солнца их же монетой.$b$bУстанови одну на кораблях Похитителей Солнца, еще одну – у кристаллов ясновидения, а последнюю – на мосту, ведущему к их передовой базе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите тактическую мана-бомбу на корабле Похитителей Солнца, у кристаллов ясновидения и на самом внутреннем мосту Мыса Искателя Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32827,'Используй меня еще раз','Даже в самой сильной обороне можно обнаружить брешь, |3-6($c). Нам надо найти слабое место в обороне Похитителей Солнца и использовать его.$b$bРазведчики доносят о том, что их лагерь на Мысе Искателя Рассвета охраняется защитными кристаллами. Они мощные, но не смертельно опасные.$b$bЕсли их отключить, мы сможем более эффективно наблюдать за противником.','Уничтожьте 6 защитных кристаллов Похитителей Солнца на Мысе Искателя Рассвета.','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Используй меня еще раз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже в самой сильной обороне можно обнаружить брешь, |3-6($c). Нам надо найти слабое место в обороне Похитителей Солнца и использовать его.$b$bРазведчики доносят о том, что их лагерь на Мысе Искателя Рассвета охраняется защитными кристаллами. Они мощные, но не смертельно опасные.$b$bЕсли их отключить, мы сможем более эффективно наблюдать за противником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 защитных кристаллов Похитителей Солнца на Мысе Искателя Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллеан Гребень Волны на Аметистовый утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32832,'Сцена с Тажанем Чжу и Дезко') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сцена с Тажанем Чжу и Дезко',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32836,'Скрипучая флейта','Эта скрипучая флейта наскоро вырезана из корня дерева, а по всей ее длине неравномерно проделаны отверстия.$b$bПри внимательном осмотре задней части обнаруживается вырезанная в дереве надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните скрипучую флейту кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрипучая флейта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта скрипучая флейта наскоро вырезана из корня дерева, а по всей ее длине неравномерно проделаны отверстия.$b$bПри внимательном осмотре задней части обнаруживается вырезанная в дереве надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните скрипучую флейту кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32837,'Дедушка Скрипучая Флейта','Карточка вызова, которая может сегодня стать твоей, принадлежит груммелю с чудесным именем дедушка Скрипучая Флейта. Хоть груммели и не отличаются особым боевым мастерством, везения этим малышам не занимать.$b$bВозможно, все дело в их... как там они их называют... удачках?','Приобретите карточку вызова дедушки Скрипучей Флейты, вызовите Дедушку на поединок в бойцовской гильдии и победите его.','Отличный был бой! Пусть даже и дрался ты с малышом.$B$BЭто была заслуженная победа.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дедушка Скрипучая Флейта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Карточка вызова, которая может сегодня стать твоей, принадлежит груммелю с чудесным именем дедушка Скрипучая Флейта. Хоть груммели и не отличаются особым боевым мастерством, везения этим малышам не занимать.$b$bВозможно, все дело в их... как там они их называют... удачках?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова дедушки Скрипучей Флейты, вызовите Дедушку на поединок в бойцовской гильдии и победите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный был бой! Пусть даже и дрался ты с малышом.$B$BЭто была заслуженная победа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32838,'Сказка о любви и благородстве','Маленькая детская книжка. Она хорошо переплетена и неплохо сохранилась.$b$bНа задней стороне книги рядом с переплетом вы замечаете надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните "Медведя и прекрасную даму" кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сказка о любви и благородстве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маленькая детская книжка. Она хорошо переплетена и неплохо сохранилась.$b$bНа задней стороне книги рядом с переплетом вы замечаете надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните "Медведя и прекрасную даму" кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32839,'Медведь и прекрасная дама','Эта карточка дает тебе право сразиться с двумя весьма необычными личностями. Пожалуй, больше мне и добавить-то нечего.$b$bПриобрети карточку вызова, и $gсам:сама; все увидишь.','Приобретите карточку вызова медведя и прекрасной дамы, вызовите их на поединок в бойцовской гильдии и одержите над ними победу.','Ты так... так величественно парил по воздуху! Превосходно!','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медведь и прекрасная дама',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта карточка дает тебе право сразиться с двумя весьма необычными личностями. Пожалуй, больше мне и добавить-то нечего.$b$bПриобрети карточку вызова, и $gсам:сама; все увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова медведя и прекрасной дамы, вызовите их на поединок в бойцовской гильдии и одержите над ними победу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты так... так величественно парил по воздуху! Превосходно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (32840,'Фитиль Бум-Бума','Из ошметков хозенского мяса и шерсти, летающих туда-сюда вокруг Коту Кон, сеющей хаос и разрушение, вам удалось выхватить небольшой фитиль.$b$bВесь фитиль сплетен из спутанных волос с хвоста хозена. Он издает сильный запах.$b$bК одному из концов фитиля прикреплен небольшой бумажный ярлычок с надписью:$b$b"Вернуть в бойцовскую гильдию".','Верните фитиль Бум-Бума кому-нибудь из вашей бойцовской гильдии.','Что это за запах?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фитиль Бум-Бума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из ошметков хозенского мяса и шерсти, летающих туда-сюда вокруг Коту Кон, сеющей хаос и разрушение, вам удалось выхватить небольшой фитиль.$b$bВесь фитиль сплетен из спутанных волос с хвоста хозена. Он издает сильный запах.$b$bК одному из концов фитиля прикреплен небольшой бумажный ярлычок с надписью:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните фитиль Бум-Бума кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это за запах?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32841,'Мастер Бум-Бум','Ты $gнашел:нашла; карточку, принадлежащую хозену-бомбометателю по имени мастер Бум-Бум.$b$bХозены в большинстве своем любят разрушительную мощь взрывов, но мало кому из них удается научиться обращению с бомбами, не подорвав при этом себя. Мастер Бум-Бум – исключение.$b$bУдачи тебе!','Приобретите карточку вызова мастера Бум-Бума, вызовите его на поединок в бойцовской гильдии и победите.','Я даже не знаю, что сказать. Я желала тебе победы, но при том... желала и посмотреть, как ты взорвешься.$B$BТолько чур без обид! Я просто люблю взрывы.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер Бум-Бум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gнашел:нашла; карточку, принадлежащую хозену-бомбометателю по имени мастер Бум-Бум.$b$bХозены в большинстве своем любят разрушительную мощь взрывов, но мало кому из них удается научиться обращению с бомбами, не подорвав при этом себя. Мастер Бум-Бум – исключение.$b$bУдачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова мастера Бум-Бума, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я даже не знаю, что сказать. Я желала тебе победы, но при том... желала и посмотреть, как ты взорвешься.$B$BТолько чур без обид! Я просто люблю взрывы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32842,'Зубы, похожие на мечи','Зуб оканчивается острой кромкой, будто его заточили специально. Сразу видно, что он принадлежал злобному чудовищу.$b$bОсторожно разглядывая зуб, вы замечаете, что на его эмали тщательно вырезана надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните невероятно острый зуб кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зубы, похожие на мечи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зуб оканчивается острой кромкой, будто его заточили специально. Сразу видно, что он принадлежал злобному чудовищу.$b$bОсторожно разглядывая зуб, вы замечаете, что на его эмали тщательно вырезана надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните невероятно острый зуб кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32843,'Щербохмыл','Эта карточка дает тебе право сразиться с одним из самых опасных созданий Южных морей – Щербохмылом. Один укус такими зубами – и от тебя останется только не поддающаяся опознанию груда кожи и кишок в луже крови.$b$bВсего хорошего!','Приобретите карточку вызова Щербохмыла, вызовите его на поединок в бойцовской гильдии и победите.','Поздравляю!$B$BДа и, согласись, позорно было бы быть съеденным акулой, выброшенной на берег?','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щербохмыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта карточка дает тебе право сразиться с одним из самых опасных созданий Южных морей – Щербохмылом. Один укус такими зубами – и от тебя останется только не поддающаяся опознанию груда кожи и кишок в луже крови.$b$bВсего хорошего!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Щербохмыла, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поздравляю!$B$BДа и, согласись, позорно было бы быть съеденным акулой, выброшенной на берег?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32844,'Секрет неизвестной жидкости','Содержимое склянки неистово бурлит и вскипает, из-за чего сама склянка дрожит у вас в руках. Вглядываясь в нее, вы смутно различаете образ чьего-то злобного лица.$b$bЗатычка отлично подходит к горлышку склянки. Вдоль ее края искусно вырезана следующая надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните склянку с красноватой жидкостью кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет неизвестной жидкости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Содержимое склянки неистово бурлит и вскипает, из-за чего сама склянка дрожит у вас в руках. Вглядываясь в нее, вы смутно различаете образ чьего-то злобного лица.$b$bЗатычка отлично подходит к горлышку склянки. Вдоль ее края искусно вырезана следующая надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните склянку с красноватой жидкостью кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32845,'Бульк','Полагаю, с Блэтом, нашим гильдейским бойцом 2 ранга, ты уже $gзнаком:знакома;. Эта карточка дает тебе право сразиться с Бульк, его старшей сестрой. Она злобная.$b$bПостарайся не умереть. А если умрешь – то хотя бы сделай это так, чтобы наблюдать было интересно!','Приобретите карточку вызова Бульк, вызовите ее на поединок в бойцовской гильдии и одержите победу.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бульк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, с Блэтом, нашим гильдейским бойцом 2 ранга, ты уже $gзнаком:знакома;. Эта карточка дает тебе право сразиться с Бульк, его старшей сестрой. Она злобная.$b$bПостарайся не умереть. А если умрешь – то хотя бы сделай это так, чтобы наблюдать было интересно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Бульк, вызовите ее на поединок в бойцовской гильдии и одержите победу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (32846,'Модифицированный рубильный аппарат','Вы, возможно, и не узнали бы в этом агрегате модифицированный рубильный аппарат, не будь на нем кривыми буквами выведена надпись "МОДИФИЦИРОВАННЫЙ РУБИЛЬНЫЙ АППАРАТ".$b$bПрямо под этикеткой вы замечаете еще одну, уже не такую большую, но гораздо более аккуратную надпись ярко-красными чернилами:$b$b"Вернуть в бойцовскую гильдию".','Верните модифицированный рубильный аппарат кому-нибудь из вашей бойцовской гильдии.','Я могу тебе чем-то помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Модифицированный рубильный аппарат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы, возможно, и не узнали бы в этом агрегате модифицированный рубильный аппарат, не будь на нем кривыми буквами выведена надпись "МОДИФИЦИРОВАННЫЙ РУБИЛЬНЫЙ АППАРАТ".$b$bПрямо под этикеткой вы замечаете еще одну, уже не такую большую, но гораздо более аккуратную надпись ярко-красными чернилами:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните модифицированный рубильный аппарат кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я могу тебе чем-то помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32847,'Меха-Брюс','Все знают Брюса. Все любят Брюса! И рано или поздно все убивают Брюса.$b$bОдному орку-охотнику с инженерным талантом это надоело, и он нашел себе кроколиска и слегка его модернизировал.$b$bЭта карточка вызова дает тебе право сразиться с Меха-Брюсом. Такой бой обязательно станет настоящей кровавой бойней. Весь вопрос в том, чья кровь прольется – твоя, или противника?','Приобретите карточку вызова Меха-Брюса, вызовите его на поединок в бойцовской гильдии и победите.','Ох... Бедный Меха-Брюс.$B$BЯ дам тебе награду. Но без всякой радости!','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меха-Брюс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все знают Брюса. Все любят Брюса! И рано или поздно все убивают Брюса.$b$bОдному орку-охотнику с инженерным талантом это надоело, и он нашел себе кроколиска и слегка его модернизировал.$b$bЭта карточка вызова дает тебе право сразиться с Меха-Брюсом. Такой бой обязательно станет настоящей кровавой бойней. Весь вопрос в том, чья кровь прольется – твоя, или противника?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Меха-Брюса, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох... Бедный Меха-Брюс.$B$BЯ дам тебе награду. Но без всякой радости!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32848,'Морозная скорлупа','Это кусок скорлупы – вероятно, от пингвиньего яйца. Его края покрыты инеем, и по самому осколку видно, что яйцо, от которого он откололся, было огромным.$b$bК своему немалому удивлению вы замечаете на внутренней стороне осколка надпись нефритово-зелеными чернилами:$b$b"Вернуть в бойцовскую гильдию".','Верните морозную скорлупу кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Морозная скорлупа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это кусок скорлупы – вероятно, от пингвиньего яйца. Его края покрыты инеем, и по самому осколку видно, что яйцо, от которого он откололся, было огромным.$b$bК своему немалому удивлению вы замечаете на внутренней стороне осколка надпись нефритово-зелеными чернилами:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните морозную скорлупу кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32849,'Тюка и Тяпа','Все ветераны бойцовской гильдии помнят пингвина Тюку. Тюка – не самый грозный боец гильдии, но и отнюдь не слабак!$b$bНет, ну с соображалкой у него, конечно, не очень...$b$bНеважно! Эта карточка дает вам право сразиться как с Тюкой, так и с его крупным старшим братцем Тяпой. Пусть оба они и туповаты, но это не значит, что им не по силам вас убить вдвоем или в одиночку.','Приобретите карточку вызова Тюки и Тяпы, вызовите их на поединок в бойцовской гильдии и победите.','Не думала, что когда-нибудь такое скажу, но победа над парой пингвинов – признак истинного, проверенного бойца. Ты заслужил свою награду.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюка и Тяпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все ветераны бойцовской гильдии помнят пингвина Тюку. Тюка – не самый грозный боец гильдии, но и отнюдь не слабак!$b$bНет, ну с соображалкой у него, конечно, не очень...$b$bНеважно! Эта карточка дает вам право сразиться как с Тюкой, так и с его крупным старшим братцем Тяпой. Пусть оба они и туповаты, но это не значит, что им не по силам вас убить вдвоем или в одиночку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Тюки и Тяпы, вызовите их на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думала, что когда-нибудь такое скажу, но победа над парой пингвинов – признак истинного, проверенного бойца. Ты заслужил свою награду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32850,'Прошлогодняя модель','Этот робот в неважном состоянии. В нем есть несколько гнезд, в которых, как и у Блескотрона-4000, вероятно, были драгоценные камни, но теперь они пусты.$b$bВ пыли, покрывающей заднюю часть робота, блестит металлическая табличка с надписью:$b$b"Вернуть в бойцовскую гильдию".','Верните старого пыльного робота кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прошлогодняя модель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот робот в неважном состоянии. В нем есть несколько гнезд, в которых, как и у Блескотрона-4000, вероятно, были драгоценные камни, но теперь они пусты.$b$bВ пыли, покрывающей заднюю часть робота, блестит металлическая табличка с надписью:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните старого пыльного робота кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32851,'Блескотрон-3000','Серия Блескотронов не была особенно популярна до тех пор, пока на полки магазинов не попала модель 4000. Мало кто помнит о Блескотроне-3000, а ведь он в каком-то смысле был настоящим инженерным чудом!$b$bЭта карточка вызова дает тебе право сразиться с Блекскотроном-3000 прямо здесь, в бойцовской гильдии. $b$bВот это повезло!','Приобретите карточку вызова Блескотрона-3000, вызовите его на поединок в бойцовской гильдии и победите.','У тебя, Скайчик, настоящий талант к уничтожению роботов.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блескотрон-3000',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серия Блескотронов не была особенно популярна до тех пор, пока на полки магазинов не попала модель 4000. Мало кто помнит о Блескотроне-3000, а ведь он в каком-то смысле был настоящим инженерным чудом!$b$bЭта карточка вызова дает тебе право сразиться с Блекскотроном-3000 прямо здесь, в бойцовской гильдии. $b$bВот это повезло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Блескотрона-3000, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя, Скайчик, настоящий талант к уничтожению роботов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32852,'Лопата мастера','Совершенно обычная с виду лопата, на рукоятке которой затейливыми буквами вырезана надпись "Лопата мастера".$b$bНа обратной же стороне рукоятки видна надпись поменьше, сделанная буквами попроще:$b$b"Вернуть в бойцовскую гильдию".','Верните лопату мастера кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лопата мастера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совершенно обычная с виду лопата, на рукоятке которой затейливыми буквами вырезана надпись "Лопата мастера".$b$bНа обратной же стороне рукоятки видна надпись поменьше, сделанная буквами попроще:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните лопату мастера кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32853,'Мингус Коппс','Ты $gзаслужил:заслужила; право сразиться с археологом Мингусом Коппсом!$b$bНасколько мне известно, сам по себе Мингус не такой уж и страшный боец, но устроители боев позволяют ему приносить с собой на ринг отрытые им сокровища. Их-то и надо беречься больше всего.$b$bКогда будешь $gготов:готова;, смело покупай эту карточку!','Приобретите карточку вызова Мингуса Коппса, вызовите его на поединок в бойцовской гильдии и победите.','Ты так быстро бегал кругами по арене, что у меня даже голова закружилась.$B$BПоздравляю!','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мингус Коппс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gзаслужил:заслужила; право сразиться с археологом Мингусом Коппсом!$b$bНасколько мне известно, сам по себе Мингус не такой уж и страшный боец, но устроители боев позволяют ему приносить с собой на ринг отрытые им сокровища. Их-то и надо беречься больше всего.$b$bКогда будешь $gготов:готова;, смело покупай эту карточку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Мингуса Коппса, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты так быстро бегал кругами по арене, что у меня даже голова закружилась.$B$BПоздравляю!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (32854,'Изношенная повязка для глаз','Кусок ткани размером под среднюю человеческую голову. Ткань самая простая, без каких-либо украшений, если не считать маленького ярлычка на краю, на которой написано:$b$b"Вернуть в бойцовскую гильдию".','Верните изношенную повязку для глаз кому-нибудь из вашей бойцовской гильдии.','Полагаю, ты хочешь что-то отдать мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изношенная повязка для глаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кусок ткани размером под среднюю человеческую голову. Ткань самая простая, без каких-либо украшений, если не считать маленького ярлычка на краю, на которой написано:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните изношенную повязку для глаз кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полагаю, ты хочешь что-то отдать мне.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32855,'Слепой герой','Эта карточка дает тебе право сразиться со cлепым героем, таинственным воином минувшей эпохи. Никто не способен превзойти его во владении клинком. Никто.$b$bК счастью, он абсолютно слеп. Желаю повеселиться!','Приобретите карточку вызова cлепого героя, вызовите его на поединок в бойцовской гильдии и победите.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слепой герой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта карточка дает тебе право сразиться со cлепым героем, таинственным воином минувшей эпохи. Никто не способен превзойти его во владении клинком. Никто.$b$bК счастью, он абсолютно слеп. Желаю повеселиться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова cлепого героя, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32856,'Обернутый в бумагу камень','Перед вами странная комбинация предметов. Камень, обернутый настолько толстым слоем бумаги, что он скрадывает его истинные размеры. Под этой бумагой камень кажется совсем маленьким. $b$bЕсли рассматривать бумагу на просвет, видно водяной знак и надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните обернутый в бумагу камень кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обернутый в бумагу камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед вами странная комбинация предметов. Камень, обернутый настолько толстым слоем бумаги, что он скрадывает его истинные размеры. Под этой бумагой камень кажется совсем маленьким. $b$bЕсли рассматривать бумагу на просвет, видно водяной знак и надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните обернутый в бумагу камень кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32857,'Ро-Шамбо','Новая карточка дает тебе право сразиться с Ро-Шамбо, непонятным созданием из неизвестных краев.$b$bБерегись. Я слышала, у нее в запасе есть пара хитрых фокусов.','Приобретите карточку вызова Ро-Шамбо, вызовите ее на поединок в бойцовской гильдии и победите.','Ты отлично справился! Даже если допустить, что тебе немного повезло...','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ро-Шамбо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новая карточка дает тебе право сразиться с Ро-Шамбо, непонятным созданием из неизвестных краев.$b$bБерегись. Я слышала, у нее в запасе есть пара хитрых фокусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Ро-Шамбо, вызовите ее на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отлично справился! Даже если допустить, что тебе немного повезло...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32858,'Боксерские перчатки из шкуры ящера','Швы на перчатках грубые, а шкуру, судя по запаху, обрабатывали слизью краба. Но сами перчатки при этом весьма прочные и удобные.$b$bНа изнанке перчаток видна следующая, логичная, в общем-то, надпись:$b$b"Вернуть в бойцовскую гильдию".','Верните боксерские перчатки из шкуры ящера кому-нибудь из вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боксерские перчатки из шкуры ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Швы на перчатках грубые, а шкуру, судя по запаху, обрабатывали слизью краба. Но сами перчатки при этом весьма прочные и удобные.$b$bНа изнанке перчаток видна следующая, логичная, в общем-то, надпись:$b$b"Вернуть в бойцовскую гильдию".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните боксерские перчатки из шкуры ящера кому-нибудь из вашей бойцовской гильдии.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32859,'Ти\'тар','Ты $gзаслужил:заслужила; право приобрести карточку вызова, и принадлежит эта карточка троллю по имени Ти\'тар.$b$bТи\'тар обладает очень характерным боевым стилем, и тебе, как того требует соглашение с бойцовской гильдией, придется драться по его правилам – лицом к лицу, на кулаках и не убегать. До трех нокдаунов.$b$bУдачи!','Приобретите карточку вызова Ти\'тара, вызовите его на поединок в бойцовской гильдии и победите.','Вы только гляньте! Ты вышел на арену и одолел Ти\'тара по его же правилам.$B$BДержи. Вот твой заслуженный приз.','Вернитесь к продавцу карт вашей бойцовской гильдии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ти\'тар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gзаслужил:заслужила; право приобрести карточку вызова, и принадлежит эта карточка троллю по имени Ти\'тар.$b$bТи\'тар обладает очень характерным боевым стилем, и тебе, как того требует соглашение с бойцовской гильдией, придется драться по его правилам – лицом к лицу, на кулаках и не убегать. До трех нокдаунов.$b$bУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приобретите карточку вызова Ти\'тара, вызовите его на поединок в бойцовской гильдии и победите.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы только гляньте! Ты вышел на арену и одолел Ти\'тара по его же правилам.$B$BДержи. Вот твой заслуженный приз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к продавцу карт вашей бойцовской гильдии.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32860,'Битва за Колючий Холм – задание на отслеживание') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Колючий Холм – задание на отслеживание',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32861,'Плащ добродетели','Отправляйтесь на Причуду Камнетеса на Сокрытой лестнице и поговорите с Гневионом.','Я могу сшить плащ, который лучше всего подойдет к твоей специализации. Выбирай же с умом!$B$BСейчас в плаще содержится лишь часть той силы, которую он может вместить. Я уже вынашиваю план по его улучшению…','Поговорите с Гневионом на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плащ добродетели',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Причуду Камнетеса на Сокрытой лестнице и поговорите с Гневионом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я могу сшить плащ, который лучше всего подойдет к твоей специализации. Выбирай же с умом!$B$BСейчас в плаще содержится лишь часть той силы, которую он может вместить. Я уже вынашиваю план по его улучшению…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гневионом на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32862,'Поле битвы: Степи','Наша работа далека от завершения, $n. Горят костры перемен, хотя их еще можно задуть.$B$BПринеси мне больше кор\'кронских припасов, и я тебя награжу.','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.','Вернитесь к Ки\'те Стрелоклыку в деревню Сен\'джин или в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поле битвы: Степи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша работа далека от завершения, $n. Горят костры перемен, хотя их еще можно задуть.$B$BПринеси мне больше кор\'кронских припасов, и я тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ки\'те Стрелоклыку в деревню Сен\'джин или в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32863,'Ради чего мы обучались','Ты $gготов:готова; подвергнуть своих питомцев испытанию? На арене для боевых питомцев нет места хилым кроликам, туда стоит нести ракетобота, не меньше. Если у тебя есть три полностью обученных питомца, найди укротителей, примерно равных тебе по умениям, и устрой с ними бой. За подробностями обращайся в атлас питомцев.','Воспользуйтесь системой поиска боев и победите 10 игроков. Все питомцы из вашей команды должны быть 25 уровня.','До меня тут дошли слухи о твоих сражениях – должно быть, славное было зрелище! Я думаю, ты заслужил эту награду. Поздравляю, укротитель питомцев, так держать.','Вернитесь в Вечноцветущий дол, Оргриммар или Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ради чего мы обучались',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gготов:готова; подвергнуть своих питомцев испытанию? На арене для боевых питомцев нет места хилым кроликам, туда стоит нести ракетобота, не меньше. Если у тебя есть три полностью обученных питомца, найди укротителей, примерно равных тебе по умениям, и устрой с ними бой. За подробностями обращайся в атлас питомцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь системой поиска боев и победите 10 игроков. Все питомцы из вашей команды должны быть 25 уровня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','До меня тут дошли слухи о твоих сражениях – должно быть, славное было зрелище! Я думаю, ты заслужил эту награду. Поздравляю, укротитель питомцев, так держать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Вечноцветущий дол, Оргриммар или Штормград.',`completedtext_loc8`);
