INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32867,'Вол\'джин из племени Черного Копья','С возвращением в Сен\'джин. Знаю, ты $gпроделал:проделала; долгий путь, чтобы поговорить с Вол\'джином, предводителем Черного Копья.$B$BПрости, придется еще чуть подождать. Надо поговорить.','Выслушайте Ки\'ту Стрелоклыка.','Поговорите с Вол\'джином в деревне Сен\'джин в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вол\'джин из племени Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С возвращением в Сен\'джин. Знаю, ты $gпроделал:проделала; долгий путь, чтобы поговорить с Вол\'джином, предводителем Черного Копья.$B$BПрости, придется еще чуть подождать. Надо поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Ки\'ту Стрелоклыка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вол\'джином в деревне Сен\'джин в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32868,'Звери из легенд, книга II','В этих краях всегда будут рассказывать истории о Счастливчике И, Сером копытце и Быстролапом Кся. Хочешь сразиться с ними еще раз?','Победите Счастливчика И, Серое копытце и Быстролапого Кся.','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.','Вернитесь в Вечноцветущий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звери из легенд, книга II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих краях всегда будут рассказывать истории о Счастливчике И, Сером копытце и Быстролапом Кся. Хочешь сразиться с ними еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Счастливчика И, Серое копытце и Быстролапого Кся.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Вечноцветущий дол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32869,'Звери из легенд, книга III','В этих краях всегда будут рассказывать истории о Но-Но, Ти\'уне Страннике и Кровоспине. Хочешь сразиться с ними еще раз?','Победите Но-Но, Ти\'уна Странника и Кровоспина.','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.','Вернитесь в Вечноцветущий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звери из легенд, книга III',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих краях всегда будут рассказывать истории о Но-Но, Ти\'уне Страннике и Кровоспине. Хочешь сразиться с ними еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Но-Но, Ти\'уна Странника и Кровоспина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я склоняюсь перед тем, кто продолжает следовать путями великих сказаний пандаренов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь в Вечноцветущий дол.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32870,'Подготовка к удару','Лед тронулся, $n. Нам осталось выполнить одно последнее задание, перед тем как мы перейдем к финальной стадии моего плана.$b$bРазведчики доносят мне, что король Ринн заново собрал флот после поражения у Терамора, а Вол\'джин идет на север через Дуротар, открыто восстав против вождя.$b$bКогда они будут готовы сойтись у ворот, приходи ко мне. Мы доведем эту войну до славного завершения!','Вернитесь к Гневиону в таверну "В туманах" на Сокрытой лестнице.','Вернитесь к Гневиону в таверну "В туманах" на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к удару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лед тронулся, $n. Нам осталось выполнить одно последнее задание, перед тем как мы перейдем к финальной стадии моего плана.$b$bРазведчики доносят мне, что король Ринн заново собрал флот после поражения у Терамора, а Вол\'джин идет на север через Дуротар, открыто восстав против вождя.$b$bКогда они будут готовы сойтись у ворот, приходи ко мне. Мы доведем эту войну до славного завершения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Гневиону в таверну "В туманах" на Сокрытой лестнице.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах" на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32871,'Вол\'джин из племени Черного Копья','Давай провожу к Вол\'джину.','Идите к Вол\'джину с Зен\'таброй.','Поговорите с Вол\'джином на Колючем Холме в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вол\'джин из племени Черного Копья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давай провожу к Вол\'джину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите к Вол\'джину с Зен\'таброй.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вол\'джином на Колючем Холме в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32872,'Поле битвы: Степи','Работа еще не окончена, |3-6($r). Если ты $gготов:готова; опять рискнуть головой, помогая Черному Копью, награда будет достойной.','[Еженедельное задание] Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.','Вернитесь к Ки\'те Стрелоклыку в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поле битвы: Степи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работа еще не окончена, |3-6($r). Если ты $gготов:готова; опять рискнуть головой, помогая Черному Копью, награда будет достойной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Еженедельное задание] Соберите $1oa кусков кор\'кронской древесины, $2oa емкостей кор\'кронской нефти, $3oa кусков кор\'кронского мяса и $4oa блоков кор\'кронского камня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ки\'те Стрелоклыку в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
