INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (32892,'Грядет война','При входе в долину вы замечаете, что упитанный пандарен на балконе Дворца Могу\'шан делает вам знаки остановиться. Похоже, что хранитель истории Чо пытается привлечь ваше внимание. Нужно узнать, в чем дело!','Поговорите с хранителем истории Чо.','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.','Он машет рукой из Обители Мудрости.','Хранитель истории Чо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грядет война',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При входе в долину вы замечаете, что упитанный пандарен на балконе Дворца Могу\'шан делает вам знаки остановиться. Похоже, что хранитель истории Чо пытается привлечь ваше внимание. Нужно узнать, в чем дело!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хранителем истории Чо.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо в Обители Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Он машет рукой из Обители Мудрости.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Хранитель истории Чо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32895,'Путь к войне','Эй! У меня свежие новости от наших агентов в Дуротаре.$B$BВосстанию Черного Копья нужна твоя помощь.$B$BГоворят, ты уже неплохо ладишь с троллями. Может, побываешь в Дуротаре и посмотришь, что там происходит?','Поговорите с Ки\'той Стрелоклыком в Колючем Холме, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к войне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! У меня свежие новости от наших агентов в Дуротаре.$B$BВосстанию Черного Копья нужна твоя помощь.$B$BГоворят, ты уже неплохо ладишь с троллями. Может, побываешь в Дуротаре и посмотришь, что там происходит?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ки\'той Стрелоклыком в Колючем Холме, что в Дуротаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (32896,'Путь к войне','У меня новости от Бейна. Восстанию Черного Копья нужна твоя помощь.$B$BОтправляйся в Колючий Холм и найди Ки\'ту Стрелоклыка.$B$BИ никому ни слова!','Поговорите с Ки\'той Стрелоклыком в Колючем Холме, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к войне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня новости от Бейна. Восстанию Черного Копья нужна твоя помощь.$B$BОтправляйся в Колючий Холм и найди Ки\'ту Стрелоклыка.$B$BИ никому ни слова!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ки\'той Стрелоклыком в Колючем Холме, что в Дуротаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32900,'Героические свершения','Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.','Пройдите любой сценарий в героическом режиме сложности.','Вернитесь к Тайцзину Циклону в Святилище Семи Звезд, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Героические свершения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите любой сценарий в героическом режиме сложности.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тайцзину Циклону в Святилище Семи Звезд, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32901,'Героические свершения','Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.','Пройдите любой сценарий в героическом режиме сложности.','Вернитесь к Цзиньхо Разрывателю Ветра в Святилище Двух Лун, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Героические свершения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я просто умираю от скуки. Мне никогда не выбраться из этого места!$b$bТы производишь впечатление $gбывалого искателя:бывалой искательницы; приключений. Порадуй меня по-настоящему героической историей. В награду я дам тебе кое-что особенное, что тебя непременно заинтересует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите любой сценарий в героическом режиме сложности.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цзиньхо Разрывателю Ветра в Святилище Двух Лун, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32910,'Используй меня еще раз','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.','Убейте главного кузнеца и получите фрагмент кодекса от стража врат могу на Острове Грома.','Вернитесь к <тому, кто выдал задание>.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Используй меня еще раз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется сделать еще кое-что.\r\n\r\nУбей Итоку, главного кузнеца, и найди фрагмент кодекса Плотореза Хоку, хранителя врат Властелина Грома.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте главного кузнеца и получите фрагмент кодекса от стража врат могу на Острове Грома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к <тому, кто выдал задание>.',`completedtext_loc8`);
