INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32943,'Заказ: Войска Похитителей Солнца II','Когда лук-шалот вырастет, останется только сложить его в ящик.$b$bПодумать только, благодаря этому луку солдаты на передовой будут накормлены!','Соберите урожай с 8 растений лука-шалота и упакуйте 40 единиц лука-шалота для Войск Похитителей Солнца.','Положите лук-шалот в ящик. Скоро за ним придет посыльный Войск Похитителей Солнца.','Пустой ящик, в который нужно положить урожай.','Положите лук-шалот в пустой ящик на Ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Войска Похитителей Солнца II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда лук-шалот вырастет, останется только сложить его в ящик.$b$bПодумать только, благодаря этому луку солдаты на передовой будут накормлены!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите урожай с 8 растений лука-шалота и упакуйте 40 единиц лука-шалота для Войск Похитителей Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите лук-шалот в ящик. Скоро за ним придет посыльный Войск Похитителей Солнца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите лук-шалот в пустой ящик на Ферме Солнечной Песни.',`completedtext_loc8`);
