INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (32945,'Заказ: Армия Кирин-Тора II','Когда хрустящая морковь вырастет, останется только сложить ее в ящик.$b$bПодумать только, благодаря этой моркови солдаты на передовой будут накормлены!','Соберите урожай с 8 растений хрустящей моркови и упакуйте 40 единиц хрустящей моркови для Армии Кирин-Тора.','Положите хрустящую морковь в ящик. Скоро за ним придет посыльный Армии Кирин-Тора.','Пустой ящик, в который нужно положить урожай.','Положите хрустящую морковь в пустой ящик на Ферме Солнечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ: Армия Кирин-Тора II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда хрустящая морковь вырастет, останется только сложить ее в ящик.$b$bПодумать только, благодаря этой моркови солдаты на передовой будут накормлены!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите урожай с 8 растений хрустящей моркови и упакуйте 40 единиц хрустящей моркови для Армии Кирин-Тора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Положите хрустящую морковь в ящик. Скоро за ним придет посыльный Армии Кирин-Тора.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пустой ящик, в который нужно положить урожай.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Положите хрустящую морковь в пустой ящик на Ферме Солнечной Песни.',`completedtext_loc8`);
