INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32974,'Загадка Роло','<Свиток очень ветхий, выцветший от времени. На нем запечатлены следующие слова:>$B$BНа острове времени братья стоят,\r\nЧетверо сильных в круге не спят.\r\nСамый низкий из братьев укажет тебе,\r\nКакая тропа приводит ко мне.','Разгадайте загадку.','<На этом месте земля как будто перекопана. Возможно, здесь что-то зарыто.>','Найдите подсказку на Вневременном острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Роло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Свиток очень ветхий, выцветший от времени. На нем запечатлены следующие слова:>$B$BНа острове времени братья стоят,\r\nЧетверо сильных в круге не спят.\r\nСамый низкий из братьев укажет тебе,\r\nКакая тропа приводит ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадайте загадку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<На этом месте земля как будто перекопана. Возможно, здесь что-то зарыто.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите подсказку на Вневременном острове.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32975,'Загадка Роло','<В земле зарыт еще один свиток.>$B$BНадежда стоит тут, раскинув крыла,\r\nНайди ту тропу, что на север вела.\r\nПройди сквозь древние врата,\r\nУ пары камней я встречу тебя.','Разгадайте загадку.','<Еще один перекопанный клочок земли! Быть может, здесь что-то зарыто?>','Найдите подсказку на Вневременном острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Роло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В земле зарыт еще один свиток.>$B$BНадежда стоит тут, раскинув крыла,\r\nНайди ту тропу, что на север вела.\r\nПройди сквозь древние врата,\r\nУ пары камней я встречу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадайте загадку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Еще один перекопанный клочок земли! Быть может, здесь что-то зарыто?>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите подсказку на Вневременном острове.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (32976,'Загадка Роло','Остался шаг к моим дарам:\r\nВода стремится в землю там.\r\nПод тенью от заоблачных высот\r\nОдна дорога – воздух и полет.','Разгадайте загадку.','<Ветхий сундук давно никто не трогал.>','Найдите сокровище на Вневременном острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Роло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остался шаг к моим дарам:\r\nВода стремится в землю там.\r\nПод тенью от заоблачных высот\r\nОдна дорога – воздух и полет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадайте загадку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ветхий сундук давно никто не трогал.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите сокровище на Вневременном острове.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32995,'Залитый кровью свиток','[TEMP TEXT] С виду этот свиток очень ветхий. Он покрыт пылью и перепачкан кровью, но вам удается разглядеть несколько слов о "владении оружием".$b$bСвиток может помочь вам в обучении.$b$bВозможно, умелый воин сможет рассказать вам что-то об этом свитке.','[TEMP TEXT] Принесите свиток воителя Гауросу Сотрясателю Земли на Арену Морд\'Бой в Оргриммаре.','[TEMP TEXT] Найдите Гауроса Сотрясателя Земли на Арене Морд\'Бой в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Залитый кровью свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] С виду этот свиток очень ветхий. Он покрыт пылью и перепачкан кровью, но вам удается разглядеть несколько слов о "владении оружием".$b$bСвиток может помочь вам в обучении.$b$bВозможно, умелый воин сможет рассказать вам что-то об этом свитке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT] Принесите свиток воителя Гауросу Сотрясателю Земли на Арену Морд\'Бой в Оргриммаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[TEMP TEXT] Найдите Гауроса Сотрясателя Земли на Арене Морд\'Бой в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (32996,'Закаленные в битве реликвии','[TEMP TEXT] Мне не раз доводилось слышать твое имя, $n. Ты уже долгое время считаешься $gодним из лучших воинов:одной из лучших воительниц; Орды.$b$bТем не менее, я тебя совсем не знаю, и перед тем, как помочь тебе со свитком, я должен выяснить, на что ты $gспособен:способна;.$b$bНедавно xxx обнаружили xxx. Принеси трофеи из этих подземелий, они послужат доказательством твоей силы.','[TEMP TEXT] Соберите 100 закаленных в битве реликвий, победив боссов в xxx.','[TEMP TEXT] Вернитесь к Гауросу Сотрясателю Земли на Арену Морд\'Бой в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закаленные в битве реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] Мне не раз доводилось слышать твое имя, $n. Ты уже долгое время считаешься $gодним из лучших воинов:одной из лучших воительниц; Орды.$b$bТем не менее, я тебя совсем не знаю, и перед тем, как помочь тебе со свитком, я должен выяснить, на что ты $gспособен:способна;.$b$bНедавно xxx обнаружили xxx. Принеси трофеи из этих подземелий, они послужат доказательством твоей силы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT] Соберите 100 закаленных в битве реликвий, победив боссов в xxx.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[TEMP TEXT] Вернитесь к Гауросу Сотрясателю Земли на Арену Морд\'Бой в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (32997,'Tracking Quest - First - Zesqua') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Tracking Quest - First - Zesqua',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (33000,'Саурфанг, воин','[TEMP TEXT] Любой хороший воин обладает не только силой, но и лидерскими качествами. Сила нужна, чтобы одержать верх над противниками. Быть лидером нужно, чтобы собирать союзников. Воин, с которым тебе предстоит встретиться, обладает и тем, и другим.$b$bВерховный правитель Саурфанг ждет тебя в Колючем Холме. Когда-то давно он многому меня обучил и сможет помочь тебе со свитком.$b$bЯ отправил Саурфангу весточку, он ожидает твоего прибытия, $n.','Отправляйтесь в Колючий Холм, что в Дуротаре, и доложите о своем прибытии Верховному правителю Саурфангу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саурфанг, воин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] Любой хороший воин обладает не только силой, но и лидерскими качествами. Сила нужна, чтобы одержать верх над противниками. Быть лидером нужно, чтобы собирать союзников. Воин, с которым тебе предстоит встретиться, обладает и тем, и другим.$b$bВерховный правитель Саурфанг ждет тебя в Колючем Холме. Когда-то давно он многому меня обучил и сможет помочь тебе со свитком.$b$bЯ отправил Саурфангу весточку, он ожидает твоего прибытия, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Колючий Холм, что в Дуротаре, и доложите о своем прибытии Верховному правителю Саурфангу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33001,'Воители','[TEMP TEXT] В свитке описана особая техника владения оружием – стиль воителя, которого я не видел в деле уже многие годы. Я могу помочь с деталями, которые не упомянуты в свитке, но без опыта и практики это будут лишь слова на бумаге.$b$bЗа свою жизнь я сталкивался с множеством противников, но немногие из них мастерски владели своим оружием. Эти воители давно умерли, но с помощью xxx ты тоже сможешь с ними сразиться.','[TEMP TEXT]','[TEMP TEXT] Вернитесь к Верховному правителю Саурфангу в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] В свитке описана особая техника владения оружием – стиль воителя, которого я не видел в деле уже многие годы. Я могу помочь с деталями, которые не упомянуты в свитке, но без опыта и практики это будут лишь слова на бумаге.$b$bЗа свою жизнь я сталкивался с множеством противников, но немногие из них мастерски владели своим оружием. Эти воители давно умерли, но с помощью xxx ты тоже сможешь с ними сразиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT]',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[TEMP TEXT] Вернитесь к Верховному правителю Саурфангу в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (33002,'Писец Вэй У','[TEMP TEXT] Я использовал свои знания, чтобы заполнить пропущенные и нечитабельные места в твоем свитке, $n. Но я не писарь, а таким документам необходимо не только вести учет, но и хранить их соответствующе.$b$bПисцы Пандарии хранят такие древние тексты в архивах. Отнеси свиток в Обитель Мудрости и отдай его писцу.$b$bУдачи тебе, $gвоин:воительница;.','[TEMP TEXT] Поговорите с писцом Вэй У в Обители Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Писец Вэй У',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] Я использовал свои знания, чтобы заполнить пропущенные и нечитабельные места в твоем свитке, $n. Но я не писарь, а таким документам необходимо не только вести учет, но и хранить их соответствующе.$b$bПисцы Пандарии хранят такие древние тексты в архивах. Отнеси свиток в Обитель Мудрости и отдай его писцу.$b$bУдачи тебе, $gвоин:воительница;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT] Поговорите с писцом Вэй У в Обители Мудрости, что в Вечноцветущем доле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33003,'Символ воителя','[TEMP TEXT] Этот свиток нужно бережно переписать. У меня есть пергамент, но для такого текста нужны особые чернила, которые нелегко добыть. Обычные чернила тут бесполезны.$b$bВ Вечноцветущем доле водятся существа... легендарные существа, из крови которых можно изготовить нужные чернила. Я покажу тебе, где их найти.','[TEMP TEXT] Добудьте алую кровь Обана Оджу, черную как смоль кровь Как\'чаррика и лазурную кровь Искорки.','Вернитесь к писцу Вэй У в Обитель Мудрости, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ воителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] Этот свиток нужно бережно переписать. У меня есть пергамент, но для такого текста нужны особые чернила, которые нелегко добыть. Обычные чернила тут бесполезны.$b$bВ Вечноцветущем доле водятся существа... легендарные существа, из крови которых можно изготовить нужные чернила. Я покажу тебе, где их найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT] Добудьте алую кровь Обана Оджу, черную как смоль кровь Как\'чаррика и лазурную кровь Искорки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к писцу Вэй У в Обитель Мудрости, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33007,'Арена испытаний','[TEMP TEXT] Гаурос уже испытал тебя, но я думаю, что ты $gспособен:способна; на большее, $n. Я знаю, через что проходят такие воины, и выполнение пары заданий вряд ли представляет для тебя какую-либо сложность.$b$bНастоящее испытание ждет тебя в [PROVING GROUNDS TOWN]. Поговори с [PROVING GROUNDS JIM] в [PROVING GROUNDS TOWN] и выполни одно из его испытаний.','[TEMP TEXT] Выполните [PROVING GROUNDS TRIAL].','[TEMP TEXT] Return to High Overlord Saurfang at Razor Hill in Durotar.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арена испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[TEMP TEXT] Гаурос уже испытал тебя, но я думаю, что ты $gспособен:способна; на большее, $n. Я знаю, через что проходят такие воины, и выполнение пары заданий вряд ли представляет для тебя какую-либо сложность.$b$bНастоящее испытание ждет тебя в [PROVING GROUNDS TOWN]. Поговори с [PROVING GROUNDS JIM] в [PROVING GROUNDS TOWN] и выполни одно из его испытаний.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[TEMP TEXT] Выполните [PROVING GROUNDS TRIAL].',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[TEMP TEXT] Return to High Overlord Saurfang at Razor Hill in Durotar.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (33008,'В Дол') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Дол',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (33018,'Давно забытые секреты приготовления лапши','Разбирая завалы, вы обнаружили кусок старой вывески. Стерев с него пыль, вы увидели иероглифы пандаренов "лапша" и "Линь".$B$BОглянувшись, вы сделали вывод, что это заведение стояло на мосту, который теперь лежит в руинах. Вряд ли заведение на мосту просуществовало долго... скорее всего, его хозяин живет где-то неподалеку.$B$BБыть может, вам удастся разузнать что-нибудь в поселении на этом острове?','Найдите владельца фрагмента старой вывески в Древнем Пи\'джоу, что на Вневременном острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Давно забытые секреты приготовления лапши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разбирая завалы, вы обнаружили кусок старой вывески. Стерев с него пыль, вы увидели иероглифы пандаренов "лапша" и "Линь".$B$BОглянувшись, вы сделали вывод, что это заведение стояло на мосту, который теперь лежит в руинах. Вряд ли заведение на мосту просуществовало долго... скорее всего, его хозяин живет где-то неподалеку.$B$BБыть может, вам удастся разузнать что-нибудь в поселении на этом острове?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите владельца фрагмента старой вывески в Древнем Пи\'джоу, что на Вневременном острове.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33020,'Тайна секретного ингредиента','Победите Ша Сомнения.','На свитке вы видите имя "Линь" и чуть ниже иероглиф "рецепт".$B$BВы нашли его!$B$BНо вы опасаетесь, что темная сила ша, о которой так много говорится в пандарийских преданиях, могла запятнать и этот свиток. Есть только один способ узнать наверняка...','Найдите свиток семьи Линь в Нефритовом Сердце, что в Храме Нефритовой Змеи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна секретного ингредиента',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Ша Сомнения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На свитке вы видите имя "Линь" и чуть ниже иероглиф "рецепт".$B$BВы нашли его!$B$BНо вы опасаетесь, что темная сила ша, о которой так много говорится в пандарийских преданиях, могла запятнать и этот свиток. Есть только один способ узнать наверняка...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите свиток семьи Линь в Нефритовом Сердце, что в Храме Нефритовой Змеи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (33021,'Разгадка тайны, утраченная навеки?','<С древним рецептом супа с лапшой семьи Линь вы решили отправиться на рынок Полугорья.>$B$B<Если кто в Пандарии и сможет расшифровать рецепт, так это Суншинь Железная Лапа.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разгадка тайны, утраченная навеки?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<С древним рецептом супа с лапшой семьи Линь вы решили отправиться на рынок Полугорья.>$B$B<Если кто в Пандарии и сможет расшифровать рецепт, так это Суншинь Железная Лапа.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33022,'Лови и неси','Надо же! Дедушка рассказывал мне о знаменитом супе из лапши, который готовит семья Линь.$B$BГоворят, рецепт зашифрован, но я думаю, что мы с тобой сможем разгадать его тайны!$B$BДля начала нам понадобится много зерна, чтобы сделать лапшу.$B$BОтправляйся в хранилище и собирай зерно в этот мешок, а затем складывай его в повозку, которую я оставила рядом с хранилищем.','Используйте мешок для сбора зерна, чтобы поймать 20 мешков зерна, которые разбрасывают зерновые вандалы в императорском хранилище зерна.$B$BВы растеряете все собранное зерно, если воспользуетесь верховым животным или получите какой-либо урон.','Отлично, Олдру! У нас достаточно зерна, чтобы начать работу.$B$BДумаю, сначала тебе нужно попробовать сварить суп с лапшой. У меня есть для тебя отличный рецепт, чтобы ты смог попрактиковаться.','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лови и неси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо же! Дедушка рассказывал мне о знаменитом супе из лапши, который готовит семья Линь.$B$BГоворят, рецепт зашифрован, но я думаю, что мы с тобой сможем разгадать его тайны!$B$BДля начала нам понадобится много зерна, чтобы сделать лапшу.$B$BОтправляйся в хранилище и собирай зерно в этот мешок, а затем складывай его в повозку, которую я оставила рядом с хранилищем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте мешок для сбора зерна, чтобы поймать 20 мешков зерна, которые разбрасывают зерновые вандалы в императорском хранилище зерна.$B$BВы растеряете все собранное зерно, если воспользуетесь верховым животным или получите какой-либо урон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Олдру! У нас достаточно зерна, чтобы начать работу.$B$BДумаю, сначала тебе нужно попробовать сварить суп с лапшой. У меня есть для тебя отличный рецепт, чтобы ты смог попрактиковаться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33024,'Есть такая единица объема?','Отлично, Олдру. Теперь мы можем приготовить особый бульон.$B$BУ меня есть новые чертежи для твоей тележки с супом с лапшой. С таким бульоном тебе точно нужно расширяться.$B$BСледующий шаг: надо найти секретный ингредиент для супа Линь с лапшой!','Хорошо, что этим занимаешься ты. Я-то хмель не особенно люблю.','Вернитесь к Суншинь Железной Лапе на рынок Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Есть такая единица объема?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, Олдру. Теперь мы можем приготовить особый бульон.$B$BУ меня есть новые чертежи для твоей тележки с супом с лапшой. С таким бульоном тебе точно нужно расширяться.$B$BСледующий шаг: надо найти секретный ингредиент для супа Линь с лапшой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что этим занимаешься ты. Я-то хмель не особенно люблю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Суншинь Железной Лапе на рынок Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33026,'Это вам не жирный козий стейк!','Я в предвкушении, $n. Мы узнали практически все ингредиенты супа с лапшой!$B$BУ нас достаточно овощей и пряностей, но семья Линь использовала редкое мясо, которого в Пандарии уже не найти. Нам нужно хорошее, жирное мясо.$B$BДедушка рассказывал мне о древних черепахах, которые живут у побережья Вневременного острова. У животных, которые живут так долго, должно быть отличное питательное мясо.$B$BСооруди тележку с изысканным супом с лапшой, принеси жирные черепашьи стейки, и мы продолжим.','Создайте комплект для установки тележки с изысканным супом с лапшой и соберите 50 жирных черепашьих стейков.','Да. То, что нужно, Скотомогила.$B$BНам осталось лишь найти секретный ингредиент супа Линь с лапшой.$B$BНепростая задача!','Я почти ощущаю вкус этого супа во рту!','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это вам не жирный козий стейк!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я в предвкушении, $n. Мы узнали практически все ингредиенты супа с лапшой!$B$BУ нас достаточно овощей и пряностей, но семья Линь использовала редкое мясо, которого в Пандарии уже не найти. Нам нужно хорошее, жирное мясо.$B$BДедушка рассказывал мне о древних черепахах, которые живут у побережья Вневременного острова. У животных, которые живут так долго, должно быть отличное питательное мясо.$B$BСооруди тележку с изысканным супом с лапшой, принеси жирные черепашьи стейки, и мы продолжим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Создайте комплект для установки тележки с изысканным супом с лапшой и соберите 50 жирных черепашьих стейков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да. То, что нужно, Скотомогила.$B$BНам осталось лишь найти секретный ингредиент супа Линь с лапшой.$B$BНепростая задача!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я почти ощущаю вкус этого супа во рту!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33027,'Секретный ингредиент','Проще всего эта задача решается с помощью дегустаторов.$B$BПо моему приглашению сюда прибудут торговцы, ученые и крестьяне со всей Пандарии, чтобы отведать твои супы. Лучших результатов мы достигнем, если ты приготовишь им те супы, которые им нравятся.$B$BПришло время найти наш секретный ингредиент!','Встаньте в очередь и пройдите сценарий "Секретный ингредиент".','Как здорово, Скотомогила! Все присутствующие пришли отведать твой суп с лапшой, и именно благодаря тебе они так счастливы!$B$BРазве ты не понимаешь? Секретный ингредиент – это ты!$B$BОтправляйся в путь и сделай наш мир счастливее с помощью своей новой тележки с супом с лапшой!','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секретный ингредиент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проще всего эта задача решается с помощью дегустаторов.$B$BПо моему приглашению сюда прибудут торговцы, ученые и крестьяне со всей Пандарии, чтобы отведать твои супы. Лучших результатов мы достигнем, если ты приготовишь им те супы, которые им нравятся.$B$BПришло время найти наш секретный ингредиент!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встаньте в очередь и пройдите сценарий "Секретный ингредиент".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как здорово, Скотомогила! Все присутствующие пришли отведать твой суп с лапшой, и именно благодаря тебе они так счастливы!$B$BРазве ты не понимаешь? Секретный ингредиент – это ты!$B$BОтправляйся в путь и сделай наш мир счастливее с помощью своей новой тележки с супом с лапшой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Суншинь Железной Лапе на рынке Полугорья, что в Долине Четырех Ветров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (33047,'Награда за самоотверженность') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за самоотверженность',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (33087,'Встреча в таверне','Уверен, тебе не терпится испытать новый плащ. Опробуй его.$b$bВстретимся в таверне! Я узнал, что события приняли новый оборот, и у нас есть шанс этим воспользоваться.','Встретьтесь с Гневионом на втором этаже таверны "В туманах" на Сокрытой лестнице.','Ты готов к новому приключению?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча в таверне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверен, тебе не терпится испытать новый плащ. Опробуй его.$b$bВстретимся в таверне! Я узнал, что события приняли новый оборот, и у нас есть шанс этим воспользоваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Гневионом на втором этаже таверны "В туманах" на Сокрытой лестнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты готов к новому приключению?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (33088,'Вневременное открытие','Пандария. Стоит только подумать, что разгадал все ее тайны, как я тут же совершаю новые открытия.$b$bНа сей раз я узнал об острове, который называют Вневременным. Он сокрыт в туманах, появляется и исчезает будто по собственной воле. Говорят, время там не имеет значения, солнце не восходит и не заходит.$b$bМы можем воспользоваться, этой аномалией, $n! Если мне удастся зафиксировать твой плащ во времени, он сможет накапливать... колоссальную энергию.$b$bНаш путь лежит туда. Лети на юго-восток от Нефритового леса. Встретимся на Вневременном острове!','Отправляйтесь на Вневременный остров к юго-востоку от Нефритового леса и поговорите с Гневионом.','Ты здесь! Как давно я тебя жду?$B$B<Гневион в замешательстве.>$B$BКажется, что я только что прибыл сюда... А может, и несколько недель назад... Этот остров совсем задурил мне голову.$B$BКайроз пытался все мне объяснить, но похоже, что бронзовые драконы любят говорить загадками.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вневременное открытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пандария. Стоит только подумать, что разгадал все ее тайны, как я тут же совершаю новые открытия.$b$bНа сей раз я узнал об острове, который называют Вневременным. Он сокрыт в туманах, появляется и исчезает будто по собственной воле. Говорят, время там не имеет значения, солнце не восходит и не заходит.$b$bМы можем воспользоваться, этой аномалией, $n! Если мне удастся зафиксировать твой плащ во времени, он сможет накапливать... колоссальную энергию.$b$bНаш путь лежит туда. Лети на юго-восток от Нефритового леса. Встретимся на Вневременном острове!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Вневременный остров к юго-востоку от Нефритового леса и поговорите с Гневионом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты здесь! Как давно я тебя жду?$B$B<Гневион в замешательстве.>$B$BКажется, что я только что прибыл сюда... А может, и несколько недель назад... Этот остров совсем задурил мне голову.$B$BКайроз пытался все мне объяснить, но похоже, что бронзовые драконы любят говорить загадками.',`offerrewardtext_loc8`);
