INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33100,'Путь Императора','Августейшие Небожители подвергли тебя испытанию, и ты блестяще с ним $gсправился:справилась;.$b$bНо сможешь ли ты одолеть Небожителей в бою? Они испытывают храбрость всех героев Пандарии.$b$bИспытание не из легких, и тебе придется последовать совету последнего императора пандаренов – идти на испытание с непоколебимой верой в себя. Также тебе понадобится небольшая армия, поэтому найди тех, кому ты всецело доверяешь.$b$bСразись с четырьмя Небожителями здесь, на Турнирной площадке Небожителей, одержи победу, и наш путь будет почти завершен...','Победите четырех Августейших Небожителей Пандарии – Юй-лун, Чи-Цзи, Сюэня и Нюцзао.','Возвращайтесь к Гневиону на Вневременный остров, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Императора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Августейшие Небожители подвергли тебя испытанию, и ты блестяще с ним $gсправился:справилась;.$b$bНо сможешь ли ты одолеть Небожителей в бою? Они испытывают храбрость всех героев Пандарии.$b$bИспытание не из легких, и тебе придется последовать совету последнего императора пандаренов – идти на испытание с непоколебимой верой в себя. Также тебе понадобится небольшая армия, поэтому найди тех, кому ты всецело доверяешь.$b$bСразись с четырьмя Небожителями здесь, на Турнирной площадке Небожителей, одержи победу, и наш путь будет почти завершен...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите четырех Августейших Небожителей Пандарии – Юй-лун, Чи-Цзи, Сюэня и Нюцзао.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Возвращайтесь к Гневиону на Вневременный остров, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33104,'Легенда пандаренов','Друг, я столько всего узнал в этом месте, где время застыло. Благодаря мудрости Небожителей и необычным возможностям этих вневременных артефактов я смогу улучшить твой плащ.$b$bНаложить на него чары необходимо в священном месте. Быстрее! Встретимся у Обители Мудрости над дворцом Могу\'шан в Вечноцветущем доле.$b$bСегодня мы создадим твою легенду!','Встретьтесь с Гневионом у Обители Мудрости в Вечноцветущем доле.','Сделай шаг вперед.$B$BНастал час твоей славы.','Встретьтесь с Гневионом у Обители Мудрости в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенда пандаренов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друг, я столько всего узнал в этом месте, где время застыло. Благодаря мудрости Небожителей и необычным возможностям этих вневременных артефактов я смогу улучшить твой плащ.$b$bНаложить на него чары необходимо в священном месте. Быстрее! Встретимся у Обители Мудрости над дворцом Могу\'шан в Вечноцветущем доле.$b$bСегодня мы создадим твою легенду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Гневионом у Обители Мудрости в Вечноцветущем доле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сделай шаг вперед.$B$BНастал час твоей славы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтесь с Гневионом у Обители Мудрости в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33105,'Решение Черного принца','Итак. Последняя часть моего плана. Время исполнить твое предназначение.$b$bПора положить конец этой войне при помощи твоих новообретенных сил. Уничтожь Гарроша Адского Крика. Твой народ требует этого, и многие поколения будут воспевать тебя как $gпредвестника:предвестницу; дивного нового мира, который мы создадим вместе.$b$bМне больше нечего предложить тебе в награду. Я сделал все, что было в моих силах, чтобы обеспечить тебе победу. Теперь все зависит только от тебя.$b$bПоложи конец правлению Гарроша.','<Гневион вне себя от ярости. Должно быть, черный дракон уже прознал о поражении Гарроша и стремлении короля Ринна к миру.>','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решение Черного принца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак. Последняя часть моего плана. Время исполнить твое предназначение.$b$bПора положить конец этой войне при помощи твоих новообретенных сил. Уничтожь Гарроша Адского Крика. Твой народ требует этого, и многие поколения будут воспевать тебя как $gпредвестника:предвестницу; дивного нового мира, который мы создадим вместе.$b$bМне больше нечего предложить тебе в награду. Я сделал все, что было в моих силах, чтобы обеспечить тебе победу. Теперь все зависит только от тебя.$b$bПоложи конец правлению Гарроша.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гневион вне себя от ярости. Должно быть, черный дракон уже прознал о поражении Гарроша и стремлении короля Ринна к миру.>',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гневиону в таверну "В туманах", что на Сокрытой лестнице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (33107,'Все хуже, чем кажется','<Вы разворачиваете свиток и понимаете, что ваши худшие опасения подтвердились: энергия ша осквернила рецепт семьи Линь.>$B$B<У вас нет иного выхода, кроме как одержать верх над этой энергией и надеяться, что свиток уцелеет.>','Победите призрака Линь Да-Гу.','Победите призрака Линь Да-Гу!','Призрак Линь Да-Гу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все хуже, чем кажется',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вы разворачиваете свиток и понимаете, что ваши худшие опасения подтвердились: энергия ша осквернила рецепт семьи Линь.>$B$B<У вас нет иного выхода, кроме как одержать верх над этой энергией и надеяться, что свиток уцелеет.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите призрака Линь Да-Гу.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Победите призрака Линь Да-Гу!',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Призрак Линь Да-Гу',`questgivertargetname_loc8`);
