INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33110,'Узурпатор','Кусок сердца И\'Шараджа лежит и не движется. Принесите его членам Золотого Лотоса в качестве доказательства того, что Гаррош повержен.','Получите свою награду за свержение Гарроша Адского Крика, бывшего вождя Орды.','Вернитесь к [PH] в Вечноскорбящий дол.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узурпатор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кусок сердца И\'Шараджа лежит и не движется. Принесите его членам Золотого Лотоса в качестве доказательства того, что Гаррош повержен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите свою награду за свержение Гарроша Адского Крика, бывшего вождя Орды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к [PH] в Вечноскорбящий дол.',`completedtext_loc8`);
