INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33137,'Турнир Небожителей','На Вневременном острове проводится турнир – настоящая проверка лидерских качеств участников. Те, кто докажут, что достойны награды, получат возможность познакомиться с воплощением благочестия – потомком самих Небожителей.$b$bЗа каждую победу в турнире я буду вручать тебе церемониальную монету. Когда ты соберешь достаточно монет, обратись ко мне, и мы поговорим о награде.','Поговорите с мастером Ли, чтобы принять участие в Турнире Небожителей, и победите всех участников.','Передо мной стоит настоящий лидер. Для меня честь вручить тебе эту монету, Лрг.','Чтобы получить монету, нужно выиграть Турнир Небожителей.','Вернитесь к мастеру Ли на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Турнир Небожителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Вневременном острове проводится турнир – настоящая проверка лидерских качеств участников. Те, кто докажут, что достойны награды, получат возможность познакомиться с воплощением благочестия – потомком самих Небожителей.$b$bЗа каждую победу в турнире я буду вручать тебе церемониальную монету. Когда ты соберешь достаточно монет, обратись ко мне, и мы поговорим о награде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Ли, чтобы принять участие в Турнире Небожителей, и победите всех участников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Передо мной стоит настоящий лидер. Для меня честь вручить тебе эту монету, Лрг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы получить монету, нужно выиграть Турнир Небожителей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Ли на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33138,'Почему мы сражаемся?','$gДруг мой:Дорогая подруга;, сегодня ты вместе со спутниками $gодержал:одержала; верх над ша, которые существовали в Пандарии с тех времен, когда события еще не записывали. Ты $gсмог:смогла; сделать то, что было не под силу титанам и их слугам могу – $gуничтожил:уничтожила; последние дыхания И\'Шараджа.$b$bДавай встретимся в Вечноцветущем доле. Я хочу тебе кое-что показать.','Хранитель истории Чо хочет поговорить с вами в Вечноцветущем доле.','Наш прекрасный Вечноцветущий дол. Так много разрушений и жестокости. Но... я чувствую, что есть надежда.','Поговорите с хранителем истории Чо у Приисков Пышного Цветения, что в Вечноцветущем доле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почему мы сражаемся?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gДруг мой:Дорогая подруга;, сегодня ты вместе со спутниками $gодержал:одержала; верх над ша, которые существовали в Пандарии с тех времен, когда события еще не записывали. Ты $gсмог:смогла; сделать то, что было не под силу титанам и их слугам могу – $gуничтожил:уничтожила; последние дыхания И\'Шараджа.$b$bДавай встретимся в Вечноцветущем доле. Я хочу тебе кое-что показать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хранитель истории Чо хочет поговорить с вами в Вечноцветущем доле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наш прекрасный Вечноцветущий дол. Так много разрушений и жестокости. Но... я чувствую, что есть надежда.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с хранителем истории Чо у Приисков Пышного Цветения, что в Вечноцветущем доле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (33139,'Разгадка тайны, утраченная навеки?','<С древним рецептом супа с лапшой семьи Линь вы решили отправиться на рынок Полугорья.>$B$B<Если кто в Пандарии и сможет расшифровать рецепт, так это Суншинь Железная Лапа.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разгадка тайны, утраченная навеки?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<С древним рецептом супа с лапшой семьи Линь вы решили отправиться на рынок Полугорья.>$B$B<Если кто в Пандарии и сможет расшифровать рецепт, так это Суншинь Железная Лапа.>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (33147,'Последний вздох И\'Шараджа','Темная, похожая на пар субстанция покрывает пол комнаты. Это все, что осталось от древнего бога И\'Шараджа.','Видишь? Даже сейчас он продолжает развеиваться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний вздох И\'Шараджа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темная, похожая на пар субстанция покрывает пол комнаты. Это все, что осталось от древнего бога И\'Шараджа.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? Даже сейчас он продолжает развеиваться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (33156,'Хранитель Времени Кайроз','Ты $gнашел:нашла; способ попасть на Вневременный остров, |3-6($c). Бронзовые драконы желают разузнать его тайны, но остров опасен, и нам нужна твоя помощь.$b$bИди вдоль берега, и на полпути ты увидишь мощеную дорогу, которая ведет на восток.$B$BОна приведет тебя на Турнирную площадку Небожителей. Там ты найдешь Кайроза, одного из Хранителей Времени, с которым мы работаем.$B$BКайроз ответит на любые твои вопросы. Будь $gосторожен:осторожна;, путь может быть опасным.','Поговорите с Кайрозом на Вневременном острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель Времени Кайроз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gнашел:нашла; способ попасть на Вневременный остров, |3-6($c). Бронзовые драконы желают разузнать его тайны, но остров опасен, и нам нужна твоя помощь.$b$bИди вдоль берега, и на полпути ты увидишь мощеную дорогу, которая ведет на восток.$B$BОна приведет тебя на Турнирную площадку Небожителей. Там ты найдешь Кайроза, одного из Хранителей Времени, с которым мы работаем.$B$BКайроз ответит на любые твои вопросы. Будь $gосторожен:осторожна;, путь может быть опасным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кайрозом на Вневременном острове.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (33160,'Хранитель Времени Кайроз','Ты $gнашел:нашла; способ попасть на Вневременный остров, |3-6($c). Бронзовые драконы желают разузнать его тайны, но остров опасен, и нам нужна твоя помощь.$b$bИди вдоль берега, и на полпути ты увидишь мощеную дорогу, которая ведет на восток.$B$BОна приведет тебя на Турнирную площадку Небожителей. Там ты найдешь Кайроза, одного из Хранителей Времени, с которым мы работаем.$B$BКайроз ответит на любые твои вопросы. Будь $gосторожен:осторожна;, путь может быть опасным.','Поговорите с Кайрозом на Вневременном острове.','А! Рад знакомству, Тархиус!$B$BМне сообщили, что ты уже в пути, но я не ожидал, что ты прибудешь так скоро.$B$B...Или прошло уже много времени? В этом месте не поймешь.$B$BИтак, приступим?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель Времени Кайроз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gнашел:нашла; способ попасть на Вневременный остров, |3-6($c). Бронзовые драконы желают разузнать его тайны, но остров опасен, и нам нужна твоя помощь.$b$bИди вдоль берега, и на полпути ты увидишь мощеную дорогу, которая ведет на восток.$B$BОна приведет тебя на Турнирную площадку Небожителей. Там ты найдешь Кайроза, одного из Хранителей Времени, с которым мы работаем.$B$BКайроз ответит на любые твои вопросы. Будь $gосторожен:осторожна;, путь может быть опасным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кайрозом на Вневременном острове.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Рад знакомству, Тархиус!$B$BМне сообщили, что ты уже в пути, но я не ожидал, что ты прибудешь так скоро.$B$B...Или прошло уже много времени? В этом месте не поймешь.$B$BИтак, приступим?',`offerrewardtext_loc8`);
