INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33211,'Вневременный вопрос','Судьба. Рок. Карма. Эти слова предполагают неизменность временных потоков.$B$BНо так ли это? По сей день многие обитатели Азерота стремятся изменить прошлое. Но наши поступки не только меняют нас, но и придают форму нашему миру.$B$BПредставь, что это – нити, из которых сплетена наша реальность. Обрежь достаточно нитей, и причинно-следственная связь нарушится, а ткань реальности пойдет по швам. Более того, для этого достаточно даже одной нити. Нужно лишь выбрать правильную.','Правильно ответьте на один вопрос Эвелины об истории Азерота.','В этом заключается тяжкое бремя Историка. Если временные потоки Азерота окажутся под угрозой, мы должны в точности восстановить историю, иначе последствия могут быть плачевными. Распространяя наши знания и рассказы, мы создаем надежное будущее для всех нас.','Давай поговорим о событиях, которые уже произошли.','Вернитесь к старшему историку Эвелине на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вневременный вопрос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судьба. Рок. Карма. Эти слова предполагают неизменность временных потоков.$B$BНо так ли это? По сей день многие обитатели Азерота стремятся изменить прошлое. Но наши поступки не только меняют нас, но и придают форму нашему миру.$B$BПредставь, что это – нити, из которых сплетена наша реальность. Обрежь достаточно нитей, и причинно-следственная связь нарушится, а ткань реальности пойдет по швам. Более того, для этого достаточно даже одной нити. Нужно лишь выбрать правильную.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Правильно ответьте на один вопрос Эвелины об истории Азерота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В этом заключается тяжкое бремя Историка. Если временные потоки Азерота окажутся под угрозой, мы должны в точности восстановить историю, иначе последствия могут быть плачевными. Распространяя наши знания и рассказы, мы создаем надежное будущее для всех нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай поговорим о событиях, которые уже произошли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему историку Эвелине на Вневременный остров.',`completedtext_loc8`);
