INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33332,'Подсказки из прошлого','Нам предстоит многое узнать, но это место не желает раскрывать свои секреты.$b$bМеня очень заинтересовало то, что ты $gупомянул:упомянула; в нашей предыдущей беседе. У ткача туманов Ай есть потрепанный дневник, так ведь? Возможно, в нем мы сможем найти ответы на многие вопросы... или же вопросов станет еще больше. Полагаю, это зависит от усердия исследователя-путешественника, который вел дневник, находясь в этом странном месте.$b$bЗаполучи этот потрепанный дневник, принеси его мне, и мы вместе раскроем его тайны.','Купите потрепанный дневник у ткача туманов Ай.','Принесите потрепанный дневник Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подсказки из прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам предстоит многое узнать, но это место не желает раскрывать свои секреты.$b$bМеня очень заинтересовало то, что ты $gупомянул:упомянула; в нашей предыдущей беседе. У ткача туманов Ай есть потрепанный дневник, так ведь? Возможно, в нем мы сможем найти ответы на многие вопросы... или же вопросов станет еще больше. Полагаю, это зависит от усердия исследователя-путешественника, который вел дневник, находясь в этом странном месте.$b$bЗаполучи этот потрепанный дневник, принеси его мне, и мы вместе раскроем его тайны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите потрепанный дневник у ткача туманов Ай.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите потрепанный дневник Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33333,'Вневременные сокровища','В дневнике утверждается, что по всему острову можно найти сокровища, до которых крайне тяжело добраться, а также тайники в темных пещерах и лощинах. Что же именно хранится там столько лет?$b$bИ, что еще интереснее, кто же спрятал эти сокровища?$b$bИсследуй остров, найди эти сокровища и принеси мне их. Не забывай: не все то золото, что блестит, но и обратное тоже верно. Порой даже самый обычный полый пень отлично подойдет, чтобы спрятать нечто ценное.','Найдите спрятанное на Вневременном острове сокровище.','Вернитесь к Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вневременные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В дневнике утверждается, что по всему острову можно найти сокровища, до которых крайне тяжело добраться, а также тайники в темных пещерах и лощинах. Что же именно хранится там столько лет?$b$bИ, что еще интереснее, кто же спрятал эти сокровища?$b$bИсследуй остров, найди эти сокровища и принеси мне их. Не забывай: не все то золото, что блестит, но и обратное тоже верно. Порой даже самый обычный полый пень отлично подойдет, чтобы спрятать нечто ценное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите спрятанное на Вневременном острове сокровище.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (33334,'Выживет сильнейший','Этот остров затерян во времени, но на нем кипит жизнь!$b$bГде он побывал? Просто отправился в будущее или же очутился в Круговерти Пустоты?$b$bОдно можно сказать наверняка – существа, населяющие этот остров, не так просты, как кажутся. Я чувствую, что в них сокрыта сила, накопленная за миллиарды лет. Найди пять сильнейших существ, обладающих невиданной мощью, и убей их.$b$bБыть может, их смерть позволит нам найти ответы.','Убейте пять редких и редких элитных существ на Вневременном острове.','Вернитесь к Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выживет сильнейший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот остров затерян во времени, но на нем кипит жизнь!$b$bГде он побывал? Просто отправился в будущее или же очутился в Круговерти Пустоты?$b$bОдно можно сказать наверняка – существа, населяющие этот остров, не так просты, как кажутся. Я чувствую, что в них сокрыта сила, накопленная за миллиарды лет. Найди пять сильнейших существ, обладающих невиданной мощью, и убей их.$b$bБыть может, их смерть позволит нам найти ответы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте пять редких и редких элитных существ на Вневременном острове.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33335,'Последний император','Судя по тому, что мне удалось узнать, это место использовали для проведения какого-то турнира. На нем воины со всей Пандарии демонстрировали свои умения, проходя по стопам своего последнего императора – Шаохао.$b$bГоворят, когда Шаохао прошел все испытания, он стал единым целым с Пандарией и окутал ее густым туманом, который защищал эту землю даже от действия наших способностей, позволяющих влиять на ход времени.$b$bВесьма любопытно. Возможно, тебе стоит побеседовать с ним?','Поговорите с императором Шаохао.','Я преисполнился гордыни и пытался скрыть существование Пандарии ото всех, и вновь эта земля преподала мне важные уроки. Я рад, что опять могу делиться знаниями со своим народом. Помочь познать то, что смог познать я. Дать возможность учиться на моих ошибках. Возможно, Пандария все еще может научить чему-то и тебя.','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний император',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по тому, что мне удалось узнать, это место использовали для проведения какого-то турнира. На нем воины со всей Пандарии демонстрировали свои умения, проходя по стопам своего последнего императора – Шаохао.$b$bГоворят, когда Шаохао прошел все испытания, он стал единым целым с Пандарией и окутал ее густым туманом, который защищал эту землю даже от действия наших способностей, позволяющих влиять на ход времени.$b$bВесьма любопытно. Возможно, тебе стоит побеседовать с ним?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с императором Шаохао.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я преисполнился гордыни и пытался скрыть существование Пандарии ото всех, и вновь эта земля преподала мне важные уроки. Я рад, что опять могу делиться знаниями со своим народом. Помочь познать то, что смог познать я. Дать возможность учиться на моих ошибках. Возможно, Пандария все еще может научить чему-то и тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33336,'Сущность времени','Пришло время сообщить тебе о цели нашего пребывания на этом острове.$b$bСилы бронзовых драконов уже не те, что прежде – мы можем улавливать лишь мимолетные видения во времени. Это... печалит нас.$b$bНо мы не бессильны. Это Образ времени – артефакт, который мы создали. Существа, населяющие этот остров, перемещались во времени, и в них содержится его сущность. Мы наполним ею песочные часы и снова получим доступ к временным потокам.','Получите камень Вечности, убив одно из существ на Вневременном острове.','Удалось что-нибудь найти?','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность времени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время сообщить тебе о цели нашего пребывания на этом острове.$b$bСилы бронзовых драконов уже не те, что прежде – мы можем улавливать лишь мимолетные видения во времени. Это... печалит нас.$b$bНо мы не бессильны. Это Образ времени – артефакт, который мы создали. Существа, населяющие этот остров, перемещались во времени, и в них содержится его сущность. Мы наполним ею песочные часы и снова получим доступ к временным потокам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите камень Вечности, убив одно из существ на Вневременном острове.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось что-нибудь найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33337,'Видение во времени','Весьма интригующе. Мне нужно будет внести некоторые изменения и, возможно, найти более подходящий катализатор. Спасибо тебе за этот эксперимент. Надеюсь, нет никаких побочных эффектов? Если ты готов помочь, возможно, в скором времени я еще раз попрошу тебя об услуге.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видение во времени',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Весьма интригующе. Мне нужно будет внести некоторые изменения и, возможно, найти более подходящий катализатор. Спасибо тебе за этот эксперимент. Надеюсь, нет никаких побочных эффектов? Если ты готов помочь, возможно, в скором времени я еще раз попрошу тебя об услуге.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33338,'Сила песочных часов','Эти песочные часы позволяют наблюдать за потоками времени, по которым мы когда-то могли с легкостью перемещаться.$b$bСобери больше камней Вечности, чтобы мы могли и дальше использовать силу песочных часов и изучать тайны временных потоков.$b$bОт этого зависит будущее.','Собирайте камни Вечности, убивая существ на Вневременном острове.','Подожди, пока я перемалываю камни и наполняю песочные часы, и нам откроется что-то новое.$B$BОчень хорошо, что я склонен рассматривать определенные моменты во времени, а не длинные цепочки событий.$B$BСудя по временным потокам, в ближайшем будущем нам не раз понадобится воспользоваться силой песочных часов.','Камни Вечности – редкая квинтэссенция кристаллизованного времени.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила песочных часов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти песочные часы позволяют наблюдать за потоками времени, по которым мы когда-то могли с легкостью перемещаться.$b$bСобери больше камней Вечности, чтобы мы могли и дальше использовать силу песочных часов и изучать тайны временных потоков.$b$bОт этого зависит будущее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Собирайте камни Вечности, убивая существ на Вневременном острове.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подожди, пока я перемалываю камни и наполняю песочные часы, и нам откроется что-то новое.$B$BОчень хорошо, что я склонен рассматривать определенные моменты во времени, а не длинные цепочки событий.$B$BСудя по временным потокам, в ближайшем будущем нам не раз понадобится воспользоваться силой песочных часов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Камни Вечности – редкая квинтэссенция кристаллизованного времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33340,'Вневременное питание','Как ты и $gпредполагал:предполагала;, на этом острове крайне необычные флора и фауна. Но этому может быть простое объяснение. Иногда, чтобы узнать об окружающем нас мире, нужно присмотреться к земле. Тебе не приходило в голову, что существа на этом острове могли вырасти до таких размеров всего лишь из-за местной пищи?$b$bТы можешь найти ее в изобилии по всему острову: спелые плоды, яйца, мясо, цветы, орехи и даже камни. Попробуй эту еду и узнай о силе, заключенной в земле.','Остров дарует изобилие пищи и множество ответов. Нужно лишь оглянуться по сторонам, чтобы найти то, что ищешь.','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вневременное питание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты и $gпредполагал:предполагала;, на этом острове крайне необычные флора и фауна. Но этому может быть простое объяснение. Иногда, чтобы узнать об окружающем нас мире, нужно присмотреться к земле. Тебе не приходило в голову, что существа на этом острове могли вырасти до таких размеров всего лишь из-за местной пищи?$b$bТы можешь найти ее в изобилии по всему острову: спелые плоды, яйца, мясо, цветы, орехи и даже камни. Попробуй эту еду и узнай о силе, заключенной в земле.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остров дарует изобилие пищи и множество ответов. Нужно лишь оглянуться по сторонам, чтобы найти то, что ищешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33341,'Путевые святилища Небожителей','Небожители наполнили тебя своей силой и мудростью. Открой свое сердце и позволь этим знаниям остаться в нем навечно.','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путевые святилища Небожителей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Небожители наполнили тебя своей силой и мудростью. Открой свое сердце и позволь этим знаниям остаться в нем навечно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33343,'Архиерей пламени','Призовите и победите архиерея пламени.','Посланники Ордоса повержены, но лишь на время.$B$BЗнай, что злобе, жестокости и ненависти никогда не будет конца. Эти ша терпеливо ждут, когда в душах пробудится тьма. Они могут появиться при разных обстоятельствах, принять множество обличий... Полководец, жаждущий власти, удар кинжалом в спину ночью, юный принц, ступивший на путь тьмы, и даже отчаянное сражение с превосходящими силами противника.$B$BУсвой урок этих чувств, иначе тебя поглотит тьма.','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Архиерей пламени',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и победите архиерея пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посланники Ордоса повержены, но лишь на время.$B$BЗнай, что злобе, жестокости и ненависти никогда не будет конца. Эти ша терпеливо ждут, когда в душах пробудится тьма. Они могут появиться при разных обстоятельствах, принять множество обличий... Полководец, жаждущий власти, удар кинжалом в спину ночью, юный принц, ступивший на путь тьмы, и даже отчаянное сражение с превосходящими силами противника.$B$BУсвой урок этих чувств, иначе тебя поглотит тьма.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Императором Шаохао на Вневременном острове, что неподалеку от Нефритового леса.',`completedtext_loc8`);
