INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (33374,'Путь странника туманов','Убейте 20 элитных существ на Вневременном острове.','Пусть это будет твоим ежедневным упражнением, которое позволит тебе стать сильнее, мудрее и развить силу духа.','Полученные в Пандарии знания помогли тебе в твоем путешествии?','Вернитесь к императору Шаохао на Вневременный остров, что неподалеку от Нефритового леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь странника туманов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 элитных существ на Вневременном острове.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть это будет твоим ежедневным упражнением, которое позволит тебе стать сильнее, мудрее и развить силу духа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полученные в Пандарии знания помогли тебе в твоем путешествии?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к императору Шаохао на Вневременный остров, что неподалеку от Нефритового леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33375,'Усовершенствование видения','Рассказ об истинном героизме и о важнейшем моменте в истории. Но, боюсь, не совсем то, что мы искали.$B$BОстается не так много времени. Я приложу вдвое больше усилий.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усовершенствование видения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рассказ об истинном героизме и о важнейшем моменте в истории. Но, боюсь, не совсем то, что мы искали.$B$BОстается не так много времени. Я приложу вдвое больше усилий.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (33376,'В поисках судьбы','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках судьбы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33377,'Сокрытые нити','Штормград… разрушен?$B$BПонимаю, это видение потрясло тебя. На данный момент я вряд ли знаю больше, чем ты. Но я постараюсь найти ответы на вопросы, обещаю тебе.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокрытые нити',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Штормград… разрушен?$B$BПонимаю, это видение потрясло тебя. На данный момент я вряд ли знаю больше, чем ты. Но я постараюсь найти ответы на вопросы, обещаю тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33378,'Судьба принца','Ага, похоже, нашему юному принцу еще предстоит сыграть свою роль. Но мы больше не должны говорить об этом, чтобы не изменить будущее.$B$BДаже у деревьев есть уши. Храни молчание. Со временем мы узнаем ответы на наши вопросы.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба принца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, похоже, нашему юному принцу еще предстоит сыграть свою роль. Но мы больше не должны говорить об этом, чтобы не изменить будущее.$B$BДаже у деревьев есть уши. Храни молчание. Со временем мы узнаем ответы на наши вопросы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (33379,'Один последний переворот','Соридорми, супруга Ноздорму, мертва? И я тоже был там?$B$BМы не можем знать, что все это значит, что произойдет в будущем, и даже, принадлежит ли это видение к нашему пути времени. Ты никому не должен говорить об этом видении, иначе мы изменим течение времени и навлечем на всех нас большую опасность. Все, что мы можем сделать сейчас – это завершить видение времени. Оно покажет нам, что на самом деле готовит нам будущее.','Вернитесь к Кайрозу на Вневременный остров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Один последний переворот',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Соридорми, супруга Ноздорму, мертва? И я тоже был там?$B$BМы не можем знать, что все это значит, что произойдет в будущем, и даже, принадлежит ли это видение к нашему пути времени. Ты никому не должен говорить об этом видении, иначе мы изменим течение времени и навлечем на всех нас большую опасность. Все, что мы можем сделать сейчас – это завершить видение времени. Оно покажет нам, что на самом деле готовит нам будущее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайрозу на Вневременный остров.',`completedtext_loc8`);
